/* ============================================================
 * IIQE 刷题题库（原创练习题 + 真实练习题）— 简/繁双语版
 * 依据：VTC/PEAK 官方考试范围（卷一《保险原理及实务》7 章、
 *       卷三《长期保险》5 章）编写，全部题目均附详细解析。
 * 简体为主(sh/q/o/e)，繁体副(tw.ch/tw.q/tw.o/tw.e)；真实题繁体
 *       为源 PDF 原文，其余为 OpenCC s2t 转换。
 * 字段：p=试卷(1/3) ch=章节 q=题干 o=选项 a=正确选项下标
 *       e=解析 src=来源（缺省/0=原创，1=真实题） tw=繁体
 * ============================================================ */
window.QBANK = [
{p:1,ch:"风险与保险",q:"下列哪一项属于「纯粹风险」？",o:["开办新业务","赌博","火灾造成财物损失","股票投资"],a:2,e:"纯粹风险只有损失的可能、没有收益的可能（如火灾、意外），属于可保风险；投机风险则可能有收益，一般不可保。",tw:{ch:"風險與保險",q:"下列哪一項屬於「純粹風險」？",o:["開辦新業務","賭博","火災造成財物損失","股票投資"],e:"純粹風險只有損失的可能、沒有收益的可能（如火災、意外），屬於可保風險；投機風險則可能有收益，一般不可保。"}},
{p:1,ch:"风险与保险",q:"下列哪一项属于「基本风险」的例子？",o:["个人受伤","战争、饥荒等大规模灾难","家中的火灾","汽车意外"],a:1,e:"基本风险指影响整个社会或大范围人群的灾难性风险（如战争、饥荒、恐怖袭击），除寿险外一般不可保；特定风险只影响少数人，属于可保范围。",tw:{ch:"風險與保險",q:"下列哪一項屬於「基本風險」的例子？",o:["個人受傷","戰爭、饑荒等大規模災難","家中的火災","汽車意外"],e:"基本風險指影響整個社會或大範圍人羣的災難性風險（如戰爭、饑荒、恐怖襲擊），除壽險外一般不可保；特定風險隻影響少數人，屬於可保範圍。"}},
{p:1,ch:"风险与保险",q:"风险管理过程的正确顺序是？",o:["应对 → 识别 → 量化","量化 → 识别 → 应对","识别 → 量化 → 应对","识别 → 应对 → 量化"],a:2,e:"风险管理先识别风险，再量化/评估其频率与严重程度，最后选择应对方法（风险避免、风险转移、风险融资、损失防范与降低等）。",tw:{ch:"風險與保險",q:"風險管理過程的正確順序是？",o:["應對 → 識別 → 量化","量化 → 識別 → 應對","識別 → 量化 → 應對","識別 → 應對 → 量化"],e:"風險管理先識別風險，再量化/評估其頻率與嚴重程度，最後選擇應對方法（風險避免、風險轉移、風險融資、損失防範與降低等）。"}},
{p:1,ch:"风险与保险",q:"保险的基本功能（或基本好处）是？",o:["促进经济增长","提供储蓄与投资渠道","提供就业","风险转移机制"],a:3,e:"保险最基本的功能是风险转移机制；损失防范、经济增长、金融服务、储蓄等都属于辅助功能。",tw:{ch:"風險與保險",q:"保險的基本功能（或基本好處）是？",o:["促進經濟增長","提供儲蓄與投資渠道","提供就業","風險轉移機制"],e:"保險最基本的功能是風險轉移機制；損失防範、經濟增長、金融服務、儲蓄等都屬於輔助功能。"}},
{p:1,ch:"风险与保险",q:"保单提供「全险」（All Risks）保障的意思是？",o:["除列明除外的原因外，由任何原因造成的损失均属受保","全世界通行的保险","只承保保单列明的特定危险","所有保单都承保的风险"],a:0,e:"全险保单采取「列明除外」方式：除非造成损失的原因属于列明的除外责任，否则任何原因造成的损失都在保障范围内。",tw:{ch:"風險與保險",q:"保單提供「全險」（All Risks）保障的意思是？",o:["除列明除外的原因外，由任何原因造成的損失均屬受保","全世界通行的保險","只承保保單列明的特定危險","所有保單都承保的風險"],e:"全險保單採取「列明除外」方式：除非造成損失的原因屬於列明的除外責任，否則任何原因造成的損失都在保障範圍內。"}},
{p:1,ch:"风险与保险",q:"保险公司的风险管理，管理的是哪类风险？",o:["纯粹风险／可保风险","所有商业风险","汇率风险","投机风险"],a:0,e:"保险公司管理的只是纯粹风险，即只可保的风险；投机风险（可能获利）不属于保险管理的范围。",tw:{ch:"風險與保險",q:"保險公司的風險管理，管理的是哪類風險？",o:["純粹風險／可保風險","所有商業風險","匯率風險","投機風險"],e:"保險公司管理的只是純粹風險，即只可保的風險；投機風險（可能獲利）不屬於保險管理的範圍。"}},
{p:1,ch:"风险与保险",q:"「风险」最贴切的定义是？",o:["必然发生的事件","只涉及金钱的问题","可以完全消除的事故","损失发生的不确定性"],a:3,e:"风险是指损失发生的不确定性——结果未知、可能有损失。保险正是管理这种不确定性的机制。",tw:{ch:"風險與保險",q:"「風險」最貼切的定義是？",o:["必然發生的事件","只涉及金錢的問題","可以完全消除的事故","損失發生的不確定性"],e:"風險是指損失發生的不確定性——結果未知、可能有損失。保險正是管理這種不確定性的機制。"}},
{p:1,ch:"风险与保险",q:"下列哪项属于「实质危险因素」？",o:["投保人的不诚实倾向","市场的投机气氛","仓库内存放易燃物品","投保后疏于防火的心理"],a:2,e:"实质危险因素是有形的物理因素（如建筑材料、易燃物品），会增加损失的可能或严重程度；道德及心理危险因素则涉及人的品行与心态。",tw:{ch:"風險與保險",q:"下列哪項屬於「實質危險因素」？",o:["投保人的不誠實傾向","市場的投機氣氛","倉庫內存放易燃物品","投保後疏於防火的心理"],e:"實質危險因素是有形的物理因素（如建築材料、易燃物品），會增加損失的可能或嚴重程度；道德及心理危險因素則涉及人的品行與心態。"}},
{p:1,ch:"风险与保险",q:"「道德危险」的例子是？",o:["投保人蓄意纵火骗保的品行倾向","楼梯没有扶手","地震带地区","电线老化"],a:0,e:"道德危险指个人品格或行为倾向引致损失的可能（如欺诈、纵火），较难量化；实质危险因素则是可观察的物理状况。",tw:{ch:"風險與保險",q:"「道德危險」的例子是？",o:["投保人蓄意縱火騙保的品行傾向","樓梯沒有扶手","地震帶地區","電線老化"],e:"道德危險指個人品格或行為傾向引致損失的可能（如欺詐、縱火），較難量化；實質危險因素則是可觀察的物理狀況。"}},
{p:1,ch:"风险与保险",q:"「心理（士气）危险因素」指？",o:["已投保因而减低防范损失的小心程度（如投保火险后不再检查灭火器）","金融市场波动","纵火骗保","楼宇结构缺陷"],a:0,e:"士气危险指因为有保险保障而疏忽大意、减低防范意识的心态，属无形风险因素。",tw:{ch:"風險與保險",q:"「心理（士氣）危險因素」指？",o:["已投保因而減低防範損失的小心程度（如投保火險後不再檢查滅火器）","金融市場波動","縱火騙保","樓宇結構缺陷"],e:"士氣危險指因為有保險保障而疏忽大意、減低防範意識的心態，屬無形風險因素。"}},
{p:1,ch:"风险与保险",q:"下列哪项属于「风险避免」？",o:["不进行高空蹦极活动，以避免受伤风险","购买保险","自留小额损失","安装防盗系统"],a:0,e:"风险避免是设法完全不接触某风险（不从事该活动）；买保险属风险转移，装设备属损失防范，自留属风险融资。",tw:{ch:"風險與保險",q:"下列哪項屬於「風險避免」？",o:["不進行高空蹦極活動，以避免受傷風險","購買保險","自留小額損失","安裝防盜系統"],e:"風險避免是設法完全不接觸某風險（不從事該活動）；買保險屬風險轉移，裝設備屬損失防範，自留屬風險融資。"}},
{p:1,ch:"风险与保险",q:"购买保险属于哪种风险管理方法？",o:["损失防范","风险自留","风险避免","风险转移（风险融资）"],a:3,e:"投保人以缴付保费为代价，把潜在损失的经济后果转移给保险人，属风险融资中的风险转移。",tw:{ch:"風險與保險",q:"購買保險屬於哪種風險管理方法？",o:["損失防範","風險自留","風險避免","風險轉移（風險融資）"],e:"投保人以繳付保費為代價，把潛在損失的經濟後果轉移給保險人，屬風險融資中的風險轉移。"}},
{p:1,ch:"风险与保险",q:"保单设定「免赔额」，就免赔额以内的损失而言，投保人采用了？",o:["风险避免","风险自留","风险转移","风险分散"],a:1,e:"免赔额以内的损失由投保人自行承担，即自留风险；自留小额损失也可减少索偿次数及降低保费。",tw:{ch:"風險與保險",q:"保單設定「免賠額」，就免賠額以內的損失而言，投保人採用了？",o:["風險避免","風險自留","風險轉移","風險分散"],e:"免賠額以內的損失由投保人自行承擔，即自留風險；自留小額損失也可減少索償次數及降低保費。"}},
{p:1,ch:"风险与保险",q:"下列哪项不是「可保风险」的特征？",o:["损失具有偶然性或不确定性","存在大量同质的风险单位","属投机性风险（可能获利）","损失可以金钱衡量"],a:2,e:"可保风险须为非投机性（只有损失可能）、偶然发生、可计量、非灾难性，并有大量同质风险单位以作大数法则计算；投机风险不可保。",tw:{ch:"風險與保險",q:"下列哪項不是「可保風險」的特徵？",o:["損失具有偶然性或不確定性","存在大量同質的風險單位","屬投機性風險（可能獲利）","損失可以金錢衡量"],e:"可保風險須為非投機性（只有損失可能）、偶然發生、可計量、非災難性，並有大量同質風險單位以作大數法則計算；投機風險不可保。"}},
{p:1,ch:"风险与保险",q:"保险最适合处理哪类风险？",o:["低频率、低损失程度","高频率、高损失程度","高频率、低损失程度","低频率、高损失程度"],a:3,e:"低频率、高损失程度的风险最难以自留，最适合以保险转移（如火灾、死亡）；高频率低损失的风险通常自留更经济。",tw:{ch:"風險與保險",q:"保險最適合處理哪類風險？",o:["低頻率、低損失程度","高頻率、高損失程度","高頻率、低損失程度","低頻率、高損失程度"],e:"低頻率、高損失程度的風險最難以自留，最適合以保險轉移（如火災、死亡）；高頻率低損失的風險通常自留更經濟。"}},
{p:1,ch:"风险与保险",q:"「逆选择」指？",o:["中介人选择产品","保险人拒绝理赔","保险人挑选客户","知道自己风险较高的人更倾向及更积极投保"],a:3,e:"逆选择指风险状况较差者投保意愿更强的倾向，核保制度正是为识别及管理逆选择而设。",tw:{ch:"風險與保險",q:"「逆選擇」指？",o:["中介人選擇產品","保險人拒絕理賠","保險人挑選客户","知道自己風險較高的人更傾向及更積極投保"],e:"逆選擇指風險狀況較差者投保意願更強的傾向，核保制度正是為識別及管理逆選擇而設。"}},
{p:1,ch:"法律原则",q:"下列哪一项不是一份有效合约必须具备的要素？",o:["立约能力","必须采用书面形式","对价","要约与承诺"],a:1,e:"有效合约的基本要素为：要约、承诺、对价、立约能力与合法的合约目的。合约一般无须书面形式即可有效（保险合约常要求书面是另一回事）。",tw:{ch:"法律原則",q:"下列哪一項不是一份有效合約必須具備的要素？",o:["立約能力","必須採用書面形式","對價","要約與承諾"],e:"有效合約的基本要素為：要約、承諾、對價、立約能力與合法的合約目的。合約一般無須書面形式即可有效（保險合約常要求書面是另一回事）。"}},
{p:1,ch:"法律原则",q:"人寿保险的可保利益必须在何时存在？",o:["退保时","索赔时","订立合约时","任何时间"],a:2,e:"人寿保险要求在投保（订立合约）时存在可保利益，并不要求索赔时仍存在；一般保险则要求损失发生时存在可保利益。",tw:{ch:"法律原則",q:"人壽保險的可保利益必須在何時存在？",o:["退保時","索賠時","訂立合約時","任何時間"],e:"人壽保險要求在投保（訂立合約）時存在可保利益，並不要求索賠時仍存在；一般保險則要求損失發生時存在可保利益。"}},
{p:1,ch:"法律原则",q:"投保人的「披露重要事实」责任，重要事实是指？",o:["所有与健康有关的事实","会影响一名谨慎保险人决定是否承保或以何种条件承保的事实","保险人书面询问的事实","保险人知道的事实"],a:1,e:"重要（重大）事实是那些会影响一名谨慎的保险人决定是否承保、或以何种费率及条款承保的事实，投保人须如实披露。",tw:{ch:"法律原則",q:"投保人的「披露重要事實」責任，重要事實是指？",o:["所有與健康有關的事實","會影響一名謹慎保險人決定是否承保或以何種條件承保的事實","保險人書面詢問的事實","保險人知道的事實"],e:"重要（重大）事實是那些會影響一名謹慎的保險人決定是否承保、或以何種費率及條款承保的事實，投保人須如實披露。"}},
{p:1,ch:"法律原则",q:"投保人违反最大诚信原则（如不披露重要事实或误述），保险人可采取的后果是？",o:["只可向中介人追讨","合约自动无效，无需通知","可取消合约（合约成为可撤销）","必须照常赔偿"],a:2,e:"违反最大诚信（不披露、误述或欺诈）使合约成为可撤销（voidable），保险人可选择取消合约；并非自动无效。",tw:{ch:"法律原則",q:"投保人違反最大誠信原則（如不披露重要事實或誤述），保險人可採取的後果是？",o:["只可向中介人追討","合約自動無效，無需通知","可取消合約（合約成為可撤銷）","必須照常賠償"],e:"違反最大誠信（不披露、誤述或欺詐）使合約成為可撤銷（voidable），保險人可選擇取消合約；並非自動無效。"}},
{p:1,ch:"法律原则",q:"最大诚信原则约束的对象是？",o:["只约束投保人","只约束保险人","只约束保险中介人","投保人与保险人双方"],a:3,e:"最大诚信（Utmost Good Faith）是双向原则：投保人须如实披露，保险人（尤其经其代理人）也须如实说明保单的重要条款。",tw:{ch:"法律原則",q:"最大誠信原則約束的對象是？",o:["只約束投保人","只約束保險人","只約束保險中介人","投保人與保險人雙方"],e:"最大誠信（Utmost Good Faith）是雙向原則：投保人須如實披露，保險人（尤其經其代理人）也須如實說明保單的重要條款。"}},
{p:1,ch:"法律原则",q:"保险代理人在授权范围内向客户作出的承诺，对保险公司有约束力吗？",o:["须由保监局确认","有，代理人的行为归于其委任人（保险公司）","只有书面承诺才有效","没有，代理人自己负责"],a:1,e:"代理人在授权范围内的行为视为本人（保险公司）的行为，保险公司须受约束并承担责任。",tw:{ch:"法律原則",q:"保險代理人在授權範圍內向客户作出的承諾，對保險公司有約束力嗎？",o:["須由保監局確認","有，代理人的行為歸於其委任人（保險公司）","只有書面承諾才有效","沒有，代理人自己負責"],e:"代理人在授權範圍內的行為視為本人（保險公司）的行為，保險公司須受約束並承擔責任。"}},
{p:1,ch:"法律原则",q:"「表见代理」（Apparent Authority）指？",o:["虽无实际授权，但本人行为使第三方合理相信代理人有权限，本人仍须负责","代理人实际获得的授权","代理人的私人授权","只在寿险适用的代理"],a:0,e:"表见代理下，即使代理人越权，只要本人的行为令第三方合理地相信其有权代理，本人仍须对代理人的行为负责。",tw:{ch:"法律原則",q:"「表見代理」（Apparent Authority）指？",o:["雖無實際授權，但本人行為使第三方合理相信代理人有權限，本人仍須負責","代理人實際獲得的授權","代理人的私人授權","只在壽險適用的代理"],e:"表見代理下，即使代理人越權，只要本人的行為令第三方合理地相信其有權代理，本人仍須對代理人的行為負責。"}},
{p:1,ch:"法律原则",q:"在一般的投保过程中，投保人递交填妥的投保单，在法律上构成？",o:["要约","合约","承诺","邀请要约"],a:0,e:"投保单是投保人向保险人提出的要约（offer）；保险人核保后签发保单构成承诺（acceptance）。",tw:{ch:"法律原則",q:"在一般的投保過程中，投保人遞交填妥的投保單，在法律上構成？",o:["要約","合約","承諾","邀請要約"],e:"投保單是投保人向保險人提出的要約（offer）；保險人核保後簽發保單構成承諾（acceptance）。"}},
{p:1,ch:"法律原则",q:"合约相对性原则的意思是？",o:["只有合约的一方可以对另一方强制执行合约权利","任何第三者都可强制执行合约","合约只对保险公司适用","合约对政府无约束力"],a:0,e:"合约相对性指原则上只有合约双方之间产生权利和义务，第三者不能强制执行合约（保险中有法定例外情形）。",tw:{ch:"法律原則",q:"合約相對性原則的意思是？",o:["只有合約的一方可以對另一方強制執行合約權利","任何第三者都可強制執行合約","合約只對保險公司適用","合約對政府無約束力"],e:"合約相對性指原則上只有合約雙方之間產生權利和義務，第三者不能強制執行合約（保險中有法定例外情形）。"}},
{p:1,ch:"法律原则",q:"保险公司在报章刊登的产品广告，在法律上一般构成？",o:["要约","邀请要约（邀请他人提出要约）","承诺","合约"],a:1,e:"广告、宣传单张一般属邀请要约，邀请公众提出要约（投保）；保险人核保承保时才构成承诺。",tw:{ch:"法律原則",q:"保險公司在報章刊登的產品廣告，在法律上一般構成？",o:["要約","邀請要約（邀請他人提出要約）","承諾","合約"],e:"廣告、宣傳單張一般屬邀請要約，邀請公眾提出要約（投保）；保險人核保承保時才構成承諾。"}},
{p:1,ch:"法律原则",q:"在人寿保险合约中，投保人缴付的保费属于？",o:["代理人的报酬","投保人的对价","税款","罚款"],a:1,e:"对价是合约双方互相付出的有价值的东西：投保人付出保费，保险人承诺于受保事故发生时给付。",tw:{ch:"法律原則",q:"在人壽保險合約中，投保人繳付的保費屬於？",o:["代理人的報酬","投保人的對價","税款","罰款"],e:"對價是合約雙方互相付出的有價值的東西：投保人付出保費，保險人承諾於受保事故發生時給付。"}},
{p:1,ch:"法律原则",q:"关于立约能力，下列哪项正确？",o:["立约能力与合约有效性无关","所有人订立的合约同样有效","未成年人订立的合约一般可由该未成年人撤销","公司没有立约能力"],a:2,e:"未成年人、精神不健全者等立约能力受限，他们所订合约可能无效或可撤销，影响合约的有效性。",tw:{ch:"法律原則",q:"關於立約能力，下列哪項正確？",o:["立約能力與合約有效性無關","所有人訂立的合約同樣有效","未成年人訂立的合約一般可由該未成年人撤銷","公司沒有立約能力"],e:"未成年人、精神不健全者等立約能力受限，他們所訂合約可能無效或可撤銷，影響合約的有效性。"}},
{p:1,ch:"法律原则",q:"投保人对受保生命毫无可保利益而投保，该保单？",o:["保费加倍","有效","属赌博性保单，法律不予强制执行","自动转为储蓄保险"],a:2,e:"无可保利益的保单等于赌博，法律不承认其效力；可保利益原则正是防止赌博性保单及道德危险。",tw:{ch:"法律原則",q:"投保人對受保生命毫無可保利益而投保，該保單？",o:["保費加倍","有效","屬賭博性保單，法律不予強制執行","自動轉為儲蓄保險"],e:"無可保利益的保單等於賭博，法律不承認其效力；可保利益原則正是防止賭博性保單及道德危險。"}},
{p:1,ch:"法律原则",q:"投保人作欺诈性误述，保险人可？",o:["取消合约并拒绝赔偿，且不受不可争议条款保障","只可减少赔偿","必须续保","无权取消合约"],a:0,e:"欺诈性误述属最严重的违反诚信行为，保险人可取消合约、拒赔；欺诈通常不受不可争议条款保护。",tw:{ch:"法律原則",q:"投保人作欺詐性誤述，保險人可？",o:["取消合約並拒絕賠償，且不受不可爭議條款保障","只可減少賠償","必須續保","無權取消合約"],e:"欺詐性誤述屬最嚴重的違反誠信行為，保險人可取消合約、拒賠；欺詐通常不受不可爭議條款保護。"}},
{p:1,ch:"法律原则",q:"保单条文由保险人草拟，条文有歧义时，法庭一般会？",o:["宣布合约无效","作不利于草拟人（保险人）的解释","作有利于保险人的解释","按投保人理解为准"],a:1,e:"按「不利于草拟人」原则，含糊条款会作对被保险人有利、对保险人（草拟方）不利的解释。",tw:{ch:"法律原則",q:"保單條文由保險人草擬，條文有歧義時，法庭一般會？",o:["宣佈合約無效","作不利於草擬人（保險人）的解釋","作有利於保險人的解釋","按投保人理解為準"],e:"按「不利於草擬人」原則，含糊條款會作對被保險人有利、對保險人（草擬方）不利的解釋。"}},
{p:1,ch:"法律原则",q:"保险经纪在法律上是「」的代理人？",o:["投保人（客户）","保险人","再保险人","保监局"],a:0,e:"经纪受客户委托安排保险，是客户的代理人，须向客户负责；这与代表保险公司的代理人不同。",tw:{ch:"法律原則",q:"保險經紀在法律上是「」的代理人？",o:["投保人（客户）","保險人","再保險人","保監局"],e:"經紀受客户委託安排保險，是客户的代理人，須向客户負責；這與代表保險公司的代理人不同。"}},
{p:1,ch:"法律原则",q:"保险代理人在招揽过程中知悉的重要事实，就法律而言？",o:["毋须理会","视为保险公司亦已知道","与保险公司无关","只属代理人的个人知识"],a:1,e:"代理人（包括其业务代表）在授权范围内知悉的资料，法律上视为本人（保险公司）已知悉，保险人不能以投保人未直接告知为由抗辩。",tw:{ch:"法律原則",q:"保險代理人在招攬過程中知悉的重要事實，就法律而言？",o:["毋須理會","視為保險公司亦已知道","與保險公司無關","只屬代理人的個人知識"],e:"代理人（包括其業務代表）在授權範圍內知悉的資料，法律上視為本人（保險公司）已知悉，保險人不能以投保人未直接告知為由抗辯。"}},
{p:1,ch:"保险原则",q:"「近因」（Proximate Cause）是指？",o:["时间上最先发生的原因","造成损失的有效或主导成因","时间上最后发生的原因","距离损失地点最近的原因"],a:1,e:"近因是损失的有效或主导成因，不一定是首个或最后的成因；索赔时必须在每个案中抽出一个主导成因判断是否受保。",tw:{ch:"保險原則",q:"「近因」（Proximate Cause）是指？",o:["時間上最先發生的原因","造成損失的有效或主導成因","時間上最後發生的原因","距離損失地點最近的原因"],e:"近因是損失的有效或主導成因，不一定是首個或最後的成因；索賠時必須在每個案中抽出一個主導成因判斷是否受保。"}},
{p:1,ch:"保险原则",q:"损失的单一成因属于保单列明的除外危险，该损失？",o:["受保","不受保","由中介人赔偿","按半额赔偿"],a:1,e:"只有单一成因时，属受保危险则获保障；属不保危险或除外危险则不获保障。",tw:{ch:"保險原則",q:"損失的單一成因屬於保單列明的除外危險，該損失？",o:["受保","不受保","由中介人賠償","按半額賠償"],e:"只有單一成因時，屬受保危險則獲保障；屬不保危險或除外危險則不獲保障。"}},
{p:1,ch:"保险原则",q:"多项危险同时造成一项损失，当中包括受保危险，应如何处理？",o:["由保险人和被保险人各承担一半","自动全赔","自动不赔","抽出主导的成因判断是否受保"],a:3,e:"涉及多项危险时，须找出主导近因：若主导成因为受保危险通常获保（除外的发生一般令索偿失败）；个案中须抽出一个主导成因。",tw:{ch:"保險原則",q:"多項危險同時造成一項損失，當中包括受保危險，應如何處理？",o:["由保險人和被保險人各承擔一半","自動全賠","自動不賠","抽出主導的成因判斷是否受保"],e:"涉及多項危險時，須找出主導近因：若主導成因為受保危險通常獲保（除外的發生一般令索償失敗）；個案中須抽出一個主導成因。"}},
{p:1,ch:"保险原则",q:"弥偿原则不适用于下列哪种保险？",o:["汽车保险","水险","火险","人寿保险"],a:3,e:"人寿保险（及人身意外）属「利益保单」，按约定金额给付，不适用弥偿原则；财产类保险适用弥偿——不多不少的补偿。",tw:{ch:"保險原則",q:"彌償原則不適用於下列哪種保險？",o:["汽車保險","水險","火險","人壽保險"],e:"人壽保險（及人身意外）屬「利益保單」，按約定金額給付，不適用彌償原則；財產類保險適用彌償——不多不少的補償。"}},
{p:1,ch:"保险原则",q:"保险人提供弥偿的方式不包括？",o:["修理","现金支付","恢复原状","惩罚性赔偿"],a:3,e:"弥偿方式包括现金支付、修理、更换及恢复原状；保险只补偿实际损失，不作惩罚性赔偿。",tw:{ch:"保險原則",q:"保險人提供彌償的方式不包括？",o:["修理","現金支付","恢復原狀","懲罰性賠償"],e:"彌償方式包括現金支付、修理、更換及恢復原狀；保險只補償實際損失，不作懲罰性賠償。"}},
{p:1,ch:"保险原则",q:"保险标的受损后留下残余部分（损余 Salvage），一般如何处理？",o:["一定归被保险人","损余必须销毁","在赔偿额中扣除损余价值，或保险人全赔后收回损余","损余自动归中介人"],a:2,e:"常见处理方式有二：从赔偿额中扣除损余价值，或由保险人全额赔付后收回损余自行处理（注意海事法中的 Salvage 指尖救助）。",tw:{ch:"保險原則",q:"保險標的受損後留下殘餘部分（損餘 Salvage），一般如何處理？",o:["一定歸被保險人","損餘必須銷燬","在賠償額中扣除損餘價值，或保險人全賠後收回損餘","損餘自動歸中介人"],e:"常見處理方式有二：從賠償額中扣除損餘價值，或由保險人全額賠付後收回損餘自行處理（注意海事法中的 Salvage 指尖救助）。"}},
{p:1,ch:"保险原则",q:"「委付」（Abandonment）最常出现于哪种保险？",o:["汽车保险","火险","水险（海上保险）","人寿保险"],a:2,e:"委付主要见于水险：被保险人将保险标的（或残余）完全移交保险人，以索取全损赔偿，保险人可从中获益。",tw:{ch:"保險原則",q:"「委付」（Abandonment）最常出現於哪種保險？",o:["汽車保險","火險","水險（海上保險）","人壽保險"],e:"委付主要見於水險：被保險人將保險標的（或殘餘）完全移交保險人，以索取全損賠償，保險人可從中獲益。"}},
{p:1,ch:"保险原则",q:"某屋实际价值 200 万，保额 100 万，火灾损失 40 万，保单含比例分摊（Average）条款，保险人应赔多少？",o:["100 万","40 万","20 万","80 万"],a:2,e:"比例分摊：赔偿 = 损失 ×（保额 ÷ 实际价值）= 40 万 ×（100 万 ÷ 200 万）= 20 万。不足额投保下被保险人自负比例损失。",tw:{ch:"保險原則",q:"某屋實際價值 200 萬，保額 100 萬，火災損失 40 萬，保單含比例分攤（Average）條款，保險人應賠多少？",o:["100 萬","40 萬","20 萬","80 萬"],e:"比例分攤：賠償 = 損失 ×（保額 ÷ 實際價值）= 40 萬 ×（100 萬 ÷ 200 萬）= 20 萬。不足額投保下被保險人自負比例損失。"}},
{p:1,ch:"保险原则",q:"「分担」（Contribution）原则适用的前提是？",o:["保额不足时","两份或以上弥偿保单保障相同标的、相同危险、相同权益，总保额超法律容许的弥偿程度","两份人寿保单","任何两份保单"],a:1,e:"分担适用于重复保险：多张弥偿保单就同一标的、同一危险、同一权益重复投保且总保额超过可弥偿程度时，各保险人按比例分担；不适用于人寿保险。",tw:{ch:"保險原則",q:"「分擔」（Contribution）原則適用的前提是？",o:["保額不足時","兩份或以上彌償保單保障相同標的、相同危險、相同權益，總保額超法律容許的彌償程度","兩份人壽保單","任何兩份保單"],e:"分擔適用於重複保險：多張彌償保單就同一標的、同一危險、同一權益重複投保且總保額超過可彌償程度時，各保險人按比例分擔；不適用於人壽保險。"}},
{p:1,ch:"保险原则",q:"保险人行使代位权利时，是以谁的名义进行？",o:["保监局的名义","保险人的名义","法院的名义","被保险人的名义"],a:3,e:"保险人须以被保险人的名义向第三者追偿，且追偿所得以保险人已支付的赔偿金额为限。",tw:{ch:"保險原則",q:"保險人行使代位權利時，是以誰的名義進行？",o:["保監局的名義","保險人的名義","法院的名義","被保險人的名義"],e:"保險人須以被保險人的名義向第三者追償，且追償所得以保險人已支付的賠償金額為限。"}},
{p:1,ch:"保险原则",q:"保险人通过代位追偿所得金额，上限是？",o:["损失的总额","不设上限","保额的全部","保险人已支付的赔偿金额"],a:3,e:"代位允许保险人取得第三者的赔偿，但以保险人已赔付的金额为限；超出部分应归被保险人。",tw:{ch:"保險原則",q:"保險人通過代位追償所得金額，上限是？",o:["損失的總額","不設上限","保額的全部","保險人已支付的賠償金額"],e:"代位允許保險人取得第三者的賠償，但以保險人已賠付的金額為限；超出部分應歸被保險人。"}},
{p:1,ch:"保险原则",q:"代位权利可来源于下列哪一项？",o:["侵权法上的第三者疏忽","被保险人赠与","遗产分配","遗嘱继承"],a:0,e:"代位可源于侵权（第三者疏忽）、合约（如租约）、法规（如雇员补偿条例）及损余，但不适用于人寿保险。",tw:{ch:"保險原則",q:"代位權利可來源於下列哪一項？",o:["侵權法上的第三者疏忽","被保險人贈與","遺產分配","遺囑繼承"],e:"代位可源於侵權（第三者疏忽）、合約（如租約）、法規（如僱員補償條例）及損餘，但不適用於人壽保險。"}},
{p:1,ch:"保险原则",q:"下列哪些保险原则不适用于人寿保险？",o:["最大诚信","近因","弥偿、分担及代位","可保利益"],a:2,e:"人寿保险属利益保单，不适用弥偿原则，随之分担与代位也不适用；但最大诚信、可保利益（投保时）及近因等原则仍适用。",tw:{ch:"保險原則",q:"下列哪些保險原則不適用於人壽保險？",o:["最大誠信","近因","彌償、分擔及代位","可保利益"],e:"人壽保險屬利益保單，不適用彌償原則，隨之分擔與代位也不適用；但最大誠信、可保利益（投保時）及近因等原則仍適用。"}},
{p:1,ch:"保险原则",q:"「弃权与禁止反言」指？",o:["中介人放弃佣金","投保人放弃索偿","双方终止合约","保险人明知有权主张某项权利（如以违反条款为由拒赔）而放弃后，不得反悔再主张"],a:3,e:"弃权是自愿放弃已知权利；禁止反言指放弃后不得反悔。此原则约束保险人，保障被保险人的合理期望。",tw:{ch:"保險原則",q:"「棄權與禁止反言」指？",o:["中介人放棄佣金","投保人放棄索償","雙方終止合約","保險人明知有權主張某項權利（如以違反條款為由拒賠）而放棄後，不得反悔再主張"],e:"棄權是自願放棄已知權利；禁止反言指放棄後不得反悔。此原則約束保險人，保障被保險人的合理期望。"}},
{p:1,ch:"保险原则",q:"「列明危险」（Named Perils）保单的意思是？",o:["除列明除外责任外全部受保","只承保保单中明确列出的危险","承保全世界所有危险","由投保人选定除外责任"],a:1,e:"列明危险保单只保列明的危险；与「全险」保单相反，后者除列明除外责任外一律受保。",tw:{ch:"保險原則",q:"「列明危險」（Named Perils）保單的意思是？",o:["除列明除外責任外全部受保","只承保保單中明確列出的危險","承保全世界所有危險","由投保人選定除外責任"],e:"列明危險保單隻保列明的危險；與「全險」保單相反，後者除列明除外責任外一律受保。"}},
{p:1,ch:"保险原则",q:"除外责任条款的字眼有歧义时，一般如何解释？",o:["一律从严解释","一律视作无效","作有利于保险人的解释","作不利于保险人的解释"],a:3,e:"除外条款须清晰明确表达；有疑义时按不利于草拟人原则解释，即作对被保险人有利的解释。",tw:{ch:"保險原則",q:"除外責任條款的字眼有歧義時，一般如何解釋？",o:["一律從嚴解釋","一律視作無效","作有利於保險人的解釋","作不利於保險人的解釋"],e:"除外條款須清晰明確表達；有疑義時按不利於草擬人原則解釋，即作對被保險人有利的解釋。"}},
{p:1,ch:"保险原则",q:"某楼宇实际价值 150 万，投保火险保额 90 万，火灾损失 30 万，保单含比例分摊条款，保险人应赔？",o:["30 万","22.5 万","15 万","18 万"],a:3,e:"30 万 ×（90 万 ÷ 150 万）= 18 万。不足额投保时，被保险人须自行承担差额部分。",tw:{ch:"保險原則",q:"某樓宇實際價值 150 萬，投保火險保額 90 萬，火災損失 30 萬，保單含比例分攤條款，保險人應賠？",o:["30 萬","22.5 萬","15 萬","18 萬"],e:"30 萬 ×（90 萬 ÷ 150 萬）= 18 萬。不足額投保時，被保險人須自行承擔差額部分。"}},
{p:1,ch:"保险原则",q:"同一标的向两家公司重复投保火险（均含比例分摊条款），发生损失时？",o:["先出单的公司全赔","两家公司按各自保额占总保额的比例分摊赔偿","各赔一半","由投保人任选一家全赔"],a:1,e:"重复保险下各保险人按比例分担，确保被保险人合计获得的赔偿不超过实际损失（弥偿原则）。",tw:{ch:"保險原則",q:"同一標的向兩家公司重複投保火險（均含比例分攤條款），發生損失時？",o:["先出單的公司全賠","兩家公司按各自保額佔總保額的比例分攤賠償","各賠一半","由投保人任選一家全賠"],e:"重複保險下各保險人按比例分擔，確保被保險人合計獲得的賠償不超過實際損失（彌償原則）。"}},
{p:1,ch:"保险原则",q:"损失发生后，被保险人应采取什么行动？",o:["尽力施救，防止损失扩大（合理的施救费用通常可获补偿）","销毁现场证据","等候保险人指示才行动","立即撤离并放弃标的"],a:0,e:"被保险人有义务于损失发生时尽力施救（Sue and Labour），因此招致的合理费用一般可由保险人补偿。",tw:{ch:"保險原則",q:"損失發生後，被保險人應採取什麼行動？",o:["盡力施救，防止損失擴大（合理的施救費用通常可獲補償）","銷燬現場證據","等候保險人指示才行動","立即撤離並放棄標的"],e:"被保險人有義務於損失發生時盡力施救（Sue and Labour），因此招致的合理費用一般可由保險人補償。"}},
{p:1,ch:"保险原则",q:"代位（Subrogation）原则的主要目的是？",o:["防止被保险人因同一损失双重受偿，并令造成损失的第三者负上责任","增加保险人利润","降低保费","方便续保"],a:0,e:"代位使保险人赔付后可代被保险人向责任方追偿，避免双重受偿，也确保过失方承担后果。",tw:{ch:"保險原則",q:"代位（Subrogation）原則的主要目的是？",o:["防止被保險人因同一損失雙重受償，並令造成損失的第三者負上責任","增加保險人利潤","降低保費","方便續保"],e:"代位使保險人賠付後可代被保險人向責任方追償，避免雙重受償，也確保過失方承擔後果。"}},
{p:1,ch:"保险原则",q:"人身意外保险适用弥偿原则吗？",o:["视乎意外类型","不适用，属利益保单，按约定金额给付","适用","只适用于一半赔偿额"],a:1,e:"与人寿保险一样，人身意外保险属利益保单，按保单金额给付，不适用弥偿、分担及代位原则。",tw:{ch:"保險原則",q:"人身意外保險適用彌償原則嗎？",o:["視乎意外類型","不適用，屬利益保單，按約定金額給付","適用","只適用於一半賠償額"],e:"與人壽保險一樣，人身意外保險屬利益保單，按保單金額給付，不適用彌償、分擔及代位原則。"}},
{p:1,ch:"保险公司的主要功能",q:"核保（Underwriting）的主要工作是？",o:["处理客户投诉","推销保险产品","管理公司投资","选择承保的风险及决定采用的条款和费率"],a:3,e:"核保是选择承保的风险、决定承保条件与费率的过程；人寿核保「一次过」、权限集中，一般保险持续监察、权限较分散。",tw:{ch:"保險公司的主要功能",q:"核保（Underwriting）的主要工作是？",o:["處理客户投訴","推銷保險產品","管理公司投資","選擇承保的風險及決定採用的條款和費率"],e:"核保是選擇承保的風險、決定承保條件與費率的過程；人壽核保「一次過」、權限集中，一般保險持續監察、權限較分散。"}},
{p:1,ch:"保险公司的主要功能",q:"人寿保险核保与一般保险核保的主要分别是？",o:["人寿核保一次过、权限集中；一般保险持续监察结果及个别风险、权限分散","人寿核保持续监察，一般保险一次过","一般保险权限更集中","两者完全相同"],a:0,e:"人寿保险核保在签发保单时一次过完成且权限集中；一般保险则持续监察风险，核保权限较分散，续保时可检讨条件甚至取消保单。",tw:{ch:"保險公司的主要功能",q:"人壽保險核保與一般保險核保的主要分別是？",o:["人壽核保一次過、權限集中；一般保險持續監察結果及個別風險、權限分散","人壽核保持續監察，一般保險一次過","一般保險權限更集中","兩者完全相同"],e:"人壽保險核保在簽發保單時一次過完成且權限集中；一般保險則持續監察風險，核保權限較分散，續保時可檢討條件甚至取消保單。"}},
{p:1,ch:"保险公司的主要功能",q:"关于人寿保单的处理，下列哪项正确？",o:["人寿保险合约的存在以收到首次保费为准","人寿保单无须出示文件即可索赔","保险人可随时取消人寿保单","人寿保单错误问题不大"],a:0,e:"保险人不得取消人寿保险；人寿保单文件须于索赔时出示；人寿保单一经签发，没有保单所有人同意不能修改，故出单前核实事实极为重要。",tw:{ch:"保險公司的主要功能",q:"關於人壽保單的處理，下列哪項正確？",o:["人壽保險合約的存在以收到首次保費為準","人壽保單無須出示文件即可索賠","保險人可隨時取消人壽保單","人壽保單錯誤問題不大"],e:"保險人不得取消人壽保險；人壽保單文件須於索賠時出示；人壽保單一經簽發，沒有保單所有人同意不能修改，故出單前核實事實極為重要。"}},
{p:1,ch:"保险公司的主要功能",q:"保险理赔处理的两个基本考虑是？",o:["责任与赔偿数额","保费与佣金","市场与促销","核保与投资"],a:0,e:"理赔分两步：先确定保险人的法律责任（责任），再厘定应赔金额（数额 Quantum）。",tw:{ch:"保險公司的主要功能",q:"保險理賠處理的兩個基本考慮是？",o:["責任與賠償數額","保費與佣金","市場與促銷","核保與投資"],e:"理賠分兩步：先確定保險人的法律責任（責任），再釐定應賠金額（數額 Quantum）。"}},
{p:1,ch:"保险公司的主要功能",q:"再保险对保单持有人的直接影响是？",o:["可直接向再保险人索赔","保单自动升级为全险","无直接影响，保单持有人无权得知再保险安排","保费必然降低"],a:2,e:"再保险是保险人之间的风险分摊安排，对保单持有人没有直接影响，保单持有人亦无权得知有关安排。",tw:{ch:"保險公司的主要功能",q:"再保險對保單持有人的直接影響是？",o:["可直接向再保險人索賠","保單自動升級為全險","無直接影響，保單持有人無權得知再保險安排","保費必然降低"],e:"再保險是保險人之間的風險分攤安排，對保單持有人沒有直接影響，保單持有人亦無權得知有關安排。"}},
{p:1,ch:"保险公司的主要功能",q:"《保险业条例》对长期业务保险人的精算要求包括？",o:["精算师由保险经纪担任","无须委任精算师","只需每月评估一次","委任获保监局接纳的精算师，并每年评估资产及负债"],a:3,e:"经营长期业务的保险人须委任合资格并获保监局接纳的精算师，每年评估资产与负债；从事汽车或雇员补偿保险业务的还须每年作精算检讨。",tw:{ch:"保險公司的主要功能",q:"《保險業條例》對長期業務保險人的精算要求包括？",o:["精算師由保險經紀擔任","無須委任精算師","只需每月評估一次","委任獲保監局接納的精算師，並每年評估資產及負債"],e:"經營長期業務的保險人須委任合資格並獲保監局接納的精算師，每年評估資產與負債；從事汽車或僱員補償保險業務的還須每年作精算檢討。"}},
{p:1,ch:"保险公司的主要功能",q:"保险产品开发的起点通常是？",o:["培训销售人员","印制保单册子","市场调研，识别客户的保障需要","精算定价"],a:2,e:"产品开发由识别市场需求开始，继而设计保障范围、精算定价、核保规则及行销计划。",tw:{ch:"保險公司的主要功能",q:"保險產品開發的起點通常是？",o:["培訓銷售人員","印製保單冊子","市場調研，識別客户的保障需要","精算定價"],e:"產品開發由識別市場需求開始，繼而設計保障範圍、精算定價、核保規則及行銷計劃。"}},
{p:1,ch:"保险公司的主要功能",q:"下列哪项不属于精算师的职责？",o:["厘定费率所用的假设（死亡率、利率、费用率）","逐宗审批所有理赔个案","评估长期业务负债及准备金","进行经验分析（如死亡率、退保率）"],a:1,e:"理赔审批属理赔部门工作；精算师负责定价假设、准备金评估、经验分析及财务报告支持。",tw:{ch:"保險公司的主要功能",q:"下列哪項不屬於精算師的職責？",o:["釐定費率所用的假設（死亡率、利率、費用率）","逐宗審批所有理賠個案","評估長期業務負債及準備金","進行經驗分析（如死亡率、退保率）"],e:"理賠審批屬理賠部門工作；精算師負責定價假設、準備金評估、經驗分析及財務報告支持。"}},
{p:1,ch:"保险公司的主要功能",q:"临时再保险（Facultative Reinsurance）的特点是？",o:["按合约自动分保","无须缴付再保费","逐笔磋商，分出公司及再保险公司均可选择是否接受","只适用于人寿保险"],a:2,e:"临时再保就个别风险逐笔洽商，双方均无义务；合约再保则按合约条款自动分保一整类业务。",tw:{ch:"保險公司的主要功能",q:"臨時再保險（Facultative Reinsurance）的特點是？",o:["按合約自動分保","無須繳付再保費","逐筆磋商，分出公司及再保險公司均可選擇是否接受","只適用於人壽保險"],e:"臨時再保就個別風險逐筆洽商，雙方均無義務；合約再保則按合約條款自動分保一整類業務。"}},
{p:1,ch:"保险公司的主要功能",q:"合约再保险的特点是？",o:["只可分保一笔业务","只适用于车险","分出公司凡属合约范围内的业务，必须按合约条件自动分保","逐笔洽商才生效"],a:2,e:"合约再保以长期合约为基础，约定范围内的业务自动分保，手续较简便，是再保的主要形式。",tw:{ch:"保險公司的主要功能",q:"合約再保險的特點是？",o:["只可分保一筆業務","只適用於車險","分出公司凡屬合約範圍內的業務，必須按合約條件自動分保","逐筆洽商才生效"],e:"合約再保以長期合約為基礎，約定範圍內的業務自動分保，手續較簡便，是再保的主要形式。"}},
{p:1,ch:"保险公司的主要功能",q:"理赔调查的主要目的是？",o:["拖延赔付","核实索偿的真伪，防止欺诈，并协助确定法律责任及赔偿金额","向客户推销附加保障","增加保费收入"],a:1,e:"调查可为保险人提供独立证据，核实事故原因及损失程度，既防止欺诈，也确保获赔者得到公平、迅速的赔偿。",tw:{ch:"保險公司的主要功能",q:"理賠調查的主要目的是？",o:["拖延賠付","核實索償的真偽，防止欺詐，並協助確定法律責任及賠償金額","向客户推銷附加保障","增加保費收入"],e:"調查可為保險人提供獨立證據，核實事故原因及損失程度，既防止欺詐，也確保獲賠者得到公平、迅速的賠償。"}},
{p:1,ch:"保险公司的主要功能",q:"为何投资表现对长期保险人（寿险公司）尤其重要？",o:["客户要求每年分红","法律禁止寿险公司投资","与保单负债无关","保单利益往往在多年后才给付，须靠稳健投资回报支持负债"],a:3,e:"长期业务的负债期极长，保费收入与给付之间的时间差须以投资增值填补，故投资是寿险公司的核心功能之一。",tw:{ch:"保險公司的主要功能",q:"為何投資表現對長期保險人（壽險公司）尤其重要？",o:["客户要求每年分紅","法律禁止壽險公司投資","與保單負債無關","保單利益往往在多年後才給付，須靠穩健投資回報支持負債"],e:"長期業務的負債期極長，保費收入與給付之間的時間差須以投資增值填補，故投資是壽險公司的核心功能之一。"}},
{p:1,ch:"保险公司的主要功能",q:"理赔处理中「责任」（Liability）阶段要确定的是？",o:["代理人的佣金","再保险人的意见","客户的续保意愿","危险是否属于受保范围、保单是否有效、有否违反条款"],a:3,e:"先确定保险人的法律责任（是否受保、保单是否有效、有否违反最大诚信或条款），再进入赔偿数额（Quantum）的厘定。",tw:{ch:"保險公司的主要功能",q:"理賠處理中「責任」（Liability）階段要確定的是？",o:["代理人的佣金","再保險人的意見","客户的續保意願","危險是否屬於受保範圍、保單是否有效、有否違反條款"],e:"先確定保險人的法律責任（是否受保、保單是否有效、有否違反最大誠信或條款），再進入賠償數額（Quantum）的釐定。"}},
{p:1,ch:"保险公司的主要功能",q:"为何人寿保单的记录及文件处理要求特别高？",o:["与合约无关","只为符合审计格式","因为文件越多越好看","人寿保单一经签发不能单方修改，记录错误往往须保单所有人同意方可更正"],a:3,e:"人寿保单是长期、不可由保险人单方更改的合约，任何记录错误都可能影响日后的给付，故须于签发前仔细核实。",tw:{ch:"保險公司的主要功能",q:"為何人壽保單的記錄及文件處理要求特別高？",o:["與合約無關","只為符合審計格式","因為文件越多越好看","人壽保單一經簽發不能單方修改，記錄錯誤往往須保單所有人同意方可更正"],e:"人壽保單是長期、不可由保險人單方更改的合約，任何記錄錯誤都可能影響日後的給付，故須於簽發前仔細核實。"}},
{p:1,ch:"香港保险业的结构",q:"保险代理人在法律上代表谁的利益？",o:["投保人","保监局","保险人（保险公司）","保险经纪"],a:2,e:"代理人代表保险人销售保单；保险经纪则代表投保人（客户）安排保险，两者法律地位不同。",tw:{ch:"香港保險業的結構",q:"保險代理人在法律上代表誰的利益？",o:["投保人","保監局","保險人（保險公司）","保險經紀"],e:"代理人代表保險人銷售保單；保險經紀則代表投保人（客户）安排保險，兩者法律地位不同。"}},
{p:1,ch:"香港保险业的结构",q:"香港保险业联会（HKFI）的角色是？",o:["政府发牌机构","投资监管机关","专责处理索偿的法院","业界自律组织，制订并执行行业守则"],a:3,e:"HKFI 是保险业界自律组织，负责执行《承保商专业守则》等行业规范；发牌监管由独立的保监局负责。",tw:{ch:"香港保險業的結構",q:"香港保險業聯會（HKFI）的角色是？",o:["政府發牌機構","投資監管機關","專責處理索償的法院","業界自律組織，制訂並執行行業守則"],e:"HKFI 是保險業界自律組織，負責執行《承保商專業守則》等行業規範；發牌監管由獨立的保監局負責。"}},
{p:1,ch:"香港保险业的结构",q:"相互保险公司（Mutual Company）的特点是？",o:["由股东拥有","没有股东，由分红保单持有人拥有","只经营一般保险","由政府全资拥有"],a:1,e:"相互保险公司没有股东，由分红保单持有人拥有，毋须与股东分享利润；缺点是需要筹集新资本时较困难。",tw:{ch:"香港保險業的結構",q:"相互保險公司（Mutual Company）的特點是？",o:["由股東擁有","沒有股東，由分紅保單持有人擁有","只經營一般保險","由政府全資擁有"],e:"相互保險公司沒有股東，由分紅保單持有人擁有，毋須與股東分享利潤；缺點是需要籌集新資本時較困難。"}},
{p:1,ch:"香港保险业的结构",q:"「专属代理人」指？",o:["只代表一家保险公司销售其产品的代理人","只为多家公司销售的中介","独立的保险经纪","兼营银行保险的中介"],a:0,e:"专属（单一）代理人只代表一家保险公司；代理可有多名代理同时服务同一家公司，与独立经纪不同。",tw:{ch:"香港保險業的結構",q:"「專屬代理人」指？",o:["只代表一家保險公司銷售其產品的代理人","只為多家公司銷售的中介","獨立的保險經紀","兼營銀行保險的中介"],e:"專屬（單一）代理人只代表一家保險公司；代理可有多名代理同時服務同一家公司，與獨立經紀不同。"}},
{p:1,ch:"香港保险业的结构",q:"劳合社（Lloyd's）的本质是？",o:["由个人承保人（Name）及承保组合组成、以会员制运作的保险市场","一家跨国保险公司","政府保险部门","保险经纪公会"],a:0,e:"劳合社是历史悠久的市场，由会员（个人或公司承保人）通过承保组合（Syndicate）承保风险，并非一家保险公司。",tw:{ch:"香港保險業的結構",q:"勞合社（Lloyd's）的本質是？",o:["由個人承保人（Name）及承保組合組成、以會員制運作的保險市場","一家跨國保險公司","政府保險部門","保險經紀公會"],e:"勞合社是歷史悠久的市場，由會員（個人或公司承保人）通過承保組合（Syndicate）承保風險，並非一家保險公司。"}},
{p:1,ch:"香港保险业的结构",q:"「非授权保险人」指？",o:["没有注册的银行","未获保监局授权在本港经营保险业务的保险人","再保险公司","无牌中介人"],a:1,e:"在香港经营保险业务须获保监局授权；未经授权而经营即属违法，客户亦不受相关保障。",tw:{ch:"香港保險業的結構",q:"「非授權保險人」指？",o:["沒有註冊的銀行","未獲保監局授權在本港經營保險業務的保險人","再保險公司","無牌中介人"],e:"在香港經營保險業務須獲保監局授權；未經授權而經營即屬違法，客户亦不受相關保障。"}},
{p:1,ch:"香港保险业的结构",q:"保险人申请授权须符合的基本要求包括？",o:["最低资本及偿付能力要求、适当人选及足够再保险安排","由政府担保全部保单","毋须任何条件","只须注册有限公司"],a:0,e:"授权条件包括最低实缴资本、足够的资产净值（偿付能力）、董事及控权人属适当人选，以及足够的再保险安排等。",tw:{ch:"香港保險業的結構",q:"保險人申請授權須符合的基本要求包括？",o:["最低資本及償付能力要求、適當人選及足夠再保險安排","由政府擔保全部保單","毋須任何條件","只須註冊有限公司"],e:"授權條件包括最低實繳資本、足夠的資產淨值（償付能力）、董事及控權人屬適當人選，以及足夠的再保險安排等。"}},
{p:1,ch:"香港保险业的结构",q:"专属自保保险公司（Captive Insurer）的主要作用是？",o:["规管保险市场","向公众零售保单","管理退休基金","为母公司及其关联企业的风险提供保险"],a:3,e:"专属自保公司由大企业集团设立，主要为集团自身的风险承保，以保留风险及节省保费成本。",tw:{ch:"香港保險業的結構",q:"專屬自保保險公司（Captive Insurer）的主要作用是？",o:["規管保險市場","向公眾零售保單","管理退休基金","為母公司及其關聯企業的風險提供保險"],e:"專屬自保公司由大企業集團設立，主要為集團自身的風險承保，以保留風險及節省保費成本。"}},
{p:1,ch:"香港保险业的结构",q:"保险经纪公司的收入主要来自？",o:["保险人支付的佣金（及按服务协议向客户收取的费用）","政府资助","保监局拨款","向客户罚款"],a:0,e:"经纪主要按保单收取保险人佣金，亦可与客户约定收取咨询或服务费用，但须披露利益冲突。",tw:{ch:"香港保險業的結構",q:"保險經紀公司的收入主要來自？",o:["保險人支付的佣金（及按服務協議向客户收取的費用）","政府資助","保監局撥款","向客户罰款"],e:"經紀主要按保單收取保險人佣金，亦可與客户約定收取諮詢或服務費用，但須披露利益衝突。"}},
{p:1,ch:"香港保险业的结构",q:"再保险经纪人的角色是？",o:["承保个人保单","作为分出公司的顾问，代为洽购最有利的再保安排","代表再保险人核保","发牌监管再保市场"],a:1,e:"再保险经纪代表分出公司（原保险人）向再保险市场洽购再保，提供技术意见及安排合约。",tw:{ch:"香港保險業的結構",q:"再保險經紀人的角色是？",o:["承保個人保單","作為分出公司的顧問，代為洽購最有利的再保安排","代表再保險人核保","發牌監管再保市場"],e:"再保險經紀代表分出公司（原保險人）向再保險市場洽購再保，提供技術意見及安排合約。"}},
{p:1,ch:"香港保险业的结构",q:"相互保险公司的主要缺点是？",o:["不受法例规管","不能承保人寿业务","需要筹集新资本时较为困难","不能派发红利"],a:2,e:"相互公司没有股东，增资只能靠盈余或借贷，灵活性较低；其余选项均非事实（相互公司多经营分红寿险）。",tw:{ch:"香港保險業的結構",q:"相互保險公司的主要缺點是？",o:["不受法例規管","不能承保人壽業務","需要籌集新資本時較為困難","不能派發紅利"],e:"相互公司沒有股東，增資只能靠盈餘或借貸，靈活性較低；其餘選項均非事實（相互公司多經營分紅壽險）。"}},
{p:1,ch:"香港保险业的结构",q:"股份保险公司（Stock/Proprietary Company）的特点是？",o:["没有股东","只经营团体业务","由政府全资拥有","由股东拥有，须向股东负责并追求利润"],a:3,e:"股份公司以股东资金经营，盈余归股东；与由保单持有人拥有的相互公司形成对照。",tw:{ch:"香港保險業的結構",q:"股份保險公司（Stock/Proprietary Company）的特點是？",o:["沒有股東","只經營團體業務","由政府全資擁有","由股東擁有，須向股東負責並追求利潤"],e:"股份公司以股東資金經營，盈餘歸股東；與由保單持有人擁有的相互公司形成對照。"}},
{p:1,ch:"保险业的规管架构",q:"规管香港保险业的主要法例是？",o:["《银行条例》","《公司条例》","《保险业条例》（第 41 章）","《证券及期货条例》"],a:2,e:"《保险业条例》（香港法例第 41 章）是保险业的核心规管法例，由保险业监管局负责执行。",tw:{ch:"保險業的規管架構",q:"規管香港保險業的主要法例是？",o:["《銀行條例》","《公司條例》","《保險業條例》（第 41 章）","《證券及期貨條例》"],e:"《保險業條例》（香港法例第 41 章）是保險業的核心規管法例，由保險業監管局負責執行。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局（IA）的职责包括？",o:["为保单提供担保","审批保险产品设计费","监管保险公司及发牌规管保险中介人","管理强积金"],a:2,e:"保监局负责监管保险公司、审批牌照及规管保险中介人，自 2017 年 12 月起全面接手中介人发牌规管。",tw:{ch:"保險業的規管架構",q:"保險業監管局（IA）的職責包括？",o:["為保單提供擔保","審批保險產品設計費","監管保險公司及發牌規管保險中介人","管理強積金"],e:"保監局負責監管保險公司、審批牌照及規管保險中介人，自 2017 年 12 月起全面接手中介人發牌規管。"}},
{p:1,ch:"保险业的规管架构",q:"「适当人选」（Fit and Proper）准则主要考虑个人持牌人的哪些因素？",o:["学历及外貌","国籍及性别","诚信、品格、财政稳健及胜任能力","年龄及婚姻状况"],a:2,e:"按保监局指引 23，适当人选准则考虑诚信与声誉、品格、财政稳健、知识、经验及胜任能力等，与个人背景中无关的因素（如性别）无关。",tw:{ch:"保險業的規管架構",q:"「適當人選」（Fit and Proper）準則主要考慮個人持牌人的哪些因素？",o:["學歷及外貌","國籍及性別","誠信、品格、財政穩健及勝任能力","年齡及婚姻狀況"],e:"按保監局指引 23，適當人選準則考慮誠信與聲譽、品格、財政穩健、知識、經驗及勝任能力等，與個人背景中無關的因素（如性別）無關。"}},
{p:1,ch:"保险业的规管架构",q:"在香港无牌从事受规管的保险中介活动，后果是？",o:["只属违规罚款","没有任何后果","由保险公司口头警告","属刑事罪行，可处罚款及监禁"],a:3,e:"《保险业条例》第 64G 条规定，无牌进行受规管活动即属刑事罪行，最高可处罚款及监禁（可高达 100 万港元罚款及 2 年监禁）。",tw:{ch:"保險業的規管架構",q:"在香港無牌從事受規管的保險中介活動，後果是？",o:["只屬違規罰款","沒有任何後果","由保險公司口頭警告","屬刑事罪行，可處罰款及監禁"],e:"《保險業條例》第 64G 條規定，無牌進行受規管活動即屬刑事罪行，最高可處罰款及監禁（可高達 100 萬港元罰款及 2 年監禁）。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》由哪个机构执行？",o:["保险业监管局","香港金融管理局","消费者委员会","香港保险业联会（HKFI）"],a:3,e:"《承保商专业守则》属行业自律规范，由香港保险业联会执行，适用于在香港签发、以私人用途投保的个人保单。",tw:{ch:"保險業的規管架構",q:"《承保商專業守則》由哪個機構執行？",o:["保險業監管局","香港金融管理局","消費者委員會","香港保險業聯會（HKFI）"],e:"《承保商專業守則》屬行業自律規範，由香港保險業聯會執行，適用於在香港簽發、以私人用途投保的個人保單。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险代理人的登记委任程序是？",o:["无须任何登记","由保险公司委任并向保监局登记后方可在其名下经营","向税务局登记","自行向保监局申请即可执业"],a:1,e:"代理人须由持牌保险公司委任，再由保险公司向保监局办理登记；个人不能脱离保险公司自行持牌执业。",tw:{ch:"保險業的規管架構",q:"持牌保險代理人的登記委任程序是？",o:["無須任何登記","由保險公司委任並向保監局登記後方可在其名下經營","向税務局登記","自行向保監局申請即可執業"],e:"代理人須由持牌保險公司委任，再由保險公司向保監局辦理登記；個人不能脱離保險公司自行持牌執業。"}},
{p:1,ch:"保险业的规管架构",q:"保险经纪在法律上代表谁，并须向谁负责？",o:["保险公司股东；股东","保险人；保险人","保监局；保监局","投保人／潜在客户；投保人"],a:3,e:"保险经纪代表投保人（客户）的利益，就安排保险事宜向客户负责，与代表保险公司的代理人有本质区别。",tw:{ch:"保險業的規管架構",q:"保險經紀在法律上代表誰，並須向誰負責？",o:["保險公司股東；股東","保險人；保險人","保監局；保監局","投保人／潛在客户；投保人"],e:"保險經紀代表投保人（客户）的利益，就安排保險事宜向客户負責，與代表保險公司的代理人有本質區別。"}},
{p:1,ch:"保险业的规管架构",q:"持续专业进修（CPD）要求的目的是？",o:["取代资格考试","增加保险公司收入","只为新入行人士而设","维持及提升个人持牌人的专业能力与知识"],a:3,e:"持牌中介人须按规管要求完成持续专业进修时数，以维持专业能力；具体要求以保监局最新公布为准。",tw:{ch:"保險業的規管架構",q:"持續專業進修（CPD）要求的目的是？",o:["取代資格考試","增加保險公司收入","只為新入行人士而設","維持及提升個人持牌人的專業能力與知識"],e:"持牌中介人須按規管要求完成持續專業進修時數，以維持專業能力；具體要求以保監局最新公佈為準。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局（IA）于哪一年成立？",o:["2021 年","2015 年","2008 年","1997 年"],a:1,e:"保监局于 2015 年底根据《保险业条例》成立，其后全面接手保险公司及保险中介人的规管工作（此前中介人由业界自律机构规管）。",tw:{ch:"保險業的規管架構",q:"保險業監管局（IA）於哪一年成立？",o:["2021 年","2015 年","2008 年","1997 年"],e:"保監局於 2015 年底根據《保險業條例》成立，其後全面接手保險公司及保險中介人的規管工作（此前中介人由業界自律機構規管）。"}},
{p:1,ch:"保险业的规管架构",q:"保险中介人牌照类别不包括？",o:["保险经纪公司","业务代表（代理人／经纪）","个人保险代理人","证券经纪"],a:3,e:"受规管的保险中介人分为个人代理人、保险代理机构、业务代表，以及保险经纪公司与保险经纪；证券经纪不受《保险业条例》规管。",tw:{ch:"保險業的規管架構",q:"保險中介人牌照類別不包括？",o:["保險經紀公司","業務代表（代理人／經紀）","個人保險代理人","證券經紀"],e:"受規管的保險中介人分為個人代理人、保險代理機構、業務代表，以及保險經紀公司與保險經紀；證券經紀不受《保險業條例》規管。"}},
{p:1,ch:"保险业的规管架构",q:"保险公司委任个人代理人后，须于多久内向保监局登记？",o:["30 天内","无须登记","7 天内","半年内"],a:2,e:"代理人须由保险公司委任，并须于委任后 7 天内向保监局登记；登记后代理人才可合法展业。",tw:{ch:"保險業的規管架構",q:"保險公司委任個人代理人後，須於多久內向保監局登記？",o:["30 天內","無須登記","7 天內","半年內"],e:"代理人須由保險公司委任，並須於委任後 7 天內向保監局登記；登記後代理人才可合法展業。"}},
{p:1,ch:"保险业的规管架构",q:"保监局对违规持牌中介人的纪律处分权力不包括？",o:["处以罚款","作出公开谴责","判处监禁","吊销或撤销牌照"],a:2,e:"保监局可谴责、罚款、暂时吊销或撤销牌照；监禁属刑事刑罚，只能由法院判处（如无牌经营）。",tw:{ch:"保險業的規管架構",q:"保監局對違規持牌中介人的紀律處分權力不包括？",o:["處以罰款","作出公開譴責","判處監禁","吊銷或撤銷牌照"],e:"保監局可譴責、罰款、暫時吊銷或撤銷牌照；監禁屬刑事刑罰，只能由法院判處（如無牌經營）。"}},
{p:1,ch:"保险业的规管架构",q:"评估「适当人选」时，保监局可能考虑的因素包括？",o:["身高与外貌","破产纪录、刑事定罪纪录、纪律处分纪录","星座与血型","婚姻状况"],a:1,e:"适当人选评估聚焦诚信与声誉（如刑事纪录、破产纪录、过往纪律处分）、财政稳健、知识及经验等实质因素。",tw:{ch:"保險業的規管架構",q:"評估「適當人選」時，保監局可能考慮的因素包括？",o:["身高與外貌","破產紀錄、刑事定罪紀錄、紀律處分紀錄","星座與血型","婚姻狀況"],e:"適當人選評估聚焦誠信與聲譽（如刑事紀錄、破產紀錄、過往紀律處分）、財政穩健、知識及經驗等實質因素。"}},
{p:1,ch:"保险业的规管架构",q:"保险经纪公司须委任什么人以监督其合规运作？",o:["任何持牌代表","非执行董事","客户主任","负责人（Responsible Officer）"],a:3,e:"保险经纪公司须委任至少一名负责人，负责确保公司遵守《保险业条例》及其持牌条件。",tw:{ch:"保險業的規管架構",q:"保險經紀公司須委任什麼人以監督其合規運作？",o:["任何持牌代表","非執行董事","客户主任","負責人（Responsible Officer）"],e:"保險經紀公司須委任至少一名負責人，負責確保公司遵守《保險業條例》及其持牌條件。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险中介人须遵守《打击洗钱及恐怖分子资金筹集条例》的主要要求是？",o:["限制保费金额","统一佣金标准","进行客户尽职审查（核实身份、了解资金来源）并备存纪录","禁止销售任何保险产品"],a:2,e:"保险中介人属指定非金融业务，须履行客户尽职审查、持续监察及备存纪录等反洗钱责任。",tw:{ch:"保險業的規管架構",q:"持牌保險中介人須遵守《打擊洗錢及恐怖分子資金籌集條例》的主要要求是？",o:["限制保費金額","統一佣金標準","進行客户盡職審查（核實身份、瞭解資金來源）並備存紀錄","禁止銷售任何保險產品"],e:"保險中介人屬指定非金融業務，須履行客户盡職審查、持續監察及備存紀錄等反洗錢責任。"}},
{p:1,ch:"保险业的规管架构",q:"无牌在香港进行受规管的保险中介活动，最高可被判？",o:["没收佣金即可","罚款 100 万港元及监禁 2 年","罚款 1,000 元","只作口头警告"],a:1,e:"《保险业条例》第 64G 条将无牌经营定为刑事罪行，最高可处罚款 100 万港元及监禁 2 年。",tw:{ch:"保險業的規管架構",q:"無牌在香港進行受規管的保險中介活動，最高可被判？",o:["沒收佣金即可","罰款 100 萬港元及監禁 2 年","罰款 1,000 元","只作口頭警告"],e:"《保險業條例》第 64G 條將無牌經營定為刑事罪行，最高可處罰款 100 萬港元及監禁 2 年。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人向客户提供建议时，最基本的专业操守是？",o:["推荐佣金最高的产品","只推销公司指定产品","按客户需要及负担能力提供合适建议","隐瞒保单的重要条款"],a:2,e:"合适性原则是核心操守：建议须基于客户的需要、目标及负担能力，而非中介人的佣金利益；重要条款必须披露，不得误导。",tw:{ch:"職業道德及其他有關問題",q:"中介人向客户提供建議時，最基本的專業操守是？",o:["推薦佣金最高的產品","只推銷公司指定產品","按客户需要及負擔能力提供合適建議","隱瞞保單的重要條款"],e:"合適性原則是核心操守：建議須基於客户的需要、目標及負擔能力，而非中介人的佣金利益；重要條款必須披露，不得誤導。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人对于客户提供的个人及财务资料应如何处理？",o:["可出售予第三方","保密，不得作无关用途","可用于其他客户推销","无须理会"],a:1,e:"客户资料保密是基本职业道德；中介人只可将资料用于其提供的用途，并须遵守《个人资料（私隐）条例》。",tw:{ch:"職業道德及其他有關問題",q:"中介人對於客户提供的個人及財務資料應如何處理？",o:["可出售予第三方","保密，不得作無關用途","可用於其他客户推銷","無須理會"],e:"客户資料保密是基本職業道德；中介人只可將資料用於其提供的用途，並須遵守《個人資料（私隱）條例》。"}},
{p:1,ch:"职业道德及其他有关问题",q:"当保险中介人的佣金收入与其建议存在利益冲突时，正确的做法是？",o:["劝客户加买","向客户披露有关利益冲突","无须理会","隐瞒佣金"],a:1,e:"存在利益冲突时应向客户披露，让客户在知情下决定，这是「客户为先」职业道德的体现。",tw:{ch:"職業道德及其他有關問題",q:"當保險中介人的佣金收入與其建議存在利益衝突時，正確的做法是？",o:["勸客户加買","向客户披露有關利益衝突","無須理會","隱瞞佣金"],e:"存在利益衝突時應向客户披露，讓客户在知情下決定，這是「客户為先」職業道德的體現。"}},
{p:1,ch:"职业道德及其他有关问题",q:"投保人与保险公司就保单产生合约纠纷，可向哪个独立机构提出投诉？",o:["保险投诉局","破产管理署","税务局","立法会"],a:0,e:"保险投诉局以调解及仲裁方式独立处理保单持有人与保险公司之间的合约纠纷；涉及中介人操守的可向保监局投诉。",tw:{ch:"職業道德及其他有關問題",q:"投保人與保險公司就保單產生合約糾紛，可向哪個獨立機構提出投訴？",o:["保險投訴局","破產管理署","税務局","立法會"],e:"保險投訴局以調解及仲裁方式獨立處理保單持有人與保險公司之間的合約糾紛；涉及中介人操守的可向保監局投訴。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人收受某产品的销售回佣而未向客户披露，主要违反？",o:["税务条例","商品说明条例","廉洁及披露利益冲突的专业操守","只违反公司内部守则"],a:2,e:"隐瞒利益（如回佣）属严重操守失当，违反诚信及披露利益冲突的要求，可被纪律处分。",tw:{ch:"職業道德及其他有關問題",q:"中介人收受某產品的銷售回佣而未向客户披露，主要違反？",o:["税務條例","商品說明條例","廉潔及披露利益衝突的專業操守","只違反公司內部守則"],e:"隱瞞利益（如回佣）屬嚴重操守失當，違反誠信及披露利益衝突的要求，可被紀律處分。"}},
{p:1,ch:"职业道德及其他有关问题",q:"销售投资相连长期保单前进行「财务需要分析」及「风险承受能力评估」的目的是？",o:["代替核保","拖延销售流程","提高保费","确保建议的产品适合客户的情况与风险偏好"],a:3,e:"财务需要分析及风险承受能力评估是投连销售的规定步骤，确保建议合适，保障客户利益。",tw:{ch:"職業道德及其他有關問題",q:"銷售投資相連長期保單前進行「財務需要分析」及「風險承受能力評估」的目的是？",o:["代替核保","拖延銷售流程","提高保費","確保建議的產品適合客户的情況與風險偏好"],e:"財務需要分析及風險承受能力評估是投連銷售的規定步驟，確保建議合適，保障客户利益。"}},
{p:1,ch:"职业道德及其他有关问题",q:"客户对保单有不满，第一步应向谁提出？",o:["传媒","保监局","承保的保险公司","立即入禀法院"],a:2,e:"投诉应先向保险公司提出，让其内部处理；未能解决的可再向保险投诉局（合约纠纷）或保监局（中介人操守）投诉。",tw:{ch:"職業道德及其他有關問題",q:"客户對保單有不滿，第一步應向誰提出？",o:["傳媒","保監局","承保的保險公司","立即入稟法院"],e:"投訴應先向保險公司提出，讓其內部處理；未能解決的可再向保險投訴局（合約糾紛）或保監局（中介人操守）投訴。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人处理客户个人资料须遵守的主要法例是？",o:["《个人资料（私隐）条例》","《公司条例》","《版权条例》","《印花税条例》"],a:0,e:"收集、使用及保管个人资料须符合《个人资料（私隐）条例》的保障资料原则，只可用于收集时声明的用途。",tw:{ch:"職業道德及其他有關問題",q:"中介人處理客户個人資料須遵守的主要法例是？",o:["《個人資料（私隱）條例》","《公司條例》","《版權條例》","《印花税條例》"],e:"收集、使用及保管個人資料須符合《個人資料（私隱）條例》的保障資料原則，只可用於收集時聲明的用途。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人离职后对其旧客户的个人资料应？",o:["可出售图利","随意弃置","可公开分享","继续保密，不得作无关用途"],a:3,e:"保密责任不因离职而终止；个人资料仍受私隐条例保护，不得出售、泄露或作无关用途。",tw:{ch:"職業道德及其他有關問題",q:"中介人離職後對其舊客户的個人資料應？",o:["可出售圖利","隨意棄置","可公開分享","繼續保密，不得作無關用途"],e:"保密責任不因離職而終止；個人資料仍受私隱條例保護，不得出售、泄露或作無關用途。"}},
{p:1,ch:"职业道德及其他有关问题",q:"「客户为先」职业道德的核心含义是？",o:["只服务高净值客户","先完成公司销售指标","把客户的利益置于中介人自身利益之上","优先推销佣金最高的产品"],a:2,e:"客户为先要求建议以客户的需要、目标及负担能力为本，避免及披露利益冲突，重要事项如实说明。",tw:{ch:"職業道德及其他有關問題",q:"「客户為先」職業道德的核心含義是？",o:["只服務高淨值客户","先完成公司銷售指標","把客户的利益置於中介人自身利益之上","優先推銷佣金最高的產品"],e:"客户為先要求建議以客户的需要、目標及負擔能力為本，避免及披露利益衝突，重要事項如實說明。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险的基本性质是？",o:["属弥偿性质的保险","以人的生命为标的、以死亡或生存为给付条件的长期保险","以财物为标的的短期保险","只保意外的保险"],a:1,e:"人寿保险以人的生命为标的，属长期业务，按「利益保单」方式于死亡或期满生存时给付，不适用弥偿原则。",tw:{ch:"人壽保險簡介",q:"人壽保險的基本性質是？",o:["屬彌償性質的保險","以人的生命為標的、以死亡或生存為給付條件的長期保險","以財物為標的的短期保險","只保意外的保險"],e:"人壽保險以人的生命為標的，屬長期業務，按「利益保單」方式於死亡或期滿生存時給付，不適用彌償原則。"}},
{p:3,ch:"人寿保险简介",q:"为什么说人寿保险属于「利益保单」？",o:["可随时取消","按保单约定的金额给付，而非按实际损失计算","无需缴保费","保费可随意调整"],a:1,e:"人寿保险按约定保额给付，人的生命损失难以用金钱衡量，故不计算实际损失，属利益保单，不适用弥偿原则。",tw:{ch:"人壽保險簡介",q:"為什麼說人壽保險屬於「利益保單」？",o:["可隨時取消","按保單約定的金額給付，而非按實際損失計算","無需繳保費","保費可隨意調整"],e:"人壽保險按約定保額給付，人的生命損失難以用金錢衡量，故不計算實際損失，屬利益保單，不適用彌償原則。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险核保及定价的核心统计基础是？",o:["当地天气数据","股票市场指数","楼宇成交记录","死亡率／生命表"],a:3,e:"人寿保险以生命表（死亡率）、预定利率及费用率为定价与核保基础，这是其区别于一般保险的核心。",tw:{ch:"人壽保險簡介",q:"人壽保險核保及定價的核心統計基礎是？",o:["當地天氣數據","股票市場指數","樓宇成交記錄","死亡率／生命表"],e:"人壽保險以生命表（死亡率）、預定利率及費用率為定價與核保基礎，這是其區別於一般保險的核心。"}},
{p:3,ch:"人寿保险简介",q:"投保人以他人的生命投保人寿保险，必须具备什么条件？",o:["对该生命具有可保利益（如亲属或债权关系）","只限直系亲属","对方须年满 18 岁","无须任何条件"],a:0,e:"以他人生命投保须于投保时具有可保利益，如亲属关系、债权债务关系等，以防道德危险与赌博性保单。",tw:{ch:"人壽保險簡介",q:"投保人以他人的生命投保人壽保險，必須具備什麼條件？",o:["對該生命具有可保利益（如親屬或債權關係）","只限直系親屬","對方須年滿 18 歲","無須任何條件"],e:"以他人生命投保須於投保時具有可保利益，如親屬關係、債權債務關係等，以防道德危險與賭博性保單。"}},
{p:3,ch:"人寿保险简介",q:"人寿保单中的「受益人」是指？",o:["签发保单的经理","缴付保费的人","指定于受保人死亡时收取保险金的人","核保的医生"],a:2,e:"受益人由保单所有人指定，于受保人死亡时领取死亡保险金；投保人（保单所有人）与受保人、受益人可以是不同人。",tw:{ch:"人壽保險簡介",q:"人壽保單中的「受益人」是指？",o:["簽發保單的經理","繳付保費的人","指定於受保人死亡時收取保險金的人","核保的醫生"],e:"受益人由保單所有人指定，於受保人死亡時領取死亡保險金；投保人（保單所有人）與受保人、受益人可以是不同人。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险与一般保险的基本分别之一是？",o:["寿险无须核保","一般保险都是利益保单","寿险的死亡必然发生但时间不定；一般保险的损失纯属偶发","寿险都是一年期"],a:2,e:"死亡是必然事件，只是时间不确定，寿险正是承保这个时间风险；一般保险承保的是或然损失。",tw:{ch:"人壽保險簡介",q:"人壽保險與一般保險的基本分別之一是？",o:["壽險無須核保","一般保險都是利益保單","壽險的死亡必然發生但時間不定；一般保險的損失純屬偶發","壽險都是一年期"],e:"死亡是必然事件，只是時間不確定，壽險正是承保這個時間風險；一般保險承保的是或然損失。"}},
{p:3,ch:"人寿保险简介",q:"「均衡保费」制度的意思是？",o:["每期保费相同，早期多缴部分累积形成现金价值","保费逐年递减","只在首年缴付","保费逐年递增"],a:0,e:"均衡保费把高龄时的高保障成本平均摊到各年，早期多缴的保费连同利息累积成现金价值。",tw:{ch:"人壽保險簡介",q:"「均衡保費」制度的意思是？",o:["每期保費相同，早期多繳部分累積形成現金價值","保費逐年遞減","只在首年繳付","保費逐年遞增"],e:"均衡保費把高齡時的高保障成本平均攤到各年，早期多繳的保費連同利息累積成現金價值。"}},
{p:3,ch:"人寿保险简介",q:"「自然保费」制的特点是？",o:["只适用于团体保险","每期保费固定","无须核保","每期保费随年龄递增"],a:3,e:"自然保费按各年龄的当年死亡率计算，随年龄递增；其缺点是晚年保费高昂，容易因负担不起而失保。",tw:{ch:"人壽保險簡介",q:"「自然保費」制的特點是？",o:["只適用於團體保險","每期保費固定","無須核保","每期保費隨年齡遞增"],e:"自然保費按各年齡的當年死亡率計算，隨年齡遞增；其缺點是晚年保費高昂，容易因負擔不起而失保。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险的可保利益金额有否法定上限？",o:["有，不得超过年薪十倍","一般没有上限，视乎投保人需要及财务核保结果","不得超过保费总额","统一为 100 万港元"],a:1,e:"寿险可保利益只要求关系合法存在，金额上没有法定上限；但是否承保及保额多少取决于财务核保（需要与负担能力）。",tw:{ch:"人壽保險簡介",q:"人壽保險的可保利益金額有否法定上限？",o:["有，不得超過年薪十倍","一般沒有上限，視乎投保人需要及財務核保結果","不得超過保費總額","統一為 100 萬港元"],e:"壽險可保利益只要求關係合法存在，金額上沒有法定上限；但是否承保及保額多少取決於財務核保（需要與負擔能力）。"}},
{p:3,ch:"人寿保险简介",q:"保单所有人与受益人可以是同一人吗？",o:["属违法行为","绝对不可以","可以，如自己为自己投保并指定自己为受益人","只限团体保险"],a:2,e:"投保人与受保人、受益人的角色可以重叠（如自己投保、自己受保、指定配偶或自己为受益人）。",tw:{ch:"人壽保險簡介",q:"保單所有人與受益人可以是同一人嗎？",o:["屬違法行為","絕對不可以","可以，如自己為自己投保並指定自己為受益人","只限團體保險"],e:"投保人與受保人、受益人的角色可以重疊（如自己投保、自己受保、指定配偶或自己為受益人）。"}},
{p:3,ch:"人寿保险简介",q:"以配偶的生命投保人寿保险，可保利益来自？",o:["血缘关系","朋友关系","雇佣关系","婚姻关系"],a:3,e:"婚姻（及亲属血缘）关系本身产生可保利益；债权债务、雇佣等经济关系亦可产生。",tw:{ch:"人壽保險簡介",q:"以配偶的生命投保人壽保險，可保利益來自？",o:["血緣關係","朋友關係","僱傭關係","婚姻關係"],e:"婚姻（及親屬血緣）關係本身產生可保利益；債權債務、僱傭等經濟關係亦可產生。"}},
{p:3,ch:"人寿保险简介",q:"「生命表」的用途是？",o:["厘定佣金","预测股市走势","显示各年龄的死亡率，供定价及准备金评估之用","规管中介人"],a:2,e:"生命表按年龄及性别列出死亡率／生存率，是寿险定价、准备金及红利测算的基础。",tw:{ch:"人壽保險簡介",q:"「生命表」的用途是？",o:["釐定佣金","預測股市走勢","顯示各年齡的死亡率，供定價及準備金評估之用","規管中介人"],e:"生命表按年齡及性別列出死亡率／生存率，是壽險定價、準備金及紅利測算的基礎。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险合约一般是？",o:["自动失效的合约","长期合约，保障期可达终身","每日续保","短期、每年续保的合约"],a:1,e:"寿险属长期业务，保障期长达数十年甚至终身，与每年续保的短期一般保险不同。",tw:{ch:"人壽保險簡介",q:"人壽保險合約一般是？",o:["自動失效的合約","長期合約，保障期可達終身","每日續保","短期、每年續保的合約"],e:"壽險屬長期業務，保障期長達數十年甚至終身，與每年續保的短期一般保險不同。"}},
{p:3,ch:"人寿保险简介",q:"投保人与保单所有人可以是不同人吗？",o:["只限亲属","违法","不可以","可以，如雇主为雇员投保"],a:3,e:"保单所有人持有保单权利（如退保、指定受益人），可以由投保人以外的人（如出资的雇主或父母）担任。",tw:{ch:"人壽保險簡介",q:"投保人與保單所有人可以是不同人嗎？",o:["只限親屬","違法","不可以","可以，如僱主為僱員投保"],e:"保單所有人持有保單權利（如退保、指定受益人），可以由投保人以外的人（如出資的僱主或父母）擔任。"}},
{p:3,ch:"人寿保险简介",q:"受益人由谁指定及更改？",o:["一经指定永不可改","由保单所有人指定，可随时更改（可撤销受益人）","由保监局指定","由代理人指定"],a:1,e:"指定及更改受益人是保单所有人的权利；对不可撤销受益人的更改则须该受益人同意。",tw:{ch:"人壽保險簡介",q:"受益人由誰指定及更改？",o:["一經指定永不可改","由保單所有人指定，可隨時更改（可撤銷受益人）","由保監局指定","由代理人指定"],e:"指定及更改受益人是保單所有人的權利；對不可撤銷受益人的更改則須該受益人同意。"}},
{p:3,ch:"人寿保险及年金的种类",q:"定期寿险（Term Life）的给付条件是？",o:["期满生存即赔","只保意外死亡","仅于指定期限内死亡方给付，通常无现金价值","任何时间死亡均赔"],a:2,e:"定期寿险仅在保单指定期内死亡才给付；期满仍生存则合约终止，通常无储蓄成分及现金价值，故相同保额下保费最低。",tw:{ch:"人壽保險及年金的種類",q:"定期壽險（Term Life）的給付條件是？",o:["期滿生存即賠","只保意外死亡","僅於指定期限內死亡方給付，通常無現金價值","任何時間死亡均賠"],e:"定期壽險僅在保單指定期內死亡才給付；期滿仍生存則合約終止，通常無儲蓄成分及現金價值，故相同保額下保費最低。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险（Whole Life）的基本特点是？",o:["只保一年","不可指定受益人","于任何时间死亡均给付保险金","期满生存给付双倍"],a:2,e:"终身寿险于受保人任何时间死亡均给付（保障终身），保费可按年缴或限定期缴，通常累积现金价值。",tw:{ch:"人壽保險及年金的種類",q:"終身壽險（Whole Life）的基本特點是？",o:["只保一年","不可指定受益人","於任何時間死亡均給付保險金","期滿生存給付雙倍"],e:"終身壽險於受保人任何時間死亡均給付（保障終身），保費可按年繳或限定期繳，通常累積現金價值。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险（两全寿险 Endowment）的给付条件是？",o:["期满生存或期内死亡均给付","永不给付","只于期内死亡给付","只于期满生存给付"],a:0,e:"储蓄寿险结合了保障与储蓄：保险期内死亡或期满生存均可获得给付，因此保费较定期及终身寿险高。",tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險（兩全壽險 Endowment）的給付條件是？",o:["期滿生存或期內死亡均給付","永不給付","只於期內死亡給付","只於期滿生存給付"],e:"儲蓄壽險結合了保障與儲蓄：保險期內死亡或期滿生存均可獲得給付，因此保費較定期及終身壽險高。"}},
{p:3,ch:"人寿保险及年金的种类",q:"相同保额下，通常保费最低的人寿保险是？",o:["定期寿险","万用寿险","储蓄寿险","终身寿险"],a:0,e:"定期寿险纯保障、无储蓄成分、保障期有限，故保费最低；保费高低一般为：定期 < 终身 < 储蓄。",tw:{ch:"人壽保險及年金的種類",q:"相同保額下，通常保費最低的人壽保險是？",o:["定期壽險","萬用壽險","儲蓄壽險","終身壽險"],e:"定期壽險純保障、無儲蓄成分、保障期有限，故保費最低；保費高低一般為：定期 < 終身 < 儲蓄。"}},
{p:3,ch:"人寿保险及年金的种类",q:"定期寿险的「可转换条款」指？",o:["可自由转换任何保险公司","可转换为医疗保险","可转换为年金","可于指定期间内转换为终身或储蓄寿险，无须提供可保性证明"],a:3,e:"可转换权让投保人于指定期内将定期险转为长期险而无须提供可保证明，避免因健康转差而失去保障。",tw:{ch:"人壽保險及年金的種類",q:"定期壽險的「可轉換條款」指？",o:["可自由轉換任何保險公司","可轉換為醫療保險","可轉換為年金","可於指定期間內轉換為終身或儲蓄壽險，無須提供可保性證明"],e:"可轉換權讓投保人於指定期內將定期險轉為長期險而無須提供可保證明，避免因健康轉差而失去保障。"}},
{p:3,ch:"人寿保险及年金的种类",q:"定期寿险的「可续保条款」指？",o:["无须缴保费","可按约定续保而无需可保性证明，但保费随年龄递增","保证按原保费续保","只可续保一次"],a:1,e:"可续保权让投保人在保障期届满后续保而无须重新核保，但续保费率按续保时年龄厘定，通常会递增。",tw:{ch:"人壽保險及年金的種類",q:"定期壽險的「可續保條款」指？",o:["無須繳保費","可按約定續保而無需可保性證明，但保費隨年齡遞增","保證按原保費續保","只可續保一次"],e:"可續保權讓投保人在保障期屆滿後續保而無須重新核保，但續保費率按續保時年齡釐定，通常會遞增。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险（Universal Life）的特点不包括？",o:["死亡保险金不可调整","保费缴付灵活","分列定价因素（保障成本、利息、开支）","提供年度报表"],a:0,e:"万用寿险的特点是保费灵活、保额可调、成本透明分列；增加保险利益时可能需要提供可保性证明。",tw:{ch:"人壽保險及年金的種類",q:"萬用壽險（Universal Life）的特點不包括？",o:["死亡保險金不可調整","保費繳付靈活","分列定價因素（保障成本、利息、開支）","提供年度報表"],e:"萬用壽險的特點是保費靈活、保額可調、成本透明分列；增加保險利益時可能需要提供可保性證明。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险保单所有人要求调高死亡保险金，保险人可能要求什么？",o:["无须任何证明","提供可保性证明","转为年金","重新考试"],a:1,e:"调高死亡保险金即增加风险保额，保险人可要求提供可保性证明；调低则通常无须。",tw:{ch:"人壽保險及年金的種類",q:"萬用壽險保單所有人要求調高死亡保險金，保險人可能要求什麼？",o:["無須任何證明","提供可保性證明","轉為年金","重新考試"],e:"調高死亡保險金即增加風險保額，保險人可要求提供可保性證明；調低則通常無須。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投资相连（单位相连）长期保单的价值与什么挂钩？",o:["银行储蓄利率","固定利率","黄金价格","特殊单位化基金／单位信托的单位价值"],a:3,e:"投连保单的价值与所选基金单位价格挂钩，可升可跌，属投资性质的保险产品；任何类型的寿险均可做成投连形式。",tw:{ch:"人壽保險及年金的種類",q:"投資相連（單位相連）長期保單的價值與什麼掛鈎？",o:["銀行儲蓄利率","固定利率","黃金價格","特殊單位化基金／單位信託的單位價值"],e:"投連保單的價值與所選基金單位價格掛鈎，可升可跌，屬投資性質的保險產品；任何類型的壽險均可做成投連形式。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「分红保单」的意思是？",o:["保单所有人可分享保险公司的可分配利润（红利）","只能分两次供款","保费分两年缴交","保单可以拆开"],a:0,e:"分红保单持有人可按公司可分配盈余获得红利（英式为保额增值，美式为现金或缴清增额），多见于相互保险公司。",tw:{ch:"人壽保險及年金的種類",q:"「分紅保單」的意思是？",o:["保單所有人可分享保險公司的可分配利潤（紅利）","只能分兩次供款","保費分兩年繳交","保單可以拆開"],e:"分紅保單持有人可按公司可分配盈餘獲得紅利（英式為保額增值，美式為現金或繳清增額），多見於相互保險公司。"}},
{p:3,ch:"人寿保险及年金的种类",q:"年金（Annuity）的基本给付条件是？",o:["以生存为条件，于约定期间定期给付","按损失计算给付","受保人死亡时一次性给付","只给付一次"],a:0,e:"年金以年金领取人生存为条件，于指定期间或终身定期给付，主要用于退休收入安排。",tw:{ch:"人壽保險及年金的種類",q:"年金（Annuity）的基本給付條件是？",o:["以生存為條件，於約定期間定期給付","按損失計算給付","受保人死亡時一次性給付","只給付一次"],e:"年金以年金領取人生存為條件，於指定期間或終身定期給付，主要用於退休收入安排。"}},
{p:3,ch:"人寿保险及年金的种类",q:"即期年金与延期年金的分别是？",o:["延期年金不可领取","即期保费较高","即期年金于缴清保费后立即开始给付；延期年金于未来约定日期才开始给付","两者完全相同"],a:2,e:"即期年金一次性或即期缴清后立即开始给付；延期年金则积累一段时间后（如退休后）才开始给付。",tw:{ch:"人壽保險及年金的種類",q:"即期年金與延期年金的分別是？",o:["延期年金不可領取","即期保費較高","即期年金於繳清保費後立即開始給付；延期年金於未來約定日期才開始給付","兩者完全相同"],e:"即期年金一次性或即期繳清後立即開始給付；延期年金則積累一段時間後（如退休後）才開始給付。"}},
{p:3,ch:"人寿保险及年金的种类",q:"合资格延期年金保单（QDAP）的最低保费总额要求是？",o:["10 万港元","无要求","18 万港元","100 万港元"],a:2,e:"按保监局指引 19，QDAP 的最低保费总额为 18 万港元，最短保费缴付期为 5 年。",tw:{ch:"人壽保險及年金的種類",q:"合資格延期年金保單（QDAP）的最低保費總額要求是？",o:["10 萬港元","無要求","18 萬港元","100 萬港元"],e:"按保監局指引 19，QDAP 的最低保費總額為 18 萬港元，最短保費繳付期為 5 年。"}},
{p:3,ch:"人寿保险及年金的种类",q:"QDAP 的年金期规定包括？",o:["最短 20 年，55 岁开始","无任何规定","最短 3 年，45 岁开始","最短 10 年，最早可于年金领取人年满 50 岁开始"],a:3,e:"QDAP 要求：最短年金期 10 年、年金最早于领取人年满 50 岁开始、给付频率至少每年一次。",tw:{ch:"人壽保險及年金的種類",q:"QDAP 的年金期規定包括？",o:["最短 20 年，55 歲開始","無任何規定","最短 3 年，45 歲開始","最短 10 年，最早可於年金領取人年滿 50 歲開始"],e:"QDAP 要求：最短年金期 10 年、年金最早於領取人年滿 50 歲開始、給付頻率至少每年一次。"}},
{p:3,ch:"人寿保险及年金的种类",q:"缴付合资格延期年金保费的税务扣除上限是？",o:["无限额","每人每年 10 万港元","不可扣税","每人每年 6 万港元（与强积金可扣税自愿性供款合并计算）"],a:3,e:"QDAP 保费与 TVC 合并计算，每人每年最高 6 万港元扣除额；配偶为联合年金领取人的夫妇可申请合共 12 万港元。",tw:{ch:"人壽保險及年金的種類",q:"繳付合資格延期年金保費的税務扣除上限是？",o:["無限額","每人每年 10 萬港元","不可扣税","每人每年 6 萬港元（與強積金可扣税自願性供款合併計算）"],e:"QDAP 保費與 TVC 合併計算，每人每年最高 6 萬港元扣除額；配偶為聯合年金領取人的夫婦可申請合共 12 萬港元。"}},
{p:3,ch:"人寿保险及年金的种类",q:"递减定期寿险的常见用途是？",o:["退休收入","教育储蓄","遗产规划","按揭贷款保障（保额随贷款余额递减）"],a:3,e:"递减定期寿保障期与还款期一致，保额随贷款余额下降，保费较定额定期寿险低，正好配合按揭保障需要。",tw:{ch:"人壽保險及年金的種類",q:"遞減定期壽險的常見用途是？",o:["退休收入","教育儲蓄","遺產規劃","按揭貸款保障（保額隨貸款餘額遞減）"],e:"遞減定期壽保障期與還款期一致，保額隨貸款餘額下降，保費較定額定期壽險低，正好配合按揭保障需要。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「定额定期寿险」的保额特点是？",o:["保障期内保额维持不变","保额逐年递增","保额逐年递减","只保意外"],a:0,e:"定额定期寿险于整个保障期内保额不变，适合替代收入或支付遗产开支等固定需要。",tw:{ch:"人壽保險及年金的種類",q:"「定額定期壽險」的保額特點是？",o:["保障期內保額維持不變","保額逐年遞增","保額逐年遞減","只保意外"],e:"定額定期壽險於整個保障期內保額不變，適合替代收入或支付遺產開支等固定需要。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险的保费缴付方式可以是？",o:["一次性趸缴或于指定期内（如 20 年）分期缴付","只能一次性趸缴","无须缴付","只能缴到 40 岁"],a:0,e:"终身寿险保费可于签约时一次缴清，或按年于限定年数内缴清；缴清后保障维持终身。",tw:{ch:"人壽保險及年金的種類",q:"終身壽險的保費繳付方式可以是？",o:["一次性躉繳或於指定期內（如 20 年）分期繳付","只能一次性躉繳","無須繳付","只能繳到 40 歲"],e:"終身壽險保費可於簽約時一次繳清，或按年於限定年數內繳清；繳清後保障維持終身。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险（两全保险）的满期金常见用途是？",o:["强制捐出","偿还信用卡欠款","缴付罚款","子女教育基金或退休资金"],a:3,e:"储蓄寿险于期满时给付满期金，常被规划作教育或退休用途；期内死亡则给付死亡保险金。",tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險（兩全保險）的滿期金常見用途是？",o:["強制捐出","償還信用卡欠款","繳付罰款","子女教育基金或退休資金"],e:"儲蓄壽險於期滿時給付滿期金，常被規劃作教育或退休用途；期內死亡則給付死亡保險金。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的「透明」体现在？",o:["只报一个总价","从不列明任何费用","分列死亡成本、利息及行政费用，并定期提供报表","由政府统一定价"],a:2,e:"万用寿险按现行利率及费用率定期结算，保单所有人可从年度报表看到保障成本、利息及费用如何影响现金价值。",tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的「透明」體現在？",o:["只報一個總價","從不列明任何費用","分列死亡成本、利息及行政費用，並定期提供報表","由政府統一定價"],e:"萬用壽險按現行利率及費用率定期結算，保單所有人可從年度報表看到保障成本、利息及費用如何影響現金價值。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投资相连保单的投资风险由谁承担？",o:["保险人","保单持有人","中介人","保监局"],a:1,e:"投连保单的价值随所选基金单位价格升跌，投资风险由保单持有人自行承担，回报并无保证。",tw:{ch:"人壽保險及年金的種類",q:"投資相連保單的投資風險由誰承擔？",o:["保險人","保單持有人","中介人","保監局"],e:"投連保單的價值隨所選基金單位價格升跌，投資風險由保單持有人自行承擔，回報並無保證。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投连保单的常见收费不包括？",o:["认购费／买卖差价","退保费用","保单管理费","医院诊金"],a:3,e:"投连保单涉及认购费、管理年费、退保费／提取费等；医院诊金属医疗开支，与投连保单收费无关。",tw:{ch:"人壽保險及年金的種類",q:"投連保單的常見收費不包括？",o:["認購費／買賣差價","退保費用","保單管理費","醫院診金"],e:"投連保單涉及認購費、管理年費、退保費／提取費等；醫院診金屬醫療開支，與投連保單收費無關。"}},
{p:3,ch:"人寿保险及年金的种类",q:"分红保单的红利实现率由谁公布？",o:["保险公司按保监局指引公布","由政府公布","无需公布","由中介人自行估算"],a:0,e:"按保监局指引，保险公司须公布分红保单的红利实现率（实际派发与当初说明的比率），提升透明度。",tw:{ch:"人壽保險及年金的種類",q:"分紅保單的紅利實現率由誰公佈？",o:["保險公司按保監局指引公佈","由政府公佈","無需公佈","由中介人自行估算"],e:"按保監局指引，保險公司須公佈分紅保單的紅利實現率（實際派發與當初說明的比率），提升透明度。"}},
{p:3,ch:"人寿保险及年金的种类",q:"即期年金通常如何缴付保费？",o:["按周缴付","免缴","按月缴付 30 年","一次性缴清（趸缴）"],a:3,e:"即期年金于缴清保费（通常一次过）后立即开始给付，适合已累积一笔资金的退休人士。",tw:{ch:"人壽保險及年金的種類",q:"即期年金通常如何繳付保費？",o:["按周繳付","免繳","按月繳付 30 年","一次性繳清（躉繳）"],e:"即期年金於繳清保費（通常一次過）後立即開始給付，適合已累積一筆資金的退休人士。"}},
{p:3,ch:"人寿保险及年金的种类",q:"联合及最后生存者年金（Joint and Last Survivor）给付至何时？",o:["其中一人死亡即停止","最后一名年金领取人死亡才停止","领取人退休时","固定 20 年"],a:1,e:"此类年金只要任何一名领取人生存即持续给付，至最后一人死亡为止，适合夫妇共用退休收入。",tw:{ch:"人壽保險及年金的種類",q:"聯合及最後生存者年金（Joint and Last Survivor）給付至何時？",o:["其中一人死亡即停止","最後一名年金領取人死亡才停止","領取人退休時","固定 20 年"],e:"此類年金只要任何一名領取人生存即持續給付，至最後一人死亡為止，適合夫婦共用退休收入。"}},
{p:3,ch:"人寿保险及年金的种类",q:"简易人寿保险的特点不包括？",o:["一般免体检","保费可按周缴付","保额须达 1,000 万","保额较小"],a:2,e:"简易寿险（工业寿险）保额小、免体检、每周上门收保费，方便基层人士；保额不可能高达千万。",tw:{ch:"人壽保險及年金的種類",q:"簡易人壽保險的特點不包括？",o:["一般免體檢","保費可按周繳付","保額須達 1,000 萬","保額較小"],e:"簡易壽險（工業壽險）保額小、免體檢、每週上門收保費，方便基層人士；保額不可能高達千萬。"}},
{p:3,ch:"人寿保险及年金的种类",q:"年金与人寿保险的基本分别是？",o:["年金只保意外","两者完全相同","年金以生存为给付条件，寿险以死亡为主要给付条件","寿险只保生存"],a:2,e:"寿险为死亡风险提供保障；年金以生存为条件定期给付，为长寿风险提供收入，功能正好互补。",tw:{ch:"人壽保險及年金的種類",q:"年金與人壽保險的基本分別是？",o:["年金只保意外","兩者完全相同","年金以生存為給付條件，壽險以死亡為主要給付條件","壽險只保生存"],e:"壽險為死亡風險提供保障；年金以生存為條件定期給付，為長壽風險提供收入，功能正好互補。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾（严重疾病）附约的给付条件是？",o:["确诊指明危疾，且诊断通常须在附约生效 90 天等候期后作出","住院即赔","投保人辞职即赔","任何小病即可索偿"],a:0,e:"危疾附约须由主诊医生确认患上指明疾病、终末疾病（寿命不超过 12 个月）或接受指明医疗程序；通常有 90 天等候期，一般限 80 岁前及标准风险。",tw:{ch:"保險利益附約及其他產品",q:"危疾（嚴重疾病）附約的給付條件是？",o:["確診指明危疾，且診斷通常須在附約生效 90 天等候期後作出","住院即賠","投保人辭職即賠","任何小病即可索償"],e:"危疾附約須由主診醫生確認患上指明疾病、終末疾病（壽命不超過 12 個月）或接受指明醫療程序；通常有 90 天等候期，一般限 80 歲前及標準風險。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾附约的常见限制不包括？",o:["通常 80 岁前有效","多重或复发疾病可能不给付","任何疾病均可索偿","只限标准风险"],a:2,e:"危疾附约只保指明疾病、限标准风险、通常 80 岁截止，等候期内诊断不保；并非任何疾病都可索偿。",tw:{ch:"保險利益附約及其他產品",q:"危疾附約的常見限制不包括？",o:["通常 80 歲前有效","多重或復發疾病可能不給付","任何疾病均可索償","只限標準風險"],e:"危疾附約只保指明疾病、限標準風險、通常 80 歲截止，等候期內診斷不保；並非任何疾病都可索償。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「提前支付死亡保险金」（生前给付）附约的运作是？",o:["增加保额","受保人患末期病时可提前获付部分或全部死亡保险金，其后从死亡保险金中扣减","只适用于年金","受保人可随时取款"],a:1,e:"在受保人处于订明的严重或末期情况（即使仍在生）时，可提前获得全部或部分死亡保险金，数额从日后的死亡保险金中扣除；受益人及承让人须签署弃权声明。",tw:{ch:"保險利益附約及其他產品",q:"「提前支付死亡保險金」（生前給付）附約的運作是？",o:["增加保額","受保人患末期病時可提前獲付部分或全部死亡保險金，其後從死亡保險金中扣減","只適用於年金","受保人可隨時取款"],e:"在受保人處於訂明的嚴重或末期情況（即使仍在生）時，可提前獲得全部或部分死亡保險金，數額從日後的死亡保險金中扣除；受益人及承讓人須簽署棄權聲明。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「豁免保费」附约的作用是？",o:["保费减半","退保退回全部保费","首期保费全免","投保人伤残后，豁免其后的续保保费"],a:3,e:"豁免保费附约承诺于投保人发生所界定的伤残后，豁免应缴的续保保费，保单继续有效；部分设定 3 个月等候期。",tw:{ch:"保險利益附約及其他產品",q:"「豁免保費」附約的作用是？",o:["保費減半","退保退回全部保費","首期保費全免","投保人傷殘後，豁免其後的續保保費"],e:"豁免保費附約承諾於投保人發生所界定的傷殘後，豁免應繳的續保保費，保單繼續有效；部分設定 3 個月等候期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「保证可保利益」（GI）附约让保单所有人有权在何时增购保险而无需可保证明？",o:["只限退休时","指定备择日期／年龄，或结婚、子女出生等指定事件发生时","任何时候","任何情况下均不可"],a:1,e:"GI（预批购买选择权）允许保单所有人在指定日期、年龄或人生事件（结婚、子女出生）时购买增额保险而无须提供可保性证明；增额通常不超过原有面额，并可能限 40 岁前行使。",tw:{ch:"保險利益附約及其他產品",q:"「保證可保利益」（GI）附約讓保單所有人有權在何時增購保險而無需可保證明？",o:["只限退休時","指定備擇日期／年齡，或結婚、子女出生等指定事件發生時","任何時候","任何情況下均不可"],e:"GI（預批購買選擇權）允許保單所有人在指定日期、年齡或人生事件（結婚、子女出生）時購買增額保險而無須提供可保性證明；增額通常不超過原有面額，並可能限 40 歲前行使。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「生活指数调整」（COLA）附约的调整特点是？",o:["固定每年加 10%","每五年调整一次","随通胀和通缩双向调整","只随通胀上调利益，不涉及通缩下调"],a:3,e:"COLA 的利益金额与独立指数（如综合消费物价指数）挂钩上调，以抵销通胀，但利益不会随通缩下调。",tw:{ch:"保險利益附約及其他產品",q:"「生活指數調整」（COLA）附約的調整特點是？",o:["固定每年加 10%","每五年調整一次","隨通脹和通縮雙向調整","只隨通脹上調利益，不涉及通縮下調"],e:"COLA 的利益金額與獨立指數（如綜合消費物價指數）掛鈎上調，以抵銷通脹，但利益不會隨通縮下調。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体人寿保险的核保特点是？",o:["逐一体检","集体核保，通常不要求详细的个人资料","无须核保","按个人病史逐一核保"],a:1,e:"团体保险按团体整体风险集体核保，通常不要求成员详细个人资料，故保费较低；个人合格性由雇主或团体决定。",tw:{ch:"保險利益附約及其他產品",q:"團體人壽保險的核保特點是？",o:["逐一體檢","集體核保，通常不要求詳細的個人資料","無須核保","按個人病史逐一核保"],e:"團體保險按團體整體風險集體核保，通常不要求成員詳細個人資料，故保費較低；個人合格性由僱主或團體決定。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体保险的「在职工作要求」指？",o:["只限管理层","兼职不可受保","保险生效时，每个团体被保险人必须是受雇且在在职工作","退休后才可受保"],a:2,e:"成员须于保险生效时在职工作（没有生病或休假），这是防止逆选择的团体核保基本原则。",tw:{ch:"保險利益附約及其他產品",q:"團體保險的「在職工作要求」指？",o:["只限管理層","兼職不可受保","保險生效時，每個團體被保險人必須是受僱且在在職工作","退休後才可受保"],e:"成員須於保險生效時在職工作（沒有生病或休假），這是防止逆選擇的團體核保基本原則。"}},
{p:3,ch:"保险利益附约及其他产品",q:"雇员离开公司后，其团体人寿保险保障如何处理？",o:["永久不可再投保","自动转为个人保单且保费不变","中止；但通常可在指定期间内转为个人保单","由保险公司免费延续"],a:2,e:"离职（或欠缴保费）时团体保障中止；通常可在指定期间内转为个人保单（部分情况须提供可保证明），但保费会按个人风险重新厘定。",tw:{ch:"保險利益附約及其他產品",q:"僱員離開公司後，其團體人壽保險保障如何處理？",o:["永久不可再投保","自動轉為個人保單且保費不變","中止；但通常可在指定期間內轉為個人保單","由保險公司免費延續"],e:"離職（或欠繳保費）時團體保障中止；通常可在指定期間內轉為個人保單（部分情況須提供可保證明），但保費會按個人風險重新釐定。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体保险合约的双方是？",o:["雇主与保监局","保险人与每位雇员","保险人与团体保单持有人（如雇主）；成员为团体被保险人","雇员与经纪"],a:2,e:"团体保险以总团体保单承保：保险人与团体保单持有人（雇主／工会／协会）为合约双方，雇员属团体被保险人。",tw:{ch:"保險利益附約及其他產品",q:"團體保險合約的雙方是？",o:["僱主與保監局","保險人與每位僱員","保險人與團體保單持有人（如僱主）；成員為團體被保險人","僱員與經紀"],e:"團體保險以總團體保單承保：保險人與團體保單持有人（僱主／工會／協會）為合約雙方，僱員屬團體被保險人。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾附约的等候期（如 90 天）内确诊指明疾病，通常？",o:["转为年金","不获赔付（视条款退还保费或附约终止）","双倍赔付","全额赔付"],a:1,e:"等候期内确诊一般不获赔付，以防逆选择（已感不适才投保）；细节以各附约条款为准。",tw:{ch:"保險利益附約及其他產品",q:"危疾附約的等候期（如 90 天）內確診指明疾病，通常？",o:["轉為年金","不獲賠付（視條款退還保費或附約終止）","雙倍賠付","全額賠付"],e:"等候期內確診一般不獲賠付，以防逆選擇（已感不適才投保）；細節以各附約條款為準。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾附约的给付性质是？",o:["实报实销","按月发放","按附约保额一次性给付","只赔住院费"],a:2,e:"确诊指明危疾后按附约保额一笔过给付，属利益性质，用途不限于医疗开支（如弥补收入损失）。",tw:{ch:"保險利益附約及其他產品",q:"危疾附約的給付性質是？",o:["實報實銷","按月發放","按附約保額一次性給付","只賠住院費"],e:"確診指明危疾後按附約保額一筆過給付，屬利益性質，用途不限於醫療開支（如彌補收入損失）。"}},
{p:3,ch:"保险利益附约及其他产品",q:"住院及手术（医疗）附约一般按什么原则赔付？",o:["双倍赔偿","按实际医疗费用实报实销","不设赔偿","按固定保额一笔过"],a:1,e:"医疗附约补偿实际合理医疗费用（弥偿性质），多设分项赔偿上限及每年／终身限额；与危疾附约的定额给付不同。",tw:{ch:"保險利益附約及其他產品",q:"住院及手術（醫療）附約一般按什麼原則賠付？",o:["雙倍賠償","按實際醫療費用實報實銷","不設賠償","按固定保額一筆過"],e:"醫療附約補償實際合理醫療費用（彌償性質），多設分項賠償上限及每年／終身限額；與危疾附約的定額給付不同。"}},
{p:3,ch:"保险利益附约及其他产品",q:"长期护理附约的给付条件一般是？",o:["患任何小病","失业","退休","失去日常生活活动能力（如不能自理进食、穿衣、沐浴）"],a:3,e:"长期护理附约于受保人失去若干项日常生活活动能力时定期给付，用以支付长期照护开支。",tw:{ch:"保險利益附約及其他產品",q:"長期護理附約的給付條件一般是？",o:["患任何小病","失業","退休","失去日常生活活動能力（如不能自理進食、穿衣、沐浴）"],e:"長期護理附約於受保人失去若干項日常生活活動能力時定期給付，用以支付長期照護開支。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「意外死亡及伤残」附约的赔付条件是？",o:["只保自然死亡","因意外事故导致死亡（或伤残）时，按附约额外金额给付","任何原因死亡均赔","只保疾病"],a:1,e:"意外死亡及伤残附约于意外事故导致死亡或指定伤残时给付额外金额；疾病或自然死亡不属于其范围。",tw:{ch:"保險利益附約及其他產品",q:"「意外死亡及傷殘」附約的賠付條件是？",o:["只保自然死亡","因意外事故導致死亡（或傷殘）時，按附約額外金額給付","任何原因死亡均賠","只保疾病"],e:"意外死亡及傷殘附約於意外事故導致死亡或指定傷殘時給付額外金額；疾病或自然死亡不屬於其範圍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体人寿保险的一般特点不包括？",o:["只限公司高层投保","按团体整体风险定价，成本较低","成员通常免体检","个人离职时保障中止"],a:0,e:"团体保险面向合资格成员整体（如全体全职雇员），核保按集体进行；并非只保高层，其余各项均为其特点。",tw:{ch:"保險利益附約及其他產品",q:"團體人壽保險的一般特點不包括？",o:["只限公司高層投保","按團體整體風險定價，成本較低","成員通常免體檢","個人離職時保障中止"],e:"團體保險面向合資格成員整體（如全體全職僱員），核保按集體進行；並非只保高層，其餘各項均為其特點。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体保险下新入职的合资格员工？",o:["只限经理亲属","须经一年核保","符合资格即自动加入团体保障","永不可加入"],a:2,e:"团体保单通常约定合资格成员（如全职雇员）自动受保，毋须个别核保，这是团体保险的便利性。",tw:{ch:"保險利益附約及其他產品",q:"團體保險下新入職的合資格員工？",o:["只限經理親屬","須經一年核保","符合資格即自動加入團體保障","永不可加入"],e:"團體保單通常約定合資格成員（如全職僱員）自動受保，毋須個別核保，這是團體保險的便利性。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体保单的保费通常由谁缴付？",o:["政府","雇主（可安排成员分担部分）","受益人","保监局"],a:1,e:"团体保单持有人（雇主／团体）负责缴付保费，成员一般无须个别缴费或只分担部分。",tw:{ch:"保險利益附約及其他產品",q:"團體保單的保費通常由誰繳付？",o:["政府","僱主（可安排成員分擔部分）","受益人","保監局"],e:"團體保單持有人（僱主／團體）負責繳付保費，成員一般無須個別繳費或只分擔部分。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「保证可保利益」附约下增购保额，通常？",o:["永远不可行使","不超过原有保额，并设有可行使的年龄上限","无上限限制","必须增至双倍"],a:1,e:"GI 附约的增购权一般以原有保额为上限，并限定须于某年龄前行使，以避免逆选择。",tw:{ch:"保險利益附約及其他產品",q:"「保證可保利益」附約下增購保額，通常？",o:["永遠不可行使","不超過原有保額，並設有可行使的年齡上限","無上限限制","必須增至雙倍"],e:"GI 附約的增購權一般以原有保額為上限，並限定須於某年齡前行使，以避免逆選擇。"}},
{p:3,ch:"保险利益附约及其他产品",q:"团体人寿保险合约的续保特点是？",o:["一次签发终身有效","不可续保","每年须全员重新体检","通常每年续保，只要团体继续缴付保费及符合条款即维持有效"],a:3,e:"团体保单多按年续保，只要保单持有人继续缴费且团体仍然存在，保障便持续；保费可按团体经验调整。",tw:{ch:"保險利益附約及其他產品",q:"團體人壽保險合約的續保特點是？",o:["一次簽發終身有效","不可續保","每年須全員重新體檢","通常每年續保，只要團體繼續繳付保費及符合條款即維持有效"],e:"團體保單多按年續保，只要保單持有人繼續繳費且團體仍然存在，保障便持續；保費可按團體經驗調整。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单签发后，保险人可否单方面取消或修改保单？",o:["只可修改不可取消","不可以，取消或修改须经保单所有人同意","只限首年内","可以"],a:1,e:"人寿保单一经签发，保险人不得单方取消或修改；任何更改须经保单所有人同意（一般保险保单则可在续保时检讨条件）。",tw:{ch:"闡釋人壽保險單",q:"人壽保單簽發後，保險人可否單方面取消或修改保單？",o:["只可修改不可取消","不可以，取消或修改須經保單所有人同意","只限首年內","可以"],e:"人壽保單一經簽發，保險人不得單方取消或修改；任何更改須經保單所有人同意（一般保險保單則可在續保時檢討條件）。"}},
{p:3,ch:"阐释人寿保险单",q:"「不可争议条款」的一般内容是？",o:["任何错误都不影响保单","条款永不更改","保单生效（或复效）满两年后，保险人不得质疑合约的有效性","保费不可争议"],a:2,e:"不可争议条款规定保单生效或复效满两年后，保险人不得再以投保时的误述或不披露为由对抗索赔（欺诈性个案通常除外）。",tw:{ch:"闡釋人壽保險單",q:"「不可爭議條款」的一般內容是？",o:["任何錯誤都不影響保單","條款永不更改","保單生效（或復效）滿兩年後，保險人不得質疑合約的有效性","保費不可爭議"],e:"不可爭議條款規定保單生效或復效滿兩年後，保險人不得再以投保時的誤述或不披露為由對抗索賠（欺詐性個案通常除外）。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单「自杀条款」的一般规定是？",o:["任何自杀均赔","不设任何限制","保单生效一年内自杀，保险人不赔（通常退还已缴保费）","自杀双倍赔偿"],a:2,e:"一般保单规定生效一年内自杀属除外，只退还已缴保费（不计利息）；一年后自杀则按保单赔付，以防逆选择。",tw:{ch:"闡釋人壽保險單",q:"人壽保單「自殺條款」的一般規定是？",o:["任何自殺均賠","不設任何限制","保單生效一年內自殺，保險人不賠（通常退還已繳保費）","自殺雙倍賠償"],e:"一般保單規定生效一年內自殺屬除外，只退還已繳保費（不計利息）；一年後自殺則按保單賠付，以防逆選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单的「宽限期」一般为多久，作用是什么？",o:["约 31 天，期内未缴费保单暂不失效","7 天，只供咨询","一年，期内免缴保费","没有宽限期"],a:0,e:"宽限期（通常 31 天）内保单即使未收到保费仍然有效，期内发生保险事故仍须赔付（扣除欠缴保费），保障保单所有人不会因一时延误失保障。",tw:{ch:"闡釋人壽保險單",q:"人壽保單的「寬限期」一般為多久，作用是什麼？",o:["約 31 天，期內未繳費保單暫不失效","7 天，只供諮詢","一年，期內免繳保費","沒有寬限期"],e:"寬限期（通常 31 天）內保單即使未收到保費仍然有效，期內發生保險事故仍須賠付（扣除欠繳保費），保障保單所有人不會因一時延誤失保障。"}},
{p:3,ch:"阐释人寿保险单",q:"香港长期保险保单的「冷静期」为多久？",o:["14 天","21 天","7 天","3 个月"],a:1,e:"香港长期保险（含投连）冷静期为 21 天（或按保单条款规定的更长期限），期内取消保单可获退还保费（投连按市值计算）。",tw:{ch:"闡釋人壽保險單",q:"香港長期保險保單的「冷靜期」為多久？",o:["14 天","21 天","7 天","3 個月"],e:"香港長期保險（含投連）冷靜期為 21 天（或按保單條款規定的更長期限），期內取消保單可獲退還保費（投連按市值計算）。"}},
{p:3,ch:"阐释人寿保险单",q:"「保单贷款」的安排是？",o:["借后保单即失效","以保单现金价值为担保向保险人借款，贷款额以现金价值为上限","向银行申请的信用贷款","无须偿还"],a:1,e:"储蓄型保单累积现金价值后，保单所有人可向保险人贷款，金额以现金价值为限；贷款本息未还会减少死亡保险金，超过现金价值时保单可能失效。",tw:{ch:"闡釋人壽保險單",q:"「保單貸款」的安排是？",o:["借後保單即失效","以保單現金價值為擔保向保險人借款，貸款額以現金價值為上限","向銀行申請的信用貸款","無須償還"],e:"儲蓄型保單累積現金價值後，保單所有人可向保險人貸款，金額以現金價值為限；貸款本息未還會減少死亡保險金，超過現金價值時保單可能失效。"}},
{p:3,ch:"阐释人寿保险单",q:"「自动垫缴保费条款」指？",o:["保费自动加倍","宽限期后仍未缴费时，保险人自动以保单现金价值垫缴到期保费","保费自动转为年金","保险公司代缴保费"],a:1,e:"自动垫缴条款下，宽限期届满未缴费，保险人用现金价值垫缴保费以维持保单有效，直至现金价值耗尽。",tw:{ch:"闡釋人壽保險單",q:"「自動墊繳保費條款」指？",o:["保費自動加倍","寬限期後仍未繳費時，保險人自動以保單現金價值墊繳到期保費","保費自動轉為年金","保險公司代繳保費"],e:"自動墊繳條款下，寬限期屆滿未繳費，保險人用現金價值墊繳保費以維持保單有效，直至現金價值耗盡。"}},
{p:3,ch:"阐释人寿保险单",q:"关于更改人寿保单受益人，下列哪项正确？",o:["任何受益人更改都须受益人同意","可撤销受益人可随时更改，无须受益人同意","只可更改为亲属","受益人不可更改"],a:1,e:"「可撤销」受益人：保单所有人可随时更改，无须受益人同意；「不可撤销」受益人的权益则须其同意方可更改。",tw:{ch:"闡釋人壽保險單",q:"關於更改人壽保單受益人，下列哪項正確？",o:["任何受益人更改都須受益人同意","可撤銷受益人可隨時更改，無須受益人同意","只可更改為親屬","受益人不可更改"],e:"「可撤銷」受益人：保單所有人可隨時更改，無須受益人同意；「不可撤銷」受益人的權益則須其同意方可更改。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单常见的除外责任不包括？",o:["受保人自然死亡","受保人参与高风险活动","保单生效一年内的自杀","战争或军事行动风险"],a:0,e:"正常自然死亡是寿险的基本承保范围；常见除外包括生效一年内自杀、战争、高空／潜水等高风险活动（以具体保单条款为准）。",tw:{ch:"闡釋人壽保險單",q:"人壽保單常見的除外責任不包括？",o:["受保人自然死亡","受保人蔘與高風險活動","保單生效一年內的自殺","戰爭或軍事行動風險"],e:"正常自然死亡是壽險的基本承保範圍；常見除外包括生效一年內自殺、戰爭、高空／潛水等高風險活動（以具體保單條款為準）。"}},
{p:3,ch:"阐释人寿保险单",q:"储蓄型人寿保单的「现金价值」来自哪里？",o:["保费中扣除保障成本及费用后累积的储蓄成分","保险公司的捐款","银行利息赠送","政府补贴"],a:0,e:"均衡保费制度下，早期多缴的保费扣除当期保障成本与费用后累积生息，形成现金价值；退保时可取回（通常少于已缴保费）。",tw:{ch:"闡釋人壽保險單",q:"儲蓄型人壽保單的「現金價值」來自哪裏？",o:["保費中扣除保障成本及費用後累積的儲蓄成分","保險公司的捐款","銀行利息贈送","政府補貼"],e:"均衡保費制度下，早期多繳的保費扣除當期保障成本與費用後累積生息，形成現金價值；退保時可取回（通常少於已繳保費）。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单的「完整合约条款」指？",o:["投保单副本附于保单，与保单条款共同构成完整合约","以口头协议为准","保单内容可日后任意补写","可随意加入口头承诺"],a:0,e:"完整合约条款把投保书及保单条款锁定为合约全部内容，防止任何一方日后以口头承诺增减合约。",tw:{ch:"闡釋人壽保險單",q:"人壽保單的「完整合約條款」指？",o:["投保單副本附於保單，與保單條款共同構成完整合約","以口頭協議為準","保單內容可日後任意補寫","可隨意加入口頭承諾"],e:"完整合約條款把投保書及保單條款鎖定為合約全部內容，防止任何一方日後以口頭承諾增減合約。"}},
{p:3,ch:"阐释人寿保险单",q:"投保时误报年龄，且申报年龄大于实际年龄（保险人多收了保费），一般会？",o:["保单无效","不作任何调整","保费加倍","退还多收保费或按实足年龄调高保额"],a:3,e:"年龄误报条款通常把多收保费退还或调高保额；若少报年龄，则须补缴保费或按比例调减保额。",tw:{ch:"闡釋人壽保險單",q:"投保時誤報年齡，且申報年齡大於實際年齡（保險人多收了保費），一般會？",o:["保單無效","不作任何調整","保費加倍","退還多收保費或按實足年齡調高保額"],e:"年齡誤報條款通常把多收保費退還或調高保額；若少報年齡，則須補繳保費或按比例調減保額。"}},
{p:3,ch:"阐释人寿保险单",q:"失效保单申请复效，一般须符合什么条件？",o:["不可复效","自动复效","随时免费复效","于失效后指定期内申请、缴清欠缴保费及利息，并提供可保证明"],a:3,e:"复效须在指定期限内提出申请、补缴欠款及利息，并重新提供可保性证明；复效后不可争议期通常重新起算。",tw:{ch:"闡釋人壽保險單",q:"失效保單申請復效，一般須符合什麼條件？",o:["不可復效","自動復效","隨時免費復效","於失效後指定期內申請、繳清欠繳保費及利息，並提供可保證明"],e:"復效須在指定期限內提出申請、補繳欠款及利息，並重新提供可保性證明；復效後不可爭議期通常重新起算。"}},
{p:3,ch:"阐释人寿保险单",q:"保单复效后，不可争议条款的两年期限由何时起算？",o:["由复效日起重新计算","由法院裁定","由签发日起永久不变","复效后不再适用"],a:0,e:"多数保单的不可争议条款订明，复效后的两年期限由复效日起重新计算，以覆盖复效时的申报。",tw:{ch:"闡釋人壽保險單",q:"保單復效後，不可爭議條款的兩年期限由何時起算？",o:["由復效日起重新計算","由法院裁定","由簽發日起永久不變","復效後不再適用"],e:"多數保單的不可爭議條款訂明，復效後的兩年期限由復效日起重新計算，以覆蓋復效時的申報。"}},
{p:3,ch:"阐释人寿保险单",q:"分红保单红利的常见使用方式不包括？",o:["现金领取","抵缴到期保费","要求保险人保证固定派息率","积存生息"],a:2,e:"红利可选择现金、抵缴保费、积存生息或购买增额缴清保险等；红利属非保证利益，投保人不能要求保证固定派息。",tw:{ch:"闡釋人壽保險單",q:"分紅保單紅利的常見使用方式不包括？",o:["現金領取","抵繳到期保費","要求保險人保證固定派息率","積存生息"],e:"紅利可選擇現金、抵繳保費、積存生息或購買增額繳清保險等；紅利屬非保證利益，投保人不能要求保證固定派息。"}},
{p:3,ch:"阐释人寿保险单",q:"保单贷款未偿还对保单有何影响？",o:["自动转为年金","毫无影响","保额自动加倍","减少死亡保险金及退保价值，本息超过现金价值时保单失效"],a:3,e:"贷款本息会于给付时扣减；若贷款本息累积至超过现金价值，保单可能失效，投保人应留意贷款余额。",tw:{ch:"闡釋人壽保險單",q:"保單貸款未償還對保單有何影響？",o:["自動轉為年金","毫無影響","保額自動加倍","減少死亡保險金及退保價值，本息超過現金價值時保單失效"],e:"貸款本息會於給付時扣減；若貸款本息累積至超過現金價值，保單可能失效，投保人應留意貸款餘額。"}},
{p:3,ch:"阐释人寿保险单",q:"受益人先于受保人死亡，且保单无其他指定，保险金归？",o:["归保险中介人","归税务局","成为受保人遗产的一部分","由保险公司没收"],a:2,e:"无在世指定受益人时，保险金按遗产处理；故保单所有人应适时检视及更新受益人指定。",tw:{ch:"闡釋人壽保險單",q:"受益人先於受保人死亡，且保單無其他指定，保險金歸？",o:["歸保險中介人","歸税務局","成為受保人遺產的一部分","由保險公司沒收"],e:"無在世指定受益人時，保險金按遺產處理；故保單所有人應適時檢視及更新受益人指定。"}},
{p:3,ch:"阐释人寿保险单",q:"受保人与保单所有人不同（如父母为子女投保）时，退保及更改受益人的权利属于？",o:["代理人","保单所有人","受保人","受益人"],a:1,e:"保单的一切主权（退保、贷款、更改受益人等）属于保单所有人，受保人只是生命标的。",tw:{ch:"闡釋人壽保險單",q:"受保人與保單所有人不同（如父母為子女投保）時，退保及更改受益人的權利屬於？",o:["代理人","保單所有人","受保人","受益人"],e:"保單的一切主權（退保、貸款、更改受益人等）屬於保單所有人，受保人只是生命標的。"}},
{p:3,ch:"阐释人寿保险单",q:"冷静期内取消长期保单，可获退还？",o:["双倍退还","已缴保费（投连保单按市值计算，市值低于保费时不获补回差额）","只退现金价值","分文不退"],a:1,e:"冷静期内取消可全数取回已缴保费；投连保单按市值退还，如市值下跌，投保人或取回较少金额。",tw:{ch:"闡釋人壽保險單",q:"冷靜期內取消長期保單，可獲退還？",o:["雙倍退還","已繳保費（投連保單按市值計算，市值低於保費時不獲補回差額）","只退現金價值","分文不退"],e:"冷靜期內取消可全數取回已繳保費；投連保單按市值退還，如市值下跌，投保人或取回較少金額。"}},
{p:3,ch:"阐释人寿保险单",q:"自动垫缴保费条款运作期间，保单的状态是？",o:["仍然有效，直至现金价值耗尽","即时失效","转为定期保险","保额自动加倍"],a:0,e:"垫缴期间保单持续有效，但贷款本息累积；现金价值耗尽而仍未缴费时保单方才失效。",tw:{ch:"闡釋人壽保險單",q:"自動墊繳保費條款運作期間，保單的狀態是？",o:["仍然有效，直至現金價值耗盡","即時失效","轉為定期保險","保額自動加倍"],e:"墊繳期間保單持續有效，但貸款本息累積；現金價值耗盡而仍未繳費時保單方才失效。"}},
{p:3,ch:"阐释人寿保险单",q:"不可争议条款一般不适用于哪种情况？",o:["迟缴保费","投保时的欺诈性误述","无心的年龄误报","一般的不披露"],a:1,e:"欺诈性误述不受不可争议条款保护——即使保单生效超过两年，保险人仍可基于欺诈抗辩。",tw:{ch:"闡釋人壽保險單",q:"不可爭議條款一般不適用於哪種情況？",o:["遲繳保費","投保時的欺詐性誤述","無心的年齡誤報","一般的不披露"],e:"欺詐性誤述不受不可爭議條款保護——即使保單生效超過兩年，保險人仍可基於欺詐抗辯。"}},
{p:3,ch:"阐释人寿保险单",q:"宽限期内（尚未缴费）发生受保事故，保险人应？",o:["仍须赔付，可从保险金中扣除欠缴保费","只退保费","双倍赔偿","保单失效拒赔"],a:0,e:"宽限期内保单仍然有效，发生死亡事故仍须按保单赔付（扣除欠缴保费），这正是宽限期的意义。",tw:{ch:"闡釋人壽保險單",q:"寬限期內（尚未繳費）發生受保事故，保險人應？",o:["仍須賠付，可從保險金中扣除欠繳保費","只退保費","雙倍賠償","保單失效拒賠"],e:"寬限期內保單仍然有效，發生死亡事故仍須按保單賠付（扣除欠繳保費），這正是寬限期的意義。"}},
{p:3,ch:"人寿保险程序",q:"投保单一般须载有哪些资料？",o:["只需缴款方式","只需受益人资料","只需姓名","投保人及受保人资料、健康声明、保额、受益人及签署"],a:3,e:"投保单是核保基础，须包括投保人／受保人个人资料、健康及职业声明、保额、受益人、保费缴付方式及投保人签署。",tw:{ch:"人壽保險程序",q:"投保單一般須載有哪些資料？",o:["只需繳款方式","只需受益人資料","只需姓名","投保人及受保人資料、健康聲明、保額、受益人及簽署"],e:"投保單是核保基礎，須包括投保人／受保人個人資料、健康及職業聲明、保額、受益人、保費繳付方式及投保人簽署。"}},
{p:3,ch:"人寿保险程序",q:"「附条件保费收据」的保障生效方式是？",o:["与投保日无关","缴费即无条件生效","保障追溯至投保日，但须日后证实投保时按标准条款具有可保性才有效","只保 7 天"],a:2,e:"附条件收据（如香港常见的「投保时生效」收据）把保障追溯至投保日，但若日后核保发现投保时不具可保性，保障可被撤销。",tw:{ch:"人壽保險程序",q:"「附條件保費收據」的保障生效方式是？",o:["與投保日無關","繳費即無條件生效","保障追溯至投保日，但須日後證實投保時按標準條款具有可保性才有效","只保 7 天"],e:"附條件收據（如香港常見的「投保時生效」收據）把保障追溯至投保日，但若日後核保發現投保時不具可保性，保障可被撤銷。"}},
{p:3,ch:"人寿保险程序",q:"「立约保费收据」（临时保险协议 TIA）的性质是？",o:["只保障 7 天","可无限期延续","只是一张收据","本身是一份独立合约，于签署投保单并缴清保费当日即时生效"],a:3,e:"TIA 是独立的临时保障合约，不依赖日后是否签发正式保单；保障期一般为指定日数（如 60／90 天）。",tw:{ch:"人壽保險程序",q:"「立約保費收據」（臨時保險協議 TIA）的性質是？",o:["只保障 7 天","可無限期延續","只是一張收據","本身是一份獨立合約，於簽署投保單並繳清保費當日即時生效"],e:"TIA 是獨立的臨時保障合約，不依賴日後是否簽發正式保單；保障期一般為指定日數（如 60／90 天）。"}},
{p:3,ch:"人寿保险程序",q:"「暂保单」（Cover Note）的主要特点是？",o:["保障终身","主要用于非人寿保险，提供暂时性、可取消的保障，通常为期约 30 天","等同于正式保单","主要用于人寿保险"],a:1,e:"暂保单是非寿险中的临时保障凭证，通常为期约 30 天且可取消；人寿保险中对应概念是临时保险协议（TIA）。",tw:{ch:"人壽保險程序",q:"「暫保單」（Cover Note）的主要特點是？",o:["保障終身","主要用於非人壽保險，提供暫時性、可取消的保障，通常為期約 30 天","等同於正式保單","主要用於人壽保險"],e:"暫保單是非壽險中的臨時保障憑證，通常為期約 30 天且可取消；人壽保險中對應概念是臨時保險協議（TIA）。"}},
{p:3,ch:"人寿保险程序",q:"核保对风险的建议分类一般包括？",o:["男性和女性","标准风险、次标准风险、拒保风险（及优良风险）","大客户与小客户","本地与外地"],a:1,e:"技术性核保将风险分类为：标准（按表定费率）、次标准（附加保费或限制）、拒保，部分公司另设「优良风险」给予优惠费率。",tw:{ch:"人壽保險程序",q:"核保對風險的建議分類一般包括？",o:["男性和女性","標準風險、次標準風險、拒保風險（及優良風險）","大客户與小客户","本地與外地"],e:"技術性核保將風險分類為：標準（按表定費率）、次標準（附加保費或限制）、拒保，部分公司另設「優良風險」給予優惠費率。"}},
{p:3,ch:"人寿保险程序",q:"「道德危险」与「实质危险」的分别是？",o:["两者相同","实质危险较道德危险更难确定","道德危险只存在于年金","道德危险（品格、诚信、行为倾向）比实质危险（身体及环境状况）较难确定"],a:3,e:"实质危险指可观察的身体及环境风险因素；道德危险涉及品格与诚信，难以量化，故较难确定。",tw:{ch:"人壽保險程序",q:"「道德危險」與「實質危險」的分別是？",o:["兩者相同","實質危險較道德危險更難確定","道德危險只存在於年金","道德危險（品格、誠信、行為傾向）比實質危險（身體及環境狀況）較難確定"],e:"實質危險指可觀察的身體及環境風險因素；道德危險涉及品格與誠信，難以量化，故較難確定。"}},
{p:3,ch:"人寿保险程序",q:"「财务性核保」主要评估什么？",o:["保额是否与收入匹配、既有累计保额及再保险安排","代理人的佣金","保险公司股价","投保人的投资品味"],a:0,e:"财务核保评估投保金额与投保人收入及需要是否相称、同一人累计已购保额、以及是否需要再保险，以防超额投保及道德危险。",tw:{ch:"人壽保險程序",q:"「財務性核保」主要評估什麼？",o:["保額是否與收入匹配、既有累計保額及再保險安排","代理人的佣金","保險公司股價","投保人的投資品味"],e:"財務核保評估投保金額與投保人收入及需要是否相稱、同一人累計已購保額、以及是否需要再保險，以防超額投保及道德危險。"}},
{p:3,ch:"人寿保险程序",q:"哪些情况下保险人通常会要求体检或主诊医生报告？",o:["投保金额很高或投保人年龄较大（如超过 50 岁）时","只限女性","只限团体保险","任何投保都强制体检"],a:0,e:"高额投保、高龄或有健康申报时，核保会要求体检医生检查或主诊医生报告；费用由保险人支付。",tw:{ch:"人壽保險程序",q:"哪些情況下保險人通常會要求體檢或主診醫生報告？",o:["投保金額很高或投保人年齡較大（如超過 50 歲）時","只限女性","只限團體保險","任何投保都強制體檢"],e:"高額投保、高齡或有健康申報時，核保會要求體檢醫生檢查或主診醫生報告；費用由保險人支付。"}},
{p:3,ch:"人寿保险程序",q:"对次标准风险，保险人可采取的措施不包括？",o:["设置保单负债","指定除外责任","无条件按标准费率承保","附加保费"],a:2,e:"次标准风险的处理包括：附加保费（反映超额死亡率）、指定除外责任、设置递减式保单负债，或拒绝承保；不会无条件按标准费率承保。",tw:{ch:"人壽保險程序",q:"對次標準風險，保險人可採取的措施不包括？",o:["設置保單負債","指定除外責任","無條件按標準費率承保","附加保費"],e:"次標準風險的處理包括：附加保費（反映超額死亡率）、指定除外責任、設置遞減式保單負債，或拒絕承保；不會無條件按標準費率承保。"}},
{p:3,ch:"人寿保险程序",q:"处理死亡索偿时，下列哪项正确？",o:["须出示死亡证明正本并确定死亡日期；若受益人谋杀受保人，该受益人依法不得获益","口头通知即可","由代理人决定赔否","无须任何证明"],a:0,e:"死亡索偿须出示死亡证明正本；死亡日期影响递减保额及红利计算；按公共政策，谋杀受保人的受益人不可获益；推定死亡须由法庭裁决。",tw:{ch:"人壽保險程序",q:"處理死亡索償時，下列哪項正確？",o:["須出示死亡證明正本並確定死亡日期；若受益人謀殺受保人，該受益人依法不得獲益","口頭通知即可","由代理人決定賠否","無須任何證明"],e:"死亡索償須出示死亡證明正本；死亡日期影響遞減保額及紅利計算；按公共政策，謀殺受保人的受益人不可獲益；推定死亡須由法庭裁決。"}},
{p:3,ch:"人寿保险程序",q:"「期满索偿」主要与哪种保单有关？",o:["储蓄寿险","定期寿险","医疗保险","意外保险"],a:0,e:"期满索偿与储蓄（两全）寿险有关：到期日前保险人发信提醒期满日期及金额，并附解除责任凭证供收款时签署。",tw:{ch:"人壽保險程序",q:"「期滿索償」主要與哪種保單有關？",o:["儲蓄壽險","定期壽險","醫療保險","意外保險"],e:"期滿索償與儲蓄（兩全）壽險有關：到期日前保險人發信提醒期滿日期及金額，並附解除責任憑證供收款時簽署。"}},
{p:3,ch:"人寿保险程序",q:"为什么人寿保险特别重视售后持续服务与保单保留？",o:["只为促销新产品","大部分成本与开支在保单开始时支付，业务持续与保留对盈利能力至关重要","法律规定不得失客","为增加文书工作"],a:1,e:"寿险的首年佣金及出单成本很高，公司利润依赖保单持续有效；优质的保单所有人服务（POS）是客户忠诚与盈利的关键。",tw:{ch:"人壽保險程序",q:"為什麼人壽保險特別重視售後持續服務與保單保留？",o:["只為促銷新產品","大部分成本與開支在保單開始時支付，業務持續與保留對盈利能力至關重要","法律規定不得失客","為增加文書工作"],e:"壽險的首年佣金及出單成本很高，公司利潤依賴保單持續有效；優質的保單所有人服務（POS）是客户忠誠與盈利的關鍵。"}},
{p:3,ch:"人寿保险程序",q:"人寿核保的资料来源不包括？",o:["主诊医生报告","投保书","受益人的投资意见","体检报告"],a:2,e:"核保依据包括投保书、体检、主诊医生报告、财务证明及调查报告等；受益人意见与风险评估无关。",tw:{ch:"人壽保險程序",q:"人壽核保的資料來源不包括？",o:["主診醫生報告","投保書","受益人的投資意見","體檢報告"],e:"核保依據包括投保書、體檢、主診醫生報告、財務證明及調查報告等；受益人意見與風險評估無關。"}},
{p:3,ch:"人寿保险程序",q:"「法律性核保」主要确定？",o:["保费高低","可保利益、立约能力等令合约具有法律效力的要件","佣金比例","红利水平"],a:1,e:"法律性核保核实可保利益、年龄／立约能力及最大诚信等法律要件，避免合约无效或可撤销。",tw:{ch:"人壽保險程序",q:"「法律性核保」主要確定？",o:["保費高低","可保利益、立約能力等令合約具有法律效力的要件","佣金比例","紅利水平"],e:"法律性核保核實可保利益、年齡／立約能力及最大誠信等法律要件，避免合約無效或可撤銷。"}},
{p:3,ch:"人寿保险程序",q:"「技术性核保」主要评估？",o:["死亡风险程度，以决定标准承保、附加保费或拒保","公司盈利","股市走势","客户喜好"],a:0,e:"技术性核保按健康、职业、嗜好等因素评估超额死亡率，把风险分类为标准、次标准或拒保。",tw:{ch:"人壽保險程序",q:"「技術性核保」主要評估？",o:["死亡風險程度，以決定標準承保、附加保費或拒保","公司盈利","股市走勢","客户喜好"],e:"技術性核保按健康、職業、嗜好等因素評估超額死亡率，把風險分類為標準、次標準或拒保。"}},
{p:3,ch:"人寿保险程序",q:"次标准风险的处理方式不包括？",o:["削减保额","附加保费","无条件按标准费率承保","推迟承保"],a:2,e:"次标准风险须以附加保费、削减保额、除外责任或推迟承保等方式处理；无条件标准费率承保即失去核保意义。",tw:{ch:"人壽保險程序",q:"次標準風險的處理方式不包括？",o:["削減保額","附加保費","無條件按標準費率承保","推遲承保"],e:"次標準風險須以附加保費、削減保額、除外責任或推遲承保等方式處理；無條件標準費率承保即失去核保意義。"}},
{p:3,ch:"人寿保险程序",q:"普通人法制度下，失踪人士一般须失踪多久方可由法院颁令宣告（推定）死亡？",o:["7 年","1 年","20 年","4 年"],a:0,e:"按普通法惯例，失踪满 7 年且无仍然生存的确切证据，利害关系人可申请法院颁令推定死亡，保险人才据此处理死亡索偿。",tw:{ch:"人壽保險程序",q:"普通人法制度下，失蹤人士一般須失蹤多久方可由法院頒令宣告（推定）死亡？",o:["7 年","1 年","20 年","4 年"],e:"按普通法慣例，失蹤滿 7 年且無仍然生存的確切證據，利害關係人可申請法院頒令推定死亡，保險人才據此處理死亡索償。"}},
{p:3,ch:"人寿保险程序",q:"处理期满索偿时，保险人除给付外通常要求签署什么文件？",o:["保单贷款协议","解除责任凭证（Discharge Voucher）","受益人弃权书","新投保书"],a:1,e:"收款人签署解除责任凭证确认收妥满期金、保险人责任完结，是期满索偿的常规步骤。",tw:{ch:"人壽保險程序",q:"處理期滿索償時，保險人除給付外通常要求籤署什麼文件？",o:["保單貸款協議","解除責任憑證（Discharge Voucher）","受益人棄權書","新投保書"],e:"收款人簽署解除責任憑證確認收妥滿期金、保險人責任完結，是期滿索償的常規步驟。"}},
{p:3,ch:"人寿保险程序",q:"「保单所有人服务」（POS）不包括下列哪项？",o:["保单查询及文件补发","更改受益人或联络资料","代客买卖股票","办理保单贷款或复效"],a:2,e:"POS 涵盖保单日常行政服务（更改、贷款、复效、查询等），但代客投资证券属受规管活动，与保单服务无关。",tw:{ch:"人壽保險程序",q:"「保單所有人服務」（POS）不包括下列哪項？",o:["保單查詢及文件補發","更改受益人或聯絡資料","代客買賣股票","辦理保單貸款或復效"],e:"POS 涵蓋保單日常行政服務（更改、貸款、復效、查詢等），但代客投資證券屬受規管活動，與保單服務無關。"}},
{p:3,ch:"人寿保险程序",q:"受保人失踪，保险人会如何处理死亡索偿？",o:["一律拒不受理","由代理人决定","自动双倍赔偿","凭法院宣告死亡的命令按推定死亡日期处理"],a:3,e:"失踪个案须待法院颁令宣告死亡，保险人凭命令按推定死亡日期厘定递减保额及红利后给付。",tw:{ch:"人壽保險程序",q:"受保人失蹤，保險人會如何處理死亡索償？",o:["一律拒不受理","由代理人決定","自動雙倍賠償","憑法院宣告死亡的命令按推定死亡日期處理"],e:"失蹤個案須待法院頒令宣告死亡，保險人憑命令按推定死亡日期釐定遞減保額及紅利後給付。"}},
{p:3,ch:"人寿保险程序",q:"长期保险佣金的常见结构是？",o:["首年最低","首年佣金较高，续年递减","每年完全相同","只收取一次"],a:1,e:"长期保单首年佣金比例较高以补偿招揽及出单成本，续年佣金递减，鼓励中介人做好售后服务及保留保单。",tw:{ch:"人壽保險程序",q:"長期保險佣金的常見結構是？",o:["首年最低","首年佣金較高，續年遞減","每年完全相同","只收取一次"],e:"長期保單首年佣金比例較高以補償招攬及出單成本，續年佣金遞減，鼓勵中介人做好售後服務及保留保單。"}},
{p:3,ch:"人寿保险程序",q:"投保书上的健康声明及投保人签署有何重要性？",o:["纯属参考","可由代理人随意代答","构成合约基础，误述可影响合约有效性","可留空不填"],a:2,e:"投保书是核保及合约的基础，签署代表申报属实；代理人代答或诱导隐瞒可令合约被撤销并引致纪律处分。",tw:{ch:"人壽保險程序",q:"投保書上的健康聲明及投保人簽署有何重要性？",o:["純屬參考","可由代理人隨意代答","構成合約基礎，誤述可影響合約有效性","可留空不填"],e:"投保書是核保及合約的基礎，簽署代表申報屬實；代理人代答或誘導隱瞞可令合約被撤銷並引致紀律處分。"}},
{p:1,ch:"风险与保险",q:"下列哪一项属于「特定风险」（Particular Risk）的例子？",o:["战争","核灾难","家中火灾","恶性通货膨胀"],a:2,e:"特定风险只影响个别人或机构（如火灾、偷窃、车祸），属可保范围；基本风险影响全社会（战争、通胀等）。",tw:{ch:"風險與保險",q:"下列哪一項屬於「特定風險」（Particular Risk）的例子？",o:["戰爭","核災難","家中火災","惡性通貨膨脹"],e:"特定風險隻影響個別人或機構（如火災、偷竊、車禍），屬可保範圍；基本風險影響全社會（戰爭、通脹等）。"}},
{p:1,ch:"风险与保险",q:"风险的组成元素包括？",o:["危险、风险因素、损失","只有损失","只有利润","保费、佣金、利润"],a:0,e:"风险由危险因素（导致损失的原因）、危险事件（如火灾）及损失（经济后果）等元素构成。",tw:{ch:"風險與保險",q:"風險的組成元素包括？",o:["危險、風險因素、損失","只有損失","只有利潤","保費、佣金、利潤"],e:"風險由危險因素（導致損失的原因）、危險事件（如火災）及損失（經濟後果）等元素構成。"}},
{p:1,ch:"风险与保险",q:"衡量风险大小的两大尺度是？",o:["损失频率与损失程度","保额与保费","保费与佣金","年龄与性别"],a:0,e:"风险评估量化两件事：损失发生的可能性（频率）及损失发生时的严重程度（程度）。",tw:{ch:"風險與保險",q:"衡量風險大小的兩大尺度是？",o:["損失頻率與損失程度","保額與保費","保費與佣金","年齡與性別"],e:"風險評估量化兩件事：損失發生的可能性（頻率）及損失發生時的嚴重程度（程度）。"}},
{p:1,ch:"风险与保险",q:"风险管理的最终目标是？",o:["完全不承担任何风险","以最低成本把风险的不利影响降至最低","把所有风险转移给保险人","完全消除所有风险"],a:1,e:"风险管理并非消除风险，而是识别、评估后选择最经济的应对方式，使风险对财务的不利影响最小化。",tw:{ch:"風險與保險",q:"風險管理的最終目標是？",o:["完全不承擔任何風險","以最低成本把風險的不利影響降至最低","把所有風險轉移給保險人","完全消除所有風險"],e:"風險管理並非消除風險，而是識別、評估後選擇最經濟的應對方式，使風險對財務的不利影響最小化。"}},
{p:1,ch:"风险与保险",q:"「损失防范」与「损失降低」的分别是？",o:["两者完全相同","防范是事前减少发生可能；降低是事后减少严重程度","降低属事前","防范属事后"],a:1,e:"损失防范（Prevention）针对损失频率（事前防止事故发生）；损失降低（Reduction）针对损失程度（事后减轻损失）。",tw:{ch:"風險與保險",q:"「損失防範」與「損失降低」的分別是？",o:["兩者完全相同","防範是事前減少發生可能；降低是事後減少嚴重程度","降低屬事前","防範屬事後"],e:"損失防範（Prevention）針對損失頻率（事前防止事故發生）；損失降低（Reduction）針對損失程度（事後減輕損失）。"}},
{p:1,ch:"风险与保险",q:"下列哪项属于「风险自留」的具体形式？",o:["成立自保公司或计提风险准备金","购买全险保单","购买再保险","风险避免"],a:0,e:"风险自留是由自己承担风险后果，形式包括无意识地自担（未察觉）或有计划地自留（自保公司、准备金、免赔额）。",tw:{ch:"風險與保險",q:"下列哪項屬於「風險自留」的具體形式？",o:["成立自保公司或計提風險準備金","購買全險保單","購買再保險","風險避免"],e:"風險自留是由自己承擔風險後果，形式包括無意識地自擔（未察覺）或有計劃地自留（自保公司、準備金、免賠額）。"}},
{p:1,ch:"风险与保险",q:"保险对社会的效益不包括？",o:["完全消除社会上的所有风险","补偿经济损失、助人灾后重建","协助信贷（银行要求按揭物业投保）","提供心理安心、促进商业与投资活动"],a:0,e:"保险可补偿损失、提供安心、促进经济活动，但不能消除风险本身——风险依然存在，只是损失获分摊。",tw:{ch:"風險與保險",q:"保險對社會的效益不包括？",o:["完全消除社會上的所有風險","補償經濟損失、助人災後重建","協助信貸（銀行要求按揭物業投保）","提供心理安心、促進商業與投資活動"],e:"保險可補償損失、提供安心、促進經濟活動，但不能消除風險本身——風險依然存在，只是損失獲分攤。"}},
{p:1,ch:"风险与保险",q:"保险与赌博的基本分别是？",o:["保险也是一种赌博","赌博受保监局规管","完全相同","保险须有可保利益且只降低既有风险；赌博无利益关系且制造新风险"],a:3,e:"保险要求可保利益，投保人本就暴露于该风险；赌博凭空制造风险。此分别是可保利益原则存在的重要理由。",tw:{ch:"風險與保險",q:"保險與賭博的基本分別是？",o:["保險也是一種賭博","賭博受保監局規管","完全相同","保險須有可保利益且只降低既有風險；賭博無利益關係且製造新風險"],e:"保險要求可保利益，投保人本就暴露於該風險；賭博憑空製造風險。此分別是可保利益原則存在的重要理由。"}},
{p:1,ch:"风险与保险",q:"「大数法则」对保险的作用是？",o:["消除所有风险","保证保险公司永不亏损","让保费随意定价","承保风险单位越多，实际损失率越接近预期，定价越准确"],a:3,e:"大数法则说明样本越大，实际结果越接近统计预期；这是保险以生命表／损失统计定价的数理基础。",tw:{ch:"風險與保險",q:"「大數法則」對保險的作用是？",o:["消除所有風險","保證保險公司永不虧損","讓保費隨意定價","承保風險單位越多，實際損失率越接近預期，定價越準確"],e:"大數法則說明樣本越大，實際結果越接近統計預期；這是保險以生命表／損失統計定價的數理基礎。"}},
{p:1,ch:"风险与保险",q:"基本风险一般不可保的主因是？",o:["法例鼓励自留","损失太轻微","影响面太广、损失巨大，私人保险市场难以承担","发生太罕见"],a:2,e:"战争、地震等基本风险会影响大量保单持有人 simultaneously，远超保险人承受能力，故通常列为除外或由政府安排保障。",tw:{ch:"風險與保險",q:"基本風險一般不可保的主因是？",o:["法例鼓勵自留","損失太輕微","影響面太廣、損失巨大，私人保險市場難以承擔","發生太罕見"],e:"戰爭、地震等基本風險會影響大量保單持有人 simultaneously，遠超保險人承受能力，故通常列為除外或由政府安排保障。"}},
{p:1,ch:"风险与保险",q:"可保利益原则的作用不包括？",o:["防止赌博性保单","让投保人与保险标的有真实利害关系","保证保险人盈利","控制道德危险"],a:2,e:"可保利益确保投保人对标的有真实利害关系，以防赌博与道德危险；它不能保证保险人盈利。",tw:{ch:"風險與保險",q:"可保利益原則的作用不包括？",o:["防止賭博性保單","讓投保人與保險標的有真實利害關係","保證保險人盈利","控制道德危險"],e:"可保利益確保投保人對標的有真實利害關係，以防賭博與道德危險；它不能保證保險人盈利。"}},
{p:1,ch:"风险与保险",q:"个人进行风险评估时，「量化风险」是指？",o:["缴付保费","估计损失发生的频率及潜在严重程度","填写投保单","接受体检"],a:1,e:"量化风险是把已识别的风险转化为数字：发生概率多大、一旦发生的损失多严重，以决定应对方式。",tw:{ch:"風險與保險",q:"個人進行風險評估時，「量化風險」是指？",o:["繳付保費","估計損失發生的頻率及潛在嚴重程度","填寫投保單","接受體檢"],e:"量化風險是把已識別的風險轉化為數字：發生概率多大、一旦發生的損失多嚴重，以決定應對方式。"}},
{p:1,ch:"风险与保险",q:"「心理（士气）危险」与「道德危险」的分别是？",o:["道德危险是无心之过","两者完全相同","心理危险较严重","心理危险是无心的疏忽心态；道德危险涉及不诚实的意图"],a:3,e:"士气危险是无意的（以为有保就大意），道德危险是有欺诈意图的（如蓄意制造损失），后者性质更严重。",tw:{ch:"風險與保險",q:"「心理（士氣）危險」與「道德危險」的分別是？",o:["道德危險是無心之過","兩者完全相同","心理危險較嚴重","心理危險是無心的疏忽心態；道德危險涉及不誠實的意圖"],e:"士氣危險是無意的（以為有保就大意），道德危險是有欺詐意圖的（如蓄意製造損失），後者性質更嚴重。"}},
{p:1,ch:"风险与保险",q:"保险人防范「逆选择」的主要工具是？",o:["核保","广告宣传","派发红利","提高佣金"],a:0,e:"核保通过风险评估、体检、财务审查筛选风险，是管理逆选择（高风险者更愿投保）的核心机制。",tw:{ch:"風險與保險",q:"保險人防範「逆選擇」的主要工具是？",o:["核保","廣告宣傳","派發紅利","提高佣金"],e:"核保通過風險評估、體檢、財務審查篩選風險，是管理逆選擇（高風險者更願投保）的核心機制。"}},
{p:1,ch:"风险与保险",q:"「损失频率低、损失程度低」的风险（如小额易耗品），通常应？",o:["购买全险","转嫁他人","自留（自担）","完全避免一切活动"],a:2,e:"低频率低损失的风险自担成本很低，买保险反而不经济——保费含费用及利润，小额损失自留即可。",tw:{ch:"風險與保險",q:"「損失頻率低、損失程度低」的風險（如小額易耗品），通常應？",o:["購買全險","轉嫁他人","自留（自擔）","完全避免一切活動"],e:"低頻率低損失的風險自擔成本很低，買保險反而不經濟——保費含費用及利潤，小額損失自留即可。"}},
{p:1,ch:"法律原则",q:"要约人何时可以撤回要约？",o:["合约签订之后","承诺作出之前的任何时候","任何时候都不可以","承诺作出之后"],a:1,e:"要约可于受要约人承诺前撤回；一旦承诺，合约即告成立，不得单方撤回。",tw:{ch:"法律原則",q:"要約人何時可以撤回要約？",o:["合約簽訂之後","承諾作出之前的任何時候","任何時候都不可以","承諾作出之後"],e:"要約可於受要約人承諾前撤回；一旦承諾，合約即告成立，不得單方撤回。"}},
{p:1,ch:"法律原则",q:"有效的承诺必须是？",o:["沉默即可","只接受部分条款","绝对且无条件地接受要约条款","附条件地接受"],a:2,e:"承诺须与要约条款完全一致；附加条件的「承诺」视为反要约，原要约人有权接受或拒绝。",tw:{ch:"法律原則",q:"有效的承諾必須是？",o:["沉默即可","只接受部分條款","絕對且無條件地接受要約條款","附條件地接受"],e:"承諾須與要約條款完全一致；附加條件的「承諾」視為反要約，原要約人有權接受或拒絕。"}},
{p:1,ch:"法律原则",q:"「沉默一般不构成承诺」的意思是？",o:["只在寿险适用","由中介决定","受要约人不出声，通常不视为接受要约","沉默即接受"],a:2,e:"除非双方有既定惯例或事先约定，否则要约人不能把受要约人的沉默视为承诺——须明确表达接受。",tw:{ch:"法律原則",q:"「沉默一般不構成承諾」的意思是？",o:["只在壽險適用","由中介決定","受要約人不出聲，通常不視為接受要約","沉默即接受"],e:"除非雙方有既定慣例或事先約定，否則要約人不能把受要約人的沉默視為承諾——須明確表達接受。"}},
{p:1,ch:"法律原则",q:"对价的基本要求是？",o:["有价值即可，无须与对方的付出相等","必须与对方付出完全等值","必须以金钱形式","只有一方需要付出"],a:0,e:"法律只要求对价有法律价值（保费、承诺等均可），不要求等价——1 港元也可构成有效对价。",tw:{ch:"法律原則",q:"對價的基本要求是？",o:["有價值即可，無須與對方的付出相等","必須與對方付出完全等值","必須以金錢形式","只有一方需要付出"],e:"法律只要求對價有法律價值（保費、承諾等均可），不要求等價——1 港元也可構成有效對價。"}},
{p:1,ch:"法律原则",q:"合约的目的必须？",o:["合法","书面订立","盈利","经政府批准"],a:0,e:"非法目的（如诈骗、走私）的合约自始无效；合法性是合约有效的基本要素之一。",tw:{ch:"法律原則",q:"合約的目的必須？",o:["合法","書面訂立","盈利","經政府批准"],e:"非法目的（如詐騙、走私）的合約自始無效；合法性是合約有效的基本要素之一。"}},
{p:1,ch:"法律原则",q:"「契据」（Deed）与「简单合约」的分别是？",o:["契据没有约束力","两者完全相同","简单合约须律师签署","契据须以盖章形式订立、无须对价；简单合约须有对价"],a:3,e:"契据以书面盖章形式订立而无须对价（如馈赠契据）；一般商业及保险合约属简单合约，须有对价。",tw:{ch:"法律原則",q:"「契據」（Deed）與「簡單合約」的分別是？",o:["契據沒有約束力","兩者完全相同","簡單合約須律師簽署","契據須以蓋章形式訂立、無須對價；簡單合約須有對價"],e:"契據以書面蓋章形式訂立而無須對價（如饋贈契據）；一般商業及保險合約屬簡單合約，須有對價。"}},
{p:1,ch:"法律原则",q:"投保人披露重要事实的对象是？",o:["法院","家人","保险人（通常经由其代理或中介）","税务局"],a:2,e:"披露义务指向保险人——现实中多经由保险代理或经纪转达，代理人知悉即视为保险人知悉。",tw:{ch:"法律原則",q:"投保人披露重要事實的對象是？",o:["法院","家人","保險人（通常經由其代理或中介）","税務局"],e:"披露義務指向保險人——現實中多經由保險代理或經紀轉達，代理人知悉即視為保險人知悉。"}},
{p:1,ch:"法律原则",q:"投保人不知道自己患病而未申报，是否构成「不披露重要事实」？",o:["构成犯罪","不构成——投保人不知道的事实无须披露","构成欺诈","构成违约"],a:1,e:"披露义务限于投保人实际知道或应当知道的重要事实；连自己也不知悉的病症不构成不披露（但须如实回答已知情况）。",tw:{ch:"法律原則",q:"投保人不知道自己患病而未申報，是否構成「不披露重要事實」？",o:["構成犯罪","不構成——投保人不知道的事實無須披露","構成欺詐","構成違約"],e:"披露義務限於投保人實際知道或應當知道的重要事實；連自己也不知悉的病症不構成不披露（但須如實回答已知情況）。"}},
{p:1,ch:"法律原则",q:"被保险人违反保单中的「保证」（Warranty）条款，保险人可以？",o:["自动延长保障","必须继续承保","只罚款了事","自违反时起免除保险责任"],a:3,e:"保证是严格的合约承诺（如安装消防装置、不存放危险品），违反保证保险人可免除相应责任，不论违反与损失有无关连。",tw:{ch:"法律原則",q:"被保險人違反保單中的「保證」（Warranty）條款，保險人可以？",o:["自動延長保障","必須繼續承保","只罰款了事","自違反時起免除保險責任"],e:"保證是嚴格的合約承諾（如安裝消防裝置、不存放危險品），違反保證保險人可免除相應責任，不論違反與損失有無關連。"}},
{p:1,ch:"法律原则",q:"「陈述」（Representation）与「保证」的分别是？",o:["陈述是投保时的申报，一般只须大致准确；保证是严格承诺，必须完全遵守","两者相同","保证只适用于汽车保险","陈述较严格"],a:0,e:"陈述（如对健康状况的问卷回答）须诚实且大致准确；保证则具严格法律约束力，稍有违反即可免除责任。",tw:{ch:"法律原則",q:"「陳述」（Representation）與「保證」的分別是？",o:["陳述是投保時的申報，一般只須大致準確；保證是嚴格承諾，必須完全遵守","兩者相同","保證只適用於汽車保險","陳述較嚴格"],e:"陳述（如對健康狀況的問卷回答）須誠實且大致準確；保證則具嚴格法律約束力，稍有違反即可免除責任。"}},
{p:1,ch:"法律原则",q:"保险人发现可撤销合约的理由后，取消合约须？",o:["任何时候均可无限期保留权利","在知悉权利后于合理时间内行使，否则可能丧失该权利","必须经立法会同意","只须经保监局批准"],a:1,e:"弃权与禁止反言原则下，保险人知悉撤销权后若继续收取保费或不作行动，可能被视为放弃权利。",tw:{ch:"法律原則",q:"保險人發現可撤銷合約的理由後，取消合約須？",o:["任何時候均可無限期保留權利","在知悉權利後於合理時間內行使，否則可能喪失該權利","必須經立法會同意","只須經保監局批准"],e:"棄權與禁止反言原則下，保險人知悉撤銷權後若繼續收取保費或不作行動，可能被視為放棄權利。"}},
{p:1,ch:"法律原则",q:"代理人的授权可以如何产生？",o:["只可书面授予","不能授予授权","只可口头授予","明示授权，或由职位/惯例产生的暗示授权，或表见授权"],a:3,e:"授权来源包括明示（书面/口头委任）、暗示（履行职务所必需）及表见授权（本人行为令第三方合理信赖）。",tw:{ch:"法律原則",q:"代理人的授權可以如何產生？",o:["只可書面授予","不能授予授權","只可口頭授予","明示授權，或由職位/慣例產生的暗示授權，或表見授權"],e:"授權來源包括明示（書面/口頭委任）、暗示（履行職務所必需）及表見授權（本人行為令第三方合理信賴）。"}},
{p:1,ch:"法律原则",q:"代理人收取投保人保费后据为己有，对投保人而言？",o:["视为已缴付给保险人，投保人无须再缴","不了了之","投保人须再缴一次","由中介赔偿"],a:0,e:"代理人在授权范围内收取保费视为本人（保险人）收取，保险人受损失应向代理人追讨，不能要求投保人再缴。",tw:{ch:"法律原則",q:"代理人收取投保人保費後據為己有，對投保人而言？",o:["視為已繳付給保險人，投保人無須再繳","不了了之","投保人須再繳一次","由中介賠償"],e:"代理人在授權範圍內收取保費視為本人（保險人）收取，保險人受損失應向代理人追討，不能要求投保人再繳。"}},
{p:1,ch:"法律原则",q:"保险经纪收到客户交来的保费，应如何处理？",o:["存入与自有资金分开的客户款项账户","与自有资金混用","捐作慈善","拿去投资"],a:0,e:"经纪受信责任要求客户款项与公司资金严格分离，并存放在指定的客户款项银行账户，保障客户利益。",tw:{ch:"法律原則",q:"保險經紀收到客户交來的保費，應如何處理？",o:["存入與自有資金分開的客户款項賬户","與自有資金混用","捐作慈善","拿去投資"],e:"經紀受信責任要求客户款項與公司資金嚴格分離，並存放在指定的客户款項銀行賬户，保障客户利益。"}},
{p:1,ch:"保险原则",q:"「全险」保单下，有关举证责任的正确说法是？",o:["无须任何举证","被保险人须证明损失由受保意外造成；除外责任的存在由保险人举证","全部举证责任归保险人","全部举证责任归被保险人"],a:1,e:"全险保单下，被保险人须证明有受保意外发生；保险人若援引除外责任，须就该除外事实负举证责任。",tw:{ch:"保險原則",q:"「全險」保單下，有關舉證責任的正確說法是？",o:["無須任何舉證","被保險人須證明損失由受保意外造成；除外責任的存在由保險人舉證","全部舉證責任歸保險人","全部舉證責任歸被保險人"],e:"全險保單下，被保險人須證明有受保意外發生；保險人若援引除外責任，須就該除外事實負舉證責任。"}},
{p:1,ch:"保险原则",q:"受保危险与除外危险同时造成一项不可分割的损失，通常？",o:["按主导（近）成因判断","各赔一半","自动全赔","自动不赔"],a:0,e:"损失不可分割时须找出主导成因：主导为受保危险则获赔，主导为除外危险则不获赔。",tw:{ch:"保險原則",q:"受保危險與除外危險同時造成一項不可分割的損失，通常？",o:["按主導（近）成因判斷","各賠一半","自動全賠","自動不賠"],e:"損失不可分割時須找出主導成因：主導為受保危險則獲賠，主導為除外危險則不獲賠。"}},
{p:1,ch:"保险原则",q:"除人寿保险外，下列哪项也属「利益保单」而不适用弥偿？",o:["人身意外保险","火险","水险","汽车保险"],a:0,e:"人身意外按约定金额给付，与人寿、危疾等同属利益保单；财产保险才适用弥偿。",tw:{ch:"保險原則",q:"除人壽保險外，下列哪項也屬「利益保單」而不適用彌償？",o:["人身意外保險","火險","水險","汽車保險"],e:"人身意外按約定金額給付，與人壽、危疾等同屬利益保單；財產保險才適用彌償。"}},
{p:1,ch:"保险原则",q:"弥偿原则中「不多不少」的「不多」是指？",o:["随意赔付","赔偿必定高于损失","赔偿必定低于损失","被保险人不得因投保而获得比实际损失更多的利益"],a:3,e:"弥偿既防不足也防超额：被保险人最多只能回复到损失发生前的财务状况，不得从中获利。",tw:{ch:"保險原則",q:"彌償原則中「不多不少」的「不多」是指？",o:["隨意賠付","賠償必定高於損失","賠償必定低於損失","被保險人不得因投保而獲得比實際損失更多的利益"],e:"彌償既防不足也防超額：被保險人最多隻能回覆到損失發生前的財務狀況，不得從中獲利。"}},
{p:1,ch:"保险原则",q:"「重置价值」（Reinstatement Value）保单的特点？",o:["按购买原价打折","按重置新价赔偿，不扣折旧，赔偿可超过实际现金价值","按折旧后价值赔偿","只赔现金"],a:1,e:"重置价值保单（常见于火险楼宇/机器）以新换旧方式赔偿，保障被保险人可重置财产。",tw:{ch:"保險原則",q:"「重置價值」（Reinstatement Value）保單的特點？",o:["按購買原價打折","按重置新價賠償，不扣折舊，賠償可超過實際現金價值","按折舊後價值賠償","只賠現金"],e:"重置價值保單（常見於火險樓宇/機器）以新換舊方式賠償，保障被保險人可重置財產。"}},
{p:1,ch:"保险原则",q:"「定值保单」（Valued Policy）最常见于？",o:["责任保险","海上保险（水险）","医疗保险","汽车保险"],a:1,e:"水险中船舶、货物价值难以事后确定，故于投保时约定价值，全损时按约定价值赔付。",tw:{ch:"保險原則",q:"「定值保單」（Valued Policy）最常見於？",o:["責任保險","海上保險（水險）","醫療保險","汽車保險"],e:"水險中船舶、貨物價值難以事後確定，故於投保時約定價值，全損時按約定價值賠付。"}},
{p:1,ch:"保险原则",q:"比例分摊（Average）条款的目的不包括？",o:["让不足额投保者自负部分损失","鼓励足额投保","增加保险公司利润","公平对待足额投保的投保人"],a:2,e:"平均条款旨在维护足额投保者之间的公平：不足额投保者按比例自留部分损失，并非为增加保险人利润。",tw:{ch:"保險原則",q:"比例分攤（Average）條款的目的不包括？",o:["讓不足額投保者自負部分損失","鼓勵足額投保","增加保險公司利潤","公平對待足額投保的投保人"],e:"平均條款旨在維護足額投保者之間的公平：不足額投保者按比例自留部分損失，並非為增加保險人利潤。"}},
{p:1,ch:"保险原则",q:"被保险人向多家保险人投保同一标的，应？",o:["无须申报","对其他保险人保密","将其他保险的存在通知各保险人","只告知先出单的公司"],a:2,e:"重复保险时须如实通知各保险人，以便按保单条款（比例分摊或溢额条款）处理，避免违反最大诚信。",tw:{ch:"保險原則",q:"被保險人向多家保險人投保同一標的，應？",o:["無須申報","對其他保險人保密","將其他保險的存在通知各保險人","只告知先出單的公司"],e:"重複保險時須如實通知各保險人，以便按保單條款（比例分攤或溢額條款）處理，避免違反最大誠信。"}},
{p:1,ch:"保险原则",q:"保险人行使代位权利的时间是？",o:["任何时间均可","向被保险人赔付之后","核保之前","投保时"],a:1,e:"代位权于保险人赔付后取得——未赔付前无损失可代位，故赔付是代位的前提。",tw:{ch:"保險原則",q:"保險人行使代位權利的時間是？",o:["任何時間均可","向被保險人賠付之後","核保之前","投保時"],e:"代位權於保險人賠付後取得——未賠付前無損失可代位，故賠付是代位的前提。"}},
{p:1,ch:"保险原则",q:"被保险人事先与第三者订约放弃追偿权，对保险人代位权的影响是？",o:["损害保险人的代位权，保险人可就受影响部分拒赔","毫无影响","保险人须双倍赔偿","由中介人代位"],a:0,e:"事前放弃追偿等于剥夺保险人代位权，属违反保单义务，保险人有权就因此受损的范围拒绝赔偿。",tw:{ch:"保險原則",q:"被保險人事先與第三者訂約放棄追償權，對保險人代位權的影響是？",o:["損害保險人的代位權，保險人可就受影響部分拒賠","毫無影響","保險人須雙倍賠償","由中介人代位"],e:"事前放棄追償等於剝奪保險人代位權，屬違反保單義務，保險人有權就因此受損的範圍拒絕賠償。"}},
{p:1,ch:"保险原则",q:"重复保险下，被保险人合计可获得的最高赔偿是？",o:["实际损失额","损失额的两倍","全部保单保额总和","保额加保费"],a:0,e:"弥偿原则下，重复保险不会令被保险人致富——合计赔偿以实际损失为上限，各保险人按比例分担。",tw:{ch:"保險原則",q:"重複保險下，被保險人合計可獲得的最高賠償是？",o:["實際損失額","損失額的兩倍","全部保單保額總和","保額加保費"],e:"彌償原則下，重複保險不會令被保險人致富——合計賠償以實際損失為上限，各保險人按比例分擔。"}},
{p:1,ch:"保险原则",q:"「委付」（Abandonment）的生效条件是？",o:["自动生效","可部分委付","只适用于汽车险","须就全部损失提出、不得附带条件，保险人可接受或拒绝"],a:3,e:"委付必须完整、无条件提出，由保险人选择接受（取得标的残余）或拒绝；获全损赔偿后标的残余归保险人。",tw:{ch:"保險原則",q:"「委付」（Abandonment）的生效條件是？",o:["自動生效","可部分委付","只適用於汽車險","須就全部損失提出、不得附帶條件，保險人可接受或拒絕"],e:"委付必須完整、無條件提出，由保險人選擇接受（取得標的殘餘）或拒絕；獲全損賠償後標的殘餘歸保險人。"}},
{p:1,ch:"保险原则",q:"施救费用（Sue and Labour Charges）与损失赔偿的合计上限通常是？",o:["没有上限","保险金额","按已缴保费","固定 1 万元"],a:1,e:"被保险人于损失发生后尽力施救，施救费用与损失赔偿合计一般仍以保额为限，防止道德危险。",tw:{ch:"保險原則",q:"施救費用（Sue and Labour Charges）與損失賠償的合計上限通常是？",o:["沒有上限","保險金額","按已繳保費","固定 1 萬元"],e:"被保險人於損失發生後盡力施救，施救費用與損失賠償合計一般仍以保額為限，防止道德危險。"}},
{p:1,ch:"保险原则",q:"「损余」（Salvage）处理与代位原则的共同精神是？",o:["方便理赔","增加保险人收益","防止被保险人获得超过实际损失的得益","惩罚第三者"],a:2,e:"损余扣减与代位追偿都源于弥偿原则的精神：被保险人不可因损失而额外获利，利益归于保险人。",tw:{ch:"保險原則",q:"「損餘」（Salvage）處理與代位原則的共同精神是？",o:["方便理賠","增加保險人收益","防止被保險人獲得超過實際損失的得益","懲罰第三者"],e:"損餘扣減與代位追償都源於彌償原則的精神：被保險人不可因損失而額外獲利，利益歸於保險人。"}},
{p:1,ch:"保险原则",q:"保险体现「公平」的方式不包括？",o:["费率反映风险高低（公平对待同类投保人）","风险共担（公平分摊损失）","赔偿按实际损失（公平对待被保险人）","随意收取保费"],a:3,e:"公平体现在风险分摊、费率与风险挂钩、赔偿与损失一致；随意定价违反核保与公平原则。",tw:{ch:"保險原則",q:"保險體現「公平」的方式不包括？",o:["費率反映風險高低（公平對待同類投保人）","風險共擔（公平分攤損失）","賠償按實際損失（公平對待被保險人）","隨意收取保費"],e:"公平體現在風險分攤、費率與風險掛鈎、賠償與損失一致；隨意定價違反核保與公平原則。"}},
{p:1,ch:"法律原则",q:"「保险单本身并不是合约」，这句话的意思是？",o:["保单等同投保单","保险单只是一张广告","保险单是保险合约存在的证据，合约先于保单存在","保单没有法律效力"],a:2,e:"合约是无形的法律关系，在要约获承诺时即告成立；保险单是证明合约条款的文件。保险合约甚至无须书面也可有效，实际上几乎一律书面。",tw:{ch:"法律原則",q:"「保險單本身並不是合約」，這句話的意思是？",o:["保單等同投保單","保險單只是一張廣告","保險單是保險合約存在的證據，合約先於保單存在","保單沒有法律效力"],e:"合約是無形的法律關係，在要約獲承諾時即告成立；保險單是證明合約條款的文件。保險合約甚至無須書面也可有效，實際上幾乎一律書面。"}},
{p:1,ch:"法律原则",q:"受要约人的「承约」内容与要约内容不完全相同，法律后果是？",o:["仍然有效承诺","要约永久有效","合约自动成立","构成反要约，原要约失效"],a:3,e:"承约必须与要约完全一致；更改条款的承约视为反要约，原要约即告失效，由要约人再决定接受与否。",tw:{ch:"法律原則",q:"受要約人的「承約」內容與要約內容不完全相同，法律後果是？",o:["仍然有效承諾","要約永久有效","合約自動成立","構成反要約，原要約失效"],e:"承約必須與要約完全一致；更改條款的承約視為反要約，原要約即告失效，由要約人再決定接受與否。"}},
{p:1,ch:"法律原则",q:"「有缺陷的合约」不包括下列哪类？",o:["永不失效的合约","无效合约（法律上不存在）","不能强制执行的合约（只欠某些形式要求）","可使无效合约（受屈方可选择推翻）"],a:0,e:"无效合约自始无法律效力；可使无效合约在被推翻前有效；不能强制执行的合约只是暂欠形式要求（如未完成书面手续），补足即可执行。",tw:{ch:"法律原則",q:"「有缺陷的合約」不包括下列哪類？",o:["永不失效的合約","無效合約（法律上不存在）","不能強制執行的合約（只欠某些形式要求）","可使無效合約（受屈方可選擇推翻）"],e:"無效合約自始無法律效力；可使無效合約在被推翻前有效；不能強制執行的合約只是暫欠形式要求（如未完成書面手續），補足即可執行。"}},
{p:1,ch:"法律原则",q:"保险代理人的权限种类不包括？",o:["隐含授权","无限授权","表见（表面）授权","明示授权"],a:1,e:"代理人权限包括明示、隐含（职务必需）、表见（本人行为令第三方合理信赖）及必要权限（紧急情况保护委托人利益）；不存在「无限授权」。",tw:{ch:"法律原則",q:"保險代理人的權限種類不包括？",o:["隱含授權","無限授權","表見（表面）授權","明示授權"],e:"代理人權限包括明示、隱含（職務必需）、表見（本人行為令第三方合理信賴）及必要權限（緊急情況保護委託人利益）；不存在「無限授權」。"}},
{p:1,ch:"法律原则",q:"「必要权限」（Authority of Necessity）通常在什么情况下产生？",o:["委托人的财产或权益面临紧急危险，代理人须代为处理","签订任何合约","代理人想多赚佣金","日常推销产品"],a:0,e:"在紧急情况下为保护委托人利益而必需行事时，代理人取得必要权限，其合理行为对委托人有效。",tw:{ch:"法律原則",q:"「必要權限」（Authority of Necessity）通常在什麼情況下產生？",o:["委託人的財產或權益面臨緊急危險，代理人須代為處理","簽訂任何合約","代理人想多賺佣金","日常推銷產品"],e:"在緊急情況下為保護委託人利益而必需行事時，代理人取得必要權限，其合理行為對委託人有效。"}},
{p:1,ch:"法律原则",q:"代理人能否把自己的职责转授他人？",o:["只能转授给亲属","可以，无须任何条件","绝对不能","除具有转授权限外，不能自行转授"],a:3,e:"代理人须亲自执行，不得擅自转授权限；只有委托人同意或代理权限明确容许时方可转授。",tw:{ch:"法律原則",q:"代理人能否把自己的職責轉授他人？",o:["只能轉授給親屬","可以，無須任何條件","絕對不能","除具有轉授權限外，不能自行轉授"],e:"代理人須親自執行，不得擅自轉授權限；只有委託人同意或代理權限明確容許時方可轉授。"}},
{p:1,ch:"法律原则",q:"关于委托人对代理人的责任，下列哪项正确？",o:["委托人须承担代理人一切私人开支","佣金并非保证，须视乎代理协议及业绩","佣金是委托人的保证给付，必须支付","委托人无义务补偿代理人的业务支出"],a:1,e:"除非协议保证，佣金须按代理人实际做成的业务支付；委托人一般须补偿代理人获授权招致的业务支出。",tw:{ch:"法律原則",q:"關於委託人對代理人的責任，下列哪項正確？",o:["委託人須承擔代理人一切私人開支","佣金並非保證，須視乎代理協議及業績","佣金是委託人的保證給付，必須支付","委託人無義務補償代理人的業務支出"],e:"除非協議保證，佣金須按代理人實際做成的業務支付；委託人一般須補償代理人獲授權招致的業務支出。"}},
{p:1,ch:"法律原则",q:"下列哪项不会导致代理关系终止？",o:["协议期限届满","委托人或代理人死亡（或公司清盘）","代理人的子女出生","双方同意撤销"],a:2,e:"代理关系可因协议终止、撤销、违约、死亡、精神错乱、非法或期限届满而终止；代理关系不可世袭继承。",tw:{ch:"法律原則",q:"下列哪項不會導致代理關係終止？",o:["協議期限屆滿","委託人或代理人死亡（或公司清盤）","代理人的子女出生","雙方同意撤銷"],e:"代理關係可因協議終止、撤銷、違約、死亡、精神錯亂、非法或期限屆滿而終止；代理關係不可世襲繼承。"}},
{p:1,ch:"保险原则",q:"财产保险中，下列哪类人对他人财产具有可保权益？",o:["任何朋友","承按人（按揭权人）","普通路人","邻居"],a:1,e:"承按人、受托保管人、遗嘱执行人、遗产管理人、信托人等对他人财产负有法律责任或权益，故具有可保利益。",tw:{ch:"保險原則",q:"財產保險中，下列哪類人對他人財產具有可保權益？",o:["任何朋友","承按人（按揭權人）","普通路人","鄰居"],e:"承按人、受託保管人、遺囑執行人、遺產管理人、信託人等對他人財產負有法律責任或權益，故具有可保利益。"}},
{p:1,ch:"保险原则",q:"雇主对雇员工作时疏忽引致的第三者损失负上责任，这属于？",o:["直接责任","转承责任","合约责任","道德责任"],a:1,e:"转承责任（Vicarious Liability）指一方须为另一方的行为负责，如雇主为雇员的职务疏忽负责；可就此投保责任保险。",tw:{ch:"保險原則",q:"僱主對僱員工作時疏忽引致的第三者損失負上責任，這屬於？",o:["直接責任","轉承責任","合約責任","道德責任"],e:"轉承責任（Vicarious Liability）指一方須為另一方的行為負責，如僱主為僱員的職務疏忽負責；可就此投保責任保險。"}},
{p:1,ch:"保险原则",q:"「保单转让」与「收取保险金权利的转让」的分别是？",o:["保单转让不须任何手续","收取保险金权利转让须经保险人同意","两者相同","保单转让是合约权益全数转移；收取保险金权利转让后保单仍承保原被保险人"],a:3,e:"保单转让（如寿险、海上货物保单）可不经保险人同意；只转让收取赔款的权利时，保单仍属原被保险人，承让人无须有可保利益。",tw:{ch:"保險原則",q:"「保單轉讓」與「收取保險金權利的轉讓」的分別是？",o:["保單轉讓不須任何手續","收取保險金權利轉讓須經保險人同意","兩者相同","保單轉讓是合約權益全數轉移；收取保險金權利轉讓後保單仍承保原被保險人"],e:"保單轉讓（如壽險、海上貨物保單）可不經保險人同意；只轉讓收取賠款的權利時，保單仍屬原被保險人，承讓人無須有可保利益。"}},
{p:1,ch:"保险原则",q:"下列哪种保单的转让实务上可不经保险人同意？",o:["汽车保单","人寿保单及海上货物保单","所有保单都不可以","所有保单都可以"],a:1,e:"人寿保单与海上货物保单具流通性，可自由转让；其他保单转让通常受条款限制。",tw:{ch:"保險原則",q:"下列哪種保單的轉讓實務上可不經保險人同意？",o:["汽車保單","人壽保單及海上貨物保單","所有保單都不可以","所有保單都可以"],e:"人壽保單與海上貨物保單具流通性，可自由轉讓；其他保單轉讓通常受條款限制。"}},
{p:1,ch:"保险原则",q:"多项危险造成损失，受保危险属主导成因、不保危险为次要，该损失？",o:["受保","各半赔","不受保","视乎保费"],a:0,e:"近因规则：受保危险主导或不保危险主导、而近因属受保的，损失一般受保；唯独除外危险主导时索偿失败。",tw:{ch:"保險原則",q:"多項危險造成損失，受保危險屬主導成因、不保危險為次要，該損失？",o:["受保","各半賠","不受保","視乎保費"],e:"近因規則：受保危險主導或不保危險主導、而近因屬受保的，損失一般受保；唯獨除外危險主導時索償失敗。"}},
{p:1,ch:"保险原则",q:"多项危险中「除外危险」属主导成因，则？",o:["自动全赔","索偿一般失败，除非条款另有约定","损失仍可能受保","由中介赔偿"],a:1,e:"除外危险主导时，即使同时存在受保危险，索偿一般失败——这是除外责任效力的核心。",tw:{ch:"保險原則",q:"多項危險中「除外危險」屬主導成因，則？",o:["自動全賠","索償一般失敗，除非條款另有約定","損失仍可能受保","由中介賠償"],e:"除外危險主導時，即使同時存在受保危險，索償一般失敗——這是除外責任效力的核心。"}},
{p:1,ch:"保险原则",q:"近因（主导成因）是否必须在保单所载的受保处所发生？",o:["无须","由中介决定","必须","只适用于火险"],a:0,e:"近因无须在所保处所发生——关键是成因与损失的因果关系，而非地理地点。",tw:{ch:"保險原則",q:"近因（主導成因）是否必須在保單所載的受保處所發生？",o:["無須","由中介決定","必須","只適用於火險"],e:"近因無須在所保處所發生——關鍵是成因與損失的因果關係，而非地理地點。"}},
{p:1,ch:"保险原则",q:"下列哪组条文会「限制」弥偿？",o:["比例分摊、保单限额、免赔额、起配额","以上皆是","重置条款、以新代旧","定值保单、约定价值"],a:0,e:"限制弥偿的条文使赔偿少于实际损失：比例分摊（不足额投保）、保单限额、免赔额及起配额（超赔）。",tw:{ch:"保險原則",q:"下列哪組條文會「限制」彌償？",o:["比例分攤、保單限額、免賠額、起配額","以上皆是","重置條款、以新代舊","定值保單、約定價值"],e:"限制彌償的條文使賠償少於實際損失：比例分攤（不足額投保）、保單限額、免賠額及起配額（超賠）。"}},
{p:1,ch:"保险原则",q:"在水险中，「Average」一词的意思是？",o:["损余","比例分摊条款","海损（部分损失）","平均保费"],a:2,e:"水险术语中 Average 指海损（部分损失）；只有在火险等语境下 average 才指比例分摊条款，考试须分清。",tw:{ch:"保險原則",q:"在水險中，「Average」一詞的意思是？",o:["損餘","比例分攤條款","海損（部分損失）","平均保費"],e:"水險術語中 Average 指海損（部分損失）；只有在火險等語境下 average 才指比例分攤條款，考試須分清。"}},
{p:1,ch:"保险原则",q:"「以新代旧」（New for Old）条款最常用于？",o:["人寿保险","医疗保险","责任保险","家居财物保险及船体保险"],a:3,e:"以新代旧不以折旧扣减，多用于家居财物及船体保单；重置条款则常见于火险及商业全险。",tw:{ch:"保險原則",q:"「以新代舊」（New for Old）條款最常用於？",o:["人壽保險","醫療保險","責任保險","家居財物保險及船體保險"],e:"以新代舊不以折舊扣減，多用於家居財物及船體保單；重置條款則常見於火險及商業全險。"}},
{p:1,ch:"保险原则",q:"定值保单常用于艺术品、珠宝等，是因为？",o:["较便宜","法律强制","这些物品价值高且价值不随折旧下降，保额按专家估值厘定","方便续保"],a:2,e:"价值不因折旧贬损且难以事后估值的物品适合定值保单；船体及海上货物保单甚至以约定价值一律视为损失时的实质价值。",tw:{ch:"保險原則",q:"定值保單常用於藝術品、珠寶等，是因為？",o:["較便宜","法律強制","這些物品價值高且價值不隨折舊下降，保額按專家估值釐定","方便續保"],e:"價值不因折舊貶損且難以事後估值的物品適合定值保單；船體及海上貨物保單甚至以約定價值一律視為損失時的實質價值。"}},
{p:1,ch:"保险原则",q:"重复保险中常见的「分担条款」不包括？",o:["免分担条款","无条件双倍赔偿条款","全险条款","比率之数条款"],a:1,e:"分担安排包括比率之数（按保额比例）、全险（各自全赔再追偿）、免分担及部分分担（海上条款）等；不存在无条件双倍赔偿。",tw:{ch:"保險原則",q:"重複保險中常見的「分擔條款」不包括？",o:["免分擔條款","無條件雙倍賠償條款","全險條款","比率之數條款"],e:"分擔安排包括比率之數（按保額比例）、全險（各自全賠再追償）、免分擔及部分分擔（海上條款）等；不存在無條件雙倍賠償。"}},
{p:1,ch:"保险原则",q:"代位权利可因「法规」而产生，香港例子是？",o:["《印花税条例》","《税务条例》","《公司条例》","《雇员补偿条例》"],a:3,e:"除侵权与合约外，法规亦可产生代位权——如雇员补偿条例下承保人赔付后可向疏忽第三者追偿。",tw:{ch:"保險原則",q:"代位權利可因「法規」而產生，香港例子是？",o:["《印花税條例》","《税務條例》","《公司條例》","《僱員補償條例》"],e:"除侵權與合約外，法規亦可產生代位權——如僱員補償條例下承保人賠付後可向疏忽第三者追償。"}},
{p:1,ch:"保险原则",q:"人寿保单在「每份保单均须全数赔付」方面的含义是？",o:["只赔一份","视乎保额","各保单按比例分摊","每份保单均独立全数给付，保单之间无分摊"],a:3,e:"人寿保单属利益保单，不适用弥偿与分担：持有多份寿险可获全数给付，这是与财产保险的重要分别。",tw:{ch:"保險原則",q:"人壽保單在「每份保單均須全數賠付」方面的含義是？",o:["只賠一份","視乎保額","各保單按比例分攤","每份保單均獨立全數給付，保單之間無分攤"],e:"人壽保單屬利益保單，不適用彌償與分擔：持有多份壽險可獲全數給付，這是與財產保險的重要分別。"}},
{p:1,ch:"保险公司的主要功能",q:"关于产品开发，下列哪项正确？",o:["全新产品推出后竞争力可维持多年","全新产品具有竞争力的寿命极为短暂，须不断研究改良","产品研究只看自家产品","产品开发是一次性工作"],a:1,e:"保险市场竞争激烈，新产品的竞争优势很快消失，故产品研究须持续进行，涵盖改良原有产品、竞争对手产品及市场趋势。",tw:{ch:"保險公司的主要功能",q:"關於產品開發，下列哪項正確？",o:["全新產品推出後競爭力可維持多年","全新產品具有競爭力的壽命極為短暫，須不斷研究改良","產品研究只看自家產品","產品開發是一次性工作"],e:"保險市場競爭激烈，新產品的競爭優勢很快消失，故產品研究須持續進行，涵蓋改良原有產品、競爭對手產品及市場趨勢。"}},
{p:1,ch:"保险公司的主要功能",q:"核保部门常用的指引工具不包括？",o:["拒绝名单","中奖名单","保费率指南","核保手册"],a:1,e:"核保手册、保费率指南及拒绝名单（不应承保的业务类型）是核保标准工具；列出拒绝业务时须留意不违反歧视法规。",tw:{ch:"保險公司的主要功能",q:"核保部門常用的指引工具不包括？",o:["拒絕名單","中獎名單","保費率指南","核保手冊"],e:"核保手冊、保費率指南及拒絕名單（不應承保的業務類型）是核保標準工具；列出拒絕業務時須留意不違反歧視法規。"}},
{p:1,ch:"保险公司的主要功能",q:"「拒绝名单」的使用要注意什么？",o:["越多越好","只限内部参考","会否违反任何歧视法规","字体要美观"],a:2,e:"拒绝名单虽可列明不承保的业务，但不得基于性别、残疾等受法例保障的特征作出歧视性拒绝。",tw:{ch:"保險公司的主要功能",q:"「拒絕名單」的使用要注意什麼？",o:["越多越好","只限內部參考","會否違反任何歧視法規","字體要美觀"],e:"拒絕名單雖可列明不承保的業務，但不得基於性別、殘疾等受法例保障的特徵作出歧視性拒絕。"}},
{p:1,ch:"保险公司的主要功能",q:"人寿保险合约的存在取决于？",o:["是否印刷保单","是否收到首次保费","是否见客","是否登报"],a:1,e:"人寿保险合约以收到首次保费为存在条件；一般保险合约则可在未收保费前已生效。",tw:{ch:"保險公司的主要功能",q:"人壽保險合約的存在取決於？",o:["是否印刷保單","是否收到首次保費","是否見客","是否登報"],e:"人壽保險合約以收到首次保費為存在條件；一般保險合約則可在未收保費前已生效。"}},
{p:1,ch:"保险公司的主要功能",q:"一般保险合约与人寿保险合约在生效上的分别是？",o:["一般保险必须收到保费才生效","人寿保单可随时取消","一般保险合约可于未收到保费时开始生效","没有分别"],a:2,e:"一般保险可在保费未收前生效（之后追缴）；人寿保险合约的存在则以收到首次保费为准。",tw:{ch:"保險公司的主要功能",q:"一般保險合約與人壽保險合約在生效上的分別是？",o:["一般保險必須收到保費才生效","人壽保單可隨時取消","一般保險合約可於未收到保費時開始生效","沒有分別"],e:"一般保險可在保費未收前生效（之後追繳）；人壽保險合約的存在則以收到首次保費為準。"}},
{p:1,ch:"保险公司的主要功能",q:"人寿保险理赔与一般保险理赔在管理模式上的分别是？",o:["人寿非集中","一般保险全部集中总部","人寿集中处理；一般保险非集中处理且赔案类型多","两者均非集中"],a:2,e:"人寿索偿相对单一（死亡、期满、退保），适合集中处理；一般保险索偿分散且类型多，多以非集中模式处理。",tw:{ch:"保險公司的主要功能",q:"人壽保險理賠與一般保險理賠在管理模式上的分別是？",o:["人壽非集中","一般保險全部集中總部","人壽集中處理；一般保險非集中處理且賠案類型多","兩者均非集中"],e:"人壽索償相對單一（死亡、期滿、退保），適合集中處理；一般保險索償分散且類型多，多以非集中模式處理。"}},
{p:1,ch:"保险公司的主要功能",q:"按保监局规定，从事哪类业务的保险人必须每年就该等业务储备金进行精算检讨？",o:["汽车保险或雇员补偿保险","人寿保险","旅游保险","水险"],a:0,e:"经营汽车保险或雇员补偿（法定）业务的保险人及再保险人，须每年对该等业务的未决申索储备金进行精算检讨。",tw:{ch:"保險公司的主要功能",q:"按保監局規定，從事哪類業務的保險人必須每年就該等業務儲備金進行精算檢討？",o:["汽車保險或僱員補償保險","人壽保險","旅遊保險","水險"],e:"經營汽車保險或僱員補償（法定）業務的保險人及再保險人，須每年對該等業務的未決申索儲備金進行精算檢討。"}},
{p:1,ch:"保险公司的主要功能",q:"精算部的「估值」工作为何重要？",o:["与财务无关","只为制作年报","只影响佣金","估值方法重大地影响公司的偿付准备金及可分配盈余金额"],a:3,e:"资产与负债的估值直接决定偿付准备金及可分配盈余，影响公司偿付能力及分红能力，是精算部核心职能。",tw:{ch:"保險公司的主要功能",q:"精算部的「估值」工作為何重要？",o:["與財務無關","只為製作年報","隻影響佣金","估值方法重大地影響公司的償付準備金及可分配盈餘金額"],e:"資產與負債的估值直接決定償付準備金及可分配盈餘，影響公司償付能力及分紅能力，是精算部核心職能。"}},
{p:1,ch:"保险公司的主要功能",q:"人寿核保与一般保险核保对「目标风险」的理解分别是？",o:["目标风险与客户无关","两者均指合意业务","人寿：目标风险是极合意的业务；一般保险：目标风险是甚高风险、极不合意的业务","两者均指高风险业务"],a:2,e:"同一术语在两语境下意义相反：寿险公司积极争取目标风险（优质业务）；一般保险人则警惕目标风险（危险业务，须拒保或特别条件）。",tw:{ch:"保險公司的主要功能",q:"人壽核保與一般保險核保對「目標風險」的理解分別是？",o:["目標風險與客户無關","兩者均指合意業務","人壽：目標風險是極合意的業務；一般保險：目標風險是甚高風險、極不合意的業務","兩者均指高風險業務"],e:"同一術語在兩語境下意義相反：壽險公司積極爭取目標風險（優質業務）；一般保險人則警惕目標風險（危險業務，須拒保或特別條件）。"}},
{p:1,ch:"保险公司的主要功能",q:"保险公司的培训与发展工作涵盖？",o:["只限管理层","无须培训","只限新入职","公司内部职员及外勤人员（职员及代理人）"],a:3,e:"培训与发展涵盖内部及外勤人员，内容须配合公司持续发展，亦鼓励员工考取专业资格。",tw:{ch:"保險公司的主要功能",q:"保險公司的培訓與發展工作涵蓋？",o:["只限管理層","無須培訓","只限新入職","公司內部職員及外勤人員（職員及代理人）"],e:"培訓與發展涵蓋內部及外勤人員，內容須配合公司持續發展，亦鼓勵員工考取專業資格。"}},
{p:1,ch:"保险公司的主要功能",q:"市场行销及促销部门的工作包括？",o:["精算估值","公共关系、推广、广告、赞助、市场调查","核保","理赔"],a:1,e:"行销及促销部门负责推广活动、广告赞助及市场调查，与产品开发部门紧密配合。",tw:{ch:"保險公司的主要功能",q:"市場行銷及促銷部門的工作包括？",o:["精算估值","公共關係、推廣、廣告、贊助、市場調查","核保","理賠"],e:"行銷及促銷部門負責推廣活動、廣告贊助及市場調查，與產品開發部門緊密配合。"}},
{p:1,ch:"保险公司的主要功能",q:"客户服务部门的职能不包括？",o:["提供文件","处理投诉","决定保费率","联络与公共关系"],a:2,e:"客户服务部负责联络、公关、文件提供及投诉处理；保费率厘定属精算及核保职能。",tw:{ch:"保險公司的主要功能",q:"客户服務部門的職能不包括？",o:["提供文件","處理投訴","決定保費率","聯絡與公共關係"],e:"客户服務部負責聯絡、公關、文件提供及投訴處理；保費率釐定屬精算及核保職能。"}},
{p:1,ch:"香港保险业的结构",q:"「银行保险」（Bancassurance）指？",o:["只限保险产品贷款","保险公司经营银行业务","银行与保险公司合并","银行代售保险产品"],a:3,e:"银行保险是透过银行分销保险产品的渠道模式，银行收取佣金或手续费，受相应规管。",tw:{ch:"香港保險業的結構",q:"「銀行保險」（Bancassurance）指？",o:["只限保險產品貸款","保險公司經營銀行業務","銀行與保險公司合併","銀行代售保險產品"],e:"銀行保險是透過銀行分銷保險產品的渠道模式，銀行收取佣金或手續費，受相應規管。"}},
{p:1,ch:"香港保险业的结构",q:"电话、互联网等直销渠道的主要优点是？",o:["提高保费","降低分销成本","不受规管","只适合团体业务"],a:1,e:"直销渠道省去中介佣金，降低分销成本，但亦须遵守同样的销售操守规管。",tw:{ch:"香港保險業的結構",q:"電話、互聯網等直銷渠道的主要優點是？",o:["提高保費","降低分銷成本","不受規管","只適合團體業務"],e:"直銷渠道省去中介佣金，降低分銷成本，但亦須遵守同樣的銷售操守規管。"}},
{p:1,ch:"香港保险业的结构",q:"香港保险市场的特点不包括？",o:["完全由政府垄断经营","自由开放、保险公司众多","竞争激烈","高度国际化"],a:0,e:"香港保险市场是国际化的自由市场，保险公司及中介众多，受法例规管而非政府经营。",tw:{ch:"香港保險業的結構",q:"香港保險市場的特點不包括？",o:["完全由政府壟斷經營","自由開放、保險公司眾多","競爭激烈","高度國際化"],e:"香港保險市場是國際化的自由市場，保險公司及中介眾多，受法例規管而非政府經營。"}},
{p:1,ch:"香港保险业的结构",q:"一般保险业务的主要类别不包括？",o:["汽车保险","水险","长期寿险","责任保险"],a:2,e:"一般保险涵盖汽车、财产、水险、意外、责任及雇员补偿等；长期寿险属长期业务类别。",tw:{ch:"香港保險業的結構",q:"一般保險業務的主要類別不包括？",o:["汽車保險","水險","長期壽險","責任保險"],e:"一般保險涵蓋汽車、財產、水險、意外、責任及僱員補償等；長期壽險屬長期業務類別。"}},
{p:1,ch:"香港保险业的结构",q:"保险中介人（代理人及经纪）在保险市场中的核心功能是？",o:["安排及促成保险合约、提供专业意见","制定保险法例","承保风险","管理保单持有人基金"],a:0,e:"中介人连接保险人与客户：代理人代表保险人销售，经纪代表客户安排保险，均属分销及顾问角色。",tw:{ch:"香港保險業的結構",q:"保險中介人（代理人及經紀）在保險市場中的核心功能是？",o:["安排及促成保險合約、提供專業意見","制定保險法例","承保風險","管理保單持有人基金"],e:"中介人連接保險人與客户：代理人代表保險人銷售，經紀代表客户安排保險，均屬分銷及顧問角色。"}},
{p:1,ch:"香港保险业的结构",q:"再保险人在保险市场中的角色是？",o:["直接面对零售客户销售","发牌监管中介","管理强积金","承接直接保险人分出的风险"],a:3,e:"再保险人只与保险人交易，承接分出风险，增强直接保险市场的承保能力。",tw:{ch:"香港保險業的結構",q:"再保險人在保險市場中的角色是？",o:["直接面對零售客户銷售","發牌監管中介","管理強積金","承接直接保險人分出的風險"],e:"再保險人只與保險人交易，承接分出風險，增強直接保險市場的承保能力。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局的性质是？",o:["保险业联会的附属部门","政府的政策局","商业公司","独立法定机构，财政及运作上独立于政府与业界"],a:3,e:"保监局是按《保险业条例》设立的独立法定机构，财政与运作独立于政府及业界，向保单持有人负责。",tw:{ch:"保險業的規管架構",q:"保險業監管局的性質是？",o:["保險業聯會的附屬部門","政府的政策局","商業公司","獨立法定機構，財政及運作上獨立於政府與業界"],e:"保監局是按《保險業條例》設立的獨立法定機構，財政與運作獨立於政府及業界，向保單持有人負責。"}},
{p:1,ch:"保险业的规管架构",q:"保监局的主要职能包括？",o:["制订保险产品","为保单持有人提供投资回报","保障保单持有人及潜在保单持有人的利益、促进保险业整体稳定","承保商业风险"],a:2,e:"保监局以保障保单持有人利益及促进保险业稳定为首要职能，并涵盖中介操守、公众教育、市场研究及协助维持金融稳定等。",tw:{ch:"保險業的規管架構",q:"保監局的主要職能包括？",o:["制訂保險產品","為保單持有人提供投資回報","保障保單持有人及潛在保單持有人的利益、促進保險業整體穩定","承保商業風險"],e:"保監局以保障保單持有人利益及促進保險業穩定為首要職能，並涵蓋中介操守、公眾教育、市場研究及協助維持金融穩定等。"}},
{p:1,ch:"保险业的规管架构",q:"保险人申请授权的最低「实缴股本」，经营一般业务为？",o:["1,000 万港元","200 万港元","5,000 万港元","2,000 万港元"],a:0,e:"授权最低实缴股本：一般业务 1,000 万、长期业务 1,000 万、两者兼营 2,000 万、法定业务 2,000 万、专属自保保险人 200 万港元。",tw:{ch:"保險業的規管架構",q:"保險人申請授權的最低「實繳股本」，經營一般業務為？",o:["1,000 萬港元","200 萬港元","5,000 萬港元","2,000 萬港元"],e:"授權最低實繳股本：一般業務 1,000 萬、長期業務 1,000 萬、兩者兼營 2,000 萬、法定業務 2,000 萬、專屬自保保險人 200 萬港元。"}},
{p:1,ch:"保险业的规管架构",q:"经营「长期业务」的保险人，授权最低实缴股本为？",o:["100 万港元","2,000 万港元","1,000 万港元","200 万港元"],a:2,e:"长期业务最低实缴股本为 1,000 万港元；若同时经营一般及长期业务则为 2,000 万港元。",tw:{ch:"保險業的規管架構",q:"經營「長期業務」的保險人，授權最低實繳股本為？",o:["100 萬港元","2,000 萬港元","1,000 萬港元","200 萬港元"],e:"長期業務最低實繳股本為 1,000 萬港元；若同時經營一般及長期業務則為 2,000 萬港元。"}},
{p:1,ch:"保险业的规管架构",q:"「专属自保保险人」的授权最低实缴股本为？",o:["200 万港元","2,000 万港元","1,000 万港元","500 万港元"],a:0,e:"专属自保保险人只为关联企业承保，风险集中，最低实缴股本要求较低，为 200 万港元。",tw:{ch:"保險業的規管架構",q:"「專屬自保保險人」的授權最低實繳股本為？",o:["200 萬港元","2,000 萬港元","1,000 萬港元","500 萬港元"],e:"專屬自保保險人只為關聯企業承保，風險集中，最低實繳股本要求較低，為 200 萬港元。"}},
{p:1,ch:"保险业的规管架构",q:"偿付准备金规定方面，经营一般业务保险人的最低要求为？",o:["1,000 万港元","200 万港元","2,000 万港元","1,200 万港元"],a:0,e:"最低偿付准备金：一般业务 1,000 万、长期业务 200 万、两者兼营 1,200 万、法定业务 2,000 万、专属自保 200 万港元。",tw:{ch:"保險業的規管架構",q:"償付準備金規定方面，經營一般業務保險人的最低要求為？",o:["1,000 萬港元","200 萬港元","2,000 萬港元","1,200 萬港元"],e:"最低償付準備金：一般業務 1,000 萬、長期業務 200 萬、兩者兼營 1,200 萬、法定業務 2,000 萬、專屬自保 200 萬港元。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险代理人的委任数目上限是？",o:["只限 1 家","任何人最多获 4 名获授权保险人委任，其中经营长期业务的保险人不超过 2 名","不设上限","最多 10 家"],a:1,e:"一人最多同时获 4 家保险人委任为代理人，但长期业务保险人最多 2 家，以防利益冲突及管理失当。",tw:{ch:"保險業的規管架構",q:"持牌保險代理人的委任數目上限是？",o:["只限 1 家","任何人最多獲 4 名獲授權保險人委任，其中經營長期業務的保險人不超過 2 名","不設上限","最多 10 家"],e:"一人最多同時獲 4 家保險人委任為代理人，但長期業務保險人最多 2 家，以防利益衝突及管理失當。"}},
{p:1,ch:"保险业的规管架构",q:"《持牌保险代理人操守守则》一般原则的数目及内容包括？",o:["12 项","8 项，包括诚实持正、公平行事并以客户最佳利益为重、谨慎技巧努力、胜任、资料披露、意见合适性、利益冲突及客户资产","5 项","3 项"],a:1,e:"操守守则有 8 项一般原则，涵盖由诚实持正至客户资产的完整操守框架。",tw:{ch:"保險業的規管架構",q:"《持牌保險代理人操守守則》一般原則的數目及內容包括？",o:["12 項","8 項，包括誠實持正、公平行事並以客户最佳利益為重、謹慎技巧努力、勝任、資料披露、意見合適性、利益衝突及客户資產","5 項","3 項"],e:"操守守則有 8 項一般原則，涵蓋由誠實持正至客户資產的完整操守框架。"}},
{p:1,ch:"保险业的规管架构",q:"《操守守则》在法律上的地位是？",o:["法庭判例","非附属法例，本身不具法律效力，但违反可致纪律处分","只供参考无法律后果","附属法例，直接有法律效力"],a:1,e:"操守守则非附属法例，但持牌人违反可构成纪律处分的依据，如谴责、罚款或吊销牌照。",tw:{ch:"保險業的規管架構",q:"《操守守則》在法律上的地位是？",o:["法庭判例","非附屬法例，本身不具法律效力，但違反可致紀律處分","只供參考無法律後果","附屬法例，直接有法律效力"],e:"操守守則非附屬法例，但持牌人違反可構成紀律處分的依據，如譴責、罰款或吊銷牌照。"}},
{p:1,ch:"保险业的规管架构",q:"按《操守守则》「诚实及持正」原则，代理人不得？",o:["防止贿赂","骚扰、强迫或不当影响客户","对客户作出准确的陈述","合规经营"],a:1,e:"诚实持正原则要求准确陈述、合规及防止贿赂，并明确禁止骚扰、强迫或不当影响客户作决定。",tw:{ch:"保險業的規管架構",q:"按《操守守則》「誠實及持正」原則，代理人不得？",o:["防止賄賂","騷擾、強迫或不當影響客户","對客户作出準確的陳述","合規經營"],e:"誠實持正原則要求準確陳述、合規及防止賄賂，並明確禁止騷擾、強迫或不當影響客户作決定。"}},
{p:1,ch:"保险业的规管架构",q:"按《操守守则》「胜任提供意见」原则，代理人应？",o:["只跟随公司指标","什么产品都推销","隐瞒知识不足","只推销熟悉的产品并清楚自己知识的局限"],a:3,e:"胜任原则要求代理人具备适当专业知识，只进行自己胜任的受规管活动，并清楚自身局限。",tw:{ch:"保險業的規管架構",q:"按《操守守則》「勝任提供意見」原則，代理人應？",o:["只跟隨公司指標","什麼產品都推銷","隱瞞知識不足","只推銷熟悉的產品並清楚自己知識的侷限"],e:"勝任原則要求代理人具備適當專業知識，只進行自己勝任的受規管活動，並清楚自身侷限。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》的适用对象是？",o:["离岸保单","在香港签发、由香港居民个人作为保单持有人并以私人用途投保的保单","再保合约","所有公司保单"],a:1,e:"守则适用于香港签发、个人为私人用途投保的保单；公司及离岸业务不在其列。",tw:{ch:"保險業的規管架構",q:"《承保商專業守則》的適用對象是？",o:["離岸保單","在香港簽發、由香港居民個人作為保單持有人並以私人用途投保的保單","再保合約","所有公司保單"],e:"守則適用於香港簽發、個人為私人用途投保的保單；公司及離岸業務不在其列。"}},
{p:1,ch:"保险业的规管架构",q:"保监局对问题保险人的「干预权利」不包括？",o:["限制投资种类／地点","委任经理管理","为客户垫付赔款","限制保费收入"],a:2,e:"保监局可限制新业务、保费收入及投资、规定资产由认可受托人保管、委任经理甚至将保险人清盘，但不直接垫付赔款。",tw:{ch:"保險業的規管架構",q:"保監局對問題保險人的「干預權利」不包括？",o:["限制投資種類／地點","委任經理管理","為客户墊付賠款","限制保費收入"],e:"保監局可限制新業務、保費收入及投資、規定資產由認可受託人保管、委任經理甚至將保險人清盤，但不直接墊付賠款。"}},
{p:1,ch:"保险业的规管架构",q:"「适当人选」准则适用于保险公司的哪些人员？",o:["不适用于公司人员","只适用于核保师","只适用于前线销售员","控权人、董事、管控要员及获委任精算师"],a:3,e:"《保险业条例》要求控权人、董事、管控要员及指定精算师均属适当人选，以公司治理保障保单持有人。",tw:{ch:"保險業的規管架構",q:"「適當人選」準則適用於保險公司的哪些人員？",o:["不適用於公司人員","只適用於核保師","只適用於前線銷售員","控權人、董事、管控要員及獲委任精算師"],e:"《保險業條例》要求控權人、董事、管控要員及指定精算師均屬適當人選，以公司治理保障保單持有人。"}},
{p:1,ch:"职业道德及其他有关问题",q:"「骚扰、强迫或不当影响」客户投保，主要违反操守守则的哪项一般原则？",o:["产品知识","资料披露","客户资产","诚实及持正"],a:3,e:"以高压手段促成销售属违反「诚实及持正」原则；客户须在自愿及充分资讯下作决定。",tw:{ch:"職業道德及其他有關問題",q:"「騷擾、強迫或不當影響」客户投保，主要違反操守守則的哪項一般原則？",o:["產品知識","資料披露","客户資產","誠實及持正"],e:"以高壓手段促成銷售屬違反「誠實及持正」原則；客户須在自願及充分資訊下作決定。"}},
{p:1,ch:"职业道德及其他有关问题",q:"按「意见合适性」原则，代理人提供意见时应？",o:["只推荐高佣金产品","确保意见与客户的情况、需要及负担能力匹配","让客户自己决定，不提供意见","统一推荐同一产品"],a:1,e:"意见须基于客户的实际状况度身订造，这正是合适性（Suitability）原则的要求。",tw:{ch:"職業道德及其他有關問題",q:"按「意見合適性」原則，代理人提供意見時應？",o:["只推薦高佣金產品","確保意見與客户的情況、需要及負擔能力匹配","讓客户自己決定，不提供意見","統一推薦同一產品"],e:"意見須基於客户的實際狀況度身訂造，這正是合適性（Suitability）原則的要求。"}},
{p:1,ch:"职业道德及其他有关问题",q:"操守守则要求代理人如何处理「客户的资产」（包括客户交来的保费）？",o:["可与公司资金混同","可先借用","无须纪录","与自己的资金分开处理，并尽快转交保险人"],a:3,e:"「客户的资产」原则要求客户款项与公司资金严格分开、妥善保管并及时转交，保障客户免受挪用风险。",tw:{ch:"職業道德及其他有關問題",q:"操守守則要求代理人如何處理「客户的資產」（包括客户交來的保費）？",o:["可與公司資金混同","可先借用","無須紀錄","與自己的資金分開處理，並儘快轉交保險人"],e:"「客户的資產」原則要求客户款項與公司資金嚴格分開、妥善保管並及時轉交，保障客户免受挪用風險。"}},
{p:1,ch:"职业道德及其他有关问题",q:"向客户提供的说明文件及利益说明，正确做法是？",o:["清晰、准确、不夸大收益并披露重要限制","隐瞒费用","用难以理解的术语","只讲优点"],a:0,e:"准确陈述与资料披露是基本操守；误导性说明可致纪律处分及合约被撤销。",tw:{ch:"職業道德及其他有關問題",q:"向客户提供的說明文件及利益說明，正確做法是？",o:["清晰、準確、不誇大收益並披露重要限制","隱瞞費用","用難以理解的術語","只講優點"],e:"準確陳述與資料披露是基本操守；誤導性說明可致紀律處分及合約被撤銷。"}},
{p:1,ch:"职业道德及其他有关问题",q:"发现客户年纪大、理解能力有限时，代理人应？",o:["更耐心地解释并确保其理解，必要时请家人陪同","省略说明","改让年轻客户投保","加快签约"],a:0,e:"保障弱势客户是「公平行事并以客户最佳利益为重」的体现，尤其须防止对长者的失当销售。",tw:{ch:"職業道德及其他有關問題",q:"發現客户年紀大、理解能力有限時，代理人應？",o:["更耐心地解釋並確保其理解，必要時請家人陪同","省略說明","改讓年輕客户投保","加快簽約"],e:"保障弱勢客户是「公平行事並以客户最佳利益為重」的體現，尤其須防止對長者的失當銷售。"}},
{p:1,ch:"职业道德及其他有关问题",q:"代理人离职或转公司后，对前客户的义务是？",o:["继续保密并妥善移交客户资料及服务","带走客户资料自行联络","立即停止一切接触包括通知","向客户收取转介费"],a:0,e:"离职不解除保密责任；客户资料属公司受信资产，须妥善移交，服务交接亦应以客户利益为先。",tw:{ch:"職業道德及其他有關問題",q:"代理人離職或轉公司後，對前客户的義務是？",o:["繼續保密並妥善移交客户資料及服務","帶走客户資料自行聯絡","立即停止一切接觸包括通知","向客户收取轉介費"],e:"離職不解除保密責任；客户資料屬公司受信資產，須妥善移交，服務交接亦應以客户利益為先。"}},
{p:1,ch:"职业道德及其他有关问题",q:"违反《操守守则》的可能后果是？",o:["被保监局纪律处分（谴责、罚款、停牌或撤牌）","只受公司内部表扬","自动加薪","没有后果"],a:0,e:"违反操守守则可构成纪律处分依据，处罚由谴责至撤销牌照不等，严重者可被刑事检控。",tw:{ch:"職業道德及其他有關問題",q:"違反《操守守則》的可能後果是？",o:["被保監局紀律處分（譴責、罰款、停牌或撤牌）","只受公司內部表揚","自動加薪","沒有後果"],e:"違反操守守則可構成紀律處分依據，處罰由譴責至撤銷牌照不等，嚴重者可被刑事檢控。"}},
{p:1,ch:"职业道德及其他有关问题",q:"「防止贿赂」对保险代理人的要求是？",o:["只限现金才算贿赂","可给客户回扣","不得提供或收受任何不正当利益以影响业务","可收小额礼物"],a:2,e:"《防止贿赂条例》及守则均禁止代理人在业务中提供或收受不正当利益，包括回扣、贵重礼物等。",tw:{ch:"職業道德及其他有關問題",q:"「防止賄賂」對保險代理人的要求是？",o:["只限現金才算賄賂","可給客户回扣","不得提供或收受任何不正當利益以影響業務","可收小額禮物"],e:"《防止賄賂條例》及守則均禁止代理人在業務中提供或收受不正當利益，包括回扣、貴重禮物等。"}},
{p:3,ch:"人寿保险简介",q:"最初（早期）的人寿保险保单有什么特点？",o:["全是投连保单","终身保障","保额极高","有效期较短，为暂时性风险提供保障（如海上航行）"],a:3,e:"寿险最初是短期的，只为暂时性风险提供保障（例如一次海上航行）；后来才发展为长期保障及储蓄工具。",tw:{ch:"人壽保險簡介",q:"最初（早期）的人壽保險保單有什麼特點？",o:["全是投連保單","終身保障","保額極高","有效期較短，為暫時性風險提供保障（如海上航行）"],e:"壽險最初是短期的，只為暫時性風險提供保障（例如一次海上航行）；後來才發展為長期保障及儲蓄工具。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项属于「个人寿险需求」的例子？",o:["写字楼火险","汽车维修","教育经费、退休收入、善终开支","公司购买设备"],a:2,e:"个人寿险需求包括教育经费、残疾收入、偿还按揭、退休收入、受养人生活开支、应急资金及善终开支等。",tw:{ch:"人壽保險簡介",q:"下列哪項屬於「個人壽險需求」的例子？",o:["寫字樓火險","汽車維修","教育經費、退休收入、善終開支","公司購買設備"],e:"個人壽險需求包括教育經費、殘疾收入、償還按揭、退休收入、受養人生活開支、應急資金及善終開支等。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项属于「业务寿险需求」的例子？",o:["家居火险","个人旅游保险","关键人物人寿保险","汽车保险"],a:2,e:"业务寿险需求包括合伙人利益、企业拥有人安排、关键人物保险及雇员福利计划等。",tw:{ch:"人壽保險簡介",q:"下列哪項屬於「業務壽險需求」的例子？",o:["家居火險","個人旅遊保險","關鍵人物人壽保險","汽車保險"],e:"業務壽險需求包括合夥人利益、企業擁有人安排、關鍵人物保險及僱員福利計劃等。"}},
{p:3,ch:"人寿保险简介",q:"父母为未成年（18 岁以下）子女投保人寿保险，其可保利益金额是？",o:["没有可保利益","限于 10 万港元","无限","限于子女学费"],a:2,e:"父母／监护人对未成年子女享有无限可保利益，与对自己及配偶的生命一样。",tw:{ch:"人壽保險簡介",q:"父母為未成年（18 歲以下）子女投保人壽保險，其可保利益金額是？",o:["沒有可保利益","限於 10 萬港元","無限","限於子女學費"],e:"父母／監護人對未成年子女享有無限可保利益，與對自己及配偶的生命一樣。"}},
{p:3,ch:"人寿保险简介",q:"投保人为堂表亲（其他血缘关系）的生命投保，该合约？",o:["只须加保费","技术上无效","视为团体保险","自动有效"],a:1,e:"除自己、配偶及未成年子女外，其他血缘或家庭关系不产生法定可保利益，相关合约在技术上无效。",tw:{ch:"人壽保險簡介",q:"投保人為堂表親（其他血緣關係）的生命投保，該合約？",o:["只須加保費","技術上無效","視為團體保險","自動有效"],e:"除自己、配偶及未成年子女外，其他血緣或家庭關係不產生法定可保利益，相關合約在技術上無效。"}},
{p:3,ch:"人寿保险简介",q:"债权人以债务人的生命投保，其可保利益金额通常为？",o:["贷款额加应计利息","债务人的全部身家","无限","固定 100 万"],a:0,e:"债务人的可保利益以债权额度为限——保额一般等于贷款额加应计利息，防止超额投保。",tw:{ch:"人壽保險簡介",q:"債權人以債務人的生命投保，其可保利益金額通常為？",o:["貸款額加應計利息","債務人的全部身家","無限","固定 100 萬"],e:"債務人的可保利益以債權額度為限——保額一般等於貸款額加應計利息，防止超額投保。"}},
{p:3,ch:"人寿保险简介",q:"人寿保单须注明什么有关可保权益的资料？",o:["享有可保利益的人的姓名／身份及数额","代理人的编号","受益人的职业","投保人的银行账号"],a:0,e:"保单须注明享有可保权益的人的名字及数额，以证明合约非赌博性保单。",tw:{ch:"人壽保險簡介",q:"人壽保單須註明什麼有關可保權益的資料？",o:["享有可保利益的人的姓名／身份及數額","代理人的編號","受益人的職業","投保人的銀行賬號"],e:"保單須註明享有可保權益的人的名字及數額，以證明合約非賭博性保單。"}},
{p:3,ch:"人寿保险简介",q:"人寿保单签发后，下列哪种情况会使保单失效？",o:["保单已转让","债务已偿还","以上皆不会仅因此失效","投保人与受保人离婚"],a:2,e:"可保利益只须在合约开始时存在：离婚后、债务偿还后或保单转让后，保单仍然有效。",tw:{ch:"人壽保險簡介",q:"人壽保單簽發後，下列哪種情況會使保單失效？",o:["保單已轉讓","債務已償還","以上皆不會僅因此失效","投保人與受保人離婚"],e:"可保利益只須在合約開始時存在：離婚後、債務償還後或保單轉讓後，保單仍然有效。"}},
{p:3,ch:"人寿保险简介",q:"为绕开可保权益规定而安排投保（名义投保人代无利益者投保），该合约？",o:["有效","自起保日起无效","只须补交文件","可由中介补签"],a:1,e:"规避可保权益的安排在法律上自始无效——事实上的被保险人（预定承让人）缺乏所需的可保利益。",tw:{ch:"人壽保險簡介",q:"為繞開可保權益規定而安排投保（名義投保人代無利益者投保），該合約？",o:["有效","自起保日起無效","只須補交文件","可由中介補籤"],e:"規避可保權益的安排在法律上自始無效——事實上的被保險人（預定承讓人）缺乏所需的可保利益。"}},
{p:3,ch:"人寿保险简介",q:"「免体检投保」下，若保险人没有要求体检？",o:["保险人难以指称投保人未披露投保单没问到的事项构成不披露","保费加倍","保单自动无效","投保人什么都不用披露"],a:0,e:"未经体检的，保险人很难指控投保人因没披露申请表内未问及的事项而构成不披露重要事实。",tw:{ch:"人壽保險簡介",q:"「免體檢投保」下，若保險人沒有要求體檢？",o:["保險人難以指稱投保人未披露投保單沒問到的事項構成不披露","保費加倍","保單自動無效","投保人什麼都不用披露"],e:"未經體檢的，保險人很難指控投保人因沒披露申請表內未問及的事項而構成不披露重要事實。"}},
{p:3,ch:"人寿保险简介",q:"「要体检投保」下，体检医生诊断错误，保险人可否因此为难投保人？",o:["不可以","可以，双倍收费","可以，一律拒保","由中介决定"],a:0,e:"保险人不能因合资格医务人员在体检中的失职或诊断错误而令投保人承担后果——这是投保人的保障。",tw:{ch:"人壽保險簡介",q:"「要體檢投保」下，體檢醫生診斷錯誤，保險人可否因此為難投保人？",o:["不可以","可以，雙倍收費","可以，一律拒保","由中介決定"],e:"保險人不能因合資格醫務人員在體檢中的失職或診斷錯誤而令投保人承擔後果——這是投保人的保障。"}},
{p:3,ch:"人寿保险简介",q:"投保接受体检时，根据《个人资料（私隐）条例》及良好操守，投保人？",o:["结果须保密不给本人","无权过问","有权知道检查内容、资料用途及检查结果","只可由中介转告"],a:2,e:"体检须遵守私隐条例：测试前解释要求资料的原因，投保人有权了解检查的结果。",tw:{ch:"人壽保險簡介",q:"投保接受體檢時，根據《個人資料（私隱）條例》及良好操守，投保人？",o:["結果須保密不給本人","無權過問","有權知道檢查內容、資料用途及檢查結果","只可由中介轉告"],e:"體檢須遵守私隱條例：測試前解釋要求資料的原因，投保人有權瞭解檢查的結果。"}},
{p:3,ch:"人寿保险简介",q:"毛保费的构成是？",o:["净保费 + 附加保费","只有佣金","只有税项","纯保障成本"],a:0,e:"毛保费 = 净保费（死亡率 + 利息）+ 附加保费（内部营运开支、佣金、税款、应付异常风险等）。",tw:{ch:"人壽保險簡介",q:"毛保費的構成是？",o:["淨保費 + 附加保費","只有佣金","只有税項","純保障成本"],e:"毛保費 = 淨保費（死亡率 + 利息）+ 附加保費（內部營運開支、佣金、税款、應付異常風險等）。"}},
{p:3,ch:"人寿保险简介",q:"「净保费」是指？",o:["税后保费","第一年的保费","正常统计预期下足够支付死亡索偿的金额","扣除佣金后的保费"],a:2,e:"净保费基于死亡率与利息计算，正常预期下足以支付死亡赔付，未含营运开支。",tw:{ch:"人壽保險簡介",q:"「淨保費」是指？",o:["税後保費","第一年的保費","正常統計預期下足夠支付死亡索償的金額","扣除佣金後的保費"],e:"淨保費基於死亡率與利息計算，正常預期下足以支付死亡賠付，未含營運開支。"}},
{p:3,ch:"人寿保险简介",q:"「附加保费」不包括下列哪项？",o:["营运开支及佣金","保额本身","应付异常死亡率或新灾难的准备","税款"],a:1,e:"附加保费涵盖内部营运成本、业务开支、应付异常风险、税款及佣金等；保额本身不属于保费构成元素。",tw:{ch:"人壽保險簡介",q:"「附加保費」不包括下列哪項？",o:["營運開支及佣金","保額本身","應付異常死亡率或新災難的準備","税款"],e:"附加保費涵蓋內部營運成本、業務開支、應付異常風險、税款及佣金等；保額本身不屬於保費構成元素。"}},
{p:3,ch:"人寿保险简介",q:"相同条件下，「分红保单」与「不分红保单」的费率关系是？",o:["不分红较高","完全相同","分红较便宜","分红保单费率较高"],a:3,e:"分红保单除保障外还提供分享盈余的红利，成本较高，故费率一般高于不分红保单。",tw:{ch:"人壽保險簡介",q:"相同條件下，「分紅保單」與「不分紅保單」的費率關係是？",o:["不分紅較高","完全相同","分紅較便宜","分紅保單費率較高"],e:"分紅保單除保障外還提供分享盈餘的紅利，成本較高，故費率一般高於不分紅保單。"}},
{p:3,ch:"人寿保险简介",q:"「自然保费制」的缺点包括？",o:["晚年保费高昂致续保率下降、出现逆选择、风险不平衡","不受规管","保费太低","没有现金价值"],a:0,e:"自然保费随年龄递增，易因负担不起而断保（留下高风险者，逆选择），现已没有保险人实行；现行均为均衡保费制。",tw:{ch:"人壽保險簡介",q:"「自然保費制」的缺點包括？",o:["晚年保費高昂致續保率下降、出現逆選擇、風險不平衡","不受規管","保費太低","沒有現金價值"],e:"自然保費隨年齡遞增，易因負擔不起而斷保（留下高風險者，逆選擇），現已沒有保險人實行；現行均為均衡保費制。"}},
{p:3,ch:"人寿保险简介",q:"均衡保费制下，早期「超额」保费的去向是？",o:["作为佣金","连利息形成基金或储备，累积成现金价值","退还给投保人","上缴保监局"],a:1,e:"早期缴付高于当年保障成本的保费，连同利息累积成储备，形成现金价值——这是保单贷款、不能作废条款等安排的基础。",tw:{ch:"人壽保險簡介",q:"均衡保費制下，早期「超額」保費的去向是？",o:["作為佣金","連利息形成基金或儲備，累積成現金價值","退還給投保人","上繳保監局"],e:"早期繳付高於當年保障成本的保費，連同利息累積成儲備，形成現金價值——這是保單貸款、不能作廢條款等安排的基礎。"}},
{p:3,ch:"人寿保险及年金的种类",q:"定期寿险的一般特点是？",o:["通常不分红、没有现金价值","必定分红","只限终身","一定有现金价值"],a:0,e:"定期寿险是纯保障产品，通常不分红、期满无任何给付、没有现金价值，故保费最低廉。",tw:{ch:"人壽保險及年金的種類",q:"定期壽險的一般特點是？",o:["通常不分紅、沒有現金價值","必定分紅","只限終身","一定有現金價值"],e:"定期壽險是純保障產品，通常不分紅、期滿無任何給付、沒有現金價值，故保費最低廉。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「信用寿险」（Credit Life Insurance）的运作是？",o:["借款人在欠款还清前死亡，保险金直接向贷款人支付贷款余额","向借款人支付双倍","属年金","只保贷款机构员工"],a:0,e:"信用寿险以借款人生命为标的，死亡时保险金直接付给贷款机构偿还余额，通常以集体形式售予贷款机构。",tw:{ch:"人壽保險及年金的種類",q:"「信用壽險」（Credit Life Insurance）的運作是？",o:["借款人在欠款還清前死亡，保險金直接向貸款人支付貸款餘額","向借款人支付雙倍","屬年金","只保貸款機構員工"],e:"信用壽險以借款人生命為標的，死亡時保險金直接付給貸款機構償還餘額，通常以集體形式售予貸款機構。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「家庭收入寿险」的给付方式是？",o:["于指定期限剩余期间按月向受益人给付，总支付金额随时间递减","按月递增","一次性给付","只于期满给付"],a:0,e:"家庭收入寿险承诺于指定期内每月支付指定金额予受益人，随月份过去总给付额递减，功能类似递减定期寿。",tw:{ch:"人壽保險及年金的種類",q:"「家庭收入壽險」的給付方式是？",o:["於指定期限剩餘期間按月向受益人給付，總支付金額隨時間遞減","按月遞增","一次性給付","只於期滿給付"],e:"家庭收入壽險承諾於指定期內每月支付指定金額予受益人，隨月份過去總給付額遞減，功能類似遞減定期壽。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「抵押赎回保险」（Mortgage Redemption Insurance）的特点是？",o:["属医疗险","只保一名借款人","期满双倍给付","常以联合寿险方式订立，于首名受保人死亡时给付与贷款余额相符的保额"],a:3,e:"抵押赎回保险保额与按揭贷款余额同步递减，多以夫妻联合寿险订立，首名受保人死亡即获给付，保障按揭人利益。",tw:{ch:"人壽保險及年金的種類",q:"「抵押贖回保險」（Mortgage Redemption Insurance）的特點是？",o:["屬醫療險","只保一名借款人","期滿雙倍給付","常以聯合壽險方式訂立，於首名受保人死亡時給付與貸款餘額相符的保額"],e:"抵押贖回保險保額與按揭貸款餘額同步遞減，多以夫妻聯合壽險訂立，首名受保人死亡即獲給付，保障按揭人利益。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「递增定期寿险」的保额递增方式可以是？",o:["只按银行利率","按固定百分比或按综合消费物价指数递增","固定不变","逐年递减"],a:1,e:"递增定期寿险使保额维持购买力：可按固定百分比或挂钩综合消费物价指数递增，保费亦按比例增加。",tw:{ch:"人壽保險及年金的種類",q:"「遞增定期壽險」的保額遞增方式可以是？",o:["只按銀行利率","按固定百分比或按綜合消費物價指數遞增","固定不變","逐年遞減"],e:"遞增定期壽險使保額維持購買力：可按固定百分比或掛鈎綜合消費物價指數遞增，保費亦按比例增加。"}},
{p:3,ch:"人寿保险及年金的种类",q:"可续保定期寿险续保时的保费按什么计算？",o:["到达年龄（续保时的年龄）","固定不变","统一费率","原投保年龄"],a:0,e:"续保无须可保证明，但新保费按续保时到达年龄厘定，故随年龄递增。",tw:{ch:"人壽保險及年金的種類",q:"可續保定期壽險續保時的保費按什麼計算？",o:["到達年齡（續保時的年齡）","固定不變","統一費率","原投保年齡"],e:"續保無須可保證明，但新保費按續保時到達年齡釐定，故隨年齡遞增。"}},
{p:3,ch:"人寿保险及年金的种类",q:"为防范逆选择，可续保条款的常见限制不包括？",o:["费率高于不可续保保单","续保保额不超过原保额","限制续保次数（如三次）","保证无限次续保且费率不变"],a:3,e:"可续保权通常设保额上限、次数上限，费率亦高于不可续保保单；不存在保证无限次续保且费率不变的安排。",tw:{ch:"人壽保險及年金的種類",q:"為防範逆選擇，可續保條款的常見限制不包括？",o:["費率高於不可續保保單","續保保額不超過原保額","限制續保次數（如三次）","保證無限次續保且費率不變"],e:"可續保權通常設保額上限、次數上限，費率亦高於不可續保保單；不存在保證無限次續保且費率不變的安排。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「可转换定期寿险」可转换为？",o:["永久计划（如终身寿险）","年金","汽车保险","医疗附约"],a:0,e:"可转换权让投保人把定期保单转为终身等永久计划，无须可保证明，新保费按到达年龄计算。",tw:{ch:"人壽保險及年金的種類",q:"「可轉換定期壽險」可轉換為？",o:["永久計劃（如終身壽險）","年金","汽車保險","醫療附約"],e:"可轉換權讓投保人把定期保單轉為終身等永久計劃，無須可保證明，新保費按到達年齡計算。"}},
{p:3,ch:"人寿保险及年金的种类",q:"可转换条款的常见限制不包括？",o:["永久计划的保额不超过原定期保额","可随时无限额转换","保单生效一段期间后不可转换","超过某年龄（如 55 或 65 岁）不可转换"],a:1,e:"为防逆选择，转换设年龄上限、生效期上限及保额上限；并非随时无限额转换。",tw:{ch:"人壽保險及年金的種類",q:"可轉換條款的常見限制不包括？",o:["永久計劃的保額不超過原定期保額","可隨時無限額轉換","保單生效一段期間後不可轉換","超過某年齡（如 55 或 65 歲）不可轉換"],e:"為防逆選擇，轉換設年齡上限、生效期上限及保額上限；並非隨時無限額轉換。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险（两全保险）在构成上等于？",o:["定期寿险 + 纯生存保险","万用寿险 + 投连","意外 + 医疗","终身寿险 + 年金"],a:0,e:"储蓄寿险 = 定期寿险（期内死亡给付）+ 纯生存保险（期满生存给付）的结合。",tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險（兩全保險）在構成上等於？",o:["定期壽險 + 純生存保險","萬用壽險 + 投連","意外 + 醫療","終身壽險 + 年金"],e:"儲蓄壽險 = 定期壽險（期內死亡給付）+ 純生存保險（期滿生存給付）的結合。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险在香港不太流行的主因是？",o:["不受规管","保费相对昂贵","不可指定受益人","没有保障功能"],a:1,e:"储蓄寿险结合保障与储蓄、保费不低，消费者多选择「定期寿＋独立储蓄/投资」的组合，故香港不太流行。",tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險在香港不太流行的主因是？",o:["不受規管","保費相對昂貴","不可指定受益人","沒有保障功能"],e:"儲蓄壽險結合保障與儲蓄、保費不低，消費者多選擇「定期壽＋獨立儲蓄/投資」的組合，故香港不太流行。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险中，受保人活到生命表上的最高龄（如 99 或 100 岁）时？",o:["保险人支付保额，合约终止","保费加倍","转为年金","保单失效"],a:0,e:"精算上视为「死亡」：受保人达生命表最高龄时保险人支付保额、合约终止，保费即按此精算定价。",tw:{ch:"人壽保險及年金的種類",q:"終身壽險中，受保人活到生命表上的最高齡（如 99 或 100 歲）時？",o:["保險人支付保額，合約終止","保費加倍","轉為年金","保單失效"],e:"精算上視為「死亡」：受保人達生命表最高齡時保險人支付保額、合約終止，保費即按此精算定價。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「纯粹寿险单」（Straight Life Policy）指？",o:["趸缴终身寿","只保一年的定期险","投连保单","终身缴付保费的终身寿险"],a:3,e:"终身缴付（连续缴费）的终身寿险称为纯粹寿险单；相对的是限期缴费终身寿险。",tw:{ch:"人壽保險及年金的種類",q:"「純粹壽險單」（Straight Life Policy）指？",o:["躉繳終身壽","只保一年的定期險","投連保單","終身繳付保費的終身壽險"],e:"終身繳付（連續繳費）的終身壽險稱為純粹壽險單；相對的是限期繳費終身壽險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「等级保费保单」（Graded Premium Policy）的保费模式是？",o:["逐年递减","保费固定","趸缴","固定保额，保费定期（如每 3 年）递增，直至达至均衡保费水平"],a:3,e:"等级保费保单初期保费较低，定期递增，最终达到余下保险期的均衡保费水平，迎合收入渐长的投保人。",tw:{ch:"人壽保險及年金的種類",q:"「等級保費保單」（Graded Premium Policy）的保費模式是？",o:["逐年遞減","保費固定","躉繳","固定保額，保費定期（如每 3 年）遞增，直至達至均衡保費水平"],e:"等級保費保單初期保費較低，定期遞增，最終達到餘下保險期的均衡保費水平，迎合收入漸長的投保人。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险保单所有人可选择的「死亡保险金」形式包括？",o:["只有现金价值","由受益人决定","只有保额","保额（定额）或 保额 + 现金价值"],a:3,e:"万用寿险提供死亡保险金选择：定额（level）或递增（保额加现金价值），影响保费与现金价值的运作。",tw:{ch:"人壽保險及年金的種類",q:"萬用壽險保單所有人可選擇的「死亡保險金」形式包括？",o:["只有現金價值","由受益人決定","只有保額","保額（定額）或 保額 + 現金價值"],e:"萬用壽險提供死亡保險金選擇：定額（level）或遞增（保額加現金價值），影響保費與現金價值的運作。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投连保单中保费的运用方式是？",o:["购买黄金","全数存入银行","全部或部分保费以当时基金价格购入基金单位","缴付税款"],a:2,e:"投连保单的全部或部分保费会按当时基金价格购入单位，保单价值随单位价格升跌。",tw:{ch:"人壽保險及年金的種類",q:"投連保單中保費的運用方式是？",o:["購買黃金","全數存入銀行","全部或部分保費以當時基金價格購入基金單位","繳付税款"],e:"投連保單的全部或部分保費會按當時基金價格購入單位，保單價值隨單位價格升跌。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投连保单最常见的保单类型是？",o:["汽车保险","医疗保险","终身寿险及储蓄寿险","定期寿险"],a:2,e:"任何类型的寿险都可以是投连形式，最常见的是终身寿险及储蓄寿险。",tw:{ch:"人壽保險及年金的種類",q:"投連保單最常見的保單類型是？",o:["汽車保險","醫療保險","終身壽險及儲蓄壽險","定期壽險"],e:"任何類型的壽險都可以是投連形式，最常見的是終身壽險及儲蓄壽險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"即期年金的给付由何时开始？",o:["购后立即","一年后","年金购买后的第一个年金期完结时","退休年龄"],a:2,e:"即期年金（趸缴购买）于第一个年金期（如一个月）完结时开始给付，而非购买当日。",tw:{ch:"人壽保險及年金的種類",q:"即期年金的給付由何時開始？",o:["購後立即","一年後","年金購買後的第一個年金期完結時","退休年齡"],e:"即期年金（躉繳購買）於第一個年金期（如一個月）完結時開始給付，而非購買當日。"}},
{p:3,ch:"人寿保险及年金的种类",q:"延期年金包括哪两个阶段？",o:["累积期及年金期","等候期及观察期","冷静期及复效期","缴费期及宽限期"],a:0,e:"延期年金先有累积期（定期供款并投资增值），累积期完结后进入年金期（定期领取年金）。",tw:{ch:"人壽保險及年金的種類",q:"延期年金包括哪兩個階段？",o:["累積期及年金期","等候期及觀察期","冷靜期及復效期","繳費期及寬限期"],e:"延期年金先有累積期（定期供款並投資增值），累積期完結後進入年金期（定期領取年金）。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「确定年金」（Annuity Certain）指？",o:["视乎投资表现","仅于规定年期内支付年金，不论领取人生死","终身支付","只支付一次"],a:1,e:"确定年金于固定年期（N 年）内支付，期满即停，与领取人生死无关。",tw:{ch:"人壽保險及年金的種類",q:"「確定年金」（Annuity Certain）指？",o:["視乎投資表現","僅於規定年期內支付年金，不論領取人生死","終身支付","只支付一次"],e:"確定年金於固定年期（N 年）內支付，期滿即停，與領取人生死無關。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「确定期间终身年金」（有保证期的终身年金）的给付方式是？",o:["至少于指定年期内支付；领取人活过该年期则继续给付至身故","按投资表现","只付一年","只付 N 年"],a:0,e:"此类年金结合保证期与终身保障：保证期内不论生死照付，活过保证期后则终身给付（给付总额 ≥ N 年）。",tw:{ch:"人壽保險及年金的種類",q:"「確定期間終身年金」（有保證期的終身年金）的給付方式是？",o:["至少於指定年期內支付；領取人活過該年期則繼續給付至身故","按投資表現","只付一年","只付 N 年"],e:"此類年金結合保證期與終身保障：保證期內不論生死照付，活過保證期後則終身給付（給付總額 ≥ N 年）。"}},
{p:3,ch:"人寿保险及年金的种类",q:"退休金方面，政府机构与非政府机构的给付形式分别是？",o:["两者均一次过","政府一次过；非政府按月","两者均按月","政府通常按月给付；非政府机构多为公积金计划一次过支付"],a:3,e:"政府公务员退休金按月给付至去世；非政府机构多为公积金（一次过整笔）计划。强积金制度于 2000 年 12 月开始实施。",tw:{ch:"人壽保險及年金的種類",q:"退休金方面，政府機構與非政府機構的給付形式分別是？",o:["兩者均一次過","政府一次過；非政府按月","兩者均按月","政府通常按月給付；非政府機構多為公積金計劃一次過支付"],e:"政府公務員退休金按月給付至去世；非政府機構多為公積金（一次過整筆）計劃。強積金制度於 2000 年 12 月開始實施。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「合资格团体」投保团体人寿保险包括？",o:["只限政府机构","只限上市公司","任何临时聚会","单一雇主、非为买保险而成立的组织团体、多个雇主的团体"],a:3,e:"合资格团体包括单一雇主、非为投保而成立的组织团体（工会/协会等）及多雇主团体；须有一定组织基础以防逆选择。",tw:{ch:"人壽保險及年金的種類",q:"「合資格團體」投保團體人壽保險包括？",o:["只限政府機構","只限上市公司","任何臨時聚會","單一僱主、非為買保險而成立的組織團體、多個僱主的團體"],e:"合資格團體包括單一僱主、非為投保而成立的組織團體（工會/協會等）及多僱主團體；須有一定組織基礎以防逆選擇。"}},
{p:3,ch:"人寿保险及年金的种类",q:"团体保险计划按保费来源分为？",o:["只限供款","由中介供款","只限非供款","供款计划（成员分担保费）及非供款计划（成员无须供款）"],a:3,e:"供款计划由雇主与成员分担保费；非供款计划保费全由团体保单持有人承担，成员免费受保。",tw:{ch:"人壽保險及年金的種類",q:"團體保險計劃按保費來源分為？",o:["只限供款","由中介供款","只限非供款","供款計劃（成員分擔保費）及非供款計劃（成員無須供款）"],e:"供款計劃由僱主與成員分擔保費；非供款計劃保費全由團體保單持有人承擔，成員免費受保。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「附约」（Rider／附加条款）对主保单的作用是？",o:["只供记录","扩展或限制合约应付的利益","取代主保单","令保单失效"],a:1,e:"附约依附主保单运作，用于加入额外保障（如危疾、豁免保费）或附加限制；用于免除责任的附约称豁免承保附约。",tw:{ch:"保險利益附約及其他產品",q:"「附約」（Rider／附加條款）對主保單的作用是？",o:["只供記錄","擴展或限制合約應付的利益","取代主保單","令保單失效"],e:"附約依附主保單運作，用於加入額外保障（如危疾、豁免保費）或附加限制；用於免除責任的附約稱豁免承保附約。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「残疾豁免保费」附约的等候期（起赔期间）通常为？",o:["十年","一年","三或六个月","没有等候期"],a:2,e:"豁免保费附约多设三至六个月等候期：完全伤残持续逾等候期后，保险人放弃收取续保保费。",tw:{ch:"保險利益附約及其他產品",q:"「殘疾豁免保費」附約的等候期（起賠期間）通常為？",o:["十年","一年","三或六個月","沒有等候期"],e:"豁免保費附約多設三至六個月等候期：完全傷殘持續逾等候期後，保險人放棄收取續保保費。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「残疾豁免保费」附约生效期间，主保单？",o:["继续有效并继续产生现金价值及红利","保额减半","即时失效","转为定期"],a:0,e:"豁免保费只免去缴费，保障维持不变——保单仍累积现金价值及（分红保单的）红利。",tw:{ch:"保險利益附約及其他產品",q:"「殘疾豁免保費」附約生效期間，主保單？",o:["繼續有效並繼續產生現金價值及紅利","保額減半","即時失效","轉為定期"],e:"豁免保費只免去繳費，保障維持不變——保單仍累積現金價值及（分紅保單的）紅利。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「残疾豁免保费」附约常见的年龄限制是？",o:["只限 18 岁","15 至 65 岁","0 至 100 岁","只限 60 岁以上"],a:1,e:"常见承保年龄为 15-65 岁；部分保单还规定残疾期间不得变更保费缴付频率，或须转为按月缴付。",tw:{ch:"保險利益附約及其他產品",q:"「殘疾豁免保費」附約常見的年齡限制是？",o:["只限 18 歲","15 至 65 歲","0 至 100 歲","只限 60 歲以上"],e:"常見承保年齡為 15-65 歲；部分保單還規定殘疾期間不得變更保費繳付頻率，或須轉為按月繳付。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「残疾收入」附约的等候期通常为？",o:["一年","十年","五年","一个月至六个月"],a:3,e:"残疾收入附约等候期一般一至六个月，短于豁免保费的等候期。",tw:{ch:"保險利益附約及其他產品",q:"「殘疾收入」附約的等候期通常為？",o:["一年","十年","五年","一個月至六個月"],e:"殘疾收入附約等候期一般一至六個月，短於豁免保費的等候期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「残疾收入」附约的给付金额可如何厘定？",o:["按保额","随意","定额或与伤残前收入挂钩的公式","按保费"],a:2,e:"给付可按固定金额，或按伤残前收入的某个百分比扣减其他伤残收入后厘定；并非贷款或预缴保费。",tw:{ch:"保險利益附約及其他產品",q:"「殘疾收入」附約的給付金額可如何釐定？",o:["按保額","隨意","定額或與傷殘前收入掛鈎的公式","按保費"],e:"給付可按固定金額，或按傷殘前收入的某個百分比扣減其他傷殘收入後釐定；並非貸款或預繳保費。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「残疾收入」附约的性质，正确的是？",o:["是向保险人的借款","是预缴保费","是退保金","属于收入保障给付，并非贷款或预缴保费"],a:3,e:"残疾收入是在完全伤残期间提供收入，保单同时维持完全有效；若期间死亡，仍按基本保单保额给付。",tw:{ch:"保險利益附約及其他產品",q:"「殘疾收入」附約的性質，正確的是？",o:["是向保險人的借款","是預繳保費","是退保金","屬於收入保障給付，並非貸款或預繳保費"],e:"殘疾收入是在完全傷殘期間提供收入，保單同時維持完全有效；若期間死亡，仍按基本保單保額給付。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾相关附约的常见除外责任不包括？",o:["从事违法活动导致伤残","保单生效前已患的疾病","蓄意自伤","感冒发烧"],a:3,e:"常见除外包括自伤、违法活动、既有疾病及战争时服兵役所致伤残；普通小病并非除外责任的典型例子。",tw:{ch:"保險利益附約及其他產品",q:"殘疾相關附約的常見除外責任不包括？",o:["從事違法活動導致傷殘","保單生效前已患的疾病","蓄意自傷","感冒發燒"],e:"常見除外包括自傷、違法活動、既有疾病及戰爭時服兵役所致傷殘；普通小病並非除外責任的典型例子。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「意外死亡及丧失肢体」（AD&D）附约对同一次意外事故？",o:["视乎保费","不会同时支付意外死亡及丧失肢体两项利益","三倍支付","双倍同时支付"],a:1,e:"同一次意外不会同时获意外死亡与丧失肢体两项给付；丧失两肢或双目失明一般按意外死亡金额给付。",tw:{ch:"保險利益附約及其他產品",q:"「意外死亡及喪失肢體」（AD&D）附約對同一次意外事故？",o:["視乎保費","不會同時支付意外死亡及喪失肢體兩項利益","三倍支付","雙倍同時支付"],e:"同一次意外不會同時獲意外死亡與喪失肢體兩項給付；喪失兩肢或雙目失明一般按意外死亡金額給付。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「双倍赔」（Double Indemnity）指？",o:["保费双倍","任何死亡双倍","保额双倍缴费","意外死亡时额外支付一笔相等于基本保额的利益"],a:3,e:"意外死亡附约（双倍赔利益）于意外死亡时额外给付相等于基本保额的金额，合共双倍。",tw:{ch:"保險利益附約及其他產品",q:"「雙倍賠」（Double Indemnity）指？",o:["保費雙倍","任何死亡雙倍","保額雙倍繳費","意外死亡時額外支付一筆相等於基本保額的利益"],e:"意外死亡附約（雙倍賠利益）於意外死亡時額外給付相等於基本保額的金額，合共雙倍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡附约要求死亡必须？",o:["只限疾病","十年后亦可","由意外身体受伤直接引起，并与所有其他原因无关，且于受伤后一年内发生","任何原因"],a:2,e:"意外死亡须为意外受伤的直接结果、排除其他原因，并通常在受伤一年内发生，以防争议。",tw:{ch:"保險利益附約及其他產品",q:"意外死亡附約要求死亡必須？",o:["只限疾病","十年後亦可","由意外身體受傷直接引起，並與所有其他原因無關，且於受傷後一年內發生","任何原因"],e:"意外死亡須為意外受傷的直接結果、排除其他原因，並通常在受傷一年內發生，以防爭議。"}},
{p:3,ch:"保险利益附约及其他产品",q:"AD&D 附约的「航空」除外责任，常见例外是？",o:["私人飞机驾驶","购票乘客乘坐商业航班","热气球","特技飞行"],a:1,e:"航空活动（如私人飞行、特技飞行）一般除外，但购买机票的商业航班乘客通常受保。",tw:{ch:"保險利益附約及其他產品",q:"AD&D 附約的「航空」除外責任，常見例外是？",o:["私人飛機駕駛","購票乘客乘坐商業航班","熱氣球","特技飛行"],e:"航空活動（如私人飛行、特技飛行）一般除外，但購買機票的商業航班乘客通常受保。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「提前支付死亡保险金」（生前给付）附约通常适用于？",o:["大额保单","只限年金","只限儿童","任何小额保单"],a:0,e:"生前给付多设于大额保单：受保人处于订明严重情况（即使仍在生）可提前获付，金额从日后死亡保险金扣除。",tw:{ch:"保險利益附約及其他產品",q:"「提前支付死亡保險金」（生前給付）附約通常適用於？",o:["大額保單","只限年金","只限兒童","任何小額保單"],e:"生前給付多設於大額保單：受保人處於訂明嚴重情況（即使仍在生）可提前獲付，金額從日後死亡保險金扣除。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾附约中的「终末疾病」通常指？",o:["慢性病","感冒","轻伤","确诊后预期寿命不超过 12 个月的疾病"],a:3,e:"终末疾病指主诊医生证实寿命不超过 12 个月的疾病，属危疾附约的给付情形之一。",tw:{ch:"保險利益附約及其他產品",q:"危疾附約中的「終末疾病」通常指？",o:["慢性病","感冒","輕傷","確診後預期壽命不超過 12 個月的疾病"],e:"終末疾病指主診醫生證實壽命不超過 12 個月的疾病，屬危疾附約的給付情形之一。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「长期护理」附约的给付条件一般包括？",o:["失业","退休","住院一晚","医生证明已失去指定数目的日常生活活动能力"],a:3,e:"长期护理附约须医生证明受保人因疾病失去指定数目的 ADLs，并通常设有 90 日等候期及保单生效满一年的要求。",tw:{ch:"保險利益附約及其他產品",q:"「長期護理」附約的給付條件一般包括？",o:["失業","退休","住院一晚","醫生證明已失去指定數目的日常生活活動能力"],e:"長期護理附約須醫生證明受保人因疾病失去指定數目的 ADLs，並通常設有 90 日等候期及保單生效滿一年的要求。"}},
{p:3,ch:"保险利益附约及其他产品",q:"医疗附约（住院及手术）的「基本计划」一般不包括？",o:["门诊病人的跟进护理","私家护理","身故抚恤金","住院费用及手术费用"],a:2,e:"基本计划涵盖住院、私家护理、外科医生/麻醉师/手术室、住院内外科医生及门诊跟进等；身故抚恤金属寿险范畴。",tw:{ch:"保險利益附約及其他產品",q:"醫療附約（住院及手術）的「基本計劃」一般不包括？",o:["門診病人的跟進護理","私家護理","身故撫卹金","住院費用及手術費用"],e:"基本計劃涵蓋住院、私家護理、外科醫生/麻醉師/手術室、住院內外科醫生及門診跟進等；身故撫卹金屬壽險範疇。"}},
{p:3,ch:"保险利益附约及其他产品",q:"医疗附约的「自选医疗计划」提供什么？",o:["免费保障","终身保证续保","寿险保障","缴额外保费以提升基本计划各分项的保障限额"],a:3,e:"自选计划以额外保费换取基本计划各保障项目更高的赔偿限额，属加购式安排。",tw:{ch:"保險利益附約及其他產品",q:"醫療附約的「自選醫療計劃」提供什麼？",o:["免費保障","終身保證續保","壽險保障","繳額外保費以提升基本計劃各分項的保障限額"],e:"自選計劃以額外保費換取基本計劃各保障項目更高的賠償限額，屬加購式安排。"}},
{p:3,ch:"保险利益附约及其他产品",q:"医疗附约的主要除外责任不包括？",o:["保单生效前已患的疾病","涉及吸毒、自伤或性接触传染的疾病","普通伤风门诊","与怀孕及生育有关的开支"],a:2,e:"常见除外包括既有疾病、怀孕生育、滥用药物/自伤/性病、艾滋病相关症状（保单首数年）及先天性畸形治疗。",tw:{ch:"保險利益附約及其他產品",q:"醫療附約的主要除外責任不包括？",o:["保單生效前已患的疾病","涉及吸毒、自傷或性接觸傳染的疾病","普通傷風門診","與懷孕及生育有關的開支"],e:"常見除外包括既有疾病、懷孕生育、濫用藥物/自傷/性病、艾滋病相關症狀（保單首數年）及先天性畸形治療。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「自愿医保计划」（VHIS）的「认可产品」由谁认可？",o:["政府（食物及卫生局／医务卫生局）","保监局","保险公司自行认可","保险业联会"],a:0,e:"自愿医保由政府部门认可，旨在提升个人住院保险的质素与透明度，方便市民使用私营医疗服务。",tw:{ch:"保險利益附約及其他產品",q:"「自願醫保計劃」（VHIS）的「認可產品」由誰認可？",o:["政府（食物及衞生局／醫務衞生局）","保監局","保險公司自行認可","保險業聯會"],e:"自願醫保由政府部門認可，旨在提升個人住院保險的質素與透明度，方便市民使用私營醫療服務。"}},
{p:3,ch:"保险利益附约及其他产品",q:"自愿医保保费的税务扣除规定是？",o:["只限配偶一人","每名受保人每年上限 8,000 元，可申请扣减的指明亲属人数不设上限","不可扣税","无限额"],a:1,e:"纳税人为本人或指明亲属（配偶、子女、双方祖父母/父母/兄弟姐妹等）缴付的认可产品保费可扣税：每人每年 8,000 元上限，亲属人数不限。",tw:{ch:"保險利益附約及其他產品",q:"自願醫保保費的税務扣除規定是？",o:["只限配偶一人","每名受保人每年上限 8,000 元，可申請扣減的指明親屬人數不設上限","不可扣税","無限額"],e:"納税人為本人或指明親屬（配偶、子女、雙方祖父母/父母/兄弟姐妹等）繳付的認可產品保費可扣税：每人每年 8,000 元上限，親屬人數不限。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「保证可保利益」（GI）附约的行权时点包括？",o:["只限周年日","只限退休","任何时候无限额","指定日期／年龄，或结婚、子女出生等指定事件"],a:3,e:"GI 允许于指定备择日期、指定年龄或人生事件（结婚、子女出生）时增购保险而无须可保证明，增额不超过原面额并可能限 40 岁前行使。",tw:{ch:"保險利益附約及其他產品",q:"「保證可保利益」（GI）附約的行權時點包括？",o:["只限週年日","只限退休","任何時候無限額","指定日期／年齡，或結婚、子女出生等指定事件"],e:"GI 允許於指定備擇日期、指定年齡或人生事件（結婚、子女出生）時增購保險而無須可保證明，增額不超過原面額並可能限 40 歲前行使。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「生活指数调整」（COLA）附约适用于？",o:["为残疾的受保保单所有人提供与独立指数挂钩的定期递增收入","只适用车险","提高身故保额","降低保费"],a:0,e:"COLA 为残疾收入提供与消费物价指数等挂钩的定期增幅，应对通胀；只升不跌（不涉及通缩下调）。",tw:{ch:"保險利益附約及其他產品",q:"「生活指數調整」（COLA）附約適用於？",o:["為殘疾的受保保單所有人提供與獨立指數掛鈎的定期遞增收入","只適用車險","提高身故保額","降低保費"],e:"COLA 為殘疾收入提供與消費物價指數等掛鈎的定期增幅，應對通脹；只升不跌（不涉及通縮下調）。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单的「完整合约」包括？",o:["口头承诺","保险单 + 附约 + 投保单复印本","只有保险单","只有投保单"],a:1,e:"完整合约 = 保单 + 附约 + 投保单复印本，属封闭式合约：仅保险人指定的高级职员有权更改，修改须书面作出。",tw:{ch:"闡釋人壽保險單",q:"人壽保單的「完整合約」包括？",o:["口頭承諾","保險單 + 附約 + 投保單複印本","只有保險單","只有投保單"],e:"完整合約 = 保單 + 附約 + 投保單複印本，屬封閉式合約：僅保險人指定的高級職員有權更改，修改須書面作出。"}},
{p:3,ch:"阐释人寿保险单",q:"香港人寿保单与一般保单在风格上的分别是？",o:["人寿用英式；一般保险用美式","完全相同","人寿保单倾向美式（北美）风格；一般保险多用源自英国的保单方式","均由政府统一"],a:2,e:"香港寿险市场多采用美式保单条款风格，一般保险则承袭英式传统，考试常作区分。",tw:{ch:"闡釋人壽保險單",q:"香港人壽保單與一般保單在風格上的分別是？",o:["人壽用英式；一般保險用美式","完全相同","人壽保單傾向美式（北美）風格；一般保險多用源自英國的保單方式","均由政府統一"],e:"香港壽險市場多采用美式保單條款風格，一般保險則承襲英式傳統，考試常作區分。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险索偿时必须出示什么？",o:["保单正本","名片","投保单副本","收据即可"],a:0,e:"人寿索偿须出示保单正本（故保单文件须妥善保管），这是一般保险索偿通常没有的严格要求。",tw:{ch:"闡釋人壽保險單",q:"人壽保險索償時必須出示什麼？",o:["保單正本","名片","投保單副本","收據即可"],e:"人壽索償須出示保單正本（故保單文件須妥善保管），這是一般保險索償通常沒有的嚴格要求。"}},
{p:3,ch:"阐释人寿保险单",q:"宽限期不适用于？",o:["年缴保费","月缴保费","续期保费","保单的首期保费"],a:3,e:"宽限期适用于到期续保保费；首期保费必须在保单生效前缴清，不设宽限。",tw:{ch:"闡釋人壽保險單",q:"寬限期不適用於？",o:["年繳保費","月繳保費","續期保費","保單的首期保費"],e:"寬限期適用於到期續保保費；首期保費必須在保單生效前繳清，不設寬限。"}},
{p:3,ch:"阐释人寿保险单",q:"宽限期内缴付的保费被视为？",o:["逾期缴付","双倍缴付","无效缴付","准时缴付"],a:3,e:"宽限期是「缓冲」而非免费期：期内缴款视同准时，保障持续。",tw:{ch:"闡釋人壽保險單",q:"寬限期內繳付的保費被視為？",o:["逾期繳付","雙倍繳付","無效繳付","準時繳付"],e:"寬限期是「緩衝」而非免費期：期內繳款視同準時，保障持續。"}},
{p:3,ch:"阐释人寿保险单",q:"「宽限期并非免费保险期」的意思是？",o:["期内无须缴费","宽限期内保单生效但欠缴的保费仍须补缴","期内保额加倍","期内免费受保"],a:1,e:"宽限期只是延迟缴费的容忍期，欠缴保费终究要补；并非毋须缴费的保障期。",tw:{ch:"闡釋人壽保險單",q:"「寬限期並非免費保險期」的意思是？",o:["期內無須繳費","寬限期內保單生效但欠繳的保費仍須補繳","期內保額加倍","期內免費受保"],e:"寬限期只是延遲繳費的容忍期，欠繳保費終究要補；並非毋須繳費的保障期。"}},
{p:3,ch:"阐释人寿保险单",q:"宽限期届满仍未缴费，英式保单与美式保单的失效时点分别是？",o:["两者均由到期日失效","两者均宽限届满失效","英式：由保费到期日起失效；美式：宽限期届满时失效","英式宽限届满失效，美式到期日失效"],a:2,e:"英式保单由保费到期日开始失效，美式保单则维持有效至宽限期届满，这是两种保单风格的分别。",tw:{ch:"闡釋人壽保險單",q:"寬限期屆滿仍未繳費，英式保單與美式保單的失效時點分別是？",o:["兩者均由到期日失效","兩者均寬限屆滿失效","英式：由保費到期日起失效；美式：寬限期屆滿時失效","英式寬限屆滿失效，美式到期日失效"],e:"英式保單由保費到期日開始失效，美式保單則維持有效至寬限期屆滿，這是兩種保單風格的分別。"}},
{p:3,ch:"阐释人寿保险单",q:"「概括式指定」受益人的例子是？",o:["指名公司","指名张三","指定「我的子女」","指名配偶姓名"],a:2,e:"概括式指定以类别描述受益人（如「我的子女」），成员以受保人死亡时的实际情况确定；指明指定则点名特定人士。",tw:{ch:"闡釋人壽保險單",q:"「概括式指定」受益人的例子是？",o:["指名公司","指名張三","指定「我的子女」","指名配偶姓名"],e:"概括式指定以類別描述受益人（如「我的子女」），成員以受保人死亡時的實際情況確定；指明指定則點名特定人士。"}},
{p:3,ch:"阐释人寿保险单",q:"受益人领取死亡保险金的条件是？",o:["须缴清保费","于受保人死亡时仍在世","须为亲属","须年满 18 岁"],a:1,e:"受益人只须于受保人死亡时生存即可领取；先于此日死亡或同时死亡时未能确定先后的，一般不获给付（视同时死亡条款）。",tw:{ch:"闡釋人壽保險單",q:"受益人領取死亡保險金的條件是？",o:["須繳清保費","於受保人死亡時仍在世","須為親屬","須年滿 18 歲"],e:"受益人只須於受保人死亡時生存即可領取；先於此日死亡或同時死亡時未能確定先後的，一般不獲給付（視同時死亡條款）。"}},
{p:3,ch:"阐释人寿保险单",q:"按《已婚者地位条例》，保单持有人为配偶或子女利益购买人寿保单的效果是？",o:["保单无效","保单归政府","设立法定信托，配偶／子女成为实益拥有人，保单所有人成为受托人","配偶自动成为保单所有人"],a:2,e:"该条例令为配偶／子女利益投保的寿险设立法定信托：受益人成为实益拥有人，保单款项不属受保人产业、不受其债务规限（欺诈债权人意图除外）。",tw:{ch:"闡釋人壽保險單",q:"按《已婚者地位條例》，保單持有人為配偶或子女利益購買人壽保單的效果是？",o:["保單無效","保單歸政府","設立法定信託，配偶／子女成為實益擁有人，保單所有人成為受託人","配偶自動成為保單所有人"],e:"該條例令為配偶／子女利益投保的壽險設立法定信託：受益人成為實益擁有人，保單款項不屬受保人產業、不受其債務規限（欺詐債權人意圖除外）。"}},
{p:3,ch:"阐释人寿保险单",q:"「不能作废条款」（Non-forfeiture Provisions）给予保单所有人的选择不包括？",o:["减额清缴保险","退保现金价值","展期保险","终身免费保障"],a:3,e:"停止缴费时保单所有人可取回部分保单价值：退保取现金价值、以净现金价值作趸缴购买减额清缴保险，或购买同额展期定期保险。",tw:{ch:"闡釋人壽保險單",q:"「不能作廢條款」（Non-forfeiture Provisions）給予保單所有人的選擇不包括？",o:["減額清繳保險","退保現金價值","展期保險","終身免費保障"],e:"停止繳費時保單所有人可取回部分保單價值：退保取現金價值、以淨現金價值作躉繳購買減額清繳保險，或購買同額展期定期保險。"}},
{p:3,ch:"阐释人寿保险单",q:"「减额清缴保险」的运作是？",o:["以净现金价值作整付保费，购买同计划但保额较低的人寿保险","保额加倍","自动续保","退保取现金"],a:0,e:"减额清缴用现金价值一次过购买较低保额的同类保单，此后无须再缴费。",tw:{ch:"闡釋人壽保險單",q:"「減額清繳保險」的運作是？",o:["以淨現金價值作整付保費，購買同計劃但保額較低的人壽保險","保額加倍","自動續保","退保取現金"],e:"減額清繳用現金價值一次過購買較低保額的同類保單，此後無須再繳費。"}},
{p:3,ch:"阐释人寿保险单",q:"「展期保险」的运作是？",o:["以净现金价值作整付保费，购买与原保额相同的定期寿险，期限视现金价值多少而定","延长缴费期","购买终身寿险","购买年金"],a:0,e:"展期保险维持原保额但改为定期：保障期限长短取决于现金价值能支持多久。",tw:{ch:"闡釋人壽保險單",q:"「展期保險」的運作是？",o:["以淨現金價值作整付保費，購買與原保額相同的定期壽險，期限視現金價值多少而定","延長繳費期","購買終身壽險","購買年金"],e:"展期保險維持原保額但改為定期：保障期限長短取決於現金價值能支持多久。"}},
{p:3,ch:"阐释人寿保险单",q:"保单贷款的金额上限一般为？",o:["现金价值全额","现金价值减去一年的贷款利息","保额的一半","已缴保费"],a:1,e:"贷款以现金价值作抵押，上限通常为现金价值扣减一年利息，以保障利息有缓冲；利率或设订明上限。",tw:{ch:"闡釋人壽保險單",q:"保單貸款的金額上限一般為？",o:["現金價值全額","現金價值減去一年的貸款利息","保額的一半","已繳保費"],e:"貸款以現金價值作抵押，上限通常為現金價值扣減一年利息，以保障利息有緩衝；利率或設訂明上限。"}},
{p:3,ch:"阐释人寿保险单",q:"保单贷款用途的限制是？",o:["只可用于教育","无任何限制","只可用于还款","只可用于医疗"],a:1,e:"保单所有人可自行决定贷款用途、还款时间及金额，弹性极高；未还利息并入贷款本金。",tw:{ch:"闡釋人壽保險單",q:"保單貸款用途的限制是？",o:["只可用於教育","無任何限制","只可用於還款","只可用於醫療"],e:"保單所有人可自行決定貸款用途、還款時間及金額，彈性極高；未還利息併入貸款本金。"}},
{p:3,ch:"阐释人寿保险单",q:"保单复效适用于？",o:["所有情况","已失效（而非已退保）的保单","已退保的保单","从未生效的保单"],a:1,e:"复效只适用于因欠费失效的保单；已主动退保的保单不可复效，须重新投保。",tw:{ch:"闡釋人壽保險單",q:"保單復效適用於？",o:["所有情況","已失效（而非已退保）的保單","已退保的保單","從未生效的保單"],e:"復效只適用於因欠費失效的保單；已主動退保的保單不可復效，須重新投保。"}},
{p:3,ch:"阐释人寿保险单",q:"保单复效后，不可争议条款及自杀条款的处理是？",o:["重新起算另一段可异议期及自杀免责期","永久不再适用","继续按原日期计算","自动豁免"],a:0,e:"复效相当于重新审核风险，故可异议期及自杀免责期均由复效日起重新计算。",tw:{ch:"闡釋人壽保險單",q:"保單復效後，不可爭議條款及自殺條款的處理是？",o:["重新起算另一段可異議期及自殺免責期","永久不再適用","繼續按原日期計算","自動豁免"],e:"復效相當於重新審核風險，故可異議期及自殺免責期均由復效日起重新計算。"}},
{p:3,ch:"阐释人寿保险单",q:"「误报年龄或性别」在索偿前的常见处理方式是？",o:["保额不变，补收或退还保费差额","保费加倍","保单一律无效","双倍赔偿"],a:0,e:"索偿前发现误报，通常按正确年龄性别调整保费（多退少补）；最常见的英式做法则是保额只向下调整、多收保费退还（不计利息）。",tw:{ch:"闡釋人壽保險單",q:"「誤報年齡或性別」在索償前的常見處理方式是？",o:["保額不變，補收或退還保費差額","保費加倍","保單一律無效","雙倍賠償"],e:"索償前發現誤報，通常按正確年齡性別調整保費（多退少補）；最常見的英式做法則是保額只向下調整、多收保費退還（不計利息）。"}},
{p:3,ch:"阐释人寿保险单",q:"保单转让自何时起生效？",o:["保险人同意之日","周年日","向保险人发出通知之日","签署转让文件之日"],a:2,e:"转让文件签署后，须通知保险人方对保险人生效；保险人收到书面通知后才承认承让人。",tw:{ch:"闡釋人壽保險單",q:"保單轉讓自何時起生效？",o:["保險人同意之日","週年日","向保險人發出通知之日","簽署轉讓文件之日"],e:"轉讓文件簽署後，須通知保險人方對保險人生效；保險人收到書面通知後才承認承讓人。"}},
{p:3,ch:"阐释人寿保险单",q:"「抵押转让」保单的特点是？",o:["永久转让","承让人取得全部权益","暂时性质押，承让人利益限于贷款额连利息，还清后权益复归","无须还款"],a:2,e:"抵押转让以保单担保贷款：承让人（债权人）仅于贷款额连利息范围内有权益，还款后权益复归转让人。",tw:{ch:"闡釋人壽保險單",q:"「抵押轉讓」保單的特點是？",o:["永久轉讓","承讓人取得全部權益","暫時性質押，承讓人利益限於貸款額連利息，還清後權益復歸","無須還款"],e:"抵押轉讓以保單擔保貸款：承讓人（債權人）僅於貸款額連利息範圍內有權益，還款後權益復歸轉讓人。"}},
{p:3,ch:"阐释人寿保险单",q:"已通知保险人的抵押转让生效后，转让人（借款人）？",o:["保费加倍","保单自动失效","仍可随意退保","不可再申请保单贷款或退保"],a:3,e:"抵押转让通知保险人后，保单权益受债权人限制，转让人不得再贷款或退保损害债权人利益。",tw:{ch:"闡釋人壽保險單",q:"已通知保險人的抵押轉讓生效後，轉讓人（借款人）？",o:["保費加倍","保單自動失效","仍可隨意退保","不可再申請保單貸款或退保"],e:"抵押轉讓通知保險人後，保單權益受債權人限制，轉讓人不得再貸款或退保損害債權人利益。"}},
{p:3,ch:"阐释人寿保险单",q:"保单转让的限制不包括？",o:["可随意无限次重复抵押","不得侵犯不可撤换受益人的既得权利","不可为非法目的（如洗黑钱）而转让","利益须以整笔支付"],a:0,e:"转让不得损害不可撤换受益人权益、不得用于非法目的、且以整笔利益支付承让人；并非可随意无限重复抵押。",tw:{ch:"闡釋人壽保險單",q:"保單轉讓的限制不包括？",o:["可隨意無限次重複抵押","不得侵犯不可撤換受益人的既得權利","不可為非法目的（如洗黑錢）而轉讓","利益須以整筆支付"],e:"轉讓不得損害不可撤換受益人權益、不得用於非法目的、且以整筆利益支付承讓人；並非可隨意無限重複抵押。"}},
{p:3,ch:"阐释人寿保险单",q:"「现金红利」（美式）一经宣布，性质是？",o:["可撤回","不保证","只限周年日","即时应付给保单所有人"],a:3,e:"美式现金红利一经宣布即属保单所有人，可提取、缴付保费、积存生息、购买一年定期寿或清缴增额保险等。",tw:{ch:"闡釋人壽保險單",q:"「現金紅利」（美式）一經宣佈，性質是？",o:["可撤回","不保證","只限週年日","即時應付給保單所有人"],e:"美式現金紅利一經宣佈即屬保單所有人，可提取、繳付保費、積存生息、購買一年定期壽或清繳增額保險等。"}},
{p:3,ch:"阐释人寿保险单",q:"「英式红利」（复归红利）的支付时点是？",o:["每年现金支付","随时提取","即时支付","于保额（死亡或满期利益）支付时才一并支付"],a:3,e:"英式复归红利附加于保额，于索偿或满期时连同保额一并支付，提前退保则可能只获部分价值。",tw:{ch:"闡釋人壽保險單",q:"「英式紅利」（復歸紅利）的支付時點是？",o:["每年現金支付","隨時提取","即時支付","於保額（死亡或滿期利益）支付時才一併支付"],e:"英式復歸紅利附加於保額，於索償或滿期時連同保額一併支付，提前退保則可能只獲部分價值。"}},
{p:3,ch:"阐释人寿保险单",q:"保单所有人没有指定红利用法时，保单通常采用？",o:["自动红利选择（如积存生息或购买清缴增额保险）","放弃红利","购买定期寿","现金支付"],a:0,e:"保单多预设自动红利选择，常见为存放保险人处生息或购买缴清增额保险，避免红利闲置。",tw:{ch:"闡釋人壽保險單",q:"保單所有人沒有指定紅利用法時，保單通常採用？",o:["自動紅利選擇（如積存生息或購買清繳增額保險）","放棄紅利","購買定期壽","現金支付"],e:"保單多預設自動紅利選擇，常見為存放保險人處生息或購買繳清增額保險，避免紅利閒置。"}},
{p:3,ch:"阐释人寿保险单",q:"「赔付选择」（Settlement Options）不包括？",o:["转投股市","利息选择","定期支付","整笔支付"],a:0,e:"保险金给付方式可选：整笔、定期、定额、终身受益或利息选择（保险金留保险公司生息、分期取息）；不涉及转投股市。",tw:{ch:"闡釋人壽保險單",q:"「賠付選擇」（Settlement Options）不包括？",o:["轉投股市","利息選擇","定期支付","整筆支付"],e:"保險金給付方式可選：整筆、定期、定額、終身受益或利息選擇（保險金留保險公司生息、分期取息）；不涉及轉投股市。"}},
{p:3,ch:"阐释人寿保险单",q:"自杀条款下，证明死亡由自杀引起的举证责任在？",o:["受益人","中介人","投保人","保险人"],a:3,e:"保险人若援引自杀除外须负举证责任；部分个案保险人亦可选择通融赔付（法律上并非必须）。",tw:{ch:"闡釋人壽保險單",q:"自殺條款下，證明死亡由自殺引起的舉證責任在？",o:["受益人","中介人","投保人","保險人"],e:"保險人若援引自殺除外須負舉證責任；部分個案保險人亦可選擇通融賠付（法律上並非必須）。"}},
{p:3,ch:"阐释人寿保险单",q:"「受益人须于受保人死亡时仍在世」，若受益人先亡而保单无次顺位指定，保险金？",o:["归中介","成为受保人遗产的一部分","自动充公","归保险人"],a:1,e:"无在世受益人时保险金按遗产处理；设次顺位受益人可避免遗产程序，体现指定受益人的价值。",tw:{ch:"闡釋人壽保險單",q:"「受益人須於受保人死亡時仍在世」，若受益人先亡而保單無次順位指定，保險金？",o:["歸中介","成為受保人遺產的一部分","自動充公","歸保險人"],e:"無在世受益人時保險金按遺產處理；設次順位受益人可避免遺產程序，體現指定受益人的價值。"}},
{p:3,ch:"阐释人寿保险单",q:"「不可撤换受益人」的权益要更改须？",o:["取得该受益人书面同意","中介同意即可","无须任何同意","保单所有人单方决定即可"],a:0,e:"不可撤换受益人于保单中享有既得权益，任何更改（包括退保）原则上须其书面同意。",tw:{ch:"闡釋人壽保險單",q:"「不可撤換受益人」的權益要更改須？",o:["取得該受益人書面同意","中介同意即可","無須任何同意","保單所有人單方決定即可"],e:"不可撤換受益人於保單中享有既得權益，任何更改（包括退保）原則上須其書面同意。"}},
{p:3,ch:"阐释人寿保险单",q:"保单条款有歧义时，按「不利于草拟人」原则，会作有利于谁的解释？",o:["保单所有人（不利保险人）","保监局","中介人","保险人"],a:0,e:"寿险条款属保险人草拟的标准条款，有疑义时作对被保险人有利的解释，与一般保险一致。",tw:{ch:"闡釋人壽保險單",q:"保單條款有歧義時，按「不利於草擬人」原則，會作有利於誰的解釋？",o:["保單所有人（不利保險人）","保監局","中介人","保險人"],e:"壽險條款屬保險人草擬的標準條款，有疑義時作對被保險人有利的解釋，與一般保險一致。"}},
{p:3,ch:"人寿保险程序",q:"填写投保单的正确做法是？",o:["投保人须亲自填写，避免改动及修正，全面回答所有问题","留空稍后补","只填重要部分","由代理人代填"],a:0,e:"投保书是合约基础：须由投保人亲自填写、如实全面回答、避免涂改；改动处须签章确认，否则影响核保及日后争议。",tw:{ch:"人壽保險程序",q:"填寫投保單的正確做法是？",o:["投保人須親自填寫，避免改動及修正，全面回答所有問題","留空稍後補","只填重要部分","由代理人代填"],e:"投保書是合約基礎：須由投保人親自填寫、如實全面回答、避免塗改；改動處須簽章確認，否則影響核保及日後爭議。"}},
{p:3,ch:"人寿保险程序",q:"投保人不识字，应如何签署投保单？",o:["只按手指模无须见证","由中介全权代签","不能投保","以符号／图章代替签名，加两名见证人，代理人可作见证人之一"],a:3,e:"不会写字者可画符号或盖图章，并由两名见证人见证（代理人可作其中一人），确保签署的真实性。",tw:{ch:"人壽保險程序",q:"投保人不識字，應如何簽署投保單？",o:["只按手指模無須見證","由中介全權代簽","不能投保","以符號／圖章代替簽名，加兩名見證人，代理人可作見證人之一"],e:"不會寫字者可畫符號或蓋圖章，並由兩名見證人見證（代理人可作其中一人），確保簽署的真實性。"}},
{p:3,ch:"人寿保险程序",q:"投保时「上一个／下一个生日年龄」为何重要？",o:["不影响保费","人寿保费按年龄厘定，生日前后投保的保费可能不同","只影响红利","只影响冷静期"],a:1,e:"保费按投保时的到达年龄（最近生日）计算，生日前后数日投保保费可能不同，故须确定上一个或下一个生日年龄。",tw:{ch:"人壽保險程序",q:"投保時「上一個／下一個生日年齡」為何重要？",o:["不影響保費","人壽保費按年齡釐定，生日前後投保的保費可能不同","隻影響紅利","隻影響冷靜期"],e:"保費按投保時的到達年齡（最近生日）計算，生日前後數日投保保費可能不同，故須確定上一個或下一個生日年齡。"}},
{p:3,ch:"人寿保险程序",q:"「附条件保费收据」（Conditional Premium Receipt）下，保障？",o:["只保三十天","完全无效","追溯至投保时生效，但事后须证实投保时按标准条款具可保性方有效","即时无条件永久生效"],a:2,e:"附条件收据（「投保时生效」收据）把保障追溯至投保日，若核保后发现投保时本不具可保性，保障可被推翻。",tw:{ch:"人壽保險程序",q:"「附條件保費收據」（Conditional Premium Receipt）下，保障？",o:["只保三十天","完全無效","追溯至投保時生效，但事後須證實投保時按標準條款具可保性方有效","即時無條件永久生效"],e:"附條件收據（「投保時生效」收據）把保障追溯至投保日，若核保後發現投保時本不具可保性，保障可被推翻。"}},
{p:3,ch:"人寿保险程序",q:"「立约保费收据」（TIA）与一般收据的分别是？",o:["TIA 本身是独立合约，不依附日后签发的正式保单","须保险人批准才生效","等同正式保单","只是一张收据"],a:0,e:"临时保险协议是独立的临时保障合约，签署投保单并缴清保费当日生效，与日后是否签发正式保单无关。",tw:{ch:"人壽保險程序",q:"「立約保費收據」（TIA）與一般收據的分別是？",o:["TIA 本身是獨立合約，不依附日後簽發的正式保單","須保險人批准才生效","等同正式保單","只是一張收據"],e:"臨時保險協議是獨立的臨時保障合約，簽署投保單並繳清保費當日生效，與日後是否簽發正式保單無關。"}},
{p:3,ch:"人寿保险程序",q:"暂保单（Cover Note）的保障期及性质是？",o:["终身","三年","不可取消","约三十天、暂时性、可取消"],a:3,e:"暂保单（非人寿保险）提供约三十天的暂时保障，不附条件但可取消，且未必受是否缴费影响。",tw:{ch:"人壽保險程序",q:"暫保單（Cover Note）的保障期及性質是？",o:["終身","三年","不可取消","約三十天、暫時性、可取消"],e:"暫保單（非人壽保險）提供約三十天的暫時保障，不附條件但可取消，且未必受是否繳費影響。"}},
{p:3,ch:"人寿保险程序",q:"冷静期规定的来源及时长是？",o:["法例规定 7 天","保险公司自定 30 天","业界守则规定，保单交付或通知书发出（以较先者）后起计 21 天","没有冷静期"],a:2,e:"冷静期由业界守则（香港保险业联会）规定：保单或冷静期通知书交付（以较先者为准）后起计 21 天，文件须印上冷静期权益及届满日。",tw:{ch:"人壽保險程序",q:"冷靜期規定的來源及時長是？",o:["法例規定 7 天","保險公司自定 30 天","業界守則規定，保單交付或通知書發出（以較先者）後起計 21 天","沒有冷靜期"],e:"冷靜期由業界守則（香港保險業聯會）規定：保單或冷靜期通知書交付（以較先者為準）後起計 21 天，文件須印上冷靜期權益及屆滿日。"}},
{p:3,ch:"人寿保险程序",q:"冷静期内取消非投资相连保单，可获退还？",o:["90% 保费","分文不退","只退现金价值","100% 已缴保费"],a:3,e:"非投连保单冷静期取消全数退还保费；自愿医保产品可提供更长的冷静期。",tw:{ch:"人壽保險程序",q:"冷靜期內取消非投資相連保單，可獲退還？",o:["90% 保費","分文不退","只退現金價值","100% 已繳保費"],e:"非投連保單冷靜期取消全數退還保費；自願醫保產品可提供更長的冷靜期。"}},
{p:3,ch:"人寿保险程序",q:"冷静期内取消投连保单或非投连整付保费保单，退还金额为？",o:["只退一半","按现金价值","保费减去市值调整（MVA）","100% 保费"],a:2,e:"投连及非投连整付保单退还「保费 − 市值调整」；MVA 只可用于反映保险人变现资产的亏损，不得计入签发费用或佣金。",tw:{ch:"人壽保險程序",q:"冷靜期內取消投連保單或非投連整付保費保單，退還金額為？",o:["只退一半","按現金價值","保費減去市值調整（MVA）","100% 保費"],e:"投連及非投連整付保單退還「保費 − 市值調整」；MVA 只可用於反映保險人變現資產的虧損，不得計入簽發費用或佣金。"}},
{p:3,ch:"人寿保险程序",q:"「市值调整」（MVA）的用途是？",o:["计算税款","补偿佣金","惩罚投保人","只计算保险人兑现资产可能出现的亏损"],a:3,e:"MVA 仅限弥补资产变现亏损，保险人签发保单支出的费用或佣金不得计算在内，保障冷静期权益不被侵蚀。",tw:{ch:"人壽保險程序",q:"「市值調整」（MVA）的用途是？",o:["計算税款","補償佣金","懲罰投保人","只計算保險人兑現資產可能出現的虧損"],e:"MVA 僅限彌補資產變現虧損，保險人簽發保單支出的費用或佣金不得計算在內，保障冷靜期權益不被侵蝕。"}},
{p:3,ch:"人寿保险程序",q:"「转保」（Replacement）指？",o:["定期转终身","加购附约","以一份新的寿险保单取代现有保单","保单贷款"],a:2,e:"转保是以新保单取代现有保单；注意：将定期寿险转换为终身寿险等永久保险不视为转保。",tw:{ch:"人壽保險程序",q:"「轉保」（Replacement）指？",o:["定期轉終身","加購附約","以一份新的壽險保單取代現有保單","保單貸款"],e:"轉保是以新保單取代現有保單；注意：將定期壽險轉換為終身壽險等永久保險不視為轉保。"}},
{p:3,ch:"人寿保险程序",q:"「诱导转保」（Twisting）指？",o:["定期转终身","退保","以不正确或误导的言论或比较，诱使保单持有人以新保单取代现有保单而蒙受损失","正常转保建议"],a:2,e:"诱导转保属不当销售行为：误导性比较令客户过早退保损失既有利益；销售时须提供《客户保障声明书》以保障客户。",tw:{ch:"人壽保險程序",q:"「誘導轉保」（Twisting）指？",o:["定期轉終身","退保","以不正確或誤導的言論或比較，誘使保單持有人以新保單取代現有保單而蒙受損失","正常轉保建議"],e:"誘導轉保屬不當銷售行為：誤導性比較令客户過早退保損失既有利益；銷售時須提供《客户保障聲明書》以保障客户。"}},
{p:3,ch:"人寿保险程序",q:"「相连保单退保说明文件」由谁规定提供？",o:["保监局","保险业联会","证券及期货事务监察委员会（证监会）","税务局"],a:2,e:"投连保单的销售须附证监会规定的退保说明文件；万用及分红保单的销售说明文件则由香港保险业联会寿险总会指定。",tw:{ch:"人壽保險程序",q:"「相連保單退保說明文件」由誰規定提供？",o:["保監局","保險業聯會","證券及期貨事務監察委員會（證監會）","税務局"],e:"投連保單的銷售須附證監會規定的退保說明文件；萬用及分紅保單的銷售說明文件則由香港保險業聯會壽險總會指定。"}},
{p:3,ch:"人寿保险程序",q:"「分红保单销售说明文件」的适用范围是？",o:["所有保单","只限团体","只限投连","针对特定分红保单（万用寿险保单除外）提供利益概括说明"],a:3,e:"说明文件确保准保单持有人获得该分红保单的最低限度利益说明；万用寿险有其专属说明文件安排。",tw:{ch:"人壽保險程序",q:"「分紅保單銷售說明文件」的適用範圍是？",o:["所有保單","只限團體","只限投連","針對特定分紅保單（萬用壽險保單除外）提供利益概括說明"],e:"說明文件確保準保單持有人獲得該分紅保單的最低限度利益說明；萬用壽險有其專屬說明文件安排。"}},
{p:3,ch:"人寿保险程序",q:"按保监局指引，保险公司须于网站披露分红保单的？",o:["内部佣金表","非保证红利／英式红利实现率","全部客户名单","核保手册"],a:1,e:"保险人须披露分红保单的实现率（实际派发非保证红利 ÷ 销售说明所述金额），万用寿险则披露过往派息率，提升透明度。",tw:{ch:"人壽保險程序",q:"按保監局指引，保險公司須於網站披露分紅保單的？",o:["內部佣金表","非保證紅利／英式紅利實現率","全部客户名單","核保手冊"],e:"保險人須披露分紅保單的實現率（實際派發非保證紅利 ÷ 銷售說明所述金額），萬用壽險則披露過往派息率，提升透明度。"}},
{p:3,ch:"人寿保险程序",q:"「红利实现率」的计算方式是？",o:["派发金额 ÷ 保费","现金价值 ÷ 保额","红利 ÷ 佣金","实际派发的非保证红利 ÷ 销售时利益说明所述金额"],a:3,e:"实现率 = 实际派发的非保证红利／英式红利，除以销售时利益说明所示金额的平均数，用以衡量说明与实际的距离。",tw:{ch:"人壽保險程序",q:"「紅利實現率」的計算方式是？",o:["派發金額 ÷ 保費","現金價值 ÷ 保額","紅利 ÷ 佣金","實際派發的非保證紅利 ÷ 銷售時利益說明所述金額"],e:"實現率 = 實際派發的非保證紅利／英式紅利，除以銷售時利益說明所示金額的平均數，用以衡量說明與實際的距離。"}},
{p:3,ch:"人寿保险程序",q:"内地人士在港投购人身／寿险保单，须签署什么文件？",o:["英文声明书","无须签署","只在内地签","重要资料声明书（简体中文版本）"],a:3,e:"保监局规定供长期业务保险人遵守：内地访港旅客投保须签署简体中文的《重要资料声明书》，确认知悉跨境投保事宜。",tw:{ch:"人壽保險程序",q:"內地人士在港投購人身／壽險保單，須簽署什麼文件？",o:["英文聲明書","無須簽署","只在內地籤","重要資料聲明書（簡體中文版本）"],e:"保監局規定供長期業務保險人遵守：內地訪港旅客投保須簽署簡體中文的《重要資料聲明書》，確認知悉跨境投保事宜。"}},
{p:3,ch:"人寿保险程序",q:"主诊医生报告（APS）通常在什么情况下要求？",o:["投保书披露健康问题须查证、保额很高或投保人年龄较大（如超过 50 岁）","任何小额投保","只限儿童","从不要求"],a:0,e:"核保要求主诊医生报告以查证披露的健康资料，常见于高额或高龄投保；费用由保险人支付。",tw:{ch:"人壽保險程序",q:"主診醫生報告（APS）通常在什麼情況下要求？",o:["投保書披露健康問題須查證、保額很高或投保人年齡較大（如超過 50 歲）","任何小額投保","只限兒童","從不要求"],e:"核保要求主診醫生報告以查證披露的健康資料，常見於高額或高齡投保；費用由保險人支付。"}},
{p:3,ch:"人寿保险程序",q:"「特殊医疗问卷」的用途是？",o:["计算佣金","推销产品","向检查或主诊医生取得特定疾病的进一步资料","客户投诉"],a:2,e:"保险人可向医生发出特别设计的问卷，深入了解某疾病或身体状况；投保人有权知悉检查内容、目的及结果。",tw:{ch:"人壽保險程序",q:"「特殊醫療問卷」的用途是？",o:["計算佣金","推銷產品","向檢查或主診醫生取得特定疾病的進一步資料","客户投訴"],e:"保險人可向醫生髮出特別設計的問卷，深入瞭解某疾病或身體狀況；投保人有權知悉檢查內容、目的及結果。"}},
{p:3,ch:"人寿保险程序",q:"对次标准风险「设置保单负债」的适用情况是？",o:["永久高风险","超额死亡率明显呈下降趋势且属临时性质","拒保个案","所有次标准风险"],a:1,e:"保单负债（递减式）适用于暂时性、递减的超额死亡率风险——负债逐渐减少至指定日期完全消失。",tw:{ch:"人壽保險程序",q:"對次標準風險「設置保單負債」的適用情況是？",o:["永久高風險","超額死亡率明顯呈下降趨勢且屬臨時性質","拒保個案","所有次標準風險"],e:"保單負債（遞減式）適用於暫時性、遞減的超額死亡率風險——負債逐漸減少至指定日期完全消失。"}},
{p:3,ch:"人寿保险程序",q:"个人人寿保单一般由谁负责交付？",o:["保险／销售代理人","邮差","客户自取","保监局"],a:0,e:"个人保单由代理人负责送交保单所有人；团体保单则由中介或团体保险部代表监察总保单、保险凭证及成员登记。",tw:{ch:"人壽保險程序",q:"個人人壽保單一般由誰負責交付？",o:["保險／銷售代理人","郵差","客户自取","保監局"],e:"個人保單由代理人負責送交保單所有人；團體保單則由中介或團體保險部代表監察總保單、保險憑證及成員登記。"}},
{p:3,ch:"人寿保险程序",q:"「保单所有人服务部」（POS）处理更改保单时，哪项更改须特别核保考虑？",o:["更改（增加）保额","更改缴费方式","补发文件","更改地址"],a:0,e:"增加保额等于增加风险，须经核保审批；更改地址等行政事项无须核保。所有更改亦须防范欺诈及洗黑钱风险。",tw:{ch:"人壽保險程序",q:"「保單所有人服務部」（POS）處理更改保單時，哪項更改須特別核保考慮？",o:["更改（增加）保額","更改繳費方式","補發文件","更改地址"],e:"增加保額等於增加風險，須經核保審批；更改地址等行政事項無須核保。所有更改亦須防範欺詐及洗黑錢風險。"}},
{p:3,ch:"人寿保险程序",q:"死亡索偿中「死亡日期」为何重要？",o:["只影响冷静期","影响递减保额保单的给付金额及红利计算","无关紧要","只影响保费"],a:1,e:"死亡日期决定递减定期寿的当时保额，并影响红利的结算，故必须凭死亡证明确定。",tw:{ch:"人壽保險程序",q:"死亡索償中「死亡日期」為何重要？",o:["隻影響冷靜期","影響遞減保額保單的給付金額及紅利計算","無關緊要","隻影響保費"],e:"死亡日期決定遞減定期壽的當時保額，並影響紅利的結算，故必須憑死亡證明確定。"}},
{p:3,ch:"人寿保险程序",q:"期满索偿（满期金）的正确处理流程是？",o:["十年后给付","只电话通知","到期前发信提醒，附支付金额／条件及解除责任凭证，收款时签署","无声无息"],a:2,e:"保险人于期满前主动发信：提醒期满日期、金额及条件，并附解除责任凭证供收款时签署。",tw:{ch:"人壽保險程序",q:"期滿索償（滿期金）的正確處理流程是？",o:["十年後給付","只電話通知","到期前發信提醒，附支付金額／條件及解除責任憑證，收款時簽署","無聲無息"],e:"保險人於期滿前主動發信：提醒期滿日期、金額及條件，並附解除責任憑證供收款時簽署。"}},
{p:3,ch:"人寿保险程序",q:"处理退保索偿时，给付金额一般为？",o:["已缴保费全数","红利全数","现金价值减去保单贷款本息及未缴保费","保额全数"],a:2,e:"退保给付 = 现金价值 − 保单贷款本息 − 欠缴保费（如有），故早期退保金额常远低于已缴保费。",tw:{ch:"人壽保險程序",q:"處理退保索償時，給付金額一般為？",o:["已繳保費全數","紅利全數","現金價值減去保單貸款本息及未繳保費","保額全數"],e:"退保給付 = 現金價值 − 保單貸款本息 − 欠繳保費（如有），故早期退保金額常遠低於已繳保費。"}},
{p:3,ch:"人寿保险程序",q:"核保分类中「优良风险」（Preferred Risks）指？",o:["高风险","拒保风险","健康状况及生活习惯优于平均的风险，可获优惠费率","次标准风险"],a:2,e:"优良风险（如不吸烟、体格标准、家族病史良好）死亡率低于平均，保险人给予优惠费率以争取业务。",tw:{ch:"人壽保險程序",q:"核保分類中「優良風險」（Preferred Risks）指？",o:["高風險","拒保風險","健康狀況及生活習慣優於平均的風險，可獲優惠費率","次標準風險"],e:"優良風險（如不吸煙、體格標準、家族病史良好）死亡率低於平均，保險人給予優惠費率以爭取業務。"}},
{p:3,ch:"人寿保险程序",q:"「财务性核保」评估「保额是否明显高于通常标准」的目的？",o:["增加保费","防范超额投保及道德危险","加快出单","挑选客户"],a:1,e:"保额与收入不成比例、累计保额异常皆可能引发道德危险，财务核保由此把关并决定再保险安排。",tw:{ch:"人壽保險程序",q:"「財務性核保」評估「保額是否明顯高於通常標準」的目的？",o:["增加保費","防範超額投保及道德危險","加快出單","挑選客户"],e:"保額與收入不成比例、累計保額異常皆可能引發道德危險，財務核保由此把關並決定再保險安排。"}},
{p:3,ch:"人寿保险程序",q:"核保时要求体检或医疗报告的费用一般由谁支付？",o:["保险人","投保人","受益人","中介人"],a:0,e:"体检医生按保险人要求进行检查，费用由保险人支付；主诊医生报告亦然，此点考试常考。",tw:{ch:"人壽保險程序",q:"核保時要求體檢或醫療報告的費用一般由誰支付？",o:["保險人","投保人","受益人","中介人"],e:"體檢醫生按保險人要求進行檢查，費用由保險人支付；主診醫生報告亦然，此點考試常考。"}},
{p:3,ch:"人寿保险程序",q:"「顾客服务」对寿险公司特别重要的原因是？",o:["法律强制","只为广告","可有可无","大部分成本在保单开始时支付，业务持续与保留对盈利至关重要"],a:3,e:"寿险首年佣金及出单成本高昂，利润来自保单长期持续；优质服务（以客为本文化、前线授权、满意度监察、培训）是保留业务的关键。",tw:{ch:"人壽保險程序",q:"「顧客服務」對壽險公司特別重要的原因是？",o:["法律強制","只為廣告","可有可無","大部分成本在保單開始時支付，業務持續與保留對盈利至關重要"],e:"壽險首年佣金及出單成本高昂，利潤來自保單長期持續；優質服務（以客為本文化、前線授權、滿意度監察、培訓）是保留業務的關鍵。"}},
{p:3,ch:"人寿保险程序",q:"「孤儿保单」（Orphan Policy）指？",o:["新保单","失效保单","原代理人离职后无人持续服务的保单","团体保单"],a:2,e:"代理人离职会令保单变成「孤儿保单」，公司须安排其他人员接管，确保售后服务不中断。",tw:{ch:"人壽保險程序",q:"「孤兒保單」（Orphan Policy）指？",o:["新保單","失效保單","原代理人離職後無人持續服務的保單","團體保單"],e:"代理人離職會令保單變成「孤兒保單」，公司須安排其他人員接管，確保售後服務不中斷。"}},
{p:1,ch:"风险与保险",q:"保险运作的核心机制，是把少数不幸者的经济损失？",o:["分摊到全体投保人身上","由保险人股东永久承担","转嫁给再保险公司","由政府以税收承担"],a:0,e:"保险透过集合大量同质风险单位，以众人缴付的保费赔付少数实际发生损失者，把个别损失分摊于整体，此即「损失分摊／风险分摊」机制。",tw:{ch:"風險與保險",q:"保險運作的核心機制，是把少數不幸者的經濟損失？",o:["分攤到全體投保人身上","由保險人股東永久承擔","轉嫁給再保險公司","由政府以税收承擔"],e:"保險透過集合大量同質風險單位，以眾人繳付的保費賠付少數實際發生損失者，把個別損失分攤於整體，此即「損失分攤／風險分攤」機制。"}},
{p:1,ch:"风险与保险",q:"下列对「危险」（Peril）与「危险因素」（Hazard）的区分，哪项正确？",o:["两者含义完全相同","危险是造成损失的直接原因；危险因素是增加损失机会或严重程度的情况","危险因素指火灾、水灾等事件","只有「危险」才与保险有关"],a:1,e:"危险（Peril）是引致损失的原因或事件本身（如火灾、盗窃）；危险因素（Hazard）则是影响损失发生几率或严重程度的情况，可分为实质、道德及心理（士气）危险因素。",tw:{ch:"風險與保險",q:"下列對「危險」（Peril）與「危險因素」（Hazard）的區分，哪項正確？",o:["兩者含義完全相同","危險是造成損失的直接原因；危險因素是增加損失機會或嚴重程度的情況","危險因素指火災、水災等事件","只有「危險」才與保險有關"],e:"危險（Peril）是引致損失的原因或事件本身（如火災、盜竊）；危險因素（Hazard）則是影響損失發生幾率或嚴重程度的情況，可分為實質、道德及心理（士氣）危險因素。"}},
{p:1,ch:"风险与保险",q:"可保风险的损失须具「偶然性／意外性」，下列哪项最符合？",o:["损失须在投保人控制之内","损失必须定期发生","损失须由意外、偶然事件引起，非投保人蓄意制造或必然发生","损失金额必须十分巨大"],a:2,e:"可保风险的损失须为偶然、意外且不可预料，排除必然发生及投保人蓄意造成的情况，以免引致道德危险。",tw:{ch:"風險與保險",q:"可保風險的損失須具「偶然性／意外性」，下列哪項最符合？",o:["損失須在投保人控制之內","損失必須定期發生","損失須由意外、偶然事件引起，非投保人蓄意製造或必然發生","損失金額必須十分巨大"],e:"可保風險的損失須為偶然、意外且不可預料，排除必然發生及投保人蓄意造成的情況，以免引致道德危險。"}},
{p:1,ch:"风险与保险",q:"对于「高频率、低损失程度」的风险，最常见的应对方式是？",o:["购买保险转移","寻求再保险","风险避免","自留，并配合损失防范与降低"],a:3,e:"高频低损的风险（如小额遗失、耗损）购买保险因含费用与利润而不经济，宜自留并配合防损措施；低频高损才是保险的典型对象。",tw:{ch:"風險與保險",q:"對於「高頻率、低損失程度」的風險，最常見的應對方式是？",o:["購買保險轉移","尋求再保險","風險避免","自留，並配合損失防範與降低"],e:"高頻低損的風險（如小額遺失、耗損）購買保險因含費用與利潤而不經濟，宜自留並配合防損措施；低頻高損才是保險的典型對象。"}},
{p:1,ch:"法律原则",q:"一般（非寿险）财产保险的可保利益，须在何时存在？",o:["损失发生时","订立合约时","退保时","任何时间均须存在"],a:0,e:"人寿／长期保险要求订约（投保）时可保利益；一般保险则要求损失发生时可保利益——出险时须对标的具利害关系方可获偿。",tw:{ch:"法律原則",q:"一般（非壽險）財產保險的可保利益，須在何時存在？",o:["損失發生時","訂立合約時","退保時","任何時間均須存在"],e:"人壽／長期保險要求訂約（投保）時可保利益；一般保險則要求損失發生時可保利益——出險時須對標的具利害關係方可獲償。"}},
{p:1,ch:"法律原则",q:"未成年人订立关于「生活必需品」的合约，其效力一般为？",o:["一律无效","对未成年人具约束力（须支付合理价钱）","可由保险人单方撤销","须经其监护人追认方有效"],a:1,e:"未成年人为生活必需品（necessaries）订立的合约对其有约束力；其余非必需品合约一般可由该未成年人撤销，属立约能力的例外规范。",tw:{ch:"法律原則",q:"未成年人訂立關於「生活必需品」的合約，其效力一般為？",o:["一律無效","對未成年人具約束力（須支付合理價錢）","可由保險人單方撤銷","須經其監護人追認方有效"],e:"未成年人為生活必需品（necessaries）訂立的合約對其有約束力；其餘非必需品合約一般可由該未成年人撤銷，屬立約能力的例外規範。"}},
{p:1,ch:"法律原则",q:"投保人因疏忽提供了不准确的资料（非蓄意欺骗），在法律上属于？",o:["欺诈性误述","无辜误述","疏忽性误述，若涉重要事实可令合约可撤销","不构成任何问题"],a:2,e:"误述可分为无辜、疏忽及欺诈三种；疏忽性误述是未尽谨慎而误述，涉及重要事实时可令合约成为可撤销，欺诈性误述后果最严重且不受不可争议条款保护。",tw:{ch:"法律原則",q:"投保人因疏忽提供了不準確的資料（非蓄意欺騙），在法律上屬於？",o:["欺詐性誤述","無辜誤述","疏忽性誤述，若涉重要事實可令合約可撤銷","不構成任何問題"],e:"誤述可分為無辜、疏忽及欺詐三種；疏忽性誤述是未盡謹慎而誤述，涉及重要事實時可令合約成為可撤銷，欺詐性誤述後果最嚴重且不受不可爭議條款保護。"}},
{p:1,ch:"法律原则",q:"最大诚信（Utmost Good Faith）原则源自下列哪一法律领域？",o:["公司法","刑事法","税法","海商法（海上保险）"],a:3,e:"最大诚信原则源于海商／海上保险：承保人往往依赖被保险人遥在外地的申报而无法核实，故要求投保人绝对诚实披露重要事实，其后推广至所有保险合约。",tw:{ch:"法律原則",q:"最大誠信（Utmost Good Faith）原則源自下列哪一法律領域？",o:["公司法","刑事法","税法","海商法（海上保險）"],e:"最大誠信原則源於海商／海上保險：承保人往往依賴被保險人遙在外地的申報而無法核實，故要求投保人絕對誠實披露重要事實，其後推廣至所有保險合約。"}},
{p:1,ch:"法律原则",q:"代理关系属于以信任为基础的「受信关系」，因此代理人应？",o:["以委托人的利益为先、避免利益冲突并如实交代","优先考虑自身佣金","可自行把职责转授他人","隐瞒可能影响委托人的事实"],a:0,e:"代理属受信（fiduciary）关系，代理人须忠诚、以委托人利益为先，如实交代并避免利益冲突；不得擅自转授，亦不得隐瞒涉及委托人的重大事实。",tw:{ch:"法律原則",q:"代理關係屬於以信任為基礎的「受信關係」，因此代理人應？",o:["以委託人的利益為先、避免利益衝突並如實交代","優先考慮自身佣金","可自行把職責轉授他人","隱瞞可能影響委託人的事實"],e:"代理屬受信（fiduciary）關係，代理人須忠誠、以委託人利益為先，如實交代並避免利益衝突；不得擅自轉授，亦不得隱瞞涉及委託人的重大事實。"}},
{p:1,ch:"保险原则",q:"某财产实际价值 100 万元，却投保 150 万元（超额投保），发生损失 40 万元，保单为不定额弥偿保单，保险人应赔？",o:["150 万元","40 万元","100 万元","60 万元"],a:1,e:"弥偿原则以实际损失为上限：纵使保额高于实际价值，赔偿最多等于实际损失 40 万元，被保险人不得因投保而获利。",tw:{ch:"保險原則",q:"某財產實際價值 100 萬元，卻投保 150 萬元（超額投保），發生損失 40 萬元，保單為不定額彌償保單，保險人應賠？",o:["150 萬元","40 萬元","100 萬元","60 萬元"],e:"彌償原則以實際損失為上限：縱使保額高於實際價值，賠償最多等於實際損失 40 萬元，被保險人不得因投保而獲利。"}},
{p:1,ch:"保险原则",q:"一连串事件先后发生造成损失，应用「近因」原则判断时，应？",o:["取时间上最先发生的事件","取时间上最后发生的事件","分析因果链，找出有效的、支配性的成因","由被保险人任选其一"],a:2,e:"近因并非仅按时间先后，而是在因果链中找出对损失具有有效、支配作用的成因；该成因属受保危险则获赔，属除外危险则不赔。",tw:{ch:"保險原則",q:"一連串事件先後發生造成損失，應用「近因」原則判斷時，應？",o:["取時間上最先發生的事件","取時間上最後發生的事件","分析因果鏈，找出有效的、支配性的成因","由被保險人任選其一"],e:"近因並非僅按時間先後，而是在因果鏈中找出對損失具有有效、支配作用的成因；該成因屬受保危險則獲賠，屬除外危險則不賠。"}},
{p:1,ch:"保险原则",q:"下列对「委付」与「代位」的区分，哪项正确？",o:["委付是保险人赔付后向第三者追偿","代位是水险全损时移交标的","两者含义完全相同","委付是把标的（残余）交予保险人以索取全损；代位是赔付后取得对第三者的追偿权"],a:3,e:"委付（Abandonment）主要见于水险，由被保险人把标的残余完全移交保险人以索取推定全损赔偿；代位（Subrogation）是保险人赔付后以被保险人名义向责任第三者追偿。",tw:{ch:"保險原則",q:"下列對「委付」與「代位」的區分，哪項正確？",o:["委付是保險人賠付後向第三者追償","代位是水險全損時移交標的","兩者含義完全相同","委付是把標的（殘餘）交予保險人以索取全損；代位是賠付後取得對第三者的追償權"],e:"委付（Abandonment）主要見於水險，由被保險人把標的殘餘完全移交保險人以索取推定全損賠償；代位（Subrogation）是保險人賠付後以被保險人名義向責任第三者追償。"}},
{p:1,ch:"保险原则",q:"被保险人提出「委付」一般须在什么情况下进行？",o:["推定全损（Constructive Total Loss）等符合全损的情况下","任何部分损失时","任何时间","损失发生后一年内"],a:0,e:"委付主要见于水险，须在推定全损（如修理费超过标的恢复后的价值）等符合全损的情况下提出，且必须完整、无条件，由保险人接受或拒绝。",tw:{ch:"保險原則",q:"被保險人提出「委付」一般須在什麼情況下進行？",o:["推定全損（Constructive Total Loss）等符合全損的情況下","任何部分損失時","任何時間","損失發生後一年內"],e:"委付主要見於水險，須在推定全損（如修理費超過標的恢復後的價值）等符合全損的情況下提出，且必須完整、無條件，由保險人接受或拒絕。"}},
{p:1,ch:"保险原则",q:"损失发生后，被保险人除尽力施救外，还应？",o:["立即承认对第三者的责任","尽快通知保险人，且未经同意不应自行承认对第三者的责任","销毁现场证据","等候法律程序完全结束"],a:1,e:"被保险人有义务尽快通知保险人、保护损余并配合调查，且未经保险人同意不应擅自承认对第三者的责任，以免损害保险人的代位及抗辩权利。",tw:{ch:"保險原則",q:"損失發生後，被保險人除盡力施救外，還應？",o:["立即承認對第三者的責任","儘快通知保險人，且未經同意不應自行承認對第三者的責任","銷燬現場證據","等候法律程序完全結束"],e:"被保險人有義務儘快通知保險人、保護損餘並配合調查，且未經保險人同意不應擅自承認對第三者的責任，以免損害保險人的代位及抗辯權利。"}},
{p:1,ch:"保险公司的主要功能",q:"「成数再保险」（Quota Share）的特点是？",o:["只承保超过自留额的部分","逐笔磋商才生效","分出公司按固定百分比把每笔风险分给再保险人","只适用于人寿保险"],a:2,e:"成数再保是比例再保险的一种：分出公司把每张保单的风险按固定百分比分给再保险人，再保险人按同一比例收保费、担赔付，可简化手续。",tw:{ch:"保險公司的主要功能",q:"「成數再保險」（Quota Share）的特點是？",o:["只承保超過自留額的部分","逐筆磋商才生效","分出公司按固定百分比把每筆風險分給再保險人","只適用於人壽保險"],e:"成數再保是比例再保險的一種：分出公司把每張保單的風險按固定百分比分給再保險人，再保險人按同一比例收保費、擔賠付，可簡化手續。"}},
{p:1,ch:"保险公司的主要功能",q:"「溢额再保险」（Surplus）中，分给再保险人的部分是？",o:["每笔风险的固定百分比","全部风险","只限巨灾风险","超出分出公司「自留额」的部分"],a:3,e:"溢额再保以自留额（及线数／倍数）为前提：分出公司先自留约定数额，超过自留额的溢额部分才分给再保险人，可保留小额、分散大额风险。",tw:{ch:"保險公司的主要功能",q:"「溢額再保險」（Surplus）中，分給再保險人的部分是？",o:["每筆風險的固定百分比","全部風險","只限巨災風險","超出分出公司「自留額」的部分"],e:"溢額再保以自留額（及線數／倍數）為前提：分出公司先自留約定數額，超過自留額的溢額部分才分給再保險人，可保留小額、分散大額風險。"}},
{p:1,ch:"保险公司的主要功能",q:"保险公司核保时设定「自留额」的主要作用是？",o:["决定自己保留与向外分出的风险界限，维持承保能力并分散风险","限制再保险人的利润","计算应付佣金","满足税务要求"],a:0,e:"自留额是保险人愿自行承担的最高风险额，超出部分经再保险分出；合理设定可平衡承保能力、资本效率与风险集中度。",tw:{ch:"保險公司的主要功能",q:"保險公司核保時設定「自留額」的主要作用是？",o:["決定自己保留與向外分出的風險界限，維持承保能力並分散風險","限制再保險人的利潤","計算應付佣金","滿足税務要求"],e:"自留額是保險人願自行承擔的最高風險額，超出部分經再保險分出；合理設定可平衡承保能力、資本效率與風險集中度。"}},
{p:1,ch:"保险公司的主要功能",q:"长期业务保险人的投资，一般须遵循的原则是？",o:["追求最高投机回报","稳健审慎，并与负债（保单给付）相匹配","集中于单一高回报资产","不受任何规管"],a:1,e:"寿险负债期限长，投资须稳健审慎并与负债性质、期限相匹配，以确保多年后能履行给付，并受保监局规管及偿付能力约束。",tw:{ch:"保險公司的主要功能",q:"長期業務保險人的投資，一般須遵循的原則是？",o:["追求最高投機回報","穩健審慎，並與負債（保單給付）相匹配","集中於單一高回報資產","不受任何規管"],e:"壽險負債期限長，投資須穩健審慎並與負債性質、期限相匹配，以確保多年後能履行給付，並受保監局規管及償付能力約束。"}},
{p:1,ch:"保险公司的主要功能",q:"核保人员厘定承保条件时，正确的做法是？",o:["对一切高风险一律拒保","只承保相识的人","依客观风险厘定条件，但不得基于性别、残疾等受法例保障的特征作不当歧视","按佣金多寡决定"],a:2,e:"核保可按客观风险厘定费率及条件，但须遵守反歧视法例，不得基于性别、家庭岗位、残疾、种族等受保障特征作不公平对待。",tw:{ch:"保險公司的主要功能",q:"核保人員釐定承保條件時，正確的做法是？",o:["對一切高風險一律拒保","只承保相識的人","依客觀風險釐定條件，但不得基於性別、殘疾等受法例保障的特徵作不當歧視","按佣金多寡決定"],e:"核保可按客觀風險釐定費率及條件，但須遵守反歧視法例，不得基於性別、家庭崗位、殘疾、種族等受保障特徵作不公平對待。"}},
{p:1,ch:"保险公司的主要功能",q:"保费率的厘定主要依据哪类资料？",o:["广告预算及促销开支","竞争对手的情绪","中介人的偏好","索赔经验、损失统计及精算假设（死亡率／损失率、利率、费用率）"],a:3,e:"费率须基于实际赔付经验、损失率及精算假设厘定，使保费反映风险，既具竞争力又保证偿付能力。",tw:{ch:"保險公司的主要功能",q:"保費率的釐定主要依據哪類資料？",o:["廣告預算及促銷開支","競爭對手的情緒","中介人的偏好","索賠經驗、損失統計及精算假設（死亡率／損失率、利率、費用率）"],e:"費率須基於實際賠付經驗、損失率及精算假設釐定，使保費反映風險，既具競爭力又保證償付能力。"}},
{p:1,ch:"香港保险业的结构",q:"按现行规管，下列哪项不属于保险中介人的持牌形式？",o:["直接保险人","个人保险代理人","保险代理机构（公司代理）","业务代表"],a:0,e:"中介人牌照包括个人代理、保险代理机构、业务代表及保险经纪；「直接保险人」是承保风险的保险公司，受规管但属保险人而非中介牌照类别。",tw:{ch:"香港保險業的結構",q:"按現行規管，下列哪項不屬於保險中介人的持牌形式？",o:["直接保險人","個人保險代理人","保險代理機構（公司代理）","業務代表"],e:"中介人牌照包括個人代理、保險代理機構、業務代表及保險經紀；「直接保險人」是承保風險的保險公司，受規管但屬保險人而非中介牌照類別。"}},
{p:1,ch:"香港保险业的结构",q:"保险中介人资格考试（IIQE）的性质是？",o:["保险公司自设的内部考试","「保险中介人质素保证计划」下的资格试，由 VTC 高峰进修学院（PEAK）代表保监局举办","强制大学入学试","证监会举办的考试"],a:1,e:"IIQE 属保险中介人质素保证计划的环节，由职业训练局辖下高峰进修学院代表保监局举办，是成为合资格保险中介人的资格要求之一。",tw:{ch:"香港保險業的結構",q:"保險中介人資格考試（IIQE）的性質是？",o:["保險公司自設的內部考試","「保險中介人質素保證計劃」下的資格試，由 VTC 高峰進修學院（PEAK）代表保監局舉辦","強制大學入學試","證監會舉辦的考試"],e:"IIQE 屬保險中介人質素保證計劃的環節，由職業訓練局轄下高峰進修學院代表保監局舉辦，是成為合資格保險中介人的資格要求之一。"}},
{p:1,ch:"香港保险业的结构",q:"IIQE 卷一的题量与时限是？",o:["50 题 ／ 60 分钟","100 题 ／ 90 分钟","75 题 ／ 120 分钟","100 题 ／ 150 分钟"],a:2,e:"卷一《保险原理及实务》共 75 条选择题、时限 120 分钟；所有试卷合格分数均为 70%。",tw:{ch:"香港保險業的結構",q:"IIQE 卷一的題量與時限是？",o:["50 題 ／ 60 分鐘","100 題 ／ 90 分鐘","75 題 ／ 120 分鐘","100 題 ／ 150 分鐘"],e:"卷一《保險原理及實務》共 75 條選擇題、時限 120 分鐘；所有試卷合格分數均為 70%。"}},
{p:1,ch:"香港保险业的结构",q:"银行透过分行或网络销售保险产品（「银行保险」），有关销售活动？",o:["不受任何规管","只受《银行条例》规管","一律禁止","属受规管的保险分销活动，相关销售人员须为登记／持牌人员并遵从操守守则"],a:3,e:"银行保险是保险分销渠道之一，须符合《保险业条例》对中介人发牌及操守的规管——负责销售的人员须为登记业务代表等，遵守与一般中介人相同的操守要求。",tw:{ch:"香港保險業的結構",q:"銀行透過分行或網絡銷售保險產品（「銀行保險」），有關銷售活動？",o:["不受任何規管","只受《銀行條例》規管","一律禁止","屬受規管的保險分銷活動，相關銷售人員須為登記／持牌人員並遵從操守守則"],e:"銀行保險是保險分銷渠道之一，須符合《保險業條例》對中介人發牌及操守的規管——負責銷售的人員須為登記業務代表等，遵守與一般中介人相同的操守要求。"}},
{p:1,ch:"香港保险业的结构",q:"保险中介人接触客户时，首要应向客户表明什么？",o:["所代表的是保险公司（代理）还是客户（经纪），并说明其中介人身份","自己的佣金比例","个人收入","相关公司股价"],a:0,e:"代理人代表保险公司、经纪代表客户，两者责任与角色不同；中介人须向客户清楚表明身份及所代表的一方，避免误解。",tw:{ch:"香港保險業的結構",q:"保險中介人接觸客户時，首要應向客户表明什麼？",o:["所代表的是保險公司（代理）還是客户（經紀），並說明其中介人身份","自己的佣金比例","個人收入","相關公司股價"],e:"代理人代表保險公司、經紀代表客户，兩者責任與角色不同；中介人須向客户清楚表明身份及所代表的一方，避免誤解。"}},
{p:1,ch:"香港保险业的结构",q:"香港保险市场在规管「本地业务」与「离岸业务」方面的一般做法是？",o:["两者受完全相同规管","主要规管在港经营及以在港保单持有人为对象的业务，离岸业务多由当地规管","离岸业务一律禁止","本地与离岸业务均不受规管"],a:1,e:"香港主要规管在港或从香港经营、以本地保单持有人为对象的业务；离岸（境外）业务一般由其当地规管机构处理，不必然落入香港《保险业条例》的保障范围。",tw:{ch:"香港保險業的結構",q:"香港保險市場在規管「本地業務」與「離岸業務」方面的一般做法是？",o:["兩者受完全相同規管","主要規管在港經營及以在港保單持有人為對象的業務，離岸業務多由當地規管","離岸業務一律禁止","本地與離岸業務均不受規管"],e:"香港主要規管在港或從香港經營、以本地保單持有人為對象的業務；離岸（境外）業務一般由其當地規管機構處理，不必然落入香港《保險業條例》的保障範圍。"}},
{p:1,ch:"保险业的规管架构",q:"关于香港保险业的「保费征费」（Premium Levy），下列哪项正确？",o:["由保险公司从利润中拨出","属一次性税项","按保费的一个百分比征收（自 2021 年起为 0.1%），由保险人向投保人收取后转交保监局","只对投资相连产品征收"],a:2,e:"保费征费按保费的一个百分比向投保人收取、由保险人汇集后转交保监局，使保监局财政独立自给；最终费率自 2021 年起为 0.1%，并设每单上限。",tw:{ch:"保險業的規管架構",q:"關於香港保險業的「保費徵費」（Premium Levy），下列哪項正確？",o:["由保險公司從利潤中撥出","屬一次性税項","按保費的一個百分比徵收（自 2021 年起為 0.1%），由保險人向投保人收取後轉交保監局","只對投資相連產品徵收"],e:"保費徵費按保費的一個百分比向投保人收取、由保險人彙集後轉交保監局，使保監局財政獨立自給；最終費率自 2021 年起為 0.1%，並設每單上限。"}},
{p:1,ch:"保险业的规管架构",q:"「保单持有人保障计划」的主要目的是？",o:["提高保险公司利润","资助保险中介人进修","取代再保险","于保险公司无力偿债时，向保单持有人提供补偿安排"],a:3,e:"保单持有人保障计划旨在当保险人无力偿债时向保单持有人（尤其个人保单）提供保障，维持市场信心，保费征费即其资金来源之一。",tw:{ch:"保險業的規管架構",q:"「保單持有人保障計劃」的主要目的是？",o:["提高保險公司利潤","資助保險中介人進修","取代再保險","於保險公司無力償債時，向保單持有人提供補償安排"],e:"保單持有人保障計劃旨在當保險人無力償債時向保單持有人（尤其個人保單）提供保障，維持市場信心，保費徵費即其資金來源之一。"}},
{p:1,ch:"保险业的规管架构",q:"公众如何核实某保险中介人是否持有效牌照及受哪家保险人委任？",o:["查阅保监局的公开登记册","只能询问中介人本人","并无任何途径","向香港银行公会查询"],a:0,e:"保监局备有保险中介人公开登记册，公众可查核中介人的持牌状态、牌照类别及受委任保险人等资料。",tw:{ch:"保險業的規管架構",q:"公眾如何核實某保險中介人是否持有效牌照及受哪家保險人委任？",o:["查閲保監局的公開登記冊","只能詢問中介人本人","並無任何途徑","向香港銀行公會查詢"],e:"保監局備有保險中介人公開登記冊，公眾可查核中介人的持牌狀態、牌照類別及受委任保險人等資料。"}},
{p:1,ch:"保险业的规管架构",q:"保险中介人的发牌与规管，现由哪个机构负责？",o:["香港保险业联会","保险业监管局（保监局）","消费者委员会","香港银行公会"],a:1,e:"中介人发牌与规管由保监局直接负责，取代以往业界自律规管机构，实现与保险公司的统一规管。",tw:{ch:"保險業的規管架構",q:"保險中介人的發牌與規管，現由哪個機構負責？",o:["香港保險業聯會","保險業監管局（保監局）","消費者委員會","香港銀行公會"],e:"中介人發牌與規管由保監局直接負責，取代以往業界自律規管機構，實現與保險公司的統一規管。"}},
{p:1,ch:"保险业的规管架构",q:"关于 IIQE 的合格分数，下列哪项正确？",o:["60 分合格","50 分合格","所有试卷的合格分数均为 70%","依报考人数浮动"],a:2,e:"IIQE 各卷合格分数均为 70%；卷一 75 题、卷三 50 题，须达该分数方合资格。",tw:{ch:"保險業的規管架構",q:"關於 IIQE 的合格分數，下列哪項正確？",o:["60 分合格","50 分合格","所有試卷的合格分數均為 70%","依報考人數浮動"],e:"IIQE 各卷合格分數均為 70%；卷一 75 題、卷三 50 題，須達該分數方合資格。"}},
{p:1,ch:"保险业的规管架构",q:"保险公司作为受反洗钱法例规管的「指定」机构，其反洗钱责任包括？",o:["只对逾百万保单作审查","无须保存纪录","只检查现金交易","建立客户尽职审查、持续监察、纪录保存及可疑交易申报等制度"],a:3,e:"受《打击洗钱及恐怖分子资金筹集条例》规管，保险人及中介须建立客户尽职审查、持续监察、纪录保存及向联合财富情报组报告可疑交易等制度。",tw:{ch:"保險業的規管架構",q:"保險公司作為受反洗錢法例規管的「指定」機構，其反洗錢責任包括？",o:["只對逾百萬保單作審查","無須保存紀錄","只檢查現金交易","建立客户盡職審查、持續監察、紀錄保存及可疑交易申報等制度"],e:"受《打擊洗錢及恐怖分子資金籌集條例》規管，保險人及中介須建立客户盡職審查、持續監察、紀錄保存及向聯合財富情報組報告可疑交易等制度。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人发现客户交易可能涉及洗钱或恐怖分子资金筹集，正确做法是？",o:["依程序向联合财富情报组提交可疑交易报告","置之不理","直接拒绝并告知客户原因","通知同业以免其受骗"],a:0,e:"发现可疑交易应依程序向联合财富情报组（JFIU）提交可疑交易报告；妥为申报可获法定保护，但不得向客户「通风报信」（tipping off）。",tw:{ch:"職業道德及其他有關問題",q:"中介人發現客户交易可能涉及洗錢或恐怖分子資金籌集，正確做法是？",o:["依程序向聯合財富情報組提交可疑交易報告","置之不理","直接拒絕並告知客户原因","通知同業以免其受騙"],e:"發現可疑交易應依程序向聯合財富情報組（JFIU）提交可疑交易報告；妥為申報可獲法定保護，但不得向客户「通風報信」（tipping off）。"}},
{p:1,ch:"职业道德及其他有关问题",q:"《防止贿赂条例》下，保险中介人为促成业务而向客户提供或收受不正当利益，后果是？",o:["属正常商业行为","可能构成贿赂罪行，可被刑事检控并受纪律处分","只须补缴税款","由保险公司内部自行决定"],a:1,e:"中介人收受或提供回佣、礼物等不正当利益以影响业务，可触犯《防止贿赂条例》并被检控，同时违反操守守则的「诚实及持正」原则。",tw:{ch:"職業道德及其他有關問題",q:"《防止賄賂條例》下，保險中介人為促成業務而向客户提供或收受不正當利益，後果是？",o:["屬正常商業行為","可能構成賄賂罪行，可被刑事檢控並受紀律處分","只須補繳税款","由保險公司內部自行決定"],e:"中介人收受或提供回佣、禮物等不正當利益以影響業務，可觸犯《防止賄賂條例》並被檢控，同時違反操守守則的「誠實及持正」原則。"}},
{p:1,ch:"职业道德及其他有关问题",q:"保险投诉局主要处理哪类投诉？",o:["保险公司的投资决策","中介人的刑事罪行","个人保单持有人与保险公司之间的合约纠纷","强积金供款安排"],a:2,e:"保险投诉局以调解／仲裁方式处理个人保单持有人与保险人的合约纠纷，并设有申诉金额上限；涉及中介人操守的投诉则属保监局范畴。",tw:{ch:"職業道德及其他有關問題",q:"保險投訴局主要處理哪類投訴？",o:["保險公司的投資決策","中介人的刑事罪行","個人保單持有人與保險公司之間的合約糾紛","強積金供款安排"],e:"保險投訴局以調解／仲裁方式處理個人保單持有人與保險人的合約糾紛，並設有申訴金額上限；涉及中介人操守的投訴則屬保監局範疇。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人应在何时向客户披露潜在的利益冲突（如仅某产品佣金较高）？",o:["促成交易之后","客户投诉之后","无须披露","提出建议或促成交易之前"],a:3,e:"利益冲突应在建议或促成交易前向客户披露，让客户在知情下作决定，符合「客户为先」及「诚实及持正」原则。",tw:{ch:"職業道德及其他有關問題",q:"中介人應在何時向客户披露潛在的利益衝突（如僅某產品佣金較高）？",o:["促成交易之後","客户投訴之後","無須披露","提出建議或促成交易之前"],e:"利益衝突應在建議或促成交易前向客户披露，讓客户在知情下作決定，符合「客户為先」及「誠實及持正」原則。"}},
{p:1,ch:"职业道德及其他有关问题",q:"中介人把客户的个人资料出售予第三方作市场推广，正确前提是？",o:["已获客户同意，或符合该资料收集时声明的用途","无须任何前提","只须事后口头通知","只须向公司报告"],a:0,e:"个人资料只可用于收集时声明的用途；转作其他用途（如出售、对外推广）须取得客户同意，否则违反《个人资料（私隐）条例》。",tw:{ch:"職業道德及其他有關問題",q:"中介人把客户的個人資料出售予第三方作市場推廣，正確前提是？",o:["已獲客户同意，或符合該資料收集時聲明的用途","無須任何前提","只須事後口頭通知","只須向公司報告"],e:"個人資料只可用於收集時聲明的用途；轉作其他用途（如出售、對外推廣）須取得客户同意，否則違反《個人資料（私隱）條例》。"}},
{p:1,ch:"职业道德及其他有关问题",q:"面对不熟悉产品或以不同语言沟通的客户，中介人的正确做法是？",o:["尽快签单以节省时间","以客户能理解的语文清楚解释，确保其了解条款、费用及风险","只提供英文文件","由客户自行阅读全部文件"],a:1,e:"中介人有责任以客户理解的语文清楚说明保单内容、费用及风险，确保「公平对待客户」，避免因资讯不对称作出的购买决定。",tw:{ch:"職業道德及其他有關問題",q:"面對不熟悉產品或以不同語言溝通的客户，中介人的正確做法是？",o:["儘快簽單以節省時間","以客户能理解的語文清楚解釋，確保其瞭解條款、費用及風險","只提供英文文件","由客户自行閲讀全部文件"],e:"中介人有責任以客户理解的語文清楚說明保單內容、費用及風險，確保「公平對待客户」，避免因資訊不對稱作出的購買決定。"}},
{p:3,ch:"人寿保险简介",q:"其他条件不变，若保险公司的「预定利率（投资回报假设）」上升，寿险保单的净保费会？",o:["上升","不变","下降","先升后跌"],a:2,e:"预定利率上升意味着保费的投资收益更高、可抵销更多保障成本，故净保费可相应下降；利率下降则净保费上升。",tw:{ch:"人壽保險簡介",q:"其他條件不變，若保險公司的「預定利率（投資回報假設）」上升，壽險保單的淨保費會？",o:["上升","不變","下降","先升後跌"],e:"預定利率上升意味着保費的投資收益更高、可抵銷更多保障成本，故淨保費可相應下降；利率下降則淨保費上升。"}},
{p:3,ch:"人寿保险简介",q:"其他条件不变，若某风险组别的预期死亡率上升，其寿险净保费将？",o:["下降","不变","无法确定","上升"],a:3,e:"死亡率上升代表预期赔付增加，净保费须相应提高以维持偿付；反之死亡率下降则保费降低。",tw:{ch:"人壽保險簡介",q:"其他條件不變，若某風險組別的預期死亡率上升，其壽險淨保費將？",o:["下降","不變","無法確定","上升"],e:"死亡率上升代表預期賠付增加，淨保費須相應提高以維持償付；反之死亡率下降則保費降低。"}},
{p:3,ch:"人寿保险简介",q:"一般而言，以下列哪个年龄以同一保额投保，保费（每万元保额）最高？",o:["60 岁","20 岁","35 岁","年龄不影响保费"],a:0,e:"死亡率随年龄上升，故年龄越大（60 岁）投保，保障成本越高、保费越高；这与「均衡保费」把晚年的高成本摊于早年缴付并不矛盾。",tw:{ch:"人壽保險簡介",q:"一般而言，以下列哪個年齡以同一保額投保，保費（每萬元保額）最高？",o:["60 歲","20 歲","35 歲","年齡不影響保費"],e:"死亡率隨年齡上升，故年齡越大（60 歲）投保，保障成本越高、保費越高；這與「均衡保費」把晚年的高成本攤於早年繳付並不矛盾。"}},
{p:3,ch:"人寿保险简介",q:"投保人对自己的生命所具有的可保利益是？",o:["以年收入为限","无限","以保额为限","以净资产为限"],a:1,e:"投保人对自己（及配偶、未成年子女）的生命拥有无限可保利益；对其他血缘关系（如堂表亲）则并无法定可保利益。",tw:{ch:"人壽保險簡介",q:"投保人對自己的生命所具有的可保利益是？",o:["以年收入為限","無限","以保額為限","以淨資產為限"],e:"投保人對自己（及配偶、未成年子女）的生命擁有無限可保利益；對其他血緣關係（如堂表親）則並無法定可保利益。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「联合寿险」（Joint Life）的给付条件是？",o:["所有受保人均去世才给付","期满才给付","首名受保人死亡时给付，保单随即终止","按伤残程度给付"],a:2,e:"联合寿险覆盖两名（或以上）受保人，于首名受保人死亡时给付保险金、保单随即终止；常见于夫妇按揭「首亡偿付」安排。",tw:{ch:"人壽保險及年金的種類",q:"「聯合壽險」（Joint Life）的給付條件是？",o:["所有受保人均去世才給付","期滿才給付","首名受保人死亡時給付，保單隨即終止","按傷殘程度給付"],e:"聯合壽險覆蓋兩名（或以上）受保人，於首名受保人死亡時給付保險金、保單隨即終止；常見於夫婦按揭「首亡償付」安排。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「最后生存者寿险」（Survivorship）于何时给付？",o:["首名受保人死亡时","期满时","任一受保人伤残时","最后一名受保人死亡时"],a:3,e:"最后生存者寿险于最后一名受保人死亡时才给付，常用于遗产策划及缴付遗产开支，保费较以单一生命投保的负担为低。",tw:{ch:"人壽保險及年金的種類",q:"「最後生存者壽險」（Survivorship）於何時給付？",o:["首名受保人死亡時","期滿時","任一受保人傷殘時","最後一名受保人死亡時"],e:"最後生存者壽險於最後一名受保人死亡時才給付，常用於遺產策劃及繳付遺產開支，保費較以單一生命投保的負擔為低。"}},
{p:3,ch:"人寿保险及年金的种类",q:"享有「可续保／可转换」权利的定期寿险，其保费与无此权利的同类保单相比一般为？",o:["较高","较低","相同","视乎性别"],a:0,e:"可续保及可转换权为投保人提供免体检的弹性（对冲健康转差风险），代价是保费通常高于无此权利的定期保单。",tw:{ch:"人壽保險及年金的種類",q:"享有「可續保／可轉換」權利的定期壽險，其保費與無此權利的同類保單相比一般為？",o:["較高","較低","相同","視乎性別"],e:"可續保及可轉換權為投保人提供免體檢的彈性（對沖健康轉差風險），代價是保費通常高於無此權利的定期保單。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「终身年金」（Life Annuity）的给付方式是？",o:["仅于固定年期内给付","以领取人生存为条件，给付至其身故为止","与领取人生死无关","期满一次过给付"],a:1,e:"终身年金（生命年金）只要领取人生存即持续给付至身故，用于对冲「长寿风险」；与固定年期、与生死无关的确定年金不同。",tw:{ch:"人壽保險及年金的種類",q:"「終身年金」（Life Annuity）的給付方式是？",o:["僅於固定年期內給付","以領取人生存為條件，給付至其身故為止","與領取人生死無關","期滿一次過給付"],e:"終身年金（生命年金）只要領取人生存即持續給付至身故，用於對沖「長壽風險」；與固定年期、與生死無關的確定年金不同。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「住院现金」附约的给付特点是？",o:["按实际医疗开支实报实销","只赔偿手术费","因住院按日给付固定现金（津贴），与实际费用无关","到期满才给付"],a:2,e:"住院现金附约按住院日数给付定额现金津贴，与实际医疗支出无关，用以补偿住院期间的收入损失或杂项开支，属利益（定额）性质。",tw:{ch:"保險利益附約及其他產品",q:"「住院現金」附約的給付特點是？",o:["按實際醫療開支實報實銷","只賠償手術費","因住院按日給付固定現金（津貼），與實際費用無關","到期滿才給付"],e:"住院現金附約按住院日數給付定額現金津貼，與實際醫療支出無關，用以補償住院期間的收入損失或雜項開支，屬利益（定額）性質。"}},
{p:3,ch:"保险利益附约及其他产品",q:"与「住院及手术（医疗）附约」的实报实销相比，「住院现金」附约的根本分别是？",o:["两者相同","医疗附约无须缴费","现金附约只保意外","现金附约定额给付且与费用无关；医疗附约按实际合理费用补偿"],a:3,e:"医疗附约属弥偿、按实际费用补偿；住院现金附约定额给付、不论实际花费，可弥补收入损失，两者性质与用途不同。",tw:{ch:"保險利益附約及其他產品",q:"與「住院及手術（醫療）附約」的實報實銷相比，「住院現金」附約的根本分別是？",o:["兩者相同","醫療附約無須繳費","現金附約只保意外","現金附約定額給付且與費用無關；醫療附約按實際合理費用補償"],e:"醫療附約屬彌償、按實際費用補償；住院現金附約定額給付、不論實際花費，可彌補收入損失，兩者性質與用途不同。"}},
{p:3,ch:"保险利益附约及其他产品",q:"下列对「豁免保费」与「残疾收入」两种附约的比较，哪项正确？",o:["豁免保费是免除续保保费以维持保单；残疾收入是在伤残期间提供现金（收入）给付","两者均提供现金收入","两者完全相同","豁免保费提供现金、残疾收入免除保费"],a:0,e:"豁免保费附约在投保人伤残后免除其续保保费、保单持续有效；残疾收入附约则在伤残期间定期给付现金以补偿收入损失，两者目的不同。",tw:{ch:"保險利益附約及其他產品",q:"下列對「豁免保費」與「殘疾收入」兩種附約的比較，哪項正確？",o:["豁免保費是免除續保保費以維持保單；殘疾收入是在傷殘期間提供現金（收入）給付","兩者均提供現金收入","兩者完全相同","豁免保費提供現金、殘疾收入免除保費"],e:"豁免保費附約在投保人傷殘後免除其續保保費、保單持續有效；殘疾收入附約則在傷殘期間定期給付現金以補償收入損失，兩者目的不同。"}},
{p:3,ch:"保险利益附约及其他产品",q:"依照「保证可保利益」（GI）附约增购保险，新购部分的保费按什么厘定？",o:["原保单投保时的费率","行使选择权时的到达年龄","固定不变","免费的"],a:1,e:"GI 附约免去可保证明，但增购部分的保费按行使权利时的到达年龄厘定，故并非沿用投保当时的较低费率。",tw:{ch:"保險利益附約及其他產品",q:"依照「保證可保利益」（GI）附約增購保險，新購部分的保費按什麼釐定？",o:["原保單投保時的費率","行使選擇權時的到達年齡","固定不變","免費的"],e:"GI 附約免去可保證明，但增購部分的保費按行使權利時的到達年齡釐定，故並非沿用投保當時的較低費率。"}},
{p:3,ch:"阐释人寿保险单",q:"「不可争议条款」到期（如两年）后，下列哪种争议保险人仍可提出？",o:["一般的健康误述","职业误述","年龄或性别的误报","任何误述"],a:2,e:"不可争议条款通常不适用于年龄／性别的误报——保费按年龄厘定，误报会实质影响费率，故无论何时发现，保险人都可按正确年龄调整保额或保费；欺诈亦不获保障。",tw:{ch:"闡釋人壽保險單",q:"「不可爭議條款」到期（如兩年）後，下列哪種爭議保險人仍可提出？",o:["一般的健康誤述","職業誤述","年齡或性別的誤報","任何誤述"],e:"不可爭議條款通常不適用於年齡／性別的誤報——保費按年齡釐定，誤報會實質影響費率，故無論何時發現，保險人都可按正確年齡調整保額或保費；欺詐亦不獲保障。"}},
{p:3,ch:"阐释人寿保险单",q:"受保人死亡后才发现其投保时误报年龄（申报较小），保险金一般如何处理？",o:["维持原保额不变","全额拒赔","加倍赔付","按「实缴保费与按正确年龄应缴保费」的比例调减保险金"],a:3,e:"死亡索偿时发现年龄／性别误报，最常见做法是按比例调减保额：实际保额 ＝ 原保额 ×（实缴保费 ÷ 按正确年龄应缴保费），以还原正确的对价关系。",tw:{ch:"闡釋人壽保險單",q:"受保人死亡後才發現其投保時誤報年齡（申報較小），保險金一般如何處理？",o:["維持原保額不變","全額拒賠","加倍賠付","按「實繳保費與按正確年齡應繳保費」的比例調減保險金"],e:"死亡索償時發現年齡／性別誤報，最常見做法是按比例調減保額：實際保額 ＝ 原保額 ×（實繳保費 ÷ 按正確年齡應繳保費），以還原正確的對價關係。"}},
{p:3,ch:"阐释人寿保险单",q:"受保人与受益人在同一事故中身故、无法判定死亡先后，保险金一般？",o:["视为受益人先于受保人死亡，保险金转归保单所有人或受保人遗产","归受益人的继承人","归保险公司","由法院平均分配"],a:0,e:"依「同时死亡」条款或法律推定，无法判定先后时多视为受益人先死，保险金按保单处理，受益人的继承人不能直接收取，以免理赔对象不明。",tw:{ch:"闡釋人壽保險單",q:"受保人與受益人在同一事故中身故、無法判定死亡先後，保險金一般？",o:["視為受益人先於受保人死亡，保險金轉歸保單所有人或受保人遺產","歸受益人的繼承人","歸保險公司","由法院平均分配"],e:"依「同時死亡」條款或法律推定，無法判定先後時多視為受益人先死，保險金按保單處理，受益人的繼承人不能直接收取，以免理賠對象不明。"}},
{p:3,ch:"阐释人寿保险单",q:"「绝对转让」人寿保单的后果是？",o:["保单权益暂质押给债权人","保单的全部权益无条件转给承让人，承让人成为新的保单所有人","保险金自动捐出","保单自动失效"],a:1,e:"绝对转让把保单完整权益（包括退保、受益人指定及死亡保险金权利）无条件转移，承让人成为新保单所有人；与仅担保贷款的「抵押转让」不同。",tw:{ch:"闡釋人壽保險單",q:"「絕對轉讓」人壽保單的後果是？",o:["保單權益暫質押給債權人","保單的全部權益無條件轉給承讓人，承讓人成為新的保單所有人","保險金自動捐出","保單自動失效"],e:"絕對轉讓把保單完整權益（包括退保、受益人指定及死亡保險金權利）無條件轉移，承讓人成為新保單所有人；與僅擔保貸款的「抵押轉讓」不同。"}},
{p:3,ch:"人寿保险程序",q:"保险人把新的人寿保单交付客户时，通常须一并确认？",o:["客户的投资收益","客户的社会地位","客户已理解保单权益、冷静期条款及退保程序","客户的年龄"],a:2,e:"交付新保单时须确保客户获取并理解保单文件、冷静期及权益说明（文件印有冷静期届满日），以保障客户在冷静期内可重新考虑，属销售程序的基本要求。",tw:{ch:"人壽保險程序",q:"保險人把新的人壽保單交付客户時，通常須一併確認？",o:["客户的投資收益","客户的社會地位","客户已理解保單權益、冷靜期條款及退保程序","客户的年齡"],e:"交付新保單時須確保客户獲取並理解保單文件、冷靜期及權益說明（文件印有冷靜期屆滿日），以保障客户在冷靜期內可重新考慮，屬銷售程序的基本要求。"}},
{p:3,ch:"人寿保险程序",q:"进行「转保」（以新保单取代现有保单）时，为保障客户通常须提供？",o:["股票交收单","银行贷款合约","出入境证明","列明新旧保单比较及客户权利的声明文件（如《客户保障声明书》）"],a:3,e:"转保可能令客户蒙受旧保单的退保损失，故须提供清晰的比较说明及《客户保障声明书》等文件，让客户知悉利弊后决定，防止「诱导转保」。",tw:{ch:"人壽保險程序",q:"進行「轉保」（以新保單取代現有保單）時，為保障客户通常須提供？",o:["股票交收單","銀行貸款合約","出入境證明","列明新舊保單比較及客户權利的聲明文件（如《客户保障聲明書》）"],e:"轉保可能令客户蒙受舊保單的退保損失，故須提供清晰的比較說明及《客户保障聲明書》等文件，讓客户知悉利弊後決定，防止「誘導轉保」。"}},
{p:3,ch:"人寿保险程序",q:"从事高风险职业（如高空作业、矿工）的投保人，核保一般会？",o:["附加保费、加设除外或拒保，因职业令死亡率上升","无条件按标准费率承保","自动豁免保费","只影响红利"],a:0,e:"职业属实质危险因素，高风险职业者申报后可被附加保费、加列除外责任或拒保；如实申报职业是投保人的披露义务。",tw:{ch:"人壽保險程序",q:"從事高風險職業（如高空作業、礦工）的投保人，核保一般會？",o:["附加保費、加設除外或拒保，因職業令死亡率上升","無條件按標準費率承保","自動豁免保費","隻影響紅利"],e:"職業屬實質危險因素，高風險職業者申報後可被附加保費、加列除外責任或拒保；如實申報職業是投保人的披露義務。"}},
{p:3,ch:"人寿保险程序",q:"保单持有人提交虚假资料提呈欺诈性索偿，保险人一般可？",o:["照常赔偿","拒赔、撤销保单，并可能向执法机构举报","只作口头警告","减少一半赔偿"],a:1,e:"欺诈性索偿违反最大诚信，保险人可拒绝赔偿、撤销保单，个案或转交执法机构调查；诚实申报与如实提交证明是保单持有人的义务。",tw:{ch:"人壽保險程序",q:"保單持有人提交虛假資料提呈欺詐性索償，保險人一般可？",o:["照常賠償","拒賠、撤銷保單，並可能向執法機構舉報","只作口頭警告","減少一半賠償"],e:"欺詐性索償違反最大誠信，保險人可拒絕賠償、撤銷保單，個案或轉交執法機構調查；誠實申報與如實提交證明是保單持有人的義務。"}},
{p:1,ch:"风险与保险",q:"「一项与潜在损失有关的不确定性」是描述:",o:["风险","一种可能出现的收益或损失","可保的风险而已","任何预期以外之事件,不论结果是怎样"],a:0,e:"风险的标准定义就是「与潜在损失有关的不确定性」，这是保险可保风险的核心理念。其余选项或引入收益概念、或把范围限定为「可保风险而已」、或过于宽泛的不确定事件，均与这一定义不符。",src:1,tw:{ch:"風險與保險",q:"「一項與潛在損失有關的不確定性」是描述：",o:["風險","一種可能出現的收益或損失","可保的風險而已","任何預期以外之事件,不論結果是怎樣"],e:"風險的標準定義就是「與潛在損失有關的不確定性」，這是保險可保風險的核心理念。其餘選項或引入收益概念、或把範圍限定為「可保風險而已」、或過於寬泛的不確定事件，均與這一定義不符。"}},
{p:1,ch:"风险与保险",q:"「保险」与「风险」之间的关系是如何?",o:["有些风险(不是所有类型的风险)是可保的","有着保险的保障, 所有财务上的损失都是保险人的责任","应付风险的唯一方法就是保险","所有风险都是可保的"],a:0,e:"并非所有风险都可保，只有符合特定条件（如纯粹风险、损失可衡量）的风险才能获得保险保障，故「有些风险是可保的」正确。其余选项称所有财务损失都由保险人负责、只有保险可应付风险或所有风险均能承保，均属绝对化的错误说法。",src:1,tw:{ch:"風險與保險",q:"「保險」與「風險」之間的關係是如何?",o:["有些風險(不是所有類型的風險)是可保的","有着保險的保障, 所有財務上的損失都是保險人的責任","應付風險的唯一方法就是保險","所有風險都是可保的"],e:"並非所有風險都可保，只有符合特定條件（如純粹風險、損失可衡量）的風險才能獲得保險保障，故「有些風險是可保的」正確。其餘選項稱所有財務損失都由保險人負責、只有保險可應付風險或所有風險均能承保，均屬絕對化的錯誤說法。"}},
{p:1,ch:"风险与保险",q:"「投机风险」的定义:",o:["一个有收益及损失的可能的风险","一个商业风险","一个只有收益但没有损失的可能的风险","一份可使无效的合约"],a:0,e:"投机风险同时具有获益与损失两种可能（如投资、赌博），区别于只有损失机会的纯粹风险。其余选项或把投机与商业风险混同、或说只有收益没有损失、或把风险与合约效力混淆，均不正确。",src:1,tw:{ch:"風險與保險",q:"「投機風險」的定義：",o:["一個有收益及損失的可能的風險","一個商業風險","一個只有收益但沒有損失的可能的風險","一份可使無效的合約"],e:"投機風險同時具有獲益與損失兩種可能（如投資、賭博），區別於只有損失機會的純粹風險。其餘選項或把投機與商業風險混同、或說只有收益沒有損失、或把風險與合約效力混淆，均不正確。"}},
{p:1,ch:"风险与保险",q:"「纯粹风险」的定义:",o:["一个永久不可保的风险","一份保险而保单持有人抱着诚实的态度","一项只有损失而不具收益的风险","一个具有灾难性损失的风险"],a:2,e:"纯粹风险指只有损失可能而无获益机会的风险（如火灾、意外），是保险主要承保的对象。其余选项的「永久不可保」「具灾难性损失」并非定义要件，「保单持有人诚实态度」更与定义无关。",src:1,tw:{ch:"風險與保險",q:"「純粹風險」的定義：",o:["一個永久不可保的風險","一份保險而保單持有人抱着誠實的態度","一項只有損失而不具收益的風險","一個具有災難性損失的風險"],e:"純粹風險指只有損失可能而無獲益機會的風險（如火災、意外），是保險主要承保的對象。其餘選項的「永久不可保」「具災難性損失」並非定義要件，「保單持有人誠實態度」更與定義無關。"}},
{p:1,ch:"风险与保险",q:"「风险」:",o:["这一个术语是保险从业员专用的","可以指受保单保障的损失成因","在任何情况下均解作一项潜在收益的不确定性","在任何情况下均解作一项潜在损失的不确定性"],a:1,e:"在保险语境中，「风险」可指受保单保障的损失成因，也可指受保的财物或人身。其余选项或说它是保险从业员专用术语，或把风险片面限定为收益、损失的不确定性，均不够全面。",src:1,tw:{ch:"風險與保險",q:"「風險」：",o:["這一個術語是保險從業員專用的","可以指受保單保障的損失成因","在任何情況下均解作一項潛在收益的不確定性","在任何情況下均解作一項潛在損失的不確定性"],e:"在保險語境中，「風險」可指受保單保障的損失成因，也可指受保的財物或人身。其餘選項或說它是保險從業員專用術語，或把風險片面限定為收益、損失的不確定性，均不夠全面。"}},
{p:1,ch:"风险与保险",q:"「风险」一词:",o:["保险中只有一个意思","任何情况都是损失的不确定性","一半情况都是损失的不确定性","可能是指导致损失的成因 (指受保原因)"],a:3,e:"「风险」一词具有多重含义，其中之一即指导致损失的成因（受保原因）。其余选项称其只有一个意思、或任何／一半情况都是损失的不确定性，忽视了这一多重含义。",src:1,tw:{ch:"風險與保險",q:"「風險」一詞:",o:["保險中只有一個意思","任何情況都是損失的不確定性","一半情況都是損失的不確定性","可能是指導致損失的成因 (指受保原因)"],e:"「風險」一詞具有多重含義，其中之一即指導致損失的成因（受保原因）。其餘選項稱其只有一個意思、或任何／一半情況都是損失的不確定性，忽視了這一多重含義。"}},
{p:1,ch:"风险与保险",q:"一般学术性的管理风险上,除风险识别及应对那些对某些机构构成威胁的风险 外,还有一项亦为重要:",o:["商讨计策","量化","减轻风险","防范化"],a:1,e:"风险管理的标准步骤为识别、量化与应对风险，题干已列出识别与应对，所缺少的正是「量化」。商讨计策、减轻风险、防范化均不是标准三大步骤之一。",src:1,tw:{ch:"風險與保險",q:"一般學術性的管理風險上，除風險識別及應對那些對某些機構構成威脅的風險 外，還有一項亦為重要：",o:["商討計策","量化","減輕風險","防範化"],e:"風險管理的標準步驟為識別、量化與應對風險，題幹已列出識別與應對，所缺少的正是「量化」。商討計策、減輕風險、防範化均不是標準三大步驟之一。"}},
{p:1,ch:"风险与保险",q:"下列哪三项有关风险管理的陈述是正确的? i. 可能涉及投机风险和纯粹风险 ii. 作为一门独立科学,它涉及的问题较保险广泛 iii. 以保险人角度看,它很大程度涉及受保风险 iv. 以被保险人角度看,它只涉及不受保的风险",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:0,e:"风险管理涉及投机与纯粹两类风险（i），作为独立学科所涉问题较保险更广（ii），而且从保险人角度多聚焦于受保风险（iii），三项均正确。iv 称被保险人角度只涉及不可保风险，与事实不符，故排除。",src:1,tw:{ch:"風險與保險",q:"下列哪三項有關風險管理的陳述是正確的？ i. 可能涉及投機風險和純粹風險 ii. 作為一門獨立科學，它涉及的問題較保險廣泛 iii. 以保險人角度看，它很大程度涉及受保風險 iv. 以被保險人角度看，它只涉及不受保的風險",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"風險管理涉及投機與純粹兩類風險（i），作為獨立學科所涉問題較保險更廣（ii），而且從保險人角度多聚焦於受保風險（iii），三項均正確。iv 稱被保險人角度只涉及不可保風險，與事實不符，故排除。"}},
{p:1,ch:"风险与保险",q:"下列哪些是「纯粹风险」? i. 建筑物在空难中被摧毁 ii. 开发海洋钻井技术 iii. 建筑物被意外引起的火灾烧毁 iv. 一幅有价值的名画在博物馆被盗",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:2,e:"建筑物在空难中被毁、意外火灾烧毁、名画在博物馆被盗，都只有损失而没有获益机会，属纯粹风险。开发海洋钻井技术是有盈有亏的投机活动，故应排除 ii。",src:1,tw:{ch:"風險與保險",q:"下列哪些是「純粹風險」？ i. 建築物在空難中被摧毀 ii. 開發海洋鑽井技術 iii. 建築物被意外引起的火災燒毁 iv. 一幅有價值的名畫在博物館被盜",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],e:"建築物在空難中被毀、意外火災燒燬、名畫在博物館被盜，都只有損失而沒有獲益機會，屬純粹風險。開發海洋鑽井技術是有盈有虧的投機活動，故應排除 ii。"}},
{p:1,ch:"风险与保险",q:"下列哪些是「纯粹风险」? i. 汽车损毁 ii. 买入公司股票 iii. 火警中烧毁的建筑物 iv. 从博物馆遭盗的名画",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:2,e:"汽车损毁、火警烧毁建筑物、名画被盗均只有损失机会，属纯粹风险。买入公司股票可赚可蚀，属投机风险，故应选 i、iii、iv。",src:1,tw:{ch:"風險與保險",q:"下列哪些是「純粹風險」？ i. 汽車損毀 ii. 買入公司股票 iii. 火警中燒毁的建築物 iv. 從博物館遭盜的名畫",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],e:"汽車損毀、火警燒燬建築物、名畫被盜均只有損失機會，屬純粹風險。買入公司股票可賺可蝕，屬投機風險，故應選 i、iii、iv。"}},
{p:1,ch:"风险与保险",q:"下列哪些是可保风险? i. 纯粹风险 ii. 特定风险 iii. 基本风险 iv. 投机风险",o:["i, ii","i, iii","ii, iii","ii, iii, iv"],a:0,e:"可保风险通常须是纯粹风险及特定风险：前者只有损失机会，后者影响有限且较个体化，便于精算与承保。基本风险影响广泛（如战争），投机风险有获益可能，一般均不可保。",src:1,tw:{ch:"風險與保險",q:"下列哪些是可保風險？ i. 純粹風險 ii. 特定風險 iii. 基本風險 iv. 投機風險",o:["i, ii","i, iii","ii, iii","ii, iii, iv"],e:"可保風險通常須是純粹風險及特定風險：前者只有損失機會，後者影響有限且較個體化，便於精算與承保。基本風險影響廣泛（如戰爭），投機風險有獲益可能，一般均不可保。"}},
{p:1,ch:"风险与保险",q:"下列哪项或哪些可以分类为投机风险? i. 恒生指数股票的波动 ii. 禽流感疫苗的研究及发展 iii. 一个赌场被火灾损坏的风险 iv. 在沙田马场举行的一场赛马的结果",o:["iii","i, ii","i, ii, iv","i, ii, iii, iv"],a:2,e:"恒生指数波动、禽流感疫苗研发、赛马结果均有赚或蚀两种可能，属投机风险。赌场被火灾损坏只有损失机会，属纯粹风险，故应排除 iii。",src:1,tw:{ch:"風險與保險",q:"下列哪項或哪些可以分類為投機風險？ i. 恆生指數股票的波動 ii. 禽流感疫苗的研究及發展 iii. 一個賭場被火災損壞的風險 iv. 在沙田馬場舉行的一場賽馬的結果",o:["iii","i, ii","i, ii, iv","i, ii, iii, iv"],e:"恒生指數波動、禽流感疫苗研發、賽馬結果均有賺或蝕兩種可能，屬投機風險。賭場被火災損壞只有損失機會，屬純粹風險，故應排除 iii。"}},
{p:1,ch:"风险与保险",q:"下列哪项有关风险管理的句子是正确的?",o:["在研究的独立范畴中,风险管理指投资及其他投机风险","在银行领域中,风险管理是指识别,量化及应对 那些对某些机构构成威胁的风险","对保险人而言,风险管理可能只针对纯粹风险","以上各项皆不正确"],a:2,e:"保险人在运用「风险管理」时，通常将其收窄至纯粹（受保）风险，故该项正确。独立学科范畴中的风险管理兼涉纯粹与投机风险而非仅投机，银行领域则侧重于识别、量化及应对的投资／投机风险，故其余选项均有误。",src:1,tw:{ch:"風險與保險",q:"下列哪項有關風險管理的句子是正確的？",o:["在研究的獨立範疇中，風險管理指投資及其他投機風險","在銀行領域中，風險管理是指識別，量化及應對 那些對某些機構構成威脅的風險","對保險人而言，風險管理可能只針對純粹風險","以上各項皆不正確"],e:"保險人在運用「風險管理」時，通常將其收窄至純粹（受保）風險，故該項正確。獨立學科範疇中的風險管理兼涉純粹與投機風險而非僅投機，銀行領域則側重於識別、量化及應對的投資／投機風險，故其餘選項均有誤。"}},
{p:1,ch:"风险与保险",q:"于识别、量化和应付的方法中,作为一门独立的学科及研究的范围,这是称为 :",o:["风险融资","风险转移","会计成本","风险管理"],a:3,e:"「识别、量化及应付风险」正是风险管理的三大步骤，故答案即风险管理。风险融资、风险转移只是应付手段之一，会计成本则与题干无关。",src:1,tw:{ch:"風險與保險",q:"於識別、量化和應付的方法中，作為一門獨立的學科及研究的範圍，這是稱為 ：",o:["風險融資","風險轉移","會計成本","風險管理"],e:"「識別、量化及應付風險」正是風險管理的三大步驟，故答案即風險管理。風險融資、風險轉移只是應付手段之一，會計成本則與題幹無關。"}},
{p:1,ch:"风险与保险",q:"什么是保险所带出的基本功能/好处?",o:["为投保人作出感受上的安慰","替投保人作出明智的财务选择","为投保人作出金钱上的赔偿","以上各项皆是"],a:2,e:"保险的基本功能是向投保人提供金钱上的赔偿，透过风险转移填补其财务损失。感受上的安慰只是附带心理效果，替投保人作财务选择并非保险的功能，故均不选。",src:1,tw:{ch:"風險與保險",q:"什麼是保險所帶出的基本功能/好處？",o:["為投保人作出感受上的安慰","替投保人作出明智的財務選擇","為投保人作出金錢上的賠償","以上各項皆是"],e:"保險的基本功能是向投保人提供金錢上的賠償，透過風險轉移填補其財務損失。感受上的安慰只是附帶心理效果，替投保人作財務選擇並非保險的功能，故均不選。"}},
{p:1,ch:"风险与保险",q:"从保险从业员的角度,风险一词是指: i. 所保的危险 ii. 承保的财物 iii. 保险人承保的人身 iv. 一项与潜在损失有关的不确定性",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:3,e:"从保险从业员角度看，「风险」既指所保的危险、承保的财物、保险人承保的人身，也指与潜在损失有关的不确定性，四种含义均成立，故四项全对。",src:1,tw:{ch:"風險與保險",q:"從保險從業員的角度，風險一詞是指： i. 所保的危險 ii. 承保的財物 iii. 保險人承保的人身 iv. 一項與潛在損失有關的不確定性",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"從保險從業員角度看，「風險」既指所保的危險、承保的財物、保險人承保的人身，也指與潛在損失有關的不確定性，四種含義均成立，故四項全對。"}},
{p:1,ch:"风险与保险",q:"以下关于风险的描述中哪一项是正确的: i. 所有风险都是可保的 ii. 并非所有风险都属于商业上可保的 iii.保险是应付风险的唯一方法 iv. 保险人谈及风险时可以有很多不同的意思",o:["i, ii","ii, iv","i, iv","i, iii, iv"],a:1,e:"并非所有风险都属于商业上可保（ii），且保险人谈及「风险」可以有多种不同意思（iv），两项均正确。而「所有风险都可保」「保险是唯一方法」（i、iii）属错误的绝对说法。",src:1,tw:{ch:"風險與保險",q:"以下關於風險的描述中哪一項是正確的： i. 所有風險都是可保的 ii. 並非所有風險都屬於商業上可保的 iii.保險是應付風險的唯一方法 iv. 保險人談及風險時可以有很多不同的意思",o:["i, ii","ii, iv","i, iv","i, iii, iv"],e:"並非所有風險都屬於商業上可保（ii），且保險人談及「風險」可以有多種不同意思（iv），兩項均正確。而「所有風險都可保」「保險是唯一方法」（i、iii）屬錯誤的絕對說法。"}},
{p:1,ch:"风险与保险",q:"以下哪些描述「基本风险」是正确的?",o:["它包括大规模洪灾及地震这类自然灾害","它只影响个别的投保人士","被视为社会并非个人的灾害","A和C"],a:3,e:"基本风险包括大规模洪灾、地震等自然灾害，影响遍及整体社会，被视为社会的而非个人的灾害，故 A、C 均正确。B 称它只影响个别投保人士，恰好与定义相反。",src:1,tw:{ch:"風險與保險",q:"以下哪些描述「基本風險」是正確的?",o:["它包括大規模洪災及地震這類自然災害","它只影響個別的投保人士","被視為社會並非個人的災害","A和C"],e:"基本風險包括大規模洪災、地震等自然災害，影響遍及整體社會，被視為社會的而非個人的災害，故 A、C 均正確。B 稱它隻影響個別投保人士，恰好與定義相反。"}},
{p:1,ch:"风险与保险",q:"以下哪些是可保风险:",o:["财产","感情","情绪","以上各项"],a:0,e:"只有财产这类可用金钱衡量的风险才具可保性。感情、情绪属主观感受，损失无法客观量化，一般不具可保性，故答案仅为财产。",src:1,tw:{ch:"風險與保險",q:"以下哪些是可保風險:",o:["財產","感情","情緒","以上各項"],e:"只有財產這類可用金錢衡量的風險才具可保性。感情、情緒屬主觀感受，損失無法客觀量化，一般不具可保性，故答案僅為財產。"}},
{p:1,ch:"风险与保险",q:"以下哪些是特定风险与基本风险的分别?",o:["所有风险都是可保的","所有风险都是不可保的","特定风险相对基本风险较为可保","特定风险相对基本风险较为不可保"],a:2,e:"特定风险影响范围有限且个体化，相对于影响广泛的基本风险更具备可保性，故该项正确。其余选项或以「所有风险」作绝对结论，或颠倒了二者的可保性高低。",src:1,tw:{ch:"風險與保險",q:"以下哪些是特定風險與基本風險的分別?",o:["所有風險都是可保的","所有風險都是不可保的","特定風險相對基本風險較為可保","特定風險相對基本風險較為不可保"],e:"特定風險影響範圍有限且個體化，相對於影響廣泛的基本風險更具備可保性，故該項正確。其餘選項或以「所有風險」作絕對結論，或顛倒了二者的可保性高低。"}},
{p:1,ch:"风险与保险",q:"以下哪类风险的影响是有限的(并非广泛的)?",o:["纯粹风险","投机风险","特定风险","基本风险"],a:2,e:"特定风险只影响个别或少数人，后果相对有限，故符合题意。基本风险影响非常广泛；纯粹与投机风险是按财务后果的另一分类维度，不在此比较之列。",src:1,tw:{ch:"風險與保險",q:"以下哪類風險的影響是有限的(並非廣泛的)？",o:["純粹風險","投機風險","特定風險","基本風險"],e:"特定風險隻影響個別或少數人，後果相對有限，故符合題意。基本風險影響非常廣泛；純粹與投機風險是按財務後果的另一分類維度，不在此比較之列。"}},
{p:1,ch:"风险与保险",q:"以下哪类风险的影响是非常广泛的?",o:["纯粹风险","投机风险","特定风险","基本风险"],a:3,e:"基本风险（如战争、瘟疫、大规模天灾）影响遍及整个社会，属影响非常广泛的风险，故该项正确。特定风险影响有限，纯粹与投机风险按财务后果划分，不合题意。",src:1,tw:{ch:"風險與保險",q:"以下哪類風險的影響是非常廣泛的？",o:["純粹風險","投機風險","特定風險","基本風險"],e:"基本風險（如戰爭、瘟疫、大規模天災）影響遍及整個社會，屬影響非常廣泛的風險，故該項正確。特定風險影響有限，純粹與投機風險按財務後果劃分，不合題意。"}},
{p:1,ch:"风险与保险",q:"以下哪项不应被视为保险对社会的间接益处 ?",o:["为不少人提供就业机会","协助损失控制","促进经济发展","对受保的受害人提供财务上的补偿"],a:3,e:"向受保受害人提供财务补偿是保险的直接（基本）功能，而非对社会的间接益处。提供就业、协助损失控制、促进经济发展均属保险附带的间接社会效益。",src:1,tw:{ch:"風險與保險",q:"以下哪項不應被視為保險對社會的間接益處 ?",o:["為不少人提供就業機會","協助損失控制","促進經濟發展","對受保的受害人提供財務上的補償"],e:"向受保受害人提供財務補償是保險的直接（基本）功能，而非對社會的間接益處。提供就業、協助損失控制、促進經濟發展均屬保險附帶的間接社會效益。"}},
{p:1,ch:"风险与保险",q:"以下哪项不是保险的辅助功能 ?",o:["增加就业机会","帮助经济增长及发展","把金钱上的损失转移到保险公司身上","作为储蓄用途"],a:2,e:"把金钱上的损失转移给保险公司，是保险的基本功能（风险转移），并非辅助功能。增加就业、帮助经济增长及发展、作为储蓄用途均属保险的附带（辅助）功能。",src:1,tw:{ch:"風險與保險",q:"以下哪項不是保險的輔助功能 ?",o:["增加就業機會","幫助經濟增長及發展","把金錢上的損失轉移到保險公司身上","作為儲蓄用途"],e:"把金錢上的損失轉移給保險公司，是保險的基本功能（風險轉移），並非輔助功能。增加就業、幫助經濟增長及發展、作為儲蓄用途均屬保險的附帶（輔助）功能。"}},
{p:1,ch:"风险与保险",q:"以下哪项不是保险的辅助功能?",o:["作为储蓄途径","提供就业机会","转移机制","降低意外发生"],a:2,e:"转移机制即风险转移，是保险的基本功能，而非辅助功能。作为储蓄途径、提供就业机会、降低意外发生均属保险的辅助／附带功能。",src:1,tw:{ch:"風險與保險",q:"以下哪項不是保險的輔助功能 ?",o:["作為儲蓄途徑","提供就業機會","轉移機制","降低意外發生"],e:"轉移機制即風險轉移，是保險的基本功能，而非輔助功能。作為儲蓄途徑、提供就業機會、降低意外發生均屬保險的輔助／附帶功能。"}},
{p:1,ch:"风险与保险",q:"以下哪项为「基本风险」而非「特定风险」的类别?",o:["巴士堕崖","航机失事","战事","渡轮意外"],a:2,e:"战事影响波及整个社会，属基本风险。巴士堕崖、航机失事、渡轮意外通常只影响个别群体，属特定风险，不符合题意。",src:1,tw:{ch:"風險與保險",q:"以下哪項為「基本風險」而非「特定風險」的類別？",o:["巴士墮崖","航機失事","戰事","渡輪意外"],e:"戰事影響波及整個社會，屬基本風險。巴士墮崖、航機失事、渡輪意外通常隻影響個別羣體，屬特定風險，不符合題意。"}},
{p:1,ch:"风险与保险",q:"以下哪项关于基本风险的描述是正确的?",o:["地震或自然灾害","通常都属于除外责任","影响遍及整体社会而非个别人士","以上各项皆正确"],a:3,e:"基本风险如地震等自然灾害，通常被列为除外责任（因影响广泛、损失巨大而难承保），且其影响遍及整体社会而非个别人士，三项描述均正确。",src:1,tw:{ch:"風險與保險",q:"以下哪項關於基本風險的描述是正確的？",o:["地震或自然災害","通常都屬於除外責任","影響遍及整體社會而非個別人士","以上各項皆正確"],e:"基本風險如地震等自然災害，通常被列為除外責任（因影響廣泛、損失巨大而難承保），且其影響遍及整體社會而非個別人士，三項描述均正確。"}},
{p:1,ch:"风险与保险",q:"以下哪项关于纯粹风险的描述是不正确的?",o:["沉船的货物","买入公司股票","被火烧毁的建筑物","展览馆被偷取名画"],a:1,e:"买入公司股票有盈有亏，属投机风险而非纯粹风险；题目问「不正确」的描述，故选此项。沉船货物、火毁建筑物、名画被盗均只有损失机会，属纯粹风险。",src:1,tw:{ch:"風險與保險",q:"以下哪項關於純粹風險的描述是不正確的？",o:["沉船的貨物","買入公司股票","被火燒毀的建築物","展覽館被偷取名畫"],e:"買入公司股票有盈有虧，屬投機風險而非純粹風險；題目問「不正確」的描述，故選此項。沉船貨物、火毀建築物、名畫被盜均只有損失機會，屬純粹風險。"}},
{p:1,ch:"风险与保险",q:"以下哪项可被视为保险为香港带来的辅助功能/好处? i. 作为储蓄途径 ii. 提供就业机会 iii. 鼓励经济发展 iv. 降低意外/损失的次数",o:["i, ii","i, ii, iii","ii, iii, iv","以上全部皆是"],a:3,e:"作为储蓄途径、提供就业机会、鼓励经济发展、降低意外或损失的次数，均属保险为香港带来的辅助功能／好处，四项皆对。",src:1,tw:{ch:"風險與保險",q:"以下哪項可被視為保險為香港帶來的輔助功能/好處? i. 作為儲蓄途徑 ii. 提供就業機會 iii. 鼓勵經濟發展 iv. 降低意外/損失的次數",o:["i, ii","i, ii, iii","ii, iii, iv","以上全部皆是"],e:"作為儲蓄途徑、提供就業機會、鼓勵經濟發展、降低意外或損失的次數，均屬保險為香港帶來的輔助功能／好處，四項皆對。"}},
{p:1,ch:"风险与保险",q:"以下哪项属于「投机风险」类型?",o:["制造商推出新款汽车于市场竞争","对未来恒生指数作推测","与友人合资投彩于赛马活动中","以上各项皆是"],a:3,e:"制造商推出新车参与市场竞争、推测未来恒指、合资投注赛马，均可能获利或亏损，皆属投机风险，故三项全对。",src:1,tw:{ch:"風險與保險",q:"以下哪項屬於「投機風險」類型？",o:["製造商推出新款汽車於市場競爭","對未來恆生指數作推測","與友人合資投彩於賽馬活動中","以上各項皆是"],e:"製造商推出新車參與市場競爭、推測未來恒指、合資投注賽馬，均可能獲利或虧損，皆屬投機風險，故三項全對。"}},
{p:1,ch:"风险与保险",q:"以下哪项属于基本风险的例子?",o:["冠状病毒的爆发","几个人的意外","一架车的失窃","交通意外"],a:0,e:"冠状病毒爆发影响整个社会、不受个人控制，属基本风险的例子。数人意外、单车失窃、交通意外通常只影响个别人士，属特定风险。",src:1,tw:{ch:"風險與保險",q:"以下哪項屬於基本風險的例子？",o:["冠狀病毒的爆發","幾個人的意外","一架車的失竊","交通意外"],e:"冠狀病毒爆發影響整個社會、不受個人控制，屬基本風險的例子。數人意外、單車失竊、交通意外通常隻影響個別人士，屬特定風險。"}},
{p:1,ch:"风险与保险",q:"以下哪项属于投机风险:",o:["两车辆相撞","股票投资","大厦火警所造成的损毁","以上各项皆不是"],a:1,e:"股票投资可赚可蚀，属典型的投机风险。两车相撞、大厦火警损毁均只有损失机会，属纯粹风险。",src:1,tw:{ch:"風險與保險",q:"以下哪項屬於投機風險：",o:["兩車輛相撞","股票投資","大廈火警所造成的損毀","以上各項皆不是"],e:"股票投資可賺可蝕，屬典型的投機風險。兩車相撞、大廈火警損毀均只有損失機會，屬純粹風險。"}},
{p:1,ch:"风险与保险",q:"以下哪项或哪些可称得上是保险的基本功能/好处 ?",o:["风险转移机制","为本港提供就业机会","为大部分人提供储蓄","以上各项皆是"],a:0,e:"风险转移机制是保险的基本功能。提供就业机会、为大部分人提供储蓄属保险的辅助／附带功能，而非基本功能。",src:1,tw:{ch:"風險與保險",q:"以下哪項或哪些可稱得上是保險的基本功能/好處 ?",o:["風險轉移機制","為本港提供就業機會","為大部分人提供儲蓄","以上各項皆是"],e:"風險轉移機制是保險的基本功能。提供就業機會、為大部分人提供儲蓄屬保險的輔助／附帶功能，而非基本功能。"}},
{p:1,ch:"风险与保险",q:"以下哪项或哪些潜在损失可能是可保的?",o:["财务上的","情緖上的","心理上的","以上各项皆是"],a:0,e:"可保的潜在损失须是可用金钱衡量的财务损失。情绪上、心理上的损失无法客观量化，一般不具可保性，故答案仅财务上的损失。",src:1,tw:{ch:"風險與保險",q:"以下哪項或哪些潛在損失可能是可保的？",o:["財務上的","情緖上的","心理上的","以上各項皆是"],e:"可保的潛在損失須是可用金錢衡量的財務損失。情緒上、心理上的損失無法客觀量化，一般不具可保性，故答案僅財務上的損失。"}},
{p:1,ch:"风险与保险",q:"以下哪项描述最适用于特定风险:",o:["一项不可保的风险","一项造成相对有限后果的风险","一项只影响指明保单持有人的风险","一项指明个别财物的财产保险"],a:1,e:"特定风险最突出的特征是影响（后果）范围相对有限，只牵涉个别人士，故该项最适用于描述特定风险。「不可保」「只影响指明保单持有人」或「指明个别财物的财产保险」均非其标准定义。",src:1,tw:{ch:"風險與保險",q:"以下哪項描述最適用於特定風險：",o:["一項不可保的風險","一項造成相對有限後果的風險","一項只影響指明保單持有人的風險","一項指明個別財物的財產保險"],e:"特定風險最突出的特徵是影響（後果）範圍相對有限，只牽涉個別人士，故該項最適用於描述特定風險。「不可保」「隻影響指明保單持有人」或「指明個別財物的財產保險」均非其標準定義。"}},
{p:1,ch:"风险与保险",q:"以下哪项是保险的基本功能/好处 ?",o:["增加就业机会","为被保险的受害人提供金钱上的补偿","巩固金融服务业","帮助经济增长及发展"],a:1,e:"为被保险（受保）的受害人提供金钱上的补偿，是保险的基本功能。增加就业机会、巩固金融服务业、帮助经济增长均属保险的附带／间接益处。",src:1,tw:{ch:"風險與保險",q:"以下哪項是保險的基本功能/好處 ?",o:["增加就業機會","為被保險的受害人提供金錢上的補償","鞏固金融服務業","幫助經濟增長及發展"],e:"為被保險（受保）的受害人提供金錢上的補償，是保險的基本功能。增加就業機會、鞏固金融服務業、幫助經濟增長均屬保險的附帶／間接益處。"}},
{p:1,ch:"风险与保险",q:"以下哪项是保险的基本功能?",o:["损失降低","增加就业的机会","经济增长","风险转移"],a:3,e:"风险转移是保险的核心基本功能。损失降低、增加就业机会、经济增长属保险可能带来的辅助或附带效果，并非基本功能。",src:1,tw:{ch:"風險與保險",q:"以下哪項是保險的基本功能？",o:["損失降低","增加就業的機會","經濟增長","風險轉移"],e:"風險轉移是保險的核心基本功能。損失降低、增加就業機會、經濟增長屬保險可能帶來的輔助或附帶效果，並非基本功能。"}},
{p:1,ch:"风险与保险",q:"以下哪项是基本风险在香港情况的描述?",o:["基本风险是损失的可能,非收益的机会","它的影响一般是不广泛的","它的影响是对个人而非整个社会的","它相当可能是不受保的"],a:3,e:"基本风险影响广泛、损失巨大且常被列为除外责任，故相当可能不受保，该项正确。A 描述的是纯粹风险（无收益机会）的特性，B、C 把影响说成「不广泛」「对个人」，均与基本风险特征相反。",src:1,tw:{ch:"風險與保險",q:"以下哪項是基本風險在香港情況的描述？",o:["基本風險是損失的可能，非收益的機會","它的影響一般是不廣泛的","它的影響是對個人而非整個社會的","它相當可能是不受保的"],e:"基本風險影響廣泛、損失巨大且常被列為除外責任，故相當可能不受保，該項正確。A 描述的是純粹風險（無收益機會）的特性，B、C 把影響說成「不廣泛」「對個人」，均與基本風險特徵相反。"}},
{p:1,ch:"风险与保险",q:"以下哪项是对「风险管理」的正确描述?",o:["风险管理的其中一个方法是保险的安排","风险管理和保险并没有联系","风险管理乃是保险界的专有词汇","风险管理即物质上控制风险"],a:0,e:"保险是风险管理中风险融资／转移的手段之一，故「保险的安排是风险管理的其中一个方法」正确。其余选项否认二者联系、称其为保险界专有词汇或把它等同于物质上的风险控制，均不正确。",src:1,tw:{ch:"風險與保險",q:"以下哪項是對「風險管理」的正確描述?",o:["風險管理的其中一個方法是保險的安排","風險管理和保險並沒有聯繫","風險管理乃是保險界的專有詞彙","風險管理即物質上控制風險"],e:"保險是風險管理中風險融資／轉移的手段之一，故「保險的安排是風險管理的其中一個方法」正確。其餘選項否認二者聯繫、稱其為保險界專有詞彙或把它等同於物質上的風險控制，均不正確。"}},
{p:1,ch:"风险与保险",q:"以下哪项是对有关「风险管理」一词的描述是正确的?",o:["只适用于保险业","保险人相当不可能收窄至可保风险","它的三大步骤为风险免除、风险认别及风险融资","它包含风险的认别与应付"],a:3,e:"风险管理包含风险的识别（认别）与应付等步骤，故该项正确。它并不只适用于保险业，保险人通常会把范围收窄至可保风险，且三大步骤是识别、量化与应对而非免除、识别、融资，各干扰项均有误。",src:1,tw:{ch:"風險與保險",q:"以下哪項是對有關「風險管理」一詞的描述是正確的？",o:["只適用於保險業","保險人相當不可能收窄至可保風險","它的三大步驟為風險免除、風險認別及風險融資","它包含風險的認別與應付"],e:"風險管理包含風險的識別（認別）與應付等步驟，故該項正確。它並不只適用於保險業，保險人通常會把範圍收窄至可保風險，且三大步驟是識別、量化與應對而非免除、識別、融資，各干擾項均有誤。"}},
{p:1,ch:"风险与保险",q:"以下哪项是属于投机风险的?",o:["投资股票","两辆汽车相撞","雷电打击造成建筑物严重的破坏","以上的没有一项"],a:0,e:"投资股票可赚可蚀，属投机风险。两辆汽车相撞、雷电打击毁楼都只有损失机会，属纯粹风险，故不选。",src:1,tw:{ch:"風險與保險",q:"以下哪項是屬於投機風險的？",o:["投資股票","兩輛汽車相撞","雷電打擊造成建築物嚴重的破壞","以上的沒有一項"],e:"投資股票可賺可蝕，屬投機風險。兩輛汽車相撞、雷電打擊毀樓都只有損失機會，屬純粹風險，故不選。"}},
{p:1,ch:"风险与保险",q:"以下哪项是投机风险:",o:["股票买卖","意外失足双脚折断","建筑因雷电引致严重损失","以上各项皆不是"],a:0,e:"股票买卖有盈亏两种可能，属投机风险。意外骨折、建筑被雷电引致严重损失只有损失机会，属纯粹风险。",src:1,tw:{ch:"風險與保險",q:"以下哪項是投機風險:",o:["股票買賣","意外失足雙腳折斷","建築因雷電引致嚴重損失","以上各項皆不是"],e:"股票買賣有盈虧兩種可能，屬投機風險。意外骨折、建築被雷電引致嚴重損失只有損失機會，屬純粹風險。"}},
{p:1,ch:"风险与保险",q:"以下哪项是投机风险而非纯粹风险的例子?",o:["意外失足双脚折断","发生严重车祸","建筑因雷电引致严重损失","以上各项皆不是"],a:3,e:"意外失足双脚折断、发生严重车祸、建筑因雷电引致严重损失，均只有损失机会而无获益可能，属纯粹风险而非投机风险。故本题所列为「没有一项」，选以上各项皆不是。",src:1,tw:{ch:"風險與保險",q:"以下哪項是投機風險而非純粹風險的例子？",o:["意外失足雙腳折斷","發生嚴重車禍","建築因雷電引致嚴重損失","以上各項皆不是"],e:"意外失足雙腳折斷、發生嚴重車禍、建築因雷電引致嚴重損失，均只有損失機會而無獲益可能，屬純粹風險而非投機風險。故本題所列為「沒有一項」，選以上各項皆不是。"}},
{p:1,ch:"风险与保险",q:"以下哪项是描述纯粹风险而不是投机风险?",o:["投注赛马","买卖股票","投资外汇","一辆汽车撞毁另一辆汽车"],a:3,e:"一辆汽车撞毁另一辆汽车只有损失机会，属纯粹风险。投注赛马、买卖股票、投资外汇均有赚蚀可能，属投机风险，故不选。",src:1,tw:{ch:"風險與保險",q:"以下哪項是描述純粹風險而不是投機風險？",o:["投注賽馬","買賣股票","投資外匯","一輛汽車撞毁另一輛汽車"],e:"一輛汽車撞毀另一輛汽車只有損失機會，屬純粹風險。投注賽馬、買賣股票、投資外匯均有賺蝕可能，屬投機風險，故不選。"}},
{p:1,ch:"风险与保险",q:"以下哪项是正确描述「纯粹风险」的? i. 一艘船只沉没 ii. 战争武器的生产 iii. 一幅名画于博物馆内被盗窃 iv. 一辆飞机堕毁",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:2,e:"船只沉没、名画在博物馆内被盗、飞机坠毁均只有损失而无获益机会，属纯粹风险。战争武器的生产是有盈利可能的投机活动，故应排除 ii。",src:1,tw:{ch:"風險與保險",q:"以下哪項是正確描述「純粹風險」的？ i. 一艘船隻沉沒 ii. 戰爭武器的生產 iii. 一幅名畫於博物館內被盜竊 iv. 一輛飛機墮毀",o:["i, ii","i, ii, iii","i, iii, iv","i, ii, iii, iv"],e:"船隻沉沒、名畫在博物館內被盜、飛機墜毀均只有損失而無獲益機會，屬純粹風險。戰爭武器的生產是有盈利可能的投機活動，故應排除 ii。"}},
{p:1,ch:"风险与保险",q:"以下哪项有关风险的描述是正确的: i. 所有风险是商业上可保的 ii. 保险人谈及风险时,是指其营业成绩 iii. 有些风险在商业上是不可保的 iv. 在任何情形下,财务上及身体上的风险都是可保的",o:["i, ii","ii, iii","只有 iii","iii, iv"],a:2,e:"有些风险在商业上是不可保的（iii），这一点正确。并非所有风险都可保（i 错），保险人谈及风险多指受保危险而非营业成绩（ii 错），财务与身体风险亦非在任何情况下都可保（iv 错），故答案只有 iii。",src:1,tw:{ch:"風險與保險",q:"以下哪項有關風險的描述是正確的： i. 所有風險是商業上可保的 ii. 保險人談及風險時，是指其營業成績 iii. 有些風險在商業上是不可保的 iv. 在任何情形下，財務上及身體上的風險都是可保的",o:["i, ii","ii, iii","只有 iii","iii, iv"],e:"有些風險在商業上是不可保的（iii），這一點正確。並非所有風險都可保（i 錯），保險人談及風險多指受保危險而非營業成績（ii 錯），財務與身體風險亦非在任何情況下都可保（iv 錯），故答案只有 iii。"}},
{p:1,ch:"风险与保险",q:"以下哪项有关风险的陈述不正确?",o:["保险人在使用风险一词可能有其他意思","所有风险皆属商业上可保","购买保险不单是应对风险的唯一方法","风险可能带来的忧虑增加购买保险需要"],a:1,e:"「所有风险皆属商业上可保」是错误说法（如投机风险、基本风险均不可保）；题目问不正确的陈述，故选此项。保险人对「风险」有多种含义、保险并非唯一应对方法、忧虑可增加投保需求，均属正确陈述。",src:1,tw:{ch:"風險與保險",q:"以下哪項有關風險的陳述不正確？",o:["保險人在使用風險一詞可能有其他意思","所有風險皆屬商業上可保","購買保險不單是應對風險的唯一方法","風險可能帶來的憂慮增加購買保險需要"],e:"「所有風險皆屬商業上可保」是錯誤說法（如投機風險、基本風險均不可保）；題目問不正確的陳述，故選此項。保險人對「風險」有多種含義、保險並非唯一應對方法、憂慮可增加投保需求，均屬正確陳述。"}},
{p:1,ch:"风险与保险",q:"以下哪项有关风险管理的描述是正确的?",o:["只适用于保险公司","保险公司不大可能收窄此词的应用范围至纯粹风险","风险管理指三个步骤:风险识别,风险免除及风险融资","它包含风险识别和风险量化"],a:3,e:"风险管理包含风险识别和（量化及）应付，故「它包含风险识别和风险量化」正确。它不只适用于保险公司，保险人通常会将其收窄至纯粹风险，三大步骤亦非「识别、免除、融资」。",src:1,tw:{ch:"風險與保險",q:"以下哪項有關風險管理的描述是正確的？",o:["只適用於保險公司","保險公司不大可能收窄此詞的應用範圍至純粹風險","風險管理指三個步驟：風險識別，風險免除及風險融資","它包含風險識別和風險量化"],e:"風險管理包含風險識別和（量化及）應付，故「它包含風險識別和風險量化」正確。它不只適用於保險公司，保險人通常會將其收窄至純粹風險，三大步驟亦非「識別、免除、融資」。"}},
{p:1,ch:"风险与保险",q:"以下哪项正确地描述特定风险?",o:["是必然可保的","是必然不可保的","可保性相对于投机风险为低","可保性相对于投机风险为高"],a:3,e:"特定风险只具损失机会且影响有限，其可保性高于有获益可能的投机风险，故该项正确。「必然可保」与「必然不可保」均过于绝对。",src:1,tw:{ch:"風險與保險",q:"以下哪項正確地描述特定風險？",o:["是必然可保的","是必然不可保的","可保性相對於投機風險為低","可保性相對於投機風險為高"],e:"特定風險只具損失機會且影響有限，其可保性高於有獲益可能的投機風險，故該項正確。「必然可保」與「必然不可保」均過於絕對。"}},
{p:1,ch:"风险与保险",q:"以下哪项正确地描述纯粹风险?",o:["是必然可保的","是必然不可保的","可保性相对于投机风险为高","可保性相对于投机风险为低"],a:2,e:"纯粹风险只具损失机会，是保险的主要承保对象，可保性高于投机风险，故该项正确。「必然可保」或「必然不可保」均为绝对化错误说法。",src:1,tw:{ch:"風險與保險",q:"以下哪項正確地描述純粹風險？",o:["是必然可保的","是必然不可保的","可保性相對於投機風險為高","可保性相對於投機風險為低"],e:"純粹風險只具損失機會，是保險的主要承保對象，可保性高於投機風險，故該項正確。「必然可保」或「必然不可保」均為絕對化錯誤說法。"}},
{p:1,ch:"风险与保险",q:"以下哪项被列为「基本风险」?",o:["锅炉爆炸","沙士爆发","数辆车相撞","打劫"],a:1,e:"沙士（SARS）爆发影响整个社会，属基本风险。锅炉爆炸、数辆车相撞、打劫通常只影响个别人士，属特定风险。",src:1,tw:{ch:"風險與保險",q:"以下哪項被列為「基本風險」？",o:["鍋爐爆炸","沙士爆發","數輛車相撞","打劫"],e:"沙士（SARS）爆發影響整個社會，屬基本風險。鍋爐爆炸、數輛車相撞、打劫通常隻影響個別人士，屬特定風險。"}},
{p:1,ch:"风险与保险",q:"以独立的一门学科看,风险管理被视为:",o:["保险的一部分","投机风险","保险可作为其中一种应付选择","与保险完全没有关系"],a:2,e:"作为独立的一门学科，风险管理涵盖识别、量化与应付，保险只是其中一种应付（风险融资）选择，故该项正确。其余选项称它是保险的一部分、是投机风险或与保险毫无关系，均不正确。",src:1,tw:{ch:"風險與保險",q:"以獨立的一門學科看，風險管理被視為：",o:["保險的一部分","投機風險","保險可作為其中一種應付選擇","與保險完全沒有關係"],e:"作為獨立的一門學科，風險管理涵蓋識別、量化與應付，保險只是其中一種應付（風險融資）選擇，故該項正確。其餘選項稱它是保險的一部分、是投機風險或與保險毫無關係，均不正確。"}},
{p:1,ch:"风险与保险",q:"以独立的一门学问来看,「风险管理」可以利用哪项或哪些项的保险应付?",o:["工程保险","经济权益保险","一篮子保单","以上各项皆是"],a:3,e:"风险管理可运用工程保险、经济权益保险、一篮子保单等多种保险工具来转移风险，故以上各项皆是。",src:1,tw:{ch:"風險與保險",q:"以獨立的一門學問來看，「風險管理」可以利用哪項或哪些項的保險應付？",o:["工程保險","經濟權益保險","一籃子保單","以上各項皆是"],e:"風險管理可運用工程保險、經濟權益保險、一籃子保單等多種保險工具來轉移風險，故以上各項皆是。"}},
{p:1,ch:"风险与保险",q:"作为一门独立学科及研究范围,风险管理应用于:",o:["纯粹风险","投机风险","纯粹风险及投机风险","非纯粹风险亦非投机风险"],a:2,e:"作为独立学科，风险管理同时适用于纯粹风险与投机风险，两类风险都需识别、量化与应对。仅限其中一类，或说两者皆不涉，均不完整。",src:1,tw:{ch:"風險與保險",q:"作為一門獨立學科及研究範圍，風險管理應用於：",o:["純粹風險","投機風險","純粹風險及投機風險","非純粹風險亦非投機風險"],e:"作為獨立學科，風險管理同時適用於純粹風險與投機風險，兩類風險都需識別、量化與應對。僅限其中一類，或說兩者皆不涉，均不完整。"}},
{p:1,ch:"风险与保险",q:"作为一门独立的学科,风险管理涉及:",o:["纯风险及投机风险","以保险人角度看,涉及纯粹风险","以银行家角度看,涉及投机风险","以上所有各项"],a:3,e:"风险管理既涉及纯粹风险与投机风险；从保险人角度看侧重纯粹风险，从银行家角度看侧重投机风险，三项均正确，故以上所有各项皆是。",src:1,tw:{ch:"風險與保險",q:"作為一門獨立的學科，風險管理涉及：",o:["純風險及投機風險","以保險人角度看，涉及純粹風險","以銀行家角度看，涉及投機風險","以上所有各項"],e:"風險管理既涉及純粹風險與投機風險；從保險人角度看側重純粹風險，從銀行家角度看側重投機風險，三項均正確，故以上所有各項皆是。"}},
{p:1,ch:"风险与保险",q:"保险中的「危险」是指:",o:["电单车","受保人","身体受伤","投保人"],a:2,e:"保险中的「危险」（peril）指造成损失的原因或事件，如身体受伤、火灾等，故「身体受伤」正确。电单车是财物标的，受保人、投保人均属当事人身份，并非「危险」。",src:1,tw:{ch:"風險與保險",q:"保險中的「危險」是指：",o:["電單車","受保人","身體受傷","投保人"],e:"保險中的「危險」（peril）指造成損失的原因或事件，如身體受傷、火災等，故「身體受傷」正確。電單車是財物標的，受保人、投保人均屬當事人身份，並非「危險」。"}},
{p:1,ch:"风险与保险",q:"保险为社会带来好处吗?",o:["是有的;保险本是一种社会手段","是有的;通过保险人要求采取可接受的损失控制措施等等","没有的;保险仅仅是私人之间的安排","没有的;除非是强制保险"],a:1,e:"保险确能为社会带来好处，其途径之一是通过保险人要求采取可接受的损失控制措施，从而减少事故发生。A 仅笼统说它是社会手段、未点明机制，C、D 否认保险的社会效益，均不正确。",src:1,tw:{ch:"風險與保險",q:"保險為社會帶來好處嗎？",o:["是有的；保險本是一種社會手段","是有的；通過保險人要求採取可接受的損失控制措施等等","沒有的；保險僅僅是私人之間的安排","沒有的；除非是強制保險"],e:"保險確能為社會帶來好處，其途徑之一是通過保險人要求採取可接受的損失控制措施，從而減少事故發生。A 僅籠統說它是社會手段、未點明機制，C、D 否認保險的社會效益，均不正確。"}},
{p:1,ch:"风险与保险",q:"保险人对受保标的的潜在损失可以改进是属于下列哪项?",o:["核保","风险评估","风险管理","保险风险分析"],a:2,e:"保险人透过改善受保标的的风险状况来降低潜在损失，这一做法属「风险管理」。核保是承保判断环节，风险评估只是其中的一环，保险风险分析则非标准术语。",src:1,tw:{ch:"風險與保險",q:"保險人對受保標的的潛在損失可以改進是屬於下列哪項?",o:["核保","風險評估","風險管理","保險風險分析"],e:"保險人透過改善受保標的的風險狀況來降低潛在損失，這一做法屬「風險管理」。核保是承保判斷環節，風險評估只是其中的一環，保險風險分析則非標準術語。"}},
{p:1,ch:"风险与保险",q:"保险人形容造成损失的原因,或承保的财物是指:",o:["风险","危险","投保人","保单持有人"],a:0,e:"「风险」在保险中可同时指造成损失的原因或承保的财物（标的），故答案为风险。「危险」仅指损失成因，投保人、保单持有人是当事人，均不涵盖承保财物这一层含义。",src:1,tw:{ch:"風險與保險",q:"保險人形容造成損失的原因，或承保的財物是指：",o:["風險","危險","投保人","保單持有人"],e:"「風險」在保險中可同時指造成損失的原因或承保的財物（標的），故答案為風險。「危險」僅指損失成因，投保人、保單持有人是當事人，均不涵蓋承保財物這一層含義。"}},
{p:1,ch:"风险与保险",q:"保险公司在使用风险管理一词时,它可能是指:",o:["投资及其他投机风险","在正常情况下不可保的风险","正在承保或考虑承保的风险","公司内主管核保部门的行政人员"],a:2,e:"保险公司所称「风险管理」常指其正在承保或考虑承保的风险的分析与改善，故该项正确。投资及其他投机风险、在正常情况下不可保的风险、行政人员，均非保险人在此语境下的用法。",src:1,tw:{ch:"風險與保險",q:"保險公司在使用風險管理一詞時，它可能是指：",o:["投資及其他投機風險","在正常情況下不可保的風險","正在承保或考慮承保的風險","公司內主管核保部門的行政人員"],e:"保險公司所稱「風險管理」常指其正在承保或考慮承保的風險的分析與改善，故該項正確。投資及其他投機風險、在正常情況下不可保的風險、行政人員，均非保險人在此語境下的用法。"}},
{p:1,ch:"风险与保险",q:"保险可被形容为:",o:["一种应付风险的方法","应付风险的唯一方法","应付任何类型风险的最廉价的方法","一种确保不会出现损失的万无一失的方法"],a:0,e:"保险是应付风险的方法之一（透过风险转移），但并非唯一、最廉价或万无一失的方法，故仅「一种应付风险的方法」正确。",src:1,tw:{ch:"風險與保險",q:"保險可被形容為：",o:["一種應付風險的方法","應付風險的唯一方法","應付任何類型風險的最廉價的方法","一種確保不會出現損失的萬無一失的方法"],e:"保險是應付風險的方法之一（透過風險轉移），但並非唯一、最廉價或萬無一失的方法，故僅「一種應付風險的方法」正確。"}},
{p:1,ch:"风险与保险",q:"保险和风险管理的关系是:",o:["保险是风险管理的其中一环","风险管理是保险的其中一环","保险和风险管理是完全相同的学科","保险和风险管理是无关的"],a:0,e:"风险管理涵盖识别、量化、应对的整个流程，保险只是其中风险融资／转移的一环，故「保险是风险管理的其中一环」正确。反向或等同、无关的说法均错误。",src:1,tw:{ch:"風險與保險",q:"保險和風險管理的關係是：",o:["保險是風險管理的其中一環","風險管理是保險的其中一環","保險和風險管理是完全相同的學科","保險和風險管理是無關的"],e:"風險管理涵蓋識別、量化、應對的整個流程，保險只是其中風險融資／轉移的一環，故「保險是風險管理的其中一環」正確。反向或等同、無關的說法均錯誤。"}},
{p:1,ch:"风险与保险",q:"保险基本上是:",o:["与赌博相同","是一种风险转移机制","只是一种应付投机风险的抗衡方法","是一种保证没有意外可发生的途径"],a:1,e:"保险本质上是一种风险转移机制，由保险人集合众多投保人的保费来承担承保风险。它不同于创制风险的赌博，也非仅应付投机风险、或保证没有意外发生的途径。",src:1,tw:{ch:"風險與保險",q:"保險基本上是：",o:["與賭博相同","是一種風險轉移機制","只是一種應付投機風險的抗衡方法","是一種保證沒有意外可發生的途徑"],e:"保險本質上是一種風險轉移機制，由保險人集合眾多投保人的保費來承擔承保風險。它不同於創制風險的賭博，也非僅應付投機風險、或保證沒有意外發生的途徑。"}},
{p:1,ch:"风险与保险",q:"只有损失的机会而无收益的可能性之风险称为:",o:["纯粹风险","特定风险","投机风险","基本风险"],a:0,e:"只有损失机会而无收益可能性的风险即纯粹风险的定义。特定风险、基本风险按影响范围分类，投机风险则具盈亏两种可能，均不符题意。",src:1,tw:{ch:"風險與保險",q:"只有損失的機會而無收益的可能性之風險稱為：",o:["純粹風險","特定風險","投機風險","基本風險"],e:"只有損失機會而無收益可能性的風險即純粹風險的定義。特定風險、基本風險按影響範圍分類，投機風險則具盈虧兩種可能，均不符題意。"}},
{p:1,ch:"风险与保险",q:"哪类风险具有收益亦有损失的两种可能性?",o:["纯粹风险","投机风险","特定风险","基本风险"],a:1,e:"同时具有收益与损失两种可能性的风险是投机风险。纯粹风险只有损失机会，特定与基本风险按影响范围划分，均不合题意。",src:1,tw:{ch:"風險與保險",q:"哪類風險具有收益亦有損失的兩種可能性？",o:["純粹風險","投機風險","特定風險","基本風險"],e:"同時具有收益與損失兩種可能性的風險是投機風險。純粹風險只有損失機會，特定與基本風險按影響範圍劃分，均不合題意。"}},
{p:1,ch:"风险与保险",q:"在不同的情况下,有一相同词语来形容造成损失的原因、承保的财物或人身、 所保风险,这一词语是:",o:["风险","保险","保单","近因"],a:0,e:"在保险中，「风险」一词可分别指造成损失的原因、承保的财物或人身以及所保风险，故答案为风险。保险、保单、近因均无此多重含义。",src:1,tw:{ch:"風險與保險",q:"在不同的情況下，有一相同詞語來形容造成損失的原因、承保的財物或人身、 所保風險，這一詞語是：",o:["風險","保險","保單","近因"],e:"在保險中，「風險」一詞可分別指造成損失的原因、承保的財物或人身以及所保風險，故答案為風險。保險、保單、近因均無此多重含義。"}},
{p:1,ch:"风险与保险",q:"在保险方面,以下哪项最能描述风险的含意:",o:["有关潜在损失的不确定性","有关潜在收益的不确定性","取得利益的数学必然率","保险人可能变得无力偿债的危险性"],a:0,e:"在保险方面，风险指有关潜在损失的不确定性，这是其基本含义。B 说潜在收益的不确定性、C 说取得利益的数学必然率、D 说保险人无力偿债的危险性，均非此含义。",src:1,tw:{ch:"風險與保險",q:"在保險方面，以下哪項最能描述風險的含意：",o:["有關潛在損失的不確定性","有關潛在收益的不確定性","取得利益的數學必然率","保險人可能變得無力償債的危險性"],e:"在保險方面，風險指有關潛在損失的不確定性，這是其基本含義。B 說潛在收益的不確定性、C 說取得利益的數學必然率、D 說保險人無力償債的危險性，均非此含義。"}},
{p:1,ch:"风险与保险",q:"在知识及研究的范畴中,风险管理的步骤包括: i. 识别风险 ii. 量化风险 iii. 应对及防范风险,降低风险或以风险融资 iv. 确别风险",o:["i, ii,iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:0,e:"风险管理的步骤包括识别、量化、应对及防范（降低风险或以风险融资），故 i、ii、iii 均正确。「确别风险」只是「识别」的笔误重复，iv 不构成独立步骤。",src:1,tw:{ch:"風險與保險",q:"在知識及研究的範疇中，風險管理的步驟包括： i. 識別風險 ii. 量化風險 iii. 應對及防範風險，降低風險或以風險融資 iv. 確別風險",o:["i, ii,iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"風險管理的步驟包括識別、量化、應對及防範（降低風險或以風險融資），故 i、ii、iii 均正確。「確別風險」只是「識別」的筆誤重複，iv 不構成獨立步驟。"}},
{p:1,ch:"风险与保险",q:"在知识及研究的范畴中,风险管理的步骤包括识别风险﹑应对风险及_________ 。",o:["防范化","商讨计策","量化风险","减轻风险"],a:2,e:"风险管理的三大步骤为识别、应对及量化风险，缺少的正是「量化风险」。防范化、商讨计策、减轻风险均非标准步骤名称。",src:1,tw:{ch:"風險與保險",q:"在知識及研究的範疇中，風險管理的步驟包括識別風險﹑應對風險及 _________ 。",o:["防範化","商討計策","量化風險","減輕風險"],e:"風險管理的三大步驟為識別、應對及量化風險，缺少的正是「量化風險」。防範化、商討計策、減輕風險均非標準步驟名稱。"}},
{p:1,ch:"风险与保险",q:"在银行及其他保险业以外的金融服务领域中,风险管理是指: i. 投资风险 ii. 投机风险 iii. 防范风险 iv. 减轻风险",o:["i, ii","i, iii","i, ii, iii","i, ii, iii, iv"],a:0,e:"在银行及其他金融服务领域，风险管理主要指投资风险与投机风险（i、ii）。防范、减轻属应对手段而非该范畴风险管理的对象，故不选 iii、iv。",src:1,tw:{ch:"風險與保險",q:"在銀行及其他保險業以外的金融服務領域中，風險管理是指： i. 投資風險 ii. 投機風險 iii. 防範風險 iv. 減輕風險",o:["i, ii","i, iii","i, ii, iii","i, ii, iii, iv"],e:"在銀行及其他金融服務領域，風險管理主要指投資風險與投機風險（i、ii）。防範、減輕屬應對手段而非該範疇風險管理的對象，故不選 iii、iv。"}},
{p:1,ch:"风险与保险",q:"在需要作出赔偿时, 该项的损失是指?",o:["风险","危险","事件","实质与道德"],a:0,e:"在需要作出赔偿时，所涉的损失即指所承保的「风险」（危险或标的）的发生。危险仅指损失成因，事件的表述过于笼统，实质与道德风险属风险因子的分类，均不准确。",src:1,tw:{ch:"風險與保險",q:"在需要作出賠償時, 該項的損失是指?",o:["風險","危險","事件","實質與道德"],e:"在需要作出賠償時，所涉的損失即指所承保的「風險」（危險或標的）的發生。危險僅指損失成因，事件的表述過於籠統，實質與道德風險屬風險因子的分類，均不準確。"}},
{p:1,ch:"风险与保险",q:"在风险管理的课题中,识别威胁一家机构的风险后,会有以下哪些步骤? i. 量化 ii. 损失防范 iii. 损失降低 iv. 风险融资",o:["i, ii","i, iii","i, ii, iii","i, ii, iii, iv"],a:2,e:"识别风险之后，须先量化风险的严重程度，再采取损失防范与损失降低等应对措施，故 i、ii、iii 均为后续步骤。风险融资属另一类处理安排，不在本题所列三项之内，故排除 iv。",src:1,tw:{ch:"風險與保險",q:"在風險管理的課題中，識別威脅一家機構的風險後，會有以下哪些步驟？ i. 量化 ii. 損失防範 iii. 損失降低 iv. 風險融資",o:["i, ii","i, iii","i, ii, iii","i, ii, iii, iv"],e:"識別風險之後，須先量化風險的嚴重程度，再採取損失防範與損失降低等應對措施，故 i、ii、iii 均為後續步驟。風險融資屬另一類處理安排，不在本題所列三項之內，故排除 iv。"}},
{p:1,ch:"风险与保险",q:"基本风险是:",o:["通常带来的影响为固定及可计算量度的","相当可能影响大和毁灭性强","必然可保的","相当可能牵涉政府"],a:1,e:"基本风险通常影响大、毁灭性强（如天灾、战争），故该项正确。其影响既非固定可量度，也非必然可保，「相当可能牵涉政府」并非其定义特征。",src:1,tw:{ch:"風險與保險",q:"基本風險是：",o:["通常帶來的影響為固定及可計算量度的","相當可能影響大和毀滅性強","必然可保的","相當可能牽涉政府"],e:"基本風險通常影響大、毀滅性強（如天災、戰爭），故該項正確。其影響既非固定可量度，也非必然可保，「相當可能牽涉政府」並非其定義特徵。"}},
{p:1,ch:"风险与保险",q:"如果一份保单根据「全险」(all risk)形式签发,在这前题下「风险」(risk) 的设定含义是:",o:["所保危险或造成损失的原因","损失或收益的可能性","受保财物","保单被保人"],a:0,e:"在「全险」（all risks）保单下，「风险」指所承保的危险或造成损失的原因。损失或收益的可能性、受保财物、保单被保人均非该语境下的含义。",src:1,tw:{ch:"風險與保險",q:"如果一份保單根據「全險」(all risk)形式簽發，在這前題下「風險」(risk) 的設定含義是：",o:["所保危險或造成損失的原因","損失或收益的可能性","受保財物","保單被保人"],e:"在「全險」（all risks）保單下，「風險」指所承保的危險或造成損失的原因。損失或收益的可能性、受保財物、保單被保人均非該語境下的含義。"}},
{p:1,ch:"风险与保险",q:"如果一份保单根据「全险」形式签发,在这前题下「风险」的设定含义是:",o:["所保「危险」或造成损失的原因","损失或收益的可能性","被保险财产的位置","作为保单的受保障人士"],a:0,e:"「全险」保单中的「风险」指所保「危险」或造成损失的原因，故该项正确。损失或收益的可能性、被保险财产的位置、受保障人士均非题中「风险」的含义。",src:1,tw:{ch:"風險與保險",q:"如果一份保單根據「全險」形式簽發，在這前題下「風險」的設定含義是：",o:["所保「危險」或造成損失的原因","損失或收益的可能性","被保險財產的位置","作為保單的受保障人士"],e:"「全險」保單中的「風險」指所保「危險」或造成損失的原因，故該項正確。損失或收益的可能性、被保險財產的位置、受保障人士均非題中「風險」的含義。"}},
{p:1,ch:"风险与保险",q:"如果一名由保险人聘请的检验人,他必须为某项「风险」作出检验,那么,「 风险」一词在这方面有以下哪项或哪些含义?",o:["将会成为被保人人的缴付保费的能力","将会成为受保的财产","将会成为被保人的信贷资料","以上所有各项"],a:1,e:"保险人聘请检验人检验某项「风险」时，此处的「风险」指将会成为受保对象的财产（标的）。缴付保费的能力、信贷资料均非「风险」在此情况的含义。",src:1,tw:{ch:"風險與保險",q:"如果一名由保險人聘請的檢驗人，他必須為某項「風險」作出檢驗，那麼，「 風險」一詞在這方面有以下哪項或哪些含義？",o:["將會成為被保人人的繳付保費的能力","將會成為受保的財產","將會成為被保人的信貸資料","以上所有各項"],e:"保險人聘請檢驗人檢驗某項「風險」時，此處的「風險」指將會成為受保對象的財產（標的）。繳付保費的能力、信貸資料均非「風險」在此情況的含義。"}},
{p:1,ch:"风险与保险",q:"如果从风险的原因与影响作分类,它可分为:",o:["纯粹风险及投机风险","可保风险及不可保风险","特定风险及基本风险","纯粹风险及特定风险"],a:2,e:"按风险的原因与影响分类，风险可分为特定风险与基本风险（以影响范围划分）。纯粹／投机风险是按财务后果分类，可保／不可保是按可保性分类。",src:1,tw:{ch:"風險與保險",q:"如果從風險的原因與影響作分類，它可分為：",o:["純粹風險及投機風險","可保風險及不可保風險","特定風險及基本風險","純粹風險及特定風險"],e:"按風險的原因與影響分類，風險可分為特定風險與基本風險（以影響範圍劃分）。純粹／投機風險是按財務後果分類，可保／不可保是按可保性分類。"}},
{p:1,ch:"风险与保险",q:"如果从风险的影响作分类,它可分为:",o:["特定风险和纯粹风险","基本风险和纯粹风险","基本风险和特定风险","非特定风险和投资风险"],a:2,e:"按影响范围分类，风险分为基本风险（影响广泛）与特定风险（影响有限），故该项正确。纯粹风险、非特定风险、投资风险均不属此一分类。",src:1,tw:{ch:"風險與保險",q:"如果從風險的影響作分類，它可分為：",o:["特定風險和純粹風險","基本風險和純粹風險","基本風險和特定風險","非特定風險和投資風險"],e:"按影響範圍分類，風險分為基本風險（影響廣泛）與特定風險（影響有限），故該項正確。純粹風險、非特定風險、投資風險均不屬此一分類。"}},
{p:1,ch:"风险与保险",q:"如果从风险的财务后果作分类,它可分为:",o:["特定风险和基本风险","纯粹风险和投机风险","可保风险和不可保风险","非特定风险和特定风险"],a:1,e:"按财务后果分类，风险分为纯粹风险（只有损失）与投机风险（有盈有亏），故该项正确。特定／基本风险按影响划分，可保／不可保按可保性划分。",src:1,tw:{ch:"風險與保險",q:"如果從風險的財務後果作分類，它可分為：",o:["特定風險和基本風險","純粹風險和投機風險","可保風險和不可保風險","非特定風險和特定風險"],e:"按財務後果分類，風險分為純粹風險（只有損失）與投機風險（有盈有虧），故該項正確。特定／基本風險按影響劃分，可保／不可保按可保性劃分。"}},
{p:1,ch:"风险与保险",q:"如果风险被视为独立的知识及研究学科,风险管理一词经常被提及或应用,当 保险人应用风险管理时:",o:["与独立的知识及研究学科中的意思无异","较为着重改善风险","指投机风险而非纯粹风险","只涉及保费计算"],a:1,e:"保险人应用「风险管理」时，较着重于改善受保风险（降低潜在的损失可能），而非沿用独立学科中的广义含义，也不是指投机风险或仅涉及保费计算。",src:1,tw:{ch:"風險與保險",q:"如果風險被視為獨立的知識及研究學科，風險管理一詞經常被提及或應用，當 保險人應用風險管理時：",o:["與獨立的知識及研究學科中的意思無異","較為着重改善風險","指投機風險而非純粹風險","只涉及保費計算"],e:"保險人應用「風險管理」時，較着重於改善受保風險（降低潛在的損失可能），而非沿用獨立學科中的廣義含義，也不是指投機風險或僅涉及保費計算。"}},
{p:1,ch:"风险与保险",q:"对保险人而言,描述受保损失的成因,受保财产的字眼是:",o:["风险","危险","被保险人","保单持有人"],a:0,e:"保险人以「风险」描述受保损失的成因或受保财产，故答案为风险。「危险」仅指损失成因，被保险人、保单持有人均为当事人，不含标的之含义。",src:1,tw:{ch:"風險與保險",q:"對保險人而言，描述受保損失的成因，受保財產的字眼是：",o:["風險","危險","被保險人","保單持有人"],e:"保險人以「風險」描述受保損失的成因或受保財產，故答案為風險。「危險」僅指損失成因，被保險人、保單持有人均為當事人，不含標的之含義。"}},
{p:1,ch:"风险与保险",q:"就业、经济增长及储蓄属于以下哪一项?",o:["与保险全无关系","是保险的基本功能","是保险的辅助功能","是保险的基本目的而非副产品"],a:2,e:"就业、经济增长及储蓄属保险的辅助功能（副产品），而非基本功能（基本功能是风险转移与赔偿）。说它们与保险全无关系或属基本目的，均不正确。",src:1,tw:{ch:"風險與保險",q:"就業、經濟增長及儲蓄屬於以下哪一項？",o:["與保險全無關係","是保險的基本功能","是保險的輔助功能","是保險的基本目的而非副產品"],e:"就業、經濟增長及儲蓄屬保險的輔助功能（副產品），而非基本功能（基本功能是風險轉移與賠償）。說它們與保險全無關係或屬基本目的，均不正確。"}},
{p:1,ch:"风险与保险",q:"当保单提供「全险」的保险保障时,所提及的风险是指",o:["造成损失的原因","所承保的财物","正在考虑承保的人身","正在考虑承保的财物或人身"],a:0,e:"当保单提供「全险」保障时，所提的「风险」指造成损失的原因（承保危险）。所承保的财物、正在考虑承保的人身或财物，均非「全险」语境下该词的含义。",src:1,tw:{ch:"風險與保險",q:"當保單提供「全險」的保險保障時，所提及的風險是指",o:["造成損失的原因","所承保的財物","正在考慮承保的人身","正在考慮承保的財物或人身"],e:"當保單提供「全險」保障時，所提的「風險」指造成損失的原因（承保危險）。所承保的財物、正在考慮承保的人身或財物，均非「全險」語境下該詞的含義。"}},
{p:1,ch:"风险与保险",q:"当保险公司向被保人的受益人支付死亡保险金,这是:",o:["人寿保险的唯一功能","人寿保险的基本功能","保险的唯一功能","并不是保险的基本和辅助功能"],a:1,e:"保险公司向受益人死亡保险金，是人寿保险的基本功能（提供保障）。它并非保险或人寿保险的唯一功能，故其余选项均不正确。",src:1,tw:{ch:"風險與保險",q:"當保險公司向被保人的受益人支付死亡保險金，這是：",o:["人壽保險的唯一功能","人壽保險的基本功能","保險的唯一功能","並不是保險的基本和輔助功能"],e:"保險公司向受益人死亡保險金，是人壽保險的基本功能（提供保障）。它並非保險或人壽保險的唯一功能，故其餘選項均不正確。"}},
{p:1,ch:"风险与保险",q:"恐怖袭击、大规模洪灾和其他灾害等。这类风险发生的原因是超逾一个人或甚 至一群人所能操控的,受影响的人不计其数。这是:",o:["纯粹风险","灾难风险","特定风险","基本风险"],a:3,e:"恐怖袭击、大规模洪灾等影响超逾个人所能操控、波及人数众多，属基本风险。灾难风险并非正式分类，特定风险影响有限，纯粹风险是另一分类维度，均不合题意。",src:1,tw:{ch:"風險與保險",q:"恐怖襲擊、大規模洪災和其他災害等。這類風險發生的原因是超逾一個人或甚 至一群人所能操控的，受影響的人不計其數。這是：",o:["純粹風險","災難風險","特定風險","基本風險"],e:"恐怖襲擊、大規模洪災等影響超逾個人所能操控、波及人數眾多，屬基本風險。災難風險並非正式分類，特定風險影響有限，純粹風險是另一分類維度，均不合題意。"}},
{p:1,ch:"风险与保险",q:"战争、恐怖袭击是属于_________________。",o:["纯粹风险","灾难风险","特定风险","基本风险"],a:3,e:"战争、恐怖袭击影响遍及整个社会、不受个人控制，属基本风险。它们虽亦具纯粹性，但题目按影响范围分类，故应归入基本风险。",src:1,tw:{ch:"風險與保險",q:"戰爭、恐怖襲擊是屬於_________________。",o:["純粹風險","災難風險","特定風險","基本風險"],e:"戰爭、恐怖襲擊影響遍及整個社會、不受個人控制，屬基本風險。它們雖亦具純粹性，但題目按影響範圍分類，故應歸入基本風險。"}},
{p:1,ch:"风险与保险",q:"描述保险及风险的关系,以下哪项是正确的:",o:["并非所有风险都属于商业上可保的","保险是抗衡风险的唯一挽救方法","所有风险在商业上都是可保的","以上所有各项皆是"],a:0,e:"并非所有风险都属于商业上可保，只有符合可保条件的风险才获承保，故该项正确。保险并非抗衡风险的唯一方法，也说不上所有风险皆可保。",src:1,tw:{ch:"風險與保險",q:"描述保險及風險的關係，以下哪項是正確的：",o:["並非所有風險都屬於商業上可保的","保險是抗衡風險的唯一挽救方法","所有風險在商業上都是可保的","以上所有各項皆是"],e:"並非所有風險都屬於商業上可保，只有符合可保條件的風險才獲承保，故該項正確。保險並非抗衡風險的唯一方法，也說不上所有風險皆可保。"}},
{p:1,ch:"风险与保险",q:"提供就业,损失防范,协助储蓄及投资,可分被形容为:",o:["与保险全无关系","是保险的基本功能","是保险的辅助功能而非基本功能","是保险的基本目的而非副产品"],a:2,e:"提供就业、损失防范、协助储蓄及投资，属保险的辅助功能而非基本功能。说它们与保险全无关系、或属基本功能／基本目的，均不正确。",src:1,tw:{ch:"風險與保險",q:"提供就業，損失防範，協助儲蓄及投資，可分被形容為：",o:["與保險全無關係","是保險的基本功能","是保險的輔助功能而非基本功能","是保險的基本目的而非副產品"],e:"提供就業、損失防範、協助儲蓄及投資，屬保險的輔助功能而非基本功能。說它們與保險全無關係、或屬基本功能／基本目的，均不正確。"}},
{p:1,ch:"风险与保险",q:"有一种风险是很多财产保单中的除外责任,这种风险称为",o:["纯粹风险","特定风险","基本风险","以上各项皆是"],a:2,e:"基本风险影响广大、损失巨大，常被列为众多财产保单中的除外责任，故答案即基本风险。纯粹风险、特定风险一般可承保，不合题意。",src:1,tw:{ch:"風險與保險",q:"有一種風險是很多財產保單中的除外責任，這種風險稱為",o:["純粹風險","特定風險","基本風險","以上各項皆是"],e:"基本風險影響廣大、損失巨大，常被列為眾多財產保單中的除外責任，故答案即基本風險。純粹風險、特定風險一般可承保，不合題意。"}},
{p:1,ch:"风险与保险",q:"有些风险只会引起难过的感觉,并不牵涉财务损失,它们:",o:["任何情况下都可保","经常被承保","只有当损失的成因是意外时才可保","相当可能是不可以受保的"],a:3,e:"仅引起难过感觉、不牵涉财务损失的风险，因无法以金钱衡量，相当可能不可以受保。可保风险须有可量化的财务损失，故其余选项均错误。",src:1,tw:{ch:"風險與保險",q:"有些風險只會引起難過的感覺，並不牽涉財務損失，它們：",o:["任何情況下都可保","經常被承保","只有當損失的成因是意外時才可保","相當可能是不可以受保的"],e:"僅引起難過感覺、不牽涉財務損失的風險，因無法以金錢衡量，相當可能不可以受保。可保風險須有可量化的財務損失，故其餘選項均錯誤。"}},
{p:1,ch:"风险与保险",q:"汽车意外属于:",o:["基本风险","特定风险","纯粹风险","投机风险"],a:1,e:"汽车意外一般只影响个别涉事者、后果有限，按影响范围属特定风险，故答案为该项。它虽兼具纯粹风险特征，但本题选项系按其影响归类。",src:1,tw:{ch:"風險與保險",q:"汽車意外屬於:",o:["基本風險","特定風險","純粹風險","投機風險"],e:"汽車意外一般隻影響個別涉事者、後果有限，按影響範圍屬特定風險，故答案為該項。它雖兼具純粹風險特徵，但本題選項系按其影響歸類。"}},
{p:1,ch:"风险与保险",q:"特定风险是指:",o:["相当可能影响大量人数的风险","相当可能不会导致灾难的后果","相当可能导致灾难性的后果","相当可能牵涉政府"],a:1,e:"特定风险的影响有限、相当可能不会导致灾难性后果，故该项正确。它并非影响大量人数，亦不牵涉政府，A、C、D 均与定义不符。",src:1,tw:{ch:"風險與保險",q:"特定風險是指：",o:["相當可能影響大量人數的風險","相當可能不會導致災難的後果","相當可能導致災難性的後果","相當可能牽涉政府"],e:"特定風險的影響有限、相當可能不會導致災難性後果，故該項正確。它並非影響大量人數，亦不牽涉政府，A、C、D 均與定義不符。"}},
{p:1,ch:"风险与保险",q:"纯粹风险的定义是:",o:["一项只有收益而不具损失的风险","一项只有损失而不具收益的风险","一个绝对可保的风险","一个具有灾难性损失的风险"],a:1,e:"纯粹风险指一项只有损失而不具收益的风险，故该项正确。「只有收益而不具损失」是相反概念，且纯粹风险并非绝对可保、也未必具灾难性损失。",src:1,tw:{ch:"風險與保險",q:"純粹風險的定義是：",o:["一項只有收益而不具損失的風險","一項只有損失而不具收益的風險","一個絕對可保的風險","一個具有災難性損失的風險"],e:"純粹風險指一項只有損失而不具收益的風險，故該項正確。「只有收益而不具損失」是相反概念，且純粹風險並非絕對可保、也未必具災難性損失。"}},
{p:1,ch:"风险与保险",q:"考虑改善受保风险之潜在损失可能性,保险人可能采用的字眼为:",o:["核保","风险评估","风险管理","保险风险分析"],a:2,e:"保险人考虑改善受保风险、降低其潜在损失的可能性时，所用的字眼是「风险管理」。核保、风险评估、保险风险分析各有侧重，但此情境的标准说法即风险管理。",src:1,tw:{ch:"風險與保險",q:"考慮改善受保風險之潛在損失可能性，保險人可能採用的字眼為：",o:["核保","風險評估","風險管理","保險風險分析"],e:"保險人考慮改善受保風險、降低其潛在損失的可能性時，所用的字眼是「風險管理」。核保、風險評估、保險風險分析各有側重，但此情境的標準說法即風險管理。"}},
{p:1,ch:"风险与保险",q:"请说明以下风险工具: 不提供食物及饮料以免除食物中毒的风险。",o:["损失防范","风险融资","风险转移","风险避免"],a:3,e:"完全不提供食物及饮料，从而彻底免除食物中毒的风险，属风险避免（回避）。损失防范是降低发生可能，风险融资与风险转移是财务安排，均与「彻底不做」不符。",src:1,tw:{ch:"風險與保險",q:"請說明以下風險工具： 不提供食物及飲料以免除食物中毒的風險。",o:["損失防範","風險融資","風險轉移","風險避免"],e:"完全不提供食物及飲料，從而徹底免除食物中毒的風險，屬風險避免（迴避）。損失防範是降低發生可能，風險融資與風險轉移是財務安排，均與「徹底不做」不符。"}},
{p:1,ch:"风险与保险",q:"请说明以下风险工具: 没有提供专业意见以消除法律责任的风险是?",o:["风险避免","风险融资","风险转移","损失防范"],a:0,e:"没有提供专业意见，从而彻底消除承担法律责任的风险，属风险避免。风险融资、风险转移、损失防范均非此类「彻底放弃该行为」的做法。",src:1,tw:{ch:"風險與保險",q:"請說明以下風險工具: 沒有提供專業意見以消除法律責任的風險是?",o:["風險避免","風險融資","風險轉移","損失防範"],e:"沒有提供專業意見，從而徹底消除承擔法律責任的風險，屬風險避免。風險融資、風險轉移、損失防範均非此類「徹底放棄該行為」的做法。"}},
{p:1,ch:"风险与保险",q:"进行工业安全活动属于哪种处理风险工具?",o:["风险避免","风险融资","风险转移","损失防范"],a:3,e:"进行工业安全活动旨在降低意外发生的可能性，属损失防范。风险避免是彻底不做该活动，风险融资与风险转移属资金安排，均不符。",src:1,tw:{ch:"風險與保險",q:"進行工業安全活動屬於哪種處理風險工具?",o:["風險避免","風險融資","風險轉移","損失防範"],e:"進行工業安全活動旨在降低意外發生的可能性，屬損失防範。風險避免是徹底不做該活動，風險融資與風險轉移屬資金安排，均不符。"}},
{p:1,ch:"风险与保险",q:"风险可以用潜在的财务后果及它的原因和影响去分类。财务后果包括纯粹风险 及:",o:["非纯粹风险","附加风险","衍生风险","投机风险"],a:3,e:"按潜在财务后果分类，风险分为纯粹风险与投机风险两类，故缺少的正是投机风险。非纯粹风险、附加风险、衍生风险均非标准分类。",src:1,tw:{ch:"風險與保險",q:"風險可以用潛在的財務後果及它的原因和影響去分類。財務後果包括純粹風險 及：",o:["非純粹風險","附加風險","衍生風險","投機風險"],e:"按潛在財務後果分類，風險分為純粹風險與投機風險兩類，故缺少的正是投機風險。非純粹風險、附加風險、衍生風險均非標準分類。"}},
{p:1,ch:"风险与保险",q:"风险和保险的联系:",o:["有些风险 (但不是所有类型) 是可以得到承保的","只要有保险的保障,所有的财务损失都是保险人的责任","就风险提供保障的唯一方法就是保险","所有风险都是可保的"],a:0,e:"有些风险（但不是所有类型）可以得到承保，这是保险与风险的正确关系。保险并非提供保障的唯一方法，也非所有风险皆可保，各类绝对化说法均有误。",src:1,tw:{ch:"風險與保險",q:"風險和保險的聯繫：",o:["有些風險 (但不是所有類型) 是可以得到承保的","只要有保險的保障，所有的財務損失都是保險人的責任","就風險提供保障的唯一方法就是保險","所有風險都是可保的"],e:"有些風險（但不是所有類型）可以得到承保，這是保險與風險的正確關係。保險並非提供保障的唯一方法，也非所有風險皆可保，各類絕對化說法均有誤。"}},
{p:1,ch:"风险与保险",q:"风险对保险人来说可以理解为: i. 保单所保「危险」或损失 ii. 承保的受风险财物或人身 iii. 对潜在损失的不确定性 iv. 在任何情形下都不可受保的",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:2,e:"保险人对「风险」可理解为保单所保的危险或损失（i）、承保的财物或人身（ii）及对潜在损失的不确定性（iii）均成立；「在任何情况下都不可保」（iv）错误，故不选。",src:1,tw:{ch:"風險與保險",q:"風險對保險人來說可以理解為： i. 保單所保「危險」或損失 ii. 承保的受風險財物或人身 iii. 對潛在損失的不確定性 iv. 在任何情形下都不可受保的",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"保險人對「風險」可理解為保單所保的危險或損失（i）、承保的財物或人身（ii）及對潛在損失的不確定性（iii）均成立；「在任何情況下都不可保」（iv）錯誤，故不選。"}},
{p:1,ch:"风险与保险",q:"风险管理在独立的知识及研究范畴上,一般的理解为:",o:["投资或投机风险所带来的损失","保险人对受保风险损失上的改善","以识别、量化及应对作为进行的步骤","环绕着对保险合约的订立及处理"],a:2,e:"作为独立知识及研究范畴，风险管理一般理解为以识别、量化及应对作为进行的步骤，故该项正确。只谈投资损失、承保改善或保险合约办理，均不完整。",src:1,tw:{ch:"風險與保險",q:"風險管理在獨立的知識及研究範疇上，一般的理解為：",o:["投資或投機風險所帶來的損失","保險人對受保風險損失上的改善","以識別、量化及應對作為進行的步驟","環繞着對保險合約的訂立及處理"],e:"作為獨立知識及研究範疇，風險管理一般理解為以識別、量化及應對作為進行的步驟，故該項正確。只談投資損失、承保改善或保險合約辦理，均不完整。"}},
{p:1,ch:"风险与保险",q:"风险转移机制的概念,以下哪项的描述是正确?",o:["与保险的关系不大","是保险的基本功能","是保险辅助功能的其中一个特点","不是以上所有各项"],a:1,e:"风险转移机制是保险的基本功能（核心要素），而非辅助功能，也并非与保险关系不大或全无关系。",src:1,tw:{ch:"風險與保險",q:"風險轉移機制的概念，以下哪項的描述是正確？",o:["與保險的關係不大","是保險的基本功能","是保險輔助功能的其中一個特點","不是以上所有各項"],e:"風險轉移機制是保險的基本功能（核心要素），而非輔助功能，也並非與保險關係不大或全無關係。"}},
{p:1,ch:"风险与保险",q:"风险转移机制的概念是:",o:["只适用于保险上","是保险的基本特点","是保险的辅助特点","只适用于人寿保险及海上货物保险"],a:1,e:"风险转移是保险的基本特点（基本功能），并非只适用于保险，也不是辅助特点或局限于人寿及海上货物保险，故该项正确。",src:1,tw:{ch:"風險與保險",q:"風險轉移機制的概念是：",o:["只適用於保險上","是保險的基本特點","是保險的輔助特點","只適用於人壽保險及海上貨物保險"],e:"風險轉移是保險的基本特點（基本功能），並非只適用於保險，也不是輔助特點或侷限於人壽及海上貨物保險，故該項正確。"}},
{p:1,ch:"风险与保险",q:"饥荒,战争及大规模水灾是属于哪类风险?",o:["纯粹风险","灾难风险","特定风险","基本风险"],a:3,e:"饥荒、战争及大规模水灾影响遍及整个社会，属基本风险。它们虽亦具纯粹性，但题目按影响范围分类，故应归入基本风险。",src:1,tw:{ch:"風險與保險",q:"饑荒，戰爭及大規模水災是屬於哪類風險？",o:["純粹風險","災難風險","特定風險","基本風險"],e:"饑荒、戰爭及大規模水災影響遍及整個社會，屬基本風險。它們雖亦具純粹性，但題目按影響範圍分類，故應歸入基本風險。"}},
{p:1,ch:"法律原则",q:"「一份协议的内容必须是合法的」,此句子形容合约元素中的哪一项:",o:["订约的行为能力","代价","合法性","订立法律关系意向"],a:2,e:"「协议内容必须是合法的」对应合约要素中的「合法性」，故该项正确。订约的行为能力、代价、订立法律关系的意向是其它合约要素，均不符题干表述。",src:1,tw:{ch:"法律原則",q:"「一份協議的內容必須是合法的」，此句子形容合約元素中的哪一項：",o:["訂約的行為能力","代價","合法性","訂立法律關係意向"],e:"「協議內容必須是合法的」對應合約要素中的「合法性」，故該項正確。訂約的行為能力、代價、訂立法律關係的意向是其它合約要素，均不符題幹表述。"}},
{p:1,ch:"法律原则",q:"「不容反悔」的代理关系来自:",o:["明示权限","法定条文","事后对代理人的行为所作的确认","据称的委托人的行为"],a:3,e:"「不容反悔」的代理关系源于据称的委托人的行为，即本人使第三方合理地相信代理权存在。明示权限、法定条文、事后确认均非其来源。",src:1,tw:{ch:"法律原則",q:"「不容反悔」的代理關係來自:",o:["明示權限","法定條文","事後對代理人的行為所作的確認","據稱的委託人的行為"],e:"「不容反悔」的代理關係源於據稱的委託人的行為，即本人使第三方合理地相信代理權存在。明示權限、法定條文、事後確認均非其來源。"}},
{p:1,ch:"法律原则",q:"「必要代理人」是指一名代理人,他:",o:["替一名未成年人士行事(未满18岁)","已经取得明示(书面或口头)指令","事后被有关委托人追认为代理人","因当时情况所需而无可非议地为另一人行事"],a:3,e:"「必要代理人」指因当时情况所需，而无可非议地为另一人（未经授权地）行事。替未成年人士行事、已取得明示指令、事后被追认，均非其定义特征。",src:1,tw:{ch:"法律原則",q:"「必要代理人」是指一名代理人，他:",o:["替一名未成年人士行事(未滿18歲)","已經取得明示(書面或口頭)指令","事後被有關委託人追認為代理人","因當時情況所需而無可非議地為另一人行事"],e:"「必要代理人」指因當時情況所需，而無可非議地為另一人（未經授權地）行事。替未成年人士行事、已取得明示指令、事後被追認，均非其定義特徵。"}},
{p:1,ch:"法律原则",q:"「明示实际权」的「明示」指:",o:["它是合约上的表达","突发或危急的情况下才给予权限","委托人向代理人表明的权限","总是书面给予权限"],a:2,e:"「明示实际权」的「明示」指委托人向代理人表明（明确授予）的权限，故该项正确。它不限于合约表达、亦非仅在危急时才给予，更不一定总是书面。",src:1,tw:{ch:"法律原則",q:"「明示實際權」的「明示」指：",o:["它是合約上的表達","突發或危急的情況下才給予權限","委託人向代理人表明的權限","總是書面給予權限"],e:"「明示實際權」的「明示」指委託人向代理人表明（明確授予）的權限，故該項正確。它不限於合約表達、亦非僅在危急時才給予，更不一定總是書面。"}},
{p:1,ch:"法律原则",q:"「明示权限」的明示是指:",o:["与订明合约条款中的「订明」的意思相同","于迫切或危急情况发生后必要的授权","委托人已明确地指示代理人","委托人对代理人的指示必须是书面的"],a:2,e:"「明示权限」的明示指委托人已明确地指示（授权）代理人，故该项正确。它并非只在危急后必要授权，亦不要求必须书面，与「订明」条款的含义也不尽相同。",src:1,tw:{ch:"法律原則",q:"「明示權限」的明示是指：",o:["與訂明合約條款中的「訂明」的意思相同","於迫切或危急情況發生後必要的授權","委託人已明確地指示代理人","委託人對代理人的指示必須是書面的"],e:"「明示權限」的明示指委託人已明確地指示（授權）代理人，故該項正確。它並非只在危急後必要授權，亦不要求必須書面，與「訂明」條款的含義也不盡相同。"}},
{p:1,ch:"法律原则",q:"「简单合约」是指:",o:["有效性并不取决于特殊的手续","只涉及一些不重要的事情","使用每人都明白的字句","不会涉及复杂和艰深的字句"],a:0,e:"「简单合约」指其有效性并不取决于特殊手续（如盖章、递送）的合约，故该项正确。它与所涉事情的重要性或字句深浅无关。",src:1,tw:{ch:"法律原則",q:"「簡單合約」是指：",o:["有效性並不取決於特殊的手續","只涉及一些不重要的事情","使用每人都明白的字句","不會涉及複雜和艱深的字句"],e:"「簡單合約」指其有效性並不取決於特殊手續（如蓋章、遞送）的合約，故該項正確。它與所涉事情的重要性或字句深淺無關。"}},
{p:1,ch:"法律原则",q:"「透过他人行事与自己亲自执行并无分别」,这属于下列哪个法律原则?",o:["代理法","合约法","保险法","《保险业条例》"],a:0,e:"「透过他人行事与自己亲自执行并无分别」体现的是代理关系本质（代理人行为视同本人行为），属代理法。合约法、保险法、保险业条例均非直接体现此原则。",src:1,tw:{ch:"法律原則",q:"「透過他人行事與自己親自執行並無分別」，這屬於下列哪個法律原則？",o:["代理法","合約法","保險法","《保險業條例》"],e:"「透過他人行事與自己親自執行並無分別」體現的是代理關係本質（代理人行為視同本人行為），屬代理法。合約法、保險法、保險業條例均非直接體現此原則。"}},
{p:1,ch:"法律原则",q:"「透过他人行事与自己亲自执行并无分别」。这个与以下哪一项是有最有关系的 法律原则?",o:["合约法","代理法","保险人的法律原则","以上各项皆是"],a:1,e:"「透过他人行事与自己亲自执行并无分别」最直接相关的是代理法，即代理人的行为归于本人，故答案为代理法；其它选项并非最贴切的法律原则。",src:1,tw:{ch:"法律原則",q:"「透過他人行事與自己親自執行並無分別」。這個與以下哪一項是有最有關係的 法律原則?",o:["合約法","代理法","保險人的法律原則","以上各項皆是"],e:"「透過他人行事與自己親自執行並無分別」最直接相關的是代理法，即代理人的行為歸於本人，故答案為代理法；其它選項並非最貼切的法律原則。"}},
{p:1,ch:"法律原则",q:"一个人在店舖内购买物件时,放下金钱并取走物件,过程中不发一言,在这种情 况下:",o:["属于违法事件","以行为证明下订立了合约","因为没有盖章及签署,故此订立了契据","已订立了一份记录合约"],a:1,e:"顾客放下金钱并取走物件、过程不发一言，是以行为证明下订立了合约（行为可表达要约与承约），故该项正确。此种交易并不违法，亦非契据或记录合约。",src:1,tw:{ch:"法律原則",q:"一個人在店舖內購買物件時，放下金錢並取走物件，過程中不發一言，在這種情 況下：",o:["屬於違法事件","以行為證明下訂立了合約","因為沒有蓋章及簽署,故此訂立了契據","已訂立了一份記錄合約"],e:"顧客放下金錢並取走物件、過程不發一言，是以行為證明下訂立了合約（行為可表達要約與承約），故該項正確。此種交易並不違法，亦非契據或記錄合約。"}},
{p:1,ch:"法律原则",q:"一个简单合约中,双方必须订出各自应付出的代价,以下哪项/哪些符合保险人 的代价? i 被保险人支付保费的承诺 ii 保险人赔付的承诺 iii 保险人赔付的款项 iv 保险人根据保单条款付出的承诺",o:["只有i","只有iii","ii, iv","i, iv"],a:3,e:"简单合约须双方付出代价：被保险人的代价是支付保费的承诺，保险人的代价是依保单条款作出赔付的承诺（ii、iv 正确）。已实际赔付的款项属履行而非承诺，故不选 iii。",src:1,tw:{ch:"法律原則",q:"一個簡單合約中,雙方必須訂出各自應付出的代價,以下哪項/哪些符合保險人 的代價? i 被保險人支付保費的承諾 ii 保險人賠付的承諾 iii 保險人賠付的款項 iv 保險人根據保單條款付出的承諾",o:["只有i","只有iii","ii, iv","i, iv"],e:"簡單合約須雙方付出代價：被保險人的代價是支付保費的承諾，保險人的代價是依保單條款作出賠付的承諾（ii、iv 正確）。已實際賠付的款項屬履行而非承諾，故不選 iii。"}},
{p:1,ch:"法律原则",q:"一份「可使无效」的合约,如果合约的受屈一方没有采取有关行动,那么:",o:["有关合约可在法庭上执行","有关合约在合理时间后便会变成无效","有关合约在合理时间后便不会变成无效","有关合约没有法律效力"],a:2,e:"「可使无效」的合约赋予受屈一方撤销的权利；若该方不采取行动，合约在合理时间后仍保持有效，不会自动变成无效，故该项正确。",src:1,tw:{ch:"法律原則",q:"一份「可使無效」的合約，如果合約的受屈一方沒有採取有關行動，那麼：",o:["有關合約可在法庭上執行","有關合約在合理時間後便會變成無效","有關合約在合理時間後便不會變成無效","有關合約沒有法律效力"],e:"「可使無效」的合約賦予受屈一方撤銷的權利；若該方不採取行動，合約在合理時間後仍保持有效，不會自動變成無效，故該項正確。"}},
{p:1,ch:"法律原则",q:"一份从行为中推断出来的合约称为:",o:["简单合约","契据","特别合约","行为合约"],a:0,e:"从行为中推断出来的合约仍属简单合约（无需特殊形式即可成立），故答案为简单合约。契据须签署、盖章及递送，特别合约与行为合约并非标准分类。",src:1,tw:{ch:"法律原則",q:"一份從行為中推斷出來的合約稱為：",o:["簡單合約","契據","特別合約","行為合約"],e:"從行為中推斷出來的合約仍屬簡單合約（無需特殊形式即可成立），故答案為簡單合約。契據須簽署、蓋章及遞送，特別合約與行為合約並非標準分類。"}},
{p:1,ch:"法律原则",q:"一份合约由于一些要求还未完成而令致有关合约无法执行,此称为:",o:["可使无效的合约","不能强制执行的合约","无效的合约","不合法的合约"],a:1,e:"合约因某些法定要求尚未完成而无法强制执行，称为不能强制执行的合约，故该项正确。可使无效、无效、不合法的合约各有其特定含义，均不符题意。",src:1,tw:{ch:"法律原則",q:"一份合約由於一些要求還未完成而令致有關合約無法執行，此稱為：",o:["可使無效的合約","不能強制執行的合約","無效的合約","不合法的合約"],e:"合約因某些法定要求尚未完成而無法強制執行，稱為不能強制執行的合約，故該項正確。可使無效、無效、不合法的合約各有其特定含義，均不符題意。"}},
{p:1,ch:"法律原则",q:"一份属于简单合约的保险,其代价:",o:["必须由双方付出","只须由被保险人付出","只须由保险人付出","无须由保险人或被保险人付出,但合约必须是书面"],a:0,e:"一份属于简单合约的保险，其代价必须由双方付出：被保险人付保费、保险人承诺赔付，故该项正确。仅一方付出或双方均无须付出的说法均有误。",src:1,tw:{ch:"法律原則",q:"一份屬於簡單合約的保險，其代價：",o:["必須由雙方付出","只須由被保險人付出","只須由保險人付出","無須由保險人或被保險人付出，但合約必須是書面"],e:"一份屬於簡單合約的保險，其代價必須由雙方付出：被保險人付保費、保險人承諾賠付，故該項正確。僅一方付出或雙方均無須付出的說法均有誤。"}},
{p:1,ch:"法律原则",q:"一份有别于必须签署、盖章及递送的合约,其订立形式简单,有效性不取决于特 殊手续的为:",o:["简单合约","契据","不复杂合约","纪录合约"],a:0,e:"订立形式简单、有效性不取决于特殊手续（无须盖章）的合约，即简单合约。契据须签署、盖章及递送；不复杂合约、纪录合约并非标准术语。",src:1,tw:{ch:"法律原則",q:"一份有別於必須簽署、蓋章及遞送的合約，其訂立形式簡單，有效性不取決於特 殊手續的為：",o:["簡單合約","契據","不複雜合約","紀錄合約"],e:"訂立形式簡單、有效性不取決於特殊手續（無須蓋章）的合約，即簡單合約。契據須簽署、蓋章及遞送；不復雜合約、紀錄合約並非標準術語。"}},
{p:1,ch:"法律原则",q:"一份简单合约需要满足一些条件,其中代价:",o:["双方都要付出","只需要保险人付出","只需要被保险人付出","双方都不需要付出,只需要在合约上约定即可"],a:0,e:"简单合约的代价要求双方都要付出：被保险人作支付保费承诺，保险人作赔付承诺，故该项正确。只要一方付出或双方均不付出的说法均错误。",src:1,tw:{ch:"法律原則",q:"一份簡單合約需要滿足一些條件，其中代價：",o:["雙方都要付出","只需要保險人付出","只需要被保險人付出","雙方都不需要付出，只需要在合約上約定即可"],e:"簡單合約的代價要求雙方都要付出：被保險人作支付保費承諾，保險人作賠付承諾，故該項正確。只要一方付出或雙方均不付出的說法均錯誤。"}},
{p:1,ch:"法律原则",q:"一位买者购买东西,付钱后完成交易,一份合约已经订立,称为:",o:["简单合约","不是合约,因为没有口头或者书面证明","是契据,因为没有口头或者书面证明","以上各项皆不是"],a:0,e:"买者付钱、卖方交付即完成交易，已透过行为订立一份合约，称为简单合约，故该项正确。说它因无口头书面证明即非合约，或属契据，均不正确。",src:1,tw:{ch:"法律原則",q:"一位買者購買東西，付錢後完成交易，一份合約已經訂立，稱為：",o:["簡單合約","不是合約，因為沒有口頭或者書面證明","是契據，因為沒有口頭或者書面證明","以上各項皆不是"],e:"買者付錢、賣方交付即完成交易，已透過行為訂立一份合約，稱為簡單合約，故該項正確。說它因無口頭書面證明即非合約，或屬契據，均不正確。"}},
{p:1,ch:"法律原则",q:"一位代理人何时可将责任下放予分代理人?",o:["只要他愿意随时也可","他认为合理便可","除非他具有这样的权限","当他收到委托人及分代理人的双份佣金之后"],a:2,e:"代理人原则上须亲自执行职务，只有在具有这样的权限（获委托人明示或默示授权）时，才可将责任下放予分代理人，故该项正确。随时或仅凭自认合理即可下放，均错误。",src:1,tw:{ch:"法律原則",q:"一位代理人何時可將責任下放予分代理人？",o:["只要他願意隨時也可","他認為合理便可","除非他具有這樣的權限","當他收到委託人及分代理人的雙份佣金之後"],e:"代理人原則上須親自執行職務，只有在具有這樣的權限（獲委託人明示或默示授權）時，才可將責任下放予分代理人，故該項正確。隨時或僅憑自認合理即可下放，均錯誤。"}},
{p:1,ch:"法律原则",q:"一名某人经过报纸贩卖档拿起一份报纸,表明要购买报纸, 这是:",o:["技术上不可能是合约","从行为中推断出来的合约","经盖章后发出的合约","无效的合约"],a:1,e:"顾客拿起报纸并表明要购买，是以行为表达要约，属从行为中推断出来的合约，故该项正确。这在技术上并非不可能，亦非经盖章发出或无效的合约。",src:1,tw:{ch:"法律原則",q:"一名某人經過報紙販賣檔拿起一份報紙，表明要購買報紙， 這是:",o:["技術上不可能是合約","從行為中推斷出來的合約","經蓋章後發出的合約","無效的合約"],e:"顧客拿起報紙並表明要購買，是以行為表達要約，屬從行為中推斷出來的合約，故該項正確。這在技術上並非不可能，亦非經蓋章發出或無效的合約。"}},
{p:1,ch:"法律原则",q:"一种要对他人的作为或不作为应付的法律责任:",o:["委托人责任","转承责任","附加责任","授权责任"],a:1,e:"对他人的作为或不作为须承担的法律责任，称为转承责任，故该项正确。委托人责任、附加责任、授权责任均非此法定概念的标准名称。",src:1,tw:{ch:"法律原則",q:"一種要對他人的作為或不作為應付的法律責任:",o:["委託人責任","轉承責任","附加責任","授權責任"],e:"對他人的作為或不作為須承擔的法律責任，稱為轉承責任，故該項正確。委託人責任、附加責任、授權責任均非此法定概念的標準名稱。"}},
{p:1,ch:"法律原则",q:"一项合法的代理关系原本订定为期一年,但由于法例于该代理关系开始六个月后 有所改变,导致该代理关系的内容违反法例,此情况下:",o:["该项代理关系即时终止","合约双方同意下,该代理关系可随时终止","于合约结束后即时终止","该关系依旧维持"],a:0,e:"当法例改变使代理关系的内容违反法律时，该项代理关系即时终止，无须待双方同意或合约期满，故该项正确。",src:1,tw:{ch:"法律原則",q:"一項合法的代理關係原本訂定為期一年，但由於法例於該代理關係開始六個月後 有所改變，導致該代理關係的內容違反法例，此情況下：",o:["該項代理關係即時終止","合約雙方同意下，該代理關係可隨時終止","於合約結束後即時終止","該關係依舊維持"],e:"當法例改變使代理關係的內容違反法律時，該項代理關係即時終止，無須待雙方同意或合約期滿，故該項正確。"}},
{p:1,ch:"法律原则",q:"下列哪三项有关长期保险合约的陈述是正确的? i 并非所有协议都是合约 ii 所有合约必须经盖章签发 iii 合约是一份在法律上可强制执行的协议 iv 严格来说,合约是无形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"并非所有协议都是合约（i）、合约是在法律上可强制执行的协议（iii）、严格来说合约是无形的（iv）均正确；而所有合约必须经盖章签发（ii）是错误的，故答案为 i、iii、iv。",src:1,tw:{ch:"法律原則",q:"下列哪三項有關長期保險合約的陳述是正確的? i 並非所有協議都是合約 ii 所有合約必須經蓋章簽發 iii 合約是一份在法律上可強制執行的協議 iv 嚴格來說，合約是無形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"並非所有協議都是合約（i）、合約是在法律上可強制執行的協議（iii）、嚴格來說合約是無形的（iv）均正確；而所有合約必須經蓋章簽發（ii）是錯誤的，故答案為 i、iii、iv。"}},
{p:1,ch:"法律原则",q:"下列哪项或哪些不是订立的合约正确的描述 ?",o:["可以是透过行为而订立","可以是书面及经盖章后发出","它必须是个人的合约","可以是口头及书面订立"],a:2,e:"合约可透过行为、口头及书面订立，并无「必须是个人的合约」这一说法，故选项「它必须是个人的合约」是不正确的描述，符合题意。",src:1,tw:{ch:"法律原則",q:"下列哪項或哪些不是訂立的合約正確的描述 ？",o:["可以是透過行為而訂立","可以是書面及經蓋章後發出","它必須是個人的合約","可以是口頭及書面訂立"],e:"合約可透過行為、口頭及書面訂立，並無「必須是個人的合約」這一說法，故選項「它必須是個人的合約」是不正確的描述，符合題意。"}},
{p:1,ch:"法律原则",q:"为他人采取紧急行动,并于行动时未获他人同意,在此情况下产生以下那种代理 关系?",o:["追认","确认","必要权限","表面权限"],a:2,e:"为他人采取紧急行动、于行动时未获其同意，在此情况下产生的是「必要权限」（必要代理）关系，故该项正确。追认、确认、表面权限均需其他条件，不合题意。",src:1,tw:{ch:"法律原則",q:"為他人採取緊急行動，並於行動時未獲他人同意，在此情況下產生以下那種代理 關係?",o:["追認","確認","必要權限","表面權限"],e:"為他人採取緊急行動、於行動時未獲其同意，在此情況下產生的是「必要權限」（必要代理）關係，故該項正確。追認、確認、表面權限均需其他條件，不合題意。"}},
{p:1,ch:"法律原则",q:"为何保险合约属于简单合约?",o:["因为它只涉及易于了解及简单的内容","因为在法律上必须以书面订立","因为没有指定要以书面订立","因为必须要以简易浅白的文字订立"],a:2,e:"保险合约属简单合约，是因为法律没有指定其必须以书面订立（无须契据形式），故该项正确。并非因为它内容简单或规定必须以浅白文字订立。",src:1,tw:{ch:"法律原則",q:"為何保險合約屬於簡單合約?",o:["因為它只涉及易於了解及簡單的內容","因為在法律上必須以書面訂立","因為沒有指定要以書面訂立","因為必須要以簡易淺白的文字訂立"],e:"保險合約屬簡單合約，是因為法律沒有指定其必須以書面訂立（無須契據形式），故該項正確。並非因為它內容簡單或規定必須以淺白文字訂立。"}},
{p:1,ch:"法律原则",q:"事后批准一些之前并未获授权的行为,这种做法称为:",o:["违法","追认","必要的代理关系","表面权限的代理关系"],a:1,e:"事后批准一些之前并未获授权的行为，在代理法中称为「追认」，故该项正确。这不属违法，亦非必要代理关系或表面权限。",src:1,tw:{ch:"法律原則",q:"事後批准一些之前並未獲授權的行為，這種做法稱為:",o:["違法","追認","必要的代理關係","表面權限的代理關係"],e:"事後批准一些之前並未獲授權的行為，在代理法中稱為「追認」，故該項正確。這不屬違法，亦非必要代理關係或表面權限。"}},
{p:1,ch:"法律原则",q:"于合约条款中,那方可在协议有效期间内撤销协议?",o:["委托人,不是代理人","代理人,不是委托人","委托人或代理人","不是委托人,也不是代理人"],a:2,e:"无论委托人或代理人均可在协议有效期间内通知对方以撤销代理关系，故答案为委托人或代理人。「只有一方可撤销」的说法均不完整。",src:1,tw:{ch:"法律原則",q:"於合約條款中，那方可在協議有效期間內撤銷協議?",o:["委託人，不是代理人","代理人，不是委託人","委託人或代理人","不是委託人，也不是代理人"],e:"無論委託人或代理人均可在協議有效期間內通知對方以撤銷代理關係，故答案為委託人或代理人。「只有一方可撤銷」的說法均不完整。"}},
{p:1,ch:"法律原则",q:"他人为某人采取某些行动,这人可以批准这个行动,并事后确认这个情况,在代 理法下,这称为:",o:["追认","确认","明示的代理权限","必要的代理权限"],a:0,e:"他人为某人采取行动、这人事后可批准并确认该行为，在代理法下称为「追认」，故该项正确。确认、明示权限、必要权限均非此情境的专有称谓。",src:1,tw:{ch:"法律原則",q:"他人為某人採取某些行動，這人可以批准這個行動，並事後確認這個情況，在代 理法下，這稱為：",o:["追認","確認","明示的代理權限","必要的代理權限"],e:"他人為某人採取行動、這人事後可批准並確認該行為，在代理法下稱為「追認」，故該項正確。確認、明示權限、必要權限均非此情境的專有稱謂。"}},
{p:1,ch:"法律原则",q:"代理人可以引用以下哪项情况终止代理关系?",o:["委托人已达到退休年龄","委托人已成立为有限公司","委托人基本地违反协议","以上所有各项"],a:2,e:"当委托人基本上违反协议时，代理人可引用此一理由终止代理关系，故该项正确。委托人达到退休年龄、成立为有限公司，本身并非法定的终止事由。",src:1,tw:{ch:"法律原則",q:"代理人可以引用以下哪項情況終止代理關係？",o:["委託人已達到退休年齡","委託人已成立為有限公司","委託人基本地違反協議","以上所有各項"],e:"當委託人基本上違反協議時，代理人可引用此一理由終止代理關係，故該項正確。委託人達到退休年齡、成立為有限公司，本身並非法定的終止事由。"}},
{p:1,ch:"法律原则",q:"代理人如未获本身委托人的授权采取若干行动,委托人事后仍可给予授权,这种 情况可视为 :",o:["违法","追认","明示代理","必要代理"],a:1,e:"代理人未获授权先采取行动，委托人事后仍可给予授权确认，这种情况在代理法中称为「追认」，故该项正确。它不属违法，亦非明示代理或必要代理。",src:1,tw:{ch:"法律原則",q:"代理人如未獲本身委託人的授權採取若干行動，委託人事後仍可給予授權，這種 情況可視為 :",o:["違法","追認","明示代理","必要代理"],e:"代理人未獲授權先採取行動，委託人事後仍可給予授權確認，這種情況在代理法中稱為「追認」，故該項正確。它不屬違法，亦非明示代理或必要代理。"}},
{p:1,ch:"法律原则",q:"代理人对委托人的责任包括: i 遵从 ii 忠心与诚信 iii 报帐 iv 承担委托人的所有合理开支",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各项皆正确"],a:0,e:"代理人对委托人的责任包括遵从指示、忠心与诚信、报帐（i、ii、iii 正确）。承担委托人的合理开支是委托人对代理人的义务，而非代理人的责任，故排除 iv。",src:1,tw:{ch:"法律原則",q:"代理人對委託人的責任包括： i 遵從 ii 忠心與誠信 iii 報帳 iv 承擔委託人的所有合理開支",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各項皆正確"],e:"代理人對委託人的責任包括遵從指示、忠心與誠信、報帳（i、ii、iii 正確）。承擔委託人的合理開支是委託人對代理人的義務，而非代理人的責任，故排除 iv。"}},
{p:1,ch:"法律原则",q:"代理人对委托人的责任包括? i 遵从 ii 亲自执行/不可下放给别人 iii 为委托人争取最佳利益 iv 保存清楚帐目",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"代理人须遵从指示、亲自执行（不可随意下放予别人）并保存清楚帐目（i、ii、iv 均正确）。「为委托人争取最佳利益」是经纪角色的特征，非代理人基本责任，故排除 iii。",src:1,tw:{ch:"法律原則",q:"代理人對委託人的責任包括? i 遵從 ii 親自執行/不可下放給別人 iii 為委託人爭取最佳利益 iv 保存清楚帳目",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"代理人須遵從指示、親自執行（不可隨意下放予別人）並保存清楚帳目（i、ii、iv 均正確）。「為委託人爭取最佳利益」是經紀角色的特徵，非代理人基本責任，故排除 iii。"}},
{p:1,ch:"法律原则",q:"代理人需对委托人的责任包括?",o:["遵行委托人合法地发出的指示","遵行委托人的一切指示","只要符合道德标准,遵行委托人的一切指示","安排分代理人执行有关指示"],a:0,e:"代理人须遵行委托人合法地发出的指示，而非遵行委托人的一切指示（违法者除外），故该项正确。以道德标准为据或安排分代理人执行，均非此项责任的内容。",src:1,tw:{ch:"法律原則",q:"代理人需對委託人的責任包括？",o:["遵行委託人合法地發出的指示","遵行委託人的一切指示","只要符合道德標準，遵行委託人的一切指示","安排分代理人執行有關指示"],e:"代理人須遵行委託人合法地發出的指示，而非遵行委託人的一切指示（違法者除外），故該項正確。以道德標準為據或安排分代理人執行，均非此項責任的內容。"}},
{p:1,ch:"法律原则",q:"代理人须向其委托人负上「报帐」的责任,是指代理人必须为代表委托人所收取 的金钱提供清楚证明,并且:",o:["只能间中地提供回佣","备存与代理业务有关的足够记录","用书面记录每次与委托人沟通的资料","在收取金钱的同一天,向委托人转付该笔金钱"],a:1,e:"「报帐」责任指代理人须为代收的金钱提供清楚证明，并备存与代理业务有关的足够记录，故该项正确。间中提供回佣、书面记录每次沟通、当日转付金钱均非其定义。",src:1,tw:{ch:"法律原則",q:"代理人須向其委託人負上「報帳」的責任，是指代理人必須為代表委託人所收取 的金錢提供清楚證明，並且：",o:["只能間中地提供回佣","備存與代理業務有關的足夠記錄","用書面記錄每次與委託人溝通的資料","在收取金錢的同一天，向委託人轉付該筆金錢"],e:"「報帳」責任指代理人須為代收的金錢提供清楚證明，並備存與代理業務有關的足夠記錄，故該項正確。間中提供回佣、書面記錄每次溝通、當日轉付金錢均非其定義。"}},
{p:1,ch:"法律原则",q:"代理关系可以透过以下哪项订立? i 明示协议 ii 隐含协议 iii 紧急的代理关系 iv 代理人的错误事故",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:2,e:"代理关系可透过明示协议、隐含协议及紧急的代理关系（必要代理）订立，故 i、ii、iii 正确。代理人的错误事故并不产生代理关系，故排除 iv。",src:1,tw:{ch:"法律原則",q:"代理關係可以透過以下哪項訂立? i 明示協議 ii 隱含協議 iii 緊急的代理關係 iv 代理人的錯誤事故",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"代理關係可透過明示協議、隱含協議及緊急的代理關係（必要代理）訂立，故 i、ii、iii 正確。代理人的錯誤事故並不產生代理關係，故排除 iv。"}},
{p:1,ch:"法律原则",q:"代理法适用于:",o:["只包括保险代理人","只包括保险经纪","既非保险代埋人,也非保险经纪","保险代理人及保险经纪"],a:3,e:"代理法普遍适用于各类代理关系，既包括保险代理人、也包括保险经纪，故答案为两者皆是。",src:1,tw:{ch:"法律原則",q:"代理法適用於：",o:["只包括保險代理人","只包括保險經紀","既非保險代埋人，也非保險經紀","保險代理人及保險經紀"],e:"代理法普遍適用於各類代理關係，既包括保險代理人、也包括保險經紀，故答案為兩者皆是。"}},
{p:1,ch:"法律原则",q:"代理的追认是指?",o:["化理人追认某次行动","代理人确认委托人","委托人追认代理人行动","委托人无须为代理负上法律责任除非代理作出追认"],a:2,e:"代理的追认指委托人（本人）对代理人之前未经授权的行动予以事后确认，故该项正确。不是代理人追认行动，也不是代理人确认委托人。",src:1,tw:{ch:"法律原則",q:"代理的追認是指?",o:["化理人追認某次行動","代理人確認委託人","委託人追認代理人行動","委託人無須為代理負上法律責任除非代理作出追認"],e:"代理的追認指委託人（本人）對代理人之前未經授權的行動予以事後確認，故該項正確。不是代理人追認行動，也不是代理人確認委託人。"}},
{p:1,ch:"法律原则",q:"以上哪一个原因不足以令代理关系终止?",o:["双方同意","大额索偿","其中一方辞世","违反协议"],a:1,e:"双方同意、其中一方辞世、违反协议均可令代理关系终止；而「大额索偿」并非代理关系的法定终止事由，故此项不足以终止代理关系，符合题意。",src:1,tw:{ch:"法律原則",q:"以上哪一個原因不足以令代理關係終止?",o:["雙方同意","大額索償","其中一方辭世","違反協議"],e:"雙方同意、其中一方辭世、違反協議均可令代理關係終止；而「大額索償」並非代理關係的法定終止事由，故此項不足以終止代理關係，符合題意。"}},
{p:1,ch:"法律原则",q:"以下哪一个陈述是正确描述要约:",o:["保险合约法的要约显着地有别于非保险合约法的要约","保险合约法的要约有点儿有别于非保险合约法的要约","保险合约法的要约完全有别于非保险合约法的要约","没有要约,没有合约"],a:3,e:"合约的成立必须有要约，没有要约便没有合约，故该项正确。保险合约法中的要约规则与一般合约法并无「显着／有点儿／完全有别」的分别，其余选项均不成立。",src:1,tw:{ch:"法律原則",q:"以下哪一個陳述是正確描述要約:",o:["保險合約法的要約顯着地有別於非保險合約法的要約","保險合約法的要約有點兒有別於非保險合約法的要約","保險合約法的要約完全有別於非保險合約法的要約","沒有要約,沒有合約"],e:"合約的成立必須有要約，沒有要約便沒有合約，故該項正確。保險合約法中的要約規則與一般合約法並無「顯着／有點兒／完全有別」的分別，其餘選項均不成立。"}},
{p:1,ch:"法律原则",q:"以下哪一项属于有缺陷的合约?",o:["简单合约","可使无效的合约","要约","承约"],a:1,e:"「可使无效的合约」属有缺陷的合约类别之一，故该项正确。简单合约是合约的形式，要约、承约是合约订立的要素，均非「有缺陷」的分类。",src:1,tw:{ch:"法律原則",q:"以下哪一項屬於有缺陷的合約？",o:["簡單合約","可使無效的合約","要約","承約"],e:"「可使無效的合約」屬有缺陷的合約類別之一，故該項正確。簡單合約是合約的形式，要約、承約是合約訂立的要素，均非「有缺陷」的分類。"}},
{p:1,ch:"法律原则",q:"以下哪三项关于一份法律责任保险合约是正确的? i   不是所有协议都具有法律效力 ii  必须是经盖章的 iii 是一份可强制执行的协议 iv  严格来说,合约是无形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"不是所有协议都具有法律效力（i）、合约是一份可强制执行的协议（iii）、严格来说合约是无形的（iv）均正确；合约不须经盖章（ii）错误，故答案为 i、iii、iv。",src:1,tw:{ch:"法律原則",q:"以下哪三項關於一份法律責任保險合約是正確的? i 不是所有協議都具有法律效力 ii 必須是經蓋章的 iii 是一份可強制執行的協議 iv 嚴格來說，合約是無形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"不是所有協議都具有法律效力（i）、合約是一份可強制執行的協議（iii）、嚴格來說合約是無形的（iv）均正確；合約不須經蓋章（ii）錯誤，故答案為 i、iii、iv。"}},
{p:1,ch:"法律原则",q:"以下哪三项对代理法的描述是正确的: i 委托人委托代理人 ii 保险经纪及保险代理人同属代理人 iii 委托人对代理人需负上转承责任 iv 只涉及保险经纪及保险代理人",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"委托人委托代理人（i）、保险经纪及保险代理人同属代理人（ii）、委托人对代理人负转承责任（iii）均正确。代理法适用于各类代理，并不仅涉及保险业两种代理（iv 错），故排除含 iv 的选项。",src:1,tw:{ch:"法律原則",q:"以下哪三項對代理法的描述是正確的: i 委託人委託代理人 ii 保險經紀及保險代理人同屬代理人 iii 委託人對代理人需負上轉承責任 iv 只涉及保險經紀及保險代理人",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"委託人委託代理人（i）、保險經紀及保險代理人同屬代理人（ii）、委託人對代理人負轉承責任（iii）均正確。代理法適用於各類代理，並不僅涉及保險業兩種代理（iv 錯），故排除含 iv 的選項。"}},
{p:1,ch:"法律原则",q:"以下哪三项有关仅以个人所涉及行为订立的简单合约的说明是不正确的? i 法律上,这种交易不是真正的合约 ii 这些是特殊情况,并因此称为特殊合约 iii 为使其合约有效,这种合约随后会以书面形式表达 iv 尽管不是以口头表达或书面方式,这种合约仍然是有效的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"仅以个人行为所订立的交易，在法律上仍是真正的合约（i 错）、并非「特殊情况下的特殊合约」（ii 错）、也无须随后以书面表达方为有效（iii 错）；iv 所述「虽非口头或书面仍有效」正确，故不正确者为 i、ii、iii。",src:1,tw:{ch:"法律原則",q:"以下哪三項有關僅以個人所涉及行為訂立的簡單合約的說明是不正確的? i 法律上，這種交易不是真正的合約 ii 這些是特殊情況，並因此稱為特殊合約 iii 為使其合約有效，這種合約隨後會以書面形式表達 iv 儘管不是以口頭表達或書面方式，這種合約仍然是有效的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"僅以個人行為所訂立的交易，在法律上仍是真正的合約（i 錯）、並非「特殊情況下的特殊合約」（ii 錯）、也無須隨後以書面表達方為有效（iii 錯）；iv 所述「雖非口頭或書面仍有效」正確，故不正確者為 i、ii、iii。"}},
{p:1,ch:"法律原则",q:"以下哪三项有关火险保单陈述是正确? i 并非所有协议都是合约 ii 合约是一份可以强制执行的协议 iii 合约可以经盖印而订立 iv 严格来说,所有合约都是无形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"并非所有协议都是合约（i）、合约是可强制执行的协议（ii）、严格来说所有合约都是无形的（iv）均正确；合约并非必须经盖印（iii 错），故答案为 i、ii、iv。",src:1,tw:{ch:"法律原則",q:"以下哪三項有關火險保單陳述是正確？ i 並非所有協議都是合約 ii 合約是一份可以強制執行的協議 iii 合約可以經蓋印而訂立 iv 嚴格來說，所有合約都是無形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"並非所有協議都是合約（i）、合約是可強制執行的協議（ii）、嚴格來說所有合約都是無形的（iv）均正確；合約並非必須經蓋印（iii 錯），故答案為 i、ii、iv。"}},
{p:1,ch:"法律原则",q:"以下哪两项有关简单合约的陈述是正确的? i 它们永不可以用书面形式出现 ii 它们不是经盖章后发出 iii 它们在任何情况下必须用书面形式出现 iv 它们可以是口头或书面性质出现",o:["i及ii","i及iii","ii及iii","ii及iv"],a:3,e:"简单合约不是经盖章后发出（ii 对），可以是口头或书面性质出现（iv 对）；「永不／必须用书面形式」（i、iii）均错误，故答案为 ii 及 iv。",src:1,tw:{ch:"法律原則",q:"以下哪兩項有關簡單合約的陳述是正確的？ i 它們永不可以用書面形式出現 ii 它們不是經蓋章後發出 iii 它們在任何情況下必須用書面形式出現 iv 它們可以是口頭或書面性質出現",o:["i及ii","i及iii","ii及iii","ii及iv"],e:"簡單合約不是經蓋章後發出（ii 對），可以是口頭或書面性質出現（iv 對）；「永不／必須用書面形式」（i、iii）均錯誤，故答案為 ii 及 iv。"}},
{p:1,ch:"法律原则",q:"以下哪些关于专业弥偿保险合约的描述是正确的?",o:["不是所有协议都是合约","合约必须经过盖章发出","合约是无形的","A及C"],a:3,e:"并非所有协议都是合约（A 对），且严格来说合约是无形的（C 对）；合约无须经过盖章发出（B 错），故答案为 A 及 C。",src:1,tw:{ch:"法律原則",q:"以下哪些關於專業彌償保險合約的描述是正確的？",o:["不是所有協議都是合約","合約必須經過蓋章發出","合約是無形的","A及C"],e:"並非所有協議都是合約（A 對），且嚴格來說合約是無形的（C 對）；合約無須經過蓋章發出（B 錯），故答案為 A 及 C。"}},
{p:1,ch:"法律原则",q:"以下哪些或哪项是「表面权限」正确的描述?",o:["明确的授权","代理人的行为协助委托人订立合约,令委托人受到约束","存在实际权限","没有授权"],a:1,e:"表面权限（表见代理权）指虽无实际授权，但委托人的言行使第三者合理地相信代理人有权限，代理人的行为因此约束委托人。其余选项「明确的授权」「存在实际权限」指实际权限，「没有授权」则与表面权限相反。",src:1,tw:{ch:"法律原則",q:"以下哪些或哪項是「表面權限」正確的描述？",o:["明確的授權","代理人的行為協助委託人訂立合約，令委託人受到約束","存在實際權限","沒有授權"],e:"表面權限（表見代理權）指雖無實際授權，但委託人的言行使第三者合理地相信代理人有權限，代理人的行為因此約束委託人。其餘選項「明確的授權」「存在實際權限」指實際權限，「沒有授權」則與表面權限相反。"}},
{p:1,ch:"法律原则",q:"以下哪些是代理的关系:",o:["法律认可的关系","具备订立法律关系的意向","受代理合约所支配","代价"],a:0,e:"代理关系是由法律认可的关系，委托人据此授权代理人代表其与第三者订立法律关系。代价、订立法律关系的意向及受代理合约支配并非代理关系成立的必备条件，故不选。",src:1,tw:{ch:"法律原則",q:"以下哪些是代理的關係:",o:["法律認可的關係","具備訂立法律關係的意向","受代理合約所支配","代價"],e:"代理關係是由法律認可的關係，委託人據此授權代理人代表其與第三者訂立法律關係。代價、訂立法律關係的意向及受代理合約支配並非代理關係成立的必備條件，故不選。"}},
{p:1,ch:"法律原则",q:"以下哪些是契据的描述? i 必须是书面 ii 必须经盖印 iii 毋须书面 iv 永不会是保险合约",o:["i, ii","ii, iii","i, ii, iv","iii, iv"],a:0,e:"契据是经签署、盖印并交付的书面文件，故 i、ii 正确。契据必须以书面形式作出，且担保等亦可以契据订立，故 iii、iv 错误。",src:1,tw:{ch:"法律原則",q:"以下哪些是契據的描述? i 必須是書面 ii 必須經蓋印 iii 毋須書面 iv 永不會是保險合約",o:["i, ii","ii, iii","i, ii, iv","iii, iv"],e:"契據是經簽署、蓋印並交付的書面文件，故 i、ii 正確。契據必須以書面形式作出，且擔保等亦可以契據訂立，故 iii、iv 錯誤。"}},
{p:1,ch:"法律原则",q:"以下哪些有关明示实际权限是正确? i. 合约明示 ii. 口头指示 iii. 书面表示 iv. 明确显示",o:["i, iv","i, ii","ii, iii","i,ii, iii, iv"],a:2,e:"明示实际权限是指以口头指示或书面表示等清楚方式表达出来的权限，故 ii、iii 正确。其余两项虽相关，但并非本题所指明示权限的典型形式。",src:1,tw:{ch:"法律原則",q:"以下哪些有關明示實際權限是正確? i. 合約明示 ii. 口頭指示 iii. 書面表示 iv. 明確顯示",o:["i, iv","i, ii","ii, iii","i,ii, iii, iv"],e:"明示實際權限是指以口頭指示或書面表示等清楚方式表達出來的權限，故 ii、iii 正確。其餘兩項雖相關，但並非本題所指明示權限的典型形式。"}},
{p:1,ch:"法律原则",q:"以下哪方或哪一方精神错乱可构成终止保险代理合约?",o:["委托人(自然人)","代理人(法定团体)的董事","委托人(法定团体)的常务董事","以上任何一方"],a:0,e:"精神错乱作为终止代理关系的原因只适用于自然人，故委托人（自然人）精神错乱才可终止保险代理合约。法定团体的董事或常务董事精神错乱不影响法团自身订约资格。",src:1,tw:{ch:"法律原則",q:"以下哪方或哪一方精神錯亂可構成終止保險代理合約?",o:["委託人(自然人)","代理人(法定團體)的董事","委託人(法定團體)的常務董事","以上任何一方"],e:"精神錯亂作為終止代理關係的原因只適用於自然人，故委託人（自然人）精神錯亂才可終止保險代理合約。法定團體的董事或常務董事精神錯亂不影響法團自身訂約資格。"}},
{p:1,ch:"法律原则",q:"以下哪种合约是保险人在正常情况下会以契据方式成立的?",o:["忠诚保证保险","强制性(第三者)汽车保险","担保","以上所有各项"],a:2,e:"担保常因缺乏代价支持而必须以契据（盖印）形式订立方有效。忠诚保证保险及强制性汽车保险属一般保险，通常以简单合约订立。",src:1,tw:{ch:"法律原則",q:"以下哪種合約是保險人在正常情況下會以契據方式成立的？",o:["忠誠保證保險","強制性(第三者)汽車保險","擔保","以上所有各項"],e:"擔保常因缺乏代價支持而必須以契據（蓋印）形式訂立方有效。忠誠保證保險及強制性汽車保險屬一般保險，通常以簡單合約訂立。"}},
{p:1,ch:"法律原则",q:"以下哪种情况下,代理人可以撤销代理关系?",o:["这未有条文禁止有关行为","它包含一项取消条款","委托人未于指定期内给予代理人有关报酬","委托人已经精神错乱"],a:1,e:"若代理合约载有取消（撤销）条款，代理人即可依约行使撤销权终止代理关系。其余情形均不构成可据以撤销代理关系的正当根据。",src:1,tw:{ch:"法律原則",q:"以下哪種情況下，代理人可以撤銷代理關係？",o:["這未有條文禁止有關行為","它包含一項取消條款","委託人未於指定期內給予代理人有關報酬","委託人已經精神錯亂"],e:"若代理合約載有取消（撤銷）條款，代理人即可依約行使撤銷權終止代理關係。其餘情形均不構成可據以撤銷代理關係的正當根據。"}},
{p:1,ch:"法律原则",q:"以下哪类人士在订约的行为能力方面可能会受到限制?",o:["精神错乱","未满十八岁","破产人士","以上所有各项"],a:3,e:"精神错乱者、未满十八岁的未成年人及破产人士，其订立合约的行为能力均可能受法律限制，故以上各项皆属受限人士。",src:1,tw:{ch:"法律原則",q:"以下哪類人士在訂約的行為能力方面可能會受到限制?",o:["精神錯亂","未滿十八歲","破產人士","以上所有各項"],e:"精神錯亂者、未滿十八歲的未成年人及破產人士，其訂立合約的行為能力均可能受法律限制，故以上各項皆屬受限人士。"}},
{p:1,ch:"法律原则",q:"以下哪项不属于代理人对委托人的责任?",o:["遵从指示","亲自执行","所有帐目必须以电脑形式记录","必须保存与代理业务有关的足够纪录"],a:2,e:"代理人对委托人的责任包括遵从指示、亲自执行及保存足够业务纪录，但并无必须「以电脑形式记录所有帐目」的要求，故该项不属于代理人责任。",src:1,tw:{ch:"法律原則",q:"以下哪項不屬於代理人對委託人的責任？",o:["遵從指示","親自執行","所有帳目必須以電腦形式記錄","必須保存與代理業務有關的足夠紀錄"],e:"代理人對委託人的責任包括遵從指示、親自執行及保存足夠業務紀錄，但並無必須「以電腦形式記錄所有帳目」的要求，故該項不屬於代理人責任。"}},
{p:1,ch:"法律原则",q:"以下哪项不是代理人向委托人负上的责任?",o:["遵行其委托人所有合法的指示","代理人要忠心与诚信","代理人只向委托人介绍有利可图的生意","代理人没有权利将责任下放给他人,除非得到这样的权限"],a:2,e:"代理人须忠心与诚信、遵从委托人合法指示，且非经授权不得转委托。代理人并无「只向委托人介绍有利可图生意」的义务，故该项不属于代理人的责任。",src:1,tw:{ch:"法律原則",q:"以下哪項不是代理人向委託人負上的責任?",o:["遵行其委託人所有合法的指示","代理人要忠心與誠信","代理人只向委託人介紹有利可圖的生意","代理人沒有權利將責任下放給他人，除非得到這樣的權限"],e:"代理人須忠心與誠信、遵從委託人合法指示，且非經授權不得轉委託。代理人並無「只向委託人介紹有利可圖生意」的義務，故該項不屬於代理人的責任。"}},
{p:1,ch:"法律原则",q:"以下哪项不是委托人对代理人的责任:",o:["给予代理人协定的报酬","给予代理人协定的正当开支","给予代理人合理的报酬","保证代理人的报酬会因价格不同而有所调整"],a:3,e:"委托人须支付协定或合理的报酬及正当开支，但无须保证报酬会因价格变动而调整，故该项并非委托人的责任。",src:1,tw:{ch:"法律原則",q:"以下哪項不是委託人對代理人的責任:",o:["給予代理人協定的報酬","給予代理人協定的正當開支","給予代理人合理的報酬","保證代理人的報酬會因價格不同而有所調整"],e:"委託人須支付協定或合理的報酬及正當開支，但無須保證報酬會因價格變動而調整，故該項並非委託人的責任。"}},
{p:1,ch:"法律原则",q:"以下哪项不是委托人对代理人的责任?",o:["报帐","支出","报酬","违反责任"],a:0,e:"报帐是代理人对委托人的责任，即按委托人名义收取的款项须向委托人交代，而非委托人对代理人的责任。支出、报酬及违反责任均属委托人应向代理人承担的义务范畴。",src:1,tw:{ch:"法律原則",q:"以下哪項不是委託人對代理人的責任？",o:["報帳","支出","報酬","違反責任"],e:"報帳是代理人對委託人的責任，即按委託人名義收取的款項須向委託人交代，而非委託人對代理人的責任。支出、報酬及違反責任均屬委託人應向代理人承擔的義務範疇。"}},
{p:1,ch:"法律原则",q:"以下哪项为保险代理关系终止的途径?",o:["撤销","冲突","不忠诚","以上各项皆是"],a:0,e:"撤销（如依合约条款或双方同意）是终止保险代理关系的途径之一。冲突或不忠诚本身并非独立的终止方式，只有构成违反责任时才可能引致撤销。",src:1,tw:{ch:"法律原則",q:"以下哪項為保險代理關係終止的途徑?",o:["撤銷","衝突","不忠誠","以上各項皆是"],e:"撤銷（如依合約條款或雙方同意）是終止保險代理關係的途徑之一。衝突或不忠誠本身並非獨立的終止方式，只有構成違反責任時才可能引致撤銷。"}},
{p:1,ch:"法律原则",q:"以下哪项会导致终止代理关系? i 双方同意 ii 撤销协议 iii 其中一方辞世 iv 精神错乱",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"双方同意、撤销协议、任何一方辞世及精神错乱，均可导致代理关系终止，故 i、ii、iii、iv 全部正确。",src:1,tw:{ch:"法律原則",q:"以下哪項會導致終止代理關係? i 雙方同意 ii 撤銷協議 iii 其中一方辭世 iv 精神錯亂",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"雙方同意、撤銷協議、任何一方辭世及精神錯亂，均可導致代理關係終止，故 i、ii、iii、iv 全部正確。"}},
{p:1,ch:"法律原则",q:"以下哪项关于简单合约的陈述是正确的?",o:["它必须经过实质交付","它可以书面或口头方式订立","它必须盖章后发出","以上皆是"],a:1,e:"简单合约无需盖印或实质交付，可以书面或口头方式订立。盖章、交付是契据的特征，故不选。",src:1,tw:{ch:"法律原則",q:"以下哪項關於簡單合約的陳述是正確的？",o:["它必須經過實質交付","它可以書面或口頭方式訂立","它必須蓋章後發出","以上皆是"],e:"簡單合約無需蓋印或實質交付，可以書面或口頭方式訂立。蓋章、交付是契據的特徵，故不選。"}},
{p:1,ch:"法律原则",q:"以下哪项关于要约的描述是正确的?",o:["根据普通法,投保人向保险人填交任何投保书就是 代表向保险人发出要约","人寿保险的要约法跟一般保险的要约法是不同的","要约在合约中是不重要的","没有要约,没有合约"],a:3,e:"合约成立须具备要约与承约，没有要约便无从订立合约。其余选项或与普通法规则不符，或贬低要约的重要性，均不正确。",src:1,tw:{ch:"法律原則",q:"以下哪項關於要約的描述是正確的？",o:["根據普通法，投保人向保險人填交任何投保書就是 代表向保險人發出要約","人壽保險的要約法跟一般保險的要約法是不同的","要約在合約中是不重要的","没有要約，沒有合約"],e:"合約成立須具備要約與承約，沒有要約便無從訂立合約。其餘選項或與普通法規則不符，或貶低要約的重要性，均不正確。"}},
{p:1,ch:"法律原则",q:"以下哪项对可使无效的保险合约之陈述是正确的?",o:["可使无效的合约是永远不能变为有效的","可使无效与无效两者的含意完全相同","受屈的一方可于合理时间内把合约视为无效","只有被保险人才能把保单视作可使无效 (即可予以取消)"],a:2,e:"可使无效（可撤销）合约可由受屈一方在合理时间内选择撤销，使合约归于无效。它并非永远无效，亦不只限于被保险人一方可使其无效。",src:1,tw:{ch:"法律原則",q:"以下哪項對可使無效的保險合約之陳述是正確的?",o:["可使無效的合約是永遠不能變為有效的","可使無效與無效兩者的含意完全相同","受屈的一方可於合理時間內把合約視為無效","只有被保險人才能把保單視作可使無效 (即可予以取消)"],e:"可使無效（可撤銷）合約可由受屈一方在合理時間內選擇撤銷，使合約歸於無效。它並非永遠無效，亦不只限於被保險人一方可使其無效。"}},
{p:1,ch:"法律原则",q:"以下哪项对委托人支付给代理人之报酬的描述是正确的?",o:["不包括佣金","经由有关的行业或机构设定的计算表计算","在该财政年度完结时支付","须于合理时间或任何指定的期限内支付"],a:3,e:"委托人应于合理时间或指定期限内支付协定的报酬，报酬可包括佣金，无须一律按行业计算表或于财政年度支付。",src:1,tw:{ch:"法律原則",q:"以下哪項對委託人支付給代理人之報酬的描述是正確的？",o:["不包括佣金","經由有關的行業或機構設定的計算表計算","在該財政年度完結時支付","須於合理時間或任何指定的期限內支付"],e:"委託人應於合理時間或指定期限內支付協定的報酬，報酬可包括佣金，無須一律按行業計算表或於財政年度支付。"}},
{p:1,ch:"法律原则",q:"以下哪项对法律开支合约的描述是正确的?",o:["严格来说,合约是无形的","不是所有协议都是合约","是可在法律上强制执行的协议","以上各项皆是"],a:3,e:"合约是可在法律上强制执行的协议，严格而言无形，且并非所有协议都构成合约，三项陈述均正确。",src:1,tw:{ch:"法律原則",q:"以下哪項對法律開支合約的描述是正確的?",o:["嚴格來說，合約是無形的","不是所有協議都是合約","是可在法律上強制執行的協議","以上各項皆是"],e:"合約是可在法律上強制執行的協議，嚴格而言無形，且並非所有協議都構成合約，三項陳述均正確。"}},
{p:1,ch:"法律原则",q:"以下哪项对简单合约之陈述是正确的?",o:["不经盖章的书面合约","必须经盖章后发出才有效","口头合约","A及C"],a:3,e:"简单合约既可不经盖章而以书面订立，亦可以口头形式订立，故 A 及 C 均属简单合约的正确描述。",src:1,tw:{ch:"法律原則",q:"以下哪項對簡單合約之陳述是正確的?",o:["不經蓋章的書面合約","必須經蓋章後發出才有效","口頭合約","A及C"],e:"簡單合約既可不經蓋章而以書面訂立，亦可以口頭形式訂立，故 A 及 C 均屬簡單合約的正確描述。"}},
{p:1,ch:"法律原则",q:"以下哪项或哪些关于死亡或清盘而中止的代理协议是正确的?",o:["委托人的死亡可构成有效的原因","代理人的死亡可构成有效的原因","法团委托人或代理人清盘可构成有效的原因","以上各项皆正确"],a:3,e:"委托人或代理人死亡，以及法团委托人或代理人清盘，均可构成终止代理协议的有效原因，故三项皆正确。",src:1,tw:{ch:"法律原則",q:"以下哪項或哪些關於死亡或清盤而中止的代理協議是正確的？",o:["委託人的死亡可構成有效的原因","代理人的死亡可構成有效的原因","法團委託人或代理人清盤可構成有效的原因","以上各項皆正確"],e:"委託人或代理人死亡，以及法團委託人或代理人清盤，均可構成終止代理協議的有效原因，故三項皆正確。"}},
{p:1,ch:"法律原则",q:"以下哪项或哪些关于死亡或清盘而终止代理人合约的论述是正确的?",o:["委托人死亡可构成有效的原因","代理人死亡可构成有效的原因","委托人的法团或代理人清盘可构成有效原因","以上各项皆属正确"],a:3,e:"同前：委托人或代理人死亡、法团清盘均是终止代理人合约的有效原因，故各项皆属正确。",src:1,tw:{ch:"法律原則",q:"以下哪項或哪些關於死亡或清盤而終止代理人合約的論述是正確的?",o:["委託人死亡可構成有效的原因","代理人死亡可構成有效的原因","委託人的法團或代理人清盤可構成有效原因","以上各項皆屬正確"],e:"同前：委託人或代理人死亡、法團清盤均是終止代理人合約的有效原因，故各項皆屬正確。"}},
{p:1,ch:"法律原则",q:"以下哪项或哪些是一份简单合约必要的?",o:["必须以书面形式订立","合约的各方都需付出代价","用词必须简单及容易明白","以上各项皆是"],a:1,e:"简单合约的必要元素之一是各订约方均须付出代价，用以支持承诺的履行。书面形式及浅白用语并非必备要求。",src:1,tw:{ch:"法律原則",q:"以下哪項或哪些是一份簡單合約必要的?",o:["必須以書面形式訂立","合約的各方都需付出代價","用詞必須簡單及容易明白","以上各項皆是"],e:"簡單合約的必要元素之一是各訂約方均須付出代價，用以支持承諾的履行。書面形式及淺白用語並非必備要求。"}},
{p:1,ch:"法律原则",q:"以下哪项或哪些有关代理人的「报帐」的评论是正确的?",o:["它必须对替本身委托人所收取所有的金钱报帐","它必须保存足够与代理业务有关的记录","它必须对以委托人的名义所收取的其他所有物件报帐","以上所有评论都是正确"],a:3,e:"代理人须就为委托人收取的所有金钱及其他物件报帐，并保存充足业务纪录，三项评论均正确。",src:1,tw:{ch:"法律原則",q:"以下哪項或哪些有關代理人的「報帳」的評論是正確的?",o:["它必須對替本身委託人所收取所有的金錢報帳","它必須保存足夠與代理業務有關的記錄","它必須對以委託人的名義所收取的其他所有物件報帳","以上所有評論都是正確"],e:"代理人須就為委託人收取的所有金錢及其他物件報帳，並保存充足業務紀錄，三項評論均正確。"}},
{p:1,ch:"法律原则",q:"以下哪项描述委托人追认并确认对代理人的关系?",o:["委托人有效地追溯与某人的代理关系","代理人在行事之前已经得到委托人的明示权限","代理人曾在紧急的情况下替委托人行事","代理人以往亦曾在汲有得到授权的情况下,替委托人做过类似的事情"],a:0,e:"追认指委托人追溯确认某人先前未经授权却代其作出的行为，使该行为自此对其产生约束力，故该项正确。",src:1,tw:{ch:"法律原則",q:"以下哪項描述委託人追認並確認對代理人的關係?",o:["委託人有效地追溯與某人的代理關係","代理人在行事之前已經得到委託人的明示權限","代理人曾在緊急的情況下替委託人行事","代理人以往亦曾在汲有得到授權的情況下，替委託人做過類似的事情"],e:"追認指委託人追溯確認某人先前未經授權卻代其作出的行為，使該行為自此對其產生約束力，故該項正確。"}},
{p:1,ch:"法律原则",q:"以下哪项是简单合约不必要的元素?",o:["合法性","代价","订立法律关系的意向","合理和公平的价格"],a:3,e:"简单合约须具备合法性、代价及订立法律关系的意向，但并无要求价格「合理公平」，故该项为不必要元素。",src:1,tw:{ch:"法律原則",q:"以下哪項是簡單合約不必要的元素？",o:["合法性","代價","訂立法律關係的意向","合理和公平的價格"],e:"簡單合約須具備合法性、代價及訂立法律關係的意向，但並無要求價格「合理公平」，故該項為不必要元素。"}},
{p:1,ch:"法律原则",q:"以下哪项是简单合约必须具有的条件? i 代价 ii 要约 iii 签署及盖章 iv 必定以书面形式发出",o:["只有i","i及ii","i, ii, iii","i, ii, iii, iv"],a:1,e:"代价与要约均是简单合约必须具备的条件；签署盖章或以书面发出并非简单合约成立的齐全要件，故只选 i 及 ii。",src:1,tw:{ch:"法律原則",q:"以下哪項是簡單合約必須具有的條件？ i 代價 ii 要約 iii 簽署及蓋章 iv 必定以書面形式發出",o:["只有i","i及ii","i, ii, iii","i, ii, iii, iv"],e:"代價與要約均是簡單合約必須具備的條件；簽署蓋章或以書面發出並非簡單合約成立的齊全要件，故只選 i 及 ii。"}},
{p:1,ch:"法律原则",q:"以下哪项是简单合约的真实形容?",o:["它不可解释作贵重财物的投保","它可以是书面或口头的","它必须经盖章后发出才有效","以上没有一项是正确的"],a:1,e:"简单合约可以书面或口头形式订立，无须盖章始生效力，故「可以是书面或口头」为正确描述。",src:1,tw:{ch:"法律原則",q:"以下哪項是簡單合約的真實形容?",o:["它不可解釋作貴重財物的投保","它可以是書面或口頭的","它必須經蓋章後發出才有效","以上沒有一項是正確的"],e:"簡單合約可以書面或口頭形式訂立，無須蓋章始生效力，故「可以是書面或口頭」為正確描述。"}},
{p:1,ch:"法律原则",q:"以下哪项有关「直接责任」及「转承责任」的描述是不正确的?",o:["直接责任是指对自己的行为负上责任","直接责任是指对他人的行为负上责任","转承责任是指对他人行为疏忽所构成的责任负责","转承责任是指对他人的行为负上责任"],a:1,e:"直接责任是指对自己的行为负责，转承责任才是指因他人（如雇员或代理人）的行为而负责任，故「直接责任是对他人行为负责」不正确。",src:1,tw:{ch:"法律原則",q:"以下哪項有關「直接責任」及「轉承責任」的描述是不正確的?",o:["直接責任是指對自己的行為負上責任","直接責任是指對他人的行為負上責任","轉承責任是指對他人行為疏忽所構成的責任負責","轉承責任是指對他人的行為負上責任"],e:"直接責任是指對自己的行為負責，轉承責任才是指因他人（如僱員或代理人）的行為而負責任，故「直接責任是對他人行為負責」不正確。"}},
{p:1,ch:"法律原则",q:"以下哪项有关反要约是正确的? i 原要约人变成受要约人 ii 受要约人变成要约人 iii 原要约人可决定是否接受反要约建议 iv 如不接纳反要约,必须跟随原有要约进行",o:["i, ii","ii, iii","i, ii, iii","ii,iii, iv"],a:2,e:"作出反要约后，原受要约人成为新要约人，原要约人则成为受要约人并有权决定是否接受；并不强制须跟随原要约，故 i、ii、iii 正确。",src:1,tw:{ch:"法律原則",q:"以下哪項有關反要約是正確的？ i 原要約人變成受要約人 ii 受要約人變成要約人 iii 原要約人可決定是否接受反要約建議 iv 如不接納反要約，必須跟隨原有要約進行",o:["i, ii","ii, iii","i, ii, iii","ii,iii, iv"],e:"作出反要約後，原受要約人成為新要約人，原要約人則成為受要約人並有權決定是否接受；並不強制須跟隨原要約，故 i、ii、iii 正確。"}},
{p:1,ch:"法律原则",q:"以下哪项有关合约的陈述是不正确的?",o:["一份在法律上可强制执行的协议","严格来说,合约是无形的东西","所有合约都是协议","所有协议都是合约"],a:3,e:"所有合约都是协议，但并非所有协议都构成合约；只有具备法律效力要件的协议才是合约，故「所有协议都是合约」错误。",src:1,tw:{ch:"法律原則",q:"以下哪項有關合約的陳述是不正確的？",o:["一份在法律上可強制執行的協議","嚴格來說，合約是無形的東西","所有合約都是協議","所有協議都是合約"],e:"所有合約都是協議，但並非所有協議都構成合約；只有具備法律效力要件的協議才是合約，故「所有協議都是合約」錯誤。"}},
{p:1,ch:"法律原则",q:"以下哪项正确描述简单合约?",o:["必须以易于理解及明白的语言订立","可以书面或口头方或订立","必须以盖章形或订立","以上各项皆不正确"],a:1,e:"简单合约可以书面或口头方式订立，无须盖章，用语亦无严格要求，故第二项正确。",src:1,tw:{ch:"法律原則",q:"以下哪項正確描述簡單合約?",o:["必須以易於理解及明白的語言訂立","可以書面或口頭方或訂立","必須以蓋章形或訂立","以上各項皆不正確"],e:"簡單合約可以書面或口頭方式訂立，無須蓋章，用語亦無嚴格要求，故第二項正確。"}},
{p:1,ch:"法律原则",q:"保单在执行上往往以甚么形式出现?",o:["口头性质","经盖章后发出","书面","用词简单及易于明白"],a:2,e:"保险单在执行上通常以书面形式签发，虽属简单合约毋须盖章，但实务中均以文件形式呈现。",src:1,tw:{ch:"法律原則",q:"保單在執行上往往以甚麼形式出現?",o:["口頭性質","經蓋章後發出","書面","用詞簡單及易於明白"],e:"保險單在執行上通常以書面形式簽發，雖屬簡單合約毋須蓋章，但實務中均以文件形式呈現。"}},
{p:1,ch:"法律原则",q:"保险中介人是指哪些人士?",o:["保险代理人","保险经纪","保险代理人或保险经纪","保险代理人及保险经纪"],a:3,e:"保险中介人包括保险代理人及保险经纪两类，二者并称保险中介人，故该项正确。",src:1,tw:{ch:"法律原則",q:"保險中介人是指哪些人士？",o:["保險代理人","保險經紀","保險代理人或保險經紀","保險代理人及保險經紀"],e:"保險中介人包括保險代理人及保險經紀兩類，二者並稱保險中介人，故該項正確。"}},
{p:1,ch:"法律原则",q:"保险保障要求提出后,保险人要求增加保费才接受保险保障要求,保险人的要求 在法律上称为 :",o:["反要约","相反要约","有保留承约","有条件承约"],a:0,e:"保险人提出改动（如增加保费）即拒绝原有要约并提出新条件，构成反要约，须由投保人承约方可成立合约。",src:1,tw:{ch:"法律原則",q:"保險保障要求提出後，保險人要求增加保費才接受保險保障要求，保險人的要求 在法律上稱為 :",o:["反要約","相反要約","有保留承約","有條件承約"],e:"保險人提出改動（如增加保費）即拒絕原有要約並提出新條件，構成反要約，須由投保人承約方可成立合約。"}},
{p:1,ch:"法律原则",q:"保险公司发出的担保,是属于:",o:["简单合约","契据","复杂合约","不能强制执行的合约"],a:1,e:"担保因通常缺乏代价支持，必须经签署、盖印及交付，以契据形式订立方可强制执行。",src:1,tw:{ch:"法律原則",q:"保險公司發出的擔保，是屬於：",o:["簡單合約","契據","複雜合約","不能強制執行的合約"],e:"擔保因通常缺乏代價支持，必須經簽署、蓋印及交付，以契據形式訂立方可強制執行。"}},
{p:1,ch:"法律原则",q:"保险合约中,「订约的行为能力」这个元素只涉及:",o:["受保人","保险人","保单持有人及保险人","非受保人及保险人"],a:2,e:"「订约的行为能力」关乎合约双方的资格，即保单持有人（要约人）与保险人双方均须具备订立合约的能力。",src:1,tw:{ch:"法律原則",q:"保險合約中，「訂約的行為能力」這個元素只涉及：",o:["受保人","保險人","保單持有人及保險人","非受保人及保險人"],e:"「訂約的行為能力」關乎合約雙方的資格，即保單持有人（要約人）與保險人雙方均須具備訂立合約的能力。"}},
{p:1,ch:"法律原则",q:"保险合约通常属于哪一类合约?",o:["简单","盖印","纪录","契据"],a:0,e:"保险合约一般属简单合约，可以书面或口头订立，无须以契据或盖印形式作出。",src:1,tw:{ch:"法律原則",q:"保險合約通常屬於哪一類合約？",o:["簡單","蓋印","紀錄","契據"],e:"保險合約一般屬簡單合約，可以書面或口頭訂立，無須以契據或蓋印形式作出。"}},
{p:1,ch:"法律原则",q:"假如保险人根据被保险人的行为,合理地推断(其实未获授权)一名事务律师获得授 权替被保人行事,根据以下哪项法则,被保险人会受到事务律师的行为所约束?",o:["明示权限","不容反悔代理权","必要权限","追认权限"],a:1,e:"保险人基于被保险人的表现合理地相信事务律师获授权行事，属表面权限（不容反悔代理权），被保险人因而受该律师行为约束。",src:1,tw:{ch:"法律原則",q:"假如保險人根據被保險人的行為，合理地推斷(其實未獲授權)一名事務律師獲得授 權替被保人行事，根據以下哪項法則，被保險人會受到事務律師的行為所約束?",o:["明示權限","不容反悔代理權","必要權限","追認權限"],e:"保險人基於被保險人的表現合理地相信事務律師獲授權行事，屬表面權限（不容反悔代理權），被保險人因而受該律師行為約束。"}},
{p:1,ch:"法律原则",q:"双方同意终止代理合约:",o:["是必然可行的","除非合约有特别规定,否则是不容许的","必须牵涉向代理人提供金钱赔偿","足以令第三者所订立之所有合约无效"],a:0,e:"代理合约可由双方同意而终止，除非合约另有特别规定，故「必然可行」为正确。",src:1,tw:{ch:"法律原則",q:"雙方同意終止代理合約：",o:["是必然可行的","除非合約有特別規定，否則是不容許的","必須牽涉向代理人提供金錢賠償","足以令第三者所訂立之所有合約無效"],e:"代理合約可由雙方同意而終止，除非合約另有特別規定，故「必然可行」為正確。"}},
{p:1,ch:"法律原则",q:"合约可以界定为:",o:["在法律上可强制执行的协议","两人或多人之间的承诺","以书面形式表达的协议","任何两方或多方的协议"],a:0,e:"合约的法定定义即为「在法律上可强制执行的协议」，其余描述均不完整。",src:1,tw:{ch:"法律原則",q:"合約可以界定為：",o:["在法律上可強制執行的協議","兩人或多人之間的承諾","以書面形式表達的協議","任何兩方或多方的協議"],e:"合約的法定定義即為「在法律上可強制執行的協議」，其餘描述均不完整。"}},
{p:1,ch:"法律原则",q:"合约是什么?",o:["可以口头或书面形式","只可以经盖章形式订立","可以内容简单而浅白","(a)及(c)都是正确的"],a:0,e:"合约（简单合约）可以口头或书面形式订立，不以盖章为必要，故「可以口头或书面」正确。",src:1,tw:{ch:"法律原則",q:"合約是什麼？",o:["可以口頭或書面形式","只可以經蓋章形式訂立","可以內容簡單而淺白","(a)及(c)都是正確的"],e:"合約（簡單合約）可以口頭或書面形式訂立，不以蓋章為必要，故「可以口頭或書面」正確。"}},
{p:1,ch:"法律原则",q:"合约是法律上可强制执行的协议,而:",o:["在订立合约时,必须有第三者在场","它的内容必须涉及财务利益","内容可包含重要及次要事项","订立时必须有法律人士在场"],a:2,e:"合约内容既可包含重要事项，亦可包含次要事项；不必有第三者在场、必然涉及财务利益或律师在场。",src:1,tw:{ch:"法律原則",q:"合約是法律上可強制執行的協議，而：",o:["在訂立合約時，必須有第三者在場","它的內容必須涉及財務利益","內容可包含重要及次要事項","訂立時必須有法律人士在場"],e:"合約內容既可包含重要事項，亦可包含次要事項；不必有第三者在場、必然涉及財務利益或律師在場。"}},
{p:1,ch:"法律原则",q:"在「一般保险」的合约中发生了一些误解,被保险人希望为他的家居财产投保, 但保单保障该建筑物的结构及家居财产,因此这合约便视为「无效」,因为它不 符合下列哪项合约的元素?",o:["合法性","代价","各方订约的行为能力","订立法律关系的意向"],a:3,e:"因双方对保障内容存在误解，欠缺共同的订立法律关系意向，故合约不符合该元素而无效。",src:1,tw:{ch:"法律原則",q:"在「一般保險」的合約中發生了一些誤解，被保險人希望為他的家居財產投保， 但保單保障該建築物的結構及家居財產，因此這合約便視為「無效」，因為它不 符合下列哪項合約的元素？",o:["合法性","代價","各方訂約的行為能力","訂立法律關係的意向"],e:"因雙方對保障內容存在誤解，欠缺共同的訂立法律關係意向，故合約不符合該元素而無效。"}},
{p:1,ch:"法律原则",q:"在一份建议合约上的要约对象称为 :",o:["要约人","受要约人","被动人","准客户"],a:1,e:"在接受要约过程中，被邀作出承约的一方称为受要约人，故该项正确。",src:1,tw:{ch:"法律原則",q:"在一份建議合約上的要約對象稱為 :",o:["要約人","受要約人","被動人","準客戶"],e:"在接受要約過程中，被邀作出承約的一方稱為受要約人，故該項正確。"}},
{p:1,ch:"法律原则",q:"在下列哪种情况下,代理人可提出撤销代理协议?",o:["这未被明文禁止","当中须根据合约中有关给予通知及/或补偿的条款进行","委托人已违反协议","委托人已精神错乱"],a:1,e:"代理人须依合约中关于给予通知及／或补偿的条款，方可提出撤销代理协议，故该项正确。",src:1,tw:{ch:"法律原則",q:"在下列哪種情況下，代理人可提出撤銷代理協議?",o:["這未被明文禁止","當中須根據合約中有關給予通知及/或補償的條款進行","委託人已違反協議","委託人已精神錯亂"],e:"代理人須依合約中關於給予通知及／或補償的條款，方可提出撤銷代理協議，故該項正確。"}},
{p:1,ch:"法律原则",q:"在代理法中,「表面权限」是指:",o:["权限不存在","代理人的行为订立一份或一宗对委托人有约束力的合约或交易","代理人已获得明确的指示行事","所有情况下显示实际权限已经存在"],a:1,e:"表面权限指代理人的行为足以订立对委托人有约束力的合约或交易，即便无实际授权，故该项为正确描述。",src:1,tw:{ch:"法律原則",q:"在代理法中，「表面權限」是指:",o:["權限不存在","代理人的行為訂立一份或一宗對委託人有約束力的合約或交易","代理人已獲得明確的指示行事","所有情況下顯示實際權限已經存在"],e:"表面權限指代理人的行為足以訂立對委託人有約束力的合約或交易，即便無實際授權，故該項為正確描述。"}},
{p:1,ch:"法律原则",q:"在代理法中,以下哪项对于保险中介人的描述是正确的?",o:["保险经纪是代表保险公司","保险代理人是代表被保险人","保险经纪及保险代理人同属保险中介人","任何保险的事务都涉及以上两者"],a:2,e:"保险代理人代表保险人、保险经纪代表投保人，两者均属保险中介人，故该项正确。",src:1,tw:{ch:"法律原則",q:"在代理法中，以下哪項對於保險中介人的描述是正確的？",o:["保險經紀是代表保險公司","保險代理人是代表被保險人","保險經紀及保險代理人同屬保險中介人","任何保險的事務都涉及以上兩者"],e:"保險代理人代表保險人、保險經紀代表投保人，兩者均屬保險中介人，故該項正確。"}},
{p:1,ch:"法律原则",q:"在代理法中,表面授权是指:",o:["没有授权","代理人在欺骗客户","代理人获明确授权行事","代理人关系可以透过委托人行为推断"],a:3,e:"表面授权指代理关系可透过委托人的行为或表现推断出来，即第三者合理地相信有权限存在，故该项正确。",src:1,tw:{ch:"法律原則",q:"在代理法中，表面授權是指:",o:["沒有授權","代理人在欺騙客戶","代理人獲明確授權行事","代理人關係可以透過委託人行為推斷"],e:"表面授權指代理關係可透過委託人的行為或表現推斷出來，即第三者合理地相信有權限存在，故該項正確。"}},
{p:1,ch:"法律原则",q:"在代理法内,保险代理人或保险经纪是指 :",o:["只有保险经纪属于代理人,保险代理人则不是","只有保险代理人属于代理人,保险经纪则不是","保险代理人及保险经纪两者都属于代理人","保险代理人及保险经纪两者都不属于代理人"],a:2,e:"在法律意义上，保险代理人及保险经纪均属代理人（分别代理保险人及投保人），故两者都属于代理人。",src:1,tw:{ch:"法律原則",q:"在代理法內，保險代理人或保險經紀是指 :",o:["只有保險經紀屬於代理人，保險代理人則不是","只有保險代理人屬於代理人，保險經紀則不是","保險代理人及保險經紀兩者都屬於代理人","保險代理人及保險經紀兩者都不屬於代理人"],e:"在法律意義上，保險代理人及保險經紀均屬代理人（分別代理保險人及投保人），故兩者都屬於代理人。"}},
{p:1,ch:"法律原则",q:"在执行上,以下哪项对代理法规管的描述是正确的 :",o:["保险代理人及保险经纪都视为委托人","只有保险代理人才属于中介人","委托人对代理人需负上转承责任","只适用于保险代理人及保险经纪"],a:2,e:"委托人须对代理人在授权范围内所为行为承担转承责任，这是代理法对委托人的重要约束，故该项正确。",src:1,tw:{ch:"法律原則",q:"在執行上，以下哪項對代理法規管的描述是正確的 :",o:["保險代理人及保險經紀都視為委託人","只有保險代理人才屬於中介人","委託人對代理人需負上轉承責任","只適用於保險代理人及保險經紀"],e:"委託人須對代理人在授權範圍內所為行為承擔轉承責任，這是代理法對委託人的重要約束，故該項正確。"}},
{p:1,ch:"法律原则",q:"在没有获授权的情况下,为另一方作了某些事情,而该行为是基于合理及必要, 在此情况下,这人便成为了:",o:["不容反悔代理人","明示权限代理人","必要代理人","实际权限代理人"],a:2,e:"在未获授权但为他人最佳利益、且属合理必要的情况下行事，即构成必要代理人，故该项正确。",src:1,tw:{ch:"法律原則",q:"在沒有獲授權的情況下，為另一方作了某些事情，而該行為是基於合理及必要， 在此情況下，這人便成為了：",o:["不容反悔代理人","明示權限代理人","必要代理人","實際權限代理人"],e:"在未獲授權但為他人最佳利益、且屬合理必要的情況下行事，即構成必要代理人，故該項正確。"}},
{p:1,ch:"法律原则",q:"在紧急情况下,某人承担或支付代理另一人行事的开支,则即使他人没有在产生 开支期间或之后授权,此人成为他人代理人,这是基于以下哪种代理关系?",o:["实际权限","表面权限","必要权限","不容反悔的代理权"],a:2,e:"在紧急情况下为他人利益合理支付开支，纵使事先未获授权，亦基于必要权限成立代理关系。",src:1,tw:{ch:"法律原則",q:"在緊急情況下，某人承擔或支付代理另一人行事的開支，則即使他人沒有在產生 開支期間或之後授權，此人成為他人代理人，這是基於以下哪種代理關係?",o:["實際權限","表面權限","必要權限","不容反悔的代理權"],e:"在緊急情況下為他人利益合理支付開支，縱使事先未獲授權，亦基於必要權限成立代理關係。"}},
{p:1,ch:"法律原则",q:"在终止代理人关系的范围中,「精神错乱」只适合应用于:",o:["代理人(自然人)","委托人","代理人或委托人","代理人或经纪"],a:2,e:"精神错乱作为终止代理关系的原因，适用于任何自然人，即代理人或委托人均可，故该项正确。",src:1,tw:{ch:"法律原則",q:"在終止代理人關係的範圍中，「精神錯亂」只適合應用於：",o:["代理人(自然人)","委託人","代理人或委託人","代理人或經紀"],e:"精神錯亂作為終止代理關係的原因，適用於任何自然人，即代理人或委託人均可，故該項正確。"}},
{p:1,ch:"法律原则",q:"在终止代理关系的范围中,「精神错乱」只适合应用于:",o:["代理人(自然人)","委托人","代理人或委托人","代理人或经纪"],a:2,e:"同前：精神错乱终止代理关系适用于代理人或委托人，二者皆是自然人时均适用。",src:1,tw:{ch:"法律原則",q:"在終止代理關係的範圍中，「精神錯亂」只適合應用於：",o:["代理人(自然人)","委託人","代理人或委託人","代理人或經紀"],e:"同前：精神錯亂終止代理關係適用於代理人或委託人，二者皆是自然人時均適用。"}},
{p:1,ch:"法律原则",q:"在给予通知及/或代价补偿的合约条文下,协议可在何时撤销?",o:["在协议生效时间前","在协议生效时间内","在协议生效的头七天内取消","协议在任何时间都不能取消"],a:1,e:"依合约中给予通知及／或补偿的条文，协议可在生效期间内按条款撤销，故「在协议生效时间内」正确。",src:1,tw:{ch:"法律原則",q:"在給予通知及/或代價補償的合約條文下，協議可在何時撤銷？",o:["在協議生效時間前","在協議生效時間內","在協議生效的頭七天內取消","協議在任何時間都不能取消"],e:"依合約中給予通知及／或補償的條文，協議可在生效期間內按條款撤銷，故「在協議生效時間內」正確。"}},
{p:1,ch:"法律原则",q:"在给予通知及/或代价补偿的合约条文下,属于以下哪项终止代理关系的方式?",o:["双方同意","撤销协议","精神错乱","违反合约"],a:1,e:"依通知及／或代价补偿的合约条文撤销，属「撤销协议」这一终止方式，故该项正确。",src:1,tw:{ch:"法律原則",q:"在給予通知及/或代價補償的合約條文下，屬於以下哪項終止代理關係的方式？",o:["雙方同意","撤銷協議","精神錯亂","違反合約"],e:"依通知及／或代價補償的合約條文撤銷，屬「撤銷協議」這一終止方式，故該項正確。"}},
{p:1,ch:"法律原则",q:"如果一份合约是「无效的」意指:",o:["保险人有权取消合约","任何一方均可取消合约","在法律上这份合约是无效的","保险人已决定不作赔偿"],a:2,e:"「无效」指合约自始即无法律效力，任何一方都不能据以主张权利，故「在法律上无效」正确。",src:1,tw:{ch:"法律原則",q:"如果一份合約是「無效的」意指：",o:["保險人有權取消合約","任何一方均可取消合約","在法律上這份合約是無效的","保險人已決定不作賠償"],e:"「無效」指合約自始即無法律效力，任何一方都不能據以主張權利，故「在法律上無效」正確。"}},
{p:1,ch:"法律原则",q:"如果一名代理人在履行职责时没具有「应有的谨慎及技巧」,而最后令委托人蒙 受损失,该名委托人:",o:["拥有向该名代理人要求赔偿的权利","没有向该名代理人要求赔偿的权利","只有在构成欺骗行为时才可向该名代理人要求赔偿","只能追索该名代理人所引致损失的50%"],a:0,e:"代理人履行职务未尽应有的谨慎与技巧而致委托人损失，即违反其义务，委托人可向其追偿。",src:1,tw:{ch:"法律原則",q:"如果一名代理人在履行職責時沒具有「應有的謹慎及技巧」，而最後令委託人蒙 受損失，該名委託人：",o:["擁有向該名代理人要求賠償的權利","沒有向該名代理人要求賠償的權利","只有在構成欺騙行為時才可向該名代理人要求賠償","只能追索該名代理人所引致損失的50%"],e:"代理人履行職務未盡應有的謹慎與技巧而致委託人損失，即違反其義務，委託人可向其追償。"}},
{p:1,ch:"法律原则",q:"如果一名代理人未能履行「应有的谨慎」的责任,而最后令委托人蒙受损失的话 ,该名委托人:",o:["拥有向该名代理人追偿的权利","不会拥有任何补救","惟有在该代理人作出过诈骗行为时才可向该阿代理人追偿","只能追偿该名代理人所引致损失的50%, 理由是「均等便是公平」"],a:0,e:"代理人未尽应有谨慎致委托人受损，属违反责任，委托人享有追偿权利，并非限于欺诈或只追一半。",src:1,tw:{ch:"法律原則",q:"如果一名代理人未能履行「應有的謹慎」的責任，而最後令委託人蒙受損失的話 ，該名委託人：",o:["擁有向該名代理人追償的權利","不會擁有任何補救","惟有在該代理人作出過詐騙行為時才可向該阿代理人追償","只能追償該名代理人所引致損失的50%， 理由是「均等便是公平」"],e:"代理人未盡應有謹慎致委託人受損，屬違反責任，委託人享有追償權利，並非限於欺詐或只追一半。"}},
{p:1,ch:"法律原则",q:"如果一名代理人的权限是透过委托人对第三者表明同意而产生的,是属于下列哪 项代理人的权限:",o:["实际权限","表面权限","必要权限","不容反悔的代理权"],a:1,e:"委托人向第三者表明同意代理人代表其行事而产生的权限，属表面权限（表见代理），故该项正确。",src:1,tw:{ch:"法律原則",q:"如果一名代理人的權限是透過委託人對第三者表明同意而產生的，是屬於下列哪 項代理人的權限：",o:["實際權限","表面權限","必要權限","不容反悔的代理權"],e:"委託人向第三者表明同意代理人代表其行事而產生的權限，屬表面權限（表見代理），故該項正確。"}},
{p:1,ch:"法律原则",q:"如果个人代理人辞世,其与委托人的代理关系:",o:["自动终止","自动传与其继承人","在其遗嘱订明下才传给其继承人","在其委托人书面通知下才终止"],a:0,e:"个人代理人辞世，其代理关系自动终止，不会自动传予继承人。",src:1,tw:{ch:"法律原則",q:"如果個人代理人辭世，其與委託人的代理關係:",o:["自動終止","自動傳與其繼承人","在其遺囑訂明下才傳給其繼承人","在其委託人書面通知下才終止"],e:"個人代理人辭世，其代理關係自動終止，不會自動傳予繼承人。"}},
{p:1,ch:"法律原则",q:"如果代理人是属于公司性质,而公司正处于清盘阶段,与有关委托人的代理协议 :",o:["便告自动终止","便可供公司的清盘人购买","便可供公司的任何股东购买","便自动转让予公司的前常务董事"],a:0,e:"公司性质的代理人进入清盘，其法律人格不能继续履行代理，代理协议即自动终止。",src:1,tw:{ch:"法律原則",q:"如果代理人是屬於公司性質，而公司正處於清盤階段，與有關委託人的代理協議 ：",o:["便告自動終止","便可供公司的清盤人購買","便可供公司的任何股東購買","便自動轉讓予公司的前常務董事"],e:"公司性質的代理人進入清盤，其法律人格不能繼續履行代理，代理協議即自動終止。"}},
{p:1,ch:"法律原则",q:"如果代理协议在生效六个月后变成非法,以下哪项有关该协议的描述是正确的?",o:["即时终止","必须待至期限终结","其中一方提出便可终结","双方同意便可终结"],a:0,e:"代理协议在生效后因法律变更而变成非法，即告即时终止，无须等待期限届满。",src:1,tw:{ch:"法律原則",q:"如果代理協議在生效六個月後變成非法，以下哪項有關該協議的描述是正確的？",o:["即時終止","必須待至期限終結","其中一方提出便可終結","雙方同意便可終結"],e:"代理協議在生效後因法律變更而變成非法，即告即時終止，無須等待期限屆滿。"}},
{p:1,ch:"法律原则",q:"如果保险人以「明示权限」方式委托了一名代理人,那意味着?",o:["代理人的权限必须以书面方式写在合约上","这是在紧急情况下产生的","获得了委任后,代理人可以代表保险人做某件事","获得了委任后,代理人可以代表保险人接受保险业务"],a:3,e:"以明示权限委任代理人，意味着代理人在获明确授权范围内可代表保险人行事，包括接受保险业务。",src:1,tw:{ch:"法律原則",q:"如果保險人以「明示權限」方式委託了一名代理人,那意味着?",o:["代理人的權限必須以書面方式寫在合約上","這是在緊急情況下產生的","獲得了委任後,代理人可以代表保險人做某件事","獲得了委任後,代理人可以代表保險人接受保險業務"],e:"以明示權限委任代理人，意味着代理人在獲明確授權範圍內可代表保險人行事，包括接受保險業務。"}},
{p:1,ch:"法律原则",q:"如果有一份合约为期一年,一年后:",o:["仍然生效","仍然生效,除非其中一方终止","即时终止,除非双方重新协议","须双方同意下才可终止"],a:2,e:"定期为一年的合约期满即告终止，除非双方重新达成协议续期，故「即时终止，除非重新协议」正确。",src:1,tw:{ch:"法律原則",q:"如果有一份合約為期一年，一年後:",o:["仍然生效","仍然生效，除非其中一方終止","即時終止，除非雙方重新協議","須雙方同意下才可終止"],e:"定期為一年的合約期滿即告終止，除非雙方重新達成協議續期，故「即時終止，除非重新協議」正確。"}},
{p:1,ch:"法律原则",q:"委托人可以透过甚么途径委任代理人?",o:["通过协议","以隐含方式","以事后确认方式","以上所有各项"],a:3,e:"委托人可透过明确协议、隐含方式或事后追认等途径委任代理人，故各项皆正确。",src:1,tw:{ch:"法律原則",q:"委託人可以透過甚麼途徑委任代理人?",o:["通過協議","以隱含方式","以事後確認方式","以上所有各項"],e:"委託人可透過明確協議、隱含方式或事後追認等途徑委任代理人，故各項皆正確。"}},
{p:1,ch:"法律原则",q:"委托人对代理人应付的责任包括以下哪项?",o:["利润保证","同意按照相关行业标准支付薪酬","支付费用乃合理地及正常地替委托人所招致","以上各项皆是"],a:2,e:"委托人须承担代理人合理地及正常地为执行职务所招致的费用与开支，故该项为应负责任。",src:1,tw:{ch:"法律原則",q:"委託人對代理人應付的責任包括以下哪項?",o:["利潤保證","同意按照相關行業標準支付薪酬","支付費用乃合理地及正常地替委託人所招致","以上各項皆是"],e:"委託人須承擔代理人合理地及正常地為執行職務所招致的費用與開支，故該項為應負責任。"}},
{p:1,ch:"法律原则",q:"委托人对代理人的责任不包括:",o:["给付合理报酬","承担代理人行事所有合理成本及开支","履行对代理人的义务","保证代理人的佣金每年递增"],a:3,e:"委托人须给付合理报酬、承担合理开支并履行对代理人的义务，惟无须保证代理人佣金逐年递增。",src:1,tw:{ch:"法律原則",q:"委託人對代理人的責任不包括：",o:["給付合理報酬","承擔代理人行事所有合理成本及開支","履行對代理人的義務","保證代理人的佣金每年遞增"],e:"委託人須給付合理報酬、承擔合理開支並履行對代理人的義務，惟無須保證代理人佣金逐年遞增。"}},
{p:1,ch:"法律原则",q:"委托人对代理人的责任包括:",o:["承担代理人所有合理开支","报酬","违反责任","以上各项皆是"],a:3,e:"委托人对代理人须给付报酬、承担合理开支，并就其违反责任承担后果，故各项皆属委托人的责任。",src:1,tw:{ch:"法律原則",q:"委託人對代理人的責任包括：",o:["承擔代理人所有合理開支","報酬","違反責任","以上各項皆是"],e:"委託人對代理人須給付報酬、承擔合理開支，並就其違反責任承擔後果，故各項皆屬委託人的責任。"}},
{p:1,ch:"法律原则",q:"委托人对代理人的责任包括以下哪项或哪些?",o:["所招致之一切合理费用及开支","以代收回款项50%为上限","回佣及礼物","以上皆是"],a:0,e:"委托人须偿付代理人因代为行事而合理及正当招致的一切费用与开支，故该项正确。",src:1,tw:{ch:"法律原則",q:"委托人對代理人的責任包括以下哪項或哪些？",o:["所招致之一切合理費用及開支","以代收回款項50%為上限","回佣及禮物","以上皆是"],e:"委託人須償付代理人因代為行事而合理及正當招致的一切費用與開支，故該項正確。"}},
{p:1,ch:"法律原则",q:"委托人明示或隐含地向代理人表明同意代理人代表委托人或替其行事,是属于下 列哪项代理人的权限:",o:["实际权限","表面权限","必要权限","不容反悔的代理权"],a:0,e:"委托人明示或隐含地同意代理人代表其行事所产生的权限，即属实际权限（明示或默示的实际权限）。",src:1,tw:{ch:"法律原則",q:"委託人明示或隱含地向代理人表明同意代理人代表委託人或替其行事，是屬於下 列哪項代理人的權限：",o:["實際權限","表面權限","必要權限","不容反悔的代理權"],e:"委託人明示或隱含地同意代理人代表其行事所產生的權限，即屬實際權限（明示或默示的實際權限）。"}},
{p:1,ch:"法律原则",q:"委托人追认其代理人的行为意味着:",o:["有关代理协定的终结","该代理人将无权取得任何佣金","该委托人以追溯形式授权有关行为","该委托人拒绝为代理人的行为负上责任"],a:2,e:"追认指委托人追溯性地授权代理人先前未经授权的行为，使该行为对委托人有效，故该项正确。",src:1,tw:{ch:"法律原則",q:"委託人追認其代理人的行為意味着:",o:["有關代理協定的終結","該代理人將無權取得任何佣金","該委託人以追溯形式授權有關行為","該委託人拒絕為代理人的行為負上責任"],e:"追認指委託人追溯性地授權代理人先前未經授權的行為，使該行為對委託人有效，故該項正確。"}},
{p:1,ch:"法律原则",q:"安琪在登机前购买一份旅游保险,保险人容许她在旅程后缴付保险费。安琪不幸 在旅程中断了一条腿,保险人拒绝赔付安琪有关的医疗费用,请问保险人有权这 样做吗?",o:["没有。根据承保商专业守则,保险人禁止因迟交保费为由而拒绝赔付","没有。一张旅游保险合约已经生效","有。双方没有订立法律关系的意向","有。安琪没有付出保费"],a:1,e:"保险人已同意在旅程后缴付保费并作出承保承诺，旅游保险合约已于投保时成立生效，故保险人不能以未付保费为由拒赔。",src:1,tw:{ch:"法律原則",q:"安琪在登機前購買一份旅遊保險，保險人容許她在旅程後繳付保險費。安琪不幸 在旅程中斷了一條腿，保險人拒絕賠付安琪有關的醫療費用，請問保險人有權這 樣做嗎？",o:["沒有。根據承保商專業守則，保險人禁止因遲交保費為由而拒絕賠付","沒有。一張旅遊保險合約已經生效","有。雙方沒有訂立法律關係的意向","有。安琪沒有付出保費"],e:"保險人已同意在旅程後繳付保費並作出承保承諾，旅遊保險合約已於投保時成立生效，故保險人不能以未付保費為由拒賠。"}},
{p:1,ch:"法律原则",q:"家庭内的安排，例如替妈妈做家务的协定:",o:["是一份道德上的合约","通常不构成一份合约","只在涉及报酬的情况下才属于一份合约","当该安排以书面形式表达时才构成一份合约"],a:1,e:"家庭内的安排（如替妈妈做家务）通常缺乏订立法律关系的意向，因而不构成法律上可强制执行的合约。",src:1,tw:{ch:"法律原則",q:"家庭內的安排，例如替媽媽做家務的協定:",o:["是一份道德上的合約","通常不構成一份合約","只在涉及報酬的情況下才屬於一份合約","當該安排以書面形式表達時才構成一份合約"],e:"家庭內的安排（如替媽媽做家務）通常缺乏訂立法律關係的意向，因而不構成法律上可強制執行的合約。"}},
{p:1,ch:"法律原则",q:"对代理人追认意味着 :",o:["代理人确认其过去的行为","代理人获支付所有的开支","委托人授权从某时起计算","委托人对代理人的合约不需负上任何责任,除非代理人后来追认"],a:2,e:"追认意味着委托人自某一时点起追溯授权代理人的相关行为，故「委托人授权从某时起计算」正确。",src:1,tw:{ch:"法律原則",q:"對代理人追認意味着 :",o:["代理人確認其過去的行為","代理人獲支付所有的開支","委託人授權從某時起計算","委託人對代理人的合約不需負上任何責任,除非代理人後來追認"],e:"追認意味着委託人自某一時點起追溯授權代理人的相關行為，故「委託人授權從某時起計算」正確。"}},
{p:1,ch:"法律原则",q:"尽管缺乏口头或书面证据,但可从涉及之人或行为断定某项合约的存在,在法律 上可描述为 :",o:["简单合约","契据","推断合约","以上任何一项"],a:0,e:"缺乏明示口头或书面证据、只能凭当事人行为推断而成立的合约，仍属简单合约，因简单合约可由行为默示订立而无须盖章。",src:1,tw:{ch:"法律原則",q:"儘管缺乏口頭或書面證據，但可從涉及之人或行為斷定某項合約的存在，在法律 上可描述為 :",o:["簡單合約","契據","推斷合約","以上任何一項"],e:"缺乏明示口頭或書面證據、只能憑當事人行為推斷而成立的合約，仍屬簡單合約，因簡單合約可由行為默示訂立而無須蓋章。"}},
{p:1,ch:"法律原则",q:"当一份协议已告完成,便会:",o:["自动延续,只要代理人同意","自动延续,只要委托人同意","便告终止,除非双方有意续约","便告终止,除非委托人同意给代理人额外报酬"],a:2,e:"当协议已告完成，合约即告终止，除非双方有意续约，故该项正确。",src:1,tw:{ch:"法律原則",q:"當一份協議已告完成，便會：",o:["自動延續，只要代理人同意","自動延續，只要委託人同意","便告終止，除非雙方有意續約","便告終止，除非委託人同意給代理人額外報酬"],e:"當協議已告完成，合約即告終止，除非雙方有意續約，故該項正確。"}},
{p:1,ch:"法律原则",q:"当保险代理人替保险人为投保人安排保险,我们可以说当中出现两份合约,其中 一份在于保险人及投保人之间,而另一份合约是:",o:["在于保险人与保险业监管局之间","在于投保人及再保险人之间","在于保险代理人及保险人之间","在于投保人及代理人之间"],a:2,e:"代理人替保险人为投保人安排保险，除保险人与投保人之间的保单外，另一份是保险人与代理人之间的代理合约。",src:1,tw:{ch:"法律原則",q:"當保險代理人替保險人為投保人安排保險，我們可以說當中出現兩份合約，其中 一份在於保險人及投保人之間，而另一份合約是:",o:["在於保險人與保險業監管局之間","在於投保人及再保險人之間","在於保險代理人及保險人之間","在於投保人及代理人之間"],e:"代理人替保險人為投保人安排保險，除保險人與投保人之間的保單外，另一份是保險人與代理人之間的代理合約。"}},
{p:1,ch:"法律原则",q:"按照简单合约,订约的行为能力是指订立合约的能力,在保险合约方面,这个元 素该涉及 :",o:["投保人及保险人","未满成年岁数的投保人","投保人,但不一定保险人","保险人,但不一定投保人"],a:0,e:"就保险合约而言，「订约的行为能力」涉及投保人及保险人双方，故该项正确。",src:1,tw:{ch:"法律原則",q:"按照簡單合約，訂約的行為能力是指訂立合約的能力，在保險合約方面，這個元 素該涉及 :",o:["投保人及保險人","未滿成年歲數的投保人","投保人，但不一定保險人","保險人，但不一定投保人"],e:"就保險合約而言，「訂約的行為能力」涉及投保人及保險人雙方，故該項正確。"}},
{p:1,ch:"法律原则",q:"有一个人发现一只昂贵的纯种狗,在他照料这狗只的同时,并努力寻找失主。几 日后与失主联络上,并在照料狗只期间的狗食兽医的相当数量的费用,他可争辩 有权向失主为这款项赔付,因为在这段时间期间,他被视为这失主的:",o:["明示代理人","表面代理人","必要代理人","不容反悔代理人"],a:2,e:"拾获他人昂贵宠物并为其合理支付饲料与兽医费用，属在必要时为物主利益行事，构成必要代理人，可向失主追讨。",src:1,tw:{ch:"法律原則",q:"有一個人發現一隻昂貴的純種狗，在他照料這狗隻的同時，並努力尋找失主。幾 日後與失主聯絡上，並在照料狗隻期間的狗食獸醫的相當數量的費用，他可爭辯 有權向失主為這款項賠付，因為在這段時間期間，他被視為這失主的：",o:["明示代理人","表面代理人","必要代理人","不容反悔代理人"],e:"拾獲他人昂貴寵物併為其合理支付飼料與獸醫費用，屬在必要時為物主利益行事，構成必要代理人，可向失主追討。"}},
{p:1,ch:"法律原则",q:"有些合约是「可使无效的」,「可使无效」是指:",o:["永远不能变为有效","可由一方将它变成无效","是有效的,但不可在法庭上执行","受屈一方可于合理时间内把合约视为无效"],a:3,e:"「可使无效」指受屈一方可在合理时间内将合约视为无效而撤销之，故该项正确。",src:1,tw:{ch:"法律原則",q:"有些合約是「可使無效的」，「可使無效」是指：",o:["永遠不能變為有效","可由一方將它變成無效","是有效的，但不可在法庭上執行","受屈一方可於合理時間內把合約視為無效"],e:"「可使無效」指受屈一方可在合理時間內將合約視為無效而撤銷之，故該項正確。"}},
{p:1,ch:"法律原则",q:"朋友间的晚饭约会是:",o:["一份道德上的合约","一份法律上不能强制执行的合约","如超过两人以上便可构成合约","如以书面形式表示,即可成为一份合约"],a:1,e:"朋友间的晚饭约会属社交安排，缺乏订立法律关系的意向，属法律上不能强制执行的合约。",src:1,tw:{ch:"法律原則",q:"朋友間的晚飯約會是：",o:["一份道德上的合約","一份法律上不能強制執行的合約","如超過兩人以上便可構成合約","如以書面形式表示，即可成為一份合約"],e:"朋友間的晚飯約會屬社交安排，缺乏訂立法律關係的意向，屬法律上不能強制執行的合約。"}},
{p:1,ch:"法律原则",q:"构成有效的简单合约,必须符合以下哪项要求?",o:["香港身份证","商业登记","简单的条款及条件","订立法律关系意图"],a:3,e:"构成有效简单合约，必须具备订立法律关系的意向，这是基本要素之一，故该项正确。",src:1,tw:{ch:"法律原則",q:"構成有效的簡單合約，必須符合以下哪項要求?",o:["香港身份證","商業登記","簡單的條款及條件","訂立法律關係意圖"],e:"構成有效簡單合約，必須具備訂立法律關係的意向，這是基本要素之一，故該項正確。"}},
{p:1,ch:"法律原则",q:"某人在某时为他人的最佳利益行事,虽然他事前并没有获得授权,但在法律上却 持有这权限,并被视为:",o:["必要代理人","紧急情况下代理人","具有追溯性的授权的代理人","自动获授权的代理人"],a:0,e:"未经授权但为他人的最佳利益行事，法律上被视为拥有必要权限，即必要代理人，故该项正确。",src:1,tw:{ch:"法律原則",q:"某人在某時為他人的最佳利益行事，雖然他事前並沒有獲得授權，但在法律上卻 持有這權限，並被視為:",o:["必要代理人","緊急情況下代理人","具有追溯性的授權的代理人","自動獲授權的代理人"],e:"未經授權但為他人的最佳利益行事，法律上被視為擁有必要權限，即必要代理人，故該項正確。"}},
{p:1,ch:"法律原则",q:"某人拾获遗失的狗只,在妥为照料之余,亦同时积极追寻狗主。期后狗主领回该 狗只后,某人以代理的身份,向狗主追索期间所支出的兽医及食物费用。这种产 生代理的方式是:",o:["实际权限","表面权限","必要权限","不容反悔的代理权"],a:2,e:"拾获遗失狗只后妥为照料并追寻狗主，其后追讨合理支出，此乃基于必要权限而成立的代理关系。",src:1,tw:{ch:"法律原則",q:"某人拾獲遺失的狗隻，在妥為照料之餘，亦同時積極追尋狗主。期後狗主領回該 狗隻後，某人以代理的身份，向狗主追索期間所支出的獸醫及食物費用。這種產 生代理的方式是：",o:["實際權限","表面權限","必要權限","不容反悔的代理權"],e:"拾獲遺失狗只後妥為照料並追尋狗主，其後追討合理支出，此乃基於必要權限而成立的代理關係。"}},
{p:1,ch:"法律原则",q:"甚么是代价?",o:["它必须由双方在合约中订定","这是合约的一方对另一方的承诺","这是合约的一方对另一方的义务","以上各项皆正确"],a:1,e:"代价是指合约一方为使对方作出承诺而付出的对价，即一方对另一方的承诺或作为，故该项正确。",src:1,tw:{ch:"法律原則",q:"甚麼是代價？",o:["它必須由雙方在合約中訂定","這是合約的一方對另一方的承諾","這是合約的一方對另一方的義務","以上各項皆正確"],e:"代價是指合約一方為使對方作出承諾而付出的對價，即一方對另一方的承諾或作為，故該項正確。"}},
{p:1,ch:"法律原则",q:"社交聚会,朋友之间所约定的午餐聚会:",o:["是一份不可强制执行的合约","是两人的约定合约","只要双方都在书面约定就是合约","出席聚会开始,合约便开始生效"],a:0,e:"朋友间约定的午餐属社交聚会，缺乏订立法律关系意向，属不可强制执行的合约。",src:1,tw:{ch:"法律原則",q:"社交聚會，朋友之間所約定的午餐聚會:",o:["是一份不可強制執行的合約","是兩人的約定合約","只要雙方都在書面約定就是合約","出席聚會開始，合約便開始生效"],e:"朋友間約定的午餐屬社交聚會，缺乏訂立法律關係意向，屬不可強制執行的合約。"}},
{p:1,ch:"法律原则",q:"经签署、盖章和交付的书面文件,这是",o:["简单合约","特定合约","第三者合约","契据"],a:3,e:"经签署、盖章并交付的书面文件即构成契据，故该项正确。",src:1,tw:{ch:"法律原則",q:"經簽署、蓋章和交付的書面文件，這是",o:["簡單合約","特定合約","第三者合約","契據"],e:"經簽署、蓋章並交付的書面文件即構成契據，故該項正確。"}},
{p:1,ch:"法律原则",q:"苏先生在电话中要求一张机器全险保单,保险人承诺在一星期内发出保单,电话 对话完结一小时后,该等机器在火灾中被毁,请问有否一个有效的机器全险保险 合约承保是次火灾损失?",o:["没有 : 承约不曾存在","没有 : 保单还没签发","有: 保险人一承诺发单,合约便订立了","一个有追溯力的合约将在付保费时生效"],a:2,e:"保险人在电话中承诺发出保单即构成承约，合约于承诺时即告成立，无须待保单签发，故有有效合约承保损失。",src:1,tw:{ch:"法律原則",q:"蘇先生在電話中要求一張機器全險保單，保險人承諾在一星期內發出保單，電話 對話完結一小時後，該等機器在火災中被毀，請問有否一個有效的機器全險保險 合約承保是次火災損失?",o:["沒有 : 承約不曾存在","沒有 : 保單還沒簽發","有: 保險人一承諾發單，合約便訂立了","一個有追溯力的合約將在付保費時生效"],e:"保險人在電話中承諾發出保單即構成承約，合約於承諾時即告成立，無須待保單簽發，故有有效合約承保損失。"}},
{p:1,ch:"法律原则",q:"若保险代理人精神错乱:",o:["保险人有权终止保险代理协议","保险代理的近亲可自动成为保险代理人","保险人必须维持代理合约直至保险代理人康复为止","保险人必须继续发放佣金给代理人"],a:0,e:"若保险代理人精神错乱，保险人有权终止保险代理协议，无须维持至代理人康复或继续发佣。",src:1,tw:{ch:"法律原則",q:"若保險代理人精神錯亂：",o:["保險人有權終止保險代理協議","保險代理的近親可自動成為保險代理人","保險人必須維持代理合約直至保險代理人康復為止","保險人必須繼續發放佣金給代理人"],e:"若保險代理人精神錯亂，保險人有權終止保險代理協議，無須維持至代理人康復或繼續發傭。"}},
{p:1,ch:"法律原则",q:"若委托人对其代理人作出违反责任的行为,下列哪项情况被视为正确?",o:["此乃属于刑事罪行","在法律上,代理人没有追讨权","代理人可以运用其法律权利向委托人采取行动","所有经此代理人而办理的保单变为失效"],a:2,e:"委托人违反其对代理人的责任，代理人可行使法律权利向委托人采取行动追讨，故该项正确。",src:1,tw:{ch:"法律原則",q:"若委託人對其代理人作出違反責任的行為，下列哪項情況被視為正確？",o:["此乃屬於刑事罪行","在法律上，代理人沒有追討權","代理人可以運用其法律權利向委託人採取行動","所有經此代理人而辦理的保單變為失效"],e:"委託人違反其對代理人的責任，代理人可行使法律權利向委託人採取行動追討，故該項正確。"}},
{p:1,ch:"法律原则",q:"若果代理人或委托人违反协议,另一方可采取甚么行动? i 终止合约 ii 要求赔偿 iii 合约可以维持一段时间",o:["i","ii","i, ii","i, ii, iii"],a:2,e:"一方违反协议，另一方可终止合约及／或要求赔偿，故 i 及 ii 正确。",src:1,tw:{ch:"法律原則",q:"若果代理人或委託人違反協議，另一方可採取甚麼行動? i 終止合約 ii 要求賠償 iii 合約可以維持一段時間",o:["i","ii","i, ii","i, ii, iii"],e:"一方違反協議，另一方可終止合約及／或要求賠償，故 i 及 ii 正確。"}},
{p:1,ch:"法律原则",q:"虽然在行事时并未获授权,但只要委托人事后确认该行动,就如同给予一种追溯 性的授权。此种情况下产生之代理关系称为 :",o:["通过协议","明示协议","追认","隐含授权"],a:2,e:"尽管行事时未获授权，但事后经委托人确认即产生追溯授权，此种代理关系称为追认。",src:1,tw:{ch:"法律原則",q:"雖然在行事時並未獲授權，但只要委託人事後確認該行動，就如同給予一種追溯 性的授權。此種情況下產生之代理關係稱為 :",o:["通過協議","明示協議","追認","隱含授權"],e:"儘管行事時未獲授權，但事後經委託人確認即產生追溯授權，此種代理關係稱為追認。"}},
{p:1,ch:"法律原则",q:"要成为有效合约,一份协议必须具备订立法律关系的意向,以下哪项构成有关内 容?",o:["必须支付代价","在订立法律关系时没有明示意向的某种情况下,订立法律关系的意向 可以由法庭推定的","合约双方或多方均具有订立法律关系的意向","订立法律关系的意向不适用于社交协议"],a:2,e:"订立法律关系的意向要求合约双方或多方均具备订立法律关系的意向；缺失时可酌情由法庭推定，故该项陈述正确。",src:1,tw:{ch:"法律原則",q:"要成為有效合約，一份協議必須具備訂立法律關係的意向，以下哪項構成有關內 容？",o:["必須支付代價","在訂立法律關係時沒有明示意向的某種情況下，訂立法律關係的意向 可以由法庭推定的","合約雙方或多方均具有訂立法律關係的意向","訂立法律關係的意向不適用於社交協議"],e:"訂立法律關係的意向要求合約雙方或多方均具備訂立法律關係的意向；缺失時可酌情由法庭推定，故該項陳述正確。"}},
{p:1,ch:"法律原则",q:"要成立任何合约,其邀约:",o:["必须按其原有内容而被承约","可以视乎若干条件后而被承约","必须被承约,并须以书面通知收到","总是必须大体上被承约"],a:0,e:"合约的承约必须与要约原有内容一致，任何改变即构成反要约，故「必须按其原有内容被承约」正确。",src:1,tw:{ch:"法律原則",q:"要成立任何合約，其邀約：",o:["必須按其原有內容而被承約","可以視乎若干條件後而被承約","必須被承約，並須以書面通知收到","總是必須大體上被承約"],e:"合約的承約必須與要約原有內容一致，任何改變即構成反要約，故「必須按其原有內容被承約」正確。"}},
{p:1,ch:"法律原则",q:"要约是:",o:["必定只是投保人提交投保书","递交投保书的一方,使为要约人,保单即是生效","没有要约,没有合约","投保人提交人寿保单投保书,未缴交任何费用"],a:2,e:"没有要约便无法成立合约，这是合约法的基本原则，故该项正确。",src:1,tw:{ch:"法律原則",q:"要約是:",o:["必定只是投保人提交投保書","遞交投保書的一方，使為要約人，保單即是生效","没有要約，沒有合約","投保人提交人壽保單投保書，未繳交任何費用"],e:"沒有要約便無法成立合約，這是合約法的基本原則，故該項正確。"}},
{p:1,ch:"法律原则",q:"要终止代理协定关系 :",o:["只有委托人","只有受托人及委托人","双方同意的情况下,可以撤销合约","一旦合约生效,并不能撤销合约"],a:2,e:"代理协定关系可在双方同意的情况下予以撤销，故该项正确。",src:1,tw:{ch:"法律原則",q:"要終止代理協定關係 :",o:["只有委託人","只有受託人及委託人","雙方同意的情況下，可以撤銷合約","一旦合約生效，並不能撤銷合約"],e:"代理協定關係可在雙方同意的情況下予以撤銷，故該項正確。"}},
{p:1,ch:"法律原则",q:"要达成有效合约,一项协议必须在订立时具备订立法律关系的意向,下面哪项属 于这方面的要求?",o:["这种意向必须在合约文件中表明","只在年满18岁合约一方必须具备这种意向","在没有明示意向订立法律关系的某种情况下, 订立法律关系意向是可以由法院推定的","这项要求不适用于商业协议"],a:0,e:"订立法律关系的意向作为有效合约的要件，须于订立时明确表明；法院推定只是无明示意图时的补充，而非该要件本身。",src:1,tw:{ch:"法律原則",q:"要達成有效合約，一項協議必須在訂立時具備訂立法律關係的意向，下面哪項屬 於這方面的要求？",o:["這種意向必須在合約文件中表明","只在年滿18歲合約一方必須具備這種意向","在沒有明示意向訂立法律關係的某種情況下， 訂立法律關係意向是可以由法院推定的","這項要求不適用於商業協議"],e:"訂立法律關係的意向作為有效合約的要件，須於訂立時明確表明；法院推定只是無明示意圖時的補充，而非該要件本身。"}},
{p:1,ch:"法律原则",q:"订立代理关系,以下哪项必须存在?",o:["以法律认可的方式订立","具备订立法律关系的意向","受代理合约所支配","代价"],a:0,e:"代理关系须以法律认可的方式（如协议、隐含或追认）成立，这是订立代理关系的前提，故该项正确。",src:1,tw:{ch:"法律原則",q:"訂立代理關係，以下哪項必須存在？",o:["以法律認可的方式訂立","具備訂立法律關係的意向","受代理合約所支配","代價"],e:"代理關係須以法律認可的方式（如協議、隱含或追認）成立，這是訂立代理關係的前提，故該項正確。"}},
{p:1,ch:"法律原则",q:"除保险代理合约叧外指明,委托人必须偿付代理人以下哪项支出?",o:["任何种类的支出","包括代理人的行政开支","代理人替委托人行事时合理和正当地招致的费用及开支","代理人替委托人收取的款项,以50%为上限"],a:2,e:"除合约另有指明外，委托人须偿付代理人替其行事时合理和正当地招致的费用及开支，故该项正确。",src:1,tw:{ch:"法律原則",q:"除保險代理合約叧外指明，委託人必須償付代理人以下哪項支出？",o:["任何種類的支出","包括代理人的行政開支","代理人替委託人行事時合理和正當地招致的費用及開支","代理人替委託人收取的款項，以50%為上限"],e:"除合約另有指明外，委託人須償付代理人替其行事時合理和正當地招致的費用及開支，故該項正確。"}},
{p:1,ch:"法律原则",q:"需要甚么规定才能延续一份为期一年的协议?",o:["只需委托人同意便可","只需代理人同意便可","需在委托人及代理人双方同意下才可延续","自动延续"],a:2,e:"为期一年的协议须经委托人及代理人双方同意方可延续，不能单方或自动延续。",src:1,tw:{ch:"法律原則",q:"需要甚麼規定才能延續一份為期一年的協議?",o:["只需委託人同意便可","只需代理人同意便可","需在委託人及代理人雙方同意下才可延續","自動延續"],e:"為期一年的協議須經委託人及代理人雙方同意方可延續，不能單方或自動延續。"}},
{p:1,ch:"保险原则",q:"A向”X”买了第三者保险。B向“Y”为自己的汽车投买保险,但A撞毁B的 汽车,分担并不适用的原因为:",o:["是次意外是由A的错失引致","B在是次意外上是无辜的","“X”及 “Y”没有共同保障的利益","B不想损失无赔偿折扣"],a:2,e:"分担须有多份保单就同一被保险人及同一受保利益承保；A、B 各自投保自己的车，X 与 Y 没有共同保障的利益，故不适用分担。",src:1,tw:{ch:"保險原則",q:"A向”X”買了第三者保險。B向“Y”為自己的汽車投買保險,但A撞毀B的 汽車,分擔並不適用的原因為:",o:["是次意外是由A的錯失引致","B在是次意外上是無辜的","“X”及 “Y”沒有共同保障的利益","B不想損失無賠償折扣"],e:"分擔須有多份保單就同一被保險人及同一受保利益承保；A、B 各自投保自己的車，X 與 Y 沒有共同保障的利益，故不適用分擔。"}},
{p:1,ch:"保险原则",q:"「委付」必须涉及以下哪项条件? i 把保险标的交予保险人 ii 保单有全保条款 iii 保险标的全损 iv 有关保单受弥偿原则约束",o:["只有i","i 及iv","ii及iii","ii, iii 及iv"],a:1,e:"委付适用于受弥偿原则约束的保单，须把保险标的交予保险人并提出委付通知；全保条款或全损并非必要条件，故 i 及 iv 正确。",src:1,tw:{ch:"保險原則",q:"「委付」必須涉及以下哪項條件？ i 把保險標的交予保險人 ii 保單有全保條款 iii 保險標的全損 iv 有關保單受彌償原則約束",o:["只有i","i 及iv","ii及iii","ii, iii 及iv"],e:"委付適用於受彌償原則約束的保單，須把保險標的交予保險人並提出委付通知；全保條款或全損並非必要條件，故 i 及 iv 正確。"}},
{p:1,ch:"保险原则",q:"「将根据合约所需给付的金额,转付予保单持有人以外的人」。此句子是指 :",o:["代位权","权益转让","委付","保单收益转让"],a:3,e:"将合约下给付金额转付予保单持有人以外的人，属保单收益的转让，故该项正确。",src:1,tw:{ch:"保險原則",q:"「將根據合約所需給付的金額，轉付予保單持有人以外的人」。此句子是指 ：",o:["代位權","權益轉讓","委付","保單收益轉讓"],e:"將合約下給付金額轉付予保單持有人以外的人，屬保單收益的轉讓，故該項正確。"}},
{p:1,ch:"保险原则",q:"「更换」这种赔偿方法,不适用于哪类保单? i 家居保险 ii 水险 iii 人身意外保险 iv 人寿保险",o:["i及ii","i及iii","ii及iv","iii及iv"],a:3,e:"「更换」是以新换旧的财产赔偿方法，不适用于给付定额的人身意外及人寿保险，故 iii、iv 正确。",src:1,tw:{ch:"保險原則",q:"「更換」這種賠償方法，不適用於哪類保單？ i 家居保險 ii 水險 iii 人身意外保險 iv 人壽保險",o:["i及ii","i及iii","ii及iv","iii及iv"],e:"「更換」是以新換舊的財產賠償方法，不適用於給付定額的人身意外及人壽保險，故 iii、iv 正確。"}},
{p:1,ch:"保险原则",q:"「最高诚信」的责任适用于:",o:["被保险人而非保险人","保险人而非被保险人","任何情况下的被保险人及保险人","被保险人及保险人,但只限于保单有这要求"],a:2,e:"最高诚信是相互责任，适用于任何情况下的被保险人及保险人双方，而非仅限一方。",src:1,tw:{ch:"保險原則",q:"「最高誠信」的責任適用於：",o:["被保險人而非保險人","保險人而非被保險人","任何情況下的被保險人及保險人","被保險人及保險人，但只限於保單有這要求"],e:"最高誠信是相互責任，適用於任何情況下的被保險人及保險人雙方，而非僅限一方。"}},
{p:1,ch:"保险原则",q:"「近因」是很重要的,因为:",o:["它是找出购买保险的原因","需要它去确定保险标的的价值","不是每一项引致损失的原因均受到保障","以上各项皆是"],a:2,e:"近因原则用于确定导致损失的有效原因，因为并非每个引致损失的原因都在保障范围，只有近因是受保危险才获赔。",src:1,tw:{ch:"保險原則",q:"「近因」是很重要的，因為：",o:["它是找出購買保險的原因","需要它去確定保險標的的價值","不是每一項引致損失的原因均受到保障","以上各項皆是"],e:"近因原則用於確定導致損失的有效原因，因為並非每個引致損失的原因都在保障範圍，只有近因是受保危險才獲賠。"}},
{p:1,ch:"保险原则",q:"一个保险的原则,致力于恢愎被保人在损失前的财务状况,被称为:",o:["弥偿","代位权","最高诚信","可保权益"],a:0,e:"弥偿原则致力于使被保险人回复损失前的财务状况，故该项正确。",src:1,tw:{ch:"保險原則",q:"一個保險的原則，致力於恢愎被保人在損失前的財務狀況，被稱為：",o:["彌償","代位權","最高誠信","可保權益"],e:"彌償原則致力於使被保險人回覆損失前的財務狀況，故該項正確。"}},
{p:1,ch:"保险原则",q:"一个单位购买火险后,邻居发生火警,在必要情况下,消防员需要破坏此单 位某些设施进入邻居救火,有关这些设施的损失:",o:["因为受保危险引致不保危险,故此可得到赔偿","因为不保危险引致受保危险,故此得不到赔偿","属于不保危险,故此得不到赔偿","属于受保危险,故此得到赔偿"],a:0,e:"邻居火灾（受保危险）迫使消防员为救火而破坏本单位设施，损失近因是受保危险，故可获赔偿。",src:1,tw:{ch:"保險原則",q:"一個單位購買火險後，鄰居發生火警，在必要情況下，消防員需要破壞此單 位某些設施進入鄰居救火，有關這些設施的損失：",o:["因為受保危險引致不保危險，故此可得到賠償","因為不保危險引致受保危險，故此得不到賠償","屬於不保危險，故此得不到賠償","屬於受保危險，故此得到賠償"],e:"鄰居火災（受保危險）迫使消防員為救火而破壞本單位設施，損失近因是受保危險，故可獲賠償。"}},
{p:1,ch:"保险原则",q:"一些货品受到商业火险的保障,但因为受到火灾的浓烟导致货品毁于一旦。 对此以下哪项是正确?",o:["不会得到保障的,因为损失是由非受保危险引致","不会得到保障的,因为损失是由除外危险引致","得到保障的,因为损失是由受保危险引致不保危险","必然会提供赔偿,这是保险人同情所显示的"],a:2,e:"火灾（受保危险）产生的浓烟损毁货物，损失近因为受保危险，即使浓烟本身可能属不保危险，仍获保障。",src:1,tw:{ch:"保險原則",q:"一些貨品受到商業火險的保障，但因為受到火災的濃煙導致貨品毁於一旦。 對此以下哪項是正確？",o:["不會得到保障的，因為損失是由非受保危險引致","不會得到保障的，因為損失是由除外危險引致","得到保障的，因為損失是由受保危險引致不保危險","必然會提供賠償，這是保險人同情所顯示的"],e:"火災（受保危險）產生的濃煙損毀貨物，損失近因為受保危險，即使濃煙本身可能屬不保危險，仍獲保障。"}},
{p:1,ch:"保险原则",q:"一份商业火险保险单含有所谓的「海上条款」,这条款的主要目的是:",o:["豁免承保储存在码头旁边仓库里的财产","避免和任何足额水险分担","确保任何承保了有关财产的现有水险无效","如果有水险保单也承保了有关财产,就可以完成避开火险保单"],a:1,e:"海上条款旨在当同一财产同时由水险承保时，令火险退让，避免与足额水险发生分担。",src:1,tw:{ch:"保險原則",q:"一份商業火險保險單含有所謂的「海上條款」，這條款的主要目的是：",o:["豁免承保儲存在碼頭旁邊倉庫裡的財產","避免和任何足額水險分擔","確保任何承保了有關財產的現有水險無效","如果有水險保單也承保了有關財產，就可以完成避開火險保單"],e:"海上條款旨在當同一財產同時由水險承保時，令火險退讓，避免與足額水險發生分擔。"}},
{p:1,ch:"保险原则",q:"一份恰当地安排的财产保险,于被保险人的全损出现时,应可提供完全的补 偿。这项补偿代表该名被保险人在有关财产上的权益,显示弥偿与以下哪一 项的原则相连?",o:["近因","可保权益","最高诚信","以上所有各项"],a:1,e:"补偿额代表被保险人在财产上的权益，显示赔偿以可保权益为上限，故弥偿与可保权益原则相连。",src:1,tw:{ch:"保險原則",q:"一份恰當地安排的財產保險，於被保險人的全損出現時，應可提供完全的補 償。這項補償代表該名被保險人在有關財產上的權益，顯示彌償與以下哪一 項的原則相連？",o:["近因","可保權益","最高誠信","以上所有各項"],e:"補償額代表被保險人在財產上的權益，顯示賠償以可保權益為上限，故彌償與可保權益原則相連。"}},
{p:1,ch:"保险原则",q:"一份水险保单以定值作索偿,下列哪项损失赔偿为正确:",o:["赔偿为保额的一半","这是一份弥偿赔偿","以约定的定价赔偿","无论损失多少也会得到十足的赔偿"],a:2,e:"定值保单按事先约定的价值赔偿，而非损失时重新估价，故「以约定的定价赔偿」正确。",src:1,tw:{ch:"保險原則",q:"一份水險保單以定值作索償，下列哪項損失賠償為正確：",o:["賠償為保額的一半","這是一份彌償賠償","以約定的定價賠償","無論損失多少也會得到十足的賠償"],e:"定值保單按事先約定的價值賠償，而非損失時重新估價，故「以約定的定價賠償」正確。"}},
{p:1,ch:"保险原则",q:"一份船体保单的承保书上这样写着: 「保额:1,000,000,约定价值:1,000,000」,这样意味着:",o:["在损失时,保单持有人将得到一半赔偿","约定价值在损失时将被视作实际损失价值,但只限于全损索偿目的","约定价值在损失时将被视作实际损失价值","这是一项重复保险"],a:2,e:"保单载明约定价值，损失时即以该约定价值视作实际损失价值计算赔偿，故该项正确。",src:1,tw:{ch:"保險原則",q:"一份船體保單的承保書上這樣寫着: 「保額:1,000,000,約定價值:1,000,000」,這樣意味着:",o:["在損失時,保單持有人將得到一半賠償","約定價值在損失時將被視作實際損失價值,但只限於全損索償目的","約定價值在損失時將被視作實際損失價值","這是一項重複保險"],e:"保單載明約定價值，損失時即以該約定價值視作實際損失價值計算賠償，故該項正確。"}},
{p:1,ch:"保险原则",q:"一名建筑承判商须负责向一部私家车的拥有人支付HK$10,000,000,由于一 项责任限额的应用,向保险人获得HK$8,000,000赔偿,保险人后来追讨HK$ 5,000,000。请问谁有权分享这笔钱?而分到的金额又是多少?",o:["保险人占HK$5,000,000,被保险人没份儿","保险人占HK$3,000,000,被保险人占HK$2,000,000","保险人没份儿,被保险人占HK$5,000,000","保险人占五份之四,被保险人占五份之一"],a:1,e:"被保险人自留未获赔偿的缺口2,000,000应优先从追回款项中取回，余额3,000,000归保险人，故为保险占3M、被保险人占2M。",src:1,tw:{ch:"保險原則",q:"一名建築承判商須負責向一部私家車的擁有人支付HK$10,000,000，由於一 項責任限額的應用，向保險人獲得HK$8,000,000賠償，保險人後來追討HK$ 5,000,000。請問誰有權分享這筆錢？而分到的金額又是多少？",o:["保險人佔HK$5,000,000，被保險人沒份兒","保險人佔HK$3,000,000，被保險人佔HK$2,000,000","保險人沒份兒，被保險人佔HK$5,000,000","保險人佔五份之四，被保險人佔五份之一"],e:"被保險人自留未獲賠償的缺口2,000,000應優先從追回款項中取回，餘額3,000,000歸保險人，故為保險佔3M、被保險人佔2M。"}},
{p:1,ch:"保险原则",q:"一名建筑承判商须负责向一部私家车的拥有人支付HK$12,000,000,因为一 项部份责任限额的应用,他只有权向其汽车保险人取得保险金HK$10,000,00 0,如果保险人后能够向对有关意外须承担60%责任的另一名驾车者追回 HK$8,000,000,请问谁有权分享这笔钱?而分到的金额又是多少?",o:["保险人占HK$8,000,000,被保险人没份儿","保险人占HK$6,000,000,被保险人占HK$2,000,000","保险人没份儿,被保险人占HK$8,000,000","保险人占6成,被保险人占4成"],a:1,e:"被保险人未获赔的自留缺口为2,000,000，先从追回8,000,000中取回，余额6,000,000归保险人，故正确。",src:1,tw:{ch:"保險原則",q:"一名建築承判商須負責向一部私家車的擁有人支付HK$12,000,000，因為一 項部份責任限額的應用，他只有權向其汽車保險人取得保險金HK$10,000,00 0，如果保險人後能夠向對有關意外須承擔60%責任的另一名駕車者追回 HK$8,000,000，請問誰有權分享這筆錢？而分到的金額又是多少？",o:["保險人佔HK$8,000,000，被保險人沒份兒","保險人佔HK$6,000,000，被保險人佔HK$2,000,000","保險人沒份兒，被保險人佔HK$8,000,000","保險人佔6成，被保險人佔4成"],e:"被保險人未獲賠的自留缺口為2,000,000，先從追回8,000,000中取回，餘額6,000,000歸保險人，故正確。"}},
{p:1,ch:"保险原则",q:"一名建筑承判商须负责向一部私家车的拥有人支付HK$13,000,000,因为一 项部份责任限额的应用,他只有权向其汽车保险人取得保险金HK$12,000,00 0,如果保险人后能够向对有关意外须承担80%责任的另一名驾车者追回 HK$7,000,000,请问谁有权分享这笔钱?而分到的金额又是多少?",o:["保险人占HK$7,000,000,被保险人没份儿","保险人占HK$6,000,000,被保险人占HK$1,000,000","保险人没份儿,被保险人占HK$7,000,000","保险人占十三分之十二,被保险人占十三分之一"],a:1,e:"被保险人自留缺口1,000,000先获补足，余下6,000,000归保险人，故为保险占6M、被保险人占1M。",src:1,tw:{ch:"保險原則",q:"一名建築承判商須負責向一部私家車的擁有人支付HK$13,000,000，因為一 項部份責任限額的應用，他只有權向其汽車保險人取得保險金HK$12,000,00 0，如果保險人後能夠向對有關意外須承擔80%責任的另一名駕車者追回 HK$7,000,000，請問誰有權分享這筆錢？而分到的金額又是多少？",o:["保險人佔HK$7,000,000，被保險人沒份兒","保險人佔HK$6,000,000，被保險人佔HK$1,000,000","保險人沒份兒，被保險人佔HK$7,000,000","保險人佔十三分之十二，被保險人佔十三分之一"],e:"被保險人自留缺口1,000,000先獲補足，餘下6,000,000歸保險人，故為保險佔6M、被保險人佔1M。"}},
{p:1,ch:"保险原则",q:"一名提供雇员补偿保险的保险人,在一项条款下,可向疏忽的第三者索偿对 受伤员工已支付的赔偿,这显示以下哪项情况出现?",o:["在损余中出现代位权","在合约上出现代位权","在侵权法上出现代位权","在法规下出现代位权"],a:3,e:"依据雇员补偿条例等法规，保险人赔偿后可向疏忽的第三者追偿，属在法规下产生的代位权。",src:1,tw:{ch:"保險原則",q:"一名提供僱員補償保險的保險人，在一項條款下，可向疏忽的第三者索償對 受傷員工已支付的賠償，這顯示以下哪項情況出現？",o:["在損餘中出現代位權","在合約上出現代位權","在侵權法上出現代位權","在法規下出現代位權"],e:"依據僱員補償條例等法規，保險人賠償後可向疏忽的第三者追償，屬在法規下產生的代位權。"}},
{p:1,ch:"保险原则",q:"一幢大厦因地震倒塌,而这大厦已经有二十年楼龄,大厦亦有购买火灾及附 加危险保障,让保险人须为重建这大厦的重建费用作出全数赔付,但不能扣 除损耗,即是表示这大厦的保险是以什么形式发出?",o:["「以新代旧」形式","不能扣减形式","以新代旧形式","重置保险"],a:3,e:"全数赔付重建费用而不扣除楼龄折旧，即以重置价值方式承保，属重置保险。",src:1,tw:{ch:"保險原則",q:"一幢大廈因地震倒塌，而這大廈已經有二十年樓齡，大廈亦有購買火災及附 加危險保障，讓保險人須為重建這大廈的重建費用作出全數賠付，但不能扣 除損耗，即是表示這大廈的保險是以什麼形式發出？",o:["「以新代舊」形式","不能扣減形式","以新代舊形式","重置保險"],e:"全數賠付重建費用而不扣除樓齡折舊，即以重置價值方式承保，屬重置保險。"}},
{p:1,ch:"保险原则",q:"一批货物已经购买商业火险单,大厦发现火灾,货物受浓烟损坏,损失是:",o:["不会得到保障的,因为损失是由非受保危险引致","不会得到保障的,因为损失是由除外危险引致","得到保障的,因为损失是由受保危险引致不保危险","得到保障的,因为损失是由受保危险引致"],a:2,e:"货物因火灾（受保危险）产生的浓烟受损，近因为受保危险，故获保障。",src:1,tw:{ch:"保險原則",q:"一批貨物已經購買商業火險單，大廈發現火災，貨物受濃煙損壞，損失是：",o:["不會得到保障的，因為損失是由非受保危險引致","不會得到保障的，因為損失是由除外危險引致","得到保障的，因為損失是由受保危險引致不保危險","得到保障的，因為損失是由受保危險引致"],e:"貨物因火災（受保危險）產生的濃煙受損，近因為受保危險，故獲保障。"}},
{p:1,ch:"保险原则",q:"一般情况下,人寿及大部分人身意外保单均不受弥偿所约束,以下哪项是正 确的:",o:["人命价值是无法量度的","这种保险具有无限可保权益","不论支付多少,也无法得出精确的财务补偿","以上各项均成立"],a:3,e:"人命价值无法精确以财务量度，人寿及人身意外被视为附有无穷可保权益，且给付无法达到精确补偿，故各项均成立。",src:1,tw:{ch:"保險原則",q:"一般情況下，人壽及大部分人身意外保單均不受彌償所約束，以下哪項是正 確的：",o:["人命價值是無法量度的","這種保險具有無限可保權益","不論支付多少，也無法得出精確的財務補償","以上各項均成立"],e:"人命價值無法精確以財務量度，人壽及人身意外被視為附有無窮可保權益，且給付無法達到精確補償，故各項均成立。"}},
{p:1,ch:"保险原则",q:"一间育儿院负责人要求每位家长必须签署一份协议,当中订明其孩子在育儿 院内所受之伤害,家长不得向育儿院追究。尽管如此,育儿院营运人就其所 照顾的孩子们在其处所所受之伤害的潜在法律责任购买了一份责任保险,请 问育儿院是否有权购买此份保险?理据为何?",o:["他不必购买此份保险;因政府注册的育儿院不须承担责任","保险无效;因负责人并无法律责任,因此欠缺可保权益而不能投保","保险无效;因为责任保单将「受保处所之伤害」列为除外责任","保险有效;因育儿院须为其作为与不作为承担潜在的法律责任"],a:3,e:"该免责协议不能免除育儿院的潜在法定责任，育儿院对其作为与不作为仍承担潜在法律责任，故具有可保权益，保险有效。",src:1,tw:{ch:"保險原則",q:"一間育兒院負責人要求每位家長必須簽署一份協議，當中訂明其孩子在育兒 院內所受之傷害，家長不得向育兒院追究。儘管如此，育兒院營運人就其所 照顧的孩子們在其處所所受之傷害的潛在法律責任購買了一份責任保險，請 問育兒院是否有權購買此份保險？理據為何?",o:["他不必購買此份保險；因政府註冊的育兒院不須承擔責任","保險無效；因負責人並無法律責任，因此欠缺可保權益而不能投保","保險無效；因為責任保單將「受保處所之傷害」列為除外責任","保險有效；因育兒院須為其作為與不作為承擔潛在的法律責任"],e:"該免責協議不能免除育兒院的潛在法定責任，育兒院對其作為與不作為仍承擔潛在法律責任，故具有可保權益，保險有效。"}},
{p:1,ch:"保险原则",q:"一项损失发生了,金额为$4,000,为此提供保障的火险保单为$1,000,000, 其中包括了一项比例分摊条款及金额为$8,000的单一物件限额。在损失发生 时,财产的价值为$4,000,000,保险人根据保单条款作出了赔偿,其后保险 人把受毁的财产卖掉,取得$800。究竟保险人向被保险人作出了多少赔偿? 在处理受毁财产时,就剩余价值 (如有的话)向被保险人给付多少钱?",o:["$1,000及$0","$1,000及$600","$4,000及$0","$4,000及$800 3.4.7,"],a:1,e:"按比例分摊，赔偿为4,000×(1,000,000/4,000,000)＝1,000；损余800按未投保比例3/4归被保险人即600，故正确。",src:1,tw:{ch:"保險原則",q:"一項損失發生了，金額為$4,000，為此提供保障的火險保單為$1,000,000， 其中包括了一項比例分攤條款及金額為$8,000的單一物件限額。在損失發生 時，財產的價值為$4,000,000，保險人根據保單條款作出了賠償，其後保險 人把受毁的財產賣掉，取得$800。究竟保險人向被保險人作出了多少賠償？ 在處理受毁財產時，就剩餘價值 (如有的話)向被保險人給付多少錢？",o:["$1,000及$0","$1,000及$600","$4,000及$0","$4,000及$800 3.4.7,"],e:"按比例分攤，賠償為4,000×(1,000,000/4,000,000)＝1,000；損餘800按未投保比例3/4歸被保險人即600，故正確。"}},
{p:1,ch:"保险原则",q:"一项损失发生了,金额为$4,000,就此提供保障的火险单的保额为$1,000,0 00,并包含了一项比例分摊条款及一项$8,000的限额。损失发生时,受保财 产的实际价值为$4,000,000。保险人就保单提供弥偿后,把受摧毁的财产卖 掉,取得$800。请问保险人就保单赔付了多少钱?又就处理受摧毁的财产后 ,须就残余价值(如有的话)向被保险人支付多少钱?",o:["分别为$1,000及$600","分别为$1,000及$0","分别为$4,000及$600","分别为$4,000及$800"],a:0,e:"同上，比例分摊后赔1,000，损余800中未投保部分600归被保险人，故正确。",src:1,tw:{ch:"保險原則",q:"一項損失發生了，金額為$4,000，就此提供保障的火險單的保額為$1,000,0 00，並包含了一項比例分攤條款及一項$8,000的限額。損失發生時，受保財 產的實際價值為$4,000,000。保險人就保單提供彌償後，把受摧毀的財產賣 掉，取得$800。請問保險人就保單賠付了多少錢？又就處理受摧毀的財產後 ，須就殘餘價值(如有的話)向被保險人支付多少錢？",o:["分別為$1,000及$600","分別為$1,000及$0","分別為$4,000及$600","分別為$4,000及$800"],e:"同上，比例分攤後賠1,000，損餘800中未投保部分600歸被保險人，故正確。"}},
{p:1,ch:"保险原则",q:"一项损失发生了,金额为$6,000,就此提供保障的火险单的保额为$1,000,0 00,并包含了一项比例分摊条款及一项$1,000的起赔额。损失发生时,受保 财产的实际价值为$3,000,000。保险人就保单提供弥偿后,把受摧毁的财产 卖掉,取得$300。请问保险人就保单赔付了多少钱?又就处理受摧毁的财产 后,须就残余价值(如有的话)向被保险人支付多少钱?",o:["分别为$2,000及$200","分别为$2,000及$100","分别为$1,000及$300","分别为$1,000及$200"],a:0,e:"按比例分摊，赔偿为6,000×(1,000,000/3,000,000)＝2,000；损余300中未投保部分（2/3）200归被保险人，故正确。",src:1,tw:{ch:"保險原則",q:"一項損失發生了，金額為$6,000，就此提供保障的火險單的保額為$1,000,0 00，並包含了一項比例分攤條款及一項$1,000的起賠額。損失發生時，受保 財產的實際價值為$3,000,000。保險人就保單提供彌償後，把受摧毀的財產 賣掉，取得$300。請問保險人就保單賠付了多少錢？又就處理受摧毀的財產 後，須就殘餘價值(如有的話)向被保險人支付多少錢？",o:["分別為$2,000及$200","分別為$2,000及$100","分別為$1,000及$300","分別為$1,000及$200"],e:"按比例分攤，賠償為6,000×(1,000,000/3,000,000)＝2,000；損餘300中未投保部分（2/3）200歸被保險人，故正確。"}},
{p:1,ch:"保险原则",q:"下列哪项属于转让保险合约所带来的影响?",o:["承让人会成为保单的保管人","承让人会成为保单收益的受托人","不论转让人或是承保人所作的违法行为不会对承让人构成影响","保险合约从此保障承让人可能遭受的损失"],a:3,e:"保险合约经转让后，保单自此保障承让人在受保财产上可能遭受的损失，承让人成为新的受保人。",src:1,tw:{ch:"保險原則",q:"下列哪項屬於轉讓保險合約所帶來的影響？",o:["承讓人會成為保單的保管人","承讓人會成為保單收益的受托人","不論轉讓人或是承保人所作的違法行為不會對承讓人構成影響","保險合約從此保障承讓人可能遭受的損失"],e:"保險合約經轉讓後，保單自此保障承讓人在受保財產上可能遭受的損失，承讓人成為新的受保人。"}},
{p:1,ch:"保险原则",q:"下列哪项是最高诚信的正确描述? i 它是一项披露责任 ii 无论有否被问及,都必须披露重要资料 iii 源自普通法,可以以保单措词修改 iv 在任何情况下,保险人必须承担违反最高诚信的法律责任",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],a:0,e:"最高诚信要求不论有否被问及均须披露重要事实，其源自普通法并可借保单措词修改，故 i、ii、iii 正确；保险人并非在任何情况下都须承担违反责任，iv 不对。",src:1,tw:{ch:"保險原則",q:"下列哪項是最高誠信的正確描述？ i 它是一項披露責任 ii 無論有否被問及，都必須披露重要資料 iii 源自普通法，可以以保單措詞修改 iv 在任何情況下，保險人必須承擔違反最高誠信的法律責任",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"最高誠信要求不論有否被問及均須披露重要事實，其源自普通法並可借保單措詞修改，故 i、ii、iii 正確；保險人並非在任何情況下都須承擔違反責任，iv 不對。"}},
{p:1,ch:"保险原则",q:"下列哪项最能解释弥偿?",o:["补偿","精确赔偿","保单的实际保额","保险标的实际价值"],a:1,e:"弥偿的精义在于精确赔偿，使被保险人回复损失前状况而非从中获利，故「精确赔偿」最能解释弥偿。",src:1,tw:{ch:"保險原則",q:"下列哪項最能解釋彌償？",o:["補償","精確賠償","保單的實際保額","保險標的實際價值"],e:"彌償的精義在於精確賠償，使被保險人回覆損失前狀況而非從中獲利，故「精確賠償」最能解釋彌償。"}},
{p:1,ch:"保险原则",q:"下列哪项有关约定价值保单是正确? i 这类保单可以用于价值较高的物件上,例如艺术作品 ii 折旧是最大的考虑因素 iii 保额视乎专家的估价 iv 当出现全损时,保单就会承担专家估价的保额再扣除当时的折旧率",o:["i及ii","i及iii","ii及iii","iii及iv"],a:1,e:"约定价值保单适用于艺术品等高价物件，保额依专家估价，且全损按约定价值赔偿而不普遍考虑折旧，故 i、iii 正确。",src:1,tw:{ch:"保險原則",q:"下列哪項有關約定價值保單是正確？ i 這類保單可以用於價值較高的物件上，例如藝術作品 ii 折舊是最大的考慮因素 iii 保額視乎專家的估價 iv 當出現全損時，保單就會承擔專家估價的保額再扣除當時的折舊率",o:["i及ii","i及iii","ii及iii","iii及iv"],e:"約定價值保單適用於藝術品等高價物件，保額依專家估價，且全損按約定價值賠償而不普遍考慮折舊，故 i、iii 正確。"}},
{p:1,ch:"保险原则",q:"不同类型保单在不同时间须具有可保权益,以下哪些保单在索偿时须具有可 保权益? i 人寿保险 ii 利润损失保险 iii 任何形式的责任保险 iv 船上货物保险",o:["i, ii","ii, iii","i, ii, iv","ii, iii, iv"],a:3,e:"利润损失保险、责任保险及船上货物保险均在索偿时须具有可保权益；人寿保险则只需在投保时具备，故 ii、iii、iv 正确。",src:1,tw:{ch:"保險原則",q:"不同類型保單在不同時間須具有可保權益，以下哪些保單在索償時須具有可 保權益？ i 人壽保險 ii 利潤損失保險 iii 任何形式的責任保險 iv 船上貨物保險",o:["i, ii","ii, iii","i, ii, iv","ii, iii, iv"],e:"利潤損失保險、責任保險及船上貨物保險均在索償時須具有可保權益；人壽保險則只需在投保時具備，故 ii、iii、iv 正確。"}},
{p:1,ch:"保险原则",q:"为何分担不适用于人寿保险?",o:["因为人寿保险不受弥偿所约束","因为它们不是保障导致损失的相同危险","因为所有保障都是由同一保险人提供","因为它们不是保障相同的标的"],a:0,e:"人寿保险不受弥偿原则约束，故分担（弥偿的引申）不适用于人寿保险。",src:1,tw:{ch:"保險原則",q:"為何分擔不適用於人壽保險？",o:["因為人壽保險不受彌償所約束","因為它們不是保障導致損失的相同危險","因為所有保障都是由同一保險人提供","因為它們不是保障相同的標的"],e:"人壽保險不受彌償原則約束，故分擔（彌償的引申）不適用於人壽保險。"}},
{p:1,ch:"保险原则",q:"为何弥偿不能适用于人寿保险及人身意外保险? i 人命是没有任何方法精确地以财务方法量度 ii 人寿保险一般视为附有无穷的可保权益 iii 人寿保险一般视为附有有限的可保权益 iv 人命是可以精确地以财务方法量度",o:["i 及 ii","i 及iii","ii 及 iii","iii 及 iv"],a:0,e:"人命无法精确以财务量度，人寿保险一般被视为附有无穷可保权益，故弥偿不适用于人寿及人身意外保险，i、ii 正确。",src:1,tw:{ch:"保險原則",q:"為何彌償不能適用於人壽保險及人身意外保險？ i 人命是沒有任何方法精確地以財務方法量度 ii 人壽保險一般視為附有無窮的可保權益 iii 人壽保險一般視為附有有限的可保權益 iv 人命是可以精確地以財務方法量度",o:["i 及 ii","i 及iii","ii 及 iii","iii 及 iv"],e:"人命無法精確以財務量度，人壽保險一般被視為附有無窮可保權益，故彌償不適用於人壽及人身意外保險，i、ii 正確。"}},
{p:1,ch:"保险原则",q:"人寿保险可保权益有别于一般业务,寿险可保权益在什么时候需要?",o:["保单开始时","索偿出现时","保单转让时","保单开始及索偿时"],a:0,e:"人寿保险的可保权益只需在保单开始（投保）时存在，索偿时无须具备，故该项正确。",src:1,tw:{ch:"保險原則",q:"人壽保險可保權益有別於一般業務，壽險可保權益在什麼時候需要？",o:["保單開始時","索償出現時","保單轉讓時","保單開始及索償時"],e:"人壽保險的可保權益只需在保單開始（投保）時存在，索償時無須具備，故該項正確。"}},
{p:1,ch:"保险原则",q:"人寿及人身意外保单有时称为「利益保单」,这是由于:",o:["在正常情况下它们不提供弥偿","赔付的比财务损失多","所缴付的保费毋须缴税","赔偿时不会受比例分担约束"],a:0,e:"人寿及人身意外保单通常给付定额而非提供弥偿，故称为「利益保单」。",src:1,tw:{ch:"保險原則",q:"人壽及人身意外保單有時稱為「利益保單」，這是由於：",o:["在正常情況下它們不提供彌償","賠付的比財務損失多","所繳付的保費毋須繳稅","賠償時不會受比例分擔約束"],e:"人壽及人身意外保單通常給付定額而非提供彌償，故稱為「利益保單」。"}},
{p:1,ch:"保险原则",q:"代位与分担有近似目标,就是两者均:",o:["要求有两份以上的保单","要求不同保险单保障相同权益","力求确保由疏忽一方赔偿损失","确保被保险人最后不会收取超过弥偿的金额"],a:3,e:"代位与分担的共同目标均是确保被保险人最终不会收取超过弥偿的金额，防止超额获利。",src:1,tw:{ch:"保險原則",q:"代位與分擔有近似目標，就是兩者均：",o:["要求有兩份以上的保單","要求不同保險單保障相同權益","力求確保由疏忽一方賠償損失","確保被保險人最後不會收取超過彌償的金額"],e:"代位與分擔的共同目標均是確保被保險人最終不會收取超過彌償的金額，防止超額獲利。"}},
{p:1,ch:"保险原则",q:"代位权可以透过以下哪种/哪些方式产生?",o:["侵权法上","合约上","法规上","以上各项皆是"],a:3,e:"代位权可经侵权法、合约或法规等途径产生，故各项皆正确。",src:1,tw:{ch:"保險原則",q:"代位權可以透過以下哪種/哪些方式產生?",o:["侵權法上","合約上","法規上","以上各項皆是"],e:"代位權可經侵權法、合約或法規等途徑產生，故各項皆正確。"}},
{p:1,ch:"保险原则",q:"代位权如何出现? i 在侵权法上 ii 在合约上 iii 在法规下 iv 在损余中",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"代位权可在侵权法、合约及法规下产生，亦可因损余处理而产生，故四项均正确。",src:1,tw:{ch:"保險原則",q:"代位權如何出現？ i 在侵權法上 ii 在合約上 iii 在法規下 iv 在損餘中",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"代位權可在侵權法、合約及法規下產生，亦可因損餘處理而產生，故四項均正確。"}},
{p:1,ch:"保险原则",q:"代位权的出现,大部份由于第三者疏忽地对受保财产造成损害,而且该财产 的保险人承继了向疏忽的人行使法律权利,技术上,这意味着代位权来自:",o:["侵权法","法规","分担","因转承责任"],a:0,e:"因第三者疏忽损害受保财产，保险人承继被保险人向疏忽者行使的权利，属侵权法上的代位权。",src:1,tw:{ch:"保險原則",q:"代位權的出現,大部份由於第三者疏忽地對受保財產造成損害,而且該財產 的保險人承繼了向疏忽的人行使法律權利,技術上,這意味着代位權來自:",o:["侵權法","法規","分擔","因轉承責任"],e:"因第三者疏忽損害受保財產，保險人承繼被保險人向疏忽者行使的權利，屬侵權法上的代位權。"}},
{p:1,ch:"保险原则",q:"以下哪一项保险产品类别不适用于弥偿的定义上:",o:["汽车意外保险","家居保险","火险","人身意外保险"],a:3,e:"人身意外保险给付定额，不受弥偿定义约束，故该项不适用弥偿。",src:1,tw:{ch:"保險原則",q:"以下哪一項保險產品類別不適用於彌償的定義上：",o:["汽車意外保險","家居保險","火險","人身意外保險"],e:"人身意外保險給付定額，不受彌償定義約束，故該項不適用彌償。"}},
{p:1,ch:"保险原则",q:"以下哪三项存在可保权益? i 配偶 ii 债权人 iii 欠债人 iv 年届15岁的子女",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, iii, iv"],a:3,e:"配偶、债权人对债务人及年届15岁的子女均存在可保权益；欠债人对债权人无反向权益，故 i、ii、iv 正确。",src:1,tw:{ch:"保險原則",q:"以下哪三項存在可保權益？ i 配偶 ii 債權人 iii 欠債人 iv 年屆15歲的子女",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, iii, iv"],e:"配偶、債權人對債務人及年屆15歲的子女均存在可保權益；欠債人對債權人無反向權益，故 i、ii、iv 正確。"}},
{p:1,ch:"保险原则",q:"以下哪三项对不属于自己的财产具有可保权益? i 受托人(以信托形式托管财产) ii 户主的儿子(母亲的房屋) iii 遗产执行人(死者遗下的物业) iv 一家银行借钱给按揭人(按揭建筑物)",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, iii, iv"],a:3,e:"受托人、遗产执行人及银行（对按揭物业）对并非属于自己的财产均具可保权益；户主儿子对其母亲的房屋并无自动权益，故 i、iii、iv 正确。",src:1,tw:{ch:"保險原則",q:"以下哪三項對不屬於自己的財產具有可保權益？ i 受託人(以信託形式托管財產) ii 戶主的兒子(母親的房屋) iii 遺產執行人(死者遺下的物業) iv 一家銀行借錢給按揭人(按揭建築物)",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, iii, iv"],e:"受託人、遺產執行人及銀行（對按揭物業）對並非屬於自己的財產均具可保權益；户主兒子對其母親的房屋並無自動權益，故 i、iii、iv 正確。"}},
{p:1,ch:"保险原则",q:"以下哪三项属于违反最高诚信: i 真正地忘记了以往的一项被爆窃事件(盗窃险) ii 畜意地隐瞒一项不良的索偿纪录(火险) iii 有意地提供良好的健康证明,但明知事实是相反的(人寿保险) iv 没有披露一项自己完全不知道的健康情况(人身意外保险)",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"忘记披露曾遭爆窃仍属未披露重要事实，蓄意隐瞒不良索偿及提供明知不实的健康证明均违反最高诚信；完全不知的健康情况无从披露，故 i、ii、iii 正确。",src:1,tw:{ch:"保險原則",q:"以下哪三項屬於違反最高誠信： i 真正地忘記了以往的一項被爆竊事件(盜竊險) ii 畜意地隱瞞一項不良的索償紀錄(火險) iii 有意地提供良好的健康證明，但明知事實是相反的(人壽保險) iv 沒有披露一項自己完全不知道的健康情況(人身意外保險)",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"忘記披露曾遭爆竊仍屬未披露重要事實，蓄意隱瞞不良索償及提供明知不實的健康證明均違反最高誠信；完全不知的健康情況無從披露，故 i、ii、iii 正確。"}},
{p:1,ch:"保险原则",q:"以下哪三项形容委付是正确的? i 委付是将损余交付保险人的行为 ii 出售损余后的收入归于保险人 iii 适用于任何类型保单(人寿及一般保险) iv 非水险保单条件通常剔除委付",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"委付是把损余交付保险人、出售损余收益归保险人的行为，非水险通常剔除委付，故 i、ii、iv 正确；委付并不适用于任何类型保单。",src:1,tw:{ch:"保險原則",q:"以下哪三項形容委付是正確的？ i 委付是將損餘交付保險人的行為 ii 出售損餘後的收入歸於保險人 iii 適用於任何類型保單(人壽及一般保險) iv 非水險保單條件通常剔除委付",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"委付是把損餘交付保險人、出售損餘收益歸保險人的行為，非水險通常剔除委付，故 i、ii、iv 正確；委付並不適用於任何類型保單。"}},
{p:1,ch:"保险原则",q:"以下哪三项是被视为违反最高诚信﹕ i 欺诈性不披露 ii 欺诈性声明 iii 欺诈性失实陈述 iv 非欺诈性失实陈述",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"违反最高诚信主要表现为欺诈性或非欺诈性的不披露与失实陈述，故 i、iii、iv 属之；「欺诈性声明」并非材料采用的分类用语。",src:1,tw:{ch:"保險原則",q:"以下哪三項是被視為違反最高誠信﹕ i 欺詐性不披露 ii 欺詐性聲明 iii 欺詐性失實陳述 iv 非欺詐性失實陳述",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"違反最高誠信主要表現為欺詐性或非欺詐性的不披露與失實陳述，故 i、iii、iv 屬之；「欺詐性聲明」並非材料採用的分類用語。"}},
{p:1,ch:"保险原则",q:"以下哪两项保险原则有相当密切的关系: i 弥偿 ii 分担 iii 近因 iv 最高诚信",o:["i, ii","ii,iii","iii, iv","i, iii"],a:0,e:"分担是弥偿原则的直接引申，二者关系密切，共同防止被保险人超额获赔，故 i、ii 正确。",src:1,tw:{ch:"保險原則",q:"以下哪兩項保險原則有相當密切的關係： i 彌償 ii 分擔 iii 近因 iv 最高誠信",o:["i, ii","ii,iii","iii, iv","i, iii"],e:"分擔是彌償原則的直接引申，二者關係密切，共同防止被保險人超額獲賠，故 i、ii 正確。"}},
{p:1,ch:"保险原则",q:"以下哪个保险原则是与弥偿无直接或间接相关联?",o:["代位","分担","可保权益","复原财产"],a:2,e:"代位、分担与复原财产均是弥偿原则的体现或引申；可保权益是独立的订约前提，并非弥偿原则的引申内容，故该项与弥偿无直接关联。",src:1,tw:{ch:"保險原則",q:"以下哪個保險原則是與彌償無直接或間接相關聯?",o:["代位","分擔","可保權益","復原財產"],e:"代位、分擔與復原財產均是彌償原則的體現或引申；可保權益是獨立的訂約前提，並非彌償原則的引申內容，故該項與彌償無直接關聯。"}},
{p:1,ch:"保险原则",q:"以下哪个是分担的正确描述:",o:["适用于人寿保单","适用于利益保单","适用于非弥偿保单","适用于弥偿保单"],a:3,e:"分担只适用于弥偿保单，用以防止同一损失被多重全额获赔，故该项正确。",src:1,tw:{ch:"保險原則",q:"以下哪個是分擔的正確描述:",o:["適用於人壽保單","適用於利益保單","適用於非彌償保單","適用於彌償保單"],e:"分擔只適用於彌償保單，用以防止同一損失被多重全額獲賠，故該項正確。"}},
{p:1,ch:"保险原则",q:"以下哪二项保险原理有相当密切的关系? i 弥偿 ii 分担 iii 近因 iv 最高诚信",o:["i及 ii","ii及 iii","iii及 iv","i及 iii"],a:0,e:"弥偿与分担关系密切，分担为确保弥偿不超额而设，故 i、ii 正确。",src:1,tw:{ch:"保險原則",q:"以下哪二項保險原理有相當密切的關係？ i 彌償 ii 分擔 iii 近因 iv 最高誠信",o:["i及 ii","ii及 iii","iii及 iv","i及 iii"],e:"彌償與分擔關係密切，分擔為確保彌償不超額而設，故 i、ii 正確。"}},
{p:1,ch:"保险原则",q:"以下哪些不大可能应用弥偿原则中的分担条件?",o:["保险人的责任限于损失的某个比率份额","保单中有更具体的物件正在受保","放弃分担条件,全数赔偿","有另一张弥偿保单,可撤销保单赔偿"],a:3,e:"若另有一张弥偿保单可「撤销」（退让）本保单的赔偿责任，则不发生分担而由一单独自承担，故该项不大可能应用分担条件。",src:1,tw:{ch:"保險原則",q:"以下哪些不大可能應用彌償原則中的分擔條件?",o:["保險人的責任限於損失的某個比率份額","保單中有更具體的物件正在受保","放棄分擔條件，全數賠償","有另一張彌償保單，可撤銷保單賠償"],e:"若另有一張彌償保單可「撤銷」（退讓）本保單的賠償責任，則不發生分擔而由一單獨自承擔，故該項不大可能應用分擔條件。"}},
{p:1,ch:"保险原则",q:"以下哪些不是属于合法权利保险:",o:["车辆损毁,需要租车备用 (租车保险)","住客不小心令住屋着火 (租金保险)","工厂机器损坏,影响盈利 (利润损失保险)","为水上货物提供保障 (水险单)"],a:3,e:"可保权益可在合法权益受侵害或预期收入受损时产生，租车保障、租金损失及利润损失保险均属此类；为水上货物提供保障的水险单，是基于对货物本身的财产权益，并非因合法权利受侵害而产生的权益保险，故不属于合法权利保险。",src:1,tw:{ch:"保險原則",q:"以下哪些不是屬於合法權利保險:",o:["車輛損毀,需要租車備用 (租車保險)","住客不小心令住屋着火 (租金保險)","工廠機器損壞,影響盈利 (利潤損失保險)","為水上貨物提供保障 (水險單)"],e:"可保權益可在合法權益受侵害或預期收入受損時產生，租車保障、租金損失及利潤損失保險均屬此類；為水上貨物提供保障的水險單，是基於對貨物本身的財產權益，並非因合法權利受侵害而產生的權益保險，故不屬於合法權利保險。"}},
{p:1,ch:"保险原则",q:"以下哪些不是弥偿原则的定义:",o:["禁止使用于人寿保单,保险人可使保单无效","适用于非人寿保单","提供精确的财务补偿","人寿及人身意外保单不受弥偿原则约束"],a:0,e:"弥偿原则旨在对被保险人的实际损失提供精确财务补偿，一般适用于非人寿保险，而人寿及人身意外等利益保单不受其约束；说「禁止使用于人寿保单、保险人可使保单无效」表述错误，人寿保单不适用弥偿并非因此无效，故不选。",src:1,tw:{ch:"保險原則",q:"以下哪些不是彌償原則的定義:",o:["禁止使用於人壽保單，保險人可使保單無效","適用於非人壽保單","提供精確的財務補償","人壽及人身意外保單不受彌償原則約束"],e:"彌償原則旨在對被保險人的實際損失提供精確財務補償，一般適用於非人壽保險，而人壽及人身意外等利益保單不受其約束；說「禁止使用於人壽保單、保險人可使保單無效」表述錯誤，人壽保單不適用彌償並非因此無效，故不選。"}},
{p:1,ch:"保险原则",q:"以下哪些或哪项是「一般诚信」正确的描述?",o:["全面揭露的责任","不说谎的消极责任","提供重要事实的积极责任","以上皆否"],a:1,e:"一般诚信只是要求当事人不作出虚假陈述的消极责任，即不说谎；全面揭露、主动提供重要事实属最高诚信的积极披露义务，非一般诚信，故正确答案为「不说谎的消极责任」。",src:1,tw:{ch:"保險原則",q:"以下哪些或哪項是「一般誠信」正確的描述？",o:["全面揭露的責任","不說謊的消極責任","提供重要事實的積極責任","以上皆否"],e:"一般誠信只是要求當事人不作出虛假陳述的消極責任，即不說謊；全面揭露、主動提供重要事實屬最高誠信的積極披露義務，非一般誠信，故正確答案為「不說謊的消極責任」。"}},
{p:1,ch:"保险原则",q:"以下哪些描述一般诚信是正确:",o:["可能是真也可能是假的,所以不可靠","所有事情都要披露,不论是否有问及","有责任担保所有披露的资料一定完全真实","忠实并确保所有陈述是实质上真实"],a:3,e:"一般诚信（非保险合约）要求当事人忠实并确保其所作陈述在实质上是真实的，而非保证绝对完全真实，也没有主动披露所有事实的义务；其他选项混淆了一般诚信与最高诚信，故不选。",src:1,tw:{ch:"保險原則",q:"以下哪些描述一般誠信是正確:",o:["可能是真也可能是假的，所以不可靠","所有事情都要披露，不論是否有問及","有責任擔保所有披露的資料一定完全真實","忠實並確保所有陳述是實質上真實"],e:"一般誠信（非保險合約）要求當事人忠實並確保其所作陳述在實質上是真實的，而非保證絕對完全真實，也沒有主動披露所有事實的義務；其他選項混淆了一般誠信與最高誠信，故不選。"}},
{p:1,ch:"保险原则",q:"以下哪些是一般诚信的不正确描述?",o:["与常识有关的事实","必然是重要事实","可以在商业的合约","永不用于保险合约"],a:1,e:"一般诚信适用于一般商业合约，仅要求不作虚假陈述，与常识有关的事实无需主动披露，也未必属重要事实；认为其「必然是重要事实」不正确，故答案选此项。",src:1,tw:{ch:"保險原則",q:"以下哪些是一般誠信的不正確描述?",o:["與常識有關的事實","必然是重要事實","可以在商業的合約","永不用於保險合約"],e:"一般誠信適用於一般商業合約，僅要求不作虛假陳述，與常識有關的事實無需主動披露，也未必屬重要事實；認為其「必然是重要事實」不正確，故答案選此項。"}},
{p:1,ch:"保险原则",q:"以下哪些是属于违反最高诚信: i 欺诈性失实陈述 ii 非欺诈性失实陈述 iii 欺诈性不披露 iv 非欺诈性不披露",o:["ii, iv","i, iii","i, ii, iii","i, ii, iii, iv"],a:3,e:"最高诚信要求如实披露所有重要事实，无论欺诈性还是非欺诈性的失实陈述或不披露，均构成对最高诚信义务的违反，故四项全部正确。",src:1,tw:{ch:"保險原則",q:"以下哪些是屬於違反最高誠信: i 欺詐性失實陳述 ii 非欺詐性失實陳述 iii 欺詐性不披露 iv 非欺詐性不披露",o:["ii, iv","i, iii","i, ii, iii","i, ii, iii, iv"],e:"最高誠信要求如實披露所有重要事實，無論欺詐性還是非欺詐性的失實陳述或不披露，均構成對最高誠信義務的違反，故四項全部正確。"}},
{p:1,ch:"保险原则",q:"以下哪些是风险类别: i 除外危险 ii 受保危险 iii 可保危险 iv 不保危险",o:["i, ii","ii, iii","i, ii, iv","iii, iv"],a:2,e:"保险中的危险依保障划分三类：受保危险、不保危险及除外危险；「可保危险」并非标准分类用语，故正确组合为 i、ii、iv。",src:1,tw:{ch:"保險原則",q:"以下哪些是風險類別: i 除外危險 ii 受保危險 iii 可保危險 iv 不保危險",o:["i, ii","ii, iii","i, ii, iv","iii, iv"],e:"保險中的危險依保障劃分三類：受保危險、不保危險及除外危險；「可保危險」並非標準分類用語，故正確組合為 i、ii、iv。"}},
{p:1,ch:"保险原则",q:"以下哪些财产可投买保险? i 从偷窃中得来的财产 ii 以持有人名义投买的财产 iii 信托人保管的财产 iv 遗嘱执行人保管的财产",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],a:1,e:"从偷窃得来的财产属于非法占有，并不产生法律认可的权益，故不可投保；以本人名义持有、信托人及遗嘱执行人保管的财产均存在法律认可的财产权益，可投保，故正确组合为 ii、iii、iv。",src:1,tw:{ch:"保險原則",q:"以下哪些財產可投買保險？ i 從偷竊中得來的財產 ii 以持有人名義投買的財產 iii 信託人保管的財產 iv 遺囑執行人保管的財產",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"從偷竊得來的財產屬於非法佔有，並不產生法律認可的權益，故不可投保；以本人名義持有、信託人及遺囑執行人保管的財產均存在法律認可的財產權益，可投保，故正確組合為 ii、iii、iv。"}},
{p:1,ch:"保险原则",q:"以下哪种情况不会阻止被保险人从弥偿保单中获得赔偿?",o:["保单起赔额","保单限额","死亡时缺乏可保权益","保单起陪期"],a:2,e:"弥偿保单只要求在损失发生时存在可保权益，因此死亡时缺乏可保权益不会影响赔偿；而起赔额、保单限额及起赔期均会限制或延后赔偿，故不选。",src:1,tw:{ch:"保險原則",q:"以下哪種情況不會阻止被保險人從彌償保單中獲得賠償？",o:["保單起賠額","保單限額","死亡時缺乏可保權益","保單起陪期"],e:"彌償保單隻要求在損失發生時存在可保權益，因此死亡時缺乏可保權益不會影響賠償；而起賠額、保單限額及起賠期均會限制或延後賠償，故不選。"}},
{p:1,ch:"保险原则",q:"以下哪项/哪几项属于提供弥偿的方法?",o:["恢复原状","更换","现金支付","以上各项皆是"],a:3,e:"提供弥偿的方式包括现金支付、修理或恢复原状、更换等，保险人视情况选择最适当的方式；三者均为常见弥偿方法，故「以上各项皆是」。",src:1,tw:{ch:"保險原則",q:"以下哪項/哪幾項屬於提供彌償的方法？",o:["恢復原狀","更換","現金支付","以上各項皆是"],e:"提供彌償的方式包括現金支付、修理或恢復原狀、更換等，保險人視情況選擇最適當的方式；三者均為常見彌償方法，故「以上各項皆是」。"}},
{p:1,ch:"保险原则",q:"以下哪项不属于对最高诚信的不正碓描述﹖",o:["在一般保险中,通常会降低最高诚信的责任","最高诚信只适用于保单条款中所订明的事项","最高诚信只要求就发问的问题提供真实的答案","以上各项皆不正确"],a:3,e:"最高诚信要求主动披露所有重要事实，不因一般保险而降低，也不仅限于保单条款订明事项或已发问的问题；三句描述均不正确，故「以上各项皆不正确」。",src:1,tw:{ch:"保險原則",q:"以下哪項不屬於對最高誠信的不正碓描述﹖",o:["在一般保險中，通常會降低最高誠信的責任","最高誠信只適用於保單條款中所訂明的事項","最高誠信只要求就發問的問題提供真實的答案","以上各項皆不正確"],e:"最高誠信要求主動披露所有重要事實，不因一般保險而降低，也不僅限於保單條款訂明事項或已發問的問題；三句描述均不正確，故「以上各項皆不正確」。"}},
{p:1,ch:"保险原则",q:"以下哪项与近因有关?",o:["由受保危险引起,可获得赔偿","如非单一成因引起,危险必须既不是不保危险, 也不是除外危险,便可得到保障","若保障是由除外危险引起,一般会令索偿失效","以上各项皆正确"],a:3,e:"近因原则下，受保危险引起的损失可获赔偿；多个成因时须既非除外亦非不保危险方可获保；除外危险引起的损失通常令索偿失效，三句均正确。",src:1,tw:{ch:"保險原則",q:"以下哪項與近因有關？",o:["由受保危險引起，可獲得賠償","如非單一成因引起，危險必須既不是不保危險， 也不是除外危險，便可得到保障","若保障是由除外危險引起，一般會令索償失效","以上各項皆正確"],e:"近因原則下，受保危險引起的損失可獲賠償；多個成因時須既非除外亦非不保危險方可獲保；除外危險引起的損失通常令索償失效，三句均正確。"}},
{p:1,ch:"保险原则",q:"以下哪项事项毋须要披露?",o:["存在的战争状况","预期保险人应已知悉的资料","可能改善承保人评估有关风险的事实","以上各项都毋须披露"],a:3,e:"投保人毋须披露保险人已知或应知的资料、属常识的事实，以及能改善风险的事实；存在的战争状况属常识、预期保险人应知悉及改善风险的事实均无需披露，故三项皆是。",src:1,tw:{ch:"保險原則",q:"以下哪項事項毋須要披露？",o:["存在的戰爭狀況","預期保險人應已知悉的資料","可能改善承保人評估有關風險的事實","以上各項都毋須披露"],e:"投保人毋須披露保險人已知或應知的資料、屬常識的事實，以及能改善風險的事實；存在的戰爭狀況屬常識、預期保險人應知悉及改善風險的事實均無需披露，故三項皆是。"}},
{p:1,ch:"保险原则",q:"以下哪项保险只有在合约办妥时(保单开始)才需要可保权益?",o:["火险","人寿保险","水险","航空保险"],a:1,e:"人寿保险只需在保单订约时存在可保权益，其后权益即使消失保单仍有效；火险、水险及航空等弥偿保险则要求在损失发生时具备可保权益，故答案为人寿保险。",src:1,tw:{ch:"保險原則",q:"以下哪項保險只有在合約辦妥時(保單開始)才需要可保權益?",o:["火險","人壽保險","水險","航空保險"],e:"人壽保險只需在保單訂約時存在可保權益，其後權益即使消失保單仍有效；火險、水險及航空等彌償保險則要求在損失發生時具備可保權益，故答案為人壽保險。"}},
{p:1,ch:"保险原则",q:"以下哪项发生时不会延伸或恢复履行最高诚信?",o:["保单续保时","索偿有问题时","合约条款更改时","以上各项都是"],a:1,e:"最高诚信在保单续保及合约条款更改时须重新履行；索偿出现问题属另一范畴，并不因此延伸或恢复最高诚信义务，故答案选「索偿有问题时」。",src:1,tw:{ch:"保險原則",q:"以下哪項發生時不會延伸或恢復履行最高誠信？",o:["保單續保時","索償有問題時","合約條款更改時","以上各項都是"],e:"最高誠信在保單續保及合約條款更改時須重新履行；索償出現問題屬另一範疇，並不因此延伸或恢復最高誠信義務，故答案選「索償有問題時」。"}},
{p:1,ch:"保险原则",q:"以下哪项存在合法权利上的可保权益,而非人身上、财产上及责任上?",o:["业主为自己建筑物投保","业主为未来的租金购买保险","债权人就欠债人购买保险","就应支付可能受伤的职员,而购买雇员补偿保险"],a:1,e:"合法权利上的可保权益源于权益受侵害或预期收入损失的风险，业主为未来租金投保即属此类；为自己建筑物投保属财产权益，债权人对债务人、雇员补偿则分别属人身及责任权益，故不选。",src:1,tw:{ch:"保險原則",q:"以下哪項存在合法權利上的可保權益，而非人身上、財產上及責任上？",o:["業主為自己建築物投保","業主為未來的租金購買保險","債權人就欠債人購買保險","就應支付可能受傷的職員，而購買僱員補償保險"],e:"合法權利上的可保權益源於權益受侵害或預期收入損失的風險，業主為未來租金投保即屬此類；為自己建築物投保屬財產權益，債權人對債務人、僱員補償則分別屬人身及責任權益，故不選。"}},
{p:1,ch:"保险原则",q:"以下哪项存在法律责任上的可保权益,而非人身上、财产上及责任上?",o:["业主为自己建筑物投保","酒楼经营者就禽流感爆发产生的利润损失购买保险","债权人就欠债人购买保险","就应支付可能受伤的职员而购买的雇员补偿保险"],a:1,e:"酒楼经营者因禽流感爆发而产生的利润损失，属合法权利上的可保权益（预期收益受损而投保）；为自己建筑物投保属财产权益、债权人对债务人属人身权益、雇员补偿属责任权益，均与题意不符。",src:1,tw:{ch:"保險原則",q:"以下哪項存在法律責任上的可保權益，而非人身上、財產上及責任上？",o:["業主為自己建築物投保","酒樓經營者就禽流感爆發產生的利潤損失購買保險","債權人就欠債人購買保險","就應支付可能受傷的職員而購買的僱員補償保險"],e:"酒樓經營者因禽流感爆發而產生的利潤損失，屬合法權利上的可保權益（預期收益受損而投保）；為自己建築物投保屬財產權益、債權人對債務人屬人身權益、僱員補償屬責任權益，均與題意不符。"}},
{p:1,ch:"保险原则",q:"以下哪项对于受保危险,不保危险及除外危险的描述是正确的?",o:["因受保危险所引致的损失不可得到保障","因除外危险所引致的损失可得到保障","因受保危险直接产生的不保危险所导致的损失可得到保障","因受保危险直接产生的不保危险所导致的损失不可得到保障"],a:2,e:"按近因原则，因受保危险直接产生的不保危险所导致的损失仍可获保障（如火灾为受保危险，灭火用水造成的损失）；其余选项把受保危险说成不获保障、或宣称除外危险可获保障，均错误。",src:1,tw:{ch:"保險原則",q:"以下哪項對於受保危險，不保危險及除外危險的描述是正確的？",o:["因受保危險所引致的損失不可得到保障","因除外危險所引致的損失可得到保障","因受保危險直接產生的不保危險所導致的損失可得到保障","因受保危險直接產生的不保危險所導致的損失不可得到保障"],e:"按近因原則，因受保危險直接產生的不保危險所導致的損失仍可獲保障（如火災為受保危險，滅火用水造成的損失）；其餘選項把受保危險說成不獲保障、或宣稱除外危險可獲保障，均錯誤。"}},
{p:1,ch:"保险原则",q:"以下哪项对于财产上的可保权益并非必要的?",o:["与该财产必须有法律认可关系","必须对该财产有拥有权","购买的保险必须与该财产有关","与该财产必须有财务上的关系"],a:1,e:"财产上的可保权益只要求与财产存在法律认可及财务上的关系，并不要求拥有所有权，受托人、承按人、租客等均有可保权益；法律认可关系、保险与财产相关及财务关系均为必要，故不拥有权并非必要。",src:1,tw:{ch:"保險原則",q:"以下哪項對於財產上的可保權益並非必要的？",o:["與該財產必須有法律認可關係","必須對該財產有擁有權","購買的保險必須與該財產有關","與該財產必須有財務上的關係"],e:"財產上的可保權益只要求與財產存在法律認可及財務上的關係，並不要求擁有所有權，受託人、承按人、租客等均有可保權益；法律認可關係、保險與財產相關及財務關係均為必要，故不擁有權並非必要。"}},
{p:1,ch:"保险原则",q:"以下哪项对保单起赔额或免赔额的描述是正确的? i 两者的原意均是减少琐碎的索偿 ii 两种保单意味着相同的运作方式 iii 保单起赔额之保单会赔偿全数损失,如损失超过起赔额 iv 对少于起赔额的损失是可受保的保证",o:["i及ii","i及iii","iii及iv","i及iv"],a:1,e:"免赔额与起赔额的原意均在于减少琐碎索偿；起赔额保单在损失超过起赔额时赔偿全额损失。两者运作方式不同，且低于起赔额的损失不获赔，故只有 i、iii 正确。",src:1,tw:{ch:"保險原則",q:"以下哪項對保單起賠額或免賠額的描述是正確的? i 兩者的原意均是減少瑣碎的索償 ii 兩種保單意味着相同的運作方式 iii 保單起賠額之保單會賠償全數損失,如損失超過起賠額 iv 對少於起賠額的損失是可受保的保證",o:["i及ii","i及iii","iii及iv","i及iv"],e:"免賠額與起賠額的原意均在於減少瑣碎索償；起賠額保單在損失超過起賠額時賠償全額損失。兩者運作方式不同，且低於起賠額的損失不獲賠，故只有 i、iii 正確。"}},
{p:1,ch:"保险原则",q:"以下哪项对保险术语average之含义的理解是不正确的?",o:["在火险中,它是指不足额的保险","在海上货物保险中,它的含义与火险完全不同","对不足额保险的处理,适用于各类的保险","以上各项皆不正确"],a:2,e:"「average」在火险中指比例分摊（不足额保险），在海上货物保险则指部分损失或海损，含义完全不同；「对不足额保险的处理适用于各类保险」这一说法不正确，故答案为该项。",src:1,tw:{ch:"保險原則",q:"以下哪項對保險術語average之含義的理解是不正確的？",o:["在火險中，它是指不足額的保險","在海上貨物保險中，它的含義與火險完全不同","對不足額保險的處理，適用於各類的保險","以上各項皆不正確"],e:"「average」在火險中指比例分攤（不足額保險），在海上貨物保險則指部分損失或海損，含義完全不同；「對不足額保險的處理適用於各類保險」這一說法不正確，故答案為該項。"}},
{p:1,ch:"保险原则",q:"以下哪项对分担条件描述是正确的?",o:["保险人可在保单指明分担条款不适用","保险人可在保单上指明不会寻求分担","如有分担出现该份合约便会无效","保险人可限制其责任只承担指定比率的分担责任"],a:3,e:"分担原则下，保险人可在保单中限制其责任，只承担指定比率的分担责任；保险人不能单方面排除分担原则，分担的出现也不会令合约失效，故答案为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項對分擔條件描述是正確的？",o:["保險人可在保單指明分擔條款不適用","保險人可在保單上指明不會尋求分擔","如有分擔出現該份合約便會無效","保險人可限制其責任只承擔指定比率的分擔責任"],e:"分擔原則下，保險人可在保單中限制其責任，只承擔指定比率的分擔責任；保險人不能單方面排除分擔原則，分擔的出現也不會令合約失效，故答案為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项对委付的描述是正确的?",o:["大多数出现在水险中","于火险单中通过剔除委付","将损余交付保险人","以上所有各项"],a:3,e:"委付多出现于水险中，指被保险人将损余交付保险人以换取全损赔偿，火险保单一般以剔除委付条款处理；三项描述均正确，故「以上所有各项」。",src:1,tw:{ch:"保險原則",q:"以下哪項對委付的描述是正確的？",o:["大多數出現在水險中","於火險單中通過剔除委付","將損餘交付保險人","以上所有各項"],e:"委付多出現於水險中，指被保險人將損餘交付保險人以換取全損賠償，火險保單一般以剔除委付條款處理；三項描述均正確，故「以上所有各項」。"}},
{p:1,ch:"保险原则",q:"以下哪项对转让的陈述是正确的? i 人寿保险可以不经保险人同意自由转让 ii 海上货物保险可以不经保险人同意自由转让 iii 商业「全险」保单不可以没有保险人同意便转让 iv 人寿保险不可以没有保险人同意便转让",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"人寿保险及海上货物保险的保单权益可无须保险人同意而自由转让，商业「全险」保单则须经保险人同意方可转让；选项 iv 谓人寿保险必须获得同意属错误，故正确组合为 i、ii、iii。",src:1,tw:{ch:"保險原則",q:"以下哪項對轉讓的陳述是正確的？ i 人壽保險可以不經保險人同意自由轉讓 ii 海上貨物保險可以不經保險人同意自由轉讓 iii 商業「全險」保單不可以沒有保險人同意便轉讓 iv 人壽保險不可以沒有保險人同意便轉讓",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"人壽保險及海上貨物保險的保單權益可無須保險人同意而自由轉讓，商業「全險」保單則須經保險人同意方可轉讓；選項 iv 謂人壽保險必須獲得同意屬錯誤，故正確組合為 i、ii、iii。"}},
{p:1,ch:"保险原则",q:"以下哪项属于最方便提供弥偿的方法?",o:["恢复原状","更换","现金支付","修理"],a:2,e:"现金支付是提供弥偿最直接、最方便的方式；恢复原状、修理及更换需考虑可行性与耗时，故最方便的方法为现金支付。",src:1,tw:{ch:"保險原則",q:"以下哪項屬於最方便提供彌償的方法？",o:["恢復原狀","更換","現金支付","修理"],e:"現金支付是提供彌償最直接、最方便的方式；恢復原狀、修理及更換需考慮可行性與耗時，故最方便的方法為現金支付。"}},
{p:1,ch:"保险原则",q:"以下哪项并不构成可保权益?",o:["个人自身","个人的叔父","15岁的子女","债务人"],a:1,e:"就人身保险而言，个人对自己、配偶及未成年子女天然存在可保权益，债权人对债务人也具可保权益；叔父一般不在可保权益范围内，故答案为其叔父。",src:1,tw:{ch:"保險原則",q:"以下哪項並不構成可保權益？",o:["個人自身","個人的叔父","15歲的子女","債務人"],e:"就人身保險而言，個人對自己、配偶及未成年子女天然存在可保權益，債權人對債務人也具可保權益；叔父一般不在可保權益範圍內，故答案為其叔父。"}},
{p:1,ch:"保险原则",q:"以下哪项弥偿的索偿,最应以维修方式提供?",o:["玻璃碎裂","一座建筑物完全倒下","一项汽车损坏,非全损","以上各项皆是"],a:2,e:"汽车非全损的损坏，最适宜以维修方式恢复至损失前状况；玻璃碎裂通常以更换处理，建筑物完全倒下则须重建，故以维修方式提供弥偿者为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項彌償的索償，最應以維修方式提供？",o:["玻璃碎裂","一座建築物完全倒下","一項汽車損壞，非全損","以上各項皆是"],e:"汽車非全損的損壞，最適宜以維修方式恢復至損失前狀況；玻璃碎裂通常以更換處理，建築物完全倒下則須重建，故以維修方式提供彌償者為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项情况在没有披露的情形下会被视为违反最高诚信?",o:["过往遭到盗窃的记录(盗窃险)","受保地方战争情况(水险)","发泡胶的高度可燃性(火险)","受保范围的防火花洒装置(火险)"],a:0,e:"过往盗窃纪录属影响承保人判断的重要事实，投保盗窃险时必须披露，隐瞒即违反最高诚信；战争情况与发泡胶可燃性属常识或保险人应知悉，防火洒水装置属改善风险的事实，均毋须披露。",src:1,tw:{ch:"保險原則",q:"以下哪項情況在沒有披露的情形下會被視為違反最高誠信？",o:["過往遭到盜竊的記錄(盜竊險)","受保地方戰爭情況(水險)","發泡膠的高度可燃性(火險)","受保範圍的防火花灑裝置(火險)"],e:"過往盜竊紀錄屬影響承保人判斷的重要事實，投保盜竊險時必須披露，隱瞞即違反最高誠信；戰爭情況與發泡膠可燃性屬常識或保險人應知悉，防火灑水裝置屬改善風險的事實，均毋須披露。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些事实,关于盗窃保险合约是视为重要但无须披露的事实?",o:["盗窃损失纪录","提高风险的事实","在所保处已安装一套防盗系统","只有 A & C 是无须披露的事实"],a:2,e:"已安装防盗系统属改善风险的事实，此类有利资料毋须披露；而盗窃损失纪录及提高风险的事实属重要事实，必须主动披露，故只有该安装防盗系统的事实毋须披露。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些事實，關於盜竊保險合約是視為重要但無須披露的事實？",o:["盜竊損失紀錄","提高風險的事實","在所保處已安裝一套防盜系統","只有 A & C 是無須披露的事實"],e:"已安裝防盜系統屬改善風險的事實，此類有利資料毋須披露；而盜竊損失紀錄及提高風險的事實屬重要事實，必須主動披露，故只有該安裝防盜系統的事實毋須披露。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些人士,尽管不是绝对拥有人,但仍对某项财产具有可保权益 ?",o:["一名拥有一幢建筑物的男子的太太","一项私人信托的信托人,对该项有关信托财产","一名获准使用一名朋友的相机的人士","以上各项皆有可保权益"],a:1,e:"信托人虽非绝对拥有人，但对信托财产负有保管责任并拥有法定权益，故具有可保权益；业主的妻子对丈夫的建筑物、获准使用他人相机者一般缺乏法律认可的财务权益，故不选。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些人士，儘管不是絕對擁有人，但仍對某項財產具有可保權益 ？",o:["一名擁有一幢建築物的男子的太太","一項私人信託的信託人，對該項有關信託財產","一名獲准使用一名朋友的相機的人士","以上各項皆有可保權益"],e:"信託人雖非絕對擁有人，但對信託財產負有保管責任並擁有法定權益，故具有可保權益；業主的妻子對丈夫的建築物、獲准使用他人相機者一般缺乏法律認可的財務權益，故不選。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些保险不可以在没有获得保险人的同意下转让﹖",o:["海上货物保险","游艇保险","人寿保险","以上 (b)和(c)项"],a:1,e:"海上货物保险与人寿保险的权益可无须保险人同意而自由转让；游艇保险涉及对特定被保险人的风险评估，转让须获保险人同意，故答案为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些保險不可以在沒有獲得保險人的同意下轉讓﹖",o:["海上貨物保險","遊艇保險","人壽保險","以上 (b)和(c)項"],e:"海上貨物保險與人壽保險的權益可無須保險人同意而自由轉讓；遊艇保險涉及對特定被保險人的風險評估，轉讓須獲保險人同意，故答案為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些保险是以修理损失为弥偿方式?",o:["玻璃保险","公众责任保险","非全险汽车索偿","以上所有皆是"],a:2,e:"非全损的汽车索偿以维修方式提供弥偿最合适，可恢复至损失前状况；玻璃保险多采用更换，公众责任一般以现金赔偿，故只有非全险汽车索偿以修理为弥偿方式。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些保險是以修理損失為彌償方式？",o:["玻璃保險","公眾責任保險","非全險汽車索償","以上所有皆是"],e:"非全損的汽車索償以維修方式提供彌償最合適，可恢復至損失前狀況；玻璃保險多采用更換，公眾責任一般以現金賠償，故只有非全險汽車索償以修理為彌償方式。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些保险转让不可以在没有获得保险人的同意下转让﹖",o:["运费保险","海上货物保险","人身保险","以上 (a)和(c)项"],a:0,e:"海上货物保险及人身保险的保单可无须保险人同意而自由转让；运费（船舶运费）保险保单的转让仍须取得保险人同意，故答案为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些保險轉讓不可以在沒有獲得保險人的同意下轉讓﹖",o:["運費保險","海上貨物保險","人身保險","以上 (a)和(c)項"],e:"海上貨物保險及人身保險的保單可無須保險人同意而自由轉讓；運費（船舶運費）保險保單的轉讓仍須取得保險人同意，故答案為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些对分担的陈述是正确的:",o:["适用于人寿保险保单","只适合应用于弥偿保险","不适用于弥偿保险","其中一方在索偿时出现过错的保单"],a:1,e:"分担原则仅适用于弥偿保险，用以集合多份保单对同一损失合理分摊、防止超额赔偿；人寿保险属利益保单不适用分担，故答案为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些對分擔的陳述是正確的：",o:["適用於人壽保險保單","只適合應用於彌償保險","不適用於彌償保險","其中一方在索償時出現過錯的保單"],e:"分擔原則僅適用於彌償保險，用以集合多份保單對同一損失合理分攤、防止超額賠償；人壽保險屬利益保單不適用分擔，故答案為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些情况下出现的损失或索偿,在没有构成可保权益时,都不会 形成拒绝赔偿的理由?",o:["人寿保险(被保险人为前配偶,现已离婚)","火险,由前承按人购买(欠款已于火灾前还清)","车险(汽车意外摧毁前已买出)","以上各项"],a:0,e:"人寿保险只须在投保时存在可保权益，离婚后保单仍有效，损失时缺乏权益不构成拒赔理由；火险及车险须在损失时具备可保权益，权益已消失将遭拒赔，故答案为人寿保险项。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些情況下出現的損失或索償，在沒有構成可保權益時，都不會 形成拒絕賠償的理由？",o:["人壽保險（被保險人為前配偶，現已離婚）","火險，由前承按人購買（欠款已於火災前還清）","車險（汽車意外摧毀前已買出）","以上各項"],e:"人壽保險只須在投保時存在可保權益，離婚後保單仍有效，損失時缺乏權益不構成拒賠理由；火險及車險須在損失時具備可保權益，權益已消失將遭拒賠，故答案為人壽保險項。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些有关最高诚信和保险在香港的情况是不正确的?",o:["最高诚信只要求就所发问的问题提供合理的答案","最高诚信只在保单条款有规定的情况下才适用","所有保单内包含某些条款,更改最高诚信责任","以上所有各项都不正确"],a:3,e:"最高诚信要求主动披露所有重要事实，并非只回答已发问的问题，也不以保单条款规定为前提；更非所有保单都载有更改最高诚信责任的条款，三句均不正确。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些有關最高誠信和保險在香港的情況是不正確的？",o:["最高誠信只要求就所發問的問題提供合理的答案","最高誠信只在保單條款有規定的情況下才適用","所有保單內包含某些條款，更改最高誠信責任","以上所有各項都不正確"],e:"最高誠信要求主動披露所有重要事實，並非只回答已發問的問題，也不以保單條款規定為前提；更非所有保單都載有更改最高誠信責任的條款，三句均不正確。"}},
{p:1,ch:"保险原则",q:"以下哪项或哪些有关财产保险中的可保权益的陈述是正确的?",o:["单单管有货物不足以构成可保权益","与保险标的有法律认可关系","不一定对标的有绝对拥有权亦有可保权益","以上各项皆是"],a:3,e:"财产保险中的可保权益须以法律认可关系为基础，单纯管有货物未必构成可保权益，且不必拥有所有权（如受托人、承按人）；三项陈述均正确。",src:1,tw:{ch:"保險原則",q:"以下哪項或哪些有關財產保險中的可保權益的陳述是正確的？",o:["單單管有貨物不足以構成可保權益","與保險標的有法律認可關係","不一定對標的有絕對擁有權亦有可保權益","以上各項皆是"],e:"財產保險中的可保權益須以法律認可關係為基礎，單純管有貨物未必構成可保權益，且不必擁有所有權（如受託人、承按人）；三項陳述均正確。"}},
{p:1,ch:"保险原则",q:"以下哪项指「既不是受保也不是除外责任的危险,而是在保单保障的范围以 外」?",o:["受保危险","除外危险","不保危险","不特定危险"],a:2,e:"不保危险指既非受保危险、亦非除外危险，处于保单保障范围以外的危险；此类危险单独引起的损失通常不获保障，故答案为不保危险。",src:1,tw:{ch:"保險原則",q:"以下哪項指「既不是受保也不是除外責任的危險，而是在保單保障的範圍以 外」？",o:["受保危險","除外危險","不保危險","不特定危險"],e:"不保危險指既非受保危險、亦非除外危險，處於保單保障範圍以外的危險；此類危險單獨引起的損失通常不獲保障，故答案為不保危險。"}},
{p:1,ch:"保险原则",q:"以下哪项是保险合约中的比例分摊的描述是不正确的?",o:["实际支付的赔偿额比应付的弥偿金额少","水险中,这术语有着不同的含义","对不足额的保险的惩罚,适用于所有类型的保险","以上各项都不正确"],a:2,e:"比例分摊是对不足额保险的处罚安排，但并非适用于所有保险类型，且「average」在水险中有不同含义，故称其适用于所有类型保险不正确。",src:1,tw:{ch:"保險原則",q:"以下哪項是保險合約中的比例分攤的描述是不正確的？",o:["實際支付的賠償額比應付的彌償金額少","水險中,這術語有着不同的含義","對不足額的保險的懲罰,適用於所有類型的保險","以上各項都不正確"],e:"比例分攤是對不足額保險的處罰安排，但並非適用於所有保險類型，且「average」在水險中有不同含義，故稱其適用於所有類型保險不正確。"}},
{p:1,ch:"保险原则",q:"以下哪项是保险理赔涉及的范围?",o:["损余","代位权的可能性","分担","以上各项"],a:3,e:"保险理赔过程中会涉及损余处理、代位权的行使以及分担等因素，三者均属理赔考虑的范围，故「以上各项」。",src:1,tw:{ch:"保險原則",q:"以下哪項是保險理賠涉及的範圍？",o:["損餘","代位權的可能性","分擔","以上各項"],e:"保險理賠過程中會涉及損餘處理、代位權的行使以及分擔等因素，三者均屬理賠考慮的範圍，故「以上各項」。"}},
{p:1,ch:"保险原则",q:"以下哪项是对「免赔额」和「起赔额」的正确描述? i 两者的原意均是避免琐碎的索偿 ii 两者的意思一样 iii 当低于免赔额时得不到赔偿 iv 当高于起赔额时可获全数的赔偿",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"免赔额与起赔额均旨在减少琐碎索偿；低于免赔额时不予赔偿，损失超过起赔额时可获全数赔偿，但两者运作机制不同、意思并不一样，故正确为 i、iii、iv。",src:1,tw:{ch:"保險原則",q:"以下哪項是對「免賠額」和「起賠額」的正確描述？ i 兩者的原意均是避免瑣碎的索償 ii 兩者的意思一樣 iii 當低於免賠額時得不到賠償 iv 當高於起賠額時可獲全數的賠償",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"免賠額與起賠額均旨在減少瑣碎索償；低於免賠額時不予賠償，損失超過起賠額時可獲全數賠償，但兩者運作機制不同、意思並不一樣，故正確為 i、iii、iv。"}},
{p:1,ch:"保险原则",q:"以下哪项是对最高诚信应用于保险的不正确描述?",o:["只就所发问的问题以诚实及实质上真实的态度处理","在保单条款上必定是可以宽免的","只有在保单条款上规定才须遵守","以上各项都不正确"],a:3,e:"最高诚信不仅限于诚实回答已发问的问题，也非仅在保单条款规定时才须遵守，更非可任意宽免；三句描述均不正确。",src:1,tw:{ch:"保險原則",q:"以下哪項是對最高誠信應用於保險的不正確描述？",o:["只就所發問的問題以誠實及實質上真實的態度處理","在保單條款上必定是可以寬免的","只有在保單條款上規定才須遵守","以上各項都不正確"],e:"最高誠信不僅限於誠實回答已發問的問題，也非僅在保單條款規定時才須遵守，更非可任意寬免；三句描述均不正確。"}},
{p:1,ch:"保险原则",q:"以下哪项是被保险人毋须披露:",o:["与常识有关的资料","保险人已知或当作已知的事实","改善风险的事实","以上所有各项"],a:3,e:"被保险人毋须披露与常识有关的资料、保险人已知或应知的事实，以及能改善风险的事实，三项均属毋须披露之列。",src:1,tw:{ch:"保險原則",q:"以下哪項是被保險人毋須披露：",o:["與常識有關的資料","保險人已知或當作已知的事實","改善風險的事實","以上所有各項"],e:"被保險人毋須披露與常識有關的資料、保險人已知或應知的事實，以及能改善風險的事實，三項均屬毋須披露之列。"}},
{p:1,ch:"保险原则",q:"以下哪项是重要事实?",o:["入屋犯法的纪录(盗窃保单)","某地区的战争情况(水险单)","发泡胶的高度易燃性(火险单)","屋宇已安装的消防洒水系统(火险单)"],a:0,e:"入屋犯法纪录直接影响承保人对盗窃风险的判断，属重要事实必须披露；战争情况、发泡胶可燃性属常识，消防洒水系统属改善风险的事实，均非必须披露的重要事实。",src:1,tw:{ch:"保險原則",q:"以下哪項是重要事實？",o:["入屋犯法的紀錄（盜竊保單）","某地區的戰爭情況（水險單）","發泡膠的高度易燃性（火險單）","屋宇已安裝的消防灑水系統（火險單）"],e:"入屋犯法紀錄直接影響承保人對盜竊風險的判斷，屬重要事實必須披露；戰爭情況、發泡膠可燃性屬常識，消防灑水系統屬改善風險的事實，均非必須披露的重要事實。"}},
{p:1,ch:"保险原则",q:"以下哪项最能描述财产保险的可保权益?",o:["财产的管有","购买保险的欲望","投保标的的价值","与财产的法律认可关系"],a:3,e:"财产保险的可保权益，核心在于被保险人与财产之间存在法律认可的关系，该关系使财产受损会为其带来财务损害；单纯管有、购买欲望或标的价值不足以单独构成可保权益。",src:1,tw:{ch:"保險原則",q:"以下哪項最能描述財產保險的可保權益？",o:["財產的管有","購買保險的欲望","投保標的的價值","與財產的法律認可關係"],e:"財產保險的可保權益，核心在於被保險人與財產之間存在法律認可的關係，該關係使財產受損會為其帶來財務損害；單純管有、購買慾望或標的價值不足以單獨構成可保權益。"}},
{p:1,ch:"保险原则",q:"以下哪项有关「弥偿」的描述并不正确:",o:["它适用于大多数非弥偿保单外的险种","它仅仅适用于利益保单","它不适用于人寿保单","它意味着保单持有人收到的赔偿不会超越损失金额"],a:1,e:"弥偿原则适用于大多数非人寿、非利益保单，旨在使赔偿不超过实际损失；说弥偿「仅仅适用于利益保单」明显错误，故答案为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項有關「彌償」的描述並不正確：",o:["它適用於大多數非彌償保單外的險種","它僅僅適用於利益保單","它不適用於人壽保單","它意味着保單持有人收到的賠償不會超越損失金額"],e:"彌償原則適用於大多數非人壽、非利益保單，旨在使賠償不超過實際損失；說彌償「僅僅適用於利益保單」明顯錯誤，故答案為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项有关收取保险金权利转让是正确的?",o:["人寿保险中,转让决不会换入新的受保生命","有关非寿险保险合约的收取保险金转让必须得到保险人的同意","不论保险金的形式如何,转让收取保险金的权利无须得到保险人的同意","收取保险金权利无须同意。人寿及海上货物例外"],a:2,e:"转让收取保险金的权利一般无须保险人同意，无论保险金的形式为何；而转让保单本身则视险种可能有不同要求，故答案为此项。",src:1,tw:{ch:"保險原則",q:"以下哪項有關收取保險金權利轉讓是正確的?",o:["人壽保險中，轉讓決不會換入新的受保生命","有關非壽險保險合約的收取保險金轉讓必須得到保險人的同意","不論保險金的形式如何，轉讓收取保險金的權利無須得到保險人的同意","收取保險金權利無須同意。人壽及海上貨物例外"],e:"轉讓收取保險金的權利一般無須保險人同意，無論保險金的形式為何；而轉讓保單本身則視險種可能有不同要求，故答案為此項。"}},
{p:1,ch:"保险原则",q:"以下哪项有关直接责任和转承责任的陈述是不正确的?",o:["直接责任是指由个人本身的行为的法律责任","直接责任是由个人对别人行为的法律责任","转承责任在雇佣关系中产生","转承责任是在委托人/代理人关系中产生"],a:1,e:"直接责任指因个人自身行为产生的法律责任，转承责任才是指对他人的行为承担责任（如雇主对雇员、委托人对代理人）；把直接责任说成对别人行为负责显然错误。",src:1,tw:{ch:"保險原則",q:"以下哪項有關直接責任和轉承責任的陳述是不正確的？",o:["直接責任是指由個人本身的行為的法律責任","直接責任是由個人對別人行為的法律責任","轉承責任在僱傭關係中產生","轉承責任是在委託人/代理人關係中產生"],e:"直接責任指因個人自身行為產生的法律責任，轉承責任才是指對他人的行為承擔責任（如僱主對僱員、委託人對代理人）；把直接責任說成對別人行為負責顯然錯誤。"}},
{p:1,ch:"保险原则",q:"以下哪项符合分担的条件?",o:["每张保单都对有关损失提供弥偿","每张保单都承保了受影响的权益","每张保单都对该损失负上赔偿责任","以上各项皆是"],a:3,e:"适用分担须各保单均对同一损失提供弥偿、承保同一受影响权益，并对该损失负有赔偿责任，三项条件缺一不可，故「以上各项皆是」。",src:1,tw:{ch:"保險原則",q:"以下哪項符合分擔的條件?",o:["每張保單都對有關損失提供彌償","每張保單都承保了受影響的權益","每張保單都對該損失負上賠償責任","以上各項皆是"],e:"適用分擔須各保單均對同一損失提供彌償、承保同一受影響權益，並對該損失負有賠償責任，三項條件缺一不可，故「以上各項皆是」。"}},
{p:1,ch:"保险原则",q:"以下哪项购买财产保险的关系中不会出现可保权益?",o:["手表的受托保管人","遗嘱执行人打算投保已逝者的建筑物","承按人打算投保按揭保障","以上各项均可构成可保权益"],a:3,e:"受托保管人、遗嘱执行人及承按人对相关财产均具法律认可的权益，均可构成可保权益；题意问不会出现可保权益的情况，三项皆会出现权益，故「以上各项均可构成可保权益」。",src:1,tw:{ch:"保險原則",q:"以下哪項購買財產保險的關係中不會出現可保權益？",o:["手錶的受託保管人","遺囑執行人打算投保已逝者的建築物","承按人打算投保按揭保障","以上各項均可構成可保權益"],e:"受託保管人、遺囑執行人及承按人對相關財產均具法律認可的權益，均可構成可保權益；題意問不會出現可保權益的情況，三項皆會出現權益，故「以上各項均可構成可保權益」。"}},
{p:1,ch:"保险原则",q:"以弥偿原则而言,在某些情况下可容许赔偿的金额超过实际损失, 但并不包括:",o:["人寿保险","重置保险","以新代旧保险","约定价值保单"],a:0,e:"重置保险、以新代旧及约定价值保单虽偏离严格弥偿，允许赔偿高于实际损失或市场价值；人寿保险属利益保单，根本不适用弥偿原则，故不包括在内。",src:1,tw:{ch:"保險原則",q:"以彌償原則而言，在某些情況下可容許賠償的金額超過實際損失， 但並不包括：",o:["人壽保險","重置保險","以新代舊保險","約定價值保單"],e:"重置保險、以新代舊及約定價值保單雖偏離嚴格彌償，允許賠償高於實際損失或市場價值；人壽保險屬利益保單，根本不適用彌償原則，故不包括在內。"}},
{p:1,ch:"保险原则",q:"保单免赔额和保单起赔额之分别:",o:["免赔额保单是指保险人会赔付十足保额","起赔额保单是指保险人会赔付十足保额","免赔额保单会支付十足保障额,除非投保人付额外保费","起赔额保单会支付十足保障额,除非投保人付额外保费"],a:1,e:"免赔额保单会从损失中扣减免赔额部分；起赔额保单则在损失超过起赔额时按十足金额赔付，故正确项为「起赔额保单是指保险人会赔付十足保额」。",src:1,tw:{ch:"保險原則",q:"保單免賠額和保單起賠額之分別:",o:["免賠額保單是指保險人會賠付十足保額","起賠額保單是指保險人會賠付十足保額","免賠額保單會支付十足保障額，除非投保人付額外保費","起賠額保單會支付十足保障額，除非投保人付額外保費"],e:"免賠額保單會從損失中扣減免賠額部分；起賠額保單則在損失超過起賠額時按十足金額賠付，故正確項為「起賠額保單是指保險人會賠付十足保額」。"}},
{p:1,ch:"保险原则",q:"保单条款中没有列明一定可以或不能得到赔偿的危险属于以下哪项?",o:["受保危险","除外危险","不保危险","指定危险"],a:2,e:"未在保单条款中明确列为受保或除外的危险，属于不保危险；此类危险引起的损失一般不在保障范围内，故答案为不保危险。",src:1,tw:{ch:"保險原則",q:"保單條款中沒有列明一定可以或不能得到賠償的危險屬於以下哪項？",o:["受保危險","除外危險","不保危險","指定危險"],e:"未在保單條款中明確列為受保或除外的危險，屬於不保危險；此類危險引起的損失一般不在保障範圍內，故答案為不保危險。"}},
{p:1,ch:"保险原则",q:"保单的条件通常说明,该保险人有权即时取得代位权,可以立刻开始执行补 偿程序的行动,但在普通法中:",o:["不合法的","在给予弥偿以后,才可获得代位权","在比例分摊的条件下,才可执行","违反最高诚信"],a:1,e:"普通法规定保险人须先向被保险人支付弥偿后，方可取得代位权；保单条件虽常赋予即时代位以尽快追偿，但普通法下的原则是弥偿后才获代位权。",src:1,tw:{ch:"保險原則",q:"保單的條件通常說明，該保險人有權即時取得代位權，可以立刻開始執行補 償程序的行動，但在普通法中：",o:["不合法的","在給予彌償以後，才可獲得代位權","在比例分攤的條件下，才可執行","違反最高誠信"],e:"普通法規定保險人須先向被保險人支付彌償後，方可取得代位權；保單條件雖常賦予即時代位以儘快追償，但普通法下的原則是彌償後才獲代位權。"}},
{p:1,ch:"保险原则",q:"保单的赔偿额已决定,当损失出现时,保单就会承担这个金额,这种赔偿方 式称为:",o:["重置保险","以新代旧","约定价值","水险保单"],a:2,e:"保单预先约定赔偿金额、损失发生时按该金额赔付的方式，称为约定价值保单；重置保险、以新代旧等则基于实际重置或修理成本，故答案为此项。",src:1,tw:{ch:"保險原則",q:"保單的賠償額已決定，當損失出現時，保單就會承擔這個金額，這種賠償方 式稱為：",o:["重置保險","以新代舊","約定價值","水險保單"],e:"保單預先約定賠償金額、損失發生時按該金額賠付的方式，稱為約定價值保單；重置保險、以新代舊等則基於實際重置或修理成本，故答案為此項。"}},
{p:1,ch:"保险原则",q:"保单转让是一份保单具有相同的保险标的,转为另一人为保单持有人。以下 哪项或哪些毋须事前得到保险人的同意便可转让? i 人寿保险 ii 出口信贷保险 iii 任何类型的责任保险 iv 海上货物保险",o:["i,ii","i, iv","ii, iii","iii, iv"],a:1,e:"人寿保险及海上货物保险可无须保险人同意而自由转让；出口信贷保险及责任保险涉及特定风险，转让须获同意，故正确组合为 i、iv。",src:1,tw:{ch:"保險原則",q:"保單轉讓是一份保單具有相同的保險標的，轉為另一人為保單持有人。以下 哪項或哪些毋須事前得到保險人的同意便可轉讓？ i 人壽保險 ii 出口信貸保險 iii 任何類型的責任保險 iv 海上貨物保險",o:["i,ii","i, iv","ii, iii","iii, iv"],e:"人壽保險及海上貨物保險可無須保險人同意而自由轉讓；出口信貸保險及責任保險涉及特定風險，轉讓須獲同意，故正確組合為 i、iv。"}},
{p:1,ch:"保险原则",q:"保险人有时会对普通法中的最高诚信作出延伸,要求投保人在投保书上作出 声明,以下哪项关于这项声明的陈述是正确的?",o:["透过这声明,投保人保证无论是否重要事实, 对所有披露的资料必须实质地真实","透过这声明,投保人保证所有披露的资料都必须是完全真实","没有这项声明,投保人无须对此负上任何责任","透过这声明,投保人保证完全披露所有资料 注1"],a:1,e:"透过投保书声明（合约基础条款），投保人保证所披露的答案必须完全真实，即使个别内容并非重要事实，不实亦可使合约失效；故正确项为「保证所有披露的资料都必须是完全真实」。",src:1,tw:{ch:"保險原則",q:"保險人有時會對普通法中的最高誠信作出延伸，要求投保人在投保書上作出 聲明，以下哪項關於這項聲明的陳述是正確的？",o:["透過這聲明,投保人保證無論是否重要事實, 對所有披露的資料必須實質地真實","透過這聲明,投保人保證所有披露的資料都必須是完全真實","沒有這項聲明,投保人無須對此負上任何責任","透過這聲明,投保人保證完全披露所有資料 注1"],e:"透過投保書聲明（合約基礎條款），投保人保證所披露的答案必須完全真實，即使個別內容並非重要事實，不實亦可使合約失效；故正確項為「保證所有披露的資料都必須是完全真實」。"}},
{p:1,ch:"保险原则",q:"保险单:",o:["一般不可更改近因法则的应用","通常排除近因法则的应用","可用一些短句对近因法则的应用作出更改","以上各项皆不正确"],a:2,e:"保单并未排除近因法则，但可通过特定措辞对近因法则的应用作出调整或更改；说其一般不可更改或通常排除均不准确，故答案为此项。",src:1,tw:{ch:"保險原則",q:"保險單：",o:["一般不可更改近因法則的應用","通常排除近因法則的應用","可用一些短句對近因法則的應用作出更改","以上各項皆不正確"],e:"保單並未排除近因法則，但可通過特定措辭對近因法則的應用作出調整或更改；說其一般不可更改或通常排除均不準確，故答案為此項。"}},
{p:1,ch:"保险原则",q:"保险合约的转让是一份保单具有相同的保险标的,转为另一人为保单持有人 ,以下哪项或哪些情况需要事前获得保险人的同意而作转让﹖",o:["营业中断保险","盗窃保险","汽车保险","以上各项皆是"],a:3,e:"营业中断、盗窃及汽车保险的转让均须事先取得保险人同意，因该类合约涉及对特定被保险人的风险与诚信评估，故「以上各项皆是」。",src:1,tw:{ch:"保險原則",q:"保險合約的轉讓是一份保單具有相同的保險標的，轉為另一人為保單持有人 ，以下哪項或哪些情況需要事前獲得保險人的同意而作轉讓﹖",o:["營業中斷保險","盜竊保險","汽車保險","以上各項皆是"],e:"營業中斷、盜竊及汽車保險的轉讓均須事先取得保險人同意，因該類合約涉及對特定被保險人的風險與誠信評估，故「以上各項皆是」。"}},
{p:1,ch:"保险原则",q:"假如保险人提出要求投保人披露所有重要及无须披露的事实,这表示:",o:["是违法的,不能强制执行","这令到最高诚信原则不致太严谨","这延伸了最高诚信的应用","应用了一般诚信而非最高诚信"],a:2,e:"要求披露所有（包括本毋须披露的）事实，是对普通法最高诚信义务的延伸，令披露责任更为严谨，并非违法，也非改采一般诚信，故答案为此项。",src:1,tw:{ch:"保險原則",q:"假如保險人提出要求投保人披露所有重要及無須披露的事實，這表示：",o:["是違法的，不能強制執行","這令到最高誠信原則不致太嚴謹","這延伸了最高誠信的應用","應用了一般誠信而非最高誠信"],e:"要求披露所有（包括本毋須披露的）事實，是對普通法最高誠信義務的延伸，令披露責任更為嚴謹，並非違法，也非改採一般誠信，故答案為此項。"}},
{p:1,ch:"保险原则",q:"假如发生的事件只有单一成因,以下哪项描述是正确的?",o:["不保危险引致的损失并不得到保障","除外危险引致的损失并不得到保障","受保危险引致的损失可以得到保障","以上各项皆正确"],a:3,e:"单一成因时，受保危险造成的损失获保障，而不保危险或除外危险造成的损失均不受保障，三项描述均正确。",src:1,tw:{ch:"保險原則",q:"假如發生的事件只有單一成因，以下哪項描述是正確的？",o:["不保危險引致的損失並不得到保障","除外危險引致的損失並不得到保障","受保危險引致的損失可以得到保障","以上各項皆正確"],e:"單一成因時，受保危險造成的損失獲保障，而不保危險或除外危險造成的損失均不受保障，三項描述均正確。"}},
{p:1,ch:"保险原则",q:"假设保单的免赔额是X,下列哪项有关的陈述是正确的?",o:["被保人的首X元损失将不获保障","索偿时会获得最高X的赔偿","索偿超过X时,将获十足的全数赔偿","被保人需付额外X保费"],a:0,e:"免赔额 X 指被保险人自行承担首 X 元的损失，超出部分才由保险人赔偿；并非获最高 X 的赔偿，也非超过 X 即十足全赔或另缴保费，故答案为首 X 元不获保障。",src:1,tw:{ch:"保險原則",q:"假設保單的免賠額是X，下列哪項有關的陳述是正確的?",o:["被保人的首X元損失將不獲保障","索償時會獲得最高X的賠償","索償超過X時，將獲十足的全數賠償","被保人需付額外X保費"],e:"免賠額 X 指被保險人自行承擔首 X 元的損失，超出部分才由保險人賠償；並非獲最高 X 的賠償，也非超過 X 即十足全賠或另繳保費，故答案為首 X 元不獲保障。"}},
{p:1,ch:"保险原则",q:"假设火险保单只保障火灾或雷电带来的损失或损坏,如果雨水透过敞开的窗 户进入室内造成损失,是得不到保障的,因为其近因是:",o:["外来危险","除外危险","不保危险","不可保危险"],a:2,e:"火险仅承保火灾或雷电，雨水经敞开窗户进入并非受保危险，亦非列明的除外危险，属保单保障范围之外的不保危险，故其损失不获保障。",src:1,tw:{ch:"保險原則",q:"假設火險保單只保障火災或雷電帶來的損失或損壞，如果雨水透過敞開的窗 戶進入室內造成損失，是得不到保障的，因為其近因是：",o:["外來危險","除外危險","不保危險","不可保危險"],e:"火險僅承保火災或雷電，雨水經敞開窗户進入並非受保危險，亦非列明的除外危險，屬保單保障範圍之外的不保危險，故其損失不獲保障。"}},
{p:1,ch:"保险原则",q:"分担与代位两者十分相似,两者均是:",o:["确保被保险人不会获得超额赔偿","确保疏忽人士作出赔偿","可以应用于其他保险类型","以上没有一项正确"],a:0,e:"分担与代位权的共同目标，都是确保被保险人不能从保险中获得超过实际损失的赔偿，防止不当得利；其余选项描述并不准确。",src:1,tw:{ch:"保險原則",q:"分擔與代位兩者十分相似，兩者均是:",o:["確保被保險人不會獲得超額賠償","確保疏忽人士作出賠償","可以應用於其他保險類型","以上沒有一項正確"],e:"分擔與代位權的共同目標，都是確保被保險人不能從保險中獲得超過實際損失的賠償，防止不當得利；其餘選項描述並不準確。"}},
{p:1,ch:"保险原则",q:"分担和代位权有近似目标,就是两者均:",o:["要求有两份或以上保单","要求其他保险保障相同权益","力求确保疏忽一方支付损失","力求确保被保险人最后收取的赔偿不会超过弥偿"],a:3,e:"分担与代位权目标相近，均在于确保被保险人最终获得的赔偿总额不超过弥偿（实际损失），避免超额赔偿，故答案为此项。",src:1,tw:{ch:"保險原則",q:"分擔和代位權有近似目標，就是兩者均：",o:["要求有兩份或以上保單","要求其他保險保障相同權益","力求確保疏忽一方支付損失","力求確保被保險人最後收取的賠償不會超過彌償"],e:"分擔與代位權目標相近，均在於確保被保險人最終獲得的賠償總額不超過彌償（實際損失），避免超額賠償，故答案為此項。"}},
{p:1,ch:"保险原则",q:"分担属于下列哪项重要原则之一?",o:["代位权","弥偿","委付","损余"],a:1,e:"分担是弥偿原则的延伸，用以在多重保险下防止超额赔偿，故属弥偿原则之一；代位权、委付、损余是相关但不同的概念。",src:1,tw:{ch:"保險原則",q:"分擔屬於下列哪項重要原則之一？",o:["代位權","彌償","委付","損餘"],e:"分擔是彌償原則的延伸，用以在多重保險下防止超額賠償，故屬彌償原則之一；代位權、委付、損餘是相關但不同的概念。"}},
{p:1,ch:"保险原则",q:"分担应用时,任何一位保险人对被保险人的损失应负最终部分是:",o:["比例分摊","免赔额","起赔额","比率之数"],a:3,e:"在分担原则下，每位保险人最终按比率分摊损失份额；「比例分摊」为不足额保险下的处理，免赔额与起赔额与此无关，故答案为「比率之数」。",src:1,tw:{ch:"保險原則",q:"分擔應用時，任何一位保險人對被保險人的損失應負最終部分是：",o:["比例分攤","免賠額","起賠額","比率之數"],e:"在分擔原則下，每位保險人最終按比率分攤損失份額；「比例分攤」為不足額保險下的處理，免賠額與起賠額與此無關，故答案為「比率之數」。"}},
{p:1,ch:"保险原则",q:"危险的种类有三种,分别是不保危险﹑除外危险及 _____________ 。",o:["可保危险","受保危险","额外危险","不被接受危险"],a:1,e:"危险依保障可分为受保危险、不保危险及除外危险三类，题干已列出不保危险与除外危险，故空格应为「受保危险」。",src:1,tw:{ch:"保險原則",q:"危險的種類有三種,分別是不保危險﹑除外危險及 _____________ 。",o:["可保危險","受保危險","額外危險","不被接受危險"],e:"危險依保障可分為受保危險、不保危險及除外危險三類，題幹已列出不保危險與除外危險，故空格應為「受保危險」。"}},
{p:1,ch:"保险原则",q:"可保权益可以在合法权利受到侵害或未来收入存在损失的情况下出现,以下 哪项属于这种情况?",o:["酒楼经营者就电力中断后产生的营业利润损失而购买保险","汽车意外后需租用另一辆汽车","酒楼经营者就禽流感爆发产生的利润损失购买保险","以上所有皆是"],a:3,e:"酒楼因电力中断或禽流感爆发产生的利润损失、汽车意外后租用替代车辆的开支，均属合法权益受侵害或预期收入受损而产生的可保权益，三项皆是。",src:1,tw:{ch:"保險原則",q:"可保權益可以在合法權利受到侵害或未來收入存在損失的情況下出現，以下 哪項屬於這種情況？",o:["酒樓經營者就電力中斷後產生的營業利潤損失而購買保險","汽車意外後需租用另一輛汽車","酒樓經營者就禽流感爆發產生的利潤損失購買保險","以上所有皆是"],e:"酒樓因電力中斷或禽流感爆發產生的利潤損失、汽車意外後租用替代車輛的開支，均屬合法權益受侵害或預期收入受損而產生的可保權益，三項皆是。"}},
{p:1,ch:"保险原则",q:"可保权益可以在合法权益受到侵犯或当损失/支出在间接的情况下发生,下列 哪项或哪些有关:",o:["房东-因火灾引致损失租金","汽车-因损坏而付出的额外汽车租金","工厂-因爆炸而导致利润损失","以上所有各项"],a:3,e:"房东因火灾损失租金、车主因损坏额外租车、工厂因爆炸导致利润损失，均属合法权益受损或间接损失产生的可保权益，故「以上所有各项」。",src:1,tw:{ch:"保險原則",q:"可保權益可以在合法權益受到侵犯或當損失/支出在間接的情况下發生，下列 哪項或哪些有關：",o:["房東-因火災引致損失租金","汽車-因損壞而付出的額外汽車租金","工廠-因爆炸而導致利潤損失","以上所有各項"],e:"房東因火災損失租金、車主因損壞額外租車、工廠因爆炸導致利潤損失，均屬合法權益受損或間接損失產生的可保權益，故「以上所有各項」。"}},
{p:1,ch:"保险原则",q:"可保权益的合法权利益指受到侵犯或损失/开支产生的可能性,以下哪些例子 是正确的?",o:["房东因火灾损失租金的收入","汽车意外需租用另一辆汽车","酒楼因电力供应中断而导致利润的损失","以上皆是"],a:3,e:"房东因火灾损失租金、汽车意外租用替代车辆、酒楼因停电损失利润，均体现合法权益受侵害或损失可能发生而产生的可保权益，故「以上皆是」。",src:1,tw:{ch:"保險原則",q:"可保權益的合法權利益指受到侵犯或損失/開支產生的可能性，以下哪些例子 是正確的?",o:["房東因火災損失租金的收入","汽車意外需租用另一輛汽車","酒樓因電力供應中斷而導致利潤的損失","以上皆是"],e:"房東因火災損失租金、汽車意外租用替代車輛、酒樓因停電損失利潤，均體現合法權益受侵害或損失可能發生而產生的可保權益，故「以上皆是」。"}},
{p:1,ch:"保险原则",q:"哪一类保险保障只需在保单开始时存在可保权益便可以?",o:["汽车保险","家居保险","人寿保险","医疗保险"],a:2,e:"人寿保险只须在保单生效时存在可保权益，其后权益消失亦不影响保单；汽车、家居及医疗等保险须在损失时具备可保权益，故答案为人寿保险。",src:1,tw:{ch:"保險原則",q:"哪一類保險保障只需在保單開始時存在可保權益便可以？",o:["汽車保險","家居保險","人壽保險","醫療保險"],e:"人壽保險只須在保單生效時存在可保權益，其後權益消失亦不影響保單；汽車、家居及醫療等保險須在損失時具備可保權益，故答案為人壽保險。"}},
{p:1,ch:"保险原则",q:"哪一项是属于超额弥偿的类别:",o:["双方协议","以旧代新","约定价值","保单起赔额"],a:2,e:"约定价值保单在订立时即确定赔偿金额，即使该金额可能超过损失发生时的实际价值，属容许超额弥偿的类别；双方协议并非此类，起赔额反而限制赔偿，故答案为约定价值。",src:1,tw:{ch:"保險原則",q:"哪一項是屬於超額彌償的類別：",o:["雙方協議","以舊代新","約定價值","保單起賠額"],e:"約定價值保單在訂立時即確定賠償金額，即使該金額可能超過損失發生時的實際價值，屬容許超額彌償的類別；雙方協議並非此類，起賠額反而限制賠償，故答案為約定價值。"}},
{p:1,ch:"保险原则",q:"哪一项是属于超额弥偿的类别?",o:["双方协议","以旧代新","约定价值","保单起赔额"],a:2,e:"约定价值保单按订约时约定的价值赔偿，即使超出损失时实际价值亦照付，属超额弥偿的类别；以新代旧、双方协议及起赔额并非此类，故答案为约定价值。",src:1,tw:{ch:"保險原則",q:"哪一項是屬於超額彌償的類別?",o:["雙方協議","以舊代新","約定價值","保單起賠額"],e:"約定價值保單按訂約時約定的價值賠償，即使超出損失時實際價值亦照付，屬超額彌償的類別；以新代舊、雙方協議及起賠額並非此類，故答案為約定價值。"}},
{p:1,ch:"保险原则",q:"在「近因」的法则中,一项并非在保障范围内剔除,亦非包括在保障范围内 之危险名称:",o:["不保危险","可保危险","受保危险","除外危险"],a:0,e:"近因法则中，既不属承保范围、亦未列明的危险称为不保危险；此类危险引起的损失一般不获保障，故答案为不保危险。",src:1,tw:{ch:"保險原則",q:"在「近因」的法則中，一項並非在保障範圍內剔除，亦非包括在保障範圍內 之危險名稱：",o:["不保危險","可保危險","受保危險","除外危險"],e:"近因法則中，既不屬承保範圍、亦未列明的危險稱為不保危險；此類危險引起的損失一般不獲保障，故答案為不保危險。"}},
{p:1,ch:"保险原则",q:"在一般情况下,如果遇到风险有所转变,例如购买火险后风险比起购买前提 高了:",o:["明显地对保险人来说是十分重要的","以保险条款来说是必须通知保险人的","普通法提及在续约前并不需要通知保险人","以上所列各项"],a:3,e:"风险重大转变对保险人极为重要，个别保单条款要求通知，而普通法一般只需在续约时告知，三项均正确，故「以上所列各项」。",src:1,tw:{ch:"保險原則",q:"在一般情況下，如果遇到風險有所轉變，例如購買火險後風險比起購買前提 高了：",o:["明顯地對保險人來說是十分重要的","以保險條款來說是必須通知保險人的","普通法提及在續約前並不需要通知保險人","以上所列各項"],e:"風險重大轉變對保險人極為重要，個別保單條款要求通知，而普通法一般只需在續約時告知，三項均正確，故「以上所列各項」。"}},
{p:1,ch:"保险原则",q:"在代位权的补偿上,以下哪项具体的考虑因素会出现? i  保险人从代位权安排下取得的补偿,不可多于弥偿安排下的金额 ii 假如代位权在委付财产予保险人后出现,保险人便可从此财产中取利 iii 对于每一元的付出,代位权能给予的上限为百分之一百 iv 假如代位权在委付财产予保险人后出现,对于每一元的付出, 代位权能给予的上限为百分之一百",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:0,e:"代位权下保险人取得的补偿不得超过其已付弥偿金额，委付财产后保险人可从中获益，且代位权上限为每一元付出的百分之一百；选项 iv 与 iii 矛盾故错，正确组合为 i、ii、iii。",src:1,tw:{ch:"保險原則",q:"在代位權的補償上，以下哪項具體的考慮因素會出現？ i 保險人從代位權安排下取得的補償，不可多於彌償安排下的金額 ii 假如代位權在委付財產予保險人後出現，保險人便可從此財產中取利 iii 對於每一元的付出，代位權能給予的上限為百分之一百 iv 假如代位權在委付財產予保險人後出現，對於每一元的付出， 代位權能給予的上限為百分之一百",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"代位權下保險人取得的補償不得超過其已付彌償金額，委付財產後保險人可從中獲益，且代位權上限為每一元付出的百分之一百；選項 iv 與 iii 矛盾故錯，正確組合為 i、ii、iii。"}},
{p:1,ch:"保险原则",q:"在代位权的补偿中,如何处置向第三者索取的多余的款项:",o:["属于被保险人","属于保险人","运用比例分摊","保险人和被保险人平均分享"],a:0,e:"代位权下，保险人向第三者追偿所得若超过其已付赔偿，超出部分仍属被保险人，保险人不得藉此获利，故多余款项归被保险人。",src:1,tw:{ch:"保險原則",q:"在代位權的補償中，如何處置向第三者索取的多餘的款項：",o:["屬於被保險人","屬於保險人","運用比例分攤","保險人和被保險人平均分享"],e:"代位權下，保險人向第三者追償所得若超過其已付賠償，超出部分仍屬被保險人，保險人不得藉此獲利，故多餘款項歸被保險人。"}},
{p:1,ch:"保险原则",q:"在任何时候,向另一方披露所有重要事实?",o:["特殊诚信","最高诚信","一般诚信","合约诚信"],a:1,e:"要求在任何时候向另一方披露所有重要事实的义务，属最高诚信原则；一般诚信仅要求不作虚假陈述，无主动披露义务，故答案为最高诚信。",src:1,tw:{ch:"保險原則",q:"在任何時候，向另一方披露所有重要事實?",o:["特殊誠信","最高誠信","一般誠信","合約誠信"],e:"要求在任何時候向另一方披露所有重要事實的義務，屬最高誠信原則；一般誠信僅要求不作虛假陳述，無主動披露義務，故答案為最高誠信。"}},
{p:1,ch:"保险原则",q:"在合约有效期内,下列哪项是正确的?",o:["在普通法中,风险的转变只须续约时才予以知会","当保单续保时,最高诚信的责任不适用","在合约有效期内,要求披露重要资料是一种特殊做法","以上各项都是"],a:0,e:"普通法下，保单有效期内风险发生转变，一般只需在续约时告知保险人，毋须即时通知；其余选项对最高诚信的理解有误，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在合約有效期內，下列哪項是正確的？",o:["在普通法中，風險的轉變只須續約時才予以知會","當保單續保時，最高誠信的責任不適用","在合約有效期內，要求披露重要資料是一種特殊做法","以上各項都是"],e:"普通法下，保單有效期內風險發生轉變，一般只需在續約時告知保險人，毋須即時通知；其餘選項對最高誠信的理解有誤，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在处理一项财产保险的中介人,应尽力确保客户将要求的保额是代表该财产 的价值,因不足额的保险:",o:["合约便告无效","被保险人需付额外保费","保险人于赔偿时会作出比例分摊","不足额保险是不重要的"],a:2,e:"不足额保险会在赔偿时按比例分摊递减保险人的责任，令被保险人无法获十足赔偿，故中介应确保保额足额；合约并不因此无效，也非缴付额外保费或无关紧要。",src:1,tw:{ch:"保險原則",q:"在處理一項財產保險的中介人，應盡力確保客戶將要求的保額是代表該財產 的價值，因不足額的保險：",o:["合約便告無效","被保險人需付額外保費","保險人於賠償時會作出比例分攤","不足額保險是不重要的"],e:"不足額保險會在賠償時按比例分攤遞減保險人的責任，令被保險人無法獲十足賠償，故中介應確保保額足額；合約並不因此無效，也非繳付額外保費或無關緊要。"}},
{p:1,ch:"保险原则",q:"在多数的财产保险索偿中标的有时还有剩余价值,该价值应于赔偿给付中计 算在内,称为:",o:["损余","分担","比例分摊","代位权"],a:0,e:"财产损失后仍存的剩余价值称为损余，计算弥偿时须将其价值计入从赔偿中扣除；分担、比例分摊及代位权均为不同概念，故答案为损余。",src:1,tw:{ch:"保險原則",q:"在多數的財產保險索償中標的有時還有剩餘價值，該價值應於賠償給付中計 算在內，稱為：",o:["損餘","分擔","比例分攤","代位權"],e:"財產損失後仍存的剩餘價值稱為損餘，計算彌償時須將其價值計入從賠償中扣除；分擔、比例分攤及代位權均為不同概念，故答案為損餘。"}},
{p:1,ch:"保险原则",q:"在委付及给予弥偿后,保险人应如何处理售卖损余中得到的利润?",o:["将利润归还保单持有人","保险人和保单持有人五五分帐","利益归保险人","保险人不可售卖损余"],a:2,e:"委付并支付全损赔款后，损余归保险人所有，其出售损余所得的利润亦归保险人；被保险人已获全数赔偿，不得再分享，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在委付及給予彌償後，保險人應如何處理售賣損餘中得到的利潤？",o:["將利潤歸還保單持有人","保險人和保單持有人五五分帳","利益歸保險人","保險人不可售賣損餘"],e:"委付並支付全損賠款後，損餘歸保險人所有，其出售損餘所得的利潤亦歸保險人；被保險人已獲全數賠償，不得再分享，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在实际情况下,除人寿保险外,下列哪类保险在索偿时才需要证明可保权益 ?",o:["雇员补偿","营业中断","一切责任保险","以上所有各项"],a:3,e:"除人寿保险只须投保时具备可保权益外，雇员补偿、营业中断及一切责任保险均须在损失发生时证明可保权益，故「以上所有各项」。",src:1,tw:{ch:"保險原則",q:"在實際情況下，除人壽保險外，下列哪類保險在索償時才需要證明可保權益 ？",o:["僱員補償","營業中斷","一切責任保險","以上所有各項"],e:"除人壽保險只須投保時具備可保權益外，僱員補償、營業中斷及一切責任保險均須在損失發生時證明可保權益，故「以上所有各項」。"}},
{p:1,ch:"保险原则",q:"在实际执行时,除人寿保险外,差不多所有保单都要求可保权益只是:",o:["在续保时存在","当受保事件发生时存在","当缴付首期保费后存在","当填妥投保申请书时存在"],a:1,e:"除人寿保险外，多数保单要求可保权益在受保事件（损失）发生时存在，而非续保、缴付保费或填妥投保书时，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在實際執行時，除人壽保險外，差不多所有保單都要求可保權益只是：",o:["在續保時存在","當受保事件發生時存在","當繳付首期保費後存在","當填妥投保申請書時存在"],e:"除人壽保險外，多數保單要求可保權益在受保事件（損失）發生時存在，而非續保、繳付保費或填妥投保書時，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在弥偿中,下列哪些条件有时意味着比应予赔偿为少的金额? i 保单免赔额 ii 保单起赔额 iii 约定价值保单 iv 水险保单",o:["i及ii","i及iii","ii及iii","iii及iv"],a:0,e:"免赔额会从损失中扣减，起赔额在损失低于起赔额时不予赔偿，均可能令赔偿少于应有金额；约定价值保单按约定价值赔付，水险保单无此减赔特性，故答案为 i 及 ii。",src:1,tw:{ch:"保險原則",q:"在彌償中,下列哪些條件有時意味着比應予賠償為少的金額? i 保單免賠額 ii 保單起賠額 iii 約定價值保單 iv 水險保單",o:["i及ii","i及iii","ii及iii","iii及iv"],e:"免賠額會從損失中扣減，起賠額在損失低於起賠額時不予賠償，均可能令賠償少於應有金額；約定價值保單按約定價值賠付，水險保單無此減賠特性，故答案為 i 及 ii。"}},
{p:1,ch:"保险原则",q:"在机缘巧合下,出售损余的款项高于实际赔偿的金额,那么:",o:["保险人便可赚取不俗的利润","盈余须与被保险人以五五分帐形式分享","这项事宜须呈交法庭解决","盈余须归予被保险人(保险人没有权利赚取利润)"],a:0,e:"委付后保险人取得损余，若出售损余所得高于已付赔偿，差额归保险人所有，保险人可因此获益；被保险人已获全赔不得分享，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在機緣巧合下，出售損餘的款項高於實際賠償的金額，那麼：",o:["保險人便可賺取不俗的利潤","盈餘須與被保險人以五五分帳形式分享","這項事宜須呈交法庭解決","盈餘須歸予被保險人（保險人沒有權利賺取利潤）"],e:"委付後保險人取得損餘，若出售損餘所得高於已付賠償，差額歸保險人所有，保險人可因此獲益；被保險人已獲全賠不得分享，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在法律上,投保人有责任向保险人披露重要事实的责任,在以下哪项情况下 出现:",o:["整份保单有效期内","保险人签发保单为止","保险人接受投保为止","投保人签署投保书为止"],a:2,e:"投保人披露重要事实的责任持续至保险人接受投保为止，其间情况有变亦须补报；并非整个保单有效期内持续或仅止于签署投保书，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在法律上，投保人有責任向保險人披露重要事實的責任，在以下哪項情況下 出現：",o:["整份保單有效期內","保險人簽發保單為止","保險人接受投保為止","投保人簽署投保書為止"],e:"投保人披露重要事實的責任持續至保險人接受投保為止，其間情況有變亦須補報；並非整個保單有效期內持續或僅止於簽署投保書，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在考虑「损余」时,以下哪项并不正确?",o:["当弥偿适用时便会考虑","在海事法中这个术语有不同含义","当计算弥偿时,必须把该价值考虑在内","只有在不足保险上才会考虑"],a:3,e:"损余在适用弥偿的任何情况下均须考虑其价值并予扣除，并非只在不足额保险时才考虑；其余描述正确，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在考慮「損餘」時，以下哪項並不正確？",o:["當彌償適用時便會考慮","在海事法中這個術語有不同含義","當計算彌償時，必須把該價值考慮在內","只有在不足保險上才會考慮"],e:"損餘在適用彌償的任何情況下均須考慮其價值並予扣除，並非只在不足額保險時才考慮；其餘描述正確，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在考虑近因之应用时,如果一项特定损失只涉及单一成因,而:",o:["成因是受保危险,被保人便可以得到损失的保障额","成因是不保危险,被保人便可以得到损失的保障额","成因是除外危险,被保人便可以得到损失的保障额","以上各项都是"],a:0,e:"单一成因时，若近因为受保危险，损失可获保障；不保危险或除外危险导致的损失不获保障，故正确答案为此项。",src:1,tw:{ch:"保險原則",q:"在考慮近因之應用時，如果一項特定損失只涉及單一成因，而：",o:["成因是受保危險，被保人便可以得到損失的保障額","成因是不保危險，被保人便可以得到損失的保障額","成因是除外危險，被保人便可以得到損失的保障額","以上各項都是"],e:"單一成因時，若近因為受保危險，損失可獲保障；不保危險或除外危險導致的損失不獲保障，故正確答案為此項。"}},
{p:1,ch:"保险原则",q:"在近因原则中,以下哪些是不保危险的不正确陈述:",o:["尽管不是特别包括在内,但也不是特别排除在外","由受保危险引致的不保危险,其导致的损失可得到保障","术语中不保危险和除外危险是完全相同的","如果由单一原因引致的损失,不保危险引致的损失是得不到保障的"],a:2,e:"不保危险与除外危险是两种不同概念，除外危险被保单明确剔除，不保危险则未被列入亦未剔除；「两者完全相同」是错误描述，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在近因原則中，以下哪些是不保危險的不正確陳述：",o:["儘管不是特別包括在內，但也不是特別排除在外","由受保危險引致的不保危險，其導致的損失可得到保障","術語中不保危險和除外危險是完全相同的","如果由單一原因引致的損失，不保危險引致的損失是得不到保障的"],e:"不保危險與除外危險是兩種不同概念，除外危險被保單明確剔除，不保危險則未被列入亦未剔除；「兩者完全相同」是錯誤描述，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在重复保险上,以下哪项不应出现分担原理:",o:["火险","盗窃保险","人身意外保险中的人寿利益部份","以上各项皆是"],a:2,e:"人身意外保险中的人寿利益部分属利益给付，不适用分担原理；火险、盗窃险属弥偿保险可适用分担，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在重覆保險上，以下哪項不應出現分擔原理：",o:["火險","盜竊保險","人身意外保險中的人壽利益部份","以上各項皆是"],e:"人身意外保險中的人壽利益部分屬利益給付，不適用分擔原理；火險、盜竊險屬彌償保險可適用分擔，故答案為此項。"}},
{p:1,ch:"保险原则",q:"在非人寿保险续保时,最高诚信:",o:["需要再履行","不需要履行","没有需要","以上各项均不正确"],a:0,e:"非人寿保险续保时，最高诚信义务须重新履行，被保险人须对续保时的新情况如实披露，故「需要再履行」。",src:1,tw:{ch:"保險原則",q:"在非人壽保險續保時，最高誠信：",o:["需要再履行","不需要履行","沒有需要","以上各項均不正確"],e:"非人壽保險續保時，最高誠信義務須重新履行，被保險人須對續保時的新情況如實披露，故「需要再履行」。"}},
{p:1,ch:"保险原则",q:"在香港,每一名人士对以下哪项或哪些人士的生命不具可保权益(为个人本 身的利益购买人寿保险)?",o:["个人自己","个人的配偶","其17岁刚于数天前丧失父亲的姪儿(或外甥)","未满18岁的子女或被监护人"],a:2,e:"为自己、配偶及未满18岁的子女或被监护人投保具天然可保权益；17岁的侄儿或外甥若无财务依赖关系，对其生命无可保权益，故答案为此项。",src:1,tw:{ch:"保險原則",q:"在香港，每一名人士對以下哪項或哪些人士的生命不具可保權益（為個人本 身的利益購買人壽保險）？",o:["個人自己","個人的配偶","其17歲剛於數天前喪失父親的姪兒(或外甥)","未滿18歲的子女或被監護人"],e:"為自己、配偶及未滿18歲的子女或被監護人投保具天然可保權益；17歲的侄兒或外甥若無財務依賴關係，對其生命無可保權益，故答案為此項。"}},
{p:1,ch:"保险原则",q:"多种财产保险中的保单条款都规定,如果发生损失时不足额保险存在,保险 人的责任便会按不足额的保险价值的百分比递减,这一项条款通常称为?",o:["代位","分担","比例分摊","保单免赔额"],a:2,e:"不足额保险下按保额与价值之比递减赔偿责任的条款，称为比例分摊条款；代位、分担及免赔额与之不同，故答案为此项。",src:1,tw:{ch:"保險原則",q:"多種財產保險中的保單條款都規定，如果發生損失時不足額保險存在，保險 人的責任便會按不足額的保險價值的百分比遞減，這一項條款通常稱為？",o:["代位","分擔","比例分攤","保單免賠額"],e:"不足額保險下按保額與價值之比遞減賠償責任的條款，稱為比例分攤條款；代位、分擔及免賠額與之不同，故答案為此項。"}},
{p:1,ch:"保险原则",q:"大部分商业合约均受到:",o:["一般诚信的约束","最高诚信的约束","简单诚信的约束","披露所有重要事实的法定要求约束"],a:0,e:"一般商业合约受一般诚信约束，即只需负不作虚假陈述的消极诚实义务；最高诚信及披露所有重要事实的法定要求主要针对保险合约，故答案为一般诚信。",src:1,tw:{ch:"保險原則",q:"大部分商業合約均受到：",o:["一般誠信的約束","最高誠信的約束","簡單誠信的約束","披露所有重要事實的法定要求約束"],e:"一般商業合約受一般誠信約束，即只需負不作虛假陳述的消極誠實義務；最高誠信及披露所有重要事實的法定要求主要針對保險合約，故答案為一般誠信。"}},
{p:1,ch:"保险原则",q:"如在保险保障期间,风险上有重大转变:",o:["很明显地对保险人极为重要","某些保险合约可能要求被保险人作出披露","普通法要求在续约时方须提出","以上各项皆正确"],a:3,e:"保障期间风险重大转变对保险人极为重要，某些合约要求被保险人披露，普通法则只须在续约时提出，三项均正确。",src:1,tw:{ch:"保險原則",q:"如在保險保障期間，風險上有重大轉變：",o:["很明顯地對保險人極為重要","某些保險合約可能要求被保險人作出披露","普通法要求在續約時方須提出","以上各項皆正確"],e:"保障期間風險重大轉變對保險人極為重要，某些合約要求被保險人披露，普通法則只須在續約時提出，三項均正確。"}},
{p:1,ch:"保险原则",q:"如果一个人买了人身意外及私人汽车保险中的意外死亡利益,而其后在一次 汽车意外中死亡,则:",o:["每份保单均需作出赔偿","仅仅首先生效的保单须要作出赔偿","仅仅保额较高的保单须要作出赔偿","既然是由于汽车意外而死,只有汽车保险须要作出赔偿"],a:0,e:"人身意外及汽车保险的意外死亡利益属利益给付而非弥偿，两保单均须按各自条款作出赔偿，并不互相抵扣，故「每份保单均需作出赔偿」。",src:1,tw:{ch:"保險原則",q:"如果一個人買了人身意外及私人汽車保險中的意外死亡利益，而其後在一次 汽車意外中死亡，則：",o:["每份保單均需作出賠償","僅僅首先生效的保單須要作出賠償","僅僅保額較高的保單須要作出賠償","既然是由於汽車意外而死，只有汽車保險須要作出賠償"],e:"人身意外及汽車保險的意外死亡利益屬利益給付而非彌償，兩保單均須按各自條款作出賠償，並不互相抵扣，故「每份保單均需作出賠償」。"}},
{p:1,ch:"保险原则",q:"如果一份保单承诺依据保单条款及条件向被保险人提供「弥偿」,这意味着 :",o:["任何理赔给付均只能以现金方式进行","该份保单必须代表一份人寿保险合约","针对特定损失,该保险人只会给付已声明的利益","保险人打算对损失提供一项精确的补偿"],a:3,e:"弥偿指保险人对被保险人的实际损失提供精确补偿，使其恢复损失前状况，不以现金为唯一方式，也非只给付声明利益或代表人寿合约，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果一份保單承諾依據保單條款及條件向被保險人提供「彌償」,這意味着 :",o:["任何理賠給付均只能以現金方式進行","該份保單必須代表一份人壽保險合約","針對特定損失,該保險人只會給付已聲明的利益","保險人打算對損失提供一項精確的補償"],e:"彌償指保險人對被保險人的實際損失提供精確補償，使其恢復損失前狀況，不以現金為唯一方式，也非只給付聲明利益或代表人壽合約，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果一份保单有3000元的免赔额,意思是:",o:["如果损失超过3000元便不会得到赔偿","如果损失不超过3000元便会得到赔偿","如果损失超过3000元便会得到全额赔偿","如果损失不超过3000元便不会得到赔偿"],a:3,e:"免赔额3000元指损失不超过3000元时被保险人自行承担、不获赔偿，超出部分才获赔；并非超过即全赔，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果一份保單有3000元的免賠額，意思是：",o:["如果損失超過3000元便不會得到賠償","如果損失不超過3000元便會得到賠償","如果損失超過3000元便會得到全額賠償","如果損失不超過3000元便不會得到賠償"],e:"免賠額3000元指損失不超過3000元時被保險人自行承擔、不獲賠償，超出部分才獲賠；並非超過即全賠，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果一份保单有6000元的免赔额,意思是:",o:["如果损失超过6000元便不会得到赔偿","如果损失不超过6000元便会得到赔偿","如果损失超过6000元便会得到全额赔偿","如果损失不超过6000元便不会得到赔偿 3.4.7(a),"],a:3,e:"免赔额6000元指损失不超过6000元时不获赔偿，由被保险人自行承担，只有超出6000元的部分才获赔付，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果一份保單有6000元的免賠額，意思是：",o:["如果損失超過6000元便不會得到賠償","如果損失不超過6000元便會得到賠償","如果損失超過6000元便會得到全額賠償","如果損失不超過6000元便不會得到賠償 3.4.7(a),"],e:"免賠額6000元指損失不超過6000元時不獲賠償，由被保險人自行承擔，只有超出6000元的部分才獲賠付，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果一份水险单起赔额为5%,意味着?",o:["受保损失总额的4%可获全额赔偿","保额的6%可获全额赔偿","受保损失总额的5%是免赔额","起赔额的5%不获赔偿"],a:1,e:"5%起赔额表示当损失超过保险金额的5%时，保险人便按全数赔偿损失（如损失达保额的6%即已超过起赔额，可获全额赔偿）；把起赔额当作免赔额或固定扣减的说法不正确。",src:1,tw:{ch:"保險原則",q:"如果一份水險單起賠額為5%,意味着?",o:["受保損失總額的4%可獲全額賠償","保額的6%可獲全額賠償","受保損失總額的5%是免賠額","起賠額的5%不獲賠償"],e:"5%起賠額表示當損失超過保險金額的5%時，保險人便按全數賠償損失（如損失達保額的6%即已超過起賠額，可獲全額賠償）；把起賠額當作免賠額或固定扣減的說法不正確。"}},
{p:1,ch:"保险原则",q:"如果一份海上货物险起赔额为5%,意味着?",o:["受保损失总额的5%可获全额赔偿","保额的6%可获全额赔偿","如受保损失超过保额5%,受保损失总额的5%是免赔额","如超过保额的5%,不获赔偿"],a:1,e:"5%起赔额指损失超过保险金额的5%时即可获全数赔偿（达保额6%即已超逾起赔额故获全额赔偿）；起赔额并非免赔额，超过后亦非不获赔偿，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果一份海上貨物險起賠額為5%,意味着?",o:["受保損失總額的5%可獲全額賠償","保額的6%可獲全額賠償","如受保損失超過保額5%,受保損失總額的5%是免賠額","如超過保額的5%,不獲賠償"],e:"5%起賠額指損失超過保險金額的5%時即可獲全數賠償（達保額6%即已超逾起賠額故獲全額賠償）；起賠額並非免賠額，超過後亦非不獲賠償，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果一份财产保险单被称为「受比例分摊条件约束」,意思是:",o:["所代表的是一种标准风险,因此标准保费适用该风险","不足保额保险是不重要","在任何情汜下均不会对损失提供十足的支付","如果保额足够的话,便会对损失提供十足的支付"],a:3,e:"受比例分摊条件约束指不足额保险时赔偿按比例递减，但保额足够时会对损失作十足支付；并非表示不足额无关紧要或在任何情况下都不足额赔付，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果一份財產保險單被稱為「受比例分攤條件約束」，意思是:",o:["所代表的是一種標準風險，因此標準保費適用該風險","不足保額保險是不重要","在任何情汜下均不會對損失提供十足的支付","如果保額足夠的話，便會對損失提供十足的支付"],e:"受比例分攤條件約束指不足額保險時賠償按比例遞減，但保額足夠時會對損失作十足支付；並非表示不足額無關緊要或在任何情況下都不足額賠付，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果保险人要求保证所有披露资料,不论重要与否,均需完全真实,这表示 :",o:["违反法例并不能强制执行","延伸普通法中的最高诚信的要求","这合约受制于一般诚信而非最高诚信","这合约受制于最高诚信"],a:1,e:"要求所有披露资料（不论是否重要）均须完全真实，是在普通法最高诚信基础上的延伸，使披露标准更严格，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果保險人要求保證所有披露資料，不論重要與否，均需完全真實，這表示 ：",o:["違反法例並不能強制執行","延伸普通法中的最高誠信的要求","這合約受制於一般誠信而非最高誠信","這合約受制於最高誠信"],e:"要求所有披露資料（不論是否重要）均須完全真實，是在普通法最高誠信基礎上的延伸，使披露標準更嚴格，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果发现保单持有人有两份保险提供财产上的保障(例如盗窃),以下哪情况是 正确:",o:["保单持有人可以得到双倍赔偿","因为可能涉及欺诈,两份保单都不会作出赔偿","只有第一份购买的保单会承担所有赔偿","两份保单会共同分担赔偿"],a:3,e:"双重保险下，两份保单会按分担原则共同承担赔偿，被保险人只能获一次与实际损失相当的赔偿，不能获得双倍赔偿，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果發現保單持有人有兩份保險提供財產上的保障(例如盜竊)，以下哪情況是 正確：",o:["保單持有人可以得到雙倍賠償","因為可能涉及欺詐，兩份保單都不會作出賠償","只有第一份購買的保單會承擔所有賠償","兩份保單會共同分擔賠償"],e:"雙重保險下，兩份保單會按分擔原則共同承擔賠償，被保險人只能獲一次與實際損失相當的賠償，不能獲得雙倍賠償，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果只有单一成因,请问以下哪项损失是受保的?",o:["受保危险","除外危险","不保危险","非除外危险"],a:0,e:"单一成因时，仅受保危险造成的损失可获得保障；除外危险及不保危险造成的损失不受保，故答案为受保危险。",src:1,tw:{ch:"保險原則",q:"如果只有單一成因，請問以下哪項損失是受保的？",o:["受保危險","除外危險","不保危險","非除外危險"],e:"單一成因時，僅受保危險造成的損失可獲得保障；除外危險及不保危險造成的損失不受保，故答案為受保危險。"}},
{p:1,ch:"保险原则",q:"如果投保人为自己的财产投买了两份保障(例如盗窃),在合法的情况下:",o:["投保人可以得到双倍赔偿","因为可能是欺诈,两份保单都得不到赔偿","只有第一份购买的保单会承担所有赔偿","该两间保险公司均需分担有关的损失"],a:3,e:"就同一财产投保两份保险时，合法情况下由两间保险公司按分担原则共同分担损失，被保险人不能获得双倍赔偿，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果投保人為自己的財產投買了兩份保障(例如盜竊)，在合法的情況下：",o:["投保人可以得到雙倍賠償","因為可能是欺詐，兩份保單都得不到賠償","只有第一份購買的保單會承擔所有賠償","該兩間保險公司均需分擔有關的損失"],e:"就同一財產投保兩份保險時，合法情況下由兩間保險公司按分擔原則共同分擔損失，被保險人不能獲得雙倍賠償，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果投保人违反最高诚信:",o:["保险人可不作追究","除非牵涉欺诈成份,保险人才可得到补救","除非牵涉欺诈或疏忽成份,保险人才可得到补救","保单会自动取消"],a:0,e:"违反最高诚信后，保险人可选择不追究（放弃补救），合约可继续有效；并非必须在有欺诈或疏忽时才有补救或保单自动取消，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果投保人違反最高誠信:",o:["保險人可不作追究","除非牽涉欺詐成份，保險人才可得到補救","除非牽涉欺詐或疏忽成份，保險人才可得到補救","保單會自動取消"],e:"違反最高誠信後，保險人可選擇不追究（放棄補救），合約可繼續有效；並非必須在有欺詐或疏忽時才有補救或保單自動取消，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果汽车在意外中损毁,保险人虽已作出全额赔偿,但仍需考虑汽车残骸的 任何剩余价值,该残骸如以2000元售出,该残骸的价值:",o:["应全数属于被保险人","应全数属于保险人","应在下一次保费扣除","包括在以后任何一项赔偿中"],a:1,e:"保险人已作全额赔偿后取得代位权，汽车残骸（损余）归保险人所有，出售所得归保险人；被保险人已获全赔不得再主张，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果汽車在意外中損毀，保險人雖已作出全額賠償，但仍需考慮汽車殘骸的 任何剩餘價值，該殘骸如以2000元售出，該殘骸的價值：",o:["應全數屬於被保險人","應全數屬於保險人","應在下一次保費扣除","包括在以後任何一項賠償中"],e:"保險人已作全額賠償後取得代位權，汽車殘骸（損餘）歸保險人所有，出售所得歸保險人；被保險人已獲全賠不得再主張，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果汽车在意外中损毁,保险人虽已作出全额赔偿,但仍需考虑汽车残骸的 任何剩余价值。该残骸:",o:["应全数属于被保险人","应全数属于保险人","应在下一次保费中扣除","包括在以后任何一项赔偿中"],a:1,e:"全额赔偿后，残骸的剩余价值属保险人所有，出售残骸所得归保险人；被保险人已获全数赔偿，无权再分取残骸价值，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如果汽車在意外中損毁，保險人雖已作出全額賠償，但仍需考慮汽車殘骸的 任何剩餘價值。該殘骸：",o:["應全數屬於被保險人","應全數屬於保險人","應在下一次保費中扣除","包括在以後任何一項賠償中"],e:"全額賠償後，殘骸的剩餘價值屬保險人所有，出售殘骸所得歸保險人；被保險人已獲全數賠償，無權再分取殘骸價值，故答案為此項。"}},
{p:1,ch:"保险原则",q:"如果被保人拥有两份保障相同损失的弥偿保单,厘定如何在两者分配损失的 保险原则为:",o:["弥偿","分担","最高诚信","可保权益"],a:1,e:"两份保单保障同一损失时，按分担原则厘定两保险人各自承担的赔偿比例；最高诚信与可保权益与分配机制无关，故答案为分担。",src:1,tw:{ch:"保險原則",q:"如果被保人擁有兩份保障相同損失的彌償保單，釐定如何在兩者分配損失的 保險原則為：",o:["彌償","分擔","最高誠信","可保權益"],e:"兩份保單保障同一損失時，按分擔原則釐定兩保險人各自承擔的賠償比例；最高誠信與可保權益與分配機制無關，故答案為分擔。"}},
{p:1,ch:"保险原则",q:"如果被保险人投买了两份保障相同损失的火险保单,对赔偿额分配的有关原 则是:",o:["分担","可保权益","最高诚信","弥偿"],a:0,e:"双重火险保单对同一损失的赔偿额分配，适用分担原则，由各保险人按各自责任比例承担，避免超额赔偿，故答案为分担。",src:1,tw:{ch:"保險原則",q:"如果被保險人投買了兩份保障相同損失的火險保單，對賠償額分配的有關原 則是：",o:["分擔","可保權益","最高誠信","彌償"],e:"雙重火險保單對同一損失的賠償額分配，適用分擔原則，由各保險人按各自責任比例承擔，避免超額賠償，故答案為分擔。"}},
{p:1,ch:"保险原则",q:"如被保险人违反最高诚信,保险人可以:",o:["推翻合约及退回保费","拒绝作出赔偿","如涉及诈骗,可向被保险人以侵权法为由追索损害赔偿","上述 (a) 及 (c)"],a:3,e:"被保险人违反最高诚信，保险人可推翻合约并退回保费；若涉及诈骗，还可凭侵权法向被保险人追索损害赔偿，故答案为 (a) 及 (c)。",src:1,tw:{ch:"保險原則",q:"如被保險人違反最高誠信，保險人可以：",o:["推翻合約及退回保費","拒絕作出賠償","如涉及詐騙，可向被保險人以侵權法為由追索損害賠償","上述 (a) 及 (c)"],e:"被保險人違反最高誠信，保險人可推翻合約並退回保費；若涉及詐騙，還可憑侵權法向被保險人追索損害賠償，故答案為 (a) 及 (c)。"}},
{p:1,ch:"保险原则",q:"如被保险人违反最高诚信,保险人可以: i 推翻合约及退回保费 ii 如涉及诈骗,可从民事诉讼要求损害赔偿金 iii 拒绝作出赔偿 iv 不再追究违反,合约继续生效",o:["i, ii","i, iii","i, ii, iv","ii, iii, iv"],a:2,e:"违反最高诚信时，保险人可推翻合约并退回保费、涉及诈骗时可民事追讨损害赔偿，或选择不追究令合约继续生效；「拒绝作出赔偿」不在此列，故正确组合为 i、ii、iv。",src:1,tw:{ch:"保險原則",q:"如被保險人違反最高誠信，保險人可以： i 推翻合約及退回保費 ii 如涉及詐騙，可從民事訴訟要求損害賠償金 iii 拒絕作出賠償 iv 不再追究違反，合約繼續生效",o:["i, ii","i, iii","i, ii, iv","ii, iii, iv"],e:"違反最高誠信時，保險人可推翻合約並退回保費、涉及詐騙時可民事追討損害賠償，或選擇不追究令合約繼續生效；「拒絕作出賠償」不在此列，故正確組合為 i、ii、iv。"}},
{p:1,ch:"保险原则",q:"如该保单是以定值作索偿,下列哪项损失赔偿为正确?",o:["全损情况下按实际价值赔偿","需要考虑折旧因素","无论实际价值如何,根据约定价值赔偿","无论损失多少也会得到十足的赔偿"],a:2,e:"定值（约定价值）保单不论损失发生时的实际价值如何，均按订约约定的价值赔偿，无需重新估价或考虑折旧，故答案为此项。",src:1,tw:{ch:"保險原則",q:"如該保單是以定值作索償，下列哪項損失賠償為正確？",o:["全損情況下按實際價值賠償","需要考慮折舊因素","無論實際價值如何，根據約定價值賠償","無論損失多少也會得到十足的賠償"],e:"定值（約定價值）保單不論損失發生時的實際價值如何，均按訂約約定的價值賠償，無需重新估價或考慮折舊，故答案為此項。"}},
{p:1,ch:"保险原则",q:"容许保险人给付赔偿后,为本身的利益承继及使用被保险人向第三者索偿权 利,这是哪项保险原则:",o:["分担","代位权","重复保险","最高诚信"],a:1,e:"保险人赔偿后取得被保险人向第三者追偿的权利，称为代位权；分担、重复保险、最高诚信均不同，故答案为代位权。",src:1,tw:{ch:"保險原則",q:"容許保險人給付賠償後，為本身的利益承繼及使用被保險人向第三者索償權 利，這是哪項保險原則：",o:["分擔","代位權","重覆保險","最高誠信"],e:"保險人賠償後取得被保險人向第三者追償的權利，稱為代位權；分擔、重複保險、最高誠信均不同，故答案為代位權。"}},
{p:1,ch:"保险原则",q:"导致损失的成因均称为危险,近因应注意的危险为: i 受保危险 ii 不保危险 iii 除外危险 iv 额外危险",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"近因考察的危险为受保危险、不保危险及除外危险三类；「额外危险」并非标准类别，故正确组合为 i、ii、iii。",src:1,tw:{ch:"保險原則",q:"導致損失的成因均稱為危險，近因應注意的危險為： i 受保危險 ii 不保危險 iii 除外危險 iv 額外危險",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"近因考察的危險為受保危險、不保危險及除外危險三類；「額外危險」並非標準類別，故正確組合為 i、ii、iii。"}},
{p:1,ch:"保险原则",q:"就人寿保险而言,对以下哪类人士并无可保权益?",o:["保单持有人本身","保单持有人的商业伙伴","保单持有人的前度配偶(离婚后)","保单持有人的贷款欠款人"],a:2,e:"就人寿保险而言，对自己、商业伙伴及欠款债务人具有可保权益；离婚后的前度配偶已无财务关联，对其生命无可保权益，故答案为此项。",src:1,tw:{ch:"保險原則",q:"就人壽保險而言，對以下哪類人士並無可保權益？",o:["保單持有人本身","保單持有人的商業夥伴","保單持有人的前度配偶(離婚後)","保單持有人的貸款欠款人"],e:"就人壽保險而言，對自己、商業夥伴及欠款債務人具有可保權益；離婚後的前度配偶已無財務關聯，對其生命無可保權益，故答案為此項。"}},
{p:1,ch:"保险原则",q:"就保险而言,普通法规定当提供弥偿后,可取得代位权。非水险保单条件:",o:["从不可改变普通法的规定","在法律上不得更改普通法的规定","只当就索偿结清达成协定后方给予保险人代位权","通常即时给予保险人代位权,以便马上展开追偿行动"],a:3,e:"普通法须在弥偿后才取得代位权，但非水险保单条件通常即时授予保险人代位权，以便尽早展开追偿行动，故答案为此项。",src:1,tw:{ch:"保險原則",q:"就保險而言，普通法規定當提供彌償後，可取得代位權。非水險保單條件：",o:["從不可改變普通法的規定","在法律上不得更改普通法的規定","只當就索償結清達成協定後方給予保險人代位權","通常即時給予保險人代位權，以便馬上展開追償行動"],e:"普通法須在彌償後才取得代位權，但非水險保單條件通常即時授予保險人代位權，以便儘早展開追償行動，故答案為此項。"}},
{p:1,ch:"保险原则",q:"就保险而言,非欺诈性不披露:",o:["等同于无意地违反保证","如属投保人行为,在技术上则容许保险人推翻合约","属于违反最高诚信,只容许受屈的一方作出损害赔偿","是指投保人漫不经心的情况对重要事实的失实陈述"],a:1,e:"非欺诈性不披露虽无欺骗意图，但在技术上仍属违反最高诚信，容许保险人推翻合约；并非仅可索赔损害或等同无意违反保证，故答案为此项。",src:1,tw:{ch:"保險原則",q:"就保險而言，非欺詐性不披露：",o:["等同於無意地違反保證","如屬投保人行為，在技術上則容許保險人推翻合約","屬於違反最高誠信，只容許受屈的一方作出損害賠償","是指投保人漫不經心的情況對重要事實的失實陳述"],e:"非欺詐性不披露雖無欺騙意圖，但在技術上仍屬違反最高誠信，容許保險人推翻合約；並非僅可索賠損害或等同無意違反保證，故答案為此項。"}},
{p:1,ch:"保险原则",q:"就保险金权利转让,意思是:",o:["必须就保险单应支付的金钱转予指定的第三者","把保单转让于另一家保险公司","把保单拥有权转让予他人","让另一人代替原本的被保险人"],a:0,e:"保险金权利转让，指将保单应付的保险金转予指定的第三者，而非转让保单拥有权、转给另一保险公司或更换被保险人，故答案为此项。",src:1,tw:{ch:"保險原則",q:"就保險金權利轉讓，意思是：",o:["必須就保險單應支付的金錢轉予指定的第三者","把保單轉讓於另一家保險公司","把保單擁有權轉讓予他人","讓另一人代替原本的被保險人"],e:"保險金權利轉讓，指將保單應付的保險金轉予指定的第三者，而非轉讓保單擁有權、轉給另一保險公司或更換被保險人，故答案為此項。"}},
{p:1,ch:"保险原则",q:"就最高诚信的责任而言,以下哪些对重要事实的陈述是正确的? i 它会影响审慎的承保人在某些方面的判断 ii 它只适用于涉及实质物件的保险 iii 它只影响订立保费 iv 改善风险的事实毋须披露",o:["i, ii","i, iii","i, iv","ii, iv"],a:2,e:"重要事实会影响审慎承保人对是否承保及条件的判断，而改善风险的事实则毋须披露；重要事实不限于实物保险、也非只影响保费，故正确为 i、iv。",src:1,tw:{ch:"保險原則",q:"就最高誠信的責任而言，以下哪些對重要事實的陳述是正確的？ i 它會影響審慎的承保人在某些方面的判斷 ii 它只適用於涉及實質物件的保險 iii 它只影響訂立保費 iv 改善風險的事實毋須披露",o:["i, ii","i, iii","i, iv","ii, iv"],e:"重要事實會影響審慎承保人對是否承保及條件的判斷，而改善風險的事實則毋須披露；重要事實不限於實物保險、也非隻影響保費，故正確為 i、iv。"}},
{p:1,ch:"保险原则",q:"就近因而言,以下哪项陈述是正确?",o:["要构成有效的索偿,近因必须不属于不保危险","由除外危险单独造成的损失不可获得赔偿","由自然地来自一项除外危险的不保危险导致的损失是可以获得保障的","以上各项所有"],a:1,e:"近因原则下，由除外危险独立造成的损失不获赔偿；选项一仅强调非不保危险、未涵盖须为受保危险，选项三称除外危险衍生损失可获保障为错误，故答案为「由除外危险单独造成的损失不可获得赔偿」。",src:1,tw:{ch:"保險原則",q:"就近因而言，以下哪項陳述是正確？",o:["要構成有效的索償，近因必須不屬於不保危險","由除外危險單獨造成的損失不可獲得賠償","由自然地來自一項除外危險的不保危險導致的損失是可以獲得保障的","以上各項所有"],e:"近因原則下，由除外危險獨立造成的損失不獲賠償；選項一僅強調非不保危險、未涵蓋須為受保危險，選項三稱除外危險衍生損失可獲保障為錯誤，故答案為「由除外危險單獨造成的損失不可獲得賠償」。"}},
{p:1,ch:"保险原则",q:"弥偿与可保权益之联系为:",o:["完全无关","近乎一样","皆与近因原则有密切关系","有共同基础,建基于受保人之财产权益上"],a:3,e:"弥偿与可保权益有共同基础，均建基于被保险人对受保标的的财务权益之上，二者紧密相连而非无关或等同。",src:1,tw:{ch:"保險原則",q:"彌償與可保權益之聯繫為：",o:["完全無關","近乎一樣","皆與近因原則有密切關係","有共同基礎，建基於受保人之財產權益上"],e:"彌償與可保權益有共同基礎，均建基於被保險人對受保標的的財務權益之上，二者緊密相連而非無關或等同。"}},
{p:1,ch:"保险原则",q:"弥偿与可保权益这两项保险原则:",o:["是完全相同的","是毫不相干的","与近因原则的关系非常密切","皆有共同的基础,因为它们均涉及被保险人的财务权益"],a:3,e:"弥偿与可保权益虽各有内涵，但皆有共同基础——涉及被保险人的财务权益，并非完全相同或毫不相干，故答案为此项。",src:1,tw:{ch:"保險原則",q:"彌償與可保權益這兩項保險原則：",o:["是完全相同的","是毫不相干的","與近因原則的關係非常密切","皆有共同的基礎，因為它們均涉及被保險人的財務權益"],e:"彌償與可保權益雖各有內涵，但皆有共同基礎——涉及被保險人的財務權益，並非完全相同或毫不相干，故答案為此項。"}},
{p:1,ch:"保险原则",q:"弥偿是指当损失出现时,对损失作出:",o:["长远具持续的补偿","精确补偿","50%的补偿","有限度的补偿"],a:1,e:"弥偿指对损失作出精确的补偿，使被保险人恢复至损失前的财务状况，而非持续、50%或有限度的补偿，故答案为精确补偿。",src:1,tw:{ch:"保險原則",q:"彌償是指當損失出現時，對損失作出：",o:["長遠具持續的補償","精確補償","50%的補償","有限度的補償"],e:"彌償指對損失作出精確的補償，使被保險人恢復至損失前的財務狀況，而非持續、50%或有限度的補償，故答案為精確補償。"}},
{p:1,ch:"保险原则",q:"弥偿需要同时符合以下哪项原则?",o:["代位","分担","可保权益","以上皆是"],a:3,e:"弥偿原则的实施需要可保权益为前提，并以代位权及分担防止超额赔偿，三者共同支撑弥偿，故「以上皆是」。",src:1,tw:{ch:"保險原則",q:"彌償需要同時符合以下哪項原則?",o:["代位","分擔","可保權益","以上皆是"],e:"彌償原則的實施需要可保權益為前提，並以代位權及分擔防止超額賠償，三者共同支撐彌償，故「以上皆是」。"}},
{p:1,ch:"保险原则",q:"当第三者一方出现疏忽后,下列哪项情况不会产生代位权: i 被保人离世(人寿保险) ii 受保财产在火灾中损毁(火险) iii 被保人在意外中受伤(人身意外保险) iv 汽车在事故中损毁(车保)",o:["i, ii","i, iii","ii, iii","ii, iv"],a:1,e:"人寿保险及人身意外保险属利益保单，一般不产生代位权；火险及车险属弥偿保单，第三者疏忽时可行使代位权，故不会产生代位权的为 i、iii。",src:1,tw:{ch:"保險原則",q:"當第三者一方出現疏忽後，下列哪項情況不會產生代位權： i 被保人離世（人壽保險） ii 受保財產在火災中損毀（火險） iii 被保人在意外中受傷（人身意外保險） iv 汽車在事故中損毀（車保）",o:["i, ii","i, iii","ii, iii","ii, iv"],e:"人壽保險及人身意外保險屬利益保單，一般不產生代位權；火險及車險屬彌償保單，第三者疏忽時可行使代位權，故不會產生代位權的為 i、iii。"}},
{p:1,ch:"保险原则",q:"当被保险人提出索偿时,将损余部份交予保险人以换取全数赔偿。当保险人 出售该损余后,该笔款项:",o:["保险人得到不俗的额外利益","保险人及被保险人各占50%","全数交予政府","全数交予被保险人(因保险人不可得到其利益)"],a:0,e:"被保险人委付损余以换取全赔后，损余归保险人，出售所得（即使超出赔偿额）亦归保险人所有，故答案为此项。",src:1,tw:{ch:"保險原則",q:"當被保險人提出索償時，將損餘部份交予保險人以換取全數賠償。當保險人 出售該損餘後，該筆款項：",o:["保險人得到不俗的額外利益","保險人及被保險人各佔50%","全數交予政府","全數交予被保險人（因保險人不可得到其利益）"],e:"被保險人委付損餘以換取全賠後，損餘歸保險人，出售所得（即使超出賠償額）亦歸保險人所有，故答案為此項。"}},
{p:1,ch:"保险原则",q:"必须符合以下哪些条件,才可以应用分担?",o:["每张保单必须属非弥偿保单","每张保单必须有相同的条款及相同的保额","每张保单都必须保障一套相同的危险","每张保单均保障受影响的权益"],a:3,e:"应用分担的核心条件是每张保单均保障受影响的相同权益，且各自对该损失负赔偿责任；要求条款及保额相同或属非弥偿保单的说法均不正确，故答案为此项。",src:1,tw:{ch:"保險原則",q:"必須符合以下哪些條件，才可以應用分擔？",o:["每張保單必須屬非彌償保單","每張保單必須有相同的條款及相同的保額","每張保單都必須保障一套相同的危險","每張保單均保障受影響的權益"],e:"應用分擔的核心條件是每張保單均保障受影響的相同權益，且各自對該損失負賠償責任；要求條款及保額相同或屬非彌償保單的說法均不正確，故答案為此項。"}},
{p:1,ch:"保险原则",q:"投保人投保一份12个月的火险保单,投保人忘记了披露某些重要事实,保单 的总保费为12,000元;保险人在一个月后发现,保险人可以作出怎样的处理?",o:["保险人可以推翻保险合约","保险人可以推翻保险合约,并退回所有保费","保险人可以推翻保险合约,并只收取一个月保费,即1,000元","在没有披露重要事实当天,保险合约被视为取消生效,并收取所有保费"],a:1,e:"投保人无意不披露重要事实属非欺诈性不披露，保险人可推翻合约并退回全部保费；因无欺诈，不需没收保费或仅收一个月保费，故答案为此项。",src:1,tw:{ch:"保險原則",q:"投保人投保一份12個月的火險保單，投保人忘記了披露某些重要事實，保單 的總保費為12,000元；保險人在一個月後發現，保險人可以作出怎樣的處理?",o:["保險人可以推翻保險合約","保險人可以推翻保險合約，並退回所有保費","保險人可以推翻保險合約，並只收取一個月保費，即1,000元","在沒有披露重要事實當天，保險合約被視為取消生效，並收取所有保費"],e:"投保人無意不披露重要事實屬非欺詐性不披露，保險人可推翻合約並退回全部保費；因無欺詐，不需沒收保費或僅收一個月保費，故答案為此項。"}},
{p:1,ch:"保险原则",q:"损余出现时,若被保险人保留损余,保险人会从赔偿中扣除损余之价值;若 被保险人不保留损余,以下哪种情况会出现?",o:["合约便失去效力","保险人可拒绝赔偿","保险人可要求被保险人出售损余","被保险人将损余交予保险人,以求全数索偿"],a:3,e:"被保险人不保留损余时，可将损余交予保险人，以换取全数赔偿；并非合约失效、保险人拒绝赔偿或要求被保险人出售，故答案为此项。",src:1,tw:{ch:"保險原則",q:"損餘出現時，若被保險人保留損餘，保險人會從賠償中扣除損餘之價值；若 被保險人不保留損餘，以下哪種情況會出現？",o:["合約便失去效力","保險人可拒絕賠償","保險人可要求被保險人出售損餘","被保險人將損餘交予保險人，以求全數索償"],e:"被保險人不保留損餘時，可將損餘交予保險人，以換取全數賠償；並非合約失效、保險人拒絕賠償或要求被保險人出售，故答案為此項。"}},
{p:1,ch:"保险原则",q:"更换一项损毁或失去的受保物件,可以作为一种提供弥偿的形式。这种安排 适合以下哪项情况?",o:["当盗窃是导致损失的近因时","各式各样的索偿","仅于汽车保险而已","完全没有或只有少量折旧的部份"],a:3,e:"以更换提供弥偿，适合几乎没有折旧或折旧很少的物件，因更换能充分恢复其损失前价值；并非适用于一切索偿或仅限汽车保险，故答案为此项。",src:1,tw:{ch:"保險原則",q:"更換一項損毀或失去的受保物件，可以作為一種提供彌償的形式。這種安排 適合以下哪項情況？",o:["當盜竊是導致損失的近因時","各式各樣的索償","僅於汽車保險而已","完全沒有或只有少量折舊的部份"],e:"以更換提供彌償，適合幾乎沒有折舊或折舊很少的物件，因更換能充分恢復其損失前價值；並非適用於一切索償或僅限汽車保險，故答案為此項。"}},
{p:1,ch:"保险原则",q:"更换是对摧毁或遗失的受保物件的一种损害赔偿的形式,以下哪项可使用此 形式?",o:["每类的索偿","完全没有或只有少量折旧的物件","仅在汽车损毁的索偿","近因是盗窃损害的"],a:1,e:"更换的弥偿方式适用于完全没有或仅有少量折旧的物件，这样更换足以恢复损失前状况；各类索偿或仅限汽车的说法不正确，故答案为此项。",src:1,tw:{ch:"保險原則",q:"更換是對摧毁或遺失的受保物件的一種損害賠償的形式，以下哪項可使用此 形式？",o:["每類的索償","完全沒有或只有少量折舊的物件","僅在汽車損毁的索償","近因是盜竊損害的"],e:"更換的彌償方式適用於完全沒有或僅有少量折舊的物件，這樣更換足以恢復損失前狀況；各類索償或僅限汽車的說法不正確，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有一名男子在人身保险保单及汽车保单投保了意外死亡保险,如果该男子驾 驶自己的汽车发生意外事故而死亡?",o:["仅仅首先生效的保单利益作全额赔偿","两份保单须将死亡利益全数额赔偿","仅仅保额最大的保单作赔偿全数死亡利益","由于死亡发生是汽车意外事故所造成,所以仅仅汽车保单作出全额赔偿"],a:1,e:"人身保险及汽车保单中的意外死亡利益均为利益给付，两者均须全额赔偿死亡利益，不互相抵扣，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有一名男子在人身保險保單及汽車保單投保了意外死亡保險，如果該男子駕 駛自己的汽車發生意外事故而死亡？",o:["僅僅首先生效的保單利益作全額賠償","兩份保單須將死亡利益全數額賠償","僅僅保額最大的保單作賠償全數死亡利益","由於死亡發生是汽車意外事故所造成，所以僅僅汽車保單作出全額賠償"],e:"人身保險及汽車保單中的意外死亡利益均為利益給付，兩者均須全額賠償死亡利益，不互相抵扣，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有两种保险合约被视为可以自由转让的,它们是:",o:["人寿与火险","人寿与水险","水险与公众责任","水险与忠实保险"],a:1,e:"人寿保险与海上货物（水险货物）保险可无须保险人同意而自由转让，其余如公众责任、忠实保险等须获同意，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有兩種保險合約被視為可以自由轉讓的，它們是：",o:["人壽與火險","人壽與水險","水險與公眾責任","水險與忠實保險"],e:"人壽保險與海上貨物（水險貨物）保險可無須保險人同意而自由轉讓，其餘如公眾責任、忠實保險等須獲同意，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有些保单条款允许多于严格弥偿的赔偿,以下哪项不属于这个范围之内:",o:["比例分摊","约定价值保单","重置保险","以新代旧"],a:0,e:"约定价值保单、重置保险及以新代旧均属可超逾严格弥偿赔偿的安排；比例分摊是对不足额保险的减赔机制，不属于此类，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有些保單條款允許多於嚴格彌償的賠償，以下哪項不屬於這個範圍之內：",o:["比例分攤","約定價值保單","重置保險","以新代舊"],e:"約定價值保單、重置保險及以新代舊均屬可超逾嚴格彌償賠償的安排；比例分攤是對不足額保險的減賠機制，不屬於此類，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有关一项索偿,是由一宗(受火险保单保障)意外火灾而导致的。在火灾发生的 过程中,消防员为了进入建筑物通道及用水扑救火灾,而进一步引致损失, 就近因的规则而言,消防员的努力而引致的损失:",o:["只有50%的保障,因真正导致损失的是该火灾","因由一项非受保危险导致的,故此得不到保障","是由一项受保危险而引致的不保危险,故此得到保障","只有由火险保单伸展到该危险风险时才能得到保障"],a:2,e:"消防员救火所造成的水损，属由受保危险（火灾）直接产生的不保危险，按近因原则仍获保障；并非仅50%保障或须额外伸展条款，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有關一項索償，是由一宗(受火險保單保障)意外火災而導致的。在火災發生的 過程中，消防員為了進入建築物通道及用水撲救火災，而進一步引致損失， 就近因的規則而言，消防員的努力而引致的損失：",o:["只有50%的保障，因真正導致損失的是該火災","因由一項非受保危險導致的，故此得不到保障","是由一項受保危險而引致的不保危險，故此得到保障","只有由火險保單伸展到該危險風險時才能得到保障"],e:"消防員救火所造成的水損，屬由受保危險（火災）直接產生的不保危險，按近因原則仍獲保障；並非僅50%保障或須額外伸展條款，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有别于最高诚信,一般诚信是指由各方提供的资料?",o:["必须大致真实","必须绝对真实且没有遗漏任何重要事实","可以是真实或虚假,所以不应信赖","必须实质上真实,但没有主动的责任披露每项事实"],a:3,e:"一般诚信要求提供的资料实质上真实即可，但无主动披露每项事实的积极责任；绝对真实、无遗漏及必须大致真实等描述均不准确，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有別於最高誠信，一般誠信是指由各方提供的資料?",o:["必須大致真實","必須絕對真實且沒有遺漏任何重要事實","可以是真實或虛假，所以不應信賴","必須實質上真實，但沒有主動的責任披露每項事實"],e:"一般誠信要求提供的資料實質上真實即可，但無主動披露每項事實的積極責任；絕對真實、無遺漏及必須大致真實等描述均不準確，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有别于最高诚信,一般诚信要求:",o:["保证所作出的陈述是百分百真实","不论有否被问及,以须陈述","应用于整个保险合约过程","忠实并确保所有陈述是实质上真实"],a:3,e:"一般诚信只要求当事人忠实并确保陈述实质真实，并无百分百真实或主动披露所有事实的义务，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有別於最高誠信，一般誠信要求：",o:["保證所作出的陳述是百分百真實","不論有否被問及，以須陳述","應用於整個保險合約過程","忠實並確保所有陳述是實質上真實"],e:"一般誠信只要求當事人忠實並確保陳述實質真實，並無百分百真實或主動披露所有事實的義務，故答案為此項。"}},
{p:1,ch:"保险原则",q:"有别于最高诚信,一般诚信要求有关各方:",o:["保证他们作出的每项陈述均是百分百真实","不论有否被问及也要披露所有重要事实","担保他们没有遗漏任何对有关合约的重要事实","忠诚及确保将要提供给对方的资料在实质上真实"],a:3,e:"一般诚信要求各方忠诚并确保提供的资料在实质上真实，而无须主动披露所有重要事实或保证百分百真实，故答案为此项。",src:1,tw:{ch:"保險原則",q:"有別於最高誠信，一般誠信要求有關各方：",o:["保證他們作出的每項陳述均是百分百真實","不論有否被問及也要披露所有重要事實","擔保他們沒有遺漏任何對有關合約的重要事實","忠誠及確保將要提供給對方的資料在實質上真實"],e:"一般誠信要求各方忠誠並確保提供的資料在實質上真實，而無須主動披露所有重要事實或保證百分百真實，故答案為此項。"}},
{p:1,ch:"保险原则",q:"权益保单不适用于弥偿的原则,因为:",o:["权益的定义是可大可小难以厘定","这是保险公司所定的法定条例","权益保单是涉及人寿及人身意外故此是不适用","弥偿与权益保单完全谈不上"],a:2,e:"权益保单涉及人寿及人身意外，人的生命与健康难以货币精确衡量，无法适用弥偿原则，故答案为此项。",src:1,tw:{ch:"保險原則",q:"權益保單不適用於彌償的原則，因為：",o:["權益的定義是可大可小難以釐定","這是保險公司所定的法定條例","權益保單是涉及人壽及人身意外故此是不適用","彌償與權益保單完全談不上"],e:"權益保單涉及人壽及人身意外，人的生命與健康難以貨幣精確衡量，無法適用彌償原則，故答案為此項。"}},
{p:1,ch:"保险原则",q:"某些情况下向保险人交出保险标的,作为全损的赔偿金额的条件,这情况称 为?",o:["损余","委付","弥偿","代位"],a:1,e:"被保险人将保险标的交出保险人以换取全损赔偿，称为委付；损余、弥偿、代位均为不同概念，故答案为此项。",src:1,tw:{ch:"保險原則",q:"某些情況下向保險人交出保險標的，作為全損的賠償金額的條件，這情況稱 為？",o:["損餘","委付","彌償","代位"],e:"被保險人將保險標的交出保險人以換取全損賠償，稱為委付；損餘、彌償、代位均為不同概念，故答案為此項。"}},
{p:1,ch:"保险原则",q:"某人于购买保险时,把某些事情误作为不须披露的事实而没有作出披露,但 其后法庭听证会上法官则持相反看法。在此情况下,某人可能违反最高诚信 的﹕",o:["欺诈性不披露","非欺诈性不披露","欺诈性失实陈述","非欺诈性失实陈述"],a:1,e:"投保人误以为某事实毋须披露而未披露，属无意的不披露，即非欺诈性不披露；并无欺骗意图，亦非失实陈述，故答案为此项。",src:1,tw:{ch:"保險原則",q:"某人於購買保險時，把某些事情誤作為不須披露的事實而沒有作出披露，但 其後法庭聽證會上法官則持相反看法。在此情況下，某人可能違反最高誠信 的﹕",o:["欺詐性不披露","非欺詐性不披露","欺詐性失實陳述","非欺詐性失實陳述"],e:"投保人誤以為某事實毋須披露而未披露，屬無意的不披露，即非欺詐性不披露；並無欺騙意圖，亦非失實陳述，故答案為此項。"}},
{p:1,ch:"保险原则",q:"某人于购买保险时,没有说出重要事实,是因为怕保险人拒绝受保。在此情 况下,某人可能违反最高诚信的﹕",o:["欺诈性不披露","非欺诈性不披露","欺诈性失实陈述","非欺诈性失实陈述"],a:0,e:"因担心被拒保而故意隐瞒重要事实，具欺骗意图，构成欺诈性不披露；并非无意遗漏或失实陈述，故答案为此项。",src:1,tw:{ch:"保險原則",q:"某人於購買保險時，沒有說出重要事實，是因為怕保險人拒絕受保。在此情 況下，某人可能違反最高誠信的﹕",o:["欺詐性不披露","非欺詐性不披露","欺詐性失實陳述","非欺詐性失實陳述"],e:"因擔心被拒保而故意隱瞞重要事實，具欺騙意圖，構成欺詐性不披露；並非無意遺漏或失實陳述，故答案為此項。"}},
{p:1,ch:"保险原则",q:"某部电视机在火灾损害的时候已经使用了5年,在该损害所导致的维修费为 $6000,有关的家居保险人有负责全额赔付,由此可推算该保单是以下哪种 形式订立?",o:["「以旧代新」形式","重置保险","「以新代旧」形式","不扣减形式"],a:2,e:"已使用5年的电视机出险，保险人未扣折旧而全额赔偿维修费，显示保单采「以新代旧」形式；若采严格弥偿则会扣除折旧，故答案为此项。",src:1,tw:{ch:"保險原則",q:"某部電視機在火災損害的時候已經使用了5年，在該損害所導致的維修費為 $6000，有關的家居保險人有負責全額賠付，由此可推算該保單是以下哪種 形式訂立？",o:["「以舊代新」形式","重置保險","「以新代舊」形式","不扣減形式"],e:"已使用5年的電視機出險，保險人未扣折舊而全額賠償維修費，顯示保單採「以新代舊」形式；若採嚴格彌償則會扣除折舊，故答案為此項。"}},
{p:1,ch:"保险原则",q:"根据比例分摊的条款:",o:["购买不足的保障额,并不是重要的问题","保险人会根据不足的投保额,不会提供十足的赔付","投保足够的保费,保险人会提供十足的赔付","这是标准风险,受标准风险条款约束"],a:1,e:"比例分摊条款下，若投保额不足，保险人按不足比例承担，不会作十足赔付；保额足够时才十足赔付，不足额并非不重要，故答案为此项。",src:1,tw:{ch:"保險原則",q:"根據比例分攤的條款:",o:["購買不足的保障額，並不是重要的問題","保險人會根據不足的投保額，不會提供十足的賠付","投保足夠的保費，保險人會提供十足的賠付","這是標準風險，受標準風險條款約束"],e:"比例分攤條款下，若投保額不足，保險人按不足比例承擔，不會作十足賠付；保額足夠時才十足賠付，不足額並非不重要，故答案為此項。"}},
{p:1,ch:"保险原则",q:"根据近因的一般原则,当雷电导致火警的话,下列哪类的损毁可按商业火险 得到保障? i 电极造成的损毁 ii 有关火警对建筑物造成的损毁 iii 浓烟对存货造成的损毁,然而货物未有被火烧毁 iv 因尝试以水救火而对建筑物造成的损毁",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"雷电属火险承保危险，其直接造成的损毁、火警烧毁建筑物、浓烟损坏存货及救火用水造成的损毁，均近因于雷电或火灾，四项均可获保障。",src:1,tw:{ch:"保險原則",q:"根據近因的一般原則，當雷電導致火警的話，下列哪類的損毀可按商業火險 得到保障？ i 電極造成的損毀 ii 有關火警對建築物造成的損毀 iii 濃煙對存貨造成的損毀，然而貨物未有被火燒毀 iv 因嘗試以水救火而對建築物造成的損毀",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"雷電屬火險承保危險，其直接造成的損毀、火警燒燬建築物、濃煙損壞存貨及救火用水造成的損毀，均近因於雷電或火災，四項均可獲保障。"}},
{p:1,ch:"保险原则",q:"欺诈性失实陈述和非欺诈性失实陈述有什么共同/分别之处? i 欺诈性失实陈述涉及并非知情欺骗,非欺诈性失实陈述涉及歪曲事实 ii 欺诈性失实陈述涉及蓄意歪曲事实,非欺诈性失实陈述涉及非知情欺骗 iii 两者同样提供虚假资料 iv 欺诈性失实陈述指蓄意保留重要资料, 非欺诈性失实陈述指非蓄意保留重要资料",o:["i, ii","ii, iii","i, iii","iii, iv"],a:1,e:"欺诈性失实陈述指蓄意提供虚假资料，非欺诈性失实陈述指无欺骗意图的失实，两者同样提供虚假资料；i 把两者颠倒、iv 混淆了不披露概念，故正确为 ii、iii。",src:1,tw:{ch:"保險原則",q:"欺詐性失實陳述和非欺詐性失實陳述有什麼共同/分別之處? i 欺詐性失實陳述涉及並非知情欺騙，非欺詐性失實陳述涉及歪曲事實 ii 欺詐性失實陳述涉及蓄意歪曲事實，非欺詐性失實陳述涉及非知情欺騙 iii 兩者同樣提供虛假資料 iv 欺詐性失實陳述指蓄意保留重要資料， 非欺詐性失實陳述指非蓄意保留重要資料",o:["i, ii","ii, iii","i, iii","iii, iv"],e:"欺詐性失實陳述指蓄意提供虛假資料，非欺詐性失實陳述指無欺騙意圖的失實，兩者同樣提供虛假資料；i 把兩者顛倒、iv 混淆了不披露概念，故正確為 ii、iii。"}},
{p:1,ch:"保险原则",q:"水险单起赔额为5%,下列哪项对损失赔偿的描述是正确的?",o:["损失超过3%则全数赔偿3%","损失超过5%则全数赔偿损失","损失超过6%则赔偿5%以外的损失","损失超过5%则只赔偿5%"],a:1,e:"起赔额（相对免赔额）规定损失达到约定比例时即全数赔偿，故水险单起赔额5%表示损失超过5%则全数赔偿损失。损失超过3%才赔3%、只赔5%以外的损失、以及仅赔5%，均混淆了起赔额与超额免赔的区别。",src:1,tw:{ch:"保險原則",q:"水險單起賠額為5%，下列哪項對損失賠償的描述是正確的？",o:["損失超過3%則全數賠償3%","損失超過5%則全數賠償損失","損失超過6%則賠償5%以外的損失","損失超過5%則只賠償5%"],e:"起賠額（相對免賠額）規定損失達到約定比例時即全數賠償，故水險單起賠額5%表示損失超過5%則全數賠償損失。損失超過3%才賠3%、只賠5%以外的損失、以及僅賠5%，均混淆了起賠額與超額免賠的區別。"}},
{p:1,ch:"保险原则",q:"法院颁令一名的士司机需向一名私家车拥有人赔偿 $10,000,000的损失, 但由于一项保单限额的限制,保险人只承担$8,000,000的赔偿,后来成功向 须为损失承担 50%责任的另一名私家车拥有人追讨 $7,000,000,请问谁有权取得赔偿?金额是多少?",o:["保险人占 $7,000,000;被保险人没份儿","保险人占 $5,000,000;被保险人占 $2,000,000","保险人没份儿,被保险人占 $7,000,000","保险人及被保险人各占百分之五十"],a:1,e:"代位追偿所得应先使被保险人获得完全弥偿。被保险人损失1,000万，保险人因保单限额只赔800万，尚欠200万未获补偿，故追回的700万中先补足被保险人200万，其余500万归保险人。其余选项把追偿全数分配给一方，违反先弥补被保险人损失的原则。",src:1,tw:{ch:"保險原則",q:"法院頒令一名的士司機需向一名私家車擁有人賠償 $10,000,000的損失， 但由於一項保單限額的限制，保險人只承擔$8,000,000的賠償，後來成功向 須為損失承擔 50%責任的另一名私家車擁有人追討 $7,000,000，請問誰有權取得賠償？金額是多少？",o:["保險人佔 $7,000,000；被保險人沒份兒","保險人佔 $5,000,000；被保險人佔 $2,000,000","保險人沒份兒，被保險人佔 $7,000,000","保險人及被保險人各佔百分之五十"],e:"代位追償所得應先使被保險人獲得完全彌償。被保險人損失1,000萬，保險人因保單限額只賠800萬，尚欠200萬未獲補償，故追回的700萬中先補足被保險人200萬，其餘500萬歸保險人。其餘選項把追償全數分配給一方，違反先彌補被保險人損失的原則。"}},
{p:1,ch:"保险原则",q:"海上保险术语average是指?",o:["部分(非全部)损失","不足额保险的惩罚","标准风险的选择","剩余保险标的的价值"],a:0,e:"海上保险术语 average（海损）指部分而非全部损失，包括共同海损与单独海损。不足额保险的惩罚、标准风险选择、剩余标的价值均与该术语含义无关。",src:1,tw:{ch:"保險原則",q:"海上保險術語average是指？",o:["部分(非全部)損失","不足額保險的懲罰","標準風險的選擇","剩餘保險標的的價值"],e:"海上保險術語 average（海損）指部分而非全部損失，包括共同海損與單獨海損。不足額保險的懲罰、標準風險選擇、剩餘標的價值均與該術語含義無關。"}},
{p:1,ch:"保险原则",q:"涉及有计划地保留重要事实,蓄意欺骗保险人的违反最高诚信的行为属于﹕",o:["欺诈性不披露","非欺诈性不披露","欺诈性失实陈述","非欺诈性失实陈述"],a:0,e:"有计划地保留重要事实以欺骗保险人属于欺诈性不披露，即投保人明知重要事实却蓄意隐瞒并怀有欺骗意图。非欺诈性不披露是无意遗漏，而失实陈述是积极地作出虚假陈述而非单纯隐瞒，故不选。",src:1,tw:{ch:"保險原則",q:"涉及有計劃地保留重要事實，蓄意欺騙保險人的違反最高誠信的行為屬於﹕",o:["欺詐性不披露","非欺詐性不披露","欺詐性失實陳述","非欺詐性失實陳述"],e:"有計劃地保留重要事實以欺騙保險人屬於欺詐性不披露，即投保人明知重要事實卻蓄意隱瞞並懷有欺騙意圖。非欺詐性不披露是無意遺漏，而失實陳述是積極地作出虛假陳述而非單純隱瞞，故不選。"}},
{p:1,ch:"保险原则",q:"由于大部分保单都有除外责任,所以确定什么是最有效的损失原因是十分重 要,这类调查与下列哪项原则最有关系?",o:["最高诚信","近因","可保权益","代位"],a:1,e:"因保单多有除外责任，须查明最有效、最直接的损失原因以判断是否受保，这正是近因原则的核心。最高诚信关乎披露、可保权益关乎投保人与标的之关系、代位关乎追偿，与此调查无直接关系。",src:1,tw:{ch:"保險原則",q:"由於大部分保單都有除外責任，所以確定什麼是最有效的損失原因是十分重 要，這類調查與下列哪項原則最有關係？",o:["最高誠信","近因","可保權益","代位"],e:"因保單多有除外責任，須查明最有效、最直接的損失原因以判斷是否受保，這正是近因原則的核心。最高誠信關乎披露、可保權益關乎投保人與標的之關係、代位關乎追償，與此調查無直接關係。"}},
{p:1,ch:"保险原则",q:"第三者一方出现疏忽后,下列哪项情况不会产生代位权:",o:["被保险人辞世(寿险保单)","受保财产的损毁(火险保单)","受保汽车的摧毁(汽车保单)","上述所有各项"],a:0,e:"寿险属定额给付而非弥偿保险，人命损失无法代位，故被保险人辞世不产生代位权。火险、汽车险属财产性质弥偿保险，标的受损后可向疏忽的第三者代位追偿。",src:1,tw:{ch:"保險原則",q:"第三者一方出現疏忽後，下列哪項情況不會產生代位權：",o:["被保險人辭世（壽險保單）","受保財產的損毁（火險保單）","受保汽車的摧毀（汽車保單）","上述所有各項"],e:"壽險屬定額給付而非彌償保險，人命損失無法代位，故被保險人辭世不產生代位權。火險、汽車險屬財產性質彌償保險，標的受損後可向疏忽的第三者代位追償。"}},
{p:1,ch:"保险原则",q:"索偿如达X元便作出正常赔偿的保单,利用了限制弥偿保单中的哪项条款?",o:["保单超额的十足赔偿","保单起赔额的十足赔偿","保单超额的保费","保单起赔额的保费"],a:1,e:"起赔额（相对免赔额）规定索偿达约定金额即作十足赔偿。保单超额则是超过部分才赔的绝对免赔，与「达X元便正常赔偿」不符，保费两项更与本题无关。",src:1,tw:{ch:"保險原則",q:"索償如達X元便作出正常賠償的保單，利用了限制彌償保單中的哪項條款？",o:["保單超額的十足賠償","保單起賠額的十足賠償","保單超額的保費","保單起賠額的保費"],e:"起賠額（相對免賠額）規定索償達約定金額即作十足賠償。保單超額則是超過部分才賠的絕對免賠，與「達X元便正常賠償」不符，保費兩項更與本題無關。"}},
{p:1,ch:"保险原则",q:"若合约各方对他方须负上忠实披露资料的责任,但他可以对另一方没有直接 询问的事情,有权保持缄默,这种诚信责任属于:",o:["一般诚信","最高诚信","有限诚信","部份诚信"],a:0,e:"一般诚信只要求合约各方对直接询问的事项如实回应，对未被直接问及的可保持缄默。最高诚信则要求主动披露一切重要事实，责任较重，故本题所述属一般诚信；「有限诚信」「部份诚信」并非标准术语。",src:1,tw:{ch:"保險原則",q:"若合約各方對他方須負上忠實披露資料的責任，但他可以對另一方沒有直接 詢問的事情，有權保持緘默，這種誠信責任屬於：",o:["一般誠信","最高誠信","有限誠信","部份誠信"],e:"一般誠信只要求合約各方對直接詢問的事項如實回應，對未被直接問及的可保持緘默。最高誠信則要求主動披露一切重要事實，責任較重，故本題所述屬一般誠信；「有限誠信」「部份誠信」並非標準術語。"}},
{p:1,ch:"保险原则",q:"若损毁了一块受保的金砖而留下残余的金碎,在理赔时会把残余一并计算, 称为:",o:["损余","分担比例","剩余物质","损毁"],a:0,e:"金砖损坏后留下残余金碎属损余（salvage），理赔时会将其价值一并折抵以贯彻弥偿原则，避免被保险人超额受偿。分担比例、剩余物质、损毁等表述均不准确。",src:1,tw:{ch:"保險原則",q:"若損毀了一塊受保的金磚而留下殘餘的金碎，在理賠時會把殘餘一併計算， 稱為：",o:["損餘","分擔比例","剩餘物質","損毀"],e:"金磚損壞後留下殘餘金碎屬損餘（salvage），理賠時會將其價值一併折抵以貫徹彌償原則，避免被保險人超額受償。分擔比例、剩餘物質、損毀等表述均不準確。"}},
{p:1,ch:"保险原则",q:"虽然弥偿原则有多种方法,但下列哪项为最常用及方便的方法?",o:["现金支付","维修受损的受保物件","更换损害的物件","将受损的受保物恢复原状"],a:0,e:"弥偿的给付方式有现金支付、维修、更换、恢复原状等多种，其中现金支付最常用和最方便。维修、更换、恢复原状需具体操作与评估，只在特定情形采用。",src:1,tw:{ch:"保險原則",q:"雖然彌償原則有多種方法，但下列哪項為最常用及方便的方法？",o:["現金支付","維修受損的受保物件","更換損害的物件","將受損的受保物恢復原狀"],e:"彌償的給付方式有現金支付、維修、更換、恢復原狀等多種，其中現金支付最常用和最方便。維修、更換、恢復原狀需具體操作與評估，只在特定情形採用。"}},
{p:1,ch:"保险原则",q:"虽然某份财产全损保单在损失发生的时候不存在保额不足的情况,但由于一 项免赔额条文的应用,保险人就该$7,000的损失赔付了$6,000。如果保险人 就代位权的行动中追回了$8,000,请问谁人有权分享这笔款项?而各人的分 配又是多少?",o:["保险人$6,000;被保险人$1,000","保险人$7,000;被保险人$1,000","保险人$6,000;被保险人$2,000","保险人八份之六;被保险人八份之二"],a:2,e:"代位求偿以保险人实际赔付额为限：保险人已赔6,000，只能收回6,000；追回8,000中超出部分的2,000归被保险人。其余选项将7,000全数或按比例分配，不符合代位以已赔付额为限的原则。",src:1,tw:{ch:"保險原則",q:"雖然某份財產全損保單在損失發生的時候不存在保額不足的情況，但由於一 項免賠額條文的應用，保險人就該$7,000的損失賠付了$6,000。如果保險人 就代位權的行動中追回了$8,000，請問誰人有權分享這筆款項？而各人的分 配又是多少？",o:["保險人$6,000；被保險人$1,000","保險人$7,000；被保險人$1,000","保險人$6,000；被保險人$2,000","保險人八份之六；被保險人八份之二"],e:"代位求償以保險人實際賠付額為限：保險人已賠6,000，只能收回6,000；追回8,000中超出部分的2,000歸被保險人。其餘選項將7,000全數或按比例分配，不符合代位以已賠付額為限的原則。"}},
{p:1,ch:"保险原则",q:"被保单条款所剔除的危险称为:",o:["除外危险","不保危险","不受保危险","不被接受危险"],a:0,e:"被保单条款明确剔除不承保的危险称除外危险，属除外责任的范畴。不保危险、不受保危险、不被接受危险均非标准术语。",src:1,tw:{ch:"保險原則",q:"被保單條款所剔除的危險稱為：",o:["除外危險","不保危險","不受保危險","不被接受危險"],e:"被保單條款明確剔除不承保的危險稱除外危險，屬除外責任的範疇。不保危險、不受保危險、不被接受危險均非標準術語。"}},
{p:1,ch:"保险原则",q:"财产保险给予保险人提供更换的偿付。在这种情况下,「更换」的意思是?",o:["现金支付","维修受损的受保物件","更换损害的物件","将受损的受保物恢复原状"],a:2,e:"财产保险中的「更换」指以新物件替换受损物件。现金支付是另一种弥偿方式，维修是修复而非更换，恢复原状的含义亦与更换不同。",src:1,tw:{ch:"保險原則",q:"財產保險給予保險人提供更換的償付。在這種情況下，「更換」的意思是？",o:["現金支付","維修受損的受保物件","更換損害的物件","將受損的受保物恢復原狀"],e:"財產保險中的「更換」指以新物件替換受損物件。現金支付是另一種彌償方式，維修是修復而非更換，恢復原狀的含義亦與更換不同。"}},
{p:1,ch:"保险原则",q:"购买火险中,可能包含一项海上条款,其含意是:",o:["受到水险的保障下,不可与火险单作出分担赔偿","货物在近水的仓库储存均受到保障","水险保单均可与火险保单共同作出赔偿","以上各项皆不是"],a:0,e:"火险保单中的海上条款规定，同一种保险标的若同时受水险保障，则火险保单不与他险作出分担赔偿。近水仓库储存受保障、水险与火险共同赔偿等说法失真，「以上皆不是」亦错误。",src:1,tw:{ch:"保險原則",q:"購買火險中，可能包含一項海上條款，其含意是：",o:["受到水險的保障下，不可與火險單作出分擔賠償","貨物在近水的倉庫儲存均受到保障","水險保單均可與火險保單共同作出賠償","以上各項皆不是"],e:"火險保單中的海上條款規定，同一種保險標的若同時受水險保障，則火險保單不與他險作出分擔賠償。近水倉庫儲存受保障、水險與火險共同賠償等說法失真，「以上皆不是」亦錯誤。"}},
{p:1,ch:"保险原则",q:"近因原则在保险中非常重要,理由是:",o:["不是所有损失之近因都是受保的","政府要求损失之近因的统计数字","如属个人疏忽导致的损失,保险人毋需负责","如属天意造成的损失及损毁,保险人永远不需赔偿"],a:0,e:"近因之所以重要，是因为并非所有损失的近因都属受保危险；须确认近因是否在承保范围内，保险人才决定是否赔付。政府统计、个人疏忽、天意等选项表述过窄或绝对化，均不准确。",src:1,tw:{ch:"保險原則",q:"近因原則在保險中非常重要，理由是：",o:["不是所有損失之近因都是受保的","政府要求損失之近因的統計數字","如屬個人疏忽導致的損失，保險人毋需負責","如屬天意造成的損失及損毀，保險人永遠不需賠償"],e:"近因之所以重要，是因為並非所有損失的近因都屬受保危險；須確認近因是否在承保範圍內，保險人才決定是否賠付。政府統計、個人疏忽、天意等選項表述過窄或絕對化，均不準確。"}},
{p:1,ch:"保险原则",q:"近因对保险索偿来就是一项十分重要的原则,它在索偿的应用",o:["永不会由保单条款来修改","往往可以由保单条款来修改","有时可以透过保单条款来修改","往往指个别索偿得不到赔偿"],a:1,e:"近因原则并非绝对，其适用往往可透过保单条款（承保范围、除外责任、特别约定）予以修改。永不会修改过于绝对，有时修改不如「往往」准确，个别索偿不获赔偿与本题无关。",src:1,tw:{ch:"保險原則",q:"近因對保險索償來就是一項十分重要的原則，它在索償的應用",o:["永不會由保單條款來修改","往往可以由保單條款來修改","有時可以透過保單條款來修改","往往指個別索償得不到賠償"],e:"近因原則並非絕對，其適用往往可透過保單條款（承保範圍、除外責任、特別約定）予以修改。永不會修改過於絕對，有時修改不如「往往」準確，個別索償不獲賠償與本題無關。"}},
{p:1,ch:"保险原则",q:"近因的定义是什么?",o:["最后导致损失的原因","间接导致损失的原因","真正导致损失的原因","任何导致损失的原因"],a:2,e:"近因是真正、直接且有效地导致损失的原因，而非时间上最后或间接的原因。最后导致损失、间接导致损失、任何导致损失的原因，均不符合近因的定义。",src:1,tw:{ch:"保險原則",q:"近因的定義是什麼？",o:["最後導致損失的原因","間接導致損失的原因","真正導致損失的原因","任何導致損失的原因"],e:"近因是真正、直接且有效地導致損失的原因，而非時間上最後或間接的原因。最後導致損失、間接導致損失、任何導致損失的原因，均不符合近因的定義。"}},
{p:1,ch:"保险原则",q:"近因的重要是因为:",o:["保险原则中一项甚为重要的要项","通常与核保息息相关","与保险人是否愿意承保有着密切关系","一般情况中与赔偿理赔的处理关系甚为密切"],a:3,e:"近因决定损失是否属承保范围、保险人是否须负责，故与理赔处理关系最密切。与核保、承保意愿虽有关联，但不如其与赔偿理赔的直接关联紧密。",src:1,tw:{ch:"保險原則",q:"近因的重要是因為：",o:["保險原則中一項甚為重要的要項","通常與核保息息相關","與保險人是否願意承保有着密切關係","一般情況中與賠償理賠的處理關係甚為密切"],e:"近因決定損失是否屬承保範圍、保險人是否須負責，故與理賠處理關係最密切。與核保、承保意願雖有關聯，但不如其與賠償理賠的直接關聯緊密。"}},
{p:1,ch:"保险原则",q:"遗失了戒指一只,保险人按照保单约定赔偿了5万,但该戒指于稍后时间寻回 并以6万售出,对于该1万元的额外收入,应属于哪一方?",o:["属于保险人","属于被保险人","不属于保险人或被保险人","按保险人指明的慈善机构"],a:1,e:"弥偿原则下保险人按约赔付后，标的寻回并售出所得的增值部分（6万减5万的1万元）并非保险人赔付范围，应归被保险人所有。归保险人会违反弥偿，归慈善机构及「不属于任何人」的说法亦无依据。",src:1,tw:{ch:"保險原則",q:"遺失了戒指一隻，保險人按照保單約定賠償了5萬，但該戒指於稍後時間尋回 並以6萬售出，對於該1萬元的額外收入，應屬於哪一方？",o:["屬於保險人","屬於被保險人","不屬於保險人或被保險人","按保險人指明的慈善機構"],e:"彌償原則下保險人按約賠付後，標的尋回並售出所得的增值部分（6萬減5萬的1萬元）並非保險人賠付範圍，應歸被保險人所有。歸保險人會違反彌償，歸慈善機構及「不屬於任何人」的說法亦無依據。"}},
{p:1,ch:"保险原则",q:"重置保险,「以新代旧」保障,约定价值保单的共通点是:",o:["都是水险方面的保单","都是火险方面的保单","不会就损耗,折旧等作出扣除","提供弥偿时必须具有经济价值"],a:2,e:"重置保险、「以新代旧」保障与约定价值保单的共通点是赔付时不就损耗、折旧作扣除，分别以重置价值、新件或约定价值给付。三者并非只限水险或火险，其余说法亦不符。",src:1,tw:{ch:"保險原則",q:"重置保險，「以新代舊」保障，約定價值保單的共通點是：",o:["都是水險方面的保單","都是火險方面的保單","不會就損耗，折舊等作出扣除","提供彌償時必須具有經濟價值"],e:"重置保險、「以新代舊」保障與約定價值保單的共通點是賠付時不就損耗、折舊作扣除，分別以重置價值、新件或約定價值給付。三者並非只限水險或火險，其餘說法亦不符。"}},
{p:1,ch:"保险原则",q:"重置保险、「以新代旧」保障、约定价值保单及水险保单之共通点是:",o:["不受弥偿限制","同样提供超额弥偿","同样适用于所有业务","跟弥偿没有关系"],a:1,e:"重置保险、「以新代旧」、约定价值保单及水险保单都可能使被保险人获得超过实际现金价值的赔付，故共同点是同样提供超额弥偿，属弥偿原则的例外。不受弥偿限制过于绝对，适用于所有业务、与弥偿无关均错误。",src:1,tw:{ch:"保險原則",q:"重置保險、「以新代舊」保障、約定價值保單及水險保單之共通點是：",o:["不受彌償限制","同樣提供超額彌償","同樣適用於所有業務","跟彌償沒有關係"],e:"重置保險、「以新代舊」、約定價值保單及水險保單都可能使被保險人獲得超過實際現金價值的賠付，故共同點是同樣提供超額彌償，屬彌償原則的例外。不受彌償限制過於絕對，適用於所有業務、與彌償無關均錯誤。"}},
{p:1,ch:"保险原则",q:"银行向「A」的物业作出贷款,银行基于本身的利益为该贷款购买保险(贷款 价值),而「A」亦为该物业购买保险,当损失出现时:",o:["不适用于比例分摊条款,保险人各自赔偿50%","不适用于分担条款,因两份保险提供不同保障","只有「A」得到赔偿,因两份保险提供不同保障","只有银行得到赔偿,因两份保险提供不同保障"],a:1,e:"银行基于贷款利益投保，物主基于所有权投保，两者可保权益与保障范围不同，不属同一利益的双重保险，故不适用分担或比例分摊条款。只有某一方获赔的说法错误，各赔50%也无依据。",src:1,tw:{ch:"保險原則",q:"銀行向「A」的物業作出貸款，銀行基於本身的利益為該貸款購買保險（貸款 價值），而「A」亦為該物業購買保險，當損失出現時：",o:["不適用於比例分攤條款，保險人各自賠償50%","不適用於分擔條款，因兩份保險提供不同保障","只有「A」得到賠償，因兩份保險提供不同保障","只有銀行得到賠償，因兩份保險提供不同保障"],e:"銀行基於貸款利益投保，物主基於所有權投保，兩者可保權益與保障範圍不同，不屬同一利益的雙重保險，故不適用分擔或比例分攤條款。只有某一方獲賠的說法錯誤，各賠50%也無依據。"}},
{p:1,ch:"保险原则",q:"阿伦准许他的朋友玫瑰免费住在一个他拥有的单位2个月。请问玫瑰可否为该 单位购买保险? 原因何在?",o:["可以,合法占用单位人均有权以所有人的代理人身份为该单位购买保险","不可以,因玫瑰没有付出代价","可以,因玫瑰以受托保管人的身份对该单位有权益","不可以,因玫瑰并非拥有该单位"],a:2,e:"玫瑰经合法占用成为受托保管人，对该单位的妥善保管负有责任，因此对该单位有可保权益，可就其责任购买保险。她没有付出代价、并非拥有人均不影响其以保管人身份投保；充作所有人的代理人则不当。",src:1,tw:{ch:"保險原則",q:"阿倫准許他的朋友玫瑰免費住在一個他擁有的單位2個月。請問玫瑰可否為該 單位購買保險? 原因何在?",o:["可以，合法佔用單位人均有權以所有人的代理人身份為該單位購買保險","不可以，因玫瑰沒有付出代價","可以，因玫瑰以受託保管人的身份對該單位有權益","不可以，因玫瑰並非擁有該單位"],e:"玫瑰經合法佔用成為受託保管人，對該單位的妥善保管負有責任，因此對該單位有可保權益，可就其責任購買保險。她沒有付出代價、並非擁有人均不影響其以保管人身份投保；充作所有人的代理人則不當。"}},
{p:1,ch:"保险原则",q:"雅伦将他的物业免费借给玫瑰入住两个月,在这情况下,玫瑰有可保权益为 该物业购买保险吗?为什么?",o:["可以,她以受托保管人的身份为物业购买保险","不可以,她并非物业拥有人","不可以,借住只是暂时安排,无法购置保险","可以,在衡平法则上她可分担该物业之风险"],a:0,e:"玫瑰作为受托保管人，对借住期间单位的妥善保管负有法律责任，因而拥有可保权益，可以此身份投保。并非拥有人、借住只是暂时安排、衡平法分担风险等说法，均未正确反映其保管人责任所产生的权益。",src:1,tw:{ch:"保險原則",q:"雅倫將他的物業免費借給玫瑰入住兩個月，在這情況下，玫瑰有可保權益為 該物業購買保險嗎？為什麼？",o:["可以，她以受托保管人的身份為物業購買保險","不可以，她並非物業擁有人","不可以，借住只是暫時安排，無法購置保險","可以，在衡平法則上她可分擔該物業之風險"],e:"玫瑰作為受託保管人，對借住期間單位的妥善保管負有法律責任，因而擁有可保權益，可以此身份投保。並非擁有人、借住只是暫時安排、衡平法分擔風險等說法，均未正確反映其保管人責任所產生的權益。"}},
{p:1,ch:"保险公司的主要功能",q:"「建立良好公司品牌」属于客户服务部的哪项具体工作内容?",o:["联络","公共关系","文件提供","投诉"],a:1,e:"建立良好品牌属公共关系职能，透过对外沟通与形象塑造维护公司声誉。联络、文件提供、投诉虽同属客户服务范畴，但属具体事务，与品牌建设关联较弱。",src:1,tw:{ch:"保險公司的主要功能",q:"「建立良好公司品牌」屬於客戶服務部的哪項具體工作内容？",o:["聯絡","公共關係","文件提供","投訴"],e:"建立良好品牌屬公共關係職能，透過對外溝通與形象塑造維護公司聲譽。聯絡、文件提供、投訴雖同屬客户服務範疇，但屬具體事務，與品牌建設關聯較弱。"}},
{p:1,ch:"保险公司的主要功能",q:"「精算师」角色在各类保险产品中日见重要,当中尤为与哪类保险至为紧密?",o:["汽车保险","人身意外保险","人寿保险","家居保险"],a:2,e:"人寿保险须依赖死亡率、利率等长期精算假设厘定保费与储备，精算师的参与至关重要。汽车、人身意外、家居保险以短期经验与统计为主，对精算的依赖较低。",src:1,tw:{ch:"保險公司的主要功能",q:"「精算師」角色在各類保險產品中日見重要，當中尤為與哪類保險至為緊密？",o:["汽車保險","人身意外保險","人壽保險","家居保險"],e:"人壽保險須依賴死亡率、利率等長期精算假設釐定保費與儲備，精算師的參與至關重要。汽車、人身意外、家居保險以短期經驗與統計為主，對精算的依賴較低。"}},
{p:1,ch:"保险公司的主要功能",q:"一些需要长时间才出现的索偿,当中精算师在计算过程实在功不可没,这类索 偿通常属于:",o:["长期责任业务","短期责任业务","长期保单","长期业务"],a:0,e:"需长时间后才出现的索偿（如责任险潜伏期赔款）属长期责任业务，精算师须估算延迟索偿的储备。短期责任业务、长期保单、长期业务等表述与此情境不符。",src:1,tw:{ch:"保險公司的主要功能",q:"一些需要長時間才出現的索償，當中精算師在計算過程實在功不可沒，這類索 償通常屬於:",o:["長期責任業務","短期責任業務","長期保單","長期業務"],e:"需長時間後才出現的索償（如責任險潛伏期賠款）屬長期責任業務，精算師須估算延遲索償的儲備。短期責任業務、長期保單、長期業務等表述與此情境不符。"}},
{p:1,ch:"保险公司的主要功能",q:"一家典型保险公司的公共关系部负责处理颇多类型的事务,下列哪项则不属于 它的范围之内?",o:["协调对外的联系工作","参与繁多的产品研究","召开记者招待会以作出发布消息或解释","工商界及其他杂志报章准备新闻稿及副本"],a:1,e:"产品研究属产品开发或市场部门职责，非公共关系部范围。协调对外联系、召开记者招待会、准备新闻稿等，都是公共关系部的典型职能。",src:1,tw:{ch:"保險公司的主要功能",q:"一家典型保險公司的公共關係部負責處理頗多類型的事務，下列哪項則不屬於 它的範圍之內?",o:["協調對外的聯繫工作","參與繁多的產品研究","召開記者招待會以作出發佈消息或解釋","工商界及其他雜誌報章準備新聞稿及副本"],e:"產品研究屬產品開發或市場部門職責，非公共關係部範圍。協調對外聯繫、召開記者招待會、準備新聞稿等，都是公共關係部的典型職能。"}},
{p:1,ch:"保险公司的主要功能",q:"一般保险的理赔部门,不大考虑以下哪项?",o:["分担","尚未偿还的贷款","代位权的可能性","比例分摊的应用"],a:1,e:"保单贷款通常只发生在具现金价值的人寿保险中，一般财产、责任保险少见，故一般保险理赔部门不大考虑未偿还贷款。分担、代位权、比例分摊均是一般保险理赔的常见考量。",src:1,tw:{ch:"保險公司的主要功能",q:"一般保險的理賠部門，不大考慮以下哪項?",o:["分擔","尚未償還的貸款","代位權的可能性","比例分攤的應用"],e:"保單貸款通常只發生在具現金價值的人壽保險中，一般財產、責任保險少見，故一般保險理賠部門不大考慮未償還貸款。分擔、代位權、比例分攤均是一般保險理賠的常見考量。"}},
{p:1,ch:"保险公司的主要功能",q:"一项保险,保险人于其后时间不能取消,而且只可对每项风险进行一次核保, 此保险为:",o:["人寿保险","汽车保险","海上船体保险","公众责任保险"],a:0,e:"人寿保险是长期合约，签约后保险人不可随意取消，且核保只能在承保时进行一次。汽车、海上船体、公众责任保险多为一年期，续保时条件可检讨，若可取消则不符题意。",src:1,tw:{ch:"保險公司的主要功能",q:"一項保險，保險人於其後時間不能取消，而且只可對每項風險進行一次核保， 此保險為:",o:["人壽保險","汽車保險","海上船體保險","公眾責任保險"],e:"人壽保險是長期合約，簽約後保險人不可隨意取消，且核保只能在承保時進行一次。汽車、海上船體、公眾責任保險多為一年期，續保時條件可檢討，若可取消則不符題意。"}},
{p:1,ch:"保险公司的主要功能",q:"下列哪项不太可能是客户服务的职责?",o:["公共关系","处理投诉","联络","索偿的谈判"],a:3,e:"索偿谈判属理赔部门的职责。公共关系、处理投诉、联络均是客户服务部的典型职能，故不大可能由客户服务部负责的是索偿谈判。",src:1,tw:{ch:"保險公司的主要功能",q:"下列哪項不太可能是客戶服務的職責？",o:["公共關係","處理投訴","聯絡","索償的談判"],e:"索償談判屬理賠部門的職責。公共關係、處理投訴、聯絡均是客户服務部的典型職能，故不大可能由客户服務部負責的是索償談判。"}},
{p:1,ch:"保险公司的主要功能",q:"下列哪项业务较可能与产品开发部有关?",o:["产品研究","产品组合开发","个别产品开发","以上皆是"],a:3,e:"产品研究、产品组合开发、个别产品开发均属产品开发部的工作，故题目所述各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"下列哪項業務較可能與產品開發部有關?",o:["產品研究","產品組合開發","個別產品開發","以上皆是"],e:"產品研究、產品組合開發、個別產品開發均屬產品開發部的工作，故題目所述各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"下列哪项属于会计及投资部门的工作? i 纪录保存 ii 款项收集 iii 付款 iv 投资",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各项皆是"],a:3,e:"纪录保存、款项收集、付款及投资均属会计及投资部门的工作，故各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"下列哪項屬於會計及投資部門的工作? i 紀錄保存 ii 款項收集 iii 付款 iv 投資",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各項皆是"],e:"紀錄保存、款項收集、付款及投資均屬會計及投資部門的工作，故各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"下列哪项较不大可能是产品开发部的主要功能?",o:["产品研究","产品定价","个别产品开发","产品组合开发"],a:1,e:"产品定价主要依靠精算部门厘定保费率，非产品开发部主要功能。产品研究、个别产品开发、产品组合开发均属产品开发工作。",src:1,tw:{ch:"保險公司的主要功能",q:"下列哪項較不大可能是產品開發部的主要功能？",o:["產品研究","產品定價","個別產品開發","產品組合開發"],e:"產品定價主要依靠精算部門釐定保費率，非產品開發部主要功能。產品研究、個別產品開發、產品組合開發均屬產品開發工作。"}},
{p:1,ch:"保险公司的主要功能",q:"不论由培训及发展部门主理或安排,当考虑培训及教育时:",o:["培训可视为对现在的或未来的工作所作的准备","两者所指的含义相同","永不会由公司内部的职员提供培训","培训的目的主要是为预备公开考试"],a:0,e:"培训可视为对现在或未来工作所作的技能准备。培训与教育含义不完全相同（教育侧重广博知识），培训可由内部职员提供，且目的不只为公开考试。",src:1,tw:{ch:"保險公司的主要功能",q:"不論由培訓及發展部門主理或安排，當考慮培訓及教育時:",o:["培訓可視為對現在的或未來的工作所作的準備","兩者所指的含義相同","永不會由公司內部的職員提供培訓","培訓的目的主要是為預備公開考試"],e:"培訓可視為對現在或未來工作所作的技能準備。培訓與教育含義不完全相同（教育側重廣博知識），培訓可由內部職員提供，且目的不只為公開考試。"}},
{p:1,ch:"保险公司的主要功能",q:"个别产品的开发:",o:["这是一个延续不停的过程","这是言过其实,对于保险人提供很小价值","如非必要,不用开发","这是非强制性产品才必要"],a:0,e:"个别产品的开发是一个延续不停的过程，须随市场变化不断改良。其余选项对产品开发的描述均不符实际。",src:1,tw:{ch:"保險公司的主要功能",q:"個別產品的開發:",o:["這是一個延續不停的過程","這是言過其實，對於保險人提供很小價值","如非必要，不用開發","這是非強制性產品才必要"],e:"個別產品的開發是一個延續不停的過程，須隨市場變化不斷改良。其餘選項對產品開發的描述均不符實際。"}},
{p:1,ch:"保险公司的主要功能",q:"为何人寿保单在核保过程中不能出现错误?",o:["因保险公司不能取消人寿保单,而且只可核保一次","因保单可能已转让予第三者","因保单可能已作抵押","以上各项皆是"],a:0,e:"人寿保险为长期合约，保险人日后不能单方面取消，且核保只能在投保时进行一次，故核保一旦出错难以事后补救。保单可能转让或抵押，是出错的后果而非根本原因。",src:1,tw:{ch:"保險公司的主要功能",q:"為何人壽保單在核保過程中不能出現錯誤?",o:["因保險公司不能取消人壽保單，而且只可核保一次","因保單可能已轉讓予第三者","因保單可能已作抵押","以上各項皆是"],e:"人壽保險為長期合約，保險人日後不能單方面取消，且核保只能在投保時進行一次，故核保一旦出錯難以事後補救。保單可能轉讓或抵押，是出錯的後果而非根本原因。"}},
{p:1,ch:"保险公司的主要功能",q:"产品开发的工作是:",o:["产品研究","个别产品开发","产品组合开发","以上所有各项"],a:3,e:"产品开发的工作包含产品研究、个别产品开发及产品组合开发，故以上所有各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"產品開發的工作是:",o:["產品研究","個別產品開發","產品組合開發","以上所有各項"],e:"產品開發的工作包含產品研究、個別產品開發及產品組合開發，故以上所有各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"产品的研究应从以下哪方面作出考虑?",o:["公司原有产品","竞争对手的产品","公司及竞争对手的产品","公司原有、竞争对手的产品及市场趋势"],a:3,e:"产品研究须综合公司原有产品、竞争对手的产品及市场趋势作全面考虑。前三项仅涵盖部分角度，不完整。",src:1,tw:{ch:"保險公司的主要功能",q:"產品的研究應從以下哪方面作出考慮?",o:["公司原有產品","競爭對手的產品","公司及競爭對手的產品","公司原有、競爭對手的產品及市場趨勢"],e:"產品研究須綜合公司原有產品、競爭對手的產品及市場趨勢作全面考慮。前三項僅涵蓋部分角度，不完整。"}},
{p:1,ch:"保险公司的主要功能",q:"人寿保险理赔部,不会负责处理以下哪项:",o:["红利","尚未清还的保单贷款","可能出现的保单转让","运用比例分摊"],a:3,e:"比例分摊是财产保险中多保单分摊的机制，人寿保险为定额给付，不适用比例分摊。红利、未清还保单贷款、保单转让均是人寿理赔常需处理的。",src:1,tw:{ch:"保險公司的主要功能",q:"人壽保險理賠部，不會負責處理以下哪項:",o:["紅利","尚未清還的保單貸款","可能出現的保單轉讓","運用比例分攤"],e:"比例分攤是財產保險中多保單分攤的機制，人壽保險為定額給付，不適用比例分攤。紅利、未清還保單貸款、保單轉讓均是人壽理賠常需處理的。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪一类型的保险是可以集中核保的?",o:["人寿","旅游","汽车","以上皆是"],a:0,e:"人寿保险核保在总部集中进行，可以集中核保。旅游、汽车等一般保险多采取分散或分支核保的形式。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪一類型的保險是可以集中核保的?",o:["人壽","旅遊","汽車","以上皆是"],e:"人壽保險核保在總部集中進行，可以集中核保。旅遊、汽車等一般保險多采取分散或分支核保的形式。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪三项有关人寿保险的理赔处理的描述是正确的? i 可能需要考虑尚未清还的保单贷款 ii 可能需要考虑保单的转让 iii 可能需要考虑代位权及损余的问题 iv 可能需要把分红或期末红利一并考虑",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"人寿理赔须考虑未清还保单贷款、保单转让及分红或期末红利（i、ii、iv）。代位权及损余（iii）是财产险弥偿的考量，人寿保险不适用。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪三項有關人壽保險的理賠處理的描述是正確的? i 可能需要考慮尚未清還的保單貸款 ii 可能需要考慮保單的轉讓 iii 可能需要考慮代位權及損餘的問題 iv 可能需要把分紅或期末紅利一併考慮",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"人壽理賠須考慮未清還保單貸款、保單轉讓及分紅或期末紅利（i、ii、iv）。代位權及損餘（iii）是財產險彌償的考量，人壽保險不適用。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪些为精算师的职责? i 计算储备 ii 负债的估值 iii 预计利息收益 iv 保费率的厘定",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"计算储备、负债估值、预计利息收益及厘定保费率，均为精算师的职责，故四项全对。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪些為精算師的職責? i 計算儲備 ii 負債的估值 iii 預計利息收益 iv 保費率的釐定",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"計算儲備、負債估值、預計利息收益及釐定保費率，均為精算師的職責，故四項全對。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪些可能对人寿保险理赔造成一定的影响? i 还未清偿的保费贷款 ii 与受益人有关的复杂事项 iii 转让保单予第三者的可能性 iv 对死者死亡的真确性或身分存在不确定因素",o:["i, ii","ii, iii","i, iii, iv","i, ii, iii, iv"],a:3,e:"未清偿保费贷款、受益人相关复杂事项、保单转让予第三者的可能性，以及对死亡真确性或身份的疑问，均会影响人寿理赔，故四项全对。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪些可能對人壽保險理賠造成一定的影響? i 還未清償的保費貸款 ii 與受益人有關的複雜事項 iii 轉讓保單予第三者的可能性 iv 對死者死亡的真確性或身分存在不確定因素",o:["i, ii","ii, iii","i, iii, iv","i, ii, iii, iv"],e:"未清償保費貸款、受益人相關複雜事項、保單轉讓予第三者的可能性，以及對死亡真確性或身份的疑問，均會影響人壽理賠，故四項全對。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪类保险的核保以非集中的形式可能性较小?",o:["人寿","旅游","汽车","家居"],a:0,e:"人寿保险通常在总部集中核保，较少采用非集中形式；旅游、汽车、家居等一般保险多分散核保，故人寿核保以非集中形式进行的可能性较小。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪類保險的核保以非集中的形式可能性較小？",o:["人壽","旅遊","汽車","家居"],e:"人壽保險通常在總部集中核保，較少採用非集中形式；旅遊、汽車、家居等一般保險多分散核保，故人壽核保以非集中形式進行的可能性較小。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项不大可能是会计部门工作",o:["保存准确的财务纪录","制订征收保费表","款项收集","缴付账单及欠款"],a:1,e:"制订征收保费表属精算或产品职能，不大可能是会计部门工作。保存财务纪录、款项收集、缴付账单及欠款均属会计部门职责。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項不大可能是會計部門工作",o:["保存準確的財務紀錄","制訂徵收保費表","款項收集","繳付賬單及欠款"],e:"制訂徵收保費表屬精算或產品職能，不大可能是會計部門工作。保存財務紀錄、款項收集、繳付賬單及欠款均屬會計部門職責。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项不太可能是保险销售部的职能?",o:["产品各环节的联系","索偿个案的调查","掌握结果及趋势","加强销售计划"],a:1,e:"调查索偿个案属理赔部门的职能。产品各环节的联系、掌握结果及趋势、加强销售计划，均属保险销售部的职能。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項不太可能是保險銷售部的職能？",o:["產品各環節的聯繫","索償個案的調查","掌握結果及趨勢","加強銷售計劃"],e:"調查索償個案屬理賠部門的職能。產品各環節的聯繫、掌握結果及趨勢、加強銷售計劃，均屬保險銷售部的職能。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项不属于核保部门的工作?",o:["制备核保手册及保费率指南","制订拒绝名单","以集中形式处理一般保险的核保","以集中形式处理人寿保险的核保"],a:2,e:"核保部门以集中形式处理的是人寿保险而非一般保险的核保，故该陈述不屑核保部门工作。制备核保手册、保费率指南、拒绝名单均是核保部门职责。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項不屬於核保部門的工作?",o:["製備核保手冊及保費率指南","製訂拒絕名單","以集中形式處理一般保險的核保","以集中形式處理人壽保險的核保"],e:"核保部門以集中形式處理的是人壽保險而非一般保險的核保，故該陳述不屑核保部門工作。製備核保手冊、保費率指南、拒絕名單均是核保部門職責。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项不是人寿保险理赔部所考虑的范围?",o:["退休策划","红利因素","保单转让","有否未清还之保单贷款"],a:0,e:"退休策划属销售或顾问服务范畴，非人寿理赔部所考虑。红利因素、保单转让、未清还保单贷款均是人寿理赔须处理的。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項不是人壽保險理賠部所考慮的範圍?",o:["退休策劃","紅利因素","保單轉讓","有否未清還之保單貸款"],e:"退休策劃屬銷售或顧問服務範疇，非人壽理賠部所考慮。紅利因素、保單轉讓、未清還保單貸款均是人壽理賠須處理的。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项为一般保险业务的特点? i 它们会收集于总部处理 ii 它们的处理保障类型多不胜数 iii 保单在续保时,条件可以检讨,在必要时保单甚至可以取消 iv 它们只能每年处理理赔一次",o:["i, ii","ii, iii","iii, iv","i, iv"],a:1,e:"一般保险业务特点包括处理的保障类型众多（ii），以及续保时条件可检讨、必要时可取消保单（iii）。收集于总部处理不符一般保险分散实况，只能每年处理理赔一次亦明显错误。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項為一般保險業務的特點? i 它們會收集於總部處理 ii 它們的處理保障類型多不勝數 iii 保單在續保時，條件可以檢討，在必要時保單甚至可以取消 iv 它們只能每年處理理賠一次",o:["i, ii","ii, iii","iii, iv","i, iv"],e:"一般保險業務特點包括處理的保障類型眾多（ii），以及續保時條件可檢討、必要時可取消保單（iii）。收集於總部處理不符一般保險分散實況，只能每年處理理賠一次亦明顯錯誤。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项对于再保险的描述是不正确的?",o:["只是保险人与再保险人之间的事情","要向在香港注册的公司购买","要维持足够的再保险","对保单持有人没有任何影响"],a:1,e:"再保险无需向在香港注册的公司购买，可向境外再保险人分保，故该项不正确。其余三项（仅是保险人与再保险人之事、须维持足够再保险、不影响原保单持有人）均正确。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項對於再保險的描述是不正確的?",o:["只是保險人與再保險人之間的事情","要向在香港註冊的公司購買","要維持足夠的再保險","對保單持有人沒有任何影響"],e:"再保險無需向在香港註冊的公司購買，可向境外再保險人分保，故該項不正確。其餘三項（僅是保險人與再保險人之事、須維持足夠再保險、不影響原保單持有人）均正確。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项属于客户服务部的职能范围? i 联络 ii 公共关系 iii 赔偿的谈判 iv 处理投诉",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"客户服务部职能包括联络、公共关系及处理投诉（i、ii、iv）。赔偿谈判属理赔部门，故iii不包括在内。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項屬於客戶服務部的職能範圍? i 聯絡 ii 公共關係 iii 賠償的談判 iv 處理投訴",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"客户服務部職能包括聯絡、公共關係及處理投訴（i、ii、iv）。賠償談判屬理賠部門，故iii不包括在內。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项属于核保的范围? i 评估风险的可保性 ii 厘定可保风险的条款 iii 制备核保手册和保费率指南 iv 制备「拒绝名单 」",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:3,e:"核保范围包括评估风险的可保性、厘定可保风险的条款、制备核保手册与保费率指南，以及制备「拒绝名单」，故四项全对。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項屬於核保的範圍? i 評估風險的可保性 ii 釐定可保風險的條款 iii 製備核保手冊和保費率指南 iv 製備「拒絕名單 」",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"核保範圍包括評估風險的可保性、釐定可保風險的條款、製備核保手冊與保費率指南，以及製備「拒絕名單」，故四項全對。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项并非核保部门的工作范围?",o:["制备核保手册","制备保费指南","处理索偿","制备「拒绝名单」"],a:2,e:"处理索偿属理赔部门的职责，并非核保部门工作。制备核保手册、保费指南、「拒绝名单」均属核保部门工作范围。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項並非核保部門的工作範圍？",o:["製備核保手冊","製備保費指南","處理索償","製備「拒絶名單」"],e:"處理索償屬理賠部門的職責，並非核保部門工作。製備核保手冊、保費指南、「拒絕名單」均屬核保部門工作範圍。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项或哪些是会计部及投资部对于他们的投资组合必须特别注意的地方?",o:["安全性","流动性","收益性","以上所有各项"],a:3,e:"会计及投资部门对投资组合须同时注意安全性、流动性与收益性三大要素，故以上所有各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項或哪些是會計部及投資部對於他們的投資組合必須特別注意的地方?",o:["安全性","流動性","收益性","以上所有各項"],e:"會計及投資部門對投資組合須同時注意安全性、流動性與收益性三大要素，故以上所有各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项或哪些有可能包括在给涉及核保风险之员工的指引和指示内?",o:["拒绝名单","保费率指南","核保手册","以上所有各项"],a:3,e:"给予涉及核保风险员工的指引，可能包括「拒绝名单」、保费率指南及核保手册，故以上所有各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項或哪些有可能包括在給涉及核保風險之員工的指引和指示內?",o:["拒絕名單","保費率指南","核保手冊","以上所有各項"],e:"給予涉及核保風險員工的指引，可能包括「拒絕名單」、保費率指南及核保手冊，故以上所有各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项描述人寿保险的核保是不正确的?",o:["是与可保风险有关","核保是由低级职员处理,是项简单程序","人寿保险是一份合约,并不可以重复处理","风险评估"],a:1,e:"人寿核保是专业且复杂的重要程序，由专门核保人员处理，并非由低级职员办理的简单程序。其余三项关于寿险核保的描述均正确。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項描述人壽保險的核保是不正確的？",o:["是與可保風險有關","核保是由低級職員處理，是項簡單程序","人壽保險是一份合約，並不可以重複處理","風險評估"],e:"人壽核保是專業且複雜的重要程序，由專門核保人員處理，並非由低級職員辦理的簡單程序。其餘三項關於壽險核保的描述均正確。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项描述再保险是正确的?",o:["当保险人分出再保险后,不用知会被保险人","再保险人需要承担某程度的风险损失","为大规模的风险提供分担赔偿","以上所列各项"],a:3,e:"分出再保险毋须知会被保险人，再保险人须承担一定程度的损失风险，且再保险为大规模风险提供分担，故以上所列各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項描述再保險是正確的?",o:["當保險人分出再保險後，不用知會被保險人","再保險人需要承擔某程度的風險損失","為大規模的風險提供分擔賠償","以上所列各項"],e:"分出再保險毋須知會被保險人，再保險人須承擔一定程度的損失風險，且再保險為大規模風險提供分擔，故以上所列各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项是核保部门的工作范围?",o:["制备核保手册","制备保费指南","制备「拒绝名单」","以上各项皆是"],a:3,e:"制备核保手册、保费指南及「拒绝名单」均属核保部门的工作范围，故以上各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項是核保部門的工作範圍？",o:["製備核保手冊","製備保費指南","製備「拒絶名單」","以上各項皆是"],e:"製備核保手冊、保費指南及「拒絕名單」均屬核保部門的工作範圍，故以上各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项最有可能是客户服务部的功能:",o:["保险索偿","客户联络","加强销售","以上皆是"],a:1,e:"客户服务部的核心功能是客户联络。保险索偿属理赔部门，加强销售属销售部门，故「以上皆是」不成立。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項最有可能是客戶服務部的功能：",o:["保險索償","客戶聯絡","加強銷售","以上皆是"],e:"客户服務部的核心功能是客户聯絡。保險索償屬理賠部門，加強銷售屬銷售部門，故「以上皆是」不成立。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项有关再保险的陈述并不正确?",o:["必须透过本港以外的再保险人进行再保险","再保险有时指与再保险人分担一项风险","再保险不会直接影响原来的保单持有人","本港的保险人必须维持「足够的再保险」"],a:0,e:"再保险并无「必须透过本港以外再保险人进行」的规定，故该项不正确。再保险与再保险人分担风险、不影响原保单持有人、保险人须维持足够再保险，均属正确。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項有關再保險的陳述並不正確?",o:["必須透過本港以外的再保險人進行再保險","再保險有時指與再保險人分擔一項風險","再保險不會直接影響原來的保單持有人","本港的保險人必須維持「足夠的再保險」"],e:"再保險並無「必須透過本港以外再保險人進行」的規定，故該項不正確。再保險與再保險人分擔風險、不影響原保單持有人、保險人須維持足夠再保險，均屬正確。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项有关核保的陈述是不正确?",o:["它包括选择承保的风险","它包括应用于受保风险之条款","它包括非人寿业务的保单续保","于人寿保险中,是一种每年进行一次的过程"],a:3,e:"人寿保险的核保只在承保时进行一次，并非每年进行的程序，故该项不正确。选择承保风险、应用条款、处理非人寿业务的续保等陈述均正确。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項有關核保的陳述是不正確?",o:["它包括選擇承保的風險","它包括應用於受保風險之條款","它包括非人壽業務的保單續保","於人壽保險中，是一種每年進行一次的過程"],e:"人壽保險的核保只在承保時進行一次，並非每年進行的程序，故該項不正確。選擇承保風險、應用條款、處理非人壽業務的續保等陳述均正確。"}},
{p:1,ch:"保险公司的主要功能",q:"以下是精算支援的职责包括:",o:["厘定保费率","储备金的计算","负债的估值","以上皆是"],a:3,e:"厘定保费率、储备金计算及负债估值均属精算支援的职责，故以上皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"以下是精算支援的職責包括：",o:["釐定保費率","儲備金的計算","負債的估值","以上皆是"],e:"釐定保費率、儲備金計算及負債估值均屬精算支援的職責，故以上皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"会计及投资的责任不包括:",o:["保存准确的财务纪录","制订征收保费表","款项收集","缴付账单及欠款"],a:1,e:"制订征收保费表属精算或产品职能，不包括在会计及投资部门责任内。保存财务纪录、款项收集、缴付账单及欠款均属其职责。",src:1,tw:{ch:"保險公司的主要功能",q:"會計及投資的責任不包括:",o:["保存準確的財務紀錄","制訂徵收保費表","款項收集","繳付賬單及欠款"],e:"制訂徵收保費表屬精算或產品職能，不包括在會計及投資部門責任內。保存財務紀錄、款項收集、繳付賬單及欠款均屬其職責。"}},
{p:1,ch:"保险公司的主要功能",q:"保险业条例要求所有从事长期业务的保险人,委派一名合资格的精算师,并要 求:",o:["每年呈交一份属于该保险人的独立死亡率报告","对该保险人的所有资产及负债进行评估最少一年一次的","每年呈交一份索偿报告","以上所列各项要求均要达致"],a:1,e:"保险业条例要求长期业务保险人委任合资格精算师，并至少每年一次对保险人的资产及负债进行估值。每年呈交死亡率报告、索偿报告并非该条所订要求。",src:1,tw:{ch:"保險公司的主要功能",q:"保險業條例要求所有從事長期業務的保險人，委派一名合資格的精算師，並要 求:",o:["每年呈交一份屬於該保險人的獨立死亡率報告","對該保險人的所有資產及負債進行評估最少一年一次的","每年呈交一份索償報告","以上所列各項要求均要達致"],e:"保險業條例要求長期業務保險人委任合資格精算師，並至少每年一次對保險人的資產及負債進行估值。每年呈交死亡率報告、索償報告並非該條所訂要求。"}},
{p:1,ch:"保险公司的主要功能",q:"保险人对保单条款作适当技术调整,这称之为:",o:["核保","风险管理","风险分散","保险风险分析"],a:0,e:"保险人对保单条款作适当技术调整（如设定免赔额、特别条款），属于核保工作。风险管理、风险分散、保险风险分析是更广泛的概念，非指此具体工作。",src:1,tw:{ch:"保險公司的主要功能",q:"保險人對保單條款作適當技術調整，這稱之為：",o:["核保","風險管理","風險分散","保險風險分析"],e:"保險人對保單條款作適當技術調整（如設定免賠額、特別條款），屬於核保工作。風險管理、風險分散、保險風險分析是更廣泛的概念，非指此具體工作。"}},
{p:1,ch:"保险公司的主要功能",q:"保险新产品的最具竞争力时期是 :",o:["很短,可能只有数星期或几个月","约一年","通常在竞争对手还未将注意力放在新产品前大约二年","没有限制"],a:0,e:"新产品推向市场后竞争者会迅速模仿，故其最具竞争力的独占期通常很短，可能只有数星期或几个月。约一年、约二年、没有限制均不符实际。",src:1,tw:{ch:"保險公司的主要功能",q:"保險新產品的最具競爭力時期是 :",o:["很短，可能只有數星期或幾個月","約一年","通常在競爭對手還未將注意力放在新產品前大約二年","沒有限制"],e:"新產品推向市場後競爭者會迅速模仿，故其最具競爭力的獨佔期通常很短，可能只有數星期或幾個月。約一年、約二年、沒有限制均不符實際。"}},
{p:1,ch:"保险公司的主要功能",q:"保险的理赔部门正在处理保单的转让、保单贷款、保单红利等问题,很大程度 正在处理哪类保险:",o:["人寿保险","汽车保险","火险","人身意外保险"],a:0,e:"保单转让、保单贷款、保单红利等都是人寿保险特有的内容。汽车保险、火险、人身意外保险无此类问题。",src:1,tw:{ch:"保險公司的主要功能",q:"保險的理賠部門正在處理保單的轉讓、保單貸款、保單紅利等問題，很大程度 正在處理哪類保險：",o:["人壽保險","汽車保險","火險","人身意外保險"],e:"保單轉讓、保單貸款、保單紅利等都是人壽保險特有的內容。汽車保險、火險、人身意外保險無此類問題。"}},
{p:1,ch:"保险公司的主要功能",q:"保险销售的工作是:",o:["产品的联系","与培训及市场行销部合作加强销售计划","掌握销售成果及趋势","以上各项皆是"],a:3,e:"保险销售工作包括产品的联系、与培训及市场行销部合作加强销售计划，以及掌握销售成果及趋势，故以上各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"保險銷售的工作是:",o:["產品的聯繫","與培訓及市場行銷部合作加強銷售計劃","掌握銷售成果及趨勢","以上各項皆是"],e:"保險銷售工作包括產品的聯繫、與培訓及市場行銷部合作加強銷售計劃，以及掌握銷售成果及趨勢，故以上各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"保险销售部就销售成果和趋势小心关注,这一过程常被称为:",o:["促销","监察","市场调查","进度提升"],a:1,e:"保险销售部持续关注销售成果与趋势，这一过程常被称为监察。促销、市场调查、进度提升均非此特定表述。",src:1,tw:{ch:"保險公司的主要功能",q:"保險銷售部就銷售成果和趨勢小心關注，這一過程常被稱為:",o:["促銷","監察","市場調查","進度提升"],e:"保險銷售部持續關注銷售成果與趨勢，這一過程常被稱為監察。促銷、市場調查、進度提升均非此特定表述。"}},
{p:1,ch:"保险公司的主要功能",q:"保险销售部门的工作是:",o:["产品的联系","与培训及市场行销部合作加强销售计划","掌握销售成果及趋势","以上各项皆是"],a:3,e:"保险销售部门的工作包括产品的联系、与培训及市场行销部合作加强销售计划，以及掌握销售成果及趋势，故以上各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"保險銷售部門的工作是:",o:["產品的聯繫","與培訓及市場行銷部合作加強銷售計劃","掌握銷售成果及趨勢","以上各項皆是"],e:"保險銷售部門的工作包括產品的聯繫、與培訓及市場行銷部合作加強銷售計劃，以及掌握銷售成果及趨勢，故以上各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"保险销售部门较有可能与以下哪个部门的联系最为密切?",o:["市场行销部门","核保部门","会计及投资部门","产品发展"],a:0,e:"保险销售与市场推广密不可分，故销售部门与市场行销部门的联系最为密切。核保、会计投资、产品发展的联系相对间接。",src:1,tw:{ch:"保險公司的主要功能",q:"保險銷售部門較有可能與以下哪個部門的聯繫最為密切?",o:["市場行銷部門","核保部門","會計及投資部門","產品發展"],e:"保險銷售與市場推廣密不可分，故銷售部門與市場行銷部門的聯繫最為密切。核保、會計投資、產品發展的聯繫相對間接。"}},
{p:1,ch:"保险公司的主要功能",q:"哪一类型的保险是可以集中核保的?",o:["人寿","旅游","家居","意外"],a:0,e:"人寿保险通常在总部集中核保。旅游、家居、意外等一般保险多采分散核保形式。",src:1,tw:{ch:"保險公司的主要功能",q:"哪一類型的保險是可以集中核保的?",o:["人壽","旅遊","家居","意外"],e:"人壽保險通常在總部集中核保。旅遊、家居、意外等一般保險多采分散核保形式。"}},
{p:1,ch:"保险公司的主要功能",q:"在保单中出现错误是非常严重的,因为:",o:["保单可以转让予其他人士","保险人不能取消保单","保单可以用作贷款抵押","以上各项皆是"],a:3,e:"因保单可转让予他人、保险人不能取消保单、又可作贷款抵押，若保单出现错误后果便非常严重，故以上各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"在保單中出現錯誤是非常嚴重的，因為:",o:["保單可以轉讓予其他人士","保險人不能取消保單","保單可以用作貸款抵押","以上各項皆是"],e:"因保單可轉讓予他人、保險人不能取消保單、又可作貸款抵押，若保單出現錯誤後果便非常嚴重，故以上各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"在处理人寿和非人寿保险赔偿时有两项共通特点,就是数额及:",o:["如何提供弥偿问题","代位权的问题","责任问题","分担的问题"],a:2,e:"处理人寿与非人寿保险赔偿的两项共通特点是赔偿数额，以及保险人是否须负赔偿责任（责任问题）。如何弥偿、代位权、分担问题在两类保险中并不同样适用。",src:1,tw:{ch:"保險公司的主要功能",q:"在處理人壽和非人壽保險賠償時有兩項共通特點，就是數額及:",o:["如何提供彌償問題","代位權的問題","責任問題","分擔的問題"],e:"處理人壽與非人壽保險賠償的兩項共通特點是賠償數額，以及保險人是否須負賠償責任（責任問題）。如何彌償、代位權、分擔問題在兩類保險中並不同樣適用。"}},
{p:1,ch:"保险公司的主要功能",q:"在处理所有的保险理赔时,有两个特别注意的地方,一为理赔责任,另一为:",o:["数额","红利的计算","保单贷款是否不清","失去索偿折扣"],a:0,e:"处理所有保险理赔时须特别注意理赔责任（是否该赔）与理赔数额（赔多少）两点。红利计算、保单贷款、失去索偿折扣是寿险特有或次要问题。",src:1,tw:{ch:"保險公司的主要功能",q:"在處理所有的保險理賠時，有兩個特別注意的地方，一為理賠責任，另一為:",o:["數額","紅利的計算","保單貸款是否不清","失去索償折扣"],e:"處理所有保險理賠時須特別注意理賠責任（是否該賠）與理賠數額（賠多少）兩點。紅利計算、保單貸款、失去索償折扣是壽險特有或次要問題。"}},
{p:1,ch:"保险公司的主要功能",q:"在处理死亡索偿时,有些要特别注意的地方,包括赔偿利益及",o:["权益的转让","红利","保单中未清还的保单贷款数额","以上所有各项"],a:3,e:"处理死亡索偿时须注意赔偿利益、权益的转让、红利及保单中未清还的保单贷款数额，故以上所有各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"在處理死亡索償時，有些要特別注意的地方，包括賠償利益及",o:["權益的轉讓","紅利","保單中未清還的保單貸款數額","以上所有各項"],e:"處理死亡索償時須注意賠償利益、權益的轉讓、紅利及保單中未清還的保單貸款數額，故以上所有各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"在核保部门,「拒绝名单」是指:",o:["尤其应该鼓励的风险","不鼓励争取或应拒绝的业务","给予代理人毋须在该年度内接受业务指示","直至缴付保费之前,不应接受新业务"],a:1,e:"「拒绝名单」指不鼓励争取或应拒绝的业务，供核保人员参考。尤其该鼓励的风险相反，其余两项与名单功能无关。",src:1,tw:{ch:"保險公司的主要功能",q:"在核保部門，「拒絕名單」是指:",o:["尤其應該鼓勵的風險","不鼓勵爭取或應拒絕的業務","給予代理人毋須在該年度內接受業務指示","直至繳付保費之前，不應接受新業務"],e:"「拒絕名單」指不鼓勵爭取或應拒絕的業務，供核保人員參考。尤其該鼓勵的風險相反，其餘兩項與名單功能無關。"}},
{p:1,ch:"保险公司的主要功能",q:"在非人寿保险中的目标风险是:",o:["保额低的指定风险","保险人喜欢保障的风险","保险人不喜欢保障的风险","给予中介人佣金率最高的风险"],a:2,e:"非人寿保险中的「目标风险」指保险人不喜欢保障的高风险业务。保额低的指定风险、保险人喜欢保障的风险、佣金最高的风险，均与目标风险的涵义相反或无关。",src:1,tw:{ch:"保險公司的主要功能",q:"在非人壽保險中的目標風險是：",o:["保額低的指定風險","保險人喜歡保障的風險","保險人不喜歡保障的風險","給予中介人佣金率最高的風險"],e:"非人壽保險中的「目標風險」指保險人不喜歡保障的高風險業務。保額低的指定風險、保險人喜歡保障的風險、佣金最高的風險，均與目標風險的涵義相反或無關。"}},
{p:1,ch:"保险公司的主要功能",q:"培训与发展部门在保险公司内部是很重要,培训和教育的分别在于:",o:["两者的意义大致相同","培训不是由内部职员负责指导","培训的目的是为了考取专业资格考试","教育可视为对较为广博知识的学习"],a:3,e:"培训与教育的分别在于：教育可视为对较广博知识的学习，培训则专注特定工作技能。两者意义并非相同，培训也可由内部职员指导，目的不只为了公开考试。",src:1,tw:{ch:"保險公司的主要功能",q:"培訓與發展部門在保險公司內部是很重要，培訓和教育的分別在於：",o:["兩者的意義大致相同","培訓不是由內部職員負責指導","培訓的目的是為了考取專業資格考試","教育可視為對較為廣博知識的學習"],e:"培訓與教育的分別在於：教育可視為對較廣博知識的學習，培訓則專注特定工作技能。兩者意義並非相同，培訓也可由內部職員指導，目的不只為了公開考試。"}},
{p:1,ch:"保险公司的主要功能",q:"培训及发展部门培训对象是:",o:["所有内部人员及外勤人员","外勤人员而非内部人员","非外勤人员是内部人员","既非内部人员也非外勤人员"],a:0,e:"培训及发展部门的培训对象包括所有内部人员及外勤人员，两者同样重要。仅外勤或仅内勤的说法不完整。",src:1,tw:{ch:"保險公司的主要功能",q:"培訓及發展部門培訓對象是:",o:["所有內部人員及外勤人員","外勤人員而非內部人員","非外勤人員是內部人員","既非內部人員也非外勤人員"],e:"培訓及發展部門的培訓對象包括所有內部人員及外勤人員，兩者同樣重要。僅外勤或僅內勤的說法不完整。"}},
{p:1,ch:"保险公司的主要功能",q:"处理人寿保险与非人寿保险的理赔的二个共通点为数额及:",o:["保险人的责任","被保险人的责任","分担的可能性","代位权的可能性"],a:0,e:"处理人寿与非人寿保险理赔的两个共通点是赔偿数额及保险人的责任。被保险人的责任、分担、代位权并非两类保险共同面对的考量。",src:1,tw:{ch:"保險公司的主要功能",q:"處理人壽保險與非人壽保險的理賠的二個共通點為數額及：",o:["保險人的責任","被保險人的責任","分擔的可能性","代位權的可能性"],e:"處理人壽與非人壽保險理賠的兩個共通點是賠償數額及保險人的責任。被保險人的責任、分擔、代位權並非兩類保險共同面對的考量。"}},
{p:1,ch:"保险公司的主要功能",q:"处理任何保险赔案时,人寿保险公司及一般保险公司有两个共同特点,除考虑 责任外,还考虑什么?",o:["数额","分红保单涉及红利的因素","可能有还未清偿的保单贷款","对于死亡的真确性或死者的身份存在不确定的因素"],a:0,e:"处理任何赔案时，除考虑理赔责任外，还须考虑赔偿数额。红利因素、未清偿保单贷款、死亡真确性等是寿险特有，不属两类保险的共通点。",src:1,tw:{ch:"保險公司的主要功能",q:"處理任何保險賠案時，人壽保險公司及一般保險公司有兩個共同特點，除考慮 責任外，還考慮什麼?",o:["數額","分紅保單涉及紅利的因素","可能有還未清償的保單貸款","對於死亡的真確性或死者的身份存在不確定的因素"],e:"處理任何賠案時，除考慮理賠責任外，還須考慮賠償數額。紅利因素、未清償保單貸款、死亡真確性等是壽險特有，不屬兩類保險的共通點。"}},
{p:1,ch:"保险公司的主要功能",q:"如果理赔部门涉及复杂的保单贷款情况,保单的权益转让及现金红利/期末红利 的计算,那么很明显地,它正在处理的理赔属于:",o:["人身意外保险","人寿保险","火险","汽车保险"],a:1,e:"若理赔部门处理复杂的保单贷款、权益转让及现金红利或期末红利计算，显然是在处理人寿保险的理赔。人身意外、火险、汽车保险均无此类问题。",src:1,tw:{ch:"保險公司的主要功能",q:"如果理賠部門涉及複雜的保單貸款情況，保單的權益轉讓及現金紅利/期末紅利 的計算，那麼很明顯地，它正在處理的理賠屬於:",o:["人身意外保險","人壽保險","火險","汽車保險"],e:"若理賠部門處理複雜的保單貸款、權益轉讓及現金紅利或期末紅利計算，顯然是在處理人壽保險的理賠。人身意外、火險、汽車保險均無此類問題。"}},
{p:1,ch:"保险公司的主要功能",q:"定订保费率,储备计算及债务估值的职务应属于:",o:["会计及投资","精算","产品发展","市场推广"],a:1,e:"订定保费率、储备计算及债务估值属精算部门的职务。会计及投资、产品发展、市场推广均不承担这些技术性工作。",src:1,tw:{ch:"保險公司的主要功能",q:"定訂保費率，儲備計算及債務估值的職務應屬於：",o:["會計及投資","精算","產品發展","市場推廣"],e:"訂定保費率、儲備計算及債務估值屬精算部門的職務。會計及投資、產品發展、市場推廣均不承擔這些技術性工作。"}},
{p:1,ch:"保险公司的主要功能",q:"实际保单文件对于以下哪种保险业务是重要的?",o:["责任保险","人寿保险","火险","汽车保险"],a:1,e:"人寿保险的合约内容全载于保单文件，权利义务皆有赖其记载，故实际保单文件对人寿保险业务尤为重要。责任、火险、汽车保险的保单重要性相对较低。",src:1,tw:{ch:"保險公司的主要功能",q:"實際保單文件對於以下哪種保險業務是重要的?",o:["責任保險","人壽保險","火險","汽車保險"],e:"人壽保險的合約內容全載於保單文件，權利義務皆有賴其記載，故實際保單文件對人壽保險業務尤為重要。責任、火險、汽車保險的保單重要性相對較低。"}},
{p:1,ch:"保险公司的主要功能",q:"客户服务又称:",o:["保证销售","保单处理","顾客服务","公共关系"],a:2,e:"客户服务又称顾客服务。保证销售、保单处理、公共关系均为不同概念。",src:1,tw:{ch:"保險公司的主要功能",q:"客戶服務又稱:",o:["保證銷售","保單處理","顧客服務","公共關係"],e:"客户服務又稱顧客服務。保證銷售、保單處理、公共關係均為不同概念。"}},
{p:1,ch:"保险公司的主要功能",q:"对于一般保险理赔部门来说,以下哪项有关的陈述是不正确的?",o:["非集中形式处理索偿是颇为普遍","责任索偿可能涉及大额款项","可能出现的理赔范围比人寿保险要大","在支付红利的情况下,必须小心核对有关的保单"],a:3,e:"红利属人寿分红保单特有，一般保险理赔无支付红利的核对问题，故该项不正确。非集中处理普遍、责任索偿大额、理赔范围较大，均属一般保险理赔的正确描述。",src:1,tw:{ch:"保險公司的主要功能",q:"對於一般保險理賠部門來說，以下哪項有關的陳述是不正確的?",o:["非集中形式處理索償是頗為普遍","責任索償可能涉及大額款項","可能出現的理賠範圍比人壽保險要大","在支付紅利的情況下，必須小心核對有關的保單"],e:"紅利屬人壽分紅保單特有，一般保險理賠無支付紅利的核對問題，故該項不正確。非集中處理普遍、責任索償大額、理賠範圍較大，均屬一般保險理賠的正確描述。"}},
{p:1,ch:"保险公司的主要功能",q:"对于保险公司的运作来说,核保可解作:",o:["销售行动","对任何未能出售的股票承担责任","作为保险目的而进行的风险评估","保单和其他何约文件的实际签署"],a:2,e:"核保可解作为保险目的而进行的风险评估与选择。销售行动、对未售股票承担责任、签署保单文件，均非核保的含义。",src:1,tw:{ch:"保險公司的主要功能",q:"對於保險公司的運作來說，核保可解作:",o:["銷售行動","對任何未能出售的股票承擔責任","作為保險目的而進行的風險評估","保單和其他何約文件的實際簽署"],e:"核保可解作為保險目的而進行的風險評估與選擇。銷售行動、對未售股票承擔責任、簽署保單文件，均非核保的含義。"}},
{p:1,ch:"保险公司的主要功能",q:"对于公共关系、赞助及广告是属于下列哪个部门的职务?",o:["核保","保单销售","保单处理","市场行销及促销部门"],a:3,e:"公共关系、赞助及广告属市场行销及促销部门的职务。核保、保单销售、保单处理各有其职，不负责此等工作。",src:1,tw:{ch:"保險公司的主要功能",q:"對於公共關係、贊助及廣告是屬於下列哪個部門的職務?",o:["核保","保單銷售","保單處理","市場行銷及促銷部門"],e:"公共關係、贊助及廣告屬市場行銷及促銷部門的職務。核保、保單銷售、保單處理各有其職，不負責此等工作。"}},
{p:1,ch:"保险公司的主要功能",q:"对于培训及发展部门,以下哪项的描述是正确的? i 培训对于内勤及外勤的员工同样重要 ii 它必须与公司的需要配合 iii 它必须由非职员提供 iv 资源及纪录对提高该部门的运作效率是非常重要的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"培训对内勤与外勤员工同样重要（i）、必须与公司需要配合（ii）及重视资源纪录以提高效率（iv）均正确；培训不一定须由非职员提供（iii），故iii错误。",src:1,tw:{ch:"保險公司的主要功能",q:"對於培訓及發展部門，以下哪項的描述是正確的? i 培訓對於內勤及外勤的員工同樣重要 ii 它必須與公司的需要配合 iii 它必須由非職員提供 iv 資源及紀錄對提高該部門的運作效率是非常重要的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"培訓對內勤與外勤員工同樣重要（i）、必須與公司需要配合（ii）及重視資源紀錄以提高效率（iv）均正確；培訓不一定須由非職員提供（iii），故iii錯誤。"}},
{p:1,ch:"保险公司的主要功能",q:"对人寿保险人是极为合意的业务类型,或在非寿险中有时指广泛,危险性高的 风险术语是?",o:["纯粹风险","目标风险","特定风险","基本风险"],a:1,e:"「目标风险」在人寿保险中指保险人极愿承保的理想业务，在非寿险中则指广泛而危险性高的风险。纯粹风险、特定风险、基本风险均非此术语。",src:1,tw:{ch:"保險公司的主要功能",q:"對人壽保險人是極為合意的業務類型，或在非壽險中有時指廣泛，危險性高的 風險術語是？",o:["純粹風險","目標風險","特定風險","基本風險"],e:"「目標風險」在人壽保險中指保險人極願承保的理想業務，在非壽險中則指廣泛而危險性高的風險。純粹風險、特定風險、基本風險均非此術語。"}},
{p:1,ch:"保险公司的主要功能",q:"对很多险种来说,通常在收到保费之前保障已经开始生效,但是,以下哪业务 种类几乎总是根据第一笔保费才能确定合约的存在?",o:["人寿保险","火灾保险","人身意外保险","以上各项皆是"],a:0,e:"人寿保险通常以首期保费缴付为合约生效条件，几乎总须凭第一笔保费确定合约存在。火灾、人身意外等一般保险的保障，常在未收到保费前已开始生效。",src:1,tw:{ch:"保險公司的主要功能",q:"對很多險種來說，通常在收到保費之前保障已經開始生效，但是，以下哪業務 種類幾乎總是根據第一筆保費才能確定合約的存在?",o:["人壽保險","火災保險","人身意外保險","以上各項皆是"],e:"人壽保險通常以首期保費繳付為合約生效條件，幾乎總須憑第一筆保費確定合約存在。火災、人身意外等一般保險的保障，常在未收到保費前已開始生效。"}},
{p:1,ch:"保险公司的主要功能",q:"寿险保单核保工作尤为重要,以下哪项原因是正确的:",o:["保险标的是人类","保险人不能单方面取消保单","寿险保单的保额通常巨大","寿险保单牵涉的佣金较大"],a:1,e:"寿险保险人日后不能单方面取消保单，核保须在承保时作准，故尤为重要。保险标的是人类、保额巨大、佣金较大均非根本原因。",src:1,tw:{ch:"保險公司的主要功能",q:"壽險保單核保工作尤為重要，以下哪項原因是正確的:",o:["保險標的是人類","保險人不能單方面取消保單","壽險保單的保額通常巨大","壽險保單牽涉的佣金較大"],e:"壽險保險人日後不能單方面取消保單，核保須在承保時作準，故尤為重要。保險標的是人類、保額巨大、佣金較大均非根本原因。"}},
{p:1,ch:"保险公司的主要功能",q:"市场行销及促销部主要负责哪项或哪些职务?",o:["协调对外的联系","协调媒介的查询及采访","准备新闻稿及副本予工商界及其他杂志报章","以上各项皆是"],a:3,e:"市场行销及促销部负责协调对外联系、协调媒介的查询采访，以及准备新闻稿及副本，故以上各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"市場行銷及促銷部主要負責哪項或哪些職務?",o:["協調對外的聯繫","協調媒介的查詢及採訪","準備新聞稿及副本予工商界及其他雜誌報章","以上各項皆是"],e:"市場行銷及促銷部負責協調對外聯繫、協調媒介的查詢採訪，以及準備新聞稿及副本，故以上各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"市场行销及促销部的功能不包括:",o:["公共关系","市场调查","处理投诉","推广公司业务"],a:2,e:"处理投诉属客户服务部的功能，不在市场行销及促销部范围内。公共关系、市场调查、推广公司业务均属其职能。",src:1,tw:{ch:"保險公司的主要功能",q:"市場行銷及促銷部的功能不包括:",o:["公共關係","市場調查","處理投訴","推廣公司業務"],e:"處理投訴屬客户服務部的功能，不在市場行銷及促銷部範圍內。公共關係、市場調查、推廣公司業務均屬其職能。"}},
{p:1,ch:"保险公司的主要功能",q:"市场行销部不断地监察当前及潜在的市场,这过程称为:",o:["宣传","市场调查","监察","服务提升"],a:1,e:"市场行销部不断监察当前及潜在市场，此过程称为市场调查。宣传、监察、服务提升均非此特定术语。",src:1,tw:{ch:"保險公司的主要功能",q:"市場行銷部不斷地監察當前及潛在的市場，這過程稱為:",o:["宣傳","市場調查","監察","服務提昇"],e:"市場行銷部不斷監察當前及潛在市場，此過程稱為市場調查。宣傳、監察、服務提升均非此特定術語。"}},
{p:1,ch:"保险公司的主要功能",q:"广告是很重要的环节,促销及行销的广告职能是:",o:["挑选外面的代理机构","协调广告活动","研究采用电视或其他媒介的程度","以上各项皆是"],a:3,e:"促销及行销的广告职能包括挑选广告代理、协调广告活动，以及研究采用电视或其他媒介的程度，故以上各项皆是。",src:1,tw:{ch:"保險公司的主要功能",q:"廣告是很重要的環節，促銷及行銷的廣告職能是:",o:["挑選外面的代理機構","協調廣告活動","研究採用電視或其他媒介的程度","以上各項皆是"],e:"促銷及行銷的廣告職能包括挑選廣告代理、協調廣告活動，以及研究採用電視或其他媒介的程度，故以上各項皆是。"}},
{p:1,ch:"保险公司的主要功能",q:"投诉、联络、提供文件及公共关系的职务属于哪个部门负责?",o:["核保部","客户服务部","行销及推广部","产品开发部"],a:1,e:"投诉、联络、提供文件及公共关系均属客户服务部的职务。核保部、行销推广部、产品开发部各司其职。",src:1,tw:{ch:"保險公司的主要功能",q:"投訴、聯絡、提供文件及公共關係的職務屬於哪個部門負責？",o:["核保部","客戶服務部","行銷及推廣部","產品開發部"],e:"投訴、聯絡、提供文件及公共關係均屬客户服務部的職務。核保部、行銷推广部、產品開發部各司其職。"}},
{p:1,ch:"保险公司的主要功能",q:"查核保单的准确程度及续保,相当可能属于以下哪个部门的工作?",o:["理赔","核保","保单处理","市场行销及促销"],a:2,e:"查核保单的准确程度及办理续保，属保单处理部门的工作。理赔、核保、市场行销及促销均不负责此项。",src:1,tw:{ch:"保險公司的主要功能",q:"查核保單的準確程度及續保，相當可能屬於以下哪個部門的工作?",o:["理賠","核保","保單處理","市場行銷及促銷"],e:"查核保單的準確程度及辦理續保，屬保單處理部門的工作。理賠、核保、市場行銷及促銷均不負責此項。"}},
{p:1,ch:"保险公司的主要功能",q:"火灾保险中「目标风险」一词指:",o:["没有什么价值的投保物件","一项大的,很高的风险","一项普遍的风险","很低的保费率"],a:1,e:"火灾保险中的「目标风险」指一项特别庞大、危险度很高的风险。没有什么价值的投保物件、普遍风险、很低保费率均与此含义不符。",src:1,tw:{ch:"保險公司的主要功能",q:"火災保險中「目標風險」一詞指:",o:["沒有什麼價值的投保物件","一項大的，很高的風險","一項普遍的風險","很低的保費率"],e:"火災保險中的「目標風險」指一項特別龐大、危險度很高的風險。沒有什麼價值的投保物件、普遍風險、很低保費率均與此含義不符。"}},
{p:1,ch:"保险公司的主要功能",q:"选择承保风险及决定采用甚么保险条款属于哪部门工作?",o:["核保部门","理赔部门","精算部门","会计部门"],a:0,e:"选择承保风险及决定采用什么保险条款，属核保部门的工作。理赔、精算、会计部门不承担此职。",src:1,tw:{ch:"保險公司的主要功能",q:"選擇承保風險及決定採用甚麼保險條款屬於哪部門工作？",o:["核保部門","理賠部門","精算部門","會計部門"],e:"選擇承保風險及決定採用什麼保險條款，屬核保部門的工作。理賠、精算、會計部門不承擔此職。"}},
{p:1,ch:"保险公司的主要功能",q:"非人寿保险的目标风险,很大可能是指以下哪项风险?",o:["极低保额的保险","保险人极为合意的业务","保险人极不合意的业务","给予中介人最高佣金率的业务"],a:2,e:"非人寿保险的目标风险，很大可能指保险人极不合意的业务，即广泛而危险性高的风险。极低保额、保险人极合意、佣金最高均与目标风险的涵义相反或无关。",src:1,tw:{ch:"保險公司的主要功能",q:"非人壽保險的目標風險，很大可能是指以下哪項風險？",o:["極低保額的保險","保險人極為合意的業務","保險人極不合意的業務","給予中介人最高佣金率的業務"],e:"非人壽保險的目標風險，很大可能指保險人極不合意的業務，即廣泛而危險性高的風險。極低保額、保險人極合意、佣金最高均與目標風險的涵義相反或無關。"}},
{p:1,ch:"香港保险业的结构",q:"《保险业条例》把保险业务分为两大法定类别,其中一种是长期业务,另一种是:",o:["特殊业务","意外保险","责任保险","一般保险"],a:3,e:"《保险业条例》把保险业务分为长期业务及一般业务两大法定类别。特殊业务、意外保险、责任保险均非此第二大法定类别的名称。",src:1,tw:{ch:"香港保險業的結構",q:"《保險業條例》把保險業務分為兩大法定類別，其中一種是長期業務，另一種是:",o:["特殊業務","意外保險","責任保險","一般保險"],e:"《保險業條例》把保險業務分為長期業務及一般業務兩大法定類別。特殊業務、意外保險、責任保險均非此第二大法定類別的名稱。"}},
{p:1,ch:"香港保险业的结构",q:"《保险业条例》第70条赋予保险业监管局批准保险经纪团体成立的权力。到目前为止,这类经批 准的保险经纪团体有:",o:["一个","两个","三个","四个"],a:1,e:"《保险业条例》第70条赋予保险业监管局批准保险经纪团体成立的权力，至今获批准的保险经纪团体共有两个。一个、三个、四个均不符。",src:1,tw:{ch:"香港保險業的結構",q:"《保險業條例》第70條賦予保險業監管局批准保險經紀團體成立的權力。到目前為止，這類經批 准的保險經紀團體有：",o:["一個","兩個","三個","四個"],e:"《保險業條例》第70條賦予保險業監管局批准保險經紀團體成立的權力，至今獲批准的保險經紀團體共有兩個。一個、三個、四個均不符。"}},
{p:1,ch:"香港保险业的结构",q:"「保险人向其他保险人/再保险人购买保险,以取得保障」是指:",o:["分出再保险","分入再保险","专业再保险","以上三项皆不是"],a:0,e:"保险人向其他保险人或再保险人购买保险以取得保障，即把风险分出，称分出再保险。分入再保险是再保险人接受业务的角度，专业再保险指只做再保险的公司。",src:1,tw:{ch:"香港保險業的結構",q:"「保險人向其他保險人/再保險人購買保險,以取得保障」是指:",o:["分出再保險","分入再保險","專業再保險","以上三項皆不是"],e:"保險人向其他保險人或再保險人購買保險以取得保障，即把風險分出，稱分出再保險。分入再保險是再保險人接受業務的角度，專業再保險指只做再保險的公司。"}},
{p:1,ch:"香港保险业的结构",q:"专业再保险人是指:",o:["已取得专业评审资格","对大而危险的风险具备经验","只经营单一类型业务的保险","只提供再保险"],a:3,e:"专业再保险人指只提供再保险、不直接承保原保险的保险人。与取得专业资格、对高危风险具经验、只经营单一类型业务等均无关。",src:1,tw:{ch:"香港保險業的結構",q:"專業再保險人是指：",o:["已取得專業評審資格","對大而危險的風險具備經驗","只經營單一類型業務的保險","只提供再保險"],e:"專業再保險人指只提供再保險、不直接承保原保險的保險人。與取得專業資格、對高危風險具經驗、只經營單一類型業務等均無關。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪一项不属于长期业务?",o:["意外","人寿及","婚姻及出生","永久健康"],a:0,e:"意外保险属一般业务，不属于长期业务。人寿及年金、婚姻及出生、永久健康均属长期业务范畴。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪一項不屬於長期業務?",o:["意外","人壽及","婚姻及出生","永久健康"],e:"意外保險屬一般業務，不屬於長期業務。人壽及年金、婚姻及出生、永久健康均屬長期業務範疇。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪项属于一般保险业务?",o:["意外","汽车保险","船舶的法律责任","以上各项皆是"],a:3,e:"意外、汽车保险、船舶的法律责任均属一般保险业务，故以上各项皆是。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪項屬於一般保險業務？",o:["意外","汽車保險","船舶的法律責任","以上各項皆是"],e:"意外、汽車保險、船舶的法律責任均屬一般保險業務，故以上各項皆是。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪项或哪些是保险业中的学术分类?",o:["建筑保险","经济权益保险","一篮子保险","以上各项皆是"],a:1,e:"保险业的学术分类按标的或功能分为人身、财产、责任及经济权益保险，故经济权益保险属之。建筑保险、一篮子保险是具体险种或组合，非该学术分类。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪項或哪些是保險業中的學術分類？",o:["建築保險","經濟權益保險","一籃子保險","以上各項皆是"],e:"保險業的學術分類按標的或功能分為人身、財產、責任及經濟權益保險，故經濟權益保險屬之。建築保險、一籃子保險是具體險種或組合，非該學術分類。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪项是保险公司 (雇员补偿) 无力偿债管理局的职责?",o:["处理续保纠纷","就已无力偿债的会员保险人的雇员补偿保单责任承担责任","处理违规纠纷","就无力偿债的雇主承担责任"],a:1,e:"保险公司（雇员补偿）无力偿债管理局的职责，是对已无力偿债会员保险人的雇员补偿保单责任承担责任。处理续保纠纷、违规纠纷、为无力偿债雇主担责，均非其职责。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪項是保險公司 (僱員補償) 無力償債管理局的職責？",o:["處理續保糾紛","就已無力償債的會員保險人的僱員補償保單責任承擔責任","處理違規糾紛","就無力償債的僱主承擔責任"],e:"保險公司（僱員補償）無力償債管理局的職責，是對已無力償債會員保險人的僱員補償保單責任承擔責任。處理續保糾紛、違規糾紛、為無力償債僱主擔責，均非其職責。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪项是有关香港保险业联会的正确描述?",o:["所有在香港经营保险业务的保险人总是其会员","除了代表本港的保险人,亦代表再保险人的共同利益","提倡会员的效率","受保险监管机构承认为「保险人及经纪的代表组织」"],a:1,e:"香港保险业联会除代表本港保险人外，亦代表再保险人的共同利益，故该项正确。所有保险人总是会员过于绝对，其余对其角色与获承认性质的表述不准确。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪項是有關香港保險業聯會的正確描述？",o:["所有在香港經營保險業務的保險人總是其會員","除了代表本港的保險人，亦代表再保險人的共同利益","提倡會員的效率","受保險監管機構承認為「保險人及經紀的代表組織」"],e:"香港保險業聯會除代表本港保險人外，亦代表再保險人的共同利益，故該項正確。所有保險人總是會員過於絕對，其餘對其角色與獲承認性質的表述不準確。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪项是香港汽车保险局的基本职责:",o:["为汽车意外受害者而提供福利","对汽车保险索偿作出裁决","为未偿清的汽车意外的赔偿作出补偿","厘定汽车保险应收取的保险费"],a:2,e:"香港汽车保险局的基本职责，是对未能清偿的汽车意外赔偿作出补偿，保障无辜受害人。为受害者提供福利、裁决索偿、厘定保费均非其职能。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪項是香港汽車保險局的基本職責：",o:["為汽車意外受害者而提供福利","對汽車保險索償作出裁決","為未償清的汽車意外的賠償作出補償","釐定汽車保險應收取的保險費"],e:"香港汽車保險局的基本職責，是對未能清償的汽車意外賠償作出補償，保障無辜受害人。為受害者提供福利、裁決索償、釐定保費均非其職能。"}},
{p:1,ch:"香港保险业的结构",q:"以下哪项符合专业再保险人的描述?",o:["具备专业资格","只负责某一种保险业务","专门负责续保工作","只负责再保险"],a:3,e:"专业再保险人指只负责再保险业务的保险人。具备专业资格、只负责某一种保险业务、专门负责续保，均非专业再保险人的准确定义。",src:1,tw:{ch:"香港保險業的結構",q:"以下哪項符合專業再保險人的描述？",o:["具備專業資格","只負責某一種保險業務","專門負責續保工作","只負責再保險"],e:"專業再保險人指只負責再保險業務的保險人。具備專業資格、只負責某一種保險業務、專門負責續保，均非專業再保險人的準確定義。"}},
{p:1,ch:"香港保险业的结构",q:"以人身保险、财产保险、责任保险及经济权益保险作为保险的业务分类的类别称为:",o:["业务来源分类","部门式分类","功能式分类","学术分类"],a:3,e:"以人身保险、财产保险、责任保险及经济权益保险作为业务分类，是按标的或功能划分的学术分类。业务来源、部门式、功能式分类均非此分法。",src:1,tw:{ch:"香港保險業的結構",q:"以人身保險、財產保險、責任保險及經濟權益保險作為保險的業務分類的類別稱為：",o:["業務來源分類","部門式分類","功能式分類","學術分類"],e:"以人身保險、財產保險、責任保險及經濟權益保險作為業務分類，是按標的或功能劃分的學術分類。業務來源、部門式、功能式分類均非此分法。"}},
{p:1,ch:"香港保险业的结构",q:"以寿险、海上保险、火险及意外业务类型作为保险的业务分类的类别称为:",o:["业务来源分类","部门式分类","功能式分类","学术分类"],a:1,e:"以寿险、海上保险、火险及意外业务类型作分类，称为部门式分类。业务来源、功能式、学术分类均非此分法。",src:1,tw:{ch:"香港保險業的結構",q:"以壽險、海上保險、火險及意外業務類型作為保險的業務分類的類別稱為：",o:["業務來源分類","部門式分類","功能式分類","學術分類"],e:"以壽險、海上保險、火險及意外業務類型作分類，稱為部門式分類。業務來源、功能式、學術分類均非此分法。"}},
{p:1,ch:"香港保险业的结构",q:"保险业务传统分类方法分为四类别:寿险、海上保险、火险及意外险,这种分类方法可描述为:",o:["法定分类","功能分类","部门式分类","年代分类"],a:2,e:"保险业务传统分类分为寿险、海上保险、火险及意外险四类，这种分类方法可描述为部门式分类。法定、功能、年代分类均不符。",src:1,tw:{ch:"香港保險業的結構",q:"保險業務傳統分類方法分為四類別：壽險、海上保險、火險及意外險，這種分類方法可描述為:",o:["法定分類","功能分類","部門式分類","年代分類"],e:"保險業務傳統分類分為壽險、海上保險、火險及意外險四類，這種分類方法可描述為部門式分類。法定、功能、年代分類均不符。"}},
{p:1,ch:"香港保险业的结构",q:"保险公司 (雇员补偿) 无力偿债管理局的经费来自:",o:["特区政府","保险业联会","保险索偿投诉局","雇员补偿保费的附加费"],a:3,e:"保险公司（雇员补偿）无力偿债管理局的经费，来自雇员补偿保费的附加费。特区政府、保险业联会、保险索偿投诉局均非经费来源。",src:1,tw:{ch:"香港保險業的結構",q:"保險公司 (僱員補償) 無力償債管理局的經費來自：",o:["特區政府","保險業聯會","保險索償投訴局","僱員補償保費的附加費"],e:"保險公司（僱員補償）無力償債管理局的經費，來自僱員補償保費的附加費。特區政府、保險業聯會、保險索償投訴局均非經費來源。"}},
{p:1,ch:"香港保险业的结构",q:"保险可按保险标的或功能作分类,以下哪项不属于经济权益保险的功能分类:",o:["租金","信贷","火险","以上各项都是"],a:2,e:"经济权益保险按功能分类包括租金、信贷等经济损失保障；火险属财产保险范畴，故不属于经济权益保险。租金、信贷均属经济权益保险。",src:1,tw:{ch:"香港保險業的結構",q:"保險可按保險標的或功能作分類，以下哪項不屬於經濟權益保險的功能分類：",o:["租金","信貸","火險","以上各項都是"],e:"經濟權益保險按功能分類包括租金、信貸等經濟損失保障；火險屬財產保險範疇，故不屬於經濟權益保險。租金、信貸均屬經濟權益保險。"}},
{p:1,ch:"香港保险业的结构",q:"再保险人又称?",o:["专业再保险人","独立再保险人","间接再保险人","指定再保险人"],a:0,e:"只经营再保险业务的保险人称为专业再保险人，故再保险人又称专业再保险人。独立、间接、指定再保险人均非通用术语。",src:1,tw:{ch:"香港保險業的結構",q:"再保險人又稱?",o:["專業再保險人","獨立再保險人","間接再保險人","指定再保險人"],e:"只經營再保險業務的保險人稱為專業再保險人，故再保險人又稱專業再保險人。獨立、間接、指定再保險人均非通用術語。"}},
{p:1,ch:"香港保险业的结构",q:"只参与再保险业务的保险人称为:",o:["专属再保险人","分出再保险人","分入再保险人","专业再保险人"],a:3,e:"只参与再保险业务的保险人称为专业再保险人。专属、分出、分入再保险人所指的角色不同，并非本题所指。",src:1,tw:{ch:"香港保險業的結構",q:"只參與再保險業務的保險人稱為：",o:["專屬再保險人","分出再保險人","分入再保險人","專業再保險人"],e:"只參與再保險業務的保險人稱為專業再保險人。專屬、分出、分入再保險人所指的角色不同，並非本題所指。"}},
{p:1,ch:"香港保险业的结构",q:"哪个历史悠久的团体是为保险人争取利益?",o:["香港保险业联会","香港保险学会","保险业监管局","香港保险顾问联会"],a:0,e:"香港保险业联会历史最悠久，是为保险人争取共同利益的组织。香港保险学会侧重教育，保险业监管局是监管机构，香港保险顾问联会代表经纪。",src:1,tw:{ch:"香港保險業的結構",q:"哪個歷史悠久的團體是為保險人爭取利益？",o:["香港保險業聯會","香港保險學會","保險業監管局","香港保險顧問聯會"],e:"香港保險業聯會歷史最悠久，是為保險人爭取共同利益的組織。香港保險學會側重教育，保險業監管局是監管機構，香港保險顧問聯會代表經紀。"}},
{p:1,ch:"香港保险业的结构",q:"因意外丧失能力或健康欠佳提供利益的长期保单是指:",o:["意外","永久健康","意外及疾病","人寿及年金"],a:1,e:"因意外丧失能力或健康欠佳而提供利益的长期保单，称为永久健康保险。意外属一般业务，意外及疾病、人寿及年金均非此特定定义。",src:1,tw:{ch:"香港保險業的結構",q:"因意外喪失能力或健康欠佳提供利益的長期保單是指：",o:["意外","永久健康","意外及疾病","人壽及年金"],e:"因意外喪失能力或健康欠佳而提供利益的長期保單，稱為永久健康保險。意外屬一般業務，意外及疾病、人壽及年金均非此特定定義。"}},
{p:1,ch:"香港保险业的结构",q:"在《保险业条例》中,以下哪些不属于长期业务?",o:["人寿及","财产损坏","相连长期","以上各项皆是"],a:1,e:"财产损坏属一般业务，不属于《保险业条例》下的长期业务。人寿及年金、相连长期均属长期业务，故「以上各项皆是」不成立。",src:1,tw:{ch:"香港保險業的結構",q:"在《保險業條例》中，以下哪些不屬於長期業務？",o:["人壽及","財產損壞","相連長期","以上各項皆是"],e:"財產損壞屬一般業務，不屬於《保險業條例》下的長期業務。人壽及年金、相連長期均屬長期業務，故「以上各項皆是」不成立。"}},
{p:1,ch:"香港保险业的结构",q:"在《保险业条例》中,以下哪些属于长期业务?",o:["火险","汽车","永久健康","水险"],a:2,e:"永久健康属《保险业条例》下的长期业务。火险、汽车、水险均属一般业务。",src:1,tw:{ch:"香港保險業的結構",q:"在《保險業條例》中，以下哪些屬於長期業務？",o:["火險","汽車","永久健康","水險"],e:"永久健康屬《保險業條例》下的長期業務。火險、汽車、水險均屬一般業務。"}},
{p:1,ch:"香港保险业的结构",q:"在保险法定类别中,保险以业务作为分类,可分为长期业务及一般业务,以下哪项陈述是正确的 ?",o:["一般保险主要涉及人寿保险","长期保险主要涉及人寿保险","长期保险的种类比一般保险为多","以上各项皆是"],a:1,e:"长期业务主要涉及人寿相关保险（人寿、年金、永久健康等），故该项正确。一般保险主要涉及人寿相反，长期保险种类比一般多亦不成立。",src:1,tw:{ch:"香港保險業的結構",q:"在保險法定類別中，保險以業務作為分類，可分為長期業務及一般業務，以下哪項陳述是正確的 ？",o:["一般保險主要涉及人壽保險","長期保險主要涉及人壽保險","長期保險的種類比一般保險為多","以上各項皆是"],e:"長期業務主要涉及人壽相關保險（人壽、年金、永久健康等），故該項正確。一般保險主要涉及人壽相反，長期保險種類比一般多亦不成立。"}},
{p:1,ch:"香港保险业的结构",q:"在香港,保险公司一般会采用英式或美式的保险分类,美式保险的特点是:",o:["人寿与非人寿保险是分开的","非人寿保险分为: 火险、海上保险、保证险和意外险","非人寿保险分为: 火险和意外险","以上 A B两项"],a:3,e:"美式分类把人寿与非人寿分开，非人寿再分为火险、海上保险、保证险和意外险，即A、B两项均正确，故选A及B。",src:1,tw:{ch:"香港保險業的結構",q:"在香港，保險公司一般會採用英式或美式的保險分類，美式保險的特點是:",o:["人壽與非人壽保險是分開的","非人壽保險分為: 火險、海上保險、保證險和意外險","非人壽保險分為: 火險和意外險","以上 A B兩項"],e:"美式分類把人壽與非人壽分開，非人壽再分為火險、海上保險、保證險和意外險，即A、B兩項均正確，故選A及B。"}},
{p:1,ch:"香港保险业的结构",q:"在香港获授权的保险人,划分为纯一般业务保险人、纯长期业务保险人及:",o:["综合业务保险人","双重业务保险人","两险种保险人","多险种保险人"],a:0,e:"在香港获授权的保险人划分为纯一般业务保险人、纯长期业务保险人及综合业务保险人（兼营两者）。双重、两险种、多险种均非标准称谓。",src:1,tw:{ch:"香港保險業的結構",q:"在香港獲授權的保險人，劃分為純一般業務保險人、純長期業務保險人及：",o:["綜合業務保險人","雙重業務保險人","兩險種保險人","多險種保險人"],e:"在香港獲授權的保險人劃分為純一般業務保險人、純長期業務保險人及綜合業務保險人（兼營兩者）。雙重、兩險種、多險種均非標準稱謂。"}},
{p:1,ch:"香港保险业的结构",q:"客户类型是保险分类方法之一,客户对象为:",o:["私人及业务","个人及非个人","个人或商号和机构","业务及非业务"],a:2,e:"按客户类型分类，客户对象分为个人或商号和机构两大类。其余选项未准确反映此两分法。",src:1,tw:{ch:"香港保險業的結構",q:"客戶類型是保險分類方法之一，客戶對象為：",o:["私人及業務","個人及非個人","個人或商號和機構","業務及非業務"],e:"按客户類型分類，客户對象分為個人或商號和機構兩大類。其餘選項未準確反映此兩分法。"}},
{p:1,ch:"香港保险业的结构",q:"对于本地保险中介人,以下哪项描述为正确?",o:["根据定义,所有银行都是保险中介人","他们只包括保险代理人及其雇员","所有保险上的安排不可能没有保险中介人的参与","他们包括保险代理人及保险经纪"],a:3,e:"本地保险中介人包括保险代理人及保险经纪，故该项正确。所有银行都是中介（除非获委任）错误、只包括代理人错误、不可能没有中介参与亦过于绝对。",src:1,tw:{ch:"香港保險業的結構",q:"對於本地保險中介人，以下哪項描述為正確？",o:["根據定義，所有銀行都是保險中介人","他們只包括保險代理人及其僱員","所有保險上的安排不可能沒有保險中介人的參與","他們包括保險代理人及保險經紀"],e:"本地保險中介人包括保險代理人及保險經紀，故該項正確。所有銀行都是中介（除非獲委任）錯誤、只包括代理人錯誤、不可能沒有中介參與亦過於絕對。"}},
{p:1,ch:"香港保险业的结构",q:"属于《保险业条例》下之长期业务?",o:["婚姻及出生","一般法律责任","意外","退休计划管理第4类"],a:0,e:"婚姻及出生保险属《保险业条例》下的长期业务。一般法律责任、意外属一般业务，退休计划管理第4类非长期业务的保险类别。",src:1,tw:{ch:"香港保險業的結構",q:"屬於《保險業條例》下之長期業務?",o:["婚姻及出生","一般法律責任","意外","退休計劃管理第4類"],e:"婚姻及出生保險屬《保險業條例》下的長期業務。一般法律責任、意外屬一般業務，退休計劃管理第4類非長期業務的保險類別。"}},
{p:1,ch:"香港保险业的结构",q:"按保险的功能分类方法,以下哪项不包括在内?",o:["责任保险","财产保险","人身保险","个人保险"],a:3,e:"按保险的功能分类分为人身、财产、责任及经济权益保险，个人保险不在此分类内（可作客户分类）。责任、财产、人身保险均属功能分类。",src:1,tw:{ch:"香港保險業的結構",q:"按保險的功能分類方法，以下哪項不包括在內？",o:["責任保險","財產保險","人身保險","個人保險"],e:"按保險的功能分類分為人身、財產、責任及經濟權益保險，個人保險不在此分類內（可作客户分類）。責任、財產、人身保險均屬功能分類。"}},
{p:1,ch:"香港保险业的结构",q:"有些保险人根据其业务来源来给其保险业务分类,通常是三类,下列哪一项不是其中一类?",o:["由保险代理人而来","由保险经纪而来","直接从大众人士而来","从已存在的顾客推荐而来的"],a:3,e:"按业务来源分类通常为三类：由保险代理人而来、由保险经纪而来、直接来自大众人士。从已存在顾客推荐而来不属于这三种标准来源。",src:1,tw:{ch:"香港保險業的結構",q:"有些保險人根據其業務來源來給其保險業務分類,通常是三類，下列哪一項不是其中一類?",o:["由保險代理人而來","由保險經紀而來","直接從大眾人士而來","從已存在的顧客推薦而來的"],e:"按業務來源分類通常為三類：由保險代理人而來、由保險經紀而來、直接來自大眾人士。從已存在顧客推薦而來不屬於這三種標準來源。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险业条例》,以下哪项保险法定类别的分类是不正确?",o:["联合养老保险归入长期业务","船舶归入一般业务","永久健康归入一般业务","人寿及归入长期业务"],a:2,e:"永久健康应归入长期业务而非一般业务，故该项分类不正确。联合养老保险归长期业务、船舶归一般业务、人寿及年金归长期业务均正确。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險業條例》，以下哪項保險法定類別的分類是不正確？",o:["聯合養老保險歸入長期業務","船舶歸入一般業務","永久健康歸入一般業務","人壽及歸入長期業務"],e:"永久健康應歸入長期業務而非一般業務，故該項分類不正確。聯合養老保險歸長期業務、船舶歸一般業務、人壽及年金歸長期業務均正確。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险业条例》,基本上采用了英国及欧洲联盟的形式以确定业务分类,把保险分为长期业 务及一般业务两类,以下哪些属于长期业务?",o:["汽车","婚姻","旅游","强积金第一类"],a:1,e:"婚姻保险属长期业务。汽车、旅游属一般业务，强积金第一类并非长期业务的保险类别范畴。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險業條例》，基本上採用了英國及歐洲聯盟的形式以確定業務分類，把保險分為長期業 務及一般業務兩類，以下哪些屬於長期業務?",o:["汽車","婚姻","旅遊","強積金第一類"],e:"婚姻保險屬長期業務。汽車、旅遊屬一般業務，強積金第一類並非長期業務的保險類別範疇。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险业条例》以下哪项为一般而非长期业务?",o:["人寿及年金","永久健康","资本赎回","财产损坏"],a:3,e:"财产损坏属一般（而非长期）业务。人寿及年金、永久健康、资本赎回均属长期业务。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險業條例》以下哪項為一般而非長期業務？",o:["人壽及年金","永久健康","資本贖回","財產損壞"],e:"財產損壞屬一般（而非長期）業務。人壽及年金、永久健康、資本贖回均屬長期業務。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险业条例》的分类,以下哪项或哪些保险属于长期保险的业务范围?",o:["火险","人寿及年金","财产损伤","以上各项皆是"],a:1,e:"人寿及年金属《保险业条例》下的长期保险业务范围。火险、财产损伤均属一般业务，故「以上各项皆是」不成立。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險業條例》的分類，以下哪項或哪些保險屬於長期保險的業務範圍？",o:["火險","人壽及年金","財產損傷","以上各項皆是"],e:"人壽及年金屬《保險業條例》下的長期保險業務範圍。火險、財產損傷均屬一般業務，故「以上各項皆是」不成立。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险业条例》第七十条,认可保险经纪团体成立的能力是赋予:",o:["保险业监管局","香港特别行政区政府","香港保险顾问联会","香港专业保险经纪协会"],a:0,e:"《保险业条例》第70条赋予保险业监管局批准保险经纪团体成立的权力。香港特别行政区政府、香港保险顾问联会、香港专业保险经纪协会均非被赋予该权力的主体。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險業條例》第七十條，認可保險經紀團體成立的能力是賦予：",o:["保險業監管局","香港特別行政區政府","香港保險顧問聯會","香港專業保險經紀協會"],e:"《保險業條例》第70條賦予保險業監管局批准保險經紀團體成立的權力。香港特別行政區政府、香港保險顧問聯會、香港專業保險經紀協會均非被賦予該權力的主體。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险公司的条例》的事务分类法则,雇员补偿保险:",o:["未能成为一项独立的类别","属于《一般业务》的分类","属于《一般法律责任》的类别","以上各项皆符合"],a:3,e:"雇员补偿保险未成为一项独立类别，属一般业务并归入一般法律责任类别，故各项说法皆符合。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險公司的條例》的事務分類法則，僱員補償保險：",o:["未能成為一項獨立的類別","屬於《一般業務》的分類","屬於《一般法律責任》的類别","以上各項皆符合"],e:"僱員補償保險未成為一項獨立類別，屬一般業務並歸入一般法律責任類別，故各項說法皆符合。"}},
{p:1,ch:"香港保险业的结构",q:"根据传统,经营寿险、海上保险、火险及意外业务类型等保险被描述为?",o:["部门式方法","法定方法","功能式方法","制定式方法"],a:0,e:"按传统把寿险、海上保险、火险及意外业务类型作分类的方法，称为部门式方法。法定、功能式、制定式均不符。",src:1,tw:{ch:"香港保險業的結構",q:"根據傳統，經營壽險、海上保險、火險及意外業務類型等保險被描述為?",o:["部門式方法","法定方法","功能式方法","制定式方法"],e:"按傳統把壽險、海上保險、火險及意外業務類型作分類的方法，稱為部門式方法。法定、功能式、制定式均不符。"}},
{p:1,ch:"香港保险业的结构",q:"根据可以获取的数据,以下哪项论点在香港成立? i 一般业务由相对少数的保险人支配 ii 长期业务由相对少数的保险人支配 iii 一般业务由保险人较为平均地分享 iv 长期业务由保险人较为平均地分享",o:["i及ii","i及iii","ii及iii","iii及iv"],a:2,e:"在香港，长期业务由相对少数的保险人支配（ii），而一般业务则由保险人较为平均地分享（iii），故ii及iii正确。i及iv的描述与此相反。",src:1,tw:{ch:"香港保險業的結構",q:"根據可以獲取的數據，以下哪項論點在香港成立？ i 一般業務由相對少數的保險人支配 ii 長期業務由相對少數的保險人支配 iii 一般業務由保險人較為平均地分享 iv 長期業務由保險人較為平均地分享",o:["i及ii","i及iii","ii及iii","iii及iv"],e:"在香港，長期業務由相對少數的保險人支配（ii），而一般業務則由保險人較為平均地分享（iii），故ii及iii正確。i及iv的描述與此相反。"}},
{p:1,ch:"香港保险业的结构",q:"根据英国部门式分类的制度,主要分为四大类(寿险、海上保险、火险及意外险)。美国制度下, 则分为两大类,包括人寿及非人寿。后者亦经常进一步划分为:",o:["财产及非财产","火险及其他","火险、海上保险、保证及意外","汽车及责任"],a:2,e:"美国制度下分为人寿及非人寿两大类，非人寿再细分为火险、海上保险、保证及意外。财产及非财产、火险及其他、汽车及责任均非准确划分。",src:1,tw:{ch:"香港保險業的結構",q:"根據英國部門式分類的制度，主要分為四大類(壽險、海上保險、火險及意外險)。美國制度下， 則分為兩大類，包括人壽及非人壽。後者亦經常進一步劃分為：",o:["財產及非財產","火險及其他","火險、海上保險、保證及意外","汽車及責任"],e:"美國製度下分為人壽及非人壽兩大類，非人壽再細分為火險、海上保險、保證及意外。財產及非財產、火險及其他、汽車及責任均非準確劃分。"}},
{p:1,ch:"香港保险业的结构",q:"根据香港保险业联会的使命声明,这个组织致力在会员间提倡最高的道德标准及:",o:["效力","能力","专业水平","业务诚信"],a:2,e:"根据香港保险业联会的使命声明，组织致力在会员间提倡最高的道德标准及专业水平。效力、能力、业务诚信均非该使命的关键词。",src:1,tw:{ch:"香港保險業的結構",q:"根據香港保險業聯會的使命聲明，這個組織致力在會員間提倡最高的道德標準及：",o:["效力","能力","專業水平","業務誠信"],e:"根據香港保險業聯會的使命聲明，組織致力在會員間提倡最高的道德標準及專業水平。效力、能力、業務誠信均非該使命的關鍵詞。"}},
{p:1,ch:"香港保险业的结构",q:"美式保险公司的部门分类包括:",o:["火险","水险","人寿及个人意外业务","人寿及非人寿业务"],a:3,e:"美式保险公司的部门分类为人寿及非人寿业务两大类。火险、水险、人寿及个人意外，都只是非人寿下的细分项。",src:1,tw:{ch:"香港保險業的結構",q:"美式保險公司的部門分類包括：",o:["火險","水險","人壽及個人意外業務","人壽及非人壽業務"],e:"美式保險公司的部門分類為人壽及非人壽業務兩大類。火險、水險、人壽及個人意外，都只是非人壽下的細分項。"}},
{p:1,ch:"香港保险业的结构",q:"美式保险公司的部门分类包括: i 财务及意外 ii 人寿及非人寿业务 iii 海上保险 iv 火灾",o:["只有i","只有ii","i, ii","以上各项皆是"],a:1,e:"美式保险公司的部门分类基本只有人寿及非人寿业务（ii）。财务及意外、海上保险、火灾均属细分或个别险种，而非该基本分类。",src:1,tw:{ch:"香港保險業的結構",q:"美式保險公司的部門分類包括： i 財務及意外 ii 人壽及非人壽業務 iii 海上保險 iv 火災",o:["只有i","只有ii","i, ii","以上各項皆是"],e:"美式保險公司的部門分類基本只有人壽及非人壽業務（ii）。財務及意外、海上保險、火災均屬細分或個別險種，而非該基本分類。"}},
{p:1,ch:"香港保险业的结构",q:"英国部门式制度下之保险分类有四类别,包括寿险、火险及意外险及:",o:["海上保险","责任保险","意外的责任保险","长期"],a:0,e:"英国部门式制度下的保险分类有四类，包括寿险、火险、意外险及海上保险，缺的一项是海上保险。责任保险、长期等非该分类范畴。",src:1,tw:{ch:"香港保險業的結構",q:"英國部門式制度下之保險分類有四類別，包括壽險、火險及意外險及：",o:["海上保險","責任保險","意外的責任保險","長期"],e:"英國部門式制度下的保險分類有四類，包括壽險、火險、意外險及海上保險，缺的一項是海上保險。責任保險、長期等非該分類範疇。"}},
{p:1,ch:"香港保险业的结构",q:"获授权的保险人,在香港的保险业中:",o:["长期业务比一般业务的保险人多","一般业务比长期业务的保险人多","一般业务与长期业务的保险人数目相同","综合业务保险人比长期及一般业务为多"],a:1,e:"在香港的保险业中，一般业务的获授权保险人较长期业务为多。长期业务多于一般、两者数目相同、综合业务保险人多于两者，均不符。",src:1,tw:{ch:"香港保險業的結構",q:"獲授權的保險人，在香港的保險業中：",o:["長期業務比一般業務的保險人多","一般業務比長期業務的保險人多","一般業務與長期業務的保險人數目相同","綜合業務保險人比長期及一般業務為多"],e:"在香港的保險業中，一般業務的獲授權保險人較長期業務為多。長期業務多於一般、兩者數目相同、綜合業務保險人多於兩者，均不符。"}},
{p:1,ch:"香港保险业的结构",q:"香港『综合保险人』的术语于现代使用意味着保险人:",o:["对某一业务种类很专业化","代理一种以上的业务","同时处理长期业务和一般业务","同时处理强制性业务和选择性业务"],a:2,e:"香港「综合保险人」一词指同时处理长期业务和一般业务的保险人。对某一业务很专业、代理一种以上业务、处理强制与选择业务均非其含义。",src:1,tw:{ch:"香港保險業的結構",q:"香港『綜合保險人』的術語於現代使用意味着保險人:",o:["對某一業務種類很專業化","代理一種以上的業務","同時處理長期業務和一般業務","同時處理強制性業務和選擇性業務"],e:"香港「綜合保險人」一詞指同時處理長期業務和一般業務的保險人。對某一業務很專業、代理一種以上業務、處理強制與選擇業務均非其含義。"}},
{p:1,ch:"香港保险业的结构",q:"香港汽车保险局的工作包括:",o:["维护汽车车主","售卖车险","维持公平保费","向无辜死伤的交通意外受害人提供补偿"],a:3,e:"香港汽车保险局的工作，是向无辜死伤的交通意外受害人提供补偿。维护车主、售卖车险、维持公平保费均非其职能。",src:1,tw:{ch:"香港保險業的結構",q:"香港汽車保險局的工作包括：",o:["維護汽車車主","售賣車險","維持公平保費","向無辜死傷的交通意外受害人提供補償"],e:"香港汽車保險局的工作，是向無辜死傷的交通意外受害人提供補償。維護車主、售賣車險、維持公平保費均非其職能。"}},
{p:1,ch:"香港保险业的结构",q:"香港汽车保险局的经费:",o:["须由保险代理人向被保险人征收","由特定的团体捐出","来自汽车索偿的附加征费","来自汽车保费的附加征费"],a:3,e:"香港汽车保险局的经费来自汽车保费的附加征费。由代理人向被保险人征收、由特定团体捐出、来自汽车索偿附加费均不准确。",src:1,tw:{ch:"香港保險業的結構",q:"香港汽車保險局的經費：",o:["須由保險代理人向被保險人徵收","由特定的團體捐出","來自汽車索償的附加徵費","來自汽車保費的附加徵費"],e:"香港汽車保險局的經費來自汽車保費的附加徵費。由代理人向被保險人徵收、由特定團體捐出、來自汽車索償附加費均不準確。"}},
{p:1,ch:"香港保险业的结构",q:"香港汽车保险局的经费是来自:",o:["政府资助","私人捐献","汽车保险保费的附加征费","香港保险业联会"],a:2,e:"香港汽车保险局的经费来自向汽车保险保费征收的附加征费，用于补偿意外中未获得保险保障的受害人。政府资助、私人捐献及香港保险业联会均非其经费来源。",src:1,tw:{ch:"香港保險業的結構",q:"香港汽車保險局的經費是來自：",o:["政府資助","私人捐獻","汽車保險保費的附加徵費","香港保險業聯會"],e:"香港汽車保險局的經費來自向汽車保險保費徵收的附加徵費，用於補償意外中未獲得保險保障的受害人。政府資助、私人捐獻及香港保險業聯會均非其經費來源。"}},
{p:1,ch:"保险业的规管架构",q:"《 获授权保险人的公司管治指引 》的主要目的是什么?",o:["独立的财务审计","负责任的公司管理","专业的企业形象","以上所有"],a:1,e:"该指引旨在促进获授权保险人建立负责任及有效的公司管治，改善其整体管理及功能。《》所指的独立财务审计与专业企业形象并非指引的核心目的。",src:1,tw:{ch:"保險業的規管架構",q:"《 獲授權保險人的公司管治指引 》的主要目的是什麼？",o:["獨立的財務審計","負責任的公司管理","專業的企業形象","以上所有"],e:"該指引旨在促進獲授權保險人建立負責任及有效的公司管治，改善其整體管理及功能。《》所指的獨立財務審計與專業企業形象並非指引的核心目的。"}},
{p:1,ch:"保险业的规管架构",q:"《2015年保险(修订)条例》给予保险业监管局有足够权力向保险人提出什么行动?",o:["清盘","限制保费","限制投资","限制申请经营某类保险业务的授权"],a:3,e:"《2015年保险(修订)条例》赋予保监局权力，可限制保险人申请经营某类保险业务的授权。清盘须经法院程序，限制保费与限制投资并非该条例新增的法定干预权力。",src:1,tw:{ch:"保險業的規管架構",q:"《2015年保險(修訂)條例》給予保險業監管局有足夠權力向保險人提出什麼行動?",o:["清盤","限制保費","限制投資","限制申請經營某類保險業務的授權"],e:"《2015年保險(修訂)條例》賦予保監局權力，可限制保險人申請經營某類保險業務的授權。清盤須經法院程序，限制保費與限制投資並非該條例新增的法定干預權力。"}},
{p:1,ch:"保险业的规管架构",q:"《2015年修订条例》下新增保监局的规管权力,可向获授权保险人施加纪律处分,当中包括 :",o:["限制保费收入","投资限制","对新业务的限制","公开或非公开的谴责"],a:3,e:"2015年修订条例下，保监局可对获授权保险人施加纪律处分，其中包括公开或非公开的谴责。限制保费收入、投资限制及对新业务的限制属干预措施而非纪律处分。",src:1,tw:{ch:"保險業的規管架構",q:"《2015年修訂條例》下新增保監局的規管權力，可向獲授權保險人施加紀律處分，當中包括 ：",o:["限制保費收入","投資限制","對新業務的限制","公開或非公開的譴責"],e:"2015年修訂條例下，保監局可對獲授權保險人施加紀律處分，其中包括公開或非公開的譴責。限制保費收入、投資限制及對新業務的限制屬干預措施而非紀律處分。"}},
{p:1,ch:"保险业的规管架构",q:"《2015年修订条例》下新增规管权力,保监局获赋予明确权力对保险人作出以下哪行动?",o:["限制保费收入","对新业务的限制","撤销对保险人的授权","将保险人清盘"],a:2,e:"新修订条例明确赋予保监局撤销对保险人授权的权力，属其新增规管工具。限制保费收入与限制新业务属其他干预措施，而将保险人清盘须透过法院进行，保监局不能直接执行。",src:1,tw:{ch:"保險業的規管架構",q:"《2015年修訂條例》下新增規管權力，保監局獲賦予明確權力對保險人作出以下哪行動？",o:["限制保費收入","對新業務的限制","撤銷對保險人的授權","將保險人清盤"],e:"新修訂條例明確賦予保監局撤銷對保險人授權的權力，屬其新增規管工具。限制保費收入與限制新業務屬其他干預措施，而將保險人清盤須透過法院進行，保監局不能直接執行。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业(获授权保险人的最高数目)规则》规定,获授权保险人委任为“持牌人士”的数 目为:",o:["最少四间","最少一间经营一般业务","最少一间经营长期业务","长期业务不得超过两间"],a:3,e:"该规则规限同一人可被委任为“持牌人士”的数目：就长期业务而言，委任的获授权保险人不得超过两间。其余最少四间、最少一间一般或长期业务的表述均不符。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業（獲授權保險人的最高數目）規則》規定，獲授權保險人委任為“持牌人士”的數 目為：",o:["最少四間","最少一間經營一般業務","最少一間經營長期業務","長期業務不得超過兩間"],e:"該規則規限同一人可被委任為“持牌人士”的數目：就長期業務而言，委任的獲授權保險人不得超過兩間。其餘最少四間、最少一間一般或長期業務的表述均不符。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》中干预权力,赋予规管机构有权力作出以下行动? i 特定精算调查 ii 限制保费收入 iii 将保险人清盘 iv 由认可受托人保管资产",o:["i, ii","i, ii, iii","i, ii, iv","i, ii, iii, iv"],a:3,e:"法例赋予规管机构的干预权力包括要求进行特定精算调查、限制保费收入、申请将保险人清盘以及由认可受托人保管资产，四项均属法定干预权力。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》中干預權力，賦予規管機構有權力作出以下行動？ i 特定精算調查 ii 限制保費收入 iii 將保險人清盤 iv 由認可受託人保管資產",o:["i, ii","i, ii, iii","i, ii, iv","i, ii, iii, iv"],e:"法例賦予規管機構的干預權力包括要求進行特定精算調查、限制保費收入、申請將保險人清盤以及由認可受託人保管資產，四項均屬法定干預權力。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》拟定一般业务的资产及负债估值的规定,但以下哪项或哪些不受制于这规定 ?",o:["汽车保险人","专属自保保险人","雇员补偿保险人","总部不在香港的保险人"],a:1,e:"专属自保保险人的业务仅承保其母集团本身的风险，故不受制于一般业务的资产及负债估值规定。汽车保险人、雇员补偿保险人及总部不在香港的保险人仍须遵守。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》擬定一般業務的資產及負債估值的規定，但以下哪項或哪些不受制於這規定 ？",o:["汽車保險人","專屬自保保險人","僱員補償保險人","總部不在香港的保險人"],e:"專屬自保保險人的業務僅承保其母集團本身的風險，故不受制於一般業務的資產及負債估值規定。汽車保險人、僱員補償保險人及總部不在香港的保險人仍須遵守。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》特别赋予保监局的一些权力。根据有关法例第81条,保监局可以在特定情况 下,就某人属于任何指明类别,在发生与该人所属类别有关的任何事情时,可就某人行使指 明的任何权力。以下哪项属于有关法例下行使权力的理由?",o:["该人在其属受规管人士时,犯或曾在任何时间犯不当行为","该人过去或现在担任持牌保险中介人的负责人或管理 受监管业务的人员时,该公司同意或纵容一些不当行为","被法院裁断为精神上无行为能力或被羁留在精神病院","以上各项皆正确"],a:3,e:"三项情形均属第81条下行使权力的理由：受规管人士曾犯不当行为、其担任负责人或管理层时公司同意或纵容不当行为、以及被法院裁断精神上无行为能力，故“以上各项皆正确”。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》特別賦予保監局的一些權力。根據有關法例第81條，保監局可以在特定情況 下，就某人屬於任何指明類別，在發生與該人所屬類別有關的任何事情時，可就某人行使指 明的任何權力。以下哪項屬於有關法例下行使權力的理由?",o:["該人在其屬受規管人士時，犯或曾在任何時間犯不當行為","該人過去或現在擔任持牌保險中介人的負責人或管理 受監管業務的人員時，該公司同意或縱容一些不當行為","被法院裁斷為精神上無行為能力或被羈留在精神病院","以上各項皆正確"],e:"三項情形均屬第81條下行使權力的理由：受規管人士曾犯不當行為、其擔任負責人或管理層時公司同意或縱容不當行為、以及被法院裁斷精神上無行為能力，故“以上各項皆正確”。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》由以下哪个机构负责执行?",o:["保险业监管局","香港保险业联会","证券及期货事务监察委员会","保险行业本身自律监管"],a:0,e:"保险业监管局是执行《保险业条例》的法定监管机构。香港保险业联会是行业自律组织，证监会监管证券期货，均不负责执行该条例。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》由以下哪個機構負責執行？",o:["保險業監管局","香港保險業聯會","證券及期貨事務監察委員會","保險行業本身自律監管"],e:"保險業監管局是執行《保險業條例》的法定監管機構。香港保險業聯會是行業自律組織，證監會監管證券期貨，均不負責執行該條例。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》的持牌业务代表(代理人)指:",o:["一名负责处理某保险人的代理部门的人","已获保监局发出作为任何持牌保险代理机构进行一个或多于一个业务系列的受规管活动的牌 照的个人","已获保监局发出作为任何持牌保险经纪公司进行一个或多于一个业务系列的受规管活动的牌 照的个人","保险分代理人"],a:1,e:"持牌业务代表(代理人)指获保监局发牌、代表持牌保险代理机构进行受规管活动的个人。代表经纪公司进行受规管活动者为持牌业务代表(经纪)，两者须分清。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》的持牌業務代表(代理人)指：",o:["一名負責處理某保險人的代理部門的人","已獲保監局發出作為任何持牌保險代理機構進行一個或多於一個業務系列的受規管活動的牌 照的個人","已獲保監局發出作為任何持牌保險經紀公司進行一個或多於一個業務系列的受規管活動的牌 照的個人","保險分代理人"],e:"持牌業務代表(代理人)指獲保監局發牌、代表持牌保險代理機構進行受規管活動的個人。代表經紀公司進行受規管活動者為持牌業務代表(經紀)，兩者須分清。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》要求一般业务的保险人定期缴交甚么报表? i 经审计的一般业务报表 ii 经审计的资产负债表 iii 经审计的精算报告表",o:["i, ii","i, iii","ii, iii","i, ii, iii"],a:0,e:"一般业务的保险人须定期呈交经审计的一般业务报表及经审计的资产负债表。精算调查报告属长期业务保险人的要求，故不选iii。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》要求一般業務的保險人定期繳交甚麼報表？ i 經審計的一般業務報表 ii 經審計的資產負債表 iii 經審計的精算報告表",o:["i, ii","i, iii","ii, iii","i, ii, iii"],e:"一般業務的保險人須定期呈交經審計的一般業務報表及經審計的資產負債表。精算調查報告屬長期業務保險人的要求，故不選iii。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》要求所有保险人根据的要求呈交准备好的财务报表,呈交的频率是:",o:["每月","每年","每季度","每三年"],a:1,e:"《保险业条例》要求所有保险人每年呈交备妥的财务报表，而非每月、每季度或每三年。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》要求所有保險人根據的要求呈交準備好的財務報表，呈交的頻率是:",o:["每月","每年","每季度","每三年"],e:"《保險業條例》要求所有保險人每年呈交備妥的財務報表，而非每月、每季度或每三年。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》规定保险人必须持有最低的偿付准备金,偿付准备金是什么?",o:["负债超出资产的金额","资产超出负债的金额","只限于长期保险保费的收入","根据一项公式的计算,不管其经营的业务为何"],a:1,e:"偿付准备金指保险人资产超出负债的金额，反映其偿付能力。负债超出资产表示资不抵债，且偿付准备金适用于各类业务而非仅限长期保费收入。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》規定保險人必須持有最低的償付準備金，償付準備金是什麼？",o:["負債超出資產的金額","資產超出負債的金額","只限於長期保險保費的收入","根據一項公式的計算，不管其經營的業務為何"],e:"償付準備金指保險人資產超出負債的金額，反映其償付能力。負債超出資產表示資不抵債，且償付準備金適用於各類業務而非僅限長期保費收入。"}},
{p:1,ch:"保险业的规管架构",q:"《保险业条例》赋予规管机构有权力作出不同行动,以下哪些法定干预权力是正确的? i 海外股本 ii 总资产占比最高的由保险监管局明示 iii 限制新业务 iv 由认可受托人保管资产",o:["i, iii","iii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"法定干预权力包括对新业务的限制及由认可受托人保管资产。海外股本与“总资产占比最高由保监局明示”并非干预权力，故只选 iii、iv。",src:1,tw:{ch:"保險業的規管架構",q:"《保險業條例》賦予規管機構有權力作出不同行動，以下哪些法定干預權力是正確的？ i 海外股本 ii 總資產佔比最高的由保險監管局明示 iii 限制新業務 iv 由認可受托人保管資產",o:["i, iii","iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"法定干預權力包括對新業務的限制及由認可受託人保管資產。海外股本與“總資產佔比最高由保監局明示”並非干預權力，故只選 iii、iv。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》 由哪一个机构负责执行?",o:["香港保险业联会","保险业监管局","保险业监理处","保险人"],a:0,e:"《承保商专业守则》是香港保险业联会制定的行业自律守则，由其负责执行。保险业监管局及保险业监理处为法定监管机构，保险人本身亦非执行者。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》 由哪一個機構負責執行？",o:["香港保險業聯會","保險業監管局","保險業監理處","保險人"],e:"《承保商專業守則》是香港保險業聯會制定的行業自律守則，由其負責執行。保險業監管局及保險業監理處為法定監管機構，保險人本身亦非執行者。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》中有关提供建议及销售惯例必须:",o:["浅白语言,明确指引","解释最高诚信的重要性","小心解释任何附带问卷的重要性","以上皆是"],a:3,e:"守则要求提供建议及销售惯例须使用浅白语言、作出明确指引、解释最高诚信的重要性，并小心解释附带问卷的重要性，三项均属必须，故选“以上皆是”。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》中有關提供建議及銷售慣例必須：",o:["淺白語言，明確指引","解釋最高誠信的重要性","小心解釋任何附帶問卷的重要性","以上皆是"],e:"守則要求提供建議及銷售慣例須使用淺白語言、作出明確指引、解釋最高誠信的重要性，並小心解釋附帶問卷的重要性，三項均屬必須，故選“以上皆是”。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》对于建议及销售部分必须包括:",o:["保单","销售资料","医疗证明书及投保书","以上全部皆是"],a:3,e:"守则规定建议及销售部分须包括保单、销售资料以及医疗证明书和投保书等文件，三者均为必须，故“以上全部皆是”。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》對於建議及銷售部分必須包括：",o:["保單","銷售資料","醫療證明書及投保書","以上全部皆是"],e:"守則規定建議及銷售部分須包括保單、銷售資料以及醫療證明書和投保書等文件，三者均為必須，故“以上全部皆是”。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》对以下哪项的「提供建议及销售做法」是不正确的?",o:["资料保持更新","浅白易明的文字","不具误导成份","载有竞争对手的所有资料"],a:3,e:"守则要求资料保持更新、文字浅白易明及不具误导成份。“载有竞争对手的所有资料”并非守则要求，属不正确陈述。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》對以下哪項的「提供建議及銷售做法」是不正確的?",o:["資料保持更新","淺白易明的文字","不具誤導成份","載有競爭對手的所有資料"],e:"守則要求資料保持更新、文字淺白易明及不具誤導成份。“載有競爭對手的所有資料”並非守則要求，屬不正確陳述。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》就处理索偿提供建议,包括:",o:["代表保险人的第三者在任何情况下都应当合理地行事","代表保险人的第三者在任何情况下都应具备专业资格","代表保险人的第三者,在任何情况下都应当合理地行事,并且应该具备专业资格","保险人不得聘请律师或理赔师处理索偿"],a:2,e:"守则要求代表保险人的第三者在任何情况下都应当合理地行事，并且应该具备专业资格，两者缺一不可。单具其一或禁止保险人聘请律师或理赔师均不正确。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》就處理索償提供建議，包括：",o:["代表保險人的第三者在任何情況下都應當合理地行事","代表保險人的第三者在任何情況下都應具備專業資格","代表保險人的第三者，在任何情況下都應當合理地行事，並且應該具備專業資格","保險人不得聘請律師或理賠師處理索償"],e:"守則要求代表保險人的第三者在任何情況下都應當合理地行事，並且應該具備專業資格，兩者缺一不可。單具其一或禁止保險人聘請律師或理賠師均不正確。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》就提供建议及销售的做法作出明确论述,包括: i. 表达语言精确浅白 ii. 销售资料应该是最新的 iii. 小心解释最高诚信原则要求的重要性 iv. 小心解释任何附带问卷的重要性",o:["只有i及ii","只有i, ii, iii","只有ii, iii, iv","以上皆是"],a:3,e:"守则就提供建议及销售做法要求：表达语言精确浅白、销售资料最新、解释最高诚信原则的重要性，并小心解释附带问卷的重要性，四项均正确。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》就提供建議及銷售的做法作出明確論述，包括： i. 表達語言精確淺白 ii. 銷售資料應該是最新的 iii. 小心解釋最高誠信原則要求的重要性 iv. 小心解釋任何附帶問卷的重要性",o:["只有i及ii","只有i, ii, iii","只有ii, iii, iv","以上皆是"],e:"守則就提供建議及銷售做法要求：表達語言精確淺白、銷售資料最新、解釋最高誠信原則的重要性，並小心解釋附帶問卷的重要性，四項均正確。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》指即使违反保证,只要符合两项条件,保险人便不应拒赔,当中包括:",o:["损失少于港币$1,000","被保险人承认违反保证","赔偿与该项违反保证没有相互关系","以上各项皆正确"],a:2,e:"守则指即使被保险人违反保证，只要赔偿与该项违反保证没有相互关系（且损失并非因违反保证而起），保险人便不应拒赔。“损失少于$1,000”及“被保险人承认违反保证”并非该两项条件。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》指即使違反保證，只要符合兩項條件，保險人便不應拒賠，當中包括：",o:["損失少於港幣$1,000","被保險人承認違反保證","賠償與該項違反保證沒有相互關係","以上各項皆正確"],e:"守則指即使被保險人違反保證，只要賠償與該項違反保證沒有相互關係（且損失並非因違反保證而起），保險人便不應拒賠。“損失少於$1,000”及“被保險人承認違反保證”並非該兩項條件。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》旨在订立与下列情形相关的符合标准的优良保险做法,包括:",o:["核保及索偿","产品分析","广泛的顾客权利及权益","以上皆是"],a:3,e:"《承保商专业守则》旨在就核保及索偿、产品分析以及广泛的顾客权利及权益订立优良保险做法，三项均属其涵盖内容。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》旨在訂立與下列情形相關的符合標準的優良保險做法，包括:",o:["核保及索償","產品分析","廣泛的顧客權利及權益","以上皆是"],e:"《承保商專業守則》旨在就核保及索償、產品分析以及廣泛的顧客權利及權益訂立優良保險做法，三項均屬其涵蓋內容。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》旨在订立应有水平的优良保险惯例,包括: i 产品分析 ii 保险合约下的顾客权益及须负的责任 iii 广泛的顾客权利及权益 iv 提高行业的公众形象以作为优秀企业公民",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"守则旨在订立的优良保险惯例包括产品分析、顾客在合约下的权益及责任、广泛的顾客权利及权益，以及提高行业的公众形象，四项全对。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》旨在訂立應有水平的優良保險慣例，包括： i 產品分析 ii 保險合約下的顧客權益及須負的責任 iii 廣泛的顧客權利及權益 iv 提高行業的公眾形象以作為優秀企業公民",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"守則旨在訂立的優良保險慣例包括產品分析、顧客在合約下的權益及責任、廣泛的顧客權利及權益，以及提高行業的公眾形象，四項全對。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》的目的是对核保、索偿产品分析等订立:",o:["销售做法","优良保险做法","投保的优良做法","索偿做法"],a:1,e:"《承保商专业守则》的目的是对核保、索偿及产品分析等订立优良保险做法，而非单纯销售、投保或索偿的单一方面做法。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》的目的是對核保、索償產品分析等訂立：",o:["銷售做法","優良保險做法","投保的優良做法","索償做法"],e:"《承保商專業守則》的目的是對核保、索償及產品分析等訂立優良保險做法，而非單純銷售、投保或索償的單一方面做法。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》第四部份有关保险代理人管理方面,保险人需确保:",o:["尽力确保保险代理人的公平及诚实","处理投诉程序恰当","代理人得到足够支援","以上各项皆是"],a:3,e:"守则第四部分要求保险人尽力确保代理人公平诚实、设恰当的投诉处理程序，并对代理人提供足够支援，三项均属其要求。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》第四部份有關保險代理人管理方面，保險人需確保：",o:["盡力確保保險代理人的公平及誠實","處理投訴程序恰當","代理人得到足夠支援","以上各項皆是"],e:"守則第四部分要求保險人盡力確保代理人公平誠實、設恰當的投訴處理程序，並對代理人提供足夠支援，三項均屬其要求。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》要求保单合约:",o:["应该力求清晰及易于理解","提供合约条款可见的证据","于续保时需要披露重要事实的最高诚信原则要求,都应予以小心地解释","以上各项部都是"],a:3,e:"守则要求保单合约应力求清晰易明、提供合约条款可见的证据，并于续保时小心解释披露重要事实的最高诚信要求，各项均正确。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》要求保單合約：",o:["應該力求清晰及易於理解","提供合約條款可見的證據","於續保時需要披露重要事實的最高誠信原則要求，都應予以小心地解釋","以上各項部都是"],e:"守則要求保單合約應力求清晰易明、提供合約條款可見的證據，並於續保時小心解釋披露重要事實的最高誠信要求，各項均正確。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》要求保险人处理索偿时:",o:["公平并有效率地处理赔款","对有效的索偿要求及时支付赔款","索偿人可以合理地得知保险人处理保险金的进度","以上皆是"],a:3,e:"守则要求保险人公平并有效率地处理赔款、对有效索偿及时支付，并让索偿人合理地得知处理进度，三项均属其要求。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》要求保險人處理索償時：",o:["公平並有效率地處理賠款","對有效的索償要求及時支付賠款","索償人可以合理地得知保險人處理保險金的進度","以上皆是"],e:"守則要求保險人公平並有效率地處理賠款、對有效索償及時支付，並讓索償人合理地得知處理進度，三項均屬其要求。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》订下什么标准？",o:["优良保险做法","法定保险做法","强制保险做法","优良商业做法"],a:0,e:"《承保商专业守则》订下的是优良（良好）保险做法的标准，属行业自律性质，而非法定、强制或一般商业做法。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》訂下什麼標準？",o:["優良保險做法","法定保險做法","強制保險做法","優良商業做法"],e:"《承保商專業守則》訂下的是優良（良好）保險做法的標準，屬行業自律性質，而非法定、強制或一般商業做法。"}},
{p:1,ch:"保险业的规管架构",q:"「持牌保险代理人应具备适当程度的专业知识和经验,及只可进行该代理人所胜任的受规管 活动」,这是根据《持牌保险代理人操守守则》中的哪一个原则?",o:["一般原则 1 - 诚实及持正","一般原则 2 - 公平行事并符合客户的最佳利益","一般原则 3 - 以谨慎、技巧和努力行事","一般原则 4 - 胜任提供意见"],a:3,e:"“具备适当知识经验及只可进行所胜任的受规管活动”对应一般原则4「胜任提供意见」。诚实及持正、公平行事、谨慎技巧努力分别对应其他原则。",src:1,tw:{ch:"保險業的規管架構",q:"「持牌保險代理人應具備適當程度的專業知識和經驗，及只可進行該代理人所勝任的受規管 活動」，這是根據《持牌保險代理人操守守則》中的哪一個原則？",o:["一般原則 1 - 誠實及持正","一般原則 2 - 公平行事並符合客戶的最佳利益","一般原則 3 - 以謹慎、技巧和努力行事","一般原則 4 - 勝任提供意見"],e:"“具備適當知識經驗及只可進行所勝任的受規管活動”對應一般原則4「勝任提供意見」。誠實及持正、公平行事、謹慎技巧努力分別對應其他原則。"}},
{p:1,ch:"保险业的规管架构",q:"「持牌保险代理人操守守则」的宗旨包括: i. 期望持牌保险代理人在进行受规管活动时应遵守的操守原则及 相关的标准及常规 ii. 要求持牌保险代理人应遵守其主事人就有关其进行受规管活动 所列明的规定 iii.告知并解释持牌保险代理人须遵守的法定操守规定 iv. 要求持牌保险代理人在进行受规管活动时应要为自己争取最大利益",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:0,e:"操守守则的宗旨包括说明应遵守的操守原则及标准常规、要求遵守主事人所列规定，以及告知法定操守规定；“为自己争取最大利益”并非宗旨，故不选iv。",src:1,tw:{ch:"保險業的規管架構",q:"「持牌保險代理人操守守則」的宗旨包括： i. 期望持牌保險代理人在進行受規管活動時應遵守的操守原則及 相關的標準及常規 ii. 要求持牌保險代理人應遵守其主事人就有關其進行受規管活動 所列明的規定 iii.告知並解釋持牌保險代理人須遵守的法定操守規定 iv. 要求持牌保險代理人在進行受規管活動時應要為自己爭取最大利益",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"操守守則的宗旨包括說明應遵守的操守原則及標準常規、要求遵守主事人所列規定，以及告知法定操守規定；“為自己爭取最大利益”並非宗旨，故不選iv。"}},
{p:1,ch:"保险业的规管架构",q:"一个保险人的以下哪些人符合适当人选准则:",o:["它的委托人","它的负贵人但不包括它的业务代表","它的业务代表但不包括它的负责人","它的业务代表和负责人"],a:3,e:"保险人的业务代表和负责人都须符合适当人选准则，仅委托人、仅负责人或仅业务代表之一均不完整。",src:1,tw:{ch:"保險業的規管架構",q:"一個保險人的以下哪些人符合適當人選準則：",o:["它的委託人","它的負貴人但不包括它的業務代表","它的業務代表但不包括它的負責人","它的業務代表和負責人"],e:"保險人的業務代表和負責人都須符合適當人選準則，僅委託人、僅負責人或僅業務代表之一均不完整。"}},
{p:1,ch:"保险业的规管架构",q:"一千万港元的实缴股本的最低要求适用于:",o:["只经营长期保险或一般保险业务","经营长期保险及一般保险业务","任何法定保险业务","专属自保保险人"],a:0,e:"只经营长期保险或一般保险业务的保险人最低实缴股本为1,000万港元。同时经营两者、法定业务及专属自保各有不同规定。",src:1,tw:{ch:"保險業的規管架構",q:"一千萬港元的實繳股本的最低要求適用於:",o:["只經營長期保險或一般保險業務","經營長期保險及一般保險業務","任何法定保險業務","專屬自保保險人"],e:"只經營長期保險或一般保險業務的保險人最低實繳股本為1,000萬港元。同時經營兩者、法定業務及專屬自保各有不同規定。"}},
{p:1,ch:"保险业的规管架构",q:"一名保单持有人与保险人产生了争执,即使保单条款有一项调解安排,但保单持有人仍向保 险投诉局申请调解服务。保险投诉局向该名保单持有人告知要选择调解服务,必先要符合某 些条件,包括: i 保险投诉局鼓励争议双方达成和解,但仍未成功 ii 争议金额不超过80万港元 iii 保险人已作最终决定 iv 涉及保险人的承保及服务",o:["i, iii","ii, iv","i, ii, iii","ii, iii, iv"],a:0,e:"选择投诉局的调解服务须符合若干条件，包括投诉局鼓励双方和解但仍未成功、以及保险人已作出最终决定。“争议金额不超过80万”及“涉及承保及服务”并非所列正确条件。",src:1,tw:{ch:"保險業的規管架構",q:"一名保單持有人與保險人產生了爭執，即使保單條款有一項調解安排，但保單持有人仍向保 險投訴局申請調解服務。保險投訴局向該名保單持有人告知要選擇調解服務，必先要符合某 些條件，包括： i 保險投訴局鼓勵爭議雙方達成和解，但仍未成功 ii 爭議金額不超過80萬港元 iii 保險人已作最終決定 iv 涉及保險人的承保及服務",o:["i, iii","ii, iv","i, ii, iii","ii, iii, iv"],e:"選擇投訴局的調解服務須符合若干條件，包括投訴局鼓勵雙方和解但仍未成功、以及保險人已作出最終決定。“爭議金額不超過80萬”及“涉及承保及服務”並非所列正確條件。"}},
{p:1,ch:"保险业的规管架构",q:"下列哪项不是持牌保险经纪的「适当人选」要求?",o:["遵照最高诚信而行事","以客人的利益为首位","本着适当的谨慎及努力而行事","选择最低保费的产品介绍给客人"],a:3,e:"持牌保险经纪须遵守最高诚信、以客户利益为首位并本着适当谨慎和努力行事；“选择最低保费的产品介绍给客人”并非其适当人选要求。",src:1,tw:{ch:"保險業的規管架構",q:"下列哪項不是持牌保險經紀的「適當人選」要求？",o:["遵照最高誠信而行事","以客人的利益為首位","本着適當的謹慎及努力而行事","選擇最低保費的產品介紹給客人"],e:"持牌保險經紀須遵守最高誠信、以客户利益為首位並本着適當謹慎和努力行事；“選擇最低保費的產品介紹給客人”並非其適當人選要求。"}},
{p:1,ch:"保险业的规管架构",q:"下列哪项是在保险投诉局的职权范围内可处理的个案?",o:["由第三者引起之索偿纠纷","正在进行仲裁之索偿案件","涉及团体寿险保单","索偿金额四十万港元"],a:3,e:"投诉局处理个人保单、索偿金额不超过100万港元的金钱性质纠纷，40万港元符合范围。由第三者引起、正在进行仲裁及团体寿险保单均不在其职权范围。",src:1,tw:{ch:"保險業的規管架構",q:"下列哪項是在保險投訴局的職權範圍內可處理的個案？",o:["由第三者引起之索償糾紛","正在進行仲裁之索償案件","涉及團體壽險保單","索償金額四十萬港元"],e:"投訴局處理個人保單、索償金額不超過100萬港元的金錢性質糾紛，40萬港元符合範圍。由第三者引起、正在進行仲裁及團體壽險保單均不在其職權範圍。"}},
{p:1,ch:"保险业的规管架构",q:"下列哪项有关保险业监管局的说法是正确的?",o:["透过发牌监管保险人","提高保单持有人对保险产品的了解","于1997年成立《承保商专业守则》","保险业监管局成立由香港保险业联会"],a:1,e:"保监局的职能包括提升保单持有人对保险产品及业务的了解。发牌规管对象为保险中介人而非保险人本身，《承保商专业守则》亦非1997年由其成立。",src:1,tw:{ch:"保險業的規管架構",q:"下列哪項有關保險業監管局的說法是正確的？",o:["透過發牌監管保險人","提高保單持有人對保險產品的了解","於1997年成立《承保商專業守則》","保險業監管局成立由香港保險業聯會"],e:"保監局的職能包括提升保單持有人對保險產品及業務的瞭解。發牌規管對象為保險中介人而非保險人本身，《承保商專業守則》亦非1997年由其成立。"}},
{p:1,ch:"保险业的规管架构",q:"与保险投诉局提供的索偿无关的调解服务为正确?",o:["受理金额上限为1000万港元","投诉人可从保险投诉局所备存具相关经验和资格的调解员名单中,选择调解员以进行调解","如投诉人败诉,须支付80%堂费予保险人","如保险人败诉,须支付80%堂费予投诉人"],a:1,e:"与索偿无关的调解服务容许投诉人从投诉局备存、具相关经验和资格的调解员名单中自选调解员。受理金额上限与堂费的规定均与该服务无关。",src:1,tw:{ch:"保險業的規管架構",q:"與保險投訴局提供的索償無關的調解服務為正確?",o:["受理金額上限為1000萬港元","投訴人可從保險投訴局所備存具相關經驗和資格的調解員名單中，選擇調解員以進行調解","如投訴人敗訴，須支付80%堂費予保險人","如保險人敗訴，須支付80%堂費予投訴人"],e:"與索償無關的調解服務容許投訴人從投訴局備存、具相關經驗和資格的調解員名單中自選調解員。受理金額上限與堂費的規定均與該服務無關。"}},
{p:1,ch:"保险业的规管架构",q:"专属自保保险人的实缴股本最低要求为:",o:["50万港元","100万港元","200万港元","400万港元"],a:2,e:"专属自保保险人的最低实缴股本要求为200万港元，低于一般及长期业务的1,000万港元要求。",src:1,tw:{ch:"保險業的規管架構",q:"專屬自保保險人的實繳股本最低要求為：",o:["50萬港元","100萬港元","200萬港元","400萬港元"],e:"專屬自保保險人的最低實繳股本要求為200萬港元，低於一般及長期業務的1,000萬港元要求。"}},
{p:1,ch:"保险业的规管架构",q:"为了有效地监管,以下哪项并不属于法例赋予规管机构的干预权力?",o:["限制保费收入","限制海外投资","新业务的限制","由认可受托人保管资产"],a:1,e:"限制保费收入、对新业务的限制及由认可受托人保管资产均属法定干预权力；限制海外投资并非法例所列的干预措施。",src:1,tw:{ch:"保險業的規管架構",q:"為了有效地監管，以下哪項並不屬於法例賦予規管機構的干預權力？",o:["限制保費收入","限制海外投資","新業務的限制","由認可受託人保管資產"],e:"限制保費收入、對新業務的限制及由認可受託人保管資產均屬法定干預權力；限制海外投資並非法例所列的干預措施。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪三项不属于保险投诉局的职能范畴? i 正在进行法律诉讼的索偿投诉 ii 交通意外的第三者所提出的投诉 iii 退保金额「不充足」的投诉 iv 索偿金额达四十万港元的个案",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"正在进行法律诉讼的索偿、交通意外第三者提出的投诉及退保金额“不充足”的投诉均不属投诉局职能；索偿金额四十万港元（不超上限）的个案则属其范围，故选i、ii、iii。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪三項不屬於保險投訴局的職能範疇？ i 正在進行法律訴訟的索償投訴 ii 交通意外的第三者所提出的投訴 iii 退保金額「不充足」的投訴 iv 索償金額達四十萬港元的個案",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"正在進行法律訴訟的索償、交通意外第三者提出的投訴及退保金額“不充足”的投訴均不屬投訴局職能；索償金額四十萬港元（不超上限）的個案則屬其範圍，故選i、ii、iii。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪个是不属于保险投诉局的范围?",o:["年金购买人投诉保险公司,以错误的方法计算去派发金额,使他损失利息","吸烟及非吸烟人士收取相同保费,投诉不公平对待","保单持有人发现付了过高保费,金额等如超过他真实年龄10岁。 他投诉保险人销售是没有确认其年龄","保单持有人保单红利少于预期, 因为保险人在销售时声称这是\"抗通胀保单\""],a:1,e:"吸烟与非吸烟人士收取相同保费的定价争议属保险人的承保及定价决定，不在投诉局受理范围。年金计算错误、销售时未核实年龄、红利未符销售声称等属保单金钱性质纠纷，可受理。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪個是不屬於保險投訴局的範圍?",o:["年金購買人投訴保險公司，以錯誤的方法計算去派發金額，使他損失利息","吸煙及非吸煙人士收取相同保費，投訴不公平對待","保單持有人發現付了過高保費，金額等如超過他真實年齡10歲。 他投訴保險人銷售是沒有確認其年齡","保單持有人保單紅利少於預期， 因為保險人在銷售時聲稱這是\"抗通脹保單\""],e:"吸煙與非吸煙人士收取相同保費的定價爭議屬保險人的承保及定價決定，不在投訴局受理範圍。年金計算錯誤、銷售時未核實年齡、紅利未符銷售聲稱等屬保單金錢性質糾紛，可受理。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪个是保险投诉局的处理? i. 一个有关$30,000的一般保险赔偿 ii. 保单持有人违反保证,保险人拒绝赔偿$20,000的家居保险 iii. 有关无索偿的折扣计算 (私家车保险) iv. 一个「全险」的私家车保险,拒绝$100,000的挡风玻璃赔偿",o:["i, ii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"$30,000一般赔偿、违反保证拒赔$20,000家居保险及“全险”拒赔$100,000挡风玻璃均属个人保单金钱性质索偿，可处理；无索偿折扣计算属保费核算问题，不在处理范围。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪個是保險投訴局的處理? i. 一個有關$30,000的一般保險賠償 ii. 保單持有人違反保證，保險人拒絕賠償$20,000的家居保險 iii. 有關無索償的折扣計算 (私家車保險) iv. 一個「全險」的私家車保險，拒絕$100,000的擋風玻璃賠償",o:["i, ii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"$30,000一般賠償、違反保證拒賠$20,000家居保險及“全險”拒賠$100,000擋風玻璃均屬個人保單金錢性質索償，可處理；無索償折扣計算屬保費核算問題，不在處理範圍。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪些对保险索偿投诉委员会的委员的描述是正确的? i 两位委员是来自保险业 ii 两位委员为业外人士 iii 两位委员是由保险业监管局专员委任 iv 两位委员会成员是由保险投诉局委任",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:0,e:"保险索偿投诉委员会由四名委员组成，其中两名来自保险业、两名为业外人士，由保险投诉局委任，而非由保监局专员委任。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪些對保險索償投訴委員會的委員的描述是正確的？ i 兩位委員是來自保險業 ii 兩位委員為業外人士 iii 兩位委員是由保險業監管局專員委任 iv 兩位委員會成員是由保險投訴局委任",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"保險索償投訴委員會由四名委員組成，其中兩名來自保險業、兩名為業外人士，由保險投訴局委任，而非由保監局專員委任。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪类机构必须向保险业监管局呈交一份年度财务报表及一份核数师报告?",o:["持牌保险经纪公司","持牌保险代理人","持牌保险代理人及持牌保险经纪公司","只是认可的保险经纪团体"],a:0,e:"持牌保险经纪公司须向保险业监管局呈交年度财务报表及核数师报告。持牌保险代理人及认可保险经纪团体并无此项年度呈报要求。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪類機構必須向保險業監管局呈交一份年度財務報表及一份核數師報告？",o:["持牌保險經紀公司","持牌保險代理人","持牌保險代理人及持牌保險經紀公司","只是認可的保險經紀團體"],e:"持牌保險經紀公司須向保險業監管局呈交年度財務報表及核數師報告。持牌保險代理人及認可保險經紀團體並無此項年度呈報要求。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项《承保商业专业守则》的描述是正确的?",o:["守则由香港保险业联会执行","订立了八项建议及销售守则","订下保险人最低要求实缴股本","以上皆是"],a:0,e:"《承保商专业守则》由香港保险业联会（HKFI）执行，属行业自律；其内容为建议、销售及优良做法，而非订立实缴股本的最低法定要求。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項《承保商業專業守則》的描述是正確的?",o:["守則由香港保險業聯會執行","訂立了八項建議及銷售守則","訂下保險人最低要求實繳股本","以上皆是"],e:"《承保商專業守則》由香港保險業聯會（HKFI）執行，屬行業自律；其內容為建議、銷售及優良做法，而非訂立實繳股本的最低法定要求。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不属于《承保商专业守则》对提供建议及销售详情的要求?",o:["提供最新的资料","不会误导公众","用浅白易明的文字","把所有竞争对手的产品资料详细列出"],a:3,e:"守则要求提供最新资料、不误导公众、以浅白易明的文字表达，但并不要求把所有竞争对手的产品资料详细列出，故该选项不正确。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不屬於《承保商專業守則》對提供建議及銷售詳情的要求？",o:["提供最新的資料","不會誤導公眾","用淺白易明的文字","把所有競爭對手的產品資料詳細列出"],e:"守則要求提供最新資料、不誤導公眾、以淺白易明的文字表達，但並不要求把所有競爭對手的產品資料詳細列出，故該選項不正確。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不属于保险投诉局的职能范围:",o:["索偿金额达四百万","涉及索偿的保险人并非保险投诉局会员","索偿人已为该纠纷展开法律程序","以上各项皆不属保险投诉局的职能范围"],a:3,e:"索偿金额达四百万（超出上限）、涉及非投诉局会员的保险人以及已展开法律程序的个案均不属投诉局职能范围，故选“以上各项皆不属”。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不屬於保險投訴局的職能範圍:",o:["索償金額達四百萬","涉及索償的保險人並非保險投訴局會員","索償人已為該糾紛展開法律程序","以上各項皆不屬保險投訴局的職能範圍"],e:"索償金額達四百萬（超出上限）、涉及非投訴局會員的保險人以及已展開法律程序的個案均不屬投訴局職能範圍，故選“以上各項皆不屬”。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不属于新发牌制度下的持牌人类别?",o:["持牌保险代理机构","持牌保险负责人","持牌业务代表 (代理人)","持牌保险经纪公司"],a:1,e:"新发牌制度下的持牌人类别包括持牌保险代理机构、持牌业务代表(代理人)、持牌业务代表(经纪)及持牌保险经纪公司等，并无“持牌保险负责人”这一类别。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不屬於新發牌制度下的持牌人類別?",o:["持牌保險代理機構","持牌保險負責人","持牌業務代表 (代理人)","持牌保險經紀公司"],e:"新發牌制度下的持牌人類別包括持牌保險代理機構、持牌業務代表(代理人)、持牌業務代表(經紀)及持牌保險經紀公司等，並無“持牌保險負責人”這一類別。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不是《承保商专业守则》第四部份有关保险代理的监察?",o:["保险代理人的登记","处理保险代理人的投诉程序","保险人对代理人在执行任务时提供足够的支援","以上皆是"],a:0,e:"守则第四部分就保险代理人的监察包括处理投诉的程序及对代理人执行任务提供足够支援；“保险代理人的登记”属法定发牌制度，并非守则所述的监察内容。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不是《承保商專業守則》第四部份有關保險代理的監察?",o:["保險代理人的登記","處理保險代理人的投訴程序","保險人對代理人在執行任務時提供足夠的支援","以上皆是"],e:"守則第四部分就保險代理人的監察包括處理投訴的程序及對代理人執行任務提供足夠支援；“保險代理人的登記”屬法定發牌制度，並非守則所述的監察內容。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不是保监局成立的目的? i 确保保险业的规管架构与时并进,促进保险业的快速发展 ii 保险业监管机构的高偿付金额水平这个国际惯常做法看齐 iii维持国际保险中心地位 iv 确保保险业的规管架构与时并进,促进保险业的稳健发展",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],a:0,e:"保监局的政策目标是确保规管架构与时并进、促进保险业稳健发展，而非促进“快速发展”；“维持国际保险中心地位”及“高偿付金额国际惯例”亦非其成立目的，故i、ii、iii不属于目的。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不是保監局成立的目的？ i 確保保險業的規管架構與時並進，促進保險業的快速發展 ii 保險業監管機構的高償付金額水平這個國際慣常做法看齊 iii維持國際保險中心地位 iv 確保保險業的規管架構與時並進，促進保險業的穩健發展",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],e:"保監局的政策目標是確保規管架構與時並進、促進保險業穩健發展，而非促進“快速發展”；“維持國際保險中心地位”及“高償付金額國際慣例”亦非其成立目的，故i、ii、iii不屬於目的。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不是保监局评估正在申请牌照或申请续期的商业实体的胜任能力时的范畴?",o:["集团成员公司及进行其他业务的商业实体","盈利能力","企业管治","内部监管及风险管理"],a:1,e:"评估商业实体胜任能力的范畴包括集团成员公司、企业管治、内部监管及风险管理等。“盈利能力”并非胜任能力评估所考虑的范畴。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不是保監局評估正在申請牌照或申請續期的商業實體的勝任能力時的範疇?",o:["集團成員公司及進行其他業務的商業實體","盈利能力","企業管治","內部監管及風險管理"],e:"評估商業實體勝任能力的範疇包括集團成員公司、企業管治、內部監管及風險管理等。“盈利能力”並非勝任能力評估所考慮的範疇。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项不需要《承保商业守业守则》第四部分保险代理人管理需要加强注意?",o:["确保保险代理人获得适当的报酬","有适当程序处理对保险代理人投诉","确保保险代理人于职责上有足够支援","以上皆是"],a:0,e:"守则第四部分要求设适当程序处理对代理人的投诉及确保代理人在职责上有足够支援；“确保代理人获得适当的报酬”并非守则要求加强注意的范畴。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項不需要《承保商業守業守則》第四部分保險代理人管理需要加強注意？",o:["確保保險代理人獲得適當的報酬","有適當程序處理對保險代理人投訴","確保保險代理人於職責上有足夠支援","以上皆是"],e:"守則第四部分要求設適當程序處理對代理人的投訴及確保代理人在職責上有足夠支援；“確保代理人獲得適當的報酬”並非守則要求加強注意的範疇。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项为《保险业条例》(IO)的幅盖范围? i 为报酬而进行“受规管活动”人士 ii 保险人的直销人员 iii 在港经营业务之保险人 iv 资讯科技部门的职员",o:["i, ii","i, ii, iii","i, ii, iv","i, ii, iii, iv"],a:1,e:"《保险业条例》涵盖为报酬进行受规管活动的人士、保险人的直销人员及在港经营业务的保险人。资讯科技部门的职员一般不属其涵盖范围。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項為《保險業條例》(IO)的幅蓋範圍？ i 為報酬而進行“受規管活動”人士 ii 保險人的直銷人員 iii 在港經營業務之保險人 iv 資訊科技部門的職員",o:["i, ii","i, ii, iii","i, ii, iv","i, ii, iii, iv"],e:"《保險業條例》涵蓋為報酬進行受規管活動的人士、保險人的直銷人員及在港經營業務的保險人。資訊科技部門的職員一般不屬其涵蓋範圍。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项事宜不应与个人持牌人或负责人「适当人选」有关?",o:["学历","婚姻状况","破产","刑事记录"],a:1,e:"学历、破产及刑事记录均属适当人选准则的考虑因素；婚姻状况与适当人选的评估无关，故不属于考虑范围。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項事宜不應與個人持牌人或負責人「適當人選」有關？",o:["學歷","婚姻狀況","破產","刑事記錄"],e:"學歷、破產及刑事記錄均屬適當人選準則的考慮因素；婚姻狀況與適當人選的評估無關，故不屬於考慮範圍。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项事宜与保险中介人牌照申请人「适当人选」有关?",o:["学历","财政状况","品格","以上各项皆是"],a:3,e:"保险中介人牌照申请人的适当人选准则涵盖其学历、财政状况及品格等方面，故选“以上各项皆是”。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項事宜與保險中介人牌照申請人「適當人選」有關？",o:["學歷","財政狀況","品格","以上各項皆是"],e:"保險中介人牌照申請人的適當人選準則涵蓋其學歷、財政狀況及品格等方面，故選“以上各項皆是”。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项关于专业弥偿保险是正确的?",o:["最低弥偿限额是300万","最高弥偿限额是7500万","作出赔偿后须把限额复效至不少于订定的最低金额","以上皆正确"],a:3,e:"专业弥偿保险最低弥偿限额为300万港元、最高为7,500万港元，且作出赔偿后须把限额复效至不少于规定的最低金额，三项均正确。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項關於專業彌償保險是正確的？",o:["最低彌償限額是300萬","最高彌償限額是7500萬","作出賠償後須把限額復效至不少於訂定的最低金額","以上皆正確"],e:"專業彌償保險最低彌償限額為300萬港元、最高為7,500萬港元，且作出賠償後須把限額復效至不少於規定的最低金額，三項均正確。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项属于「受规管人士」? i. 持牌保险中介人 ii. 持牌保险经纪公司负责人 iii. 持牌保险代理机构负责人 iv. 持牌保险经纪公司所进行的受规管活动的管理层人士",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii,iii, iv"],a:3,e:"持牌保险中介人、持牌保险经纪公司负责人、持牌保险代理机构负责人及经纪公司受规管活动的管理层人士，均属“受规管人士”的范围。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項屬於「受規管人士」? i. 持牌保險中介人 ii. 持牌保險經紀公司負責人 iii. 持牌保險代理機構負責人 iv. 持牌保險經紀公司所進行的受規管活動的管理層人士",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii,iii, iv"],e:"持牌保險中介人、持牌保險經紀公司負責人、持牌保險代理機構負責人及經紀公司受規管活動的管理層人士，均屬“受規管人士”的範圍。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项属于保险业条例所涵盖的人士? i 保险代理人 ii 保险经纪 iii 保险人 iv 所有替保险代理人工作的人士",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:1,e:"《保险业条例》涵盖保险代理人、保险经纪及保险人。“所有替保险代理人工作的人士”表述过宽，并不在条例涵盖范围内。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項屬於保險業條例所涵蓋的人士？ i 保險代理人 ii 保險經紀 iii 保險人 iv 所有替保險代理人工作的人士",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],e:"《保險業條例》涵蓋保險代理人、保險經紀及保險人。“所有替保險代理人工作的人士”表述過寬，並不在條例涵蓋範圍內。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项或哪些对个人持牌人或负责人「适当人选准则」有不良影响?",o:["有关的刑事罪名","被裁定专业失当","被法院撤销担任公司董事的资格","以上所有各项"],a:3,e:"有关的刑事罪名、被裁定专业失当及被法院撤销担任董事的资格，均会对适当人选准则造成不良影响，故“以上所有各项”正确。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項或哪些對個人持牌人或負責人「適當人選準則」有不良影響？",o:["有關的刑事罪名","被裁定專業失當","被法院撤銷擔任公司董事的資格","以上所有各項"],e:"有關的刑事罪名、被裁定專業失當及被法院撤銷擔任董事的資格，均會對適當人選準則造成不良影響，故“以上所有各項”正確。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项或哪些对申请成为个人持牌人或负责人的人士的「适当人选准则」会有不良影响?",o:["相关的定罪","过往的不当职业行为","未能取得特定学历或专业资格","以上各项皆是"],a:3,e:"相关的定罪、过往的不当职业行为及未能取得特定学历或专业资格，均会对适当人选准则造成不良影响，故选“以上各项皆是”。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項或哪些對申請成為個人持牌人或負責人的人士的「適當人選準則」會有不良影響?",o:["相關的定罪","過往的不當職業行為","未能取得特定學歷或專業資格","以上各項皆是"],e:"相關的定罪、過往的不當職業行為及未能取得特定學歷或專業資格，均會對適當人選準則造成不良影響，故選“以上各項皆是”。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是《保险业条例》涵盖范围? i 保险代理人 ii 保险经纪 iii  保险人 iv 保险中介人及提供保险意见之律师",o:["iii","i,ii","iii, iv","i, ii, iii"],a:3,e:"《保险业条例》涵盖保险代理人、保险经纪及保险人；“保险中介人及提供保险意见之律师”的表述并不可替代上述三类，故不选该项。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是《保險業條例》涵蓋範圍? i 保險代理人 ii 保險經紀 iii 保險人 iv 保險中介人及提供保險意見之律師",o:["iii","i,ii","iii, iv","i, ii, iii"],e:"《保險業條例》涵蓋保險代理人、保險經紀及保險人；“保險中介人及提供保險意見之律師”的表述並不可替代上述三類，故不選該項。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是保监局在保障保单持有人及潜在的保单持有人的权益下可实行的干预的权力?",o:["在合适的情况下将保险人清盘","向保单持有人退回不必要的保费","提高强制性保险的保费率","以上各项皆是"],a:0,e:"为保障保单持有人权益，保监局可行使的干预权力包括在合适情况下将保险人清盘。退回不必要保费及提高强制性保险保费率并非法定干预权力。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是保監局在保障保單持有人及潛在的保單持有人的權益下可實行的干預的權力？",o:["在合適的情況下將保險人清盤","向保單持有人退回不必要的保費","提高強制性保險的保費率","以上各項皆是"],e:"為保障保單持有人權益，保監局可行使的干預權力包括在合適情況下將保險人清盤。退回不必要保費及提高強制性保險保費率並非法定干預權力。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是保险业监管局,因应《2015年保险业(修订)条例》下新增的规管权力,可以向获 授权的保险人进行查察、展开调查及施加纪律处分? i 非公开谴责 ii 限制投资 iii 罚款 iv 对新业务限制",o:["i, ii","i, iii","i, ii, iii","i, ii, iv"],a:1,e:"2015年修订条例下保监局可施加的纪律处分包括公开或非公开谴责及罚款；限制投资及对新业务的限制属干预措施而非纪律处分，故只选i、iii。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是保險業監管局，因應《2015年保險業(修訂)條例》下新增的規管權力，可以向獲 授權的保險人進行查察、展開調查及施加紀律處分? i 非公開譴責 ii 限制投資 iii 罰款 iv 對新業務限制",o:["i, ii","i, iii","i, ii, iii","i, ii, iv"],e:"2015年修訂條例下保監局可施加的紀律處分包括公開或非公開譴責及罰款；限制投資及對新業務的限制屬干預措施而非紀律處分，故只選i、iii。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是保险业监管局,因应《2015年修订条例》下新增的规管权力,可以向获授权的保 险人实施的纪律处分?",o:["对新业务的限制","公开谴责","投资限制","限制保费收入"],a:1,e:"公开谴责属《2015年修订条例》下保监局可施加的纪律处分；对新业务的限制、投资限制及限制保费收入均属干预权力而非纪律处分。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是保險業監管局，因應《2015年修訂條例》下新增的規管權力，可以向獲授權的保 險人實施的紀律處分？",o:["對新業務的限制","公開譴責","投資限制","限制保費收入"],e:"公開譴責屬《2015年修訂條例》下保監局可施加的紀律處分；對新業務的限制、投資限制及限制保費收入均屬干預權力而非紀律處分。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是保险业监管局,因应《2015年修订条例》下新增的规管权力,可以向获授权的保 险人实施的纪律处分? i 对新业务的限制 ii 公开谴责 iii 非公开谴责 iv 将保险人清盘",o:["i, ii","ii, iii","i, ii, iii","i, ii, iv"],a:1,e:"公开谴责及非公开谴责均属纪律处分；对新业务的限制属干预权力，而将保险人清盘亦非纪律处分，故只选ii、iii。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是保險業監管局，因應《2015年修訂條例》下新增的規管權力，可以向獲授權的保 險人實施的紀律處分？ i 對新業務的限制 ii 公開譴責 iii 非公開譴責 iv 將保險人清盤",o:["i, ii","ii, iii","i, ii, iii","i, ii, iv"],e:"公開譴責及非公開譴責均屬紀律處分；對新業務的限制屬干預權力，而將保險人清盤亦非紀律處分，故只選ii、iii。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是保险投诉局最有可能处理的:",o:["涉及续保保费的纠纷","被保险人涉及纵火,保险人拒绝一项300万的火险索偿","第三者控告被保险人因疏忽而导致他人受伤","因违反家居保单中的条件,保险人拒绝一笔2万元的索偿"],a:3,e:"因违反家居保单条件而被拒赔2万元，属个人保单、金额不超过100万的金钱性质索偿纠纷，最可能获投诉局处理。续保保费、纵火及第三者控告疏忽的纠纷不在其范围。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是保險投訴局最有可能處理的:",o:["涉及續保保費的糾紛","被保險人涉及縱火，保險人拒絕一項300萬的火險索償","第三者控告被保險人因疏忽而導致他人受傷","因違反家居保單中的條件，保險人拒絕一筆2萬元的索償"],e:"因違反家居保單條件而被拒賠2萬元，屬個人保單、金額不超過100萬的金錢性質索償糾紛，最可能獲投訴局處理。續保保費、縱火及第三者控告疏忽的糾紛不在其範圍。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是在保险投诉局的职权范围内可处理的个案?",o:["索偿金额不超过一百万港元","由第三者引起之索偿纠纷","正在进行仲裁之索偿案件","涉案保单乃团体寿险保单"],a:0,e:"投诉局受理个人保单且索偿金额不超过100万港元的个案。由第三者引起的纠纷、正在进行仲裁的案件及团体寿险保单均不在受理范围内。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是在保險投訴局的職權範圍內可處理的個案？",o:["索償金額不超過一百萬港元","由第三者引起之索償糾紛","正在進行仲裁之索償案件","涉案保單乃團體壽險保單"],e:"投訴局受理個人保單且索償金額不超過100萬港元的個案。由第三者引起的糾紛、正在進行仲裁的案件及團體壽險保單均不在受理範圍內。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项是香港保险公司对实缴股本的要求是正确的?",o:["实缴股本相等于「有关数额」","长期保险及一般保险最低数额是相同的","长期保险及一般保险的计算准则存在差异","专属自保保险人没有最低的数额要求"],a:1,e:"只经营长期及只经营一般业务的保险人最低实缴股本同为1,000万港元，两者数额相同。专属自保保险人亦有较低而非“没有”最低数额要求。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項是香港保險公司對實繳股本的要求是正確的?",o:["實繳股本相等於「有關數額」","長期保險及一般保險最低數額是相同的","長期保險及一般保險的計算準則存在差異","專屬自保保險人沒有最低的數額要求"],e:"只經營長期及只經營一般業務的保險人最低實繳股本同為1,000萬港元，兩者數額相同。專屬自保保險人亦有較低而非“沒有”最低數額要求。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项有关保险业条例中就分别备存账目的要求是正确的?",o:["保险人必须就长期保险业务的不同类别备存账目,而就其长期保险业务所维持相当于某基金 的资产,只可为该基金所涉及的业务部分而运用","保险人必须就综合保险业务的不同类别的备存账目","保险人必须就一般保险业务的不同类别的备存账目","保险人必须就长期保险业务的不同类别备存账目,否则必须就其从香港保险业务维持资产"],a:0,e:"条例要求保险人就长期保险业务的不同类别分别备存账目，且就某长期基金所维持、相当于该基金的资产，只可为该基金涉及的业务部分而运用。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項有關保險業條例中就分別備存賬目的要求是正確的?",o:["保險人必須就長期保險業務的不同類別備存賬目，而就其長期保險業務所維持相當於某基金 的資產，只可為該基金所涉及的業務部分而運用","保險人必須就綜合保險業務的不同類別的備存賬目","保險人必須就一般保險業務的不同類別的備存賬目","保險人必須就長期保險業務的不同類別備存賬目，否則必須就其從香港保險業務維持資產"],e:"條例要求保險人就長期保險業務的不同類別分別備存賬目，且就某長期基金所維持、相當於該基金的資產，只可為該基金涉及的業務部分而運用。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项有关商号控权人定义的陈述是不正确的?",o:["就独资经营而言, 作为最终拥有或控制该独资经营所进行的受规管活动的个人","就合伙而言,作为直接或间接地 有权摊分或控制该合伙的资本或利润的不少于15%","就合伙而言,直接或间接地有权行使在该合伙的投票权的不少于5%","就合伙而言,行使对该合伙的管理最终的控制权的个人"],a:2,e:"就合伙而言，控权人指直接或间接有权摊分或控制合伙资本或利润不少于15%或行使最终管理控制权者；“投票权不少于5%”并非控权人的定义，故该陈述不正确。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項有關商號控權人定義的陳述是不正確的?",o:["就獨資經營而言， 作為最終擁有或控制該獨資經營所進行的受規管活動的個人","就合夥而言，作為直接或間接地 有權攤分或控制該合夥的資本或利潤的不少於15%","就合夥而言，直接或間接地有權行使在該合夥的投票權的不少於5%","就合夥而言，行使對該合夥的管理最終的控制權的個人"],e:"就合夥而言，控權人指直接或間接有權攤分或控制合夥資本或利潤不少於15%或行使最終管理控制權者；“投票權不少於5%”並非控權人的定義，故該陳述不正確。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项有关新的规管制度生效后的《保险业条例》就受规管人士中的“负责人”不是正确 的描述?",o:["规定每个持牌保险代理机构和持牌保险经纪公司最少有一个负责人","所有负责人必须是持牌业务代表(代理人)或持牌业务代表(经纪)","委任负责人之前,必先获得保监局的认可","负责人必须是业外人士,以保持其客观性"],a:3,e:"新制度下的负责人可为业内人士，并非必须为业外人士以保持客观性，该描述不正确；最少一名负责人、须为持牌业务代表及委任前获保监局认可均正确。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項有關新的規管制度生效後的《保險業條例》就受規管人士中的“負責人”不是正確 的描述?",o:["規定每個持牌保險代理機構和持牌保險經紀公司最少有一個負責人","所有負責人必須是持牌業務代表(代理人)或持牌業務代表(經紀)","委任負責人之前，必先獲得保監局的認可","負責人必須是業外人士，以保持其客觀性"],e:"新制度下的負責人可為業內人士，並非必須為業外人士以保持客觀性，該描述不正確；最少一名負責人、須為持牌業務代表及委任前獲保監局認可均正確。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项有关现行保险中介人持牌制度的陈述是不正确的?",o:["取代了自我规管制度的保险代理人 / 经纪登记规定","进行受规管活动时,必须获得保监局发出的牌照,获得豁免者除外","在新的制度下,共有四类持牌人","设有过渡安排予已持牌人士"],a:2,e:"新发牌制度把中介人分为持牌保险代理机构、持牌保险经纪公司及持牌业务代表（代理人／经纪）等类别，“共有四类持牌人”的笼统说法不准确，为不正确陈述。其余各项均正确。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項有關現行保險中介人持牌制度的陳述是不正確的?",o:["取代了自我規管制度的保險代理人 / 經紀登記規定","進行受規管活動時，必須獲得保監局發出的牌照，獲得豁免者除外","在新的制度下，共有四類持牌人","設有過渡安排予已持牌人士"],e:"新發牌制度把中介人分為持牌保險代理機構、持牌保險經紀公司及持牌業務代表（代理人／經紀）等類別，“共有四類持牌人”的籠統說法不準確，為不正確陳述。其餘各項均正確。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项的主席必须独立于保险业以及于委任前征得财经事务及库务局局长的同意?",o:["保险业联会","保险索偿投诉委员会","香港保险顾问联会","证券及期货事务监察委员会"],a:1,e:"保险索偿投诉委员会主席须独立于保险业，并于委任前征得财经事务及库务局局长的同意。其余机构的主席并无法定有此要求。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項的主席必須獨立於保險業以及於委任前徵得財經事務及庫務局局長的同意？",o:["保險業聯會","保險索償投訴委員會","香港保險顧問聯會","證券及期貨事務監察委員會"],e:"保險索償投訴委員會主席須獨立於保險業，並於委任前徵得財經事務及庫務局局長的同意。其餘機構的主席並無法定有此要求。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪项的目的是在订立与核保、索偿、产品分析相关的符合标准的优良保险做法?",o:["标准营业员合约","承保商专业守则","保险业条例","保险业监管局"],a:1,e:"《承保商专业守则》的目的是在核保、索偿及产品分析方面订立优良保险做法；标准营业员合约、保险业条例及保监局均非此目的。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪項的目的是在訂立與核保、索償、產品分析相關的符合標準的優良保險做法?",o:["標準營業員合約","承保商專業守則","保險業條例","保險業監管局"],e:"《承保商專業守則》的目的是在核保、索償及產品分析方面訂立優良保險做法；標準營業員合約、保險業條例及保監局均非此目的。"}},
{p:1,ch:"保险业的规管架构",q:"任何人可获多于一名获授权保险人委任为“持牌人士”,以下哪项陈述是正确的?",o:["两间一般业务及一间长期业务","三间长期业务及一间一般业务","两间长期业务及一间一般业务","选项A及C都是正确"],a:3,e:"同一人可获多于一名获授权保险人委任，例如两间一般业务加一间长期业务，或两间长期业务加一间一般业务，故选项A及C均正确。",src:1,tw:{ch:"保險業的規管架構",q:"任何人可獲多於一名獲授權保險人委任為“持牌人士”，以下哪項陳述是正確的？",o:["兩間一般業務及一間長期業務","三間長期業務及一間一般業務","兩間長期業務及一間一般業務","選項A及C都是正確"],e:"同一人可獲多於一名獲授權保險人委任，例如兩間一般業務加一間長期業務，或兩間長期業務加一間一般業務，故選項A及C均正確。"}},
{p:1,ch:"保险业的规管架构",q:"作为持牌保险代理人,最低限度的操守包括:",o:["尽力确保所建议的保单符合客户的要求和资源","不得误导或欺骗客户","不得诱使被保险人以新保单取代现有保单","以上各项都是"],a:3,e:"持牌保险代理人的最低限度操守包括确保建议符合客户要求与资源、不得误导或欺骗客户、不得诱使以新保单取代现有保单，各项皆对。",src:1,tw:{ch:"保險業的規管架構",q:"作為持牌保險代理人，最低限度的操守包括：",o:["盡力確保所建議的保單符合客戶的要求和資源","不得誤導或欺騙客戶","不得誘使被保險人以新保單取代現有保單","以上各項都是"],e:"持牌保險代理人的最低限度操守包括確保建議符合客户要求與資源、不得誤導或欺騙客户、不得誘使以新保單取代現有保單，各項皆對。"}},
{p:1,ch:"保险业的规管架构",q:"保监局对于商业实体申请或继续成为保险中介人有一系列考虑因素,以下哪项属于考虑的范 围内? i. (拟)委任的负贵人具有适当的资格和足够的经验 ii. 是否有盈利能力 iii. 是否有清晰责任及权限的组织架构 iv. 有否识别出主要风险及制订策略以减低该等风险",o:["i,ii,iii","i,iii,iv","ii,iii,iv","i,ii,iii,iv"],a:1,e:"保监局考虑商业实体申请或继续成为保险中介人时，包括负责人资格与经验、组织架构的清晰责任分权及风险识别与缓减策略；“是否有盈利能力”并非考虑项，故不选ii。",src:1,tw:{ch:"保險業的規管架構",q:"保監局對於商業實體申請或繼續成為保險中介人有一系列考慮因素，以下哪項屬於考慮的範 圍內？ i. (擬)委任的負貴人具有適當的資格和足夠的經驗 ii. 是否有盈利能力 iii. 是否有清晰責任及權限的組織架構 iv. 有否識別出主要風險及制訂策略以減低該等風險",o:["i，ii，iii","i，iii，iv","ii，iii，iv","i，ii，iii，iv"],e:"保監局考慮商業實體申請或繼續成為保險中介人時，包括負責人資格與經驗、組織架構的清晰責任分權及風險識別與緩減策略；“是否有盈利能力”並非考慮項，故不選ii。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局发出了 《 与有关公司安排再保险的指引 》,以下哪项的陈述是正确的: i  说明保险业监管局在发现某项再保险安排不足时,会如何处理此问题 ii 说明如何鉴定保险人与有关连再保险人所作出的某项再保险安排为足够 iii 说明保险人应如何审控其再保险安排 iv 说明在哪种情况下,保险人与有关连再保险人作再保险安排时,须向保监局报告",o:["i, ii","ii, iii, iv","i, ii, iv","以上各项皆是"],a:0,e:"《与有关公司安排再保险的指引》说明保监局发现再保险安排不足时的处理方式，以及如何鉴定与有关连再保险人所作安排是否足够；“如何审控”及“何种情况报告”并非其内容。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局發出了 《 與有關公司安排再保險的指引 》，以下哪項的陳述是正確的： i 説明保險業監管局在發現某項再保險安排不足時，會如何處理此問題 ii 説明如何鑑定保險人與有關連再保險人所作出的某項再保險安排為足夠 iii 說明保險人應如何審控其再保險安排 iv 說明在哪種情況下，保險人與有關連再保險人作再保險安排時，須向保監局報告",o:["i, ii","ii, iii, iv","i, ii, iv","以上各項皆是"],e:"《與有關公司安排再保險的指引》說明保監局發現再保險安排不足時的處理方式，以及如何鑑定與有關連再保險人所作安排是否足夠；“如何審控”及“何種情況報告”並非其內容。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局发出了 《 获授权保险人的公司管治指引 》, 内容涵盖:",o:["获授权保险人在管理和功能方面的各个层面","除获授权保险人管治层面外,还包括获授权保险人的2个职能(包括风险管理、承保)","除获授权保险人管治层面外,还包括获授权保险人在风险管理的安排","除获授权保险人管治层面外,还包括获授权保险人的3个职能(包括风险管理、承保及理赔安 排)"],a:0,e:"《获授权保险人的公司管治指引》的内容涵盖获授权保险人在管理和功能方面的各个层面，而非仅限于管治或个别职能。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局發出了 《 獲授權保險人的公司管治指引 》， 內容涵蓋：",o:["獲授權保險人在管理和功能方面的各個層面","除獲授權保險人管治層面外，還包括獲授權保險人的2個職能(包括風險管理、承保)","除獲授權保險人管治層面外，還包括獲授權保險人在風險管理的安排","除獲授權保險人管治層面外，還包括獲授權保險人的3個職能(包括風險管理、承保及理賠安 排)"],e:"《獲授權保險人的公司管治指引》的內容涵蓋獲授權保險人在管理和功能方面的各個層面，而非僅限於管治或個別職能。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局发出了 《 获授权保险人的公司管治指引 》《 指引 10》的内容涵盖获授权保险人在管理和功能方面的哪些层面?",o:["只包括风险管理及承保","只包括理赔及顾客服务","只包括人事管理及任命","包括风险管理、承保、理赔、顾客服务、审计等等"],a:3,e:"《指引10》的涵盖范围包括获授权保险人的风险管理、承保、理赔、顾客服务、审计等多个层面，而非只限其中一两个职能。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局發出了 《 獲授權保險人的公司管治指引 》《 指引 10》的內容涵蓋獲授權保險人在管理和功能方面的哪些層面?",o:["只包括風險管理及承保","只包括理賠及顧客服務","只包括人事管理及任命","包括風險管理、承保、理賠、顧客服務、審計等等"],e:"《指引10》的涵蓋範圍包括獲授權保險人的風險管理、承保、理賠、顧客服務、審計等多個層面，而非只限其中一兩個職能。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局发出了《与有关公司安排再保险的指引》,以下哪项的陈述是正确的?",o:["说明保险业监管局在发现某项再保险安排不足时,会如何处理此问题","说明保险人应如何审核再保险安排","说明在哪种情况下,保险人与有关连再保险人所作再保险安排时,要向保监局报告","保险人与有关连再保险人所作再保险安排时,在哪种情况下要向保监局批准"],a:0,e:"《与有关公司安排再保险的指引》说明保监局在发现某项再保险安排不足时的处理方式；“审核再保险安排”及“向保监局报告/批准”并非该指引所述的陈述内容。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局發出了《與有關公司安排再保險的指引》，以下哪項的陳述是正確的？",o:["説明保險業監管局在發現某項再保險安排不足時，會如何處理此問題","說明保險人應如何審核再保險安排","說明在哪種情況下，保險人與有關連再保險人所作再保險安排時，要向保監局報告","保險人與有關連再保險人所作再保險安排時，在哪種情況下要向保監局批准"],e:"《與有關公司安排再保險的指引》說明保監局在發現某項再保險安排不足時的處理方式；“審核再保險安排”及“向保監局報告/批准”並非該指引所述的陳述內容。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局接管了保险业监管处,有什么新的法定职能?",o:["提升现有及潜在保单持有人对产品及保险业务的了解","对保险市场的研究","透过发牌,规管保险中介人","以上皆是"],a:3,e:"保监局接替保监处后新增多项法定职能，包括提升公众对产品及业务的了解、进行研究以及发牌规管保险中介人，故“以上皆是”正确。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局接管了保險業監管處，有什麼新的法定職能?",o:["提升現有及潛在保單持有人對產品及保險業務的了解","對保險市場的研究","透過發牌，規管保險中介人","以上皆是"],e:"保監局接替保監處後新增多項法定職能，包括提升公眾對產品及業務的瞭解、進行研究以及發牌規管保險中介人，故“以上皆是”正確。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局的职能和任务是?",o:["为保险持有人提供直接保障","为保险持有人的利益提供保护","确保保险业的规管架构与时并进,促进保险业发展","透过保险代理登记制度,管理保险业架构"],a:2,e:"保监局的政策目标是确保保险业的规管架构与时并进、促进保险业稳健发展；它并非提供直接保障，亦不沿用旧的自律登记制度管理架构。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局的職能和任務是?",o:["為保險持有人提供直接保障","為保險持有人的利益提供保護","確保保險業的規管架構與時並進，促進保險業發展","透過保險代理登記制度，管理保險業架構"],e:"保監局的政策目標是確保保險業的規管架構與時並進、促進保險業穩健發展；它並非提供直接保障，亦不沿用舊的自律登記制度管理架構。"}},
{p:1,ch:"保险业的规管架构",q:"保险业监管局跟据《保险业条例》,有什么任务及职能?",o:["提升保险市场的可持续性发展","提升对保险所有人的直接保障","提升保险市场的高速发展","透过发牌, 规管保险业务"],a:3,e:"保监局的法定任务及职能包括透过发牌制度规管保险中介人及保险业务；“提供直接保障”、“促进高速发展”及“提升可持续性”并非其法定职能的准确表述。",src:1,tw:{ch:"保險業的規管架構",q:"保險業監管局跟據《保險業條例》，有什麼任務及職能?",o:["提升保險市場的可持續性發展","提升對保險所有人的直接保障","提升保險市場的高速發展","透過發牌, 規管保險業務"],e:"保監局的法定任務及職能包括透過發牌制度規管保險中介人及保險業務；“提供直接保障”、“促進高速發展”及“提升可持續性”並非其法定職能的準確表述。"}},
{p:1,ch:"保险业的规管架构",q:"保险代理人/经纪登记规定被废除后,取而代之的法定发牌制度规定,但凡有意在经营业务或 受雇过程中或为报酬而进行“受规管活动”,或有意显示进行任何该等行为者, 必须首先 获得保监局发出的牌照 (已取得特定豁免者则属例外) 。 以下哪项不属于“受规管活动”?",o:["洽谈或安排保险合约","邀请或诱使,或企图邀请或诱使任何人订立保险合约","参加公众活动开拓人际网络","提供“受规管意见”"],a:2,e:"“受规管活动”包括洽谈或安排合约、邀请或诱使订立合约及提供受规管意见；参加公众活动开拓人际网络并非受规管活动，故选该项。",src:1,tw:{ch:"保險業的規管架構",q:"保險代理人/經紀登記規定被廢除後，取而代之的法定發牌制度規定，但凡有意在經營業務或 受僱過程中或為報酬而進行“受規管活動”，或有意顯示進行任何該等行為者， 必須首先 獲得保監局發出的牌照 (已取得特定豁免者則屬例外) 。 以下哪項不屬於“受規管活動”?",o:["洽談或安排保險合約","邀請或誘使，或企圖邀請或誘使任何人訂立保險合約","參加公眾活動開拓人際網絡","提供“受規管意見”"],e:"“受規管活動”包括洽談或安排合約、邀請或誘使訂立合約及提供受規管意見；參加公眾活動開拓人際網絡並非受規管活動，故選該項。"}},
{p:1,ch:"保险业的规管架构",q:"保险公司的重要人士必须是『适当人选』,以下哪项或哪些人士须符合『适当人选』的准则 :",o:["总财务经理","任何保险中介人","保险公司的行政总裁","以上所有人士"],a:2,e:"保险公司的行政总裁属须符合“适当人选”准则的“重要人士”；总财务经理及任何保险中介人并非条例所指的关键人员类别。",src:1,tw:{ch:"保險業的規管架構",q:"保險公司的重要人士必須是『適當人選』，以下哪項或哪些人士須符合『適當人選』的準則 ：",o:["總財務經理","任何保險中介人","保險公司的行政總裁","以上所有人士"],e:"保險公司的行政總裁屬須符合“適當人選”準則的“重要人士”；總財務經理及任何保險中介人並非條例所指的關鍵人員類別。"}},
{p:1,ch:"保险业的规管架构",q:"保险所有人与保险人在有关索偿正在争议, 在仲裁条件下, 保险所有人向保险投拆局作出投诉, 但是, 保险投拆局要求其符合相关条件,包括: i. 双方放弃仲裁 ii. 双方在投诉前, 不能调解纠纷 iii. 不涉及索偿 iv. 保险人已对于该项索偿提出最终决定",o:["i, ii","i, ii, iii","ii, iv","i, ii, iii, iv"],a:2,e:"在争议尚在仲裁的情况下，投诉局要求投诉前未经调解及保险人已对索偿作出最终决定等条件；“双方放弃仲裁”并非受理前提，亦非不涉及索偿，故只选ii、iv。",src:1,tw:{ch:"保險業的規管架構",q:"保險所有人與保險人在有關索償正在爭議, 在仲裁條件下, 保險所有人向保險投拆局作出投訴, 但是, 保險投拆局要求其符合相關條件,包括: i. 雙方放棄仲裁 ii. 雙方在投訴前, 不能調解糾紛 iii. 不涉及索償 iv. 保險人已對於該項索償提出最終決定",o:["i, ii","i, ii, iii","ii, iv","i, ii, iii, iv"],e:"在爭議尚在仲裁的情況下，投訴局要求投訴前未經調解及保險人已對索償作出最終決定等條件；“雙方放棄仲裁”並非受理前提，亦非不涉及索償，故只選ii、iv。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局不能接受以下哪些人士的投诉?",o:["第三者","保单持有人","保单受益人","保单转让后的合法索偿人"],a:0,e:"保险投诉局只接受个人保单的保单持有人（及合资格受益人、承让人）的投诉，第三者并非投诉局的投诉主体。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局不能接受以下哪些人士的投訴？",o:["第三者","保單持有人","保單受益人","保單轉讓後的合法索償人"],e:"保險投訴局只接受個人保單的保單持有人（及合資格受益人、承讓人）的投訴，第三者並非投訴局的投訴主體。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局于2018年1月16日成立,以下哪项描述有关保险投诉局的结构是正确的?",o:["所有董事均来自保险业界,有丰富保险行业经验","其中四位董事为业外人士(主席除外),其余四位则来自保险业界","其中四位董事为业外人士(包括主席),其余四位则来自保险业界","所有董事均为业外人士,以保持其客观性"],a:2,e:"保险投诉局的董事结构为：八名董事中，四名为业外人士（包括主席），其余四名来自保险业界，以兼顾独立性与专业经验。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局於2018年1月16日成立，以下哪項描述有關保險投訴局的結構是正確的？",o:["所有董事均來自保險業界，有豐富保險行業經驗","其中四位董事為業外人士(主席除外)，其餘四位則來自保險業界","其中四位董事為業外人士(包括主席)，其餘四位則來自保險業界","所有董事均為業外人士，以保持其客觀性"],e:"保險投訴局的董事結構為：八名董事中，四名為業外人士（包括主席），其餘四名來自保險業界，以兼顧獨立性與專業經驗。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局只能处理︰ i 涉案的保单乃个人保单 ii 由商业、工业及第三者保险引起之索偿纠纷 iii 投诉与索偿有关的个案 iv 索偿金额不超过一百万港元",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"投诉局只处理涉案保单为个人保单、与索偿有关且金额不超过100万港元的个案；商业、工业及第三者保险引起的纠纷不在其范围内。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局只能處理︰ i 涉案的保單乃個人保單 ii 由商業、工業及第三者保險引起之索償糾紛 iii 投訴與索償有關的個案 iv 索償金額不超過一百萬港元",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"投訴局只處理涉案保單為個人保單、與索償有關且金額不超過100萬港元的個案；商業、工業及第三者保險引起的糾紛不在其範圍內。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局成立的基本目的是:",o:["代表成员处理及给付理赔","处理各类针对保险人之投诉","协助解决个人保险合约所引起的、并属于金钱性质的纠纷","处理来自第三者的法定保险索偿"],a:2,e:"投诉局的基本目的是协助解决个人保险合约所引起、属于金钱性质的纠纷；它并非代成员理赔、处理所有投诉或处理第三者法定索偿。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局成立的基本目的是：",o:["代表成員處理及給付理賠","處理各類針對保險人之投訴","協助解決個人保險合約所引起的、並屬於金錢性質的糾紛","處理來自第三者的法定保險索償"],e:"投訴局的基本目的是協助解決個人保險合約所引起、屬於金錢性質的糾紛；它並非代成員理賠、處理所有投訴或處理第三者法定索償。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局提供索偿无关调解服务的先决条件是?",o:["尽管投诉局鼓励双方和解,但和解协议未能达成","服务三个月之内向投诉局申诉","争议金额不高于$100,000","尽管投诉局鼓励双方签订协议,但未能办到"],a:0,e:"与索偿无关的调解服务的先决条件是：尽管投诉局鼓励双方达成和解，但和解协议未能达成。其余各项与此先决条件无关。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局提供索償無關調解服務的先決條件是？",o:["儘管投訴局鼓勵雙方和解，但和解協議未能達成","服務三個月之內向投訴局申訴","爭議金額不高於$100,000","儘管投訴局鼓勵雙方簽訂協議，但未能辦到"],e:"與索償無關的調解服務的先決條件是：儘管投訴局鼓勵雙方達成和解，但和解協議未能達成。其餘各項與此先決條件無關。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局有权处理投诉,甚至提供与索偿无关的调解服务。以下哪项不是该局可以处理的 案件?",o:["抗通胀保单功能未能实现","投资相连保单收益不似预期","不满意储蓄寿险之红利表现","中介人服务水平欠奉"],a:3,e:"投诉局处理与保单金钱价值有关的纠纷（如抗通胀功能、投资相连收益、红利表现）；中介人的服务水平属操守问题，不在投诉局可处理范围。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局有權處理投訴，甚至提供與索償無關的調解服務。以下哪項不是該局可以處理的 案件？",o:["抗通脹保單功能未能實現","投資相連保單收益不似預期","不滿意儲蓄壽險之紅利表現","中介人服務水平欠奉"],e:"投訴局處理與保單金錢價值有關的糾紛（如抗通脹功能、投資相連收益、紅利表現）；中介人的服務水平屬操守問題，不在投訴局可處理範圍。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局的成员包括:",o:["所有保险人","专门从事长期保险的保险人","专门从事一般保险的保险人","从事个人保险业务的获授权保险人"],a:3,e:"保险投诉局的成员包括所有在港承保个人保险业务的获授权保险人，而非全部保险人或专门经营某一业务的保险人。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局的成員包括：",o:["所有保險人","專門從事長期保險的保險人","專門從事一般保險的保險人","從事個人保險業務的獲授權保險人"],e:"保險投訴局的成員包括所有在港承保個人保險業務的獲授權保險人，而非全部保險人或專門經營某一業務的保險人。"}},
{p:1,ch:"保险业的规管架构",q:"保险投诉局较可能处理下列哪项个案?",o:["保单续保的纠纷","保险人拒绝对一项超过2,000,000港元的索偿","在商业汽车保单中,第三者保险的索偿","在个人保单中,一项对超过20,000港元的索偿"],a:3,e:"在个人保单中、金额超过2万港元（且不超过上限）的索偿最可能获处理；续保纠纷、超200万索偿及商业汽车第三者索偿均不在投诉局范围内。",src:1,tw:{ch:"保險業的規管架構",q:"保險投訴局較可能處理下列哪項個案？",o:["保單續保的糾紛","保險人拒絕對一項超過2,000,000港元的索償","在商業汽車保單中，第三者保險的索償","在個人保單中，一項對超過20,000港元的索償"],e:"在個人保單中、金額超過2萬港元（且不超過上限）的索償最可能獲處理；續保糾紛、超200萬索償及商業汽車第三者索償均不在投訴局範圍內。"}},
{p:1,ch:"保险业的规管架构",q:"保险牌照代理的主事人是:",o:["客户","客户雇主","代理人的上线经理","委任的保险人"],a:3,e:"保险代理人的主事人是其所代表的委任保险人（保险公司），而非客户、客户雇主或代理人的上线经理。",src:1,tw:{ch:"保險業的規管架構",q:"保險牌照代理的主事人是:",o:["客戶","客戶僱主","代理人的上線經理","委任的保險人"],e:"保險代理人的主事人是其所代表的委任保險人（保險公司），而非客户、客户僱主或代理人的上線經理。"}},
{p:1,ch:"保险业的规管架构",q:"保险索偿投诉委员会属于一个独立组织,由一名主席及多少名委员组成?",o:["二名委员","三名委员","四名委员","五名委员"],a:2,e:"保险索偿投诉委员会由一名主席及四名委员组成，为独立组织。",src:1,tw:{ch:"保險業的規管架構",q:"保險索償投訴委員會屬於一個獨立組織，由一名主席及多少名委員組成？",o:["二名委員","三名委員","四名委員","五名委員"],e:"保險索償投訴委員會由一名主席及四名委員組成，為獨立組織。"}},
{p:1,ch:"保险业的规管架构",q:"保险索偿投诉委员会由一名主席及多少名属于非保险业界人士的委员组成?",o:["一位业外人士","两位业外人士","三位业外人士","以上皆非,所有委员均来自保险业界"],a:1,e:"委员会四名委员中，两名属非保险业界人士（业外人士），另外两名来自保险业界。",src:1,tw:{ch:"保險業的規管架構",q:"保險索償投訴委員會由一名主席及多少名屬於非保險業界人士的委員組成？",o:["一位業外人士","兩位業外人士","三位業外人士","以上皆非，所有委員均來自保險業界"],e:"委員會四名委員中，兩名屬非保險業界人士（業外人士），另外兩名來自保險業界。"}},
{p:1,ch:"保险业的规管架构",q:"保险索偿投诉委员会由哪个机构委任?",o:["保险投诉局","香港政府","保险业监管局","立法会"],a:0,e:"保险索偿投诉委员会由保险投诉局委任，而非香港政府、保险业监管局或立法会。",src:1,tw:{ch:"保險業的規管架構",q:"保險索償投訴委員會由哪個機構委任？",o:["保險投訴局","香港政府","保險業監管局","立法會"],e:"保險索償投訴委員會由保險投訴局委任，而非香港政府、保險業監管局或立法會。"}},
{p:1,ch:"保险业的规管架构",q:"保险索偿投诉局于2018年1月16日易名为保险投诉局,成员为:",o:["所有在港获授权的保险人","在港承保的一般保险业务的保险人","在港承保的长期业务的保险人","所有在港承保个人保单的保险人"],a:3,e:"自2018年易名为保险投诉局后，其成员为所有在港承保个人保险业务的获授权保险人。",src:1,tw:{ch:"保險業的規管架構",q:"保險索償投訴局於2018年1月16日易名為保險投訴局，成員為:",o:["所有在港獲授權的保險人","在港承保的一般保險業務的保險人","在港承保的長期業務的保險人","所有在港承保個人保單的保險人"],e:"自2018年易名為保險投訴局後，其成員為所有在港承保個人保險業務的獲授權保險人。"}},
{p:1,ch:"保险业的规管架构",q:"保险经纪必须遵守适合该经纪的行业法律,这要求属于哪个领域?",o:["准确的陈述及介绍","合规","骚扰、强迫或不当影响","防止贿赂"],a:1,e:"保险经纪必须遵守适合其行业的法律，属于「合规」要求的范畴，与准确陈述、防止骚扰贿赂等属不同领域。",src:1,tw:{ch:"保險業的規管架構",q:"保險經紀必須遵守適合該經紀的行業法律，這要求屬於哪個領域？",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","防止賄賂"],e:"保險經紀必須遵守適合其行業的法律，屬於「合規」要求的範疇，與準確陳述、防止騷擾賄賂等屬不同領域。"}},
{p:1,ch:"保险业的规管架构",q:"偿付准备金的计算方法为:",o:["保险人的资产减以负债","保险人的负债减以资产","只适用于长期保险业务","不同类型保险公司有不同计算方法"],a:0,e:"偿付准备金以资产减负债计算，反映保险人资产超出负债的金额；它适用于各类业务，而非只限长期业务或按公司类型完全相异。",src:1,tw:{ch:"保險業的規管架構",q:"償付準備金的計算方法為：",o:["保險人的資產減以負債","保險人的負債減以資產","只適用於長期保險業務","不同類型保險公司有不同計算方法"],e:"償付準備金以資產減負債計算，反映保險人資產超出負債的金額；它適用於各類業務，而非只限長期業務或按公司類型完全相異。"}},
{p:1,ch:"保险业的规管架构",q:"向客户提供受规管意见时,持牌保险代理人必须向客人: i 提供意见前进行适当的合适性评估 ii 按照客户情况提供意见 iii 解释所有收益均是有保证的 iv 如客户坚持作出与建议相反的决定,代理人应记录并妥善备存",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"提供受规管意见时须先作合适性评估、按客户情况提供意见，并记录客户坚持作出的相反决定；“解释所有收益均有保证”并不正确，故排除iii。",src:1,tw:{ch:"保險業的規管架構",q:"向客戶提供受規管意見時，持牌保險代理人必須向客人： i 提供意見前進行適當的合適性評估 ii 按照客戶情況提供意見 iii 解釋所有收益均是有保證的 iv 如客戶堅持作出與建議相反的決定，代理人應記錄並妥善備存",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"提供受規管意見時須先作合適性評估、按客户情況提供意見，並記錄客户堅持作出的相反決定；“解釋所有收益均有保證”並不正確，故排除iii。"}},
{p:1,ch:"保险业的规管架构",q:"商业机构于香港被法院或当局裁定对于欺诈行为、不当行为或失当行为作出法律责任, 涉及哪一个领域?",o:["可靠程度","胜任程度","财政情况","其他事宜"],a:0,e:"商业机构曾在香港或其他地方被裁定对欺诈、不当行为或失当行为负法律责任，属适当人选准则中「可靠程度」范畴。",src:1,tw:{ch:"保險業的規管架構",q:"商業機構於香港被法院或當局裁定對於欺詐行為、不當行為或失當行為作出法律責任， 涉及哪一個領域？",o:["可靠程度","勝任程度","財政情況","其他事宜"],e:"商業機構曾在香港或其他地方被裁定對欺詐、不當行為或失當行為負法律責任，屬適當人選準則中「可靠程度」範疇。"}},
{p:1,ch:"保险业的规管架构",q:"在《保险业条例》中,下列哪项或哪些呈报规定不正确? i 每位保险人须每半年向保险业监管局呈交一份本身的财务报表 ii 每位保险人须每一年向保险业监管局呈交一份本身的财务报表 iii 长期业务保险人每年须向保险业监管局呈交一份精算调查报告 iv 一般业务保险人每年须向保险业监管局呈交一份经审计的 一般业务报表",o:["只有i","只有iii","i, iii, iv","ii, iii, iv"],a:0,e:"财务报表须每年（而非每半年）向保监局呈交，故i不正确；长期业务须呈交精算调查报告、一般业务须呈交经审计的一般业务报表均正确。",src:1,tw:{ch:"保險業的規管架構",q:"在《保險業條例》中，下列哪項或哪些呈報規定不正確？ i 每位保險人須每半年向保險業監管局呈交一份本身的財務報表 ii 每位保險人須每一年向保險業監管局呈交一份本身的財務報表 iii 長期業務保險人每年須向保險業監管局呈交一份精算調查報告 iv 一般業務保險人每年須向保險業監管局呈交一份經審計的 一般業務報表",o:["只有i","只有iii","i, iii, iv","ii, iii, iv"],e:"財務報表須每年（而非每半年）向保監局呈交，故i不正確；長期業務須呈交精算調查報告、一般業務須呈交經審計的一般業務報表均正確。"}},
{p:1,ch:"保险业的规管架构",q:"在受规管活动中,「关键决定」及「受规管意见」分别是指就以下哪项或哪些事项作出决定 或发表意见?",o:["就保险合约提出申请或作出建议","取消、终止、退回或转让保险合约","更改保险合约的任何条款或条件","以上各项皆正确"],a:3,e:"“关键决定”及“受规管意见”指就申请或建议合约、取消/终止/退回/转让合约及更改条款等作出决定或发表意见，故“以上各项皆正确”。",src:1,tw:{ch:"保險業的規管架構",q:"在受規管活動中，「關鍵決定」及「受規管意見」分別是指就以下哪項或哪些事項作出決定 或發表意見?",o:["就保險合約提出申請或作出建議","取消、終止、退回或轉讓保險合約","更改保險合約的任何條款或條件","以上各項皆正確"],e:"“關鍵決定”及“受規管意見”指就申請或建議合約、取消/終止/退回/轉讓合約及更改條款等作出決定或發表意見，故“以上各項皆正確”。"}},
{p:1,ch:"保险业的规管架构",q:"在新发牌制度下,已获保监局发出作为任何持牌保险代理机构进行一个或多于一个业务系列 的受规管活动的牌照的个人,这是属于哪一类别?",o:["持牌业务代表(代理人)","持牌业务代表(经纪)","持牌保险代理机构","持牌保险经纪公司"],a:0,e:"获保监局发牌、代表持牌保险代理机构进行受规管活动的个人属“持牌业务代表(代理人)”，而非经纪或机构本身。",src:1,tw:{ch:"保險業的規管架構",q:"在新發牌制度下，已獲保監局發出作為任何持牌保險代理機構進行一個或多於一個業務系列 的受規管活動的牌照的個人，這是屬於哪一類別?",o:["持牌業務代表（代理人）","持牌業務代表（經紀）","持牌保險代理機構","持牌保險經紀公司"],e:"獲保監局發牌、代表持牌保險代理機構進行受規管活動的個人屬“持牌業務代表(代理人)”，而非經紀或機構本身。"}},
{p:1,ch:"保险业的规管架构",q:"在新发牌制度下,已获保监局发出作为任何持牌保险经纪公司进行一个或多于一个业务系列 的受规管活动的牌照的个人,这是属于哪一类别?",o:["持牌业务代表(代理人)","持牌业务代表(经纪)","持牌保险代理机构","持牌保险经纪公司"],a:1,e:"获保监局发牌、代表持牌保险经纪公司进行受规管活动的个人属“持牌业务代表(经纪)”，而非代理人或机构本身。",src:1,tw:{ch:"保險業的規管架構",q:"在新發牌制度下，已獲保監局發出作為任何持牌保險經紀公司進行一個或多於一個業務系列 的受規管活動的牌照的個人，這是屬於哪一類別?",o:["持牌業務代表（代理人）","持牌業務代表（經紀）","持牌保險代理機構","持牌保險經紀公司"],e:"獲保監局發牌、代表持牌保險經紀公司進行受規管活動的個人屬“持牌業務代表(經紀)”，而非代理人或機構本身。"}},
{p:1,ch:"保险业的规管架构",q:"在新的发牌制度下,已获保监局发出作为任何获授权保险人的代理人进行一个或多于一个业 务系列的受规管活动的牌照的个人,属于:",o:["持牌业务代表(代理人)","持牌业务代表(经纪)","持牌保险代理机构","以上皆非"],a:3,e:"新制度下个人是作为持牌保险代理机构的代表（持牌业务代表）进行受规管活动，而非直接作为“获授权保险人”的代理人，故“以上皆非”。",src:1,tw:{ch:"保險業的規管架構",q:"在新的發牌制度下，已獲保監局發出作為任何獲授權保險人的代理人進行一個或多於一個業 務系列的受規管活動的牌照的個人，屬於：",o:["持牌業務代表（代理人）","持牌業務代表（經紀）","持牌保險代理機構","以上皆非"],e:"新制度下個人是作為持牌保險代理機構的代表（持牌業務代表）進行受規管活動，而非直接作為“獲授權保險人”的代理人，故“以上皆非”。"}},
{p:1,ch:"保险业的规管架构",q:"在申请成为持牌保险经纪公司时,须附合以下哪项最低限度规定?",o:["备存独立的客户帐户","股本及净资产","须购买专业赔偿保险","以上所有各项"],a:3,e:"申请成为持牌保险经纪公司须符合备存独立客户帐户、符合股本及净资产要求以及购买专业赔偿保险等最低规定，各项皆属。",src:1,tw:{ch:"保險業的規管架構",q:"在申請成為持牌保險經紀公司時，須附合以下哪項最低限度規定？",o:["備存獨立的客戶帳戶","股本及淨資產","須購買專業賠償保險","以上所有各項"],e:"申請成為持牌保險經紀公司須符合備存獨立客户帳户、符合股本及淨資產要求以及購買專業賠償保險等最低規定，各項皆屬。"}},
{p:1,ch:"保险业的规管架构",q:"在进行广告,产品销售时,持牌保险代理必须使用委任保险人所提供的认可资料、单张, 涉及哪个范畴?",o:["准确的陈述及介绍","合规","骚扰、强逼及不恰当","意见的合适性"],a:0,e:"进行广告及产品销售时，持牌保险代理人必须使用委任保险人提供的认可资料和单张，属「准确的陈述及介绍」范畴。",src:1,tw:{ch:"保險業的規管架構",q:"在進行廣告，產品銷售時，持牌保險代理必須使用委任保險人所提供的認可資料、單張， 涉及哪個範疇?",o:["準確的陳述及介紹","合規","騷擾、強逼及不恰當","意見的合適性"],e:"進行廣告及產品銷售時，持牌保險代理人必須使用委任保險人提供的認可資料和單張，屬「準確的陳述及介紹」範疇。"}},
{p:1,ch:"保险业的规管架构",q:"如商业实体曾在香港或其他地方被任何专业团体、行业公会或监管机构拒绝或限制行使从事 任何行业、业务或专业的权利,这是关于适当人选准则的哪个范畴?",o:["可靠程度","财政状况","个人声誉","其他相关事宜"],a:0,e:"曾被专业团体、行业公会或监管机构拒绝或限制从事任何行业/业务/专业的权利，属适当人选准则的「可靠程度」范畴。",src:1,tw:{ch:"保險業的規管架構",q:"如商業實體曾在香港或其他地方被任何專業團體、行業公會或監管機構拒絕或限制行使從事 任何行業、業務或專業的權利，這是關於適當人選準則的哪個範疇？",o:["可靠程度","財政狀況","個人聲譽","其他相關事宜"],e:"曾被專業團體、行業公會或監管機構拒絕或限制從事任何行業/業務/專業的權利，屬適當人選準則的「可靠程度」範疇。"}},
{p:1,ch:"保险业的规管架构",q:"如客户资料明确合理地不完整及不准确,保险代理人有责任作出跟进,确保资料完整准确, 这是属于哪项代理人操守守则的一般原则?",o:["诚实及持正","公平、公正及以客户的最佳利益行事","以谨慎、技巧和努力行事","胜任提供意见"],a:2,e:"当客户资料明显不完整不准确时，代理人有责任跟进以确保完整准确，属「以谨慎、技巧和努力行事」的一般原则。",src:1,tw:{ch:"保險業的規管架構",q:"如客戶資料明確合理地不完整及不準確，保險代理人有責任作出跟進，確保資料完整準確， 這是屬於哪項代理人操守守則的一般原則？",o:["誠實及持正","公平、公正及以客戶的最佳利益行事","以謹慎、技巧和努力行事","勝任提供意見"],e:"當客户資料明顯不完整不準確時，代理人有責任跟進以確保完整準確，屬「以謹慎、技巧和努力行事」的一般原則。"}},
{p:1,ch:"保险业的规管架构",q:"对于持牌保险经纪公司的要求,他的净资产备存必须要不少于:",o:["港币十万元","港币五十万元","港币一百万元","港币二百万元"],a:1,e:"持牌保险经纪公司的净资产必须不少于港币50万元，选项中的10万、100万、200万均不符。",src:1,tw:{ch:"保險業的規管架構",q:"對於持牌保險經紀公司的要求，他的淨資產備存必須要不少於：",o:["港幣十萬元","港幣五十萬元","港幣一百萬元","港幣二百萬元"],e:"持牌保險經紀公司的淨資產必須不少於港幣50萬元，選項中的10萬、100萬、200萬均不符。"}},
{p:1,ch:"保险业的规管架构",q:"就着足够的再保险安排,保险业监管局已就这个议题发出及实施一项指引,名为《与有关公 司安排再保险的指引》。此《指引》只适用于获授权保险人分保给「有关连再保险人」,「 有关连再保险人」是指:",o:["再保险人占其保费收入的20%或以上是来自该获授权保险人","获授权保险人其分出再保险保费的10%或以上交予再保险人","与保险人属同一公司群组的再保险人","跟获授权保险人是同一集团的姊妹公司的再保险人"],a:2,e:"“有关连再保险人”指与获授权保险人属同一公司群组的再保险人，而非以其保费占比或分保比例界定。",src:1,tw:{ch:"保險業的規管架構",q:"就着足夠的再保險安排,保險業監管局已就這個議題發出及實施一項指引,名為《與有關公 司安排再保險的指引》。此《指引》只適用於獲授權保險人分保給「有關連再保險人」,「 有關連再保險人」是指:",o:["再保險人佔其保費收入的20%或以上是來自該獲授權保險人","獲授權保險人其分出再保險保費的10%或以上交予再保險人","與保險人屬同一公司羣組的再保險人","跟獲授權保險人是同一集團的姊妹公司的再保險人"],e:"“有關連再保險人”指與獲授權保險人屬同一公司羣組的再保險人，而非以其保費佔比或分保比例界定。"}},
{p:1,ch:"保险业的规管架构",q:"所有持牌保险经纪公司备存的会计及其他记录,其记录:",o:["必须以电子的形式记录","必须以书面的形式记录","必须以文字的形式记录","必须以书面,或任何可以随时转为书面的形式记录"],a:3,e:"经纪公司的会计及其他记录须以书面、或任何可随时转为书面（可读）的形式记录，而非只限电子或纯书面。",src:1,tw:{ch:"保險業的規管架構",q:"所有持牌保險經紀公司備存的會計及其他記錄，其記錄：",o:["必須以電子的形式記錄","必須以書面的形式記錄","必須以文字的形式記錄","必須以書面，或任何可以隨時轉為書面的形式記錄"],e:"經紀公司的會計及其他記錄須以書面、或任何可隨時轉為書面（可讀）的形式記錄，而非只限電子或純書面。"}},
{p:1,ch:"保险业的规管架构",q:"所有持牌保险经纪公司备存的会计及其他记录必须保留不少于:",o:["一年","二年","五年","七年"],a:3,e:"所有持牌保险经纪公司备存的会计及其他记录必须保留不少于七年，一年、二年、五年均不符。",src:1,tw:{ch:"保險業的規管架構",q:"所有持牌保險經紀公司備存的會計及其他記錄必須保留不少於：",o:["一年","二年","五年","七年"],e:"所有持牌保險經紀公司備存的會計及其他記錄必須保留不少於七年，一年、二年、五年均不符。"}},
{p:1,ch:"保险业的规管架构",q:"所有持牌保险经纪公司必须备存会计及其他纪录的目的是为了: i 足以解释各项交易 ii 足以反映业务的财务状况 iii 显示该公司已遵守有关规则 iv 利用电脑储存资料",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iiii, iv"],a:0,e:"备存记录的目的包括足以解释各项交易、反映业务财务状况及显示已遵守有关规则；“利用电脑储存资料”只是保存形式而非目的。",src:1,tw:{ch:"保險業的規管架構",q:"所有持牌保險經紀公司必須備存會計及其他紀錄的目的是為了： i 足以解釋各項交易 ii 足以反映業務的財務狀況 iii 顯示該公司已遵守有關規則 iv 利用電腦儲存資料",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iiii, iv"],e:"備存記錄的目的包括足以解釋各項交易、反映業務財務狀況及顯示已遵守有關規則；“利用電腦儲存資料”只是保存形式而非目的。"}},
{p:1,ch:"保险业的规管架构",q:"承保、产品分析、索偿是保险的优良传统, 概述于:",o:["保险业规管指引","承保商专业守则","保险业监管局","以上皆是"],a:1,e:"承保、产品分析及索偿属保险的优良传统，其标准概述于《承保商专业守则》。",src:1,tw:{ch:"保險業的規管架構",q:"承保、產品分析、索償是保險的優良傳統， 概述於:",o:["保險業規管指引","承保商專業守則","保險業監管局","以上皆是"],e:"承保、產品分析及索償屬保險的優良傳統，其標準概述於《承保商專業守則》。"}},
{p:1,ch:"保险业的规管架构",q:"担当保险人的董事或行政总裁,必须:",o:["有两年的保险工作经验","是适当人选","备存十万港元的净资产","最少有一个「客户帐户」"],a:1,e:"担当保险人的董事或行政总裁须为“适当人选”，这是条文的根本要求；两年的工作经验、十万净资产及客户帐户并非此职位的要求。",src:1,tw:{ch:"保險業的規管架構",q:"擔當保險人的董事或行政總裁，必須：",o:["有兩年的保險工作經驗","是適當人選","備存十萬港元的淨資產","最少有一個「客戶帳戶」"],e:"擔當保險人的董事或行政總裁須為“適當人選”，這是條文的根本要求；兩年的工作經驗、十萬淨資產及客户帳户並非此職位的要求。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险代理机构或持牌保险经纪公司的拟委任负责人,必须符合以下哪项或哪些最低要求 ?",o:["不论任何行业,最少五年工作经验","如拥有特定学历或专业资格,无需任何保险工作经验","最少五年保险业经验,其中最少两年保险业管理经验","以上所有各项皆是"],a:2,e:"拟委任负责人须具备最少五年保险业经验，其中最少两年为保险业管理经验，此为该职的最低要求。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險代理機構或持牌保險經紀公司的擬委任負責人，必須符合以下哪項或哪些最低要求 ？",o:["不論任何行業，最少五年工作經驗","如擁有特定學歷或專業資格，無需任何保險工作經驗","最少五年保險業經驗，其中最少兩年保險業管理經驗","以上所有各項皆是"],e:"擬委任負責人須具備最少五年保險業經驗，其中最少兩年為保險業管理經驗，此為該職的最低要求。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险代理机构的官方定义是?",o:["作为获授权保险人的代理人的独资经营者、合伙企业或公司","作为任何保单持有人或潜在保单持有人的代理人的公司","作为获授权保险人的独家代理机构","作为获授权保险人的官方发言代表"],a:0,e:"持牌保险代理机构指作为获授权保险人的代理人的独资经营者、合伙企业或公司；它并非保单持有人或潜在持有人的代理人。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險代理機構的官方定義是？",o:["作為獲授權保險人的代理人的獨資經營者、合夥企業或公司","作為任何保單持有人或潛在保單持有人的代理人的公司","作為獲授權保險人的獨家代理機構","作為獲授權保險人的官方發言代表"],e:"持牌保險代理機構指作為獲授權保險人的代理人的獨資經營者、合夥企業或公司；它並非保單持有人或潛在持有人的代理人。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险经纪公司如自行制作广告或营销资料以进行受规管活动,必须确保有关内容准确, 没有欺诈、误导及混淆。这涉及哪个范畴?",o:["准确的陈述及介绍","合规","骚扰、强迫或不当影响","意见的合适性"],a:0,e:"持牌保险经纪公司自行制作广告或营销资料须确保内容准确、无欺诈误导及混淆，属「准确的陈述及介绍」范畴。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險經紀公司如自行製作廣告或營銷資料以進行受規管活動，必須確保有關內容準確， 沒有欺詐、誤導及混淆。這涉及哪個範疇?",o:["準確的陳述及介紹","合規","騷擾、強迫或不當影響","意見的合適性"],e:"持牌保險經紀公司自行製作廣告或營銷資料須確保內容準確、無欺詐誤導及混淆，屬「準確的陳述及介紹」範疇。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险经纪公司必须备有「专业弥偿保险」,最低的弥偿限额是:",o:["港币10万元","港币200万元","港币300万元","港币400万元"],a:2,e:"持牌保险经纪公司须投保专业弥偿保险，最低弥偿限额为港币300万元。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險經紀公司必須備有「專業彌償保險」，最低的彌償限額是：",o:["港幣10萬元","港幣200萬元","港幣300萬元","港幣400萬元"],e:"持牌保險經紀公司須投保專業彌償保險，最低彌償限額為港幣300萬元。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险经纪公司每年均需提交财务报表及核数师报告,以下哪项有关的要求陈述是不正确 的?",o:["财务报表须包括该财政年度的保险经纪收入, 区分为一般业务及长期业务","财务报表须包括该财政年度终结时客户帐户的现金总额及须付保费","核数师报告须载有陈述,述明该核数师是否认为有关财务报表 真实而中肯地反映有关公司的财务状况及财务表现","财务报表及核数师报告均必须获公司董事批准及签署"],a:3,e:"财务报表须获董事批准签署，但核数师报告由核数师发出并签署，并非必须获公司董事批准及签署，故该陈述不正确；其余三项均正确。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險經紀公司每年均需提交財務報表及核數師報告，以下哪項有關的要求陳述是不正確 的？",o:["財務報表須包括該財政年度的保險經紀收入， 區分為一般業務及長期業務","財務報表須包括該財政年度終結時客戶帳戶的現金總額及須付保費","核數師報告須載有陳述，述明該核數師是否認為有關財務報表 真實而中肯地反映有關公司的財務狀況及財務表現","財務報表及核數師報告均必須獲公司董事批准及簽署"],e:"財務報表須獲董事批准簽署，但核數師報告由核數師發出並簽署，並非必須獲公司董事批准及簽署，故該陳述不正確；其餘三項均正確。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险经纪公司需拥有的专业弥偿保险限额是不固定的,但是额限不必高于:",o:["10万","300万","1000万","7500万"],a:3,e:"持牌保险经纪公司专业弥偿保险的弥偿限额不固定，但不必高于7,500万港元（上限），其余10万、300万、1000万不符。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險經紀公司需擁有的專業彌償保險限額是不固定的，但是額限不必高於：",o:["10萬","300萬","1000萬","7500萬"],e:"持牌保險經紀公司專業彌償保險的彌償限額不固定，但不必高於7,500萬港元（上限），其餘10萬、300萬、1000萬不符。"}},
{p:1,ch:"保险业的规管架构",q:"持牌保险经纪公司须向以下哪个机构呈交每年的财务报表及核数师报告?",o:["证劵及期货事务监察委员会","保险业监管局","保险投诉局","香港金融管理局"],a:1,e:"持牌保险经纪公司须向保险业监管局呈交每年的财务报表及核数师报告，而非证监会、投诉局或金管局。",src:1,tw:{ch:"保險業的規管架構",q:"持牌保險經紀公司須向以下哪個機構呈交每年的財務報表及核數師報告？",o:["證劵及期貨事務監察委員會","保險業監管局","保險投訴局","香港金融管理局"],e:"持牌保險經紀公司須向保險業監管局呈交每年的財務報表及核數師報告，而非證監會、投訴局或金管局。"}},
{p:1,ch:"保险业的规管架构",q:"新《保险业条例》对持牌保险代理机构的人员,持牌保险经纪公司的人员,持牌业务代表( 代理人)和持牌业务代表(经纪)设置以下哪些限制?",o:["持牌保险代理机构的人员不得兼任另一持牌保险代理机构的经营人 或合伙人","持牌保险经纪公司的人员不得兼任持牌保险代理机构的经营人或 合伙人","持牌保险经纪公司的人员不得兼任持牌个人保险代理","以上各项"],a:3,e:"新《保险业条例》对各类人员设置限制：代理机构人员不得兼任另一代理机构的经营人或合伙人、经纪公司人员不得兼任代理机构人员或个人代理等，各项皆属。",src:1,tw:{ch:"保險業的規管架構",q:"新《保險業條例》對持牌保險代理機構的人員，持牌保險經紀公司的人員，持牌業務代表（ 代理人）和持牌業務代表（經紀）設置以下哪些限制?",o:["持牌保險代理機構的人員不得兼任另一持牌保險代理機構的經營人 或合夥人","持牌保險經紀公司的人員不得兼任持牌保險代理機構的經營人或 合夥人","持牌保險經紀公司的人員不得兼任持牌個人保險代理","以上各項"],e:"新《保險業條例》對各類人員設置限制：代理機構人員不得兼任另一代理機構的經營人或合夥人、經紀公司人員不得兼任代理機構人員或個人代理等，各項皆屬。"}},
{p:1,ch:"保险业的规管架构",q:"新条例载列保监局发给牌照的条件,当中包括保险中介人牌照申请人必须符合的“适当人选 \"准则。申请人可属于独资经营人、合伙或公司,就公司而言,申请人须直接或间接地有权 行使在该公司的成员大会上的投票权的不少于X%。这里的X %是指?",o:["5%","10%","15%","20%"],a:2,e:"就公司申请人而言，控权人须直接或间接有权行使公司成员大会投票权不少于15%，故X=15%。",src:1,tw:{ch:"保險業的規管架構",q:"新條例載列保監局發給牌照的條件,當中包括保險中介人牌照申請人必須符合的“適當人選 \"準則。申請人可屬於獨資經營人、合夥或公司,就公司而言,申請人須直接或間接地有權 行使在該公司的成員大會上的投票權的不少於X%。這裏的X %是指?",o:["5%","10%","15%","20%"],e:"就公司申請人而言，控權人須直接或間接有權行使公司成員大會投票權不少於15%，故X=15%。"}},
{p:1,ch:"保险业的规管架构",q:"某商业实体与债权人订立债务偿还安排,或按照香港或其他地方法院的命令偿还任何判定债 务,属于哪个领域?",o:["财务状况","胜任能力","意见合适性","其他事项"],a:0,e:"商业实体与债权人订立债务偿还安排、或依法院命令偿还判定债务，属适当人选准则的「财务状况」范畴。",src:1,tw:{ch:"保險業的規管架構",q:"某商業實體與債權人訂立債務償還安排，或按照香港或其他地方法院的命令償還任何判定債 務，屬於哪個領域?",o:["財務狀況","勝任能力","意見合適性","其他事項"],e:"商業實體與債權人訂立債務償還安排、或依法院命令償還判定債務，屬適當人選準則的「財務狀況」範疇。"}},
{p:1,ch:"保险业的规管架构",q:"根据《2015年保险公司(修订)条例》,保险业监管局的政策目标是?",o:["为保险持有人提供直接保障","确保保险业的规管架构与时并进,促进保险业稳定发展","确保保险业的规管架构与时并进,促进保险业高速发展","巩固香港国际金融地位"],a:1,e:"《2015年保险(修订)条例》下保监局的政策目标是确保规管架构与时并进、促进保险业稳定发展，而非提供直接保障或促进“高速发展”。",src:1,tw:{ch:"保險業的規管架構",q:"根據《2015年保險公司(修訂)條例》，保險業監管局的政策目標是?",o:["為保險持有人提供直接保障","確保保險業的規管架構與時並進，促進保險業穩定發展","確保保險業的規管架構與時並進，促進保險業高速發展","鞏固香港國際金融地位"],e:"《2015年保險(修訂)條例》下保監局的政策目標是確保規管架構與時並進、促進保險業穩定發展，而非提供直接保障或促進“高速發展”。"}},
{p:1,ch:"保险业的规管架构",q:"根据《2015年保险公司(修订)条例》,其赋予保险业监管局新的规管范围是:",o:["监察所有保险人维持充足偿付储备金,与国际惯常做法看齐","要求审计处查察在港经营业务保险人有充足偿付储备金, 维持保险业整体稳定","建立一个直接规管保险中介人的制度,以取代现时自律规管制度","以上各项皆是"],a:2,e:"该条例赋予保监局建立直接规管保险中介人的制度，以取代以往的自律规管制度，属其新增规管范围。",src:1,tw:{ch:"保險業的規管架構",q:"根據《2015年保險公司(修訂)條例》，其賦予保險業監管局新的規管範圍是：",o:["監察所有保險人維持充足償付儲備金，與國際慣常做法看齊","要求審計處查察在港經營業務保險人有充足償付儲備金， 維持保險業整體穩定","建立一個直接規管保險中介人的制度，以取代現時自律規管制度","以上各項皆是"],e:"該條例賦予保監局建立直接規管保險中介人的制度，以取代以往的自律規管制度，屬其新增規管範圍。"}},
{p:1,ch:"保险业的规管架构",q:"根据《2015年保险公司(修订)条例》,成立保险业监管局的政策目标是:",o:["确保保险业的规管架构与时并进,促进保险业高速增长","确保所有保险监管机构必须维持高水平的偿付准备金, 与国际惯常做法看齐","建立一个直接规管保险中介人的制度,以补充现时自律规管制度","确保保险业的规管架构与时并进,促进保险业稳健发展"],a:3,e:"成立保监局的政策目标是确保规管架构与时并进、促进保险业稳健发展，而非促进“高速增长”、维持高偿付准备金等的表述。",src:1,tw:{ch:"保險業的規管架構",q:"根據《2015年保險公司(修訂)條例》，成立保險業監管局的政策目標是：",o:["確保保險業的規管架構與時並進，促進保險業高速增長","確保所有保險監管機構必須維持高水平的償付準備金， 與國際慣常做法看齊","建立一個直接規管保險中介人的制度，以補充現時自律規管制度","確保保險業的規管架構與時並進，促進保險業穩健發展"],e:"成立保監局的政策目標是確保規管架構與時並進、促進保險業穩健發展，而非促進“高速增長”、維持高償付準備金等的表述。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业(持牌保险经纪公司的财务及其他要求)规则》,以下哪项是规定了保险经纪公司 在任何时间的股本及净资产要求?",o:["缴足款股本: HK$500,000;净资产: HK$500,000","缴足款股本: HK$1,000,000 ;净资产: HK$1,000,000","缴足款股本: HK$500,000;净资产: HK$1,000,000","缴足款股本:HK$1,000,000;净资产: HK$500,000"],a:0,e:"《保险业(持牌保险经纪公司的财务及其他要求)规则》规定经纪公司在任何时间须维持缴足股本HK$500,000及净资产HK$500,000。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業(持牌保險經紀公司的財務及其他要求)規則》，以下哪項是規定了保險經紀公司 在任何時間的股本及淨資產要求？",o:["繳足款股本: HK$500,000；淨資產: HK$500,000","繳足款股本: HK$1,000,000 ；淨資產: HK$1,000,000","繳足款股本: HK$500,000；淨資產: HK$1,000,000","繳足款股本:HK$1,000,000；淨資產: HK$500,000"],e:"《保險業(持牌保險經紀公司的財務及其他要求)規則》規定經紀公司在任何時間須維持繳足股本HK$500,000及淨資產HK$500,000。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》(IO),在委任以下哪人或哪些人前,须先取得保监局同意?",o:["经营长期保险业务的保险人的获委任精算师","获授权保险人的行政人员","获授权的保险中介人","以上所有"],a:0,e:"委任经营长期保险业务的保险人的获委任精算师前，须先取得保监局同意；一般行政人员及中介人的委任不在此列。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》(IO)，在委任以下哪人或哪些人前，須先取得保監局同意？",o:["經營長期保險業務的保險人的獲委任精算師","獲授權保險人的行政人員","獲授權的保險中介人","以上所有"],e:"委任經營長期保險業務的保險人的獲委任精算師前，須先取得保監局同意；一般行政人員及中介人的委任不在此列。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》,以下哪项对偿付准备金要求的陈述是正确的? i 专属自保保险人为200万元 ii 从事长期业务的保险人为2000万元 iii 同时经营长期及一般业务的保险人为1200万元 iv 从事意外的保险人及汽车方面的法律责任为2000万元",o:["i, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],a:1,e:"偿付准备金规定中，专属自保为200万、同时经营长期及一般业务为1200万、意外及汽车法律责任为2000万均正确；仅从事长期业务的保险人偿付准备金并非2000万，故ii不正确。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》，以下哪項對償付準備金要求的陳述是正確的？ i 專屬自保保險人為200萬元 ii 從事長期業務的保險人為2000萬元 iii 同時經營長期及一般業務的保險人為1200萬元 iv 從事意外的保險人及汽車方面的法律責任為2000萬元",o:["i, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],e:"償付準備金規定中，專屬自保為200萬、同時經營長期及一般業務為1200萬、意外及汽車法律責任為2000萬均正確；僅從事長期業務的保險人償付準備金並非2000萬，故ii不正確。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》,以下哪项对实缴股本要求的陈述是正确的? i 专属自保保险人为200万元 ii 从事一般业务的保险人为1000万元 iii 同时经营长期及一般业务的保险人为2000万元 iv 从事意外及汽车方面的法律责任为2000万元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"实缴股本要求中，专属自保200万、一般业务1000万、同时经营两类业务2000万及意外/汽车法律责任2000万均与法例相符，各项全对。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》，以下哪項對實繳股本要求的陳述是正確的？ i 專屬自保保險人為200萬元 ii 從事一般業務的保險人為1000萬元 iii 同時經營長期及一般業務的保險人為2000萬元 iv 從事意外及汽車方面的法律責任為2000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],e:"實繳股本要求中，專屬自保200萬、一般業務1000萬、同時經營兩類業務2000萬及意外/汽車法律責任2000萬均與法例相符，各項全對。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》,以下哪项对实缴股本要求的陈述是正确的? i 专属自保保险人为200万元 ii 从事长期业务的保险人为1000万元 iii 经营长期业务及一般保险的保险人为2000万元 iv 从事意外及汽车方面的法律责任为2000万元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"实缴股本要求中，专属自保200万、长期业务1000万、同时经营两类业务2000万及意外/汽车法律责任2000万均正确，各项全对。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》，以下哪項對實繳股本要求的陳述是正確的？ i 專屬自保保險人為200萬元 ii 從事長期業務的保險人為1000萬元 iii 經營長期業務及一般保險的保險人為2000萬元 iv 從事意外及汽車方面的法律責任為2000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],e:"實繳股本要求中，專屬自保200萬、長期業務1000萬、同時經營兩類業務2000萬及意外/汽車法律責任2000萬均正確，各項全對。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》,经营一般业务的保险人除了每年要递交一份经审核的财务报表外,还 有哪两份需要提交? i 经审核的收益及损失表 ii经审计的资产负债表 iii 经 审计的一般业务报表 iv精算调查报告",o:["ii, iii","i, ii, iii","i, ii, iv","i, ii, iii, iv"],a:0,e:"一般业务保险人除每年递交经审核财务报表（已含损益表）外，还须递交经审计的资产负债表及经审计的一般业务报表；精算调查报告属长期业务。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》，經營一般業務的保險人除了每年要遞交一份經審核的財務報表外，還 有哪兩份需要提交？ i 經審核的收益及損失表 ii經審計的資產負債表 iii 經 審計的一般業務報表 iv精算調查報告",o:["ii, iii","i, ii, iii","i, ii, iv","i, ii, iii, iv"],e:"一般業務保險人除每年遞交經審核財務報表（已含損益表）外，還須遞交經審計的資產負債表及經審計的一般業務報表；精算調查報告屬長期業務。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》,若保险人同时从事一般及长期业务,最低实缴股本为:",o:["港币280万","港币1800万","港币2000万","港币4000万"],a:2,e:"同时从事一般及长期业务的保险人，其最低实缴股本为港币2,000万元。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》，若保險人同時從事一般及長期業務，最低實繳股本為：",o:["港幣280萬","港幣1800萬","港幣2000萬","港幣4000萬"],e:"同時從事一般及長期業務的保險人，其最低實繳股本為港幣2,000萬元。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》以下哪类人士或机构需符合「适当人选」准则? i 持牌保险中介人 ii 保险代理机构的控权人 iii 持牌保险经纪公司的合伙人 iv 保险代理机构的负责人",o:["i, iii","i, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"持牌保险中介人、保险代理机构的控权人、持牌保险经纪公司的合伙人及代理机构负责人均须符合“适当人选”准则，各项全对。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》以下哪類人士或機構需符合「適當人選」準則？ i 持牌保險中介人 ii 保險代理機構的控權人 iii 持牌保險經紀公司的合夥人 iv 保險代理機構的負責人",o:["i, iii","i, iv","ii, iii, iv","i, ii, iii, iv"],e:"持牌保險中介人、保險代理機構的控權人、持牌保險經紀公司的合夥人及代理機構負責人均須符合“適當人選”準則，各項全對。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》的条文,毋须得到保险业监管局的授权才可委任:",o:["公司的精算师","保险公司的行政总裁","保险公司的任何一位财务总监","保险公司的理赔经理"],a:3,e:"委任公司的精算师、行政总裁及财务总监均须保监局认可；理赔经理毋须事先获保监局授权即可委任，故该项正确。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》的條文，毋須得到保險業監管局的授權才可委任:",o:["公司的精算師","保險公司的行政總裁","保險公司的任何一位財務總監","保險公司的理賠經理"],e:"委任公司的精算師、行政總裁及財務總監均須保監局認可；理賠經理毋須事先獲保監局授權即可委任，故該項正確。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》的规定,以下哪项对本港保险人的最低实缴股本金额要求并不正确?",o:["专属自保保险人为1,000万港元","从事法定保险业务的保险人为2,000万元","只从事长期或一般业务的保险人为1,000万元","同时从事长期及一般业务的保险人为2,000万元"],a:0,e:"专属自保保险人的最低实缴股本为200万港元（而非1,000万），故该项不正确；其余各项金额均与法例相符。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》的規定，以下哪項對本港保險人的最低實繳股本金額要求並不正確?",o:["專屬自保保險人為1,000萬港元","從事法定保險業務的保險人為2,000萬元","只從事長期或一般業務的保險人為1,000萬元","同時從事長期及一般業務的保險人為2,000萬元"],e:"專屬自保保險人的最低實繳股本為200萬港元（而非1,000萬），故該項不正確；其餘各項金額均與法例相符。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》的规定,以下哪项对本港保险人的最低股本金额要求并不正确?",o:["专属自保保险人为2,000万港元","从事长期及一般业务的保险人为2,000万元","从事长期业务的保险人为1,000万元","从事车保第三者的法定业务的保险人为2,000万元"],a:0,e:"专属自保保险人的最低实缴股本为200万港元（而非2,000万），故该项不正确；其余各项金额均正确。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》的規定，以下哪項對本港保險人的最低股本金額要求並不正確?",o:["專屬自保保險人為2,000萬港元","從事長期及一般業務的保險人為2,000萬元","從事長期業務的保險人為1,000萬元","從事車保第三者的法定業務的保險人為2,000萬元"],e:"專屬自保保險人的最低實繳股本為200萬港元（而非2,000萬），故該項不正確；其餘各項金額均正確。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》第81条,以下哪些是保监局对持牌保险中介人、负责人或受规管人士可 以行使的纪律权力? i 发出谴责 ii 撤销牌照 iii 指明期间内禁止申请牌照或委任为负责人 iv 罚款",o:["i, ii","i, ii, iii","iii, iv","i, ii, iii, iv"],a:3,e:"第81条赋予保监局的纪律权力包括发出谴责、撤销牌照、指明期内禁止申请牌照或担任负责人及罚款，各项全对。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》第81條，以下哪些是保監局對持牌保險中介人、負責人或受規管人士可 以行使的紀律權力? i 發出譴責 ii 撤銷牌照 iii 指明期間內禁止申請牌照或委任為負責人 iv 罰款",o:["i, ii","i, ii, iii","iii, iv","i, ii, iii, iv"],e:"第81條賦予保監局的紀律權力包括髮出譴責、撤銷牌照、指明期內禁止申請牌照或擔任負責人及罰款，各項全對。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》第81条,给予保监局对有关人士行使什么权力? i 撤销或暂时吊销该人的牌照 ii 撤销或暂时吊销该人作为负责人的认可 iii 公开或非公开地谴责 iv  命令该人罚款最高数额如1,000万港元或获取的利润或避免的损失的数额三倍",o:["i, ii","ii, iii, iv","i, ii, iii","i, ii, iii, iv"],a:3,e:"第81条下保监局可撤销或吊销牌照、撤销或吊销负责人认可、公开或非公开谴责，并处以最高1,000万或所得利润/避免损失三倍的罚款，各项全对。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》第81條，給予保監局對有關人士行使什麼權力？ i 撤銷或暫時吊銷該人的牌照 ii 撤銷或暫時吊銷該人作為負責人的認可 iii 公開或非公開地譴責 iv 命令該人罰款最高數額如1,000萬港元或獲取的利潤或避免的損失的數額三倍",o:["i, ii","ii, iii, iv","i, ii, iii","i, ii, iii, iv"],e:"第81條下保監局可撤銷或吊銷牌照、撤銷或吊銷負責人認可、公開或非公開譴責，並處以最高1,000萬或所得利潤/避免損失三倍的罰款，各項全對。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》适用于保险人授权的一般规则中,有关再保险的要求指出,它必须:",o:["足够","足够偿还所有债务","最少相当于偿付准备金","全部放置于香港的再保险人"],a:0,e:"条例对再保险的一般要求是保险人的再保险安排必须“足够”，而非必须足以偿还所有债务、相当于偿付准备金或全部置于香港再保险人。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》適用於保險人授權的一般規則中，有關再保險的要求指出，它必須：",o:["足夠","足夠償還所有債務","最少相當於償付準備金","全部放置於香港的再保險人"],e:"條例對再保險的一般要求是保險人的再保險安排必須“足夠”，而非必須足以償還所有債務、相當於償付準備金或全部置於香港再保險人。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险公司条例》,保险人若要获得授权,必须符合哪项实缴股本要求?",o:["经营任何法定(或强制)保险业务,不论有否经营其他保险业务, 最低要求为HK$5,000,000","经营任何法定(或强制)保险业务,不论有否经营其他保险业务, 最低要求为HK$10,000,000","只经营一般业务或只经营长期业务,而非任何法定(或强制) 保险业务, 最低要求为HK$10,000,000","同时经营一般及长期业务,最低要求为HK$10,000,000"],a:2,e:"只经营一般或只经营长期业务、且非任何法定（强制）保险业务的保险人，最低实缴股本为HK$10,000,000；经营法定业务者另有较高要求。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險公司條例》，保險人若要獲得授權，必須符合哪項實繳股本要求？",o:["經營任何法定（或強制）保險業務，不論有否經營其他保險業務， 最低要求為HK$5,000,000","經營任何法定（或強制）保險業務，不論有否經營其他保險業務， 最低要求為HK$10,000,000","只經營一般業務或只經營長期業務，而非任何法定（或強制） 保險業務， 最低要求為HK$10,000,000","同時經營一般及長期業務，最低要求為HK$10,000,000"],e:"只經營一般或只經營長期業務、且非任何法定（強制）保險業務的保險人，最低實繳股本為HK$10,000,000；經營法定業務者另有較高要求。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》,以下哪些属于使用投保书/申请表的部份意见? i 以清晰浅白的语言表达 ii 解释最高诚信原则要求的重要性 iii 任何重要事实,以清晰问题作出提问 iv 小心解释任何附带问卷的重要性",o:["ii, iii","i, iii, iv","iii, iv","i, ii, iii, iv"],a:3,e:"守则就使用投保书/申请表的意见包括：清晰浅白语言、解释最高诚信的重要性、以清晰问题提问重要事实及小心解释附带问卷的重要性，各项全对。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》，以下哪些屬於使用投保書/申請表的部份意見？ i 以清晰淺白的語言表達 ii 解釋最高誠信原則要求的重要性 iii 任何重要事實，以清晰問題作出提問 iv 小心解釋任何附帶問卷的重要性",o:["ii, iii","i, iii, iv","iii, iv","i, ii, iii, iv"],e:"守則就使用投保書/申請表的意見包括：清晰淺白語言、解釋最高誠信的重要性、以清晰問題提問重要事實及小心解釋附帶問卷的重要性，各項全對。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》,以下哪项属于建议及销售的文件? i 销售资料 ii 投保书 iii 保单 iv 医疗证明书",o:["只有i","i及ii","i, ii, iii","以上所有"],a:3,e:"根据《承保商专业守则》，建议及销售的整个流程所涉及的文件包括销售资料、投保书、保单及医疗证明书，四者均属向客户作出建议及完成销售时须处理的文件，故答案为「以上所有」。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》，以下哪項屬於建議及銷售的文件？ i 銷售資料 ii 投保書 iii 保單 iv 醫療證明書",o:["只有i","i及ii","i, ii, iii","以上所有"],e:"根據《承保商專業守則》，建議及銷售的整個流程所涉及的文件包括銷售資料、投保書、保單及醫療證明書，四者均屬向客户作出建議及完成銷售時須處理的文件，故答案為「以上所有」。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》,以下哪项是正确? i 任何重要事实要以清晰问题提问 ii 于损失时须要披露重要事实是对最高诚信准则的重要性 iii 续保时须要披露重要事实是对最高诚信准则的重要性 iv 小心解释任何附带问卷的重要性",o:["ii, iii","i, iii, iv","i, iv","i, ii, iii, iv"],a:1,e:"最高诚信要求以清晰的问题就重要事实提问、续保时同样须披露重要事实，并要小心解释附带问卷；而「于损失时须披露重要事实」是索偿阶段的义务，并非最高诚信的适用时点，故 ii 不正确，答案为 i、iii、iv。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》，以下哪項是正確? i 任何重要事實要以清晰問題提問 ii 於損失時須要披露重要事實是對最高誠信準則的重要性 iii 續保時須要披露重要事實是對最高誠信準則的重要性 iv 小心解釋任何附帶問卷的重要性",o:["ii, iii","i, iii, iv","i, iv","i, ii, iii, iv"],e:"最高誠信要求以清晰的問題就重要事實提問、續保時同樣須披露重要事實，並要小心解釋附帶問卷；而「於損失時須披露重要事實」是索償階段的義務，並非最高誠信的適用時點，故 ii 不正確，答案為 i、iii、iv。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》,以下哪项适用于索偿时是正确的?",o:["代表保险人的第三者至少要有经验","代表保险人的第三者要有适当经验,并具备专业资格","不可以律师或理赔师以外的人担任保险人的第三者","代表保险人的第三者,在任何情况下都应当合理地行事, 并且应该具备专业资格"],a:3,e:"《承保商专业守则》规定，代表保险人处理索偿的第三者在任何情况下都应合理地行事，并具备专业资格，而非仅仅有经验或只限由律师、理赔师担任，故应选此项。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》，以下哪項適用於索償時是正確的？",o:["代表保險人的第三者至少要有經驗","代表保險人的第三者要有適當經驗，並具備專業資格","不可以律師或理賠師以外的人擔任保險人的第三者","代表保險人的第三者，在任何情況下都應當合理地行事， 並且應該具備專業資格"],e:"《承保商專業守則》規定，代表保險人處理索償的第三者在任何情況下都應合理地行事，並具備專業資格，而非僅僅有經驗或只限由律師、理賠師擔任，故應選此項。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》确保保险代理人遵守所有适用的法律,其责任在于:",o:["保险业监管局","保险代理登记委员会","有关保险公司的销售管理行政主任","保险人,因他是其代理人的委托人"],a:3,e:"保险人是其保险代理的委托人，因此确保代理人遵守所有适用法律的责任在于保险人本人；保监局、登记委员会及销售管理行政主任均非该责任的直接承担者。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》確保保險代理人遵守所有適用的法律，其責任在於:",o:["保險業監管局","保險代理登記委員會","有關保險公司的銷售管理行政主任","保險人，因他是其代理人的委託人"],e:"保險人是其保險代理的委託人，因此確保代理人遵守所有適用法律的責任在於保險人本人；保監局、登記委員會及銷售管理行政主任均非該責任的直接承擔者。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》订立符合标准的优良保险惯例,包括:",o:["产品分析","核保及索偿","保险合约下的顾客权益及须负的责任","以上所有各项"],a:3,e:"优良保险惯例涵盖产品分析、核保及索偿，以及保险合约下顾客的权益与责任等多个环节，故「以上所有各项」均属其订立范围。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》訂立符合標準的優良保險慣例，包括：",o:["產品分析","核保及索償","保險合約下的顧客權益及須負的責任","以上所有各項"],e:"優良保險慣例涵蓋產品分析、核保及索償，以及保險合約下顧客的權益與責任等多個環節，故「以上所有各項」均屬其訂立範圍。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险中介人持续专业培训指引》,除另有规定外,个人持牌人须在每个评核期参 与合资格持续专业培训活动,以获得最少_____的持续专业培训时数。",o:["10 (包括最少3个「道德或规例」范畴)","15 (包括最少3个「道德或规例」范畴)","15 (包括最少5个「道德或规例」范畴)","20 (包括最少5个「道德或规例」范畴)"],a:1,e:"《持牌保险中介人持续专业培训指引》规定，除另有规定外，个人持牌人每个评核期须取得最少15小时持续专业培训时数，其中最少3小时属「道德或规例」范畴。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險中介人持續專業培訓指引》,除另有規定外,個人持牌人須在每個評核期參 與合資格持續專業培訓活動,以獲得最少_____的持續專業培訓時數。",o:["10 (包括最少3個「道德或規例」範疇)","15 (包括最少3個「道德或規例」範疇)","15 (包括最少5個「道德或規例」範疇)","20 (包括最少5個「道德或規例」範疇)"],e:"《持牌保險中介人持續專業培訓指引》規定，除另有規定外，個人持牌人每個評核期須取得最少15小時持續專業培訓時數，其中最少3小時屬「道德或規例」範疇。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 1」是指:",o:["诚实及持正","公平行事并符合客户的最佳利益","以谨慎、技巧和努力行事","胜任提供意见"],a:0,e:"《持牌保险代理人操守守则》的一般原则依次为：原则1诚实及持正，故正确答案为「诚实及持正」；公平行事、谨慎行事及胜任提供意见分别是后续原则的内容。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 1」是指：",o:["誠實及持正","公平行事並符合客戶的最佳利益","以謹慎、技巧和努力行事","勝任提供意見"],e:"《持牌保險代理人操守守則》的一般原則依次為：原則1誠實及持正，故正確答案為「誠實及持正」；公平行事、謹慎行事及勝任提供意見分別是後續原則的內容。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 2」是指:",o:["诚实及持正","公平行事并符合客户的最佳利益","以谨慎、技巧和努力行事","胜任提供意见"],a:1,e:"原则2为「公平行事并符合客户的最佳利益」，要求代理人以客户利益为先。「诚实及持正」是原则1，谨慎行事及胜任提供意见则属原则3、4。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 2」是指：",o:["誠實及持正","公平行事並符合客戶的最佳利益","以謹慎、技巧和努力行事","勝任提供意見"],e:"原則2為「公平行事並符合客户的最佳利益」，要求代理人以客户利益為先。「誠實及持正」是原則1，謹慎行事及勝任提供意見則屬原則3、4。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 3」是指:",o:["诚实及持正","公平行事并符合客户的最佳利益","以谨慎、技巧和努力行事","胜任提供意见"],a:2,e:"原则3为「以谨慎、技巧和努力行事」，强调执业时的专业水准。原则1为诚实及持正、原则2为公平行事、原则4为胜任提供意见。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 3」是指：",o:["誠實及持正","公平行事並符合客戶的最佳利益","以謹慎、技巧和努力行事","勝任提供意見"],e:"原則3為「以謹慎、技巧和努力行事」，強調執業時的專業水準。原則1為誠實及持正、原則2為公平行事、原則4為勝任提供意見。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 4」是指:",o:["诚实及持正","公平行事并符合客户的最佳利益","以谨慎、技巧和努力行事","胜任提供意见"],a:3,e:"原则4为「胜任提供意见」，要求代理人具备足够能力才向客户提供建议；前三项（诚实及持正、公平行事、谨慎技巧努力）分别为原则1至3。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 4」是指：",o:["誠實及持正","公平行事並符合客戶的最佳利益","以謹慎、技巧和努力行事","勝任提供意見"],e:"原則4為「勝任提供意見」，要求代理人具備足夠能力才向客户提供建議；前三項（誠實及持正、公平行事、謹慎技巧努力）分別為原則1至3。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 5」是指:",o:["资料披露","公平行事并符合客户的最佳利益","意见的合适性","利益冲突"],a:0,e:"原则5为「资料披露」，要求代理人向客户作充分及清楚的资料披露，故答案为「资料披露」；其余选项分别对应原则2、6、7。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 5」是指：",o:["資料披露","公平行事並符合客戶的最佳利益","意見的合適性","利益衝突"],e:"原則5為「資料披露」，要求代理人向客户作充分及清楚的資料披露，故答案為「資料披露」；其餘選項分別對應原則2、6、7。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 6」是指:",o:["资料披露","公平行事并符合客户的最佳利益","意见的合适性","利益冲突"],a:2,e:"原则6为「意见的合适性」，强调所提供意见须切合客户的情况与需要。资料披露为原则5、公平行事为原则2、利益冲突为原则7。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 6」是指：",o:["資料披露","公平行事並符合客戶的最佳利益","意見的合適性","利益衝突"],e:"原則6為「意見的合適性」，強調所提供意見須切合客户的情況與需要。資料披露為原則5、公平行事為原則2、利益衝突為原則7。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 7」是指:",o:["资料披露","公平行事并符合客户的最佳利益","意见的合适性","利益冲突"],a:3,e:"原则7为「利益冲突」，要求代理人识别并妥善处理利益冲突；资料披露为原则5、意见的合适性为原则6。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 7」是指：",o:["資料披露","公平行事並符合客戶的最佳利益","意見的合適性","利益衝突"],e:"原則7為「利益衝突」，要求代理人識別並妥善處理利益衝突；資料披露為原則5、意見的合適性為原則6。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》,「一般原则 8」是指:",o:["资料披露","客户资产","意见的合适性","利益冲突"],a:1,e:"原则8为「客户资产」，规管代理人对客户资金的持有与处理，故答案为「客户资产」；其余为原则5、6、7的内容。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》，「一般原則 8」是指：",o:["資料披露","客戶資產","意見的合適性","利益衝突"],e:"原則8為「客户資產」，規管代理人對客户資金的持有與處理，故答案為「客户資產」；其餘為原則5、6、7的內容。"}},
{p:1,ch:"保险业的规管架构",q:"根据《持牌保险代理人操守守则》第IX节 - 公司管治与管控及程序,持牌保险代理机构应妥善采取五项管控及程序,以下哪项不属于有 关的范围?",o:["合规","业务发展","保存纪录","向保监局报告事件"],a:1,e:"持牌保险代理机构须建立的五项管控及程序包括合规、保存纪录、内部管控及向保监局报告事件等，「业务发展」并非规管要求的管控程序，故应选此项。",src:1,tw:{ch:"保險業的規管架構",q:"根據《持牌保險代理人操守守則》第IX節 - 公司管治與管控及程序，持牌保險代理機構應妥善採取五項管控及程序，以下哪項不屬於有 關的範圍？",o:["合規","業務發展","保存紀錄","向保監局報告事件"],e:"持牌保險代理機構須建立的五項管控及程序包括合規、保存紀錄、內部管控及向保監局報告事件等，「業務發展」並非規管要求的管控程序，故應選此項。"}},
{p:1,ch:"保险业的规管架构",q:"根据保监局规定,每一个持牌保险代理机构和持牌保险经纪公司必须委任为最少一名负责人 ,监督受规管活动的进行,以下哪项有关保监局认可负责人的条件的陈述是正确的?",o:["他是个持牌业务代表(代理人)或持牌业务代表(经纪), 或申请业务代表(代理人)牌照或业务代表(经纪)牌照的人","他将会属于履行其作为负责人的责任的适当人选 (不论是单独或联同其他负责人)","他有充分权限,并将获得充足资源及支援,以履行负责人责任","以上各项皆正确"],a:3,e:"负责人须是持牌业务代表或申请人、属履行责任的适当人选，并拥有充分权限、资源及支援，三项均符合保监局的认可条件，故「以上各项皆正确」。",src:1,tw:{ch:"保險業的規管架構",q:"根據保監局規定，每一個持牌保險代理機構和持牌保險經紀公司必須委任為最少一名負責人 ，監督受規管活動的進行，以下哪項有關保監局認可負責人的條件的陳述是正確的?",o:["他是個持牌業務代表（代理人）或持牌業務代表（經紀）， 或申請業務代表（代理人）牌照或業務代表（經紀）牌照的人","他將會屬於履行其作為負責人的責任的適當人選 （不論是單獨或聯同其他負責人）","他有充分權限，並將獲得充足資源及支援，以履行負責人責任","以上各項皆正確"],e:"負責人須是持牌業務代表或申請人、屬履行責任的適當人選，並擁有充分權限、資源及支援，三項均符合保監局的認可條件，故「以上各項皆正確」。"}},
{p:1,ch:"保险业的规管架构",q:"根据保险业条例,以下哪项必须获得保险业监管局认可才能委任?",o:["获授权保险人的管控要员","获授权保险人的财务经理及财务人员","任何保险代理人","理赔部员工"],a:0,e:"《保险业条例》规定获授权保险人的管控要员须经保监局认可后方可委任；财务经理、一般代理人及理赔部员工并非此须认可的职位，故选此项。",src:1,tw:{ch:"保險業的規管架構",q:"根據保險業條例，以下哪項必須獲得保險業監管局認可才能委任?",o:["獲授權保險人的管控要員","獲授權保險人的財務經理及財務人員","任何保險代理人","理賠部員工"],e:"《保險業條例》規定獲授權保險人的管控要員須經保監局認可後方可委任；財務經理、一般代理人及理賠部員工並非此須認可的職位，故選此項。"}},
{p:1,ch:"保险业的规管架构",q:"根据保险代理人操守守则,以下哪项不是客户资产的一般原则下处理保费的标准?",o:["妥善保管所收取的保费,并避免将有关保费与该代理人的个人资金混合","鼓励客户以最优惠的方案(年供还是月供)缴付保费","不应收取以现金方式支付的保费款项,除非未能在合理可行的情况下以其他方式 支付或获主事人授权","只可在其主事人授予的权限范围内收取保费的付款"],a:1,e:"处理保费的标准包括妥善保管、避免与个人资金混同、原则上不收取现金及仅限在主事人授权范围内收款；「鼓励客户以最优惠方案缴付保费」是销售建议而非客户资产标准，故不属该标准。",src:1,tw:{ch:"保險業的規管架構",q:"根據保險代理人操守守則，以下哪項不是客戶資產的一般原則下處理保費的標準？",o:["妥善保管所收取的保費，並避免將有關保費與該代理人的個人資金混合","鼓勵客戶以最優惠的方案（年供還是月供）繳付保費","不應收取以現金方式支付的保費款項，除非未能在合理可行的情況下以其他方式 支付或獲主事人授權","只可在其主事人授予的權限範圍內收取保費的付款"],e:"處理保費的標準包括妥善保管、避免與個人資金混同、原則上不收取現金及僅限在主事人授權範圍內收款；「鼓勵客户以最優惠方案繳付保費」是銷售建議而非客户資產標準，故不屬該標準。"}},
{p:1,ch:"保险业的规管架构",q:"根据指引23的“适当人选”准则,分为个人准则及商业实体准则,以下哪项属于个人准则中 保监局会考虑的范畴? i. 学历或其他资历或经验 ii. 称职地并公正地进行受规管活动的能力 iii.信誉、品格、可靠程度、诚实及诚信 iv. 财政状况或偿付能力",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"指引23个人准则会考虑学历资历经验、称职及公正执业能力、信誉与诚信，以及财政状况或偿付能力等范畴，四项均属保监局考虑范围，故全选。",src:1,tw:{ch:"保險業的規管架構",q:"根據指引23的“適當人選”準則，分為個人準則及商業實體準則，以下哪項屬於個人準則中 保監局會考慮的範疇? i. 學歷或其他資歷或經驗 ii. 稱職地並公正地進行受規管活動的能力 iii.信譽、品格、可靠程度、誠實及誠信 iv. 財政狀況或償付能力",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"指引23個人準則會考慮學歷資歷經驗、稱職及公正執業能力、信譽與誠信，以及財政狀況或償付能力等範疇，四項均屬保監局考慮範圍，故全選。"}},
{p:1,ch:"保险业的规管架构",q:"根据指引23的“适当人选”准则,负责人须有多少年相关工作经验?",o:["2年","5年","10年","15年"],a:3,e:"指引23的「适当人选」准则对负责人设定15年相关工作经验的要求，以确保其具备足够能力监督受规管活动；其余年数均低于该规定。",src:1,tw:{ch:"保險業的規管架構",q:"根據指引23的“適當人選”準則，負責人須有多少年相關工作經驗？",o:["2年","5年","10年","15年"],e:"指引23的「適當人選」準則對負責人設定15年相關工作經驗的要求，以確保其具備足夠能力監督受規管活動；其餘年數均低於該規定。"}},
{p:1,ch:"保险业的规管架构",q:"根据法例,偿付准备金需要200万,除了长期业务,还有:",o:["一般业务","综合业务","专属自保保险人","法定业务"],a:2,e:"法例规定长期业务及专属自保保险人的偿付准备金均为200万元；一般业务、综合业务及法定业务不属此200万元类别，故答案为专属自保保险人。",src:1,tw:{ch:"保險業的規管架構",q:"根據法例，償付準備金需要200萬，除了長期業務，還有:",o:["一般業務","綜合業務","專屬自保保險人","法定業務"],e:"法例規定長期業務及專屬自保保險人的償付準備金均為200萬元；一般業務、綜合業務及法定業務不屬此200萬元類別，故答案為專屬自保保險人。"}},
{p:1,ch:"保险业的规管架构",q:"每一个持牌保险经纪公司必须备存足够的缴足款股本最少为:",o:["25,000港元","100,000港元","500,000港元","2,000,000港元"],a:2,e:"《保险业条例》规定每一持牌保险经纪公司须备存至少500,000港元的缴足款股本，以保障其财政稳健，其余数额均不符合该要求。",src:1,tw:{ch:"保險業的規管架構",q:"每一個持牌保險經紀公司必須備存足夠的繳足款股本最少為：",o:["25,000港元","100,000港元","500,000港元","2,000,000港元"],e:"《保險業條例》規定每一持牌保險經紀公司須備存至少500,000港元的繳足款股本，以保障其財政穩健，其餘數額均不符合該要求。"}},
{p:1,ch:"保险业的规管架构",q:"独资经营、董事等就受规管活动负责的适当人选。对公司而言,是指行使公司大会投票权的X %。X%是指:",o:["5%","10%","15%","20%"],a:2,e:"就公司而言，「适当人选」适用于行使公司股东大会投票权15%的人士（即控权人/主要股东），故 X% 为15%。",src:1,tw:{ch:"保險業的規管架構",q:"獨資經營、董事等就受規管活動負責的適當人選。對公司而言，是指行使公司大會投票權的X %。X%是指:",o:["5%","10%","15%","20%"],e:"就公司而言，「適當人選」適用於行使公司股東大會投票權15%的人士（即控權人/主要股東），故 X% 為15%。"}},
{p:1,ch:"保险业的规管架构",q:"由2000年6月起,《保险业条例》准许保险业监管局在认为符合保单持有人或公众利益的情 况下,披露个别保险人和劳合社的财务和统计资料被称为:",o:["透明度","反洗黑钱","公开度","干预权力"],a:0,e:"2000年6月起《保险业条例》准许保监局在符合保单持有人或公众利益时披露个别保险人及劳合社的财务统计资料，这项安排称为「透明度」。",src:1,tw:{ch:"保險業的規管架構",q:"由2000年6月起，《保險業條例》准許保險業監管局在認為符合保單持有人或公眾利益的情 況下，披露個別保險人和勞合社的財務和統計資料被稱為：",o:["透明度","反洗黑錢","公開度","干預權力"],e:"2000年6月起《保險業條例》准許保監局在符合保單持有人或公眾利益時披露個別保險人及勞合社的財務統計資料，這項安排稱為「透明度」。"}},
{p:1,ch:"保险业的规管架构",q:"立法会通过一条监管保险业的法例,该条约为:",o:["2015年保险业(修订)条例","2015年保险公司(修订)条例","2015年保险业监督条例","2015年保险从业员条例"],a:1,e:"立法会通过的监管保险业法例为《2015年保险公司(修订)条例》，它改组监管架构并成立独立保监局；其余条例名称均不准确。",src:1,tw:{ch:"保險業的規管架構",q:"立法會通過一條監管保險業的法例，該條約為：",o:["2015年保險業(修訂)條例","2015年保險公司(修訂)條例","2015年保險業監督條例","2015年保險從業員條例"],e:"立法會通過的監管保險業法例為《2015年保險公司(修訂)條例》，它改組監管架構併成立獨立保監局；其餘條例名稱均不準確。"}},
{p:1,ch:"保险业的规管架构",q:"经营一般业务的保险人,必须就其从香港保险业务所产生的负债在香港维持资产,以下哪项 有关所需数额的计算方法是正确的? i) 所需数额为有关数额及净负债额80% ii) 所需数额为有关数额及毛负债额(即不扣除任何再保险部分)的80% iii) 以订明的两种汇算方法之一计算 iv) 以香港精算学会推荐的三个方法之一予以计算",o:["i, ii, iii","ii, iv","ii, iii, iv","i, iii"],a:3,e:"一般业务保险人须在香港维持资产，所需数额以两种订明汇算方法之一计算，其一为「有关数额加净负债额的80%」（净负债已扣除再保险），故 i、iii 正确；ii 用毛负债、iv 以精算学会三方法均为错误。",src:1,tw:{ch:"保險業的規管架構",q:"經營一般業務的保險人，必須就其從香港保險業務所產生的負債在香港維持資產，以下哪項 有關所需數額的計算方法是正確的？ i) 所需數額為有關數額及淨負債額80% ii) 所需數額為有關數額及毛負債額(即不扣除任何再保險部分)的80% iii) 以訂明的兩種匯算方法之一計算 iv) 以香港精算學會推薦的三個方法之一予以計算",o:["i, ii, iii","ii, iv","ii, iii, iv","i, iii"],e:"一般業務保險人須在香港維持資產，所需數額以兩種訂明彙算方法之一計算，其一為「有關數額加淨負債額的80%」（淨負債已扣除再保險），故 i、iii 正確；ii 用毛負債、iv 以精算學會三方法均為錯誤。"}},
{p:1,ch:"保险业的规管架构",q:"经营一般业务的保险人,必须就其从香港保险业务所产生的负债在香港维持资产,所需数额 以订明的两种汇算方法之一计算,其一所要求的数额不能少于以下两项的总和,包括有关数 额以及:",o:["净负债额 (即已经扣除免赔额)的 80%","净负债额 (即已经扣除再保险所保的那部分)的 80%","净负债额 (即已经扣除不保项目及有争议部分)的 80%","毛负债额 (即不扣除不保项目及有争议部分部分)的 80%"],a:1,e:"所需数额不能少于「有关数额」加净负债额的80%，而净负债额是指已扣除再保险所承保部分后的负债，故答案为该项，而非毛负债额或其他扣除方式。",src:1,tw:{ch:"保險業的規管架構",q:"經營一般業務的保險人，必須就其從香港保險業務所產生的負債在香港維持資產，所需數額 以訂明的兩種匯算方法之一計算，其一所要求的數額不能少於以下兩項的總和，包括有關數 額以及：",o:["淨負債額 (即已經扣除免賠額)的 80%","淨負債額 (即已經扣除再保險所保的那部分)的 80%","淨負債額 (即已經扣除不保項目及有爭議部分)的 80%","毛負債額 (即不扣除不保項目及有爭議部分部分)的 80%"],e:"所需數額不能少於「有關數額」加淨負債額的80%，而淨負債額是指已扣除再保險所承保部分後的負債，故答案為該項，而非毛負債額或其他扣除方式。"}},
{p:1,ch:"保险业的规管架构",q:"经营一般业务的保险人,必须持有至少相当于「有关数额」的偿付准备金,有关数额有两个 准则计算,一是未决申索,另一个准则是?",o:["已赔金额","保费收入","未赚保费","已赚保费"],a:1,e:"「有关数额」按两个准则取较高者计算：一为未决申索（赔偿基准），另一为保费收入（保费基准），故答案为「保费收入」。",src:1,tw:{ch:"保險業的規管架構",q:"經營一般業務的保險人，必須持有至少相當於「有關數額」的償付準備金，有關數額有兩個 準則計算，一是未決申索，另一個準則是？",o:["已賠金額","保費收入","未賺保費","已賺保費"],e:"「有關數額」按兩個準則取較高者計算：一為未決申索（賠償基準），另一為保費收入（保費基準），故答案為「保費收入」。"}},
{p:1,ch:"保险业的规管架构",q:"经营一般及长期业务的实缴股本要求为:",o:["200万","1000万","1200 万","2000万"],a:3,e:"经营一般及长期业务的获授权保险人，其实缴股本要求为2,000万元，其余数额均不符合法例规定。",src:1,tw:{ch:"保險業的規管架構",q:"經營一般及長期業務的實繳股本要求為:",o:["200萬","1000萬","1200 萬","2000萬"],e:"經營一般及長期業務的獲授權保險人，其實繳股本要求為2,000萬元，其餘數額均不符合法例規定。"}},
{p:1,ch:"保险业的规管架构",q:"规则3,任何人最多可获4名获授权保险人委任为“持牌人士” —持牌保险代理或持牌个人代理—进行受规管活动,其中获授权经营_________________的保险 人不得超过2名 。",o:["一般保险","长期业务","一般及长期保险","法定保险"],a:1,e:"规则3规定任何人最多可被4名获授权保险人委任，其中获授权经营长期业务的保险人不得超过2名，故填「长期业务」。",src:1,tw:{ch:"保險業的規管架構",q:"規則3,任何人最多可獲4名獲授權保險人委任為“持牌人士” —持牌保險代理或持牌個人代理—進行受規管活動,其中獲授權經營_________________的保險 人不得超過2名 。",o:["一般保險","長期業務","一般及長期保險","法定保險"],e:"規則3規定任何人最多可被4名獲授權保險人委任，其中獲授權經營長期業務的保險人不得超過2名，故填「長期業務」。"}},
{p:1,ch:"保险业的规管架构",q:"规则3,任何人最多可获4名获授权保险人委任为“持牌人士” —持牌保险代理或持牌个人代理—进行受规管活动,其中获授权经营长期业务的保险人不得 超过______名 。",o:["1","2","4","5"],a:1,e:"规则3规定获授权经营长期业务的保险人不得超过2名，其余数字均不符规定。",src:1,tw:{ch:"保險業的規管架構",q:"規則3,任何人最多可獲4名獲授權保險人委任為“持牌人士” —持牌保險代理或持牌個人代理—進行受規管活動,其中獲授權經營長期業務的保險人不得 超過______名 。",o:["1","2","4","5"],e:"規則3規定獲授權經營長期業務的保險人不得超過2名，其餘數字均不符規定。"}},
{p:1,ch:"保险业的规管架构",q:"豁免部份保险中介人资格考试试卷是基于以下哪些条件?",o:["指引23附件一所列明的某些保险、精算和专业资格","在紧接2000年1月1日之前已经在香港从事保险中介业务的人士, 并持有由香港保险业联会发出的一般保险业务研习证书","在2000年1月1日之前的六年内,在香港的保险业务中有五年经验","以上各项"],a:3,e:"豁免部分考试基于指引23附件一所列专业资格、2000年前已从业且持有一般保险研习证书，或六年内具五年经验等条件，故「以上各项」均属豁免依据。",src:1,tw:{ch:"保險業的規管架構",q:"豁免部份保險中介人資格考試試卷是基於以下哪些條件?",o:["指引23附件一所列明的某些保險、精算和專業資格","在緊接2000年1月1日之前已經在香港從事保險中介業務的人士， 並持有由香港保險業聯會發出的一般保險業務研習證書","在2000年1月1日之前的六年內，在香港的保險業務中有五年經驗","以上各項"],e:"豁免部分考試基於指引23附件一所列專業資格、2000年前已從業且持有一般保險研習證書，或六年內具五年經驗等條件，故「以上各項」均屬豁免依據。"}},
{p:1,ch:"保险业的规管架构",q:"适当人选准则适用于:",o:["保险人董事","财务经理","核保员","以上各项皆正确"],a:0,e:"「适当人选」准则适用于获授权保险人的董事（及控权人等），因为他们的操守与能力直接影响保险人的管理；财务经理、核保员并非该准则的直接对象。",src:1,tw:{ch:"保險業的規管架構",q:"適當人選準則適用於:",o:["保險人董事","財務經理","核保員","以上各項皆正確"],e:"「適當人選」準則適用於獲授權保險人的董事（及控權人等），因為他們的操守與能力直接影響保險人的管理；財務經理、核保員並非該準則的直接對象。"}},
{p:1,ch:"保险业的规管架构",q:"通常情况下,保险人负责确保它的保险代理人遵守所有适用的法律。保险人应该特别留意下 列哪些事项?",o:["投诉、足够支援及杂项","登记、投诉及足够支援","投诉、利润及杂项","登记、足够支援及杂项"],a:0,e:"保险人须特别留意投诉处理、给予代理人足够支援及杂项事务，以履行其确保代理人守法的责任，故答案为「投诉、足够支援及杂项」；「利润」「登记」在此并非焦点。",src:1,tw:{ch:"保險業的規管架構",q:"通常情況下，保險人負責確保它的保險代理人遵守所有適用的法律。保險人應該特別留意下 列哪些事項?",o:["投訴、足夠支援及雜項","登記、投訴及足夠支援","投訴、利潤及雜項","登記、足夠支援及雜項"],e:"保險人須特別留意投訴處理、給予代理人足夠支援及雜項事務，以履行其確保代理人守法的責任，故答案為「投訴、足夠支援及雜項」；「利潤」「登記」在此並非焦點。"}},
{p:1,ch:"保险业的规管架构",q:"针对持牌保险经纪公司妥善处理簿册及帐目,以下哪三项是适用的? i 备存资料可以交代收取或持有的客户款项 ii 备存资料必须从电脑化作储存 iii 备存资料足以解释各项交易 iv 备存资料能够方便及适当地进行审计",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],a:1,e:"持牌保险经纪公司须妥善处理簿册及帐目，使其足以交代客户款项、解释各项交易并方便适当审计；「必须电脑化储存」并非三项要求之一，故答案为 i、iii、iv。",src:1,tw:{ch:"保險業的規管架構",q:"針對持牌保險經紀公司妥善處理簿冊及帳目，以下哪三項是適用的？ i 備存資料可以交代收取或持有的客戶款項 ii 備存資料必須從電腦化作儲存 iii 備存資料足以解釋各項交易 iv 備存資料能夠方便及適當地進行審計",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],e:"持牌保險經紀公司須妥善處理簿冊及帳目，使其足以交代客户款項、解釋各項交易並方便適當審計；「必須電腦化儲存」並非三項要求之一，故答案為 i、iii、iv。"}},
{p:1,ch:"保险业的规管架构",q:"除了豁免外, 再进行___________时必须获得保险业监管局发出的牌照。",o:["物质活动","金融服务","受规管活动","专业活动"],a:2,e:"除获豁免外，进行「受规管活动」必须取得保监局发出的牌照，这是《保险业条例》的核心要求；物质活动、金融服务、专业活动均不准确。",src:1,tw:{ch:"保險業的規管架構",q:"除了豁免外, 再進行___________時必須獲得保險業監管局發出的牌照。",o:["物質活動","金融服務","受規管活動","專業活動"],e:"除獲豁免外，進行「受規管活動」必須取得保監局發出的牌照，這是《保險業條例》的核心要求；物質活動、金融服務、專業活動均不準確。"}},
{p:1,ch:"职业道德及其他有关问题",q:"《个人资料 (私隠) 条例》所列明资料保障原则,包括下列哪项或哪些项目:",o:["公平的个人资料政策","合法的个人资料收集","资料所属人可接触及更正他们的个人资料","上述所有各项"],a:3,e:"《个人资料（私隐）条例》的保障资料原则涵盖公平合法的收集、资料属主可查阅及更正等，题干所列各项均属其内容，故选「上述所有各项」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"《個人資料 (私隠) 條例》所列明資料保障原則，包括下列哪項或哪些項目：",o:["公平的個人資料政策","合法的個人資料收集","資料所屬人可接觸及更正他們的個人資料","上述所有各項"],e:"《個人資料（私隱）條例》的保障資料原則涵蓋公平合法的收集、資料屬主可查閲及更正等，題幹所列各項均屬其內容，故選「上述所有各項」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"《个人资料(私隐)条例》,保护资料第一原则:",o:["收集个人资料的目的及方式","个人资料的准确性及保留期限","个人资料的保安","个人资料的使用"],a:0,e:"保护资料第1原则规管「收集个人资料的目的及方式」，要求以合法公平方式收集，故答案为该项；准确性、保安及使用分别为其他原则。",src:1,tw:{ch:"職業道德及其他有關問題",q:"《個人資料(私隱)條例》，保護資料第一原則:",o:["收集個人資料的目的及方式","個人資料的準確性及保留期限","個人資料的保安","個人資料的使用"],e:"保護資料第1原則規管「收集個人資料的目的及方式」，要求以合法公平方式收集，故答案為該項；準確性、保安及使用分別為其他原則。"}},
{p:1,ch:"职业道德及其他有关问题",q:"《个人资料(私隐)条例》所涉及的范围: i 不论是自动化或人手作业的资料 ii 不论是公营部门或是私营部门 iii 只包括自动化的资料 iv 只包括私营部门,不包括公营部门",o:["i, ii","iii, iv","ii, iii","i, iv"],a:0,e:"条例同时适用于自动化及人手作业的资料，并涵盖公营及私营部门；「只包括自动化资料」「只包括私营部门」说法均错误，故答案为 i、ii。",src:1,tw:{ch:"職業道德及其他有關問題",q:"《個人資料(私隱)條例》所涉及的範圍： i 不論是自動化或人手作業的資料 ii 不論是公營部門或是私營部門 iii 只包括自動化的資料 iv 只包括私營部門，不包括公營部門",o:["i, ii","iii, iv","ii, iii","i, iv"],e:"條例同時適用於自動化及人手作業的資料，並涵蓋公營及私營部門；「只包括自動化資料」「只包括私營部門」說法均錯誤，故答案為 i、ii。"}},
{p:1,ch:"职业道德及其他有关问题",q:"《贩毒(追讨得益)条例》及《有组织及严重罪行条例》及有关法例当中一个保险人必须关心的共 同应用,该应用为:",o:["洗钱活动","违反保险中的最高诚信","在香港夜总会使用毒品","对保险索偿职员使用暴力"],a:0,e:"《贩毒（追讨得益）条例》及《有组织及严重罪行条例》对保险人共同的关注点在于防范洗钱活动，故答案为「洗钱活动」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"《販毒(追討得益)條例》及《有組織及嚴重罪行條例》及有關法例當中一個保險人必須關心的共 同應用，該應用為：",o:["洗錢活動","違反保險中的最高誠信","在香港夜總會使用毒品","對保險索償職員使用暴力"],e:"《販毒（追討得益）條例》及《有組織及嚴重罪行條例》對保險人共同的關注點在於防範洗錢活動，故答案為「洗錢活動」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"「资料使用者必须采取所有切实可行的步骤, 以公开他们的个人资料相关政策和做法、所持个人资料的种类及使用这些个人资料的主要目的 。」这是属于哪一个保障资料原则?",o:["第3 原则 — 个人资料的使用","第4 原则 — 个人资料的保安","第5 原则 — 资讯须在一般情况下可提供","第6 原则 — 查阅个人资料"],a:2,e:"要求资料使用者采取切实步骤公开其政策、所持资料种类及用途，属于保障资料第5原则——「资讯须在一般情况下可提供」，故答案为该项。",src:1,tw:{ch:"職業道德及其他有關問題",q:"「資料使用者必須採取所有切實可行的步驟， 以公開他們的個人資料相關政策和做法、所持個人資料的種類及使用這些個人資料的主要目的 。」這是屬於哪一個保障資料原則？",o:["第3 原則 — 個人資料的使用","第4 原則 — 個人資料的保安","第5 原則 — 資訊須在一般情況下可提供","第6 原則 — 查閱個人資料"],e:"要求資料使用者採取切實步驟公開其政策、所持資料種類及用途，屬於保障資料第5原則——「資訊須在一般情況下可提供」，故答案為該項。"}},
{p:1,ch:"职业道德及其他有关问题",q:"下列哪项有关保险中介人对保单持有人的责任是正确的? i 认识到违反一项条例要求可能牵涉刑事程序 ii 尊重法律的精神及良好的保险惯例 iii 不得从身体上、精神上或教育上有缺陷的人获得好处 iv 只担任咨询人",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:3,e:"中介人对保单持有人须意识违规可能涉及刑事程序、尊重法律精神与优良惯例、不从有缺陷者取得好处，并且只担任咨询人而非替客户作决定，四项均正确。",src:1,tw:{ch:"職業道德及其他有關問題",q:"下列哪項有關保險中介人對保單持有人的責任是正確的？ i 認識到違反一項條例要求可能牽涉刑事程序 ii 尊重法律的精神及良好的保險慣例 iii 不得從身體上、精神上或教育上有缺陷的人獲得好處 iv 只擔任諮詢人",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"中介人對保單持有人須意識違規可能涉及刑事程序、尊重法律精神與優良慣例、不從有缺陷者取得好處，並且只擔任諮詢人而非替客户作決定，四項均正確。"}},
{p:1,ch:"职业道德及其他有关问题",q:"什么是贪污?",o:["个人挪用属于他人的财产","贪污是指个人不惜损害他人的利益,为谋取私利而滥用职权","个人在不获授权的情况下谋取私利,从而引致他人的利益受损","个人在谋取私利,从而引致他人的利益受损"],a:1,e:"贪污指为了谋取私利而滥用职权，不惜损害他人利益，故答案为该项；单纯挪用财产或不获授权谋利等表述均不够完整准确。",src:1,tw:{ch:"職業道德及其他有關問題",q:"什麼是貪污?",o:["個人挪用屬於他人的財產","貪污是指個人不惜損害他人的利益，為謀取私利而濫用職權","個人在不獲授權的情況下謀取私利，從而引致他人的利益受損","個人在謀取私利，從而引致他人的利益受損"],e:"貪污指為了謀取私利而濫用職權，不惜損害他人利益，故答案為該項；單純挪用財產或不獲授權謀利等表述均不夠完整準確。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪一条法例是用来保障个人资料的?",o:["《个人资料(私人)条例》","《个人资料(私隐)条例》","《私人资料(私隐)条例》","《私人资料(个人)条例》"],a:1,e:"保障个人资料的法例是《个人资料（私隐）条例》，只有该项名称正确，其余选项用字有误。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪一條法例是用來保障個人資料的？",o:["《個人資料(私人)條例》","《個人資料(私隱)條例》","《私人資料(私隱)條例》","《私人資料(個人)條例》"],e:"保障個人資料的法例是《個人資料（私隱）條例》，只有該項名稱正確，其餘選項用字有誤。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪三项是保险代理及保险经纪的共同责任? i 公平及合理的行为 ii 不得从客户身上获取不公平的好处 iii 熟识法例管辖或要求,清楚违反条例可能涉及的程序/后果 iv 由保险中介人替客户作投保决定",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"代理与经纪共同责任包括公平合理行事、不获取不公平好处及熟识法例要求；「替客户作投保决定」违反中介人只作咨询的角色，故不选 iv，答案为 i、ii、iii。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪三項是保險代理及保險經紀的共同責任？ i 公平及合理的行為 ii 不得從客戶身上獲取不公平的好處 iii 熟識法例管轄或要求，清楚違反條例可能涉及的程序/後果 iv 由保險中介人替客戶作投保決定",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"代理與經紀共同責任包括公平合理行事、不獲取不公平好處及熟識法例要求；「替客户作投保決定」違反中介人只作諮詢的角色，故不選 iv，答案為 i、ii、iii。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪三项有关保险经纪的陈述是正确的? i 他们被视为保险业务上的专家 ii 在通常情况下,有关经纪是保险人的代理人 iii 他们必须具备专业赔偿保险 iv 保险经纪必须至少符合有关的「最低限度规定」",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"保险经纪被视为保险业专家、须投购专业赔偿保险并符合最低限度规定；但经纪是保单持有人（被保险人）的代理人而非保险人代理人，故 ii 错，答案为 i、iii、iv。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪三項有關保險經紀的陳述是正確的？ i 他們被視為保險業務上的專家 ii 在通常情況下，有關經紀是保險人的代理人 iii 他們必須具備專業賠償保險 iv 保險經紀必須至少符合有關的「最低限度規定」",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"保險經紀被視為保險業專家、須投購專業賠償保險並符合最低限度規定；但經紀是保單持有人（被保險人）的代理人而非保險人代理人，故 ii 錯，答案為 i、iii、iv。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪三项较为被保险人视为「公平歧视」: i 为女性提供较低的年金收益 ii 向男性收取较高的人寿保险保费 iii 向女性收取较高的汽车保险保费 iv在提供人身意外保险时向残疾人仕收取较高保费",o:["i,ii,iii","i, ii, iv","i,iii,iv","ii,iii,iv"],a:1,e:"以精算数据为依据的差异属「公平歧视」：女性年金收益较低、男性人寿保费较高、残疾人意外保费较高均可成立；向风险较低的女性收取较高汽车保费无合理依据，故 iii 错，答案为 i、ii、iv。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪三項較為被保險人視為「公平歧視」: i 為女性提供較低的年金收益 ii 向男性收取較高的人壽保險保費 iii 向女性收取較高的汽車保險保費 iv在提供人身意外保險時向殘疾人仕收取較高保費",o:["i,ii,iii","i, ii, iv","i,iii,iv","ii,iii,iv"],e:"以精算數據為依據的差異屬「公平歧視」：女性年金收益較低、男性人壽保費較高、殘疾人意外保費較高均可成立；向風險較低的女性收取較高汽車保費無合理依據，故 iii 錯，答案為 i、ii、iv。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项不属于平等机会委员会的事宜:",o:["婚姻状况","残疾","工作岗位","性别"],a:2,e:"平等机会委员会处理性别、残疾、家庭岗位、婚姻状况及种族等歧视事宜，「工作岗位」不属其范畴，故答案为该项。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項不屬於平等機會委員會的事宜：",o:["婚姻狀況","殘疾","工作崗位","性別"],e:"平等機會委員會處理性別、殘疾、家庭崗位、婚姻狀況及種族等歧視事宜，「工作崗位」不屬其範疇，故答案為該項。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项不是保险代理人的正确描述?",o:["对比保险经纪,保险代理人承担失实陈述的法律责任较低","必须以书面获得委任","委托人是保险人","需要购买专业责任保险"],a:3,e:"保险代理人须以书面获委任、委托人是保险人，且其失实陈述法律责任较轻；「需要购买专业责任保险」是经纪而非代理人的要求，故该项不是代理人的正确描述。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項不是保險代理人的正確描述？",o:["對比保險經紀，保險代理人承擔失實陳述的法律責任較低","必須以書面獲得委任","委託人是保險人","需要購買專業責任保險"],e:"保險代理人須以書面獲委任、委託人是保險人，且其失實陳述法律責任較輕；「需要購買專業責任保險」是經紀而非代理人的要求，故該項不是代理人的正確描述。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项关于《个人资料(私隐)条例》的约束是正确的? i 人手操作资料 ii 自动化操作资料 iii 公营部门而已 iv 只适用于香港居民及香港注册商号的人",o:["i, ii","iii, iv","ii, iii, iv","i, ii, iii, iv"],a:0,e:"条例同时约束人手操作与自动化操作的个人资料；「只适用于公营部门」及「只适用于香港居民与商号」均属错误，故答案为 i、ii。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項關於《個人資料(私隱)條例》的約束是正確的？ i 人手操作資料 ii 自動化操作資料 iii 公營部門而已 iv 只適用於香港居民及香港註冊商號的人",o:["i, ii","iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"條例同時約束人手操作與自動化操作的個人資料；「只適用於公營部門」及「只適用於香港居民與商號」均屬錯誤，故答案為 i、ii。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项对《个人资料(私隐)条例》范围的陈述是不正确的?",o:["它既涉及自动化资料及人工作业资料","它既涉及公营机构及私营机构","它有法定组织监管整个法律程序","它只涉及私营机构但不包括公营机构"],a:3,e:"条例既涉及自动化及人手资料，也涵盖公私营机构并有法定组织（私隐专员）监管；「只涉及私营、不包括公营机构」的说法错误，故选该项。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項對《個人資料(私隱)條例》範圍的陳述是不正確的?",o:["它既涉及自動化資料及人工作業資料","它既涉及公營機構及私營機構","它有法定組織監管整個法律程序","它只涉及私營機構但不包括公營機構"],e:"條例既涉及自動化及人手資料，也涵蓋公私營機構並有法定組織（私隱專員）監管；「只涉及私營、不包括公營機構」的說法錯誤，故選該項。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项或哪些有关获授权保险经纪的错误及疏忽的描述是正确的?",o:["经纪可能被裁定专业疏忽","经纪仅仅因为是获受权的保险经纪, 所以必须对错误疏忽负上法律责任","经纪的委托人,即有关的被保险人,可能有权向保险经纪提出诉讼","只有A及C"],a:3,e:"获授权经纪可能被裁定专业疏忽，且身为被保险人的委托人可被诉讼；但经纪不会「仅仅因为获授权」就必须对错误疏忽负法律责任，故 B 错，答案为 A 及 C。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項或哪些有關獲授權保險經紀的錯誤及疏忽的描述是正確的？",o:["經紀可能被裁定專業疏忽","經紀僅僅因為是獲受權的保險經紀， 所以必須對錯誤疏忽負上法律責任","經紀的委託人，即有關的被保險人，可能有權向保險經紀提出訴訟","只有A及C"],e:"獲授權經紀可能被裁定專業疏忽，且身為被保險人的委託人可被訴訟；但經紀不會「僅僅因為獲授權」就必須對錯誤疏忽負法律責任，故 B 錯，答案為 A 及 C。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项是正确的资料保障原则?",o:["私隐权是绝对的,所以在任何情况下都不能获得豁免","个人资料只能按照收集时的目的来使用","个人资料的保留时间可过于所需的","资料所属人没有权利更正他们的个人资料"],a:1,e:"正确原则是个人资料只能按收集时的目的使用；私隐权并非绝对、资料不能保留过久，且资料属主有权更正，故其余选项均错。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項是正確的資料保障原則？",o:["私隱權是絕對的，所以在任何情況下都不能獲得豁免","個人資料只能按照收集時的目的來使用","個人資料的保留時間可過於所需的","資料所屬人沒有權利更正他們的個人資料"],e:"正確原則是個人資料只能按收集時的目的使用；私隱權並非絕對、資料不能保留過久，且資料屬主有權更正，故其餘選項均錯。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项有关保险代理人的描述是不正确的?",o:["与保险经纪不同,他们须就不当履行责任而负上的机会是小的","他们须在执行业务时的疏忽而承担法律责任","他们在执行业务时必须合理谨慎","他们必须根据本身合约而购买专业责任保险"],a:3,e:"代理人须合理谨慎、就疏忽承担法律责任，但与经纪不同，其不当履行责任的机会较小；「必须根据本身合约购买专业责任保险」是经纪的要求，故该描述不正确。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項有關保險代理人的描述是不正確的？",o:["與保險經紀不同，他們須就不當履行責任而負上的機會是小的","他們須在執行業務時的疏忽而承擔法律責任","他們在執行業務時必須合理謹慎","他們必須根據本身合約而購買專業責任保險"],e:"代理人須合理謹慎、就疏忽承擔法律責任，但與經紀不同，其不當履行責任的機會較小；「必須根據本身合約購買專業責任保險」是經紀的要求，故該描述不正確。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项有关保险经纪的陈述是正确的?",o:["被视为保险业的专家","独立于任何一位保险人","保单持有人期望从保险经纪那里得到不偏不倚的建议","以上所有各项"],a:3,e:"经纪被视为保险业的专家、独立于任何单一保险人，客户期望从其获得不偏不倚的建议，三项均正确，故选「以上所有各项」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項有關保險經紀的陳述是正確的？",o:["被視為保險業的專家","獨立於任何一位保險人","保單持有人期望從保險經紀那裏得到不偏不倚的建議","以上所有各項"],e:"經紀被視為保險業的專家、獨立於任何單一保險人，客户期望從其獲得不偏不倚的建議，三項均正確，故選「以上所有各項」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下哪项构成刑事中的贪污?",o:["某人为谋取私利,从而引致社会利益受到损害","某人为谋取私利,滥用职权,从而引致社会利益受到损害","某人在不获授权的情况下谋取私利,从而引致社会利益受到损害","以上没有一项正确"],a:1,e:"构成刑事贪污须同时具备谋取私利与滥用职权两要素，从而损害社会利益，故答案为该项；仅谋取私利而无滥用职权不构成贪污。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下哪項構成刑事中的貪污?",o:["某人為謀取私利，從而引致社會利益受到損害","某人為謀取私利，濫用職權，從而引致社會利益受到損害","某人在不獲授權的情況下謀取私利，從而引致社會利益受到損害","以上沒有一項正確"],e:"構成刑事貪污須同時具備謀取私利與濫用職權兩要素，從而損害社會利益，故答案為該項；僅謀取私利而無濫用職權不構成貪污。"}},
{p:1,ch:"职业道德及其他有关问题",q:"保护资料原则第1原则是指:",o:["保留限期","准确、最新","资料当时人有权更改","收集目的"],a:3,e:"保障资料第1原则指「收集个人资料的目的及方式」，对应选项「收集目的」，故答案为该项；保留限期、准确等属其他原则。",src:1,tw:{ch:"職業道德及其他有關問題",q:"保護資料原則第1原則是指：",o:["保留限期","準確、最新","資料當時人有權更改","收集目的"],e:"保障資料第1原則指「收集個人資料的目的及方式」，對應選項「收集目的」，故答案為該項；保留限期、準確等屬其他原則。"}},
{p:1,ch:"职业道德及其他有关问题",q:"保险中介人对保单持有人的责任不包括:",o:["没有诈骗成分","不得获取不公平的好处","担任客户的决策者","所有行动必须合法"],a:2,e:"中介人对保单持有人的责任包括不作诈骗、不获取不公平好处、行动合法等，但不应担任客户的决策者（只作咨询），故「担任客户的决策者」不属于其责任。",src:1,tw:{ch:"職業道德及其他有關問題",q:"保險中介人對保單持有人的責任不包括：",o:["沒有詐騙成分","不得獲取不公平的好處","擔任客戶的決策者","所有行動必須合法"],e:"中介人對保單持有人的責任包括不作詐騙、不獲取不公平好處、行動合法等，但不應擔任客户的決策者（只作諮詢），故「擔任客户的決策者」不屬於其責任。"}},
{p:1,ch:"职业道德及其他有关问题",q:"保险代理人及保险经纪对保单持有人的共同责任为:",o:["所有行为必须合法","行为必须合理及公平","不应向客户加诸不必要的影响","以上各项皆是"],a:3,e:"代理与经纪对保单持有人的共同责任包括所有行为合法、行为合理公平，以及不向客户加诸不必要的影响，三项均正确，故选「以上各项皆是」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"保險代理人及保險經紀對保單持有人的共同責任為：",o:["所有行為必須合法","行為必須合理及公平","不應向客戶加諸不必要的影響","以上各項皆是"],e:"代理與經紀對保單持有人的共同責任包括所有行為合法、行為合理公平，以及不向客户加諸不必要的影響，三項均正確，故選「以上各項皆是」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"在以下情况,基于受保人的性别而有别于待遇,法例是容许的:",o:["有关待遇是藉参照可合理依据的来源所得的精算数据而给予的","有关待遇是藉参照可合理依据的来源所得的精算数据或其他数据 而给予的,及以该等数据及任何其他有关因素而言,有关待遇 属于合理","有关待遇已获保险业监管局豁免","有关待遇已获平等机会委员会豁免"],a:1,e:"法例容许基于性别而区别待遇，条件是待遇须参照可合理依据来源所得的精算数据或其他数据给予，并连同其他因素判断为合理，故答案为该项（须兼备数据依据与合理性）。",src:1,tw:{ch:"職業道德及其他有關問題",q:"在以下情況，基於受保人的性別而有別於待遇，法例是容許的:",o:["有關待遇是藉參照可合理依據的來源所得的精算數據而給予的","有關待遇是藉參照可合理依據的來源所得的精算數據或其他數據 而給予的，及以該等數據及任何其他有關因素而言，有關待遇 屬於合理","有關待遇已獲保險業監管局豁免","有關待遇已獲平等機會委員會豁免"],e:"法例容許基於性別而區別待遇，條件是待遇須參照可合理依據來源所得的精算數據或其他數據給予，並連同其他因素判斷為合理，故答案為該項（須兼備數據依據與合理性）。"}},
{p:1,ch:"职业道德及其他有关问题",q:"在保险实务上,保险人可根据以下哪项条件而对不同性别之投保人收取不同保费?",o:["根据市场消息及标准","根据合理客观的精算数据或其他数据,以及该等数据及任何其他有关因素","根据合理客观的精算数据或其他数据","以上各项皆是"],a:1,e:"保险人可按不同性别收取不同保费，但须依据合理客观的精算数据或其他数据，并结合其他有关因素，故答案为该项；仅凭市场消息或单一数据并不足够。",src:1,tw:{ch:"職業道德及其他有關問題",q:"在保險實務上，保險人可根據以下哪項條件而對不同性別之投保人收取不同保費？",o:["根據市場消息及標準","根據合理客觀的精算數據或其他數據，以及該等數據及任何其他有關因素","根據合理客觀的精算數據或其他數據","以上各項皆是"],e:"保險人可按不同性別收取不同保費，但須依據合理客觀的精算數據或其他數據，並結合其他有關因素，故答案為該項；僅憑市場消息或單一數據並不足夠。"}},
{p:1,ch:"职业道德及其他有关问题",q:"在各种防止诈骗的实际方法中,保险业职员值得考虑的其中最重要一项为:",o:["保持警觉,它可以在任何情况下出现","对任何索偿人士投以极大怀疑","了解到它只会于大额索偿时出现","对每一极小的细节均要求严格的证明及确认"],a:0,e:"防诈骗最重要是保持警觉，因为诈骗可在任何情况下出现；投以极大怀疑、只警惕大额索偿或事事苛求证明均非最有效做法，故答案为保持警觉。",src:1,tw:{ch:"職業道德及其他有關問題",q:"在各種防止詐騙的實際方法中，保險業職員值得考慮的其中最重要一項為：",o:["保持警覺，它可以在任何情況下出現","對任何索償人士投以極大懷疑","瞭解到它只會於大額索償時出現","對每一極小的細節均要求嚴格的證明及確認"],e:"防詐騙最重要是保持警覺，因為詐騙可在任何情況下出現；投以極大懷疑、只警惕大額索償或事事苛求證明均非最有效做法，故答案為保持警覺。"}},
{p:1,ch:"职业道德及其他有关问题",q:"在香港,下列哪项不属于平等机会的事宜?",o:["性别","宗教","家庭岗位","残疾"],a:1,e:"香港平等机会事宜包括性别、残疾、家庭岗位及种族等，「宗教」不属平等机会委员会处理的范围，故答案为该项。",src:1,tw:{ch:"職業道德及其他有關問題",q:"在香港，下列哪項不屬於平等機會的事宜？",o:["性別","宗教","家庭崗位","殘疾"],e:"香港平等機會事宜包括性別、殘疾、家庭崗位及種族等，「宗教」不屬平等機會委員會處理的範圍，故答案為該項。"}},
{p:1,ch:"职业道德及其他有关问题",q:"填写投保书时,保险中介人的责任是:",o:["不影响客户","清楚说明内容或声明客户负上责任","声明诈骗或偏差的后果","以上各项皆是"],a:3,e:"填写投保书时，中介人须不影响客户、清楚说明内容或声明客户自负责任，并说明诈骗或偏差的后果，三项均正确，故选「以上各项皆是」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"填寫投保書時，保險中介人的責任是：",o:["不影響客戶","清楚說明內容或聲明客戶負上責任","聲明詐騙或偏差的後果","以上各項皆是"],e:"填寫投保書時，中介人須不影響客户、清楚說明內容或聲明客户自負責任，並說明詐騙或偏差的後果，三項均正確，故選「以上各項皆是」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"如果中介人是保险经纪,他的一般职责是:",o:["将保险人的利益放在首要地位","必须独立于任何一位保单持有人","令保险公司得到不偏不倚的建议","令保单持有人得到不偏不倚的建议"],a:3,e:"保险经纪的一般职责是令保单持有人得到不偏不倚的建议，因为经纪以保单持有人（被保险人）的利益为先；令保险人得到建议或独立于保单持有人均错误。",src:1,tw:{ch:"職業道德及其他有關問題",q:"如果中介人是保險經紀，他的一般職責是：",o:["將保險人的利益放在首要地位","必須獨立於任何一位保單持有人","令保險公司得到不偏不倚的建議","令保單持有人得到不偏不倚的建議"],e:"保險經紀的一般職責是令保單持有人得到不偏不倚的建議，因為經紀以保單持有人（被保險人）的利益為先；令保險人得到建議或獨立於保單持有人均錯誤。"}},
{p:1,ch:"职业道德及其他有关问题",q:"如果保险代理人协助保单持有人进行诈骗,该保险代理人将被视为:",o:["保险人的代理人","投保人 / 被保人的从犯","保单持有人的合伙人","保险经纪"],a:1,e:"若代理人协助保单持有人诈骗，会被视为投保人/被保人的从犯，共同承担法律责任；代理人、合伙人、经纪等描述均不正确。",src:1,tw:{ch:"職業道德及其他有關問題",q:"如果保險代理人協助保單持有人進行詐騙，該保險代理人將被視為：",o:["保險人的代理人","投保人 / 被保人的從犯","保單持有人的合伙人","保險經紀"],e:"若代理人協助保單持有人詐騙，會被視為投保人/被保人的從犯，共同承擔法律責任；代理人、合夥人、經紀等描述均不正確。"}},
{p:1,ch:"职业道德及其他有关问题",q:"对保险业而言,以下哪项属于公平歧视(即合法)的情况:",o:["向女性收取较低的人寿保险保费","向男性付出年金款项比同一年龄的女性较多","向残疾人士的保单加设特定条款","以上各项皆是"],a:3,e:"基于寿命与风险的合理差异均属公平歧视：女性人寿保费较低、男性年金款项较多、给残疾人加设特定条款均可成立，故「以上各项皆是」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"對保險業而言，以下哪項屬於公平歧視(即合法)的情況：",o:["向女性收取較低的人壽保險保費","向男性付出年金款項比同一年齡的女性較多","向殘疾人士的保單加設特定條款","以上各項皆是"],e:"基於壽命與風險的合理差異均屬公平歧視：女性人壽保費較低、男性年金款項較多、給殘疾人加設特定條款均可成立，故「以上各項皆是」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"对保险代理人而言,以下哪项或哪些技术性地构成诈骗?",o:["建议客户不要透露某些重要事实","在诈骗索偿中,没有将明确的资料交给保险人","在安排保险过程中,故意隠瞒一些不良影响的资料","以上各项皆是"],a:3,e:"建议客户隐瞒重要事实、在诈骗索偿中不把明确资料交给保险人，以及故意隐瞒不良影响资料，三者技术上都构成诈骗，故答案为「以上各项皆是」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"對保險代理人而言，以下哪項或哪些技術性地構成詐騙?",o:["建議客戶不要透露某些重要事實","在詐騙索償中，沒有將明確的資料交給保險人","在安排保險過程中，故意隠瞞一些不良影響的資料","以上各項皆是"],e:"建議客户隱瞞重要事實、在詐騙索償中不把明確資料交給保險人，以及故意隱瞞不良影響資料，三者技術上都構成詐騙，故答案為「以上各項皆是」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"廉政公署24小时举报热线是:",o:["999","25 266 366","1823","266 366"],a:1,e:"廉政公署的24小时举报热线为2526 6366，即选项「25 266 366」，故答案为该项。",src:1,tw:{ch:"職業道德及其他有關問題",q:"廉政公署24小時舉報熱線是:",o:["999","25 266 366","1823","266 366"],e:"廉政公署的24小時舉報熱線為2526 6366，即選項「25 266 366」，故答案為該項。"}},
{p:1,ch:"职业道德及其他有关问题",q:"当保险代理挪用客人的保费可能会犯下什么罪?",o:["挪用保费罪","挪用资金罪","不诚实罪","盗窃罪"],a:3,e:"保险代理挪用客户保费会触犯盗窃罪，因为其未经授权将属于他人的款项据为己有；「挪用保费罪」「挪用资金罪」「不诚实罪」并非正确罪名。",src:1,tw:{ch:"職業道德及其他有關問題",q:"當保險代理挪用客人的保費可能會犯下什麼罪?",o:["挪用保費罪","挪用資金罪","不誠實罪","盜竊罪"],e:"保險代理挪用客户保費會觸犯盜竊罪，因為其未經授權將屬於他人的款項據為己有；「挪用保費罪」「挪用資金罪」「不誠實罪」並非正確罪名。"}},
{p:1,ch:"职业道德及其他有关问题",q:"有关保险事宜的诈骗:",o:["可循不同途径及索偿时产生","只出现在索偿时","不会出现于人寿保险","只出现于财产保险索偿过程中"],a:0,e:"保险诈骗可循不同途径（投保、核保、索偿等多环节）及在索偿时产生，而非只出现在索偿时或只限于财产保险，故答案为该项。",src:1,tw:{ch:"職業道德及其他有關問題",q:"有關保險事宜的詐騙：",o:["可循不同途徑及索償時產生","只出現在索償時","不會出現於人壽保險","只出現於財產保險索償過程中"],e:"保險詐騙可循不同途徑（投保、核保、索償等多環節）及在索償時產生，而非只出現在索償時或只限於財產保險，故答案為該項。"}},
{p:1,ch:"职业道德及其他有关问题",q:"有甚么实际步骤可以防止诈骗?",o:["对每位客户存有怀疑","尽量减少与保险人联络","保持警觉","以上各项皆是"],a:2,e:"防止诈骗的实际步骤是保持警觉，而非对每位客户存疑或尽量减少与保险人联络，故答案为「保持警觉」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"有甚麼實際步驟可以防止詐騙？",o:["對每位客戶存有懷疑","盡量減少與保險人聯絡","保持警覺","以上各項皆是"],e:"防止詐騙的實際步驟是保持警覺，而非對每位客户存疑或儘量減少與保險人聯絡，故答案為「保持警覺」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"根据《防止贿赂条例》, 以下哪项并非【利益】?",o:["款待","借贷","服务","职位"],a:0,e:"《防止贿赂条例》中的「利益」包括借贷、服务、职位等，而「款待」（如一般社交应酬）不属「利益」，故答案为款待。",src:1,tw:{ch:"職業道德及其他有關問題",q:"根據《防止賄賂條例》， 以下哪項並非【利益】?",o:["款待","借貸","服務","職位"],e:"《防止賄賂條例》中的「利益」包括借貸、服務、職位等，而「款待」（如一般社交應酬）不屬「利益」，故答案為款待。"}},
{p:1,ch:"职业道德及其他有关问题",q:"洗钱较可能出现于:",o:["人寿保险","汽车保险","公众责任保险","雇员补偿保险"],a:0,e:"人寿保险因可透过退保、保单贷款或保费预缴而退回资金，较易被用作洗钱，故洗钱较可能出现于人寿保险。",src:1,tw:{ch:"職業道德及其他有關問題",q:"洗錢較可能出現於：",o:["人壽保險","汽車保險","公眾責任保險","僱員補償保險"],e:"人壽保險因可透過退保、保單貸款或保費預繳而退回資金，較易被用作洗錢，故洗錢較可能出現於人壽保險。"}},
{p:1,ch:"职业道德及其他有关问题",q:"监察及执行《个人资料(私隐)条例》的专责人员为:",o:["保险业监管局","个人资料私人专员","私人资料个人专员","个人资料私隐专员"],a:3,e:"监察及执行《个人资料（私隐）条例》的专责人员是「个人资料私隐专员」，只有该项名称正确。",src:1,tw:{ch:"職業道德及其他有關問題",q:"監察及執行《個人資料(私隱)條例》的專責人員為：",o:["保險業監管局","個人資料私人專員","私人資料個人專員","個人資料私隱專員"],e:"監察及執行《個人資料（私隱）條例》的專責人員是「個人資料私隱專員」，只有該項名稱正確。"}},
{p:1,ch:"职业道德及其他有关问题",q:"视乎参与的性质而定, 于保险诈骗中的犯罪者不是以主犯的身份就是:",o:["常犯","惯犯","从犯","即犯"],a:2,e:"在保险诈骗中，视乎参与的性质，犯罪者不是以主犯身份就是以从犯身份参与，故答案为「从犯」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"視乎參與的性質而定， 於保險詐騙中的犯罪者不是以主犯的身份就是：",o:["常犯","慣犯","從犯","即犯"],e:"在保險詐騙中，視乎參與的性質，犯罪者不是以主犯身份就是以從犯身份參與，故答案為「從犯」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"资料使用者透过合约,对资料处理者拖加责任包括: i 资料使用者可以审核及视察资料处理者如何处理和储存个人资料 ii 适时交还、销毁或删除有关资料 iii 列明资料处理者所须采取的保安措施 iv 资料使用者必须是香港居民",o:["i, iii","ii, iii, iv","i, ii, iii","i, ii, iii, iv"],a:2,e:"资料使用者可透过合约要求资料处理者容许审核视察、适时退还删除资料并列明保安措施（i、ii、iii）；「资料使用者必须是香港居民」并非要求，故答案为 i、ii、iii。",src:1,tw:{ch:"職業道德及其他有關問題",q:"資料使用者透過合約，對資料處理者拖加責任包括: i 資料使用者可以審核及視察資料處理者如何處理和儲存個人資料 ii 適時交還、銷毀或刪除有關資料 iii 列明資料處理者所須採取的保安措施 iv 資料使用者必須是香港居民",o:["i, iii","ii, iii, iv","i, ii, iii","i, ii, iii, iv"],e:"資料使用者可透過合約要求資料處理者容許審核視察、適時退還刪除資料並列明保安措施（i、ii、iii）；「資料使用者必須是香港居民」並非要求，故答案為 i、ii、iii。"}},
{p:3,ch:"人寿保险简介",q:"「保险公司承诺当被保险人死亡时支付保险金的保险。」在人寿保险定义,以下哪项或哪些 是正确描述?",o:["是有限制的,但在可能的范围下是可行的","以研究保险历史而言,是合理的出发点","未足以描述现代的人寿保险","以上各项都是正确"],a:3,e:"「保险公司承诺当被保险人死亡时支付保险金」这一定义虽有局限，但作为研究保险历史的合理出发点仍属可行，惟不足以描述现代人寿保险，故「以上各项都是正确」。",src:1,tw:{ch:"人壽保險簡介",q:"「保險公司承諾當被保險人死亡時支付保險金的保險。」在人壽保險定義，以下哪項或哪些 是正確描述？",o:["是有限制的，但在可能的範圍下是可行的","以研究保險歷史而言，是合理的出發點","未足以描述現代的人壽保險","以上各項都是正確"],e:"「保險公司承諾當被保險人死亡時支付保險金」這一定義雖有侷限，但作為研究保險歷史的合理出發點仍屬可行，惟不足以描述現代人壽保險，故「以上各項都是正確」。"}},
{p:3,ch:"人寿保险简介",q:"「重要事实」的定义是:",o:["有关实际物件(财产)的事实","保险人毋须知道的事实","会影响一名审慎的保险人在订定保费或决定承担条件的事实","可能影响一名审慎的保险人在订定保费或决定承担条件的事实"],a:2,e:"重要事实指「会影响一名审慎的保险人在订定保费或决定承担条件的事实」，准确措辞须为「会」而非「可能」，故答案为该项；「可能影响」削弱了标准，其余选项不符定义。",src:1,tw:{ch:"人壽保險簡介",q:"「重要事實」的定義是：",o:["有關實際物件(財產)的事實","保險人毋須知道的事實","會影響一名審慎的保險人在訂定保費或決定承擔條件的事實","可能影響一名審慎的保險人在訂定保費或決定承擔條件的事實"],e:"重要事實指「會影響一名審慎的保險人在訂定保費或決定承擔條件的事實」，準確措辭須為「會」而非「可能」，故答案為該項；「可能影響」削弱了標準，其餘選項不符定義。"}},
{p:3,ch:"人寿保险简介",q:"一份完全清缴的保单是指:",o:["以往所有到期保费已给支付","保费由第三者(如雇主)支付","保单一经生效必须支付所有保费","将来的保费毋须缴付,但保单仍然维持有效"],a:3,e:"完全清缴（缴清）保单指将来保费毋须再缴付而保单仍维持有效；以往到期保费已付或由第三者支付均非其定义，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"一份完全清繳的保單是指：",o:["以往所有到期保費已給支付","保費由第三者(如僱主)支付","保單一經生效必須支付所有保費","將來的保費毋須繳付，但保單仍然維持有效"],e:"完全清繳（繳清）保單指將來保費毋須再繳付而保單仍維持有效；以往到期保費已付或由第三者支付均非其定義，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"一名男子安排免体检保险,他无意误导保险人其健康状况,如详述其健康状况,保险人并不 提供保单保障,其后该男子死亡并真相大白,以下哪项描述并不正确?",o:["不论任何时间死亡,保险人都可推翻保险合约","死亡发生于保单生效期2年内,保险人可推翻保险合约","死亡发生于保单生效期2年后,保险人不可异议","没有涉及欺诈,保险人不可推翻保险合约"],a:0,e:"该男子并无欺诈且如实列入详情，则在订约后两年可争辩期内保险人可推翻合约，两年后不可异议；「不论任何时间死亡都可推翻」明显不正确，故为该题答案。",src:1,tw:{ch:"人壽保險簡介",q:"一名男子安排免體檢保險，他無意誤導保險人其健康狀況，如詳述其健康狀況，保險人並不 提供保單保障，其後該男子死亡並真相大白，以下哪項描述並不正確？",o:["不論任何時間死亡，保險人都可推翻保險合約","死亡發生於保單生效期2年內，保險人可推翻保險合約","死亡發生於保單生效期2年後，保險人不可異議","沒有涉及欺詐，保險人不可推翻保險合約"],e:"該男子並無欺詐且如實列入詳情，則在訂約後兩年可爭辯期內保險人可推翻合約，兩年後不可異議；「不論任何時間死亡都可推翻」明顯不正確，故為該題答案。"}},
{p:3,ch:"人寿保险简介",q:"一种寿险保单,不仅支付死亡保险金,还会支付与保险人之盈余挂钩的一项利益,此类保单 称之为:",o:["单位相连保单","分红保单","相关红利保单","相关利润保单"],a:1,e:"除支付死亡保险金外还把与保险人盈余（红利）挂钩的利益给付的保单，称为分红保单；单位相连、相关红利/利润保单均非正确名称。",src:1,tw:{ch:"人壽保險簡介",q:"一種壽險保單，不僅支付死亡保險金，還會支付與保險人之盈餘掛鉤的一項利益，此類保單 稱之為：",o:["單位相連保單","分紅保單","相關紅利保單","相關利潤保單"],e:"除支付死亡保險金外還把與保險人盈餘（紅利）掛鈎的利益給付的保單，稱為分紅保單；單位相連、相關紅利/利潤保單均非正確名稱。"}},
{p:3,ch:"人寿保险简介",q:"一般计算人寿保险保费有不同因素,以下哪项属于「纯保险费」?",o:["死亡率加投资费用","死亡率加利息","利息加投资费用","营运费用加死亡率"],a:1,e:"「纯保险费」由死亡率（风险成本）与利息（预期投资收益折现）两部分构成，故答案为「死亡率加利息」；投资费用、营运费用属附加保费。",src:1,tw:{ch:"人壽保險簡介",q:"一般計算人壽保險保費有不同因素，以下哪項屬於「純保險費」？",o:["死亡率加投資費用","死亡率加利息","利息加投資費用","營運費用加死亡率"],e:"「純保險費」由死亡率（風險成本）與利息（預期投資收益折現）兩部分構成，故答案為「死亡率加利息」；投資費用、營運費用屬附加保費。"}},
{p:3,ch:"人寿保险简介",q:"一般计算人寿保险保费的三大因素是死亡率、开支及:",o:["保险人的利润","目前的投资率","预期利息所得","净边际利润"],a:2,e:"计算寿险保费的三大因素是死亡率、开支及预期利息所得，故答案为「预期利息所得」；目前投资率、利润均非三大因素之一。",src:1,tw:{ch:"人壽保險簡介",q:"一般計算人壽保險保費的三大因素是死亡率、開支及：",o:["保險人的利潤","目前的投資率","預期利息所得","淨邊際利潤"],e:"計算壽險保費的三大因素是死亡率、開支及預期利息所得，故答案為「預期利息所得」；目前投資率、利潤均非三大因素之一。"}},
{p:3,ch:"人寿保险简介",q:"丈夫为自己生命买了一份保险,保单的受益人为其妻子,两年后,他们离婚,但丈夫继续为 保单缴交保费,后来丈夫离世,妻子可否获得赔偿?",o:["不可以,因为离婚后,妻子对丈夫的生命没有可保权益","可以索取全部保额","可以取回已交保费","可以索取一半保额的赔偿"],a:1,e:"可保权益只需在保单生效时存在，订约时丈夫对妻子生命有可保权益，其后离婚不影响已有效成立的保单，故妻子仍可获全部保额。",src:1,tw:{ch:"人壽保險簡介",q:"丈夫為自己生命買了一份保險，保單的受益人為其妻子，兩年後，他們離婚，但丈夫繼續為 保單繳交保費，後來丈夫離世，妻子可否獲得賠償？",o:["不可以，因為離婚後，妻子對丈夫的生命沒有可保權益","可以索取全部保額","可以取回已交保費","可以索取一半保額的賠償"],e:"可保權益只需在保單生效時存在，訂約時丈夫對妻子生命有可保權益，其後離婚不影響已有效成立的保單，故妻子仍可獲全部保額。"}},
{p:3,ch:"人寿保险简介",q:"下列何者对财产拥有可保权益,即使他或他们不是合法拥有者?",o:["拥有大量珠宝的妇人的遗产管理人","拥有有关财产的慈善机构的信托人","遗下有关财产的离世人士的遗瞩执行人","以上各项皆是"],a:3,e:"遗产管理人、信托人及遗嘱执行人即使不是财产的合法拥有者，因肩负保管责任而对财产享有可保权益，故「以上各项皆是」。",src:1,tw:{ch:"人壽保險簡介",q:"下列何者對財產擁有可保權益，即使他或他們不是合法擁有者？",o:["擁有大量珠寶的婦人的遺產管理人","擁有有關財產的慈善機構的信託人","遺下有關財產的離世人士的遺矚執行人","以上各項皆是"],e:"遺產管理人、信託人及遺囑執行人即使不是財產的合法擁有者，因肩負保管責任而對財產享有可保權益，故「以上各項皆是」。"}},
{p:3,ch:"人寿保险简介",q:"下列哪两项是正确的? i 利益保单与弥偿保单是相同的 ii 大多数人寿保单受弥偿原则约束,但有些不受 iii 人寿保险合约一般不属弥偿 iv 弥偿不适用于人寿保险,人寿保险由利益保单构成",o:["i, ii","i, iii","ii, iii","iii, iv"],a:3,e:"人寿保险一般不属弥偿，而是由利益保单构成，弥偿原则并不适用于人寿保险，故 iii、iv 正确；i、ii 的说法均错误。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪兩項是正確的？ i 利益保單與彌償保單是相同的 ii 大多數人壽保單受彌償原則約束，但有些不受 iii 人壽保險合約一般不屬彌償 iv 彌償不適用於人壽保險，人壽保險由利益保單構成",o:["i, ii","i, iii","ii, iii","iii, iv"],e:"人壽保險一般不屬彌償，而是由利益保單構成，彌償原則並不適用於人壽保險，故 iii、iv 正確；i、ii 的說法均錯誤。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项不是自然保费制度的特性?",o:["随着年龄的增长增加保费","对保险人有不利影响","续保时,对保单所有人带来实际问题","随着年龄的增长而减少保费"],a:3,e:"自然保费制度下保费随年龄增长而增加，续保时亦会上升，因此「随着年龄增长而减少保费」不是其特性，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項不是自然保費制度的特性？",o:["隨着年齡的增長增加保費","對保險人有不利影響","續保時,對保單所有人帶來實際問題","隨着年齡的增長而減少保費"],e:"自然保費制度下保費隨年齡增長而增加，續保時亦會上升，因此「隨着年齡增長而減少保費」不是其特性，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项为寿险保单商业需求而非个人需求?",o:["合伙人","教育经费","应急资金","受养人生活开支"],a:0,e:"合伙人（生意合伙人）涉及企业的延续，属商业需求；教育经费、应急资金及受养人生活开支属个人需求，故答案为「合伙人」。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項為壽險保單商業需求而非個人需求？",o:["合夥人","教育經費","應急資金","受養人生活開支"],e:"合夥人（生意合夥人）涉及企業的延續，屬商業需求；教育經費、應急資金及受養人生活開支屬個人需求，故答案為「合夥人」。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项为寿险保单的个人需求而非商业需求? i 应急资金 ii 教育经费 iii 退休收入 iv 受养人生活开支",o:["i, ii, iii","i, ii, iv","ii. iii, iv","以上各项皆是"],a:3,e:"应急资金、教育经费、退休收入及受养人生活开支均属家庭/个人的财务需要而非商业需要，故「以上各项皆是」。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項為壽險保單的個人需求而非商業需求？ i 應急資金 ii 教育經費 iii 退休收入 iv 受養人生活開支",o:["i, ii, iii","i, ii, iv","ii. iii, iv","以上各項皆是"],e:"應急資金、教育經費、退休收入及受養人生活開支均屬家庭/個人的財務需要而非商業需要，故「以上各項皆是」。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项关系不可构成可保权益?",o:["自己10岁的女","配偶","借钱给自己的人","欠自己钱的人"],a:2,e:"自己对配偶、未成年子女及债务人（欠自己钱的人）有可保权益；而「借钱给自己的人」是自己的债权人，其死亡并不会令自己蒙受损失，故不构成可保权益。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項關係不可構成可保權益？",o:["自己10歲的女","配偶","借錢給自己的人","欠自己錢的人"],e:"自己對配偶、未成年子女及債務人（欠自己錢的人）有可保權益；而「借錢給自己的人」是自己的債權人，其死亡並不會令自己蒙受損失，故不構成可保權益。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项属于人寿保险商业上的需求而不是个人上的需求? i 合伙人 ii 关键人物 iii 退休收入 iv 雇员福利",o:["i. ii, iii","i. ii, iv","ii. Iii,iv","以上皆是"],a:1,e:"合伙人、关键人物及雇员福利属于企业延续的商业需求，退休收入则是个人需求，故答案为 i、ii、iv。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項屬於人壽保險商業上的需求而不是個人上的需求？ i 合夥人 ii 關鍵人物 iii 退休收入 iv 僱員福利",o:["i. ii, iii","i. ii, iv","ii. Iii,iv","以上皆是"],e:"合夥人、關鍵人物及僱員福利屬於企業延續的商業需求，退休收入則是個人需求，故答案為 i、ii、iv。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项或哪些不大可能是购买人寿保险的需求?",o:["暂时性潜在的财务需要","作为个人/本身家庭的储蓄","为他人可能死亡而作出的投机活动","以上各项"],a:2,e:"人寿保险的目的在于保障合法的财务需要，「为他人死亡而作投机活动」欠缺可保权益，不属于购买人寿保险的正当需求，故为答案。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項或哪些不大可能是購買人壽保險的需求？",o:["暫時性潛在的財務需要","作為個人/本身家庭的儲蓄","為他人可能死亡而作出的投機活動","以上各項"],e:"人壽保險的目的在於保障合法的財務需要，「為他人死亡而作投機活動」欠缺可保權益，不屬於購買人壽保險的正當需求，故為答案。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项描述购买人寿保险产品首要目的之现代观点最恰当?",o:["一项投机性的投资","死亡时提供一整笔款项","为满足各种财务需求","一项保证形式的储蓄,胜过银行产品"],a:2,e:"现代观点认为购买人寿保险的首要目的是为满足各种财务需求（保障与储蓄并重），而非单纯投机、只求死亡给付或保证储蓄，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項描述購買人壽保險產品首要目的之現代觀點最恰當？",o:["一項投機性的投資","死亡時提供一整筆款項","為滿足各種財務需求","一項保證形式的儲蓄，勝過銀行產品"],e:"現代觀點認為購買人壽保險的首要目的是為滿足各種財務需求（保障與儲蓄並重），而非單純投機、只求死亡給付或保證儲蓄，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项有关弥偿的陈述是正确的?",o:["除非由法律隐含,否则弥偿不存在于人寿保险中","法律是不容许人寿保险作出弥偿","向保单持有人就其丧生提供超额赔偿是不可能的事情","保单的不可异议条款可能改变这种情况"],a:2,e:"人寿保险属利益保单而非弥偿，不存在「超额赔偿」的概念，故「向保单持有人就其丧生提供超额赔偿是不可能的事情」是正确的。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項有關彌償的陳述是正確的？",o:["除非由法律隱含，否則彌償不存在於人壽保險中","法律是不容許人壽保險作出彌償","向保單持有人就其喪生提供超額賠償是不可能的事情","保單的不可異議條款可能改變這種情況"],e:"人壽保險屬利益保單而非彌償，不存在「超額賠償」的概念，故「向保單持有人就其喪生提供超額賠償是不可能的事情」是正確的。"}},
{p:3,ch:"人寿保险简介",q:"下列哪项正确描述可保权益:",o:["它不是普通法的条款","在香港的法定条文中已扩阔了它的范围","寿险保单中承让人必须具有可保权益","它只能由家庭或婚姻关系中出现"],a:1,e:"香港的法定条文已把可保权益的范围扩阔（如配偶、父母子女等），故该项正确；可保权益源于普通法，转让不须承让人具可保权益，且不限于家庭婚姻关系。",src:1,tw:{ch:"人壽保險簡介",q:"下列哪項正確描述可保權益：",o:["它不是普通法的條款","在香港的法定條文中已擴闊了它的範圍","壽險保單中承讓人必須具有可保權益","它只能由家庭或婚姻關係中出現"],e:"香港的法定條文已把可保權益的範圍擴闊（如配偶、父母子女等），故該項正確；可保權益源於普通法，轉讓不須承讓人具可保權益，且不限於家庭婚姻關係。"}},
{p:3,ch:"人寿保险简介",q:"人寿保单最初及基本的目的是保障",o:["死亡","储蓄","退休","威胁"],a:3,e:"人寿保单最初及基本的目的在于保障（应对）「威胁」，尤其早逝给家庭带来的财务威胁；储蓄、退休等属后来发展出的功能，故答案为「威胁」。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保單最初及基本的目的是保障",o:["死亡","儲蓄","退休","威脅"],e:"人壽保單最初及基本的目的在於保障（應對）「威脅」，尤其早逝給家庭帶來的財務威脅；儲蓄、退休等屬後來發展出的功能，故答案為「威脅」。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险不会分担一份损失的赔偿。但在一般保险中,例如医疗保险,如果客户有多份保险 ,有关保险就会按比例赔偿损失。这种保险概念叫做:",o:["代位权","弥偿","分担","近因"],a:2,e:"多份保险按各自保额比例分摊同一损失的机制称为「分担」原则，故答案为「分担」；代位权、弥偿、近因均非此概念。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險不會分擔一份損失的賠償。但在一般保險中，例如醫療保險，如果客戶有多份保險 ，有關保險就會按比例賠償損失。這種保險概念叫做：",o:["代位權","彌償","分擔","近因"],e:"多份保險按各自保額比例分攤同一損失的機制稱為「分擔」原則，故答案為「分擔」；代位權、彌償、近因均非此概念。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险中对可保权益的法律要求,以下哪项陈述是正确的?",o:["一名女子对自己生命享有无限的可保权益","每个人对自己生命的可保权益限于其净资产值","每个人对自己生命的可保权益限于其收入","他人生命的可保权益相同"],a:0,e:"每个人对自己生命享有无限的可保权益，不限于净资产或收入；而他人生命的可保权益则有别，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險中對可保權益的法律要求，以下哪項陳述是正確的？",o:["一名女子對自己生命享有無限的可保權益","每個人對自己生命的可保權益限於其淨資產值","每個人對自己生命的可保權益限於其收入","他人生命的可保權益相同"],e:"每個人對自己生命享有無限的可保權益，不限於淨資產或收入；而他人生命的可保權益則有別，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险保费其中一标准是【公平】的,这意味着:",o:["是市场上最便宜的保费","对客户来说是不偏不倚的","反映所面对的风险","保险人需要作出的赔偿"],a:2,e:"保费「公平」指保费应如实反映被保人所面对的风险，使同类风险者负担相称；最便宜或保证盈利等均非「公平」的定义。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險保費其中一標準是【公平】的,這意味着:",o:["是市場上最便宜的保費","對客户來說是不偏不倚的","反映所面對的風險","保險人需要作出的賠償"],e:"保費「公平」指保費應如實反映被保人所面對的風險，使同類風險者負擔相稱；最便宜或保證盈利等均非「公平」的定義。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险可分为个人及业务需求,以下哪项是个人需求? i 关键人物 ii 偿还按揭资金 iii 教育经费 iv 受养人的生活开支",o:["i, ii, iii","ii, iii, iv","i, iii, iv","i, ii, iii, iv"],a:1,e:"偿还按揭资金、教育经费及受养人生活开支属个人需求；关键人物属商业需求，故答案为 ii、iii、iv。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險可分為個人及業務需求，以下哪項是個人需求？ i 關鍵人物 ii 償還按揭資金 iii 教育經費 iv 受養人的生活開支",o:["i, ii, iii","ii, iii, iv","i, iii, iv","i, ii, iii, iv"],e:"償還按揭資金、教育經費及受養人生活開支屬個人需求；關鍵人物屬商業需求，故答案為 ii、iii、iv。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险合约最初类型:",o:["本质上属于短暂的,以保障早逝情况","本质上属于长久的,即直至死亡","与物业抵押贷款有关","属单位相连的安排"],a:0,e:"最早的人寿保险合约本质上属短暂的（定期保障），用以保障被保险人早逝的情况，故答案为该项；长久直至死亡、按揭相关或单位相连均非最初类型。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險合約最初類型：",o:["本質上屬於短暫的，以保障早逝情況","本質上屬於長久的，即直至死亡","與物業抵押貸款有關","屬單位相連的安排"],e:"最早的人壽保險合約本質上屬短暫的（定期保障），用以保障被保險人早逝的情況，故答案為該項；長久直至死亡、按揭相關或單位相連均非最初類型。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险定义为:「保险公司承诺当受保保单所有人死亡时给付保险金的保险。」 这段引述是:",o:["有限制的,在可能的情况下是可行的","这是最初及最基本的目的","这未能完全描述现代的人寿保险","以上所列各项都是正确的"],a:3,e:"该引述作为定义虽有局限但可行、是研究历史的最初及基本目的，且并不能完全描述现代的人寿保险，故「以上所列各项都是正确的」。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險定義為：「保險公司承諾當受保保單所有人死亡時給付保險金的保險。」 這段引述是：",o:["有限制的，在可能的情況下是可行的","這是最初及最基本的目的","這未能完全描述現代的人壽保險","以上所列各項都是正確的"],e:"該引述作為定義雖有侷限但可行、是研究歷史的最初及基本目的，且並不能完全描述現代的人壽保險，故「以上所列各項都是正確的」。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险最初时及最基本的目的是:",o:["为死亡(尤其是早逝) 提供一笔金钱","为尚余生命的人士提供一笔金钱","为期满的人士提供一笔金钱","储蓄用途"],a:0,e:"人寿保险最初及最基本的目的是为死亡（尤其早逝）提供一笔金钱予其家人，故答案为该项；为尚余生命者或满期者提供金钱等均非最初目的。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險最初時及最基本的目的是：",o:["為死亡(尤其是早逝) 提供一筆金錢","為尚餘生命的人士提供一筆金錢","為期滿的人士提供一筆金錢","儲蓄用途"],e:"人壽保險最初及最基本的目的是為死亡（尤其早逝）提供一筆金錢予其家人，故答案為該項；為尚餘生命者或滿期者提供金錢等均非最初目的。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险最初时的功能是:",o:["为退休时提供一笔金钱","为被保险人的家人提供死亡赔偿金","为在战争中死去的士兵提供死亡赔偿","为雇用及过程发生的死亡提供赔偿"],a:1,e:"人寿保险最初的功能是为被保险人的家人提供死亡赔偿金，以应对早逝带来的经济困难，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險最初時的功能是：",o:["為退休時提供一筆金錢","為被保險人的家人提供死亡賠償金","為在戰爭中死去的士兵提供死亡賠償","為僱用及過程發生的死亡提供賠償"],e:"人壽保險最初的功能是為被保險人的家人提供死亡賠償金，以應對早逝帶來的經濟困難，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险的最初及基本目的是?",o:["储蓄","投资","满足暂时需要","为退休作出安排"],a:2,e:"人寿保险的最初及基本目的是满足「暂时需要」，即保障早逝等短期风险；储蓄、投资、退休安排均是后来发展出来的功能，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險的最初及基本目的是?",o:["儲蓄","投資","滿足暫時需要","為退休作出安排"],e:"人壽保險的最初及基本目的是滿足「暫時需要」，即保障早逝等短期風險；儲蓄、投資、退休安排均是後來發展出來的功能，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险的最初目的是要:",o:["在某人于退休时,提供一笔金钱","在某人于死亡时,向其家人或其他人提供金钱","在一名海员于海上死亡时,提供一笔金钱","在指明年期届满时"],a:1,e:"人寿保险最初的目的是在某人死亡时向其家人或其他人提供一笔金钱，故答案为该项；退休、海员或满期给付均非最初原意。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險的最初目的是要：",o:["在某人於退休時，提供一筆金錢","在某人於死亡時，向其家人或其他人提供金錢","在一名海員於海上死亡時，提供一筆金錢","在指明年期屆滿時"],e:"人壽保險最初的目的是在某人死亡時向其家人或其他人提供一筆金錢，故答案為該項；退休、海員或滿期給付均非最初原意。"}},
{p:3,ch:"人寿保险简介",q:"从人寿保险角度看,以下哪项正确描述每个人对自己本身所拥有的可保权益?",o:["无限的","只限于其资产值","只限于其收入","与该人对其拥有可保权益人士所拥有的可保权益相同"],a:0,e:"每个人对自己生命的可保权益是无限的，因为自身死亡给本人及家属带来的财务需要不受限于资产或收入值，故答案为「无限的」。",src:1,tw:{ch:"人壽保險簡介",q:"從人壽保險角度看，以下哪項正確描述每個人對自己本身所擁有的可保權益？",o:["無限的","只限於其資產值","只限於其收入","與該人對其擁有可保權益人士所擁有的可保權益相同"],e:"每個人對自己生命的可保權益是無限的，因為自身死亡給本人及家屬帶來的財務需要不受限於資產或收入值，故答案為「無限的」。"}},
{p:3,ch:"人寿保险简介",q:"代位权在以下哪项人寿保险赔付后可获得?",o:["被保险保单持有人遭到谋杀","被一名疏忽的电单车司机撞至死亡","乘坐民航客机时遭遇空难","以上各项皆不正确"],a:3,e:"代位权是弥偿原则的延伸，而人寿保险属利益保单，赔付后保险人不取得代位权，故所有选项（谋杀、车祸、空难）均不正确。",src:1,tw:{ch:"人壽保險簡介",q:"代位權在以下哪項人壽保險賠付後可獲得？",o:["被保險保單持有人遭到謀殺","被一名疏忽的電單車司機撞至死亡","乘坐民航客機時遭遇空難","以上各項皆不正確"],e:"代位權是彌償原則的延伸，而人壽保險屬利益保單，賠付後保險人不取得代位權，故所有選項（謀殺、車禍、空難）均不正確。"}},
{p:3,ch:"人寿保险简介",q:"代位权这项保险原则在以下的人寿保险索偿显得较为重要?",o:["被保险人被谋杀","被保险人给疏忽的电单车车主撞死","机师的过失导致撞机令被保险人死亡","以上各项皆不正确"],a:3,e:"人寿保险索偿一般不涉及代位权，故无论被保险人被谋杀、被疏忽司机撞死或机师过失致死，代位权都不适用，答案为「以上各项皆不正确」。",src:1,tw:{ch:"人壽保險簡介",q:"代位權這項保險原則在以下的人壽保險索償顯得較為重要？",o:["被保險人被謀殺","被保險人給疏忽的電單車車主撞死","機師的過失導致撞機令被保險人死亡","以上各項皆不正確"],e:"人壽保險索償一般不涉及代位權，故無論被保險人被謀殺、被疏忽司機撞死或機師過失致死，代位權都不適用，答案為「以上各項皆不正確」。"}},
{p:3,ch:"人寿保险简介",q:"以下哪一种保费制度以保单开始时及其他特别之处作根据,并且在保险期内保费维持不变:",o:["自然保费制度","均衡保费制度","不变保费制度","起始保费制度"],a:1,e:"均衡保费制度以保单开始时的风险等因素为依据，在保险期内保费维持不变，故答案为「均衡保费制度」；自然保费则会递增。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪一種保費制度以保單開始時及其他特別之處作根據，並且在保險期內保費維持不變：",o:["自然保費制度","均衡保費制度","不變保費制度","起始保費制度"],e:"均衡保費制度以保單開始時的風險等因素為依據，在保險期內保費維持不變，故答案為「均衡保費制度」；自然保費則會遞增。"}},
{p:3,ch:"人寿保险简介",q:"以下哪一项不是均衡保费制度的特点?",o:["经过初期的年数,保单会累积一个现金退保价值","保费(根据相同的死亡利益)不会每年增加","保费会按照被保险人到达之年龄而增加","较早的保单保费高于死亡风险所需要的金额"],a:2,e:"均衡保费制度下保费不随年龄增加、早年保费高于风险所需并累积现金价值；「保费按被保险人到达年龄而增加」是自然保费制度的特点，故为该题答案。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪一項不是均衡保費制度的特點？",o:["經過初期的年數，保單會累積一個現金退保價值","保費(根據相同的死亡利益)不會每年增加","保費會按照被保險人到達之年齡而增加","較早的保單保費高於死亡風險所需要的金額"],e:"均衡保費制度下保費不隨年齡增加、早年保費高於風險所需並累積現金價值；「保費按被保險人到達年齡而增加」是自然保費制度的特點，故為該題答案。"}},
{p:3,ch:"人寿保险简介",q:"以下哪一项就关于近因这保险原则相当较可能重要?",o:["附加了意外死亡保险利益的保单","附加了双倍补偿利益条款的保单","保单生效一年内怀疑自杀的个案","以上各项皆是"],a:3,e:"近因原则在意外死亡利益、双倍补偿条款及一年内自杀个案中都直接影响是否属承保原因，故「以上各项皆是」。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪一項就關於近因這保險原則相當較可能重要？",o:["附加了意外死亡保險利益的保單","附加了雙倍補償利益條款的保單","保單生效一年內懷疑自殺的個案","以上各項皆是"],e:"近因原則在意外死亡利益、雙倍補償條款及一年內自殺個案中都直接影響是否屬承保原因，故「以上各項皆是」。"}},
{p:3,ch:"人寿保险简介",q:"以下哪三种原则不能应用于人寿保险? i 代位权 ii 分担 iii 弥偿 iv 可保权益",o:["i, ii, iv","i, ii, iii","i, iii, iv","ii, iii, iv"],a:1,e:"代位权、分担及弥偿三项原则均源于弥偿，不适用于人寿保险，故答案为 i、ii、iii；可保权益则适用于人寿保险。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪三種原則不能應用於人壽保險？ i 代位權 ii 分擔 iii 彌償 iv 可保權益",o:["i, ii, iv","i, ii, iii","i, iii, iv","ii, iii, iv"],e:"代位權、分擔及彌償三項原則均源於彌償，不適用於人壽保險，故答案為 i、ii、iii；可保權益則適用於人壽保險。"}},
{p:3,ch:"人寿保险简介",q:"以下哪种保险制度,保费按受保人的年龄上升而增加保费?",o:["递增保费(厘定)制度","均衡保费(厘定)制度","自然保费(厘定)制度","递升保费(厘定)制度"],a:2,e:"自然保费（厘定）制度下保费随受保人年龄上升而增加，故答案为「自然保费(厘定)制度」；均衡保费则保持不变。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪種保險制度，保費按受保人的年齡上升而增加保費？",o:["遞增保費（釐定）制度","均衡保費（釐定）制度","自然保費（釐定）制度","遞升保費（釐定）制度"],e:"自然保費（釐定）制度下保費隨受保人年齡上升而增加，故答案為「自然保費(釐定)制度」；均衡保費則保持不變。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项不是人寿保险的目的?",o:["为未来教育需求储蓄","逃税","为短暂的需求作出保障","为退休后的生活做好准备"],a:1,e:"逃税并非人寿保险的正当目的，反而可能引发法律问题；为教育储蓄、短暂需要保障及退休准备均属人寿保险的目的，故答案为「逃税」。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項不是人壽保險的目的？",o:["為未來教育需求儲蓄","逃稅","為短暫的需求作出保障","為退休後的生活做好準備"],e:"逃税並非人壽保險的正當目的，反而可能引發法律問題；為教育儲蓄、短暫需要保障及退休準備均屬人壽保險的目的，故答案為「逃税」。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项为最高诚信的正确描述? i 不期望被保人披露有理由不可能知道的情况 ii 人寿保险只要求投保人回答保险人问题时具有最高诚信 iii 免体检的保单,投保人不用披露体检表格内没有问及的事情 iv 没有欺诈而违反最高诚信,超过不可异议期后可得到豁免",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],a:1,e:"最高诚信不要求披露有理由不可能知道的情况，免体检保单无须披露未问及的事项，且无欺诈时超过不可异议期可获豁免；但人寿保险披露义务不止于回答问题，故 ii 错，答案为 i、iii、iv。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項為最高誠信的正確描述？ i 不期望被保人披露有理由不可能知道的情況 ii 人壽保險只要求投保人回答保險人問題時具有最高誠信 iii 免體檢的保單，投保人不用披露體檢表格內沒有問及的事情 iv 沒有欺詐而違反最高誠信，超過不可異議期後可得到豁免",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],e:"最高誠信不要求披露有理由不可能知道的情況，免體檢保單無須披露未問及的事項，且無欺詐時超過不可異議期可獲豁免；但人壽保險披露義務不止於回答問題，故 ii 錯，答案為 i、iii、iv。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项只有在合约开始时才需要可保权益,之后可保权益不再相干?",o:["离婚前为其配偶的生命投保","在债务得到偿还前就你的债务人的生命投保","雇主就关键雇员购买人寿,雇员几天后离职,该保单仍然维持的有效性","以上各项皆是"],a:3,e:"可保权益只需在合约开始时存在，之后失效不影响保单，故离婚前投保、债务偿还前投保及雇员离职后保单仍维持有效均属此项，答案为「以上各项皆是」。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項只有在合約開始時才需要可保權益，之後可保權益不再相干？",o:["離婚前為其配偶的生命投保","在債務得到償還前就你的債務人的生命投保","僱主就關鍵僱員購買人壽，僱員幾天後離職，該保單仍然維持的有效性","以上各項皆是"],e:"可保權益只需在合約開始時存在，之後失效不影響保單，故離婚前投保、債務償還前投保及僱員離職後保單仍維持有效均屬此項，答案為「以上各項皆是」。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项属于人寿保险的需求?",o:["善终开支","生意合伙人","关键人物","以上各项皆是"],a:3,e:"善终开支、生意合伙人及关键人物均属人寿保险的需求（个人与商业），故「以上各项皆是」。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項屬於人壽保險的需求？",o:["善終開支","生意合夥人","關鍵人物","以上各項皆是"],e:"善終開支、生意合夥人及關鍵人物均屬人壽保險的需求（個人與商業），故「以上各項皆是」。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项属于厘定人寿保费的传统标准中?",o:["市面上最便宜的","充足的","足以保证保险人可赚取盈利","低至使保单持有人有能力支付的"],a:1,e:"传统标准要求保费「充足」，即足以支付保险利益及应付未来责任，故答案为「充足的」；最便宜、保证盈利或低至可负担均非该标准。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項屬於釐定人壽保費的傳統標準中？",o:["市面上最便宜的","充足的","足以保證保險人可賺取盈利","低至使保單持有人有能力支付的"],e:"傳統標準要求保費「充足」，即足以支付保險利益及應付未來責任，故答案為「充足的」；最便宜、保證盈利或低至可負擔均非該標準。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项属于弥偿的引伸?",o:["最高诚信","代位权","A&B","以上皆否"],a:1,e:"代位权是弥偿原则的引伸——保险人赔付后取得向第三者追偿的权利，故答案为「代位权」；A&B 及最高诚信均不正确。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項屬於彌償的引伸？",o:["最高誠信","代位權","A&B","以上皆否"],e:"代位權是彌償原則的引伸——保險人賠付後取得向第三者追償的權利，故答案為「代位權」；A&B 及最高誠信均不正確。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项情况是拥有可保权益呢? i   为本身的债务人之生命购买人寿保险 ii  为本身25岁的儿子的生命购买人寿保险 iii 为现在生意合作伙伴的生命购买人寿保险 iv 为前度配偶(已离婚)的生命购买人寿保险",o:["i, ii","i, iii","ii, iii","iii, iv"],a:1,e:"对本身债务人的生命、对生意合作伙伴的生命均有可保权益；已离婚的前配偶及已自立成年儿子一般已无（或丧失）可保权益，故答案为 i、iii。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項情況是擁有可保權益呢？ i 為本身的債務人之生命購買人壽保險 ii 為本身25歲的兒子的生命購買人壽保險 iii 為現在生意合作伙伴的生命購買人壽保險 iv 為前度配偶(已離婚)的生命購買人壽保險",o:["i, ii","i, iii","ii, iii","iii, iv"],e:"對本身債務人的生命、對生意合作伙伴的生命均有可保權益；已離婚的前配偶及已自立成年兒子一般已無（或喪失）可保權益，故答案為 i、iii。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项是对人寿保单转让的不正确描述?",o:["人寿保险可以转让予关系密切的朋友","人寿保险可以转让予已离婚的配偶","人寿保险不可转让予曾经具有但现时已失去可保权益的人士","人寿保险的转让并不要求具有可保权益"],a:2,e:"人寿保单转让并不要求承让人具有可保权益，故「不可转让予曾经具有但现时已失去可保权益的人士」的说法不正确，为该题答案。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項是對人壽保單轉讓的不正確描述？",o:["人壽保險可以轉讓予關係密切的朋友","人壽保險可以轉讓予已離婚的配偶","人壽保險不可轉讓予曾經具有但現時已失去可保權益的人士","人壽保險的轉讓並不要求具有可保權益"],e:"人壽保單轉讓並不要求承讓人具有可保權益，故「不可轉讓予曾經具有但現時已失去可保權益的人士」的說法不正確，為該題答案。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项是投保时没有披露重要事实而违反最高诚信?",o:["未能验出脑肿瘤","体检医生未能发现投保人有心率不正的问题","投保人于多年前曾患有儿童疾病","以上皆不是"],a:2,e:"「多年前曾患儿童疾病」是投保人明知而应披露的重要事实，未能披露即违反最高诚信；未能验出脑肿瘤及医生未发现心率不正均属投保人不知情，不构成违反，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項是投保時沒有披露重要事實而違反最高誠信?",o:["未能驗出腦腫瘤","體檢醫生未能發現投保人有心率不正的問題","投保人於多年前曾患有兒童疾病","以上皆不是"],e:"「多年前曾患兒童疾病」是投保人明知而應披露的重要事實，未能披露即違反最高誠信；未能驗出腦腫瘤及醫生未發現心率不正均屬投保人不知情，不構成違反，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项有关寿险保单的转让与可保权益的法律规定的关系的陈述是正确的?",o:["保单所有人一般不能将寿险合约转让予缺乏可保权益的第三者","保单所有人只能透过另一合约把其寿险合约转让予第三者","保单所有人一般可以把正当地安排的寿险合约转让予第三者, 即使该第三者对受保生命缺乏可保权益","假设一名准保单所有人意图购买一份保单保某人的生命,但他对后者的 生命缺乏可保权益,他于是安排后者购买保单保自身的生命,再转让给他, 这么一种保单于转让给前者后便告无效"],a:2,e:"保单所有人一般可把正当地安排的寿险合约转让予第三者，即使该第三者对受保生命缺乏可保权益，故答案为该项；其余说法或错误或附加了错误限制。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係的陳述是正確的？",o:["保單所有人一般不能將壽險合約轉讓予缺乏可保權益的第三者","保單所有人只能透過另一合約把其壽險合約轉讓予第三者","保單所有人一般可以把正當地安排的壽險合約轉讓予第三者， 即使該第三者對受保生命缺乏可保權益","假設一名準保單所有人意圖購買一份保單保某人的生命，但他對後者的 生命缺乏可保權益，他於是安排後者購買保單保自身的生命，再轉讓給他， 這麼一種保單於轉讓給前者後便告無效"],e:"保單所有人一般可把正當地安排的壽險合約轉讓予第三者，即使該第三者對受保生命缺乏可保權益，故答案為該項；其餘說法或錯誤或附加了錯誤限制。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项有关购买人寿保险首要目的现代观点的描述是确的?",o:["一种投机性的投资","为退休作好安排","为满足各种财务需求而作好准备","一种提供保证的储蓄,较银行产品好"],a:2,e:"现代观点认为购买人寿保险首要目的是为满足各种财务需求作好准备，故答案为该项；投机、仅为退休或保证储蓄均不全面。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項有關購買人壽保險首要目的現代觀點的描述是確的？",o:["一種投機性的投資","為退休作好安排","為滿足各種財務需求而作好準備","一種提供保證的儲蓄，較銀行產品好"],e:"現代觀點認為購買人壽保險首要目的是為滿足各種財務需求作好準備，故答案為該項；投機、僅為退休或保證儲蓄均不全面。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项肯定投保人人必须披露的重要事实?",o:["与实际物件(财产)保险关系判断的事实","会影响一名审慎的核保人于订定保费决定判断的事实","会影响一名合理的核保人于订定保费决定判断的事实","可能影响一名审慎的核保人于订定保费决定判断的事实"],a:1,e:"必须披露的重要事实是「会影响一名审慎的核保人在订定保费时作判断的事实」，关键在「会影响」及「审慎的核保人」，故答案为该项；「可能影响」或「合理的核保人」均不符标准定义。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項肯定投保人人必須披露的重要事實？",o:["與實際物件(財產)保險關係判斷的事實","會影響一名審慎的核保人於訂定保費決定判斷的事實","會影響一名合理的核保人於訂定保費決定判斷的事實","可能影響一名審慎的核保人於訂定保費決定判斷的事實"],e:"必須披露的重要事實是「會影響一名審慎的核保人在訂定保費時作判斷的事實」，關鍵在「會影響」及「審慎的核保人」，故答案為該項；「可能影響」或「合理的核保人」均不符標準定義。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项肯定是对保险人来说是属于重要事实的?",o:["投保时的身体检查","不必披露予保险人的事实","是对保险人订定保费或决定是否承担风险的事实","可能对保险人于订定保费决定判断任何情况的事实"],a:2,e:"对保险人属重要的事实，是指会影响保险人订定保费或决定是否承担风险的事实，故答案为该项；体检及不必披露的事实等均不对。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項肯定是對保險人來說是屬於重要事實的？",o:["投保時的身體檢查","不必披露予保險人的事實","是對保險人訂定保費或決定是否承擔風險的事實","可能對保險人於訂定保費決定判斷任何情況的事實"],e:"對保險人屬重要的事實，是指會影響保險人訂定保費或決定是否承擔風險的事實，故答案為該項；體檢及不必披露的事實等均不對。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项说明是不正确?",o:["人寿保险可以转让予某个对受保生命不具有可保权益的人","人寿保险可以转让予某个对受保生命不具有可保权益的人,但受保生命 必须并非一名破产人士","不论承让人是否具有可保权益,人寿保单都可以转让","人寿保险可以转让予某个不属于受保生命家庭成员的人士"],a:1,e:"人寿保险可转让予对受保生命无可保权益的人，且并无「受保生命必须并非破产人士」的限制，故第二项说明不正确，为该题答案。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項說明是不正確?",o:["人壽保險可以轉讓予某個對受保生命不具有可保權益的人","人壽保險可以轉讓予某個對受保生命不具有可保權益的人，但受保生命 必須並非一名破產人士","不論承讓人是否具有可保權益，人壽保單都可以轉讓","人壽保險可以轉讓予某個不屬於受保生命家庭成員的人士"],e:"人壽保險可轉讓予對受保生命無可保權益的人，且並無「受保生命必須並非破產人士」的限制，故第二項說明不正確，為該題答案。"}},
{p:3,ch:"人寿保险简介",q:"以下那些是由均衡保费直接或间接产生? i 现金价值 ii 保单贷款 iii 不能作废 iv 清缴保险",o:["i, ii","ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"均衡保费使早年多缴部分累积成现金价值，进而衍生保单贷款、不能作废及缴清保险等权利，故四项均由均衡保费直接或间接产生。",src:1,tw:{ch:"人壽保險簡介",q:"以下那些是由均衡保費直接或間接產生？ i 現金價值 ii 保單貸款 iii 不能作廢 iv 清繳保險",o:["i, ii","ii, iii","ii, iii, iv","i, ii, iii, iv"],e:"均衡保費使早年多繳部分累積成現金價值，進而衍生保單貸款、不能作廢及繳清保險等權利，故四項均由均衡保費直接或間接產生。"}},
{p:3,ch:"人寿保险简介",q:"任何人对于下列哪些/种人可保权益?",o:["自己的配偶","债务人","生意合伙人","以上各项"],a:3,e:"对自己的配偶、债务人及生意合伙人，一般人均享有可保权益，故「以上各项」皆正确。",src:1,tw:{ch:"人壽保險簡介",q:"任何人對於下列哪些/種人可保權益？",o:["自己的配偶","債務人","生意合夥人","以上各項"],e:"對自己的配偶、債務人及生意合夥人，一般人均享有可保權益，故「以上各項」皆正確。"}},
{p:3,ch:"人寿保险简介",q:"保费随年龄增长而增加,此保费制度是为:",o:["递增保费制度","递升保费制度","均衡保费制度","自然保费制度"],a:3,e:"保费随受保人年龄增长而增加的制度是自然保费制度，故答案为「自然保费制度」；均衡保费制度则保费维持不变。",src:1,tw:{ch:"人壽保險簡介",q:"保費隨年齡增長而增加，此保費制度是為：",o:["遞增保費制度","遞升保費制度","均衡保費制度","自然保費制度"],e:"保費隨受保人年齡增長而增加的制度是自然保費制度，故答案為「自然保費制度」；均衡保費制度則保費維持不變。"}},
{p:3,ch:"人寿保险简介",q:"保险人用什么计算寿险保费: i. 死亡率 ii. 开支 iii. 疾病率 iv. 预期利息收入",o:["i, iv","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],a:2,e:"寿险保费由死亡率、开支及预期利息收入三大因素构成；疾病率属健康保险的定价因素而非传统寿险，故答案为 i、ii、iv。",src:1,tw:{ch:"人壽保險簡介",q:"保險人用什麼計算壽險保費: i.死 亡率 ii. 開支 iii.疾 病率 iv. 預期利息收入",o:["i, iv","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"壽險保費由死亡率、開支及預期利息收入三大因素構成；疾病率屬健康保險的定價因素而非傳統壽險，故答案為 i、ii、iv。"}},
{p:3,ch:"人寿保险简介",q:"保险人用什么计算寿险保费: i. 死亡率 ii. 开支 iii. 目前投资利率 iv. 预期利息收入",o:["i, iv","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],a:2,e:"寿险保费按死亡率、开支及预期利息收入计算，而非「目前投资利率」，故答案为 i、ii、iv。",src:1,tw:{ch:"人壽保險簡介",q:"保險人用什麼計算壽險保費: i.死 亡率 ii. 開支 iii.目 前投資利率 iv. 預期利息收入",o:["i, iv","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"壽險保費按死亡率、開支及預期利息收入計算，而非「目前投資利率」，故答案為 i、ii、iv。"}},
{p:3,ch:"人寿保险简介",q:"债权人对其债务人的生命具有可保权益,数额为:",o:["贷款金额,加上应付未来之利息及预期利息","不包含利息之贷款金额","贷款金额,加上应付应计之利息","贷款金额,加上应付赚取之利息"],a:2,e:"债权人对债务人生命的可保权益数额为贷款金额加上应付的应计利息，故答案为该项，而非不连利息或连未来预期利息。",src:1,tw:{ch:"人壽保險簡介",q:"債權人對其債務人的生命具有可保權益，數額為：",o:["貸款金額，加上應付未來之利息及預期利息","不包含利息之貸款金額","貸款金額，加上應付應計之利息","貸款金額，加上應付賺取之利息"],e:"債權人對債務人生命的可保權益數額為貸款金額加上應付的應計利息，故答案為該項，而非不連利息或連未來預期利息。"}},
{p:3,ch:"人寿保险简介",q:"净保费加附加保费等如毛保费,什么是净保费?",o:["死亡率加投资费用","死亡率加利息","利息加投资费用","营运费用加死亡率 (a)注"],a:1,e:"净保费由死亡率与利息（预期收益折现）构成，加上附加保费即得毛保费，故答案为「死亡率加利息」。",src:1,tw:{ch:"人壽保險簡介",q:"淨保費加附加保費等如毛保費，什麼是淨保費？",o:["死亡率加投資費用","死亡率加利息","利息加投資費用","營運費用加死亡率 (a)注"],e:"淨保費由死亡率與利息（預期收益折現）構成，加上附加保費即得毛保費，故答案為「死亡率加利息」。"}},
{p:3,ch:"人寿保险简介",q:"分担与代位权:",o:["不适用于人寿保险","对人寿保险的索偿很重要","其重要性在人寿保险索偿与一般保险索偿一致","以上各项皆不正确"],a:0,e:"分担与代位权均源自弥偿原则，而人寿保险属利益保单，两项原则均不适用，故答案为「不适用于人寿保险」。",src:1,tw:{ch:"人壽保險簡介",q:"分擔與代位權：",o:["不適用於人壽保險","對人壽保險的索償很重要","其重要性在人壽保險索償與一般保險索償一致","以上各項皆不正確"],e:"分擔與代位權均源自彌償原則，而人壽保險屬利益保單，兩項原則均不適用，故答案為「不適用於人壽保險」。"}},
{p:3,ch:"人寿保险简介",q:"分担原则:",o:["适用于超额保险的人寿保险","绝不适用于人寿保险","适用于人寿保险,如果是以弥偿形式定立","只适用于一般保险"],a:1,e:"分担原则绝不适用于人寿保险，因为人寿保险给付约定的固定金额，无分摊损失的概念；「适用于超额保险」或「以弥偿形式定立才适用」均不成立。",src:1,tw:{ch:"人壽保險簡介",q:"分擔原則：",o:["適用於超額保險的人壽保險","絕不適用於人壽保險","適用於人壽保險，如果是以彌償形式定立","只適用於一般保險"],e:"分擔原則絕不適用於人壽保險，因為人壽保險給付約定的固定金額，無分攤損失的概念；「適用於超額保險」或「以彌償形式定立才適用」均不成立。"}},
{p:3,ch:"人寿保险简介",q:"分担及代位权:",o:["只适用于超额的人寿保单","不适用于人寿保单,除非以弥偿形式订立","不适用于人寿保单,但适用于其他弥偿保单","适用于人寿保单的程度与一般保险的索偿情况是完全一样的"],a:2,e:"分担及代位权不适用于人寿保单（除非以弥偿形式订立），但适用于其他弥偿保单，故答案为该项，而非「适用于人寿保单的程度与一般保险完全一样」。",src:1,tw:{ch:"人壽保險簡介",q:"分擔及代位權：",o:["只適用於超額的人壽保單","不適用於人壽保單，除非以彌償形式訂立","不適用於人壽保單，但適用於其他彌償保單","適用於人壽保單的程度與一般保險的索償情況是完全一樣的"],e:"分擔及代位權不適用於人壽保單（除非以彌償形式訂立），但適用於其他彌償保單，故答案為該項，而非「適用於人壽保單的程度與一般保險完全一樣」。"}},
{p:3,ch:"人寿保险简介",q:"制定人寿保险保费率除了三项技术因素外,以下哪些项目同样影响保费率? i 同业的竞争 ii 公众健康的突然或非预期的转变 iii 保险人为提高市场占有率的政策上转变 iv 社会经济环境,尤其在经济衰退时",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:3,e:"除死亡率、开支、利息三项技术因素外，同业竞争、公众健康突变、保险人市场占有率政策及社会经济环境（如衰退）都会影响保费率，故四项皆会影响。",src:1,tw:{ch:"人壽保險簡介",q:"制定人壽保險保費率除了三項技術因素外，以下哪些項目同樣影響保費率？ i 同業的競爭 ii 公眾健康的突然或非預期的轉變 iii 保險人為提高市場佔有率的政策上轉變 iv 社會經濟環境，尤其在經濟衰退時",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"除死亡率、開支、利息三項技術因素外，同業競爭、公眾健康突變、保險人市場佔有率政策及社會經濟環境（如衰退）都會影響保費率，故四項皆會影響。"}},
{p:3,ch:"人寿保险简介",q:"区先生就区太太的生命订立了一份整付保费寿险保单三年后,把该份保单转让予他们的女儿 。再过两年,区太太去世了,而当时这对夫妇已经离婚。请问在根据该份保单索偿时,会产 生下列哪个有关的问题?",o:["区太太对区先生的生命具有可保权益吗?","区太太什么时候必须对区先生的生命具有可保权益?","该份保险合约属无效吗?","区太太对本身的生命具有多少可保权益?"],a:2,e:"可保权益只需在订约时存在（区先生订约时为配偶），故此个案索偿时的关键问题是该保险合约是否属无效，而非区太太对区先生有无可保权益，答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"區先生就區太太的生命訂立了一份整付保費壽險保單三年後，把該份保單轉讓予他們的女兒 。再過兩年，區太太去世了，而當時這對夫婦已經離婚。請問在根據該份保單索償時，會產 生下列哪個有關的問題？",o:["區太太對區先生的生命具有可保權益嗎？","區太太什麼時候必須對區先生的生命具有可保權益？","該份保險合約屬無效嗎？","區太太對本身的生命具有多少可保權益？"],e:"可保權益只需在訂約時存在（區先生訂約時為配偶），故此個案索償時的關鍵問題是該保險合約是否屬無效，而非區太太對區先生有無可保權益，答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"区先生就区太太的生命订立了一份整付保费寿险保单三年后,把该份保单转让予他们的女儿 。再过两年,区太太去世了,而当时这对夫妇已经离婚。请问在根据该份保单索偿时,哪个 问题不可能需要被考虑?",o:["区先生对区太太具有可保权益?","区先生什么时候对区太太必须具有可保权益?","区太太对区先生有多少可保权益?","区先生对区太太有多少可保权益?"],a:2,e:"本个案中被保生命是区太太，须考虑的是区先生对区太太（而非区太太对区先生）的可保权益，故「区太太对区先生有多少可保权益」不可能需要考虑，为该题答案。",src:1,tw:{ch:"人壽保險簡介",q:"區先生就區太太的生命訂立了一份整付保費壽險保單三年後，把該份保單轉讓予他們的女兒 。再過兩年，區太太去世了，而當時這對夫婦已經離婚。請問在根據該份保單索償時，哪個 問題不可能需要被考慮？",o:["區先生對區太太具有可保權益?","區先生什麼時候對區太太必須具有可保權益?","區太太對區先生有多少可保權益?","區先生對區太太有多少可保權益?"],e:"本個案中被保生命是區太太，須考慮的是區先生對區太太（而非區太太對區先生）的可保權益，故「區太太對區先生有多少可保權益」不可能需要考慮，為該題答案。"}},
{p:3,ch:"人寿保险简介",q:"厘定人寿保险保费时,其「充足」的保费定义为?",o:["不必高于所需要的数额","有能力与其他市场的保费率具竞争","使保险人有充足的利润","保险人有足够支付保险利益及合约中的其他责任"],a:3,e:"保费「充足」指保险人有足够款项支付保险利益及合约中的其他责任，故答案为该项；不必过高、具竞争力或确保利润均非「充足」的定义。",src:1,tw:{ch:"人壽保險簡介",q:"釐定人壽保險保費時，其「充足」的保費定義為？",o:["不必高於所需要的數額","有能力與其他市場的保費率具競爭","使保險人有充足的利潤","保險人有足夠支付保險利益及合約中的其他責任"],e:"保費「充足」指保險人有足夠款項支付保險利益及合約中的其他責任，故答案為該項；不必過高、具競爭力或確保利潤均非「充足」的定義。"}},
{p:3,ch:"人寿保险简介",q:"可作为保单抵押贷款的抵押物是:",o:["银行中的存款","保单的现金价值","保单所有人所持的财产","以上各项皆是"],a:1,e:"寿险保单贷款以保单累积的现金价值作为抵押物，故答案为「保单的现金价值」；银行存款及财产并非保单贷款的抵押品。",src:1,tw:{ch:"人壽保險簡介",q:"可作為保單抵押貸款的抵押物是：",o:["銀行中的存款","保單的現金價值","保單所有人所持的財產","以上各項皆是"],e:"壽險保單貸款以保單累積的現金價值作為抵押物，故答案為「保單的現金價值」；銀行存款及財產並非保單貸款的抵押品。"}},
{p:3,ch:"人寿保险简介",q:"可保权益是指某人与「标的」之甚么关系?",o:["最高诚信","法律认可","合约","血缘"],a:1,e:"可保权益指某人与保险标的之间存在的、为「法律认可」的经济关系，故答案为「法律认可」；最高诚信、合约或血缘均非该定义。",src:1,tw:{ch:"人壽保險簡介",q:"可保權益是指某人與「標的」之甚麼關係？",o:["最高誠信","法律認可","合約","血緣"],e:"可保權益指某人與保險標的之間存在的、為「法律認可」的經濟關係，故答案為「法律認可」；最高誠信、合約或血緣均非該定義。"}},
{p:3,ch:"人寿保险简介",q:"在下列哪项中,属于受保保单所有人在没有通知保险人的情况下也没有违反「最高诚信」?",o:["一个存在于脑部肿瘤的事实","欠下高利贷一大笔欠款而遭到死亡恐吓","一项已知的癌症","身体曾经严重受伤"],a:1,e:"脑肿瘤、已知癌症及严重受伤均属影响核保的重要健康事实，应当披露；高利贷欠款属个人财务事务而非健康事实，未通知保险人不构成违反最高诚信，故答案为该项。",src:1,tw:{ch:"人壽保險簡介",q:"在下列哪項中，屬於受保保單所有人在沒有通知保險人的情況下也沒有違反「最高誠信」？",o:["一個存在於腦部腫瘤的事實","欠下高利貸一大筆欠款而遭到死亡恐嚇","一項已知的癌症","身體曾經嚴重受傷"],e:"腦腫瘤、已知癌症及嚴重受傷均屬影響核保的重要健康事實，應當披露；高利貸欠款屬個人財務事務而非健康事實，未通知保險人不構成違反最高誠信，故答案為該項。"}},
{p:3,ch:"人寿保险简介",q:"在厘定人寿保费的传统标准中,其中一项是「公平」,其意思是:",o:["市面上最便宜的","公正的,对投保人来说,是不偏不倚的","足以保证保险人可赚取盈利","低至使保单持有人有能力支付的"],a:1,e:"传统标准的「公平」指保费对投保人公正、不偏不倚（对同类风险公平对待），故答案为该项；最便宜、保证盈利等均不符。",src:1,tw:{ch:"人壽保險簡介",q:"在釐定人壽保費的傳統標準中，其中一項是「公平」，其意思是：",o:["市面上最便宜的","公正的，對投保人來說，是不偏不倚的","足以保證保險人可賺取盈利","低至使保單持有人有能力支付的"],e:"傳統標準的「公平」指保費對投保人公正、不偏不倚（對同類風險公平對待），故答案為該項；最便宜、保證盈利等均不符。"}},
{p:3,ch:"人寿保险简介",q:"在寿险保单中,某人对他人拥有的法律权利,容许前者就此种权利,对后者进行投保,这种 原则称为:",o:["可保权益","弥偿","法律权利","最高诚信"],a:0,e:"某人对他人或财产拥有法律认可的权利并可据此投保的原则，称为可保权益，故答案为「可保权益」；弥偿、法律权利或最高诚信均非该项。",src:1,tw:{ch:"人壽保險簡介",q:"在壽險保單中，某人對他人擁有的法律權利，容許前者就此種權利，對後者進行投保，這種 原則稱為：",o:["可保權益","彌償","法律權利","最高誠信"],e:"某人對他人或財產擁有法律認可的權利並可據此投保的原則，稱為可保權益，故答案為「可保權益」；彌償、法律權利或最高誠信均非該項。"}},
{p:3,ch:"人寿保险简介",q:"在寿险保单中一头重要的原则,要求投保人披露所有重要事实,这种原则称为:",o:["可保权益","弥偿","近因","最高诚信"],a:3,e:"要求投保人披露所有重要事实的寿险原则是最高诚信（最大诚信），故答案为「最高诚信」；可保权益、弥偿及近因均非此概念。",src:1,tw:{ch:"人壽保險簡介",q:"在壽險保單中一頭重要的原則，要求投保人披露所有重要事實，這種原則稱為：",o:["可保權益","彌償","近因","最高誠信"],e:"要求投保人披露所有重要事實的壽險原則是最高誠信（最大誠信），故答案為「最高誠信」；可保權益、彌償及近因均非此概念。"}},
{p:3,ch:"人寿保险简介",q:"在香港,分红人寿保险保单跟随美式保单方式分派红利(dividends)而英式保单中,与「红利 」意义相近的用语是:",o:["「利润」(gain)","「英式红利」(bonuses)","「保单收益」(policy earning)","「利润分红」(profit participation) (a)注"],a:1,e:"香港分红保单沿用美式「红利」(dividends)，英式保单中与红利意义相近的用语是「英式红利」(bonuses)，故答案为该项；利润、保单收益等均非对应用语。",src:1,tw:{ch:"人壽保險簡介",q:"在香港，分紅人壽保險保單跟隨美式保單方式分派紅利(dividends)而英式保單中，與「紅利 」意義相近的用語是：",o:["「利潤」(gain)","「英式紅利」(bonuses)","「保單收益」(policy earning)","「利潤分紅」(profit participation) (a)注"],e:"香港分紅保單沿用美式「紅利」(dividends)，英式保單中與紅利意義相近的用語是「英式紅利」(bonuses)，故答案為該項；利潤、保單收益等均非對應用語。"}},
{p:3,ch:"人寿保险简介",q:"在香港,在血缘关系的家庭成员不存在可保权益,以下哪个是根据「保险业条例」第64A条 所指的例外?",o:["配偶","债权人","祖父","子女(未成年)"],a:3,e:"《保险业条例》第64A条规定，父母对未满18岁的子女拥有可保权益，这是血缘关系中仅有的法定例外；配偶属婚姻关系（非血缘）且同样享有可保权益，债权人属债务关系，祖父对孙辈则无血缘上的法定可保权益。",src:1,tw:{ch:"人壽保險簡介",q:"在香港，在血緣關係的家庭成員不存在可保權益，以下哪個是根據「保險業條例」第64A條 所指的例外？",o:["配偶","債權人","祖父","子女(未成年)"],e:"《保險業條例》第64A條規定，父母對未滿18歲的子女擁有可保權益，這是血緣關係中僅有的法定例外；配偶屬婚姻關係（非血緣）且同樣享有可保權益，債權人屬債務關係，祖父對孫輩則無血緣上的法定可保權益。"}},
{p:3,ch:"人寿保险简介",q:"在香港,在血缘关系的家庭成员不存在可保权益,以下哪个没有可保权益?",o:["17岁的子女","17岁的被监护人","17岁的妹妹","以上皆否"],a:2,e:"根据第64A条，父母对未满18岁子女、监护人对未满18岁被监护人均有可保权益，故17岁子女及17岁被监护人都具备；兄弟姐妹之间并无血缘上的法定可保权益，因此17岁的妹妹没有可保权益。",src:1,tw:{ch:"人壽保險簡介",q:"在香港，在血緣關係的家庭成員不存在可保權益，以下哪個沒有可保權益？",o:["17歲的子女","17歲的被監護人","17歲的妹妹","以上皆否"],e:"根據第64A條，父母對未滿18歲子女、監護人對未滿18歲被監護人均有可保權益，故17歲子女及17歲被監護人都具備；兄弟姐妹之間並無血緣上的法定可保權益，因此17歲的妹妹沒有可保權益。"}},
{p:3,ch:"人寿保险简介",q:"如何计算保险公司的保费,包括死亡率、开支及?",o:["保险公司利润","目前投资利率","投资利息","净边际利润"],a:2,e:"传统人寿保险保费的定价主要依据三大因素，即预期死亡率、投资利息（利率假设）以及营运开支；本题缺失的一项应为投资利息，它反映保险人将预收保费投资所获得的收益对保费的抵减作用。",src:1,tw:{ch:"人壽保險簡介",q:"如何計算保險公司的保費，包括死亡率、開支及?",o:["保險公司利潤","目前投資利率","投資利息","淨邊際利潤"],e:"傳統人壽保險保費的定價主要依據三大因素，即預期死亡率、投資利息（利率假設）以及營運開支；本題缺失的一項應為投資利息，它反映保險人將預收保費投資所獲得的收益對保費的抵減作用。"}},
{p:3,ch:"人寿保险简介",q:"如果形容一名保单所有人对保险合约内的权益是「复归」的,意思是指:",o:["因为所有权的延缓而不能完全享用和获得的财务利益, 直至未来某一时间或特定事件发生后才能完全得到","权益会在缴付了最后一期保费后开始","权益可能在未来某个时候出现","保单所有人急需资金时可使用"],a:0,e:"「复归」（reversionary）权益是指因所有权受到延缓，若干财务利益须待未来某一时间点或特定事件发生后，保单所有人才能完全享用或获得；其余选项所述权益性质与之不符。",src:1,tw:{ch:"人壽保險簡介",q:"如果形容一名保單所有人對保險合約內的權益是「復歸」的，意思是指：",o:["因為所有權的延緩而不能完全享用和獲得的財務利益， 直至未來某一時間或特定事件發生後才能完全得到","權益會在繳付了最後一期保費後開始","權益可能在未來某個時候出現","保單所有人急需資金時可使用"],e:"「復歸」（reversionary）權益是指因所有權受到延緩，若干財務利益須待未來某一時間點或特定事件發生後，保單所有人才能完全享用或獲得；其餘選項所述權益性質與之不符。"}},
{p:3,ch:"人寿保险简介",q:"如果某人的汽车被第三者疏忽地损坏了,那人的汽车保险人先赔偿有关损失,之后向造成汽 车损害的第三者追讨赔偿。这种保险概念叫做:",o:["代位权","弥偿","分担","近因"],a:0,e:"保险人先向被保险人赔偿损失，随后取得以被保险人名义向第三者追偿的权利，此即代位权原则；弥偿指补偿实际损失，分担指多个保险人分摊赔款，近因则是事故原因的判定原则。",src:1,tw:{ch:"人壽保險簡介",q:"如果某人的汽車被第三者疏忽地損壞了，那人的汽車保險人先賠償有關損失，之後向造成汽 車損害的第三者追討賠償。這種保險概念叫做：",o:["代位權","彌償","分擔","近因"],e:"保險人先向被保險人賠償損失，隨後取得以被保險人名義向第三者追償的權利，此即代位權原則；彌償指補償實際損失，分擔指多個保險人分攤賠款，近因則是事故原因的判定原則。"}},
{p:3,ch:"人寿保险简介",q:"妻子就其丈夫的可保权益的限额是:",o:["保额没有上限","以二人之共同资产为上限","以丈夫供养其金额为上限","以丈夫同意她购买的保障为上限"],a:0,e:"香港法例对配偶之间的人寿可保权益不设保额上限，因夫妻关系被视为具有无限利害关系；其他选项以共同资产、供养金额或丈夫同意为限的说法均不符合法律对配偶可保权益的规定。",src:1,tw:{ch:"人壽保險簡介",q:"妻子就其丈夫的可保權益的限額是：",o:["保額沒有上限","以二人之共同資產為上限","以丈夫供養其金額為上限","以丈夫同意她購買的保障為上限"],e:"香港法例對配偶之間的人壽可保權益不設保額上限，因夫妻關係被視為具有無限利害關係；其他選項以共同資產、供養金額或丈夫同意為限的說法均不符合法律對配偶可保權益的規定。"}},
{p:3,ch:"人寿保险简介",q:"寿险保单属利益保单而不是弥偿保单,这是因为:",o:["寿险保单利益支付超越损失金额","保险人及保单持有人均得到合约利益","寿险利益支付大于实际损失金额","寿险利益支付不能用精确财务补偿"],a:3,e:"人的生命价值无法用精确的财务金额衡量，故人寿保险按约定金额给付而非补偿实际损失，属利益保单而非弥偿保单；其余选项混淆了利益保单与弥偿保单的本质区别。",src:1,tw:{ch:"人壽保險簡介",q:"壽險保單屬利益保單而不是彌償保單，這是因為：",o:["壽險保單利益支付超越損失金額","保險人及保單持有人均得到合約利益","壽險利益支付大於實際損失金額","壽險利益支付不能用精確財務補償"],e:"人的生命價值無法用精確的財務金額衡量，故人壽保險按約定金額給付而非補償實際損失，屬利益保單而非彌償保單；其餘選項混淆了利益保單與彌償保單的本質區別。"}},
{p:3,ch:"人寿保险简介",q:"寿险保费的其一个标准是包括「公平」。意思是:",o:["提供最便宜的保费","反映有关的风险及约定利益","年纪越少越要负担高的保费","维护保险公司利益"],a:1,e:"保费标准的「公平」是指保费应与所承保的风险及约定的保险利益相称，使同类风险被保险人负担一致；而非强调最便宜、按年龄高低加重负担或单纯维护保险人利益。",src:1,tw:{ch:"人壽保險簡介",q:"壽險保費的其一個標準是包括「公平」。意思是：",o:["提供最便宜的保費","反映有關的風險及約定利益","年紀越少越要負擔高的保費","維護保險公司利益"],e:"保費標準的「公平」是指保費應與所承保的風險及約定的保險利益相稱，使同類風險被保險人負擔一致；而非強調最便宜、按年齡高低加重負擔或單純維護保險人利益。"}},
{p:3,ch:"人寿保险简介",q:"寿险索偿理据需要根据以下哪项保险原则?",o:["弥偿","代位权","近因","可保权益"],a:2,e:"寿险索偿须先确定导致死亡的直接且有效原因，即依近因原则判断该原因是否属承保范围，这是确定赔偿责任的关键；弥偿、代位权与可保权益虽同属保险原则，但非索偿时判定因果关系所依据的原则。",src:1,tw:{ch:"人壽保險簡介",q:"壽險索償理據需要根據以下哪項保險原則？",o:["彌償","代位權","近因","可保權益"],e:"壽險索償須先確定導致死亡的直接且有效原因，即依近因原則判斷該原因是否屬承保範圍，這是確定賠償責任的關鍵；彌償、代位權與可保權益雖同屬保險原則，但非索償時判定因果關係所依據的原則。"}},
{p:3,ch:"人寿保险简介",q:"就\"损害赔偿\"于人寿保险的应用而言,以下哪三项是正确呢? i 人寿保险是利益保单,而不是弥偿合约 ii 技术上,就任何人的生命出现超额赔偿是不可能的 iii 以大额总数为个人投保,可以提供高于弥偿的金额 iv 以人寿保险为个人提供弥偿是不可能的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"人寿保险是利益（约定给付）保单而非弥偿合约，且就任何人生命而言技术上不可能出现超额赔偿（生命无价），也不可能以人寿保险为个人提供精确「弥偿」；故i、ii、iv正确，而「以高保额提供高于弥偿金额」的说法与利益保单性质混淆而错误。",src:1,tw:{ch:"人壽保險簡介",q:"就\"損害賠償\"於人壽保險的應用而言，以下哪三項是正確呢？ i 人壽保險是利益保單，而不是彌償合約 ii 技術上，就任何人的生命出現超額賠償是不可能的 iii 以大額總數為個人投保，可以提供高於彌償的金額 iv 以人壽保險為個人提供彌償是不可能的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"人壽保險是利益（約定給付）保單而非彌償合約，且就任何人生命而言技術上不可能出現超額賠償（生命無價），也不可能以人壽保險為個人提供精確「彌償」；故i、ii、iv正確，而「以高保額提供高於彌償金額」的說法與利益保單性質混淆而錯誤。"}},
{p:3,ch:"人寿保险简介",q:"就人寿保险而言,由二名保险人分担支付一项损失赔款的情况似乎不大可能。然而,通常在 一般保险中,下列哪项保险原则会导致这种情况的出现?",o:["可保权益","代位权","分担","近因"],a:2,e:"分担原则指同一被保险标的由两名或以上保险人承保时，赔款按比例分摊；在一般保险中常见，而人寿保险因生命价值无法分割且多属利益保单，出现分担的情况极罕有。",src:1,tw:{ch:"人壽保險簡介",q:"就人壽保險而言，由二名保險人分擔支付一項損失賠款的情況似乎不大可能。然而，通常在 一般保險中，下列哪項保險原則會導致這種情況的出現？",o:["可保權益","代位權","分擔","近因"],e:"分擔原則指同一被保險標的由兩名或以上保險人承保時，賠款按比例分攤；在一般保險中常見，而人壽保險因生命價值無法分割且多屬利益保單，出現分擔的情況極罕有。"}},
{p:3,ch:"人寿保险简介",q:"就采用英式寿险制度而非美国寿险制度的保险人,较可能使用以下哪些名称: i 保单红利 ii 有利润保单 iii 分红保单 iv 复归红利",o:["i, ii","ii, iii","ii, iv","iii, iv (a)注"],a:2,e:"英式（英国传统）寿险制度习惯使用「有利润保单」称呼分红保单，并以「复归红利」形式将红利附加于保额；「保单红利」「分红保单」等更接近美式或一般表述，故只选ii、iv。",src:1,tw:{ch:"人壽保險簡介",q:"就採用英式壽險制度而非美國壽險制度的保險人，較可能使用以下哪些名稱： i 保單紅利 ii 有利潤保單 iii 分紅保單 iv 復歸紅利",o:["i, ii","ii, iii","ii, iv","iii, iv (a)注"],e:"英式（英國傳統）壽險制度習慣使用「有利潤保單」稱呼分紅保單，並以「復歸紅利」形式將紅利附加於保額；「保單紅利」「分紅保單」等更接近美式或一般表述，故只選ii、iv。"}},
{p:3,ch:"人寿保险简介",q:"当订立一份人寿保险时,被保险人应先考虑:",o:["保险公司","属于英式红利或红利的保单","符合个人或是商业上的需求","保险支付的货币"],a:2,e:"订立人寿保险时必须先厘清投保目的是符合个人保障需求还是商业（如要员保险、股东保障）需求，再选择合适产品；保险公司、英式/美式红利及货币等属技术细节，应在需求确定后再考虑。",src:1,tw:{ch:"人壽保險簡介",q:"當訂立一份人壽保險時，被保險人應先考慮：",o:["保險公司","屬於英式紅利或紅利的保單","符合個人或是商業上的需求","保險支付的貨幣"],e:"訂立人壽保險時必須先釐清投保目的是符合個人保障需求還是商業（如要員保險、股東保障）需求，再選擇合適產品；保險公司、英式/美式紅利及貨幣等屬技術細節，應在需求確定後再考慮。"}},
{p:3,ch:"人寿保险简介",q:"影响保费率的主要因素是利息,开支及:",o:["死亡率","发病率","盈利能力","公司目标及市场行销策略"],a:0,e:"人寿保险保费率主要受死亡率、利息及开支三项因素影响，三者分别对应风险成本、投资收益与营运负担；发病率主要影响健康险而非寿险，盈利能力及营销策略属经营层面而非定价核心因素。",src:1,tw:{ch:"人壽保險簡介",q:"影響保費率的主要因素是利息，開支及：",o:["死亡率","發病率","盈利能力","公司目標及市場行銷策略"],e:"人壽保險保費率主要受死亡率、利息及開支三項因素影響，三者分別對應風險成本、投資收益與營運負擔；發病率主要影響健康險而非壽險，盈利能力及營銷策略屬經營層面而非定價核心因素。"}},
{p:3,ch:"人寿保险简介",q:"影响保费的计算是死亡率、利息、开支及:",o:["保单的分红/不分红","保险公司目标","经济变化","以上各项"],a:3,e:"除死亡率、利息和开支外，保单分红与否、保险公司经营目标及经济（利率、通胀等）变化都会影响保费计算，故此三项均为影响因素；「以上各项」是对保费影响因素的完整概括。",src:1,tw:{ch:"人壽保險簡介",q:"影響保費的計算是死亡率、利息、開支及：",o:["保單的分紅/不分紅","保險公司目標","經濟變化","以上各項"],e:"除死亡率、利息和開支外，保單分紅與否、保險公司經營目標及經濟（利率、通脹等）變化都會影響保費計算，故此三項均為影響因素；「以上各項」是對保費影響因素的完整概括。"}},
{p:3,ch:"人寿保险简介",q:"投保人对以下哪些人士没有可保权益?",o:["负债人","债主","合伙人","配偶"],a:1,e:"投保人对欠自己钱的人（债务人）享有可保权益，因债务人去世会令债权落空；然而对自己欠钱的人（债主）并无可保权益，债务人去世并不能使债主财产受损，反之债主之死反可解除其债务。合伙人及配偶均有法定可保权益。",src:1,tw:{ch:"人壽保險簡介",q:"投保人對以下哪些人士沒有可保權益？",o:["負債人","債主","合伙人","配偶"],e:"投保人對欠自己錢的人（債務人）享有可保權益，因債務人去世會令債權落空；然而對自己欠錢的人（債主）並無可保權益，債務人去世並不能使債主財產受損，反之債主之死反可解除其債務。合夥人及配偶均有法定可保權益。"}},
{p:3,ch:"人寿保险简介",q:"最初,人寿保险保单是:",o:["并非保障因意外引致之死亡","均属长期性之死亡赔偿安排","祇限于被保生命于特定期限内生存时支付金额","为期短,于特定期限内支付利益"],a:3,e:"历史上最初的人寿保险保单属短期性质，只在特定期限内对死亡或生存给付利益，即定期保障的雏形；而非针对意外死亡、长期死亡赔偿安排或仅限生存的给付。",src:1,tw:{ch:"人壽保險簡介",q:"最初，人壽保險保單是：",o:["並非保障因意外引致之死亡","均屬長期性之死亡賠償安排","祇限於被保生命於特定期限內生存時支付金額","為期短，於特定期限內支付利益"],e:"歷史上最初的人壽保險保單屬短期性質，只在特定期限內對死亡或生存給付利益，即定期保障的雛形；而非針對意外死亡、長期死亡賠償安排或僅限生存的給付。"}},
{p:3,ch:"人寿保险简介",q:"最高诚信是用于所有保险种类,在该原则下,以下哪项是「重要事实」的正确定义?",o:["几乎所有人寿保险对「重要事实」的法律定义作出修改","人寿保险与非人寿保险对「重要事实」有不同的定义","「重要事实」是影响审慎的核保人就一项特定风险承保与否的事实","人寿保险的不可异议条款对「重要事实」有全面的解释"],a:2,e:"在最高诚信原则下，「重要事实」是指会影响一名审慎核保人判断是否承保、以何条件承保的事实；该定义统一适用于各类保险，并非人寿险特有或经不可异议条款修改，也非区分寿险与非寿险的定义差异。",src:1,tw:{ch:"人壽保險簡介",q:"最高誠信是用於所有保險種類，在該原則下，以下哪項是「重要事實」的正確定義？",o:["幾乎所有人壽保險對「重要事實」的法律定義作出修改","人壽保險與非人壽保險對「重要事實」有不同的定義","「重要事實」是影響審慎的核保人就一項特定風險承保與否的事實","人壽保險的不可異議條款對「重要事實」有全面的解釋"],e:"在最高誠信原則下，「重要事實」是指會影響一名審慎核保人判斷是否承保、以何條件承保的事實；該定義統一適用於各類保險，並非人壽險特有或經不可異議條款修改，也非區分壽險與非壽險的定義差異。"}},
{p:3,ch:"人寿保险简介",q:"根据《保险业条例》第64B条指出,任何对受保生命没有可保权益的保单均属:",o:["可使无效的","无效的","得不到保障的","正常的"],a:1,e:"《保险业条例》第64B条规定，对受保生命没有可保权益的人寿保单属无效（void），而非仅可使无效、得不到保障或属正常保单；这体现可保权益是人寿保险合约效力的法定要件。",src:1,tw:{ch:"人壽保險簡介",q:"根據《保險業條例》第64B條指出,任何對受保生命沒有可保權益的保單均屬:",o:["可使無效的","無效的","得不到保障的","正常的"],e:"《保險業條例》第64B條規定，對受保生命沒有可保權益的人壽保單屬無效（void），而非僅可使無效、得不到保障或屬正常保單；這體現可保權益是人壽保險合約效力的法定要件。"}},
{p:3,ch:"人寿保险简介",q:"根据「保险业条例」第64A条指出,下列哪项关系可构成可保权益?",o:["父母及其未满18岁的子女","监护人及其未满18岁的被监护人","丈夫及其妻子","以上各项"],a:3,e:"第64A条明确父母与未满18岁子女、监护人与未满18岁被监护人、丈夫与妻子之间均构成可保权益；因此三项关系皆符合，选「以上各项」。",src:1,tw:{ch:"人壽保險簡介",q:"根據「保險業條例」第64A條指出，下列哪項關係可構成可保權益?",o:["父母及其未滿18歲的子女","監護人及其未滿18歲的被監護人","丈夫及其妻子","以上各項"],e:"第64A條明確父母與未滿18歲子女、監護人與未滿18歲被監護人、丈夫與妻子之間均構成可保權益；因此三項關係皆符合，選「以上各項」。"}},
{p:3,ch:"人寿保险简介",q:"根据传统寿险保费计算方法,保费应可反应有关之风险。描述有关之保费标准为:",o:["可计算的","充足的","公平的","合适的"],a:2,e:"保费应能反映其承保风险的高低，使风险与收费相称，此项标准即为「公平」；「可计算」「充足」「合适」分别强调精算可测、足以赔付及产品适配，与「反映风险」的定价要求对应的是公平。",src:1,tw:{ch:"人壽保險簡介",q:"根據傳統壽險保費計算方法，保費應可反應有關之風險。描述有關之保費標準為：",o:["可計算的","充足的","公平的","合適的"],e:"保費應能反映其承保風險的高低，使風險與收費相稱，此項標準即為「公平」；「可計算」「充足」「合適」分別強調精算可測、足以賠付及產品適配，與「反映風險」的定價要求對應的是公平。"}},
{p:3,ch:"人寿保险简介",q:"根据传统寿险保费计算方法,保费应可应付有关成本,并可反应有关之风险。描述有关之保 费标准为:",o:["公平及公正的","公平及充足的","充足及公平(公正)的","充足及合适的"],a:2,e:"保费须足以应付相关成本（充足），同时又能真实反映所承保的风险（公平/公正）；故本题描述对应「充足及公平」标准，「合适」并非传统保费计算的专门标准。",src:1,tw:{ch:"人壽保險簡介",q:"根據傳統壽險保費計算方法，保費應可應付有關成本，並可反應有關之風險。描述有關之保 費標準為：",o:["公平及公正的","公平及充足的","充足及公平(公正)的","充足及合適的"],e:"保費須足以應付相關成本（充足），同時又能真實反映所承保的風險（公平/公正）；故本題描述對應「充足及公平」標準，「合適」並非傳統保費計算的專門標準。"}},
{p:3,ch:"人寿保险简介",q:"根据可保权益,一个人可为以下哪三项人士购买保险: i 配偶 ii 自己十岁的子女 iii 欠自己钱的人(债仔) iv 自己欠他钱的人(债主)",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],a:0,e:"个人对配偶、自己未成年子女以及欠自己钱的人（债务人）均有可保权益，可为其投保；但对自己欠钱的人（债主）并无可保权益，因为债务人的身份使债主去世反而免其债务，故iv不能选。",src:1,tw:{ch:"人壽保險簡介",q:"根據可保權益，一個人可為以下哪三項人士購買保險： i 配偶 ii 自己十歲的子女 iii 欠自己錢的人(債仔) iv 自己欠他錢的人(債主)",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],e:"個人對配偶、自己未成年子女以及欠自己錢的人（債務人）均有可保權益，可為其投保；但對自己欠錢的人（債主）並無可保權益，因為債務人的身份使債主去世反而免其債務，故iv不能選。"}},
{p:3,ch:"人寿保险简介",q:"根据最高诚信的保险原则,以下哪项是重要事实的正确描述?",o:["与实际物件(财产)保险的事实","向保险人披露的非重要事实","会影响一名审慎的核保人订定保费或决定是否承担风险方面的事实","可能会影响一名审慎的核保人订定保费或决定是否承担风险方面的事实"],a:2,e:"「重要事实」是指足以影响审慎核保人订定保费或决定是否承担风险的事实，这是最高诚信原则下投保人须主动披露的核心内容；其余选项或以财产保险事实、非重要事实或「可能影响」等措辞混淆其严格定义。",src:1,tw:{ch:"人壽保險簡介",q:"根據最高誠信的保險原則，以下哪項是重要事實的正確描述？",o:["與實際物件(財產)保險的事實","向保險人披露的非重要事實","會影響一名審慎的核保人訂定保費或決定是否承擔風險方面的事實","可能會影響一名審慎的核保人訂定保費或決定是否承擔風險方面的事實"],e:"「重要事實」是指足以影響審慎核保人訂定保費或決定是否承擔風險的事實，這是最高誠信原則下投保人須主動披露的核心內容；其餘選項或以財產保險事實、非重要事實或「可能影響」等措辭混淆其嚴格定義。"}},
{p:3,ch:"人寿保险简介",q:"根据香港法例,任何人士对以下人士皆有可保权益,除了:",o:["自己","自己与十七岁的配偶","自己与年介十七岁的儿女","自己与年介十七岁的兄弟"],a:3,e:"根据香港法例，任何人对自己、配偶及未成年子女（十七岁儿女未满18岁）均有可保权益；但兄弟姐妹之间并无血缘上的法定可保权益，故对十七岁的兄弟不享有可保权益。",src:1,tw:{ch:"人壽保險簡介",q:"根據香港法例，任何人士對以下人士皆有可保權益，除了：",o:["自己","自己與十七歲的配偶","自己與年介十七歲的兒女","自己與年介十七歲的兄弟"],e:"根據香港法例，任何人對自己、配偶及未成年子女（十七歲兒女未滿18歲）均有可保權益；但兄弟姐妹之間並無血緣上的法定可保權益，故對十七歲的兄弟不享有可保權益。"}},
{p:3,ch:"人寿保险简介",q:"根据香港法律,如果一个人(甲)对另一个人(乙)的生命享有可保权益,而甲就乙的生命安排一 份保险,那么:",o:["该份保单便属无效","甲的姓名必须于该保单内注明","利益必须给付乙","该份保单必属不分红的"],a:1,e:"若甲对乙的生命享有可保权益并就乙的生命投保，甲作为保单的利害关系人，其姓名必须于保单内注明；保单并非因此无效，利益是给付甲的受益人而非乙，保单分红与否与可保权益无关。",src:1,tw:{ch:"人壽保險簡介",q:"根據香港法律，如果一個人(甲)對另一個人(乙)的生命享有可保權益，而甲就乙的生命安排一 份保險，那麼：",o:["該份保單便屬無效","甲的姓名必須於該保單內註明","利益必須給付乙","該份保單必屬不分紅的"],e:"若甲對乙的生命享有可保權益並就乙的生命投保，甲作為保單的利害關係人，其姓名必須於保單內註明；保單並非因此無效，利益是給付甲的受益人而非乙，保單分紅與否與可保權益無關。"}},
{p:3,ch:"人寿保险简介",q:"死亡表的功能是: i 显示不同年龄的预期死亡比率的计算表 ii 计算预期及营运开支 iii 计算新型疾病及灾难的可能性的死亡率 iv 利用死亡表厘定费率,只是应付正常风险和正常预期",o:["i, iii, iv","i, ii, iv","i, iv","以上皆是"],a:2,e:"死亡表（生命表）的作用是显示不同年龄的预期死亡率以供厘定费率，且其厘定仅针对正常风险与正常预期；计算营运开支属开支而非死亡表功能，预测新型疾病或灾难也超出死亡表范畴，故只选i、iv。",src:1,tw:{ch:"人壽保險簡介",q:"死亡表的功能是: i 顯示不同年齡的預期死亡比率的計算表 ii 計算預期及營運開支 iii 計算新型疾病及災難的可能性的死亡率 iv 利用死亡表釐定費率，只是應付正常風險和正常預期",o:["i, iii, iv","i, ii, iv","i, iv","以上皆是"],e:"死亡表（生命表）的作用是顯示不同年齡的預期死亡率以供釐定費率，且其釐定僅針對正常風險與正常預期；計算營運開支屬開支而非死亡表功能，預測新型疾病或災難也超出死亡表範疇，故只選i、iv。"}},
{p:3,ch:"人寿保险简介",q:"毛保费是什么项目加上附加保费?",o:["净保费","利息","死亡率","附加保费,利息和死亡率"],a:0,e:"毛保费（总保费）等于净保费加上附加保费，其中净保费对应纯风险成本，附加保费涵盖开支、利润等；其他选项将利息、死亡率等混入附加保费结构之中，均不正确。",src:1,tw:{ch:"人壽保險簡介",q:"毛保費是什麼項目加上附加保費？",o:["淨保費","利息","死亡率","附加保費，利息和死亡率"],e:"毛保費（總保費）等於淨保費加上附加保費，其中淨保費對應純風險成本，附加保費涵蓋開支、利潤等；其他選項將利息、死亡率等混入附加保費結構之中，均不正確。"}},
{p:3,ch:"人寿保险简介",q:"甚么是「不能作废」条款?",o:["当保单已生效超过两年,保险人无权取消保单","当续保保费尚未缴交,现金价值可用以保持保单有效性","保单所有人在没有保险人的同意下无权终止保单","当保单已全部索偿,保单仍继续生效"],a:1,e:"「不能作废」（亦称不丧失价值）条款规定，当续保保费未缴交时，可动用保单现金价值自动垫付保费以维持保单效力；其余选项分别涉及不可异议、保单终止权及终止后的效力，与本条款无关。",src:1,tw:{ch:"人壽保險簡介",q:"甚麼是「不能作廢」條款？",o:["當保單已生效超過兩年，保險人無權取消保單","當續保保費尚未繳交，現金價值可用以保持保單有效性","保單所有人在沒有保險人的同意下無權終止保單","當保單已全部索償，保單仍繼續生效"],e:"「不能作廢」（亦稱不喪失價值）條款規定，當續保保費未繳交時，可動用保單現金價值自動墊付保費以維持保單效力；其餘選項分別涉及不可異議、保單終止權及終止後的效力，與本條款無關。"}},
{p:3,ch:"人寿保险简介",q:"美式保单的「现金红利」可即时使用,而英式「有利润」保单可在何时使用?",o:["即时","支付保险利益时","待保险人同意时","保单所有人急需资金时 (a)注"],a:1,e:"美式保单的现金红利可即时提取使用，而英式「有利润」保单的红利以复归红利形式附加于保额，须待支付保险利益（身故或期满）时才一并给付，故不能即时、由保险人同意或急需资金时使用。",src:1,tw:{ch:"人壽保險簡介",q:"美式保單的「現金紅利」可即時使用，而英式「有利潤」保單可在何時使用？",o:["即時","支付保險利益時","待保險人同意時","保單所有人急需資金時 (a)注"],e:"美式保單的現金紅利可即時提取使用，而英式「有利潤」保單的紅利以復歸紅利形式附加於保額，須待支付保險利益（身故或期滿）時才一併給付，故不能即時、由保險人同意或急需資金時使用。"}},
{p:3,ch:"人寿保险简介",q:"若一名保单所有人在两年前购买一份人寿保单(有分红性质),而事隔两年后,他再购买另一 份为期5年的定期寿险计划,在半年后,该投保人身亡。若以上两份保单仍生效的话:",o:["只赔偿保额较高的一份保单的保额","两张保单全数赔偿","视乎保险公司当时的决定","只赔偿有分红性质的一份"],a:1,e:"人寿保险以约定保额给付且不同保单利益可叠加，若两份保单（分红终身寿险与定期寿险）均在生效期内，则死亡时两张保单各自全数赔偿，不存在仅赔较高者或由保险公司决定的情形。",src:1,tw:{ch:"人壽保險簡介",q:"若一名保單所有人在兩年前購買一份人壽保單(有分紅性質)，而事隔兩年後，他再購買另一 份為期5年的定期壽險計劃，在半年後,該投保人身亡。若以上兩份保單仍生效的話：",o:["只賠償保額較高的一份保單的保額","兩張保單全數賠償","視乎保險公司當時的決定","只賠償有分紅性質的一份"],e:"人壽保險以約定保額給付且不同保單利益可疊加，若兩份保單（分紅終身壽險與定期壽險）均在生效期內，則死亡時兩張保單各自全數賠償，不存在僅賠較高者或由保險公司決定的情形。"}},
{p:3,ch:"人寿保险简介",q:"英式的保单对分红保单的名称是:",o:["公平保单","有利润保单","赚取利润保单","赚取红利保单 (a)注"],a:1,e:"在英式（英国传统）寿险制度中，参与利润分配的保单称为「有利润保单」，其红利多以复归红利形式附加于保额；「公平保单」「赚取利润保单」「赚取红利保单」均非英式分红保单的标准名称。",src:1,tw:{ch:"人壽保險簡介",q:"英式的保單對分紅保單的名稱是：",o:["公平保單","有利潤保單","賺取利潤保單","賺取紅利保單 (a)注"],e:"在英式（英國傳統）壽險制度中，參與利潤分配的保單稱為「有利潤保單」，其紅利多以復歸紅利形式附加於保額；「公平保單」「賺取利潤保單」「賺取紅利保單」均非英式分紅保單的標準名稱。"}},
{p:3,ch:"人寿保险简介",q:"英式的有利润保单并不设红利,取之代之,往往他们会把红利附加于应付的保额上提供,这 种英式红利称为:",o:["延期红利","未来的现金","复归红利","非即时红利 (a)注"],a:2,e:"英式有利润保单不设现金红利，而是把红利附加于应付保额上待支付利益时一并给付，这种红利称为「复归红利」；「延期红利」「未来的现金」「非即时红利」均非其标准名称。",src:1,tw:{ch:"人壽保險簡介",q:"英式的有利潤保單並不設紅利，取之代之，往往他們會把紅利附加於應付的保額上提供，這 種英式紅利稱為：",o:["延期紅利","未來的現金","復歸紅利","非即時紅利 (a)注"],e:"英式有利潤保單不設現金紅利，而是把紅利附加於應付保額上待支付利益時一併給付，這種紅利稱為「復歸紅利」；「延期紅利」「未來的現金」「非即時紅利」均非其標準名稱。"}},
{p:3,ch:"人寿保险简介",q:"要进行保单贷款,需要的抵押品是:",o:["一笔现金作按金","保单的现金价值","股票或其他有形资产","现金存款"],a:1,e:"保单贷款以保单的现金价值作为抵押品，保险人据现金价值的一定比例发放贷款；现金按金、股票及现金存款等并非寿险保单贷款的指定抵押品。",src:1,tw:{ch:"人壽保險簡介",q:"要進行保單貸款，需要的抵押品是：",o:["一筆現金作按金","保單的現金價值","股票或其他有形資產","現金存款"],e:"保單貸款以保單的現金價值作為抵押品，保險人據現金價值的一定比例發放貸款；現金按金、股票及現金存款等並非壽險保單貸款的指定抵押品。"}},
{p:3,ch:"人寿保险简介",q:"近因与不同类型的危险关系密切,而对于以下哪一项的描述是正确的的?",o:["人寿保险中包含指明的受保危险","人寿保险中除外危险并不适用","人寿保险中不受到不保危险的限制","各类危险对于人寿保险的应用是有限的 (a)注"],a:3,e:"近因与危险类型的划分密切相关，但各类危险（受保、除外、不保危险）对人寿保险的实际应用相对有限，因寿险通常承保任何原因的死亡；故「各类危险对于人寿保险的应用是有限的」描述正确。",src:1,tw:{ch:"人壽保險簡介",q:"近因與不同類型的危險關係密切，而對於以下哪一項的描述是正確的的？",o:["人壽保險中包含指明的受保危險","人壽保險中除外危險並不適用","人壽保險中不受到不保危險的限制","各類危險對於人壽保險的應用是有限的 (a)注"],e:"近因與危險類型的劃分密切相關，但各類危險（受保、除外、不保危險）對人壽保險的實際應用相對有限，因壽險通常承保任何原因的死亡；故「各類危險對於人壽保險的應用是有限的」描述正確。"}},
{p:3,ch:"人寿保险简介",q:"近因原则:",o:["永不适用于人寿保险的索偿","可能重要,尤其怀疑保险人自杀时,对人寿保险则变得重要","唯有已附加意外死亡保险利益附约的人寿保险才适用","一般情况下均适用于人寿保险的索偿"],a:1,e:"近因原则一般在人寿保险索偿中应用有限，但若涉及被保险人在保单初期自杀等情形时，判断死亡近因就变得重要；故该原则并非永不适用，也非仅当附加意外死亡附约时才适用，或一般情况下均适用。",src:1,tw:{ch:"人壽保險簡介",q:"近因原則：",o:["永不適用於人壽保險的索償","可能重要，尤其懷疑保險人自殺時，對人壽保險則變得重要","唯有已附加意外死亡保險利益附約的人壽保險才適用","一般情況下均適用於人壽保險的索償"],e:"近因原則一般在人壽保險索償中應用有限，但若涉及被保險人在保單初期自殺等情形時，判斷死亡近因就變得重要；故該原則並非永不適用，也非僅當附加意外死亡附約時才適用，或一般情況下均適用。"}},
{p:3,ch:"人寿保险简介",q:"采用英式惯例之保险,意义与分红保单相同的保单为:",o:["有利润保单","赚取利润保单","赚取红利保单","以上各项皆是 (a)注"],a:0,e:"采用英式惯例的保险中，与「分红保单」意义相同的称呼是「有利润保单」，即以复归红利形式参与利润分配；「赚取利润保单」「赚取红利保单」并非英式制度的规范名称。",src:1,tw:{ch:"人壽保險簡介",q:"採用英式慣例之保險，意義與分紅保單相同的保單為：",o:["有利潤保單","賺取利潤保單","賺取紅利保單","以上各項皆是 (a)注"],e:"採用英式慣例的保險中，與「分紅保單」意義相同的稱呼是「有利潤保單」，即以復歸紅利形式參與利潤分配；「賺取利潤保單」「賺取紅利保單」並非英式制度的規範名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「万用寿险」的特征是:",o:["灵活保费","可调整保险利益","具有「分别列示各定价因素」的定价结构","以上各项皆是"],a:3,e:"万用寿险同时具备灵活保费、可调整保险利益以及「分别列示各定价因素」的透明定价结构三项特征，故「以上各项皆是」正确概括了其特色。",src:1,tw:{ch:"人壽保險及年金的種類",q:"「萬用壽險」的特徵是：",o:["靈活保費","可調整保險利益","具有「分別列示各定價因素」的定價結構","以上各項皆是"],e:"萬用壽險同時具備靈活保費、可調整保險利益以及「分別列示各定價因素」的透明定價結構三項特徵，故「以上各項皆是」正確概括了其特色。"}},
{p:3,ch:"人寿保险及年金的种类",q:"「分别列示各定价因素」显示在给保单持有人的年报中,这年报出现在:",o:["只有万用寿险","只有储蓄寿险","只有投资相连保险","万用寿险和投资相连保险"],a:0,e:"「分别列示各定价因素」（分别披露死亡成本、利息、开支）的透明定价结构及年报制度是万用寿险独有的特点；储蓄寿险与投资相连保险不采用此种定价披露方式，故仅万用寿险。",src:1,tw:{ch:"人壽保險及年金的種類",q:"「分別列示各定價因素」顯示在給保單持有人的年報中，這年報出現在：",o:["只有萬用壽險","只有儲蓄壽險","只有投資相連保險","萬用壽險和投資相連保險"],e:"「分別列示各定價因素」（分別披露死亡成本、利息、開支）的透明定價結構及年報制度是萬用壽險獨有的特點；儲蓄壽險與投資相連保險不採用此種定價披露方式，故僅萬用壽險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一个人想于离世时获得一笔不多于也不少于100万的赔偿,该金额是用来送赠给曾就读的大学。 以最经济的角度考虑,以下哪种产品是最适合?",o:["不分红的终身寿险","分红的终身寿险","不分红的储蓄寿险","分红的储蓄寿险"],a:0,e:"需求是离世时定额给付100万元作捐款，不分红终身寿险保证任何时间死亡均给付固定金额且保费较分红型低，最符合经济原则；分红型保费较高，储蓄寿险偏重期满给付而非终身确定保额。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一個人想於離世時獲得一筆不多於也不少於100萬的賠償，該金額是用來送贈給曾就讀的大學。 以最經濟的角度考慮，以下哪種產品是最適合？",o:["不分紅的終身壽險","分紅的終身壽險","不分紅的儲蓄壽險","分紅的儲蓄壽險"],e:"需求是離世時定額給付100萬元作捐款，不分紅終身壽險保證任何時間死亡均給付固定金額且保費較分紅型低，最符合經濟原則；分紅型保費較高，儲蓄壽險偏重期滿給付而非終身確定保額。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一个人的寿险需要不会增加或减少,在一段指定时间之后就不会再有需要,如果以保险成本为最 大的考虑因素,以下哪种寿险最不可取?",o:["定额定期寿险","可转换定期寿险","分红储蓄寿险","不分红储蓄寿险"],a:2,e:"当寿险需要在一段固定期间后消失且以成本为最大考量时，应以定期寿险为主，储蓄寿险因含储蓄、退保价值而保费高昂，其中最不可取的是分红储蓄寿险（保费最高）；可转换定期寿险仍属低成本定期保障。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一個人的壽險需要不會增加或減少，在一段指定時間之後就不會再有需要，如果以保險成本為最 大的考慮因素，以下哪種壽險最不可取？",o:["定額定期壽險","可轉換定期壽險","分紅儲蓄壽險","不分紅儲蓄壽險"],e:"當壽險需要在一段固定期間後消失且以成本為最大考量時，應以定期壽險為主，儲蓄壽險因含儲蓄、退保價值而保費高昂，其中最不可取的是分紅儲蓄壽險（保費最高）；可轉換定期壽險仍屬低成本定期保障。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一个人的寿险需要不会增加或减少,大多数情况下没有出现索偿,属于以下哪种寿险?",o:["定额定期寿险","可转换定期寿险","分红储蓄寿险","不分红储蓄寿险"],a:0,e:"保险需要固定不变且多数情况不会发生索偿，正对应定额定期寿险——在指定期间内保额不变、保费低廉，期满通常无索偿；可转换或储蓄寿险保费较高，不符合此低成本纯保障特征。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一個人的壽險需要不會增加或減少，大多數情況下沒有出現索償，屬於以下哪種壽險？",o:["定額定期壽險","可轉換定期壽險","分紅儲蓄壽險","不分紅儲蓄壽險"],e:"保險需要固定不變且多數情況不會發生索償，正對應定額定期壽險——在指定期間內保額不變、保費低廉，期滿通常無索償；可轉換或儲蓄壽險保費較高，不符合此低成本純保障特徵。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一份不分红终身寿险:",o:["不论任何时候出现的死亡,均会给付保额","只会在指定期间结束时才支付保单利益","于受保生命仍然在世期间给付指定的红利","只会在指定时期内的死亡支付赔偿"],a:0,e:"不分红终身寿险是对任何时间发生的死亡均给付保额的终身保障，但不分配红利；其余选项描述的是定期寿险或储蓄寿险的给付条件，与终身寿险不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一份不分紅終身壽險：",o:["不論任何時候出現的死亡，均會給付保額","只會在指定期間結束時才支付保單利益","於受保生命仍然在世期間給付指定的紅利","只會在指定時期內的死亡支付賠償"],e:"不分紅終身壽險是對任何時間發生的死亡均給付保額的終身保障，但不分配紅利；其餘選項描述的是定期壽險或儲蓄壽險的給付條件，與終身壽險不符。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一份保单被描述为连续缴费终身寿险,它含有下列哪项描述?",o:["只需缴交一份保费","整段保险期间保费固定","终身缴付保费","终身缴付保费即使受保生命已经死亡"],a:2,e:"连续缴费（终身缴费）终身寿险的特点是保费在整个保险期间持续缴付直至受保人身故，「终身缴付保费」为其正确定义；其余选项分别描述整付、保费固定或死亡后仍缴费等错误情形。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一份保單被描述為連續繳費終身壽險，它含有下列哪項描述？",o:["只需繳交一份保費","整段保險期間保費固定","終身繳付保費","終身繳付保費即使受保生命已經死亡"],e:"連續繳費（終身繳費）終身壽險的特點是保費在整個保險期間持續繳付直至受保人身故，「終身繳付保費」為其正確定義；其餘選項分別描述整付、保費固定或死亡後仍繳費等錯誤情形。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一份没有指明期限,只会在受保生命身故时赔偿保险利益的保单称为",o:["定期寿险","储蓄寿险","终身寿验","纯生存保险"],a:2,e:"没有指定期限、只在受保人身故时才赔偿保额的保单是终身寿险；定期寿险有时限，储蓄寿险期满或身故均给付，纯生存保险仅生存至期满才给付。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一份沒有指明期限，只會在受保生命身故時賠償保險利益的保單稱為",o:["定期壽險","儲蓄壽險","終身壽驗","純生存保險"],e:"沒有指定期限、只在受保人身故時才賠償保額的保單是終身壽險；定期壽險有時限，儲蓄壽險期滿或身故均給付，純生存保險僅生存至期滿才給付。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一只具有「分别列示各定价因素」的定价结构及每年必须提供年报的寿险产品叫:",o:["万用寿险","纯生存保险","终身寿险","定期寿险"],a:0,e:"具有「分别列示各定价因素」的定价结构，并规定每年须向保单持有人提供年报的产品是万用寿险；纯生存保险、终身寿险与定期寿险均无此定价与年报要求。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一隻具有「分別列示各定價因素」的定價結構及每年必須提供年報的壽險產品叫：",o:["萬用壽險","純生存保險","終身壽險","定期壽險"],e:"具有「分別列示各定價因素」的定價結構，並規定每年須向保單持有人提供年報的產品是萬用壽險；純生存保險、終身壽險與定期壽險均無此定價與年報要求。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一对已婚夫妇的延期年金最高可享的扣除金额:",o:["60,000","80,000","100,000","120,000"],a:3,e:"香港合资格延期年金保费可享税务扣除，每名纳税人每年最高60,000港元，夫妇共同报税合计最高可达120,000港元；其余金额均非夫妇的合计扣除上限。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一對已婚夫婦的延期年金最高可享的扣除金額:",o:["60,000","80,000","100,000","120,000"],e:"香港合資格延期年金保費可享税務扣除，每名納税人每年最高60,000港元，夫婦共同報税合計最高可達120,000港元；其餘金額均非夫婦的合計扣除上限。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种与其他于逝世时一笔过赔偿的保单计划互相结合,并于指明时期的剩余时间内每月支付指定 金额,称为:",o:["万用寿险","家庭收入寿险","抵押赎回保险","递减定期寿险"],a:1,e:"家庭收入寿险与一笔过死亡赔偿保单结合，在被保险人身故后于指定期间剩余时间内按月支付固定金额，为家庭提供持续收入；万用、抵押赎回及递减定期寿险均不具按月给付收入的特点。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種與其他於逝世時一筆過賠償的保單計劃互相結合，並於指明時期的剩餘時間內每月支付指定 金額，稱為：",o:["萬用壽險","家庭收入壽險","抵押贖回保險","遞減定期壽險"],e:"家庭收入壽險與一筆過死亡賠償保單結合，在被保險人身故後於指定期間剩餘時間內按月支付固定金額，為家庭提供持續收入；萬用、抵押贖回及遞減定期壽險均不具按月給付收入的特點。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种向消费者提供更多选择和灵活性的寿险称为:",o:["递减定期寿险","连续缴费终身寿险","万用寿险","抵押赎回保险"],a:2,e:"万用寿险以灵活保费、可调整保额及透明定价向消费者提供更多选择与灵活性；递减定期寿险、连续缴费终身寿险及抵押赎回保险均不具备这样的弹性机制。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種向消費者提供更多選擇和靈活性的壽險稱為：",o:["遞減定期壽險","連續繳費終身壽險","萬用壽險","抵押贖回保險"],e:"萬用壽險以靈活保費、可調整保額及透明定價向消費者提供更多選擇與靈活性；遞減定期壽險、連續繳費終身壽險及抵押贖回保險均不具備這樣的彈性機制。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种团体保险可让多间不同的公司一同参加,该种保险称为:",o:["综合团体 (Joint groups)","多个雇主团体保险 (Multiple-employer groups)","独立雇主团体保险 (Independent employer groups)","非单一雇主团体保险 (More-than-one employer groups)"],a:1,e:"容许数间不同公司（雇主）共同参加的团体保险称为「多个雇主团体保险」（Multiple-employer groups）；其余选项的表述并非该类团体保险的标准名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種團體保險可讓多間不同的公司一同參加，該種保險稱為：",o:["綜合團體 (Joint groups)","多個僱主團體保險 (Multiple-employer groups)","獨立僱主團體保險 (Independent employer groups)","非單一僱主團體保險 (More-than-one employer groups)"],e:"容許數間不同公司（僱主）共同參加的團體保險稱為「多個僱主團體保險」（Multiple-employer groups）；其餘選項的表述並非該類團體保險的標準名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种定期寿险计划,于指定时期内死亡便会获得所述金额,这种计划称为:",o:["定额定期寿险","相同的定期寿险","递减定期寿险","非递减定期寿险"],a:0,e:"在指定期间内死亡即按约定金额给付、保额不变的定期保障是「定额定期寿险」；「相同的定期寿险」及「非递减定期寿险」非标准名称，递减定期寿险保额则逐年下降。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種定期壽險計劃，於指定時期內死亡便會獲得所述金額，這種計劃稱為：",o:["定額定期壽險","相同的定期壽險","遞減定期壽險","非遞減定期壽險"],e:"在指定期間內死亡即按約定金額給付、保額不變的定期保障是「定額定期壽險」；「相同的定期壽險」及「非遞減定期壽險」非標準名稱，遞減定期壽險保額則逐年下降。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种寿险计划只会于受保生命在特定期间内死亡时作出赔偿,而死亡时间并不影响赔偿金额。这 种计划是:",o:["终身寿险","定额定期寿险","定期保障计划","不变动保险"],a:1,e:"只在受保生命于特定期间内死亡时赔偿、且死亡时间不影响赔偿金额的计划是定额定期寿险；其保额在整个期间保持不变，符合「死亡时间不影响金额」的描述。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種壽險計劃只會於受保生命在特定期間內死亡時作出賠償，而死亡時間並不影響賠償金額。這 種計劃是：",o:["終身壽險","定額定期壽險","定期保障計劃","不變動保險"],e:"只在受保生命於特定期間內死亡時賠償、且死亡時間不影響賠償金額的計劃是定額定期壽險；其保額在整個期間保持不變，符合「死亡時間不影響金額」的描述。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种年金通常以整付方式购买,年金利益于年金购买后的第一个年金期间完结时便支付,这称为 :",o:["即时年金","特快年金","即期年金","连续年金"],a:2,e:"以整付保费购买、且年金利益在购买后第一个年金期间完结时即开始支付的是「即期年金」；与延期年金（付款延至指定年龄或时间后才开始）相对，特快、连续年金均非标准分类。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種年金通常以整付方式購買，年金利益於年金購買後的第一個年金期間完結時便支付，這稱為 ：",o:["即時年金","特快年金","即期年金","連續年金"],e:"以整付保費購買、且年金利益在購買後第一個年金期間完結時即開始支付的是「即期年金」；與延期年金（付款延至指定年齡或時間後才開始）相對，特快、連續年金均非標準分類。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种非常罕有的保险,只在受保生命在保险期结束时仍然生存的情况下,才支付保险利益的合约 ,即是:",o:["定期寿险","储蓄寿险","即期年金","纯生存保险"],a:3,e:"只在受保生命于保险期结束时仍然生存才支付保险利益的合约是「纯生存保险」；定期寿险只保死亡，储蓄寿险身故或期满均给付，即期年金则是分期给付的退休收入产品，故均不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種非常罕有的保險，只在受保生命在保險期結束時仍然生存的情況下，才支付保險利益的合約 ，即是：",o:["定期壽險","儲蓄壽險","即期年金","純生存保險"],e:"只在受保生命於保險期結束時仍然生存才支付保險利益的合約是「純生存保險」；定期壽險只保死亡，儲蓄壽險身故或期滿均給付，即期年金則是分期給付的退休收入產品，故均不符。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险在保单生效第二年开始,保费:",o:["便不能更改","只可增加,不可减少","只可减少,不可增加","可以高于或低于协定保费"],a:3,e:"万用寿险保费灵活，首年过后保单所有人可在条款限制内缴交高于或低于协定水平的保费；并非此后不可更改，或只可单方面增加、减少。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險在保單生效第二年開始，保費：",o:["便不能更改","只可增加，不可減少","只可減少，不可增加","可以高於或低於協定保費"],e:"萬用壽險保費靈活，首年過後保單所有人可在條款限制內繳交高於或低於協定水平的保費；並非此後不可更改，或只可單方面增加、減少。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的保单所有人,每年均会收到一份说明保单状况的年报,内容不包括:",o:["选定的死亡保险金选择","已加入现金价值的保证利息及额外利息","已扣除的保险纯成本","基金价格"],a:3,e:"万用寿险年报说明保单状况，内容包括涉保额、利息、死亡成本等分别列示的定价因素，但不包含「基金价格」，因基金报价属投资相连产品；故「基金价格」为年报所不含的项目。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的保單所有人，每年均會收到一份說明保單狀況的年報，內容不包括：",o:["選定的死亡保險金選擇","已加入現金價值的保證利息及額外利息","已扣除的保險純成本","基金價格"],e:"萬用壽險年報說明保單狀況，內容包括涉保額、利息、死亡成本等分別列示的定價因素，但不包含「基金價格」，因基金報價屬投資相連產品；故「基金價格」為年報所不含的項目。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的保单所有人,每年均会收到一份说明保单状况的年报,内容包括:",o:["支付的保费","选定的死亡保险金选择","已加入现金价值的保证利息及额外利息","以上皆是"],a:3,e:"万用寿险年报须向保单持有人分别披露已缴纳保费、所选死亡保险金选项，以及加入现金价值的保证利息与额外利息等内容；此三项均属年报内容，故选「以上皆是」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的保單所有人，每年均會收到一份說明保單狀況的年報，內容包括：",o:["支付的保費","選定的死亡保險金選擇","已加入現金價值的保證利息及額外利息","以上皆是"],e:"萬用壽險年報須向保單持有人分別披露已繳納保費、所選死亡保險金選項，以及加入現金價值的保證利息與額外利息等內容；此三項均屬年報內容，故選「以上皆是」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的保额的调整是:",o:["无须提供可保证明","若减少保额,必须提供可保证明","若增加保额,必须提供可保证明","如保额增加后两年内作出赔偿,便视为无效"],a:2,e:"万用寿险调整保额时，若增加保额须提供可保证明（以控制逆选择），减少保额则通常不需；无须提供证明或增加后两年内赔偿即无效的说法均不符规则。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的保額的調整是：",o:["無須提供可保証明","若減少保額，必須提供可保証明","若增加保額，必須提供可保証明","如保額增加後兩年內作出賠償，便視為無效"],e:"萬用壽險調整保額時，若增加保額須提供可保證明（以控制逆選擇），減少保額則通常不需；無須提供證明或增加後兩年內賠償即無效的說法均不符規則。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的年度报告会送交:",o:["保险业监管局","有关的保单所有人","保险人的董事局","香港金融管理局"],a:1,e:"万用寿险的年度报告（说明保单状况及分别列示定价因素的报表）是送交有关保单所有人的，以便其了解保单运作；并非送交监管机构、保险人董事局或金融管理局。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的年度報告會送交：",o:["保險業監管局","有關的保單所有人","保險人的董事局","香港金融管理局"],e:"萬用壽險的年度報告（說明保單狀況及分別列示定價因素的報表）是送交有關保單所有人的，以便其瞭解保單運作；並非送交監管機構、保險人董事局或金融管理局。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的年报为了提供有关基本摘要,但万用寿险的年报提供给谁?",o:["年金购买人","保单持有人","证监会总监","保险业监管局"],a:1,e:"万用寿险的年报旨在向保单持有人提供保单基本摘要，故送交对象是保单持有人；并非年金购买人、证监会总监或保险业监管局。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的年報為了提供有關基本摘要，但萬用壽險的年報提供給誰？",o:["年金購買人","保單持有人","證監會總監","保險業監管局"],e:"萬用壽險的年報旨在向保單持有人提供保單基本摘要，故送交對象是保單持有人；並非年金購買人、證監會總監或保險業監管局。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险首年过后,保费:",o:["保费需维持相同的水平","可增加但不可减少","可减少但不可增加","可加可减,但需受条款所限制"],a:3,e:"万用寿险在首年过后保费具灵活性，可加可减，但须受保单条款及最低/最高保费等的限制；并非必须维持相同水平，或只能单方向调整。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險首年過後，保費：",o:["保費需維持相同的水平","可增加但不可減少","可減少但不可增加","可加可減，但需受條款所限制"],e:"萬用壽險在首年過後保費具靈活性，可加可減，但須受保單條款及最低/最高保費等的限制；並非必須維持相同水平，或只能單方向調整。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪三项寿险最有可能设有及提供退保现金: i 定期寿险 ii 储蓄寿险 iii 分红终身寿险 iv 不分红终身寿险",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],a:3,e:"定期寿险纯属保障性质，无累积现金价值，而储蓄寿险、分红终身寿险及不分红终身寿险均具储蓄成分，通常设有退保现金价值；故设退保现金的为ii、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪三項壽險最有可能設有及提供退保現金: i 定期壽險 ii 儲蓄壽險 iii 分紅終身壽險 iv 不分紅終身壽險",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],e:"定期壽險純屬保障性質，無累積現金價值，而儲蓄壽險、分紅終身壽險及不分紅終身壽險均具儲蓄成分，通常設有退保現金價值；故設退保現金的為ii、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪三项是有关可续保定期寿险的描述是正确?",o:["续保保费已反映新的保费","新保费按到达年龄计算","续保时毋须递交可保证明","以上皆正确"],a:3,e:"可续保定期寿险在续保时保费按新（到达）年龄计算而反映新风险，且续保无须提供可保证明；保额一般维持或调低。三项与膝述分别对应续保保费反映新保费、按到达年龄计算及免可保证明。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪三項是有關可續保定期壽險的描述是正確？",o:["續保保費已反映新的保費","新保費按到達年齡計算","續保時毋須遞交可保證明","以上皆正確"],e:"可續保定期壽險在續保時保費按新（到達）年齡計算而反映新風險，且續保無須提供可保證明；保額一般維持或調低。三項與膝述分別對應續保保費反映新保費、按到達年齡計算及免可保證明。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪三项是有关可续保定期寿险的描述是正确? i 续保保费按到达年龄计算 ii 续保保额只可等于或少于原保额 iii 续保时不须提交可保性证明 iv 只有保险期不少于5年的定期寿险才可续保",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],a:0,e:"可续保定期寿险续保时保费按到达年龄计算、续保保额只可等于或少于原保额，且不须提交可保性证明；并无「保险期不少于5年才可续保」的规定，故i、ii、iii正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪三項是有關可續保定期壽險的描述是正確？ i 續保保費按到達年齡計算 ii 續保保額只可等於或少於原保額 iii 續保時不須提交可保性證明 iv 只有保險期不少於5年的定期壽險才可續保",o:["i, ii, iii","i, iii, iv","i, ii, iv","ii, iii, iv"],e:"可續保定期壽險續保時保費按到達年齡計算、續保保額只可等於或少於原保額，且不須提交可保性證明；並無「保險期不少於5年才可續保」的規定，故i、ii、iii正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项保险产品的特性是任何时候受保生命去世,保险人即支付保额?",o:["定期寿险","储蓄寿险","终身寿险","以上各项都是"],a:2,e:"终身寿险对受保生命任何时间（终身）死亡均给付保额，与「任何时候死亡即付保额」相符；定期寿险限指定期间，储蓄寿险则在期满或身故时给付，均非终身保障。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項保險產品的特性是任何時候受保生命去世，保險人即支付保額？",o:["定期壽險","儲蓄壽險","終身壽險","以上各項都是"],e:"終身壽險對受保生命任何時間（終身）死亡均給付保額，與「任何時候死亡即付保額」相符；定期壽險限指定期間，儲蓄壽險則在期滿或身故時給付，均非終身保障。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项关于定额定期寿险的特点是「不正确」 ?",o:["是现有人寿保险种类中最便宜的","在整个保险期内,死亡保险金维持不变","在整个保险期内,年度保费水平维持不变","没有分红"],a:0,e:"定额定期寿险保额及保费在保险期内均维持不变且通常不分红，但「是现有人寿保险种类中最便宜的」并不正确，因递减定期寿险的保费比同类定额定期寿险更低，故选此项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項關於定額定期壽險的特點是「不正確」 ？",o:["是現有人壽保險種類中最便宜的","在整個保險期內，死亡保險金維持不變","在整個保險期內，年度保費水平維持不變","沒有分紅"],e:"定額定期壽險保額及保費在保險期內均維持不變且通常不分紅，但「是現有人壽保險種類中最便宜的」並不正確，因遞減定期壽險的保費比同類定額定期壽險更低，故選此項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项关于等级保费保险是正确的?",o:["保费按周期定期增加","保费必须因应不正常风险而增加","有关中介人可获特殊佣金","保额定期增加"],a:0,e:"等级保费（分级/步进）保险的保费并非在整个期间固定，而是按周期定期调升，以反映随年龄增长而上升的风险；其余选项与等级保费的定价方式不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項關於等級保費保險是正確的？",o:["保費按周期定期增加","保費必須因應不正常風險而增加","有關中介人可獲特殊佣金","保額定期增加"],e:"等級保費（分級/步進）保險的保費並非在整個期間固定，而是按週期定期調升，以反映隨年齡增長而上升的風險；其餘選項與等級保費的定價方式不符。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项或那些是一份由保单所有人维持有效的终身寿险的特点?",o:["索偿迟早会出现","该份保单可能会维持有效达数十年之久","该份保单应可取得一个现金价值","上述所有各项"],a:3,e:"终身寿险因保障终身，索偿迟早必然出现，保单可能持续有效数十年并累积现金价值；此三项均为保单所有人维持有效的终身寿险的特点，故选「上述所有各项」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項或那些是一份由保單所有人維持有效的終身壽險的特點？",o:["索償遲早會出現","該份保單可能會維持有效達數十年之久","該份保單應可取得一個現金價值","上述所有各項"],e:"終身壽險因保障終身，索償遲早必然出現，保單可能持續有效數十年並累積現金價值；此三項均為保單所有人維持有效的終身壽險的特點，故選「上述所有各項」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项是有关年金核保与人寿保险核保的陈述是正确的?",o:["完全相同","完全相反","在男性方面相同,而在女性方面相反","在女性方面相同,而在男性方面相反"],a:1,e:"年金核保与人寿保险核保方向截然相反：寿险承保死亡率风险（偏好健康长寿者更受保），年金则承保生存风险（预期寿命较长者反而不利）；故二者的核保逻辑「完全相反」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項是有關年金核保與人壽保險核保的陳述是正確的？",o:["完全相同","完全相反","在男性方面相同，而在女性方面相反","在女性方面相同，而在男性方面相反"],e:"年金核保與人壽保險核保方向截然相反：壽險承保死亡率風險（偏好健康長壽者更受保），年金則承保生存風險（預期壽命較長者反而不利）；故二者的核保邏輯「完全相反」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项是用作「扩阔保障范围」的权益?",o:["选择特权","转换特权","转变特权","转卖特权"],a:1,e:"「转换特权」容许保单所有人在保障期内将定期寿险转换为更广泛（如终身或储蓄）保障而不需可保证明，属扩阔保障范围的权益；选择、转变、转卖特权并非寿险的标准权益名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項是用作「擴闊保障範圍」的權益？",o:["選擇特權","轉換特權","轉變特權","轉賣特權"],e:"「轉換特權」容許保單所有人在保障期內將定期壽險轉換為更廣泛（如終身或儲蓄）保障而不需可保證明，屬擴闊保障範圍的權益；選擇、轉變、轉賣特權並非壽險的標準權益名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项正确描述团体保险计划?",o:["所有雇员不能从团体保单转换个人保险保单","每个受保雇员须详细审核","保费相等于个别受保雇员保费之总和","团体保险计划可以是雇员福利计划的一种"],a:3,e:"团体保险计划常作为雇员福利计划的一环，由雇主为雇员集体投保，保费与核保均按集体而非逐一个体处理；所有雇员不能转换、每个受保雇员须详细审核及保费等于个别保费总和等说法均错误。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項正確描述團體保險計劃？",o:["所有僱員不能從團體保單轉換個人保險保單","每個受保僱員須詳細審核","保費相等於個別受保僱員保費之總和","團體保險計劃可以是僱員福利計劃的一種"],e:"團體保險計劃常作為僱員福利計劃的一環，由僱主為僱員集體投保，保費與核保均按集體而非逐一個體處理；所有僱員不能轉換、每個受保僱員須詳細審核及保費等於個別保費總和等說法均錯誤。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下到哪种保险最不可能索偿:",o:["定期寿险","终身人寿","储蓄寿险","纯生存保险"],a:0,e:"定期寿险只在指定期间内死亡才赔偿，期满通常无索偿，故是各类寿险中最不可能索偿的一种；终身寿险必赔、储蓄寿险期满或身故必给付、纯生存保险亦按生存给付。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下到哪種保險最不可能索償:",o:["定期壽險","終身人壽","儲蓄壽險","純生存保險"],e:"定期壽險只在指定期間內死亡才賠償，期滿通常無索償，故是各類壽險中最不可能索償的一種；終身壽險必賠、儲蓄壽險期滿或身故必給付、純生存保險亦按生存給付。"}},
{p:3,ch:"人寿保险及年金的种类",q:"两夫妇以联合寿险方式购买一份递减定期寿险,此份保单可能称为:",o:["家居保险","家庭保险","抵押赎回保险","抵押贷款保险"],a:2,e:"两夫妇以联合寿险方式投保的递减定期寿险通常用于偿还按揭，故称为抵押赎回（按揭偿还）保险；家庭/家居保险及抵押贷款保险并非此按揭保障的标准名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"兩夫婦以聯合壽險方式購買一份遞減定期壽險,此份保單可能稱為：",o:["家居保險","家庭保險","抵押贖回保險","抵押貸款保險"],e:"兩夫婦以聯合壽險方式投保的遞減定期壽險通常用於償還按揭，故稱為抵押贖回（按揭償還）保險；家庭/家居保險及抵押貸款保險並非此按揭保障的標準名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"中介人必须向保单所有人投保时,问及其负担保费能力和:",o:["购买人寿保险目的","投保人以年供或是月供缴交保费","中介人收取佣金的计算","中介人可提供的折扣优惠"],a:0,e:"中介人在投保时须了解投保人负担保费的能力，并问明其购买人寿保险的目的，以作需求分析及适合性评估；年供或月供、佣金计算及折扣优惠均非须先问明的核心事项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"中介人必須向保單所有人投保時，問及其負擔保費能力和：",o:["購買人壽保險目的","投保人以年供或是月供繳交保費","中介人收取佣金的計算","中介人可提供的折扣優惠"],e:"中介人在投保時須瞭解投保人負擔保費的能力，並問明其購買人壽保險的目的，以作需求分析及適合性評估；年供或月供、佣金計算及折扣優惠均非須先問明的核心事項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"为受保生命提供死亡保障的称为:",o:["定期寿险","终身寿险","储蓄寿险","以上所有各项"],a:3,e:"定期寿险、终身寿险及储蓄寿险都就受保生命提供死亡保障（储蓄寿险兼有生存给付），只是保障期限和结构不同；故选「以上所有各项」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"為受保生命提供死亡保障的稱為：",o:["定期壽險","終身壽險","儲蓄壽險","以上所有各項"],e:"定期壽險、終身壽險及儲蓄壽險都就受保生命提供死亡保障（儲蓄壽險兼有生存給付），只是保障期限和結構不同；故選「以上所有各項」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"人寿保单中,“可转换”的意思是:",o:["可以随时由保险人取消","可以由保险人决定转为另一种类的计划","可以由保单所有人决定转为另一种类的计划","可以由保单所有人决定,由何种货币缴付保费"],a:2,e:"「可转换」指由保单所有人（而非保险人）决定将现有保单转换为另一种类的计划；转换与否取决于保单持有人选择，与货币或由保险人单方面决定无关。",src:1,tw:{ch:"人壽保險及年金的種類",q:"人壽保單中，“可轉換”的意思是：",o:["可以隨時由保險人取消","可以由保險人決定轉為另一種類的計劃","可以由保單所有人決定轉為另一種類的計劃","可以由保單所有人決定，由何種貨幣繳付保費"],e:"「可轉換」指由保單所有人（而非保險人）決定將現有保單轉換為另一種類的計劃；轉換與否取決於保單持有人選擇，與貨幣或由保險人單方面決定無關。"}},
{p:3,ch:"人寿保险及年金的种类",q:"人寿保险合约中可以有一些基本变数,以下哪项/些是常见的变数? i 保险计划可以转换 ii 保险计划可以是分红或不分红 iii 假如保障最初设有限期,该限期可能可以延续 iv 计划可按需要加入不同附约",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"人寿保险合约的基本变数包括：计划可转换、可分红利或不分红利、限期保障可延续，以及可按需附加不同附约；四项均属常见基本变数，故选i、ii、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"人壽保險合約中可以有一些基本變數,以下哪項/些是常見的變數? i 保險計劃可以轉換 ii 保險計劃可以是分紅或不分紅 iii 假如保障最初設有限期,該限期可能可以延續 iv 計劃可按需要加入不同附約",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"人壽保險合約的基本變數包括：計劃可轉換、可分紅利或不分紅利、限期保障可延續，以及可按需附加不同附約；四項均屬常見基本變數，故選i、ii、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"人寿保险合约中可以有一些基本变数,以下哪项/些是常见的变数? i 保险计划可以转换 ii 保险计划可以是分红或不分红 iii 运用保单的红利购买保险公司的股票 iv 运用保单的红利购买公司的优先股",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:0,e:"人寿保险的基本变数是指计划可转换，以及计划为分红或不分红两大类；至于运用保单红利购买保险公司股票或优先股属于红利运用的具体选择，并非基本变数，故只选i、ii。",src:1,tw:{ch:"人壽保險及年金的種類",q:"人壽保險合約中可以有一些基本變數,以下哪項/些是常見的變數? i 保險計劃可以轉換 ii 保險計劃可以是分紅或不分紅 iii 運用保單的紅利購買保險公司的股票 iv 運用保單的紅利購買公司的優先股",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],e:"人壽保險的基本變數是指計劃可轉換，以及計劃為分紅或不分紅兩大類；至於運用保單紅利購買保險公司股票或優先股屬於紅利運用的具體選擇，並非基本變數，故只選i、ii。"}},
{p:3,ch:"人寿保险及年金的种类",q:"人寿保险的种类繁多,以下哪项是寿险基本变数?",o:["可转换为另一更广泛保障的计划","如果最初只投保一段有限时间,可选择续保","可加入附加条款以提供额外保障","以上所有各项皆是"],a:3,e:"寿险的基本变数涵盖可转换为更广泛保障的计划、限期保障可续保，以及可加入附约提供额外保障；三项皆为常见基本变数，故选「以上所有各项皆是」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"人壽保險的種類繁多，以下哪項是壽險基本變數？",o:["可轉換為另一更廣泛保障的計劃","如果最初只投保一段有限時間，可選擇續保","可加入附加條款以提供額外保障","以上所有各項皆是"],e:"壽險的基本變數涵蓋可轉換為更廣泛保障的計劃、限期保障可續保，以及可加入附約提供額外保障；三項皆為常見基本變數，故選「以上所有各項皆是」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪三项是储蓄寿险的正确描述? i  它可以是分红或不分红 ii  受保生命在保障期内生存或死亡均可取得保险利益 iii 它是一种纯生存保险 iv 一般情况下,须要在保障期内缴付保费",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"储蓄寿险可分为分红或不分红、受保生命在期内死亡或期满生存均可获保险利益，且一般在保障期内缴付保费；但它并非「纯生存保险」，而是纯生存与定期寿险的组合，故i、ii、iv正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪三項是儲蓄壽險的正確描述？ i 它可以是分紅或不分紅 ii 受保生命在保障期內生存或死亡均可取得保險利益 iii 它是一種純生存保險 iv 一般情況下，須要在保障期內繳付保費",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"儲蓄壽險可分為分紅或不分紅、受保生命在期內死亡或期滿生存均可獲保險利益，且一般在保障期內繳付保費；但它並非「純生存保險」，而是純生存與定期壽險的組合，故i、ii、iv正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪三项有关单位相连保单是正确的? i 保单价值直接与保费购买的投资的表现相连 ii 全部或部分保费用作购入基金单位 iii 定期寿险及储蓄寿险是最常见的单位相连保单类型 iv 基金类型有股票及固定利息投资",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"单位相连保单的保单价值直接与所购投资表现相连，全部或部分保费用于购入基金单位，基金类型包括股票及固定利息投资；最常见的载体是终身寿险和储蓄寿险，而非定期寿险，故i、ii、iv正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪三項有關單位相連保單是正確的？ i 保單價值直接與保費購買的投資的表現相連 ii 全部或部分保費用作購入基金單位 iii 定期壽險及儲蓄壽險是最常見的單位相連保單類型 iv 基金類型有股票及固定利息投資",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"單位相連保單的保單價值直接與所購投資表現相連，全部或部分保費用於購入基金單位，基金類型包括股票及固定利息投資；最常見的載體是終身壽險和儲蓄壽險，而非定期壽險，故i、ii、iv正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪些/哪项对万用寿险的陈述是正确的?",o:["具有「分别列示各定价因素」的定价结构","保费灵活,保单所有人有很大自由度","可调整保险利益,随时增加或减少死亡保险金","以上所有各项"],a:3,e:"万用寿险采用「分别列示各定价因素」的透明定价结构，保费灵活、保单所有人自由度大，并可随时调整死亡保险金（增加或减少）；三项陈述均正确，故选「以上所有各项」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪些/哪項對萬用壽險的陳述是正確的？",o:["具有「分別列示各定價因素」的定價結構","保費靈活，保單所有人有很大自由度","可調整保險利益，隨時增加或減少死亡保險金","以上所有各項"],e:"萬用壽險採用「分別列示各定價因素」的透明定價結構，保費靈活、保單所有人自由度大，並可隨時調整死亡保險金（增加或減少）；三項陳述均正確，故選「以上所有各項」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪些/哪项是终身寿险的说明是正确的?",o:["保障不可能在分红基础上","有时可能需要缴付终身保费","保费缴付到指定年龄,到时保单便会期满","以上皆是"],a:1,e:"终身寿险既可为分红或不分红、保费可终身缴付，也可限期或缴至指定年龄后保障继续而保费停缴；「有时可能需要缴付终身保费」正是其缴付方式之一，其余两项说法错误。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪些/哪項是終身壽險的說明是正確的?",o:["保障不可能在分紅基礎上","有時可能需要繳付終身保費","保費繳付到指定年齡，到時保單便會期滿","以上皆是"],e:"終身壽險既可為分紅或不分紅、保費可終身繳付，也可限期或繳至指定年齡後保障繼續而保費停繳；「有時可能需要繳付終身保費」正是其繳付方式之一，其餘兩項說法錯誤。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪些是终身寿险缴付保费的方式 i  缴付保费至终身 ii 于限期内缴付保费 iii 缴付保费至指定年龄 iv 缴付保费至退休,即使在此之前已死亡",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"终身寿险的保费缴付方式包括终身缴付、于限期内缴付以及缴付至指定年龄三种；「缴至退休即使之前已死亡」表述矛盾，不属缴付方式，故i、ii、iii正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪些是終身壽險繳付保費的方式 i 繳付保費至終身 ii 於限期內繳付保費 iii 繳付保費至指定年齡 iv 繳付保費至退休，即使在此之前已死亡",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"終身壽險的保費繳付方式包括終身繳付、於限期內繳付以及繳付至指定年齡三種；「繳至退休即使之前已死亡」表述矛盾，不屬繳付方式，故i、ii、iii正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪些陈述有关储蓄寿险是不正确的:",o:["可选择分红或不分红","均衡保费,一般按年缴交","保额会在受保生命早逝或保单期满时发放","只有在限定期间之死亡才可获支付保额"],a:3,e:"储蓄寿险在受保生命早逝或保单期满时均给付保额，而非「只有在限定期间死亡才可获支付」；该说法将储蓄寿险误作定期寿险，属不正确陈述，其余三项均为储蓄寿险的正确描述。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪些陳述有關儲蓄壽險是不正確的：",o:["可選擇分紅或不分紅","均衡保費，一般按年繳交","保額會在受保生命早逝或保單期滿時發放","只有在限定期間之死亡才可獲支付保額"],e:"儲蓄壽險在受保生命早逝或保單期滿時均給付保額，而非「只有在限定期間死亡才可獲支付」；該說法將儲蓄壽險誤作定期壽險，屬不正確陳述，其餘三項均為儲蓄壽險的正確描述。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪种保险类型的保单价值与投资表现挂钩?",o:["终身寿险","投资相连长期保险","储蓄寿险","定额定期寿险"],a:1,e:"投资相连长期保单的保单价值直接与所购投资资产的表现挂钩，会随投资波动；终身寿险、储蓄寿险及定额定期寿险的保单价值不直接连系投资表现，故选投资相连长期保险。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪種保險類型的保單價值與投資表現掛鈎？",o:["終身壽險","投資相連長期保險","儲蓄壽險","定額定期壽險"],e:"投資相連長期保單的保單價值直接與所購投資資產的表現掛鈎，會隨投資波動；終身壽險、儲蓄壽險及定額定期壽險的保單價值不直接連繫投資表現，故選投資相連長期保險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪类保险为递减定期寿险的例子? i 信用寿险 ii 按揭弥偿保险 iii 抵押赎回保险 iv 家庭收入寿险",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:3,e:"递减定期寿险的例子包括信用寿险、抵押赎回保险及家庭收入寿险，其保额随债务或需要递减；「按揭弥偿保险」属弥偿性质的一般保险，非递减定期寿险，故选i、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪類保險為遞減定期壽險的例子？ i 信用壽險 ii 按揭彌償保險 iii 抵押贖回保險 iv 家庭收入壽險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],e:"遞減定期壽險的例子包括信用壽險、抵押贖回保險及家庭收入壽險，其保額隨債務或需要遞減；「按揭彌償保險」屬彌償性質的一般保險，非遞減定期壽險，故選i、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪类保险的特色是保险额可按需求而递减的? i 信用寿险 ii 递减定期寿险 iii 抵押赎回保险 iv 家庭收入寿险",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"信用寿险、递减定期寿险、抵押赎回保险及家庭收入寿险的保额均会随需求（如未偿债务、剩余按揭或收入需要）递减；四项皆具递减特色，故选「i、ii、iii、iv」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪類保險的特色是保險額可按需求而遞減的？ i 信用壽險 ii 遞減定期壽險 iii 抵押贖回保險 iv 家庭收入壽險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"信用壽險、遞減定期壽險、抵押贖回保險及家庭收入壽險的保額均會隨需求（如未償債務、剩餘按揭或收入需要）遞減；四項皆具遞減特色，故選「i、ii、iii、iv」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项/些有关递增定期寿险是不正确?",o:["保费及保险利益按同一水平增加","保险利益按年或协定方式增加","保费及保险利益不变,但保险期增加","目的是使保险利益与货币价值保持一致"],a:2,e:"递增定期寿险的保费及保险利益按年或协定方式递增，目的是使利益与货币购买力保持一致；「保费及保险利益不变、但保险期增加」并非递增定期寿险的特征，故该项不正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項/些有關遞增定期壽險是不正確?",o:["保費及保險利益按同一水平增加","保險利益按年或協定方式增加","保費及保險利益不變,但保險期增加","目的是使保險利益與貨幣價值保持一致"],e:"遞增定期壽險的保費及保險利益按年或協定方式遞增，目的是使利益與貨幣購買力保持一致；「保費及保險利益不變、但保險期增加」並非遞增定期壽險的特徵，故該項不正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项不可能属于人寿保险的基本变数?",o:["无申请书","最初只投保一段有限时间,可以续保","如有需要,可转为更广泛形式的保障","提供额外保障的附约"],a:0,e:"寿险基本变数包括限期保障可续保、可转换为更广泛保障及附加保障附约等；「无申请书」并非基本变数，任何寿险申请都需投保资料，故选「无申请书」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項不可能屬於人壽保險的基本變數？",o:["無申請書","最初只投保一段有限時間，可以續保","如有需要，可轉為更廣泛形式的保障","提供額外保障的附約"],e:"壽險基本變數包括限期保障可續保、可轉換為更廣泛保障及附加保障附約等；「無申請書」並非基本變數，任何壽險申請都需投保資料，故選「無申請書」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项不大可能是终身寿险保费的各种变化?",o:["终身缴付保费","于限定期间内支付","于指定年龄之后,停止缴付","保单生效时,以一笔过方式支付"],a:3,e:"终身寿险保费可终身缴付、于限定期间内支付或缴至指定年龄；「保单生效时以一笔过方式支付」虽属整付模式但并非常见的终身寿险保费变化，相比之下最不大可能，故选该项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項不大可能是終身壽險保費的各種變化？",o:["終身繳付保費","於限定期間內支付","於指定年齡之後，停止繳付","保單生效時，以一筆過方式支付"],e:"終身壽險保費可終身繳付、於限定期間內支付或繳至指定年齡；「保單生效時以一筆過方式支付」雖屬整付模式但並非常見的終身壽險保費變化，相比之下最不大可能，故選該項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项不属于万用寿险的特色?",o:["灵活保费","可调整保险利益","向保单持有人披露有关的开支","自动按年增加保额"],a:3,e:"万用寿险的特色是灵活保费、可调整保险利益及向保单持有人披露开支，而非「自动按年增加保额」；自动增额并非万用寿险的固有特点，故该项不属于其特色。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項不屬於萬用壽險的特色？",o:["靈活保費","可調整保險利益","向保單持有人披露有關的開支","自動按年增加保額"],e:"萬用壽險的特色是靈活保費、可調整保險利益及向保單持有人披露開支，而非「自動按年增加保額」；自動增額並非萬用壽險的固有特點，故該項不屬於其特色。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项不属于寿险保单保障的基本转换模式?",o:["无申请书","如果只提供暂时性的保障, 则可以转换","提供额外利益附约","提供更广泛的保障计划"],a:0,e:"寿险保单保障的基本转换模式包括时限保障可转换、提供更广泛保障计划及附加利益附约等；「无申请书」不属于转换模式，故选该项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項不屬於壽險保單保障的基本轉換模式?",o:["無申請書","如果只提供暫時性的保障, 則可以轉換","提供額外利益附約","提供更廣泛的保障計劃"],e:"壽險保單保障的基本轉換模式包括時限保障可轉換、提供更廣泛保障計劃及附加利益附約等；「無申請書」不屬於轉換模式，故選該項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项为年金的正确描述? i 年金利益付款开始时的年龄越高,每一期年金利益付款便越高 ii 年金核保与传统人寿保险核保完全不同 iii 男性收取的定期年金高于相同年龄的女性 iv 相同年龄男性的保费低于女性",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:3,e:"年金给付开始年龄越高、每期金额越高，年金核保与寿险核保方向相反，且男性因寿命较短其定期年金高于同龄女性、保费则低于女性；四项描述均正确，故选i、ii、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項為年金的正確描述？ i 年金利益付款開始時的年齡越高，每一期年金利益付款便越高 ii 年金核保與傳統人壽保險核保完全不同 iii 男性收取的定期年金高於相同年齡的女性 iv 相同年齡男性的保費低於女性",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"年金給付開始年齡越高、每期金額越高，年金核保與壽險核保方向相反，且男性因壽命較短其定期年金高於同齡女性、保費則低於女性；四項描述均正確，故選i、ii、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项关于定期寿险的陈述是不正确的?",o:["只会就对指定的保险期内死亡之索偿作出理赔","一般而言,这是一种最便宜的人寿保险","只会就因意外导致的死亡而提出之索偿作出理赔","大部份定期保险保单均会在没有赔偿的情况下到期"],a:2,e:"定期寿险在指定期间内对任何原因（除除外危险外）的死亡均予理赔，并非「只对意外死亡理赔」；该说法体现对定期寿险承保范围的误解，固为不正确陈述。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項關於定期壽險的陳述是不正確的？",o:["只會就對指定的保險期內死亡之索償作出理賠","一般而言，這是一種最便宜的人壽保險","只會就因意外導致的死亡而提出之索償作出理賠","大部份定期保險保單均會在沒有賠償的情況下到期"],e:"定期壽險在指定期間內對任何原因（除除外危險外）的死亡均予理賠，並非「只對意外死亡理賠」；該說法體現對定期壽險承保範圍的誤解，固為不正確陳述。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项关于递减定期寿险是不正确的?",o:["是一项附有抵销通缩的一种附加条款计划","人寿保险种类中最便宜的","这计划特别适合于逐渐减少的短暂保障需求","受保人在保险期内死亡方可获得支付"],a:0,e:"递减定期寿险是保额逐年下降以配合递减债务需要的计划，并非「抵销通缩的附加条款计划」（抵销通缩的是递增定期寿险）；该描述错误，其余三项均正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項關於遞減定期壽險是不正確的？",o:["是一項附有抵銷通縮的一種附加條款計劃","人壽保險種類中最便宜的","這計劃特別適合於逐漸減少的短暫保障需求","受保人在保險期內死亡方可獲得支付"],e:"遞減定期壽險是保額逐年下降以配合遞減債務需要的計劃，並非「抵銷通縮的附加條款計劃」（抵銷通縮的是遞增定期壽險）；該描述錯誤，其餘三項均正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项关于递增定期寿险的保费描述是不正确的:",o:["保费可按消费者物价指数增加","保费可按比例增加","此保费设计的基本概念是使利益与货币价值保持一致","保费是不变的"],a:3,e:"递增定期寿险的保费随保额按年（或按消费者物价指数、按比例）递增，目的是保持利益与货币价值一致；「保费是不变的」违背其递增设计，故该项不正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項關於遞增定期壽險的保費描述是不正確的：",o:["保費可按消費者物價指數增加","保費可按比例增加","此保費設計的基本概念是使利益與貨幣價值保持一致","保費是不變的"],e:"遞增定期壽險的保費隨保額按年（或按消費者物價指數、按比例）遞增，目的是保持利益與貨幣價值一致；「保費是不變的」違背其遞增設計，故該項不正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项对于可续保定期寿险的描述是正确的?",o:["在续保时,其保费增加以反映其年龄之提高","在续保时,其保额只可相同或小于其原有保障额","在续保时,无须提供可保性证明","以上所有各项"],a:3,e:"可续保定期寿险续保时保费按到达年龄调升、保额只可等于或小于原保额，且无须提供可保性证明；三项均为其正确描述，故选「以上所有各项」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項對於可續保定期壽險的描述是正確的?",o:["在續保時，其保費增加以反映其年齡之提高","在續保時，其保額只可相同或小於其原有保障額","在續保時，無須提供可保性證明","以上所有各項"],e:"可續保定期壽險續保時保費按到達年齡調升、保額只可等於或小於原保額，且無須提供可保性證明；三項均為其正確描述，故選「以上所有各項」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项对单位相连长期保单的共同原则?",o:["有关保单通常有分红成份","有关单位须与股票基金挂钩","有关保险人必须保证最低的单位价格","全部或部份保费用作购买基金单位"],a:3,e:"单位相连长期保单的共同原则是全部或部分保费用作购入基金单位，使保单价值与基金表现相连；与分红成分、股票基金或保证最低单位价格无必然关联，故该项为共同原则。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項對單位相連長期保單的共同原則？",o:["有關保單通常有分紅成份","有關單位須與股票基金掛鈎","有關保險人必須保證最低的單位價格","全部或部份保費用作購買基金單位"],e:"單位相連長期保單的共同原則是全部或部分保費用作購入基金單位，使保單價值與基金表現相連；與分紅成分、股票基金或保證最低單位價格無必然關聯，故該項為共同原則。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项属于万用寿险的特色?",o:["灵活的保费","可调整的死亡保险金","披露有关的开支费用","以上皆是"],a:3,e:"万用寿险的特色包括灵活保费、可调整的死亡保险金及向保单持有人披露有关的开支费用；三项皆属其特色，故选「以上皆是」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項屬於萬用壽險的特色？",o:["靈活的保費","可調整的死亡保險金","披露有關的開支費用","以上皆是"],e:"萬用壽險的特色包括靈活保費、可調整的死亡保險金及向保單持有人披露有關的開支費用；三項皆屬其特色，故選「以上皆是」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项属于储蓄寿险的不正确描述 : i 它可以建立在分红/不分红的基础上 ii 它有退保现金价值 iii 它必须于期满才可索偿(例如 20 年) iv 保额随着受保生命何时离去有所不同",o:["i 及 ii","ii 及 iii","i 及 ii","iii 及 iv"],a:3,e:"储蓄寿险受保生命在期内死亡或期满生存均可索偿，且保额固定（不随死亡时间变动）；「必须期满才可索偿」及「保额随何时离去而不同」均错误，故不正确的为iii及iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項屬於儲蓄壽險的不正確描述 : i 它可以建立在分紅/不分紅的基礎上 ii 它有退保現金價值 iii 它必須於期滿才可索償(例如 20 年) iv 保額隨着受保生命何時離去有所不同",o:["i 及 ii","ii 及 iii","i 及 ii","iii 及 iv"],e:"儲蓄壽險受保生命在期內死亡或期滿生存均可索償，且保額固定（不隨死亡時間變動）；「必須期滿才可索償」及「保額隨何時離去而不同」均錯誤，故不正確的為iii及iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项属于终身寿险保单之特点?",o:["从不设有红利","不能获得现金价值或退保现金","于期满时给付保险金","不论任何时间死亡,均会作出赔偿"],a:3,e:"终身寿险不论受保生命任何时间死亡都会作出赔偿，是其核心特点；其余选项（从不设红、不能获现金价值、期满才给付）均与终身寿险（可分红利、有现金价值）事实不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項屬於終身壽險保單之特點？",o:["從不設有紅利","不能獲得現金價值或退保現金","於期滿時給付保險金","不論任何時間死亡，均會作出賠償"],e:"終身壽險不論受保生命任何時間死亡都會作出賠償，是其核心特點；其餘選項（從不設紅、不能獲現金價值、期滿才給付）均與終身壽險（可分紅利、有現金價值）事實不符。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项属于非传统寿险? i   储蓄寿险 ii  万用寿险 iii 单位相连长期保险 iv 终身寿险",o:["i, ii","ii, iii","i, iv","iii, iv"],a:1,e:"非传统寿险是指有别于传统终身、储蓄、定期寿险的产品，主要包括万用寿险及单位相连长期保险；储蓄寿险与终身寿险属传统寿险，故选ii、iii。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項屬於非傳統壽險？ i 儲蓄壽險 ii 萬用壽險 iii 單位相連長期保險 iv 終身壽險",o:["i, ii","ii, iii","i, iv","iii, iv"],e:"非傳統壽險是指有別於傳統終身、儲蓄、定期壽險的產品，主要包括萬用壽險及單位相連長期保險；儲蓄壽險與終身壽險屬傳統壽險，故選ii、iii。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项并不属于储蓄寿险的特点?",o:["当受保生命在保险期届满时,仍然生存,称为保单期满","可以是分红或可分红保单","计划内有很大部份的储蓄金额","受保生命必须在期满时仍然生存,才可获得保险金额"],a:3,e:"储蓄寿险在受保生命期内死亡或期满生存均可获给付保额，并非「必须在期满时仍生存才可获得」；该说法只描述纯生存保险，属非储蓄寿险特点，故选此项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項並不屬於儲蓄壽險的特點？",o:["當受保生命在保險期屆滿時，仍然生存，稱為保單期滿","可以是分紅或可分紅保單","計劃內有很大部份的儲蓄金額","受保生命必須在期滿時仍然生存，才可獲得保險金額"],e:"儲蓄壽險在受保生命期內死亡或期滿生存均可獲給付保額，並非「必須在期滿時仍生存才可獲得」；該說法只描述純生存保險，屬非儲蓄壽險特點，故選此項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项并不是年金的变化?",o:["到期领取年金时以一笔过形式支付金额","保证于特定期限内支付金额","保证以终身支付方式领取金额","于支付期限内死亡时,由受益人继续领取金额"],a:0,e:"年金的变化包括保证特定期限支付、保证终身支付及死亡后由受益人继续领取等；「到期时以一笔过形式领取金额」属整付给付而非年金分期支付的变化，故该项并非年金变化。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項並不是年金的變化？",o:["到期領取年金時以一筆過形式支付金額","保證於特定期限內支付金額","保證以終身支付方式領取金額","於支付期限內死亡時，由受益人繼續領取金額"],e:"年金的變化包括保證特定期限支付、保證終身支付及死亡後由受益人繼續領取等；「到期時以一筆過形式領取金額」屬整付給付而非年金分期支付的變化，故該項並非年金變化。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项并非有关终身寿险的陈述? i 死亡保险金按年递减 ii 必然以不分红方式发出 iii 可能须终身缴付保费 iv 于指定时限死亡才会作出赔偿",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"终身寿险保额不递减、可分红利也可不分红、且不论何时死亡均赔偿，只有「可能须终身缴付保费」为其真实陈述；故「并非」终身寿险的陈述为i、ii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項並非有關終身壽險的陳述？ i 死亡保險金按年遞減 ii 必然以不分紅方式發出 iii 可能須終身繳付保費 iv 於指定時限死亡才會作出賠償",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"終身壽險保額不遞減、可分紅利也可不分紅、且不論何時死亡均賠償，只有「可能須終身繳付保費」為其真實陳述；故「並非」終身壽險的陳述為i、ii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项或哪些是定额定期寿险的正确描述?",o:["保单利益乃按年逐步递增","缴付保费在首段时间均为一致","多为分红保单形式购买","以上各项皆不是"],a:3,e:"定额定期寿险保额固定、保费水平固定且通常不分红；「利益逐年递增」「缴费首段一致」及「多为分红」均非其描述，故以上各项皆不是。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項或哪些是定額定期壽險的正確描述？",o:["保單利益乃按年逐步遞增","繳付保費在首段時間均為一致","多為分紅保單形式購買","以上各項皆不是"],e:"定額定期壽險保額固定、保費水平固定且通常不分紅；「利益逐年遞增」「繳費首段一致」及「多為分紅」均非其描述，故以上各項皆不是。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项描述可续保定期寿险为不正确?",o:["必须于购买保单五年内行使续保权","毋须提交可保性证明","保费按照到达年龄计算","续保保额只可等于或少于原保额"],a:0,e:"可续保定期寿险并无「必须于购买五年内行使续保权」的规定，其续保不以五年为限；毋须提交可保性证明、按到达年龄计算保费及保额只可等于或少于原保额均为正确描述，故该项不正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項描述可續保定期壽險為不正確？",o:["必須於購買保單五年內行使續保權","毋須提交可保性證明","保費按照到達年齡計算","續保保額只可等於或少於原保額"],e:"可續保定期壽險並無「必須於購買五年內行使續保權」的規定，其續保不以五年為限；毋須提交可保性證明、按到達年齡計算保費及保額只可等於或少於原保額均為正確描述，故該項不正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项描述是正确的?",o:["由于女性寿命长,所以不能买年金","向男性收取的人寿保险保费低于女性","向女性支付的分期年金金额,较相同情况的男性为低","向男性支付的分期年金金额,较相同情况的女性为低"],a:2,e:"女性平均寿命较长，年金摊付期更长，故相同条件下女性每期年金金额低于男性；此即「向女性支付的分期年金较相同情况男性为低」所描述的事实，其余选项或者错误或者因果颠倒。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項描述是正確的？",o:["由於女性壽命長，所以不能買年金","向男性收取的人壽保險保費低於女性","向女性支付的分期年金金額，較相同情況的男性為低","向男性支付的分期年金金額，較相同情況的女性為低"],e:"女性平均壽命較長，年金攤付期更長，故相同條件下女性每期年金金額低於男性；此即「向女性支付的分期年金較相同情況男性為低」所描述的事實，其餘選項或者錯誤或者因果顛倒。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项描述有关抵押赎回寿险是不正确的?",o:["保障形式与按揭赔偿保险相同","可以联名(例如:夫妇)为基础","用来缴付未清还的贷款余额","保障形式是为个人而设,并非银行及贷款给银行"],a:0,e:"抵押赎回保险是递减定期寿险（为借款人按揭设计），与属弥偿性质保障承按人的「按揭赔偿保险」并不相同；故「保障形式与按揭赔偿保险相同」为不正确陈述，其余三项均正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項描述有關抵押贖回壽險是不正確的?",o:["保障形式與按揭賠償保險相同","可以聯名(例如：夫婦)為基礎","用來繳付未清還的貸款餘額","保障形式是為個人而設，並非銀行及貸款給銀行"],e:"抵押贖回保險是遞減定期壽險（為借款人按揭設計），與屬彌償性質保障承按人的「按揭賠償保險」並不相同；故「保障形式與按揭賠償保險相同」為不正確陳述，其餘三項均正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是储蓄寿险在香港较不流行的原因:",o:["它比较贵","对投保公众来说,储蓄寿险较难理解","它给予保险代理人的佣金太少","其实它比终身寿险及定期寿险更加流行"],a:0,e:"储蓄寿险保费较贵（含储蓄成分）而保障成分偏低，故在香港相对不流行；并非因难以理解、佣金太少，也非比终身及定期寿险更流行之类说法。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是儲蓄壽險在香港較不流行的原因：",o:["它比較貴","對投保公眾來說，儲蓄壽險較難理解","它給予保險代理人的佣金太少","其實它比終身壽險及定期壽險更加流行"],e:"儲蓄壽險保費較貴（含儲蓄成分）而保障成分偏低，故在香港相對不流行；並非因難以理解、佣金太少，也非比終身及定期壽險更流行之類說法。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是关于年金的说明是不正确的?",o:["于年金购买后的第一个年金期完结时开始支付","年金利益并非即时,而是从某个特定时间或年金标的人到达某个特定年龄后才开始予以支付","在世时提供周期性保险利益付款","延至明日支付利益"],a:3,e:"年金是定期（周期）给付的保险利益，可在购买后第一个年金期完结时开始（即期）或延至指定年龄（延期）；「延至明日支付利益」语义含混，不符合即期或延期年金的规范说明，故该项不正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是關於年金的說明是不正確的?",o:["於年金購買後的第一個年金期完結時開始支付","年金利益並非即時，而是從某個特定時間或年金標的人到達某個特定年齡後才開始予以支付","在世時提供週期性保險利益付款","延至明日支付利益"],e:"年金是定期（週期）給付的保險利益，可在購買後第一個年金期完結時開始（即期）或延至指定年齡（延期）；「延至明日支付利益」語義含混，不符合即期或延期年金的規範說明，故該項不正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是定期寿险的类别: i 定期定额寿险 ii 递增定期寿险 iii 可转换定期寿险 iv 递减定期寿险",o:["i, ii, iii","i, iii, iv","i, ii, iv","i, ii, iii, iv"],a:2,e:"定期寿险按保额变化分为定额定期寿险、递增定期寿险及递减定期寿险三类；「可转换定期寿险」是定期寿险的一项权益（转换特权）而非按保额划分的类别，故只选i、ii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是定期壽險的類別： i 定期定額壽險 ii 遞增定期壽險 iii 可轉換定期壽險 iv 遞減定期壽險",o:["i, ii, iii","i, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"定期壽險按保額變化分為定額定期壽險、遞增定期壽險及遞減定期壽險三類；「可轉換定期壽險」是定期壽險的一項權益（轉換特權）而非按保額劃分的類別，故只選i、ii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是定额定期寿险的特点?",o:["就递减的保费提供一项不变的利益","就不变的保费提供一项递增的利益","就不变的保费提供一项不变的利益","就递增的保费提供一项不变的利益"],a:2,e:"定额定期寿险在整个保险期间以不变的保费提供一项不变的保额，即「不变的保费提供不变的利益」；其余选项对保费或利益变动方向的描述均与定额特征不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是定額定期壽險的特點？",o:["就遞減的保費提供一項不變的利益","就不變的保費提供一項遞增的利益","就不變的保費提供一項不變的利益","就遞增的保費提供一項不變的利益"],e:"定額定期壽險在整個保險期間以不變的保費提供一項不變的保額，即「不變的保費提供不變的利益」；其餘選項對保費或利益變動方向的描述均與定額特徵不符。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是定额定期寿险的特色?",o:["通常是根据分红方式而签发","在有指定数目的学期内缴付学费","是为受保生命给付利益的最佳储蓄方法","只接受列明保障期内的死亡而给付利益"],a:3,e:"定额定期寿险只就列明保障期内发生的死亡给付利益，且通常不分红、保费低廉；「通常分红」「于指定学期缴学费」「最佳储蓄方法」均不符合其纯保障、定期限的性质。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是定額定期壽險的特色？",o:["通常是根據分紅方式而簽發","在有指定數目的學期內繳付學費","是為受保生命給付利益的最佳儲蓄方法","只接受列明保障期內的死亡而給付利益"],e:"定額定期壽險只就列明保障期內發生的死亡給付利益，且通常不分紅、保費低廉；「通常分紅」「於指定學期繳學費」「最佳儲蓄方法」均不符合其純保障、定期限的性質。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是投资相连保单之正确描述?",o:["最常见于终身寿险或储蓄寿险","保单价值与投资表现挂钩","有关基金可以包括股票或固定利息投资","以上各项均属正确"],a:3,e:"投资相连保单常见于终身寿险或储蓄寿险，其保单价值与投资表现挂钩，基金类型可包括股票或固定利息投资；三项描述均正确，故选「以上各项均属正确」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是投資相連保單之正確描述？",o:["最常見於終身壽險或儲蓄壽險","保單價值與投資表現掛鈎","有關基金可以包括股票或固定利息投資","以上各項均屬正確"],e:"投資相連保單常見於終身壽險或儲蓄壽險，其保單價值與投資表現掛鈎，基金類型可包括股票或固定利息投資；三項描述均正確，故選「以上各項均屬正確」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是正确描述团体人寿保单的核保方式?",o:["深入核保家族病史","核保对于个人保单会有高度注意, 而团体保单则不适用","对比个人保单,团体保单的核保会较为小心及详细询问","保费会高于团体个人累积的保费"],a:1,e:"团体人寿保单以集体核保为原则，不逐一向每个成员详尽询问，而个人保单则高度注意个别的健康与风险；故「对个人保单高度注意、团体保单不适用详尽核保」描述正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是正確描述團體人壽保單的核保方式?",o:["深入核保家族病史","核保對於個人保單會有高度注意， 而團體保單則不適用","對比個人保單，團體保單的核保會較為小心及詳細詢問","保費會高於團體個人累積的保費"],e:"團體人壽保單以集體核保為原則，不逐一向每個成員詳盡詢問，而個人保單則高度注意個別的健康與風險；故「對個人保單高度注意、團體保單不適用詳盡核保」描述正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是确定期间终身年金的说明是正确的?",o:["仅于规定年期内定期支付年金利益,不论年金标的人在此期间内是否已死亡","于指定年期内支付利益,如果年金标的人在该年期完结后还活着,年金更会给他终身支付利益","到达某个特定年龄后才开始予以支付","在世时提供周期性保险利益付款"],a:1,e:"确定期间终身年金在指定年期内支付年金利益，若年金标的人在该年期完结后仍生存，则继续终身支付；即「先保证一定年期，再终身给付」的结构，与其余选项不同。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是確定期間終身年金的說明是正確的?",o:["僅於規定年期內定期支付年金利益，不論年金標的人在此期間內是否已死亡","於指定年期內支付利益，如果年金標的人在該年期完結後還活着，年金更會給他終身支付利益","到達某個特定年齡後才開始予以支付","在世時提供週期性保險利益付款"],e:"確定期間終身年金在指定年期內支付年金利益，若年金標的人在該年期完結後仍生存，則繼續終身支付；即「先保證一定年期，再終身給付」的結構，與其餘選項不同。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是递增定期寿险的正确陈述?",o:["保额和保费随着相关指数上升","只有保额上升","只有保费上升","保额和保费不变"],a:0,e:"递增定期寿险的保额与保费随着相关指数（如通胀指数）上升而同步增加；并非只有保额或只有保费上升，也非两者不变，故选「保额和保费随着相关指数上升」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是遞增定期壽險的正確陳述？",o:["保額和保費隨着相關指數上升","只有保額上升","只有保費上升","保額和保費不變"],e:"遞增定期壽險的保額與保費隨着相關指數（如通脹指數）上升而同步增加；並非只有保額或只有保費上升，也非兩者不變，故選「保額和保費隨着相關指數上升」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是非供款式团体保险计划之特点?",o:["雇员无须供款","雇主无须供款","雇主及雇员分担供款","雇主及雇员无须分担供款"],a:0,e:"非供款式团体保险计划由雇主全数承担保费，雇员无须供款；并非雇主无须供款，也非双方分担或双方均不供款，故选「雇员无须供款」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是非供款式團體保險計劃之特點？",o:["僱員無須供款","僱主無須供款","僱主及僱員分擔供款","僱主及僱員無須分擔供款"],e:"非供款式團體保險計劃由僱主全數承擔保費，僱員無須供款；並非僱主無須供款，也非雙方分擔或雙方均不供款，故選「僱員無須供款」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项是香港年金计划特点 ? i    属于即期终身年金 ii   供60岁或以上的退休生活人士认购 iii 提供保证每月年金款项(属固定金额) iv  最低及最高保费金额为$50,000及$3,000,000",o:["i, ii,","i, ii, iii","i, iii, iv","i, ii, iii, iv"],a:2,e:"香港年金计划属即期终身年金，提供保证的每月年金款项，最低及最高保费分别为$50,000及$3,000,000；其主要对象为65岁或以上人士而非60岁，故正确者为i、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項是香港年金計劃特點 ？ i 屬於即期終身年金 ii 供60歲或以上的退休生活人士認購 iii 提供保證每月年金款項（屬固定金額） iv 最低及最高保費金額為$50,000及$3,000,000",o:["i, ii,","i, ii, iii","i, iii, iv","i, ii, iii, iv"],e:"香港年金計劃屬即期終身年金，提供保證的每月年金款項，最低及最高保費分別為$50,000及$3,000,000；其主要對象為65歲或以上人士而非60歲，故正確者為i、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关单位相连长期保单是正确的?",o:["它又称为投资相连长期保单","利用已支付的保费购买的投资的表现相连,其保单价值并不挂钩","没有死亡保险金","它的价值是可保证的"],a:0,e:"单位相连长期保单又称投资相连长期保单，保单价值与所购投资表现挂钩并会波动、且一般附有死亡保险金；「保单价值并不挂钩」「没有死亡保险金」「价值可保证」均错误，故该项正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關單位相連長期保單是正確的？",o:["它又稱為投資相連長期保單","利用已支付的保費購買的投資的表現相連，其保單價值並不掛鉤","沒有死亡保險金","它的價值是可保證的"],e:"單位相連長期保單又稱投資相連長期保單，保單價值與所購投資表現掛鈎並會波動、且一般附有死亡保險金；「保單價值並不掛鈎」「沒有死亡保險金」「價值可保證」均錯誤，故該項正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关定期寿险的描述是正确的?",o:["定期寿险是最便宜的人寿保险","它并无累积的现金价值","定期寿险到期时通常并无出现索偿","以上各项皆是"],a:3,e:"定期寿险是人寿保险中最便宜的一类，通常无累积现金价值，且多数保单在不发生索偿的情况下到期；三项描述均正确，故选「以上各项皆是」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關定期壽險的描述是正確的？",o:["定期壽險是最便宜的人壽保險","它並無累積的現金價值","定期壽險到期時通常並無出現索償","以上各項皆是"],e:"定期壽險是人壽保險中最便宜的一類，通常無累積現金價值，且多數保單在不發生索償的情況下到期；三項描述均正確，故選「以上各項皆是」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关投资相连保单是不正确的?",o:["投资股票是其中一类基金类型","只连系于定期及储蓄寿险","全部或部份保费用作购入基金单位","保单价值会波动"],a:1,e:"投资相连保单的基金类型包括股票、固定利息等，保单价值会波动，并以全部或部分保费购入基金单位；「只连系于定期及储蓄寿险」不正确（常见于终身与储蓄寿险），故选该项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關投資相連保單是不正確的？",o:["投資股票是其中一類基金類型","只連繫於定期及儲蓄壽險","全部或部份保費用作購入基金單位","保單價值會波動"],e:"投資相連保單的基金類型包括股票、固定利息等，保單價值會波動，並以全部或部分保費購入基金單位；「只連繫於定期及儲蓄壽險」不正確（常見於終身與儲蓄壽險），故選該項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关投资相连保单的价值的论说是正确的?",o:["必定是保证的","随着投资基金的价值变动而波动","保单价值只会增加,不会减少","上述所有各项"],a:1,e:"投资相连保单的价值随其投资基金（或资产）价值的变动而上下波动，并非保证固定，也不是只会增加不会减少；故「随投资基金价值变动而波动」为正确描述。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關投資相連保單的價值的論說是正確的？",o:["必定是保證的","隨着投資基金的價值變動而波動","保單價值只會增加,不會減少","上述所有各項"],e:"投資相連保單的價值隨其投資基金（或資產）價值的變動而上下波動，並非保證固定，也不是隻會增加不會減少；故「隨投資基金價值變動而波動」為正確描述。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关抵押赎回寿险的陈述是不正确的?",o:["它的意义和按揭赔偿保险相同","它是一项递减定期寿险","它可以用联合寿险方式(如夫妇)","它的出现目的是为了借款人而不是承按人"],a:0,e:"抵押赎回保险是递减定期寿险，代表借款人利益，与以承按人为对象的按揭赔偿保险意义不同；「它的意义和按揭赔偿保险相同」为不正确陈述，其余三项均正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關抵押贖回壽險的陳述是不正確的?",o:["它的意義和按揭賠償保險相同","它是一項遞減定期壽險","它可以用聯合壽險方式(如夫婦)","它的出現目的是為了借款人而不是承按人"],e:"抵押贖回保險是遞減定期壽險，代表借款人利益，與以承按人為對象的按揭賠償保險意義不同；「它的意義和按揭賠償保險相同」為不正確陳述，其餘三項均正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关终身寿险是不正确的?",o:["终身缴付保费","有分红","限定期间内缴付保费","到达某个年龄之后保单就期满"],a:3,e:"终身寿险没有固定期满日期（保障至终身死去），可终身缴费、可分红或不分红，也可限期缴费；「到达某个年龄之后保单就期满」并非终身寿险特性，故该项不正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關終身壽險是不正確的？",o:["終身繳付保費","有分紅","限定期間內繳付保費","到達某個年齡之後保單就期滿"],e:"終身壽險沒有固定期滿日期（保障至終身死去），可終身繳費、可分紅或不分紅，也可限期繳費；「到達某個年齡之後保單就期滿」並非終身壽險特性，故該項不正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项有关终身寿险的陈述是正确的?",o:["终身寿险从来不设分红形式","终身寿险不能获取退保价值","终身寿险只会在保单期满时才支付保额","不论何时去世,终身寿险都会支付保额"],a:3,e:"终身寿险不论受保生命何时去世都会支付保额，并可分为分红形式及累积退保价值；「从来不设分红」「不能获取退保价值」「只期满才付」均错误，故该项正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項有關終身壽險的陳述是正確的？",o:["終身壽險從來不設分紅形式","終身壽險不能獲取退保價值","終身壽險只會在保單期滿時才支付保額","不論何時去世，終身壽險都會支付保額"],e:"終身壽險不論受保生命何時去世都會支付保額，並可分為分紅形式及累積退保價值；「從來不設分紅」「不能獲取退保價值」「只期滿才付」均錯誤，故該項正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"传统寿险产品中,以下哪项不包括有现金价值?",o:["定期寿险","终身寿险","不分红储蓄寿险","分红储蓄寿险"],a:0,e:"传统寿险产品中，定期寿险属纯保障、无现金价值；终身寿险、不分红及分红储蓄寿险均含储蓄成分而累积现金价值，故「不包括现金价值」的为定期寿险。",src:1,tw:{ch:"人壽保險及年金的種類",q:"傳統壽險產品中，以下哪項不包括有現金價值？",o:["定期壽險","終身壽險","不分紅儲蓄壽險","分紅儲蓄壽險"],e:"傳統壽險產品中，定期壽險屬純保障、無現金價值；終身壽險、不分紅及分紅儲蓄壽險均含儲蓄成分而累積現金價值，故「不包括現金價值」的為定期壽險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"保单中可加入什么以提供额外保障或某些附带条件:",o:["附加保费","附加条款(附约)","额外购买另一份保单","以上各项皆不是"],a:1,e:"为提供额外保障或附加某些附带条件，可于保单中加入「附加条款（附约）」，如意外死亡、危疾等附约；附加保费是费用、额外购另一保单则非附约性质，故该项正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"保單中可加入什麼以提供額外保障或某些附帶條件：",o:["附加保費","附加條款(附約)","額外購買另一份保單","以上各項皆不是"],e:"為提供額外保障或附加某些附帶條件，可於保單中加入「附加條款（附約）」，如意外死亡、危疾等附約；附加保費是費用、額外購另一保單則非附約性質，故該項正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"假设基本因素一样,下列哪种计划最便宜?",o:["定期递减寿险","储蓄寿险","终身寿险","递减定期寿险"],a:3,e:"在基本因素相同的情况下，递减定期寿险保额逐年下降、风险保障递减，故保费最低，是四者中最便宜的产品；终身寿险与储蓄寿险含储蓄成分，保费较高。",src:1,tw:{ch:"人壽保險及年金的種類",q:"假設基本因素一樣，下列哪種計劃最便宜？",o:["定期遞減壽險","儲蓄壽險","終身壽險","遞減定期壽險"],e:"在基本因素相同的情況下，遞減定期壽險保額逐年下降、風險保障遞減，故保費最低，是四者中最便宜的產品；終身壽險與儲蓄壽險含儲蓄成分，保費較高。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险一般在哪种情况下作出赔偿?",o:["只有受保生命于保险期内死亡","只有保单期满时,受保人仍然在世","受保生命于保险期内死亡或保单期满时,受保人仍然在世","保障期完结后"],a:2,e:"储蓄寿险在受保生命于保险期内死亡或保单期满时仍生存两种情形下均给付保额，兼有死亡保障与生存储蓄功能；只保死亡或只保生存的选项均不完整。",src:1,tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險一般在哪種情況下作出賠償？",o:["只有受保生命於保險期內死亡","只有保單期滿時，受保人仍然在世","受保生命於保險期內死亡或保單期滿時，受保人仍然在世","保障期完結後"],e:"儲蓄壽險在受保生命於保險期內死亡或保單期滿時仍生存兩種情形下均給付保額，兼有死亡保障與生存儲蓄功能；只保死亡或只保生存的選項均不完整。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险包括纯生存保险及:",o:["递减定期寿险","终身年金","延期年金","定期寿险"],a:3,e:"储蓄寿险由纯生存保险与定期寿险两部分组成，前者提供期满生存给付，后者提供期内死亡保障；终身年金与延期年金属年金产品，故该项正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險包括純生存保險及：",o:["遞減定期壽險","終身年金","延期年金","定期壽險"],e:"儲蓄壽險由純生存保險與定期壽險兩部分組成，前者提供期滿生存給付，後者提供期內死亡保障；終身年金與延期年金屬年金產品，故該項正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险技术上是由储蓄寿险及____________组合而成。",o:["意外保险","定期寿险","医疗保险","第三者责任保险"],a:1,e:"储蓄寿险技术上由定期寿险（提供期内死亡保障）与纯生存（提供期满给付）组合而成；意外、医疗及责任保险属其他险种，不构成储蓄寿险的组合成分。",src:1,tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險技術上是由儲蓄壽險及____________組合而成。",o:["意外保險","定期壽險","醫療保險","第三者責任保險"],e:"儲蓄壽險技術上由定期壽險（提供期內死亡保障）與純生存（提供期滿給付）組合而成；意外、醫療及責任保險屬其他險種，不構成儲蓄壽險的組合成分。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险计划会在指定保险期结束或受保生命早逝时支付保额,亦即是由一份纯生存保险及哪一 种寿险的结合?",o:["年金","储蓄寿险","定期寿险","终身寿险"],a:2,e:"储蓄寿险即纯生存保险与定期寿险的结合：受保生命期满生存或期内死亡均给付保额；年金、终身寿险并非其组合的另一半，故选「定期寿险」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險計劃會在指定保險期結束或受保生命早逝時支付保額，亦即是由一份純生存保險及哪一 種壽險的結合？",o:["年金","儲蓄壽險","定期壽險","終身壽險"],e:"儲蓄壽險即純生存保險與定期壽險的結合：受保生命期滿生存或期內死亡均給付保額；年金、終身壽險並非其組合的另一半，故選「定期壽險」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"储蓄寿险计划在指定保险期结束及受保生命在保险期届满时,仍然生存,是为:",o:["失效","期满","可异议","无效"],a:1,e:"当储蓄寿险保单到达指定保险期结束、且受保生命在期届满时仍然生存，即达到「期满」状态并给付保额；失效、可异议、无效均非此给付情形的正确称谓。",src:1,tw:{ch:"人壽保險及年金的種類",q:"儲蓄壽險計劃在指定保險期結束及受保生命在保險期屆滿時，仍然生存，是為：",o:["失效","期滿","可異議","無效"],e:"當儲蓄壽險保單到達指定保險期結束、且受保生命在期屆滿時仍然生存，即達到「期滿」狀態並給付保額；失效、可異議、無效均非此給付情形的正確稱謂。"}},
{p:3,ch:"人寿保险及年金的种类",q:"关于终身寿险,以下哪三项是不正确的? i 可支付利益每年递增 ii 只有在受保生命去世时,才支付利益 iii 只有经过固定年数之后,才支付利益 iv 经过固定年数或去世时,便支付利益",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"终身寿险只在受保生命去世时才给付利益，且无固定年数或每年递增之利益；「利益每年递增」「固定年数后才支付」「固定年数或去世时支付」均不正确，故选i、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"關於終身壽險，以下哪三項是不正確的？ i 可支付利益每年遞增 ii 只有在受保生命去世時，才支付利益 iii 只有經過固定年數之後，才支付利益 iv 經過固定年數或去世時，便支付利益",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"終身壽險只在受保生命去世時才給付利益，且無固定年數或每年遞增之利益；「利益每年遞增」「固定年數後才支付」「固定年數或去世時支付」均不正確，故選i、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"单位相连保单常见的保单类型为储蓄寿险及",o:["定期寿险","终身寿险","递减定期寿险","递增定期寿险"],a:1,e:"单位相连保单最常见的保单类型是终身寿险及储蓄寿险，两者保单价值与投资基金相连；定期、递减或递增定期寿险均非其常见载体，故选终身寿险。",src:1,tw:{ch:"人壽保險及年金的種類",q:"單位相連保單常見的保單類型為儲蓄壽險及",o:["定期壽險","終身壽險","遞減定期壽險","遞增定期壽險"],e:"單位相連保單最常見的保單類型是終身壽險及儲蓄壽險，兩者保單價值與投資基金相連；定期、遞減或遞增定期壽險均非其常見載體，故選終身壽險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"单位相连保单的特点,是保单价值与投资资产挂钩,要做到这点,可以是与单位信托单位挂钩, 或者?",o:["只有这方法, 仅此而已","与任何股票指数挂钩","与单位化基金挂钩","与红利率挂钩"],a:2,e:"单位相连保单使保单价值与投资资产挂钩，其方法既可连系于单位信托单位，也可连系于「单位化基金」；「仅此一法」「任何股票指数」「红利率」均非规范的挂钩方式。",src:1,tw:{ch:"人壽保險及年金的種類",q:"單位相連保單的特點，是保單價值與投資資產掛鉤，要做到這點，可以是與單位信託單位掛鉤， 或者?",o:["只有這方法， 僅此而已","與任何股票指數掛鉤","與單位化基金掛鉤","與紅利率掛鉤"],e:"單位相連保單使保單價值與投資資產掛鈎，其方法既可連繫於單位信託單位，也可連繫於「單位化基金」；「僅此一法」「任何股票指數」「紅利率」均非規範的掛鈎方式。"}},
{p:3,ch:"人寿保险及年金的种类",q:"单位相连长期保单,最常见于下列哪类型的寿险产品?",o:["定期寿险","终身寿险和储蓄寿险","年金","团体保险"],a:1,e:"单位相连长期保单最常见于终身寿险和储蓄寿险这两类寿险产品中使用；定期寿险、年金及团体保险并非其最典型的产品形态，故选「终身寿险和储蓄寿险」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"單位相連長期保單，最常見於下列哪類型的壽險產品？",o:["定期壽險","終身壽險和儲蓄壽險","年金","團體保險"],e:"單位相連長期保單最常見於終身壽險和儲蓄壽險這兩類壽險產品中使用；定期壽險、年金及團體保險並非其最典型的產品形態，故選「終身壽險和儲蓄壽險」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"受保人的团体保障不再合资格(已终止雇佣合约),保障会:",o:["受保人可以于任何时间以个人保障继续承保","受保人只可取回终止合约后所缴付的保费","受保人只可取回终止合约前所缴付的保费","受保人可以于指定时期内转为个人保险而无需提供可保性证明"],a:3,e:"当雇员因终止雇佣而不再符合团体保障资格时，可于指定时期内转换为个人保险而无需提供可保性证明；并非任何时间均可转换，也非只取回已缴保费，故该项正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"受保人的團體保障不再合資格(已終止僱傭合約)，保障會：",o:["受保人可以於任何時間以個人保障繼續承保","受保人只可取回終止合約後所繳付的保費","受保人只可取回終止合約前所繳付的保費","受保人可以於指定時期內轉為個人保險而無需提供可保性證明"],e:"當僱員因終止僱傭而不再符合團體保障資格時，可於指定時期內轉換為個人保險而無需提供可保性證明；並非任何時間均可轉換，也非只取回已繳保費，故該項正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"受保生命在指定期间死亡或早逝才支付保险金,这属于下列哪类寿险?",o:["年金","储蓄寿险","纯生存保险","定期寿险"],a:3,e:"「受保生命在指定期间死亡或早逝才支付保险金」是定期寿险的定义性特征；年金、储蓄寿险及纯生存保险均涉及生存给付，故该项为定期寿险。",src:1,tw:{ch:"人壽保險及年金的種類",q:"受保生命在指定期間死亡或早逝才支付保險金，這屬於下列哪類壽險？",o:["年金","儲蓄壽險","純生存保險","定期壽險"],e:"「受保生命在指定期間死亡或早逝才支付保險金」是定期壽險的定義性特徵；年金、儲蓄壽險及純生存保險均涉及生存給付，故該項為定期壽險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"受团体保险保障的人称为:",o:["团体被保险人","团体受保生命","受保人","以上所有各项"],a:3,e:"受团体保险保障的人可称为团体被保险人、团体受保生命或受保人，三者的指称均可；故选「以上所有各项」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"受團體保險保障的人稱為：",o:["團體被保險人","團體受保生命","受保人","以上所有各項"],e:"受團體保險保障的人可稱為團體被保險人、團體受保生命或受保人，三者的指稱均可；故選「以上所有各項」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"可续保定期寿险可能涉及逆选择的出现,因此会加上下列哪项/些限制?",o:["调高保额不获续保","限制允许续保的次数","保费率可能高于不可续保的保单","上述各项的限制"],a:3,e:"可续保定期寿险易诱发逆选择，故通常设限制，如调高保额不获续保、限制允许续保次数及保费率高于不可续保保单等；诸项均为可能施加的限制，故选「上述各项的限制」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"可續保定期壽險可能涉及逆選擇的出現，因此會加上下列哪項/些限制？",o:["調高保額不獲續保","限制允許續保的次數","保費率可能高於不可續保的保單","上述各項的限制"],e:"可續保定期壽險易誘發逆選擇，故通常設限制，如調高保額不獲續保、限制允許續保次數及保費率高於不可續保保單等；諸項均為可能施加的限制，故選「上述各項的限制」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"可转换定期寿险可能会出现逆选择。下列哪项是为防止逆选择而设的限制? i 超过某一年龄之后,可能不准转换 ii 新计划保额必须高于目前保单 iii 保单实施若干年后,不可转换 iv 新计划保额不得高于目前保单",o:["i,ii","i,ii,iii","i,iii,iv","ii,iii,iv"],a:2,e:"可转换定期寿险为防止逆选择而设的限制包括：超过某年龄不准转换、保单实施若干年后不可转换，以及新计划保额不得高于目前保单；「保额必须高于目前」恰与限制相反，故正确为i、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"可轉換定期壽險可能會出現逆選擇。下列哪項是為防止逆選擇而設的限制？ i 超過某一年齡之後，可能不准轉換 ii 新計劃保額必須高於目前保單 iii 保單實施若干年後，不可轉換 iv 新計劃保額不得高於目前保單",o:["i,ii","i,ii,iii","i,iii,iv","ii,iii,iv"],e:"可轉換定期壽險為防止逆選擇而設的限制包括：超過某年齡不準轉換、保單實施若干年後不可轉換，以及新計劃保額不得高於目前保單；「保額必須高於目前」恰與限制相反，故正確為i、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"哪一项为购买团体保险的合资格团体?",o:["一个或多个会所","一个或多个工会","一个或多个体育协会","上述各项都是合资格团体"],a:3,e:"购买团体保险的合资格团体可包括会所、工会及体育协会等共同组成的团体；此类团体并非仅限单一雇主，故上述各项都是合资格团体。",src:1,tw:{ch:"人壽保險及年金的種類",q:"哪一項為購買團體保險的合資格團體？",o:["一個或多個會所","一個或多個工會","一個或多個體育協會","上述各項都是合資格團體"],e:"購買團體保險的合資格團體可包括會所、工會及體育協會等共同組成的團體；此類團體並非僅限單一僱主，故上述各項都是合資格團體。"}},
{p:3,ch:"人寿保险及年金的种类",q:"团体保险中,有关技术资料将印制于以下哪些文件内?",o:["总团体保险合约","有关被保险个人的凭证","有关被保险个人的雇员登记卡","以上各项都是"],a:0,e:"团体保险中有关计划的技术资料印制于「总团体保险合约」（主合约）内，由雇主与保险人订立；个别雇员的凭证或登记卡只是证明文件，不承载技术资料，故该项正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"團體保險中，有關技術資料將印制於以下哪些文件內？",o:["總團體保險合約","有關被保險個人的憑證","有關被保險個人的僱員登記卡","以上各項都是"],e:"團體保險中有關計劃的技術資料印製於「總團體保險合約」（主合約）內，由僱主與保險人訂立；個別僱員的憑證或登記卡只是證明文件，不承載技術資料，故該項正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"团体保险中的「在职工作」条款,它的意思是指:",o:["只在工作时受伤才可获得赔偿","只在工作时死亡才可获得赔偿","如要获得有效赔偿,必须在保单保障开始时实际当值工作","于保单保障开始时,当值工作或放假"],a:2,e:"团体保险的「在职工作」条款指被保险人必须在保单保障开始时实际当值工作，才能获得有效保障；并非只在工作时受伤或死亡才赔，也非把放假者纳入有效保障。",src:1,tw:{ch:"人壽保險及年金的種類",q:"團體保險中的「在職工作」條款，它的意思是指：",o:["只在工作時受傷才可獲得賠償","只在工作時死亡才可獲得賠償","如要獲得有效賠償，必須在保單保障開始時實際當值工作","於保單保障開始時，當值工作或放假"],e:"團體保險的「在職工作」條款指被保險人必須在保單保障開始時實際當值工作，才能獲得有效保障；並非只在工作時受傷或死亡才賠，也非把放假者納入有效保障。"}},
{p:3,ch:"人寿保险及年金的种类",q:"团体保险有另外的名称,叫做:",o:["雇主团体保险合约","总团体保险合约","单一雇主保险合约","总雇主保险合约"],a:1,e:"团体保险又称「总团体保险合约」（master group insurance contract），由保险人签发给雇主的主合约；雇主团体、单一雇主及总雇主保险合约均非其标准别名。",src:1,tw:{ch:"人壽保險及年金的種類",q:"團體保險有另外的名稱，叫做：",o:["僱主團體保險合約","總團體保險合約","單一僱主保險合約","總僱主保險合約"],e:"團體保險又稱「總團體保險合約」（master group insurance contract），由保險人簽發給僱主的主合約；僱主團體、單一僱主及總僱主保險合約均非其標準別名。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在万用寿险中,保单和年报分别并且独立向保单所有人披露合约的三个定价因素,包括保障的纯 成本,利息和开支。这样做的根据是:",o:["提高透明度","「分别列示各定价因素」的定价","保险人热衷推介该类产品","因为法律的要求"],a:1,e:"万用寿险分别在保单及年报中独立披露保障纯成本、利息及开支三个定价因素，依据的是「分别列示各定价因素」的透明定价结构；这属产品设计（提高透明度）而非法律强制或推介手段。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在萬用壽險中，保單和年報分別並且獨立向保單所有人披露合約的三個定價因素，包括保障的純 成本，利息和開支。這樣做的根據是：",o:["提高透明度","「分別列示各定價因素」的定價","保險人熱衷推介該類產品","因為法律的要求"],e:"萬用壽險分別在保單及年報中獨立披露保障純成本、利息及開支三個定價因素，依據的是「分別列示各定價因素」的透明定價結構；這屬產品設計（提高透明度）而非法律強制或推介手段。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在人寿保险中,以下哪项对定期寿险的描述是不正确的?",o:["大部分在到期时通常并无出现索偿","它并不会产生现金价值","与终身寿险一样,只是纯保障产品","定期寿险是最便宜的人寿保险"],a:2,e:"定期寿险确属纯保障产品，到期时大多不会出现索偿、不产生现金价值，也是最便宜的人寿保险。但终身寿险兼有储蓄及现金价值成分，并非纯保障产品，故「与终身寿险一样，只是纯保障产品」的陈述不正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在人壽保險中，以下哪項對定期壽險的描述是不正確的？",o:["大部分在到期時通常並無出現索償","它並不會產生現金價值","與終身壽險一樣，只是純保障產品","定期壽險是最便宜的人壽保險"],e:"定期壽險確屬純保障產品，到期時大多不會出現索償、不產生現金價值，也是最便宜的人壽保險。但終身壽險兼有儲蓄及現金價值成分，並非純保障產品，故「與終身壽險一樣，只是純保障產品」的陳述不正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在团体保险中一个合资格的受保人士在开始时拒绝受保,在何种情况下才可得到保障?",o:["永远不可保","过一段时间就可以保","换一个保险人就可以保","只要提供可保性证明,此时可以得到保障"],a:3,e:"团体保险中合资格人士若在开始时拒绝受保，其后须提供可保性证明（证明健康状况可保），保险人才会接纳承保。并非永远不可保，也不取决于更换保险人，故其余选项错误。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在團體保險中一個合資格的受保人士在開始時拒絕受保，在何種情況下才可得到保障？",o:["永遠不可保","過一段時間就可以保","換一個保險人就可以保","只要提供可保性證明，此時可以得到保障"],e:"團體保險中合資格人士若在開始時拒絕受保，其後須提供可保性證明（證明健康狀況可保），保險人才會接納承保。並非永遠不可保，也不取決於更換保險人，故其餘選項錯誤。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在安排人寿保险的过程中,中介人必须向潜在保单所有人提出两个重要的基本问题,第一个是要 确定该名人士可负担的保费,第二个是:",o:["向该中介人缴付的佣金金额","询问投保人属已婚或单身","询问是否按每年或每月缴交保费","询问投购该份寿险的基本目的及意图"],a:3,e:"安排人寿保险时，中介人除须确定投保人可负担的保费外，更要询问其投保寿险的基本目的及意图，以配配合适保障。佣金、婚姻状况或缴费频率均非安排保障应首先厘清的基本问题。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在安排人壽保險的過程中，中介人必須向潛在保單所有人提出兩個重要的基本問題，第一個是要 確定該名人士可負擔的保費，第二個是：",o:["向該中介人繳付的佣金金額","詢問投保人屬已婚或單身","詢問是否按每年或每月繳交保費","詢問投購該份壽險的基本目的及意圖"],e:"安排人壽保險時，中介人除須確定投保人可負擔的保費外，更要詢問其投保壽險的基本目的及意圖，以配配合適保障。佣金、婚姻狀況或繳費頻率均非安排保障應首先釐清的基本問題。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在特定的保险期死亡,而获得一笔特定款项赔付的寿险称之为:",o:["定额定期寿险","一般定期寿险","递减定期寿险","不递减定期寿险"],a:0,e:"在特定保险期内死亡而获一笔固定款项赔付的，是定额定期寿险，其保额在整个保障期内保持不变。一般/不递减定期寿险并非标准分类，递减定期寿险的保额则逐年减少。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在特定的保險期死亡，而獲得一筆特定款項賠付的壽險稱之為：",o:["定額定期壽險","一般定期壽險","遞減定期壽險","不遞減定期壽險"],e:"在特定保險期內死亡而獲一筆固定款項賠付的，是定額定期壽險，其保額在整個保障期內保持不變。一般/不遞減定期壽險並非標準分類，遞減定期壽險的保額則逐年減少。"}},
{p:3,ch:"人寿保险及年金的种类",q:"多种计划可解决递减保障的需要,以下哪种计划可协助解决这方面需要? i 家庭收入寿险 ii 抵押赎回保险 iii 信用寿险 iv 按揭弥偿保险",o:["i, ii","ii, iii","i, ii, iii","ii, iii, iv"],a:2,e:"家庭收入寿险、抵押赎回保险及信用寿险的保障额均随债务或所需收入递减而有助解决递减保障需要。按揭弥偿保险是保障贷款人防止借款人违约，并非递减保障，故不含 iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"多種計劃可解決遞減保障的需要，以下哪種計劃可協助解決這方面需要？ i 家庭收入壽險 ii 抵押贖回保險 iii 信用壽險 iv 按揭彌償保險",o:["i, ii","ii, iii","i, ii, iii","ii, iii, iv"],e:"家庭收入壽險、抵押贖回保險及信用壽險的保障額均隨債務或所需收入遞減而有助解決遞減保障需要。按揭彌償保險是保障貸款人防止借款人違約，並非遞減保障，故不含 iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"大多数的寿险计划,无可避免地会出现索偿,只有一个例外,就是:",o:["定期寿险","储蓄寿险","分红终身寿险","不分红终身寿险"],a:0,e:"定期寿险只在保险期内死亡才赔付，投保人大多活过保障期而无索偿，故可作为「无索偿」的例外。储蓄寿险及终身寿险因具储蓄成分或终身保障，最终几乎必然发生给付。",src:1,tw:{ch:"人壽保險及年金的種類",q:"大多數的壽險計劃，無可避免地會出現索償，只有一個例外，就是：",o:["定期壽險","儲蓄壽險","分紅終身壽險","不分紅終身壽險"],e:"定期壽險只在保險期內死亡才賠付，投保人大多活過保障期而無索償，故可作為「無索償」的例外。儲蓄壽險及終身壽險因具儲蓄成分或終身保障，最終幾乎必然發生給付。"}},
{p:3,ch:"人寿保险及年金的种类",q:"如一份须终身缴付保费的终身寿险,除称为纯粹寿险外,也可称为",o:["无限期缴费终身寿险","永久缴费终身寿险","无止境缴费终身寿险","连续缴费终身寿险"],a:3,e:"须终身缴付保费的终身寿险保障属纯粹保障、无固定缴费期满，故又称连续缴费终身寿险。其余「无限期」「永久」「无止境」缴费等表述并非标准术语。",src:1,tw:{ch:"人壽保險及年金的種類",q:"如一份須終身繳付保費的終身壽險，除稱為純粹壽險外，也可稱為",o:["無限期繳費終身壽險","永久繳費終身壽險","無止境繳費終身壽險","連續繳費終身壽險"],e:"須終身繳付保費的終身壽險保障屬純粹保障、無固定繳費期滿，故又稱連續繳費終身壽險。其餘「無限期」「永久」「無止境」繳費等表述並非標準術語。"}},
{p:3,ch:"人寿保险及年金的种类",q:"如果对于人寿保险有短暂需求,而需求的财务金额于有关时间内不会增加或减少,该保险在指定 期限终结后便告消失。如果在保险成本作为一项主要的考虑的情况下,以下哪一项是最不可取的 一项寿险保障形式?",o:["定额定期寿险","可转换定额定期寿险","分红终身寿险","不分红终身寿险"],a:2,e:"题干所述短暂、金额不变且限期届满即消失的需求，且以成本为主要考虑，应选保额固定的定期寿险。分红终身寿险保费最高且属永久保障，与本需求最不相符，故最不可取。",src:1,tw:{ch:"人壽保險及年金的種類",q:"如果對於人壽保險有短暫需求，而需求的財務金額於有關時間內不會增加或減少，該保險在指定 期限終結後便告消失。如果在保險成本作為一項主要的考慮的情況下，以下哪一項是最不可取的 一項壽險保障形式？",o:["定額定期壽險","可轉換定額定期壽險","分紅終身壽險","不分紅終身壽險"],e:"題幹所述短暫、金額不變且限期屆滿即消失的需求，且以成本為主要考慮，應選保額固定的定期壽險。分紅終身壽險保費最高且屬永久保障，與本需求最不相符，故最不可取。"}},
{p:3,ch:"人寿保险及年金的种类",q:"定期寿险的保单利益只会于死亡时保单仍属生效,而及以下哪类或哪些情况下才会支付?",o:["被保人在保单生效的整个期间仍然生存","被保人证实患上危疾","在指明的期限内死亡","在指明的期限后死亡"],a:2,e:"定期寿险只在受保人在指明的保障期限内死亡，且保单仍属生效时才支付身故利益。生存至期满、患上危疾或期限后死亡均不符合定期寿险的给付条件。",src:1,tw:{ch:"人壽保險及年金的種類",q:"定期壽險的保單利益只會於死亡時保單仍屬生效，而及以下哪類或哪些情況下才會支付？",o:["被保人在保單生效的整個期間仍然生存","被保人証實患上危疾","在指明的期限內死亡","在指明的期限後死亡"],e:"定期壽險只在受保人在指明的保障期限內死亡，且保單仍屬生效時才支付身故利益。生存至期滿、患上危疾或期限後死亡均不符合定期壽險的給付條件。"}},
{p:3,ch:"人寿保险及年金的种类",q:"定额定期寿险适用于:",o:["未来退休时的退休金","于指明日期后的年金收入","用于未偿还一笔没有分期付款的贷款","保险终结时支付学费"],a:2,e:"定额定期寿险保额固定，适合保障一笔在保障期内不会变化、也不会分期摊还的未偿贷款余额。退休金、年金收入及学费属长期或未来需求，与定额定期寿险的短暂保障不相匹配。",src:1,tw:{ch:"人壽保險及年金的種類",q:"定額定期壽險適用於:",o:["未來退休時的退休金","於指明日期後的年金收入","用於未償還一筆沒有分期付款的貸款","保險終結時支付學費"],e:"定額定期壽險保額固定，適合保障一筆在保障期內不會變化、也不會分期攤還的未償貸款餘額。退休金、年金收入及學費屬長期或未來需求，與定額定期壽險的短暫保障不相匹配。"}},
{p:3,ch:"人寿保险及年金的种类",q:"容许保单所有人将保单由指定期限转为一个永久计划,这种保单称为:",o:["可转让的","可改变的","非永久性的","可转换的"],a:3,e:"容许保单所有人将定期保单在指定期限内转为永久计划（如终身寿险）且通常无须可保证明的，称为可转换的保单。可转让、可改变或非永久性均非此特权的标准名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"容許保單所有人將保單由指定期限轉為一個永久計劃，這種保單稱為：",o:["可轉讓的","可改變的","非永久性的","可轉換的"],e:"容許保單所有人將定期保單在指定期限內轉為永久計劃（如終身壽險）且通常無須可保證明的，稱為可轉換的保單。可轉讓、可改變或非永久性均非此特權的標準名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"就一份死亡保单而言,如果该保额可由投保人领取,以下哪一种保险最有可能出现?",o:["储蓄寿险","终身寿险","递减定期寿险","定额定期寿险"],a:0,e:"死亡保单的保额若可由投保人本人领取，最可能出现于储蓄寿险，因为它同时提供满期生存利益，投保人在生也可领取保额。终身及定期寿险主要在死亡时给付，不符合此情况。",src:1,tw:{ch:"人壽保險及年金的種類",q:"就一份死亡保單而言，如果該保額可由投保人領取，以下哪一種保險最有可能出現？",o:["儲蓄壽險","終身壽險","遞減定期壽險","定額定期壽險"],e:"死亡保單的保額若可由投保人本人領取，最可能出現於儲蓄壽險，因為它同時提供滿期生存利益，投保人在生也可領取保額。終身及定期壽險主要在死亡時給付，不符合此情況。"}},
{p:3,ch:"人寿保险及年金的种类",q:"就本质上属于投资形式的寿险产品而言,其中最值得注意的一点,就是要确保消费者明白下列哪 项或哪些?",o:["必须尽早缴付保费","保单价值可升亦可跌","保险人必然保证最低的投资回报","上述所有各项"],a:1,e:"投资相连寿险属投资性质，购买者须明白其保单价值随投资表现可升亦可跌。保险人并不必然保证最低投资回报，保费亦须持续缴付而非「尽早缴付」，故答案为可升可跌。",src:1,tw:{ch:"人壽保險及年金的種類",q:"就本質上屬於投資形式的壽險產品而言，其中最值得注意的一點，就是要確保消費者明白下列哪 項或哪些？",o:["必須盡早繳付保費","保單價值可升亦可跌","保險人必然保證最低的投資回報","上述所有各項"],e:"投資相連壽險屬投資性質，購買者須明白其保單價值隨投資表現可升亦可跌。保險人並不必然保證最低投資回報，保費亦須持續繳付而非「儘早繳付」，故答案為可升可跌。"}},
{p:3,ch:"人寿保险及年金的种类",q:"就递增定期寿险而言:",o:["保险利益和保费按年或其他认可方式随时递增","保险利益递增,保费不变","保费递增,保险利益不变","只有当保单所有人提出时才递增"],a:0,e:"递增定期寿险的保险利益与保费均按年或按约定方式递增，以配合通货膨胀或增长的需要。并非仅利益递增而保费不变，也非待保单所有人提出后才递增。",src:1,tw:{ch:"人壽保險及年金的種類",q:"就遞增定期壽險而言：",o:["保險利益和保費按年或其他認可方式隨時遞增","保險利益遞增，保費不變","保費遞增，保險利益不變","只有當保單所有人提出時才遞增"],e:"遞增定期壽險的保險利益與保費均按年或按約定方式遞增，以配合通貨膨脹或增長的需要。並非僅利益遞增而保費不變，也非待保單所有人提出後才遞增。"}},
{p:3,ch:"人寿保险及年金的种类",q:"当定期寿险到期时,可有以下哪些/哪项选择?",o:["可续保保险期至终身","可转换至终身寿险,但要向保险人提供可保证明","续保时,保额只可等于或少于原保额","以上所有各项"],a:2,e:"定期寿险到期续保时，保额一般只可等于或少于原保额，不能增加。续保并非自动至终身，转换至终身寿险通常亦无须另提供可保证明，故其余选项不准确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"當定期壽險到期時，可有以下哪些/哪項選擇？",o:["可續保保險期至終身","可轉換至終身壽險，但要向保險人提供可保證明","續保時，保額只可等於或少於原保額","以上所有各項"],e:"定期壽險到期續保時，保額一般只可等於或少於原保額，不能增加。續保並非自動至終身，轉換至終身壽險通常亦無須另提供可保證明，故其餘選項不準確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"当终身寿险须终身缴付保费,可以称为纯粹寿险或:",o:["无限期终身缴付保费保单","永久终身缴付保费保单","无止境终身缴付保费保单","连续缴费终身寿险单"],a:3,e:"须终身缴付保费的终身寿险没有固定缴费期满，其保障持续至身故，故又称连续缴费终身寿险单。题中「无限期」「永久」「无止境」等表述均非标准术语。",src:1,tw:{ch:"人壽保險及年金的種類",q:"當終身壽險須終身繳付保費，可以稱為純粹壽險或：",o:["無限期終身繳付保費保單","永久終身繳付保費保單","無止境終身繳付保費保單","連續繳費終身壽險單"],e:"須終身繳付保費的終身壽險沒有固定繳費期滿，其保障持續至身故，故又稱連續繳費終身壽險單。題中「無限期」「永久」「無止境」等表述均非標準術語。"}},
{p:3,ch:"人寿保险及年金的种类",q:"所有类型的相连长期保单的形式是?",o:["保单属分红性质","单位与股票基金挂钩","保险人必须保证基金单位是最低保证价格","部分或全部保费用作购买基金单位"],a:3,e:"相连长期保单的保费全部或部分用于购买基金单位，其利益随基金表现变动。相连保单通常不具分红性质，保险人亦不保证基金单位的最低价格。",src:1,tw:{ch:"人壽保險及年金的種類",q:"所有類型的相連長期保單的形式是?",o:["保單屬分紅性質","單位與股票基金掛鉤","保險人必須保證基金單位是最低保證價格","部分或全部保費用作購買基金單位"],e:"相連長期保單的保費全部或部分用於購買基金單位，其利益隨基金表現變動。相連保單通常不具分紅性質，保險人亦不保證基金單位的最低價格。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投保人对保费不是主要的考虑因素,然而考虑保单生效一段时候后(例20年后),或出现早逝的 情况下,投保人可获最高的利益。以下哪种计划是可考虑的?",o:["定额定期寿险","分红储蓄寿险","分红终身寿险","不分红终身寿险"],a:1,e:"当保费非主要考虑，而希望在保单生效一段时间后或早逝时获最高利益，分红储蓄寿险最为合适，因其满期及身故均给付保额并可享红利。定期寿险到期无现金价值，终身寿险则在生时不能领取保额。",src:1,tw:{ch:"人壽保險及年金的種類",q:"投保人對保費不是主要的考慮因素，然而考慮保單生效一段時候後（例20年後），或出現早逝的 情況下，投保人可獲最高的利益。以下哪種計劃是可考慮的？",o:["定額定期壽險","分紅儲蓄壽險","分紅終身壽險","不分紅終身壽險"],e:"當保費非主要考慮，而希望在保單生效一段時間後或早逝時獲最高利益，分紅儲蓄壽險最為合適，因其滿期及身故均給付保額並可享紅利。定期壽險到期無現金價值，終身壽險則在生時不能領取保額。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投资相连长期保单,其利益收入:",o:["设有最低保证金额","受到特定上限的约束","随投资产品的表现而变动","不随投资产品的表现而变动"],a:2,e:"投资相连长期保单的现金价值及利益直接随所投资产品的表现而上下变动，不设最低保证金额，也不受特定上限约束。故其利益收入取决于投资表现。",src:1,tw:{ch:"人壽保險及年金的種類",q:"投資相連長期保單，其利益收入：",o:["設有最低保證金額","受到特定上限的約束","隨投資產品的表現而變動","不隨投資產品的表現而變動"],e:"投資相連長期保單的現金價值及利益直接隨所投資產品的表現而上下變動，不設最低保證金額，也不受特定上限約束。故其利益收入取決於投資表現。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投资相连长期保单可与哪类保险组合?",o:["储蓄寿险","定期寿险","终身寿险","以上所列各项"],a:3,e:"投资相连长期保单可分别与储蓄寿险、定期寿险或终身寿险组合，以提供不同保障及投资安排。题中各项组合均可行，故答案为以上所列各项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"投資相連長期保單可與哪類保險組合？",o:["儲蓄壽險","定期壽險","終身壽險","以上所列各項"],e:"投資相連長期保單可分別與儲蓄壽險、定期壽險或終身壽險組合，以提供不同保障及投資安排。題中各項組合均可行，故答案為以上所列各項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"投资相连长期保单的价值是:",o:["可保证的","可能会上升,但不可能下跌","按基金单位的价值作出调整","按恒生指数现值作出调整"],a:2,e:"投资相连长期保单的价值按所对应的基金单位价值作出调整，随基金表现增减，并无保证。其价值并非按恒生指数现值，也与固定保证金额无关。",src:1,tw:{ch:"人壽保險及年金的種類",q:"投資相連長期保單的價值是：",o:["可保證的","可能會上升，但不可能下跌","按基金單位的價值作出調整","按恒生指數現值作出調整"],e:"投資相連長期保單的價值按所對應的基金單位價值作出調整，隨基金表現增減，並無保證。其價值並非按恒生指數現值，也與固定保證金額無關。"}},
{p:3,ch:"人寿保险及年金的种类",q:"收取年金款项的人是",o:["保单持有人","年金购买人","收款人","受益人"],a:2,e:"在年金安排中，收取年金款项的人称为收款人。保单持有人是购买及拥有保单者，年金购买人未必是收款人，受益人的概念亦不同。",src:1,tw:{ch:"人壽保險及年金的種類",q:"收取年金款項的人是",o:["保單持有人","年金購買人","收款人","受益人"],e:"在年金安排中，收取年金款項的人稱為收款人。保單持有人是購買及擁有保單者，年金購買人未必是收款人，受益人的概念亦不同。"}},
{p:3,ch:"人寿保险及年金的种类",q:"早期的基本寿险保单在发生死亡时支付一整笔款项,下列哪项不属于基本保单里的基本变数/修 正:",o:["参与分享保险人的利润","保单所有人有权选择将保单转换为另一个不同计划的可转换性","以附约形式加入各类保障","在保险公司全体大会上投票的权利"],a:3,e:"早期基本寿险保单以死亡给付为本，其基本变数包括参与分享利润、可转换性及以附约加入各类保障。在保险公司股东大会投票的权利属公司事务，并非保单本身的基本修正。",src:1,tw:{ch:"人壽保險及年金的種類",q:"早期的基本壽險保單在發生死亡時支付一整筆款項,下列哪項不屬於基本保單裏的基本變數/修 正:",o:["參與分享保險人的利潤","保單所有人有權選擇將保單轉換為另一個不同計劃的可轉換性","以附約形式加入各類保障","在保險公司全體大會上投票的權利"],e:"早期基本壽險保單以死亡給付為本，其基本變數包括參與分享利潤、可轉換性及以附約加入各類保障。在保險公司股東大會投票的權利屬公司事務，並非保單本身的基本修正。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一个人购买了一间住宅楼宇。他为楼宇借了一笔十年期的贷款,于十年内分期偿还本金及利息 ,而十年后便清还所有贷款金额。他欲购买最便宜的人寿保险,确保不幸于十年内死亡,可以利 用保险金偿还当时的贷款余额。这种保险最有可能是:",o:["终身寿险","定期寿险","储蓄寿险","递减定期寿险"],a:3,e:"贷款余额随十年分期摊还而逐年递减，要以便宜保费保障递减的未偿余额，递减定期寿险最合适。终身、定期及储蓄寿险保额不变或成本较高，均非最匹配。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一個人購買了一間住宅樓宇。他為樓宇借了一筆十年期的貸款，於十年內分期償還本金及利息 ，而十年後便清還所有貸款金額。他欲購買最便宜的人壽保險，確保不幸於十年內死亡，可以利 用保險金償還當時的貸款餘額。這種保險最有可能是：",o:["終身壽險","定期壽險","儲蓄壽險","遞減定期壽險"],e:"貸款餘額隨十年分期攤還而逐年遞減，要以便宜保費保障遞減的未償餘額，遞減定期壽險最合適。終身、定期及儲蓄壽險保額不變或成本較高，均非最匹配。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一准投保人希望购买一份保单,他希望在逝世时提供一笔事先约定好的保险金,但他表示并不 在生时运用这笔保险金额,以下那项适合他?",o:["定期寿险","分红储蓄寿险","终身寿险","定额年金"],a:2,e:"希望身故时给付一笔事先约定的保险金、且生前无须运用该笔款项，终身寿险最合适，因其保障终身且必然给付。定期寿险到期可能无理赔，储蓄寿险及年金则不符死亡给付为主的诉求。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一準投保人希望購買一份保單，他希望在逝世時提供一筆事先約定好的保險金，但他表示並不 在生時運用這筆保險金額，以下那項適合他？",o:["定期壽險","分紅儲蓄壽險","終身壽險","定額年金"],e:"希望身故時給付一筆事先約定的保險金、且生前無須運用該筆款項，終身壽險最合適，因其保障終身且必然給付。定期壽險到期可能無理賠，儲蓄壽險及年金則不符死亡給付為主的訴求。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一张保单能同时为多人提供保障,此类保类称为:",o:["团体保险","商业保险","人寿保险","家居保险"],a:0,e:"一张保单同时为团体中多人提供寿险保障的，称为团体保险。商业保险是类别统称，家居保险属财产险，人寿保险通常针对个人生命，均不符「同时为多人」的定义。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一張保單能同時為多人提供保障，此類保類稱為：",o:["團體保險","商業保險","人壽保險","家居保險"],e:"一張保單同時為團體中多人提供壽險保障的，稱為團體保險。商業保險是類別統稱，家居保險屬財產險，人壽保險通常針對個人生命，均不符「同時為多人」的定義。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一种保单,它就指定有效期内出现的死亡给付利益,并为该保单每年相同的利益设定相同的保 费,这种保单称为:",o:["终身寿险","定额定期寿险","固定限期寿险","不变动定期寿险"],a:1,e:"在指定有效期内死亡即给付、且每年利益相同并收取相同保费的保单，称为定额定期寿险，其保额在期内固定不变。其余选项并非标准产品名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一種保單，它就指定有效期內出現的死亡給付利益，並為該保單每年相同的利益設定相同的保 費，這種保單稱為：",o:["終身壽險","定額定期壽險","固定限期壽險","不變動定期壽險"],e:"在指定有效期內死亡即給付、且每年利益相同並收取相同保費的保單，稱為定額定期壽險，其保額在期內固定不變。其餘選項並非標準產品名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一种保险提供非常灵活的特征,它可以选择死亡保险金是保额加上现金价值或者单单以保额作 为死亡保险金。它称为:",o:["定期寿险","终身寿险","万用寿险","储蓄寿险"],a:2,e:"万用寿险保费灵活，投保人可选死亡保险金为「保额加现金价值」或「仅保额」的可调整形式。定期、终身及储蓄寿险并不具备这种灵活取舍特征。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一種保險提供非常靈活的特徵，它可以選擇死亡保險金是保額加上現金價值或者單單以保額作 為死亡保險金。它稱為：",o:["定期壽險","終身壽險","萬用壽險","儲蓄壽險"],e:"萬用壽險保費靈活，投保人可選死亡保險金為「保額加現金價值」或「僅保額」的可調整形式。定期、終身及儲蓄壽險並不具備這種靈活取捨特徵。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一种寿险计划保障贷款人,在借款人未完全偿还欠款之前死亡可获得支付,这种计划称为:",o:["信用寿险","按揭弥偿保险","抵押赎回保险","家庭收入寿险"],a:0,e:"信用寿险保障贷款人，在借款人未完全清还欠款前死亡时给付，以清偿未偿债务。按揭弥偿保险保障的是贷款人而非借款人死亡，抵押赎回及家庭收入寿险对象亦不同。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一種壽險計劃保障貸款人，在借款人未完全償還欠款之前死亡可獲得支付，這種計劃稱為：",o:["信用壽險","按揭彌償保險","抵押贖回保險","家庭收入壽險"],e:"信用壽險保障貸款人，在借款人未完全清還欠款前死亡時給付，以清償未償債務。按揭彌償保險保障的是貸款人而非借款人死亡，抵押贖回及家庭收入壽險對象亦不同。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一种寿险计划的保险利益会不断地递减并只有在保险期内死亡方可获得支付,这种计划称为:",o:["定额定期寿险","相同的定期寿险","递减定期寿险","非递减定期寿险"],a:2,e:"保险利益随其保障目的（如贷款余额）不断递减、且仅在保险期内死亡才给付的，称为递减定期寿险。定额或非递减定期寿险保额固定，不符合递减特征。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一種壽險計劃的保險利益會不斷地遞減並只有在保險期內死亡方可獲得支付，這種計劃稱為：",o:["定額定期壽險","相同的定期壽險","遞減定期壽險","非遞減定期壽險"],e:"保險利益隨其保障目的（如貸款餘額）不斷遞減、且僅在保險期內死亡才給付的，稱為遞減定期壽險。定額或非遞減定期壽險保額固定，不符合遞減特徵。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一类寿险保单的条文,容许被保险人把保障范围更改为较广泛形式的计划,这一类保单一般称 为:",o:["可选择的","可改变的","可转换的","可转让的"],a:2,e:"容许被保险人将保障范围改为更广泛形式计划的条款，称为可转换的保单。可改变、可转让或可选择均非描述此项转换特权的标准术语。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一類壽險保單的條文，容許被保險人把保障範圍更改為較廣泛形式的計劃，這一類保單一般稱 為：",o:["可選擇的","可改變的","可轉換的","可轉讓的"],e:"容許被保險人將保障範圍改為更廣泛形式計劃的條款，稱為可轉換的保單。可改變、可轉讓或可選擇均非描述此項轉換特權的標準術語。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有一类寿险称为短期人寿保险,但更常称为:",o:["定期寿险","终身寿险","储蓄寿险","年金"],a:0,e:"短期人寿保险保障一段指定期间，更常被称为定期寿险。终身寿险保障终身，储蓄寿险兼具储蓄成分，年金提供定期收入，均非短期人寿的对应名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有一類壽險稱為短期人壽保險，但更常稱為：",o:["定期壽險","終身壽險","儲蓄壽險","年金"],e:"短期人壽保險保障一段指定期間，更常被稱為定期壽險。終身壽險保障終身，儲蓄壽險兼具儲蓄成分，年金提供定期收入，均非短期人壽的對應名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"有种寿险计划具有灵活保费﹑可调整的保险金及「分别列示各定价因素」的定价结构,这称为:",o:["单位相连长期保险","万用寿险","储蓄寿险","终身寿险"],a:1,e:"万用寿险具有灵活保费、可调整的保险金，并分别列示死亡率、费用及利息等定价因素的透明结构。单位相连、储蓄及终身寿险并无此种弹性定价设计。",src:1,tw:{ch:"人壽保險及年金的種類",q:"有種壽險計劃具有靈活保費﹑可調整的保險金及「分別列示各定價因素」的定價結構，這稱為：",o:["單位相連長期保險","萬用壽險","儲蓄壽險","終身壽險"],e:"萬用壽險具有靈活保費、可調整的保險金，並分別列示死亡率、費用及利息等定價因素的透明結構。單位相連、儲蓄及終身壽險並無此種彈性定價設計。"}},
{p:3,ch:"人寿保险及年金的种类",q:"某人欲于身故后捐出一笔不多及不少于一百万给其母校,您会建议他以最少的保费购买哪类保险 呢?",o:["分红储蓄寿险","不分红储蓄寿险","分红终身寿险","不分红终身寿险"],a:3,e:"要为母校身故后定额捐赠一百万元，须以最少保费获得固定死亡保额，不分红终身寿险最合适，因其成本较低且保额确定。分红终身寿险及储蓄寿险保费较高，不符合成本要求。",src:1,tw:{ch:"人壽保險及年金的種類",q:"某人欲於身故後捐出一筆不多及不少於一百萬給其母校，您會建議他以最少的保費購買哪類保險 呢？",o:["分紅儲蓄壽險","不分紅儲蓄壽險","分紅終身壽險","不分紅終身壽險"],e:"要為母校身故後定額捐贈一百萬元，須以最少保費獲得固定死亡保額，不分紅終身壽險最合適，因其成本較低且保額確定。分紅終身壽險及儲蓄壽險保費較高，不符合成本要求。"}},
{p:3,ch:"人寿保险及年金的种类",q:"核保时以下哪项寿险产品,通常不会要求详细的个人资料?",o:["终身寿险","团体寿险","万用寿险","递减定期寿险"],a:1,e:"团体寿险以整体核保为主，通常不要求每位雇员提供详细个人资料。终身寿险、万用寿险及递减定期寿险均属个人产品，投保时一般需提交详细健康及财务资料。",src:1,tw:{ch:"人壽保險及年金的種類",q:"核保時以下哪項壽險產品，通常不會要求詳細的個人資料？",o:["終身壽險","團體壽險","萬用壽險","遞減定期壽險"],e:"團體壽險以整體核保為主，通常不要求每位僱員提供詳細個人資料。終身壽險、萬用壽險及遞減定期壽險均屬個人產品，投保時一般需提交詳細健康及財務資料。"}},
{p:3,ch:"人寿保险及年金的种类",q:"根据定期寿险的有效索偿是需要符合以下哪些或哪项?",o:["可保权益在保单生效时已经存在","在死亡发生时保单仍然生效","死亡在指定时间内发生","以上各项皆是"],a:3,e:"定期寿险若要有效索偿，须可保权益在保单生效时已存在、死亡发生时保单仍属生效，且死亡发生在指定保障期限内，三项缺一不可。故答案为以上各项皆是。",src:1,tw:{ch:"人壽保險及年金的種類",q:"根據定期壽險的有效索償是需要符合以下哪些或哪項？",o:["可保權益在保單生效時已經存在","在死亡發生時保單仍然生效","死亡在指定時間內發生","以上各項皆是"],e:"定期壽險若要有效索償，須可保權益在保單生效時已存在、死亡發生時保單仍屬生效，且死亡發生在指定保障期限內，三項缺一不可。故答案為以上各項皆是。"}},
{p:3,ch:"人寿保险及年金的种类",q:"根据有关《合资格延期年金保单指引》的规定,保险人必须在课税年度(即3月31日)结束后多 久内向保单持有人发出该保单的年度摘要?",o:["30天","40天","45天","50天"],a:1,e:"根据《合资格延期年金保单指引》，保险人须在课税年度（3月31日）结束后 40 天内向保单持有人发出该保单的年度摘要。30、45 及 50 天均不符指定时限。",src:1,tw:{ch:"人壽保險及年金的種類",q:"根據有關《合資格延期年金保單指引》的規定，保險人必須在課稅年度（即3月31日）結束後多 久內向保單持有人發出該保單的年度摘要？",o:["30天","40天","45天","50天"],e:"根據《合資格延期年金保單指引》，保險人須在課税年度（3月31日）結束後 40 天內向保單持有人發出該保單的年度摘要。30、45 及 50 天均不符指定時限。"}},
{p:3,ch:"人寿保险及年金的种类",q:"相比于终身寿险及储蓄寿险,以下哪项有关定期寿险的描述是正确的?",o:["保费是最便宜的","大多数情况下,在保单到期时仍未出现索偿","只提供短暂的保障","上述所有各项"],a:3,e:"相比之下，定期寿险保费最便宜、大多在到期时仍未出现索偿，且只提供短暂保障，三者均正确。终身及储蓄寿险保费较高并具现金价值，故答案为上述所有各项。",src:1,tw:{ch:"人壽保險及年金的種類",q:"相比於終身壽險及儲蓄壽險，以下哪項有關定期壽險的描述是正確的？",o:["保費是最便宜的","大多數情況下，在保單到期時仍未出現索償","只提供短暫的保障","上述所有各項"],e:"相比之下，定期壽險保費最便宜、大多在到期時仍未出現索償，且只提供短暫保障，三者均正確。終身及儲蓄壽險保費較高並具現金價值，故答案為上述所有各項。"}},
{p:3,ch:"人寿保险及年金的种类",q:"确定期间终身年金与下列哪项相同?",o:["即期年金","延期年金","确定年金","终身年金"],a:3,e:"确定期间终身年金同时具备确定期间保证给付与终身给付的特征，本质与确定期间终身年金等同，故与「终身年金」最接近。即期、延期及确定年金并非该产品的同义名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"確定期間終身年金與下列哪項相同？",o:["即期年金","延期年金","確定年金","終身年金"],e:"確定期間終身年金同時具備確定期間保證給付與終身給付的特徵，本質與確定期間終身年金等同，故與「終身年金」最接近。即期、延期及確定年金並非該產品的同義名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"纯生存保险于支付利益时需要满足以下哪个条件?",o:["受保人是意外死亡","受保人于保单期满时仍然生存","于保单保障期间是已去世的儿童","期满时属于可保风险"],a:1,e:"纯生存保险只在受保人于保单期满时仍然生存才给付利益，属生存给付性质。意外死亡、儿童期内身故或期满属可保风险均非其给付条件。",src:1,tw:{ch:"人壽保險及年金的種類",q:"純生存保險於支付利益時需要滿足以下哪個條件?",o:["受保人是意外死亡","受保人於保單期滿時仍然生存","於保單保障期間是已去世的兒童","期滿時屬於可保風險"],e:"純生存保險只在受保人於保單期滿時仍然生存才給付利益，屬生存給付性質。意外死亡、兒童期內身故或期滿屬可保風險均非其給付條件。"}},
{p:3,ch:"人寿保险及年金的种类",q:"纯粹终身人寿保险的另一个名称是",o:["无止境缴费终身寿险保单","永久缴费终身寿险保单","无限期缴费终身寿险保单","连续缴费终身寿险保单"],a:3,e:"纯粹终身人寿保险须终身缴付保费，没有固定缴费期满，故又称连续缴费终身寿险保单。题中「无止境」「永久」「无限期」等均非标准名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"純粹終身人壽保險的另一個名稱是",o:["無止境繳費終身壽險保單","永久繳費終身壽險保單","無限期繳費終身壽險保單","連續繳費終身壽險保單"],e:"純粹終身人壽保險須終身繳付保費，沒有固定繳費期滿，故又稱連續繳費終身壽險保單。題中「無止境」「永久」「無限期」等均非標準名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"纯粹终身人寿属于:",o:["只对指定时间内的死亡支付赔偿","只赔偿受保生命因意外导致死亡","受保生命于生命结束前都需要连续终身缴付保费","经过固定年数后或去世的时候,便支付利益"],a:2,e:"纯粹终身人寿保险不含储蓄成分，受保生命在去世前须持续缴付保费，直至身故才给付。它并非只对指定时间内的死亡或仅意外死亡赔付，也不在固定年期后给付。",src:1,tw:{ch:"人壽保險及年金的種類",q:"純粹終身人壽屬於：",o:["只對指定時間內的死亡支付賠償","只賠償受保生命因意外導致死亡","受保生命於生命結束前都需要連續終身繳付保費","經過固定年數後或去世的時候，便支付利益"],e:"純粹終身人壽保險不含儲蓄成分，受保生命在去世前須持續繳付保費，直至身故才給付。它並非只對指定時間內的死亡或僅意外死亡賠付，也不在固定年期後給付。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险单有一种变化,保费定期递增,例如每三年一次,但保额保持不变,称为:",o:["等级保费保险单","永久终身寿险单","连续终身寿险单","递增保费人寿保单"],a:0,e:"等级保费保险单采用定期（如每三年）递增的保费而保额保持不变的缴费结构。永久、连续或递增保费保单并非描述此「保费分步递增、保额不变」特征的标准名称。",src:1,tw:{ch:"人壽保險及年金的種類",q:"終身壽險單有一種變化，保費定期遞增，例如每三年一次，但保額保持不變，稱為：",o:["等級保費保險單","永久終身壽險單","連續終身壽險單","遞增保費人壽保單"],e:"等級保費保險單採用定期（如每三年）遞增的保費而保額保持不變的繳費結構。永久、連續或遞增保費保單並非描述此「保費分步遞增、保額不變」特徵的標準名稱。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险有哪些缴费方式?",o:["于指定期限内缴费","缴费直至指定年龄","缴费直至受保人去世","视乎情况,可选择以上的方法缴费"],a:3,e:"终身寿险的缴费方式灵活，可于指定期限内缴付、缴至指定年龄或缴至受保人身故。具体采用哪种方式视乎保单安排，故答案为视乎情况可选以上方法。",src:1,tw:{ch:"人壽保險及年金的種類",q:"終身壽險有哪些繳費方式？",o:["於指定期限內繳費","繳費直至指定年齡","繳費直至受保人去世","視乎情況，可選擇以上的方法繳費"],e:"終身壽險的繳費方式靈活，可於指定期限內繳付、繳至指定年齡或繳至受保人身故。具體採用哪種方式視乎保單安排，故答案為視乎情況可選以上方法。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险的保费:",o:["在指定年数后,无须再缴付保费","在指定年岁后,无须再缴付保费","在受保生命生存期间须缴付保费","以上各项都是"],a:3,e:"终身寿险的保费可按保单于指定年数后或指定年岁后免缴，也可在受保生命生存期间持续缴付，视乎缴费安排不同。故「以上各项都是」正确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"終身壽險的保費：",o:["在指定年數後，無須再繳付保費","在指定年歲後，無須再繳付保費","在受保生命生存期間須繳付保費","以上各項都是"],e:"終身壽險的保費可按保單于指定年數後或指定年歲後免繳，也可在受保生命生存期間持續繳付，視乎繳費安排不同。故「以上各項都是」正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险的保费结构有许多的变化,以下哪项最不可能包括在内?",o:["于在生期间每年支付保费","于限定期间内缴付保费","于指定年龄前支付保费","保单生效时以一笔过支付保费"],a:3,e:"终身寿险的保费结构包括在生期间每年支付、于限定期间内缴付或于指定年龄前支付。在保单生效时以一笔过（趸缴）缴付保费最不可能属于终身寿险的常规缴费结构变化。",src:1,tw:{ch:"人壽保險及年金的種類",q:"終身壽險的保費結構有許多的變化，以下哪項最不可能包括在內？",o:["於在生期間每年支付保費","於限定期間內繳付保費","於指定年齡前支付保費","保單生效時以一筆過支付保費"],e:"終身壽險的保費結構包括在生期間每年支付、於限定期間內繳付或於指定年齡前支付。在保單生效時以一筆過（躉繳）繳付保費最不可能屬於終身壽險的常規繳費結構變化。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险的保费结构有许多的变化,其中等级保费保险的保费会定期(通常每三年)增加一次,而 保额会:",o:["维持不变","每3年按比例递增","每3年按比例递减","只会因意外导致死亡才会增加"],a:0,e:"等级保费保险的保费会定期（通常每三年）递增一次，但保额在保期内维持不变。保额并不随保费递增或递减，也不会仅在意外死亡时才增加。",src:1,tw:{ch:"人壽保險及年金的種類",q:"終身壽險的保費結構有許多的變化，其中等級保費保險的保費會定期(通常每三年)增加一次，而 保額會：",o:["維持不變","每3年按比例遞增","每3年按比例遞減","只會因意外導致死亡才會增加"],e:"等級保費保險的保費會定期（通常每三年）遞增一次，但保額在保期內維持不變。保額並不隨保費遞增或遞減，也不會僅在意外死亡時才增加。"}},
{p:3,ch:"人寿保险及年金的种类",q:"终身寿险的特点为:",o:["只对指定时期内的死亡支付赔偿","任何时候受保生命去世,即支付赔偿","在某一特定日期前死亡支付赔偿","保险人按月支付补偿给投保人"],a:1,e:"终身寿险的核心特点是无论受保人在任何时候去世，均会支付身故赔偿，保障终身。它并非限指定时期或特定日期前的死亡，也非按月给付补偿。",src:1,tw:{ch:"人壽保險及年金的種類",q:"終身壽險的特點為：",o:["只對指定時期內的死亡支付賠償","任何時候受保生命去世，即支付賠償","在某一特定日期前死亡支付賠償","保險人按月支付補償給投保人"],e:"終身壽險的核心特點是無論受保人在任何時候去世，均會支付身故賠償，保障終身。它並非限指定時期或特定日期前的死亡，也非按月給付補償。"}},
{p:3,ch:"人寿保险及年金的种类",q:"连续缴费终身寿险保单的保费是:",o:["于保单开始时缴付一整笔保费","受保生命必须缴费至逝世前","缴费至保单中指明的限定期限","缴付一段固定期间,就算受保生命已去世都是一样"],a:1,e:"连续缴费终身寿险保单不设固定缴费期满，受保生命须持续缴付保费直至逝世为止。一次性缴付、限定期限或固定期间缴费均与其连续缴费特征不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"連續繳費終身壽險保單的保費是：",o:["於保單開始時繳付一整筆保費","受保生命必須繳費至逝世前","繳費至保單中指明的限定期限","繳付一段固定期間，就算受保生命已去世都是一樣"],e:"連續繳費終身壽險保單不設固定繳費期滿，受保生命須持續繳付保費直至逝世為止。一次性繳付、限定期限或固定期間繳費均與其連續繳費特徵不符。"}},
{p:3,ch:"人寿保险及年金的种类",q:"连续缴费终身寿险单,我们可称为:",o:["纯粹寿险单","永久终身寿险单","连续终身寿险单","递增保费人寿保单"],a:0,e:"连续缴费终身寿险单因属终身缴费的纯保障形式，可称为纯粹寿险单。永久、连续或递增保费等名称并非其对应术语。",src:1,tw:{ch:"人壽保險及年金的種類",q:"連續繳費終身壽險單，我們可稱為：",o:["純粹壽險單","永久終身壽險單","連續終身壽險單","遞增保費人壽保單"],e:"連續繳費終身壽險單因屬終身繳費的純保障形式，可稱為純粹壽險單。永久、連續或遞增保費等名稱並非其對應術語。"}},
{p:3,ch:"人寿保险及年金的种类",q:"递减定期寿险指:",o:["利益每年递减","保险费每年递减","利益与保险费每年递减","付给代理人的佣金每年递减"],a:0,e:"递减定期寿险的最大特征是保险利益（保额）逐年递减，以配合递减的债务或需要，而保险费通常保持不变。故正确的是利益每年递减，而非保费或佣金递减。",src:1,tw:{ch:"人壽保險及年金的種類",q:"遞減定期壽險指：",o:["利益每年遞減","保險費每年遞減","利益與保險費每年遞減","付給代理人的佣金每年遞減"],e:"遞減定期壽險的最大特徵是保險利益（保額）逐年遞減，以配合遞減的債務或需要，而保險費通常保持不變。故正確的是利益每年遞減，而非保費或佣金遞減。"}},
{p:3,ch:"人寿保险及年金的种类",q:"递减定期寿险最适合:",o:["一项减少而短暂的需要","一项增加而短暂的需要","一项不变而短暂的需要","一项不变而终身的需要"],a:0,e:"递减定期寿险的保额随需保障的金额同步减少，最适合一项随时间而减少且属短暂的需要。增加、不变或终身的需求均与递减特征不合。",src:1,tw:{ch:"人壽保險及年金的種類",q:"遞減定期壽險最適合：",o:["一項減少而短暫的需要","一項增加而短暫的需要","一項不變而短暫的需要","一項不變而終身的需要"],e:"遞減定期壽險的保額隨需保障的金額同步減少，最適合一項隨時間而減少且屬短暫的需要。增加、不變或終身的需求均與遞減特徵不合。"}},
{p:3,ch:"人寿保险及年金的种类",q:"递减定期寿险适合应付以下哪个或哪些情况?",o:["缴付遗产税","为个人作退休资本","清缴抵押贷款余额","以上各项皆是"],a:2,e:"递减定期寿险适用于清缴随供款逐年下降的抵押贷款余额。缴付遗产税、作退休资本均非其用途，故答案为清缴抵押贷款余额，而非以上皆是。",src:1,tw:{ch:"人壽保險及年金的種類",q:"遞減定期壽險適合應付以下哪個或哪些情況？",o:["繳付遺產稅","為個人作退休資本","清繳抵押貸款餘額","以上各項皆是"],e:"遞減定期壽險適用於清繳隨供款逐年下降的抵押貸款餘額。繳付遺產税、作退休資本均非其用途，故答案為清繳抵押貸款餘額，而非以上皆是。"}},
{p:3,ch:"人寿保险及年金的种类",q:"递增定期寿险是: i 死亡保险金会按年递增 ii 死亡保险金按某个约定的指数递增 iii 必须提供持续的良好健康证明,死亡保险金才会递增 iv 考虑到通货膨胀的因素而产生",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"递增定期寿险的死亡保险金按年递增并按约定指数调整，主要因应通货膨胀因素而设。其递增无须提供持续良好健康证明，故 iii 错误，正确为 i、ii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"遞增定期壽險是： i 死亡保險金會按年遞增 ii 死亡保險金按某個約定的指數遞增 iii 必須提供持續的良好健康證明，死亡保險金才會遞增 iv 考慮到通貨膨脹的因素而產生",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"遞增定期壽險的死亡保險金按年遞增並按約定指數調整，主要因應通貨膨脹因素而設。其遞增無須提供持續良好健康證明，故 iii 錯誤，正確為 i、ii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"非供款团体寿险是指:",o:["雇员无需缴交非供款团体寿险保费","雇主无需缴交非供款团体寿险保费","个别雇员无需就个人保单而缴交非供款团体寿险保费","以上没有一个正确"],a:0,e:"非供款团体寿险指保费全数由雇主缴付，雇员无须缴交保费。雇主并非「无需缴交」，个别雇员个人保单的说法亦不恰当，故正确答案为雇员无须缴交保费。",src:1,tw:{ch:"人壽保險及年金的種類",q:"非供款團體壽險是指:",o:["僱員無需繳交非供款團體壽險保費","僱主無需繳交非供款團體壽險保費","個別僱員無需就個人保單而繳交非供款團體壽險保費","以上沒有一個正確"],e:"非供款團體壽險指保費全數由僱主繳付，僱員無須繳交保費。僱主並非「無需繳交」，個別僱員個人保單的說法亦不恰當，故正確答案為僱員無須繳交保費。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港常见的定期寿险的保障期最短是:",o:["1个月","1年","5年","20年"],a:1,e:"香港常见的定期寿险保障期可短至一年（1年），并可按年续保。1个月过短、5年及20年属较长期限，均非常见的最短保障期。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港常見的定期壽險的保障期最短是：",o:["1個月","1年","5年","20年"],e:"香港常見的定期壽險保障期可短至一年（1年），並可按年續保。1個月過短、5年及20年屬較長期限，均非常見的最短保障期。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港年金计划整付产品每人的最低认购保费金额是:",o:["$10,000","$30,000","$50,000","$100,000"],a:2,e:"香港年金计划整付产品设每人最低认购保费为50,000港元，以便退休人士参与。10,000、30,000及100,000元均不符规定的最低认购金额。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港年金計劃整付產品每人的最低認購保費金額是:",o:["$10,000","$30,000","$50,000","$100,000"],e:"香港年金計劃整付產品設每人最低認購保費為50,000港元，以便退休人士參與。10,000、30,000及100,000元均不符規定的最低認購金額。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港年金计划是由以下哪个公司推出的?",o:["香港金融管理局","香港按揭证券有限公司","香港证监会","以上都不是"],a:1,e:"香港年金计划由香港按揭证券有限公司旗下的香港年金有限公司推出。香港金融管理局是监管机构，证监会亦非推行此计划的机构。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港年金計劃是由以下哪個公司推出的？",o:["香港金融管理局","香港按揭證券有限公司","香港證監會","以上都不是"],e:"香港年金計劃由香港按揭證券有限公司旗下的香港年金有限公司推出。香港金融管理局是監管機構，證監會亦非推行此計劃的機構。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港年金计划的保单持有人可于保证期内申请提取特别款项,请问可支付以下哪个项目的费用?",o:["意外事故","医疗或牙科开支","税收贷款","葬礼费用"],a:1,e:"香港年金计划保单持有人可在保证期内申请提取特别款项，用以支付医疗或牙科开支。意外事故、税收贷款及葬礼费用并不在可支付项目之列。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港年金計劃的保單持有人可於保證期內申請提取特別款項，請問可支付以下哪個項目的費用？",o:["意外事故","醫療或牙科開支","稅收貸款","葬禮費用"],e:"香港年金計劃保單持有人可在保證期內申請提取特別款項，用以支付醫療或牙科開支。意外事故、税收貸款及葬禮費用並不在可支付項目之列。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港的年金计划是:",o:["延期终身年金计划","退休延期终身年金计划","即期终身年金计划","经税局认可的即期终身年金计划"],a:2,e:"香港的年金计划属即期终身年金，符合资格人士以一笔过保费即时开始领取年金，直至终身。它并非延期年金，也与是否经税局认可无关。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港的年金計劃是:",o:["延期終身年金計劃","退休延期終身年金計劃","即期終身年金計劃","經稅局認可的即期終身年金計劃"],e:"香港的年金計劃屬即期終身年金，符合資格人士以一筆過保費即時開始領取年金，直至終身。它並非延期年金，也與是否經税局認可無關。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港的年金计划是?",o:["延期终身年金计划","退休人士即期终身年金计划","退休人士延期终身年金计划","以上都不对"],a:1,e:"香港的年金计划是专为退休人士设计的即期终身年金计划，投保后随即开始领取年金。延期或非退休人士的描述均不准确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港的年金計劃是?",o:["延期終身年金計劃","退休人士即期終身年金計劃","退休人士延期終身年金計劃","以上都不對"],e:"香港的年金計劃是專為退休人士設計的即期終身年金計劃，投保後隨即開始領取年金。延期或非退休人士的描述均不準確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"骆先生刚毕业不久,没有多少钱购买人寿保险,然而将于明年结婚。为甚么你认为他应该考虑购 买可转换定期寿险?",o:["可转换定期寿险保费颇低,给保单所有人灵活性, 选择在无须提供可保性证明的情况下把保单转换为联合寿险计划","可转换定期寿险给保单所有人灵活性,选择在无须提供可保性证明的情况下 把保单转换为更便宜计划","可转换定期寿险保费颇低,给保单所有人灵活性, 选择在无须提供可保性证明的情况下把保单转换为永久计划","对于将近结婚的人来说,可转换定期款险是最适合不过"],a:2,e:"可转换定期寿险保费较低，且让保单所有人日后无须提供可保性证明即可将保单转换为永久计划，适合预算有限但未来保障需求将增加的骆先生。转换为联合或更便宜计划的说法均不符。",src:1,tw:{ch:"人壽保險及年金的種類",q:"駱先生剛畢業不久，沒有多少錢購買人壽保險，然而將於明年結婚。為甚麼你認為他應該考慮購 買可轉換定期壽險？",o:["可轉換定期壽險保費頗低，給保單所有人靈活性， 選擇在無須提供可保性證明的情況下把保單轉換為聯合壽險計劃","可轉換定期壽險給保單所有人靈活性，選擇在無須提供可保性證明的情況下 把保單轉換為更便宜計劃","可轉換定期壽險保費頗低，給保單所有人靈活性， 選擇在無須提供可保性證明的情況下把保單轉換為永久計劃","對於將近結婚的人來說，可轉換定期款險是最適合不過"],e:"可轉換定期壽險保費較低，且讓保單所有人日後無須提供可保性證明即可將保單轉換為永久計劃，適合預算有限但未來保障需求將增加的駱先生。轉換為聯合或更便宜計劃的說法均不符。"}},
{p:3,ch:"保险利益附约及其他产品",q:"AD&D 英文全名为:",o:["Accidental Death & Disablement","Accidental Death & Dismemberment","Anticipated Death & Disablement","Acceierated Death & Dismemberment"],a:1,e:"AD&D 的英文全名为 Accidental Death & Dismemberment，即意外死亡及丧失肢体。其余组合中的 Disablement、Anticipated 及拼写错误均非正确全称。",src:1,tw:{ch:"保險利益附約及其他產品",q:"AD&D 英文全名為:",o:["Accidental Death & Disablement","Accidental Death & Dismemberment","Anticipated Death & Disablement","Acceierated Death & Dismemberment"],e:"AD&D 的英文全名為 Accidental Death & Dismemberment，即意外死亡及喪失肢體。其餘組合中的 Disablement、Anticipated 及拼寫錯誤均非正確全稱。"}},
{p:3,ch:"保险利益附约及其他产品",q:"AD&D 附约提供以下哪项情况可以收取利益?",o:["由意外引致死亡而已","受保保单所有人意外死亡或失业时","受保保单所有人意外死亡或完全伤残时","受保保单所有人意外死亡或丧失肢体时"],a:3,e:"AD&D 附约在被保人因意外死亡或因意外丧失肢体时给付额外利益。它并不涵盖失业或完全伤残，故正确为意外死亡或丧失肢体。",src:1,tw:{ch:"保險利益附約及其他產品",q:"AD&D 附約提供以下哪項情況可以收取利益?",o:["由意外引致死亡而已","受保保單所有人意外死亡或失業時","受保保單所有人意外死亡或完全傷殘時","受保保單所有人意外死亡或喪失肢體時"],e:"AD&D 附約在被保人因意外死亡或因意外喪失肢體時給付額外利益。它並不涵蓋失業或完全傷殘，故正確為意外死亡或喪失肢體。"}},
{p:3,ch:"保险利益附约及其他产品",q:"AD&D 附约提供以下哪项额外保障?",o:["只提供意外死亡保障","意外死亡及残疾收入,按月支付","意外死亡及按照所列明之疾病","意外死亡及丧失肢体,按照个别定义"],a:3,e:"AD&D 附约在意外死亡及丧失肢体时提供额外保障，其中丧失肢体按保单个别定义给付。仅意外死亡、按月残疾收入或所列疾病均非本附约的完整范围。",src:1,tw:{ch:"保險利益附約及其他產品",q:"AD&D 附約提供以下哪項額外保障?",o:["只提供意外死亡保障","意外死亡及殘疾收入,按月支付","意外死亡及按照所列明之疾病","意外死亡及喪失肢體,按照個別定義"],e:"AD&D 附約在意外死亡及喪失肢體時提供額外保障，其中喪失肢體按保單個別定義給付。僅意外死亡、按月殘疾收入或所列疾病均非本附約的完整範圍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"COLA的英文全写为:",o:["Cost of Life Insurance Adjustment","Compensation of Life/Annuity Contract","Compensation of Life Assurance Benefit","Cost of Living Adjustment"],a:3,e:"COLA 的英文全写为 Cost of Living Adjustment，即生活指数（生活费）调整。其余组合把「生活指数调整」误写为寿险或年金相关的补偿术语，均不正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"COLA的英文全寫為:",o:["Cost of Life Insurance Adjustment","Compensation of Life/Annuity Contract","Compensation of Life Assurance Benefit","Cost of Living Adjustment"],e:"COLA 的英文全寫為 Cost of Living Adjustment，即生活指數（生活費）調整。其餘組合把「生活指數調整」誤寫為壽險或年金相關的補償術語，均不正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"COLA的英文全写是:",o:["寿险成本调整 Cost of Life Insurance Adjustment","寿险/年金合同的补偿 Compensation of Life / Annuity Contract","寿险利益补偿 Compensation of Life Assurance Benefit","生活指数调整利益 Cost of Living Adjustment Benefit"],a:3,e:"COLA 全写为 Cost of Living Adjustment Benefit，中文即「生活指数调整利益」。其余选项均误将 COLA 解释为寿险成本、补偿等，不符原意。",src:1,tw:{ch:"保險利益附約及其他產品",q:"COLA的英文全寫是:",o:["壽險成本調整 Cost of Life Insurance Adjustment","壽險/年金合同的補償 Compensation of Life / Annuity Contract","壽險利益補償 Compensation of Life Assurance Benefit","生活指數調整利益 Cost of Living Adjustment Benefit"],e:"COLA 全寫為 Cost of Living Adjustment Benefit，中文即「生活指數調整利益」。其餘選項均誤將 COLA 解釋為壽險成本、補償等，不符原意。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「意外死亡保险利益附约」向受保保单所有人提供双倍赔偿利益,以下哪个死亡原因受保保单所有人可 得到该赔偿:",o:["车祸","游泳","旅行时,受持械抢劫的人枪击","以上所有各项"],a:3,e:"意外死亡保险利益附约对被保险人的意外死亡提供额外利益，车祸、游泳意外及旅行时遭枪击均属意外死亡，可获赔偿。故答案为以上所有各项。",src:1,tw:{ch:"保險利益附約及其他產品",q:"「意外死亡保險利益附約」向受保保單所有人提供雙倍賠償利益，以下哪個死亡原因受保保單所有人可 得到該賠償：",o:["車禍","游泳","旅行時，受持械搶劫的人槍擊","以上所有各項"],e:"意外死亡保險利益附約對被保險人的意外死亡提供額外利益，車禍、游泳意外及旅行時遭槍擊均屬意外死亡，可獲賠償。故答案為以上所有各項。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「生前支付保险利益」附约经常会附加于人寿保险保单中,又可称为:",o:["死前支付保险利益","家庭收入保险利益","意外受伤保险利益","提前支付死亡保险利益"],a:3,e:"「生前支付保险利益」附约让被保人在生命结束前提前支取部分死亡保险金，故又称「提前支付死亡保险利益」。家庭收入、意外受伤等附约性质不同。",src:1,tw:{ch:"保險利益附約及其他產品",q:"「生前支付保險利益」附約經常會附加於人壽保險保單中，又可稱為：",o:["死前支付保險利益","家庭收入保險利益","意外受傷保險利益","提前支付死亡保險利益"],e:"「生前支付保險利益」附約讓被保人在生命結束前提前支取部分死亡保險金，故又稱「提前支付死亡保險利益」。家庭收入、意外受傷等附約性質不同。"}},
{p:3,ch:"保险利益附约及其他产品",q:"「豁免保费附约」是指:",o:["让有关保险合约豁免首年保费","让受保保单所有人于完全残疾期间豁免保费","它的意思是该有关保险合约是「有利润的」(即分红保单)","它的意思是当受保保单所有人意外死亡时提供双倍利益"],a:1,e:"豁免保费附约的效用是当受保保单所有人完全残疾期间，保险人代为缴付保费，使保单继续有效。它与首年保费、分红或意外死亡双倍利益无关。",src:1,tw:{ch:"保險利益附約及其他產品",q:"「豁免保費附約」是指：",o:["讓有關保險合約豁免首年保費","讓受保保單所有人於完全殘疾期間豁免保費","它的意思是該有關保險合約是「有利潤的」(即分紅保單)","它的意思是當受保保單所有人意外死亡時提供雙倍利益"],e:"豁免保費附約的效用是當受保保單所有人完全殘疾期間，保險人代為繳付保費，使保單繼續有效。它與首年保費、分紅或意外死亡雙倍利益無關。"}},
{p:3,ch:"保险利益附约及其他产品",q:"一份保单包含提前支付死亡保险利益附约,这代表:",o:["这份保单可转换为储蓄寿险","这份保单已加入残疾利益","受保保单所有人可于生命结束前支取保险利益","受保保单所有人失年届100岁时,可支取保险利益"],a:2,e:"提前支付死亡保险利益附约让受保保单所有人在生命结束前（如罹患终末疾病）预先支取部分保险利益。转换为储蓄寿险、已加入残疾利益或年届100岁支取均非其含义。",src:1,tw:{ch:"保險利益附約及其他產品",q:"一份保單包含提前支付死亡保險利益附約，這代表：",o:["這份保單可轉換為儲蓄壽險","這份保單已加入殘疾利益","受保保單所有人可於生命結束前支取保險利益","受保保單所有人失年屆100歲時，可支取保險利益"],e:"提前支付死亡保險利益附約讓受保保單所有人在生命結束前（如罹患終末疾病）預先支取部分保險利益。轉換為儲蓄壽險、已加入殘疾利益或年屆100歲支取均非其含義。"}},
{p:3,ch:"保险利益附约及其他产品",q:"一份保单已加入「豁免保费」附约,这代表:",o:["首年保费可获豁免保费","受保保单所有人逝世后可获豁免保费","受保保单所有人完全残疾时可获豁免保费","若有另一间保险公司提供较低廉保费,则可获豁免保费"],a:2,e:"加入「豁免保费」附约后，当受保保单所有人完全残疾并达指定期间，其保费可获豁免。首年、身故或其他公司保费较低均非豁免保费的触发条件。",src:1,tw:{ch:"保險利益附約及其他產品",q:"一份保單已加入「豁免保費」附約，這代表：",o:["首年保費可獲豁免保費","受保保單所有人逝世後可獲豁免保費","受保保單所有人完全殘疾時可獲豁免保費","若有另一間保險公司提供較低廉保費，則可獲豁免保費"],e:"加入「豁免保費」附約後，當受保保單所有人完全殘疾並達指定期間，其保費可獲豁免。首年、身故或其他公司保費較低均非豁免保費的觸發條件。"}},
{p:3,ch:"保险利益附约及其他产品",q:"一份典型的医疗保险,基本计划通常包括:",o:["住院费用","私人护理","住院病人内科医生费","以上各项"],a:3,e:"典型医疗保险的基本计划通常涵盖住院费用、私人护理及住院病人内科医生费等与住院相关的开支，故以上各项均包括在内。",src:1,tw:{ch:"保險利益附約及其他產品",q:"一份典型的醫療保險，基本計劃通常包括：",o:["住院費用","私人護理","住院病人內科醫生費","以上各項"],e:"典型醫療保險的基本計劃通常涵蓋住院費用、私人護理及住院病人內科醫生費等與住院相關的開支，故以上各項均包括在內。"}},
{p:3,ch:"保险利益附约及其他产品",q:"一份典型的医疗保险会包括基本计划,用作支付与医疗及住院有关的费用,以下哪项不属于计划的保障 范围?",o:["因道路交通意外入院","出院一个月后的门诊跟进护理","由主诊医生建议注册护士的家庭护理","就先天性面部疤痕作整容手术"],a:3,e:"医疗保险基本计划保障因病或意外入院的医疗开支，但美容性质的整容手术，如就先天性面部疤痕进行的整容，通常不在保障范围内。道路意外入院、门诊跟进及注册护士家庭护理一般属保障。",src:1,tw:{ch:"保險利益附約及其他產品",q:"一份典型的醫療保險會包括基本計劃，用作支付與醫療及住院有關的費用，以下哪項不屬於計劃的保障 範圍？",o:["因道路交通意外入院","出院一個月後的門診跟進護理","由主診醫生建議註冊護士的家庭護理","就先天性面部疤痕作整容手術"],e:"醫療保險基本計劃保障因病或意外入院的醫療開支，但美容性質的整容手術，如就先天性面部疤痕進行的整容，通常不在保障範圍內。道路意外入院、門診跟進及註冊護士家庭護理一般屬保障。"}},
{p:3,ch:"保险利益附约及其他产品",q:"一份典型的寿险保单附有提前支付死亡保险利益附约,如受保人患有终末疾病,保险人会预支部份死亡 保险金,而此终末疾病的预期寿命只有:",o:["一个月或以下","十二个月或以下","二年或以下","五年或以下"],a:1,e:"提前支付死亡保险利益附约在受保人罹患终末疾病时预支部分死亡保险金，该终末疾病的预期寿命一般为十二个月或以下。一个月、二年及五年均不符标准。",src:1,tw:{ch:"保險利益附約及其他產品",q:"一份典型的壽險保單附有提前支付死亡保險利益附約，如受保人患有終末疾病，保險人會預支部份死亡 保險金，而此終末疾病的預期壽命只有：",o:["一個月或以下","十二個月或以下","二年或以下","五年或以下"],e:"提前支付死亡保險利益附約在受保人罹患終末疾病時預支部分死亡保險金，該終末疾病的預期壽命一般為十二個月或以下。一個月、二年及五年均不符標準。"}},
{p:3,ch:"保险利益附约及其他产品",q:"下列哪一项有关双倍赔偿利益附约,Double indemnity Benefit的陈述是不正确?",o:["只适用于第三者保险","引起死亡的近因对这附约很重要","严格来说,它的英文术语在技术上是不正确的","它是意外保险利益附约的另一名称"],a:0,e:"双倍赔偿利益附约适用于含该附约的人寿保单，并非「只适用于第三者保险」，故此陈述不正确。该附约又称意外死亡保险利益，近因对判定赔付很重要，且其英文术语在技术上确实不严谨。",src:1,tw:{ch:"保險利益附約及其他產品",q:"下列哪一項有關雙倍賠償利益附約，Double indemnity Benefit的陳述是不正確？",o:["只適用於第三者保險","引起死亡的近因對這附約很重要","嚴格來說，它的英文術語在技術上是不正確的","它是意外保險利益附約的另一名稱"],e:"雙倍賠償利益附約適用於含該附約的人壽保單，並非「只適用於第三者保險」，故此陳述不正確。該附約又稱意外死亡保險利益，近因對判定賠付很重要，且其英文術語在技術上確實不嚴謹。"}},
{p:3,ch:"保险利益附约及其他产品",q:"下列哪项不是豁免保费的除外责任?",o:["蓄意伤害自己身体造成的残疾","从事非法活动时导致的伤残","保单生效前既存的状况","第三者刑事责任而引致的损害"],a:3,e:"豁免保费的除外责任通常包括蓄意伤害自己造成的残疾、从事非法活动致残及保单生效前的既有状况。因第三者刑事责任引致的损害并非豁免保费的除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"下列哪項不是豁免保費的除外責任？",o:["蓄意傷害自己身體造成的殘疾","從事非法活動時導致的傷殘","保單生效前既存的狀況","第三者刑事責任而引致的損害"],e:"豁免保費的除外責任通常包括蓄意傷害自己造成的殘疾、從事非法活動致殘及保單生效前的既有狀況。因第三者刑事責任引致的損害並非豁免保費的除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"下列哪项或哪些不属于人身意外保险的除外责任?",o:["因蓄意伤害自己身体所造成的残疾","因驾驶货车发生意外的残疾","并非由意外引致的疾病","指明危险活动而引起的伤残"],a:1,e:"因驾驶货车发生意外而造成残疾属意外所致，并非人身意外保险的除外责任。蓄意自残、非意外疾病及指明危险活动而致的伤残通常属除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"下列哪項或哪些不屬於人身意外保險的除外責任？",o:["因蓄意傷害自己身體所造成的殘疾","因駕駛貨車發生意外的殘疾","並非由意外引致的疾病","指明危險活動而引起的傷殘"],e:"因駕駛貨車發生意外而造成殘疾屬意外所致，並非人身意外保險的除外責任。蓄意自殘、非意外疾病及指明危險活動而致的傷殘通常屬除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"下列哪项或哪些不属于因完全残疾而豁免保费的除外责任?",o:["因企图自杀而导致完全残疾","因驾驶电单车发生意外的完全残疾","从事违法活动时导致的伤残","以上各项皆是"],a:1,e:"因驾驶电单车发生意外导致完全残疾属意外，并非豁免保费的除外责任。企图自杀及从事违法活动所致的完全残疾通常列明为除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"下列哪項或哪些不屬於因完全殘疾而豁免保費的除外責任？",o:["因企圖自殺而導致完全殘疾","因駕駛電單車發生意外的完全殘疾","從事違法活動時導致的傷殘","以上各項皆是"],e:"因駕駛電單車發生意外導致完全殘疾屬意外，並非豁免保費的除外責任。企圖自殺及從事違法活動所致的完全殘疾通常列明為除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"下列哪项是残疾收入保险利益的特性?",o:["已给付的收入不会从保险利益中扣除","完全残疾后,只需缴交50%的保费","等候期通常为期三个月或六个月","给付的收入只是贷款"],a:0,e:"残疾收入保险利益按约定给付的收入并不会从未来保险利益中扣除，是其重要特性。完全残疾后的保费安排、等候期长短及「收入仅为贷款」等描述不符。",src:1,tw:{ch:"保險利益附約及其他產品",q:"下列哪項是殘疾收入保險利益的特性？",o:["已給付的收入不會從保險利益中扣除","完全殘疾後，只需繳交50%的保費","等候期通常為期三個月或六個月","給付的收入只是貸款"],e:"殘疾收入保險利益按約定給付的收入並不會從未來保險利益中扣除，是其重要特性。完全殘疾後的保費安排、等候期長短及「收入僅為貸款」等描述不符。"}},
{p:3,ch:"保险利益附约及其他产品",q:"丧失肢体附约定义为:",o:["某些保险人可能会将定义延至整条手臂或臀部以下部位","保险涉及丧失该肢体功能","丧失一个手指关节也可得到赔偿","附有每周住院津贴保障"],a:1,e:"丧失肢体附约的保障核心是理赔涉及丧失该肢体的功能（或实际丧失肢体），而非必须实际切断或仅失去单一关节，也非附每周住院津贴。故答案涉及丧失肢体功能。",src:1,tw:{ch:"保險利益附約及其他產品",q:"喪失肢體附約定義為：",o:["某些保險人可能會將定義延至整條手臂或臀部以下部位","保險涉及喪失該肢體功能","喪失一個手指關節也可得到賠償","附有每周住院津貼保障"],e:"喪失肢體附約的保障核心是理賠涉及喪失該肢體的功能（或實際喪失肢體），而非必須實際切斷或僅失去單一關節，也非附每週住院津貼。故答案涉及喪失肢體功能。"}},
{p:3,ch:"保险利益附约及其他产品",q:"人寿保单会于下面哪种情况下根据危疾保险附约的支付利益?",o:["受保保单所有人正在罹患终末疾病,预期寿命只有12个月或以下","受保保单所有人正在罹患终末疾病,预期寿命不能确定","受保保单所有人正在罹患不痊愈之疾病,预期寿命只有12个月或以下","受保保单所有人正在罹患终末疾病后6个月内死于该病"],a:0,e:"危疾保险利益附约在受保人罹患终末疾病、且预期寿命只有12个月或以下时给付。预期寿命无法确定、不痊愈疾病或6个月内死亡等均不符给付条件。",src:1,tw:{ch:"保險利益附約及其他產品",q:"人壽保單會於下面哪種情況下根據危疾保險附約的支付利益？",o:["受保保單所有人正在罹患終末疾病，預期壽命只有12個月或以下","受保保單所有人正在罹患終末疾病，預期壽命不能確定","受保保單所有人正在罹患不痊癒之疾病，預期壽命只有12個月或以下","受保保單所有人正在罹患終末疾病後6個月內死於該病"],e:"危疾保險利益附約在受保人罹患終末疾病、且預期壽命只有12個月或以下時給付。預期壽命無法確定、不痊癒疾病或6個月內死亡等均不符給付條件。"}},
{p:3,ch:"保险利益附约及其他产品",q:"人寿保险有一项「其他意外保险利益」中所指的其他利益包括:",o:["严重烧伤","每日住院津贴","残疾期间每周津贴","以上各项皆是"],a:3,e:"「其他意外保险利益」所包括的其他利益可有严重烧伤、每日住院津贴及残疾期间每周津贴等，视乎保单条款，故以上各项皆是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"人壽保險有一項「其他意外保險利益」中所指的其他利益包括：",o:["嚴重燒傷","每日住院津貼","殘疾期間每周津貼","以上各項皆是"],e:"「其他意外保險利益」所包括的其他利益可有嚴重燒傷、每日住院津貼及殘疾期間每週津貼等，視乎保單條款，故以上各項皆是。"}},
{p:3,ch:"保险利益附约及其他产品",q:"从\"意外死亡保险利益\"中所指的死亡必须由:",o:["意外直接引致身体受伤","抢劫时直接引致身体受伤","自杀引致身体受伤","战争引致身体受伤"],a:0,e:"意外死亡保险利益所指的死亡，必须由意外直接引致身体受伤而造成。抢劫、自杀及战争所致的身体受伤分别属其他情境或除外责任，并非「意外直接引致」的典型定义。",src:1,tw:{ch:"保險利益附約及其他產品",q:"從\"意外死亡保險利益\"中所指的死亡必須由：",o:["意外直接引致身體受傷","搶劫時直接引致身體受傷","自殺引致身體受傷","戰爭引致身體受傷"],e:"意外死亡保險利益所指的死亡，必須由意外直接引致身體受傷而造成。搶劫、自殺及戰爭所致的身體受傷分別屬其他情境或除外責任，並非「意外直接引致」的典型定義。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪一项是对意外死亡及丧失肢体中的丧失肢体的不正确描述?",o:["肢体因意外引致丧失功能亦可获赔偿","保障包括丧失一个或多个肢体及失明","意外同时导致死亡及丧失肢体的情况下可获两倍的赔偿","在丧失两肢的情况下,可获相当于死亡保险金的金额赔偿"],a:2,e:"丧失肢体附约在同一意外中导致死亡时只给付死亡或丧失肢体的其中一项，而非「死亡及丧失肢体可同时获两倍赔偿」，故此描述不正确。其余有关功能丧失、肢体数目及双肢赔偿的陈述正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪一項是對意外死亡及喪失肢體中的喪失肢體的不正確描述？",o:["肢體因意外引致喪失功能亦可獲賠償","保障包括喪失一個或多個肢體及失明","意外同時導致死亡及喪失肢體的情況下可獲兩倍的賠償","在喪失兩肢的情況下，可獲相當於死亡保險金的金額賠償"],e:"喪失肢體附約在同一意外中導致死亡時只給付死亡或喪失肢體的其中一項，而非「死亡及喪失肢體可同時獲兩倍賠償」，故此描述不正確。其餘有關功能喪失、肢體數目及雙肢賠償的陳述正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪三项是对残疾收入附约的正确描述? i 附约实际上适用于任何类型的人寿保险 ii 收入利益以每月约定金类型式发送 iii 支付款项实际上是一项贷款,并会于支付保额时扣回 iv 保障附有一至六个月不等的等候期",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"残疾收入附约几乎可附加于任何类型的人寿保险，收入利益以每月约定金额支付，并设有一至六个月不等的等候期。所述「支付款项是贷款并会于支付保额时扣回」不正确，此利益并非贷款。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪三項是對殘疾收入附約的正確描述？ i 附約實際上適用於任何類型的人壽保險 ii 收入利益以每月約定金類型式發送 iii 支付款項實際上是一項貸款，並會於支付保額時扣回 iv 保障附有一至六個月不等的等候期",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"殘疾收入附約幾乎可附加於任何類型的人壽保險，收入利益以每月約定金額支付，並設有一至六個月不等的等候期。所述「支付款項是貸款並會於支付保額時扣回」不正確，此利益並非貸款。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪三项是对生活指数调整附约的正确描述? i 等候期相等于1至6个月不等 ii 它提供对被保人的残疾收入增加的保障 iii 当被保人遭致残疾期间,其残疾收入会随特定指数(例如消费者物价指数)增加 iv 被保险保单持有人于残疾后,其残疾收入会定期增加",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:3,e:"生活指数调整附约在受保人残疾期间按其残疾收入随特定指数（如消费者物价指数）定期增加，以对抗通胀。等候期1至6个月并非COLA的特征，故 i 错误，正确为 ii、iii、iv。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪三項是對生活指數調整附約的正確描述？ i 等候期相等於1至6個月不等 ii 它提供對被保人的殘疾收入增加的保障 iii 當被保人遭致殘疾期間，其殘疾收入會隨特定指數(例如消費者物價指數)增加 iv 被保險保單持有人於殘疾後，其殘疾收入會定期增加",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"生活指數調整附約在受保人殘疾期間按其殘疾收入隨特定指數（如消費者物價指數）定期增加，以對抗通脹。等候期1至6個月並非COLA的特徵，故 i 錯誤，正確為 ii、iii、iv。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪个情况寿险保单会根据其危疾保险利益附约支付?",o:["受保生命正罹患末期疾病或其他不知名疾病,预期寿命无法估计","受保生命正罹患不能痊愈的疾病,预期寿命只有十二个月或以下","受保生命正罹患末期疾病,预期寿命只有十二个月或以下","受保生命在被诊断终末疾病后的六个月内死亡"],a:2,e:"寿险保单的危疾保险利益附约在受保生命罹患末期疾病、且预期寿命只有十二个月或以下时给付。预期寿命无法估计、不能痊愈疾病或其他时限均不符合。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪個情況壽險保單會根據其危疾保險利益附約支付？",o:["受保生命正罹患末期疾病或其他不知名疾病，預期壽命無法估計","受保生命正罹患不能痊癒的疾病，預期壽命只有十二個月或以下","受保生命正罹患末期疾病，預期壽命只有十二個月或以下","受保生命在被診斷終末疾病後的六個月內死亡"],e:"壽險保單的危疾保險利益附約在受保生命罹患末期疾病、且預期壽命只有十二個月或以下時給付。預期壽命無法估計、不能痊癒疾病或其他時限均不符合。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪些并非危疾保险利益的限制:",o:["不可异议期长达5年","只保障指定岁数以下","多重疾病和复发性的可能不会获得给付,某一两类疾病或属例外","以上皆是"],a:0,e:"危疾保险利益的限制包括只保障指定岁数以下及多重/复发性疾病一般不获给付等，但「不可异议期长达5年」并非其限制，故此选项不属于限制。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪些並非危疾保險利益的限制:",o:["不可異議期長達5年","只保障指定歲數以下","多重疾病和復發性的可能不會獲得給付，某一兩類疾病或屬例外","以上皆是"],e:"危疾保險利益的限制包括只保障指定歲數以下及多重/複發性疾病一般不獲給付等，但「不可異議期長達5年」並非其限制，故此選項不屬於限制。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪些描述意外死亡及丧失肢体附约中的「丧失肢体」是正确: i 丧失肢体的描述为实际丧失肢体或丧失该肢体的功能 ii 某些保单不包括丧失单肢 iii 经修改后,丧失单肢相等于死亡保险金的一半 iv 同一意外发生后,保险人会同时支付丧失肢体及死亡保险金",o:["i, ii","i, iii","i, ii, iii","i, ii, iii, iv"],a:1,e:"丧失肢体的正确描述为「实际丧失肢体或丧失该肢体功能」，且经修改后丧失单肢通常相等于死亡保险金的一半，故 i、iii 正确。保单一般包括丧失单肢、同一意外亦不会同时给付丧失肢体与死亡金，故 ii、iv 错误。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪些描述意外死亡及喪失肢體附約中的「喪失肢體」是正確: i 喪失肢體的描述為實際喪失肢體或喪失該肢體的功能 ii 某些保單不包括喪失單肢 iii 經修改後，喪失單肢相等於死亡保險金的一半 iv 同一意外發生後，保險人會同時支付喪失肢體及死亡保險金",o:["i, ii","i, iii","i, ii, iii","i, ii, iii, iv"],e:"喪失肢體的正確描述為「實際喪失肢體或喪失該肢體功能」，且經修改後喪失單肢通常相等於死亡保險金的一半，故 i、iii 正確。保單一般包括喪失單肢、同一意外亦不會同時給付喪失肢體與死亡金，故 ii、iv 錯誤。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪些是危疾保险利益的限制: i  危疾保障仅适用于某岁数(如80岁)或以下的人 ii 危疾保障仅适用于标准风险 iii 多重疾病和复发性的可能不会获得给付,某一两类疾病或属例外 iv 等候期90天",o:["i, ii","i, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"危疾保险利益的限制包括：仅适用于指定岁数以下、仅适用标准风险、多重及复发性疾病一般不获给付，并设有90天等候期，四项均正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪些是危疾保險利益的限制: i 危疾保障僅適用於某歲數（如80歲）或以下的人 ii 危疾保障僅適用於標準風險 iii 多重疾病和復發性的可能不會獲得給付，某一兩類疾病或屬例外 iv 等候期90天",o:["i, ii","i, iii","ii, iii, iv","i, ii, iii, iv"],e:"危疾保險利益的限制包括：僅適用於指定歲數以下、僅適用標準風險、多重及複發性疾病一般不獲給付，並設有90天等候期，四項均正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪些是描述豁免保费?",o:["首期保费不用支付","失业期间不用支付保费","受保单所有人完全伤残,保险人代为支付保单保费","在市场上竞争手的保费比较低廉,保险人会退回全数保费"],a:2,e:"豁免保费是指当受保单所有人完全伤残并达指定期间，保险人代为缴付保费。首期保费、失业期间或竞争对手保费低廉均非豁免保费的触发条件。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪些是描述豁免保費?",o:["首期保費不用支付","失業期間不用支付保費","受保單所有人完全傷殘，保險人代為支付保單保費","在市場上競爭手的保費比較低廉，保險人會退回全數保費"],e:"豁免保費是指當受保單所有人完全傷殘並達指定期間，保險人代為繳付保費。首期保費、失業期間或競爭對手保費低廉均非豁免保費的觸發條件。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项不是(WP)附约的描述?",o:["(WP)是Waiting period\"的缩写,意指「等候期」","(WP)是\"Waiver of Premium\"的缩写,意指「豁免保费」","「被保险保单所有人」须要完全伤残,才可获权益","受到特定年龄所限制"],a:0,e:"豁免保费附约中 WP 是 Waiver of Premium（豁免保费）的缩写，并非 Waiting Period（等候期）。被保人须完全伤残方可获权益，且保障受到特定年龄限制，故仅选项0错误。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項不是(WP)附約的描述？",o:["(WP)是Waiting period\"的縮寫，意指「等候期」","(WP)是\"Waiver of Premium\"的縮寫，意指「豁免保費」","「被保險保單所有人」須要完全傷殘，才可獲權益","受到特定年齡所限制"],e:"豁免保費附約中 WP 是 Waiver of Premium（豁免保費）的縮寫，並非 Waiting Period（等候期）。被保人須完全傷殘方可獲權益，且保障受到特定年齡限制，故僅選項0錯誤。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项不是双倍赔偿利益的正确描述?",o:["只适用于第三者保单","这名称在技巧上不正确","近因对这项利益的赔偿极为重要","是意外死亡保险利益的另一个名称"],a:0,e:"双倍赔偿利益并不「只适用于第三者保单」，它附加于人寿保单，故此描述不正确。该名称技术上不严谨，近因对判定赔付极为重要，且它又称意外死亡保险利益。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項不是雙倍賠償利益的正確描述？",o:["只適用於第三者保單","這名稱在技巧上不正確","近因對這項利益的賠償極為重要","是意外死亡保險利益的另一個名稱"],e:"雙倍賠償利益並不「只適用於第三者保單」，它附加於人壽保單，故此描述不正確。該名稱技術上不嚴謹，近因對判定賠付極為重要，且它又稱意外死亡保險利益。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项不是意外死亡保险利益的除外责任?",o:["因情绪低落而自杀","因抢劫银行而被警方枪杀","于飞行训练期间发生意外","购票乘客于飞行期间发生意外"],a:3,e:"购票乘客于正常飞行期间发生的意外死亡属承保范围，并非意外死亡保险利益的除外责任。自杀、抢劫被击毙及飞行训练期间意外通常被列明为除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項不是意外死亡保險利益的除外責任？",o:["因情緒低落而自殺","因搶劫銀行而被警方槍殺","於飛行訓練期間發生意外","購票乘客於飛行期間發生意外"],e:"購票乘客於正常飛行期間發生的意外死亡屬承保範圍，並非意外死亡保險利益的除外責任。自殺、搶劫被擊斃及飛行訓練期間意外通常被列明為除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项不是残疾收入的常用条款?",o:["等候期","年龄限制","应付金额","并非贷款或预缴"],a:1,e:"残疾收入的常用条款包括等候期、应付金额及「并非贷款或预缴」等。年龄限制并非残疾收入利益的一般常用条款。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項不是殘疾收入的常用條款?",o:["等候期","年齡限制","應付金額","並非貸款或預繳"],e:"殘疾收入的常用條款包括等候期、應付金額及「並非貸款或預繳」等。年齡限制並非殘疾收入利益的一般常用條款。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项为意外死亡保险利益(ADB)的正确描述? i 这项利益又称双倍赔偿利益 ii 死亡必须在受伤后一年内发生 iii 人身意外保险的除外责任中相似的除外责任亦适用 iv 在正常的情况下,须要给付一项相等于保险单保额的利益",o:["i, ii","ii, iv","i, ii, iii","以上各项"],a:3,e:"意外死亡保险利益又称双倍赔偿利益，通常规定死亡须在意外受伤后一年内发生，适用与人身意外保险相似的除外责任，并支付相等于保额的利益，四项皆正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項為意外死亡保險利益(ADB)的正確描述？ i 這項利益又稱雙倍賠償利益 ii 死亡必須在受傷後一年內發生 iii 人身意外保險的除外責任中相似的除外責任亦適用 iv 在正常的情況下，須要給付一項相等於保險單保額的利益",o:["i, ii","ii, iv","i, ii, iii","以上各項"],e:"意外死亡保險利益又稱雙倍賠償利益，通常規定死亡須在意外受傷後一年內發生，適用與人身意外保險相似的除外責任，並支付相等於保額的利益，四項皆正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项为通货膨胀对长期寿险的影响?",o:["它不是一个问题","它不是保险中介人关注的问题","它是可以忽略的,因为工资和收入的升幅加大","它是谨慎受保保单所有人及保险中介人关注的问题"],a:3,e:"通货膨胀会侵蚀长期寿险固定保额的实质购买力，是审慎的受保保单所有人及保险中介人都须关注的问题，不能忽略。故选「它是谨慎受保保单所有人及保险中介人关注的问题」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項為通貨膨脹對長期壽險的影響？",o:["它不是一個問題","它不是保險中介人關注的問題","它是可以忽略的，因為工資和收入的升幅加大","它是謹慎受保保單所有人及保險中介人關注的問題"],e:"通貨膨脹會侵蝕長期壽險固定保額的實質購買力，是審慎的受保保單所有人及保險中介人都須關注的問題，不能忽略。故選「它是謹慎受保保單所有人及保險中介人關注的問題」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项关于双倍补偿利益附约 (Double Indemnity Benefit Rider) 的陈述并不正确?",o:["它只适用于第三者保单","严格地说,这个英文术语技术上并不正确","引致死亡的近因在这种附约的应用很重要","它是意外死亡保险利益附约的另一名称"],a:0,e:"双倍补偿利益附约并非「只适用于第三者保单」，而是附加于人寿保单提供意外死亡额外给付，故该陈述不正确。术语技术上不严谨、近因重要及为意外死亡利益附约别名均正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項關於雙倍補償利益附約 (Double Indemnity Benefit Rider) 的陳述並不正確？",o:["它只適用於第三者保單","嚴格地說，這個英文術語技術上並不正確","引致死亡的近因在這種附約的應用很重要","它是意外死亡保險利益附約的另一名稱"],e:"雙倍補償利益附約並非「只適用於第三者保單」，而是附加於人壽保單提供意外死亡額外給付，故該陳述不正確。術語技術上不嚴謹、近因重要及為意外死亡利益附約別名均正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项危疾保险利益的附约并不正确:",o:["利益给付金额并不在保险保障金额扣除","支付给处于终末疾病且预期寿命只有12个月或更少的被保人","经由主诊医生发出的报告","诊断患上指明疾病"],a:0,e:"危疾保险利益通常属提前支付性质，其给付金额会从保险保障金额中扣除，故「利益给付金额并不在保险保障金额扣除」不正确。其余关于终末疾病、主诊医生报告及诊断指明疾病的描述正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項危疾保險利益的附約並不正確：",o:["利益給付金額並不在保險保障金額扣除","支付給處於終末疾病且預期壽命只有12個月或更少的被保人","經由主診醫生發出的報告","診斷患上指明疾病"],e:"危疾保險利益通常屬提前支付性質，其給付金額會從保險保障金額中扣除，故「利益給付金額並不在保險保障金額扣除」不正確。其餘關於終末疾病、主診醫生報告及診斷指明疾病的描述正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项对医疗保险利益附约描述是正确的? i 此类保障没有除外责任 ii 独立签发的医疗利益保障,属于一般保险而不是长期保险 iii 保障包括住院开支及其它医疗费用 iv 自选医疗计划是为基本计划提供更高的保障限额",o:["i, ii","i, ii, iii","ii, iii, iv","i. ii, iii, iv"],a:2,e:"医疗利益保障包含除外责任（故 i 错误），独立签发的医疗利益属一般保险范畴，保障包括住院及其他医疗费用，自选计划则为基本计划提供更高限额，故 ii、iii、iv 正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項對醫療保險利益附約描述是正確的？ i 此類保障沒有除外責任 ii 獨立簽發的醫療利益保障，屬於一般保險而不是長期保險 iii 保障包括住院開支及其它醫療費用 iv 自選醫療計劃是為基本計劃提供更高的保障限額",o:["i, ii","i, ii, iii","ii, iii, iv","i. ii, iii, iv"],e:"醫療利益保障包含除外責任（故 i 錯誤），獨立簽發的醫療利益屬一般保險範疇，保障包括住院及其他醫療費用，自選計劃則為基本計劃提供更高限額，故 ii、iii、iv 正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项对意外死亡及丧失肢体的描述是正确的? i 又称为双倍赔偿利益 ii 与基本保障同样受到一年的自杀免责期的约束 iii 发生意外而引致死亡时可得到额外利益 iv 正常情况下得到相等于保额的两倍金额",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"意外死亡及丧失肢体附约又称双倍赔偿利益，因意外死亡可获额外利益，正常情况下额外给付相等于保额的金额，故 i、iii、iv 正确。它与基本保障的自杀免责期规定不同，故 ii 错误。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項對意外死亡及喪失肢體的描述是正確的？ i 又稱為雙倍賠償利益 ii 與基本保障同樣受到一年的自殺免責期的約束 iii 發生意外而引致死亡時可得到額外利益 iv 正常情況下得到相等於保額的兩倍金額",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"意外死亡及喪失肢體附約又稱雙倍賠償利益，因意外死亡可獲額外利益，正常情況下額外給付相等於保額的金額，故 i、iii、iv 正確。它與基本保障的自殺免責期規定不同，故 ii 錯誤。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项对残疾收入保险利益是正确的?",o:["保险利益会按指定金额每月支付","保险利益属于贷款,某一期间后需清还","等候期由1-6个月不等","只有A及C"],a:3,e:"残疾收入保险利益按指定金额每月支付，且有1至6个月不等的等候期，故 A 与 C 正确；该利益并非贷款、无需日后清还，故 B 错误，答案为「只有A及C」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項對殘疾收入保險利益是正確的？",o:["保險利益會按指定金額每月支付","保險利益屬於貸款，某一期間後需清還","等候期由1-6個月不等","只有A及C"],e:"殘疾收入保險利益按指定金額每月支付，且有1至6個月不等的等候期，故 A 與 C 正確；該利益並非貸款、無需日後清還，故 B 錯誤，答案為「只有A及C」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项对长期护理附约的陈述是不正确的?",o:["等候期一般是一至六个月","所支付的金额将会在保险金中扣除","在接受护理期间,通常保费会被豁免","必须在认可的护理院或在家中由正式注册护理员护理"],a:0,e:"长期护理附约的等候期一般较长（如90天或以上），并非一至六个月，此陈述不正确。所付金额会从保险金中扣除、接受护理期间通常豁免保费及须在认可护理院或由注册护理员护理均正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項對長期護理附約的陳述是不正確的？",o:["等候期一般是一至六個月","所支付的金額將會在保險金中扣除","在接受護理期間，通常保費會被豁免","必須在認可的護理院或在家中由正式註冊護理員護理"],e:"長期護理附約的等候期一般較長（如90天或以上），並非一至六個月，此陳述不正確。所付金額會從保險金中扣除、接受護理期間通常豁免保費及須在認可護理院或由註冊護理員護理均正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项对长期护理附约的陈述是正确的?",o:["等候期一般是一至九个月","所支付的金额将会在保险金中扣除","在接受护理期间,通常保费会被豁免","必须在医院接受护理"],a:2,e:"长期护理附约的正确描述是：在接受长期护理期间，保费通常会被豁免。等候期并非一至九个月、所付金额会从保险金中扣除的说法亦需注意，且护理不一定只在医院进行。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項對長期護理附約的陳述是正確的？",o:["等候期一般是一至九個月","所支付的金額將會在保險金中扣除","在接受護理期間，通常保費會被豁免","必須在醫院接受護理"],e:"長期護理附約的正確描述是：在接受長期護理期間，保費通常會被豁免。等候期並非一至九個月、所付金額會從保險金中扣除的說法亦需注意，且護理不一定只在醫院進行。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项属于保证可保选择的特点? i 限制 ii 非自动获得 iii 暂时的保障 iv 加有豁免保费(WP)附约的保单",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],a:3,e:"保证可保选择的特点包括受限制、并非自动获得、属暂时性保障，且常加附于设有豁免保费(WP)附约的保单，四项均正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項屬於保證可保選擇的特點? i 限制 ii 非自動獲得 iii 暫時的保障 iv 加有豁免保費(WP)附約的保單",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"保證可保選擇的特點包括受限制、並非自動獲得、屬暫時性保障，且常加附於設有豁免保費(WP)附約的保單，四項均正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项属于残疾收入附约的常见条款?",o:["应付金额","等候期","并非贷款或预缴","以上皆是"],a:3,e:"残疾收入附约的常见条款涵盖应付金额、等候期以及「并非贷款或预缴」等条文，故以上皆是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項屬於殘疾收入附約的常見條款?",o:["應付金額","等候期","並非貸款或預繳","以上皆是"],e:"殘疾收入附約的常見條款涵蓋應付金額、等候期以及「並非貸款或預繳」等條文，故以上皆是。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项并不是医疗保险利益的不保范围:",o:["于银行抢劫导致受伤的医疗开支","战争导致受伤或死亡的开支","强奸受害者家属的心理辅导开支","住院病人的专科医生费"],a:3,e:"住院病人的专科医生费属医疗保险的承保范围，并非不保项目。银行抢劫受伤、战争所致伤亡及强奸受害者心理辅导开支等通常列明为不保。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項並不是醫療保險利益的不保範圍:",o:["於銀行搶劫導致受傷的醫療開支","戰爭導致受傷或死亡的開支","強姦受害者家屬的心理輔導開支","住院病人的專科醫生費"],e:"住院病人的專科醫生費屬醫療保險的承保範圍，並非不保項目。銀行搶劫受傷、戰爭所致傷亡及強姦受害者心理輔導開支等通常列明為不保。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项并非符合「完全伤残」一词的定义?",o:["丧失双手","丧失一手和一腿","单目失明","丧失双腿"],a:2,e:"「完全伤残」一般指丧失两肢、双目失明或严重丧失劳动能力等，而单目失明通常只属部分伤残，不属于「完全伤残」的定义。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項並非符合「完全傷殘」一詞的定義?",o:["喪失雙手","喪失一手和一腿","單目失明","喪失雙腿"],e:"「完全傷殘」一般指喪失兩肢、雙目失明或嚴重喪失勞動能力等，而單目失明通常只屬部分傷殘，不屬於「完全傷殘」的定義。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项形容提前支付死亡保险利益? i 又名生前支付死亡保险利益 ii 只为保障受保生命预期寿命不超过12个月 iii 受益人或承继人须签署一份弃权声明 iv 可能引致受益人极为失望",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"提前支付死亡保险利益又名生前支付死亡保险利益，只保障预期寿命不超过12个月的受保生命，且受益人或承继人须签署弃权声明，故 i、ii、iii 正确；它本身是正式给付，iv 说法不正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項形容提前支付死亡保險利益？ i 又名生前支付死亡保險利益 ii 只為保障受保生命預期壽命不超過12個月 iii 受益人或承繼人須簽署一份棄權聲明 iv 可能引致受益人極為失望",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"提前支付死亡保險利益又名生前支付死亡保險利益，只保障預期壽命不超過12個月的受保生命，且受益人或承繼人須簽署棄權聲明，故 i、ii、iii 正確；它本身是正式給付，iv 說法不正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项情况是医疗保险利益之除外责任? i 保单生效前既存的状况 ii 生育的开支 iii 因道路意外而引致的医疗费用 iv 因爱滋病而有关的症状",o:["i, ii,iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"医疗保险利益的除外责任通常包括保单生效前既存的状况、生育开支及与爱滋病有关的症状，即 i、ii、iv 正确。因道路意外引致的医疗费用属承保范围，故 iii 错误。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項情況是醫療保險利益之除外責任？ i 保單生效前既存的狀況 ii 生育的開支 iii 因道路意外而引致的醫療費用 iv 因愛滋病而有關的症狀",o:["i, ii,iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"醫療保險利益的除外責任通常包括保單生效前既存的狀況、生育開支及與愛滋病有關的症狀，即 i、ii、iv 正確。因道路意外引致的醫療費用屬承保範圍，故 iii 錯誤。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项或哪些是意外死亡保险利益的除外责任?",o:["传染病引致的情况","自杀不遂导致伤残","于入屋犯法时不幸失足堕下受伤","以上都包括"],a:3,e:"意外死亡保险利益的除外责任包括传染病引致的情况、自杀不遂导致伤残及入屋犯法时堕下受伤等，故以上都包括。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項或哪些是意外死亡保險利益的除外責任？",o:["傳染病引致的情況","自殺不遂導致傷殘","於入屋犯法時不幸失足墮下受傷","以上都包括"],e:"意外死亡保險利益的除外責任包括傳染病引致的情況、自殺不遂導致傷殘及入屋犯法時墮下受傷等，故以上都包括。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项或哪些有关「豁免保费附约」的支付利益准则的描述是正确的?",o:["保单受保人在变成完全伤残时必须维持到某段时间后死亡","保单受保人在变成完全伤残时必须已经有部份残疾达到某段时间","保单受保人必须在保单有效期内完全伤残且达到某段时间,称为「等候期」","以上所有各项均不属于"],a:2,e:"豁免保费附约的支付准则为：受保保单所有人须在保单有效期内变成完全伤残，且该状况须维持达某段期间（即等候期），而非须死亡或在投保前已部分残疾。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項或哪些有關「豁免保費附約」的支付利益準則的描述是正確的？",o:["保單受保人在變成完全傷殘時必須維持到某段時間後死亡","保單受保人在變成完全傷殘時必須已經有部份殘疾達到某段時間","保單受保人必須在保單有效期內完全傷殘且達到某段時間，稱為「等候期」","以上所有各項均不屬於"],e:"豁免保費附約的支付準則為：受保保單所有人須在保單有效期內變成完全傷殘，且該狀況須維持達某段期間（即等候期），而非須死亡或在投保前已部分殘疾。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项描述残疾收入保障利益中的收入保险利益是正确的:",o:["收入保险利益会在保额扣除","收入保险利益不会影响保额","收入保险利益会在保单未来红利中扣除","收入保险利益其实未来保费的保单贷款"],a:1,e:"残疾收入保障中已给付的收入保险利益不会从保额中扣除，也不会影响未来红利，并非保单贷款，故「收入保险利益不会影响保额」正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項描述殘疾收入保障利益中的收入保險利益是正確的：",o:["收入保險利益會在保額扣除","收入保險利益不會影響保額","收入保險利益會在保單未來紅利中扣除","收入保險利益其實未來保費的保單貸款"],e:"殘疾收入保障中已給付的收入保險利益不會從保額中扣除，也不會影響未來紅利，並非保單貸款，故「收入保險利益不會影響保額」正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项是「豁免保费附约」是正确描述?",o:["保单所有人完全残疾,残疾期间豁免保费","当保单生效一段期间后保单所有人完全残疾;残疾期间豁免保费","当保单所有人失业时豁免保单所有人之保费","当市场上竞争对手保费低廉,保险人便退还保费"],a:0,e:"豁免保费附约的效用是当受保保单所有人完全残疾并达指定期间，即获豁免该期间的保费。选项0正确，其余关于生效期间、失业或竞争对手保费的描述均不符。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項是「豁免保費附約」是正確描述？",o:["保單所有人完全殘疾，殘疾期間豁免保費","當保單生效一段期間後保單所有人完全殘疾；殘疾期間豁免保費","當保單所有人失業時豁免保單所有人之保費","當市場上競爭對手保費低廉，保險人便退還保費"],e:"豁免保費附約的效用是當受保保單所有人完全殘疾並達指定期間，即獲豁免該期間的保費。選項0正確，其餘關於生效期間、失業或競爭對手保費的描述均不符。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项是对残疾收入附约的正确描述?",o:["这附加契约可附加于所有类型的保险上","等候期订为一个月至六个月不等","已收取的收入保险利益于未来死亡保险金扣回","以上各项皆是"],a:1,e:"残疾收入附约的等候期一般订为一个月至六个月不等，是其常见条款。它并不能附加于所有类型的保险，已收取的收入利益亦不会于未来死亡保险金中扣回。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項是對殘疾收入附約的正確描述？",o:["這附加契約可附加於所有類型的保險上","等候期訂為一個月至六個月不等","已收取的收入保險利益於未來死亡保險金扣回","以上各項皆是"],e:"殘疾收入附約的等候期一般訂為一個月至六個月不等，是其常見條款。它並不能附加於所有類型的保險，已收取的收入利益亦不會於未來死亡保險金中扣回。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项是有关自愿医保的机会?",o:["自愿医保计划由税务局推行及认可, 为愿意及有能力使用私营服务的消费者提供额外的选择","自愿医保计划为个人偿款住院保险产品住院保险产品, 为愿意及有能力使用私营服务的消费者提供额外的选择","自愿医保计划由税务局推行及认可, 为愿意及有能力使用私营服务的香港居民提供额外的选择","自愿医保计划为个人及团体保险产品, 为愿意及有能力使用私营服务的香港居民提供额外的选择"],a:1,e:"自愿医保计划为个人偿款住院保险产品，为愿意及有能力使用私营服务的消费者提供额外选择。它并非由税务局推行、对象亦不限于「香港居民」或团体产品，故其余表述不准确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項是有關自願醫保的機會?",o:["自願醫保計劃由稅務局推行及認可, 為願意及有能力使用私營服務的消費者提供額外的選擇","自願醫保計劃為個人償款住院保險產品住院保險產品, 為願意及有能力使用私營服務的消費者提供額外的選擇","自願醫保計劃由稅務局推行及認可, 為願意及有能力使用私營服務的香港居民提供額外的選擇","自願醫保計劃為個人及團體保險產品, 為願意及有能力使用私營服務的香港居民提供額外的選擇"],e:"自願醫保計劃為個人償款住院保險產品，為願意及有能力使用私營服務的消費者提供額外選擇。它並非由税務局推行、對象亦不限於「香港居民」或團體產品，故其餘表述不準確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项是生活指数调整附约原意﹖",o:["对抗通货膨胀和通缩的影响","在受保生命死后为其受养人提供一项收入","在保险人的盈利低于一般水平时,作为补充红利","以上皆不是"],a:3,e:"生活指数调整附约的原意是对抗通胀对购买力的影响，而非对抗通缩，亦非在受保人身故后为其受养人提供收入，更非作为补充红利，故以上皆不是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項是生活指數調整附約原意﹖",o:["對抗通貨膨脹和通縮的影響","在受保生命死後為其受養人提供一項收入","在保險人的盈利低於一般水平時，作為補充紅利","以上皆不是"],e:"生活指數調整附約的原意是對抗通脹對購買力的影響，而非對抗通縮，亦非在受保人身故後為其受養人提供收入，更非作為補充紅利，故以上皆不是。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项有关「WP」的陈述是正确的?",o:["英文缩写(WP)是指「等候期 Waiting Period」","英文缩写(WP)是指「有利润 With-Profit」","被保险人必须变成严重伤残方可获得豁免","保费获得豁免前设有一段等候时期"],a:3,e:"WP 是 Waiver of Premium（豁免保费）的缩写，而非等候期或分红，且通常规定保费获豁免前须先经过一段等候期（完全伤残持续指定期间），故答案为保费豁免前设有等候时期。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項有關「WP」的陳述是正確的?",o:["英文縮寫(WP)是指「等候期 Waiting Period」","英文縮寫(WP)是指「有利潤 With-Profit」","被保險人必須變成嚴重傷殘方可獲得豁免","保費獲得豁免前設有一段等候時期"],e:"WP 是 Waiver of Premium（豁免保費）的縮寫，而非等候期或分紅，且通常規定保費獲豁免前須先經過一段等候期（完全傷殘持續指定期間），故答案為保費豁免前設有等候時期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项有关「残疾豁免保费」是正确的?",o:["当受保保单所有人变成完全伤残时,保险人代为支付保费","当受保保单所有人变成完全伤残时,保单所有人代为支付保费","受保保单所有人逝世后可获豁免保费","若有另一间保险公司提供较低廉保费,则可获豁免保费"],a:0,e:"「残疾豁免保费」指当受保保单所有人变成完全伤残并达指定期间，保险人代为支付保费。由保单所有人自行支付、身故后豁免或竞争对手保费较低均不属于豁免保费的运作。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項有關「殘疾豁免保費」是正確的?",o:["當受保保單所有人變成完全傷殘時，保險人代為支付保費","當受保保單所有人變成完全傷殘時，保單所有人代為支付保費","受保保單所有人逝世後可獲豁免保費","若有另一間保險公司提供較低廉保費，則可獲豁免保費"],e:"「殘疾豁免保費」指當受保保單所有人變成完全傷殘並達指定期間，保險人代為支付保費。由保單所有人自行支付、身故後豁免或競爭對手保費較低均不屬於豁免保費的運作。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项有关「豁免保费」附约支付利益的准则的说明最正确的?",o:["受保保单所有人必须维持了完全偒残最少达某段期间之后死亡","当受保保单所有人变成完全偒残时,保单必须最少已经生效了某段期间","受保保单所有人必须在保单期限内变成完全伤残,而这状况又最少维持了某段期间","上述没有一项是该附约的支付利益的准则"],a:2,e:"豁免保费附约的支付利益准则为：受保保单所有人必须在保单期限内变成完全伤残，且该状况维持达某段期间（等候期），而非须死亡或仅在投保后某期间生效。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項有關「豁免保費」附約支付利益的準則的說明最正確的？",o:["受保保單所有人必須維持了完全偒殘最少達某段期間之後死亡","當受保保單所有人變成完全偒殘時，保單必須最少已經生效了某段期間","受保保單所有人必須在保單期限內變成完全傷殘，而這狀況又最少維持了某段期間","上述沒有一項是該附約的支付利益的準則"],e:"豁免保費附約的支付利益準則為：受保保單所有人必須在保單期限內變成完全傷殘，且該狀況維持達某段期間（等候期），而非須死亡或僅在投保後某期間生效。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项有关意外死亡保险利益的陈述是正确的? i 所给付的利益又称为意外利益 ii 唯一的除外责任,是由战争所引起的伤残 iii 如死亡由意外导致,须额外支付一笔与保额相等的利益 iv 意外发生后,死亡必须于一年内发生",o:["i","i, ii","iii, iv","i, ii, iii, iv"],a:2,e:"意外死亡保险利益的正确描述是：若死亡由意外导致，须额外支付一笔与保额相等的利益，且死亡必须在意外发生后一年内发生，故 iii、iv 正确。该利益并非称「意外利益」，亦非仅战争为除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項有關意外死亡保險利益的陳述是正確的？ i 所給付的利益又稱為意外利益 ii 唯一的除外責任，是由戰爭所引起的傷殘 iii 如死亡由意外導致，須額外支付一筆與保額相等的利益 iv 意外發生後，死亡必須於一年內發生",o:["i","i, ii","iii, iv","i, ii, iii, iv"],e:"意外死亡保險利益的正確描述是：若死亡由意外導致，須額外支付一筆與保額相等的利益，且死亡必須在意外發生後一年內發生，故 iii、iv 正確。該利益並非稱「意外利益」，亦非僅戰爭為除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项有关自愿医保的描述不太可能正确?",o:["提升个人住院保险的质素和透明度","为原本负担不起私营医疗服务的大众市民透过医疗保险产品而可享私营医疗服务","为愿意及有能力使用私营医疗服务的消费者提供一个额外的选择","保险公司及消费者参与自愿医保均属自愿性质"],a:1,e:"自愿医保旨在提升个人住院保险的质素和透明度，为愿意及有能力使用私营服务的消费者提供额外选择，且参与属自愿，但并非让「原本负担不起私营医疗服务的大众」都可享私营服务，故选项1不太可能正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項有關自願醫保的描述不太可能正確？",o:["提升個人住院保險的質素和透明度","為原本負擔不起私營醫療服務的大眾市民透過醫療保險產品而可享私營醫療服務","為願意及有能力使用私營醫療服務的消費者提供一個額外的選擇","保險公司及消費者參與自願醫保均屬自願性質"],e:"自願醫保旨在提升個人住院保險的質素和透明度，為願意及有能力使用私營服務的消費者提供額外選擇，且參與屬自願，但並非讓「原本負擔不起私營醫療服務的大眾」都可享私營服務，故選項1不太可能正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项适用于「生活指数调整」?",o:["关于通货膨胀与通货紧缩两者间的关系","相当于投保人去世后付予受养人一笔收入","提供予投保人一笔定期增加的保险利益","提供予投保人一笔一次性的赔偿"],a:2,e:"生活指数调整(COLA)为投保人提供一笔定期增加的保险利益，以抵御通胀。它并非讨论通胀与通缩的关系，也非身故后付予受养人的收入或一次性赔偿。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項適用於「生活指數調整」？",o:["關於通貨膨脹與通貨緊縮兩者間的關係","相當於投保人去世後付予受養人一筆收入","提供予投保人一筆定期增加的保險利益","提供予投保人一筆一次性的賠償"],e:"生活指數調整(COLA)為投保人提供一筆定期增加的保險利益，以抵禦通脹。它並非討論通脹與通縮的關係，也非身故後付予受養人的收入或一次性賠償。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下那项是豁免保费(WP)的不正确描述?",o:["通常设有等候期","非法行为引致的残疾是不受保的","遭遇残疾后可获豁免缴交基本计划的保费","在购买保障时必须是全部或部份残疾"],a:3,e:"豁免保费(WP)附约通常设有等候期、非法行为致残不受保，并在残疾后豁免基本计划保费；但它并不要求「购买保障时必须是全部或部份残疾」，故该描述不正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下那項是豁免保費(WP)的不正確描述？",o:["通常設有等候期","非法行為引致的殘疾是不受保的","遭遇殘疾後可獲豁免繳交基本計劃的保費","在購買保障時必須是全部或部份殘疾"],e:"豁免保費(WP)附約通常設有等候期、非法行為致殘不受保，並在殘疾後豁免基本計劃保費；但它並不要求「購買保障時必須是全部或部份殘疾」，故該描述不正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"伤残而不用交保费的附约称为:",o:["伤残豁免保费","伤残优惠","患病及伤残优惠","残疾保费优惠"],a:0,e:"因伤残而免缴保费的附约称为「伤残豁免保费」。伤残优惠、患病及伤残优惠及残疾保费优惠等均非其标准名称。",src:1,tw:{ch:"保險利益附約及其他產品",q:"傷殘而不用交保費的附約稱為:",o:["傷殘豁免保費","傷殘優惠","患病及傷殘優惠","殘疾保費優惠"],e:"因傷殘而免繳保費的附約稱為「傷殘豁免保費」。傷殘優惠、患病及傷殘優惠及殘疾保費優惠等均非其標準名稱。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保单内附有保证可保利益附约,但保单所有人在指定期间内没有作出购买增额保险的选择,后果是",o:["永久丧失增额的权利","保单便告终止","丧失该项权利,但下一次可获相同权利","以上所有皆正确"],a:2,e:"保证可保利益附约规定，若保单所有人在指定期间内未行使购买增额保险的选择，则失去该次权利，但下一次仍可在新的备择日期享有相同权利，而保单不会因此终止。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保單內附有保證可保利益附約，但保單所有人在指定期間內沒有作出購買增額保險的選擇，後果是",o:["永久喪失增額的權利","保單便告終止","喪失該項權利，但下一次可獲相同權利","以上所有皆正確"],e:"保證可保利益附約規定，若保單所有人在指定期間內未行使購買增額保險的選擇，則失去該次權利，但下一次仍可在新的備擇日期享有相同權利，而保單不會因此終止。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保单所有人有权在指定的备择日期赠买增额保险,而无需递交可保证明, 这种保障称为:",o:["保证可保利益","保证受保利益","终身受保权益","终身受保利益"],a:0,e:"保单所有人有权在指定的备择日期购买增额保险而无需递交可保证明的保障，称为保证可保利益。其余名称并非此标准术语。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保單所有人有權在指定的備擇日期贈買增額保險，而無需遞交可保證明, 這種保障稱為：",o:["保證可保利益","保證受保利益","終身受保權益","終身受保利益"],e:"保單所有人有權在指定的備擇日期購買增額保險而無需遞交可保證明的保障，稱為保證可保利益。其餘名稱並非此標準術語。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保(Guaranteed Insurability (GI) Benefits) 利益指保单所有人有权在指定的 备择日期购买增额保险,而毋须提供可保证明。若该保险本身已加有豁免保费附约,而「受保保单所有 人」在可以行使购买增额保险选择权时遭致伤残,「受保保单所有人」",o:["便可自动获得该额外保障","不会获得额外保障,直至康复为止","可行使有关权利,但最终由保险人决定","非自动获得该权利,除非他在备择日期时决定购买"],a:0,e:"当保单已附加豁免保费附约，而受保保单所有人在可行使增额选择时遭致伤残，则其可自动获得该额外保障，无须待康复或由保险人另行决定。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保(Guaranteed Insurability (GI) Benefits) 利益指保單所有人有權在指定的 備擇日期購買增額保險，而毋須提供可保證明。若該保險本身已加有豁免保費附約，而「受保保單所有 人」在可以行使購買增額保險選擇權時遭致傷殘，「受保保單所有人」",o:["便可自動獲得該額外保障","不會獲得額外保障，直至康復為止","可行使有關權利，但最終由保險人決定","非自動獲得該權利，除非他在備擇日期時決定購買"],e:"當保單已附加豁免保費附約，而受保保單所有人在可行使增額選擇時遭致傷殘，則其可自動獲得該額外保障，無須待康復或由保險人另行決定。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益为受保保单所有人提供增加保额的机会,如受保保单所有人于指定时间不作出选择,以下 哪种情况会发生?",o:["保单会被中止","将会失去该次保证可保利益的权利","往后所有保证可保利益都会失去","仍可以提高保额,但比原本设置的金额低"],a:1,e:"保证可保利益若在某指定日期未被行使，将失去该次增额的权利，但保单不会中止，往后的选择机会仍保留，故「将会失去该次保证可保利益的权利」正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益為受保保單所有人提供增加保額的機會，如受保保單所有人於指定時間不作出選擇，以下 哪種情況會發生？",o:["保單會被中止","將會失去該次保證可保利益的權利","往後所有保證可保利益都會失去","仍可以提高保額，但比原本設置的金額低"],e:"保證可保利益若在某指定日期未被行使，將失去該次增額的權利，但保單不會中止，往後的選擇機會仍保留，故「將會失去該次保證可保利益的權利」正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益可于某些指定日子选择增加保额,指定日期通常是指:",o:["结婚","子女出生","某些备择日期","以上各项"],a:3,e:"保证可保利益可在结婚、子女出生及某些备择日期等指定日子选择增加保额，故以上各项均可作为行使增额权的指定日期。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益可於某些指定日子選擇增加保額，指定日期通常是指：",o:["結婚","子女出生","某些備擇日期","以上各項"],e:"保證可保利益可在結婚、子女出生及某些備擇日期等指定日子選擇增加保額，故以上各項均可作為行使增額權的指定日期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益是指保单所有人在指定日子选择增加保额而无需提供可保证明,在行使期间保单所有人不 幸死亡:",o:["保险金额立即增加","取回保单原有保额","部份保险人会自动提供定期寿险提供额外保障","死者亲人可于三十天内向保险公司办理手续"],a:2,e:"保证可保利益附约下，若保单所有人在行使增额选择期间不幸死亡，部分保险人会自动提供定期寿险，为保障额提供临时额外保障，而非立即增加保额或取回原保额。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益是指保單所有人在指定日子選擇增加保額而無需提供可保證明，在行使期間保單所有人不 幸死亡：",o:["保險金額立即增加","取回保單原有保額","部份保險人會自動提供定期壽險提供額外保障","死者親人可於三十天內向保險公司辦理手續"],e:"保證可保利益附約下，若保單所有人在行使增額選擇期間不幸死亡，部分保險人會自動提供定期壽險，為保障額提供臨時額外保障，而非立即增加保額或取回原保額。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益是指受保保单所有人可在指定时期或特定日子增加保障而不需要提供可保证明,若受保保 单所有人在这指定时期内,办妥手续前逝世:",o:["保险人会双倍赔偿死亡保额","保障额会自动增加","部分保险人会在这个时期自动提供定期寿险","其双亲可在三十天内向保险人办理增额手续"],a:2,e:"受保保单所有人在指定行使期间、办妥增额手续前逝世，部分保险人会在此期间自动提供定期寿险以提供临时额外保障，并非双倍赔偿或自动增加保额。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益是指受保保單所有人可在指定時期或特定日子增加保障而不需要提供可保證明，若受保保 單所有人在這指定時期內，辦妥手續前逝世：",o:["保險人會雙倍賠償死亡保額","保障額會自動增加","部分保險人會在這個時期自動提供定期壽險","其雙親可在三十天內向保險人辦理增額手續"],e:"受保保單所有人在指定行使期間、辦妥增額手續前逝世，部分保險人會在此期間自動提供定期壽險以提供臨時額外保障，並非雙倍賠償或自動增加保額。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益的定义为:",o:["保单所有人有权在指定的备择日期赠买增额保险,无需递交可保证明","保单所有人有权在任何时候购买增额保险,无需递交可保证明","保单所有人有权在指定的备择日期赠买增额保险,必需递交可保证明","保单所有人有权在任何时候购买增额保险,必需递交可保证明"],a:0,e:"保证可保利益的定义为：保单所有人有权在指定的备择日期购买增额保险，且无需递交可保证明。并非任何时候均可行使，也非必须递交可保证明。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益的定義為：",o:["保單所有人有權在指定的備擇日期贈買增額保險，無需遞交可保證明","保單所有人有權在任何時候購買增額保險，無需遞交可保證明","保單所有人有權在指定的備擇日期贈買增額保險，必需遞交可保證明","保單所有人有權在任何時候購買增額保險，必需遞交可保證明"],e:"保證可保利益的定義為：保單所有人有權在指定的備擇日期購買增額保險，且無需遞交可保證明。並非任何時候均可行使，也非必須遞交可保證明。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益附约指保单所有人有权购买增额保险,并且保证可保,如保单同时加有豁免保费附约,受 保保单所有人准备行使增额权时遭致伤残,那么:",o:["保证可保利益附约会被取消","增额保障自动生效","待受保保单所有人完全康复后,才可行使增额保险","受保保单所有人可以要求行使增额保险,但或遭拒绝"],a:1,e:"若保单附加保证可保利益及豁免保费附约，受保保单所有人在准备行使增额权时遭致伤残，则增额保障会自动生效，无须待康复或遭拒绝。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益附約指保單所有人有權購買增額保險，並且保證可保，如保單同時加有豁免保費附約，受 保保單所有人準備行使增額權時遭致傷殘，那麼：",o:["保證可保利益附約會被取消","增額保障自動生效","待受保保單所有人完全康復後，才可行使增額保險","受保保單所有人可以要求行使增額保險，但或遭拒絕"],e:"若保單附加保證可保利益及豁免保費附約，受保保單所有人在準備行使增額權時遭致傷殘，則增額保障會自動生效，無須待康復或遭拒絕。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保选择有时附加于人寿保险单中,意思是:",o:["附加保费以接受次标准风险","付款以符合索偿时的限制保额","于特定日期时自动提供保险","无须提供可保证明下购买增额保险"],a:3,e:"保证可保选择附加于人寿保单，指保单所有人无须提供可保证明即可在指定日期购买增额保险。它并非为次标准风险附加保费、付款以符合限制保额或自动提供保险。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保選擇有時附加於人壽保險單中，意思是：",o:["附加保費以接受次標準風險","付款以符合索償時的限制保額","於特定日期時自動提供保險","無須提供可保證明下購買增額保險"],e:"保證可保選擇附加於人壽保單，指保單所有人無須提供可保證明即可在指定日期購買增額保險。它並非為次標準風險附加保費、付款以符合限制保額或自動提供保險。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保险人希望于一般保险而非寿险保单上加入医疗保障,这安排?",o:["法律上是不可行的","需要向政府额外缴付保费税款","需要经保险业监管局的认可","保险人需要有关经营疾病经营的牌照"],a:3,e:"保险人若要在一份一般保险保单上加入医疗保障，须持有经营该疾病（医疗）类别的牌照，符合监管要求。此项安排并无法律上不可行、额外保费税或须监管局认可的说法。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保險人希望於一般保險而非壽險保單上加入醫療保障，這安排?",o:["法律上是不可行的","需要向政府額外繳付保費稅款","需要經保險業監管局的認可","保險人需要有關經營疾病經營的牌照"],e:"保險人若要在一份一般保險保單上加入醫療保障，須持有經營該疾病（醫療）類別的牌照，符合監管要求。此項安排並無法律上不可行、額外保費税或須監管局認可的說法。"}},
{p:3,ch:"保险利益附约及其他产品",q:"假设意外发生时同时丧失两肢,而寿险保单附有意外死亡及丧失肢体附约,以下哪三项原因可能会导致 索偿无效? i 企图自杀 ii 服役时因战争引致受伤 iii 参予指定之运动 iv 无辜受害者于银行劫案中遭到犯案者枪击",o:["i, ii, iii","i, ii, iv","i, iii,iv","ii, iii, iv"],a:0,e:"意外死亡及丧失肢体附约中，企图自杀、服役时因战争受伤及参予指定运动（高危运动）通常属除外责任，可致索偿无效；无辜受害者于银行劫案中遭枪击属意外，仍可获赔，故 i、ii、iii 正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"假設意外發生時同時喪失兩肢，而壽險保單附有意外死亡及喪失肢體附約，以下哪三項原因可能會導致 索償無效？ i 企圖自殺 ii 服役時因戰爭引致受傷 iii 參予指定之運動 iv 無辜受害者於銀行劫案中遭到犯案者槍擊",o:["i, ii, iii","i, ii, iv","i, iii,iv","ii, iii, iv"],e:"意外死亡及喪失肢體附約中，企圖自殺、服役時因戰爭受傷及參予指定運動（高危運動）通常屬除外責任，可致索償無效；無辜受害者於銀行劫案中遭槍擊屬意外，仍可獲賠，故 i、ii、iii 正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"关于保费缴付频率的更改,豁免保费附约的规定:",o:["在任何时候,都可以要求更改","在任何情况下,更改是不允许的","在残疾保险生效期间,更改是不允许的","在残疾保险生效期间,从按月缴费更改到按年缴是允许的"],a:2,e:"豁免保费附约规定，在残疾保险（豁免保费）生效期间，保费缴付频率的更改是不允许的。其余关于随时或任何情况下更改的说法均不符。",src:1,tw:{ch:"保險利益附約及其他產品",q:"關於保費繳付頻率的更改，豁免保費附約的規定：",o:["在任何時候，都可以要求更改","在任何情況下，更改是不允許的","在殘疾保險生效期間，更改是不允許的","在殘疾保險生效期間，從按月繳費更改到按年繳是允許的"],e:"豁免保費附約規定，在殘疾保險（豁免保費）生效期間，保費繳付頻率的更改是不允許的。其餘關於隨時或任何情況下更改的說法均不符。"}},
{p:3,ch:"保险利益附约及其他产品",q:"其他意外保险利益附约的赔偿一般为: i 失去一只眼,便会有50%的赔偿金 ii 失去一眼及一手,便会有100%的赔偿金 iii 死亡,便会有100%的赔偿金 iv 死亡及丧失肢体的赔偿金是相等的",o:["i. ii, iii","i. ii, iv","i. iii, iv","ii. Iii, iv"],a:0,e:"其他意外保险利益的一般赔偿为：失去一只眼给付50%赔偿金、失去一眼及一手或死亡给付100%赔偿金，故 i、ii、iii 正确。死亡与丧失肢体的赔偿金并不相等，故 iv 错误。",src:1,tw:{ch:"保險利益附約及其他產品",q:"其他意外保險利益附約的賠償一般為： i 失去一隻眼，便會有50%的賠償金 ii 失去一眼及一手，便會有100%的賠償金 iii 死亡，便會有100%的賠償金 iv 死亡及喪失肢體的賠償金是相等的",o:["i. ii, iii","i. ii, iv","i. iii, iv","ii. Iii, iv"],e:"其他意外保險利益的一般賠償為：失去一隻眼給付50%賠償金、失去一眼及一手或死亡給付100%賠償金，故 i、ii、iii 正確。死亡與喪失肢體的賠償金並不相等，故 iv 錯誤。"}},
{p:3,ch:"保险利益附约及其他产品",q:"典型的危疾保险利益附约所保的「指明疾病」,不大可能包括﹕",o:["中风","伤风","对生命构成威胁的癌症","末期肾衰竭"],a:1,e:"危疾保险利益的「指明疾病」指严重且危及生命的疾病，如中风、威胁生命的癌症及末期肾衰竭等，而伤风属轻微疾病，不大可能被列入。",src:1,tw:{ch:"保險利益附約及其他產品",q:"典型的危疾保險利益附約所保的「指明疾病」，不大可能包括﹕",o:["中風","傷風","對生命構成威脅的癌症","末期腎衰竭"],e:"危疾保險利益的「指明疾病」指嚴重且危及生命的疾病，如中風、威脅生命的癌症及末期腎衰竭等，而傷風屬輕微疾病，不大可能被列入。"}},
{p:3,ch:"保险利益附约及其他产品",q:"包含了生活指数调整(COLA)的保单条款,为遭受残疾的受保保单所有人提供周期性增加的残疾收入保险 利益,而增加的数目一般相等于:",o:["每年增加百分之五","通货膨胀","消费者物价指数","受保保单所有人薪金调整幅度"],a:2,e:"生活指数调整(COLA)使受保保单所有人的残疾收入随指数周期性增加，增加的数目一般与消费者物价指数挂钩。定额5%、单纯通胀或薪金调整幅度均非其标准对照。",src:1,tw:{ch:"保險利益附約及其他產品",q:"包含了生活指數調整(COLA)的保單條款，為遭受殘疾的受保保單所有人提供周期性增加的殘疾收入保險 利益，而增加的數目一般相等於：",o:["每年增加百分之五","通貨膨脹","消費者物價指數","受保保單所有人薪金調整幅度"],e:"生活指數調整(COLA)使受保保單所有人的殘疾收入隨指數週期性增加，增加的數目一般與消費者物價指數掛鈎。定額5%、單純通脹或薪金調整幅度均非其標準對照。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾保险利益中的\"指明疾病\"是指: i 伤残 ii 心脏相关疾病 iii 癌症 iv 重要器官相关疾病",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],a:3,e:"危疾保险利益中的「指明疾病」通常涵盖伤残、心脏相关疾病、癌症及重要器官相关疾病等类别，故 i、ii、iii、iv 四项均属指明疾病范围。",src:1,tw:{ch:"保險利益附約及其他產品",q:"危疾保險利益中的\"指明疾病\"是指： i 傷殘 ii 心臟相關疾病 iii 癌症 iv 重要器官相關疾病",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"危疾保險利益中的「指明疾病」通常涵蓋傷殘、心臟相關疾病、癌症及重要器官相關疾病等類別，故 i、ii、iii、iv 四項均屬指明疾病範圍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾保险利益中的\"指明疾病\"是指：",o:["心脏相关疾病","癌症","重要器官相关疾病","以上皆是"],a:3,e:"危疾保险利益的「指明疾病」包括心脏相关疾病、癌症及重要器官相关疾病等，故以上皆是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"危疾保險利益中的\"指明疾病\"是指：",o:["心臟相關疾病","癌症","重要器官相關疾病","以上皆是"],e:"危疾保險利益的「指明疾病」包括心臟相關疾病、癌症及重要器官相關疾病等，故以上皆是。"}},
{p:3,ch:"保险利益附约及其他产品",q:"危疾附约:",o:["诊断患上指明疾病","诊断患上终末疾病且预期只有12个月寿命","必须接受指明的医疗程序","以上各项皆是"],a:3,e:"危疾附约的给付条件包括诊断患上指明疾病、诊断患终末疾病且预期只有12个月寿命，或必须接受指明的医疗程序，故以上各项皆是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"危疾附約：",o:["診斷患上指明疾病","診斷患上終末疾病且預期只有12個月壽命","必須接受指明的醫療程序","以上各項皆是"],e:"危疾附約的給付條件包括診斷患上指明疾病、診斷患終末疾病且預期只有12個月壽命，或必須接受指明的醫療程序，故以上各項皆是。"}},
{p:3,ch:"保险利益附约及其他产品",q:"双倍赔偿利益是指意外死亡由身体受伤而引起:",o:["保单保额双倍赔偿","保额以外的殓葬费","现金红利的两倍","已缴交保费两倍的退保费"],a:0,e:"双倍赔偿利益指因意外导致的身体受伤而死亡时，在基本保额外再给付相等于保额的利益，即合计获得保额的双倍。它并非殓葬费、红利或退保费的两倍。",src:1,tw:{ch:"保險利益附約及其他產品",q:"雙倍賠償利益是指意外死亡由身體受傷而引起：",o:["保單保額雙倍賠償","保額以外的殮葬費","現金紅利的兩倍","已繳交保費兩倍的退保費"],e:"雙倍賠償利益指因意外導致的身體受傷而死亡時，在基本保額外再給付相等於保額的利益，即合計獲得保額的雙倍。它並非殮葬費、紅利或退保費的兩倍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"受保保单所有人唯有在下列情况下可以得到长期护理附加保险利益的赔付?",o:["终身瘫痪","长期昏迷","因某些特定情况下需要长期护理","预期寿命少于1年"],a:2,e:"长期护理附加保险利益在受保人因某些特定情况（如无法自理）而需要长期护理时给付。终身瘫痪、长期昏迷或预期寿命少于1年并非其给付条件的完整描述。",src:1,tw:{ch:"保險利益附約及其他產品",q:"受保保單所有人唯有在下列情況下可以得到長期護理附加保險利益的賠付？",o:["終身癱瘓","長期昏迷","因某些特定情況下需要長期護理","預期壽命少於1年"],e:"長期護理附加保險利益在受保人因某些特定情況（如無法自理）而需要長期護理時給付。終身癱瘓、長期昏迷或預期壽命少於1年並非其給付條件的完整描述。"}},
{p:3,ch:"保险利益附约及其他产品",q:"受保保单所有人因意外入院,昏迷两月后死亡,可否得到意外死亡保险利益?",o:["不可以,因死亡并不是意外导致","可以,因死亡在意外后一年内发生,而死亡是意外的结果","不可以,因并不是即时死亡","以上各项皆不是"],a:1,e:"意外昏迷两月后死亡仍属意外死亡，只要死亡在意外发生后一年内发生且是意外直接导致的结果，即可获意外死亡保险利益。它并不要求即时死亡。",src:1,tw:{ch:"保險利益附約及其他產品",q:"受保保單所有人因意外入院，昏迷兩月後死亡，可否得到意外死亡保險利益？",o:["不可以，因死亡並不是意外導致","可以，因死亡在意外後一年內發生，而死亡是意外的結果","不可以，因並不是即時死亡","以上各項皆不是"],e:"意外昏迷兩月後死亡仍屬意外死亡，只要死亡在意外發生後一年內發生且是意外直接導致的結果，即可獲意外死亡保險利益。它並不要求即時死亡。"}},
{p:3,ch:"保险利益附约及其他产品",q:"受保保单所有人在下列哪项情况下才可获得长期护理(LTC)附约的利益?",o:["受保保单所有人出现昏迷情况","受保保单所有人出现瘫痪情况","受保保单所有人只有一年寿命","受保保单所有人身体需要接受长期护理"],a:3,e:"长期护理(LTC)附约的给付条件是受保保单所有人身体需要接受长期护理，而非仅出现昏迷、瘫痪或预期寿命只有一年。",src:1,tw:{ch:"保險利益附約及其他產品",q:"受保保單所有人在下列哪項情況下才可獲得長期護理(LTC)附約的利益？",o:["受保保單所有人出現昏迷情況","受保保單所有人出現癱瘓情況","受保保單所有人只有一年壽命","受保保單所有人身體需要接受長期護理"],e:"長期護理(LTC)附約的給付條件是受保保單所有人身體需要接受長期護理，而非僅出現昏迷、癱瘓或預期壽命只有一年。"}},
{p:3,ch:"保险利益附约及其他产品",q:"可保权利益在受保保单所有人有权行使购买增额保险选择的期间死亡,保险人会提供:",o:["自动支付双倍赔付","不能获得支付","定期寿险支付","家庭成员可以在30日内提出行使而获得提升支付"],a:2,e:"保证可保利益（可保权利益）在受保保单所有人有权行使增额选择期间死亡时，保险人会提供定期寿险支付，作为该期间的临时附加保障，而非双倍赔付或提升保额。",src:1,tw:{ch:"保險利益附約及其他產品",q:"可保權利益在受保保單所有人有權行使購買增額保險選擇的期間死亡，保險人會提供:",o:["自動支付雙倍賠付","不能獲得支付","定期壽險支付","家庭成員可以在30日內提出行使而獲得提升支付"],e:"保證可保利益（可保權利益）在受保保單所有人有權行使增額選擇期間死亡時，保險人會提供定期壽險支付，作為該期間的臨時附加保障，而非雙倍賠付或提升保額。"}},
{p:3,ch:"保险利益附约及其他产品",q:"向受保保单所有人提供周期性增加的残疾收入以抗衡通货膨胀的是",o:["物价指数调整","生活指数调整","增加收入调整","长期残疾利益"],a:1,e:"生活指数调整附约（COLA）按生活费用指数周期性调高残疾收入给付，以抵销通胀对购买力的侵蚀。物价指数调整、增加收入调整非标准术语；长期残疾利益只指给付期限较长，并无自动抗通胀的调升机制。",src:1,tw:{ch:"保險利益附約及其他產品",q:"向受保保單所有人提供週期性增加的殘疾收入以抗衡通貨膨脹的是",o:["物價指數調整","生活指數調整","增加收入調整","長期殘疾利益"],e:"生活指數調整附約（COLA）按生活費用指數週期性調高殘疾收入給付，以抵銷通脹對購買力的侵蝕。物價指數調整、增加收入調整非標準術語；長期殘疾利益只指給付期限較長，並無自動抗通脹的調升機制。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在人寿保单中附有残疾收入保险利益,以下哪项有关陈述是正确的?",o:["每月支付指定金额","支付残疾收入期间,人寿保障将会暂停","身故时于保额中扣除所支付的金额","人寿保额会不断减少"],a:0,e:"残疾收入附约通常按月支付一笔指定金额，为受保人因残疾丧失收入提供经济支持。其余三项均错：该给付为附加利益，不会使基本人寿保障暂停，也不会从身故保额中扣除或令保额递减。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在人壽保單中附有殘疾收入保險利益，以下哪項有關陳述是正確的？",o:["每月支付指定金額","支付殘疾收入期間，人壽保障將會暫停","身故時於保額中扣除所支付的金額","人壽保額會不斷減少"],e:"殘疾收入附約通常按月支付一筆指定金額，為受保人因殘疾喪失收入提供經濟支持。其餘三項均錯：該給付為附加利益，不會使基本人壽保障暫停，也不會從身故保額中扣除或令保額遞減。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在典型的危疾保险利益附约中,受保事件包括以下哪项或哪些?",o:["死亡","严重的身体伤残","一种指明疾病或接受医疗程序","以上各项皆是"],a:2,e:"危疾保险利益附约的受保事件是患上保单指明的疾病或接受指定医疗程序。死亡由寿险基本保障承担，严重身体伤残属意外或残疾保障范畴，故「以上各项皆是」不成立。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在典型的危疾保險利益附約中，受保事件包括以下哪項或哪些？",o:["死亡","嚴重的身體傷殘","一種指明疾病或接受醫療程序","以上各項皆是"],e:"危疾保險利益附約的受保事件是患上保單指明的疾病或接受指定醫療程序。死亡由壽險基本保障承擔，嚴重身體傷殘屬意外或殘疾保障範疇，故「以上各項皆是」不成立。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在同一次意外事故中,被保险人丧失两个肢体,之后引致死亡,如寿险保单附加意外死亡及丧失肢体附 约,保险人会如何作出赔付?",o:["只是保额而已","保额的两倍","保额的三倍","保额的四倍"],a:1,e:"丧失两个肢体者依约获付与保额相等的赔偿，其后因同一意外死亡再获意外死亡保险金，合计为保额两倍。只赔保额低估了赔偿，三倍、四倍则无依据。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在同一次意外事故中，被保險人喪失兩個肢體，之後引致死亡，如壽險保單附加意外死亡及喪失肢體附 約，保險人會如何作出賠付？",o:["只是保額而已","保額的兩倍","保額的三倍","保額的四倍"],e:"喪失兩個肢體者依約獲付與保額相等的賠償，其後因同一意外死亡再獲意外死亡保險金，合計為保額兩倍。只賠保額低估了賠償，三倍、四倍則無依據。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在意外发生后身体丧失多个肢体,随后更因此而死亡,根据意外死亡及丧失肢体的条款,可获得的赔偿 是:",o:["死亡保险金的总数","并不获得任何赔付","相等于死亡保险金再加一倍的赔付金额","相等于死亡保险金再加双倍的赔付金额"],a:2,e:"丧失肢体后因伤势死亡的，先就丧失肢体给付与保额相等的额外赔偿，再加付死亡保险金，故为死亡保险金再加一倍。并非只赔死亡金或分文不赔，也非加双倍。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在意外發生後身體喪失多個肢體，隨後更因此而死亡，根據意外死亡及喪失肢體的條款，可獲得的賠償 是：",o:["死亡保險金的總數","並不獲得任何賠付","相等於死亡保險金再加一倍的賠付金額","相等於死亡保險金再加雙倍的賠付金額"],e:"喪失肢體後因傷勢死亡的，先就喪失肢體給付與保額相等的額外賠償，再加付死亡保險金，故為死亡保險金再加一倍。並非只賠死亡金或分文不賠，也非加雙倍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在意外死亡保险利益有关˹丧失肢体˼的条款内,如果死亡保险金是10万,那受保保单所有人在意外中丧 失甚么,保险人才会给付一笔与死亡赔偿相等的金额? i 丧失双腿 ii 双目失明 iii 丧失一手和一腿 iv 丧失双手",o:["i, iv","i, ii, iv","i, iii, iv","以上都是"],a:3,e:"丧失双腿、双目失明、丧失一手一腿或丧失双手，均属丧失两肢或双目的级别，各可获与死亡赔偿相等的金额。故 i、ii、iii、iv 全对，选「以上都是」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在意外死亡保險利益有關˹喪失肢體的條款內，如果死亡保險金是10萬，那受保保單所有人在意外中喪 ˼ 失甚麼，保險人才會給付一筆與死亡賠償相等的金額? i 喪失雙腿 ii 雙目失明 iii 喪失一手和一腿 iv 喪失雙手",o:["i, iv","i, ii, iv","i, iii, iv","以上都是"],e:"喪失雙腿、雙目失明、喪失一手一腿或喪失雙手，均屬喪失兩肢或雙目的級別，各可獲與死亡賠償相等的金額。故 i、ii、iii、iv 全對，選「以上都是」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在意外死亡及丧失肢体附约中,丧失肢体涉及:",o:["丧失一肢或多个肢体","意外死亡","丧失肢体或视力","较轻伤残"],a:2,e:"该附约中的「丧失肢体」指因意外实际丧失一肢或多肢，或丧失视力（含单目或双目）。意外死亡是另一独立给付项目，较轻伤残另有比例给付，不属「丧失肢体」定义。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在意外死亡及喪失肢體附約中，喪失肢體涉及：",o:["喪失一肢或多個肢體","意外死亡","喪失肢體或視力","較輕傷殘"],e:"該附約中的「喪失肢體」指因意外實際喪失一肢或多肢，或喪失視力（含單目或雙目）。意外死亡是另一獨立給付項目，較輕傷殘另有比例給付，不屬「喪失肢體」定義。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在意外死亡附约中,以下哪项不可以索取赔偿?",o:["被入屋偷窃的贼人杀害","在横过马路时发生交通意外死亡","作为一名乘客而在一次撞机意外中死亡","作为一名舱务员而在一次撞机意外中死亡"],a:3,e:"舱务员属机组人员，其于撞机事故中死亡通常属附约除外责任，故不可索偿。入屋被贼杀害、过马路车祸、作为乘客撞机死亡均属承保的意外死亡。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在意外死亡附約中，以下哪項不可以索取賠償？",o:["被入屋偷竊的賊人殺害","在橫過馬路時發生交通意外死亡","作為一名乘客而在一次撞機意外中死亡","作為一名艙務員而在一次撞機意外中死亡"],e:"艙務員屬機組人員，其於撞機事故中死亡通常屬附約除外責任，故不可索償。入屋被賊殺害、過馬路車禍、作為乘客撞機死亡均屬承保的意外死亡。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在长期护理附约下,保险人要求被保人证明失去某些日常起居活动能力(ADLs),是指:",o:["Activities of Daily Living","Adjustments of Daily Living","Accumulations of Daily Living","Accumulations of Doing List"],a:0,e:"ADLs 即 Activities of Daily Living，指进食、沐浴、走动等日常起居活动能力。其余选项拼写及含义均非标准英文缩写。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在長期護理附約下，保險人要求被保人證明失去某些日常起居活動能力(ADLs),是指：",o:["Activities of Daily Living","Adjustments of Daily Living","Accumulations of Daily Living","Accumulations of Doing List"],e:"ADLs 即 Activities of Daily Living，指進食、沐浴、走動等日常起居活動能力。其餘選項拼寫及含義均非標準英文縮寫。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在附加于人寿保险的意外保险利益附约中,都包含除外责任的条文,以下哪项较可能不属于附约中的除 外责任?",o:["因传染病而死亡","非法入屋盗窃失足导致伤残","自杀不遂导致伤残","因交通意外导致伤残"],a:3,e:"交通意外致伤残是典型的意外事故，通常不在除外责任之列，故可获赔。因传染病死亡属疾病而非意外，非法入屋盗窃及自杀不遂均涉违法行为或自伤，一般为除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在附加於人壽保險的意外保險利益附約中，都包含除外責任的條文，以下哪項較可能不屬於附約中的除 外責任？",o:["因傳染病而死亡","非法入屋盜竊失足導致傷殘","自殺不遂導致傷殘","因交通意外導致傷殘"],e:"交通意外致傷殘是典型的意外事故，通常不在除外責任之列，故可獲賠。因傳染病死亡屬疾病而非意外，非法入屋盜竊及自殺不遂均涉違法行為或自傷，一般為除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"如寿险保单附加意外死亡及丧失肢体附约,死亡必须由意外身体受伤而直接引起,并于该受伤多久内发 生才可获得该赔偿?",o:["24小时","1星期 (或7天)","3个月 (或90天)","1年"],a:3,e:"意外死亡保险利益要求死亡由意外身体受伤直接引起，并须于受伤后一年内发生。24小时、一星期、三个月均过短，不符典型附约所订的指定期间。",src:1,tw:{ch:"保險利益附約及其他產品",q:"如壽險保單附加意外死亡及喪失肢體附約，死亡必須由意外身體受傷而直接引起，並於該受傷多久內發 生才可獲得該賠償？",o:["24小時","1星期 (或7天)","3個月 (或90天)","1年"],e:"意外死亡保險利益要求死亡由意外身體受傷直接引起，並須於受傷後一年內發生。24小時、一星期、三個月均過短，不符典型附約所訂的指定期間。"}},
{p:3,ch:"保险利益附约及其他产品",q:"如果人寿保单受到残疾收入附约约束并且受保生命遭遇残疾,而现正提供收入:",o:["该收入通常以每月形式支付","其基本保障会暂时停止","所支付金额会于死亡保障额扣除","此类保障通常并不设有等候期"],a:0,e:"残疾收入附约的给付通常按月支付，以补充受保人因残疾失去的收入。其基本寿险保障不会暂停，给付亦不从身故保额扣除，且此类保障设有等候期。",src:1,tw:{ch:"保險利益附約及其他產品",q:"如果人壽保單受到殘疾收入附約約束並且受保生命遭遇殘疾，而現正提供收入：",o:["該收入通常以每月形式支付","其基本保障會暫時停止","所支付金額會於死亡保障額扣除","此類保障通常並不設有等候期"],e:"殘疾收入附約的給付通常按月支付，以補充受保人因殘疾失去的收入。其基本壽險保障不會暫停，給付亦不從身故保額扣除，且此類保障設有等候期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"寿险保单中的豁免保费附约之年龄限制范围多属以下那项:",o:["年龄限制在15岁以下","年龄限制在18岁以上","年龄限制在65岁以上","年龄在15至65岁之间"],a:3,e:"豁免保费附约一般将受保年龄限制在15至65岁之间，覆盖主要工作年龄人群。其余选项均不符常规承保年龄范围。",src:1,tw:{ch:"保險利益附約及其他產品",q:"壽險保單中的豁免保費附約之年齡限制範圍多屬以下那項：",o:["年齡限制在15歲以下","年齡限制在18歲以上","年齡限制在65歲以上","年齡在15至65歲之間"],e:"豁免保費附約一般將受保年齡限制在15至65歲之間，覆蓋主要工作年齡人羣。其餘選項均不符常規承保年齡範圍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"寿险保单可能附加一种附约,它向罹患终末疾病,预期寿命只有12个月或更短的被 保险保单所有人,支付预先定下的一部分死亡金。这类附约称为:",o:["提前保额给付","死亡前利益","危疾保险利益","不治附约"],a:2,e:"在罹患终末疾病、预期寿命12个月或更短时预先给付部分死亡金的是危疾保险利益附约。提前保额给付、死亡前利益、不治附约均非准确的标准称谓。",src:1,tw:{ch:"保險利益附約及其他產品",q:"壽險保單可能附加一種附約，它向罹患終末疾病，預期壽命只有12個月或更短的被 保險保單所有人，支付預先定下的一部分死亡金。這類附約稱為：",o:["提前保額給付","死亡前利益","危疾保險利益","不治附約"],e:"在罹患終末疾病、預期壽命12個月或更短時預先給付部分死亡金的是危疾保險利益附約。提前保額給付、死亡前利益、不治附約均非準確的標準稱謂。"}},
{p:3,ch:"保险利益附约及其他产品",q:"就人寿保险的核保,判断一风险之可保性的基本因素是:",o:["保额","受保人年龄","受保人的健康状况","受保人的性别"],a:2,e:"判断风险可否承保的基本因素是受保人的健康状况，它直接决定死亡率与风险高低。保额、年龄、性别会影响费率或承保条件，但非判断可保性的根本因素。",src:1,tw:{ch:"保險利益附約及其他產品",q:"就人壽保險的核保，判斷一風險之可保性的基本因素是：",o:["保額","受保人年齡","受保人的健康狀況","受保人的性別"],e:"判斷風險可否承保的基本因素是受保人的健康狀況，它直接決定死亡率與風險高低。保額、年齡、性別會影響費率或承保條件，但非判斷可保性的根本因素。"}},
{p:3,ch:"保险利益附约及其他产品",q:"尽管死亡并未发生,但保单所列明的全部或部份死亡金仍可支付给被保险保单所有人。此利益称为:",o:["提前支付死亡保险利益","快捷给付保险利益","储蓄保险","死前支付死亡保险利益"],a:0,e:"死亡虽未发生但可预先领取全部或部分死亡金，此即提前支付死亡保险利益（加速死亡给付）。快捷给付、储蓄保险、死前支付均非标准名称。",src:1,tw:{ch:"保險利益附約及其他產品",q:"儘管死亡並未發生，但保單所列明的全部或部份死亡金仍可支付給被保險保單所有人。此利益稱為：",o:["提前支付死亡保險利益","快捷給付保險利益","儲蓄保險","死前支付死亡保險利益"],e:"死亡雖未發生但可預先領取全部或部分死亡金，此即提前支付死亡保險利益（加速死亡給付）。快捷給付、儲蓄保險、死前支付均非標準名稱。"}},
{p:3,ch:"保险利益附约及其他产品",q:"已购买保证可保利益的保单所有人在指定备择日期没有作出增额选择,会:",o:["丧失未来所获保证增额的权利","丧失有关增额的权利","可于任何时间再行使权利","自动行使权利"],a:1,e:"保证可保选择的增额权须在指定备择日期行使，若届时未作选择，即丧失该次的增额权利。此并不影响其余未来备择日期的权利，也非可随时再度行使或自动行使。",src:1,tw:{ch:"保險利益附約及其他產品",q:"已購買保證可保利益的保單所有人在指定備擇日期沒有作出增額選擇，會：",o:["喪失未來所獲保證增額的權利","喪失有關增額的權利","可於任何時間再行使權利","自動行使權利"],e:"保證可保選擇的增額權須在指定備擇日期行使，若屆時未作選擇，即喪失該次的增額權利。此並不影響其餘未來備擇日期的權利，也非可隨時再度行使或自動行使。"}},
{p:3,ch:"保险利益附约及其他产品",q:"当受保保单所有人在接受长期护理期间,保险人通常在保费上作出什么安排?",o:["增加保费","豁免保费","减少保费","利用现金价值缴交保费"],a:1,e:"受保人在接受长期护理期间，保险人通常会豁免其基本计划及相关附约的保费，以减轻其经济负担。不会加收保费，亦非减少保费或以现金价值代缴。",src:1,tw:{ch:"保險利益附約及其他產品",q:"當受保保單所有人在接受長期護理期間，保險人通常在保費上作出什麼安排？",o:["增加保費","豁免保費","減少保費","利用現金價值繳交保費"],e:"受保人在接受長期護理期間，保險人通常會豁免其基本計劃及相關附約的保費，以減輕其經濟負擔。不會加收保費，亦非減少保費或以現金價值代繳。"}},
{p:3,ch:"保险利益附约及其他产品",q:"当得到意外死亡及丧失肢体时,如遭遇意外死亡时:",o:["只能得到基本保额","赔付只限于车祸引致的死亡","可得到基本保障及额外利益","可得到基本保障及双倍额外利益"],a:2,e:"受保人意外死亡时，除寿险基本保额外，还可获得意外死亡附约的额外利益，即基本保障及额外利益。并非只赔基本保额，也不限于车祸，更非双倍额外利益。",src:1,tw:{ch:"保險利益附約及其他產品",q:"當得到意外死亡及喪失肢體時，如遭遇意外死亡時：",o:["只能得到基本保額","賠付只限於車禍引致的死亡","可得到基本保障及額外利益","可得到基本保障及雙倍額外利益"],e:"受保人意外死亡時，除壽險基本保額外，還可獲得意外死亡附約的額外利益，即基本保障及額外利益。並非只賠基本保額，也不限於車禍，更非雙倍額外利益。"}},
{p:3,ch:"保险利益附约及其他产品",q:"当某份适当的附约出现提前支付死亡保险利益索偿时,发现保单有承让人利益存在:",o:["此提前支付死亡保险利益保单不能支付","承让人必须签署一份弃权声明后,有关款项方可支付给受保人","承让人有权获取得该赔偿","这与提前支付死亡保险利益无关"],a:1,e:"若保单存在承让人利益，须先由承让人签署弃权声明，保险人方可把提前支付的死亡保险利益付给受保人。承让人并非当然取得该款，也非与提前给付无关。",src:1,tw:{ch:"保險利益附約及其他產品",q:"當某份適當的附約出現提前支付死亡保險利益索償時，發現保單有承讓人利益存在：",o:["此提前支付死亡保險利益保單不能支付","承讓人必須簽署一份棄權聲明後，有關款項方可支付給受保人","承讓人有權獲取得該賠償","這與提前支付死亡保險利益無關"],e:"若保單存在承讓人利益，須先由承讓人簽署棄權聲明，保險人方可把提前支付的死亡保險利益付給受保人。承讓人並非當然取得該款，也非與提前給付無關。"}},
{p:3,ch:"保险利益附约及其他产品",q:"当购买意外保险单后,受保人因意外死亡或断失二肢时的赔偿会是",o:["死亡与断失二肢的赔偿金额一样","死亡的赔偿金额高于断失二肢","断失二肢的赔偿金额比死亡赔偿为高","不论死亡或断失二肢,两者之赔偿均不能高于寿险金额"],a:0,e:"意外死亡与丧失二肢同属最高级别，均按保额的100%赔偿，故两者金额相同。死亡赔偿不会高于或低于丧失二肢的赔偿。",src:1,tw:{ch:"保險利益附約及其他產品",q:"當購買意外保險單後，受保人因意外死亡或斷失二肢時的賠償會是",o:["死亡與斷失二肢的賠償金額一樣","死亡的賠償金額高於斷失二肢","斷失二肢的賠償金額比死亡賠償為高","不論死亡或斷失二肢，兩者之賠償均不能高於壽險金額"],e:"意外死亡與喪失二肢同屬最高級別，均按保額的100%賠償，故兩者金額相同。死亡賠償不會高於或低於喪失二肢的賠償。"}},
{p:3,ch:"保险利益附约及其他产品",q:"很多保险人除了提供意外死亡及丧失肢体附约外,亦提供经修改的保障,内容是:",o:["丧失一只手指或脚趾就全数赔偿","丧失任何一腿或一臂就赔偿相等于死亡保险金","丧失一肢或一目失明赔偿死亡保险金的一半","以上所有都保障"],a:2,e:"经修改的意外死亡及丧失肢体保障，对丧失一肢或一目失明者给付死亡保险金的一半。丧失一指一趾、一腿一臂按各自比例给付，并非「全数」或「等于死亡保险金」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"很多保險人除了提供意外死亡及喪失肢體附約外，亦提供經修改的保障，內容是：",o:["喪失一隻手指或腳趾就全數賠償","喪失任何一腿或一臂就賠償相等於死亡保險金","喪失一肢或一目失明賠償死亡保險金的一半","以上所有都保障"],e:"經修改的意外死亡及喪失肢體保障，對喪失一肢或一目失明者給付死亡保險金的一半。喪失一指一趾、一腿一臂按各自比例給付，並非「全數」或「等於死亡保險金」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意味着放弃某种形式的法律的权利是指:",o:["附约","豁免","弃权","取消"],a:1,e:"「豁免」（waiver）指权利人自愿放弃某种法律权利，如豁免保费附约即放弃收取保费的权利。附约是附加条款，弃权与豁免含义不同，取消指终止，均不符。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意味着放棄某種形式的法律的權利是指:",o:["附約","豁免","棄權","取消"],e:"「豁免」（waiver）指權利人自願放棄某種法律權利，如豁免保費附約即放棄收取保費的權利。附約是附加條款，棄權與豁免含義不同，取消指終止，均不符。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外保险中,双倍赔偿利益在技术上不适用于人寿保险,因为:",o:["导致意外的原因可能不是不保事项","弥偿只适用于财产保险","此利益不适用于自然死亡","实际上不是弥偿"],a:3,e:"双倍赔偿利益在技术名称上不准确，是因为人寿保险是利益（给付）保单而非弥偿保单，意外死亡额外给付并非损失弥偿。其余说法与该名称不准确无关。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外保險中，雙倍賠償利益在技術上不適用於人壽保險，因為：",o:["導致意外的原因可能不是不保事項","彌償只適用於財產保險","此利益不適用於自然死亡","實際上不是彌償"],e:"雙倍賠償利益在技術名稱上不準確，是因為人壽保險是利益（給付）保單而非彌償保單，意外死亡額外給付並非損失彌償。其餘說法與該名稱不準確無關。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外保险利益的其他利益包括: i 严重烧伤 ii 每周津贴 iii 住院津贴 iv 双倍赔偿",o:["i, ii","ii, iii","i, ii, iii","以上各项皆是"],a:3,e:"意外保险利益除意外死亡及丧失肢体外，尚包括严重烧伤、每周津贴、住院津贴、双倍赔偿等。故 i、ii、iii、iv 皆属额外利益。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外保險利益的其他利益包括： i 嚴重燒傷 ii 每周津貼 iii 住院津貼 iv 雙倍賠償",o:["i, ii","ii, iii","i, ii, iii","以上各項皆是"],e:"意外保險利益除意外死亡及喪失肢體外，尚包括嚴重燒傷、每週津貼、住院津貼、雙倍賠償等。故 i、ii、iii、iv 皆屬額外利益。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外导致死亡,保险人支付一笔与保单保额相等的保险利益称为:",o:["双倍利益附约","双倍赔偿利益","意外红利利益","保额增加利益"],a:1,e:"意外导致死亡时，意外附约再支付一笔与保额相等的利益，连同基本寿险保额合共「双倍」，故该附约利益称为双倍赔偿利益。双倍利益、意外红利、保额增加均非标准叫法。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外導致死亡，保險人支付一筆與保單保額相等的保險利益稱為：",o:["雙倍利益附約","雙倍賠償利益","意外紅利利益","保額增加利益"],e:"意外導致死亡時，意外附約再支付一筆與保額相等的利益，連同基本壽險保額合共「雙倍」，故該附約利益稱為雙倍賠償利益。雙倍利益、意外紅利、保額增加均非標準叫法。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡事故中,以下哪个保险原则较为重要?",o:["近因","弥偿","最高诚信","可保权益"],a:0,e:"判断死亡是否由意外引致并属附约承保范围，须运用近因原则确定致死的最直接有效原因。弥偿、最高诚信、可保权益在意外死亡认定中并非最核心。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡事故中，以下哪個保險原則較為重要?",o:["近因","彌償","最高誠信","可保權益"],e:"判斷死亡是否由意外引致並屬附約承保範圍，須運用近因原則確定致死的最直接有效原因。彌償、最高誠信、可保權益在意外死亡認定中並非最核心。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡保险利益(ADB)被称为双倍赔偿利益(Double Indemnity Benefit), 在这里英文名称技术上并不准确,因为:",o:["弥偿只应用于定期寿险","人寿保险不受弥偿所规则","在正常情况下须额外支付两倍的保险利益","唯有是由意外引致死亡才会赔偿"],a:1,e:"人寿保险不适用弥偿原则，其给付金额以保额为限、与实际损失无关，故用 Indemnity（弥偿）描述意外死亡利益在技术上不准确。其余选项非根本原因。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡保險利益(ADB)被稱為雙倍賠償利益(Double Indemnity Benefit), 在這裡英文名稱技術上並不準確，因為：",o:["彌償只應用於定期壽險","人壽保險不受彌償所規則","在正常情況下須額外支付兩倍的保險利益","唯有是由意外引致死亡才會賠償"],e:"人壽保險不適用彌償原則，其給付金額以保額為限、與實際損失無關，故用 Indemnity（彌償）描述意外死亡利益在技術上不準確。其餘選項非根本原因。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡保险利益,受伤而导致死亡必须在下列的指定时期内发生?",o:["24小时","30天","一年","两年"],a:2,e:"意外死亡保险利益要求死亡于意外受伤后的指定期间内发生，一般为一年。24小时、30天过短，两年过长。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡保險利益，受傷而導致死亡必須在下列的指定時期內發生？",o:["24小時","30天","一年","兩年"],e:"意外死亡保險利益要求死亡於意外受傷後的指定期間內發生，一般為一年。24小時、30天過短，兩年過長。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡保险利益亦称为:",o:["双倍赔偿利益","意外双倍利益","双倍意外利益","额外附加利益"],a:0,e:"意外死亡保险利益（ADB）因在意外死亡时作双倍给付而俗称双倍赔偿利益。意外双倍利益、双倍意外利益、额外附加利益均非标准名称。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡保險利益亦稱為：",o:["雙倍賠償利益","意外雙倍利益","雙倍意外利益","額外附加利益"],e:"意外死亡保險利益（ADB）因在意外死亡時作雙倍給付而俗稱雙倍賠償利益。意外雙倍利益、雙倍意外利益、額外附加利益均非標準名稱。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡保险附约又被称为双倍赔偿利益,但其英文名称Double indemnity Benefit在技术上是不正确的,因为:",o:["有些意外引致的原因是除外责任","Indemnity(弥偿)通常出现在财产保险上","Indemnity是一项弥偿,而该保额是利益保单","自然死亡是不保的"],a:2,e:"该名称在技术上不正确，因 Indemnity（弥偿）适用于财产保险的损失补偿，而人寿保单属利益保单，给付的是约定保额而非损失弥偿。例外原因、自然死亡不保均非命名之错。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡保險附約又被稱為雙倍賠償利益,但其英文名稱Double indemnity Benefit在技術上是不正確的,因為:",o:["有些意外引致的原因是除外責任","Indemnity(彌償)通常出現在財產保險上","Indemnity是一項彌償,而該保額是利益保單","自然死亡是不保的"],e:"該名稱在技術上不正確，因 Indemnity（彌償）適用於財產保險的損失補償，而人壽保單屬利益保單，給付的是約定保額而非損失彌償。例外原因、自然死亡不保均非命名之錯。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及丧失肢体附约中,「丧失肢体」的定义通常指「由手腕/足踝关节或以上完全断离」,然而有 些保险人:",o:["要求断离的部份由肩部或臀部开始","在失去一根手指或脚指的情况下仍会给付有关利益","于有关定义中加入丧失肢体功能的情况","于任何两项不同肢体的残疾给付有关利益"],a:2,e:"在「手腕或足踝关节或以上完全断离」的基础上，部分保险人将丧失肢体功能（如完全丧失活动能力）亦纳入丧失肢体定义。要求肩部臀部断离、给付单指趾损失、任意两肢给付均不符常见做法。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及喪失肢體附約中，「喪失肢體」的定義通常指「由手腕/足踝關節或以上完全斷離」，然而有 些保險人：",o:["要求斷離的部份由肩部或臀部開始","在失去一根手指或腳指的情況下仍會給付有關利益","於有關定義中加入喪失肢體功能的情況","於任何兩項不同肢體的殘疾給付有關利益"],e:"在「手腕或足踝關節或以上完全斷離」的基礎上，部分保險人將喪失肢體功能（如完全喪失活動能力）亦納入喪失肢體定義。要求肩部臀部斷離、給付單指趾損失、任意兩肢給付均不符常見做法。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及丧失肢体附约中,关于丧失肢体,以下哪项正确?",o:["严格限制于肢体的实际丧失","必须包括实际丧失肢体","总是适用於单目失明","包括双目失明"],a:3,e:"丧失肢体的定义不仅限于四肢的实际断离，也包括丧失视力，尤其是双目失明。故「包括双目失明」正确，其余强调「严格限于实际丧失」或「总是单目」的说法错误。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及喪失肢體附約中，關於喪失肢體，以下哪項正確？",o:["嚴格限制於肢體的實際喪失","必須包括實際喪失肢體","總是適用於單目失明","包括雙目失明"],e:"喪失肢體的定義不僅限於四肢的實際斷離，也包括喪失視力，尤其是雙目失明。故「包括雙目失明」正確，其餘強調「嚴格限於實際喪失」或「總是單目」的說法錯誤。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及丧失肢体附约使保险人在受保人意外中丧失肢体时给付赔偿,提供经修改后的保障,则需:",o:["丧失一肢或一目失明,提供赔偿为保额双倍","丧失一手指或脚指,提供赔偿为保额全数","丧失一脚部或臀部,提供赔偿为保额某个百份比","丧失一肢或一目失明,提供赔偿为保额的一半"],a:3,e:"经修改的保障下，丧失一肢或一目失明给付保额的一半。双倍、全数或按脚部臀部计百分比均不符修改后的给付表。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及喪失肢體附約使保險人在受保人意外中喪失肢體時給付賠償，提供經修改後的保障，則需：",o:["喪失一肢或一目失明，提供賠償為保額雙倍","喪失一手指或腳指，提供賠償為保額全數","喪失一腳部或臀部，提供賠償為保額某個百份比","喪失一肢或一目失明，提供賠償為保額的一半"],e:"經修改的保障下，喪失一肢或一目失明給付保額的一半。雙倍、全數或按腳部臀部計百分比均不符修改後的給付表。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及丧失肢体附约内之意外死亡保险金通常:",o:["是保单保额的50%","是保单保额的100%","于意外死亡时支付,以代替保单保额","只涉及汽车意外死亡的情况下支付"],a:1,e:"意外死亡保险金通常等于保单保额的100%，即在寿险保额之外额外再赔一倍，而非仅50%或只涉汽车意外，也非代替保单保额。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及喪失肢體附約內之意外死亡保險金通常：",o:["是保單保額的50%","是保單保額的100%","於意外死亡時支付，以代替保單保額","只涉及汽車意外死亡的情況下支付"],e:"意外死亡保險金通常等於保單保額的100%，即在壽險保額之外額外再賠一倍，而非僅50%或只涉汽車意外，也非代替保單保額。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及丧失肢体附约受保生命在意外事故中可得到一笔与死亡保险金相等的赔偿金,经修改后受保 人可收取50%保险金若意外事故导致:",o:["丧失一腿","丧失一目","丧失一手","以上皆是"],a:3,e:"修改后的附约对丧失一腿、一目或一手均给付50%保险金。故三者皆可获半额，选「以上皆是」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及喪失肢體附約受保生命在意外事故中可得到一筆與死亡保險金相等的賠償金，經修改後受保 人可收取50%保險金若意外事故導致：",o:["喪失一腿","喪失一目","喪失一手","以上皆是"],e:"修改後的附約對喪失一腿、一目或一手均給付50%保險金。故三者皆可獲半額，選「以上皆是」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及意外丧失肢体中的意外死亡保险利益保额为:",o:["保单保额的50%","保单保额的100%","意外死亡时支付以代替保单保额","只涉及交通意外中意外死亡时支付"],a:1,e:"意外死亡保险利益保额为保单保额的100%，于意外死亡时在基本寿险保额之外加付，并非代替保单保额或只限交通意外。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及意外喪失肢體中的意外死亡保險利益保額為：",o:["保單保額的50%","保單保額的100%","意外死亡時支付以代替保單保額","只涉及交通意外中意外死亡時支付"],e:"意外死亡保險利益保額為保單保額的100%，於意外死亡時在基本壽險保額之外加付，並非代替保單保額或只限交通意外。"}},
{p:3,ch:"保险利益附约及其他产品",q:"接受长期护理的受保保单所有人,可获预先获支付死亡保险金,但保险人要求出示受保保单所有人的医 学证据,保险人通常需要医生证明?",o:["永久完全残疾","预期寿命不多于两年","失去某些日常起居活动能力","生理及精神不能活动(植物人)"],a:2,e:"长期护理预先支付死亡金前，保险人通常要求医生证明受保人已失去某些日常起居活动能力（ADLs）。永久残疾、预期寿命、植物人并非此处要求的医学证据。",src:1,tw:{ch:"保險利益附約及其他產品",q:"接受長期護理的受保保單所有人，可獲預先獲支付死亡保險金，但保險人要求出示受保保單所有人的醫 學證據，保險人通常需要醫生證明？",o:["永久完全殘疾","預期壽命不多於兩年","失去某些日常起居活動能力","生理及精神不能活動(植物人)"],e:"長期護理預先支付死亡金前，保險人通常要求醫生證明受保人已失去某些日常起居活動能力（ADLs）。永久殘疾、預期壽命、植物人並非此處要求的醫學證據。"}},
{p:3,ch:"保险利益附约及其他产品",q:"提供某些附约或作出某些特定的规定是指:",o:["人寿保险","附约","等候期","指定动作"],a:1,e:"「附约」是加附于保单、提供某种额外利益或作出特定规定的条文。人寿保险、等候期、指定动作均不合题意。",src:1,tw:{ch:"保險利益附約及其他產品",q:"提供某些附約或作出某些特定的規定是指：",o:["人壽保險","附約","等候期","指定動作"],e:"「附約」是加附於保單、提供某種額外利益或作出特定規定的條文。人壽保險、等候期、指定動作均不合題意。"}},
{p:3,ch:"保险利益附约及其他产品",q:"提前支付死亡保险利益中的长期护理,通常支付利益之前,有一个为期90日的时间,称为:",o:["不受保期","等候期","保险金支付期","延期保单限制"],a:1,e:"长期护理利益给付前90日的等待期间称为等候期（免赔期），而非不受保期、保险金支付期或延期保单限制。",src:1,tw:{ch:"保險利益附約及其他產品",q:"提前支付死亡保險利益中的長期護理，通常支付利益之前，有一個為期90日的時間，稱為：",o:["不受保期","等候期","保險金支付期","延期保單限制"],e:"長期護理利益給付前90日的等待期間稱為等候期（免賠期），而非不受保期、保險金支付期或延期保單限制。"}},
{p:3,ch:"保险利益附约及其他产品",q:"提前支付死亡保险利益又被称为:",o:["生前支付保险利益","死前支付死亡保险利益","快捷支付保险利益","支付保险利益"],a:0,e:"提前支付死亡保险利益因使受保人于生前即可取得死亡金，又称生前支付保险利益。死前支付、快捷支付、支付保险利益均非标准称谓。",src:1,tw:{ch:"保險利益附約及其他產品",q:"提前支付死亡保險利益又被稱為：",o:["生前支付保險利益","死前支付死亡保險利益","快捷支付保險利益","支付保險利益"],e:"提前支付死亡保險利益因使受保人於生前即可取得死亡金，又稱生前支付保險利益。死前支付、快捷支付、支付保險利益均非標準稱謂。"}},
{p:3,ch:"保险利益附约及其他产品",q:"提前支付死亡保险利益是可预先支付死亡保险金的一项附约,以下哪种情况可行使此权利﹖",o:["可于任何时间行使","保单生效2年后可行使","在极度悲伤的生命受威胁情况下可行使","以上各项皆是"],a:2,e:"该附约仅在受保人处于极度悲伤、生命受威胁或终末等特定严重情况下方可行使。并非任何时候或保单生效满两年后即可任意行使。",src:1,tw:{ch:"保險利益附約及其他產品",q:"提前支付死亡保險利益是可預先支付死亡保險金的一項附約，以下哪種情況可行使此權利﹖",o:["可於任何時間行使","保單生效2年後可行使","在極度悲傷的生命受威脅情況下可行使","以上各項皆是"],e:"該附約僅在受保人處於極度悲傷、生命受威脅或終末等特定嚴重情況下方可行使。並非任何時候或保單生效滿兩年後即可任意行使。"}},
{p:3,ch:"保险利益附约及其他产品",q:"支付残疾收入保障利益,其收入保险利益:",o:["于最后死亡保险利益中扣除","不会于最后死亡保险利益中扣除","于保单未来红利/分红扣除","是一个保单贷款并偿还保单保费"],a:1,e:"残疾收入附约给付的是额外收入，不会从最终的死亡保险利益中扣除，也不以红利或保单贷款方式冲抵保费。故此利益是独立加付。",src:1,tw:{ch:"保險利益附約及其他產品",q:"支付殘疾收入保障利益，其收入保險利益：",o:["於最後死亡保險利益中扣除","不會於最後死亡保險利益中扣除","於保單未來紅利/分紅扣除","是一個保單貸款並償還保單保費"],e:"殘疾收入附約給付的是額外收入，不會從最終的死亡保險利益中扣除，也不以紅利或保單貸款方式衝抵保費。故此利益是獨立加付。"}},
{p:3,ch:"保险利益附约及其他产品",q:"有时候,保单会以利益给付表的形式加入意外保险利益,列明各种伤残的情况及赔偿的金额。如果意外 死亡10万美金,丧失两肢的保险利益为:",o:["10万美金","5万美金","20万美金","50万美金"],a:0,e:"丧失两肢属最高伤残等级，给付与意外死亡保额相等的10万美金，而非5万、20万或50万。",src:1,tw:{ch:"保險利益附約及其他產品",q:"有時候，保單會以利益給付表的形式加入意外保險利益，列明各種傷殘的情況及賠償的金額。如果意外 死亡10萬美金，喪失兩肢的保險利益為：",o:["10萬美金","5萬美金","20萬美金","50萬美金"],e:"喪失兩肢屬最高傷殘等級，給付與意外死亡保額相等的10萬美金，而非5萬、20萬或50萬。"}},
{p:3,ch:"保险利益附约及其他产品",q:"有部份保险人会在保单中加入条文处理:受保保单所有人根据保证可保选择附约行使权利购买增额保险 前死亡的情况。有关处理的形式是:",o:["在有权行使可保权利益期间,自动提供定期寿险","自动将不分红保单转为分红保单","在有权行使可保权利益前死亡,便可得双倍补偿利益","自动增加可允许最大的保额,并在日后享有可以取消的权利"],a:0,e:"若受保人在行使保证可保增额权前死亡，部分保单会在其有权增额期间自动提供相应定期寿险，以保障该预期增额。其余转换分红、双倍补偿、事后可取消等做法并非标准处理。",src:1,tw:{ch:"保險利益附約及其他產品",q:"有部份保險人會在保單中加入條文處理：受保保單所有人根據保證可保選擇附約行使權利購買增額保險 前死亡的情況。有關處理的形式是：",o:["在有權行使可保權利益期間，自動提供定期壽險","自動將不分紅保單轉為分紅保單","在有權行使可保權利益前死亡，便可得雙倍補償利益","自動增加可允許最大的保額，並在日後享有可以取消的權利"],e:"若受保人在行使保證可保增額權前死亡，部分保單會在其有權增額期間自動提供相應定期壽險，以保障該預期增額。其餘轉換分紅、雙倍補償、事後可取消等做法並非標準處理。"}},
{p:3,ch:"保险利益附约及其他产品",q:"某人因一宗严重的交通意外而死亡。初时,伤势只是失去两个肢体,但该受害人一星期后因伤重而死亡 ,如果他的人寿保单加有意外死亡及丧失肢体附约,保单将会支付:",o:["只有保额","保额的2倍","保额的3倍","保额的4倍"],a:1,e:"丧失两个肢体先给付与保额相等的赔偿，其后因同一意外伤重死亡再获意外死亡保险金，故合计为保额两倍，而非仅保额或三倍四倍。",src:1,tw:{ch:"保險利益附約及其他產品",q:"某人因一宗嚴重的交通意外而死亡。初時，傷勢只是失去兩個肢體，但該受害人一星期後因傷重而死亡 ，如果他的人壽保單加有意外死亡及喪失肢體附約，保單將會支付：",o:["只有保額","保額的2倍","保額的3倍","保額的4倍"],e:"喪失兩個肢體先給付與保額相等的賠償，其後因同一意外傷重死亡再獲意外死亡保險金，故合計為保額兩倍，而非僅保額或三倍四倍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据《医疗保险业务指引》,以下哪一项描述是正确的?",o:["医疗保险业务指引 具有法律效力,违反指引会导致法律诉讼。","医疗保险业务指引 不具法律效力,但不遵从可能影响保监局对相关人士的评估。","医疗保险业务指引 仅适用于个人医疗保险业务,不包括团体业务。","医疗保险业务指引 是附属法例,必须遵从。"],a:1,e:"《医疗保险业务指引》并非法例，无法律强制力，但保险业监管局评估相关人士操守时会参考其是否遵从。故「不具法律效力但影响评估」正确，而非附属法例或仅适用个人业务。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據《醫療保險業務指引》，以下哪一項描述是正確的？",o:["醫療保險業務指引 具有法律效力，違反指引會導致法律訴訟。","醫療保險業務指引 不具法律效力，但不遵從可能影響保監局對相關人士的評估。","醫療保險業務指引 僅適用於個人醫療保險業務，不包括團體業務。","醫療保險業務指引 是附屬法例，必須遵從。"],e:"《醫療保險業務指引》並非法例，無法律強制力，但保險業監管局評估相關人士操守時會參考其是否遵從。故「不具法律效力但影響評估」正確，而非附屬法例或僅適用個人業務。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡保险利益,以下哪项死因可索偿?",o:["因伤心过度而自杀死亡","因打劫银行被警员以枪击毙","小型飞机撞机事故,当时正进行飞行训练","购票乘客于交通车祸中丧身"],a:3,e:"购票乘客在车祸中身亡属正常意外死亡，可获赔。伤心自杀、抢劫银行被击毙、进行飞行训练均涉自杀或危险违法活动，属除外或不可保。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡保險利益，以下哪項死因可索償？",o:["因傷心過度而自殺死亡","因打劫銀行被警員以槍擊斃","小型飛機撞機事故，當時正進行飛行訓練","購票乘客於交通車禍中喪身"],e:"購票乘客在車禍中身亡屬正常意外死亡，可獲賠。傷心自殺、搶劫銀行被擊斃、進行飛行訓練均涉自殺或危險違法活動，屬除外或不可保。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡保险利益附约,下列哪项导致死亡的原因可产生一项有效的索偿?",o:["受保保单所有人在情绪极度低落的情况下自杀","打算抢劫银行时被警方射杀","发生撞机意外时,受保保单所有人正进行飞行训练","发生撞机意外时,受保保单所有人是一名购票的普通乘客"],a:3,e:"撞机事故中作为购票普通乘客死亡属承保的意外。情绪低落自杀、抢劫银行被射杀、进行飞行训练均因自杀、违法或危险职业活动而不赔。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡保險利益附約，下列哪項導致死亡的原因可產生一項有效的索償？",o:["受保保單所有人在情緒極度低落的情況下自殺","打算搶劫銀行時被警方射殺","發生撞機意外時，受保保單所有人正進行飛行訓練","發生撞機意外時，受保保單所有人是一名購票的普通乘客"],e:"撞機事故中作為購票普通乘客死亡屬承保的意外。情緒低落自殺、搶劫銀行被射殺、進行飛行訓練均因自殺、違法或危險職業活動而不賠。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡保险利益附约支付利益,以下哪项属保单定义的意外死亡? i 死亡发生于严重交通事故 ii 醉酒驾车发生意外 iii 自杀 (保单生效四年后) iv 入屋行劫被屋主枪杀",o:["只有i","只有iii","i, ii","iii, iv"],a:0,e:"严重交通事故死亡为典型意外，属承保范围。醉酒驾车、自杀、入屋行劫被屋主枪杀分别涉违法行为、自杀或违法活动，均不符意外死亡定义，故只有 i 正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡保險利益附約支付利益，以下哪項屬保單定義的意外死亡？ i 死亡發生於嚴重交通事故 ii 醉酒駕車發生意外 iii 自殺 (保單生效四年後) iv 入屋行劫被屋主槍殺",o:["只有i","只有iii","i, ii","iii, iv"],e:"嚴重交通事故死亡為典型意外，屬承保範圍。醉酒駕車、自殺、入屋行劫被屋主槍殺分別涉違法行為、自殺或違法活動，均不符意外死亡定義，故只有 i 正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡保险利益附约支付利益的先决条件是,有关的死亡必须是意外发生后的一段指定期间内出 现。该指定时间通常是:",o:["二十四小时","一星期 (有时以七天表示)","三个月 (有时以九十天表示)","一年"],a:3,e:"意外死亡保险利益的先决条件是死亡须于意外发生后指定期间内出现，通常为一年。二十四小时、一星期、三个月均不符常见规定。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡保險利益附約支付利益的先決條件是，有關的死亡必須是意外發生後的一段指定期間內出 現。該指定時間通常是：",o:["二十四小時","一星期 (有時以七天表示)","三個月 (有時以九十天表示)","一年"],e:"意外死亡保險利益的先決條件是死亡須於意外發生後指定期間內出現，通常為一年。二十四小時、一星期、三個月均不符常見規定。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡保险利益附约支付利益的准则,死亡必须:",o:["意外受伤后一段指定期间内发生","于四十八小时内发生","在受保保单所有人完全昏迷时发生","以上各项皆是"],a:0,e:"该附约要求死亡在意外受伤后的一段指定期间内发生，而非固定四十八小时或须在完全昏迷时，故以「指定期间」之说为准。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡保險利益附約支付利益的準則，死亡必須：",o:["意外受傷後一段指定期間內發生","於四十八小時內發生","在受保保單所有人完全昏迷時發生","以上各項皆是"],e:"該附約要求死亡在意外受傷後的一段指定期間內發生，而非固定四十八小時或須在完全昏迷時，故以「指定期間」之說為準。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡及丧失肢体附约,在以下哪项原因导致死亡的情况下,才得到意外死亡保险利益?",o:["任何原因","意外身体受伤","自杀以外一切原因","谋杀以外一切原因"],a:1,e:"获意外死亡保险利益的唯一前提是死亡由意外身体受伤直接引起，而非「任何原因」，也非自杀以外或谋杀以外的一切原因。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡及喪失肢體附約，在以下哪項原因導致死亡的情況下，才得到意外死亡保險利益？",o:["任何原因","意外身體受傷","自殺以外一切原因","謀殺以外一切原因"],e:"獲意外死亡保險利益的唯一前提是死亡由意外身體受傷直接引起，而非「任何原因」，也非自殺以外或謀殺以外的一切原因。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡及丧失肢体附约中,丧失肢体的含义是指:",o:["丧失肢体或视力","丧失一个或多个肢体(四肢)","肢体必须完全断离","严格限制于肢体的实际丧失"],a:0,e:"「丧失肢体」在此附约中指丧失一个或多个肢体，或丧失视力，范围比单纯四肢断离为广。其余选项过于狭窄或表述不全。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡及喪失肢體附約中，喪失肢體的含義是指：",o:["喪失肢體或視力","喪失一個或多個肢體（四肢）","肢體必須完全斷離","嚴格限制於肢體的實際喪失"],e:"「喪失肢體」在此附約中指喪失一個或多個肢體，或喪失視力，範圍比單純四肢斷離為廣。其餘選項過於狹窄或表述不全。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据提前支付死亡保险利益条款,在某些严重的情况下,纵使死亡并未发生,保单所列明的死亡金是可 以支付给保单所有人,但:",o:["受益人/承让人必须签署弃权声明","受益人同样可以取回所有索偿","受益人如果在受保人死后两年内便可获取所有索偿","受益人只可取回保费"],a:0,e:"提前支付死亡金时会减少未来可付给受益人的金额，故须先由受益人（或承让人）签署弃权声明方可支付。受益人不能同时取回全部索偿，也非只退回保费。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據提前支付死亡保險利益條款，在某些嚴重的情況下，縱使死亡並未發生，保單所列明的死亡金是可 以支付給保單所有人，但：",o:["受益人/承讓人必須簽署棄權聲明","受益人同樣可以取回所有索償","受益人如果在受保人死後兩年內便可獲取所有索償","受益人只可取回保費"],e:"提前支付死亡金時會減少未來可付給受益人的金額，故須先由受益人（或承讓人）簽署棄權聲明方可支付。受益人不能同時取回全部索償，也非只退回保費。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据残疾收入附约条款,「完全残疾」是指受保保单所有人没有能力履行其本身固定职业的主要任务:",o:["而已","或其他任何职业的基本任务","或不能从事任何按照其以往所受教育、训练及经验在合理程度上胜任的职业","或其他最少提供相同薪金的职业的基本任务"],a:2,e:"「完全残疾」的标准定义是：无法履行本身固定职业的主要任务，或无法从事任何按以往教育、训练及经验可合理胜任的职业。其余表述不完整或不准确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據殘疾收入附約條款，「完全殘疾」是指受保保單所有人沒有能力履行其本身固定職業的主要任務：",o:["而已","或其他任何職業的基本任務","或不能從事任何按照其以往所受教育、訓練及經驗在合理程度上勝任的職業","或其他最少提供相同薪金的職業的基本任務"],e:"「完全殘疾」的標準定義是：無法履行本身固定職業的主要任務，或無法從事任何按以往教育、訓練及經驗可合理勝任的職業。其餘表述不完整或不準確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据豁免保费附加利益,如受保人伤残时在「等候期」之后仍然持续,有些保险人会退还「等候期」内 缴付的保费。「等候期」实际上是:",o:["起赔期限","时间性超赔额","保单限额","延期保单利益"],a:0,e:"豁免保费附约的「等候期」具有起赔期限的性质，伤残持续超过该期间才豁免保费，故有些保险人会退回等候期内已缴保费。时间性超赔额、保单限额、延期利益均不符。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據豁免保費附加利益，如受保人傷殘時在「等候期」之後仍然持續，有些保險人會退還「等候期」內 繳付的保費。「等候期」實際上是：",o:["起賠期限","時間性超賠額","保單限額","延期保單利益"],e:"豁免保費附約的「等候期」具有起賠期限的性質，傷殘持續超過該期間才豁免保費，故有些保險人會退回等候期內已繳保費。時間性超賠額、保單限額、延期利益均不符。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾保险利益附约中的豁免保费的等候期为:",o:["30天","90天","3或6个月","一年"],a:2,e:"豁免保费附约的等候期一般为3或6个月，而非30天、90天或一年。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾保險利益附約中的豁免保費的等候期為：",o:["30天","90天","3或6個月","一年"],e:"豁免保費附約的等候期一般為3或6個月，而非30天、90天或一年。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入保险利益附约具有等候期,时间为:",o:["通常三个月","一个月至六个月","不少于六个月","三个月至六个月(与豁免保费附约相似)"],a:1,e:"残疾收入保险利益附约的等候期通常为一个月至六个月不等。并非固定三个月、不少于六个月或仅三至六个月。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入保險利益附約具有等候期，時間為：",o:["通常三個月","一個月至六個月","不少於六個月","三個月至六個月(與豁免保費附約相似)"],e:"殘疾收入保險利益附約的等候期通常為一個月至六個月不等。並非固定三個月、不少於六個月或僅三至六個月。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入保险利益附约可附加于:",o:["只是终身寿险保单","只是储蓄寿险保单","只是定期寿险保单","事实是可附加于任何长期寿险保单"],a:3,e:"残疾收入附约无保单类型限制，可附加于任何长期寿险保单，而非只限终身、储蓄或定期寿险。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入保險利益附約可附加於：",o:["只是終身壽險保單","只是儲蓄壽險保單","只是定期壽險保單","事實是可附加於任何長期壽險保單"],e:"殘疾收入附約無保單類型限制，可附加於任何長期壽險保單，而非只限終身、儲蓄或定期壽險。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入保险利益附约有一个等候期,该等候期:",o:["总是3个月","1个月至6个月不等","持续时间不少于6个月","由3个月至6个月不等 (跟豁免保费附约一样)"],a:1,e:"残疾收入附约的等候期通常为一至六个月不等，并非固定三个月或不少于六个月。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入保險利益附約有一個等候期，該等候期：",o:["總是3個月","1個月至6個月不等","持續時間不少於6個月","由3個月至6個月不等 (跟豁免保費附約一樣)"],e:"殘疾收入附約的等候期通常為一至六個月不等，並非固定三個月或不少於六個月。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入利益的赔付形式是:",o:["每月","每年","保单年度完结时支付","伤残完结时支付"],a:0,e:"残疾收入利益的赔付形式是每月定期支付，以替代受保人因残疾失去的经常性收入。按年、于保单年度结束或伤残结束才付均不符其月付设计。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入利益的賠付形式是:",o:["每月","每年","保單年度完結時支付","傷殘完結時支付"],e:"殘疾收入利益的賠付形式是每月定期支付，以替代受保人因殘疾失去的經常性收入。按年、於保單年度結束或傷殘結束才付均不符其月付設計。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入附约受除外责任限制,以下哪些是有关的描述?",o:["投保的年龄限制","缴费模式自动转为月缴","从事违法活动的伤残","以上各项皆是"],a:2,e:"残疾收入附约通常将从事违法活动所致的伤残列为除外责任。投保年龄限制、缴费模式自动转月付并非其除外责任。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入附約受除外責任限制，以下哪些是有關的描述?",o:["投保的年齡限制","繳費模式自動轉為月繳","從事違法活動的傷殘","以上各項皆是"],e:"殘疾收入附約通常將從事違法活動所致的傷殘列為除外責任。投保年齡限制、繳費模式自動轉月付並非其除外責任。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入附约的等候期一般为:",o:["1个月","3-6个月不等","1-6个月不等","3个月 (即90天)"],a:2,e:"残疾收入附约的等候期一般为1至6个月不等，而非固定1个月、3至6个月或90天。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入附約的等候期一般為：",o:["1個月","3-6個月不等","1-6個月不等","3個月 (即90天)"],e:"殘疾收入附約的等候期一般為1至6個月不等，而非固定1個月、3至6個月或90天。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾豁免保费可附加以下哪种类型的寿险?",o:["事实是可附加于任何长期寿险保单","只是定期寿险保单","只是储蓄寿险保单","只是终身寿险保单"],a:0,e:"残疾豁免保费附约可附加于任何长期寿险保单，无类型限制，并非只限定期、储蓄或终身寿险。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾豁免保費可附加以下哪種類型的壽險?",o:["事實是可附加於任何長期壽險保單","只是定期壽險保單","只是儲蓄壽險保單","只是終身壽險保單"],e:"殘疾豁免保費附約可附加於任何長期壽險保單，無類型限制，並非只限定期、儲蓄或終身壽險。"}},
{p:3,ch:"保险利益附约及其他产品",q:"汤姆是一名纳税人,在自愿医保计划下,他购买了四份保单,包括保障自己、妻子、女儿及儿子。他以 合资格缴付保费,可以享有新俸税及个人入息课税的税务扣除。他可获税务扣除的款额是多少?",o:["8,000","16,000","24,000","32,000"],a:3,e:"自愿医保税务扣除以每名受保人每年8,000元为上限，且可同时为多名指定亲属投保。汤姆为本人、妻子、女儿及儿子共四人投保，可扣 4×8,000＝32,000元。",src:1,tw:{ch:"保險利益附約及其他產品",q:"湯姆是一名納稅人，在自願醫保計劃下，他購買了四份保單，包括保障自己、妻子、女兒及兒子。他以 合資格繳付保費，可以享有新俸稅及個人入息課稅的稅務扣除。他可獲稅務扣除的款額是多少?",o:["8,000","16,000","24,000","32,000"],e:"自願醫保税務扣除以每名受保人每年8,000元為上限，且可同時為多名指定親屬投保。湯姆為本人、妻子、女兒及兒子共四人投保，可扣 4×8,000＝32,000元。"}},
{p:3,ch:"保险利益附约及其他产品",q:"现行有些保单被称为(GIO)的条文所规限,甚么是GIO?",o:["授权保险选择 (Granted Insurance Option)","全能保险选择 (General Insurance Options)","保证保险选择 (Guaranteed Insurance Option)","保证可保选择 (Guaranteed Insurability Option)"],a:3,e:"GIO 即 Guaranteed Insurability Option（保证可保选择），允许在指定日期免提供可保性证明加购保额。授权、全能、保证保险选择均非正确全称。",src:1,tw:{ch:"保險利益附約及其他產品",q:"現行有些保單被稱為(GIO)的條文所規限，甚麼是GIO？",o:["授權保險選擇 (Granted Insurance Option)","全能保險選擇 (General Insurance Options)","保證保險選擇 (Guaranteed Insurance Option)","保證可保選擇 (Guaranteed Insurability Option)"],e:"GIO 即 Guaranteed Insurability Option（保證可保選擇），允許在指定日期免提供可保性證明加購保額。授權、全能、保證保險選擇均非正確全稱。"}},
{p:3,ch:"保险利益附约及其他产品",q:"生活指数调整附约的作用是:",o:["对抗经济周期的影响","对抗通胀和通缩所带来的影响","当保险公司盈利下降时,作为补充红利","以上所有答案皆不正确"],a:3,e:"生活指数调整附约的作用是使保障随生活费用指数提高以维持购买力、对抗通胀，并非对抗经济周期、对抗通胀兼通缩或作为补充红利，故所列选项皆不正确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"生活指數調整附約的作用是:",o:["對抗經濟週期的影響","對抗通脹和通縮所帶來的影響","當保險公司盈利下降時，作為補充紅利","以上所有答案皆不正確"],e:"生活指數調整附約的作用是使保障隨生活費用指數提高以維持購買力、對抗通脹，並非對抗經濟週期、對抗通脹兼通縮或作為補充紅利，故所列選項皆不正確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"由于通货膨胀的关系,受保保单所有人担心保额会受影响,他可以怎办?",o:["购买一份与通货膨胀挂钩的保险计划","购买附有保证可保权益的保险计划","购买分红保单以加大将来的保障","预先购买高保障的保险计划"],a:0,e:"为抵御通胀对保额的侵蚀，可购买与通胀挂钩（如生活指数调整附约）的保险计划，使保额随指数自动调升。保证可保、分红、预先买高保额均非直接抗通胀手段。",src:1,tw:{ch:"保險利益附約及其他產品",q:"由於通貨膨脹的關係，受保保單所有人擔心保額會受影響，他可以怎辦？",o:["購買一份與通貨膨脹掛鈎的保險計劃","購買附有保證可保權益的保險計劃","購買分紅保單以加大將來的保障","預先購買高保障的保險計劃"],e:"為抵禦通脹對保額的侵蝕，可購買與通脹掛鈎（如生活指數調整附約）的保險計劃，使保額隨指數自動調升。保證可保、分紅、預先買高保額均非直接抗通脹手段。"}},
{p:3,ch:"保险利益附约及其他产品",q:"监察进行医疗保险业务有关受规管的对象是?",o:["保险代理人","保险经纪","保险代理机构","以上皆是"],a:3,e:"医疗保险业务指引的规管对象包括保险代理人、保险经纪及保险代理机构等持牌或受规管中介，故以上皆是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"監察進行醫療保險業務有關受規管的對象是?",o:["保險代理人","保險經紀","保險代理機構","以上皆是"],e:"醫療保險業務指引的規管對象包括保險代理人、保險經紀及保險代理機構等持牌或受規管中介，故以上皆是。"}},
{p:3,ch:"保险利益附约及其他产品",q:"自愿医保提供什么好处?",o:["提升个人住院保险的吸引力,为愿意及有能力使用私营医疗服务的香港居民提供一个额外的选择","提升个人住院保险的质素及透明度,为愿意及有能力使用私营医疗服务的香港居民提供一个额外的选择","提升个人住院保险的质素及透明度,为愿意及有能力使用私营医疗服务的消费者提供一个额外的选择","提升个人住院保险的吸引力及透明度,为愿意及有能力使用私营医疗服务的香港居民提供一个额外的选 择"],a:2,e:"自愿医保旨在提升个人住院保险的质素与透明度，为愿意及有能力使用私营医疗服务的消费者提供额外选择。以「香港居民」或「吸引力」等字眼表述均不够准确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"自願醫保提供什麼好處？",o:["提升個人住院保險的吸引力，為願意及有能力使用私營醫療服務的香港居民提供一個額外的選擇","提升個人住院保險的質素及透明度，為願意及有能力使用私營醫療服務的香港居民提供一個額外的選擇","提升個人住院保險的質素及透明度，為願意及有能力使用私營醫療服務的消費者提供一個額外的選擇","提升個人住院保險的吸引力及透明度，為願意及有能力使用私營醫療服務的香港居民提供一個額外的選 擇"],e:"自願醫保旨在提升個人住院保險的質素與透明度，為願意及有能力使用私營醫療服務的消費者提供額外選擇。以「香港居民」或「吸引力」等字眼表述均不夠準確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"自愿医保计划(简称「自愿医保」)是由以下哪个机构所推行的政策措施?",o:["食物及衞生局","保监局","医管局","税务局"],a:0,e:"自愿医保计划是由食物及卫生局推行的政策措施，并由保监局规管相关保险产品。医管局、税务局并非推行机构。",src:1,tw:{ch:"保險利益附約及其他產品",q:"自願醫保計劃（簡稱「自願醫保」）是由以下哪個機構所推行的政策措施？",o:["食物及衞生局","保監局","醫管局","稅務局"],e:"自願醫保計劃是由食物及衞生局推行的政策措施，並由保監局規管相關保險產品。醫管局、税務局並非推行機構。"}},
{p:3,ch:"保险利益附约及其他产品",q:"自愿医保计划对购买人士有什么好处?",o:["为没有能力使用私营医疗服务的消费者提供一个额外的选择","为雇主没有提供雇员福利提供额外的保险计划","提升个人住院保险的质素和透明度并为愿意及有能力使用私营医疗服务的消费者提供一个额外的选择","为低收入人士提供使用私营医疗服务"],a:2,e:"自愿医保为愿意及有能力使用私营医疗服务的消费者提供额外选择，同时提升个人住院保险的质素与透明度。并非专为无力使用者、无雇员福利者或低收入人士而设。",src:1,tw:{ch:"保險利益附約及其他產品",q:"自願醫保計劃對購買人士有什麼好處?",o:["為沒有能力使用私營醫療服務的消費者提供一個額外的選擇","為僱主沒有提供僱員福利提供額外的保險計劃","提升個人住院保險的質素和透明度並為願意及有能力使用私營醫療服務的消費者提供一個額外的選擇","為低收入人士提供使用私營醫療服務"],e:"自願醫保為願意及有能力使用私營醫療服務的消費者提供額外選擇，同時提升個人住院保險的質素與透明度。並非專為無力使用者、無僱員福利者或低收入人士而設。"}},
{p:3,ch:"保险利益附约及其他产品",q:"若保险保单附加上双倍赔偿利益,它的补偿是以什么形式支付?",o:["双倍红利赔偿","双倍保额赔偿","双倍已缴保费总额赔偿","以上各项皆不是"],a:1,e:"双倍赔偿利益在意外死亡时，于基本保额外再给付一笔相等金额，即相当于双倍保额的赔偿。并非双倍红利或双倍已缴保费。",src:1,tw:{ch:"保險利益附約及其他產品",q:"若保險保單附加上雙倍賠償利益，它的補償是以什麼形式支付？",o:["雙倍紅利賠償","雙倍保額賠償","雙倍已繳保費總額賠償","以上各項皆不是"],e:"雙倍賠償利益在意外死亡時，於基本保額外再給付一筆相等金額，即相當於雙倍保額的賠償。並非雙倍紅利或雙倍已繳保費。"}},
{p:3,ch:"保险利益附约及其他产品",q:"若保险本身已加有豁免保费附约,而受保保单所有人在可以行使购买权时发现遭致伤残,在此情况下, 下列哪项正确?",o:["受保保单所有人的附加保障自动生效,即豁免所有保费","受保保单所有人待康复后才享有此利益","受保保单所有人可以尝试申请购买增额保险,但可能会遭受拒绝","受保保单所有人绝对不可以享有此权利"],a:0,e:"若保单已附豁免保费附约，受保人在可行使增额权时已伤残，则增额部分的保障即自动生效并获豁免保费。并非待康复后才享有，也非可被拒或完全无权。",src:1,tw:{ch:"保險利益附約及其他產品",q:"若保險本身已加有豁免保費附約，而受保保單所有人在可以行使購買權時發現遭致傷殘，在此情況下， 下列哪項正確？",o:["受保保單所有人的附加保障自動生效，即豁免所有保費","受保保單所有人待康復後才享有此利益","受保保單所有人可以嘗試申請購買增額保險，但可能會遭受拒絕","受保保單所有人絕對不可以享有此權利"],e:"若保單已附豁免保費附約，受保人在可行使增額權時已傷殘，則增額部分的保障即自動生效並獲豁免保費。並非待康復後才享有，也非可被拒或完全無權。"}},
{p:3,ch:"保险利益附约及其他产品",q:"若意外事故导致其他较轻微的指明受伤,保险公司通常会怎样赔付?",o:["保费的规定比率","以保障期计算的规定比率","医疗费用的规定比率","死亡保险金的规定比率"],a:3,e:"意外事故造成其他较轻微的指明受伤时，通常按死亡保险金的规定比率给付，而非按保费、保障期或医疗费用的比率。",src:1,tw:{ch:"保險利益附約及其他產品",q:"若意外事故導致其他較輕微的指明受傷，保險公司通常會怎樣賠付？",o:["保費的規定比率","以保障期計算的規定比率","醫療費用的規定比率","死亡保險金的規定比率"],e:"意外事故造成其他較輕微的指明受傷時，通常按死亡保險金的規定比率給付，而非按保費、保障期或醫療費用的比率。"}},
{p:3,ch:"保险利益附约及其他产品",q:"表示放弃某种形式的法律权利是指?",o:["豁免","放弃","优惠","附约"],a:0,e:"「豁免」（waiver）即自愿放弃某种法律权利，如豁免保费即放弃收取保费的权利。放弃、优惠、附约的表述均不构成「放弃法律权利」的标准含义。",src:1,tw:{ch:"保險利益附約及其他產品",q:"表示放棄某種形式的法律權利是指?",o:["豁免","放棄","優惠","附約"],e:"「豁免」（waiver）即自願放棄某種法律權利，如豁免保費即放棄收取保費的權利。放棄、優惠、附約的表述均不構成「放棄法律權利」的標準含義。"}},
{p:3,ch:"保险利益附约及其他产品",q:"被保险人获长期护理附约的支付利益,其基本计划及附约的保费:",o:["提高","暂停。但需在之后支付或扣减","于被保险人接受上述利益期间,可以得到豁免","减少百分之50%于康复收回原来的保费"],a:2,e:"受保人领取长期护理利益期间，其基本计划及附约的保费可获豁免，以减轻负担。并非提高、暂停后补交或康复后减半。",src:1,tw:{ch:"保險利益附約及其他產品",q:"被保險人獲長期護理附約的支付利益，其基本計劃及附約的保費：",o:["提高","暫停。但需在之後支付或扣減","於被保險人接受上述利益期間，可以得到豁免","減少百分之50%於康復收回原來的保費"],e:"受保人領取長期護理利益期間，其基本計劃及附約的保費可獲豁免，以減輕負擔。並非提高、暫停後補交或康復後減半。"}},
{p:3,ch:"保险利益附约及其他产品",q:"豁免保费(WP)与残疾收入(DI)的分别为?",o:["WP:受保人完全残疾时提供收入,DI:受保人完全残疾时提供豁免保费","DI:受保人完全残疾时提供收入, WP: 受保人完全残疾时提供豁免保费","WP:受保人生病时提供豁免保费, DI: 受保人生病时提供收入","WP: 受保人生病时提供收入, DI: 受保人生病时提供豁免保费"],a:1,e:"残疾收入（DI）附约在完全残疾时提供收入，豁免保费（WP）附约则在完全残疾时豁免保费。两者给付方向正相反。",src:1,tw:{ch:"保險利益附約及其他產品",q:"豁免保費(WP)與殘疾收入(DI)的分別為？",o:["WP:受保人完全殘疾時提供收入，DI:受保人完全殘疾時提供豁免保費","DI:受保人完全殘疾時提供收入, WP: 受保人完全殘疾時提供豁免保費","WP:受保人生病時提供豁免保費, DI: 受保人生病時提供收入","WP: 受保人生病時提供收入, DI: 受保人生病時提供豁免保費"],e:"殘疾收入（DI）附約在完全殘疾時提供收入，豁免保費（WP）附約則在完全殘疾時豁免保費。兩者給付方向正相反。"}},
{p:3,ch:"保险利益附约及其他产品",q:"豁免保费的等候期是指:",o:["容许保险人在该时间内作出赔偿","等候期内作出赔偿","超过等候期开始豁免保费","即宽限期,又称宽限日期"],a:2,e:"豁免保费的等候期指伤残须持续超过该期间后，才开始豁免保费。等候期内不作豁免，也非宽限日期。",src:1,tw:{ch:"保險利益附約及其他產品",q:"豁免保費的等候期是指：",o:["容許保險人在該時間內作出賠償","等候期內作出賠償","超過等候期開始豁免保費","即寬限期，又稱寬限日期"],e:"豁免保費的等候期指傷殘須持續超過該期間後，才開始豁免保費。等候期內不作豁免，也非寬限日期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"豁免保费附约与残疾收入附约的分别?",o:["两种附约完全相同","豁免保费附约才具有等候期","只有豁免保费附约才提供实质收入","只有残疾收入附约才提供实质收入"],a:3,e:"两者之别在于只有残疾收入附约提供实质的现金收入，而豁免保费附约只免除保费、不向受保人支付收入。故选「只有残疾收入附约才提供实质收入」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"豁免保費附約與殘疾收入附約的分別？",o:["兩種附約完全相同","豁免保費附約才具有等候期","只有豁免保費附約才提供實質收入","只有殘疾收入附約才提供實質收入"],e:"兩者之別在於只有殘疾收入附約提供實質的現金收入，而豁免保費附約只免除保費、不向受保人支付收入。故選「只有殘疾收入附約才提供實質收入」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"豁免保费附约中所指的完全伤残是:",o:["保障期内受保保单所有人完全伤残时,就会豁免伤残期间的保费","受保保单所有人于保障期限内遭受完全伤残,而计划于持续完全伤残某一段时间 (称为等候期)才开始豁免保费","受保保单所有人于保障期限内遭受完全伤残前,必须已部分伤残某一段时间 (称为等候期)才开始豁免保费","以上所有都适用"],a:1,e:"豁免保费附约的完全伤残指：受保人在保障期内完全伤残，并持续该状态达等候期后，才开始豁免该期间保费。并非伤残即马上豁免，也非须先部分伤残。",src:1,tw:{ch:"保險利益附約及其他產品",q:"豁免保費附約中所指的完全傷殘是：",o:["保障期內受保保單所有人完全傷殘時，就會豁免傷殘期間的保費","受保保單所有人於保障期限內遭受完全傷殘，而計劃於持續完全傷殘某一段時間 (稱為等候期)才開始豁免保費","受保保單所有人於保障期限內遭受完全傷殘前，必須已部分傷殘某一段時間 (稱為等候期)才開始豁免保費","以上所有都適用"],e:"豁免保費附約的完全傷殘指：受保人在保障期內完全傷殘，並持續該狀態達等候期後，才開始豁免該期間保費。並非傷殘即馬上豁免，也非須先部分傷殘。"}},
{p:3,ch:"保险利益附约及其他产品",q:"豁免保费附约在索偿时受到某些限制,该等限制包括:",o:["遭受残疾时的年龄","保费的缴付频率不可改变","某些原因的残疾(例如从事违法活动)","以上各项"],a:3,e:"豁免保费附约的索偿限制包括遭受残疾时的年龄、某些原因的残疾（如违法活动所致）以及缴费频率不可改变等，故以上各项皆属限制。",src:1,tw:{ch:"保險利益附約及其他產品",q:"豁免保費附約在索償時受到某些限制，該等限制包括：",o:["遭受殘疾時的年齡","保費的繳付頻率不可改變","某些原因的殘疾(例如從事違法活動)","以上各項"],e:"豁免保費附約的索償限制包括遭受殘疾時的年齡、某些原因的殘疾（如違法活動所致）以及繳費頻率不可改變等，故以上各項皆屬限制。"}},
{p:3,ch:"保险利益附约及其他产品",q:"豁免保费附约的等候期:",o:["无等候期","3或6个月","1至6个月","90日"],a:1,e:"豁免保费附约的等候期一般为3或6个月，而非无等候期、1至6个月或90日。",src:1,tw:{ch:"保險利益附約及其他產品",q:"豁免保費附約的等候期:",o:["無等候期","3或6個月","1至6個月","90日"],e:"豁免保費附約的等候期一般為3或6個月，而非無等候期、1至6個月或90日。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通常在给付长期护理保险利益(Long-Term Care)之前一个为期90日的",o:["等候期","豁免保费期","冷静期","宽限期"],a:0,e:"给付长期护理利益前为期90日的是等候期，而非豁免保费期、冷静期或宽限期。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通常在給付長期護理保險利益(Long-Term Care)之前一個為期90日的",o:["等候期","豁免保費期","冷靜期","寬限期"],e:"給付長期護理利益前為期90日的是等候期，而非豁免保費期、冷靜期或寬限期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通常在给付长期护理保险利益前有一个等候期,为期:",o:["30日","60日","90日","1年"],a:2,e:"长期护理保险利益给付前通常设有90日的等候期。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通常在給付長期護理保險利益前有一個等候期，為期：",o:["30日","60日","90日","1年"],e:"長期護理保險利益給付前通常設有90日的等候期。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通胀问题会令人寿保险的利益价值大大贬值,以下哪项附约可减低它的影响?",o:["死亡指数调整","生活指数调整","通货膨胀调整","通货调整商数"],a:1,e:"生活指数调整附约可使保额及利益随生活费用指数调升，抵销通胀令寿险利益贬值的影响。死亡指数调整、通货膨胀调整、通货调整商数均非标准附约。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通脹問題會令人壽保險的利益價值大大貶值，以下哪項附約可減低它的影響？",o:["死亡指數調整","生活指數調整","通貨膨脹調整","通貨調整商數"],e:"生活指數調整附約可使保額及利益隨生活費用指數調升，抵銷通脹令壽險利益貶值的影響。死亡指數調整、通貨膨脹調整、通貨調整商數均非標準附約。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通货膨胀可能重大的降低一项寿险利益的购买能力,为了解决这个难题而设计的独立附约称为:",o:["寿险利益调整","生活指数调整","通胀条文","通胀调整条文"],a:1,e:"为抵销通胀对购买力的侵蚀而设计的独立附约是生活指数调整附约。寿险利益调整、通胀条文、通胀调整条文均非标准名称。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通貨膨脹可能重大的降低一項壽險利益的購買能力，為了解決這個難題而設計的獨立附約稱為：",o:["壽險利益調整","生活指數調整","通脹條文","通脹調整條文"],e:"為抵銷通脹對購買力的侵蝕而設計的獨立附約是生活指數調整附約。壽險利益調整、通脹條文、通脹調整條文均非標準名稱。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通货膨胀的主要影响,是降低金钱的实际价值,以下哪类型保单须严加注意?",o:["只有终身寿险保单","只有储蓄寿险","只有残疾收入保险利益","所有长期寿险计划"],a:3,e:"通胀会侵蚀一切长期给付及保障的实际价值，故所有长期寿险计划（含终身、储蓄、残疾收入等）均须留意，并非只限于某类保单。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通貨膨脹的主要影響，是降低金錢的實際價值，以下哪類型保單須嚴加注意？",o:["只有終身壽險保單","只有儲蓄壽險","只有殘疾收入保險利益","所有長期壽險計劃"],e:"通脹會侵蝕一切長期給付及保障的實際價值，故所有長期壽險計劃（含終身、儲蓄、殘疾收入等）均須留意，並非只限於某類保單。"}},
{p:3,ch:"保险利益附约及其他产品",q:"遭受残疾的受保保单所有人之日常医疗费用会因通货膨胀而不断增加上哪项保单条款可抵消这项影响?",o:["意外死亡保险利益","豁免保费利益","生活指数调整","保证可保权益"],a:2,e:"生活指数调整附约可按指数调高残疾收入给付，抵销医疗费用因通胀上升的影响。意外死亡、豁免保费、保证可保权益均无此自动抗通胀功能。",src:1,tw:{ch:"保險利益附約及其他產品",q:"遭受殘疾的受保保單所有人之日常醫療費用會因通貨膨脹而不斷增加上哪項保單條款可抵消這項影響？",o:["意外死亡保險利益","豁免保費利益","生活指數調整","保證可保權益"],e:"生活指數調整附約可按指數調高殘疾收入給付，抵銷醫療費用因通脹上升的影響。意外死亡、豁免保費、保證可保權益均無此自動抗通脹功能。"}},
{p:3,ch:"保险利益附约及其他产品",q:"长期护理(Long Term Care)附约会支付预先定下比例的死亡金给身体状况而需要接受 长期护理的受保保单所有人。保险人通常需要什么证明才作出赔偿?",o:["经医生证明受保保单所有人患上重大疾病","经医生证明受保保单所有人失去某些日常起居活动能力","受保保单所有人患病期超过六个月","受保保单所有人接受手术的证明"],a:1,e:"长期护理附约赔偿前，通常要求经医生证明受保人已失去某些日常起居活动能力（ADLs）。患上重疾、患病超六个月、接受手术的证明均非其核心要求。",src:1,tw:{ch:"保險利益附約及其他產品",q:"長期護理(Long Term Care)附約會支付預先定下比例的死亡金給身體狀況而需要接受 長期護理的受保保單所有人。保險人通常需要什麼證明才作出賠償？",o:["經醫生證明受保保單所有人患上重大疾病","經醫生證明受保保單所有人失去某些日常起居活動能力","受保保單所有人患病期超過六個月","受保保單所有人接受手術的證明"],e:"長期護理附約賠償前，通常要求經醫生證明受保人已失去某些日常起居活動能力（ADLs）。患上重疾、患病超六個月、接受手術的證明均非其核心要求。"}},
{p:3,ch:"保险利益附约及其他产品",q:"长期护理当依合约作出赔偿前会要求「受保保单所有人」证明必须是已失去某些能力才会承认长期护理 的要求是必要的。该能力称为:",o:["所有日常活动 (All Daily Life Activities)","任何日常活动 (Any Daily Life Activities)","日常起居活动能力 (Activities of Daily Living)","悠闲时的活动 (Activities During Leisure)"],a:2,e:"长期护理所要求失去的能力是 Activities of Daily Living（日常起居活动能力）。其余选项的名称均不准确。",src:1,tw:{ch:"保險利益附約及其他產品",q:"長期護理當依合約作出賠償前會要求「受保保單所有人」證明必須是已失去某些能力才會承認長期護理 的要求是必要的。該能力稱為：",o:["所有日常活動 (All Daily Life Activities)","任何日常活動 (Any Daily Life Activities)","日常起居活動能力 (Activities of Daily Living)","悠閒時的活動 (Activities During Leisure)"],e:"長期護理所要求失去的能力是 Activities of Daily Living（日常起居活動能力）。其餘選項的名稱均不準確。"}},
{p:3,ch:"保险利益附约及其他产品",q:"附加于人寿保险的「其他意外保险利益」之利益给付表,包括:",o:["死亡而已","死亡及丧失视力","死亡、丧失视力及丧失肢体","上述及各种只较轻的伤残"],a:3,e:"「其他意外保险利益」的给付表涵盖死亡、丧失视力、丧失肢体及各种较轻微的伤残，故「上述及各种较轻的伤残」最完整。",src:1,tw:{ch:"保險利益附約及其他產品",q:"附加於人壽保險的「其他意外保險利益」之利益給付表，包括：",o:["死亡而已","死亡及喪失視力","死亡、喪失視力及喪失肢體","上述及各種只較輕的傷殘"],e:"「其他意外保險利益」的給付表涵蓋死亡、喪失視力、喪失肢體及各種較輕微的傷殘，故「上述及各種較輕的傷殘」最完整。"}},
{p:3,ch:"保险利益附约及其他产品",q:"附加于人寿保险的「其他意外保险利益」之除外责任,以下哪项并不包括:",o:["被保险人被谋杀","自杀","参与违法活动时造成的伤残","疾病 (除非由意外事故引起)"],a:0,e:"被保险人被谋杀是因他人犯罪所致，并非保单约定的除外原因，故不属除外责任。自杀、违法活动所致伤残、疾病（非意外引起）皆为除外。",src:1,tw:{ch:"保險利益附約及其他產品",q:"附加於人壽保險的「其他意外保險利益」之除外責任，以下哪項並不包括：",o:["被保險人被謀殺","自殺","參與違法活動時造成的傷殘","疾病 (除非由意外事故引起)"],e:"被保險人被謀殺是因他人犯罪所致，並非保單約定的除外原因，故不屬除外責任。自殺、違法活動所致傷殘、疾病（非意外引起）皆為除外。"}},
{p:3,ch:"保险利益附约及其他产品",q:"附加于寿险保单的保证可保选择的意思是﹕",o:["因接受一项低于标准风险的项目而须附加的费用","该保单属于有限保额计划的其中一部份","在未来指定日子自动增加保额","在不需提供可保性证明下,可选择提高保额"],a:3,e:"保证可保选择指受保人可在未来指定日期，无需提供可保性证明即可加购（提高）保额。它并非加费、有限保额或自动增额。",src:1,tw:{ch:"保險利益附約及其他產品",q:"附加於壽險保單的保證可保選擇的意思是﹕",o:["因接受一項低於標準風險的項目而須附加的費用","該保單屬於有限保額計劃的其中一部份","在未來指定日子自動增加保額","在不需提供可保性證明下，可選擇提高保額"],e:"保證可保選擇指受保人可在未來指定日期，無需提供可保性證明即可加購（提高）保額。它並非加費、有限保額或自動增額。"}},
{p:3,ch:"保险利益附约及其他产品",q:"附约\"生活指数调整\"是意味着的:",o:["对抗经济危机","对抗通货膨胀和通货收缩的意思","对罹癌病人发放部份保额","以上各项皆不是"],a:3,e:"生活指数调整附约是按生活费用指数调升保障以维持购买力，并非对抗经济危机、对抗通胀与通缩或对癌患病人发放部分保额，故以上皆不是。",src:1,tw:{ch:"保險利益附約及其他產品",q:"附約\"生活指數調整\"是意味着的:",o:["對抗經濟危機","對抗通貨膨脹和通貨收縮的意思","對罹癌病人發放部份保額","以上各項皆不是"],e:"生活指數調整附約是按生活費用指數調升保障以維持購買力，並非對抗經濟危機、對抗通脹與通縮或對癌患病人發放部分保額，故以上皆不是。"}},
{p:3,ch:"阐释人寿保险单",q:"「不可异议条款」说明保险合约生效两年之后,保险人不能提出异议。而这两年期间是:",o:["非免费保险期","不可异议期","可异议期","保单复效期"],a:2,e:"不可异议条款将合约生效后两年作为可异议期，此期间保险人可因隐瞒或误告等对保单有效性提出异议；两年后则不得异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"「不可異議條款」說明保險合約生效兩年之後，保險人不能提出異議。而這兩年期間是：",o:["非免費保險期","不可異議期","可異議期","保單復效期"],e:"不可異議條款將合約生效後兩年作為可異議期，此期間保險人可因隱瞞或誤告等對保單有效性提出異議；兩年後則不得異議。"}},
{p:3,ch:"阐释人寿保险单",q:"「不可异议条款」说明保险合约生效两年之后,保险人不能提出异议。除不可欺诈外,须满足以下哪 些条件?",o:["以缴交所需保费","不可因自杀而死","两年内仍生存","以上皆是"],a:2,e:"除须无欺诈外，不可异议条款还要求受保人在保单生效后的两年内仍然生存，否则保险人在该期间可于给付前提出异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"「不可異議條款」說明保險合約生效兩年之後，保險人不能提出異議。除不可欺詐外，須滿足以下哪 些條件？",o:["以繳交所需保費","不可因自殺而死","兩年內仍生存","以上皆是"],e:"除須無欺詐外，不可異議條款還要求受保人在保單生效後的兩年內仍然生存，否則保險人在該期間可於給付前提出異議。"}},
{p:3,ch:"阐释人寿保险单",q:"一个保单条款容许过期缴付保费而不受处罚,而保单会维持全额有效?",o:["宽限期","不能作废条款","不可异议条款","完整合约条款"],a:0,e:"宽限期容许保单所有人在保费到期后的一段期间内补缴保费而保障维持全部有效。不能作废、不可异议、完整合约条款均无此功能。",src:1,tw:{ch:"闡釋人壽保險單",q:"一個保單條款容許過期繳付保費而不受處罰，而保單會維持全額有效？",o:["寬限期","不能作廢條款","不可異議條款","完整合約條款"],e:"寬限期容許保單所有人在保費到期後的一段期間內補繳保費而保障維持全部有效。不能作廢、不可異議、完整合約條款均無此功能。"}},
{p:3,ch:"阐释人寿保险单",q:"一份人寿保单如违反了最高诚信,保单便会视为无效,以下哪项法律说明是正确的:",o:["这从不更改","最高诚信不适用","不可异议条款可以更改有关条款","违反最高诚信便会令保单自动被视为无效"],a:2,e:"违反最高诚信本会使保单无效，但不可异议条款可对此加以限制，即经过两年不可异议期后，保险人不得再以违反最高诚信为由异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"一份人壽保單如違反了最高誠信，保單便會視為無效，以下哪項法律說明是正確的:",o:["這從不更改","最高誠信不適用","不可異議條款可以更改有關條款","違反最高誠信便會令保單自動被視為無效"],e:"違反最高誠信本會使保單無效，但不可異議條款可對此加以限制，即經過兩年不可異議期後，保險人不得再以違反最高誠信為由異議。"}},
{p:3,ch:"阐释人寿保险单",q:"一份典型寿险所指明的「受益人」?",o:["受保生命","受保生命配偶","保险金准收款人","已承让保单收款人"],a:2,e:"典型寿险中的「受益人」是获指定收取保险金的准收款人，不一定是受保生命本人或其配偶。故以「保险金准收款人」为准。",src:1,tw:{ch:"闡釋人壽保險單",q:"一份典型壽險所指明的「受益人」?",o:["受保生命","受保生命配偶","保險金準收款人","已承讓保單收款人"],e:"典型壽險中的「受益人」是獲指定收取保險金的準收款人，不一定是受保生命本人或其配偶。故以「保險金準收款人」為準。"}},
{p:3,ch:"阐释人寿保险单",q:"一分完整保险合约应包括 i 投保单的复印本 ii 详细的医疗报告 iii 完整财务报告 iv 保险单正本",o:["i, ii","i, iv","ii, iii","iii, iv"],a:1,e:"完整保险合约包括保险单正本及投保单副本（附申请书内容），详细的医疗报告、完整财务报告并非合约的必要组成部分，故为 i、iv。",src:1,tw:{ch:"闡釋人壽保險單",q:"一分完整保險合約應包括 i 投保單的複印本 ii 詳細的醫療報告 iii 完整財務報告 iv 保險單正本",o:["i, ii","i, iv","ii, iii","iii, iv"],e:"完整保險合約包括保險單正本及投保單副本（附申請書內容），詳細的醫療報告、完整財務報告並非合約的必要組成部分，故為 i、iv。"}},
{p:3,ch:"阐释人寿保险单",q:"一名保险单持有人在保单中持有拥有权,然而有某些权益只会在较后时间才可享有的权益可称为:",o:["迟延权益","延期权益","预期权益","复归权益"],a:3,e:"保单所有人目前持有所有权、但须待较后时间（如受保人身故）方可享受的权益，称为复归（或有）权益。迟延、延期、预期权益均非标准称谓。",src:1,tw:{ch:"闡釋人壽保險單",q:"一名保險單持有人在保單中持有擁有權，然而有某些權益只會在較後時間才可享有的權益可稱為：",o:["遲延權益","延期權益","預期權益","復歸權益"],e:"保單所有人目前持有所有權、但須待較後時間（如受保人身故）方可享受的權益，稱為復歸（或有）權益。遲延、延期、預期權益均非標準稱謂。"}},
{p:3,ch:"阐释人寿保险单",q:"一名男子以免体检的方式安排一份人寿保险单,并无意误导了保险人其健康状况。如果当时披露这些 事实,保险人是不会提供保险。这名男子死去及真相被发现,在此情况下,下列哪项是不正确?",o:["无论死亡何时出现,保险人有权推翻合约","如死亡于两年内发生,保险人可推翻合约","如死亡于两年后发生,保险人便不可异议","如果不涉及欺诈,保险人很难不承认保单"],a:0,e:"若无欺诈，受不可异议条款约束，两年后保险人不得再推翻合约，故「无论死亡何时出现都可推翻」的说法错误。两年内死亡或涉欺诈时另当别论。",src:1,tw:{ch:"闡釋人壽保險單",q:"一名男子以免體檢的方式安排一份人壽保險單，並無意誤導了保險人其健康狀況。如果當時披露這些 事實，保險人是不會提供保險。這名男子死去及真相被發現，在此情況下，下列哪項是不正確？",o:["無論死亡何時出現，保險人有權推翻合約","如死亡於兩年內發生，保險人可推翻合約","如死亡於兩年後發生，保險人便不可異議","如果不涉及欺詐，保險人很難不承認保單"],e:"若無欺詐，受不可異議條款約束，兩年後保險人不得再推翻合約，故「無論死亡何時出現都可推翻」的說法錯誤。兩年內死亡或涉欺詐時另當別論。"}},
{p:3,ch:"阐释人寿保险单",q:"一张以投保人作受保生命的保单内,有一名第一顺位受益人及一名次顺位受益人,如第一顺位受益人 比受保生命早逝,而后者于次顺位受益人仍生存期间死亡,寿险利益将如何给付?",o:["受保生命的遗产","第一顺位受益人的承继人","次顺位受益人","次顺位受益人及第一顺位受益人的承继人平均分配"],a:2,e:"第一顺位受益人先于受保人死亡时，其受益权不转给其继承者，而由仍在世的次顺位受益人领取。故利益付予次顺位受益人。",src:1,tw:{ch:"闡釋人壽保險單",q:"一張以投保人作受保生命的保單內，有一名第一順位受益人及一名次順位受益人，如第一順位受益人 比受保生命早逝，而後者於次順位受益人仍生存期間死亡，壽險利益將如何給付？",o:["受保生命的遺產","第一順位受益人的承繼人","次順位受益人","次順位受益人及第一順位受益人的承繼人平均分配"],e:"第一順位受益人先於受保人死亡時，其受益權不轉給其繼承者，而由仍在世的次順位受益人領取。故利益付予次順位受益人。"}},
{p:3,ch:"阐释人寿保险单",q:"一次悲伤事件中,李生于交通意外离世,其妻子随后自杀,而妻子保单之自杀免责期差尚差一点到期 ,保险公司将如何处理?",o:["于自杀免责期内,不会作出任何赔偿","保单即时终止,但可获发还保费","保险公司可按「通融」赔付处理","保险公司会赔付一半保额"],a:2,e:"妻子因丧偶悲伤而自杀、且距自杀免责期届满仅差一线，保险人通常按「通融」酌情处理赔付。并非一律拒赔、即时终止退保费或赔一半。",src:1,tw:{ch:"闡釋人壽保險單",q:"一次悲傷事件中，李生於交通意外離世，其妻子隨後自殺，而妻子保單之自殺免責期差尚差一點到期 ，保險公司將如何處理？",o:["於自殺免責期內，不會作出任何賠償","保單即時終止，但可獲發還保費","保險公司可按「通融」賠付處理","保險公司會賠付一半保額"],e:"妻子因喪偶悲傷而自殺、且距自殺免責期屆滿僅差一線，保險人通常按「通融」酌情處理賠付。並非一律拒賠、即時終止退保費或賠一半。"}},
{p:3,ch:"阐释人寿保险单",q:"一般香港保单(美式保单)都有列明当误报年龄的情况出现时的处理方法,如果误报情况于索偿后才出 现。以下哪项或哪些是常见的处理方法?",o:["不会要求增加保费或退还保费","真实年龄比保单所写为低,赔偿较低利益","真实年龄比保单所写为高,赔偿较高利益","以上所有处理方法皆可"],a:0,e:"美式保单处理误报年龄是按真实年龄调整给付保额，而不要求补缴或退还保费。真实年龄较低者赔得较高而非较低，较高年龄者赔得较低而非较高，后两项方向颠倒。",src:1,tw:{ch:"闡釋人壽保險單",q:"一般香港保單(美式保單)都有列明當誤報年齡的情況出現時的處理方法，如果誤報情況於索償後才出 現。以下哪項或哪些是常見的處理方法？",o:["不會要求增加保費或退還保費","真實年齡比保單所寫為低，賠償較低利益","真實年齡比保單所寫為高，賠償較高利益","以上所有處理方法皆可"],e:"美式保單處理誤報年齡是按真實年齡調整給付保額，而不要求補繳或退還保費。真實年齡較低者賠得較高而非較低，較高年齡者賠得較低而非較高，後兩項方向顛倒。"}},
{p:3,ch:"阐释人寿保险单",q:"一项寿险保单转让中的承让人,其收取的金额称为净保险金,意思是:",o:["保险人会扣除保单中的分红或英式红利","保险人有权扣除任何过期未缴的保费或贷款和利息","承让人只可得到部份保额","以上各项均不正确"],a:1,e:"承让人在转让项下取得的「净保险金」指保险人先从保额中扣除过期未缴保费、贷款及利息后的余额。故保险人有权扣除该等项目。",src:1,tw:{ch:"闡釋人壽保險單",q:"一項壽險保單轉讓中的承讓人，其收取的金額稱為凈保險金，意思是：",o:["保險人會扣除保單中的分紅或英式紅利","保險人有權扣除任何過期未繳的保費或貸款和利息","承讓人只可得到部份保額","以上各項均不正確"],e:"承讓人在轉讓項下取得的「淨保險金」指保險人先從保額中扣除過期未繳保費、貸款及利息後的餘額。故保險人有權扣除該等項目。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项不是赔付选择?",o:["一次过整笔给付","存于保险人赚取利息","以取得的金钱买一份额外的定期保险","保险人分期给付"],a:2,e:"赔付选择包括整笔给付、存于保险人生息、分期给付等，而不包括「以取得的金钱购买额外的定期保险」。故该项并非赔付选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項不是賠付選擇？",o:["一次過整筆給付","存於保險人賺取利息","以取得的金錢買一份額外的定期保險","保險人分期給付"],e:"賠付選擇包括整筆給付、存於保險人生息、分期給付等，而不包括「以取得的金錢購買額外的定期保險」。故該項並非賠付選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项关于保单复效的陈述是不正确的?",o:["保单复效须受一定条件限制","只有在保单具有现金价值才可申请复效","已退保的保单不能复效","若保单已失效超过一定的时间,则不能复效"],a:1,e:"保单复效不要求保单必须具有现金价值，无现金价值的保单同样可申请复效。复效须受条件及失效期限限制，已退保的保单不能复效。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項關於保單復效的陳述是不正確的？",o:["保單復效須受一定條件限制","只有在保單具有現金價值才可申請復效","已退保的保單不能復效","若保單已失效超過一定的時間，則不能復效"],e:"保單復效不要求保單必須具有現金價值，無現金價值的保單同樣可申請復效。復效須受條件及失效期限限制，已退保的保單不能復效。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项对绝对转让和扺押转让的描述不正确?",o:["两者完全相同","扺押转让以保单为扺押品","绝对转让属永久性转让","以上所有各项"],a:0,e:"绝对转让是永久性的产权转移，抵押转让则仅以保单作抵押品而保留赎回权，两者并不相同。故「两者完全相同」的描述错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項對絕對轉讓和扺押轉讓的描述不正確？",o:["兩者完全相同","扺押轉讓以保單為扺押品","絕對轉讓屬永久性轉讓","以上所有各項"],e:"絕對轉讓是永久性的產權轉移，抵押轉讓則僅以保單作抵押品而保留贖回權，兩者並不相同。故「兩者完全相同」的描述錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项并非人寿保险现金红利处置的选择?",o:["可用作缴付续保保费","可用作购买保险公司股份有限公司","可以现金提取","可存放在保险人处以赚取利息"],a:1,e:"现金红利的处置选择包括抵缴续保保费、现金提取、存放赚息或购买增额缴清保险，但不包括购买保险公司股份。故该项非红利选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項並非人壽保險現金紅利處置的選擇？",o:["可用作繳付續保保費","可用作購買保險公司股份有限公司","可以現金提取","可存放在保險人處以賺取利息"],e:"現金紅利的處置選擇包括抵繳續保保費、現金提取、存放賺息或購買增額繳清保險，但不包括購買保險公司股份。故該項非紅利選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项是不正确地描述转让的句子?",o:["转让不可以为非法目的","转让不可以为金钱目的","转让可以将保单一次过转付给承让人","转让不可以影响不可撤换受益人之利益"],a:1,e:"转让可以为金钱等对价目的而进行，只要目的合法即可。所以「转让不可以为金钱目的」的描述不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項是不正確地描述轉讓的句子？",o:["轉讓不可以為非法目的","轉讓不可以為金錢目的","轉讓可以將保單一次過轉付給承讓人","轉讓不可以影響不可撤換受益人之利益"],e:"轉讓可以為金錢等對價目的而進行，只要目的合法即可。所以「轉讓不可以為金錢目的」的描述不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项有关保单抵押贷款条款的陈述是不正确?",o:["贷款用途需经保险人同意","保单所有人有权向保人借入款项","贷款金额的上限为保单现金价值","未缴清的利息会支付保险利益中扣除"],a:0,e:"保单抵押贷款的用途并无限制，不需经保险人同意。保单所有人有权以现金价值为限借款，未清偿贷款及利息会从保险利益中扣除。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項有關保單抵押貸款條款的陳述是不正確？",o:["貸款用途需經保險人同意","保單所有人有權向保人借入款項","貸款金額的上限為保單現金價值","未繳清的利息會支付保險利益中扣除"],e:"保單抵押貸款的用途並無限制，不需經保險人同意。保單所有人有權以現金價值為限借款，未清償貸款及利息會從保險利益中扣除。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项有关保单抵押贷款条款的陈述是正确?",o:["贷款用途需经保险人同意","现金价值是贷款唯一的抵押品","贷款金额没有上限","以上皆不正确"],a:1,e:"保单贷款的抵押品就是保单的现金价值，贷款用途无须保险人同意，金额亦以现金价值为上限，故「现金价值是贷款唯一的抵押品」正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項有關保單抵押貸款條款的陳述是正確？",o:["貸款用途需經保險人同意","現金價值是貸款唯一的抵押品","貸款金額沒有上限","以上皆不正確"],e:"保單貸款的抵押品就是保單的現金價值，貸款用途無須保險人同意，金額亦以現金價值為上限，故「現金價值是貸款唯一的抵押品」正確。"}},
{p:3,ch:"阐释人寿保险单",q:"不可异议条例规定保险合约生效两年后,保险人不能对合约的有效性提出异议,而合约中亦明示或隐 含地包括在没有欺诈行为的情况下发出,除此之外,还要符合下列哪项要求?",o:["受保人必须死于自杀","受保人在保单生效后一年内死亡","受保生命在生前的两年","受保人失去工作能力"],a:2,e:"除无欺诈外，不可异议条款还要求受保生命在保单生效后的两年内仍然生存。自杀、一年内死亡、失去工作能力等并非该要件。",src:1,tw:{ch:"闡釋人壽保險單",q:"不可異議條例規定保險合約生效兩年後，保險人不能對合約的有效性提出異議，而合約中亦明示或隱 含地包括在沒有欺詐行為的情況下發出，除此之外，還要符合下列哪項要求？",o:["受保人必須死於自殺","受保人在保單生效後一年內死亡","受保生命在生前的兩年","受保人失去工作能力"],e:"除無欺詐外，不可異議條款還要求受保生命在保單生效後的兩年內仍然生存。自殺、一年內死亡、失去工作能力等並非該要件。"}},
{p:3,ch:"阐释人寿保险单",q:"不可异议条款规定保险人不能对保单有效性提出异议该可以期为",o:["十二个月","三个月","二年","一年"],a:2,e:"不可异议条款所订的不可异议期为保单生效起两年（二年）。",src:1,tw:{ch:"闡釋人壽保險單",q:"不可異議條款規定保險人不能對保單有效性提出異議該可以期為",o:["十二個月","三個月","二年","一年"],e:"不可異議條款所訂的不可異議期為保單生效起兩年（二年）。"}},
{p:3,ch:"阐释人寿保险单",q:"不可异议条款除了受保人需要仍然生存,以下哪项描述是不正确:",o:["是不能作废的别名","还需要维持保单多于2年后","不是欺诈行为便可获得支付","保险人可于可异议期作出更改"],a:0,e:"「不能作废」是就保单现金价值的处置而言，与不可异议条款并非同一概念，故称两者为别名不正确。其余关于两年、无欺诈、可异议期可更改的说法成立。",src:1,tw:{ch:"闡釋人壽保險單",q:"不可異議條款除了受保人需要仍然生存，以下哪項描述是不正確:",o:["是不能作廢的別名","還需要維持保單多於2年後","不是欺詐行為便可獲得支付","保險人可於可異議期作出更改"],e:"「不能作廢」是就保單現金價值的處置而言，與不可異議條款並非同一概念，故稱兩者為別名不正確。其餘關於兩年、無欺詐、可異議期可更改的說法成立。"}},
{p:3,ch:"阐释人寿保险单",q:"个别本地保险人采用英式人寿保险保单用语时可能存在差异的地方。哪一种保险是倾向采用美国及北 美常见的保单用语?",o:["一般保险","人寿保险","意外保险","汽车保险"],a:1,e:"人寿保险倾向采用美国及北美常见的保单用语（如不可异议、不丧失价值等），而一般保险、意外、汽车保险未必如此。",src:1,tw:{ch:"闡釋人壽保險單",q:"個別本地保險人採用英式人壽保險保單用語時可能存在差異的地方。哪一種保險是傾向採用美國及北 美常見的保單用語?",o:["一般保險","人壽保險","意外保險","汽車保險"],e:"人壽保險傾向採用美國及北美常見的保單用語（如不可異議、不喪失價值等），而一般保險、意外、汽車保險未必如此。"}},
{p:3,ch:"阐释人寿保险单",q:"为什么说一张寿险保单所有人只具有有限的权利转让该保单的产权?",o:["转让一张保单的权利属于保单的受益人而非保单所有人所有","转让寿险单必须保险人的批准","转让保单的目的必须是合法的","在典型寿险保单所规定的转让必须书面通知保险人"],a:3,e:"典型寿险保单规定转让须以书面通知保险人方有效，这构成对所有权人自由转让的限制，故其转让产权之权为有限权利。",src:1,tw:{ch:"闡釋人壽保險單",q:"為什麼說一張壽險保單所有人只具有有限的權利轉讓該保單的產權？",o:["轉讓一張保單的權利屬於保單的受益人而非保單所有人所有","轉讓壽險單必須保險人的批准","轉讓保單的目的必須是合法的","在典型壽險保單所規定的轉讓必須書面通知保險人"],e:"典型壽險保單規定轉讓須以書面通知保險人方有效，這構成對所有權人自由轉讓的限制，故其轉讓產權之權為有限權利。"}},
{p:3,ch:"阐释人寿保险单",q:"为什么说一张寿险保单的保单所有人只具有有限的权利转让该保单的产权﹖",o:["若受益人已享有既得利益,保单所有人不得侵犯其利益","保单转让的权利属保单受益人的权利而非保单所有人","在保单初始期,只有保险人批准才可转让","在保单初始期,转让为保单所有人和受益人的共同权利"],a:0,e:"若受益人已享有既得利益，保单所有人便不得以转让损害其利益，这正是转让权受限的原因。其余说法不准确。",src:1,tw:{ch:"闡釋人壽保險單",q:"為什麼說一張壽險保單的保單所有人只具有有限的權利轉讓該保單的產權﹖",o:["若受益人已享有既得利益，保單所有人不得侵犯其利益","保單轉讓的權利屬保單受益人的權利而非保單所有人","在保單初始期，只有保險人批准才可轉讓","在保單初始期，轉讓為保單所有人和受益人的共同權利"],e:"若受益人已享有既得利益，保單所有人便不得以轉讓損害其利益，這正是轉讓權受限的原因。其餘說法不準確。"}},
{p:3,ch:"阐释人寿保险单",q:"于本港签发的常见寿险保单形式,下列哪项不是有关的红利选择?",o:["即时以现金给付","用以购买有关保险公司的股份","用以缴付保单的未来保费","上述没有一项是有关的红利选择"],a:1,e:"常见红利选择包括现金给付、抵扣未来保费、存放赚息、购买增额缴清保险等，但「购买保险公司的股份」并非红利选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"於本港簽發的常見壽險保單形式，下列哪項不是有關的紅利選擇？",o:["即時以現金給付","用以購買有關保險公司的股份","用以繳付保單的未來保費","上述沒有一項是有關的紅利選擇"],e:"常見紅利選擇包括現金給付、抵扣未來保費、存放賺息、購買增額繳清保險等，但「購買保險公司的股份」並非紅利選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保单的受益人是指?",o:["受保生命","受保生命的配偶","保险金准收款人","保单持有人"],a:2,e:"人寿保单的受益人是获指定收取保险金的人（保险金准收款人），未必是受保生命或其配偶、保单持有人。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保單的受益人是指？",o:["受保生命","受保生命的配偶","保險金準收款人","保單持有人"],e:"人壽保單的受益人是獲指定收取保險金的人（保險金準收款人），未必是受保生命或其配偶、保單持有人。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险中,自杀条款的目的是",o:["防止有人自杀","避免有人利用自杀而获得赔偿","不鼓励以自杀作为得到赔偿的方法","以上所有各项"],a:1,e:"自杀条款的目的是防止有人为令受益人取得保险金而利用自杀骗保。它既非为阻止一切自杀，也非仅是「不鼓励」，核心在防范道德风险。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險中，自殺條款的目的是",o:["防止有人自殺","避免有人利用自殺而獲得賠償","不鼓勵以自殺作為得到賠償的方法","以上所有各項"],e:"自殺條款的目的是防止有人為令受益人取得保險金而利用自殺騙保。它既非為阻止一切自殺，也非僅是「不鼓勵」，核心在防範道德風險。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险中「复效 (reinstatement) 」,英式保单又称为:",o:["重新订立 (re-establishment)","保单复效(policy revival)","不能作废 (non-forfeiture)","保单续保 (policy renewal)"],a:1,e:"人寿保险的复效，英式保单用语称为保单复效（policy revival）。重新订立、不能作废、保单续保均非正确称谓。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險中「復效 (reinstatement) 」，英式保單又稱為：",o:["重新訂立 (re-establishment)","保單復效(policy revival)","不能作廢 (non-forfeiture)","保單續保 (policy renewal)"],e:"人壽保險的復效，英式保單用語稱為保單復效（policy revival）。重新訂立、不能作廢、保單續保均非正確稱謂。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险是保单所有人的财产。如果进行绝对转让,下列哪些描述是正确的?",o:["绝对转让是暂时性的安排","转让人成为新的保单所有人","承让人成为新的保单所有人","以上都是错误的"],a:2,e:"绝对转让是永久的产权转移，一经转让，承让人即成为新的保单所有人。转让人丧失所有权，也非暂时性安排。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險是保單所有人的財產。如果進行絕對轉讓，下列哪些描述是正確的？",o:["絕對轉讓是暫時性的安排","轉讓人成為新的保單所有人","承讓人成為新的保單所有人","以上都是錯誤的"],e:"絕對轉讓是永久的產權轉移，一經轉讓，承讓人即成為新的保單所有人。轉讓人喪失所有權，也非暫時性安排。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险理赔时发现受保人年龄应较少,按美式保险传统做法,会赔偿较大金额,同样情况下,英式 传统做法为以下那项?",o:["与美式并无分别","赔偿死亡保险金额,不会退回多付保费","赔偿死亡保险金额,退回多付的保费","由于违反最高诚信,没有任何赔偿"],a:2,e:"英式做法：误报年龄致多缴保费者，按原订死亡保险金额赔偿，并退回多付的保费。美式则按实际年龄调整保额，两者不同。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險理賠時發現受保人年齡應較少，按美式保險傳統做法，會賠償較大金額，同樣情況下，英式 傳統做法為以下那項？",o:["與美式並無分別","賠償死亡保險金額，不會退回多付保費","賠償死亡保險金額，退回多付的保費","由於違反最高誠信，沒有任何賠償"],e:"英式做法：誤報年齡致多繳保費者，按原訂死亡保險金額賠償，並退回多付的保費。美式則按實際年齡調整保額，兩者不同。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险的转让,比较承让人的权利,保险人的优先权为﹕",o:["扣除任何未偿还的贷款","扣除贷款的利息","扣除任何过期未缴的保费","以上所列各项"],a:3,e:"转让时保险人享有优先权，可从保额中扣除未偿还贷款、贷款利息及任何过期未缴保费后，余额才付给承让人。故以上所列各项皆是。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險的轉讓，比較承讓人的權利，保險人的優先權為﹕",o:["扣除任何未償還的貸款","扣除貸款的利息","扣除任何過期未繳的保費","以上所列各項"],e:"轉讓時保險人享有優先權，可從保額中扣除未償還貸款、貸款利息及任何過期未繳保費後，餘額才付給承讓人。故以上所列各項皆是。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险的转让过程中,将保单转让给其他人的一方称为:",o:["转让人","承让人","被提名转让人","被提名承让人"],a:0,e:"将保单转让给另一方的一方称为转让人，接受保单的一方称为承让人。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險的轉讓過程中，將保單轉讓給其他人的一方稱為：",o:["轉讓人","承讓人","被提名轉讓人","被提名承讓人"],e:"將保單轉讓給另一方的一方稱為轉讓人，接受保單的一方稱為承讓人。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险转让的方式共有两种,一种是绝对转让,另一种是:",o:["部份转让","抵押转让","优先转让","永久转让"],a:1,e:"人寿保险转让有两种：绝对转让与抵押转让。部分、优先、永久转让均非标准方式。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險轉讓的方式共有兩種，一種是絕對轉讓，另一種是：",o:["部份轉讓","抵押轉讓","優先轉讓","永久轉讓"],e:"人壽保險轉讓有兩種：絕對轉讓與抵押轉讓。部分、優先、永久轉讓均非標準方式。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险转让的方式共有两种,分别是: i 部份转让 ii 抵押转让 iii 绝对转让 iv 永久转让",o:["ii, iii","ii, iv","i, ii","i, iv"],a:0,e:"人寿保险转让的两种方式是抵押转让与绝对转让，即 ii、iii。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險轉讓的方式共有兩種，分別是： i 部份轉讓 ii 抵押轉讓 iii 絕對轉讓 iv 永久轉讓",o:["ii, iii","ii, iv","i, ii","i, iv"],e:"人壽保險轉讓的兩種方式是抵押轉讓與絕對轉讓，即 ii、iii。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪一项不大可能是复效条款?",o:["保单失效两年","保单失效五年","保单失效八年","以上没有一项是正确的复效条款"],a:2,e:"复效一般限于保单失效后的较短期内（如两至五年），失效八年已远超通常期限，不大可能仍可复效。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪一項不大可能是復效條款?",o:["保單失效兩年","保單失效五年","保單失效八年","以上沒有一項是正確的復效條款"],e:"復效一般限於保單失效後的較短期內（如兩至五年），失效八年已遠超通常期限，不大可能仍可復效。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪一项说明并不正确?",o:["人寿保单可以转让予任何对受保人不具有可保权益的人","人寿保单可以转让予任何与受保人关系密切的朋友","人寿保单可以转让予受保人的债权人,但保额必须不超过负债金额","不论承让人有否可保权益,人寿保单也可以转让"],a:2,e:"人寿保单转让并无「保额不超过负债」的限制，故该说法错误。转让可向无保险利益者、关系密切者或债权人作出，且不需可保利益。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪一項說明並不正確？",o:["人壽保單可以轉讓予任何對受保人不具有可保權益的人","人壽保單可以轉讓予任何與受保人關係密切的朋友","人壽保單可以轉讓予受保人的債權人，但保額必須不超過負債金額","不論承讓人有否可保權益，人壽保單也可以轉讓"],e:"人壽保單轉讓並無「保額不超過負債」的限制，故該說法錯誤。轉讓可向無保險利益者、關係密切者或債權人作出，且不需可保利益。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪三项陈述关于自杀条款是正确的? i 自杀往往是除外责任 ii 保单生效初期自杀被列为除外责任 iii 自杀引起的举证责任在保险人身上 iv 可能涉及保费被退还",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:3,e:"自杀条款规定保单生效初期自杀属除外并可退还保费，举证责任在保险人；但自杀并非「往往」属除外（仅限初期）。故 ii、iii、iv 正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪三項陳述關於自殺條款是正確的？ i 自殺往往是除外責任 ii 保單生效初期自殺被列為除外責任 iii 自殺引起的舉證責任在保險人身上 iv 可能涉及保費被退還",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"自殺條款規定保單生效初期自殺屬除外並可退還保費，舉證責任在保險人；但自殺並非「往往」屬除外（僅限初期）。故 ii、iii、iv 正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪两项有关宽限期的陈述是正确的? i 一般为期至少30至31日 ii 适用于所有保费,包括首期保费 iii 美式保单,如未缴清保费,宽限期完结之日失效 iv 美式保单,如未缴清保费,保费到期日失效",o:["i, ii","i, iii","ii, iii","ii, iv"],a:1,e:"宽限期一般为至少30至31日、不适用于首期保费；美式保单在宽限期届满仍未缴清保费者于该日失效。故 i、iii 正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪兩項有關寬限期的陳述是正確的？ i 一般為期至少30至31日 ii 適用於所有保費，包括首期保費 iii 美式保單，如未繳清保費，寬限期完結之日失效 iv 美式保單，如未繳清保費，保費到期日失效",o:["i, ii","i, iii","ii, iii","ii, iv"],e:"寬限期一般為至少30至31日、不適用於首期保費；美式保單在寬限期屆滿仍未繳清保費者於該日失效。故 i、iii 正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪个不是有意复效的人寿保险单的条件:",o:["提交持续可保性的证明","保险人书面的同意","缴付一笔复效费","给付已到期但未缴清的保费及利息"],a:1,e:"复效条件包括提供可保性证明、缴付复效费及补缴到期未缴保费连利息，但不要求保险人书面同意。故该选项不是复效条件。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪個不是有意復效的人壽保險單的條件：",o:["提交持續可保性的證明","保險人書面的同意","繳付一筆復效費","給付已到期但未繳清的保費及利息"],e:"復效條件包括提供可保性證明、繳付復效費及補繳到期未繳保費連利息，但不要求保險人書面同意。故該選項不是復效條件。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪个描述最贴切形容人寿保险中的宽限期?",o:["被保险人于保费到期日后的免费保险期","保险人允许过期缴付保费的一段时间","保费到期日之后保险保障仍然维持有效的一段时间","保险人决定是否取消保单的一段时间"],a:2,e:"宽限期最贴切的描述是：保费到期日之后保险保障仍维持有效的一段时间。它并非免费保险期、保险人决定取消的期间，也非单纯的「允许过期缴付」。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪個描述最貼切形容人壽保險中的寬限期？",o:["被保險人於保費到期日後的免費保險期","保險人允許過期繳付保費的一段時間","保費到期日之後保險保障仍然維持有效的一段時間","保險人決定是否取消保單的一段時間"],e:"寬限期最貼切的描述是：保費到期日之後保險保障仍維持有效的一段時間。它並非免費保險期、保險人決定取消的期間，也非單純的「允許過期繳付」。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪以情况并不符合保单复效的条款?",o:["保单去年失效","保单两年前失效","保单八年前失效","以上情况皆不符合"],a:2,e:"复效须在保单失效后的指定期限内进行，失效八年已远超通常允许期限，不符合复效条款。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪以情況並不符合保單復效的條款?",o:["保單去年失效","保單兩年前失效","保單八年前失效","以上情況皆不符合"],e:"復效須在保單失效後的指定期限內進行，失效八年已遠超通常允許期限，不符合復效條款。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪情况会导致人寿保单变成可异议的状态?",o:["保单持有人的年龄少于18岁","受保人自杀","保单持有人欺诈性违反最高诚信","保单以不分红的方式签发"],a:2,e:"保单持有人欺诈性地违反最高诚信，会使保单处于可异议状态，保险人可据此异议。年龄不足、自杀、不分红签发均不直接构成可异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪情況會導致人壽保單變成可異議的狀態？",o:["保單持有人的年齡少於18歲","受保人自殺","保單持有人欺詐性違反最高誠信","保單以不分紅的方式簽發"],e:"保單持有人欺詐性地違反最高誠信，會使保單處於可異議狀態，保險人可據此異議。年齡不足、自殺、不分紅簽發均不直接構成可異議。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪方有权决定赔付的选择?",o:["保单持有人","受益人","以上两人均可","保险人"],a:2,e:"赔付的选择通常可由保单持有人或受益人作出，故两者均可。保险人并非当然决定者。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪方有權決定賠付的選擇？",o:["保單持有人","受益人","以上兩人均可","保險人"],e:"賠付的選擇通常可由保單持有人或受益人作出，故兩者均可。保險人並非當然決定者。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪种情况会最有可能导致不可异议条款不可生效?",o:["受保人未满18岁","受保人存在欺诈行为","受保人未能缴付保费","受保人失去工作能力"],a:1,e:"不可异议条款不适用于欺诈情形，若受保人存在欺诈行为，则该条款最可能失效，保险人仍可异议。未满18岁、欠费、失去工作能力与此无直接关系。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪種情況會最有可能導致不可異議條款不可生效？",o:["受保人未滿18歲","受保人存在欺詐行為","受保人未能繳付保費","受保人失去工作能力"],e:"不可異議條款不適用於欺詐情形，若受保人存在欺詐行為，則該條款最可能失效，保險人仍可異議。未滿18歲、欠費、失去工作能力與此無直接關係。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪类保单并不适用「不能作废条款」的?",o:["年金","定期保险","尚未有现金价值的保单","以上皆不适用此条款"],a:3,e:"不能作废条款适用于具有现金价值的保单，年金、定期保险及尚未有现金价值的保单均无现金价值可言，故皆不适用该条款。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪類保單並不適用「不能作廢條款」的？",o:["年金","定期保險","尚未有現金價值的保單","以上皆不適用此條款"],e:"不能作廢條款適用於具有現金價值的保單，年金、定期保險及尚未有現金價值的保單均無現金價值可言，故皆不適用該條款。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项/些是赔付的方式? i 一笔过 ii 定期支付选择 iii 定额支付选择 iv 买保险人的股票",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"赔付方式包括整笔给付、定期支付选择及定额支付选择，但不包括购买保险人的股票。故为 i、ii、iii。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項/些是賠付的方式？ i 一筆過 ii 定期支付選擇 iii 定額支付選擇 iv 買保險人的股票",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"賠付方式包括整筆給付、定期支付選擇及定額支付選擇，但不包括購買保險人的股票。故為 i、ii、iii。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项一般不是转让的惯常方式?",o:["保单所有人可以将保单永久转让给第三者","保单所有人可以将保单暂时性转让给第三者","转让不可以影响不可撤换受益人","转让必须得保险人事前同意"],a:3,e:"转让无需事先取得保险人同意，只需事后通知即可，故「转让必须得保险人事前同意」不是惯常方式。永久或暂时转让及不侵害不可撤换受益人利益均属正常。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項一般不是轉讓的慣常方式？",o:["保單所有人可以將保單永久轉讓給第三者","保單所有人可以將保單暫時性轉讓給第三者","轉讓不可以影響不可撤換受益人","轉讓必須得保險人事前同意"],e:"轉讓無需事先取得保險人同意，只需事後通知即可，故「轉讓必須得保險人事前同意」不是慣常方式。永久或暫時轉讓及不侵害不可撤換受益人利益均屬正常。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项不属于不能作废条款的选择?",o:["购买减额清缴保险","即时收取缴清保单的利益","用现金价值作保费做展期保险","以上各项皆不是"],a:1,e:"不能作废条款提供减额缴清保险、以现金价值作保费展期或退保取回现金价值等选择，而不包括「即时收取缴清保单的利益」。故该项不属于其选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項不屬於不能作廢條款的選擇？",o:["購買減額清繳保險","即時收取繳清保單的利益","用現金價值作保費做展期保險","以上各項皆不是"],e:"不能作廢條款提供減額繳清保險、以現金價值作保費展期或退保取回現金價值等選擇，而不包括「即時收取繳清保單的利益」。故該項不屬於其選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项不属于寿险利益给付的方式之一:",o:["以现金方式给付","以利息给付,把有关资金放在保险人处","以有关保险公司之股份支付","以上各项皆不是有关支付方式"],a:2,e:"寿险利益给付通常以现金、存放赚息、分期等方式，而非「以保险公司股份支付」。故该项不是给付方式。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項不屬於壽險利益給付的方式之一：",o:["以現金方式給付","以利息給付，把有關資金放在保險人處","以有關保險公司之股份支付","以上各項皆不是有關支付方式"],e:"壽險利益給付通常以現金、存放賺息、分期等方式，而非「以保險公司股份支付」。故該項不是給付方式。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项不是「红利」的选择?",o:["终身收益选择","现金支付","购买增额清缴保险","存于保险人处赚取利息"],a:0,e:"红利选择包括现金支付、抵扣保费、购买增额缴清保险、存放赚息等，而「终身收益选择」属赔付给付方式，不是红利处置选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項不是「紅利」的選擇？",o:["終身收益選擇","現金支付","購買增額清繳保險","存於保險人處賺取利息"],e:"紅利選擇包括現金支付、抵扣保費、購買增額繳清保險、存放賺息等，而「終身收益選擇」屬賠付給付方式，不是紅利處置選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项不是完整合约条款的特点?",o:["合约有效期可持续数十年","所有保险公司中的职员可获权更改保险契约","指定的保险公司高级职员可获权更改保险契约","完整保单合约包括保险单,投保单副本"],a:1,e:"完整合约条款的特点之一是只有指定高级职员方可更改契约，而非所有职员都能更改。故「所有职员可获权更改」不符该条款特点。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項不是完整合約條款的特點？",o:["合約有效期可持續數十年","所有保險公司中的職員可獲權更改保險契約","指定的保險公司高級職員可獲權更改保險契約","完整保單合約包括保險單,投保單副本"],e:"完整合約條款的特點之一是隻有指定高級職員方可更改契約，而非所有職員都能更改。故「所有職員可獲權更改」不符該條款特點。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项不是有意复效保单需要的条件?",o:["提供持续可保性的证明","保险人的书面同意","缴交复效费","补付已到期但未缴清的保费及利息"],a:1,e:"复效所需条件是提供可保性证明、缴付复效费及补缴到期未缴保费连利息，并不要求保险人书面同意。故该选项不是复效条件。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項不是有意復效保單需要的條件?",o:["提供持續可保性的證明","保險人的書面同意","繳交復效費","補付已到期但未繳清的保費及利息"],e:"復效所需條件是提供可保性證明、繳付復效費及補繳到期未繳保費連利息，並不要求保險人書面同意。故該選項不是復效條件。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项关于典型寿险保单中的保单抵押贷款条款的陈述为不正确?",o:["贷款用途无任何限制","通常要求独立的质押担保","有关贷款可于支付保额前偿还或不偿还","上述所有各项均不正确"],a:1,e:"保单抵押贷款通常以保单现金价值作抵押，不要求独立的质押担保；贷款用途无限制，且可于给付保额时偿还或不偿还。故「通常要求独立质押担保」不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項關於典型壽險保單中的保單抵押貸款條款的陳述為不正確？",o:["貸款用途無任何限制","通常要求獨立的質押擔保","有關貸款可於支付保額前償還或不償還","上述所有各項均不正確"],e:"保單抵押貸款通常以保單現金價值作抵押，不要求獨立的質押擔保；貸款用途無限制，且可於給付保額時償還或不償還。故「通常要求獨立質押擔保」不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项关于受益人的描述是正确的:",o:["所有受益人必须要有可保权益","只有第三者保单可用概栝式指定","除非保单特别指定,数位指定的受益人将平均分配保险金","如受益人比受保保单所有人较早发生死亡,他的继承人将于适当时候提取保险金"],a:2,e:"寿险保单的数位受益人若未特别列明分配比例，一般会平均分配保险金，故选C。受益人无须具备可保权益，概括式指定亦非仅限第三者保单，而无后备安排时保险金通常回归保单而非当然由继承人在适当时期取得，故其余三项错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項關於受益人的描述是正確的：",o:["所有受益人必須要有可保權益","只有第三者保單可用概栝式指定","除非保單特別指定，數位指定的受益人將平均分配保險金","如受益人比受保保單所有人較早發生死亡，他的繼承人將於適當時候提取保險金"],e:"壽險保單的數位受益人若未特別列明分配比例，一般會平均分配保險金，故選C。受益人無須具備可保權益，概括式指定亦非僅限第三者保單，而無後備安排時保險金通常回歸保單而非當然由繼承人在適當時期取得，故其餘三項錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项关于红利给付是不正确?",o:["可以现金即时给付","存于保险人处以赚取利息","如果没有作出选择,保险人会采用”自动红利选择”","如果没有作出选择,保单所有人将会丧失该红利"],a:3,e:"红利可即时以现金给付、存于保险人处赚取利息，或未作选择时由保险人采用自动红利选择，前三项均符合实务。未作选择时保单仍会自动处理，并不会丧失红利，故D为不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項關於紅利給付是不正確？",o:["可以現金即時給付","存於保險人處以賺取利息","如果沒有作出選擇，保險人會採用”自動紅利選擇”","如果沒有作出選擇，保單所有人將會喪失該紅利"],e:"紅利可即時以現金給付、存於保險人處賺取利息，或未作選擇時由保險人採用自動紅利選擇，前三項均符合實務。未作選擇時保單仍會自動處理，並不會喪失紅利，故D為不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项关于绝对转让是不正确的?",o:["所有权益归于新的保单所有人","转让是永久性的","要以扺押品作贷款抵押","新的保单所有人称为承让人"],a:2,e:"绝对转让是永久性转让，全部权益归于承让人，A、B、D描述均正确。它是以保单本身作转移，并非一定要以抵押品作贷款抵押，故C描述不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項關於絕對轉讓是不正確的？",o:["所有權益歸於新的保單所有人","轉讓是永久性的","要以扺押品作貸款抵押","新的保單所有人稱為承讓人"],e:"絕對轉讓是永久性轉讓，全部權益歸於承讓人，A、B、D描述均正確。它是以保單本身作轉移，並非一定要以抵押品作貸款抵押，故C描述不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项关于绝对转让是正确的?",o:["保单转让给保险人","保单变成不可异议","保单只可以是不分红保单","转让是永久性的,承让人成为新的保单所有人"],a:3,e:"绝对转让属永久性安排，承让人成为新的保单所有人，D正确。转让并非将保单转给保险人，亦不影响保单的不可异议性，且不限于不分红保单，故其余三项错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項關於絕對轉讓是正確的？",o:["保單轉讓給保險人","保單變成不可異議","保單只可以是不分紅保單","轉讓是永久性的，承讓人成為新的保單所有人"],e:"絕對轉讓屬永久性安排，承讓人成為新的保單所有人，D正確。轉讓並非將保單轉給保險人，亦不影響保單的不可異議性，且不限於不分紅保單，故其餘三項錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项对寿险保单的「自动红利」选择的陈述是正确的﹖",o:["保证红利的分配方式","红利的分配方式总是得一种","所有保单持有人均没有红利分配方式的选择权","除非保单持有人指明选择,否则便会采用的一项分配方式"],a:3,e:"自动红利选择是指保单持有人未明确选择时保险人自动采用的默认分配方式，D正确。它并非保证红利的分配方式，分配方式亦不止一种，且持有人享有选择权，故前三项错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項對壽險保單的「自動紅利」選擇的陳述是正確的﹖",o:["保證紅利的分配方式","紅利的分配方式總是得一種","所有保單持有人均沒有紅利分配方式的選擇權","除非保單持有人指明選擇，否則便會採用的一項分配方式"],e:"自動紅利選擇是指保單持有人未明確選擇時保險人自動採用的默認分配方式，D正確。它並非保證紅利的分配方式，分配方式亦不止一種，且持有人享有選擇權，故前三項錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项对转让的评论不正确?",o:["保单所有人是转让人","第三者是承让人","保单可当作出售或作为礼物","必须获得保险人同意"],a:3,e:"转让中保单所有人是转让人、接受转让的第三者是承让人，且可因代价（出售）或作为礼物作出，A、B、C均正确。转让一般只须书面通知保险人，并非必须取得保险人同意，故D不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項對轉讓的評論不正確？",o:["保單所有人是轉讓人","第三者是承讓人","保單可當作出售或作為禮物","必須獲得保險人同意"],e:"轉讓中保單所有人是轉讓人、接受轉讓的第三者是承讓人，且可因代價（出售）或作為禮物作出，A、B、C均正確。轉讓一般只須書面通知保險人，並非必須取得保險人同意，故D不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项属于对受益人的概括式指定?",o:["「本人的子女」","「本人的亲生兄弟姐妹」","「本人在第一段婚姻的子女」","以上各项皆是"],a:3,e:"「本人的子女」「亲生兄弟姐妹」「第一段婚姻的子女」均以类别方式描述一群人而非逐一点名，皆属概括式指定，故D「以上各项皆是」正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項屬於對受益人的概括式指定？",o:["「本人的子女」","「本人的親生兄弟姐妹」","「本人在第一段婚姻的子女」","以上各項皆是"],e:"「本人的子女」「親生兄弟姐妹」「第一段婚姻的子女」均以類別方式描述一羣人而非逐一點名，皆屬概括式指定，故D「以上各項皆是」正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项并非是寿险保单中的转让限制?",o:["不能为非法目的而安排","只能以现金进行","规定一笔过支付利益于承让人","不得侵犯任何受益人的既得利益"],a:1,e:"寿险保单的转让限制包括不得为非法目的安排、不得侵犯受益人的既得利益等，但并无「只能以现金进行」的限制，转让可以代价或馈赠方式完成。故B并非转让限制。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項並非是壽險保單中的轉讓限制？",o:["不能為非法目的而安排","只能以現金進行","規定一筆過支付利益於承讓人","不得侵犯任何受益人的既得利益"],e:"壽險保單的轉讓限制包括不得為非法目的安排、不得侵犯受益人的既得利益等，但並無「只能以現金進行」的限制，轉讓可以代價或饋贈方式完成。故B並非轉讓限制。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关完整合约条款是正确的?",o:["包括保险单以及夹付的投保单复印本","只有保险公司的指定高级职员才有权更改保险合约","除非得到保单所有人同意,否则不能对保险合约作出任何修改","以上各项都正确"],a:3,e:"完整合约条款规定保险合约由保险单及夹付的投保单复印本组成，且只有保险公司指定高级职员有权更改，并须经保单所有人同意才能修改，三项均正确，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關完整合約條款是正確的？",o:["包括保險單以及夾付的投保單複印本","只有保險公司的指定高級職員才有權更改保險合約","除非得到保單所有人同意，否則不能對保險合約作出任何修改","以上各項都正確"],e:"完整合約條款規定保險合約由保險單及夾付的投保單複印本組成，且只有保險公司指定高級職員有權更改，並須經保單所有人同意才能修改，三項均正確，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关宽限期的陈述是不正确的?",o:["一般为期14日","适用于保单的首期保费","提供免费的保险期","以上所有答案都不正确"],a:3,e:"香港寿险宽限期一般为30至31日而非14日，且不适用于首期保费；宽限期内未缴保费会在给付时扣除，并非免费保险期。所列三项陈述均不正确，故选「以上所有答案都不正确」。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關寬限期的陳述是不正確的？",o:["一般為期14日","適用於保單的首期保費","提供免費的保險期","以上所有答案都不正確"],e:"香港壽險寬限期一般為30至31日而非14日，且不適用於首期保費；寬限期內未繳保費會在給付時扣除，並非免費保險期。所列三項陳述均不正確，故選「以上所有答案都不正確」。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关宽限期的陈述是不正确的? i 在香港,宽限期的上限是15日 ii 保单持有人可于宽限期完结之后及受保生命死亡之前支付保费 iii 宽限期并非提供免费的保险期 iv 宽限期适用于首期保费",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上所有答案都不正确"],a:1,e:"宽限期上限并非15日而是约30/31日，且宽限期不适用于首期保费，故i、iv错误。iii（并非免费保险期）及ii正确，故不正确的组合为i、ii、iv。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關寬限期的陳述是不正確的？ i 在香港，寬限期的上限是15日 ii 保單持有人可於寬限期完結之後及受保生命死亡之前支付保費 iii 寬限期並非提供免費的保險期 iv 寬限期適用於首期保費",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上所有答案都不正確"],e:"寬限期上限並非15日而是約30/31日，且寬限期不適用於首期保費，故i、iv錯誤。iii（並非免費保險期）及ii正確，故不正確的組合為i、ii、iv。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关宽限期的陈述是正确的?",o:["并非免费的保险期","不适用于首期保费","宽限期内缴费会被视作准时","以上皆是正确的"],a:3,e:"宽限期并非免费的保险期，不适用于首期保费，且宽限期内缴费会被视作准时缴付，三项陈述均正确，故D「以上皆是正确的」为答案。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關寬限期的陳述是正確的？",o:["並非免費的保險期","不適用於首期保費","寬限期內繳費會被視作準時","以上皆是正確的"],e:"寬限期並非免費的保險期，不適用於首期保費，且寬限期內繳費會被視作準時繳付，三項陳述均正確，故D「以上皆是正確的」為答案。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关抵押转让的陈述是正确的?",o:["转让是永久性的安排","承让人对保单享有无限权益","抵押转让后保单仍可向保险人贷款或退保","以上所有各项皆不正确"],a:3,e:"抵押转让是暂时性安排、只为担保贷款，承让人仅享有有限权益而非无限权益，且转让后保单一般不可再向保险人贷款或退保。三项描述均错，故D「以上所有各项皆不正确」正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關抵押轉讓的陳述是正確的？",o:["轉讓是永久性的安排","承讓人對保單享有無限權益","抵押轉讓後保單仍可向保險人貸款或退保","以上所有各項皆不正確"],e:"抵押轉讓是暫時性安排、只為擔保貸款，承讓人僅享有有限權益而非無限權益，且轉讓後保單一般不可再向保險人貸款或退保。三項描述均錯，故D「以上所有各項皆不正確」正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关绝对转让及抵押转让的陈述是不正确的?",o:["绝对转让是永久性的安排","在抵押转让的情况下,保单抵押贷款或退保是不可能的","抵押转让的承让人对保单享有无限权益","抵押转让可能以保单作为贷款的抵押品"],a:2,e:"绝对转让为永久性、抵押转让下承让人仅有有限权益（限于贷款及利息），且抵押转让可以保单作为贷款抵押品。A、B、D均正确，只有C「无限权益」错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關絕對轉讓及抵押轉讓的陳述是不正確的？",o:["絕對轉讓是永久性的安排","在抵押轉讓的情況下，保單抵押貸款或退保是不可能的","抵押轉讓的承讓人對保單享有無限權益","抵押轉讓可能以保單作為貸款的抵押品"],e:"絕對轉讓為永久性、抵押轉讓下承讓人僅有有限權益（限於貸款及利息），且抵押轉讓可以保單作為貸款抵押品。A、B、D均正確，只有C「無限權益」錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关绝对转让的陈述是正确的?",o:["绝对转让是指保单转换保险人","绝对转让通常在原保单持有人破产的情况下进行","承让人成为新的保单持有人","以上所有皆不正确"],a:2,e:"绝对转让中承接人成为新的保单所有人，C正确。绝对转让并非将保单转换保险人，亦非仅在原持有人破产时才进行，故A、B及D皆不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關絕對轉讓的陳述是正確的？",o:["絕對轉讓是指保單轉換保險人","絕對轉讓通常在原保單持有人破產的情況下進行","承讓人成為新的保單持有人","以上所有皆不正確"],e:"絕對轉讓中承接人成為新的保單所有人，C正確。絕對轉讓並非將保單轉換保險人，亦非僅在原持有人破產時才進行，故A、B及D皆不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项描述是不能作废条款的主要用途?",o:["保险人无抵押贷款","现金价值用作支付保费","保单持有人随时提款","保单持有人可提出借贷以支付保费"],a:1,e:"不能作废条款的主要用途是让保单持有人在断供时利用现金价值垫缴保费，使保单不致失效，故B正确。它并非无抵押贷款或随时提款，其余选项非其主要用途。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項描述是不能作廢條款的主要用途？",o:["保險人無抵押貸款","現金價值用作支付保費","保單持有人隨時提款","保單持有人可提出借貸以支付保費"],e:"不能作廢條款的主要用途是讓保單持有人在斷供時利用現金價值墊繳保費，使保單不致失效，故B正確。它並非無抵押貸款或隨時提款，其餘選項非其主要用途。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是「自杀条款」的不正确描述?",o:["自杀被列为除外责任","此条款通常为期一年","保单生效初期被列为除外责任","保单生效首年自杀将获退回所缴保费"],a:0,e:"自杀条款只将保单生效初期（通常一至两年）的自杀列为除外责任，而非笼统说自杀一律为除外责任，故A表述不准确。B、C、D关于期限及退回保费的描述均正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是「自殺條款」的不正確描述？",o:["自殺被列為除外責任","此條款通常為期一年","保單生效初期被列為除外責任","保單生效首年自殺將獲退回所繳保費"],e:"自殺條款只將保單生效初期（通常一至兩年）的自殺列為除外責任，而非籠統說自殺一律為除外責任，故A表述不準確。B、C、D關於期限及退回保費的描述均正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是不能作废条款的主要用途?",o:["保单保额不可扣减","保险人不可取消保单","保单不会因未缴付保费而失效","保单不会因未还清贷款而失效"],a:2,e:"不能作废条款的核心作用是保单不会因未缴付保费而失效，即借助现金价值维持保障，故C正确。它并非指保额不可扣减或保单绝不可被取消，A、B、D错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是不能作廢條款的主要用途？",o:["保單保額不可扣減","保險人不可取消保單","保單不會因未繳付保費而失效","保單不會因未還清貸款而失效"],e:"不能作廢條款的核心作用是保單不會因未繳付保費而失效，即藉助現金價值維持保障，故C正確。它並非指保額不可扣減或保單絕不可被取消，A、B、D錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是保单不常见的不能作废条款?",o:["购买减额清缴保险","即时提取保险利益","利用现金价值购买展期保险","以上其中一项"],a:1,e:"不能作废条款的常见选择包括购买减额清缴保险及利用现金价值购买展期保险，A、C均常见。「即时提取保险利益」并非此类条款的常见安排，故B为答案。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是保單不常見的不能作廢條款?",o:["購買減額清繳保險","即時提取保險利益","利用現金價值購買展期保險","以上其中一項"],e:"不能作廢條款的常見選擇包括購買減額清繳保險及利用現金價值購買展期保險，A、C均常見。「即時提取保險利益」並非此類條款的常見安排，故B為答案。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是保单复效的条件?",o:["缴付复效费","提供可保性的证明","缴清未缴保费及利息","以上各项皆是"],a:3,e:"保单复效通常须缴付复效费、提供可保性证明，并缴清未缴保费及利息，三项条件皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是保單復效的條件？",o:["繳付復效費","提供可保性的證明","繳清未繳保費及利息","以上各項皆是"],e:"保單復效通常須繳付復效費、提供可保性證明，並繳清未繳保費及利息，三項條件皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是寿险保单的自杀条款的陈述是不正确?",o:["一般而言,自杀最少于首年被列为除外责任","当指明的自杀期间过后,自杀不会影响有关的索偿","自杀是违法的,因此不会获支付索偿","在指明的首段期间内自杀可能获退回保费"],a:2,e:"自杀并非法律上一律不获赔付：免责期内自杀一般退回保费，期满后自杀则会获赔。A、B、D描述正确，只有C「自杀违法故不赔」错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是壽險保單的自殺條款的陳述是不正確？",o:["一般而言，自殺最少於首年被列為除外責任","當指明的自殺期間過後，自殺不會影響有關的索償","自殺是違法的，因此不會獲支付索償","在指明的首段期間內自殺可能獲退回保費"],e:"自殺並非法律上一律不獲賠付：免責期內自殺一般退回保費，期滿後自殺則會獲賠。A、B、D描述正確，只有C「自殺違法故不賠」錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是形容「自杀条款」的?",o:["任何时间自杀为除外责任","保单生效初期(通常一年)自杀列为除外责任","保单生效后自杀可取得50%死亡金","任何时间下自杀均不会影响死亡金给付"],a:1,e:"自杀条款是将保单生效初期（通常一年，香港亦有两年）的自杀列为除外责任，故B正确。自杀并非任何时间都除外，也无固定赔50%死亡金的规定，A、C、D错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是形容「自殺條款」的？",o:["任何時間自殺為除外責任","保單生效初期（通常一年）自殺列為除外責任","保單生效後自殺可取得50%死亡金","任何時間下自殺均不會影響死亡金給付"],e:"自殺條款是將保單生效初期（通常一年，香港亦有兩年）的自殺列為除外責任，故B正確。自殺並非任何時間都除外，也無固定賠50%死亡金的規定，A、C、D錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项有关不能作废条款的陈述是不正确的?",o:["是不可异议条款的另一个名称","不会因中断缴付保费而失效","除非收到相反指示,现金价值会用以支付保费","作为「自动保费贷款」的规定"],a:0,e:"不能作废条款与不可异议条款是两条不同条款，前者针对断供不失效、后者针对承保期的争议，故A「是另一个名称」错误。B、C、D关于现金价值垫付保费的描述均正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項有關不能作廢條款的陳述是不正確的？",o:["是不可異議條款的另一個名稱","不會因中斷繳付保費而失效","除非收到相反指示，現金價值會用以支付保費","作為「自動保費貸款」的規定"],e:"不能作廢條款與不可異議條款是兩條不同條款，前者針對斷供不失效、後者針對承保期的爭議，故A「是另一個名稱」錯誤。B、C、D關於現金價值墊付保費的描述均正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项有关人寿保单的转让是不正确?",o:["转让保单的人称为承让人","获转让保单的对象称为转让人","所有转让必须涉及代价,这是合约元素之一","以上所有皆不正确"],a:3,e:"转让保单者称转让人、获转让者称承让人，A、B方向对调。转让可以礼物等无偿方式进行，并非必须涉及代价，故C亦错，选「以上所有皆不正确」。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項有關人壽保單的轉讓是不正確？",o:["轉讓保單的人稱為承讓人","獲轉讓保單的對象稱為轉讓人","所有轉讓必須涉及代價，這是合約元素之一","以上所有皆不正確"],e:"轉讓保單者稱轉讓人、獲轉讓者稱承讓人，A、B方向對調。轉讓可以禮物等無償方式進行，並非必須涉及代價，故C亦錯，選「以上所有皆不正確」。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项有关保单抵押贷款的陈述是正确的?",o:["保险人决定是否批核","指定用途才可","贷款无上限","以上皆否"],a:3,e:"保单抵押贷款由保单所有人依现金价值决定借入，保险人不得任意拒绝，用途亦无限制，且贷款有上限（不超过扣除利息后的现金价值）。A、B、C均错，故D「以上皆否」正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項有關保單抵押貸款的陳述是正確的？",o:["保險人決定是否批核","指定用途才可","貸款無上限","以上皆否"],e:"保單抵押貸款由保單所有人依現金價值決定借入，保險人不得任意拒絕，用途亦無限制，且貸款有上限（不超過扣除利息後的現金價值）。A、B、C均錯，故D「以上皆否」正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项有关抵押转让的描述是正确的?",o:["转让是永久性的","承让人对保单拥有没有上限 (约束) 的权力","转让后仍然可以进行保单抵押贷款或退保","以上各项皆不正确"],a:3,e:"抵押转让属暂时性安排，承让人仅享有有限权益（贷款及利息），且转让后保单不可再作贷款或退保。A、B、C均错，故选D「以上各项皆不正确」。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項有關抵押轉讓的描述是正確的？",o:["轉讓是永久性的","承讓人對保單擁有沒有上限 (約束) 的權力","轉讓後仍然可以進行保單抵押貸款或退保","以上各項皆不正確"],e:"抵押轉讓屬暫時性安排，承讓人僅享有有限權益（貸款及利息），且轉讓後保單不可再作貸款或退保。A、B、C均錯，故選D「以上各項皆不正確」。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项有关自杀免责期的陈述是正确的?",o:["一般情况下,自杀是人寿保单生效初期的除外责任","过了自杀免责期后,自杀便不再是除外责任","在自杀免责期内,亦可能有通融赔付","以上所有皆正确"],a:3,e:"一般情况下自杀是寿险保单生效初期的除外责任，过了免责期后自杀便不再是除外责任，而在免责期内亦可能有通融赔付或退回保费，三项均正确，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項有關自殺免責期的陳述是正確的？",o:["一般情況下，自殺是人壽保單生效初期的除外責任","過了自殺免責期後，自殺便不再是除外責任","在自殺免責期內，亦可能有通融賠付","以上所有皆正確"],e:"一般情況下自殺是壽險保單生效初期的除外責任，過了免責期後自殺便不再是除外責任，而在免責期內亦可能有通融賠付或退回保費，三項均正確，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项正确描述保单转让:",o:["只有保单保险金才可转让","转让可能要付出代价(即付款)或作为礼物赠送","承让人必须有可保权益","上述所有各项"],a:1,e:"保单转让可以付出代价（付款）或作为礼物无偿进行，故B正确。所转让的是保单的权益而非仅保险金，且承让人无须具备可保权益，A、C、D错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項正確描述保單轉讓：",o:["只有保單保險金才可轉讓","轉讓可能要付出代價（即付款）或作為禮物贈送","承讓人必須有可保權益","上述所有各項"],e:"保單轉讓可以付出代價（付款）或作為禮物無償進行，故B正確。所轉讓的是保單的權益而非僅保險金，且承讓人無須具備可保權益，A、C、D錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项正确描述宽限期?",o:["宽限在十五日以内","他不是免费保险期","保费可于宽限期及死亡前退还","以上各项"],a:1,e:"香港寿险宽限期一般为约30或31日，并非「十五日以内」；且因未缴保费会在给付时扣除，故宽限期并非免费保险期，B正确。A、C描述不准确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項正確描述寬限期？",o:["寬限在十五日以內","他不是免費保險期","保費可於寬限期及死亡前退還","以上各項"],e:"香港壽險寬限期一般為約30或31日，並非「十五日以內」；且因未繳保費會在給付時扣除，故寬限期並非免費保險期，B正確。A、C描述不準確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项误报年龄及性别的选项是不正确?",o:["美式惯例稍有别于英式惯例","如误报是重要的,保险人可以推翻保单","在保单索偿后,保险人可以更改利益保额","在保单索偿前,保险人可以更改保费或利益保额其中一项"],a:1,e:"误报年龄或性别一般按调整原则处理（改保费或改保额），而非直接推翻保单，故B「重要误报可推翻保单」不正确。A、C、D关于美英惯例差异及调整时机的描述均正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項誤報年齡及性別的選項是不正確?",o:["美式慣例稍有別於英式慣例","如誤報是重要的，保險人可以推翻保單","在保單索償後，保險人可以更改利益保額","在保單索償前，保險人可以更改保費或利益保額其中一項"],e:"誤報年齡或性別一般按調整原則處理（改保費或改保額），而非直接推翻保單，故B「重要誤報可推翻保單」不正確。A、C、D關於美英慣例差異及調整時機的描述均正確。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项陈述有关寿险中的不可异议条款是正确的? i 保单生效两年后寿险变成不可异议 ii 保单生效两年内受保生命仍然生存 iii 如涉及欺诈行为便可推翻此条款 iv 就算没有可保权益而建立的保单,都受到此条款限制",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:0,e:"不可异议条款规定保单生效两年后寿险即不可异议，但须以受保生命在该两年内仍生存为条件，且如涉及欺诈仍可推翻。i、ii、iii正确；无可保权益的保单不受此条款庇护，故iv错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項陳述有關壽險中的不可異議條款是正確的？ i 保單生效兩年後壽險變成不可異議 ii 保單生效兩年內受保生命仍然生存 iii 如涉及欺詐行為便可推翻此條款 iv 就算沒有可保權益而建立的保單，都受到此條款限制",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"不可異議條款規定保單生效兩年後壽險即不可異議，但須以受保生命在該兩年內仍生存為條件，且如涉及欺詐仍可推翻。i、ii、iii正確；無可保權益的保單不受此條款庇護，故iv錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"作出永久性转让,承让人成为新的保单持有人,称为:",o:["绝对转让","永久性转让","抵押转让","不可撤换转让"],a:0,e:"将保单权益永久转移、使承让人成为新的保单所有人的转让，称为绝对转让，故A正确。抵押转让为暂时性，另两项并非标准名称。",src:1,tw:{ch:"闡釋人壽保險單",q:"作出永久性轉讓，承讓人成為新的保單持有人，稱為:",o:["絕對轉讓","永久性轉讓","抵押轉讓","不可撤換轉讓"],e:"將保單權益永久轉移、使承讓人成為新的保單所有人的轉讓，稱為絕對轉讓，故A正確。抵押轉讓為暫時性，另兩項並非標準名稱。"}},
{p:3,ch:"阐释人寿保险单",q:"保单中可以列出以一群人为受益人,例如「我的子女」,这类受益人称为:",o:["概括式指定","特定受益人","不可撤换受益人","次顺位受益人"],a:0,e:"以「我的子女」这类以一群人为对象的受益人指定方式，称为概括式指定，故A正确。特定、不可撤换及次顺位受益人分别指其他情形。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單中可以列出以一羣人為受益人，例如「我的子女」，這類受益人稱為：",o:["概括式指定","特定受益人","不可撤換受益人","次順位受益人"],e:"以「我的子女」這類以一羣人為對象的受益人指定方式，稱為概括式指定，故A正確。特定、不可撤換及次順位受益人分別指其他情形。"}},
{p:3,ch:"阐释人寿保险单",q:"保单所有人不想再继续缴交保费,根据保单条文,以下哪项描述是不正确?",o:["购买减额清缴保险","退保获取现金价值","要求保险人免息贷款以支付交保费","运用现金价值购买展期寿险"],a:2,e:"停缴保费时可选择减额清缴保险、退保取现金价值或购买展期寿险，A、B、D均正确。保单贷款须付利息且以现金价值支撑，并不能要求保险人免息贷款缴保费，故C错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單所有人不想再繼續繳交保費，根據保單條文，以下哪項描述是不正確？",o:["購買減額清繳保險","退保獲取現金價值","要求保險人免息貸款以支付交保費","運用現金價值購買展期壽險"],e:"停繳保費時可選擇減額清繳保險、退保取現金價值或購買展期壽險，A、B、D均正確。保單貸款須付利息且以現金價值支撐，並不能要求保險人免息貸款繳保費，故C錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"保单所有人可以向保险人借入款项,以下哪项陈述是正确的?",o:["保单所有人可以不偿还贷款","贷款与否由保险人自行决定","贷款用途只可用作缴付保费","以上所有各项皆正确"],a:0,e:"保单所有人有借款权利，贷款可不偿还而于给付时扣除，故A正确。是否贷款由保单所有人而非保险人决定，用途亦不限，B、C错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單所有人可以向保險人借入款項，以下哪項陳述是正確的？",o:["保單所有人可以不償還貸款","貸款與否由保險人自行決定","貸款用途只可用作繳付保費","以上所有各項皆正確"],e:"保單所有人有借款權利，貸款可不償還而於給付時扣除，故A正確。是否貸款由保單所有人而非保險人決定，用途亦不限，B、C錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"保单所有人有权使已失效的保单重新生效,但会受到下列哪项/些条件限制?",o:["缴付任何未缴清的贷款及利息","指定期限后不能进行","补付已到期但未缴清的保费及利息","以上所有各项"],a:3,e:"复效须缴清任何未缴清的贷款及利息，补付已到期未缴的保费及利息，并受指定期限限制，三项条件皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單所有人有權使已失效的保單重新生效，但會受到下列哪項/些條件限制？",o:["繳付任何未繳清的貸款及利息","指定期限後不能進行","補付已到期但未繳清的保費及利息","以上所有各項"],e:"復效須繳清任何未繳清的貸款及利息，補付已到期未繳的保費及利息，並受指定期限限制，三項條件皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"保单抵押货款可借取:",o:["保单中的$1,000","保单中的$20,000","现金价值的50%","扣除一年利息的保单现金价值"],a:3,e:"保单抵押贷款的可借上限为扣除一年利息后的保单现金价值，故D正确。其余固定金额或50%均非标准上限。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單抵押貨款可借取:",o:["保單中的$1,000","保單中的$20,000","現金價值的50%","扣除一年利息的保單現金價值"],e:"保單抵押貸款的可借上限為扣除一年利息後的保單現金價值，故D正確。其餘固定金額或50%均非標準上限。"}},
{p:3,ch:"阐释人寿保险单",q:"保单抵押贷款的上限为:",o:["$100,000","$500,000","扣除一年利息的保单现金价值","没有上限"],a:2,e:"保单抵押贷款的上限为扣除一年利息后的保单现金价值，故C正确，其余固定金额或「没有上限」均不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單抵押貸款的上限為：",o:["$100,000","$500,000","扣除一年利息的保單現金價值","沒有上限"],e:"保單抵押貸款的上限為扣除一年利息後的保單現金價值，故C正確，其餘固定金額或「沒有上限」均不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"保单生效了4年,受保保单所有人自杀,保险人会作出以下行动:",o:["因自杀免责期,保险人拒绝赔偿","因为自杀,所以只赔偿50%死亡金","赔偿不受影响","根据刑事法,保险人拒绝赔偿"],a:2,e:"自杀免责期一般为保单生效后一至两年，保单已生效4年，自杀已超出免责期，赔偿不受影响，故C正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單生效了4年，受保保單所有人自殺，保險人會作出以下行動:",o:["因自殺免責期，保險人拒絕賠償","因為自殺，所以只賠償50%死亡金","賠償不受影響","根據刑事法，保險人拒絕賠償"],e:"自殺免責期一般為保單生效後一至兩年，保單已生效4年，自殺已超出免責期，賠償不受影響，故C正確。"}},
{p:3,ch:"阐释人寿保险单",q:"保单的「完整合约」条款,双方所同意的保单更改:",o:["只能于保单续保时作出","只能由保险公司的某些高级职员作出","只能包含于一份新的替代保单中","可由保险公司的任何职员作出"],a:1,e:"根据完整合约条款，保单的更改只能由保险公司的某些指定高级职员作出，故B正确。续保时、替代保单或任何职员均可更改均不符合条款要求。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單的「完整合約」條款，雙方所同意的保單更改：",o:["只能於保單續保時作出","只能由保險公司的某些高級職員作出","只能包含於一份新的替代保單中","可由保險公司的任何職員作出"],e:"根據完整合約條款，保單的更改只能由保險公司的某些指定高級職員作出，故B正確。續保時、替代保單或任何職員均可更改均不符合條款要求。"}},
{p:3,ch:"阐释人寿保险单",q:"保单转让包括抵押转让及:",o:["暂时转让","绝对转让","优先转让","限期转让"],a:1,e:"保单转让分为抵押转让与绝对转让两种基本类型，故B正确。其余名称并非法定转让分类。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單轉讓包括抵押轉讓及：",o:["暫時轉讓","絶對轉讓","優先轉讓","限期轉讓"],e:"保單轉讓分為抵押轉讓與絕對轉讓兩種基本類型，故B正確。其餘名稱並非法定轉讓分類。"}},
{p:3,ch:"阐释人寿保险单",q:"保单进行转让后,在给付任何保险金之前,保险人有权先扣除:",o:["过期未付的保费","未付的保单贷款","未付的利息","包括以上各项"],a:3,e:"保单转让后、给付保险金前，保险人有权先扣除过期未付的保费、未付保单贷款及未付利息，三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單進行轉讓後，在給付任何保險金之前，保險人有權先扣除：",o:["過期未付的保費","未付的保單貸款","未付的利息","包括以上各項"],e:"保單轉讓後、給付保險金前，保險人有權先扣除過期未付的保費、未付保單貸款及未付利息，三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"保单进行转让时,获转让的人称为:",o:["转让人","承让人","被转让人","转让受益人"],a:1,e:"保单转让中获转让的一方称为承让人（受让人），故B正确。转让人是原保单所有人，其余为干扰项。",src:1,tw:{ch:"闡釋人壽保險單",q:"保單進行轉讓時，獲轉讓的人稱為：",o:["轉讓人","承讓人","被轉讓人","轉讓受益人"],e:"保單轉讓中獲轉讓的一方稱為承讓人（受讓人），故B正確。轉讓人是原保單所有人，其餘為干擾項。"}},
{p:3,ch:"阐释人寿保险单",q:"保险人认为保单持有人于投保后一年内去世有可疑地方,但找不到自杀的证据,这样:",o:["法庭将假定投保人自杀","保险人仍需全数赔付","保险人将赔付一半之死亡保险金","保险人按通融赔付"],a:1,e:"若找不到自杀证据，法庭不会假定投保人自杀，保险人仍需全数赔付死亡保险金，故B正确。半额赔付或通融赔付均无依据。",src:1,tw:{ch:"闡釋人壽保險單",q:"保險人認為保單持有人於投保後一年內去世有可疑地方，但找不到自殺的證據，這樣：",o:["法庭將假定投保人自殺","保險人仍需全數賠付","保險人將賠付一半之死亡保險金","保險人按通融賠付"],e:"若找不到自殺證據，法庭不會假定投保人自殺，保險人仍需全數賠付死亡保險金，故B正確。半額賠付或通融賠付均無依據。"}},
{p:3,ch:"阐释人寿保险单",q:"保险合约的权益需要满足哪些条件才能法定转让?",o:["保险合约的权益属于据法权产","藉某些订明手续来转让据法权产","权益属于其可保权益","权益属于实际、现时、延时权益"],a:1,e:"保险合约的权益属据法权产，须依据订明手续（书面、绝对转让并发出书面通知）才能法定转让，故B正确。其余选项非转让的法定条件。",src:1,tw:{ch:"闡釋人壽保險單",q:"保險合約的權益需要滿足哪些條件才能法定轉讓？",o:["保險合約的權益屬於據法權產","藉某些訂明手續來轉讓據法權產","權益屬於其可保權益","權益屬於實際、現時、延時權益"],e:"保險合約的權益屬據法權產，須依據訂明手續（書面、絕對轉讓併發出書面通知）才能法定轉讓，故B正確。其餘選項非轉讓的法定條件。"}},
{p:3,ch:"阐释人寿保险单",q:"保险金赔付方式有很多种。以下哪项是选择赔付的方式?",o:["保单所有人只可整笔给付","第三者保单只可赚取利息收入","保险人按照自己喜好而选择","保单所有人/受益人有很多选择方式"],a:3,e:"保险金的赔付有多种方式，由保单所有人或受益人从中选择，而非只可整笔、只赚利息或由保险人任意决定，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"保險金賠付方式有很多種。以下哪項是選擇賠付的方式？",o:["保單所有人只可整筆給付","第三者保單只可賺取利息收入","保險人按照自己喜好而選擇","保單所有人/受益人有很多選擇方式"],e:"保險金的賠付有多種方式，由保單所有人或受益人從中選擇，而非只可整筆、只賺利息或由保險人任意決定，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"假若年龄或性别的误报是在索偿前发现,其中一种香港常见的做法是:",o:["保单即时无效,以及保费作废","保额永远不能向上或向下调整","保单取消,退回全数保费","保额不变,同时适当地调整保费"],a:3,e:"索偿前发现年龄或性别误报，香港常见做法是保留原保额不变，同时适当调高或调低保费，故D正确。并非即时失效或取消保单。",src:1,tw:{ch:"闡釋人壽保險單",q:"假若年齡或性別的誤報是在索償前發現，其中一種香港常見的做法是：",o:["保單即時無效，以及保費作廢","保額永遠不能向上或向下調整","保單取消，退回全數保費","保額不變，同時適當地調整保費"],e:"索償前發現年齡或性別誤報，香港常見做法是保留原保額不變，同時適當調高或調低保費，故D正確。並非即時失效或取消保單。"}},
{p:3,ch:"阐释人寿保险单",q:"假设没有不能作废条款情况下,宽限期内没有缴付保费,则保单便:",o:["失效","被取消","变成不可异议","需要缴交较高保费,保单才可继续生效"],a:0,e:"在无不能作废条款的情况下，宽限期内仍未缴付保费，保单便会失效（lapse），故A正确。保单不是被取消、亦不会变成不可异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"假設沒有不能作廢條款情況下，寬限期內沒有繳付保費，則保單便：",o:["失效","被取消","變成不可異議","需要繳交較高保費，保單才可繼續生效"],e:"在無不能作廢條款的情況下，寬限期內仍未繳付保費，保單便會失效（lapse），故A正確。保單不是被取消、亦不會變成不可異議。"}},
{p:3,ch:"阐释人寿保险单",q:"关于保单贷款,以下哪项陈述是正确的?",o:["需要一年内偿还","只可用作支付保费","如不偿还,贷款连利息于支付保险利益时扣除","要求独立的质押担保"],a:2,e:"保单贷款不要求一年内偿还、用途不限，亦无须独立质押担保，若不偿还则于给付保险利益时连同利息一并扣除，故C正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"關於保單貸款，以下哪項陳述是正確的？",o:["需要一年內償還","只可用作支付保費","如不償還，貸款連利息於支付保險利益時扣除","要求獨立的質押擔保"],e:"保單貸款不要求一年內償還、用途不限，亦無須獨立質押擔保，若不償還則於給付保險利益時連同利息一併扣除，故C正確。"}},
{p:3,ch:"阐释人寿保险单",q:"关于完整合约条款正确的是?",o:["保险人可以随意更改合约","只有保单所有人同意才可以更改合约内容","指定的高级职员可以直接更改合约","完整合约又称开放式合约"],a:1,e:"完整合约条款规定，保险合约内容须经保单所有人同意方可更改，故B正确。保险人不可随意更改，指定职员亦须在持人同意下进行。",src:1,tw:{ch:"闡釋人壽保險單",q:"關於完整合約條款正確的是？",o:["保險人可以隨意更改合約","只有保單所有人同意才可以更改合約內容","指定的高級職員可以直接更改合約","完整合約又稱開放式合約"],e:"完整合約條款規定，保險合約內容須經保單所有人同意方可更改，故B正確。保險人不可隨意更改，指定職員亦須在持人同意下進行。"}},
{p:3,ch:"阐释人寿保险单",q:"关于宽限期的叙述,哪些是错误的?",o:["宽限期一般至少是30或31日","宽限期不适用于保单首期保费","宽限期内缴交的保费视为准时缴付","这是免费的保险期"],a:3,e:"宽限期一般至少为30或31日、不适用于首期保费，且宽限期内缴费视为准时，A、B、C均正确。宽限期并非免费保险期，故D错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"關於寬限期的敘述，哪些是錯誤的？",o:["寬限期一般至少是30或31日","寬限期不適用於保單首期保費","寬限期內繳交的保費視為準時繳付","這是免費的保險期"],e:"寬限期一般至少為30或31日、不適用於首期保費，且寬限期內繳費視為準時，A、B、C均正確。寬限期並非免費保險期，故D錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"分红保单的现金红利于甚么情况下派发给保单持有人?",o:["即时","按照保险人的决定","如果他作出书面要求,可以变为可动用资产","只有在支付保单利益的时候"],a:0,e:"美式保单的现金红利通常即时派发予保单持有人，故A正确。其余按保险人决定、须书面要求或仅于付保额时派发均非现金红利的即时给付方式。",src:1,tw:{ch:"闡釋人壽保險單",q:"分紅保單的現金紅利於甚麼情況下派發給保單持有人？",o:["即時","按照保險人的決定","如果他作出書面要求，可以變為可動用資產","只有在支付保單利益的時候"],e:"美式保單的現金紅利通常即時派發予保單持有人，故A正確。其餘按保險人決定、須書面要求或僅於付保額時派發均非現金紅利的即時給付方式。"}},
{p:3,ch:"阐释人寿保险单",q:"分红寿险保单的红利选择包括: i 即时以现金给付 ii 存于保险人处以赚取利息 iii 若保单所有人没有选择,保险人便采用「自动红利选择」 iv 若保单所有人没有选择,便放弃了红利",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:0,e:"分红保单的红利选择包括即时以现金给付、存于保险人处赚取利息，及未选择时采用自动红利选择，i、ii、iii正确。未作选择并不会放弃红利，故iv错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"分紅壽險保單的紅利選擇包括： i 即時以現金給付 ii 存於保險人處以賺取利息 iii 若保單所有人沒有選擇，保險人便採用「自動紅利選擇」 iv 若保單所有人沒有選擇，便放棄了紅利",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"分紅保單的紅利選擇包括即時以現金給付、存於保險人處賺取利息，及未選擇時採用自動紅利選擇，i、ii、iii正確。未作選擇並不會放棄紅利，故iv錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"受保人去世后,发现年龄不对,那么按照北美一般习惯该如何处理?",o:["仅赔偿50%","根据年龄调整赔付金额","不进行赔偿","要回保费并要求赔偿"],a:1,e:"受保人去世（索偿）后才发现年龄误报，按北美一般习惯应根据实际年龄调整赔付金额，故B正确，而非仅赔50%或不作赔偿。",src:1,tw:{ch:"闡釋人壽保險單",q:"受保人去世後，發現年齡不對，那麽按照北美一般習慣該如何處理？",o:["僅賠償50%","根據年齡調整賠付金額","不進行賠償","要回保費並要求賠償"],e:"受保人去世（索償）後才發現年齡誤報，按北美一般習慣應根據實際年齡調整賠付金額，故B正確，而非僅賠50%或不作賠償。"}},
{p:3,ch:"阐释人寿保险单",q:"受制于某些条件下,一份已失效的保单可恢复有效。这个过程称为:",o:["续保","复原","复效","条件重订"],a:2,e:"受某些条件限制下使已失效保单恢复有效的过程称为复效（reinstatement），故C正确。续保、复原均非此专有名称。",src:1,tw:{ch:"闡釋人壽保險單",q:"受制於某些條件下，一份已失效的保單可恢復有效。這個過程稱為：",o:["續保","復原","復效","條件重訂"],e:"受某些條件限制下使已失效保單恢復有效的過程稱為復效（reinstatement），故C正確。續保、復原均非此專有名稱。"}},
{p:3,ch:"阐释人寿保险单",q:"受益人于给付保单利益时有许多不同的赔付选择,包括:",o:["以购买公司股票代替现金支付","分期支付保单收益及利息","保单收益以整付保费购买一份定期寿险","以上所有各项"],a:1,e:"保单赔付选择包括分期支付保单收益及利息，故B正确。赔付不能被用来购买公司股票或改购一份定期寿险，A、C错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"受益人於給付保單利益時有許多不同的賠付選擇，包括：",o:["以購買公司股票代替現金支付","分期支付保單收益及利息","保單收益以整付保費購買一份定期壽險","以上所有各項"],e:"保單賠付選擇包括分期支付保單收益及利息，故B正確。賠付不能被用來購買公司股票或改購一份定期壽險，A、C錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"哪一项是转让法律据法权产?",o:["法律修订(综合)条例","法律改革(综合)条例","法律修订及改革(综合)条例","法律转让产权"],a:2,e:"转让据法权产的法定依据是《法律修订及改革（综合）条例》，故C正确。其余名称非香港订明转让据法权产的条例。",src:1,tw:{ch:"闡釋人壽保險單",q:"哪一項是轉讓法律據法權產?",o:["法律修訂(綜合)條例","法律改革(綜合)條例","法律修訂及改革(綜合)條例","法律轉讓產權"],e:"轉讓據法權產的法定依據是《法律修訂及改革（綜合）條例》，故C正確。其餘名稱非香港訂明轉讓據法權產的條例。"}},
{p:3,ch:"阐释人寿保险单",q:"因为保单所有人外语名字,保单资料被误将女性填为男性,此为终身寿险保单,当发现错误时,被保 人坚持支付现时保费金额,保险人该如何处理?",o:["调整保单保额,以反映已缴付保费相符的正确保额","退回多收保费","撤销保单","保单保额向下调整"],a:0,e:"误将女性填为男性属年龄/性别误报，若持人坚持继续缴相同保费，保险人应调整保额以反映与已缴保费相符的正确保额，故A正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"因為保單所有人外語名字，保單資料被誤將女性填為男性，此為終身壽險保單，當發現錯誤時，被保 人堅持支付現時保費金額，保險人該如何處理？",o:["調整保單保額，以反映已繳付保費相符的正確保額","退回多收保費","撤銷保單","保單保額向下調整"],e:"誤將女性填為男性屬年齡/性別誤報，若持人堅持繼續繳相同保費，保險人應調整保額以反映與已繳保費相符的正確保額，故A正確。"}},
{p:3,ch:"阐释人寿保险单",q:"在人寿保单的转让中,会有甚么限制?",o:["只可转让给配偶","只可转让给有密切关系的家庭成员","只可转让给有可保权益的人士","无论承让人有否可保权益都可以转让"],a:3,e:"人寿保单的转让不限对象，无论承让人有否可保权益都可以转让，故D正确。并非只可转让给配偶或近亲、亦非必须有可保权益。",src:1,tw:{ch:"闡釋人壽保險單",q:"在人壽保單的轉讓中，會有甚麼限制？",o:["只可轉讓給配偶","只可轉讓給有密切關係的家庭成員","只可轉讓給有可保權益的人士","無論承讓人有否可保權益都可以轉讓"],e:"人壽保單的轉讓不限對象，無論承讓人有否可保權益都可以轉讓，故D正確。並非只可轉讓給配偶或近親、亦非必須有可保權益。"}},
{p:3,ch:"阐释人寿保险单",q:"在保单中的受益人指定受到「已婚者地位条例」所保护,以下那项的例子说明是正确的?",o:["受益人为保单持有人的配偶及/ 或子女,他们将成为此保单的法定持有人","受益人为保单持有人的配偶及/ 或子女,他们有权将保单随意更改","受益人为保单持有人的配偶及/ 或子女,他们将成为此保单的实益拥有人,直至保单持有人更改受益人为止","受益人为保单持有人的配偶及/ 或子女,他们将成为此保单的实益拥有人"],a:3,e:"根据《已婚者地位条例》，指定配偶及／或子女为受益人的寿险保单会构成法定信托，他们成为保单的实益拥有人，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"在保單中的受益人指定受到「已婚者地位條例」所保護，以下那項的例子說明是正確的?",o:["受益人為保單持有人的配偶及/ 或子女，他們將成為此保單的法定持有人","受益人為保單持有人的配偶及/ 或子女，他們有權將保單隨意更改","受益人為保單持有人的配偶及/ 或子女，他們將成為此保單的實益擁有人，直至保單持有人更改受益人為止","受益人為保單持有人的配偶及/ 或子女，他們將成為此保單的實益擁有人"],e:"根據《已婚者地位條例》，指定配偶及／或子女為受益人的壽險保單會構成法定信託，他們成為保單的實益擁有人，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"在变更受益人以前,必须得现有受益人书面同意。这种受益人称为:",o:["可撤换受益人","不换受益人","不可撤换受益人","非撤换受益人"],a:2,e:"变更前必须取得现有受益人书面同意的受益人，称为不可撤换受益人，故C正确。可撤换受益人则无须他人同意即可变更。",src:1,tw:{ch:"闡釋人壽保險單",q:"在變更受益人以前，必須得現有受益人書面同意。這種受益人稱為：",o:["可撤換受益人","不換受益人","不可撤換受益人","非撤換受益人"],e:"變更前必須取得現有受益人書面同意的受益人，稱為不可撤換受益人，故C正確。可撤換受益人則無須他人同意即可變更。"}},
{p:3,ch:"阐释人寿保险单",q:"在悲惨的情况下,受保保单所有人在他的妻子于交通意外身故后决定自杀。如果他本身的寿险保单生 效时间差一点才满一年,该份保单的情况是﹕",o:["他的死亡索偿可算有效","保单条款在这个案中将凌驾于自杀条款","不存在任何责任,但可给予「通融」赔付","可向法庭申请推翻有关自杀条款"],a:2,e:"保单生效不足一年即自杀，仍处自杀免责期内，保险人不承担死亡赔偿责任，但可给予通融赔付或退回保费，故C正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"在悲慘的情況下，受保保單所有人在他的妻子於交通意外身故後決定自殺。如果他本身的壽險保單生 效時間差一點才滿一年，該份保單的情況是﹕",o:["他的死亡索償可算有效","保單條款在這個案中將凌駕於自殺條款","不存在任何責任，但可給予「通融」賠付","可向法庭申請推翻有關自殺條款"],e:"保單生效不足一年即自殺，仍處自殺免責期內，保險人不承擔死亡賠償責任，但可給予通融賠付或退回保費，故C正確。"}},
{p:3,ch:"阐释人寿保险单",q:"在英式保单中,复效 (reinstatement) 称为",o:["保单复效","保单有效","保单效益","保单收益"],a:0,e:"英式保单中的复效（reinstatement）在香港称为保单复效，故A正确。其余名称并非英式保单中此概念的对应用语。",src:1,tw:{ch:"闡釋人壽保險單",q:"在英式保單中，復效 (reinstatement) 稱為",o:["保單復效","保單有效","保單效益","保單收益"],e:"英式保單中的復效（reinstatement）在香港稱為保單復效，故A正確。其餘名稱並非英式保單中此概念的對應用語。"}},
{p:3,ch:"阐释人寿保险单",q:"在香港,下列哪项保险市场倾向采用美国及北美常见的保单用语?",o:["一般保人寿保险市场","人寿保险市场","一般及人寿保险市场","以上各项都不是"],a:1,e:"香港的人寿保险市场倾向采用美国及北美常见的保单用语（如红利、宽限期等），故B正确，一般保险及两者皆采用的说法不准确。",src:1,tw:{ch:"闡釋人壽保險單",q:"在香港,下列哪項保險市場傾向採用美國及北美常見的保單用語？",o:["一般保人壽保險市場","人壽保險市場","一般及人壽保險市場","以上各項都不是"],e:"香港的人壽保險市場傾向採用美國及北美常見的保單用語（如紅利、寬限期等），故B正確，一般保險及兩者皆採用的說法不準確。"}},
{p:3,ch:"阐释人寿保险单",q:"在香港,人寿保险单所容许的「宽限期」一般为﹕",o:["最多7日","最多14日","最少30日(或 31日)","最少3个月(或 90日)"],a:2,e:"香港人寿保险单所容许的宽限期一般为最少30日（或31日），故C正确，而非7日、14日或90日。",src:1,tw:{ch:"闡釋人壽保險單",q:"在香港，人壽保險單所容許的「寬限期」一般為﹕",o:["最多7日","最多14日","最少30日(或 31日)","最少3個月(或 90日)"],e:"香港人壽保險單所容許的寬限期一般為最少30日（或31日），故C正確，而非7日、14日或90日。"}},
{p:3,ch:"阐释人寿保险单",q:"复归利益是指:",o:["未有的利益","现时可行使的利益","现在享有财产的权利但在未来才可享用","即时恢复利益的权利"],a:2,e:"复归利益是指现在已享有财产权利、但须待未来才可享用（既得但延期）的利益，故C正确。其余选项未准确表达其「现在权利、将来享用」的性质。",src:1,tw:{ch:"闡釋人壽保險單",q:"復歸利益是指：",o:["未有的利益","現時可行使的利益","現在享有財產的權利但在未來才可享用","即時恢復利益的權利"],e:"復歸利益是指現在已享有財產權利、但須待未來才可享用（既得但延期）的利益，故C正確。其餘選項未準確表達其「現在權利、將來享用」的性質。"}},
{p:3,ch:"阐释人寿保险单",q:"复效是保单持有人把已经失效的保单重新生效,又可称为:",o:["保单复效","保单续保","保单重订","重复保单"],a:0,e:"把已失效的保单重新生效称为复效，又称保单复效，故A正确。续保、重订均非此概念。",src:1,tw:{ch:"闡釋人壽保險單",q:"復效是保單持有人把已經失效的保單重新生效，又可稱為：",o:["保單復效","保單續保","保單重訂","重複保單"],e:"把已失效的保單重新生效稱為復效，又稱保單復效，故A正確。續保、重訂均非此概念。"}},
{p:3,ch:"阐释人寿保险单",q:"大多数保单最常见会以购买增额清缴保险及以下哪项为自动红利选择?",o:["立即以现金方式给付","缴付保单的保费","存放在保险人处以赚取利息","购买一年定期寿险"],a:2,e:"自动红利选择最常见的做法是购买增额清缴保险，或以存放保险人处赚取利息，故C正确。即时现金、缴保费或购买定期寿险并非最常见自动选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"大多數保單最常見會以購買增額清繳保險及以下哪項為自動紅利選擇？",o:["立即以現金方式給付","繳付保單的保費","存放在保險人處以賺取利息","購買一年定期壽險"],e:"自動紅利選擇最常見的做法是購買增額清繳保險，或以存放保險人處賺取利息，故C正確。即時現金、繳保費或購買定期壽險並非最常見自動選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"如保单中有两名受益人,但没有列明如何分配保险金,保险金将如何分配呢?",o:["两名受益人将平均分配保险金","第一顺位受益人取得两倍的保险金","次顺位受益人取得两倍的保险金","第一顺位受益人取得所有的保险金"],a:0,e:"保单有两名受益人但未列明分配方式时，两名受益人将平均分配保险金，故A正确。顺位高低并不改变平均分配的一般原则。",src:1,tw:{ch:"闡釋人壽保險單",q:"如保單中有兩名受益人，但沒有列明如何分配保險金，保險金將如何分配呢？",o:["兩名受益人將平均分配保險金","第一順位受益人取得兩倍的保險金","次順位受益人取得兩倍的保險金","第一順位受益人取得所有的保險金"],e:"保單有兩名受益人但未列明分配方式時，兩名受益人將平均分配保險金，故A正確。順位高低並不改變平均分配的一般原則。"}},
{p:3,ch:"阐释人寿保险单",q:"如保单所有人想变更受益人的指定,该指定受益人称为:",o:["第二顺位受益人","次顺位受益人","可撤换受益人","后备受益人"],a:2,e:"保单所有人可随时变更的受益人称为可撤换受益人，故C正确。次顺位、后备受益人指须待先受益人去世后才承接者。",src:1,tw:{ch:"闡釋人壽保險單",q:"如保單所有人想變更受益人的指定，該指定受益人稱為：",o:["第二順位受益人","次順位受益人","可撤換受益人","後備受益人"],e:"保單所有人可隨時變更的受益人稱為可撤換受益人，故C正確。次順位、後備受益人指須待先受益人去世後才承接者。"}},
{p:3,ch:"阐释人寿保险单",q:"如保单持有人没有指明选择红利的方式,以下哪项是「自动红利选择」的方式?",o:["换作公司的股份","以现金方式支付","存放在保险人处以赚取利息 或 购买清缴增额保险","用以缴付保单的未来保费"],a:2,e:"保单持有人未指明红利选择时，自动红利选择为存放于保险人处赚取利息或购买增额清缴保险，故C正确。换股份、即时现金或缴保费均非默认方式。",src:1,tw:{ch:"闡釋人壽保險單",q:"如保單持有人沒有指明選擇紅利的方式，以下哪項是「自動紅利選擇」的方式？",o:["換作公司的股份","以現金方式支付","存放在保險人處以賺取利息 或 購買清繳增額保險","用以繳付保單的未來保費"],e:"保單持有人未指明紅利選擇時，自動紅利選擇為存放於保險人處賺取利息或購買增額清繳保險，故C正確。換股份、即時現金或繳保費均非默認方式。"}},
{p:3,ch:"阐释人寿保险单",q:"如有保单价值,保险人的权利在承让人之上,当支付利益时会扣除相关费用,承让人得到的称为:",o:["净保额收益","余下保额收益","净保费收益","净保单收益"],a:3,e:"保险人的权利在承让人之上，付利益时会先扣除相关费用，承让人所得余款称为净保单收益，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"如有保單價值，保險人的權利在承讓人之上，當支付利益時會扣除相關費用，承讓人得到的稱為：",o:["淨保額收益","餘下保額收益","淨保費收益","淨保單收益"],e:"保險人的權利在承讓人之上，付利益時會先扣除相關費用，承讓人所得餘款稱為淨保單收益，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"如未能支付到期保费,某项保单条文利用现金价值让该保单继续有效。该条文是:",o:["提前保费贷款条款 (Advanced Premium Loan provision)","自动保费贷款条款 (Automatic Premium Loan provision)","额外保费借贷条款 (Additional Premium Lending provision)","保费借贷的援助 (Assistance with Premium Liability)"],a:1,e:"未付到期保费时利用现金价值让保单继续有效的条文，是自动保费贷款条款（Automatic Premium Loan provision），故B正确。其余名称并非标准用语。",src:1,tw:{ch:"闡釋人壽保險單",q:"如未能支付到期保費，某項保單條文利用現金價值讓該保單繼續有效。該條文是：",o:["提前保費貸款條款 (Advanced Premium Loan provision)","自動保費貸款條款 (Automatic Premium Loan provision)","額外保費借貸條款 (Additional Premium Lending provision)","保費借貸的援助 (Assistance with Premium Liability)"],e:"未付到期保費時利用現金價值讓保單繼續有效的條文，是自動保費貸款條款（Automatic Premium Loan provision），故B正確。其餘名稱並非標準用語。"}},
{p:3,ch:"阐释人寿保险单",q:"如果一份已签发的寿险保单显示受保人的年龄不正确,而该错误是于提出任何索偿前发现,那么以下 哪项描述是正确的?",o:["必须取消该份保单而签发一份新保单","其中一项选择是支付任何差额保费(或获退回多缴保费)","要更改保额或任何合约条款,实属太迟","基于不可以异议条款,不必有所作为"],a:1,e:"索偿前发现年龄误报，处理方式之一为补付差额保费或退回多缴保费，故B正确。并非必须取消保单，亦非因不可异议条款而无须处理。",src:1,tw:{ch:"闡釋人壽保險單",q:"如果一份已簽發的壽險保單顯示受保人的年齡不正確,而該錯誤是於提出任何索償前發現,那麼以下 哪項描述是正確的?",o:["必須取消該份保單而簽發一份新保單","其中一項選擇是支付任何差額保費(或獲退回多繳保費)","要更改保額或任何合約條款,實屬太遲","基於不可以異議條款,不必有所作為"],e:"索償前發現年齡誤報，處理方式之一為補付差額保費或退回多繳保費，故B正確。並非必須取消保單，亦非因不可異議條款而無須處理。"}},
{p:3,ch:"阐释人寿保险单",q:"如果保单于提出索偿后,才被发现误报年龄或性别资料,保险人会如何处理?",o:["向上或向下调整利益金额","不会作出任何调整","退回全数已缴保费","即时取消保单,并控告受保保单所有人"],a:0,e:"若索偿后才被发现误报年龄或性别，保险人会按正确年龄向上或向下调整利益金额，故A正确，而非不调整或取消保单。",src:1,tw:{ch:"闡釋人壽保險單",q:"如果保單於提出索償後，才被發現誤報年齡或性別資料，保險人會如何處理？",o:["向上或向下調整利益金額","不會作出任何調整","退回全數已繳保費","即時取消保單，並控告受保保單所有人"],e:"若索償後才被發現誤報年齡或性別，保險人會按正確年齡向上或向下調整利益金額，故A正確，而非不調整或取消保單。"}},
{p:3,ch:"阐释人寿保险单",q:"如果具有现金价值的保单持有人决定不再为保单缴付任何保费,他有什么处理方法?",o:["退保时获支付退保现金价值","购买展期保险","购买减额清缴保险","以上所有皆是"],a:3,e:"具有现金价值的保单停缴保费后，可退保取现金价值、购买展期保险或购买减额清缴保险，三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"如果具有現金價值的保單持有人決定不再為保單繳付任何保費，他有什麼處理方法？",o:["退保時獲支付退保現金價值","購買展期保險","購買減額清繳保險","以上所有皆是"],e:"具有現金價值的保單停繳保費後，可退保取現金價值、購買展期保險或購買減額清繳保險，三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"如果受保保单所有人与受保生命同属于同一人,及后被发现保单生效后三个月自杀身亡,那么保单:",o:["并没有关系,保险人需支付死亡保险利益","保险人需支付死亡保险利益,但无需支付意外死亡保险利益","保险人无需支付任何死亡保险利益","这是欺诈,索偿无效,已缴保费作废"],a:2,e:"保单生效三个月后自杀，仍处自杀免责期内，保险人无须支付任何死亡保险利益（但可能退回保费），故C正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"如果受保保單所有人與受保生命同屬於同一人，及後被發現保單生效後三個月自殺身亡，那麼保單：",o:["並沒有關係，保險人需支付死亡保險利益","保險人需支付死亡保險利益，但無需支付意外死亡保險利益","保險人無需支付任何死亡保險利益","這是欺詐，索償無效，已繳保費作廢"],e:"保單生效三個月後自殺，仍處自殺免責期內，保險人無須支付任何死亡保險利益（但可能退回保費），故C正確。"}},
{p:3,ch:"阐释人寿保险单",q:"如果受保生命在该免责期内自杀,那么保险公司应该怎样做",o:["不进行任何赔偿","如果赔就要负法律责任","赔偿一半的金额","以上皆否"],a:0,e:"受保生命在自杀免责期内自杀，保险公司不进行任何赔偿（通常只退回已缴保费），故A正确。赔偿一半或视法律责任均不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"如果受保生命在該免責期內自殺，那麽保險公司應該怎樣做",o:["不進行任何賠償","如果賠就要負法律責任","賠償一半的金額","以上皆否"],e:"受保生命在自殺免責期內自殺，保險公司不進行任何賠償（通常只退回已繳保費），故A正確。賠償一半或視法律責任均不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"如果避免受益人莉莉比我先过世,我亦将玛莉写下作为受益人。如果莉莉比我先过世,而玛莉在我死 后得到全部的保险金,玛莉称为:",o:["后备受益人","第一顺位受益人","第二顺位受益人","次顺位受益人"],a:3,e:"为防受益人先去世而设的后备受益人亦称次顺位受益人，玛莉在莉莉先去世后取得全部保险金，故此称为次顺位（后备）受益人，选D。",src:1,tw:{ch:"闡釋人壽保險單",q:"如果避免受益人莉莉比我先過世，我亦將瑪莉寫下作為受益人。如果莉莉比我先過世，而瑪莉在我死 後得到全部的保險金，瑪莉稱為：",o:["後備受益人","第一順位受益人","第二順位受益人","次順位受益人"],e:"為防受益人先去世而設的後備受益人亦稱次順位受益人，瑪莉在莉莉先去世後取得全部保險金，故此稱為次順位（後備）受益人，選D。"}},
{p:3,ch:"阐释人寿保险单",q:"宽限期在英式保单中又称为",o:["宽限阶段","宽限日期","等候期","冷静期"],a:1,e:"英式保单中的宽限期称为宽限日期（days of grace），故B正确。等候期、冷静期均为不同概念。",src:1,tw:{ch:"闡釋人壽保險單",q:"寬限期在英式保單中又稱為",o:["寬限階段","寬限日期","等候期","冷靜期"],e:"英式保單中的寬限期稱為寬限日期（days of grace），故B正確。等候期、冷靜期均為不同概念。"}},
{p:3,ch:"阐释人寿保险单",q:"对保险人来说,受保保单所有人在宽限期内缴交过期保费即表示",o:["准时缴付保费","受保保单所有人需要额外缴付过期部分的利息","在未缴付保费的期间出现了保障真空期","续保时会收取所有未缴付的保费"],a:0,e:"受保保单所有人在宽限期内缴交过期保费，会被视作准时缴付保费，故A正确，无需额外支付利息，亦不产生保障真空。",src:1,tw:{ch:"闡釋人壽保險單",q:"對保險人來說，受保保單所有人在寬限期內繳交過期保費即表示",o:["準時繳付保費","受保保單所有人需要額外繳付過期部分的利息","在未繳付保費的期間出現了保障真空期","續保時會收取所有未繳付的保費"],e:"受保保單所有人在寬限期內繳交過期保費，會被視作準時繳付保費，故A正確，無需額外支付利息，亦不產生保障真空。"}},
{p:3,ch:"阐释人寿保险单",q:"寿险保单的赔付选择中,其中一种选择是以指定的分期方式向指定人士提供终身利益。以下那项陈述 是正确的?",o:["利益采用公积金的方式","用利益购买年金","将有关寿险无限期地延期","将有关寿险修改"],a:1,e:"以指定分期方式向指定人士提供终身利益的赔付选择，实质是以保单利益购买年金，故B正确。公积金、无限延期或修改寿险均非此安排。",src:1,tw:{ch:"闡釋人壽保險單",q:"壽險保單的賠付選擇中，其中一種選擇是以指定的分期方式向指定人士提供終身利益。以下那項陳述 是正確的？",o:["利益採用公積金的方式","用利益購買年金","將有關壽險無限期地延期","將有關壽險修改"],e:"以指定分期方式向指定人士提供終身利益的賠付選擇，實質是以保單利益購買年金，故B正確。公積金、無限延期或修改壽險均非此安排。"}},
{p:3,ch:"阐释人寿保险单",q:"将一份已失效的保单复效是受很多条件所限制的,以下哪项或哪些是有关的条件?",o:["需要提供可保证明","需缴付任何未缴清的贷款及利息","补付已到期但未缴清的保费及利息","受以上所有条件限制"],a:3,e:"复效须提供可保证明、缴清未缴贷款及利息，并补付已到期未缴的保费及利息，三项条件皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"將一份已失效的保單復效是受很多條件所限制的，以下哪項或哪些是有關的條件？",o:["需要提供可保證明","需繳付任何未繳清的貸款及利息","補付已到期但未繳清的保費及利息","受以上所有條件限制"],e:"復效須提供可保證明、繳清未繳貸款及利息，並補付已到期未繳的保費及利息，三項條件皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"就保单抵押贷款条款而言,以下哪项陈述是正确的?",o:["贷款用途无任何限制","保单所有人有权向保险人借入款项","贷款可任何时间偿还,或不偿还","以上所有皆是"],a:3,e:"保单抵押贷款条款下，贷款用途无限制、保单所有人有权借入款项，且贷款可随时偿还或不偿还，三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"就保單抵押貸款條款而言，以下哪項陳述是正確的？",o:["貸款用途無任何限制","保單所有人有權向保險人借入款項","貸款可任何時間償還，或不償還","以上所有皆是"],e:"保單抵押貸款條款下，貸款用途無限制、保單所有人有權借入款項，且貸款可隨時償還或不償還，三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"当保险人及保单所有人同意下,可以按保单条款对已失效保单复效。以下哪项不是常见的保单条款?",o:["提供持续可保的证明","补付已到期但未缴清的保费及利息","无需缴付复效费","由复效日计起另一段可异议期及自杀免责期"],a:2,e:"复效通常须提供持续可保证明、补付保费及利息，并自复效日起另设一段可异议期及自杀免责期，但一般仍须缴付复效费，故C「无需缴付复效费」错误。",src:1,tw:{ch:"闡釋人壽保險單",q:"當保險人及保單所有人同意下，可以按保單條款對已失效保單復效。以下哪項不是常見的保單條款？",o:["提供持續可保的證明","補付已到期但未繳清的保費及利息","無需繳付復效費","由復效日計起另一段可異議期及自殺免責期"],e:"復效通常須提供持續可保證明、補付保費及利息，並自復效日起另設一段可異議期及自殺免責期，但一般仍須繳付復效費，故C「無需繳付復效費」錯誤。"}},
{p:3,ch:"阐释人寿保险单",q:"当支付保单的死亡赔偿时,以下哪项是赔付的选择?",o:["只有对具有享有权的人士提供整笔给付","第三者保单只可选择利息收入","保险人可选择整笔给付或其他方法","由受益人或保单所有人从多种选择中挑选"],a:3,e:"支付死亡赔偿时，由受益人或保单所有人从多种赔付选择（如整笔、分期等）中挑选，故D正确。并非只有整笔给付或由保险人单方决定。",src:1,tw:{ch:"闡釋人壽保險單",q:"當支付保單的死亡賠償時，以下哪項是賠付的選擇？",o:["只有對具有享有權的人士提供整筆給付","第三者保單只可選擇利息收入","保險人可選擇整筆給付或其他方法","由受益人或保單所有人從多種選擇中挑選"],e:"支付死亡賠償時，由受益人或保單所有人從多種賠付選擇（如整筆、分期等）中挑選，故D正確。並非只有整筆給付或由保險人單方決定。"}},
{p:3,ch:"阐释人寿保险单",q:"当证实受保人死于自杀,保险人会",o:["绝对不作任何赔偿","视乎索偿时保单生效了多久","赔偿保额的一半","若保险人作赔偿,即属违法"],a:1,e:"证实受保人死于自杀时，保险人是否赔偿视乎索偿时保单已生效多久（是否已过免责期），故B正确。并非绝对不赔或一律赔一半。",src:1,tw:{ch:"闡釋人壽保險單",q:"當證實受保人死於自殺，保險人會",o:["絕對不作任何賠償","視乎索償時保單生效了多久","賠償保額的一半","若保險人作賠償，即屬違法"],e:"證實受保人死於自殺時，保險人是否賠償視乎索償時保單已生效多久（是否已過免責期），故B正確。並非絕對不賠或一律賠一半。"}},
{p:3,ch:"阐释人寿保险单",q:"当误报年龄或性别是出现于提出索偿之前,一般在香港常见的做法是:",o:["保单即时无效以及保费作废","保额不可能向上或向下调整","把保单取消并退还全数保费","保留原有保额,并同时适当地调整保费"],a:3,e:"索偿前发现年龄或性别误报，香港常见做法是保留原有保额并适当调整保费，故D正确。并非即时失效或退还全数保费。",src:1,tw:{ch:"闡釋人壽保險單",q:"當誤報年齡或性別是出現於提出索償之前，一般在香港常見的做法是：",o:["保單即時無效以及保費作廢","保額不可能向上或向下調整","把保單取消並退還全數保費","保留原有保額，並同時適當地調整保費"],e:"索償前發現年齡或性別誤報，香港常見做法是保留原有保額並適當調整保費，故D正確。並非即時失效或退還全數保費。"}},
{p:3,ch:"阐释人寿保险单",q:"彼得写下玛莉是指明为其保单的受益人,两年后彼得将保单更改为列明若玛莉在他身故前已逝世,规 定把保单利益给予莉莉,请问莉莉会被称为以下哪一项的受益人呢?",o:["后备受益人","次顺位受益人","第二顺位受益人","第一顺位准受益人"],a:1,e:"彼得先指定玛莉为受益人，另约定玛莉先逝时利益归莉莉，莉莉即为次顺位（后备）受益人，故B正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"彼得寫下瑪莉是指明為其保單的受益人，兩年後彼得將保單更改為列明若瑪莉在他身故前已逝世，規 定把保單利益給予莉莉，請問莉莉會被稱為以下哪一項的受益人呢？",o:["後備受益人","次順位受益人","第二順位受益人","第一順位準受益人"],e:"彼得先指定瑪莉為受益人，另約定瑪莉先逝時利益歸莉莉，莉莉即為次順位（後備）受益人，故B正確。"}},
{p:3,ch:"阐释人寿保险单",q:"扺押转让是暂时性的,可以以保单作为抵押,而承让人可以在索偿时收回:",o:["保额全数","贷款金额和利息","保险金扣除贷款额之后的余额","以上各项都不正确"],a:1,e:"抵押转让是暂时性的，以保单作贷款抵押，承让人在索偿时可收回贷款金额及利息（余额归其他权利人），故B正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"扺押轉讓是暫時性的，可以以保單作為抵押，而承讓人可以在索償時收回：",o:["保額全數","貸款金額和利息","保險金扣除貸款額之後的餘額","以上各項都不正確"],e:"抵押轉讓是暫時性的，以保單作貸款抵押，承讓人在索償時可收回貸款金額及利息（餘額歸其他權利人），故B正確。"}},
{p:3,ch:"阐释人寿保险单",q:"按照「不可异议条款」的规定,以下哪项情况即使投保人违反最高诚信的原则(根据香港法律),保险 人仍不大可能拒绝作出赔偿?",o:["保单生效20个月,但于死后6个月才向保险人索偿","保单生效4年,保险人发现投保人违反最高诚信涉及蓄意隐暪重要医疗资料","保单生效4年,保险人发现投保人违反最高诚信涉及无意透露重要事实, 而投保人真诚地认为与保单无关的","保单生效10个月后投保人自杀"],a:2,e:"不可异议条款下，投保人无意漏报且真诚认为与保单无关的事项，即使违反最高诚信，保险人也较难拒绝赔偿，故C正确。蓄意隐瞒或欺诈仍可异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"按照「不可異議條款」的規定，以下哪項情況即使投保人違反最高誠信的原則(根據香港法律)，保險 人仍不大可能拒絕作出賠償？",o:["保單生效20個月，但於死後6個月才向保險人索償","保單生效4年，保險人發現投保人違反最高誠信涉及蓄意隱暪重要醫療資料","保單生效4年，保險人發現投保人違反最高誠信涉及無意透露重要事實， 而投保人真誠地認為與保單無關的","保單生效10個月後投保人自殺"],e:"不可異議條款下，投保人無意漏報且真誠認為與保單無關的事項，即使違反最高誠信，保險人也較難拒絕賠償，故C正確。蓄意隱瞞或欺詐仍可異議。"}},
{p:3,ch:"阐释人寿保险单",q:"按照美式保险制度,假设除宽限期以外其他的保单条款不存在,如果未能于宽限期内缴付一份寿险的 续保保费,保单将会:",o:["一项自动延期三十天的安排便会适用","于宽限期完结当日起该保单便会失效","从续保保费到期日起该份保单便失效","保险人会取消保单而给予十四天的通知期"],a:1,e:"美式制度下，除宽限期外无其他条款时，宽限期内未缴续保保费，保单于宽限期完结当日失效，故B正确，而非自动延期三十天。」。",src:1,tw:{ch:"闡釋人壽保險單",q:"按照美式保險制度，假設除寬限期以外其他的保單條款不存在，如果未能於寬限期內繳付一份壽險的 續保保費，保單將會：",o:["一項自動延期三十天的安排便會適用","於寬限期完結當日起該保單便會失效","從續保保費到期日起該份保單便失效","保險人會取消保單而給予十四天的通知期"],e:"美式制度下，除寬限期外無其他條款時，寬限期內未繳續保保費，保單于寬限期完結當日失效，故B正確，而非自動延期三十天。」。"}},
{p:3,ch:"阐释人寿保险单",q:"支付保单利益时可以有不同的赔付选择。以下哪项/些是赔付选择?",o:["保单收益保存于保险人处,而保险人每年支付利息","分期给付约定金额的保单收益直至付完所有保险金","向指定人士终身分期支付约定的保单收益(终身收益)","以上所有皆是"],a:3,e:"赔付选择包括将保单收益留存于保险人处每年付息、分期给付约定金额直至付完，及向指定人士终身分期支付，三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"支付保單利益時可以有不同的賠付選擇。以下哪項/些是賠付選擇?",o:["保單收益保存於保險人處,而保險人每年支付利息","分期給付約定金額的保單收益直至付完所有保險金","向指定人士終身分期支付約定的保單收益(終身收益)","以上所有皆是"],e:"賠付選擇包括將保單收益留存於保險人處每年付息、分期給付約定金額直至付完，及向指定人士終身分期支付，三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"支付保单利益时可以有以下哪些赔付选择?",o:["整笔支付给受益人","于受益人身故时整笔支付","用来购买保险公司的股票","以上所有各项"],a:0,e:"支付保单利益时可整笔支付给受益人，故A正确。于受益人身故时才支付或以之购买公司股票均非标准赔付选择。",src:1,tw:{ch:"闡釋人壽保險單",q:"支付保單利益時可以有以下哪些賠付選擇？",o:["整筆支付給受益人","於受益人身故時整筆支付","用來購買保險公司的股票","以上所有各項"],e:"支付保單利益時可整筆支付給受益人，故A正確。於受益人身故時才支付或以之購買公司股票均非標準賠付選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"有保单生效之不可异议期是两年,两年后保单仍然可异议是因为",o:["死亡原因是意外事故","保人死亡是由自杀引致","涉及欺诈","被保人在两年期间过去前已经死亡"],a:2,e:"不可异议期为两年，但如果涉及欺诈，保单即使在两年后仍可被异议，故C正确。意外、自杀或死亡本身不构成可异议理由。",src:1,tw:{ch:"闡釋人壽保險單",q:"有保單生效之不可異議期是兩年，兩年後保單仍然可異議是因為",o:["死亡原因是意外事故","保人死亡是由自殺引致","涉及欺詐","被保人在兩年期間過去前已經死亡"],e:"不可異議期為兩年，但如果涉及欺詐，保單即使在兩年後仍可被異議，故C正確。意外、自殺或死亡本身不構成可異議理由。"}},
{p:3,ch:"阐释人寿保险单",q:"有关人夀保单利益的赔付选择,以下哪项是正确的:",o:["只有保险人可决定赔付的选择","受益人或保单所有人可决定赔付的选择","只有受益人可决定赔付的选择","只有保单所有人可决定赔付的选择"],a:1,e:"保险利益的赔付选择可由受益人或保单所有人决定，故B正确，并非仅保险人、仅受益人或仅保单所有人单方决定。",src:1,tw:{ch:"闡釋人壽保險單",q:"有關人夀保單利益的賠付選擇，以下哪項是正確的:",o:["只有保險人可決定賠付的選擇","受益人或保單所有人可決定賠付的選擇","只有受益人可決定賠付的選擇","只有保單所有人可決定賠付的選擇"],e:"保險利益的賠付選擇可由受益人或保單所有人決定，故B正確，並非僅保險人、僅受益人或僅保單所有人單方決定。"}},
{p:3,ch:"阐释人寿保险单",q:"有关寿险保单中的自杀条款,如受保保单所有人出现死亡(一年内自杀),该索偿:",o:["保险人通常会作出通融赔付","保险人退还已缴保费","已缴保费不获退还","赔偿50%死亡金"],a:1,e:"保单生效一年内自杀，保险人不赔死亡金，但通常会退还已缴保费，故B正确。通融赔付或赔50%均非常规处理。",src:1,tw:{ch:"闡釋人壽保險單",q:"有關壽險保單中的自殺條款，如受保保單所有人出現死亡（一年內自殺），該索償：",o:["保險人通常會作出通融賠付","保險人退還已繳保費","已繳保費不獲退還","賠償50%死亡金"],e:"保單生效一年內自殺，保險人不賠死亡金，但通常會退還已繳保費，故B正確。通融賠付或賠50%均非常規處理。"}},
{p:3,ch:"阐释人寿保险单",q:"本港普遍采用的不可异议条款,有关保单的有效性在生后两年后不得提出争议,但须符合某些条件, 不论是明示或隐含条件,这些条件包括没有欺诈成分外,还包括以下哪项或哪些?",o:["保单持有人须缴付所有保费","受保人的死因必须不涉及自杀成因","保单持有人必须在不可异议期内仍然生存","以上所有各项"],a:2,e:"不可异议条款除要求无欺诈成分外，还要求保单持有人在不可异议期内仍然生存，故C正确。缴付所有保费及死因不涉自杀并非此项条件。",src:1,tw:{ch:"闡釋人壽保險單",q:"本港普遍採用的不可異議條款，有關保單的有效性在生後兩年後不得提出爭議，但須符合某些條件， 不論是明示或隱含條件，這些條件包括沒有欺詐成分外，還包括以下哪項或哪些？",o:["保單持有人須繳付所有保費","受保人的死因必須不涉及自殺成因","保單持有人必須在不可異議期內仍然生存","以上所有各項"],e:"不可異議條款除要求無欺詐成分外，還要求保單持有人在不可異議期內仍然生存，故C正確。繳付所有保費及死因不涉自殺並非此項條件。"}},
{p:3,ch:"阐释人寿保险单",q:"根据「自杀条款」,当受保人死因有可疑,",o:["举证责任落在受益人身上","举证责任落在保险人身上","举证责任落在警方身上","可假定死亡是由自杀引起"],a:1,e:"根据自杀条款，当受保人死因有可疑时，举证责任落在保险人身上（须证明自杀），故B正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據「自殺條款」，當受保人死因有可疑，",o:["舉證責任落在受益人身上","舉證責任落在保險人身上","舉證責任落在警方身上","可假定死亡是由自殺引起"],e:"根據自殺條款，當受保人死因有可疑時，舉證責任落在保險人身上（須證明自殺），故B正確。"}},
{p:3,ch:"阐释人寿保险单",q:"根据不可异议条款,以下哪种情况下保险人不大可能拒绝作出赔偿?",o:["保单生效一年后","保单生效二十个月后,保单所有人在六个月后提出的索偿","投保时,保单所有人蓄意违反最高诚信所作出的失实陈述","投保时,保单所有人无意违反最高诚信所作出的失实陈述"],a:3,e:"不可异议条款下，对无意违反最高诚信所作的失实陈述，保险人不大会拒绝赔偿，故D正确。蓄意失实陈述或欺诈仍可异议。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據不可異議條款，以下哪種情況下保險人不大可能拒絕作出賠償？",o:["保單生效一年後","保單生效二十個月後，保單所有人在六個月後提出的索償","投保時，保單所有人蓄意違反最高誠信所作出的失實陳述","投保時，保單所有人無意違反最高誠信所作出的失實陳述"],e:"不可異議條款下，對無意違反最高誠信所作的失實陳述，保險人不大會拒絕賠償，故D正確。蓄意失實陳述或欺詐仍可異議。"}},
{p:3,ch:"阐释人寿保险单",q:"根据人寿保单的「完整保险合约条款」,一份完整的保险合约包括",o:["保险单及保费收据","保险单及保单持有人的身份证副本","保险单及夹付投保单的复印本","保险单及投保单的正本"],a:2,e:"完整保险合约条款下，一份完整合约包括保险单及夹付的投保单复印本，故C正确。保费收据、证件副本或投保单正本均非其界定内容。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據人壽保單的「完整保險合約條款」，一份完整的保險合約包括",o:["保險單及保費收據","保險單及保單持有人的身份證副本","保險單及夾付投保單的複印本","保險單及投保單的正本"],e:"完整保險合約條款下，一份完整合約包括保險單及夾付的投保單複印本，故C正確。保費收據、證件副本或投保單正本均非其界定內容。"}},
{p:3,ch:"阐释人寿保险单",q:"根据保单抵押贷款条款,如果受保保单所有人于去世时并未偿还贷款,后果是:",o:["保单失效,保险人毋须作出任何赔偿","保险人只需退回保费","受益人必须于获得保额前,缴清任何贷款及利息","保险人赔偿前会在保险利益中扣除未缴清的贷款及利息"],a:3,e:"若受保保单所有人去世而贷款未偿还，保险人在赔偿前会在保险利益中扣除未缴清的贷款及利息，故D正确。保单并不因此失效。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據保單抵押貸款條款，如果受保保單所有人於去世時並未償還貸款，後果是：",o:["保單失效，保險人毋須作出任何賠償","保險人只需退回保費","受益人必須於獲得保額前，繳清任何貸款及利息","保險人賠償前會在保險利益中扣除未繳清的貸款及利息"],e:"若受保保單所有人去世而貸款未償還，保險人在賠償前會在保險利益中扣除未繳清的貸款及利息，故D正確。保單並不因此失效。"}},
{p:3,ch:"阐释人寿保险单",q:"根据保单抵押贷款条款,贷款的抵押品是",o:["一笔现金作为按金","现金价值","现金及其他具有价值的物件","不需要任何抵押品"],a:1,e:"保单抵押贷款的抵押品是保单的现金价值，故B正确。它并不要求现金按金或其他有形资产作担保。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據保單抵押貸款條款，貸款的抵押品是",o:["一筆現金作為按金","現金價值","現金及其他具有價值的物件","不需要任何抵押品"],e:"保單抵押貸款的抵押品是保單的現金價值，故B正確。它並不要求現金按金或其他有形資產作擔保。"}},
{p:3,ch:"阐释人寿保险单",q:"根据保单抵押贷款条款,贷款的抵押品是﹕",o:["以现金作为按金","保单中的现金价值","现金或有形资产","一项个人担保"],a:1,e:"保单抵押贷款以保单中的现金价值作抵押品，故B正确。现金按金、有形资产或个人担保均非其抵押品。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據保單抵押貸款條款，貸款的抵押品是﹕",o:["以現金作為按金","保單中的現金價值","現金或有形資產","一項個人擔保"],e:"保單抵押貸款以保單中的現金價值作抵押品，故B正確。現金按金、有形資產或個人擔保均非其抵押品。"}},
{p:3,ch:"阐释人寿保险单",q:"根据保单条文,保单生效至不可异议的时期是两年,然而,以下哪一项情况该份保单仍属可以异议?",o:["死亡原因是因为意外事故","保单所有人作出自杀行为","死亡时保单涉及一项贷款","受保生命在这两年期间过去前已经死亡"],a:3,e:"不可异议期为两年，但若受保生命在这两年期间届满前已死亡，则不可异议期尚未完成，保单仍可异议，故D正确。意外、自杀或贷款本身不构成可异议理由。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據保單條文，保單生效至不可異議的時期是兩年，然而，以下哪一項情況該份保單仍屬可以異議？",o:["死亡原因是因為意外事故","保單所有人作出自殺行為","死亡時保單涉及一項貸款","受保生命在這兩年期間過去前已經死亡"],e:"不可異議期為兩年，但若受保生命在這兩年期間屆滿前已死亡，則不可異議期尚未完成，保單仍可異議，故D正確。意外、自殺或貸款本身不構成可異議理由。"}},
{p:3,ch:"阐释人寿保险单",q:"根据保单条款,保险合约生效两年之后,如果保险人无法证实投保人违反最高诚信原则,而且根据法 律没有进行诈骗,保险人不能视合约失效,此有关条款为:",o:["复效条款","不能作废条款","不可异议条款","完整合约条款"],a:2,e:"保险合约生效两年后，若保险人无法证实投保人违反最高诚信且无诈骗，则不得使合约失效，此条款为不可异议条款，故C正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據保單條款，保險合約生效兩年之後，如果保險人無法證實投保人違反最高誠信原則，而且根據法 律沒有進行詐騙，保險人不能視合約失效，此有關條款為：",o:["復效條款","不能作廢條款","不可異議條款","完整合約條款"],e:"保險合約生效兩年後，若保險人無法證實投保人違反最高誠信且無詐騙，則不得使合約失效，此條款為不可異議條款，故C正確。"}},
{p:3,ch:"阐释人寿保险单",q:"根据保单转让条款,承让人的权利只限于净保险金。这是指承让人:",o:["只可获得保单过去的所有保费供款的金额","只可获得保单的保额扣除所有红利等利益的金额","只可获得保单的所有贷款和利息的金额","只可获得保单的保额经保险公司扣除所有贷款和利息后的保额"],a:3,e:"承让人的权利只限于净保单收益，即保额经保险公司扣除所有贷款和利息后的余额，故D正确。并非只取保费供款、红利或贷款额。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據保單轉讓條款，承讓人的權利只限於淨保險金。這是指承讓人：",o:["只可獲得保單過去的所有保費供款的金額","只可獲得保單的保額扣除所有紅利等利益的金額","只可獲得保單的所有貸款和利息的金額","只可獲得保單的保額經保險公司扣除所有貸款和利息後的保額"],e:"承讓人的權利只限於淨保單收益，即保額經保險公司扣除所有貸款和利息後的餘額，故D正確。並非只取保費供款、紅利或貸款額。"}},
{p:3,ch:"阐释人寿保险单",q:"根据完整合约条款,以下哪项有关投保人同意的保险合约修改之陈述是正确的?",o:["只有保险公司某些指定的高级职员才有权更改合约","修改将于新的替代保单中生效","须由保险公司发出书面通知","任何保险公司职员皆可修改合约"],a:0,e:"完整合约条款下，合约修改只能由保险公司某些指定高级职员作出，故A正确，任何职员皆可修改及需书面通知均不符合规定。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據完整合約條款，以下哪項有關投保人同意的保險合約修改之陳述是正確的？",o:["只有保險公司某些指定的高級職員才有權更改合約","修改將於新的替代保單中生效","須由保險公司發出書面通知","任何保險公司職員皆可修改合約"],e:"完整合約條款下，合約修改只能由保險公司某些指定高級職員作出，故A正確，任何職員皆可修改及需書面通知均不符合規定。"}},
{p:3,ch:"阐释人寿保险单",q:"根据香港普通法,「不可异议条款」是:",o:["保单生效两年后,保险人不可提出异议","保单生效两年内受保生命仍然生存","如涉及欺诈行为便可推翻此条款","以上各项皆是"],a:3,e:"香港普通法下不可异议条款规定：保单生效两年后不可异议、两年内受保生命须生存，且涉欺诈可推翻。三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據香港普通法，「不可異議條款」是：",o:["保單生效兩年後，保險人不可提出異議","保單生效兩年內受保生命仍然生存","如涉及欺詐行為便可推翻此條款","以上各項皆是"],e:"香港普通法下不可異議條款規定：保單生效兩年後不可異議、兩年內受保生命鬚生存，且涉欺詐可推翻。三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"根据香港的实务情况,以下哪些有关不可异议条款是正确的? i 在香港,欺诈往往令保险合约变为可异议 ii 在香港,保单生效两年后,任何情况也不能令保险合约变成可异议 iii 保险生效两年之后,保险合约才变为不可异议 iv 受保生命必须在保单生效的首两年内生存",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],a:1,e:"在香港，欺诈可令合约变为可异议、保单生效两年后才不可异议，且受保生命须于首两年内生存，i、iii、iv正确；「两年后任何情况也不能异议」错误，故选i、iii、iv。",src:1,tw:{ch:"闡釋人壽保險單",q:"根據香港的實務情況，以下哪些有關不可異議條款是正確的？ i 在香港，欺詐往往令保險合約變為可異議 ii 在香港，保單生效兩年後，任何情況也不能令保險合約變成可異議 iii 保險生效兩年之後，保險合約才變為不可異議 iv 受保生命必須在保單生效的首兩年內生存",o:["i, ii, iii","i, iii, iv","ii, iii, iv","i, ii, iv"],e:"在香港，欺詐可令合約變為可異議、保單生效兩年後才不可異議，且受保生命須於首兩年內生存，i、iii、iv正確；「兩年後任何情況也不能異議」錯誤，故選i、iii、iv。"}},
{p:3,ch:"阐释人寿保险单",q:"由于外国人姓名的混淆,结果签发人寿保单时,把一名女性误以为是男性,几年后错误终于被发现, 假如保单持有人不介意继续缴交相同保费,保险人需要作出哪些更改?",o:["调整保单保额,以反映已缴付保费相符的正确保额","退回多收保费","撤销保单","上调保额"],a:0,e:"误将女性填为男性属年龄/性别误报，若继续缴相同保费，应调整保额以反映与已缴保费相符的正确保额，故A正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"由於外國人姓名的混淆，結果簽發人壽保單時，把一名女性誤以為是男性，幾年後錯誤終於被發現， 假如保單持有人不介意繼續繳交相同保費，保險人需要作出哪些更改?",o:["調整保單保額，以反映已繳付保費相符的正確保額","退回多收保費","撤銷保單","上調保額"],e:"誤將女性填為男性屬年齡/性別誤報，若繼續繳相同保費，應調整保額以反映與已繳保費相符的正確保額，故A正確。"}},
{p:3,ch:"阐释人寿保险单",q:"由于对外国人姓名的混淆,结果签发人寿保单时,把一名女性误以为是男性,几年后错误终于被发现 ,假如保单持有人不介意继续缴交相同保费,需要作出哪些更改?",o:["提高保额","退回由投保至现在所缴交的所有保费","降低保额,以反映实际年龄","向保险人补回保单签发至今所有少交的保费"],a:0,e:"女性死亡率较低，误填为男性意味着持人多缴保费，若其不介意继续缴相同保费，应提高保额以反映正确费率，故A正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"由於對外國人姓名的混淆，結果簽發人壽保單時，把一名女性誤以為是男性，幾年後錯誤終於被發現 ，假如保單持有人不介意繼續繳交相同保費，需要作出哪些更改？",o:["提高保額","退回由投保至現在所繳交的所有保費","降低保額，以反映實際年齡","向保險人補回保單簽發至今所有少交的保費"],e:"女性死亡率較低，誤填為男性意味着持人多繳保費，若其不介意繼續繳相同保費，應提高保額以反映正確費率，故A正確。"}},
{p:3,ch:"阐释人寿保险单",q:"由自杀引至死亡发生,如果保单在死亡前不久订立,要知道死亡是不由自杀所引致,这工作由下列谁 人负责?",o:["警察","保险人","受益人","保单所有人"],a:1,e:"因自杀引致死亡时，若保单订立未久，须证明死亡并非由自杀所引致的举证责任由保险人承担，故B正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"由自殺引至死亡發生，如果保單在死亡前不久訂立，要知道死亡是不由自殺所引致，這工作由下列誰 人負責？",o:["警察","保險人","受益人","保單所有人"],e:"因自殺引致死亡時，若保單訂立未久，須證明死亡並非由自殺所引致的舉證責任由保險人承擔，故B正確。"}},
{p:3,ch:"阐释人寿保险单",q:"简单而言,不能作废条款是指:",o:["保单持有人即使中断缴交供款,保单仍然有效","保单一旦生效,保障便不会因任何情况而失效","保险人在保障生效之后不得随意更改保单的内容及条款","除非收到相反指示,如未能支付到期保费时,保单的红利将会被用作支付保费"],a:0,e:"不能作废条款的简单含义是：保单持有人即使中断缴交供款，保单仍可借助现金价值维持有效，故A正确。其余各项对应其他条款。",src:1,tw:{ch:"闡釋人壽保險單",q:"簡單而言，不能作廢條款是指：",o:["保單持有人即使中斷繳交供款，保單仍然有效","保單一旦生效，保障便不會因任何情況而失效","保險人在保障生效之後不得隨意更改保單的內容及條款","除非收到相反指示，如未能支付到期保費時，保單的紅利將會被用作支付保費"],e:"不能作廢條款的簡單含義是：保單持有人即使中斷繳交供款，保單仍可藉助現金價值維持有效，故A正確。其餘各項對應其他條款。"}},
{p:3,ch:"阐释人寿保险单",q:"美式红利是即时支付予保单持有人,而英式红利",o:["大多数「复归」的形式支付","有时称为有利润保单","通常于保额支付时一同支付","以上所有各项"],a:3,e:"英式红利（bonus）多采复归形式、有时称有利润保单，且通常于保额给付时一并支付，三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"美式紅利是即時支付予保單持有人，而英式紅利",o:["大多數「復歸」的形式支付","有時稱為有利潤保單","通常於保額支付時一同支付","以上所有各項"],e:"英式紅利（bonus）多采復歸形式、有時稱有利潤保單，且通常於保額給付時一併支付，三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"自动保费贷款是",o:["保险人发出无抵押贷款以支付保费","利用保单内的现金价值支付保费","保险人豁免首年保障期的保费","被保险人作出贷款以支付保费"],a:1,e:"自动保费贷款是利用保单内的现金价值作为保费垫缴，故B正确。它并非保险人无抵押贷款或豁免保费。",src:1,tw:{ch:"闡釋人壽保險單",q:"自動保費貸款是",o:["保險人發出無抵押貸款以支付保費","利用保單內的現金價值支付保費","保險人豁免首年保障期的保費","被保險人作出貸款以支付保費"],e:"自動保費貸款是利用保單內的現金價值作為保費墊繳，故B正確。它並非保險人無抵押貸款或豁免保費。"}},
{p:3,ch:"阐释人寿保险单",q:"自动红利选择的其中一种做法是将红利存放在保险人处以赚取利息,另一种做法是:",o:["用以缴付保单的未来保费","用以购买增额清缴保险","购买为期一年的定期寿险","把红利的现金价值加在保额上"],a:1,e:"自动红利选择除将红利存放保险人处赚取利息外，另一常见做法是购买增额清缴保险，故B正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"自動紅利選擇的其中一種做法是將紅利存放在保險人處以賺取利息，另一種做法是：",o:["用以繳付保單的未來保費","用以購買增額清繳保險","購買為期一年的定期壽險","把紅利的現金價值加在保額上"],e:"自動紅利選擇除將紅利存放保險人處賺取利息外，另一常見做法是購買增額清繳保險，故B正確。"}},
{p:3,ch:"阐释人寿保险单",q:"若一份美式保单在处理索价时才发现被保人年龄不符,则:",o:["保单无效","调整保费(收取或退回保费)","调整保险利益的金额","可减少50%保额"],a:2,e:"美式保单在处理索偿时才发觉年龄不符，会调整保险利益的金额（按正确年龄增减），故C正确，而非保单无效或固定减半。",src:1,tw:{ch:"闡釋人壽保險單",q:"若一份美式保單在處理索價時才發現被保人年齡不符，則：",o:["保單無效","調整保費(收取或退回保費)","調整保險利益的金額","可減少50%保額"],e:"美式保單在處理索償時才發覺年齡不符，會調整保險利益的金額（按正確年齡增減），故C正確，而非保單無效或固定減半。"}},
{p:3,ch:"阐释人寿保险单",q:"若保单持有人想复效保单,必须符合下列哪些条件?",o:["是违法的","保单必须已失效或退保","有关限制及条件是保单所有人的一些权利","只要保险人同意便足够"],a:2,e:"复效是保单所有人的一项权利，但须符合保单条文所订条件（如补缴欠款及利息、提供可保证明），故C正确。它并非违法，亦非仅凭保险人同意，且针对的是已失效（而非退保）的保单。",src:1,tw:{ch:"闡釋人壽保險單",q:"若保單持有人想復效保單，必須符合下列哪些條件？",o:["是違法的","保單必須已失效或退保","有關限制及條件是保單所有人的一些權利","只要保險人同意便足夠"],e:"復效是保單所有人的一項權利，但須符合保單條文所訂條件（如補繳欠款及利息、提供可保證明），故C正確。它並非違法，亦非僅憑保險人同意，且針對的是已失效（而非退保）的保單。"}},
{p:3,ch:"阐释人寿保险单",q:"若保单持有人想申请复效保单,必须符合下列哪项条件?",o:["保单必须已失效或退保","只须得到保险人同意","这是保单所有人的权利","保单必须退保"],a:2,e:"复效是保单所有人的权利（受所订条件限制），故C正确。保单须已失效即可复效，并非已退保，亦非只须保险人同意。",src:1,tw:{ch:"闡釋人壽保險單",q:"若保單持有人想申請復效保單，必須符合下列哪項條件？",o:["保單必須已失效或退保","只須得到保險人同意","這是保單所有人的權利","保單必須退保"],e:"復效是保單所有人的權利（受所訂條件限制），故C正確。保單須已失效即可復效，並非已退保，亦非只須保險人同意。"}},
{p:3,ch:"阐释人寿保险单",q:"若保单转让最后承让人只会收取净保单收益,即",o:["等如保险金加红利","等于贷款金额和利息","不会扣除任何贷款和利息","等如死亡利益"],a:0,e:"保单转让后，承让人得到的净保单收益由死亡保险金加上红利等利益构成，故A正确。其余关于贷款额、无扣减或仅死亡利益的表述均不准确。",src:1,tw:{ch:"闡釋人壽保險單",q:"若保單轉讓最後承讓人只會收取淨保單收益，即",o:["等如保險金加紅利","等於貸款金額和利息","不會扣除任何貸款和利息","等如死亡利益"],e:"保單轉讓後，承讓人得到的淨保單收益由死亡保險金加上紅利等利益構成，故A正確。其餘關於貸款額、無扣減或僅死亡利益的表述均不準確。"}},
{p:3,ch:"阐释人寿保险单",q:"若受益人于索偿时发现投保人的实际年龄比保单上的年龄少了几岁,美式做法会向上调整死亡利益, 英式做法会怎样处理?",o:["维持原有保额,退回保费","保单即时无效","向上调整死亡利益","把保单取消并退还全数保费"],a:0,e:"若实际年龄比保单所列年龄小（投保时年龄填大、多缴保费），英式做法是维持原有保额并退回多收保费，故A正确。美式则向上调整死亡利益。",src:1,tw:{ch:"闡釋人壽保險單",q:"若受益人於索償時發現投保人的實際年齡比保單上的年齡少了幾歲，美式做法會向上調整死亡利益， 英式做法會怎樣處理？",o:["維持原有保額，退回保費","保單即時無效","向上調整死亡利益","把保單取消並退還全數保費"],e:"若實際年齡比保單所列年齡小（投保時年齡填大、多繳保費），英式做法是維持原有保額並退回多收保費，故A正確。美式則向上調整死亡利益。"}},
{p:3,ch:"阐释人寿保险单",q:"若受益人于索偿时发现投保人的实际年龄比保单上的年龄高了几岁,会怎样处理?",o:["退回保费","向下调整死亡利益","向上调整死亡利益","维持死亡利益不变,退回多收保费"],a:1,e:"若实际年龄比保单所列年龄为大（少缴保费），会向下调整死亡利益，故B正确。向上调整或维持不变并退回保费均不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"若受益人於索償時發現投保人的實際年齡比保單上的年齡高了幾歲，會怎樣處理？",o:["退回保費","向下調整死亡利益","向上調整死亡利益","維持死亡利益不變，退回多收保費"],e:"若實際年齡比保單所列年齡為大（少繳保費），會向下調整死亡利益，故B正確。向上調整或維持不變並退回保費均不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"英式人寿保险中「保单复效(policy revival) 」又称为:",o:["重新订立 (re-establishment)","复效 (reinstatement)","不能作废 (non-forfeiture)","保单续保 (policy renewal)"],a:1,e:"英式人寿保险的保单复效（policy revival）即美式所称复效（reinstatement），故B正确。另三项为不同概念。",src:1,tw:{ch:"闡釋人壽保險單",q:"英式人壽保險中「保單復效(policy revival) 」又稱為：",o:["重新訂立 (re-establishment)","復效 (reinstatement)","不能作廢 (non-forfeiture)","保單續保 (policy renewal)"],e:"英式人壽保險的保單復效（policy revival）即美式所稱復效（reinstatement），故B正確。另三項為不同概念。"}},
{p:3,ch:"阐释人寿保险单",q:"英式惯例中的保单复效 (\"policy revival\")在香港的意思是指?",o:["保单续保 (Policy Renewal)","不能作废条款 (Nonforfeiture Provisions)","复效 (Reinstatement)","保单建立 (Policy Establishment)"],a:2,e:"英式惯例中的 policy revival 在香港即指复效（reinstatement），故C正确。续保、不能作废、保单建立均非其对应含义。",src:1,tw:{ch:"闡釋人壽保險單",q:"英式慣例中的保單復效 (\"policy revival\")在香港的意思是指?",o:["保單續保 (Policy Renewal)","不能作廢條款 (Nonforfeiture Provisions)","復效 (Reinstatement)","保單建立 (Policy Establishment)"],e:"英式慣例中的 policy revival 在香港即指復效（reinstatement），故C正確。續保、不能作廢、保單建立均非其對應含義。"}},
{p:3,ch:"阐释人寿保险单",q:"要保单复效,保单所有人必须受到下列那些条件限制? i 提供连续可保性证明 ii 缴付任何未缴清货款及利息 iii 从复效日计起的另一段自杀免责期",o:["i,ii","i,iii","ii,iii","i,ii,iii"],a:3,e:"复效须提供连续可保性证明、缴清任何未缴清贷款及利息，并自复效日起另设一段自杀免责期，三项皆是，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"要保單復效,保單所有人必須受到下列那些條件限制? i 提供連續可保性證明 ii 繳付任何未繳清貨款及利息 iii 從復效日計起的另一段自殺免責期",o:["i,ii","i,iii","ii,iii","i,ii,iii"],e:"復效須提供連續可保性證明、繳清任何未繳清貸款及利息，並自復效日起另設一段自殺免責期，三項皆是，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"误报年龄或性别,意味着就有关的保额的利益,付出了不正确的保费,这项错误在提出索偿前发现, 该保额便:",o:["保单将即时失效","必须维持不变","根据有关各方所同意的决定,可以维持不变或作出更改","以欺诈行为作理由而自动扣减"],a:2,e:"年龄或性别误报使所缴保费与保额不符，若索偿前发现，保额可根据各方同意维持不变或作出更改，故C正确，并非必须维持不变或即时失效。",src:1,tw:{ch:"闡釋人壽保險單",q:"誤報年齡或性別,意味着就有關的保額的利益,付出了不正確的保費,這項錯誤在提出索償前發現, 該保額便:",o:["保單將即時失效","必須維持不變","根據有關各方所同意的決定,可以維持不變或作出更改","以欺詐行為作理由而自動扣減"],e:"年齡或性別誤報使所繳保費與保額不符，若索償前發現，保額可根據各方同意維持不變或作出更改，故C正確，並非必須維持不變或即時失效。"}},
{p:3,ch:"阐释人寿保险单",q:"转让必需要符合某些条件才可进行,这是?",o:["该财产是属于据法产权","该财产不论是人寿或一般保险,具有法定权益","该财产是普通法下认可的可保权益","该财产已透过某订明手续而成为据法产权"],a:3,e:"转让须透过订明手续（书面、绝对转让并发出通知）使据法权产权益有效转移，故D正确。其余选项未涵盖「藉订明手续」这一要件。",src:1,tw:{ch:"闡釋人壽保險單",q:"轉讓必需要符合某些條件才可進行，這是?",o:["該財產是屬於據法產權","該財產不論是人壽或一般保險，具有法定權益","該財產是普通法下認可的可保權益","該財產已透過某訂明手續而成為據法產權"],e:"轉讓須透過訂明手續（書面、絕對轉讓併發出通知）使據法權產權益有效轉移，故D正確。其餘選項未涵蓋「藉訂明手續」這一要件。"}},
{p:3,ch:"阐释人寿保险单",q:"转让法对保险合约的权益属于据法产权,根据:",o:["法律修订及改革(综合)条例","法律修订(综合)条例","普通法中的转让原则","转让(据法权产)条例"],a:0,e:"保险合约的权益属据法权产，其转让依据《法律修订及改革（综合）条例》，故A正确。其余条例名称不准确。",src:1,tw:{ch:"闡釋人壽保險單",q:"轉讓法對保險合約的權益屬於據法產權，根據:",o:["法律修訂及改革(綜合)條例","法律修訂(綜合)條例","普通法中的轉讓原則","轉讓(據法權產)條例"],e:"保險合約的權益屬據法權產，其轉讓依據《法律修訂及改革（綜合）條例》，故A正確。其餘條例名稱不準確。"}},
{p:3,ch:"阐释人寿保险单",q:"近似美式保单的分红称为「红利」,若以英式保单,红利则称为以下哪项?",o:["利润","有利润","英式红利","花红"],a:2,e:"美式保单的「红利」（dividends）在英式保单中称为英式红利（bonuses），故C正确。利润、有利润及花红均非对应术语。",src:1,tw:{ch:"闡釋人壽保險單",q:"近似美式保單的分紅稱為「紅利」，若以英式保單，紅利則稱為以下哪項？",o:["利潤","有利潤","英式紅利","花紅"],e:"美式保單的「紅利」（dividends）在英式保單中稱為英式紅利（bonuses），故C正確。利潤、有利潤及花紅均非對應術語。"}},
{p:3,ch:"阐释人寿保险单",q:"钱先生将人寿保险单转让给ABC公司,ABC公司要求保险人支付红利,遭保险人拒绝,当中最有可能 的原因是:",o:["钱先生没有将ABC公司转为受益人","红利只能在钱先生死亡后才支付予ABC公司","即使钱先生已将险单进行转让,根据保险合约,钱先生仍然为合约的一方","保险人并没有收到书面转让通知"],a:3,e:"转让后承让人提取红利须先书面通知保险人，若保险人未收到书面转让通知，很可能拒绝支付，故D最可能是拒付原因。",src:1,tw:{ch:"闡釋人壽保險單",q:"錢先生將人壽保險單轉讓給ABC公司，ABC公司要求保險人支付紅利，遭保險人拒絕，當中最有可能 的原因是：",o:["錢先生沒有將ABC公司轉為受益人","紅利只能在錢先生死亡後才支付予ABC公司","即使錢先生已將險單進行轉讓，根據保險合約，錢先生仍然為合約的一方","保險人並沒有收到書面轉讓通知"],e:"轉讓後承讓人提取紅利須先書面通知保險人，若保險人未收到書面轉讓通知，很可能拒絕支付，故D最可能是拒付原因。"}},
{p:3,ch:"阐释人寿保险单",q:"钱先生转让一份人寿保险给ABC有限公司。ABC有限公司向保险人提出需要提取红利但遭拒绝。就以 上情况,哪项是较可能发生?",o:["钱先生没有就转让事宜正式通知保险人","转让需在死亡时才可提取红利","ABC有限公司只能提取现金价值","钱先生没有把ABC有限公司写作受益人"],a:0,e:"ABC公司向保险人提取红利遭拒，最可能是钱先生未就转让事宜正式书面通知保险人，故A正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"錢先生轉讓一份人壽保險給ABC有限公司。ABC有限公司向保險人提出需要提取紅利但遭拒絕。就以 上情況，哪項是較可能發生？",o:["錢先生沒有就轉讓事宜正式通知保險人","轉讓需在死亡時才可提取紅利","ABC有限公司只能提取現金價值","錢先生沒有把ABC有限公司寫作受益人"],e:"ABC公司向保險人提取紅利遭拒，最可能是錢先生未就轉讓事宜正式書面通知保險人，故A正確。"}},
{p:3,ch:"阐释人寿保险单",q:"除非得到保单所有人同意,否则不能对保险合约的条款作出更改,有关规定在保单合约中有订明,该 部分称为:",o:["宽限期条文","完整合约条款","不可异议条款","不能作废条款"],a:1,e:"规定除非保单所有人同意、否则不得更改合约条款的部分，称为完整合约条款，故B正确。宽限期、不可异议及不能作废为其他条款。",src:1,tw:{ch:"闡釋人壽保險單",q:"除非得到保單所有人同意，否則不能對保險合約的條款作出更改，有關規定在保單合約中有訂明，該 部分稱為：",o:["寬限期條文","完整合約條款","不可異議條款","不能作廢條款"],e:"規定除非保單所有人同意、否則不得更改合約條款的部分，稱為完整合約條款，故B正確。寬限期、不可異議及不能作廢為其他條款。"}},
{p:3,ch:"阐释人寿保险单",q:"香港的分红人寿保单一般是依照美式保单模式并赚取红利(Dividends),在英式的人寿保险体系中, 与「红利」意义相近的用语是:",o:["利润 (gains)","英式红利 (bonuses)","保单收益 (policy earnings)","利润分红 (profits participation)"],a:1,e:"美式保单的红利（dividends）在英式体系中对应的用语是英式红利（bonuses），故B正确。利润、保单收益及利润分红均不准确。",src:1,tw:{ch:"闡釋人壽保險單",q:"香港的分紅人壽保單一般是依照美式保單模式並賺取紅利(Dividends)，在英式的人壽保險體系中， 與「紅利」意義相近的用語是：",o:["利潤 (gains)","英式紅利 (bonuses)","保單收益 (policy earnings)","利潤分紅 (profits participation)"],e:"美式保單的紅利（dividends）在英式體系中對應的用語是英式紅利（bonuses），故B正確。利潤、保單收益及利潤分紅均不準確。"}},
{p:3,ch:"阐释人寿保险单",q:"黄先生为自己的生命买人寿保险,指明其最小的儿子为受益人。根据「已婚者地位条例」,会产生以 下哪个情况?",o:["儿子将成为此保单的法定上的持有人","儿子将成为此保单的实益拥有人","此条例不适用于订立子女为受益人的寿险单","此条例不适用于订立配偶或长子(或长女)以外人士为受益人的寿险单"],a:1,e:"根据《已婚者地位条例》，以自己生命投保并指定儿子为受益人会构成法定信托，儿子成为保单的实益拥有人，故B正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"黃先生為自己的生命買人壽保險，指明其最小的兒子為受益人。根據「已婚者地位條例」，會產生以 下哪個情況?",o:["兒子將成為此保單的法定上的持有人","兒子將成為此保單的實益擁有人","此條例不適用於訂立子女為受益人的壽險單","此條例不適用於訂立配偶或長子(或長女)以外人士為受益人的壽險單"],e:"根據《已婚者地位條例》，以自己生命投保並指定兒子為受益人會構成法定信託，兒子成為保單的實益擁有人，故B正確。"}},
{p:3,ch:"阐释人寿保险单",q:"黄先生为自己的生命投保人身意外保险,指明其儿子为受益人。根据「已婚者地位条例」,这安排可 以成为一个法定信托吗?",o:["不会,因为这张保单并非承保任何原因身故的保单","会,因为根据「已婚者地位条例」,适用于人身意外保险单和人寿保险单","会,因为根据「已婚者地位条例」,该保险是黄先生就自身生命买保单","不会,除非黄先生购买的是附有人身意外保险利益附约的寿险单"],a:3,e:"《已婚者地位条例》的信托规则适用于寿险保单，人身意外保单不当然构成法定信托；除非它是附有人身意外利益附约的寿险单，故D正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"黃先生為自己的生命投保人身意外保險，指明其兒子為受益人。根據「已婚者地位條例」，這安排可 以成為一個法定信託嗎？",o:["不會，因為這張保單並非承保任何原因身故的保單","會，因爲根據「已婚者地位條例」，適用於人身意外保險單和人壽保險單","會，因爲根據「已婚者地位條例」，該保險是黃先生就自身生命買保單","不會，除非黃先生購買的是附有人身意外保險利益附約的壽險單"],e:"《已婚者地位條例》的信託規則適用於壽險保單，人身意外保單不當然構成法定信託；除非它是附有人身意外利益附約的壽險單，故D正確。"}},
{p:3,ch:"阐释人寿保险单",q:"黄先生买了一张个人意外保单,儿子是保单受益人,是否可以成为法定信托?",o:["不会,因为这张保单并非承保任何原因身故的保单","不会,除非就「已婚者」的要求,是黄先生就自身生命买保单","不会,因为「已婚者」只适用于不包括个人意外保单","会,因为「已婚者条例」列明包括意外及寿险"],a:2,e:"《已婚者地位条例》只适用于寿险保单，不包括个人意外保单，故C正确。意外险指定受益人并不能当然成为法定信托。",src:1,tw:{ch:"闡釋人壽保險單",q:"黃先生買了一張個人意外保單，兒子是保單受益人，是否可以成為法定信託?",o:["不會，因為這張保單並非承保任何原因身故的保單","不會，除非就「已婚者」的要求，是黃先生就自身生命買保單","不會，因為「已婚者」只適用於不包括個人意外保單","會，因為「已婚者條例」列明包括意外及壽險"],e:"《已婚者地位條例》只適用於壽險保單，不包括個人意外保單，故C正確。意外險指定受益人並不能當然成為法定信託。"}},
{p:3,ch:"人寿保险程序",q:"TIA 即:",o:["Termination Insurance Application 停止保险申请","Temporary Insurance Agreement 临时保险协议","Temporary Insurance Acknowledge   临时保险确认书","Temporary Insurance Accepted 临时保险证明"],a:1,e:"TIA 即 Temporary Insurance Agreement，意为临时保险协议，故B正确。其余全称均非此缩写的正确展开。",src:1,tw:{ch:"人壽保險程序",q:"TIA 即：",o:["Termination Insurance Application 停止保險申請","Temporary Insurance Agreement 臨時保險協議","Temporary Insurance Acknowledge 臨時保險確認書","Temporary Insurance Accepted 臨時保險證明"],e:"TIA 即 Temporary Insurance Agreement，意為臨時保險協議，故B正確。其餘全稱均非此縮寫的正確展開。"}},
{p:3,ch:"人寿保险程序",q:"《承保长期保险业务(类别C业务除外)指引》,在销售分红保单时保险人须告知客户:",o:["分红储蓄产品,其保证款项于保单年期届满时不少于所缴保费总额","过往的红利派发表是分红产品未来表现的指标","过往的红利派发表并非分红产品未来表现的指标","非保证红利派发表是分红产品未来表现的指标"],a:2,e:"该指引要求保险人告知客户，过往的红利派发表并非分红产品未来表现的指标，故C正确，警示客户勿据此推断未来回报。",src:1,tw:{ch:"人壽保險程序",q:"《承保長期保險業務（類別C業務除外）指引》，在銷售分紅保單時保險人須告知客戶:",o:["分紅儲蓄產品，其保證款項於保單年期屆滿時不少於所繳保費總額","過往的紅利派發表是分紅產品未來表現的指標","過往的紅利派發表並非分紅產品未來表現的指標","非保證紅利派發表是分紅產品未來表現的指標"],e:"該指引要求保險人告知客户，過往的紅利派發表並非分紅產品未來表現的指標，故C正確，警示客户勿據此推斷未來回報。"}},
{p:3,ch:"人寿保险程序",q:"《承保长期保险业务(类别C业务除外)指引》是经考虑哪一个机构所颁布的《保险核心原则、标准、指引 和评估方法》而制订?",o:["特区政府","国际保险监督联会","国家保险监管人联盟","保险监督联合会"],a:1,e:"该指引是经参考国际保险监督联会（IAIS）颁布的《保险核心原则、标准、指引和评估方法》而制订，故B正确。",src:1,tw:{ch:"人壽保險程序",q:"《承保長期保險業務（類別C業務除外）指引》是經考慮哪一個機構所頒布的《保險核心原則、標準、指引 和評估方法》而制訂？",o:["特區政府","國際保險監督聯會","國家保險監管人聯盟","保險監督聯合會"],e:"該指引是經參考國際保險監督聯會（IAIS）頒佈的《保險核心原則、標準、指引和評估方法》而制訂，故B正確。"}},
{p:3,ch:"人寿保险程序",q:"《承保长期保险业务（类别C业务除外）指引》产品实现率的平均数是如何计算?",o:["「实际派发的非保证红利／英式红利」除以销售时「利益说明所述数额」","「预期派发的非保证红利／英式红利」除以销售时「利益说明所述数额」","「过往派发的保证红利／英式红利」除以销售时「利益说明所述数额」","「实际派发的保证红利／英式红利」除以销售时「利益说明所述数额」"],a:0,e:"产品实现率的平均数以「实际派发的非保证红利／英式红利」除以销售时「利益说明所述数额」计算，故A正确。",src:1,tw:{ch:"人壽保險程序",q:"《承保長期保險業務（類別C業務除外）指引》產品實現率的平均數是如何計算?",o:["「實際派發的非保證紅利／英式紅利」除以銷售時「利益說明所述數額」","「預期派發的非保證紅利／英式紅利」除以銷售時「利益說明所述數額」","「過往派發的保證紅利／英式紅利」除以銷售時「利益說明所述數額」","「實際派發的保證紅利／英式紅利」除以銷售時「利益說明所述數額」"],e:"產品實現率的平均數以「實際派發的非保證紅利／英式紅利」除以銷售時「利益說明所述數額」計算，故A正確。"}},
{p:3,ch:"人寿保险程序",q:"《重要资料声明书—内地人士在港投购人身/寿险保单》供以下哪一类人士遵守?",o:["经营长期业务的获授权保险人","经营人寿保险和人身意外保险业务的获授权保险人","经营有关保险的事宜提供意见的保险中介人","授权的保险代理和保险经纪"],a:0,e:"《重要资料声明书—内地人士在港投购人身/寿险保单》供经营长期业务的获授权保险人遵守，故A正确。",src:1,tw:{ch:"人壽保險程序",q:"《重要資料聲明書—內地人士在港投購人身/壽險保單》供以下哪一類人士遵守?",o:["經營長期業務的獲授權保險人","經營人壽保險和人身意外保險業務的獲授權保險人","經營有關保險的事宜提供意見的保險中介人","授權的保險代理和保險經紀"],e:"《重要資料聲明書—內地人士在港投購人身/壽險保單》供經營長期業務的獲授權保險人遵守，故A正確。"}},
{p:3,ch:"人寿保险程序",q:"「冷静期」建议寿险会员确保何时签发保单?",o:["在收到保费后的7天内","在收到保费后的9天内","在收到保费后的14天内","它并无指出保单应于何时签发"],a:3,e:"「冷静期」指引只规定冷静期的保障，并无指明保单应于何时签发，故D正确。",src:1,tw:{ch:"人壽保險程序",q:"「冷靜期」建議壽險會員確保何時簽發保單？",o:["在收到保費後的7天內","在收到保費後的9天內","在收到保費後的14天內","它並無指出保單應於何時簽發"],e:"「冷靜期」指引只規定冷靜期的保障，並無指明保單應於何時簽發，故D正確。"}},
{p:3,ch:"人寿保险程序",q:"「市值调整」(MVA)英文全名是:",o:["Market Value Adjustment","Market Value Assessment","Monetary Value Assessment","Monetary Value Adjustment"],a:0,e:"「市值调整」的英文全称是 Market Value Adjustment（MVA），故A正确。其余为干扰拼写。",src:1,tw:{ch:"人壽保險程序",q:"「市值調整」(MVA)英文全名是：",o:["Market Value Adjustment","Market Value Assessment","Monetary Value Assessment","Monetary Value Adjustment"],e:"「市值調整」的英文全稱是 Market Value Adjustment（MVA），故A正確。其餘為干擾拼寫。"}},
{p:3,ch:"人寿保险程序",q:"「转保」及「诱导转保」在人寿保险中的手法:",o:["两者的意义都是相同","「诱导转保」往往含有不恰当行为","「转保」往往含有不恰当行为","声誉良好的保险人对两者均不接受"],a:1,e:"转保是中性行为，而「诱导转保」常涉及误导等不恰当行为，故B正确。两者意义不同，并非均含不当或均不受理。",src:1,tw:{ch:"人壽保險程序",q:"「轉保」及「誘導轉保」在人壽保險中的手法：",o:["兩者的意義都是相同","「誘導轉保」往往含有不恰當行為","「轉保」往往含有不恰當行為","聲譽良好的保險人對兩者均不接受"],e:"轉保是中性行為，而「誘導轉保」常涉及誤導等不恰當行為，故B正確。兩者意義不同，並非均含不當或均不受理。"}},
{p:3,ch:"人寿保险程序",q:"一个审慎的保险人在什么情况下才宣布派发红利?",o:["当汇集基金的实际的业绩情况比其之前所作的精算和财务假设更有利后","保险人的业绩优胜过市场预期","汇集基金在特定期间的业绩情况跟市场的预期一致","保险人的业绩不差于市场预期"],a:0,e:"审慎的保险人会在汇集基金实际业绩优于其先前精算及财务假设后，才宣布派发红利，故A正确。仅与市场预期比较并不足以决定派红。",src:1,tw:{ch:"人壽保險程序",q:"一個審慎的保險人在什麼情況下才宣佈派發紅利？",o:["當匯集基金的實際的業績情況比其之前所作的精算和財務假設更有利後","保險人的業績優勝過市場預期","匯集基金在特定期間的業績情況跟市場的預期一致","保險人的業績不差於市場預期"],e:"審慎的保險人會在彙集基金實際業績優於其先前精算及財務假設後，才宣佈派發紅利，故A正確。僅與市場預期比較並不足以決定派紅。"}},
{p:3,ch:"人寿保险程序",q:"一个谨慎的保险人只会在什么情况下才宣布保单红利的?",o:["保险人的投资表现不差过市场的表现","保险人的投资表现差过市场的表现","期望汇集基金的将来业绩情况","以上各项皆不是"],a:3,e:"谨慎保险人只在汇集基金实际业绩优于精算假设时才宣布红利，A、B、C均不具备此条件，故D「以上各项皆不是」正确。",src:1,tw:{ch:"人壽保險程序",q:"一個謹慎的保險人只會在什麼情況下才宣佈保單紅利的？",o:["保險人的投資表現不差過市場的表現","保險人的投資表現差過市場的表現","期望匯集基金的將來業績情況","以上各項皆不是"],e:"謹慎保險人只在彙集基金實際業績優於精算假設時才宣佈紅利，A、B、C均不具備此條件，故D「以上各項皆不是」正確。"}},
{p:3,ch:"人寿保险程序",q:"一份寿险保单最常见的保单更改事宜包括:",o:["更改地址","更改受益人","更改保单持有人","以上所有各项"],a:3,e:"寿险保单最常见的更改事宜包括更改地址、更改受益人及更改保单持有人，三项皆是，故D正确。",src:1,tw:{ch:"人壽保險程序",q:"一份壽險保單最常見的保單更改事宜包括：",o:["更改地址","更改受益人","更改保單持有人","以上所有各項"],e:"壽險保單最常見的更改事宜包括更改地址、更改受益人及更改保單持有人，三項皆是，故D正確。"}},
{p:3,ch:"人寿保险程序",q:"一名谨慎的保险人,只会在以下哪情况下宣布发放红利?",o:["保险人投资表现优于市场表现","得知了汇集基金的实际业绩比其之前精算及财政假设更佳之后","保险人投资表现不差于市场表现","期望汇集基金业绩优于市场表现"],a:1,e:"谨慎的保险人只在得知汇集基金实际业绩优于其先前精算及财政假设后，才宣布发放红利，故B正确。",src:1,tw:{ch:"人壽保險程序",q:"一名謹慎的保險人，只會在以下哪情況下宣佈發放紅利？",o:["保險人投資表現優於市場表現","得知了匯集基金的實際業績比其之前精算及財政假設更佳之後","保險人投資表現不差於市場表現","期望匯集基金業績優於市場表現"],e:"謹慎的保險人只在得知彙集基金實際業績優於其先前精算及財政假設後，才宣佈發放紅利，故B正確。"}},
{p:3,ch:"人寿保险程序",q:"一种收据,保险人同意保险于投保时即开始生效,但是必须在事后能确定投保人在投保时乃属按照标准条款 具有可保性才有效。这种收据称为:",o:["独立合约","立约保费收据","附条件保费收据","临时保险协议"],a:2,e:"保险人同意保险于投保时即成立、但须事后确定投保人按标准条款具可保性才有效的收据，称附条件保费收据，故C正确。",src:1,tw:{ch:"人壽保險程序",q:"一種收據，保險人同意保險於投保時即開始生效，但是必須在事後能確定投保人在投保時乃屬按照標準條款 具有可保性才有效。這種收據稱為：",o:["獨立合約","立約保費收據","附條件保費收據","臨時保險協議"],e:"保險人同意保險於投保時即成立、但須事後確定投保人按標準條款具可保性才有效的收據，稱附條件保費收據，故C正確。"}},
{p:3,ch:"人寿保险程序",q:"一般而言,向分红保单持有人宣布及派发的红利金额与什么有直接关系?",o:["有关保险人的整体业绩","该份分红保单的汇集基金的业绩表现","证券市场的平均表现","精算师的运算"],a:1,e:"分红保单的红利来自该份保单所属汇集基金的投资、赔付及费用综合表现，故与汇集基金业绩直接相关；整体业绩、证券市场平均表现只是间接因素，精算师运算仅是厘定手段，均非直接决定因素。",src:1,tw:{ch:"人壽保險程序",q:"一般而言，向分紅保單持有人宣佈及派發的紅利金額與什麼有直接關係？",o:["有關保險人的整體業績","該份分紅保單的匯集基金的業績表現","證券市場的平均表現","精算師的運算"],e:"分紅保單的紅利來自該份保單所屬彙集基金的投資、賠付及費用綜合表現，故與彙集基金業績直接相關；整體業績、證券市場平均表現只是間接因素，精算師運算僅是釐定手段，均非直接決定因素。"}},
{p:3,ch:"人寿保险程序",q:"万用寿险(非相连)保单销售说明书中,有关现金价值及死亡保险金是:",o:["被保证等于最低值","被保证等于最高值","以「假设派息率」在保单有效期内一直不变为基础而计算的","保单生效两年后才受到约束"],a:2,e:"万用（非相连）保单说明书中现金价值与死亡保险金是按假设派息率在保单期内始终不变为基础计算的，属非保证的预估；并非被保证等于最低或最高值，亦非保单生效两年后才受约束。",src:1,tw:{ch:"人壽保險程序",q:"萬用壽險(非相連)保單銷售說明書中，有關現金價值及死亡保險金是：",o:["被保證等於最低值","被保證等於最高值","以「假設派息率」在保單有效期內一直不變為基礎而計算的","保單生效兩年後才受到約束"],e:"萬用（非相連）保單說明書中現金價值與死亡保險金是按假設派息率在保單期內始終不變為基礎計算的，屬非保證的預估；並非被保證等於最低或最高值，亦非保單生效兩年後才受約束。"}},
{p:3,ch:"人寿保险程序",q:"下列关于厘定保单红利的实务的陈述中,哪项是正确的?",o:["保险人一般会将红利平均派发,以减低短期大幅波动","红利金额是基于首席财务官的批准,并由独立精算师而非获委任精算师核实的","红利金额是基于获委任精算师的意见,并经保险业监管局批准而厘定的","红利金额是基于获委任精算师的意见,并经股东批准而厘定的"],a:0,e:"实务上保险人会平均（平滑）派发红利，让保单持有人所得红利免受短期业绩大幅波动影响；红利厘定基于获委任精算师的意见，而非CFO批准、股东批准或监管局批准。",src:1,tw:{ch:"人壽保險程序",q:"下列關於釐定保單紅利的實務的陳述中，哪項是正確的？",o:["保險人一般會將紅利平均派發，以減低短期大幅波動","紅利金額是基於首席財務官的批准，並由獨立精算師而非獲委任精算師核實的","紅利金額是基於獲委任精算師的意見，並經保險業監管局批准而釐定的","紅利金額是基於獲委任精算師的意見，並經股東批准而釐定的"],e:"實務上保險人會平均（平滑）派發紅利，讓保單持有人所得紅利免受短期業績大幅波動影響；紅利釐定基於獲委任精算師的意見，而非CFO批准、股東批准或監管局批准。"}},
{p:3,ch:"人寿保险程序",q:"下列哪两项关于「冷静期」的说法正确? i 为期只有14天 ii 所有香港保险业联会的人寿保险公司会员已承诺会遵守「冷静期」建议 iii 如果适当地行使,保单可被取消,保费可被退还 iv 指保险人可以取消保单的一段时间",o:["i, ii","i, iii","ii, iii","ii, iv"],a:2,e:"香港保险业联会人寿保险会员已承诺遵守冷静期建议（ii），且适当地行使时可取消保单并获退还保费（iii）；冷静期为期21天而非14天（i错），且是给予投保人的权利而非保险人（iv错）。",src:1,tw:{ch:"人壽保險程序",q:"下列哪兩項關於「冷靜期」的說法正確？ i 為期只有14天 ii 所有香港保險業聯會的人壽保險公司會員已承諾會遵守「冷靜期」建議 iii 如果適當地行使，保單可被取消，保費可被退還 iv 指保險人可以取消保單的一段時間",o:["i, ii","i, iii","ii, iii","ii, iv"],e:"香港保險業聯會人壽保險會員已承諾遵守冷靜期建議（ii），且適當地行使時可取消保單並獲退還保費（iii）；冷靜期為期21天而非14天（i錯），且是給予投保人的權利而非保險人（iv錯）。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项不是核保部门的工作?",o:["风险的选择","再保险的安排","安排并监督身体检查","审阅验尸报告"],a:3,e:"审阅验尸报告属理赔部门调查死因的工作，并非核保职能；风险选择、再保险安排、安排并监督身体检查均属核保部门职责范围。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項不是核保部門的工作？",o:["風險的選擇","再保險的安排","安排並監督身體檢查","審閱驗屍報告"],e:"審閲驗屍報告屬理賠部門調查死因的工作，並非核保職能；風險選擇、再保險安排、安排並監督身體檢查均屬核保部門職責範圍。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项为交付人寿保单的最常见方法?",o:["普通邮递","挂号邮递","销售代理人负责交付","投保人亲自往保险公司总部"],a:2,e:"人寿保单最常由销售代理人亲自交付给投保人，以便当面解释内容并取得收据确认；普通邮递、挂号邮递及投保人亲往总部均非主流交付方式。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項為交付人壽保單的最常見方法？",o:["普通郵遞","掛號郵遞","銷售代理人負責交付","投保人親自往保險公司總部"],e:"人壽保單最常由銷售代理人親自交付給投保人，以便當面解釋內容並取得收據確認；普通郵遞、掛號郵遞及投保人親往總部均非主流交付方式。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项为理赔情况,保险人需要特别留意或展开调查? i 受保保单所有人在保单生效初期死亡 ii 80岁自然死亡 iii 受保保单所有人在免责期内自杀 iv 受保保单所有人死亡原因有可疑",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"保单生效初期死亡、免责期内自杀及死因可疑均属异常情况，保险人需特别调查（i、iii、iv）；80岁自然死亡属高龄正常死亡，通常无需特别调查（ii）。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項為理賠情況，保險人需要特別留意或展開調查？ i 受保保單所有人在保單生效初期死亡 ii 80歲自然死亡 iii 受保保單所有人在免責期內自殺 iv 受保保單所有人死亡原因有可疑",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"保單生效初期死亡、免責期內自殺及死因可疑均屬異常情況，保險人需特別調查（i、iii、iv）；80歲自然死亡屬高齡正常死亡，通常無需特別調查（ii）。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项功能较不可能直接涉及理赔部?",o:["就一份保单进行核保工作","日常理赔的行政和处理工作以及有关的查询","核证近因的调查工作","审阅已去世受保保单所有人的验尸报告"],a:0,e:"核保是承保阶段选择风险的工作，属核保部门而非理赔部；处理日常理赔行政与查询、调查近因、审阅验尸报告均为理赔部职能。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項功能較不可能直接涉及理賠部？",o:["就一份保單進行核保工作","日常理賠的行政和處理工作以及有關的查詢","核證近因的調查工作","審閱已去世受保保單所有人的驗屍報告"],e:"核保是承保階段選擇風險的工作，屬核保部門而非理賠部；處理日常理賠行政與查詢、調查近因、審閲驗屍報告均為理賠部職能。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项属于要求主诊医生声明的一般理由?",o:["要求的保险金额很高","投保人已超过某个特定年龄","就投保单上所披露的某些健康资料须作进一步调查","以上所有各项"],a:3,e:"保额很高、投保人超过某个特定年龄、就投保单披露的健康资料须进一步查证，均构成要求主诊医生声明的常见理由，故三项全对。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項屬於要求主診醫生聲明的一般理由？",o:["要求的保險金額很高","投保人已超過某個特定年齡","就投保單上所披露的某些健康資料須作進一步調查","以上所有各項"],e:"保額很高、投保人超過某個特定年齡、就投保單披露的健康資料須進一步查證，均構成要求主診醫生聲明的常見理由，故三項全對。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项或哪些属于进行人寿保险核保时与医疗报告有关的考虑因素?",o:["其内容涉及非常敏感问题","有时需要在某些特定问题上另外取得独立的问卷","这类报告的常见类型称为主诊医生报告","上述各项"],a:3,e:"医疗报告涉及敏感问题、特定情况需另取独立问卷、主诊医生报告为其常见类型，均为核保中与医疗报告有关的考虑因素，故全选。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項或哪些屬於進行人壽保險核保時與醫療報告有關的考慮因素？",o:["其內容涉及非常敏感問題","有時需要在某些特定問題上另外取得獨立的問卷","這類報告的常見類型稱為主診醫生報告","上述各項"],e:"醫療報告涉及敏感問題、特定情況需另取獨立問卷、主診醫生報告為其常見類型，均為核保中與醫療報告有關的考慮因素，故全選。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项或哪些正确描述「保单退保」的索偿处理应该注意的地方?",o:["计算未缴清的保费、贷款及利息","所有权证明","对承让人或受益人的利益","以上各项皆是"],a:3,e:"退保索偿须计算未清缴保费、贷款及利息，并核对所有权证明及承让人或受益人利益，三项皆为处理退保索偿时应注意的要点。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項或哪些正確描述「保單退保」的索償處理應該注意的地方？",o:["計算未繳清的保費、貸款及利息","所有權證明","對承讓人或受益人的利益","以上各項皆是"],e:"退保索償須計算未清繳保費、貸款及利息，並核對所有權證明及承讓人或受益人利益，三項皆為處理退保索償時應注意的要點。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项或那类必须在投保单上签名?",o:["投保人","准受保生命(如不是投保人)","两名见证人 (如投保人不识写字)","如适用,以上各类人"],a:3,e:"投保人须签名，若准受保生命并非投保人亦须签名，投保人不识写字时还须两名见证人签署，故按适用情况以上各类人都须在投保单上签名。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項或那類必須在投保單上簽名？",o:["投保人","準受保生命(如不是投保人)","兩名見證人 (如投保人不識寫字)","如適用，以上各類人"],e:"投保人須簽名，若準受保生命並非投保人亦須簽名，投保人不識寫字時還須兩名見證人簽署，故按適用情況以上各類人都須在投保單上簽名。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项是优质顾客服务的重要性?",o:["提高客户忠诚度","提高生产及盈利能力","藉着现有客户寻找新客户","以上各项皆是"],a:3,e:"优质顾客服务能提高客户忠诚度、提升生产及盈利能力，并藉现有客户寻找新客户，三项均为其重要性之所在。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項是優質顧客服務的重要性？",o:["提高客户忠誠度","提高生產及盈利能力","藉着現有客户尋找新客户","以上各項皆是"],e:"優質顧客服務能提高客户忠誠度、提升生產及盈利能力，並藉現有客户尋找新客户，三項均為其重要性之所在。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项是正确的描述?",o:["寿险核保的工作是每年保单周年时均需要的工作","寿险核保只牵涉保费计算","核保是涉及风险的可保性及决定采用什么保险条款的问题","上述所有各项"],a:2,e:"核保是评核风险可保性并决定采用什么保险条款的过程，而非每年保单周年均需进行的工作，亦不只牵涉保费计算；其余两项描述均错误。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項是正確的描述？",o:["壽險核保的工作是每年保單週年時均需要的工作","壽險核保只牽涉保費計算","核保是涉及風險的可保性及決定採用什麼保險條款的問題","上述所有各項"],e:"核保是評核風險可保性並決定採用什麼保險條款的過程，而非每年保單週年均需進行的工作，亦不只牽涉保費計算；其餘兩項描述均錯誤。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项正确描述「立约保费收据」? i 又称为不附条件保费收据 ii 此收据是独立于其后所发签的任何保单 iii 保障会以事后能否证明投保人可保为条件 iv 保障可能在指定期的最后一天提前终止",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],a:1,e:"立约保费收据又称不附条件保费收据（i）、独立于其后签发的保单（ii），保障限于指定期内且可能在指定期最后一天提前终止（iv）；它不以事后证明可保为条件（iii错），附条件收据才如此。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項正確描述「立約保費收據」？ i 又稱為不附條件保費收據 ii 此收據是獨立於其後所發簽的任何保單 iii 保障會以事後能否證明投保人可保為條件 iv 保障可能在指定期的最後一天提前終止",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, ii, iii, iv"],e:"立約保費收據又稱不附條件保費收據（i）、獨立於其後簽發的保單（ii），保障限於指定期內且可能在指定期最後一天提前終止（iv）；它不以事後證明可保為條件（iii錯），附條件收據才如此。"}},
{p:3,ch:"人寿保险程序",q:"下面关于「冷静期」的时段描述中,哪项是正确的?",o:["「冷静期」的时段为将保单交付,或将(通知书)发予保单持有人或其代表后, 起计21天,以较先者为准","「冷静期」的时段为将保单交付,或将(通知书)发予保单持有人或其代表后, 起计21天,以较后者为准","「冷静期」的时段为将保单交付给保单持有人或收到保费后,起计21天, 以较后者为准","以上皆不正确"],a:0,e:"冷静期自保单交付或通知书发予保单持有人或其代表两者中较先者起计21天；以较后者为准或与收保费挂钩的说法均不正确。",src:1,tw:{ch:"人壽保險程序",q:"下面關於「冷靜期」的時段描述中，哪項是正確的？",o:["「冷靜期」的時段為將保單交付，或將(通知書)發予保單持有人或其代表後， 起計21天，以較先者為準","「冷靜期」的時段為將保單交付，或將(通知書)發予保單持有人或其代表後， 起計21天，以較後者為準","「冷靜期」的時段為將保單交付給保單持有人或收到保費後，起計21天， 以較後者為準","以上皆不正確"],e:"冷靜期自保單交付或通知書發予保單持有人或其代表兩者中較先者起計21天；以較後者為準或與收保費掛鈎的說法均不正確。"}},
{p:3,ch:"人寿保险程序",q:"下面关于宣布保单红利的陈述中,哪项是正确的?",o:["个别公司的宣布保单红利政策须遵守具体的自律规管措施","保险人一般保留决定红利金额的权利","分红保单设有条文,保证了最低红利额","典型的分红保单在首三个保单年度内不付红利"],a:1,e:"红利并非保证，保险人一般保留按汇集基金业绩决定红利金额的权利；分红保单一般不设保证最低红利额，且宣告政策并非常规自律措施，首三年不派红利的说法亦不典型。",src:1,tw:{ch:"人壽保險程序",q:"下面關於宣佈保單紅利的陳述中，哪項是正確的？",o:["個別公司的宣佈保單紅利政策須遵守具體的自律規管措施","保險人一般保留決定紅利金額的權利","分紅保單設有條文，保證了最低紅利額","典型的分紅保單在首三個保單年度內不付紅利"],e:"紅利並非保證，保險人一般保留按彙集基金業績決定紅利金額的權利；分紅保單一般不設保證最低紅利額，且宣告政策並非常規自律措施，首三年不派紅利的說法亦不典型。"}},
{p:3,ch:"人寿保险程序",q:"与一般保险比较,人寿保险的核保过程显得较为重要,因为:",o:["保额较高","差不多所有人寿保险均导致索偿","受保生命可能在可以修订条款前过世","保单不能被取消,而且没有另一个机会重新核保"],a:3,e:"人寿保单签发后保险人一般无权取消，核保一旦完成便没有再次核保的机会，故正确核保尤为重要；保额高低或人人最终索偿并非最主要原因。",src:1,tw:{ch:"人壽保險程序",q:"與一般保險比較，人壽保險的核保過程顯得較為重要，因為：",o:["保額較高","差不多所有人壽保險均導致索償","受保生命可能在可以修訂條款前過世","保單不能被取消，而且沒有另一個機會重新核保"],e:"人壽保單簽發後保險人一般無權取消，核保一旦完成便沒有再次核保的機會，故正確核保尤為重要；保額高低或人人最終索償並非最主要原因。"}},
{p:3,ch:"人寿保险程序",q:"与投资相连保单相比,分红保单有以下哪项优点:",o:["灵活性高","风险比较低","高透明度的保险运作","保单价值由独立精算师监管"],a:1,e:"分红保单收益较平稳且部分利益有保证，风险比投资相连保单低；灵活性高、透明度高及由独立精算师监管属投资相连保单特点，故不选其余各项。",src:1,tw:{ch:"人壽保險程序",q:"與投資相連保單相比，分紅保單有以下哪項優點：",o:["靈活性高","風險比較低","高透明度的保險運作","保單價值由獨立精算師監管"],e:"分紅保單收益較平穩且部分利益有保證，風險比投資相連保單低；靈活性高、透明度高及由獨立精算師監管屬投資相連保單特點，故不選其餘各項。"}},
{p:3,ch:"人寿保险程序",q:"与投资相连保单相比,分红保单有以下哪项好处?",o:["分红保单的所有利益均得到保证","高透明度的保险运作","保单价值由独立的精算师监管","保单持有人的回报所面临的风险比较低"],a:3,e:"分红保单回报较平稳，保单持有人回报所面临的风险比较低；其利益并非全部获得保证，透明度高、价值由独立精算师监管属投资相连保单的特点。",src:1,tw:{ch:"人壽保險程序",q:"與投資相連保單相比，分紅保單有以下哪項好處？",o:["分紅保單的所有利益均得到保證","高透明度的保險運作","保單價值由獨立的精算師監管","保單持有人的回報所面臨的風險比較低"],e:"分紅保單回報較平穩，保單持有人回報所面臨的風險比較低；其利益並非全部獲得保證，透明度高、價值由獨立精算師監管屬投資相連保單的特點。"}},
{p:3,ch:"人寿保险程序",q:"为何在人寿保险保单中,正确地评核风险是十分重要的?",o:["因为人寿保险保单的保额一般较高","因为人寿保险保单的风险核保只进行一次","因为人寿保险保单的赔偿一定会发生","因为受保人在保单更改前已死"],a:1,e:"人寿保单的核保通常只在投保时进行一次，签发后不能取消或重核，故正确评核风险尤为重要；保额较高、赔偿必发生非直接主因。",src:1,tw:{ch:"人壽保險程序",q:"為何在人壽保險保單中，正確地評核風險是十分重要的？",o:["因為人壽保險保單的保額一般較高","因為人壽保險保單的風險核保只進行一次","因為人壽保險保單的賠償一定會發生","因為受保人在保單更改前已死"],e:"人壽保單的核保通常只在投保時進行一次，簽發後不能取消或重核，故正確評核風險尤為重要；保額較高、賠償必發生非直接主因。"}},
{p:3,ch:"人寿保险程序",q:"为保障消费者的权益,客户在同意购买或决定是否购买之前,必须完成一项文件,该文件为:",o:["冷静期声明","所有权证明","客户保障声明书","消费者保障声明书"],a:2,e:"为保障消费者权益，客户在同意购买或决定购买前须完成「客户保障声明书」，以确认知悉重要事项；其余各项并非该强制签署的文件。",src:1,tw:{ch:"人壽保險程序",q:"為保障消費者的權益，客戶在同意購買或決定是否購買之前，必須完成一項文件，該文件為：",o:["冷靜期聲明","所有權證明","客戶保障聲明書","消費者保障聲明書"],e:"為保障消費者權益，客户在同意購買或決定購買前須完成「客户保障聲明書」，以確認知悉重要事項；其餘各項並非該強制簽署的文件。"}},
{p:3,ch:"人寿保险程序",q:"为确定公平的保费,保险人一般将建议风险分为哪些类别? i. 标准风险 ii. 次标准风险 iii. 拒保风险 iv. 优良风险",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各项皆是"],a:3,e:"为订立公平保费，保险人通常将风险分为标准、次标准、拒保及优良风险四类，四项全属常见风险类别。",src:1,tw:{ch:"人壽保險程序",q:"為確定公平的保費，保險人一般將建議風險分為哪些類別？ i. 標準風險 ii. 次標準風險 iii. 拒保風險 iv. 優良風險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各項皆是"],e:"為訂立公平保費，保險人通常將風險分為標準、次標準、拒保及優良風險四類，四項全屬常見風險類別。"}},
{p:3,ch:"人寿保险程序",q:"于人寿保险的死亡索偿,证明死亡的一般方法是:",o:["死亡证明书的正本","死亡证明书的副本","由受益人签署的声明书","以上任何一项"],a:0,e:"死亡索偿证明死亡的一般方法为出示死亡证明书的正本；副本或受益人签署的声明书通常不足以作为正式证明。",src:1,tw:{ch:"人壽保險程序",q:"於人壽保險的死亡索償，證明死亡的一般方法是：",o:["死亡證明書的正本","死亡證明書的副本","由受益人簽署的聲明書","以上任何一項"],e:"死亡索償證明死亡的一般方法為出示死亡證明書的正本；副本或受益人簽署的聲明書通常不足以作為正式證明。"}},
{p:3,ch:"人寿保险程序",q:"于退保时,有权收取现金价值的人需拥有什么证明?",o:["遗嘱证明","所有权证明","退保证明","授予所有权的凭证"],a:1,e:"退保时有权收取现金价值的人须出示所有权证明，以证实其为保单所有人；遗嘱证明、退保证明等并非所需的凭证。",src:1,tw:{ch:"人壽保險程序",q:"於退保時，有權收取現金價值的人需擁有什麼證明？",o:["遺囑證明","所有權證明","退保證明","授予所有權的憑證"],e:"退保時有權收取現金價值的人須出示所有權證明，以證實其為保單所有人；遺囑證明、退保證明等並非所需的憑證。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险人透过签发其中一种的保费收据,表示同意有关保险于投保时开始生效,但须于稍后证实投保人按 照标准条款是属于可保的。这种收据称为:",o:["暂时性保费收据","立约保费收据","附条件保费收据","临时性保费收据"],a:2,e:"附条件保费收据表示保险于投保时开始生效，但以事后证实投保人按标准条款可保为条件；立约（不附条件）收据则不经此条件而直接提供限期保障。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險人透過簽發其中一種的保費收據，表示同意有關保險於投保時開始生效，但須於稍後證實投保人按 照標準條款是屬於可保的。這種收據稱為：",o:["暫時性保費收據","立約保費收據","附條件保費收據","臨時性保費收據"],e:"附條件保費收據表示保險於投保時開始生效，但以事後證實投保人按標準條款可保為條件；立約（不附條件）收據則不經此條件而直接提供限期保障。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险保单的准备及交付十分重要,因为:",o:["只适用于替配偶购买","以防竞争者将来有一套较有效律的制度","避免将来的麻烦","保单的更改需要保单所有人的同意,否则不可更改或取消"],a:3,e:"人寿保单签发交付后，任何更改都须经保单所有人同意，否则不可更改或取消，故准备与交付阶段须格外慎重以免日后麻烦；其余选项与主因无关。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險保單的準備及交付十分重要，因為：",o:["只適用於替配偶購買","以防競爭者將來有一套較有效律的制度","避免將來的麻煩","保單的更改需要保單所有人的同意，否則不可更改或取消"],e:"人壽保單簽發交付後，任何更改都須經保單所有人同意，否則不可更改或取消，故準備與交付階段須格外慎重以免日後麻煩；其餘選項與主因無關。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险保单的签发和交付比非人寿保险重要,因为:",o:["这受法律所管限","寿险保单保额较大","寿险保单签发和交付后,保险人无权取消或更改","非人寿保单保障的物品比较不重要"],a:2,e:"寿险保单签发和交付后，保险人即无权取消或更改，故签发与交付比非人寿保险更重要；法律管限、保额较大、非寿险物品不重要等非根本原因。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險保單的簽發和交付比非人壽保險重要，因為：",o:["這受法律所管限","壽險保單保額較大","壽險保單簽發和交付後，保險人無權取消或更改","非人壽保單保障的物品比較不重要"],e:"壽險保單簽發和交付後，保險人即無權取消或更改，故簽發與交付比非人壽保險更重要；法律管限、保額較大、非壽險物品不重要等非根本原因。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险核保可被分为两个程序,就是确定风险程度,及:",o:["将建议风险分类","决定合适的保单计划","选择合适的再保险","确定可保权益的程度"],a:0,e:"人寿保险核保可分为确定风险程度及将建议风险分类两个程序，前者评核可保性，后者据此订立公平保费。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險核保可被分為兩個程序，就是確定風險程度，及：",o:["將建議風險分類","決定合適的保單計劃","選擇合適的再保險","確定可保權益的程度"],e:"人壽保險核保可分為確定風險程度及將建議風險分類兩個程序，前者評核可保性，後者據此訂立公平保費。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险核保的主要元素,是与增加受保事件,死亡发生率的客观因素有关,这是:",o:["道德危险","实质危险","量化评估","非客观评估"],a:1,e:"与增加受保事件（死亡）发生率的客观因素有关的是实质危险；道德危险涉及主观诚信与意向，量化评估、非客观评估并非核保危险类别。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險核保的主要元素，是與增加受保事件，死亡發生率的客觀因素有關，這是:",o:["道德危險","實質危險","量化評估","非客觀評估"],e:"與增加受保事件（死亡）發生率的客觀因素有關的是實質危險；道德危險涉及主觀誠信與意向，量化評估、非客觀評估並非核保危險類別。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险根据实质危险及道德危险核保确定有关风险程度,以下哪项因素是正确的描述?",o:["与实质危险相比,道德危险较难确定","实质危险涉及较主观的因素,环绕准被保人的基本诚信或正直意向, 道德危险主要考虑到可能增加受保事件发生率的客观因素","实质危险主要考虑诚信因素,道德危险主要考虑家族遗传因素","实质危险主要考虑正直意向因素,道德危险主要考虑高危职业或消闲活动因素"],a:0,e:"道德危险关乎准被保人的主观诚信意向，较难确定；实质危险是客观、可量化地增加死亡率的外在因素，评估相对容易，其余选项把两者内容颠倒。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險根據實質危險及道德危險核保確定有關風險程度，以下哪項因素是正確的描述?",o:["與實質危險相比，道德危險較難確定","實質危險涉及較主觀的因素，環繞準被保人的基本誠信或正直意向， 道德危險主要考慮到可能增加受保事件發生率的客觀因素","實質危險主要考慮誠信因素，道德危險主要考慮家族遺傳因素","實質危險主要考慮正直意向因素，道德危險主要考慮高危職業或消閒活動因素"],e:"道德危險關乎準被保人的主觀誠信意向，較難確定；實質危險是客觀、可量化地增加死亡率的外在因素，評估相對容易，其餘選項把兩者內容顛倒。"}},
{p:3,ch:"人寿保险程序",q:"人寿保险的死亡索偿,必须确定死亡日期,这是因为:",o:["递减定期寿险的赔付金额","分红保单的红利计算","定期保险可能已经过了期","以上皆是"],a:3,e:"确定死亡日期关系到递减定期寿险的赔付金额、分红保单的红利计算以及定期保险是否已经过期，三项均须据此判定，故全选。",src:1,tw:{ch:"人壽保險程序",q:"人壽保險的死亡索償，必須確定死亡日期，這是因為：",o:["遞減定期壽險的賠付金額","分紅保單的紅利計算","定期保險可能已經過了期","以上皆是"],e:"確定死亡日期關係到遞減定期壽險的賠付金額、分紅保單的紅利計算以及定期保險是否已經過期，三項均須據此判定，故全選。"}},
{p:3,ch:"人寿保险程序",q:"以下不大可能是理赔部门的职能?",o:["日常行政","调查工作","核保工作","处理各类型的索偿"],a:2,e:"理赔部门负责日常行政、调查工作及处理各类型索偿；核保属承保阶段的职能，不大可能由理赔部负责。",src:1,tw:{ch:"人壽保險程序",q:"以下不大可能是理賠部門的職能？",o:["日常行政","調查工作","核保工作","處理各類型的索償"],e:"理賠部門負責日常行政、調查工作及處理各類型索償；核保屬承保階段的職能，不大可能由理賠部負責。"}},
{p:3,ch:"人寿保险程序",q:"以下哪一项不大可能属于退保索偿时考虑之因素?",o:["所有权证明","死亡证","照顾任何受益人的权益","调整未清缴的保费"],a:1,e:"退保索偿须考虑所有权证明、照顾受益人权益及调整未清缴保费；死亡证用于死亡索偿，与退保无关，故不大可能属于退保考虑因素。",src:1,tw:{ch:"人壽保險程序",q:"以下哪一項不大可能屬於退保索償時考慮之因素？",o:["所有權證明","死亡證","照顧任何受益人的權益","調整未清繳的保費"],e:"退保索償須考慮所有權證明、照顧受益人權益及調整未清繳保費；死亡證用於死亡索償，與退保無關，故不大可能屬於退保考慮因素。"}},
{p:3,ch:"人寿保险程序",q:"以下哪一项是保单所有人服务部的范围?",o:["索偿管理","权益管理","广告及市场推广","以上皆是"],a:1,e:"保单所有人服务部（POS）负责权益管理及更改保单、通讯等售后服务；索偿管理属理赔部，广告及市场推广属市场行销部，故只有权益管理属POS。",src:1,tw:{ch:"人壽保險程序",q:"以下哪一項是保單所有人服務部的範圍?",o:["索償管理","權益管理","廣告及市場推廣","以上皆是"],e:"保單所有人服務部（POS）負責權益管理及更改保單、通訊等售後服務；索償管理屬理賠部，廣告及市場推廣屬市場行銷部，故只有權益管理屬POS。"}},
{p:3,ch:"人寿保险程序",q:"以下哪三项对于退保索偿来说是最重要的? i 所有权证明 ii 死亡证明书的正本 iii 合适的解除责任凭证及给付证明文件 iv 就任何尚未缴清的保费、贷款及利息作出调整",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:3,e:"退保索偿最重要的是所有权证明（i）、合适的解除责任凭证及给付证明（iii）以及就未清缴保费、贷款及利息作出调整（iv）；死亡证明书正本属死亡索偿（ii不合）。",src:1,tw:{ch:"人壽保險程序",q:"以下哪三項對於退保索償來說是最重要的？ i 所有權證明 ii 死亡證明書的正本 iii 合適的解除責任憑證及給付證明文件 iv 就任何尚未繳清的保費、貸款及利息作出調整",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],e:"退保索償最重要的是所有權證明（i）、合適的解除責任憑證及給付證明（iii）以及就未清繳保費、貸款及利息作出調整（iv）；死亡證明書正本屬死亡索償（ii不合）。"}},
{p:3,ch:"人寿保险程序",q:"以下哪三项有关人寿保险保单核保的陈述是正确的? i.  对于一项特定的风险,不存在试验的机会 ii. 涉及评核风险的可保性 iii. 在最初核保时所犯的错误,只能于续保时提出纠正 iv. 由于人寿保险没设有取消条款,故此核保重要性是很大的",o:["i, ii,iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:1,e:"寿险核保不设「试验」机会（i）、涉及评核风险可保性（ii），且因保单不设取消条款而格外重要（iv）；最初核保错误只能续保时纠正的说法错误（iii），因寿险通常只在投保时核保一次。",src:1,tw:{ch:"人壽保險程序",q:"以下哪三項有關人壽保險保單核保的陳述是正確的？ i. 對於一項特定的風險，不存在試驗的機會 ii. 涉及評核風險的可保性 iii. 在最初核保時所犯的錯誤，只能於續保時提出糾正 iv. 由於人壽保險沒設有取消條款，故此核保重要性是很大的",o:["i, ii,iii","i, ii, iv","ii, iii, iv","i, iii, iv"],e:"壽險核保不設「試驗」機會（i）、涉及評核風險可保性（ii），且因保單不設取消條款而格外重要（iv）；最初核保錯誤只能續保時糾正的說法錯誤（iii），因壽險通常只在投保時核保一次。"}},
{p:3,ch:"人寿保险程序",q:"以下哪些属于财务性核保,而非技术性核保:",o:["受保人的健康","受保人的态度和行为","所建议的保额过高","以上各项皆是"],a:2,e:"所建议保额过高涉及财务合理性，属财务性核保；受保人的健康、态度与行为均属技术性核保内容。",src:1,tw:{ch:"人壽保險程序",q:"以下哪些屬於財務性核保，而非技術性核保：",o:["受保人的健康","受保人的態度和行為","所建議的保額過高","以上各項皆是"],e:"所建議保額過高涉及財務合理性，屬財務性核保；受保人的健康、態度與行為均屬技術性核保內容。"}},
{p:3,ch:"人寿保险程序",q:"以下哪些是冷静期规定时段的正确描述?",o:["将「通知书」发予保单持有人后,或缴交保费后,起计21天,以较后者为准","新保单交付,或将「通知书」发予保单持有人或其代表后,起计21天,以较后者为准","将「通知书」发予保单持有人后,或缴交保费后,起计21天,以较先者为准","以上皆不是"],a:3,e:"冷静期为由新保单交付或通知书发予保单持有人后起计21天、以较先者为准；题干各选项（较后者或与缴保费挂钩）均不符合规定，故全错。",src:1,tw:{ch:"人壽保險程序",q:"以下哪些是冷靜期規定時段的正確描述？",o:["將「通知書」發予保單持有人後，或繳交保費後，起計21天，以較後者為準","新保單交付，或將「通知書」發予保單持有人或其代表後，起計21天，以較後者為準","將「通知書」發予保單持有人後，或繳交保費後，起計21天，以較先者為準","以上皆不是"],e:"冷靜期為由新保單交付或通知書發予保單持有人後起計21天、以較先者為準；題幹各選項（較後者或與繳保費掛鈎）均不符合規定，故全錯。"}},
{p:3,ch:"人寿保险程序",q:"以下哪种类别的人寿保险保单可由获授权保险人选择是否发出有效利益说明?",o:["个人人寿保险保单","投资相连寿险计划保单","完全清缴保险","分红保单"],a:1,e:"投资相连寿险计划保单可由获授权保险人选择是否发出有效利益说明；个人人寿、完全清缴保险及分红保单另有规定，不属此选项。",src:1,tw:{ch:"人壽保險程序",q:"以下哪種類別的人壽保險保單可由獲授權保險人選擇是否發出有效利益說明？",o:["個人人壽保險保單","投資相連壽險計劃保單","完全清繳保險","分紅保單"],e:"投資相連壽險計劃保單可由獲授權保險人選擇是否發出有效利益說明；個人人壽、完全清繳保險及分紅保單另有規定，不屬此選項。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项不可能是保单通常更改的项目?",o:["保险保障种类","受保人的身份","受益人的身份","以上皆是可能被更改"],a:1,e:"保险保障种类、受益人及保单持有人身份经双方同意可在签发后更改；受保人的身份是风险评核的基础，一般不属可更改项目。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項不可能是保單通常更改的項目？",o:["保險保障種類","受保人的身份","受益人的身份","以上皆是可能被更改"],e:"保險保障種類、受益人及保單持有人身份經雙方同意可在簽發後更改；受保人的身份是風險評核的基礎，一般不屬可更改項目。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项不大可能是人寿保险公司市场行销部的责任?",o:["市场调查","产品研究","理赔检讨","推广/宣传"],a:2,e:"理赔检讨属理赔或核保范畴，并非市场行销职责；市场调查、产品研究、推广宣传均属人寿保险公司市场行销部的工作。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項不大可能是人壽保險公司市場行銷部的責任？",o:["市場調查","產品研究","理賠檢討","推廣/宣傳"],e:"理賠檢討屬理賠或核保範疇，並非市場行銷職責；市場調查、產品研究、推廣宣傳均屬人壽保險公司市場行銷部的工作。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项为人寿保险人对不可接受的风险术语?",o:["被拒绝风险","拒保风险","不可保风险","不可接受风险"],a:1,e:"人寿保险对不可接受风险的术语称为「拒保风险」，指因健康或其他因素导致无法承保的建议风险；被拒绝风险、不可保风险等并非标准术语。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項為人壽保險人對不可接受的風險術語？",o:["被拒絕風險","拒保風險","不可保風險","不可接受風險"],e:"人壽保險對不可接受風險的術語稱為「拒保風險」，指因健康或其他因素導致無法承保的建議風險；被拒絕風險、不可保風險等並非標準術語。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项保险计划会提供保险凭证和成员登记卡等文件?",o:["人寿保险","团体寿险","家居保险","商业保险"],a:1,e:"团体寿险除总保单外，会向每位成员提供保险凭证及成员登记卡等文件；个人寿险、家居保险及商业保险一般不签发此类文件。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項保險計劃會提供保險憑證和成員登記卡等文件?",o:["人壽保險","團體壽險","家居保險","商業保險"],e:"團體壽險除總保單外，會向每位成員提供保險憑證及成員登記卡等文件；個人壽險、家居保險及商業保險一般不簽發此類文件。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项关于保险公司宣布保单红利的政策是正确的?",o:["保险公司保留厘定红利金额的权利","保证派发红利","红利是保证上升的","个别公司遵守行业的自律监管要求"],a:0,e:"分红并非保证派发，保险公司保留厘定红利金额的权利；红利不获保证亦非保证上升，行业自律监管要求并非本题所指的正确政策描述。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項關於保險公司宣佈保單紅利的政策是正確的?",o:["保險公司保留釐定紅利金額的權利","保證派發紅利","紅利是保證上升的","個別公司遵守行業的自律監管要求"],e:"分紅並非保證派發，保險公司保留釐定紅利金額的權利；紅利不獲保證亦非保證上升，行業自律監管要求並非本題所指的正確政策描述。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项功能较不可能涉及核保部门?",o:["就保险风险作技术性选择","为部份投保人安排身体检查","安排验尸工作","决定是否需要就某项风险安排再保险"],a:2,e:"验尸通常在死亡后发生，属理赔调查范畴；核保部门负责技术性风险选择、安排身体检查及决定再保险安排，故安排验尸较不涉及核保部门。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項功能較不可能涉及核保部門？",o:["就保險風險作技術性選擇","為部份投保人安排身體檢查","安排驗屍工作","決定是否需要就某項風險安排再保險"],e:"驗屍通常在死亡後發生，屬理賠調查範疇；核保部門負責技術性風險選擇、安排身體檢查及決定再保險安排，故安排驗屍較不涉及核保部門。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项对投保单的描述是不正确的?",o:["有些保险人称之为建议书","经修正或改动的投保单/保险人必定不会接受","它通常由投保人亲自填写","它是核保资料的来源"],a:1,e:"经修正或改动的投保单保险人不必然拒绝，「必定不会接受」过于绝对，故该陈述不正确；投保单俗称建议书、由投保人填写、是核保资料来源等均正确。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項對投保單的描述是不正確的？",o:["有些保險人稱之為建議書","經修正或改動的投保單/保險人必定不會接受","它通常由投保人親自填寫","它是核保資料的來源"],e:"經修正或改動的投保單保險人不必然拒絕，「必定不會接受」過於絕對，故該陳述不正確；投保單俗稱建議書、由投保人填寫、是核保資料來源等均正確。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项属于或不属于人寿保险的核保因素?你的理据何在?",o:["明显超重是核保因素;这与某些疾病有关联","在卡拉ok、酒吧或赌场入面工作不属于核保因素; 没有保险人会就该职业收取较高保费","体重过轻不属于核保因素;这同任何疾病扯不上关系","经营香烟贸易属于核保因素;毫无疑问,这种人不是主动吸烟者, 也是被动吸烟者"],a:0,e:"明显超重与多种疾病相关联，属增加死亡率的实质危险，故为核保因素；在卡拉OK、酒吧或赌场工作可能涉及职业或道德风险，保险人往往会收取较高保费，题干后述说法不成立。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項屬於或不屬於人壽保險的核保因素？你的理據何在？",o:["明顯超重是核保因素；這與某些疾病有關聯","在卡拉ok、酒吧或賭場入面工作不屬於核保因素； 沒有保險人會就該職業收取較高保費","體重過輕不屬於核保因素；這同任何疾病扯不上關係","經營香煙貿易屬於核保因素；毫無疑問，這種人不是主動吸煙者， 也是被動吸煙者"],e:"明顯超重與多種疾病相關聯，屬增加死亡率的實質危險，故為核保因素；在卡拉OK、酒吧或賭場工作可能涉及職業或道德風險，保險人往往會收取較高保費，題幹後述說法不成立。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项属于或不属于人寿保险的核保考虑因素?为什么这样说?",o:["体重过轻不属于核保考虑因素,这不涉及任何其他疾病","在卡拉ok、酒吧或赌场入面工作不属于核保因素;没有保险人会就该职业收取较高保费","体重过轻是核保考虑因素;因可能与其他疾病有联系","经营香烟贸易是核保考虑因素,因为容易有很多疾病"],a:2,e:"体重过轻可能与其他疾病有联系，属核保须考虑的因素；「在卡拉OK、酒吧或赌场工作不属核保因素」的说法错误，香烟贸易是否因疾病而属核保因素的理据亦不准确。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項屬於或不屬於人壽保險的核保考慮因素？為什麼這樣說？",o:["體重過輕不屬於核保考慮因素，這不涉及任何其他疾病","在卡拉ok、酒吧或賭場入面工作不屬於核保因素；沒有保險人會就該職業收取較高保費","體重過輕是核保考慮因素；因可能與其他疾病有聯繫","經營香煙貿易是核保考慮因素，因為容易有很多疾病"],e:"體重過輕可能與其他疾病有聯繫，屬核保須考慮的因素；「在卡拉OK、酒吧或賭場工作不屬核保因素」的說法錯誤，香煙貿易是否因疾病而屬核保因素的理據亦不準確。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项属于提供优质客户服务的原因?",o:["提升客户忠诚度","拓展客源","提升生产力及盈利","以上皆是"],a:3,e:"优质客户服务能提升客户忠诚度、拓展客源并提升生产力及盈利能力，三项均为其好处，故全选。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項屬於提供優質客戶服務的原因?",o:["提升客戶忠誠度","拓展客源","提升生產力及盈利","以上皆是"],e:"優質客户服務能提升客户忠誠度、拓展客源並提升生產力及盈利能力，三項均為其好處，故全選。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项属于财务性核保,而非技术性核保:",o:["预期受保保单所有人给付保费的能力","同一受保生命已累积购买的保单计划","是否需要再保险的安排","以上各项皆是"],a:3,e:"预期投保人缴付保费的能力、同一受保生命已累积购买的保单、是否需要再保险安排，均涉及财务合理性，属财务性而非技术性核保。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項屬於財務性核保，而非技術性核保：",o:["預期受保保單所有人給付保費的能力","同一受保生命已累積購買的保單計劃","是否需要再保險的安排","以上各項皆是"],e:"預期投保人繳付保費的能力、同一受保生命已累積購買的保單、是否需要再保險安排，均涉及財務合理性，屬財務性而非技術性核保。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项情况属于保单获签发后一年内出现可疑的死亡?",o:["法庭推定属于自杀","保险人仍需作出全额赔付","被保险人相关可能获得50%的赔偿","保险人相当可能需要作出通融赔付"],a:0,e:"保单获签发后一年内出现可疑死亡，若法庭推定属自杀，保险人通常可依自杀免责条款拒赔；全额赔付、50%赔偿及通融赔付均不符合此情形。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項情況屬於保單獲簽發後一年內出現可疑的死亡？",o:["法庭推定屬於自殺","保險人仍需作出全額賠付","被保險人相關可能獲得50%的賠償","保險人相當可能需要作出通融賠付"],e:"保單獲簽發後一年內出現可疑死亡，若法庭推定屬自殺，保險人通常可依自殺免責條款拒賠；全額賠付、50%賠償及通融賠付均不符合此情形。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些不大可能为保单所有人服务部(POS)的职能范围呢?",o:["索偿处理","权益管理","通讯","更改保单"],a:0,e:"保单所有人服务部（POS）负责权益管理、通讯及更改保单等售后服务；索偿处理属理赔部门，故不大可能属于POS的职能范围。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些不大可能為保單所有人服務部(POS)的職能範圍呢？",o:["索償處理","權益管理","通訊","更改保單"],e:"保單所有人服務部（POS）負責權益管理、通訊及更改保單等售後服務；索償處理屬理賠部門，故不大可能屬於POS的職能範圍。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些不属代理培训与管理部门的职能?",o:["代理队伍的培训需要","保险公司的定价策略","专业考试","事业发展中的资源和设施"],a:1,e:"定价策略属精算或公司管理层范畴，代理培训与管理部门负责代理队伍的培训需要、专业考试及事业发展的资源和设施，故定价策略不属其职能。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些不屬代理培訓與管理部門的職能？",o:["代理隊伍的培訓需要","保險公司的定價策略","專業考試","事業發展中的資源和設施"],e:"定價策略屬精算或公司管理層範疇，代理培訓與管理部門負責代理隊伍的培訓需要、專業考試及事業發展的資源和設施，故定價策略不屬其職能。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些为填写投保单的一般规则?",o:["必须提供所有重要事实","不能修改","必须见证","以上各项皆正确"],a:0,e:"填写投保单的一般规则是投保人须提供所有重要事实（最高诚信义务）；「不能修改」「必须见证」并非普遍适用的一般规则。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些為填寫投保單的一般規則？",o:["必須提供所有重要事實","不能修改","必須見證","以上各項皆正確"],e:"填寫投保單的一般規則是投保人須提供所有重要事實（最高誠信義務）；「不能修改」「必須見證」並非普遍適用的一般規則。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些属于实质危险?",o:["吸太多烟","明显超重","家族病史","以上各项皆是"],a:3,e:"吸太多烟、明显超重、家族病史均客观地增加死亡发生率，属实质危险，三项全是。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些屬於實質危險?",o:["吸太多煙","明顯超重","家族病史","以上各項皆是"],e:"吸太多煙、明顯超重、家族病史均客觀地增加死亡發生率，屬實質危險，三項全是。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些是实质危险而非道德危险?",o:["明显超重","烟瘾大的人","家人有心脏病病历","以上都是实质危险"],a:3,e:"明显超重、烟瘾大的人及家人有心脏病病历，均属客观增加死亡率的实质危险，而非涉及诚信意向的道德危险，故全属实质危险。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些是實質危險而非道德危險？",o:["明顯超重","煙癮大的人","家人有心臟病病歷","以上都是實質危險"],e:"明顯超重、煙癮大的人及家人有心臟病病歷，均屬客觀增加死亡率的實質危險，而非涉及誠信意向的道德危險，故全屬實質危險。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些是投保时需要考虑的重点?",o:["投保人的身份","下一个(或前一个)生日年龄","其他个人资料(包括职业、住址及病历)","以上所有各项"],a:3,e:"投保人的身份、下一个（或前一个）生日年龄及其他个人资料（包括职业、住址及病历）都是投保时须考虑的重点，故全选。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些是投保時需要考慮的重點？",o:["投保人的身份","下一個(或前一個)生日年齡","其他個人資料(包括職業、住址及病歷)","以上所有各項"],e:"投保人的身份、下一個（或前一個）生日年齡及其他個人資料（包括職業、住址及病歷）都是投保時須考慮的重點，故全選。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些是有关保险公司会计部相当可能的职务?",o:["财务收入","财务支出","法例要求的财务报告","以上所有各项"],a:3,e:"会计部负责纪录并监管财务收入、财务支出，以及编制法例要求的财务报告，三项均为其相当可能的职务。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些是有關保險公司會計部相當可能的職務？",o:["財務收入","財務支出","法例要求的財務報告","以上所有各項"],e:"會計部負責紀錄並監管財務收入、財務支出，以及編制法例要求的財務報告，三項均為其相當可能的職務。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些能够提高客户服务的效率:",o:["以客户为本的公司文化","把合理及适当的权力下放于前线雇员","设有监察客户满意程度的系统","以上各项皆是"],a:3,e:"以客户为本的公司文化、向前线雇员下放合理权力及设有监察客户满意程度的系统，皆能提高客户服务效率，三项全选。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些能夠提高客戶服務的效率：",o:["以客戶為本的公司文化","把合理及適當的權力下放於前線僱員","設有監察客戶滿意程度的系統","以上各項皆是"],e:"以客户為本的公司文化、向前線僱員下放合理權力及設有監察客户滿意程度的系統，皆能提高客户服務效率，三項全選。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或哪些较大可能为保单所有人服务部(POS)的职能范围呢?",o:["索偿处理","权益管理","推广及宣传活动","以上各项皆是"],a:1,e:"保单所有人服务部（POS）负责权益管理及通讯、更改保单等；索偿处理属理赔部，推广宣传属市场行销部，故较大可能属POS的只有权益管理。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或哪些較大可能為保單所有人服務部(POS)的職能範圍呢？",o:["索償處理","權益管理","推廣及宣傳活動","以上各項皆是"],e:"保單所有人服務部（POS）負責權益管理及通訊、更改保單等；索償處理屬理賠部，推廣宣傳屬市場行銷部，故較大可能屬POS的只有權益管理。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或那些是一项风险的实质危险而非道德危险的因素 ?",o:["吸烟","明显超重","有心脏病史的家族病历","以上各项皆是"],a:3,e:"吸烟、明显超重及有心脏病史的家族病历，均客观增加死亡率，属实质危险而非道德危险，三项全选。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或那些是一項風險的實質危險而非道德危險的因素 ?",o:["吸煙","明顯超重","有心臟病史的家族病歷","以上各項皆是"],e:"吸煙、明顯超重及有心臟病史的家族病歷，均客觀增加死亡率，屬實質危險而非道德危險，三項全選。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项或那些正描述实质风险而非道德危险﹕ i 明显超重 ii 不诚实 iii 吸烟习惯 iv 家族遗传病",o:["i, ii, iv","ii, iii","i, iii, iv","以上各项皆是"],a:2,e:"明显超重（i）、吸烟习惯（iii）、家族遗传病（iv）均为客观的实质危险；不诚实属主观的道德危险（ii），故排除。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項或那些正描述實質風險而非道德危險﹕ i 明顯超重 ii 不誠實 iii 吸煙習慣 iv 家族遺傳病",o:["i, ii, iv","ii, iii","i, iii, iv","以上各項皆是"],e:"明顯超重（i）、吸煙習慣（iii）、家族遺傳病（iv）均為客觀的實質危險；不誠實屬主觀的道德危險（ii），故排除。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是对「相互」保险公司的正确描述? i 它没有股东 ii 它由分红保单持有人共同拥有 iii 它含有相互字眼,故运作必然是相互的 iv 由董事局及高级管理层控制",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:1,e:"相互公司没有股东（i）、由分红保单持有人共同拥有（ii），运作由董事局及高级管理层控制（iv）；名称含「相互」字眼不代表必为相互经营（iii错）。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是對「相互」保險公司的正確描述？ i 它沒有股東 ii 它由分紅保單持有人共同擁有 iii 它含有相互字眼，故運作必然是相互的 iv 由董事局及高級管理層控制",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"相互公司沒有股東（i）、由分紅保單持有人共同擁有（ii），運作由董事局及高級管理層控制（iv）；名稱含「相互」字眼不代表必為相互經營（iii錯）。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是对「相互」保险公司的正确描述? i 它没有股东 ii 它由分红保单持有人共同拥有 iii 股东人数为50人或以下 iv 相互公司不能成为盈利公司",o:["i, ii,","i, ii, iv","ii, iii,","ii, iii, iv"],a:0,e:"相互保险公司没有股东、由分红保单持有人共同拥有（i、ii正确）；「股东人数50人或以下」及「不能成为盈利公司」均不正确（iii、iv错）。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是對「相互」保險公司的正確描述？ i 它沒有股東 ii 它由分紅保單持有人共同擁有 iii 股東人數為50人或以下 iv 相互公司不能成為盈利公司",o:["i, ii,","i, ii, iv","ii, iii,","ii, iii, iv"],e:"相互保險公司沒有股東、由分紅保單持有人共同擁有（i、ii正確）；「股東人數50人或以下」及「不能成為盈利公司」均不正確（iii、iv錯）。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是对相互保险公司的不正确描述?",o:["没有股东","由分红保单持有人拥有","不可变成股份公司","由董事局及高级管理层控制"],a:2,e:"相互公司没有股东、由分红保单持有人拥有、由董事局及高级管理层控制，均属正确；它可经「股份化」转为股份公司，故「不可变成股份公司」是不正确描述。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是對相互保險公司的不正確描述?",o:["沒有股東","由分紅保單持有人擁有","不可變成股份公司","由董事局及高級管理層控制"],e:"相互公司沒有股東、由分紅保單持有人擁有、由董事局及高級管理層控制，均屬正確；它可經「股份化」轉為股份公司，故「不可變成股份公司」是不正確描述。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是寿险公司的典型市场行销部的职责?",o:["公共关系","市场调查","产品研究","以上各项皆是"],a:3,e:"公共关系、市场调查及产品研究均属寿险公司市场行销部的典型职责，故全选。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是壽險公司的典型市場行銷部的職責？",o:["公共關係","市場調查","產品研究","以上各項皆是"],e:"公共關係、市場調查及產品研究均屬壽險公司市場行銷部的典型職責，故全選。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是核保人对于处理次标准的选择: i 拒绝保险 ii 增加(附加)保费 iii 提供其他计划 iv 保单负债",o:["i, ii","i, iii","i, iii, iv","以上各项皆是"],a:3,e:"核保人处理次标准的选择包括拒绝保险、增加（附加）保费、提供其他计划及保单负债等方式，四项均属可选措施。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是核保人對於處理次標準的選擇： i 拒絕保險 ii 增加(附加)保費 iii 提供其他計劃 iv 保單負債",o:["i, ii","i, iii","i, iii, iv","以上各項皆是"],e:"核保人處理次標準的選擇包括拒絕保險、增加（附加）保費、提供其他計劃及保單負債等方式，四項均屬可選措施。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是核保的合理(不一定是最完美)解释:",o:["否定被建议风险的可保性","进行风险评估","决定采用甚么保险条款","以上所有各项"],a:3,e:"核保包括否定（评核）被建议风险的可保性、进行风险评估并决定采用什么保险条款，三项皆为合理解释。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是核保的合理(不一定是最完美)解釋：",o:["否定被建議風險的可保性","進行風險評估","決定採用甚麼保險條款","以上所有各項"],e:"核保包括否定（評核）被建議風險的可保性、進行風險評估並決定採用什麼保險條款，三項皆為合理解釋。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项是精算部法律要求的核心功能?",o:["产品定价","估值","理赔及再保险","管理报告"],a:1,e:"精算部法律要求的核心功能是估值，即计算保险负债或准备金；产品定价、理赔及再保险、管理报告虽涉及精算，但估值才是法定核心。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項是精算部法律要求的核心功能？",o:["產品定價","估值","理賠及再保險","管理報告"],e:"精算部法律要求的核心功能是估值，即計算保險負債或準備金；產品定價、理賠及再保險、管理報告雖涉及精算，但估值才是法定核心。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项有关人寿保险的核保是不正确的?",o:["人寿保险核保涉及实质危险和道德危险","一般情况下,道德危险的评估比实质危险容易","一般情况下,实质危险的评估比道德危险容易","人寿保险核保不只是实质危险"],a:1,e:"实质危险是客观因素，较易评估；道德危险涉及主观诚信意向，更难确定，故「道德危险比实质危险容易」不正确，其余三项均正确。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項有關人壽保險的核保是不正確的？",o:["人壽保險核保涉及實質危險和道德危險","一般情況下，道德危險的評估比實質危險容易","一般情況下，實質危險的評估比道德危險容易","人壽保險核保不只是實質危險"],e:"實質危險是客觀因素，較易評估；道德危險涉及主觀誠信意向，更難確定，故「道德危險比實質危險容易」不正確，其餘三項均正確。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项有关投保时的补充要求是不正确的?",o:["可保性证明","缴付保费的方式","保险人报告","核保问卷"],a:2,e:"投保时的补充要求包括可保性证明、缴付保费的方式及核保问卷；「保险人报告」并非补充资料中的标准项目。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項有關投保時的補充要求是不正確的？",o:["可保性證明","繳付保費的方式","保險人報告","核保問卷"],e:"投保時的補充要求包括可保性證明、繳付保費的方式及核保問卷；「保險人報告」並非補充資料中的標準項目。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项有关期满索偿的陈述是不正确的?",o:["确认索偿人的指定权利","取得死亡证的副本","书面通知保单即将期满","以上所有"],a:1,e:"期满索偿须确认索偿人的指定权利并书面通知保单即将期满，与死亡证无关；取得死亡证副本属死亡索偿，故该陈述不正确。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項有關期滿索償的陳述是不正確的？",o:["確認索償人的指定權利","取得死亡證的副本","書面通知保單即將期滿","以上所有"],e:"期滿索償須確認索償人的指定權利並書面通知保單即將期滿，與死亡證無關；取得死亡證副本屬死亡索償，故該陳述不正確。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项有关立约保费收据的陈述是不正确的?",o:["它们又称为不附条件保费收据","它们又称为临时保险协议","它们提供了保险人不可终止的具约束力保障","保障是具约束力的,但只限于指明的日数内"],a:2,e:"立约保费收据（不附条件收据，又称临时保险协议）提供的保障具约束力但只限于指定日数内，保险人可于该期内终止；「提供不可终止的具约束力保障」说法不正确。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項有關立約保費收據的陳述是不正確的？",o:["它們又稱為不附條件保費收據","它們又稱為臨時保險協議","它們提供了保險人不可終止的具約束力保障","保障是具約束力的，但只限於指明的日數內"],e:"立約保費收據（不附條件收據，又稱臨時保險協議）提供的保障具約束力但只限於指定日數內，保險人可於該期內終止；「提供不可終止的具約束力保障」說法不正確。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项索偿只适用于储蓄保险:",o:["期满索偿","死亡索偿","退保索偿","以上皆是"],a:0,e:"期满索偿只适用于储蓄（生存）保险，指保单期满时给付；死亡索偿与退保索偿适用于各类人寿保单，故专属储蓄保险的是期满索偿。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項索償只適用於儲蓄保險：",o:["期滿索償","死亡索償","退保索償","以上皆是"],e:"期滿索償只適用於儲蓄（生存）保險，指保單期滿時給付；死亡索償與退保索償適用於各類人壽保單，故專屬儲蓄保險的是期滿索償。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项较不可能在保单内出现?",o:["下一个(或前一个)生日年龄","有关心脏病的病历","有关代理人的佣金率","所需的保单生效日期"],a:2,e:"保单内通常载有年龄、病历及生效日期等资料；代理人的佣金率属公司内部商业资料，不会在保单内出现。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項較不可能在保單內出現？",o:["下一個(或前一個)生日年齡","有關心臟病的病歷","有關代理人的佣金率","所需的保單生效日期"],e:"保單內通常載有年齡、病歷及生效日期等資料；代理人的佣金率屬公司內部商業資料，不會在保單內出現。"}},
{p:3,ch:"人寿保险程序",q:"以下哪项较不大可能直接涉及理赔部?",o:["为一份投保单进行核保的工作","日常理赔的行政和处理工作以及有关的调查","核证近因的调查工作","查核已去世受保生命的死亡报告"],a:0,e:"核保属承保阶段工作、由核保部门负责；理赔部负责日常理赔行政与查询、调查近因及查核死亡报告，故为投保单进行核保较不大可能直接涉及理赔部。",src:1,tw:{ch:"人壽保險程序",q:"以下哪項較不大可能直接涉及理賠部？",o:["為一份投保單進行核保的工作","日常理賠的行政和處理工作以及有關的調查","核証近因的調查工作","查核已去世受保生命的死亡報告"],e:"核保屬承保階段工作、由核保部門負責；理賠部負責日常理賠行政與查詢、調查近因及查核死亡報告，故為投保單進行核保較不大可能直接涉及理賠部。"}},
{p:3,ch:"人寿保险程序",q:"以下那项并非会计部主要职能?",o:["监管并纪录公司开支","监管并纪录公司应收的所有款项","提交经审核的财务报告","确定死亡及赔偿金额"],a:3,e:"确定死亡及赔偿金额属理赔部门职能，并非会计部；监管并纪录公司收支及提交经审核财务报告才是会计部主要职能。",src:1,tw:{ch:"人壽保險程序",q:"以下那項並非會計部主要職能？",o:["監管並紀錄公司開支","監管並紀錄公司應收的所有款項","提交經審核的財務報告","確定死亡及賠償金額"],e:"確定死亡及賠償金額屬理賠部門職能，並非會計部；監管並紀錄公司收支及提交經審核財務報告才是會計部主要職能。"}},
{p:3,ch:"人寿保险程序",q:"以下首三项关于非投资相连保单的销售说明的陈述中哪属于不正确?",o:["说明书只作摘要自用","说明书只显示基本计划","预期红利金额获保险人保证","以上各项皆不正确"],a:2,e:"非投资相连保单销售说明中的预期红利基于假设派息率计算，并非由保险人保证，故「预期红利金额获保险人保证」属不正确陈述。",src:1,tw:{ch:"人壽保險程序",q:"以下首三項關於非投資相連保單的銷售說明的陳述中哪屬於不正確？",o:["說明書只作摘要自用","說明書只顯示基本計劃","預期紅利金額獲保險人保證","以上各項皆不正確"],e:"非投資相連保單銷售說明中的預期紅利基於假設派息率計算，並非由保險人保證，故「預期紅利金額獲保險人保證」屬不正確陳述。"}},
{p:3,ch:"人寿保险程序",q:"保单所有人服务 (POS)负责以下职责,除了:",o:["文件处理","收取保费","核保","通讯"],a:2,e:"保单所有人服务（POS）负责文件处理、收取保费及通讯等售后服务；核保属承保部门职能，POS不负责，故「除了」核保。",src:1,tw:{ch:"人壽保險程序",q:"保單所有人服務 (POS)負責以下職責，除了:",o:["文件處理","收取保費","核保","通訊"],e:"保單所有人服務（POS）負責文件處理、收取保費及通訊等售後服務；核保屬承保部門職能，POS不負責，故「除了」核保。"}},
{p:3,ch:"人寿保险程序",q:"保单所有人服务又称:",o:["保单交付部","保单签发部","售后服务部","行政及人事部"],a:2,e:"保单所有人服务（POS）即售后服务，故又称售后服务部；保单交付部、保单签发部、行政及人事部并非其别称。",src:1,tw:{ch:"人壽保險程序",q:"保單所有人服務又稱：",o:["保單交付部","保單簽發部","售後服務部","行政及人事部"],e:"保單所有人服務（POS）即售後服務，故又稱售後服務部；保單交付部、保單簽發部、行政及人事部並非其別稱。"}},
{p:3,ch:"人寿保险程序",q:"保单更改的要求十分谨慎,因为:",o:["可能引致再保险的考虑","可能会引起严重的法律后果","可能会涉及洗黑钱活动","以上各项皆是"],a:3,e:"更改保单可能引致再保险的考虑、引起严重的法律后果，并可能涉及洗黑钱活动，故须十分谨慎，三项全选。",src:1,tw:{ch:"人壽保險程序",q:"保單更改的要求十分謹慎，因為：",o:["可能引致再保險的考慮","可能會引起嚴重的法律後果","可能會涉及洗黑錢活動","以上各項皆是"],e:"更改保單可能引致再保險的考慮、引起嚴重的法律後果，並可能涉及洗黑錢活動，故須十分謹慎，三項全選。"}},
{p:3,ch:"人寿保险程序",q:"保单条文中提供一段时间称之为冷静期,以下哪项可以让保单持有人可以再详细考虑,并允许他们就新购买 或已申请的人寿保险保单改变主意?",o:["通知书签发日期后起计9天","保单签发后起计9天","保单签发后起计两个月后","保单交付或通知书发予保单持有人或其代表后起计21天,以较先者为准"],a:3,e:"冷静期给予保单持有人重新考虑并取消保单的权利，时段为保单交付或通知书发予持有人或其代表后起计21天、以较先者为准；9天或两个月等描述均错。",src:1,tw:{ch:"人壽保險程序",q:"保單條文中提供一段時間稱之為冷靜期，以下哪項可以讓保單持有人可以再詳細考慮，並允許他們就新購買 或已申請的人壽保險保單改變主意？",o:["通知書簽發日期後起計9天","保單簽發後起計9天","保單簽發後起計兩個月後","保單交付或通知書發予保單持有人或其代表後起計21天，以較先者為準"],e:"冷靜期給予保單持有人重新考慮並取消保單的權利，時段為保單交付或通知書發予持有人或其代表後起計21天、以較先者為準；9天或兩個月等描述均錯。"}},
{p:3,ch:"人寿保险程序",q:"保险人会提供保险凭证/登记卡予下列哪种产品的受保人呢?",o:["团体保单保险","储蓄寿险","个人寿险","以上各项皆是"],a:0,e:"团体保单保险会向受保成员提供保险凭证或登记卡；储蓄寿险及个人寿险不签发此类凭证，故选团体保单保险。",src:1,tw:{ch:"人壽保險程序",q:"保險人會提供保險憑證/登記卡予下列哪種產品的受保人呢？",o:["團體保單保險","儲蓄壽險","個人壽險","以上各項皆是"],e:"團體保單保險會向受保成員提供保險憑證或登記卡；儲蓄壽險及個人壽險不簽發此類憑證，故選團體保單保險。"}},
{p:3,ch:"人寿保险程序",q:"保险人或会在其保险计划书内提及一项名为\"保费抵销\"的做法,如果要是这样,保险人应该在销售过程中:",o:["向客户详细解释清楚,任何时候,保险人可随时收回\"保费抵销\"这项选择","向客户详细解释清楚,任何时候,当客户作出这样的选择后,利率水平可以 下降的,到时客户须要恢复掏钱付保费,否则可能导致保单失效或利益额降低","向客户详细解释清楚,任何时候,当客户作出这样的选择后,死亡率水平可以 上升的,到时客户须要恢复掏钱付保费,否则可能导致保单失效或利益额降低","向客户详细解释清楚,任何时候,保险人可向客户发出14天通知,收回 \"保费抵销\"这项选择"],a:1,e:"保费抵销以保单红利抵缴保费，若其后利率水平下降而红利不足，客户须恢复缴付保费，否则保单可能失效或利益额降低，故须向客户清楚解释此风险；死亡率上升并非扣减红利的直接原因。",src:1,tw:{ch:"人壽保險程序",q:"保險人或會在其保險計劃書內提及一項名為\"保費抵銷\"的做法，如果要是這樣，保險人應該在銷售過程中：",o:["向客戶詳細解釋清楚，任何時候，保險人可隨時收回\"保費抵銷\"這項選擇","向客戶詳細解釋清楚，任何時候，當客戶作出這樣的選擇後，利率水平可以 下降的，到時客戶須要恢復掏錢付保費，否則可能導致保單失效或利益額降低","向客戶詳細解釋清楚，任何時候，當客戶作出這樣的選擇後，死亡率水平可以 上升的，到時客戶須要恢復掏錢付保費，否則可能導致保單失效或利益額降低","向客戶詳細解釋清楚，任何時候，保險人可向客戶發出14天通知，收回 \"保費抵銷\"這項選擇"],e:"保費抵銷以保單紅利抵繳保費，若其後利率水平下降而紅利不足，客户須恢復繳付保費，否則保單可能失效或利益額降低，故須向客户清楚解釋此風險；死亡率上升並非扣減紅利的直接原因。"}},
{p:3,ch:"人寿保险程序",q:"保险人最常要求的医疗报告APS的全写为:",o:["辅助的医疗报告 (Ancillary Physical Statement)","实质医疗的声明 (Actual Physical Statement)","附加的医疗声明 (Additional Physcial Statement)","主诊医生报告 (Attending Physician's Statement)"],a:3,e:"APS全写为 Attending Physician's Statement，即主诊医生报告，是保险人就投保人健康资料作进一步核保时最常要求的医疗报告。",src:1,tw:{ch:"人壽保險程序",q:"保險人最常要求的醫療報告APS的全寫為：",o:["輔助的醫療報告 (Ancillary Physical Statement)","實質醫療的聲明 (Actual Physical Statement)","附加的醫療聲明 (Additional Physcial Statement)","主診醫生報告 (Attending Physician's Statement)"],e:"APS全寫為 Attending Physician's Statement，即主診醫生報告，是保險人就投保人健康資料作進一步核保時最常要求的醫療報告。"}},
{p:3,ch:"人寿保险程序",q:"保险人须进一步调查投保单中所披露的某些健康资料,最常要求的医疗报告称为:",o:["特殊问卷","详细报告","主诊医生报告","体检医生报告"],a:2,e:"保险人须进一步调查投保单披露的某些健康资料时，最常要求的医疗报告称为主诊医生报告（APS）；特殊问卷、详细报告、体检医生报告并非此标准名称。",src:1,tw:{ch:"人壽保險程序",q:"保險人須進一步調查投保單中所披露的某些健康資料，最常要求的醫療報告稱為：",o:["特殊問卷","詳細報告","主診醫生報告","體檢醫生報告"],e:"保險人須進一步調查投保單披露的某些健康資料時，最常要求的醫療報告稱為主診醫生報告（APS）；特殊問卷、詳細報告、體檢醫生報告並非此標準名稱。"}},
{p:3,ch:"人寿保险程序",q:"保险代理人签发一张附条件保费收据给投保人,但保险公司事后才发现投保人于投保时是不可保的,这表示 :",o:["合约从未生效","如投保额在三十万以下,则合约生效","赔偿上限是50%的投保额","临时性保费收据"],a:0,e:"附条件保费收据的保障以投保人当时可按标准条款承保为前提，事后发现不可保即条件不成立，合约从未生效；「30万以下生效」「赔50%」等说法均不正确。",src:1,tw:{ch:"人壽保險程序",q:"保險代理人簽發一張附條件保費收據給投保人，但保險公司事後才發現投保人於投保時是不可保的，這表示 ：",o:["合約從未生效","如投保額在三十萬以下，則合約生效","賠償上限是50%的投保額","臨時性保費收據"],e:"附條件保費收據的保障以投保人當時可按標準條款承保為前提，事後發現不可保即條件不成立，合約從未生效；「30萬以下生效」「賠50%」等說法均不正確。"}},
{p:3,ch:"人寿保险程序",q:"保险公司会计部的主要职能和责任包括: i 记录公司收入 ii 监管公司支出 iii 提交已审核的财务报告 iv 处理电话投诉",o:["i. ii, iii","i. iii, iv","ii. iii, iv","以上各项皆是"],a:0,e:"会计部负责记录公司收入、监管公司支出并提交经审核财务报告（i、ii、iii）；处理电话投诉属顾客服务部门，故iv不属会计部职能。",src:1,tw:{ch:"人壽保險程序",q:"保險公司會計部的主要職能和責任包括： i 記錄公司收入 ii 監管公司支出 iii 提交已審核的財務報告 iv 處理電話投訴",o:["i. ii, iii","i. iii, iv","ii. iii, iv","以上各項皆是"],e:"會計部負責記錄公司收入、監管公司支出並提交經審核財務報告（i、ii、iii）；處理電話投訴屬顧客服務部門，故iv不屬會計部職能。"}},
{p:3,ch:"人寿保险程序",q:"保险公司对待特定风险,核保人不仅需电留意该风险所代表的道德及实质危险,还需注意保险金额及有关个 人对保险人有否任何累积影响,其中后者可被描述为:",o:["财务性核保","额外危险核保","非技术性核保","外来因素核保"],a:0,e:"除道德及实质危险外，核保人还须注意保险金额及有关个人对保险人的累积影响，此即财务性核保；额外危险、非技术性、外来因素核保均非标准术语。",src:1,tw:{ch:"人壽保險程序",q:"保險公司對待特定風險，核保人不僅需電留意該風險所代表的道德及實質危險，還需注意保險金額及有關個 人對保險人有否任何累積影響，其中後者可被描述為：",o:["財務性核保","額外危險核保","非技術性核保","外來因素核保"],e:"除道德及實質危險外，核保人還須注意保險金額及有關個人對保險人的累積影響，此即財務性核保；額外危險、非技術性、外來因素核保均非標準術語。"}},
{p:3,ch:"人寿保险程序",q:"保险公司顾客服务部的一般工作包括:",o:["通讯","文件整理","保单续保","以上各项皆是"],a:3,e:"顾客服务部的一般工作包括通讯、文件整理及保单续保等，三项均为其职责范畴。",src:1,tw:{ch:"人壽保險程序",q:"保險公司顧客服務部的一般工作包括：",o:["通訊","文件整理","保單續保","以上各項皆是"],e:"顧客服務部的一般工作包括通訊、文件整理及保單續保等，三項均為其職責範疇。"}},
{p:3,ch:"人寿保险程序",q:"关于人寿保险核保的事宜,哪项描述是错误的?",o:["就人寿保险来讲,核保不可以有错误","核保只可以在保单续保时更改保险人的过失","核保是保险人选择风险的活动","以上全部错误"],a:1,e:"人寿保险核保通常在投保时一次性完成，无法于续保时更正保险人的过失，故「核保只可在保单续保时更改保险人的过失」错误；核保须力求准确、是保险人选择风险的活动等说法正确。",src:1,tw:{ch:"人壽保險程序",q:"關於人壽保險核保的事宜，哪項描述是錯誤的？",o:["就人壽保險來講，核保不可以有錯誤","核保只可以在保單續保時更改保險人的過失","核保是保險人選擇風險的活動","以上全部錯誤"],e:"人壽保險核保通常在投保時一次性完成，無法於續保時更正保險人的過失，故「核保只可在保單續保時更改保險人的過失」錯誤；核保須力求準確、是保險人選擇風險的活動等說法正確。"}},
{p:3,ch:"人寿保险程序",q:"关于保单红利,汇集基金在特定时期的业绩情况与同一段期间的哪几个因素存在着密切的关系?",o:["汇集基金的投资回报","汇集基金该段时间的赔付金","汇集基金该段时间的费用","以上皆是"],a:3,e:"汇集基金特定时期的业绩与该期间的投资回报、赔付金及费用等因素密切相关，故三项全选，红利据此厘定。",src:1,tw:{ch:"人壽保險程序",q:"關於保單紅利,彙集基金在特定時期的業績情況與同一段期間的哪幾個因素存在着密切的關係?",o:["彙集基金的投資回報","彙集基金該段時間的賠付金","彙集基金該段時間的費用","以上皆是"],e:"彙集基金特定時期的業績與該期間的投資回報、賠付金及費用等因素密切相關，故三項全選，紅利據此釐定。"}},
{p:3,ch:"人寿保险程序",q:"关于保单红利的派法,汇集基金在特定时期的业绩情况在其在同一段期间的几个因素存在着密切的关系,当 中不包括:",o:["汇集基金该段时间的投资回报","相关保险人的销售团队的能力","汇集基金该段时间的费用","汇集基金该段时间的赔付金"],a:1,e:"汇集基金的业绩取决于投资回报、费用及赔付金等因素；销售团队的能力与基金业绩无关，故不包括在内。",src:1,tw:{ch:"人壽保險程序",q:"關於保單紅利的派法,彙集基金在特定時期的業績情況在其在同一段期間的幾個因素存在着密切的關係,當 中不包括:",o:["彙集基金該段時間的投資回報","相關保險人的銷售團隊的能力","彙集基金該段時間的費用","彙集基金該段時間的賠付金"],e:"彙集基金的業績取決於投資回報、費用及賠付金等因素；銷售團隊的能力與基金業績無關，故不包括在內。"}},
{p:3,ch:"人寿保险程序",q:"冷静期是可以让投保人取消投保而取回已缴保费的期间,冷静期的规定时段为新保单交付,或将「通知书」 发予保单持有人或其代表后,起计多少天,以较先者为准?",o:["21","24","14","7"],a:0,e:"冷静期为新保单交付或将通知书发予保单持有人或其代表后起计21天、以较先者为准；14、24、7均非正确天数。",src:1,tw:{ch:"人壽保險程序",q:"冷靜期是可以讓投保人取消投保而取回已繳保費的期間，冷靜期的規定時段為新保單交付，或將「通知書」 發予保單持有人或其代表後，起計多少天，以較先者為準？",o:["21","24","14","7"],e:"冷靜期為新保單交付或將通知書發予保單持有人或其代表後起計21天、以較先者為準；14、24、7均非正確天數。"}},
{p:3,ch:"人寿保险程序",q:"冷静期是指允许保单所有人就新购买或已申请的人寿保险保单,在一段时间内改变主意,但容许保险人对下 列哪类保单从退还的保费中减去「市值调整」:",o:["所有类别人寿保单","储蓄寿险保单","定期寿险保单","投资相连及非投资相连整付保费保单"],a:3,e:"冷静期内退保，保险人只可对投资相连及非投资相连整付保费保单从退还的保费中减去市值调整；其他非投资相连保单通常退还全部保费。",src:1,tw:{ch:"人壽保險程序",q:"冷靜期是指允許保單所有人就新購買或已申請的人壽保險保單，在一段時間內改變主意，但容許保險人對下 列哪類保單從退還的保費中減去「市值調整」：",o:["所有類別人壽保單","儲蓄壽險保單","定期壽險保單","投資相連及非投資相連整付保費保單"],e:"冷靜期內退保，保險人只可對投資相連及非投資相連整付保費保單從退還的保費中減去市值調整；其他非投資相連保單通常退還全部保費。"}},
{p:3,ch:"人寿保险程序",q:"准受保保单所有人在投保时,除了要填写投保书外,有时亦需要提供补充资料,包括:",o:["缴付保费方式","核保问卷","可保性证明","以上各项"],a:3,e:"投保时的补充资料包括缴付保费方式、核保问卷及可保性证明等，三项均可属补充要求。",src:1,tw:{ch:"人壽保險程序",q:"準受保保單所有人在投保時，除了要填寫投保書外，有時亦需要提供補充資料，包括：",o:["繳付保費方式","核保問卷","可保性證明","以上各項"],e:"投保時的補充資料包括繳付保費方式、核保問卷及可保性證明等，三項均可屬補充要求。"}},
{p:3,ch:"人寿保险程序",q:"准备团体保单保险时,技术系统会印制以下哪项或哪些交件?",o:["团体的总保单","每位独立雇员的保险凭证","每位独立雇员的雇员登记卡","以上所有各项"],a:3,e:"准备团体保单保险时，技术系统会印制团体的总保单、每位独立雇员的保险凭证及雇员登记卡，三项全选。",src:1,tw:{ch:"人壽保險程序",q:"準備團體保單保險時，技術系統會印製以下哪項或哪些交件？",o:["團體的總保單","每位獨立僱員的保險憑證","每位獨立僱員的僱員登記卡","以上所有各項"],e:"準備團體保單保險時，技術系統會印製團體的總保單、每位獨立僱員的保險憑證及僱員登記卡，三項全選。"}},
{p:3,ch:"人寿保险程序",q:"利用误导性陈述,不披露某些资料,错误陈述及对保单作出不详实的比较,诱使投保人更改现有寿险安排, 转而投购其他寿险保单,即视为:",o:["诱导转保(Twisting)","回佣 (Rebating)","转保(Replacement)","客户保障声明 (CPD)"],a:0,e:"以误导性陈述、不披露某些资料、错误陈述及不当比较诱使投保人更改现有寿险安排，属诱导转保（Twisting）；回佣、转保及客户保障声明均为不同概念。",src:1,tw:{ch:"人壽保險程序",q:"利用誤導性陳述，不披露某些資料，錯誤陳述及對保單作出不詳實的比較，誘使投保人更改現有壽險安排， 轉而投購其他壽險保單，即視為：",o:["誘導轉保(Twisting)","回佣 (Rebating)","轉保(Replacement)","客戶保障聲明 (CPD)"],e:"以誤導性陳述、不披露某些資料、錯誤陳述及不當比較誘使投保人更改現有壽險安排，屬誘導轉保（Twisting）；回佣、轉保及客户保障聲明均為不同概念。"}},
{p:3,ch:"人寿保险程序",q:"售后服务是一个重要因素,它是由顾客服务部或下列哪个部门负责:",o:["POS (Policyowner Service) 保单所有人服务","ASS (After-Sales Service) 售后服务","BCS (Better Customer Service) 更好客户服务","ICO (Improve Customer Service) 改善客户服务"],a:0,e:"售后服务由顾客服务部或保单所有人服务（POS）负责；ASS、BCS、ICO并非相应的标准缩写。",src:1,tw:{ch:"人壽保險程序",q:"售後服務是一個重要因素，它是由顧客服務部或下列哪個部門負責：",o:["POS (Policyowner Service) 保單所有人服務","ASS (After-Sales Service) 售後服務","BCS (Better Customer Service) 更好客戶服務","ICO (Improve Customer Service) 改善客戶服務"],e:"售後服務由顧客服務部或保單所有人服務（POS）負責；ASS、BCS、ICO並非相應的標準縮寫。"}},
{p:3,ch:"人寿保险程序",q:"售后服务部常以英文短写\"POS\"代表,其意思是:",o:["对本身的服务感到自豪 (Pride in Our Service)","保单所有人服务 (PolicyOwner Service)","优先办公室服务 (Priority Office Service)","个人行动服务 (Personal Operation Service)"],a:1,e:"POS即 PolicyOwner Service，指保单所有人服务，负责售后服务；其余英文全称均非其实际含义。",src:1,tw:{ch:"人壽保險程序",q:"售後服務部常以英文短寫\"POS\"代表，其意思是：",o:["對本身的服務感到自豪 (Pride in Our Service)","保單所有人服務 (PolicyOwner Service)","優先辦公室服務 (Priority Office Service)","個人行動服務 (Personal Operation Service)"],e:"POS即 PolicyOwner Service，指保單所有人服務，負責售後服務；其餘英文全稱均非其實際含義。"}},
{p:3,ch:"人寿保险程序",q:"团体寿险单中,除总保单外,保险人会向受保人签发:",o:["总保单影印本","保险凭证,也许还有成员登记卡","总保单的若干部分影印本","确认保单成员的挂号信"],a:1,e:"团体寿险除总保单外，保险人会向各受保人签发保险凭证，也许还有成员登记卡；总保单影印本或确认挂号信并非标准做法。",src:1,tw:{ch:"人壽保險程序",q:"團體壽險單中，除總保單外，保險人會向受保人簽發：",o:["總保單影印本","保險憑證，也許還有成員登記卡","總保單的若干部分影印本","確認保單成員的掛號信"],e:"團體壽險除總保單外，保險人會向各受保人簽發保險憑證，也許還有成員登記卡；總保單影印本或確認掛號信並非標準做法。"}},
{p:3,ch:"人寿保险程序",q:"在一份(投资)相连保单退保说明文件中,保险人必须向保单所有人声明保单价值将会受投资影响而升或跌及 :",o:["两年后保单的价值","若提前终止会对保单的影响","保证可保收益","以上各项皆是"],a:1,e:"投资相连保单退保说明文件须声明保单价值会受投资影响而升或跌，并说明若提前终止对保单的影响；「两年后价值」「保证可保收益」并非此项要求。",src:1,tw:{ch:"人壽保險程序",q:"在一份(投資)相連保單退保說明文件中，保險人必須向保單所有人聲明保單價值將會受投資影響而升或跌及 ：",o:["兩年後保單的價值","若提前終止會對保單的影響","保證可保收益","以上各項皆是"],e:"投資相連保單退保說明文件須聲明保單價值會受投資影響而升或跌，並說明若提前終止對保單的影響；「兩年後價值」「保證可保收益」並非此項要求。"}},
{p:3,ch:"人寿保险程序",q:"在一间保险公司中,通讯、文件整理、更改保单以及公共关系是以下哪个部门的工作﹖",o:["理赔部","巿场行销及促销","核保部","客户服务部"],a:3,e:"通讯、文件整理、更改保单及公共关系均属客户服务（售后）部门的工作；理赔、市场行销、核保部门各有不同职能。",src:1,tw:{ch:"人壽保險程序",q:"在一間保險公司中，通訊、文件整理、更改保單以及公共關係是以下哪個部門的工作﹖",o:["理賠部","巿場行銷及促銷","核保部","客戶服務部"],e:"通訊、文件整理、更改保單及公共關係均屬客户服務（售後）部門的工作；理賠、市場行銷、核保部門各有不同職能。"}},
{p:3,ch:"人寿保险程序",q:"在人寿保险中,保险人所签发的保费收据,已具有可保性的,可于指定日期内提出终止保障,这种收据称为 :",o:["立约保费收据","可撤销保费收据","暂时性保费收据","附条件保费收据"],a:0,e:"立约保费收据（不附条件收据）于投保时即提供保障，但保险人可于指定日期内提出终止；可撤销、暂时性或附条件收据均非此名称。",src:1,tw:{ch:"人壽保險程序",q:"在人壽保險中，保險人所簽發的保費收據，已具有可保性的，可於指定日期內提出終止保障，這種收據稱為 ：",o:["立約保費收據","可撤銷保費收據","暫時性保費收據","附條件保費收據"],e:"立約保費收據（不附條件收據）於投保時即提供保障，但保險人可於指定日期內提出終止；可撤銷、暫時性或附條件收據均非此名稱。"}},
{p:3,ch:"人寿保险程序",q:"在人寿保险中,形容因人提供人寿保险所需要做出的风险评估过程,以下那项是最贴切的:",o:["评估","核保","技术性评估","系统性评估"],a:1,e:"人寿保险中为人提供保险而作的风险评估过程，最贴切的名称是「核保」；评估、技术性评估、系统性评估均非此专业术语。",src:1,tw:{ch:"人壽保險程序",q:"在人壽保險中，形容因人提供人壽保險所需要做出的風險評估過程，以下那項是最貼切的：",o:["評估","核保","技術性評估","系統性評估"],e:"人壽保險中為人提供保險而作的風險評估過程，最貼切的名稱是「核保」；評估、技術性評估、系統性評估均非此專業術語。"}},
{p:3,ch:"人寿保险程序",q:"在人寿保险中,那些是与医疗报告没有关系的:",o:["所涉及非常敏感的体检问题","在某些特定的情况下有需要听取另外的特别意见","人寿保险体检报告的主要种类称为主诊医生报告","可能牵涉再保险"],a:3,e:"再保险安排属风险转移范畴，并非与医疗报告直接相关的考虑；触及敏感的体检问题、特定情况需听取特别意见、主诊医生报告均与医疗报告有关。",src:1,tw:{ch:"人壽保險程序",q:"在人壽保險中，那些是與醫療報告沒有關係的：",o:["所涉及非常敏感的體檢問題","在某些特定的情況下有需要聽取另外的特別意見","人壽保險體檢報告的主要種類稱為主診醫生報告","可能牽涉再保險"],e:"再保險安排屬風險轉移範疇，並非與醫療報告直接相關的考慮；觸及敏感的體檢問題、特定情況需聽取特別意見、主診醫生報告均與醫療報告有關。"}},
{p:3,ch:"人寿保险程序",q:"在以下哪情况下,不能迫令营利(或合资股份)公司的股东就公司的亏损/股本需求提供额外资金?",o:["已经向他们发出股份","他们的股份已经完全清缴","有关公司拥有充足的资本开始营运","公司完全清盘"],a:1,e:"营利（股份）公司的股东就公司亏损或股本需求提供额外资金的责任以股份是否完全清缴为限，完全清缴后不能再被追缴；其余情形不构成本题所指。",src:1,tw:{ch:"人壽保險程序",q:"在以下哪情況下，不能迫令營利(或合資股份)公司的股東就公司的虧損/股本需求提供額外資金？",o:["已經向他們發出股份","他們的股份已經完全清繳","有關公司擁有充足的資本開始營運","公司完全清盤"],e:"營利（股份）公司的股東就公司虧損或股本需求提供額外資金的責任以股份是否完全清繳為限，完全清繳後不能再被追繳；其餘情形不構成本題所指。"}},
{p:3,ch:"人寿保险程序",q:"在以下哪情况下,不能迫令营利(或合资股份)公司的股东就公司的亏损提供额外资金?",o:["已经向他们发出股份","他们的股份已经完全清缴","有关公司拥有充足的资本开始交易","就某段时间进行的会计纪录已经完结"],a:1,e:"股东股份完全清缴后，即无再就公司亏损提供额外资金的义务，不能被追缴；已发股份、资本充足或会计完结均不足以免除此项责任。",src:1,tw:{ch:"人壽保險程序",q:"在以下哪情況下，不能迫令營利(或合資股份)公司的股東就公司的虧損提供額外資金？",o:["已經向他們發出股份","他們的股份已經完全清繳","有關公司擁有充足的資本開始交易","就某段時間進行的會計紀錄已經完結"],e:"股東股份完全清繳後，即無再就公司虧損提供額外資金的義務，不能被追繳；已發股份、資本充足或會計完結均不足以免除此項責任。"}},
{p:3,ch:"人寿保险程序",q:"在冷静期权益中,所有投资相连及非投资相连整付保费保单,保险人可从退还保费中减去市值调整。对于其 他非投资相连保单,以下哪项是正确的描述:",o:["不允许退还已缴保费","可退还已缴保费的50%","可退还已缴保费的100%","退还百分比按取消保单的日期而变动"],a:2,e:"除投资相连及非投资相连整付保费保单可扣减市值调整外，其他非投资相连保单在冷静期内可退还已缴保费的100%。",src:1,tw:{ch:"人壽保險程序",q:"在冷靜期權益中，所有投資相連及非投資相連整付保費保單，保險人可從退還保費中減去市值調整。對於其 他非投資相連保單，以下哪項是正確的描述：",o:["不允許退還已繳保費","可退還已繳保費的50%","可退還已繳保費的100%","退還百分比按取消保單的日期而變動"],e:"除投資相連及非投資相連整付保費保單可扣減市值調整外，其他非投資相連保單在冷靜期內可退還已繳保費的100%。"}},
{p:3,ch:"人寿保险程序",q:"在投保人购买保险后,有一段时间可以对保单取消保单并获全数退还已缴保费,这一段时间的名称是什么?",o:["宽限期","冷静期","等候期","通知期"],a:1,e:"投保后允许取消保单并全数退还已缴保费的期间称「冷静期」；宽限期指续费宽限，等候期指疾病类保障等待期，通知期含义均不同。",src:1,tw:{ch:"人壽保險程序",q:"在投保人購買保險後，有一段時間可以對保單取消保單並獲全數退還已繳保費，這一段時間的名稱是什麼？",o:["寬限期","冷靜期","等候期","通知期"],e:"投保後允許取消保單並全數退還已繳保費的期間稱「冷靜期」；寬限期指續費寬限，等候期指疾病類保障等待期，通知期含義均不同。"}},
{p:3,ch:"人寿保险程序",q:"在核保人寿保险的申请时,以下哪项或哪些是需要考虑的重点: i 投保人的身份 ii 下一个(或前一个)生日年龄 iii 保单所需的生效日期 iv 投保人过去三年内转换职业的频密程度",o:["i, iv","ii, iv","i, ii, iii","i, ii, iii, iv"],a:2,e:"核保人寿保险申请须考虑投保人的身份、下一个（或前一个）生日年龄及保单所需生效日期（i、ii、iii）；过去三年转换职业的频密程度并非核保申请时的标准重点，故不选iv。",src:1,tw:{ch:"人壽保險程序",q:"在核保人壽保險的申請時，以下哪項或哪些是需要考慮的重點： i 投保人的身份 ii 下一個（或前一個）生日年齡 iii 保單所需的生效日期 iv 投保人過去三年內轉換職業的頻密程度",o:["i, iv","ii, iv","i, ii, iii","i, ii, iii, iv"],e:"核保人壽保險申請須考慮投保人的身份、下一個（或前一個）生日年齡及保單所需生效日期（i、ii、iii）；過去三年轉換職業的頻密程度並非核保申請時的標準重點，故不選iv。"}},
{p:3,ch:"人寿保险程序",q:"在死亡索偿中,以下哪项或哪些项目,受保人的死亡原因是很重要的?",o:["保单内或有意外死亡附加保障","自杀条款仍然生效","受益人谋杀被保人","以上各项皆是"],a:3,e:"意外死亡附加保障是否适用、自杀条款是否仍生效、受益人谋杀被保人，都使死因成为索偿中的重要事项，三项全选。",src:1,tw:{ch:"人壽保險程序",q:"在死亡索償中，以下哪項或哪些項目，受保人的死亡原因是很重要的？",o:["保單內或有意外死亡附加保障","自殺條款仍然生效","受益人謀殺被保人","以上各項皆是"],e:"意外死亡附加保障是否適用、自殺條款是否仍生效、受益人謀殺被保人，都使死因成為索償中的重要事項，三項全選。"}},
{p:3,ch:"人寿保险程序",q:"在死亡索偿中,在哪种情况下死因对索偿来说属于重要事项?",o:["该份保单设有意外死亡保险利益附约","自杀条款可能依然生效","受益人谋杀受保生命","以上所有各项"],a:3,e:"保单设有意外死亡保险利益附约、自杀条款可能依然生效、受益人谋杀受保生命等情形下，死因对索偿均属重要事项，故全选。",src:1,tw:{ch:"人壽保險程序",q:"在死亡索償中，在哪種情況下死因對索償來說屬於重要事項？",o:["該份保單設有意外死亡保險利益附約","自殺條款可能依然生效","受益人謀殺受保生命","以上所有各項"],e:"保單設有意外死亡保險利益附約、自殺條款可能依然生效、受益人謀殺受保生命等情形下，死因對索償均屬重要事項，故全選。"}},
{p:3,ch:"人寿保险程序",q:"在相连保单中,预计的退保发还金额和死亡保险金的计算必须基于以下哪些假设?",o:["4个不同的假设回报率,分别设定为每年0%、3%,、6%和9%,或3个不同的假设回 报率,分别设定为每年0%、3%,和6%","4个不同的假设回报率—分别设定为每年0%、3%,、5%和8%,或3个不同的假设回 报率,分别设定为每年0%、3%,和5%","4个不同的假设回报率,分别设定为每年0%、3%,、6%和9%","3个不同的假设回报率—分别设定为每年0%、3%,和5%"],a:0,e:"相连保单预计退保发还金额及死亡保险金的计算，须按每年0%、3%、6%、9%四个假设回报率，或0%、3%、6%三个假设回报率进行展示；其余组合不符规定。",src:1,tw:{ch:"人壽保險程序",q:"在相連保單中，預計的退保發還金額和死亡保險金的計算必須基於以下哪些假設？",o:["4個不同的假設回報率,分別設定為每年0%、3%,、6%和9%,或3個不同的假設回 報率,分別設定為每年0%、3%,和6%","4個不同的假設回報率—分別設定為每年0%、3%,、5%和8%,或3個不同的假設回 報率,分別設定為每年0%、3%,和5%","4個不同的假設回報率,分別設定為每年0%、3%,、6%和9%","3個不同的假設回報率—分別設定為每年0%、3%,和5%"],e:"相連保單預計退保發還金額及死亡保險金的計算，須按每年0%、3%、6%、9%四個假設回報率，或0%、3%、6%三個假設回報率進行展示；其餘組合不符規定。"}},
{p:3,ch:"人寿保险程序",q:"在非人寿保险中,「暂保单」提供短暂保障,保险人可于稍后时间取消该保单,而在人寿保险中,有类似功 能的称为:",o:["立约保费收据","附条件保费收据","临时收据","现金收据"],a:0,e:"非人寿保险用可取消的暂保单提供短期保障，人寿保险中类似功能的称为立约保费收据（不附条件保费收据）；附条件收据以可保性为条件，性质不同。",src:1,tw:{ch:"人壽保險程序",q:"在非人壽保險中，「暫保單」提供短暫保障，保險人可於稍後時間取消該保單，而在人壽保險中，有類似功 能的稱為：",o:["立約保費收據","附條件保費收據","臨時收據","現金收據"],e:"非人壽保險用可取消的暫保單提供短期保障，人壽保險中類似功能的稱為立約保費收據（不附條件保費收據）；附條件收據以可保性為條件，性質不同。"}},
{p:3,ch:"人寿保险程序",q:"在非寿险而言,透过签发暂保单可提供保障,然而这保障都是有期限的,而且可由保险人自由取消。就人寿 保单而言,这类别称为:",o:["立约保费收据","附条件保费收据","暂时性人寿保单","临时人寿保单收据"],a:0,e:"就人寿保单而言，与暂保单类似、提供限期且保险人可自由取消的保障称为立约保费收据；附条件收据、暂时性或临时人寿保单等名称不准确。",src:1,tw:{ch:"人壽保險程序",q:"在非壽險而言，透過簽發暫保單可提供保障，然而這保障都是有期限的，而且可由保險人自由取消。就人壽 保單而言，這類別稱為:",o:["立約保費收據","附條件保費收據","暫時性人壽保單","臨時人壽保單收據"],e:"就人壽保單而言，與暫保單類似、提供限期且保險人可自由取消的保障稱為立約保費收據；附條件收據、暫時性或臨時人壽保單等名稱不準確。"}},
{p:3,ch:"人寿保险程序",q:"在风险分类中,那些没有异常特点,可以按照投保人的年龄和性别所设应征的保费和条款而接受投保的称为 :",o:["基本风险","一般风险","标准风险","可接受风险"],a:2,e:"没有异常特点、可按投保人年龄和性别所设标准保费及条款接受投保的风险称为「标准风险」；基本、一般、可接受风险并非标准术语。",src:1,tw:{ch:"人壽保險程序",q:"在風險分類中，那些沒有異常特點，可以按照投保人的年齡和性別所設應徵的保費和條款而接受投保的稱為 ：",o:["基本風險","一般風險","標準風險","可接受風險"],e:"沒有異常特點、可按投保人年齡和性別所設標準保費及條款接受投保的風險稱為「標準風險」；基本、一般、可接受風險並非標準術語。"}},
{p:3,ch:"人寿保险程序",q:"在香港,只要保单持有人在某一段指明期间内行动,他就可以就已购买的人寿保险合约改变主意并取回已缴 保费。这可能是基于:",o:["《保险业条例》","香港保险业联会的冷静期","香港保险业联会发出的机密指引","香港保险业监管局发出的规例"],a:0,e:"香港保单持有人于冷静期内改变主意并取回已缴保费的权利，基于《保险业条例》的强制性规定；香港保险业联会的冷静期建议、机密指引及保监局规例并非此法律依据。",src:1,tw:{ch:"人壽保險程序",q:"在香港，只要保單持有人在某一段指明期間內行動，他就可以就已購買的人壽保險合約改變主意並取回已繳 保費。這可能是基於：",o:["《保險業條例》","香港保險業聯會的冷靜期","香港保險業聯會發出的機密指引","香港保險業監管局發出的規例"],e:"香港保單持有人於冷靜期內改變主意並取回已繳保費的權利，基於《保險業條例》的強制性規定；香港保險業聯會的冷靜期建議、機密指引及保監局規例並非此法律依據。"}},
{p:3,ch:"人寿保险程序",q:"基于以下哪项的假设保单可以行使保费抵销?",o:["保单红利存放于保险人","死亡业绩有利","保单红利用于购买增额清缴保险","投资业绩有利"],a:0,e:"保费抵销基于保单红利存放于保险人的假设，以累积红利抵付保费；死亡或投资业绩有利、红利购买增额清缴保险并非此假设。",src:1,tw:{ch:"人壽保險程序",q:"基於以下哪項的假設保單可以行使保費抵銷?",o:["保單紅利存放於保險人","死亡業績有利","保單紅利用於購買增額清繳保險","投資業績有利"],e:"保費抵銷基於保單紅利存放於保險人的假設，以累積紅利抵付保費；死亡或投資業績有利、紅利購買增額清繳保險並非此假設。"}},
{p:3,ch:"人寿保险程序",q:"处理次标准风险核保时,寿险核保人有多项措施。如果投保人的风险低于标准,而不能以正常保费率接受投 保,保险人通常会:",o:["拒绝提供保险","要求附加保费","增加保单除外责任","最少延迟一年后才做出提供保险的决定"],a:1,e:"风险低于标准而无法以正常费率承保时，保险人通常会要求附加保费以补偿较高的风险；拒绝保险、增加除外责任、最少延迟一年均非常规首选。",src:1,tw:{ch:"人壽保險程序",q:"處理次標準風險核保時，壽險核保人有多項措施。如果投保人的風險低於標準，而不能以正常保費率接受投 保，保險人通常會：",o:["拒絕提供保險","要求附加保費","增加保單除外責任","最少延遲一年後才做出提供保險的決定"],e:"風險低於標準而無法以正常費率承保時，保險人通常會要求附加保費以補償較高的風險；拒絕保險、增加除外責任、最少延遲一年均非常規首選。"}},
{p:3,ch:"人寿保险程序",q:"处理索偿时,保险人会从保险金中扣除甚么项目?",o:["保单的贷款","未缴清的保费","尚欠的利息","以上各项皆是"],a:3,e:"处理索偿时保险人会从保险金中扣除保单的贷款、未缴清的保费及尚欠的利息等项目，三项全选。",src:1,tw:{ch:"人壽保險程序",q:"處理索償時，保險人會從保險金中扣除甚麼項目？",o:["保單的貸款","未繳清的保費","尚欠的利息","以上各項皆是"],e:"處理索償時保險人會從保險金中扣除保單的貸款、未繳清的保費及尚欠的利息等項目，三項全選。"}},
{p:3,ch:"人寿保险程序",q:"多亏哪项,香港的保单持有人可于限时内采取行动,就购买的寿险更改主意并退款?",o:["《保险业条例》","香港保险业联会的冷静期","香港保险业联会的机密协议","保险业监管局的规则"],a:0,e:"香港保单持有人在限时内就寿险更改主意并退款的权利来自《保险业条例》；香港保险业联会的冷静期建议、机密协议及保监局规则均非此法律依据。",src:1,tw:{ch:"人壽保險程序",q:"多虧哪項，香港的保單持有人可於限時內採取行動，就購買的壽險更改主意並退款?",o:["《保險業條例》","香港保險業聯會的冷靜期","香港保險業聯會的機密協議","保險業監管局的規則"],e:"香港保單持有人在限時內就壽險更改主意並退款的權利來自《保險業條例》；香港保險業聯會的冷靜期建議、機密協議及保監局規則均非此法律依據。"}},
{p:3,ch:"人寿保险程序",q:"大多数保险人爱将风险进行分类,目的是为订立公平保费,以下哪项不是风险类别?",o:["标准风险,没有异常风险(收费标准)","次标准风险,风险较大(增加保费)","拒保风险(由于健康或其它因素使投保不可能被接受)","最高级风险,索偿机会不大(保费极低)"],a:3,e:"风险分类包括标准风险、次标准风险、拒保风险及优良风险；「索偿机会不大即保费极低」的「最高级风险」并非标准类别，故该选项不对。",src:1,tw:{ch:"人壽保險程序",q:"大多數保險人愛將風險進行分類，目的是為訂立公平保費，以下哪項不是風險類別？",o:["標準風險，沒有異常風險(收費標準)","次標準風險，風險較大(增加保費)","拒保風險(由於健康或其它因素使投保不可能被接受)","最高級風險，索償機會不大(保費極低)"],e:"風險分類包括標準風險、次標準風險、拒保風險及優良風險；「索償機會不大即保費極低」的「最高級風險」並非標準類別，故該選項不對。"}},
{p:3,ch:"人寿保险程序",q:"如保单所有人于冷静期内决定取消保单,保险人需要:",o:["从保险代理人户口中扣除已缴交的保费","将所缴交的保费全数退回","退还已扣除首月开支的保费","退还投保额"],a:1,e:"冷静期内决定取消保单时，保险人须将所缴交的保费全数退回（投资相连及非投资相连整付保单可扣市值调整除外）；从代理人户口扣除、扣首月开支、退投保额均不正确。",src:1,tw:{ch:"人壽保險程序",q:"如保單所有人於冷靜期內決定取消保單，保險人需要：",o:["從保險代理人戶口中扣除已繳交的保費","將所繳交的保費全數退回","退還已扣除首月開支的保費","退還投保額"],e:"冷靜期內決定取消保單時，保險人須將所繳交的保費全數退回（投資相連及非投資相連整付保單可扣市值調整除外）；從代理人户口扣除、扣首月開支、退投保額均不正確。"}},
{p:3,ch:"人寿保险程序",q:"如保险人同意保险于投保时即开始生效,但必须在事后能确定投保人在投保时乃属按照标准条款具有可保性 才有效,这是属于什么收据?",o:["暂时性保费收据","立约保费收据","附条件保费收据","永久保费收据"],a:2,e:"保险于投保时即开始生效、但须事后证实投保人当时按标准条款具有可保性的收据，称为附条件保费收据；立约收据则不以此条件为前提。",src:1,tw:{ch:"人壽保險程序",q:"如保險人同意保險於投保時即開始生效，但必須在事後能確定投保人在投保時乃屬按照標準條款具有可保性 才有效，這是屬於什麼收據?",o:["暫時性保費收據","立約保費收據","附條件保費收據","永久保費收據"],e:"保險於投保時即開始生效、但須事後證實投保人當時按標準條款具有可保性的收據，稱為附條件保費收據；立約收據則不以此條件為前提。"}},
{p:3,ch:"人寿保险程序",q:"如果一家营利公司的股份已经\"完全清缴\",意思是指:",o:["该公司现在可以开始交易","该公司不能透过发行股份作进一步集资","股东需承担该公司未来的所有实务","股东对该公司再没有进一步的财务责任"],a:3,e:"股份「完全清缴」指股东已缴足股款，对公司再没有进一步的财务责任；可开始交易、不能进一步集资、承担未来实务等均不符其含义。",src:1,tw:{ch:"人壽保險程序",q:"如果一家營利公司的股份已經\"完全清繳\"，意思是指：",o:["該公司現在可以開始交易","該公司不能透過發行股份作進一步集資","股東需承擔該公司未來的所有實務","股東對該公司再沒有進一步的財務責任"],e:"股份「完全清繳」指股東已繳足股款，對公司再沒有進一步的財務責任；可開始交易、不能進一步集資、承擔未來實務等均不符其含義。"}},
{p:3,ch:"人寿保险程序",q:"如果一间公司的名称含有「相互」字眼,但却有股东,由此可见此公司已经过一过程,称为:",o:["资本化","股份化","股份登记","分红成员登记"],a:1,e:"名称含「相互」却有股东，说明公司已经历「股份化」过程，由相互公司转为股份公司；资本化、股份登记、分红成员登记均非此过程名称。",src:1,tw:{ch:"人壽保險程序",q:"如果一間公司的名稱含有「相互」字眼，但卻有股東，由此可見此公司已經過一過程，稱為：",o:["資本化","股份化","股份登記","分紅成員登記"],e:"名稱含「相互」卻有股東，說明公司已經歷「股份化」過程，由相互公司轉為股份公司；資本化、股份登記、分紅成員登記均非此過程名稱。"}},
{p:3,ch:"人寿保险程序",q:"如果客人因公司倒闭遭遗散而失去工作,客人并无力缴交将到期之保费,而其保单已供了很多年,客人因此 考虑退保,保险人应采取哪些行动?",o:["解释有关不能作废条款","解释一份减额清缴保险","解释以保单抵押贷款作燃眉之急","以上各项皆是"],a:3,e:"客户失业无力缴费并考虑退保时，保险人应解释不能作废条款、减额清缴保险或以保单抵押贷款解燃眉之急，三项均属恰当行动。",src:1,tw:{ch:"人壽保險程序",q:"如果客人因公司倒閉遭遺散而失去工作，客人並無力繳交將到期之保費，而其保單已供了很多年，客人因此 考慮退保，保險人應採取哪些行動？",o:["解釋有關不能作廢條款","解釋一份減額清繳保險","解釋以保單抵押貸款作燃眉之急","以上各項皆是"],e:"客户失業無力繳費並考慮退保時，保險人應解釋不能作廢條款、減額清繳保險或以保單抵押貸款解燃眉之急，三項均屬恰當行動。"}},
{p:3,ch:"人寿保险程序",q:"如果被保人就分红保单的红利没有作出选择,保证人最普遍的做法是?",o:["以现金发放","可向保险人购买公司股份","可向保险人缴交减额清缴保险或存放于保险人滚存利息","用作缴交保费"],a:0,e:"分红保单持有人没有选择红利处理方式时，保险人最普遍的做法是以现金发放；购买公司股份、减额清缴或滚存利息、缴交保费并非此普遍默认方式。",src:1,tw:{ch:"人壽保險程序",q:"如果被保人就分紅保單的紅利沒有作出選擇，保證人最普遍的做法是?",o:["以現金發放","可向保險人購買公司股份","可向保險人繳交減額清繳保險或存放於保險人滾存利息","用作繳交保費"],e:"分紅保單持有人沒有選擇紅利處理方式時，保險人最普遍的做法是以現金髮放；購買公司股份、減額清繳或滾存利息、繳交保費並非此普遍默認方式。"}},
{p:3,ch:"人寿保险程序",q:"如果证实个别投保人的风险低于标准(Sub-standard)核保人可以:",o:["选择不同的回应核保措施","无论任何情况,必须提供保障","拒绝提供任何保障","必须以正常保费率接受或拒绝"],a:0,e:"证实风险属次标准时，核保人可弹性选择不同的回应核保措施（如附加保费、改计划等），不必强制提供保障或拒绝，也不必限于以正常费率接受或拒绝。",src:1,tw:{ch:"人壽保險程序",q:"如果證實個別投保人的風險低於標準(Sub-standard)核保人可以：",o:["選擇不同的回應核保措施","無論任何情況，必須提供保障","拒絕提供任何保障","必須以正常保費率接受或拒絕"],e:"證實風險屬次標準時，核保人可彈性選擇不同的回應核保措施（如附加保費、改計劃等），不必強制提供保障或拒絕，也不必限於以正常費率接受或拒絕。"}},
{p:3,ch:"人寿保险程序",q:"如要作出死亡索偿,死亡索偿方式是如何证明?",o:["死亡证明书正本","死亡证明书副本","受益人的签署证明","以上皆是"],a:0,e:"死亡索偿一般以死亡证明书的正本证明死亡；副本或受益人签署的证明通常不足为凭。",src:1,tw:{ch:"人壽保險程序",q:"如要作出死亡索償，死亡索償方式是如何證明?",o:["死亡證明書正本","死亡證明書副本","受益人的簽署證明","以上皆是"],e:"死亡索償一般以死亡證明書的正本證明死亡；副本或受益人簽署的證明通常不足為憑。"}},
{p:3,ch:"人寿保险程序",q:"如证实投保人于投保当天属完全不受保,以下那项有关附条件保费收据的陈述是正确的?",o:["投保人不会亦不曾受保","如缴交额外的保费,保障会变成有效","投保人涉及欺诈将不会保到保障","提交的那份保险合约是由投保当日开始生效"],a:0,e:"附条件保费收据以投保人当时可保为条件，若证实当日完全不受保，条件不成立，保障从未生效，投保人不会亦不曾受保；缴额外保费、欺诈等均无关。",src:1,tw:{ch:"人壽保險程序",q:"如證實投保人於投保當天屬完全不受保，以下那項有關附條件保費收據的陳述是正確的？",o:["投保人不會亦不曾受保","如繳交額外的保費，保障會變成有效","投保人涉及欺詐將不會保到保障","提交的那份保險合約是由投保當日開始生效"],e:"附條件保費收據以投保人當時可保為條件，若證實當日完全不受保，條件不成立，保障從未生效，投保人不會亦不曾受保；繳額外保費、欺詐等均無關。"}},
{p:3,ch:"人寿保险程序",q:"客户忠诚度、客户拓展、生产力及盈利能力所有事宜是以下哪个部门工作?",o:["理赔部","顾客服务部","市场行销部","统计部"],a:1,e:"客户忠诚度、客户拓展、生产力及盈利能力等事宜属顾客服务部工作范畴；理赔、市场行销、统计部各有侧重。",src:1,tw:{ch:"人壽保險程序",q:"客戶忠誠度、客戶拓展、生產力及盈利能力所有事宜是以下哪個部門工作？",o:["理賠部","顧客服務部","市場行銷部","統計部"],e:"客户忠誠度、客户拓展、生產力及盈利能力等事宜屬顧客服務部工作範疇；理賠、市場行銷、統計部各有側重。"}},
{p:3,ch:"人寿保险程序",q:"客户暗示将会进行退保,保险代理人应该:",o:["技巧及礼貌地询问退保原因","提供退保权利","解释保单条款可能提供帮助(例如保单抵押贷款、清缴保费等等)","以上各项皆是"],a:3,e:"客户暗示退保时，代理人应技巧礼貌地询问原因、说明退保权利，并解释保单条款（如抵押贷款、清缴保费等）可能提供的帮助，三项均应做到。",src:1,tw:{ch:"人壽保險程序",q:"客戶暗示將會進行退保，保險代理人應該：",o:["技巧及禮貌地詢問退保原因","提供退保權利","解釋保單條款可能提供幫助(例如保單抵押貸款、清繳保費等等)","以上各項皆是"],e:"客户暗示退保時，代理人應技巧禮貌地詢問原因、說明退保權利，並解釋保單條款（如抵押貸款、清繳保費等）可能提供的幫助，三項均應做到。"}},
{p:3,ch:"人寿保险程序",q:"对于大部份寿险保单而言,若保单到期日即将迫近,保险公司会: i. 通知客人到期日将到 ii. 通知客人到期日大约可领取的金额 iii. 通知客人期满后所须安排的手续及文件 iv. 附上适当形式的解除责任凭证(release)",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各项皆是"],a:3,e:"保单到期日临近，保险公司会通知到期日及约可领取金额、期满后的手续及文件，并附上解除责任凭证，四项均为到期前的安排。",src:1,tw:{ch:"人壽保險程序",q:"對於大部份壽險保單而言，若保單到期日即將迫近，保險公司會： i. 通知客人到期日將到 ii. 通知客人到期日大約可領取的金額 iii. 通知客人期滿後所須安排的手續及文件 iv. 附上適當形式的解除責任憑證(release)",o:["i, ii, iii","i, ii, iv","ii, iii, iv","以上各項皆是"],e:"保單到期日臨近，保險公司會通知到期日及約可領取金額、期滿後的手續及文件，並附上解除責任憑證，四項均為到期前的安排。"}},
{p:3,ch:"人寿保险程序",q:"对于寿险保单来说,有多个协定的更改可于保单签发后出现(透过双方同意)。然而下列 哪项较不可能属于这类更改?",o:["更改受益人","更改有关受保生命","更改保单持有人","更改保单拥有权"],a:1,e:"寿险中可经双方同意更改受益人、保单持有人及保单拥有权；受保生命是风险评定的基础，一般不可更改，属较不可能更改的项目。",src:1,tw:{ch:"人壽保險程序",q:"對於壽險保單來說，有多個協定的更改可於保單簽發後出現(透過雙方同意)。然而下列 哪項較不可能屬於這類更改？",o:["更改受益人","更改有關受保生命","更改保單持有人","更改保單擁有權"],e:"壽險中可經雙方同意更改受益人、保單持有人及保單擁有權；受保生命是風險評定的基礎，一般不可更改，屬較不可能更改的項目。"}},
{p:3,ch:"人寿保险程序",q:"寿险保单立约保费收据有时亦有其他名称。简称「TIA」的全名为:",o:["定期保险投保单(Term Insurance Application)","临时被接纳保险 (Temporary Insurance Accepted)","临时保险协议 (Temporary Insurance Agreement)","临时保险通知书(Temporary Insurance Acknowledge)"],a:2,e:"TIA全名为 Temporary Insurance Agreement（临时保险协议），是立约保费收据的另一名称；其余全称不准确。",src:1,tw:{ch:"人壽保險程序",q:"壽險保單立約保費收據有時亦有其他名稱。簡稱「TIA」的全名為：",o:["定期保險投保單(Term Insurance Application)","臨時被接納保險 (Temporary Insurance Accepted)","臨時保險協議 (Temporary Insurance Agreement)","臨時保險通知書(Temporary Insurance Acknowledge)"],e:"TIA全名為 Temporary Insurance Agreement（臨時保險協議），是立約保費收據的另一名稱；其餘全稱不準確。"}},
{p:3,ch:"人寿保险程序",q:"寿险公司的典型市场行销部的职责不可能包括以下哪项:",o:["公共关系","「次标准生命」的定义","产品研究","市场调查"],a:1,e:"「次标准生命」的定义属核保范畴，不属市场行销部职责；公共关系、产品研究、市场调查均属市场行销部的职责。",src:1,tw:{ch:"人壽保險程序",q:"壽險公司的典型市場行銷部的職責不可能包括以下哪項：",o:["公共關係","「次標準生命」的定義","產品研究","市場調查"],e:"「次標準生命」的定義屬核保範疇，不屬市場行銷部職責；公共關係、產品研究、市場調查均屬市場行銷部的職責。"}},
{p:3,ch:"人寿保险程序",q:"寿险核保人通常将风险分类,以厘定公平的保费,以下哪项属于那些不同的分类?",o:["标准风险","次标准风险","优良风险","以上各项皆是"],a:3,e:"寿险核保人为厘定公平保费，通常将风险分为标准风险、次标准风险及优良风险等类别，三者均属常见分类。",src:1,tw:{ch:"人壽保險程序",q:"壽險核保人通常將風險分類，以釐定公平的保費，以下哪項屬於那些不同的分類？",o:["標準風險","次標準風險","優良風險","以上各項皆是"],e:"壽險核保人為釐定公平保費，通常將風險分為標準風險、次標準風險及優良風險等類別，三者均屬常見分類。"}},
{p:3,ch:"人寿保险程序",q:"寿险核保经常采用「主诊」医生及「体检」医生这两个术语,以下哪项正确描述它们:",o:["它们的意思是完全相同的","主诊医生是保险人委派的医生","体检医生是个人本身的医生","它们分别是指个人本身及保险人委任的医生"],a:3,e:"主诊医生是受保人本身的医生，体检医生是保险人委派作体检的医生，两者分别指个人本身及保险人委任的医生；意思完全相同等说法错误。",src:1,tw:{ch:"人壽保險程序",q:"壽險核保經常採用「主診」醫生及「體檢」醫生這兩個術語，以下哪項正確描述它們：",o:["它們的意思是完全相同的","主診醫生是保險人委派的醫生","體檢醫生是個人本身的醫生","它們分別是指個人本身及保險人委任的醫生"],e:"主診醫生是受保人本身的醫生，體檢醫生是保險人委派作體檢的醫生，兩者分別指個人本身及保險人委任的醫生；意思完全相同等說法錯誤。"}},
{p:3,ch:"人寿保险程序",q:"就人寿保险概念而言,保险人通常会透过那一类医生索取有关医疗资料作核保及理赔时之应用: i 主诊医生 ii 体检医生 iii 经法庭法官委任的医务官 iv 享有丰富经验之病理报告",o:["i, ii","i, iv","iii, iv","以上各项皆是"],a:0,e:"就人寿保险索取医疗资料，保险人通常透过主诊医生及体检医生取得（i、ii）；法庭委任医务官、经验丰富之病理报告并非常规渠道。",src:1,tw:{ch:"人壽保險程序",q:"就人壽保險概念而言，保險人通常會透過那一類醫生索取有關醫療資料作核保及理賠時之應用： i 主診醫生 ii 體檢醫生 iii 經法庭法官委任的醫務官 iv 享有豐富經驗之病理報告",o:["i, ii","i, iv","iii, iv","以上各項皆是"],e:"就人壽保險索取醫療資料，保險人通常透過主診醫生及體檢醫生取得（i、ii）；法庭委任醫務官、經驗豐富之病理報告並非常規渠道。"}},
{p:3,ch:"人寿保险程序",q:"就人寿保险缴付之保费而签发的收据有两种,一种称为附条件保费收据,另一种:",o:["最后保费收据","立约保费收据","永久保费收据","无条件保费收据"],a:1,e:"就人寿保险缴付保费签发的收据有两种：附条件保费收据及立约保费收据；最后、永久、无条件保费收据均不属此分类。",src:1,tw:{ch:"人壽保險程序",q:"就人壽保險繳付之保費而簽發的收據有兩種，一種稱為附條件保費收據，另一種：",o:["最後保費收據","立約保費收據","永久保費收據","無條件保費收據"],e:"就人壽保險繳付保費簽發的收據有兩種：附條件保費收據及立約保費收據；最後、永久、無條件保費收據均不屬此分類。"}},
{p:3,ch:"人寿保险程序",q:"就保单红利制定建议,精算师会考虑几点因素,以下不包括:",o:["国际设定","汇集基金的业绩","经济展望","如何公平的对待汇集基金内并存的各类保单持有人及不同时间投保的保单持有人"],a:0,e:"精算师就保单红利制定建议时会考虑汇集基金业绩、经济展望及如何公平对待不同类型、不同时间投保的保单持有人等；「国际设定」并非考虑因素。",src:1,tw:{ch:"人壽保險程序",q:"就保單紅利制定建議，精算師會考慮幾點因素，以下不包括：",o:["國際設定","匯集基金的業績","經濟展望","如何公平的對待匯集基金內並存的各類保單持有人及不同時間投保的保單持有人"],e:"精算師就保單紅利制定建議時會考慮彙集基金業績、經濟展望及如何公平對待不同類型、不同時間投保的保單持有人等；「國際設定」並非考慮因素。"}},
{p:3,ch:"人寿保险程序",q:"就保单红利的派发而言,什么是汇集基金?",o:["它是指相关的保险人随着提供了分红保单而在其资产负债表上显示出来的资产 的全部,而之后保险人须为这些保单管理该等资产。","它是指相关的保险人随着经营一切类型的长期保险业务而在其资产负债表上显示 出来的资产的全部。","它是指相关的保险人随着提供了分红保单而在其保费收入的全部显示出来的资产 的全部。","它是指相关的保险人随着提供了分红保单而在已扣除日常开支的保费收入的 全部显示出来的资产的全部。"],a:0,e:"汇集基金指相关保险人因提供分红保单而在资产负债表上显示、并须为这些保单管理的全部资产；其余描述（一切长期业务、保费收入、扣除开支后的保费收入）均不准确。",src:1,tw:{ch:"人壽保險程序",q:"就保單紅利的派發而言，什麼是匯集基金？",o:["它是指相關的保險人隨着提供了分紅保單而在其資產負債表上顯示出來的資產 的全部,而之後保險人須為這些保單管理該等資產。","它是指相關的保險人隨着經營一切類型的長期保險業務而在其資產負債表上顯示 出來的資產的全部。","它是指相關的保險人隨着提供了分紅保單而在其保費收入的全部顯示出來的資產 的全部。","它是指相關的保險人隨着提供了分紅保單而在已扣除日常開支的保費收入的 全部顯示出來的資產的全部。"],e:"彙集基金指相關保險人因提供分紅保單而在資產負債表上顯示、並須為這些保單管理的全部資產；其餘描述（一切長期業務、保費收入、扣除開支後的保費收入）均不準確。"}},
{p:3,ch:"人寿保险程序",q:"就死亡索偿而言,保险人需要特别留意或展开调查? i. 被鎗击杀 ii. 保单签发不久便提出索偿 iii. 80岁被保人自然死亡 iv. 保单被保人(太太)被受益人谋杀",o:["i, iv","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],a:2,e:"被枪杀、保单签发不久即提出索偿、受益人谋杀被保人均属须特别调查的异常情况（i、ii、iv）；80岁自然死亡属高龄正常死亡，一般无需特别调查。",src:1,tw:{ch:"人壽保險程序",q:"就死亡索償而言，保險人需要特別留意或展開調查？ i. 被鎗擊殺 ii. 保單簽發不久便提出索償 iii. 80歲被保人自然死亡 iv. 保單被保人(太太)被受益人謀殺",o:["i, iv","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"被槍殺、保單簽發不久即提出索償、受益人謀殺被保人均屬須特別調查的異常情況（i、ii、iv）；80歲自然死亡屬高齡正常死亡，一般無需特別調查。"}},
{p:3,ch:"人寿保险程序",q:"已宣判的谋杀犯是不允许收取被谋杀者任何人寿保险保障利益,原因是:",o:["这是被法律所禁止的","保单条款规定拒绝的","这是违反公共政策的","已宣判的谋杀犯将会自动失去所有公民权利"],a:2,e:"允许已定罪谋杀犯领取被谋杀者的人寿保险利益，会鼓励不法行为，违反公共政策，故被禁止；法律明文禁止、保单条款拒绝、丧失公民权利并非根本依据。",src:1,tw:{ch:"人壽保險程序",q:"已宣判的謀殺犯是不允許收取被謀殺者任何人壽保險保障利益，原因是：",o:["這是被法律所禁止的","保單條款規定拒絕的","這是違反公共政策的","已宣判的謀殺犯將會自動失去所有公民權利"],e:"允許已定罪謀殺犯領取被謀殺者的人壽保險利益，會鼓勵不法行為，違反公共政策，故被禁止；法律明文禁止、保單條款拒絕、喪失公民權利並非根本依據。"}},
{p:3,ch:"人寿保险程序",q:"年度净回报率于投资寿险保单利益说明文件的具体规定是:",o:["3%","4%","8%","以上皆否"],a:0,e:"投资寿险保单利益说明文件须披露的年度净回报率规定为3%；4%、8%均不符合规定。",src:1,tw:{ch:"人壽保險程序",q:"年度淨回報率於投資壽險保單利益說明文件的具體規定是:",o:["3%","4%","8%","以上皆否"],e:"投資壽險保單利益說明文件須披露的年度淨回報率規定為3%；4%、8%均不符合規定。"}},
{p:3,ch:"人寿保险程序",q:"投保人于四月一日正式填妥投保书,保险人于四月十五日签发保单,并于四月十六日把保单交付给投保人",o:["应该,因为投保人于保单签发后的21日内提出要求","不应该,因为投保人于保单交付后30日内还未提出要求","不应该,因为投保人于保单投保后30日内还未提出要求","以上各项均不正确"],a:0,e:"冷静期由保单交付或通知书发出后起计21天，以较先者为准，投保人在保单签发后21日内提出要求即属期内，应获退还保费；「交付后30日」「投保后30日」等时限均错误。",src:1,tw:{ch:"人壽保險程序",q:"投保人於四月一日正式填妥投保書，保險人於四月十五日簽發保單，並於四月十六日把保單交付給投保人",o:["應該，因為投保人於保單簽發後的21日內提出要求","不應該，因為投保人於保單交付後30日內還未提出要求","不應該，因為投保人於保單投保後30日內還未提出要求","以上各項均不正確"],e:"冷靜期由保單交付或通知書發出後起計21天，以較先者為準，投保人在保單簽發後21日內提出要求即屬期內，應獲退還保費；「交付後30日」「投保後30日」等時限均錯誤。"}},
{p:3,ch:"人寿保险程序",q:"投保单一般由以下哪类人士负责填写及签署?",o:["投保人本身","投保人的有关保险代理人","专业保险经纪","代理投保人的律师"],a:0,e:"投保单一般由投保人本人负责填写及签署，以履行最高诚信披露义务；代理人、经纪或律师通常不代填代签。",src:1,tw:{ch:"人壽保險程序",q:"投保單一般由以下哪類人士負責填寫及簽署？",o:["投保人本身","投保人的有關保險代理人","專業保險經紀","代理投保人的律師"],e:"投保單一般由投保人本人負責填寫及簽署，以履行最高誠信披露義務；代理人、經紀或律師通常不代填代簽。"}},
{p:3,ch:"人寿保险程序",q:"投保单应由谁负责填写?",o:["投保人","代理人","顾客服务部职员","受益人"],a:0,e:"投保单是保险合约订立的基础文件，按规定应由投保人本人负责填写并签署，以确保申报资料真实准确。代理人或顾客服务部职员只能协助解释和转述，受益人亦非投保主体，均不负责填写。",src:1,tw:{ch:"人壽保險程序",q:"投保單應由誰負責填寫？",o:["投保人","代理人","顧客服務部職員","受益人"],e:"投保單是保險合約訂立的基礎文件，按規定應由投保人本人負責填寫並簽署，以確保申報資料真實準確。代理人或顧客服務部職員只能協助解釋和轉述，受益人亦非投保主體，均不負責填寫。"}},
{p:3,ch:"人寿保险程序",q:"投保手续包括填写投保单,保险中介人应于填写投保书时留意以下哪项或哪些?",o:["必须提供所有重要事实","应尽量避免改动及修正","应尽量全面回答所有问题","以上所有都应留意"],a:3,e:"投保手续中中介人填写投保书时须留意多项要点：诚实提交所有重要事实、尽量避免涂改修正、全面完整回答各项问题。三者均为填写投保书必须注意的事项，故答案为「以上所有都应留意」。",src:1,tw:{ch:"人壽保險程序",q:"投保手續包括填寫投保單，保險中介人應於填寫投保書時留意以下哪項或哪些？",o:["必須提供所有重要事實","應盡量避免改動及修正","應盡量全面回答所有問題","以上所有都應留意"],e:"投保手續中中介人填寫投保書時須留意多項要點：誠實提交所有重要事實、儘量避免塗改修正、全面完整回答各項問題。三者均為填寫投保書必須注意的事項，故答案為「以上所有都應留意」。"}},
{p:3,ch:"人寿保险程序",q:"投资相连保单的退保说明文件,保险公司必须说明于指定时间中可预期取得的退保金额及身故赔偿,该指定 时间为:",o:["保单首3年的每年年终,及其后每3年的年终","保单首5年的每年年终,及其后每5年的年终","保单首5年的每年年终,及其后每3年的年终","保单首3年的每年年终,及其后每5年的年终"],a:1,e:"投资相连保单的退保说明文件，保险公司须说明在指定时间可预期的退保金额及身故赔偿。按相关规定，该指定时间为保单首5年的每年年终，及其后每5年的年终，其余时间组合均不符规定。",src:1,tw:{ch:"人壽保險程序",q:"投資相連保單的退保說明文件，保險公司必須說明於指定時間中可預期取得的退保金額及身故賠償，該指定 時間為：",o:["保單首3年的每年年終，及其後每3年的年終","保單首5年的每年年終，及其後每5年的年終","保單首5年的每年年終，及其後每3年的年終","保單首3年的每年年終，及其後每5年的年終"],e:"投資相連保單的退保說明文件，保險公司須說明在指定時間可預期的退保金額及身故賠償。按相關規定，該指定時間為保單首5年的每年年終，及其後每5年的年終，其餘時間組合均不符規定。"}},
{p:3,ch:"人寿保险程序",q:"按照派发的方式,保单红利共有3种,包括:",o:["即时红利","最后红利","延迟红利","复归红利"],a:3,e:"按派发方式划分，保单红利通常分为现金（即时）红利、复归红利及延期（终期）红利三大类。四个选项中只有「复归红利」属于这三大类之一，即时红利、最后红利并非规范的红利分类。",src:1,tw:{ch:"人壽保險程序",q:"按照派發的方式，保單紅利共有3種，包括：",o:["即時紅利","最後紅利","延遲紅利","復歸紅利"],e:"按派發方式劃分，保單紅利通常分為現金（即時）紅利、復歸紅利及延期（終期）紅利三大類。四個選項中只有「復歸紅利」屬於這三大類之一，即時紅利、最後紅利並非規範的紅利分類。"}},
{p:3,ch:"人寿保险程序",q:"更改保单会对保险合约的条款有深远影响,故保险人会特别注意下列哪项呢?",o:["涉及法律或其他问题","有否出现意图欺诈行为如洗黑钱","可保性","以上各项皆是"],a:3,e:"更改保单会影响合约条款，保险人因此会特别留意多项风险：是否涉及法律等问题、有无洗黑钱等欺诈意图，以及可保性是否受影响。三者都在审核范围之内，故为「以上各项皆是」。",src:1,tw:{ch:"人壽保險程序",q:"更改保單會對保險合約的條款有深遠影響，故保險人會特別注意下列哪項呢？",o:["涉及法律或其他問題","有否出現意圖欺詐行為如洗黑錢","可保性","以上各項皆是"],e:"更改保單會影響合約條款，保險人因此會特別留意多項風險：是否涉及法律等問題、有無洗黑錢等欺詐意圖，以及可保性是否受影響。三者都在審核範圍之內，故為「以上各項皆是」。"}},
{p:3,ch:"人寿保险程序",q:"更改保单时要格外小心处理, 因为:",o:["有可能出现洗黑钱的情况","有需要再保险","这有机会影响到法律的更改","以上皆是"],a:3,e:"更改保单须格外小心处理，因为此举可能牵涉洗黑钱风险、需重新评估风险并安排再保险，也可能触及法律上的变更。三方面理由均成立，故答案为「以上皆是」。",src:1,tw:{ch:"人壽保險程序",q:"更改保單時要格外小心處理, 因為:",o:["有可能出現洗黑錢的情況","有需要再保險","這有機會影響到法律的更改","以上皆是"],e:"更改保單須格外小心處理，因為此舉可能牽涉洗黑錢風險、需重新評估風險並安排再保險，也可能觸及法律上的變更。三方面理由均成立，故答案為「以上皆是」。"}},
{p:3,ch:"人寿保险程序",q:"有一张人寿保单已列明保单权益会给予受托人的陈大文先生,陈先生与受保生命是有可保权益的。 现在,陈先生杀害了受保生命,那保单权益是?",o:["保单权益只会给予受益人,而非受托人","权益给付陈先生是违反基本法","谋杀犯会失去有关权利,因此陈先生不能申索保单赔偿","权益仍会赔付予陈先生"],a:2,e:"根据公共政策原则，任何人不得从自己的犯罪行为中获益。陈先生杀害受保生命，属于谋杀，故其本人丧失申索保单赔偿的权利，保单权益不能赔付予该谋杀者。",src:1,tw:{ch:"人壽保險程序",q:"有一張人壽保單已列明保單權益會給予受託人的陳大文先生，陳先生與受保生命是有可保權益的。 現在，陳先生殺害了受保生命，那保單權益是?",o:["保單權益只會給予受益人，而非受託人","權益給付陳先生是違反基本法","謀殺犯會失去有關權利，因此陳先生不能申索保單賠償","權益仍會賠付予陳先生"],e:"根據公共政策原則，任何人不得從自己的犯罪行為中獲益。陳先生殺害受保生命，屬於謀殺，故其本人喪失申索保單賠償的權利，保單權益不能賠付予該謀殺者。"}},
{p:3,ch:"人寿保险程序",q:"有一类人寿保险核保的元素,与风险的主观因素较为有关个尤其是准受保保单所有人的个人素质及态度,这 类元素称为:",o:["道德危险","实质危险","行为分析","人性因素评估"],a:0,e:"与受保生命个人素质、态度等主观因素相关的核保元素称为「道德危险」，指投保人品行或诚信可能影响其是否欺诈或对风险疏于防范。实质危险则指身体、年龄等客观条件，行为分析与人性因素评估并非规范术语。",src:1,tw:{ch:"人壽保險程序",q:"有一類人壽保險核保的元素，與風險的主觀因素較為有關個尤其是準受保保單所有人的個人素質及態度，這 類元素稱為：",o:["道德危險","實質危險","行為分析","人性因素評估"],e:"與受保生命個人素質、態度等主觀因素相關的核保元素稱為「道德危險」，指投保人品行或誠信可能影響其是否欺詐或對風險疏於防範。實質危險則指身體、年齡等客觀條件，行為分析與人性因素評估並非規範術語。"}},
{p:3,ch:"人寿保险程序",q:"有份人寿保险保单载明了死亡保险利益将支付给作为受托人之陈大民先生。要是陈先生谋杀了受保生命,下 列哪项是正确的?",o:["基于保险业条例,陈先生不可以向保单提出索偿","死亡利益赔偿予陈先生是违反基本法的","囚犯不可以成为受托人","以上各项皆不正确"],a:3,e:"受托人陈先生谋杀受保生命后虽确实不能申索，但其不得获益的依据是普通法的公共政策原则，而非《保险业条例》或《基本法》，也非因罪犯不能担任受托人。三项陈述理由均不准确，故「以上各项皆不正确」。",src:1,tw:{ch:"人壽保險程序",q:"有份人壽保險保單載明了死亡保險利益將支付給作為受托人之陳大民先生。要是陳先生謀殺了受保生命，下 列哪項是正確的？",o:["基於保險業條例，陳先生不可以向保單提出索償","死亡利益賠償予陳先生是違反基本法的","囚犯不可以成為受託人","以上各項皆不正確"],e:"受託人陳先生謀殺受保生命後雖確實不能申索，但其不得獲益的依據是普通法的公共政策原則，而非《保險業條例》或《基本法》，也非因罪犯不能擔任受託人。三項陳述理由均不準確，故「以上各項皆不正確」。"}},
{p:3,ch:"人寿保险程序",q:"期满索偿出现于:",o:["定期寿险","终身寿险","储蓄寿险","以上各项皆正确"],a:2,e:"期满索偿指受保人生存至保单期满而领取满期利益。储蓄寿险兼具保障与储蓄，保障期满时若受保人仍生存，可按约定领取满期金。定期寿险无满期价值，终身寿险保障终身亦无固定期满给付。",src:1,tw:{ch:"人壽保險程序",q:"期滿索償出現於：",o:["定期壽險","終身壽險","儲蓄壽險","以上各項皆正確"],e:"期滿索償指受保人生存至保單期滿而領取滿期利益。儲蓄壽險兼具保障與儲蓄，保障期滿時若受保人仍生存，可按約定領取滿期金。定期壽險無滿期價值，終身壽險保障終身亦無固定期滿給付。"}},
{p:3,ch:"人寿保险程序",q:"李先生生前为自己购买了一份人寿保险,而受益人为其妻子;但他死后其妻子却得不到赔偿,较可能的原因 是:",o:["他是在酒吧内发生的打斗中意外死亡","他的妻子蓄意谋杀他,目的为领取保险金","他在驾车时遇到交通意外引致身亡","他是在行劫时事败遭警员射杀的"],a:1,e:"妻子作为受益人蓄意谋杀被保人以领取保险金，属于受益人杀害被保险人，因公共政策不得从犯罪中获益，故失去领取赔偿的资格。酒后打斗、交通意外或被警员射杀等情形按条款通常仍可获赔。",src:1,tw:{ch:"人壽保險程序",q:"李先生生前為自己購買了一份人壽保險，而受益人為其妻子；但他死後其妻子卻得不到賠償，較可能的原因 是：",o:["他是在酒吧內發生的打鬥中意外死亡","他的妻子蓄意謀殺他，目的為領取保險金","他在駕車時遇到交通意外引致身亡","他是在行劫時事敗遭警員射殺的"],e:"妻子作為受益人蓄意謀殺被保人以領取保險金，屬於受益人殺害被保險人，因公共政策不得從犯罪中獲益，故失去領取賠償的資格。酒後打鬥、交通意外或被警員射殺等情形按條款通常仍可獲賠。"}},
{p:3,ch:"人寿保险程序",q:"某人在已购买人寿保单的情况下,计划再买另一份保单以取代(全部或部分)现有保单,这是?",o:["转让","转保","签发保单","以上各项也不正确"],a:1,e:"「转保」指投保人在已有人寿保单的情况下，以一份新保单取代全部或部分现有保单。这与保单权益的「转让」或首次「签发保单」不同，故正确答案为转保。",src:1,tw:{ch:"人壽保險程序",q:"某人在已購買人壽保單的情況下，計劃再買另一份保單以取代(全部或部分)現有保單，這是?",o:["轉讓","轉保","簽發保單","以上各項也不正確"],e:"「轉保」指投保人在已有人壽保單的情況下，以一份新保單取代全部或部分現有保單。這與保單權益的「轉讓」或首次「簽發保單」不同，故正確答案為轉保。"}},
{p:3,ch:"人寿保险程序",q:"核保时针对的风险可分为两大类,一类是实质危险另外一类是:",o:["非实质危险","道德危险","精神危险","形式上危险"],a:1,e:"核保针对的风险分为两大类：一类是实质危险（如年龄、健康状况等客观因素），另一类是道德危险（关乎投保人品行、诚信与投保动机）。非实质危险、精神危险、形式上危险均非规范分类。",src:1,tw:{ch:"人壽保險程序",q:"核保時針對的風險可分為兩大類，一類是實質危險另外一類是：",o:["非實質危險","道德危險","精神危險","形式上危險"],e:"核保針對的風險分為兩大類：一類是實質危險（如年齡、健康狀況等客觀因素），另一類是道德危險（關乎投保人品行、誠信與投保動機）。非實質危險、精神危險、形式上危險均非規範分類。"}},
{p:3,ch:"人寿保险程序",q:"根据送赠礼品指引,以下哪项并不属于「建立关系」而提供的礼品?",o:["抽奖奖品","获分配的基金单位花红","品牌建立活动的奖品","现金券"],a:3,e:"根据送赠礼品指引，为「建立关系」而提供的礼品如抽奖奖品、基金单位花红、品牌活动奖品等属许可范畴。现金券等同现金，不属于建立关系所允许的礼品，故不能送赠。",src:1,tw:{ch:"人壽保險程序",q:"根據送贈禮品指引，以下哪項並不屬於「建立關係」而提供的禮品？",o:["抽獎獎品","獲分配的基金單位花紅","品牌建立活動的獎品","現金券"],e:"根據送贈禮品指引，為「建立關係」而提供的禮品如抽獎獎品、基金單位花紅、品牌活動獎品等屬許可範疇。現金券等同現金，不屬於建立關係所允許的禮品，故不能送贈。"}},
{p:3,ch:"人寿保险程序",q:"正如名称所述,非(投资)相连保单销售说明书是指非投资相连人寿保险,但不包括:",o:["定期寿险","储蓄寿险","终身寿险","万用寿险"],a:3,e:"非（投资）相连保单销售说明书概述非投资相连人寿保险的利益，涵盖定期寿险、储蓄寿险、终身寿险等传统保单，但不包括万用寿险（须另备独立说明文件）。",src:1,tw:{ch:"人壽保險程序",q:"正如名稱所述，非(投資)相連保單銷售說明書是指非投資相連人壽保險，但不包括：",o:["定期壽險","儲蓄壽險","終身壽險","萬用壽險"],e:"非（投資）相連保單銷售說明書概述非投資相連人壽保險的利益，涵蓋定期壽險、儲蓄壽險、終身壽險等傳統保單，但不包括萬用壽險（須另備獨立說明文件）。"}},
{p:3,ch:"人寿保险程序",q:"由于人寿保险对个别寿险的核保只进行一次,所以第一次对寿险进行正确评核很重要,保险人就被保人建议 的保险金额评估,就有关风险程度建议或安排再保险,属于:",o:["财务性核保","技术性核保","技术性评审","道德及实际危险核保"],a:0,e:"财务性核保是针对投保金额与投保人经济状况是否相称的评估，包括就建议保额评估其合理性、衡量风险程度并据此建议或安排再保险。技术性核保则主要针对身体状况等风险事实，故本题属财务性核保。",src:1,tw:{ch:"人壽保險程序",q:"由於人壽保險對個別壽險的核保只進行一次，所以第一次對壽險進行正確評核很重要，保險人就被保人建議 的保險金額評估，就有關風險程度建議或安排再保險，屬於：",o:["財務性核保","技術性核保","技術性評審","道德及實際危險核保"],e:"財務性核保是針對投保金額與投保人經濟狀況是否相稱的評估，包括就建議保額評估其合理性、衡量風險程度並據此建議或安排再保險。技術性核保則主要針對身體狀況等風險事實，故本題屬財務性核保。"}},
{p:3,ch:"人寿保险程序",q:"相互保险公司在法律上由分红保单所有人拥有,而其管理是什么人负责?",o:["股东","保单所有人","董事局及高级管理层","代理人"],a:2,e:"相互保险公司在法律上由分红保单所有人拥有，股东不存在，其日常管理则由董事局及高级管理层负责执行。故答案为董事局及高级管理层。",src:1,tw:{ch:"人壽保險程序",q:"相互保險公司在法律上由分紅保單所有人擁有，而其管理是什麼人負責？",o:["股東","保單所有人","董事局及高級管理層","代理人"],e:"相互保險公司在法律上由分紅保單所有人擁有，股東不存在，其日常管理則由董事局及高級管理層負責執行。故答案為董事局及高級管理層。"}},
{p:3,ch:"人寿保险程序",q:"相互保险公司指:",o:["每年股东都只须负上有限负债","公司由股东拥有","所有保单所有人平均摊分利润及红利","公司在法律上由分红保单所有人拥有"],a:3,e:"相互保险公司没有股东，公司在法律上由分红保单所有人拥有，盈余以红利形式分配给保单所有人。每年承担有限负债、由股东拥有或平均摊分利润等表述均不准确。",src:1,tw:{ch:"人壽保險程序",q:"相互保險公司指：",o:["每年股東都只須負上有限負債","公司由股東擁有","所有保單所有人平均攤分利潤及紅利","公司在法律上由分紅保單所有人擁有"],e:"相互保險公司沒有股東，公司在法律上由分紅保單所有人擁有，盈餘以紅利形式分配給保單所有人。每年承擔有限負債、由股東擁有或平均攤分利潤等表述均不準確。"}},
{p:3,ch:"人寿保险程序",q:"相比技术性核保,财务性核保涉及对建议的保险金额作出评估,包括",o:["预期保单所有人履行缴付保费责任的能力","风险的程度,再保险是否可取","就同一受保生命已累积购买的保单计划","以上所有各项"],a:3,e:"财务性核保涉及对建议保险金额的评估，包括预期保单所有人履行缴付保费责任的能力、风险程度及再保险是否可取、以及就同一受保生命已累积购买的保单计划。三者皆属其范围。",src:1,tw:{ch:"人壽保險程序",q:"相比技術性核保，財務性核保涉及對建議的保險金額作出評估，包括",o:["預期保單所有人履行繳付保費責任的能力","風險的程度，再保險是否可取","就同一受保生命已累積購買的保單計劃","以上所有各項"],e:"財務性核保涉及對建議保險金額的評估，包括預期保單所有人履行繳付保費責任的能力、風險程度及再保險是否可取、以及就同一受保生命已累積購買的保單計劃。三者皆屬其範圍。"}},
{p:3,ch:"人寿保险程序",q:"相比投资相连保单与分红保单,分红保单的好处是?",o:["高透明度的保险运作","有保证现金价值和保证死亡利益","保单由独立的精算师监管","灵活性"],a:1,e:"相比投资相连保单，分红保单提供有保证的现金价值和保证的死亡利益，收益较稳定。投资相连保单的价值则随基金表现浮动、透明度较高，故分红保单的好处是「有保证现金价值和保证死亡利益」。",src:1,tw:{ch:"人壽保險程序",q:"相比投資相連保單與分紅保單，分紅保單的好處是？",o:["高透明度的保險運作","有保證現金價值和保證死亡利益","保單由獨立的精算師監管","靈活性"],e:"相比投資相連保單，分紅保單提供有保證的現金價值和保證的死亡利益，收益較穩定。投資相連保單的價值則隨基金表現浮動、透明度較高，故分紅保單的好處是「有保證現金價值和保證死亡利益」。"}},
{p:3,ch:"人寿保险程序",q:"精算能提供的职能是:",o:["产品定价","理赔及再保险","资产及负债价值","以上各项皆是"],a:3,e:"精算保险在保险公司中承担多项职能，包括产品定价、理赔及再保险的精算支持、以及资产与负债价值的计算。三项皆为其职能，故为「以上各项皆是」。",src:1,tw:{ch:"人壽保險程序",q:"精算能提供的職能是：",o:["產品定價","理賠及再保險","資產及負債價值","以上各項皆是"],e:"精算保險在保險公司中承擔多項職能，包括產品定價、理賠及再保險的精算支持、以及資產與負債價值的計算。三項皆為其職能，故為「以上各項皆是」。"}},
{p:3,ch:"人寿保险程序",q:"精算部在保险公司运作中发挥关键的作用,其任务包括: i 产品定价 ii 理赔及再保险 iii 管理报告 iv 资产及负债价值的计算",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:3,e:"精算部的关键任务涵盖产品定价、理赔及再保险、管理报告以及资产及负债价值的计算四项。四项均为精算部职责，故答案为 i、ii、iii、iv 全部。",src:1,tw:{ch:"人壽保險程序",q:"精算部在保險公司運作中發揮關鍵的作用，其任務包括： i 產品定價 ii 理賠及再保險 iii 管理報告 iv 資產及負債價值的計算",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"精算部的關鍵任務涵蓋產品定價、理賠及再保險、管理報告以及資產及負債價值的計算四項。四項均為精算部職責，故答案為 i、ii、iii、iv 全部。"}},
{p:3,ch:"人寿保险程序",q:"若事后确定投保人在投保时没有可保性的附条件保费收据,那么",o:["保单不会亦不曾有效","若客人附加保费,保单便会有效","任何情况下,客人的欺诈行为就成立","不管什么情况,须按照标准条款给予保障"],a:0,e:"附条件保费收据以投保人在投保时具有可保性为生效前提。若事后确定投保人投保时并无可保性，则附条件生效的条件不成立，保单不会亦不曾生效，而非附加保费即可生效。",src:1,tw:{ch:"人壽保險程序",q:"若事後確定投保人在投保時沒有可保性的附條件保費收據，那麼",o:["保單不會亦不曾有效","若客人附加保費，保單便會有效","任何情況下，客人的欺詐行為就成立","不管什麼情況，須按照標準條款給予保障"],e:"附條件保費收據以投保人在投保時具有可保性為生效前提。若事後確定投保人投保時並無可保性，則附條件生效的條件不成立，保單不會亦不曾生效，而非附加保費即可生效。"}},
{p:3,ch:"人寿保险程序",q:"获授权保险人在投资寿险保单利益说明文件中,必须包含哪一个假设年度净回报率以展示退保发还金额及身 故赔偿额?",o:["0%","4%","8%","以上皆否"],a:0,e:"获授权保险人在投资寿险保单利益说明文件中，须以0%的假设年度净回报率展示退保发还金额及身故赔偿额，让客户了解悲观看法下的最低利益，故答案为0%。",src:1,tw:{ch:"人壽保險程序",q:"獲授權保險人在投資壽險保單利益說明文件中，必須包含哪一個假設年度淨回報率以展示退保發還金額及身 故賠償額？",o:["0%","4%","8%","以上皆否"],e:"獲授權保險人在投資壽險保單利益說明文件中，須以0%的假設年度淨回報率展示退保發還金額及身故賠償額，讓客户瞭解悲觀看法下的最低利益，故答案為0%。"}},
{p:3,ch:"人寿保险程序",q:"营利公司与相互保险公司的分别在于?",o:["营利公司没有股东","相互保险公司没有股东","相互保险公司只经营人寿保险业务","营利公司只经营一般保险业务"],a:1,e:"营利公司由股东拥有并分享利润；相互保险公司则没有股东，由分红保单所有人拥有。相互保险公司并非只经营人寿保险业务，营利公司也不只经营一般保险业务，故正确分别在于「相互保险公司没有股东」。",src:1,tw:{ch:"人壽保險程序",q:"營利公司與相互保險公司的分別在於？",o:["營利公司沒有股東","相互保險公司沒有股東","相互保險公司只經營人壽保險業務","營利公司只經營一般保險業務"],e:"營利公司由股東擁有並分享利潤；相互保險公司則沒有股東，由分紅保單所有人擁有。相互保險公司並非只經營人壽保險業務，營利公司也不只經營一般保險業務，故正確分別在於「相互保險公司沒有股東」。"}},
{p:3,ch:"人寿保险程序",q:"许多人寿保险是在免体检的基础上安排的,但保险人亦可以要求投保人作合理的身体检查,而且投保人在进 行身体检查时有权知道:",o:["进行什么检查","检查资料的目的","任何检查的结果","以上各项皆是"],a:3,e:"投保人接受免体检或体检安排时，有权知道将进行哪些检查、检查资料的目的及任何检查的结果。三项均为投保人应被告知的内容，故为「以上各项皆是」。",src:1,tw:{ch:"人壽保險程序",q:"許多人壽保險是在免體檢的基礎上安排的，但保險人亦可以要求投保人作合理的身體檢查，而且投保人在進 行身體檢查時有權知道：",o:["進行什麼檢查","檢查資料的目的","任何檢查的結果","以上各項皆是"],e:"投保人接受免體檢或體檢安排時，有權知道將進行哪些檢查、檢查資料的目的及任何檢查的結果。三項均為投保人應被告知的內容，故為「以上各項皆是」。"}},
{p:3,ch:"人寿保险程序",q:"评估一份人寿保险的风险时,核保人可能会要求索取一份医疗报告,他除可向主诊医生索取外,还可向以下 哪项或哪些索取?",o:["独立医生","体检医生","非主诊医生","保险人委任的医生"],a:1,e:"核保人索取医疗报告时，除向主诊医生索取外，还可向为投保人进行体检的体检医生索取。独立医生、非主诊医生、保险人委任医生并非该题所规范的常规报告来源。",src:1,tw:{ch:"人壽保險程序",q:"評估一份人壽保險的風險時，核保人可能會要求索取一份醫療報告，他除可向主診醫生索取外，還可向以下 哪項或哪些索取？",o:["獨立醫生","體檢醫生","非主診醫生","保險人委任的醫生"],e:"核保人索取醫療報告時，除向主診醫生索取外，還可向為投保人進行體檢的體檢醫生索取。獨立醫生、非主診醫生、保險人委任醫生並非該題所規範的常規報告來源。"}},
{p:3,ch:"人寿保险程序",q:"负责执行再保险及风险评估是哪一个部门?",o:["精算部","会计部","理赔部","核保部"],a:3,e:"再保险安排与风险评估属于核保职能，由核保部负责执行。精算部负责定价与负债计算，会计部负责财务，理赔部处理索偿，故答案为核保部。",src:1,tw:{ch:"人壽保險程序",q:"負責執行再保險及風險評估是哪一個部門?",o:["精算部","會計部","理賠部","核保部"],e:"再保險安排與風險評估屬於核保職能，由核保部負責執行。精算部負責定價與負債計算，會計部負責財務，理賠部處理索償，故答案為核保部。"}},
{p:3,ch:"人寿保险程序",q:"财务性核保包括?",o:["被保险人是否有能力缴付保费","审慎的再保险情况","已累积购买的保单计划","以上都是"],a:3,e:"财务性核保包括评估被保险人缴付保费的能力、审慎的再保险安排、以及其已累积购买的保单计划。三者均属财务性核保范畴，故为「以上都是」。",src:1,tw:{ch:"人壽保險程序",q:"財務性核保包括？",o:["被保險人是否有能力繳付保費","審慎的再保險情況","已累積購買的保單計劃","以上都是"],e:"財務性核保包括評估被保險人繳付保費的能力、審慎的再保險安排、以及其已累積購買的保單計劃。三者均屬財務性核保範疇，故為「以上都是」。"}},
{p:3,ch:"人寿保险程序",q:"转保:",o:["是违法的","不符合保险代理协议","不符合可保权益的先决条件","在商业上是合理的"],a:3,e:"转保指以新保单取代现有保单，只要如实处理并符合监管要求，在商业上是合理的安排，并非违法。它不涉及保险代理协议的违反，也不违背可保权益的先决条件。",src:1,tw:{ch:"人壽保險程序",q:"轉保:",o:["是違法的","不符合保險代理協議","不符合可保權益的先決條件","在商業上是合理的"],e:"轉保指以新保單取代現有保單，只要如實處理並符合監管要求，在商業上是合理的安排，並非違法。它不涉及保險代理協議的違反，也不違背可保權益的先決條件。"}},
{p:3,ch:"人寿保险程序",q:"近因指某一索偿个案中造成损失的主要有效原因。以下哪项索偿不会受到近因所影响?",o:["一份寿险保单生效五年后,被保人自杀","一份受双倍赔偿利益约束的保单","死因有可疑或保单生效不足,两个月便自杀的索偿","一份寿险包含有意外死亡及丧失肢体附加保障利益"],a:0,e:"寿险对自杀通常在保单首一至两年列为除外，保单生效五年后自杀已不再受该除外限制，无论死因如何均按条款给付，故该索偿不受近因原则影响。其余涉及双倍赔偿、可疑死因及意外附加利益的索偿均需查明近因。",src:1,tw:{ch:"人壽保險程序",q:"近因指某一索償個案中造成損失的主要有效原因。以下哪項索償不會受到近因所影響？",o:["一份壽險保單生效五年後，被保人自殺","一份受雙倍賠償利益約束的保單","死因有可疑或保單生效不足，兩個月便自殺的索償","一份壽險包含有意外死亡及喪失肢體附加保障利益"],e:"壽險對自殺通常在保單首一至兩年列為除外，保單生效五年後自殺已不再受該除外限制，無論死因如何均按條款給付，故該索償不受近因原則影響。其餘涉及雙倍賠償、可疑死因及意外附加利益的索償均需查明近因。"}},
{p:3,ch:"人寿保险程序",q:"通常要求主诊医生报告的原因是:",o:["要求的保险金额很高","投保人的年龄较高","进一步调查投保单中所披露的某些健康资料","以上都是原因"],a:3,e:"核保人通常因保险金额很高、投保人年龄较高，或需进一步调查投保单披露的某些健康资料而要求主诊医生报告。三者皆为索取主诊医生报告的原因，故为「以上都是原因」。",src:1,tw:{ch:"人壽保險程序",q:"通常要求主診醫生報告的原因是：",o:["要求的保險金額很高","投保人的年齡較高","進一步調查投保單中所披露的某些健康資料","以上都是原因"],e:"核保人通常因保險金額很高、投保人年齡較高，或需進一步調查投保單披露的某些健康資料而要求主診醫生報告。三者皆為索取主診醫生報告的原因，故為「以上都是原因」。"}},
{p:3,ch:"人寿保险程序",q:"除了寿险保单的资料之外,还有一些补充详情,这些详情不大可能包括下列哪项?",o:["可保证明","谁人替代保单持有人缴交保费","某些病情/疾病的额外健康资料","支付未来保费方式"],a:1,e:"寿险核保的补充详情包括可保证明、某些病情的额外健康资料及支付未来保费方式等。由谁人替代保单持有人缴交保费与核保风险评估无关，不大可能列为需补充的详情。",src:1,tw:{ch:"人壽保險程序",q:"除了壽險保單的資料之外，還有一些補充詳情，這些詳情不大可能包括下列哪項？",o:["可保證明","誰人替代保單持有人繳交保費","某些病情/疾病的額外健康資料","支付未來保費方式"],e:"壽險核保的補充詳情包括可保證明、某些病情的額外健康資料及支付未來保費方式等。由誰人替代保單持有人繳交保費與核保風險評估無關，不大可能列為需補充的詳情。"}},
{p:3,ch:"人寿保险程序",q:"除了技术性核保之外,核保还要注意财务性核保。以下哪项问题是关于财务性核保的?",o:["准被保险人之健康状况","准被保险人的基本诚信及意向","保额是否超出一般情况类似的人的通常水准","以上所有皆是"],a:2,e:"财务性核保关注保额与投保人经济状况是否相称，例如保额是否超出类似人士的一般水平。健康状况属技术性核保，基本诚信及意向属道德危险范畴，故本题指「保额是否超出通常水准」。",src:1,tw:{ch:"人壽保險程序",q:"除了技術性核保之外，核保還要注意財務性核保。以下哪項問題是關於財務性核保的？",o:["準被保險人之健康狀況","準被保險人的基本誠信及意向","保額是否超出一般情況類似的人的通常水準","以上所有皆是"],e:"財務性核保關注保額與投保人經濟狀況是否相稱，例如保額是否超出類似人士的一般水平。健康狀況屬技術性核保，基本誠信及意向屬道德危險範疇，故本題指「保額是否超出通常水準」。"}},
{p:3,ch:"人寿保险程序",q:"除投保单外,寿险公司核保人有时要求合资格医疗人员就投保人健康状况提供进一步资料。下列哪两项是这 些资料的来源? i   主诊医生 ii  体检医生 iii 法庭委任的医生 iv  最近出版的医学百科全书",o:["i, ii","ii, iii","iii, iv","i, iv"],a:0,e:"除投保单外，核保人要求合资格医疗人员提供进一步资料时，来源主要是主诊医生及体检医生。法庭委任的医生及医学百科全书并非医疗报告的资料来源，故答案为 i、ii。",src:1,tw:{ch:"人壽保險程序",q:"除投保單外，壽險公司核保人有時要求合資格醫療人員就投保人健康狀況提供進一步資料。下列哪兩項是這 些資料的來源？ i 主診醫生 ii 體檢醫生 iii 法庭委任的醫生 iv 最近出版的醫學百科全書",o:["i, ii","ii, iii","iii, iv","i, iv"],e:"除投保單外，核保人要求合資格醫療人員提供進一步資料時，來源主要是主診醫生及體檢醫生。法庭委任的醫生及醫學百科全書並非醫療報告的資料來源，故答案為 i、ii。"}},
{p:3,ch:"人寿保险程序",q:"非(投资)相连保单销售说明书显示预期红利及现金支付利息,相关息率:",o:["在说明书中指明并且是保证的","在说明书中并无指明或保证的","在说明书中指明但此息率是没有保证的","在说明书中并无指明但息率是保证的,与市场息率相同"],a:2,e:"非（投资）相连保单销售说明书列示预期红利及现金支付利息，相关息率在说明书中虽有指明，但属于没有保证的假设息率。故答案为「在说明书中指明但此息率是没有保证的」。",src:1,tw:{ch:"人壽保險程序",q:"非(投資)相連保單銷售說明書顯示預期紅利及現金支付利息，相關息率：",o:["在說明書中指明並且是保證的","在說明書中並無指明或保證的","在說明書中指明但此息率是沒有保證的","在說明書中並無指明但息率是保證的，與市場息率相同"],e:"非（投資）相連保單銷售說明書列示預期紅利及現金支付利息，相關息率在說明書中雖有指明，但屬於沒有保證的假設息率。故答案為「在說明書中指明但此息率是沒有保證的」。"}},
{p:3,ch:"人寿保险程序",q:"非(投资)相连保单销售说明书的目的,是要概述非投资相连寿险(不包括万用寿险)的利益,并适用于:",o:["定期寿险","储蓄寿险","终身寿险","除了纯死亡保险金之外,还提供其他回报的保单"],a:3,e:"非（投资）相连保单销售说明书适用于除纯死亡保险金外还提供其他回报（如储蓄、分红）的非投资相连保单。定期、储蓄、终身寿险均为其涵盖对象，故应选涵盖「除纯死亡保险金外还提供其他回报的保单」。",src:1,tw:{ch:"人壽保險程序",q:"非(投資)相連保單銷售說明書的目的，是要概述非投資相連壽險(不包括萬用壽險)的利益，並適用於：",o:["定期壽險","儲蓄壽險","終身壽險","除了純死亡保險金之外，還提供其他回報的保單"],e:"非（投資）相連保單銷售說明書適用於除純死亡保險金外還提供其他回報（如儲蓄、分紅）的非投資相連保單。定期、儲蓄、終身壽險均為其涵蓋對象，故應選涵蓋「除純死亡保險金外還提供其他回報的保單」。"}},
{p:3,ch:"人寿保险程序",q:"顾客服务又称为:",o:["Proud of Our Service","Policyowner Service","Priority Office Service","Policy Operations Service"],a:1,e:"顾客服务部的英文名称为 Policyowner Service（保单所有人服务）。其余选项并非顾客服务的标准英文名称。",src:1,tw:{ch:"人壽保險程序",q:"顧客服務又稱為：",o:["Proud of Our Service","Policyowner Service","Priority Office Service","Policy Operations Service"],e:"顧客服務部的英文名稱為 Policyowner Service（保單所有人服務）。其餘選項並非顧客服務的標準英文名稱。"}},
{p:3,ch:"人寿保险程序",q:"风险评估、选择、评级以及按需要附加限制条款。决定所需的再保险程度并针对个别保险情况,而作出适当 的再保险安排,属于哪个部门的活动?",o:["理赔部","核保部","保单条款制定部","精算部"],a:1,e:"风险评估、选择、评级、附加限制条款以及决定再保险程度并作相应安排，属于核保部的核心活动。理赔部负责索偿处理，保单条款制定部与精算部亦不承担再保险安排职能。",src:1,tw:{ch:"人壽保險程序",q:"風險評估、選擇、評級以及按需要附加限制條款。決定所需的再保險程度並針對個別保險情況，而作出適當 的再保險安排，屬於哪個部門的活動？",o:["理賠部","核保部","保單條款制定部","精算部"],e:"風險評估、選擇、評級、附加限制條款以及決定再保險程度並作相應安排，屬於核保部的核心活動。理賠部負責索償處理，保單條款制定部與精算部亦不承擔再保險安排職能。"}},
{p:1,ch:"风险与保险",q:"以下哪项或哪些潜在损失可能是可保的？",o:["财务上的","情緖上的","心理上的","以上各项皆是"],a:0,e:"可保损失必须是能以金钱衡量并由保单补偿的财务损失。情绪上、心理上的损失难以用金钱量化衡量，不具备可保性，故仅「财务上的」潜在损失可能可保。",src:1,tw:{ch:"風險與保險",q:"以下哪項或哪些潛在損失可能是可保的？",o:["財務上的","情緖上的","心理上的","以上各項皆是"],e:"可保損失必須是能以金錢衡量並由保單補償的財務損失。情緒上、心理上的損失難以用金錢量化衡量，不具備可保性，故僅「財務上的」潛在損失可能可保。"}},
{p:1,ch:"风险与保险",q:"「投机风险」的定义：",o:["一个有收益及损失的可能的风险","一个商业风险","一个只有收益但没有损失的可能的风险","一份可使无效的合约"],a:0,e:"投机风险指既有损失可能、也有收益可能的风险，如投资股票。商业风险只是其一种表现，只有收益或只有损失均不完整，故正确定义为「一个有收益及损失的可能的风险」。",src:1,tw:{ch:"風險與保險",q:"「投機風險」的定義：",o:["一個有收益及損失的可能的風險","一個商業風險","一個只有收益但沒有損失的可能的風險","一份可使無效的合約"],e:"投機風險指既有損失可能、也有收益可能的風險，如投資股票。商業風險只是其一種表現，只有收益或只有損失均不完整，故正確定義為「一個有收益及損失的可能的風險」。"}},
{p:1,ch:"风险与保险",q:"特定风险是指：",o:["相当可能影响大量人数的风险","相当可能不会导致灾难的后果","相当可能导致灾难性的后果","相当可能牵涉政府"],a:1,e:"特定风险的影响较个别化，相当可能不会导致灾难性后果或广泛影响大量人士。会导致灾难后果、影响大量人数或牵涉政府的属基本风险，故特定风险应选「不会导致灾难的后果」。",src:1,tw:{ch:"風險與保險",q:"特定風險是指：",o:["相當可能影響大量人數的風險","相當可能不會導致災難的後果","相當可能導致災難性的後果","相當可能牽涉政府"],e:"特定風險的影響較個別化，相當可能不會導致災難性後果或廣泛影響大量人士。會導致災難後果、影響大量人數或牽涉政府的屬基本風險，故特定風險應選「不會導致災難的後果」。"}},
{p:1,ch:"风险与保险",q:"在知识及研究的范畴中，风险管理的步骤包括识别风险﹑应对风险及 。 _________",o:["防范化","商讨计策","量化风险","减轻风险"],a:2,e:"风险管理作为独立的知识范畴，其步骤包括识别风险、量化（评估）风险及应对风险。「量化风险」为中间一步，防范化、商讨计策、减轻风险均非规范步骤名称。",src:1,tw:{ch:"風險與保險",q:"在知識及研究的範疇中，風險管理的步驟包括識別風險﹑應對風險及 。 _________",o:["防範化","商討計策","量化風險","減輕風險"],e:"風險管理作為獨立的知識範疇，其步驟包括識別風險、量化（評估）風險及應對風險。「量化風險」為中間一步，防範化、商討計策、減輕風險均非規範步驟名稱。"}},
{p:1,ch:"风险与保险",q:"风险管理在独立的知识及研究范畴上，一般的理解为：",o:["投资或投机风险所带来的损失","保险人对受保风险损失上的改善","以识别、量化及应对作为进行的步骤","环绕著对保险合约的订立及处理"],a:2,e:"风险管理一般的理解是以识别、量化及应对作为进行的步骤，针对可保及不可保风险作系统管理。其余选项仅描述局部内容或保险合约范畴，非完整定义。",src:1,tw:{ch:"風險與保險",q:"風險管理在獨立的知識及研究範疇上，一般的理解為：",o:["投資或投機風險所帶來的損失","保險人對受保風險損失上的改善","以識別、量化及應對作為進行的步驟","環繞著對保險合約的訂立及處理"],e:"風險管理一般的理解是以識別、量化及應對作為進行的步驟，針對可保及不可保風險作系統管理。其餘選項僅描述局部內容或保險合約範疇，非完整定義。"}},
{p:1,ch:"风险与保险",q:"请说明以下风险工具： 不提供食物及饮料以免除食物中毒的风险。",o:["损失防范","风险融资","风险转移","风险避免"],a:3,e:"不提供食物及饮料，是从源头上彻底消除食物中毒风险的发生可能，属于「风险避免」。损失防范是降低损失发生频率，风险融资与风险转移则属事后或财务安排。",src:1,tw:{ch:"風險與保險",q:"請說明以下風險工具： 不提供食物及飲料以免除食物中毒的風險。",o:["損失防範","風險融資","風險轉移","風險避免"],e:"不提供食物及飲料，是從源頭上徹底消除食物中毒風險的發生可能，屬於「風險避免」。損失防範是降低損失發生頻率，風險融資與風險轉移則屬事後或財務安排。"}},
{p:1,ch:"法律原则",q:"以下哪三项关于一份法律责任保险合约是正确的? i 不是所有协议都具有法律效力 ii 必须是经盖章的 iii 是一份可强制执行的协议 iv 严格来说，合约是无形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"法律责任保险合约是具法律效力的可强制执行协议，严格来说合约本身是无形的；但并非所有协议都具有法律效力，也并非必须经盖章（只有契据才须盖章）。故正确三项为 i、iii、iv。",src:1,tw:{ch:"法律原則",q:"以下哪三項關於一份法律責任保險合約是正確的? i 不是所有協議都具有法律效力 ii 必須是經蓋章的 iii 是一份可強制執行的協議 iv 嚴格來說，合約是無形的",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"法律責任保險合約是具法律效力的可強制執行協議，嚴格來說合約本身是無形的；但並非所有協議都具有法律效力，也並非必須經蓋章（只有契據才須蓋章）。故正確三項為 i、iii、iv。"}},
{p:1,ch:"法律原则",q:"保险公司发出的担保，是属于：",o:["简单合约","契据","复杂合约","不能强制执行的合约"],a:1,e:"保险公司发出的担保（保证）须经正式盖章并采用契据形式，故属于「契据」，而非简单合约。契据以其形式（盖章）获得法律约束力，故答案为契据。",src:1,tw:{ch:"法律原則",q:"保險公司發出的擔保，是屬於：",o:["簡單合約","契據","複雜合約","不能強制執行的合約"],e:"保險公司發出的擔保（保證）須經正式蓋章並採用契據形式，故屬於「契據」，而非簡單合約。契據以其形式（蓋章）獲得法律約束力，故答案為契據。"}},
{p:1,ch:"法律原则",q:"一份「可使无效」的合约，如果合约的受屈一方没有采取有关行动，那么：",o:["有关合约可在法庭上执行","有关合约在合理时间后便会变成无效","有关合约在合理时间后便不会变成无效","有关合约没有法律效力"],a:2,e:"可使无效的合约赋予受屈一方撤销合约的选择权；若受屈一方没有在合理时间内采取撤销行动，合约仍具效力，不会自动变成无效。故「在合理时间后便不会变成无效」为正确。",src:1,tw:{ch:"法律原則",q:"一份「可使無效」的合約，如果合約的受屈一方沒有採取有關行動，那麼：",o:["有關合約可在法庭上執行","有關合約在合理時間後便會變成無效","有關合約在合理時間後便不會變成無效","有關合約沒有法律效力"],e:"可使無效的合約賦予受屈一方撤銷合約的選擇權；若受屈一方沒有在合理時間內採取撤銷行動，合約仍具效力，不會自動變成無效。故「在合理時間後便不會變成無效」為正確。"}},
{p:1,ch:"法律原则",q:"在代理法中，「表面权限」是指:",o:["权限不存在","代理人的行为订立一份或一宗对委托人有约束力的合约或交易","代理人已获得明确的指示行事","所有情况下显示实际权限已经存在"],a:1,e:"「表面权限」指依表象或委托人行为，使第三者合理相信代理人获授权而行事，其行为订立的合约或交易对委托人有约束力。它与实际权限、明示指示不同，故答案为「代理人订立对委托人有约束力的合约或交易」。",src:1,tw:{ch:"法律原則",q:"在代理法中，「表面權限」是指:",o:["權限不存在","代理人的行為訂立一份或一宗對委託人有約束力的合約或交易","代理人已獲得明確的指示行事","所有情況下顯示實際權限已經存在"],e:"「表面權限」指依表象或委託人行為，使第三者合理相信代理人獲授權而行事，其行為訂立的合約或交易對委託人有約束力。它與實際權限、明示指示不同，故答案為「代理人訂立對委託人有約束力的合約或交易」。"}},
{p:1,ch:"法律原则",q:"在给予通知及/或代价补偿的合约条文下，属于以下哪项终止代理关系的方式？",o:["双方同意","撤销协议","精神错乱","违反合约"],a:1,e:"在给予通知及/或代价补偿的条文下，通过撤销协议终止代理关系是法定终止方式之一。双方同意、精神错乱、违反合约均非题述「给予通知及代价补偿」下的终止方式。",src:1,tw:{ch:"法律原則",q:"在給予通知及/或代價補償的合約條文下，屬於以下哪項終止代理關係的方式？",o:["雙方同意","撤銷協議","精神錯亂","違反合約"],e:"在給予通知及/或代價補償的條文下，通過撤銷協議終止代理關係是法定終止方式之一。雙方同意、精神錯亂、違反合約均非題述「給予通知及代價補償」下的終止方式。"}},
{p:1,ch:"法律原则",q:"某人在某时为他人的最佳利益行事，虽然他事前并没有获得授权，但在法律上却持有这权限，并 被视为:",o:["必要代理人","不容反悔代理人","明示权限代理人","表面权限代理人"],a:0,e:"在紧急情况下，事前未获授权但为他人最佳利益而必要地行事的人，法律上视为获授权，称为「必要代理人」。不容反悔、明示、表面权限代理人均不符题意。",src:1,tw:{ch:"法律原則",q:"某人在某時為他人的最佳利益行事，雖然他事前並沒有獲得授權，但在法律上卻 持有這權限，並被視為:",o:["必要代理人","不容反悔代理人","明示權限代理人","表面權限代理人"],e:"在緊急情況下，事前未獲授權但為他人最佳利益而必要地行事的人，法律上視為獲授權，稱為「必要代理人」。不容反悔、明示、表面權限代理人均不符題意。"}},
{p:1,ch:"保险原则",q:"阿伦准许他的朋友玫瑰免费住在一个他拥有的单位2 个月。请问玫瑰可否为该单位购买保险? 原 因何在?",o:["可以，合法占用单位人均有权以所有人的代理人身份为该单位购买保险","不可以，因玫瑰没有付出代价","可以，因玫瑰以受托保管人的身份对该单位有权益","不可以，因玫瑰并非拥有该单位"],a:2,e:"玫瑰免费暂住该单位，虽非所有人，但作为合法占有并负有保管责任的受托保管人，对该单位具有可保权益，可以购买保险。故答案为「玫瑰以受托保管人的身份对该单位有权益」。",src:1,tw:{ch:"保險原則",q:"阿倫准許他的朋友玫瑰免費住在一個他擁有的單位2個月。請問玫瑰可否為該 單位購買保險? 原因何在?",o:["可以，合法佔用單位人均有權以所有人的代理人身份為該單位購買保險","不可以，因玫瑰沒有付出代價","可以，因玫瑰以受託保管人的身份對該單位有權益","不可以，因玫瑰並非擁有該單位"],e:"玫瑰免費暫住該單位，雖非所有人，但作為合法佔有並負有保管責任的受託保管人，對該單位具有可保權益，可以購買保險。故答案為「玫瑰以受託保管人的身份對該單位有權益」。"}},
{p:1,ch:"保险原则",q:"以下哪些财产可投买保险？ i 从偷窃中得来的财产 ii 以持有人名义投买的财产 iii 信托人保管的财产 iv 遗嘱执行人保管的财产",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],a:1,e:"以持有人名义投买的财产、信托人及遗嘱执行人保管的财产，投保人对其均具合法权益，均可投保；从偷窃得来的财产不产生合法可保权益，不得投保。故可投保者为 ii、iii、iv。",src:1,tw:{ch:"保險原則",q:"以下哪些財產可投買保險？ i 從偷竊中得來的財產 ii 以持有人名義投買的財產 iii 信託人保管的財產 iv 遺囑執行人保管的財產",o:["i, ii, iii","ii, iii, iv","i, ii, iv","i, ii, iii, iv"],e:"以持有人名義投買的財產、信託人及遺囑執行人保管的財產，投保人對其均具合法權益，均可投保；從偷竊得來的財產不產生合法可保權益，不得投保。故可投保者為 ii、iii、iv。"}},
{p:1,ch:"保险原则",q:"有别于最高诚信，一般诚信要求：",o:["保证所作出的陈述是百分百真实","不论有否被问及，以须陈述","应用于整个保险合约过程","忠实并确保所有陈述是实质上真实"],a:3,e:"最高诚信要求主动披露所有重要事实且绝对真实；一般诚信则要求忠实并确保所作陈述在实质上是真实的，无须如最高诚信般全面主动披露。故答案为「忠实并确保所有陈述是实质上真实」。",src:1,tw:{ch:"保險原則",q:"有別於最高誠信，一般誠信要求：",o:["保證所作出的陳述是百分百真實","不論有否被問及，以須陳述","應用於整個保險合約過程","忠實並確保所有陳述是實質上真實"],e:"最高誠信要求主動披露所有重要事實且絕對真實；一般誠信則要求忠實並確保所作陳述在實質上是真實的，無須如最高誠信般全面主動披露。故答案為「忠實並確保所有陳述是實質上真實」。"}},
{p:1,ch:"保险原则",q:"以下哪三项是被视为达反最高诚信﹕ i 欺诈性不披露 ii 欺诈性不声明 iii 欺诈性失实陈述 iv 非欺诈性失实陈述",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],a:2,e:"违反最高诚信的情形包括欺诈性不披露、欺诈性失实陈述及非欺诈性失实陈述。「欺诈性不声明」并非独立的法定分类，故正确三项为 i、iii、iv。",src:1,tw:{ch:"保險原則",q:"以下哪三項是被視為達反最高誠信﹕ i 欺詐性不披露 ii 欺詐性不聲明 iii 欺詐性失實陳述 iv 非欺詐性失實陳述",o:["i, ii, iii","i, ii, iv","i, iii, iv","ii, iii, iv"],e:"違反最高誠信的情形包括欺詐性不披露、欺詐性失實陳述及非欺詐性失實陳述。「欺詐性不聲明」並非獨立的法定分類，故正確三項為 i、iii、iv。"}},
{p:1,ch:"保险原则",q:"「近因」是很重要的，因为：",o:["它是找出购买保险的原因","需要它去确定保险标的的价值","不是每一项引致损失的原因均受到保障","以上各项皆是"],a:2,e:"近因之所以重要，是因为并非每一项引致损失的原因都在保单保障范围之内，须以造成损失的主要有效原因判断是否属保障危险。故答案为「不是每一项引致损失的原因均受到保障」。",src:1,tw:{ch:"保險原則",q:"「近因」是很重要的，因為：",o:["它是找出購買保險的原因","需要它去確定保險標的的價值","不是每一項引致損失的原因均受到保障","以上各項皆是"],e:"近因之所以重要，是因為並非每一項引致損失的原因都在保單保障範圍之內，須以造成損失的主要有效原因判斷是否屬保障危險。故答案為「不是每一項引致損失的原因均受到保障」。"}},
{p:1,ch:"保险原则",q:"一个单位购买火险后，邻居发生火警，在必要情况下，消防员需要破坏此单位某些设施进入邻居 救火，有关这些设施的损失：",o:["因为受保危险引致不保危险，故此可得到赔偿","因为不保危险引致受保危险，故此得不到赔偿","属于不保危险，故此得不到赔偿","属于受保危险，故此得到赔偿"],a:0,e:"消防员为救邻居火警而破坏本单位设施，其起因是受保的危险（火灾）导致本属不保的破坏。依近因原则，受保危险引致的后续损失可获赔偿，故答案为「受保危险引致不保危险，故此可得到赔偿」。",src:1,tw:{ch:"保險原則",q:"一個單位購買火險後，鄰居發生火警，在必要情況下，消防員需要破壞此單 位某些設施進入鄰居救火，有關這些設施的損失：",o:["因為受保危險引致不保危險，故此可得到賠償","因為不保危險引致受保危險，故此得不到賠償","屬於不保危險，故此得不到賠償","屬於受保危險，故此得到賠償"],e:"消防員為救鄰居火警而破壞本單位設施，其起因是受保的危險（火災）導致本屬不保的破壞。依近因原則，受保危險引致的後續損失可獲賠償，故答案為「受保危險引致不保危險，故此可得到賠償」。"}},
{p:1,ch:"保险原则",q:"如果一份保单有6000 元的免赔额，意思是：",o:["如果损失超过6000 元便不会得到赔偿","如果损失不超过6000 元便会得到赔偿","如果损失超过6000 元便会得到全额赔偿","如果损失不超过6000 元便不会得到赔偿"],a:3,e:"免赔额（自负额）指损失在约定金额以下时由被保险人自行承担，保险人不赔。故6000元免赔额意为：损失不超过6000元便不会得到赔偿，超过部分才由保险人承担。",src:1,tw:{ch:"保險原則",q:"如果一份保單有6000元的免賠額，意思是：",o:["如果損失超過6000元便不會得到賠償","如果損失不超過6000元便會得到賠償","如果損失超過6000元便會得到全額賠償","如果損失不超過6000元便不會得到賠償"],e:"免賠額（自負額）指損失在約定金額以下時由被保險人自行承擔，保險人不賠。故6000元免賠額意為：損失不超過6000元便不會得到賠償，超過部分才由保險人承擔。"}},
{p:1,ch:"保险原则",q:"有一宗火险涉及$2,000,000 的损失，当事人为财产购入重复保险，保险人的保单中有责任限额 $10,000,000 及自负额$6,000。最后，保险人赔偿$1,000,000。由此可见：",o:["所有有关保单均有分担条款","这份保单有分担条款","这份保单有五成「比例分摊」条款","所有有关保单都有「比率之数」条款"],a:1,e:"损失为2,000,000元而保险人仅赔1,000,000元（扣除自负额后按比例），显示这份保单载有与其他保单按比例分担的分担条款。题的其余选项把范围扩大至所有保单或特定比例，均无依据。",src:1,tw:{ch:"保險原則",q:"有一宗火險涉及$2,000,000 的損失，當事人為財產購入重複保險，保險人的保單中有責任限額 $10,000,000 及自負額$6,000。最後，保險人賠償$1,000,000。由此可見：",o:["所有有關保單均有分擔條款","這份保單有分擔條款","這份保單有五成「比例分攤」條款","所有有關保單都有「比率之數」條款"],e:"損失為2,000,000元而保險人僅賠1,000,000元（扣除自負額後按比例），顯示這份保單載有與其他保單按比例分擔的分擔條款。題的其餘選項把範圍擴大至所有保單或特定比例，均無依據。"}},
{p:1,ch:"保险原则",q:"代位权可以透过以下哪种／哪些方式产生？",o:["侵权法上","合约上","法规上","以上各项皆是"],a:3,e:"代位权可透过侵权法、合约及法规等多种途径产生。三项来源均存在，故答案为「以上各项皆是」。",src:1,tw:{ch:"保險原則",q:"代位權可以透過以下哪種／哪些方式產生？",o:["侵權法上","合約上","法規上","以上各項皆是"],e:"代位權可透過侵權法、合約及法規等多種途徑產生。三項來源均存在，故答案為「以上各項皆是」。"}},
{p:1,ch:"保险原则",q:"以下哪项并不构成可保权益？",o:["其自身","其配偶","其未婚妻","其欠债人"],a:2,e:"人对其自身、配偶及欠债人（债务人对其欠款金额有可保权益）均具可保权益。未婚妻在普通法上并非配偶，与投保人之间不存在法定可保权益，故不构成可保权益。",src:1,tw:{ch:"保險原則",q:"以下哪項並不構成可保權益？",o:["其自身","其配偶","其未婚妻","其欠債人"],e:"人對其自身、配偶及欠債人（債務人對其欠款金額有可保權益）均具可保權益。未婚妻在普通法上並非配偶，與投保人之間不存在法定可保權益，故不構成可保權益。"}},
{p:1,ch:"保险原则",q:"下列哪项或哪些例子符合可保权益所要求的条件？",o:["一名盗贼希望替自己偷窃得来的财物投买保险","一名男子希望替自己拥有的汽车投买保险","一名男子为了自己的利益，希望替他那位粗心大意的朋友的手表投买保险","上述所有各项"],a:1,e:"男子对自己拥有的汽车有财产可保权益，可以投保。盗贼对偷窃所得的财物、以及他人为盗取保险金而替朋友手表投保均无合法可保权益，故仅「自己拥有的汽车」符合条件。",src:1,tw:{ch:"保險原則",q:"下列哪項或哪些例子符合可保權益所要求的條件？",o:["一名盜賊希望替自己偷竊得來的財物投買保險","一名男子希望替自己擁有的汽車投買保險","一名男子為了自己的利益，希望替他那位粗心大意的朋友的手錶投買保險","上述所有各項"],e:"男子對自己擁有的汽車有財產可保權益，可以投保。盜賊對偷竊所得的財物、以及他人為盜取保險金而替朋友手錶投保均無合法可保權益，故僅「自己擁有的汽車」符合條件。"}},
{p:1,ch:"保险原则",q:"在法律上被认可的一种关系，这种关系赋予他对该保险标的购买保险的权利。这是属于:",o:["损余","比例分摊","可保权益","受托保管人"],a:2,e:"在法律上被认可、使当事人有权就该保险标的购买保险的关系，称为「可保权益」。损余、比例分摊、受托保管人均非此项定义所指，故答案为可保权益。",src:1,tw:{ch:"保險原則",q:"在法律上被認可的一種關係，這種關係賦予他對該保險標的購買保險的權利。這是屬於:",o:["損餘","比例分攤","可保權益","受託保管人"],e:"在法律上被認可、使當事人有權就該保險標的購買保險的關係，稱為「可保權益」。損餘、比例分攤、受託保管人均非此項定義所指，故答案為可保權益。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项是核保部门的工作范围？",o:["制备核保手册","制备保费指南","制备「拒绝名单」","以上各项皆是"],a:3,e:"核保部门的工作范围包括制备核保手册、制备保费指南及制备「拒绝名单」（黑名单）。三者均为核保部的职责，故为「以上各项皆是」。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項是核保部門的工作範圍？",o:["製備核保手冊","製備保費指南","製備「拒絶名單」","以上各項皆是"],e:"核保部門的工作範圍包括製備核保手冊、製備保費指南及製備「拒絕名單」（黑名單）。三者均為核保部的職責，故為「以上各項皆是」。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项再保险的陈述是正确的?",o:["这是由于现有保单的保障不足，再额外购买另一份的过程","保障为了降低实现风险而做的决定，因为当出现灾害，往往即时需要一大笔流动现金","再保险的费用很高， 所以只用于战争及恐怖袭击","必须透过本港以外的再保险人进行再保险"],a:1,e:"再保险是保险人把已承保的风险部分转嫁给再保险人，以稳定经营、降低实现风险时的现金压力，灾害发生时往往即时需要大量流动现金。它并非客户额外购保，也不只用于战争恐袭或必须经海外安排。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項再保險的陳述是正確的?",o:["這是由於現有保單的保障不足，再額外購買另一份的過程","保障為了降低實現風險而做的決定，因為當出現災害，往往即時需要一大筆流動現金","再保險的費用很高， 所以只用於戰爭及恐怖襲擊","必須透過本港以外的再保險人進行再保險"],e:"再保險是保險人把已承保的風險部分轉嫁給再保險人，以穩定經營、降低實現風險時的現金壓力，災害發生時往往即時需要大量流動現金。它並非客户額外購保，也不只用於戰爭恐襲或必須經海外安排。"}},
{p:1,ch:"保险公司的主要功能",q:"不论由培训及发展部门主理或安排，当考虑培训及教育时:",o:["培训可视为对现在的或未来的工作所作的准备","两者所指的含义相同","永不会由公司内部的职员提供培训","培训的目的主要是为预备公开考试"],a:0,e:"培训可视为对现在或未来的工作所作的准备，故培训与教育并不完全相同，培训也常由公司内部职员提供，目的并非主要为预备公开考试。正确理解是「培训可视为对现在或未来工作所作的准备」。",src:1,tw:{ch:"保險公司的主要功能",q:"不論由培訓及發展部門主理或安排，當考慮培訓及教育時:",o:["培訓可視為對現在的或未來的工作所作的準備","兩者所指的含義相同","永不會由公司內部的職員提供培訓","培訓的目的主要是為預備公開考試"],e:"培訓可視為對現在或未來的工作所作的準備，故培訓與教育並不完全相同，培訓也常由公司內部職員提供，目的並非主要為預備公開考試。正確理解是「培訓可視為對現在或未來工作所作的準備」。"}},
{p:1,ch:"保险公司的主要功能",q:"对很多险种来说，通常在收到保费之前保障已经开始生效，但是，以下哪业务种类几乎总是根据 第一笔保费才能确定合约的存在?",o:["人寿保险","火灾保险","人身意外保险","以上各项皆是"],a:0,e:"人寿保险几乎总是以收到首期保费并发出缴费收据作为合约成立的要件，保障在首期保费缴付前一般不确定生效。火灾、意外险则可在保费收取前按条款先行提供保障，故答案为人寿保险。",src:1,tw:{ch:"保險公司的主要功能",q:"對很多險種來說，通常在收到保費之前保障已經開始生效，但是，以下哪業務 種類幾乎總是根據第一筆保費才能確定合約的存在?",o:["人壽保險","火災保險","人身意外保險","以上各項皆是"],e:"人壽保險幾乎總是以收到首期保費併發出繳費收據作為合約成立的要件，保障在首期保費繳付前一般不確定生效。火災、意外險則可在保費收取前按條款先行提供保障，故答案為人壽保險。"}},
{p:1,ch:"保险公司的主要功能",q:"以下哪项属于核保的范围？ i 评估风险的可保性 ii 厘定可保风险的条款 iii 制备核保手册和保费率指南 iv 制备「拒绝名单 」",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],a:3,e:"核保的范围包括评估风险的可保性、厘定可保风险的条款、制备核保手册和保费率指南，以及制备「拒绝名单」。四项均为核保职能，故答案为 i、ii、iii、iv。",src:1,tw:{ch:"保險公司的主要功能",q:"以下哪項屬於核保的範圍? i 評估風險的可保性 ii 釐定可保風險的條款 iii 製備核保手冊和保費率指南 iv 製備「拒絕名單 」",o:["i, ii","ii, iii","i, ii, iii","i, ii, iii, iv"],e:"核保的範圍包括評估風險的可保性、釐定可保風險的條款、製備核保手冊和保費率指南，以及製備「拒絕名單」。四項均為核保職能，故答案為 i、ii、iii、iv。"}},
{p:1,ch:"香港保险业的结构",q:"「香港保险业联会」的目标:",o:["推广及提升在本港经营业务的保险人及再保险人的共同利益","所有香港以法团形式经营保险业务的保险人总是会员","它提倡会员能力","是保险监管机构承认的「认可保险人及经纪组织」"],a:0,e:"香港保险业联会的目标是推广及提升在本港经营业务的保险人及再保险人的共同利益。并非所有保险人皆是其会员，它也非监管机构承认的「认可保险人及经纪组织」，故答案为共同利益一项。",src:1,tw:{ch:"香港保險業的結構",q:"「香港保險業聯會」的目標:",o:["推廣及提升在本港經營業務的保險人及再保險人的共同利益","所有香港以法團形式經營保險業務的保險人總是會員","它提倡會員能力","是保險監管機構承認的「認可保險人及經紀組織」"],e:"香港保險業聯會的目標是推廣及提升在本港經營業務的保險人及再保險人的共同利益。並非所有保險人皆是其會員，它也非監管機構承認的「認可保險人及經紀組織」，故答案為共同利益一項。"}},
{p:1,ch:"香港保险业的结构",q:"根据《保险业条例》，以下哪项对实缴股本要求的陈述是正确的？ i 专属自保保险人为200 万元 ii 从事长期业务的保险人为1000 万元 iii 经营长期业务及一般保险的保险人为2000 万元 iv 从事意外及汽车方面的法律责任为2000 万元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"根据《保险业条例》对实缴股本的规定，专属自保保险人为200万元、从事长期业务的保险人为1000万元、兼营长期业务及一般保险的保险人为2000万元、从事意外及汽车法定责任者为2000万元。四项陈述均正确。",src:1,tw:{ch:"香港保險業的結構",q:"根據《保險業條例》，以下哪項對實繳股本要求的陳述是正確的？ i 專屬自保保險人為200萬元 ii 從事長期業務的保險人為1000萬元 iii 經營長期業務及一般保險的保險人為2000萬元 iv 從事意外及汽車方面的法律責任為2000萬元",o:["i, ii","i, ii, iii","ii, iii, iv","i, ii, iii, iv"],e:"根據《保險業條例》對實繳股本的規定，專屬自保保險人為200萬元、從事長期業務的保險人為1000萬元、兼營長期業務及一般保險的保險人為2000萬元、從事意外及汽車法定責任者為2000萬元。四項陳述均正確。"}},
{p:1,ch:"香港保险业的结构",q:"在香港，保险人倾向在两种业务的分类方法中选择其一，一种是传统的英式制度，另一种是倾向 美国的制度，在美国的制度下，涵盖范围包括：",o:["清晰界别人寿和非人寿","一般保险包括火险、海上保险、保证和意外保险","一般保险包括火险和意外保险","包括A 和C"],a:0,e:"在美国制度下，保险业务分类的涵盖范围为清晰界别人寿与非人寿两大类。英式制度则分为长期业务与一般业务，故答案为「清晰界别人寿和非人寿」。",src:1,tw:{ch:"香港保險業的結構",q:"在香港，保險人傾向在兩種業務的分類方法中選擇其一，一種是傳統的英式制度，另一種是傾向 美國的制度，在美國的制度下，涵蓋範圍包括：",o:["清晰界別人壽和非人壽","一般保險包括火險、海上保險、保證和意外保險","一般保險包括火險和意外保險","包括A 和C"],e:"在美國製度下，保險業務分類的涵蓋範圍為清晰界別人壽與非人壽兩大類。英式制度則分為長期業務與一般業務，故答案為「清晰界別人壽和非人壽」。"}},
{p:1,ch:"香港保险业的结构",q:"有些保险人根据其业务来源来给其保险业务分类,通常是三类，下列哪一项不是其中一类?",o:["由保险代理人而来","由保险经纪而来","直接从大众人士而来","从已存在的顾客推荐而来的"],a:3,e:"按业务来源分类，保险业务通常分为三类：由保险代理人而来、由保险经纪而来，以及直接从大众人士而来。「从已存在的顾客推荐而来」并非其中一类，故为答案。",src:1,tw:{ch:"香港保險業的結構",q:"有些保險人根據其業務來源來給其保險業務分類,通常是三類，下列哪一項不是其中一類?",o:["由保險代理人而來","由保險經紀而來","直接從大眾人士而來","從已存在的顧客推薦而來的"],e:"按業務來源分類，保險業務通常分為三類：由保險代理人而來、由保險經紀而來，以及直接從大眾人士而來。「從已存在的顧客推薦而來」並非其中一類，故為答案。"}},
{p:1,ch:"保险业的规管架构",q:"根据《2015 年保险公司(修订)条例》，成立保险业监管局的政策目标是：",o:["确保保险业的规管架构与时并进，促进保险业高速增长","确保所有保险监管机构必须维持高水平的偿付准备金，与国际惯常做法看齐","建立一个直接规管保险中介人的制度，以补充现时自律规管制度","确保保险业的规管架构与时并进，促进保险业稳健发展"],a:3,e:"成立保险业监管局的政策目标是确保保险业的规管架构与时并进，促进保险业稳健发展，而非单纯追求高速增长，也非维持高偿付准备金或建立中介人制度的单一目标。故答案为「促进保险业稳健发展」。",src:1,tw:{ch:"保險業的規管架構",q:"根據《2015年保險公司(修訂)條例》，成立保險業監管局的政策目標是：",o:["確保保險業的規管架構與時並進，促進保險業高速增長","確保所有保險監管機構必須維持高水平的償付準備金， 與國際慣常做法看齊","建立一個直接規管保險中介人的制度，以補充現時自律規管制度","確保保險業的規管架構與時並進，促進保險業穩健發展"],e:"成立保險業監管局的政策目標是確保保險業的規管架構與時並進，促進保險業穩健發展，而非單純追求高速增長，也非維持高償付準備金或建立中介人制度的單一目標。故答案為「促進保險業穩健發展」。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》中有关提供建议及销售惯例必须：",o:["浅白语言，明确指引","解释最高诚信的重要性","小心解释任何附带问卷的重要性","以上皆是"],a:3,e:"《承保商专业守则》中对提供建议及销售惯例须使用浅白语言、明确指引，解释最高诚信的重要性，并小心说明任何附带问卷的重要性。三项皆须遵守，故为「以上皆是」。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》中有關提供建議及銷售慣例必須：",o:["淺白語言，明確指引","解釋最高誠信的重要性","小心解釋任何附帶問卷的重要性","以上皆是"],e:"《承保商專業守則》中對提供建議及銷售慣例須使用淺白語言、明確指引，解釋最高誠信的重要性，並小心說明任何附帶問卷的重要性。三項皆須遵守，故為「以上皆是」。"}},
{p:1,ch:"保险业的规管架构",q:"以下哪宗是索偿案件不是保险投诉局的职责?",o:["年金购买人投诉保险公司，以错误的方法计算去派发其退保价值，使他损失利息","保单持有人发现付了过高保费，金额等如超过他真实年龄10 岁。他投诉保险人销售时没有确 认其年龄","保险公司没有在合理时间内向保单持有人作出续保保单条件通知而投诉","保单持有人不满红利派发金额，因为保险人在销售时声称是\"抗通胀保单\""],a:0,e:"保险投诉局主要处理个人保险的索偿争议，而非退保价值计算方法等投资回报/条款性质纠纷，年金退保价值计算的投诉不属其职责。其余涉及销售误导、保费计算、续保通知的投诉均在其受理范围。",src:1,tw:{ch:"保險業的規管架構",q:"以下哪宗是索償案件不是保險投訴局的職責?",o:["年金購買人投訴保險公司，以錯誤的方法計算去派發其退保價值，使他損失利息","保單持有人發現付了過高保費，金額等如超過他真實年齡10 歲。他投訴保險人銷售時沒有確 認其年齡","保險公司沒有在合理時間內向保單持有人作出續保保單條件通知而投訴","保單持有人不滿紅利派發金額，因為保險人在銷售時聲稱是\"抗通脹保單\""],e:"保險投訴局主要處理個人保險的索償爭議，而非退保價值計算方法等投資回報/條款性質糾紛，年金退保價值計算的投訴不屬其職責。其餘涉及銷售誤導、保費計算、續保通知的投訴均在其受理範圍。"}},
{p:1,ch:"保险业的规管架构",q:"独资经营, 合伙和公司, 合伙人, 董事和有联系的公司进行有关规管业务。x%项是他们在公司大会 中拥有最少投票权, x%代表什么 ?",o:["5%","10%","15%","20%"],a:2,e:"根据对「控权人」等受规管人士的界定，独资经营、合伙及公司的合伙人、董事及有联系公司在公司大会中拥有最少15%投票权者即被视为具有控权资格。故x%代表15%。",src:1,tw:{ch:"保險業的規管架構",q:"獨資經營, 合夥和公司, 合夥人, 董事和有聯繫的公司進行有關規管業務。x%項是他們在公司大會 中擁有最少投票權, x%代表什麼 ?",o:["5%","10%","15%","20%"],e:"根據對「控權人」等受規管人士的界定，獨資經營、合夥及公司的合夥人、董事及有聯繫公司在公司大會中擁有最少15%投票權者即被視為具有控權資格。故x%代表15%。"}},
{p:1,ch:"保险业的规管架构",q:"《承保商专业守则》的目的是对核保、索偿产品分析等订立：",o:["销售做法","优良保险做法","投保的优良做法","索偿做法"],a:1,e:"《承保商专业守则》的目的是对核保、索偿、产品分析等订定「优良保险做法」的行业标准。销售做法、投保做法、索偿做法均非其整体目的，故答案为优良保险做法。",src:1,tw:{ch:"保險業的規管架構",q:"《承保商專業守則》的目的是對核保、索償產品分析等訂立：",o:["銷售做法","優良保險做法","投保的優良做法","索償做法"],e:"《承保商專業守則》的目的是對核保、索償、產品分析等訂定「優良保險做法」的行業標準。銷售做法、投保做法、索償做法均非其整體目的，故答案為優良保險做法。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》，以下哪项是正确? i 任何重要事实要以清晰问题题问 ii 于损失时须要披露重要事实是对最高诚信准则的重要性 iii 续保时须要披露重要事实是对最高诚信准则的重要性 iv 小心解释任何附带问卷的重要性",o:["ii, iii","i, iii, iv","i, iv","i, ii, iii, iv"],a:1,e:"根据《承保商专业守则》，任何重要事实要以清晰问题提问、续保时须披露重要事实、并小心解释附带问卷的重要性。三项正确为 i、iii、iv；「于损失时须披露重要事实」并非该守则所指，故排除 ii。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》，以下哪項是正確? i 任何重要事實要以清晰問題題問 ii 於損失時須要披露重要事實是對最高誠信準則的重要性 iii 續保時須要披露重要事實是對最高誠信準則的重要性 iv 小心解釋任何附帶問卷的重要性",o:["ii, iii","i, iii, iv","i, iv","i, ii, iii, iv"],e:"根據《承保商專業守則》，任何重要事實要以清晰問題提問、續保時須披露重要事實、並小心解釋附帶問卷的重要性。三項正確為 i、iii、iv；「於損失時須披露重要事實」並非該守則所指，故排除 ii。"}},
{p:1,ch:"保险业的规管架构",q:"根据《承保商专业守则》，以下哪项适用于索偿时是正确的？",o:["代表保险人之理赔师至少应有经验","代表保险人之理赔师，在任何情况下都应当合理地行事，并具备专业牌照","代表保险人之理赔师至少应有经验，并具备专业牌照","不得委任理赔师以外之第三者"],a:1,e:"根据《承保商专业守则》，代表保险人的理赔师在任何情况下都应当合理地行事，并具备专业牌照。仅有经验或不得委任第三人等表述均不完整，故答案为「合理地行事并具备专业牌照」。",src:1,tw:{ch:"保險業的規管架構",q:"根據《承保商專業守則》，以下哪項適用於索償時是正確的？",o:["代表保險人之理賠師至少應有經驗","代表保險人之理賠師，在任何情況下都應當合理地行事，並具備專業牌照","代表保險人之理賠師至少應有經驗，並具備專業牌照","不得委任理賠師以外之第三者"],e:"根據《承保商專業守則》，代表保險人的理賠師在任何情況下都應當合理地行事，並具備專業牌照。僅有經驗或不得委任第三人等表述均不完整，故答案為「合理地行事並具備專業牌照」。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》， 对哪类别进行监管和监督?",o:["只有保险经纪","只有保险中介人","保险人及中介人","保险人及保险代理人"],a:2,e:"根据《保险业条例》，保监局对保险人及中介人（保险代理与保险经纪）均进行监管和监督。只监管经纪、只监管中介人或只监管代理人等表述均不完整。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》， 對哪類別進行監管和監督?",o:["只有保險經紀","只有保險中介人","保險人及中介人","保險人及保險代理人"],e:"根據《保險業條例》，保監局對保險人及中介人（保險代理與保險經紀）均進行監管和監督。只監管經紀、只監管中介人或只監管代理人等表述均不完整。"}},
{p:1,ch:"保险业的规管架构",q:"根据《保险业条例》，持牌代理保险机构的 参与受规管活动有联络的适当人选。 ________",o:["持牌业务代表(代理人)","控权人","中介人","以上皆是"],a:1,e:"根据《保险业条例》，持牌代理保险机构的控权人须符合「适当人选」要求并经保监局认可。持牌业务代表、中介人并非本题所指的机构控权职位，故答案为控权人。",src:1,tw:{ch:"保險業的規管架構",q:"根據《保險業條例》，持牌代理保險機構的 參與受規管活動有聯絡的適當人選。 ________",o:["持牌業務代表(代理人)","控權人","中介人","以上皆是"],e:"根據《保險業條例》，持牌代理保險機構的控權人須符合「適當人選」要求並經保監局認可。持牌業務代表、中介人並非本題所指的機構控權職位，故答案為控權人。"}},
{p:1,ch:"保险业的规管架构",q:"除了豁免外， 再进行 时必须获得保险业监管局发出的牌照。 ___________",o:["物质活动","金融服务","受规管活动","专业活动"],a:2,e:"除豁免外，进行「受规管活动」必须获得保险业监管局发出的牌照。物质活动、金融服务、专业活动均非保险业条例所指须发牌的规范表述，故答案为受规管活动。",src:1,tw:{ch:"保險業的規管架構",q:"除了豁免外， 再進行 時必須獲得保險業監管局發出的牌照。 ___________",o:["物質活動","金融服務","受規管活動","專業活動"],e:"除豁免外，進行「受規管活動」必須獲得保險業監管局發出的牌照。物質活動、金融服務、專業活動均非保險業條例所指鬚髮牌的規範表述，故答案為受規管活動。"}},
{p:1,ch:"保险业的规管架构",q:"下列那项有关保险业监管局的说法是正确的？",o:["透过发牌监管保险人","提高保单持有人对保险产品的了解","于1997 年成立《承保商专业守则》","保险业监管局成立由香港保险业联会"],a:1,e:"保险业监管局负责发牌与监管，并提高保单持有人对保险产品的了解。它并非由香港保险业联会成立，也不只透过发牌监管保险人，故正确说法为「提高保单持有人对保险产品的了解」。",src:1,tw:{ch:"保險業的規管架構",q:"下列那項有關保險業監管局的說法是正確的？",o:["透過發牌監管保險人","提高保單持有人對保險產品的了解","於1997 年成立《承保商專業守則》","保險業監管局成立由香港保險業聯會"],e:"保險業監管局負責發牌與監管，並提高保單持有人對保險產品的瞭解。它並非由香港保險業聯會成立，也不只透過發牌監管保險人，故正確說法為「提高保單持有人對保險產品的瞭解」。"}},
{p:1,ch:"保险业的规管架构",q:"根据保险业条例，以下哪项必须获得保险业监管局认可才能委任?",o:["获授权保险人的财务经理及财务人员","获授权保险人的董事","理赔主任","以上皆是"],a:1,e:"根据《保险业条例》，获授权保险人的董事（属控权职位）委任前须获保险业监管局认可其为适当人选。财务经理、财务人员及理赔主任不在须预先认可之列，故答案为董事。",src:1,tw:{ch:"保險業的規管架構",q:"根據保險業條例，以下哪項必須獲得保險業監管局認可才能委任?",o:["獲授權保險人的財務經理及財務人員","獲授權保險人的董事","理賠主任","以上皆是"],e:"根據《保險業條例》，獲授權保險人的董事（屬控權職位）委任前須獲保險業監管局認可其為適當人選。財務經理、財務人員及理賠主任不在須預先認可之列，故答案為董事。"}},
{p:1,ch:"职业道德及其他有关问题",q:"根据《防止贿赂条例》，以下那项是雇员必须遵守或应避免的行为？",o:["雇员在处理雇主的业务或事务时，不得创业","雇员在处理雇主的业务或事务时，不得在与雇主关系终止五年内创业","雇员在处理雇主的业务或事务时，不得谋取或收受利益","雇员在处理雇主的业务或事务时，不得委任分代理人"],a:2,e:"根据《防止贿赂条例》，雇员在处理雇主的业务或事务时，未得雇主许可不得索取或接受利益，即「不得谋取或收受利益」。创业限制及分代理人委任并非该条例对雇员的直接规定。",src:1,tw:{ch:"職業道德及其他有關問題",q:"根據《防止賄賂條例》，以下那項是僱員必須遵守或應避免的行為？",o:["僱員在處理僱主的業務或事務時，不得創業","僱員在處理僱主的業務或事務時，不得在與僱主關係終止五年內創業","僱員在處理僱主的業務或事務時，不得謀取或收受利益","僱員在處理僱主的業務或事務時，不得委任分代理人"],e:"根據《防止賄賂條例》，僱員在處理僱主的業務或事務時，未得僱主許可不得索取或接受利益，即「不得謀取或收受利益」。創業限制及分代理人委任並非該條例對僱員的直接規定。"}},
{p:1,ch:"职业道德及其他有关问题",q:"以下那些/哪项关于《个人资料(私隐)条例》的约束是正确的？ i 人手操作资料 ii 自动化操作资料 iii 公营部门而已 iv 只适用于香港居民及香港注册商号的人",o:["i, ii","iii, iv","ii, iii, iv","i, ii, iii, iv"],a:0,e:"《个人资料（私隐）条例》同时规管人手操作及自动化操作的个人资料，适用于公营及私营机构，亦不限香港居民。故正确两项为 i、ii。",src:1,tw:{ch:"職業道德及其他有關問題",q:"以下那些/哪項關於《個人資料(私隱)條例》的約束是正確的？ i 人手操作資料 ii 自動化操作資料 iii 公營部門而已 iv 只適用於香港居民及香港註冊商號的人",o:["i, ii","iii, iv","ii, iii, iv","i, ii, iii, iv"],e:"《個人資料（私隱）條例》同時規管人手操作及自動化操作的個人資料，適用於公營及私營機構，亦不限香港居民。故正確兩項為 i、ii。"}},
{p:1,ch:"职业道德及其他有关问题",q:"香港成立的平等机会委员会负责执行消除各种歧视但不包括以下哪项或哪些？",o:["性别","年龄","婚姻状况","以上各项皆是"],a:1,e:"平等机会委员会负责执行消除性别、婚姻状况、残疾、家庭岗位、种族等歧视的条例，但年龄歧视不在其现行法定执行范围之内。故答案为「年龄」。",src:1,tw:{ch:"職業道德及其他有關問題",q:"香港成立的平等機會委員會負責執行消除各種歧視但不包括以下哪項或哪些？",o:["性別","年齡","婚姻狀況","以上各項皆是"],e:"平等機會委員會負責執行消除性別、婚姻狀況、殘疾、家庭崗位、種族等歧視的條例，但年齡歧視不在其現行法定執行範圍之內。故答案為「年齡」。"}},
{p:1,ch:"职业道德及其他有关问题",q:"《个人资料(私隐)条例》，保护资料第一原则:",o:["收集个人资料的目的及方式","个人资料的准确性及保留期限","个人资料的保安","个人资料的使用"],a:0,e:"《个人资料（私隐）条例》保障资料第一原则规定个人资料须以合法及公平方式收集，并须告知收集目的及用途，即关乎「收集个人资料的目的及方式」。故答案为收集目的及方式。",src:1,tw:{ch:"職業道德及其他有關問題",q:"《個人資料(私隱)條例》，保護資料第一原則:",o:["收集個人資料的目的及方式","個人資料的準確性及保留期限","個人資料的保安","個人資料的使用"],e:"《個人資料（私隱）條例》保障資料第一原則規定個人資料須以合法及公平方式收集，並須告知收集目的及用途，即關乎「收集個人資料的目的及方式」。故答案為收集目的及方式。"}},
{p:1,ch:"职业道德及其他有关问题",q:"保险业监管局发出打击《洗钱及恐怖分子资金筹集条例》指引，要求金融机构设立打击洗钱／恐 怖分子资金筹集制度，所制订的管控措施应涵盖的范畴包括:",o:["委任一名洗钱报告主任","行驶货币","委任一名法律主任","建立情报组"],a:0,e:"保险业监管局的打击洗钱指引要求金融机构设立打击洗钱及恐怖分子资金筹集制度，其管控措施包括委任一名洗钱报告主任。行使货币、法律主任、情报组均非该规定要求，故答案为委任洗钱报告主任。",src:1,tw:{ch:"職業道德及其他有關問題",q:"保險業監管局發出打擊《洗錢及恐怖分子資金籌集條例》指引，要求金融機構設立打擊洗錢／恐 怖分子資金籌集制度，所制訂的管控措施應涵蓋的範疇包括:",o:["委任一名洗錢報告主任","行駛貨幣","委任一名法律主任","建立情報組"],e:"保險業監管局的打擊洗錢指引要求金融機構設立打擊洗錢及恐怖分子資金籌集制度，其管控措施包括委任一名洗錢報告主任。行使貨幣、法律主任、情報組均非該規定要求，故答案為委任洗錢報告主任。"}},
{p:3,ch:"人寿保险简介",q:"人寿保险最初时及最基本的目的是：",o:["为死亡(尤其是早逝) 提供一笔金钱","为尚余生命的人士提供一笔金钱","为期满的人士提供一笔金钱","储蓄用途"],a:0,e:"人寿保险最初及最基本的目的是在受保人死亡（尤其是早逝）时提供一笔金钱，保障其家属的经济需要。为尚余生命、期满或储蓄用途均是后来发展出的功能，非最初基本目的。",src:1,tw:{ch:"人壽保險簡介",q:"人壽保險最初時及最基本的目的是：",o:["為死亡(尤其是早逝) 提供一筆金錢","為尚餘生命的人士提供一筆金錢","為期滿的人士提供一筆金錢","儲蓄用途"],e:"人壽保險最初及最基本的目的是在受保人死亡（尤其是早逝）時提供一筆金錢，保障其家屬的經濟需要。為尚餘生命、期滿或儲蓄用途均是後來發展出的功能，非最初基本目的。"}},
{p:3,ch:"人寿保险简介",q:"在香港，在血缘关系的家庭成员不存在可保权益，以下哪个没有可保权益？",o:["17 岁的子女","17 岁的被监护人","17 岁的妹妹","以上皆否"],a:2,e:"在香港，父母对其未成年子女、监护人对被监护人因抚养关系具有可保权益；而兄弟姐妹之间一般不存在金钱权益，故对17岁妹妹无可保权益。17岁子女与被监护人不属此列。",src:1,tw:{ch:"人壽保險簡介",q:"在香港，在血緣關係的家庭成員不存在可保權益，以下哪個沒有可保權益？",o:["17歲的子女","17歲的被監護人","17歲的妹妹","以上皆否"],e:"在香港，父母對其未成年子女、監護人對被監護人因撫養關係具有可保權益；而兄弟姐妹之間一般不存在金錢權益，故對17歲妹妹無可保權益。17歲子女與被監護人不屬此列。"}},
{p:3,ch:"人寿保险简介",q:"以下哪项有关寿险保单的转让与可保权益的法律规定的关系的陈述是正确的？",o:["保单所有人一般不能将寿险合约转让予缺乏可保权益的第三者","保单所有人只能透过另一合约把其寿险合约转让予第三者","保单所有人一般可以把正当地安排的寿险合约转让予第三者， 即使该第三者对受保生命缺乏可保权益","假设一名准保单所有人意图购买一份保单保某人的生命，但他对后者的 生命缺乏可保权益，他于是安排后者购买保单保自身的生命，再转让给他， 这么一种保单于转让给前者后便告无效"],a:2,e:"人寿保险是利益保单而非弥偿保单，正当地安排并已生效的寿险合约，保单所有人一般可转让予任何第三者，即使该第三者对受保生命缺乏可保权益。故答案为「可转让予缺乏可保权益的第三者」。",src:1,tw:{ch:"人壽保險簡介",q:"以下哪項有關壽險保單的轉讓與可保權益的法律規定的關係的陳述是正確的？",o:["保單所有人一般不能將壽險合約轉讓予缺乏可保權益的第三者","保單所有人只能透過另一合約把其壽險合約轉讓予第三者","保單所有人一般可以把正當地安排的壽險合約轉讓予第三者， 即使該第三者對受保生命缺乏可保權益","假設一名準保單所有人意圖購買一份保單保某人的生命，但他對後者的 生命缺乏可保權益，他於是安排後者購買保單保自身的生命，再轉讓給他， 這麼一種保單於轉讓給前者後便告無效"],e:"人壽保險是利益保單而非彌償保單，正當地安排並已生效的壽險合約，保單所有人一般可轉讓予任何第三者，即使該第三者對受保生命缺乏可保權益。故答案為「可轉讓予缺乏可保權益的第三者」。"}},
{p:3,ch:"人寿保险简介",q:"最高诚信是用于所有保险种类，在该原则下，以下哪项是「重要事实」的正确 定义？",o:["几乎所有人寿保险对「重要事实」的法律定义作出修改","人寿保险与非人寿保险对「重要事实」有不同的定义","「重要事实」是影响审慎的核保人就一项特定风险承保与否的事实","人寿保险的不可异议条款对「重要事实」有全面的解释"],a:2,e:"在最高诚信原则下，「重要事实」指会影响一名审慎的核保人就特定风险决定承保与否的事实。故正确定义为「影响审慎的核保人就一项特定风险承保与否的事实」。",src:1,tw:{ch:"人壽保險簡介",q:"最高誠信是用於所有保險種類，在該原則下，以下哪項是「重要事實」的正確定義？",o:["幾乎所有人壽保險對「重要事實」的法律定義作出修改","人壽保險與非人壽保險對「重要事實」有不同的定義","「重要事實」是影響審慎的核保人就一項特定風險承保與否的事實","人壽保險的不可異議條款對「重要事實」有全面的解釋"],e:"在最高誠信原則下，「重要事實」指會影響一名審慎的核保人就特定風險決定承保與否的事實。故正確定義為「影響審慎的核保人就一項特定風險承保與否的事實」。"}},
{p:3,ch:"人寿保险简介",q:"根据最高诚信的保险原则，以下哪项是重要事实的正确描述？",o:["与实际物件(财产)保险的事实","向保险人披露的非重要事实","会影响一名审慎的核保人订定保费或决定是否承担风险方面的事实","可能会影响一名审慎的核保人订定保费或决定是否承担风险方面的事实"],a:2,e:"「重要事实」是会影响一名审慎的核保人订定保费或决定是否承担风险的事实（而非「可能会影响」这类不确定表述，也非指财产实物或已披露的非重要事实）。故答案为「会影响核保人订定保费或决定承担风险的事实」。",src:1,tw:{ch:"人壽保險簡介",q:"根據最高誠信的保險原則，以下哪項是重要事實的正確描述？",o:["與實際物件(財產)保險的事實","向保險人披露的非重要事實","會影響一名審慎的核保人訂定保費或決定是否承擔風險方面的事實","可能會影響一名審慎的核保人訂定保費或決定是否承擔風險方面的事實"],e:"「重要事實」是會影響一名審慎的核保人訂定保費或決定是否承擔風險的事實（而非「可能會影響」這類不確定表述，也非指財產實物或已披露的非重要事實）。故答案為「會影響核保人訂定保費或決定承擔風險的事實」。"}},
{p:3,ch:"人寿保险简介",q:"制定人寿保险保费率除了三项技术因素外，以下哪些项目同样影响保费率？ i 同业的竞争 ii 公众健康的突然或非预期的转变 iii 保险人为提高市场占有率的政策上转变 iv 社会经济环境，尤其在经济衰退时",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],a:3,e:"决定寿险保费率除死亡率、利率、费用三项技术因素外，同业的竞争、公众健康的意外转变、保险人为提高市场占有率的政策转变及社会经济环境（尤其经济衰退）均会影响保费率。四项皆正确。",src:1,tw:{ch:"人壽保險簡介",q:"制定人壽保險保費率除了三項技術因素外，以下哪些項目同樣影響保費率？ i 同業的競爭 ii 公眾健康的突然或非預期的轉變 iii 保險人為提高市場佔有率的政策上轉變 iv 社會經濟環境，尤其在經濟衰退時",o:["i, ii, iii","i, ii, iv","i, iii, iv","i, ii, iii, iv"],e:"決定壽險保費率除死亡率、利率、費用三項技術因素外，同業的競爭、公眾健康的意外轉變、保險人為提高市場佔有率的政策轉變及社會經濟環境（尤其經濟衰退）均會影響保費率。四項皆正確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一个人的寿险需要不会增加或减少，在一段指定时间之后就不会再有需要，如 果以保险成本为最大的考虑因素，以下哪种寿险最不可取？",o:["定额定期寿险","可转换定期寿险","分红储蓄寿险","不分红储蓄寿险"],a:2,e:"寿险需要固定且期满后不再需要、以成本为主要考虑时，应选保费经济的定期寿险。分红储蓄寿险保费最高、大部分用于储蓄与分红，纯保障成本效益最差，故最不可取。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一個人的壽險需要不會增加或減少，在一段指定時間之後就不會再有需要，如果以保險成本為最 大的考慮因素，以下哪種壽險最不可取？",o:["定額定期壽險","可轉換定期壽險","分紅儲蓄壽險","不分紅儲蓄壽險"],e:"壽險需要固定且期滿後不再需要、以成本為主要考慮時，應選保費經濟的定期壽險。分紅儲蓄壽險保費最高、大部分用於儲蓄與分紅，純保障成本效益最差，故最不可取。"}},
{p:3,ch:"人寿保险及年金的种类",q:"团体保险有另外的名称，叫做：",o:["雇主团体保险合约","总团体保险合约","单一雇主保险合约","总雇主保险合约"],a:1,e:"团体保险由一份总保单（master policy）承保整组成员，故另有名称「总团体保险合约」。雇主团体保险合约、单一/总雇主角度的表述均非其正式别名。",src:1,tw:{ch:"人壽保險及年金的種類",q:"團體保險有另外的名稱，叫做：",o:["僱主團體保險合約","總團體保險合約","單一僱主保險合約","總僱主保險合約"],e:"團體保險由一份總保單（master policy）承保整組成員，故另有名稱「總團體保險合約」。僱主團體保險合約、單一/總僱主角度的表述均非其正式別名。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在安排人寿保险的过程中，中介人必须向潜在保单所有人提出两个重要的基本 问题，第一个是要确定该名人士可负担的保费，第二个是：",o:["向该中介人缴付的佣金金额","询问投保人属已婚或单身","询问是否按每年或每月缴交保费","询问投购该份寿险的基本目的及意图"],a:3,e:"安排人寿保险时中介人须提出的两个基本问题：一是确定可负担的保费，二是询问投购该份寿险的基本目的及意图。佣金、婚姻状况及缴付方式均非第二个核心问题。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在安排人壽保險的過程中，中介人必須向潛在保單所有人提出兩個重要的基本問題，第一個是要 確定該名人士可負擔的保費，第二個是：",o:["向該中介人繳付的佣金金額","詢問投保人屬已婚或單身","詢問是否按每年或每月繳交保費","詢問投購該份壽險的基本目的及意圖"],e:"安排人壽保險時中介人須提出的兩個基本問題：一是確定可負擔的保費，二是詢問投購該份壽險的基本目的及意圖。佣金、婚姻狀況及繳付方式均非第二個核心問題。"}},
{p:3,ch:"人寿保险及年金的种类",q:"递减定期寿险指：",o:["利益每年递减","保险费每年递减","利益与保险费每年递减","付给代理人的佣金每年递减"],a:0,e:"递减定期寿险指保险利益按年递减（通常配合同额递减的债务如按揭），而保险费未必递减。故正确定义为「利益每年递减」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"遞減定期壽險指：",o:["利益每年遞減","保險費每年遞減","利益與保險費每年遞減","付給代理人的佣金每年遞減"],e:"遞減定期壽險指保險利益按年遞減（通常配合同額遞減的債務如按揭），而保險費未必遞減。故正確定義為「利益每年遞減」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪类保险为递减定期寿险的例子？ i 信用寿险 ii 按揭弥偿保险 iii 抵押赎回保险 iv 家庭收入寿险",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],a:3,e:"递减定期寿险的典型例子包括信用寿险、抵押赎回保险及家庭收入寿险（其保障额随时间递减）。按揭弥偿保险属财产保险，非递减定期寿险，故正确为 i、iii、iv。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪類保險為遞減定期壽險的例子？ i 信用壽險 ii 按揭彌償保險 iii 抵押贖回保險 iv 家庭收入壽險",o:["i, ii, iii","i, ii, iv","ii, iii, iv","i, iii, iv"],e:"遞減定期壽險的典型例子包括信用壽險、抵押贖回保險及家庭收入壽險（其保障額隨時間遞減）。按揭彌償保險屬財產保險，非遞減定期壽險，故正確為 i、iii、iv。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一种寿险计划只会于受保生命在特定期间内死亡时作出赔偿，而死亡时间并不 影响赔偿金额。这种计划是：",o:["终身寿险","定额定期寿险","定期保障计划","不变动保险"],a:1,e:"定额定期寿险只在特定保险期间内于受保人死亡时作出赔偿，且不论死亡发生于期内何时，赔偿金额固定不变。终身寿险无固定期满，定期保障计划与不变动保险表述不准确。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一種壽險計劃只會於受保生命在特定期間內死亡時作出賠償，而死亡時間並不影響賠償金額。這 種計劃是：",o:["終身壽險","定額定期壽險","定期保障計劃","不變動保險"],e:"定額定期壽險只在特定保險期間內於受保人死亡時作出賠償，且不論死亡發生於期內何時，賠償金額固定不變。終身壽險無固定期滿，定期保障計劃與不變動保險表述不準確。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一份保单被描述为连续缴费终身寿险，它含有下列哪项描述？",o:["只需缴交一份保费","整段保险期间保费固定","终身缴付保费","终身缴付保费即使受保生命已经死亡"],a:2,e:"「连续缴费终身寿险」指保费须终身缴付，直至受保人死亡为止，期间保额不变。故其描述为「终身缴付保费」，而非只缴一份、保费固定或死后仍缴。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一份保單被描述為連續繳費終身壽險，它含有下列哪項描述？",o:["只需繳交一份保費","整段保險期間保費固定","終身繳付保費","終身繳付保費即使受保生命已經死亡"],e:"「連續繳費終身壽險」指保費須終身繳付，直至受保人死亡為止，期間保額不變。故其描述為「終身繳付保費」，而非只繳一份、保費固定或死後仍繳。"}},
{p:3,ch:"人寿保险及年金的种类",q:"在万用寿险中，保单和年报分别并且独立向保单所有人披露合约的三个定价因 素，包括保障的纯成本，利息和开支。这样做的根据是：",o:["提高透明度","「分别列示各定价因素」的定价","保险人热衷推介该类产品","因为法律的要求"],a:1,e:"万用寿险向保单所有人分别及独立披露合约的三个定价因素（保障纯成本、利息、开支），其根据是「分别列示各定价因素」的定价方法，以提高透明度，而非因法律强制或保险人推介。",src:1,tw:{ch:"人壽保險及年金的種類",q:"在萬用壽險中，保單和年報分別並且獨立向保單所有人披露合約的三個定價因素，包括保障的純 成本，利息和開支。這樣做的根據是：",o:["提高透明度","「分別列示各定價因素」的定價","保險人熱衷推介該類產品","因為法律的要求"],e:"萬用壽險向保單所有人分別及獨立披露合約的三個定價因素（保障純成本、利息、開支），其根據是「分別列示各定價因素」的定價方法，以提高透明度，而非因法律強制或保險人推介。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪项不属于万用寿险的特色？",o:["灵活保费","可调整保险利益","向保单持有人披露有关的开支","自动按年增加保额"],a:3,e:"万用寿险的特色包括灵活保费、可调整保险利益及向保单持有人披露有关开支。「自动按年增加保额」并非万用寿险特色，故为答案。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪項不屬於萬用壽險的特色？",o:["靈活保費","可調整保險利益","向保單持有人披露有關的開支","自動按年增加保額"],e:"萬用壽險的特色包括靈活保費、可調整保險利益及向保單持有人披露有關開支。「自動按年增加保額」並非萬用壽險特色，故為答案。"}},
{p:3,ch:"人寿保险及年金的种类",q:"万用寿险的保单所有人，每年均会收到一份说明保单状况的年报，内容不包 括：",o:["选定的死亡保险金选择","已加入现金价值的保证利息及额外利息","已扣除的保险纯成本","基金价格"],a:3,e:"万用寿险年报会列示选定的死亡保险金选择、已加入的保证及额外利息、已扣除的纯保险成本等。「基金价格」是投资相连保单的内容，万用寿险无基金单位，故年报不包括基金价格。",src:1,tw:{ch:"人壽保險及年金的種類",q:"萬用壽險的保單所有人，每年均會收到一份說明保單狀況的年報，內容不包括：",o:["選定的死亡保險金選擇","已加入現金價值的保證利息及額外利息","已扣除的保險純成本","基金價格"],e:"萬用壽險年報會列示選定的死亡保險金選擇、已加入的保證及額外利息、已扣除的純保險成本等。「基金價格」是投資相連保單的內容，萬用壽險無基金單位，故年報不包括基金價格。"}},
{p:3,ch:"人寿保险及年金的种类",q:"香港年金计划是由以下哪个公司推出的？",o:["香港金融管理局","香港按揭证券有限公司","香港证监会","以上都不是"],a:1,e:"香港年金计划（公共年金计划）由香港按揭证券有限公司推出，并非由金融管理局或证监会推出。故答案为香港按揭证券有限公司。",src:1,tw:{ch:"人壽保險及年金的種類",q:"香港年金計劃是由以下哪個公司推出的？",o:["香港金融管理局","香港按揭證券有限公司","香港證監會","以上都不是"],e:"香港年金計劃（公共年金計劃）由香港按揭證券有限公司推出，並非由金融管理局或證監會推出。故答案為香港按揭證券有限公司。"}},
{p:3,ch:"人寿保险及年金的种类",q:"下列哪项正确描述团体保险计划？",o:["团体保单和个人保单核保过程基本是一样的","一般来说团体保险保单核保过程中会要求详细的个人健康资料","一般来说团体保险保单核保过程中不会要求详细的个人健康资料","团体保险核保时会按各受保成员的情况分别计算保费"],a:2,e:"团体保险以团体为单位承保，核保过程一般不要求每位成员提供详细的个人健康资料，而以团体的整体特征及规模评估风险并计算保费。故答案为「不会要求详细的个人健康资料」。",src:1,tw:{ch:"人壽保險及年金的種類",q:"下列哪項正確描述團體保險計劃？",o:["團體保單和個人保單核保過程基本是一樣的","一般來說團體保險保單核保過程中會要求詳細的個人健康資料","一般來說團體保險保單核保過程中不會要求詳細的個人健康資料","團體保險核保時會按各受保成員的情況分別計算保費"],e:"團體保險以團體為單位承保，核保過程一般不要求每位成員提供詳細的個人健康資料，而以團體的整體特徵及規模評估風險並計算保費。故答案為「不會要求詳細的個人健康資料」。"}},
{p:3,ch:"人寿保险及年金的种类",q:"以下哪种保险类型的保单价值与投资表现挂钩？",o:["终身寿险","投资相连⾧期保险","储蓄寿险","定额定期寿险"],a:1,e:"投资相连长期保险的保单价值直接与所投资基金的表现为挂钩，随市场波动。终身寿险、储蓄寿险、定额定期寿险的价值或利益均不由投资表现决定，故答案为投资相连长期保险。",src:1,tw:{ch:"人壽保險及年金的種類",q:"以下哪種保險類型的保單價值與投資表現掛鈎？",o:["終身壽險","投資相連⾧期保險","儲蓄壽險","定額定期壽險"],e:"投資相連長期保險的保單價值直接與所投資基金的表現為掛鈎，隨市場波動。終身壽險、儲蓄壽險、定額定期壽險的價值或利益均不由投資表現決定，故答案為投資相連長期保險。"}},
{p:3,ch:"人寿保险及年金的种类",q:"一个人的寿险需要不会增加或减少，大多数情况下没有出现索偿，属于以下哪 种寿险？",o:["定额定期寿险","可转换定期寿险","分红储蓄寿险","不分红储蓄寿险"],a:0,e:"定额定期寿险的保障需要固定不变、多数情况下没有索偿（因期内未必死亡），属纯粹保障型的定期寿险。分红/不分红储蓄寿险有储蓄成分，可转换定期亦不符题意。",src:1,tw:{ch:"人壽保險及年金的種類",q:"一個人的壽險需要不會增加或減少，大多數情況下沒有出現索償，屬於以下哪種壽險？",o:["定額定期壽險","可轉換定期壽險","分紅儲蓄壽險","不分紅儲蓄壽險"],e:"定額定期壽險的保障需要固定不變、多數情況下沒有索償（因期內未必死亡），屬純粹保障型的定期壽險。分紅/不分紅儲蓄壽險有儲蓄成分，可轉換定期亦不符題意。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项是「豁免保费附约」是正确描述？",o:["保单所有人完全残疾，残疾期间豁免保费","当保单生效一段期间后保单所有人完全残疾；残疾期间豁免保费","当保单所有人失业时豁免保单所有人之保费","当市场上竞争对手保费低廉，保险人便退还保费"],a:0,e:"「豁免保费附约」规定当保单所有人完全残疾时，残疾期间的保费获豁免，保障继续有效。失业、竞争减价退费等均非其触发条件，故答案为「完全残疾期间豁免保费」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項是「豁免保費附約」是正確描述？",o:["保單所有人完全殘疾，殘疾期間豁免保費","當保單生效一段期間後保單所有人完全殘疾；殘疾期間豁免保費","當保單所有人失業時豁免保單所有人之保費","當市場上競爭對手保費低廉，保險人便退還保費"],e:"「豁免保費附約」規定當保單所有人完全殘疾時，殘疾期間的保費獲豁免，保障繼續有效。失業、競爭減價退費等均非其觸發條件，故答案為「完全殘疾期間豁免保費」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡保险附约又名双倍赔偿利益，但其英文名称(Double Indemnity",o:["有些意外引致死亡的原因是除外责任","Indemnity(弥偿)通常出现在财产保险上","Indemnity 是一项弥偿，而该保单是利益保单","自然死亡是不保的"],a:2,e:"意外死亡保险附约又称「Double Indemnity」的英文名称不贴切，因为 Indemnity（弥偿）含义是补偿实际损失，通常用于财产保险；而人寿保单是利益保单，赔付固定利益而非弥偿，故名称用词不当。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡保險附約又名雙倍賠償利益，但其英文名稱(Double Indemnity",o:["有些意外引致死亡的原因是除外責任","Indemnity(彌償)通常出現在財產保險上","Indemnity 是一項彌償，而該保單是利益保單","自然死亡是不保的"],e:"意外死亡保險附約又稱「Double Indemnity」的英文名稱不貼切，因為 Indemnity（彌償）含義是補償實際損失，通常用於財產保險；而人壽保單是利益保單，賠付固定利益而非彌償，故名稱用詞不當。"}},
{p:3,ch:"保险利益附约及其他产品",q:"残疾收入保险利益附约有一个等候期，该等候期：",o:["总是3 个月","1 个月至6 个月不等","持续时间不少于6 个月","由3 个月至6 个月不等 (跟豁免保费附约一样)"],a:1,e:"残疾收入保险利益附约设有等候期，期间内残疾不获给付。该等候期并非固定，通常由1个月至6个月不等，故答案为「1个月至6个月不等」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"殘疾收入保險利益附約有一個等候期，該等候期：",o:["總是3個月","1個月至6個月不等","持續時間不少於6個月","由3個月至6個月不等 (跟豁免保費附約一樣)"],e:"殘疾收入保險利益附約設有等候期，期間內殘疾不獲給付。該等候期並非固定，通常由1個月至6個月不等，故答案為「1個月至6個月不等」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"以下哪项或哪些是意外死亡保险利益的除外责任？",o:["传染病引致的情况","自杀不遂导致伤残","于入屋犯法时不幸失足堕下受伤","以上都包括"],a:3,e:"意外死亡保险利益的除外责任包括传染病引致的情况、自杀不遂导致的伤残，以及参与非法活动（如入屋犯法）时受伤。三者均为除外责任，故「以上都包括」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"以下哪項或哪些是意外死亡保險利益的除外責任？",o:["傳染病引致的情況","自殺不遂導致傷殘","於入屋犯法時不幸失足墮下受傷","以上都包括"],e:"意外死亡保險利益的除外責任包括傳染病引致的情況、自殺不遂導致的傷殘，以及參與非法活動（如入屋犯法）時受傷。三者均為除外責任，故「以上都包括」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡及丧失肢体附约受保生命在意外事故中可得到一笔与死亡保险金相等 的赔偿金，经修改后受保人可收取50%保险金若意外事故导致：",o:["丧失一腿","丧失一目","丧失一手","以上皆是"],a:3,e:"意外死亡及丧失肢体附约在受保人因意外丧失一腿、一目或一手（属单一肢体/器官损失）时，可获50%保险金。三者皆符合，故为「以上皆是」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡及喪失肢體附約受保生命在意外事故中可得到一筆與死亡保險金相等的賠償金，經修改後受保 人可收取50%保險金若意外事故導致：",o:["喪失一腿","喪失一目","喪失一手","以上皆是"],e:"意外死亡及喪失肢體附約在受保人因意外喪失一腿、一目或一手（屬單一肢體/器官損失）時，可獲50%保險金。三者皆符合，故為「以上皆是」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"在同一次意外事故中，被保险人丧失两个肢体，之后引致死亡，如寿险保单附 加意外死亡及丧失肢体附约，保险人会如何作出赔付？",o:["只是保额而已","保额的两倍","保额的三倍","保额的四倍"],a:1,e:"同一意外事故中丧失两个肢体，按附约丧失肢体共赔保额的一倍（各50%），其后又引致死亡，再按死亡利益赔一倍，合计共保额的两倍。故保险人赔付保额两倍。",src:1,tw:{ch:"保險利益附約及其他產品",q:"在同一次意外事故中，被保險人喪失兩個肢體，之後引致死亡，如壽險保單附加意外死亡及喪失肢體附 約，保險人會如何作出賠付？",o:["只是保額而已","保額的兩倍","保額的三倍","保額的四倍"],e:"同一意外事故中喪失兩個肢體，按附約喪失肢體共賠保額的一倍（各50%），其後又引致死亡，再按死亡利益賠一倍，合計共保額的兩倍。故保險人賠付保額兩倍。"}},
{p:3,ch:"保险利益附约及其他产品",q:"意外死亡保险附约又双倍赔偿利益，但其英文名称Double indemnity",o:["有些意外引致的原因是除外责任","Indemnity(弥偿)通常出现在财产保险上","Indemnity 是一项弥偿，而该保保额是利益保单","自然死亡是不保的"],a:2,e:"意外死亡保险附约称为「Double Indemnity」其实用词不当，因为 Indemnity（弥偿）是对实际损失的补偿，通常用于财产险；而人寿保单是利益保单，给付固定利益而非弥偿，因此名称不贴切。",src:1,tw:{ch:"保險利益附約及其他產品",q:"意外死亡保險附約又雙倍賠償利益，但其英文名稱Double indemnity",o:["有些意外引致的原因是除外責任","Indemnity(彌償)通常出現在財產保險上","Indemnity 是一項彌償，而該保保額是利益保單","自然死亡是不保的"],e:"意外死亡保險附約稱為「Double Indemnity」其實用詞不當，因為 Indemnity（彌償）是對實際損失的補償，通常用於財產險；而人壽保單是利益保單，給付固定利益而非彌償，因此名稱不貼切。"}},
{p:3,ch:"保险利益附约及其他产品",q:"附加于人寿保险的「其他意外保险利益」之利益给付表，包括：",o:["死亡而已","死亡及丧失视力","死亡、丧失视力及丧失肢体","上述及各种只较轻的伤残"],a:3,e:"附加于人寿保险的「其他意外保险利益」给付表涵盖死亡、丧失视力、丧失肢体，以及各种较轻的伤残等不同严重程度，给付也不同。故答案为「上述及各种只较轻的伤残」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"附加於人壽保險的「其他意外保險利益」之利益給付表，包括：",o:["死亡而已","死亡及喪失視力","死亡、喪失視力及喪失肢體","上述及各種只較輕的傷殘"],e:"附加於人壽保險的「其他意外保險利益」給付表涵蓋死亡、喪失視力、喪失肢體，以及各種較輕的傷殘等不同嚴重程度，給付也不同。故答案為「上述及各種只較輕的傷殘」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"有部份保险人会在保单中加入条文处理：受保保单所有人根据保证可保选择附 约行使权利购买增额保险前死亡的情况。有关处理的形式是：",o:["在有权行使可保权利益期间，自动提供定期寿险","自动将不分红保单转为分红保单","在有权行使可保权利益前死亡，便可得双倍补偿利益","自动增加可允许最大的保额，并在日后享有可以取消的权利"],a:0,e:"保证可保选择附约允许保单所有人在指定日期增买保险而无须可保性证明。为处理在行使权利前死亡的情况，保险人会在有权行使期间自动提供定期寿险作为过渡保障，故答案为自动提供定期寿险。",src:1,tw:{ch:"保險利益附約及其他產品",q:"有部份保險人會在保單中加入條文處理：受保保單所有人根據保證可保選擇附約行使權利購買增額保險 前死亡的情況。有關處理的形式是：",o:["在有權行使可保權利益期間，自動提供定期壽險","自動將不分紅保單轉為分紅保單","在有權行使可保權利益前死亡，便可得雙倍補償利益","自動增加可允許最大的保額，並在日後享有可以取消的權利"],e:"保證可保選擇附約允許保單所有人在指定日期增買保險而無須可保性證明。為處理在行使權利前死亡的情況，保險人會在有權行使期間自動提供定期壽險作為過渡保障，故答案為自動提供定期壽險。"}},
{p:3,ch:"保险利益附约及其他产品",q:"保证可保利益是指保单所有人在指定日子选择增加保额而无需提供可保证明， 在行使期间保单所有人不幸死亡：",o:["保险金额立即增加","取回保单原有保额","部份保险人会自动提供定期寿险提供额外保障","死者亲人可于三十天内向保险公司办理手续"],a:2,e:"保证可保利益允许保单所有人在指定日子增额而无需可保证明；若在行使期间不幸死亡，部分保险人会自动提供定期寿险，为受保生命提供额外保障。故答案为「自动提供定期寿险提供额外保障」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"保證可保利益是指保單所有人在指定日子選擇增加保額而無需提供可保證明，在行使期間保單所有人不 幸死亡：",o:["保險金額立即增加","取回保單原有保額","部份保險人會自動提供定期壽險提供額外保障","死者親人可於三十天內向保險公司辦理手續"],e:"保證可保利益允許保單所有人在指定日子增額而無需可保證明；若在行使期間不幸死亡，部分保險人會自動提供定期壽險，為受保生命提供額外保障。故答案為「自動提供定期壽險提供額外保障」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"附约\"生活指数调整\"是意味著的：",o:["对抗经济危机","对抗通货膨胀和通货收缩的意思","对罹癌病人发放部份保额","以上各项皆不是"],a:3,e:"「生活指数调整」附约是按生活指数（通胀）调整保额以维持其购买力，既非对抗经济危机或缩窄到通缩，也非对癌症病人发放部分保额。题干各选项表述均不准确，故为「以上各项皆不是」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"附約\"生活指數調整\"是意味著的：",o:["對抗經濟危機","對抗通貨膨脹和通貨收縮的意思","對罹癌病人發放部份保額","以上各項皆不是"],e:"「生活指數調整」附約是按生活指數（通脹）調整保額以維持其購買力，既非對抗經濟危機或縮窄到通縮，也非對癌症病人發放部分保額。題幹各選項表述均不準確，故為「以上各項皆不是」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据《医疗保险业务指引》，以下哪一项描述是正确的？",o:["医疗保险业务指引 具有法律效力，违反指引会导致法律诉讼。","医疗保险业务指引 不具法律效力，但不遵从可能影响保监局对相关人士的评 估。","医疗保险业务指引 仅适用于个人医疗保险业务，不包括团体业务。","医疗保险业务指引 是附属法例，必须遵从。"],a:1,e:"《医疗保险业务指引》属监管指引，不具法律效力，违反不会直接引起法律诉讼；但不遵从可能影响保监局对相关人士的评估。它并非附属法例，也不只适用于个人业务，故为「不具法律效力」一项。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據《醫療保險業務指引》，以下哪一項描述是正確的？",o:["醫療保險業務指引 具有法律效力，違反指引會導致法律訴訟。","醫療保險業務指引 不具法律效力，但不遵從可能影響保監局對相關人士的評估。","醫療保險業務指引 僅適用於個人醫療保險業務，不包括團體業務。","醫療保險業務指引 是附屬法例，必須遵從。"],e:"《醫療保險業務指引》屬監管指引，不具法律效力，違反不會直接引起法律訴訟；但不遵從可能影響保監局對相關人士的評估。它並非附屬法例，也不只適用於個人業務，故為「不具法律效力」一項。"}},
{p:3,ch:"保险利益附约及其他产品",q:"根据意外死亡及丧失肢体附约，在以下哪项原因导致死亡的情况下，才得到意 外死亡保险利益？",o:["意外身体受伤","第三者意外或蓄意导致","受保人意外或蓄意导致","以上皆否"],a:0,e:"意外死亡及丧失肢体附约仅在死亡由「意外身体受伤」直接导致时给付意外死亡利益。第三者蓄意杀害、受保人蓄意行为等均属除外，故答案为「意外身体受伤」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"根據意外死亡及喪失肢體附約，在以下哪項原因導致死亡的情況下，才得到意外死亡保險利益？",o:["意外身體受傷","第三者意外或蓄意導致","受保人意外或蓄意導致","以上皆否"],e:"意外死亡及喪失肢體附約僅在死亡由「意外身體受傷」直接導致時給付意外死亡利益。第三者蓄意殺害、受保人蓄意行為等均屬除外，故答案為「意外身體受傷」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通常在给付⾧期护理保险利益前有一个等候期，为期：",o:["30 日","60 日","90 日","1 年"],a:2,e:"长期护理保险利益在给付前通常设有等候期，受保人须处于符合给付的护理状态并持续该期间。标准等候期一般为90日，故答案为90日。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通常在給付⾧期護理保險利益前有一個等候期，為期：",o:["30 日","60 日","90 日","1 年"],e:"長期護理保險利益在給付前通常設有等候期，受保人須處於符合給付的護理狀態並持續該期間。標準等候期一般為90日，故答案為90日。"}},
{p:3,ch:"保险利益附约及其他产品",q:"18. 自愿医保计划对购买人士有什么好处?",o:["为没有能力使用私营医疗服务的消费者提供一个额外的选择","为雇主没有提供雇员福利提供额外的保险计划","提升个人住院保险的质素和透明度并为愿意及有能力使用私营医疗服务的消 费者提供一个额外的选择","为低收入人士提供使用私营医疗服务"],a:2,e:"自愿医保计划的目的是提升个人住院保险的质素和透明度，并为愿意及有能力使用私营医疗服务的消费者提供额外选择。其并非专为低收入或无力负担私营医疗者提供保障，故答案为提升质素与提供额外选择。",src:1,tw:{ch:"保險利益附約及其他產品",q:"18. 自願醫保計劃對購買人士有什麼好處?",o:["為沒有能力使用私營醫療服務的消費者提供一個額外的選擇","為僱主沒有提供僱員福利提供額外的保險計劃","提升個人住院保險的質素和透明度並為願意及有能力使用私營醫療服務的消 費者提供一個額外的選擇","為低收入人士提供使用私營醫療服務"],e:"自願醫保計劃的目的是提升個人住院保險的質素和透明度，併為願意及有能力使用私營醫療服務的消費者提供額外選擇。其並非專為低收入或無力負擔私營醫療者提供保障，故答案為提升質素與提供額外選擇。"}},
{p:3,ch:"阐释人寿保险单",q:"有关人夀保单利益的赔付选择，以下哪项是正确的:",o:["只有保险人可决定赔付的选择","受益人或保单所有人可决定赔付的选择","只有受益人可决定赔付的选择","只有保单所有人可决定赔付的选择"],a:1,e:"人寿保单利益的赔付选择可由受益人或保单所有人决定，保险人本身无权单方面决定。故答案为「受益人或保单所有人可决定赔付的选择」。",src:1,tw:{ch:"闡釋人壽保險單",q:"有關人夀保單利益的賠付選擇，以下哪項是正確的:",o:["只有保險人可決定賠付的選擇","受益人或保單所有人可決定賠付的選擇","只有受益人可決定賠付的選擇","只有保單所有人可決定賠付的選擇"],e:"人壽保單利益的賠付選擇可由受益人或保單所有人決定，保險人本身無權單方面決定。故答案為「受益人或保單所有人可決定賠付的選擇」。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险中，自杀条款的目的是",o:["防止有人自杀","避免有人利用自杀而获得赔偿","不鼓励以自杀作为得到赔偿的方法","以上所有各项"],a:1,e:"自杀条款在保单首段期间内将自杀列为除外，目的是避免有人为取得赔偿而蓄意自杀，防止道德危险。故答案为「避免有人利用自杀而获得赔偿」。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險中，自殺條款的目的是",o:["防止有人自殺","避免有人利用自殺而獲得賠償","不鼓勵以自殺作為得到賠償的方法","以上所有各項"],e:"自殺條款在保單首段期間內將自殺列為除外，目的是避免有人為取得賠償而蓄意自殺，防止道德危險。故答案為「避免有人利用自殺而獲得賠償」。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项是寿险保单的自杀条款的陈述是不正确？",o:["一般而言，自杀最少于首年被列为除外责任","当指明的自杀期间过后，自杀不会影响有关的索偿","自杀是违法的，因此不会获支付索偿","在指明的首段期间内自杀可能获退回保费"],a:2,e:"寿险保单自杀条款一般将首一至两年内的自杀列为除外，之后自杀不影响索偿；首段期间自杀可能退回保费。自杀并非「违法而不获支付」的理由，故「自杀是违法的，因此不会获支付索偿」为不正确陈述。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項是壽險保單的自殺條款的陳述是不正確？",o:["一般而言，自殺最少於首年被列為除外責任","當指明的自殺期間過後，自殺不會影響有關的索償","自殺是違法的，因此不會獲支付索償","在指明的首段期間內自殺可能獲退回保費"],e:"壽險保單自殺條款一般將首一至兩年內的自殺列為除外，之後自殺不影響索償；首段期間自殺可能退回保費。自殺並非「違法而不獲支付」的理由，故「自殺是違法的，因此不會獲支付索償」為不正確陳述。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项有关保单抵押贷款条款的陈述是不正确？",o:["贷款用途需经保险人同意","保单所有人有权向保人借入款项","贷款金额的上限为保单现金价值","未缴清的利息会支付保险利益中扣除"],a:0,e:"保单抵押贷款条款下，保单所有人有权以保单现金价值为抵押向保险人借款，贷款用途无需经保险人同意，贷款金额以现金价值为上限，未偿利息从保险利益中扣除。故「贷款用途需经保险人同意」为不正确。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項有關保單抵押貸款條款的陳述是不正確？",o:["貸款用途需經保險人同意","保單所有人有權向保人借入款項","貸款金額的上限為保單現金價值","未繳清的利息會支付保險利益中扣除"],e:"保單抵押貸款條款下，保單所有人有權以保單現金價值為抵押向保險人借款，貸款用途無需經保險人同意，貸款金額以現金價值為上限，未償利息從保險利益中扣除。故「貸款用途需經保險人同意」為不正確。"}},
{p:3,ch:"阐释人寿保险单",q:"一般香港保单(美式保单)都有列明当误报年龄的情况出现时的处理方法，如果 误报情况于索偿后才出现。以下哪项或哪些是常见的处理方法？",o:["不会要求增加保费或退还保费","真实年龄比保单所写为低，赔偿较低利益","真实年龄比保单所写为高，赔偿较高利益","以上所有处理方法皆可"],a:0,e:"美式保单对误报年龄的处理，是在索偿后按实际年龄调整保险利益，而非要求增加或退还保费。故「不会要求增加保费或退还保费」为常见处理方法。",src:1,tw:{ch:"闡釋人壽保險單",q:"一般香港保單(美式保單)都有列明當誤報年齡的情況出現時的處理方法，如果誤報情況於索償後才出 現。以下哪項或哪些是常見的處理方法？",o:["不會要求增加保費或退還保費","真實年齡比保單所寫為低，賠償較低利益","真實年齡比保單所寫為高，賠償較高利益","以上所有處理方法皆可"],e:"美式保單對誤報年齡的處理，是在索償後按實際年齡調整保險利益，而非要求增加或退還保費。故「不會要求增加保費或退還保費」為常見處理方法。"}},
{p:3,ch:"阐释人寿保险单",q:"为什么说一张寿险保单所有人只具有有限的权利转让该保单的产权？",o:["转让一张保单的权利属于保单的受益人而非保单所有人所有","转让寿险单必须保险人的批准","转让保单的目的必须是合法的","在典型寿险保单所规定的转让必须书面通知保险人"],a:3,e:"寿险保单所有人转让保单产权的权利受到限制，因典型寿险保单规定转让须以书面通知保险人才生效。转让权利属保单所有人（而非受益人），不须保险人批准也不限合法目的，故答案为书面通知保险人。",src:1,tw:{ch:"闡釋人壽保險單",q:"為什麼說一張壽險保單所有人只具有有限的權利轉讓該保單的產權？",o:["轉讓一張保單的權利屬於保單的受益人而非保單所有人所有","轉讓壽險單必須保險人的批准","轉讓保單的目的必須是合法的","在典型壽險保單所規定的轉讓必須書面通知保險人"],e:"壽險保單所有人轉讓保單產權的權利受到限制，因典型壽險保單規定轉讓須以書面通知保險人才生效。轉讓權利屬保單所有人（而非受益人），不須保險人批准也不限合法目的，故答案為書面通知保險人。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险转让的方式共有两种，分别是： i 部份转让 ii 抵押转让 iii 绝对转让 iv 永久转让",o:["ii, iii","ii, iv","i, ii","i, iv"],a:0,e:"人寿保险转让的方式共有两种：抵押转让（附条件转让）及绝对转让。部份转让与永久转让并非规范分类，故答案为 ii、iii。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險轉讓的方式共有兩種，分別是： i 部份轉讓 ii 抵押轉讓 iii 絕對轉讓 iv 永久轉讓",o:["ii, iii","ii, iv","i, ii","i, iv"],e:"人壽保險轉讓的方式共有兩種：抵押轉讓（附條件轉讓）及絕對轉讓。部份轉讓與永久轉讓並非規範分類，故答案為 ii、iii。"}},
{p:3,ch:"阐释人寿保险单",q:"关于完整合约条款正确的是？",o:["保险人可以随意更改合约","只有保单所有人同意才可以更改合约内容","指定的高级职员可以直接更改合约","完整合约又称开放式合约"],a:1,e:"完整合约条款规定保险合约的签署文件为合约全部内容，只有经保单所有人同意才可更改合约内容，保险人不得单方面随意改动，指定职员亦无权直接更改。故答案为「只有保单所有人同意才可以更改合约内容」。",src:1,tw:{ch:"闡釋人壽保險單",q:"關於完整合約條款正確的是？",o:["保險人可以隨意更改合約","只有保單所有人同意才可以更改合約內容","指定的高級職員可以直接更改合約","完整合約又稱開放式合約"],e:"完整合約條款規定保險合約的簽署文件為合約全部內容，只有經保單所有人同意才可更改合約內容，保險人不得單方面隨意改動，指定職員亦無權直接更改。故答案為「只有保單所有人同意才可以更改合約內容」。"}},
{p:3,ch:"阐释人寿保险单",q:"下列哪项有关保单抵押贷款条款的陈述是正确？",o:["贷款用途需经保险人同意","现金价值是贷款唯一的抵押品","贷款金额没有上限","以上皆不正确"],a:1,e:"保单抵押贷款以保单现金价值作为贷款的唯一抵押品，贷款金额以现金价值为上限，贷款用途无需经保险人同意。故正确陈述为「现金价值是贷款唯一的抵押品」。",src:1,tw:{ch:"闡釋人壽保險單",q:"下列哪項有關保單抵押貸款條款的陳述是正確？",o:["貸款用途需經保險人同意","現金價值是貸款唯一的抵押品","貸款金額沒有上限","以上皆不正確"],e:"保單抵押貸款以保單現金價值作為貸款的唯一抵押品，貸款金額以現金價值為上限，貸款用途無需經保險人同意。故正確陳述為「現金價值是貸款唯一的抵押品」。"}},
{p:3,ch:"阐释人寿保险单",q:"以下哪项或哪些有关宽限期的陈述是正确的？",o:["并非免费的保险期","不适用于首期保费","宽限期内缴费会被视作准时","以上皆是正确的"],a:3,e:"宽限期并非免费保险期，不适用于首期保费，但在宽限期内缴费会被视为准时缴付。三项关于宽限期的陈述均正确，故为「以上皆是正确的」。",src:1,tw:{ch:"闡釋人壽保險單",q:"以下哪項或哪些有關寬限期的陳述是正確的？",o:["並非免費的保險期","不適用於首期保費","寬限期內繳費會被視作準時","以上皆是正確的"],e:"寬限期並非免費保險期，不適用於首期保費，但在寬限期內繳費會被視為準時繳付。三項關於寬限期的陳述均正確，故為「以上皆是正確的」。"}},
{p:3,ch:"阐释人寿保险单",q:"人寿保险中「复效 (reinstatement) 」，英式保单又称为：",o:["重新订立 (re-establishment)","保单复效(policy revival)","不能作废 (non-forfeiture)","保单续保 (policy renewal)"],a:1,e:"人寿保险的「复效」指已失效保单在满足条件下恢复效力，英式保单又称「保单复效」（policy revival）。重新订立、不能作废、保单续保均非其英式称谓。",src:1,tw:{ch:"闡釋人壽保險單",q:"人壽保險中「復效 (reinstatement) 」，英式保單又稱為：",o:["重新訂立 (re-establishment)","保單復效(policy revival)","不能作廢 (non-forfeiture)","保單續保 (policy renewal)"],e:"人壽保險的「復效」指已失效保單在滿足條件下恢復效力，英式保單又稱「保單復效」（policy revival）。重新訂立、不能作廢、保單續保均非其英式稱謂。"}},
{p:3,ch:"阐释人寿保险单",q:"若受益人于索偿时发现投保人的实际年龄比保单上的年龄高了几岁，美式做法 会向上调整死亡利益，英式做法会怎样处理？",o:["维持原有保额，退回保费","保单即时无效","向上调整死亡利益","把保单取消并退还全数保费"],a:0,e:"对误报年龄的处理，美式按实际年龄比例调整保额；英式则维持原有保额，将因年龄误报而多收的保费退回。故英式做法为「维持原有保额，退回保费」。",src:1,tw:{ch:"闡釋人壽保險單",q:"若受益人於索償時發現投保人的實際年齡比保單上的年齡高了幾歲，美式做法 會向上調整死亡利益，英式做法會怎樣處理？",o:["維持原有保額，退回保費","保單即時無效","向上調整死亡利益","把保單取消並退還全數保費"],e:"對誤報年齡的處理，美式按實際年齡比例調整保額；英式則維持原有保額，將因年齡誤報而多收的保費退回。故英式做法為「維持原有保額，退回保費」。"}},
{p:3,ch:"人寿保险程序",q:"下列哪项功能较不可能直接涉及理赔部？",o:["就一份保单进行核保工作","日常理赔的行政和处理工作以及有关的查询","核证近因的调查工作","审阅已去世受保保单所有人的验尸报告"],a:0,e:"理赔部负责理赔行政、近因调查及审阅验尸报告等。「就一份保单进行核保工作」属于核保部职能，较不可能直接涉及理赔部，故为答案。",src:1,tw:{ch:"人壽保險程序",q:"下列哪項功能較不可能直接涉及理賠部？",o:["就一份保單進行核保工作","日常理賠的行政和處理工作以及有關的查詢","核證近因的調查工作","審閱已去世受保保單所有人的驗屍報告"],e:"理賠部負責理賠行政、近因調查及審閲驗屍報告等。「就一份保單進行核保工作」屬於核保部職能，較不可能直接涉及理賠部，故為答案。"}},
{p:3,ch:"人寿保险程序",q:"以下哪种类别的人寿保险保单可由获授权保险人选择是否发出有效利益说 明？",o:["个人人寿保险保单","投资相连寿险计划保单","完全清缴保险","分红保单"],a:1,e:"投资相连寿险计划保单可由获授权保险人选择是否发出有效利益说明。个人人寿、分红保单及完全清缴保单须按规定提供说明，故答案为「投资相连寿险计划保单」。",src:1,tw:{ch:"人壽保險程序",q:"以下哪種類別的人壽保險保單可由獲授權保險人選擇是否發出有效利益說明？",o:["個人人壽保險保單","投資相連壽險計劃保單","完全清繳保險","分紅保單"],e:"投資相連壽險計劃保單可由獲授權保險人選擇是否發出有效利益說明。個人人壽、分紅保單及完全清繳保單須按規定提供說明，故答案為「投資相連壽險計劃保單」。"}},
{p:3,ch:"人寿保险程序",q:"哪些因素会影响红利的派发? i 其他保险人的同行竞争 ii 社会持续的经济衰退 iii 公司的市场行销策略改变 iv 流行传染病影响了公众健康",o:["i, ii","i, iii","ii, iii, iv","i, ii, iii, iv"],a:3,e:"影响红利派发的因素包括其他保险人的同行竞争、社会经济持续衰退、公司市场行销策略改变以及流行传染病影响公众健康（影响死亡率及投资回报）。四项均有影响，故为 i、ii、iii、iv。",src:1,tw:{ch:"人壽保險程序",q:"哪些因素會影響紅利的派發? i 其他保險人的同行競爭 ii 社會持續的經濟衰退 iii 公司的市場行銷策略改變 iv 流行傳染病影響了公衆健康",o:["i, ii","i, iii","ii, iii, iv","i, ii, iii, iv"],e:"影響紅利派發的因素包括其他保險人的同行競爭、社會經濟持續衰退、公司市場行銷策略改變以及流行傳染病影響公眾健康（影響死亡率及投資回報）。四項均有影響，故為 i、ii、iii、iv。"}},
{p:3,ch:"人寿保险程序",q:"财务性核保包括？",o:["被保险人是否有能力缴付保费","审慎的再保险情况","已累积购买的保单计划","以上都是"],a:3,e:"财务性核保包括评估被保险人缴付保费的能力、审慎的再保险安排，以及其已累积购买的保单计划是否过重。三项均属财务性核保范畴，故为「以上都是」。",src:1,tw:{ch:"人壽保險程序",q:"財務性核保包括？",o:["被保險人是否有能力繳付保費","審慎的再保險情況","已累積購買的保單計劃","以上都是"],e:"財務性核保包括評估被保險人繳付保費的能力、審慎的再保險安排，以及其已累積購買的保單計劃是否過重。三項均屬財務性核保範疇，故為「以上都是」。"}},
{p:3,ch:"保险利益附约及其他产品",q:"通胀问题会令人寿保险的利益价值大大贬值，以下哪项附约可减低它的影响？",o:["死亡指数调整","生活指数调整","通货膨胀调整","通货调整商数"],a:1,e:"通胀会令固定保额的人寿保险价值贬值，而生活指数调整附约可按通胀指数相应调高保额，以维持保障的实际购买力，从而减低通胀影响。故答案为「生活指数调整」。",src:1,tw:{ch:"保險利益附約及其他產品",q:"通脹問題會令人壽保險的利益價值大大貶值，以下哪項附約可減低它的影響？",o:["死亡指數調整","生活指數調整","通貨膨脹調整","通貨調整商數"],e:"通脹會令固定保額的人壽保險價值貶值，而生活指數調整附約可按通脹指數相應調高保額，以維持保障的實際購買力，從而減低通脹影響。故答案為「生活指數調整」。"}},
];
